N'ALTER PROC [dbo].[TEMPVLSQTYADJ]
AS
SET NOCOUNT ON;
BEGIN
DECLARE @SaleQty DECIMAL(15,4) = 5
declare @tblTranSaleDetail [tvpTranSaleDetail] 
declare @tvpVLSItemdetails as [tvpVLSItemdetails]
DECLARE @InvQtyType INT = 1,@Index INT
CREATE TABLE #InventoryId (Ident INT IDENTITY ,TempInvId INT,TempInvQty DECIMAL (15,4))  
select VD.ID,VD.InventoryID,VD.ProdID,SUM(VD.UomQty) UomQty,SUM(VD.VLSMQty) VLSMQty,VD.UomPrice,VD.MRP INTO #DATA1 from tblVanLoadingSlipHeader VH WITH (READCOMMITTEDLOCK)
JOIN tblVanLoadingSlipDetail VD WITH (READCOMMITTEDLOCK) ON VD.ID = VH.ID
WHERE VH.SalesmanID = 17 AND ProdID = 526 AND UomPrice = 65.0000 AND VD.MRP = 70 AND (UomQty - ISNULL(VLSMQty,0)) > 0
GROUP BY VD.ID,VD.InventoryID,VD.ProdID,VD.UomPrice,VD.MRP 
ORDER BY VD.ID

SELECT * FROM #DATA1
DECLARE @InventoryId INT,@InventoryQty DECIMAL(25, 9)  
DECLARE cursor_Inventory CURSOR LOCAL FAST_FORWARD FOR (SELECT InventoryId,UomQty AS Qty FROM #DATA1)  
OPEN cursor_Inventory  
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty  
WHILE @@FETCH_STATUS =0  
BEGIN  
--Loop Exist Qty Adjusted After  
IF(@SaleQty =0)  
BEGIN  
BREAK;  
END  
--Qty Type SALE  
IF(@InvQtyType=1)  
BEGIN  IF @SaleQty >@InventoryQty  
BEGIN  
UPDATE tblVanLoadingSlipDetail SET VLSMQty = ISNULL(VLSMQty,0)+ISNULL(@InventoryQty,0)
WHERE InventoryId =@InventoryId  
SET @SaleQty =@SaleQty - @InventoryQty  
INSERT INTO #InventoryId VALUES (@InventoryId,@InventoryQty)  
END  
ELSE IF @SaleQty <@InventoryQty  
BEGIN  
UPDATE tblVanLoadingSlipDetail SET VLSMQty = ISNULL(VLSMQty,0)+ISNULL(@SaleQty,0)  
WHERE InventoryId =@InventoryId  
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)  
SET @SaleQty =0  
END  
ELSE IF @SaleQty=@InventoryQty  
BEGIN  
UPDATE tblVanLoadingSlipDetail SET VLSMQty = ISNULL(VLSMQty,0)+ISNULL(@SaleQty,0) WHERE InventoryId =@InventoryId  
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)  
SET @SaleQty =0  
END  
END  
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty  
END  
CLOSE cursor_Inventory  
DEALLOCATE cursor_Inventory  
SELECT * FROM #DATA1

IF ISNULL(@SaleQty,0) !=0  
BEGIN  
RAISERROR(''Qty Mismatched'',16,1);  
END  
ELSE  
BEGIN  
DECLARE @InsertCount INT=(SELECT COUNT(*) FROM #InventoryId )  
DECLARE @InsertIdent INT SET @InsertIdent=1;  
DECLARE @InvAdjId INT,@InvAdjQty DECIMAL(25, 9)  
SET @Index=1  
--loop Inentory Adjustment Qty  

--WHILE @InsertCount>0  
--BEGIn  
--SET @InvAdjId=(SELECT TempInvId FROM #InventoryId WHERE Ident=@InsertIdent)  
--SET @InvAdjQty=(SELECT TempInvQty FROM #InventoryId WHERE Ident=@InsertIdent)  
--IF @Index=1  
--BEGIN  
--set @dtluomqty = (@InvAdjQty / @SaleUomCRate)
--set @dtluomprice = (@BaseUomPrice * @SaleUomCRate)
