/****** uspAddTrackPoint ******/
EXEC #Apply07 N'dbo.uspAddTrackPoint', 0x3A7A3CE18753DD534EEA93B4BE164DB24D1BC989478A35C0411935922D4E75C9, NULL, NULL, 0xD25B6820FCC19EF8522080CC34FAFF36260E285D0849052F5AABE0D439A8A98C, 0xCC0843FAC0D957D2135197DDE4B1926DA97ABE806FB13046C167E188F0118348, NULL,
N'--[uspAddTrackPoint] 1,230
 ALTER PROCEDURE [dbo].[uspAddTrackPoint]  
@NetAmount DECIMAL (25,6)=NULL,  
@Cond INT,  
@CustID INT  
AS  
SET NOCOUNT ON;
BEGIN  
DECLARE @TrackPointAmount DECIMAL (25,6),@TrackPoint DECIMAL (25,6),@PerPointAmt DECIMAL (25,6),@TotalAmount DECIMAL (25,6)  
SELECT @PerPointAmt = AppValue FROM tblAppConfig WITH (READCOMMITTEDLOCK) WHERE AppId IN(39)  
  
SELECT @TrackPointAmount =AppValue FROM tblAppConfig WITH (READCOMMITTEDLOCK) WHERE AppId IN(37)  
  
SELECT @TrackPoint = AppValue  FROM tblAppConfig WITH (READCOMMITTEDLOCK) WHERE AppId IN(38)  
  
SET @TotalAmount = ((@NetAmount/@TrackPointAmount)* (@TrackPoint))  
IF ISNULL(@Cond,0)=1 ---Sales and Cancel sales Return Add Amount  
BEGIN  
UPDATE tblMasterCustomer SET ClosingTrackPoint = (ISNULL(ClosingTrackPoint,0) + @TotalAmount) WHERE ID =@CustID  
END  
IF ISNULL(@Cond,0)=2 --Cancel sales and Sales Retrun  
BEGIN  
UPDATE tblMasterCustomer SET ClosingTrackPoint = (ISNULL(ClosingTrackPoint,0) - @TotalAmount) WHERE ID =@CustID  
END  
END',
N'[export] nocount;readcommittedlock=3';
GO
/****** uspAllTransLedgerHeader ******/
EXEC #Apply07 N'dbo.uspAllTransLedgerHeader', 0x9BE7255D78663DE0B2572374E456C89A951EC2DD7A4F3171F90E447E6F4A1332, NULL, NULL, 0x102BD5F2C1388B9D004708CA49AA01250157FDF216FC298AAFBC873FB33F8B7D, 0x0FB1C7F10C30A9DC45B0D1C4EA926F15D7A3759159049ABBB3E255FF051EE65E, NULL,
N'ALTER proc [dbo].[uspAllTransLedgerHeader]  
@TransID INT = 9,@FromDate DATE = ''2025-01-01'',@ToDate  DATE = ''2025-11-30''  
AS  
SET NOCOUNT ON;
BEGIN  
select * INTO #AllTransData from (  
--Invoice  
select SH.DocPrefix TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.InvDate [Tran Date],  
DocRef [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remark,Narration from tblTranSalesHeader SH  
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix = 15 AND Status IN (1,3,5) AND InvDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--SR - sales  
select SH.DocPrefix TransID,SH.ID,''Sales Return'' [Transaction],SH.DocID [Doc ID],SH.InvDate [Tran Date],  
DocRef [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remark,Narration from tblTranSalesHeader SH  
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix = 16 AND TransactionType = 2 AND Status IN (3,5,6) AND InvDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--SR - damage  
select 17 TransID,SH.ID,''Damage Return'' [Transaction],SH.DocID [Doc ID],SH.InvDate [Tran Date],  
DocRef [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remark,Narration from tblTranSalesHeader SH  
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix = 16 AND TransactionType = 3 AND Status IN (3,5,7) AND InvDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--PR  
select SH.TransID TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.Date [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remarks Remark,Narration from tblTransPurchaseHeader SH  
JOIN tblMasterVendor  MC ON MC.ID = SH.VendorID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID = 12 AND Status IN (3,5,6,7) AND Date BETWEEN @FromDate AND @ToDate  
UNION ALL  
--BILL  
select SH.TransID TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.Date [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remarks Remark,Narration from tblTransPurchaseHeader SH  
JOIN tblMasterVendor  MC ON MC.ID = SH.VendorID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID = 1 AND Status IN (1,3,5) AND Date BETWEEN @FromDate AND @ToDate  
UNION ALL  
--AUTO INDENT  
select SH.TransID TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.Date [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],0 Value,0 Balance,STS.Description Status,Remarks Remark,Narration from tblTransAutomaticIndentHeader SH  
JOIN tblMasterVendor  MC ON MC.ID = SH.VendorID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID = 2 AND Status IN (1,3,5) AND Date BETWEEN @FromDate AND @ToDate  
UNION ALL  
--PO  
select SH.TransID TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.DocDate [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],sh.NetAmt Value,0 Balance,STS.Description Status,Remarks Remark,Narration from tblPurchaseOrderHeader SH  
JOIN tblMasterVendor  MC ON MC.ID = SH.VendorID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID = 3 AND Status IN (1,3,5) AND DocDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--PAYMENT & OTERH PAYMENT  
select SH.PYPrefix TransID,SH.PYID ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.PYDate [Tran Date],  
PYDocRefNo [Ref No],MC.AccountName [Party Name],sh.PYAmt Value,Balance,STS.Description Status,Remarks Remark,Narration from tblTranPaymentHeader SH  
LEFT JOIN tblFAAccount MC ON MC.FAID = SH.AccID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.PYPrefix  
WHERE SH.PYPrefix IN (11,18) AND Status IN (1,3,5) AND PYDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--COLLECTION & OTERH COLLECTION  
select SH.DocPrefix TransID,SH.ColID ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.ColDate [Tran Date],  
ColDocRefNo [Ref No],MC.AccountName [Party Name],sh.ColAmt Value,Balance,STS.Description Status,Remarks Remark,Narration from tblTranCollectionHeader SH  
LEFT JOIN tblFAAccount MC ON MC.FAID = SH.AccID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix IN (10,19) AND Status IN (1,3,5) AND ColDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--Quotataion  
select SH.DocPrefix TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.DocDate [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],sh.NetAmt Value,0 Balance,STS.Description Status,Remark,Narration from tblQuotationHeader SH  
JOIN tblMasterCustomer MC ON MC.ID = SH.CustomerID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix = 14 AND Status IN (1,3,5) AND DocDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--Assign Inv  
select SH.TransID TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.DocDate [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],0 Value,0 Balance,STS.Description Status,null Remark,null Narration from tblAssignInvoicesHeader SH  
JOIN tblMasterSalesman MC ON MC.ID = SH.SalesmanID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID = 21 AND Status IN (1,3,5) AND DocDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--Delivery
select SH.DocPrefix TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.DocDate [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],0 Value,0 Balance,STS.Description Status,Remarks Remark,Narration Narration 
from tblDeliveryOrderHeader SH  
JOIN tblMasterSalesman MC ON MC.ID = SH.SalesmanID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix = 23 AND Status IN (1,3,5) AND DocDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--inv adj, Inv Conv  
select SH.TransID TransID,SH.InventoryID ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.InventoryDate [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],TotalAmt Value,0 Balance,STS.Description Status,Remarks Remark,Narration from tblInventoryHeader SH  
JOIN tblMasterBranchOffice MC ON MC.ID = SH.BranchID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID in (13,22) AND Status IN (1,3,5) AND InventoryDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--CR & DR Note  
select SH.TransID TransID,SH.ID ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.DocDate [Tran Date],  
RefNo [Ref No],MC.AccountName [Party Name],sh.NoteValue Value,Balance,STS.Description Status,Remark,Narration   
from tblNoteDetails SH  
LEFT JOIN tblFAAccount MC ON MC.FAID = SH.PartyID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID IN (4,5) AND Status IN (1,3,5) AND DocDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--PAY & REC Voucher  
select SH.TransID TransID,SH.ID ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.DocDate [Tran Date],  
RefNo [Ref No],MC.AccountName [Party Name],sh.NetAmount Value,Balance,STS.Description Status,Remarks Remark,Narration   
from tblTranPRVoucher SH  
LEFT JOIN tblFAAccount MC ON MC.FAID = SH.PartyID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID IN (6,7) AND Status IN (1,3,5) AND DocDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--Contra  
select SH.TransID TransID,SH.ID ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.DocDate [Tran Date],  
RefNo [Ref No],MC.AccountName [Party Name],sh.Amount Value,Balance,STS.Description Status,Remarks Remark,Narration   
from tblTranContra SH  
LEFT JOIN tblFAAccount MC ON MC.FAID = SH.FromFAID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID IN (8) AND Status IN (1,3,5) AND DocDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--cheq dep  
select SH.DocPrefix TransID,SH.DepositID ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.DocDate [Tran Date],  
null [Ref No],MC.AccountName [Party Name],0 Value,0 Balance,STS.Description Status,null Remark,null Narration   
from tblTranChequeDeposit SH  
LEFT JOIN tblFAAccount MC ON MC.FAID = SH.DepositAccountId  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix IN (20) AND Status IN (1,3,5,9) AND DocDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--cheq dep  
select SH.DocPrefix TransID,SH.NoteID ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.DocDate [Tran Date],  
null [Ref No],MC.AccountName [Party Name],Credit Value,Balance,STS.Description Status,null Remark,null Narration   
from tblFAJournal SH  
LEFT JOIN tblFAAccount MC ON MC.FAID = SH.AccountID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix IN (9) AND Status IN (1,3,5) AND DocDate BETWEEN @FromDate AND @ToDate) as REC  
  
select TransID,ID,[Transaction],[Doc ID],FORMAT([Tran Date],''dd/MMM/yyyy'') [Doc Date],[Ref No],[Party Name],dbo.fnGetRoundedValue(Value) Value,  
dbo.fnGetRoundedValue(Balance) Balance,Status,Remark,Narration from #AllTransData   
WHERE TransID = (CASE WHEN ISNULL(@TransID,0) = 0 THEN TransID ELSE @TransID END)  
order by [Tran Date]   
drop table #AllTransData  
END',
N'[export] nocount';
GO
/****** uspAssignInvoiceDetail ******/
EXEC #Apply07 N'dbo.uspAssignInvoiceDetail', 0x23426FE6567101072CBE3CC8D5F6B0E2722CFA417B6083C02064411F34BC8C60, NULL, NULL, 0x35FD8AF11C32A4FB62BCB8FA825A97242711CD8669547E1B0B95BC4543927BE7, 0xC4FD4254750C0E541E52454BEE4F82713B244A9DFACFD266694D8AF949A9D91B, NULL,
N'ALTER PROC [dbo].[uspAssignInvoiceDetail]    
@AinvID int = 7    
as    
SET NOCOUNT ON;
begin    
select  Row_number() OVER (order by MC.Name) as [Serial No],DocID [Doc ID],FORMAT(InvDate,''dd-MMM-yyyy'') [Doc Date],DocRef [Ref No],mb.Name [Beat Name],SM.Name [Salesman Name],    
MC.Name [Customer Name],dbo.fnGetRoundedValue(SH.NetAmt) [Net Amount],dbo.fnGetRoundedValue(SH.Balance) [Balance],DATEDIFF(DD,InvDate,GETDATE()) Ageing    
from tblAssignInvoicesDetail AID    
JOIN tblTranSalesHeader SH ON SH.ID = AID.InvID    
join tblMasterCustomer MC ON MC.ID = SH.CustID    
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesmanID    
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID    
WHERE AID.HID = @AinvID    
ORDER BY MC.Name,[Serial No],InvDate,DocValue  
end',
N'[export] nocount';
GO
/****** uspAssignInvoiceHeader ******/
EXEC #Apply07 N'dbo.uspAssignInvoiceHeader', 0x02950AC153C6103B830B3B25E4374BD61A009B95860DA4084B78877DD9F913CC, NULL, NULL, 0xDDAFA7AF257A47714213F6FC7DA6F8EFB5623CD8BC8E9CB08F57F4C9266A8DB2, 0x7C212AD74E4179A24069BEACE2FE8738277CED9D38EFACA5EB46C8F4B95F998E, NULL,
N'--uspAssignInvoiceHeader 10  
ALTER proc [dbo].[uspAssignInvoiceHeader]  
@AinvID int = 0  
as  
SET NOCOUNT ON;
begin  
select AIS.DocID [Doc ID],FORMAT(DocDate,''dd-MMM-yyyy'') [Doc Date],SM.Name [Salesman Name],SM.MobileNo [Salesman Mob No],RefNo [Ref No],URS.UserName [User Name],  
FORMAT(AIS.CDate,''dd-MM-yyyy hh:mm tt'') [Create Date],'''' Remarks,'''' Narration,COUNT(ASD.InvID) [Invoice Count],
dbo.fnGetRoundedValue(sum(SH.NetAmt)) [Net Amount],dbo.fnGetRoundedValue(SUM(SH.Balance)) [Balance] from tblAssignInvoicesHeader AIS  
JOIN tblMasterSalesman SM ON SM.ID = AIS.SalesmanID  
JOIN tblUsers URS ON URS.ID = AIS.CBy  
join tblAssignInvoicesDetail ASD ON ASD.HID = AIS.ID  
JOIN tblTranSalesHeader SH ON SH.ID = ASD.InvID
WHERE AIS.ID = @AinvID  
GROUP BY AIS.DocID,DocDate,SM.Name,RefNo,URS.UserName,AIS.CDate,SM.MobileNo  
end',
N'[export] nocount';
GO
/****** uspAutoBackUp ******/
EXEC #Apply07 N'dbo.uspAutoBackUp', 0xB437B6A95B25AB528274BA632A8C51D66F7C9684291B9FB4C2FA4379DB5B0E4F, NULL, NULL, 0x66DA0F69803732AF1C4FA8D80CA5BFC60C7B6D157C9CED273AF3B16F63FE3FAC, 0xB70583DF51998AE26FCC3F1B6EE09DE287B48405EC4367AD9251288D1E8CFF54, NULL,
N'--[uspAutoBackUp] 1  
ALTER PROCEDURE [dbo].[uspAutoBackUp]        
@Cond INT=NULL                                
AS                                 
BEGIN TRY      
SET NOCOUNT ON               
DECLARE @CompanyCode NVARCHAR(255), @Remainder INT,@LastBackUpDate DATE,@CurrentDate DATE,@AppPath NVARCHAR(MAX) ,@DBName NVARCHAR(255),              
@path NVARCHAR(500),@SetBackUpYesNo SMALLINT=0,@FinancialStartDate date               
--Get Company code from Table              
SELECT @CompanyCode =CompanyCode,@LastBackUpDate=LastBackUpDate ,@AppPath=BackupPath,@FinancialStartDate=F_SD          
FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)              
  
--Login In Time BackUp Database based last back up date              
IF ISNULL(@Cond,0) =0               
BEGIN               
 SELECT @Remainder=ISNULL(AppValue,0) FROM tblAppConfig WITH (READCOMMITTEDLOCK) WHERE AppName =''BackUpRemainder''               
 SET @CurrentDate=DATEADD(DAY,@Remainder,@LastBackUpDate)              
 IF(@CurrentDate<=CAST(GETDATE() AS DATE))                
 BEGIN                 
  SET @SetBackUpYesNo=1                         
 END               
END               
--Dirsct BackUp no Restriction              
IF ISNULL(@Cond,0) =1               
BEGIN              
 SET @SetBackUpYesNo=1                
END               
--1 For Get Back Up otherwise Not get Back Up.              
IF ISNULL(@SetBackUpYesNo,0)=1                
 BEGIN                 
  SET @path=@AppPath+''\BACKUPFILES\'';                        
  EXEC master.dbo.xp_create_subdir @path        
  declare @filename nvarchar(255) = ''BK_''+@CompanyCode+''_''+upper (CONVERT(CHAR(3), @FinancialStartDate, 100)) + CONVERT(CHAR(4), @FinancialStartDate, 120)+''_''+REPLACE(CONVERT(NVARCHAR,GETDATE(),112)+''''+CONVERT(NVARCHAR,GETDATE(),114),'':'','''')+''.bak''       
  
  
  SET @AppPath=@path+@filename        
          
  SET  @DBName=(SELECT DB_NAME())                               
  BACKUP DATABASE @DBName TO DISK =@AppPath  
  UPDATE CR SET LastBackUpDate =GETDATE () FROM tblCompanyRegistration CR WHERE CompanyCode = @CompanyCode         
  select @filename as filename,@AppPath as FullPath      
 END               
END TRY      
BEGIN CATCH      
SELECT ERROR_MESSAGE() [ERROR_MESSAGE],ERROR_LINE() [ERROR_LINE],ERROR_PROCEDURE() [ERROR_PROCEDURE]      
END CATCH',
N'[export] readcommittedlock=2';
GO
/****** uspAutoIndentDetail ******/
EXEC #Apply07 N'dbo.uspAutoIndentDetail', 0x34F261EF4D83CCF044FA8F33DE64DA55ACCCA0747CF5A162321F296D3505F15D, NULL, NULL, 0x677AF1DA849F9A2D6B111235E7EA7EC71C64C187A34DAD4EE2920BA7FE5929D8, 0x1FEA1E51ABD4797F25F5144246B2D6C85D9C6D2867C50B691502E867FA3C03B4, NULL,
N'--uspAutoIndentDetail 44
ALTER PROC [dbo].[uspAutoIndentDetail]        
@IndentId NVARCHAR(255)=null                                      
AS                                    
SET NOCOUNT ON;
BEGIN   

SELECT ProdID,Serial [Temp Serial],                
(SUM(RAM.[CGST %])) AS [CGST %],                                    
SUM((RAM.[CGST Amount])) AS [CGST Amount],                                    
(SUM(RAM.[SGST %])) AS [SGST %],                                    
(SUM(RAM.[SGST Amount])) AS [SGST Amount],                                    
(SUM(RAM.[UTGST %])) AS [UTGST %],                                    
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],                                    
(SUM(RAM.[GCESS %])) AS [GCESS %],                                    
SUM((RAM.[GCESS Amount])) AS [GCESS Amount],                             
(SUM(RAM.[IGST %])) AS [IGST %],                                    
SUM((RAM.[IGST Amount])) AS [IGST Amount],                            
(SUM(RAM.[ICESS %])) AS [ICESS %],                                    
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],            
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],            
SUM([GCESS Amount]  + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount]   INTO #Tax                      
FROM                                    
(                      
                      
SELECT SRI.ProdID,SRI.Serial,--SRI.[Gross Amount],                                
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 1),0)) AS [CGST %],                                    
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],                                    
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 2),0)) AS [SGST %],                                    
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],                                    
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 3),0)) AS [UTGST %],                                    
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],                             
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 4),0)) AS [GCESS %],                                    
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 5),0)) AS [GUOM %],                                  
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 1),0)) AS [IGST %],                                    
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],                            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 2),0)) AS [ICESS %],                                    
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 3),0)) AS [IUOM %],                                  
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]            
FROM                                    
(              
SELECT * FROM                                     
(            
SELECT Temp.ProdID,Temp.Serial,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],                             
Temp.TaxName AS TaxName,                                    
SUM(Temp.TaxValue) AS [TaxValue]--, SUM(Temp.[Gross Amount]) AS [Gross Amount]                                
FROM                                    
(                                    
SELECT GSTInfo.ProdID,GSTInfo.SERIAL,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,                          
CASE                            
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 3 THEN ''CGST Amount''                             
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 3 THEN ''SGST Amount''                                    
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 3 THEN ''UTGST Amount''                                    
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 3 THEN ''GCESS Amount''             
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 3 THEN ''GUOM Amount''                           
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 5 THEN ''IGST Amount''                            
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 5 THEN ''ICESS Amount''             
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 5 THEN ''IUOM Amount''                            
END AS [GST Comp]--, GSTInfo.GrossAmt AS [Gross Amount]                                
FROM tblTransGSTInfo AS GSTInfo                            
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID                         
WHERE TransIdentID=@IndentId AND TransID=22                            
) Temp                                    
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.ProdID,Temp.Serial                      
) src                                    
PIVOT                                    
(                                    
SUM([TaxValue])                                    
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])            
) piv                                    
) AS SRI                                    
) AS RAM                                
GROUP BY ProdID,Serial--,[CGST %]                
--ORDER BY RAM.[CGST %] ASC                    
declare @oby NVARCHAR(10) = (SELECT AppValue FROM tblAppConfig WHERE AppId = 167)          
SELECT IDENTITY (INT, 1, 1) AS NEW_ID,AIDetail.ProdID,prod.Code AS [Product Code],prod.Name as [Product Name],prod.HSNCode AS [HSN Code],Uom.Name as [Uom Name],                                     
AIDetail.ABSQty as [Qty],AIDetail.IndentValue as [AutoIndent Qty],AIDetail.PurchasePrice as [Purchase Price],                                                 
AIDetail.MOH as [MOH],AIDetail.MOQ as [MOQ],Row_number() OVER (order by AIDetail.HID) as [Serial No],              
     
      
prod.WebOrder [Web Order],uom.Name AS [Uom Group Name],      
AIDetail.IndentValue as [Base Qty],AIDetail.IndentValue as [Uom Qty],      
(AIDetail.IndentValue / prod.SalesCR) AS [Deft_S_UOM_Qty],      
(AIDetail.PurchasePrice / prod.SalesCR) AS [Base Uom Price],AIDetail.PurchasePrice as [UOM Price],      
prod.SalesCR AS [Deft_S_UOM_CF],      
AIDetail.PurchasePrice + (AIDetail.PurchasePrice * (MT.GST / 100)) as [Rate],      
AIDetail.PurchasePrice as [Per Piece Exclusive Price],                                              
AIDetail.PurchasePrice +(AIDetail.PurchasePrice * (MT.GST / 100)) as [Per Piece Inclusive Price],PROD.MRP [MRP Price],      
(AIDetail.PurchasePrice *AIDetail.IndentValue) [Goods Amount],(AIDetail.PurchasePrice *AIDetail.IndentValue) [Gross Amount]      
,(AIDetail.PurchasePrice *AIDetail.IndentValue) [Tax Value],      
((AIDetail.PurchasePrice *AIDetail.IndentValue) * (MT.GST / 100)) [Tax Amount],MT.GST [Tax percentage],MT.TaxName [Tax Name],      
prod.BaseCR AS [UOM CF],Serial  
 INTO #AI              
From dbo.tblTransAutomaticIndentDetail as AIDetail                                     
JOIN tblMasterProduct as prod ON prod.ID=AIDetail.ProdId                                                  
JOIN dbo.tblMasterUOM as Uom on Uom.ID = AIDetail.UomId      
join tblMasterTax MT ON MT.TaxID = prod.PurchaseTaxId                
WHERE AIDetail.HID = @IndentId --order by AIDetail.Serial              
 ORDER BY (CASE WHEN @oby = ''0'' THEN AIDetail.HID END) asc,        
(CASE WHEN @oby = ''1'' THEN Prod.Name END) asc      
      
      
SELECT Serial,[Product Code],[Product Name],[HSN Code],[Uom Name],[Qty],[AutoIndent Qty],[Purchase Price],[MOH],[MOQ],              
NEW_ID AS [Serial No],      
[Web Order],[Uom Group Name],[Base Qty],[Uom Qty],[Deft_S_UOM_Qty],[Base Uom Price],[UOM Price],[Tax Value],[Deft_S_UOM_CF],      
[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price],[MRP Price],[Goods Amount],[Gross Amount],[Tax Amount],      
[Tax Amount] + [Gross Amount] [Net Amount],[Tax percentage],      
[Tax Name],[UOM CF],dbo.fnGetRoundedValue(sum([CGST %])) [CGST %],dbo.fnGetRoundedValue(sum([CGST Amount])) [CGST Amount],                
dbo.fnGetRoundedValue(sum([SGST %])) [SGST %],                      
dbo.fnGetRoundedValue(sum([SGST Amount])) [SGST Amount],                      
dbo.fnGetRoundedValue(sum([UTGST %])) [UTGST %],dbo.fnGetRoundedValue(sum([UTGST Amount])) [UTGST Amount],                
dbo.fnGetRoundedValue(sum([GCESS %])) [GCESS %], dbo.fnGetRoundedValue(SUM([GCESS Amount])) [GCESS Amount],                
dbo.fnGetRoundedValue(sum([IGST %])) [IGST %],                      
dbo.fnGetRoundedValue(sum([IGST Amount])) [IGST Amount],             
dbo.fnGetRoundedValue(sum([ICESS %])) [ICESS %],dbo.fnGetRoundedValue(sum([ICESS Amount])) [ICESS Amount],            
dbo.fnGetRoundedValue(sum(TX.[GUOM %])) [GUOM %],dbo.fnGetRoundedValue(sum(TX.[GUOM Amount])) [GUOM Amount],            
dbo.fnGetRoundedValue(sum(TX.[IUOM %])) [IUOM %],dbo.fnGetRoundedValue(sum(TX.[IUOM Amount])) [IUOM Amount],            
dbo.fnGetRoundedValue(sum(TX.[Cumulative CESS Amount])) [Cumulative CESS Amount]  FROM #AI AI               
LEFT JOIN #Tax TX ON TX.ProdID = AI.ProdID              
GROUP BY Serial,[Product Code],[Product Name],[HSN Code],[Uom Name],[Qty],[AutoIndent Qty],[Purchase Price],[MOH],[MOQ],              
[Serial No],NEW_ID,      
[Web Order],[Uom Group Name],[Base Qty],[Uom Qty],[Deft_S_UOM_Qty],[Base Uom Price],[UOM Price],[Deft_S_UOM_CF],      
[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price],[MRP Price],[Goods Amount],[Gross Amount],[Tax Value],[Tax percentage],      
[Tax Name],[UOM CF],[Tax Amount]      
 ORDER BY (CASE WHEN @oby = ''0'' THEN [Serial No] END) asc,        
(CASE WHEN @oby = ''1'' THEN [Product Name] END) asc              
END',
N'[export] nocount';
GO
/****** uspAutoIndentHeader ******/
EXEC #Apply07 N'dbo.uspAutoIndentHeader', 0x0528DD9CA3FB20D7611ECC9133050B3E28EEF9BC9704E3FE40B6BCF473DB424C, NULL, NULL, 0x59A3C9F25361D1F7344DE65AF0894351214EE9F91A7A4CD762A6F53431A69621, 0xDBDBCA9CC69C3ABD8F6E3B87F1048BE17FC2E58C8DEB12B77ED0AA8FD51762A4, NULL,
N'--uspAutoIndentHeader 44 
ALTER PROC [dbo].[uspAutoIndentHeader]              
@IdentityID int =null                    
AS                    
SET NOCOUNT ON;
BEGIN   
WITH tempDetail (HID,TotQty,TotValue,TotCountQty) AS              
(              
SELECT HID,SUM(IndentValue),SUM(PurchasePrice*IndentValue),    
convert(nvarchar(255),MAX(Serial)) + '' / '' + convert(nvarchar(255),dbo.fnGetRoundedValue(SUM(IndentValue)))    
FROM tblTransAutomaticIndentDetail WHERE HID=@IdentityID              
GROUP BY HID              
)  
SELECT AI.ID As [Indent ID],Convert (nvarchar, AI.Date,103) as [Doc Date], AI.DocID as [Doc ID] ,Isnull(CONVERT(nvarchar(5),AI.MDate,108),          
CONVERT(nvarchar(5),AI .CDate,108)) as [Time],Doc.TransName as [Trans Name],    
Vendor.Name as [Party Name],          
Vendor.Code as [Party Code],Vendor.mob1 as [Party Prim Mobile No],Vendor.ph1 as [Party Prim Phone No],Vendor.email as [Email ID],        
Vendor.billadd1 AS [Party Bill Address 1],Vendor.billadd2 as [Party Bill Address 2],Vendor.billadd3 as [Party Bill Address 3],        
Vendor.billadd1+Vendor.billadd2+Vendor.billadd3 as [Party Full Address],    
Vendor.shipadd1 AS [Party Ship Address 1],Vendor.shipadd2 as [Party Ship Address 2],Vendor.shipadd3 as [Party Ship Address 3],     
Vendor.ContactPerson [Contact Person],Tax.TaxTypeName AS [Party TaxType],   
Vendor.pincode [Party PinCode],AI.RefNo as [Doc Ref],          
UserTab.username as [User Name],Vendor.GSTIN [Party GSTIN],Vendor.AadharNo AS [Party Aadhar Number],        
Vendor.PANNumber AS [Party PAN No],Vendor.FSSAINo AS [Party FSSAI No],    
AD.TotQty AS [Total Qty],TotCountQty [Tot Count Qty],    
AD.TotValue AS [Rounded Net Amount],AD.TotValue AS [Aft Adj NetAmt],    
[dbo].[fnConvertAmountinWords](AD.TotValue) AS [Amt_in_Words]       
FROM tblTransAutomaticIndentHeader as AI              
LEFT JOIN tempDetail AS AD ON AD.HID = AI.ID              
JOIN dbo.tblDocumentSeries AS Doc ON AI.TransID = Doc.TransID                                            
JOIN  dbo.tblMasterVendor AS Vendor ON AI.VendorID = Vendor.ID       
JOIN dbo.tblMasterTaxType as Tax on Vendor.taxtypeid = Tax.TaxTypeID                                  
JOIN dbo.tblUsers as UserTab on UserTab.ID = AI.MBy or UserTab.ID  = AI.Cby                     
WHERE  AI.ID = @IdentityID                     
END',
N'[export] nocount';
GO
/****** uspAutomaticIndentHeaderReport ******/
EXEC #Apply07 N'dbo.uspAutomaticIndentHeaderReport', 0x30A91D5BFE0BE8331A96F2A2C82FB81EC0BA4471F8A23B6693F7160813A33123, NULL, NULL, 0x25A87BDC7C48D53468EE92AB48EABDBEE9A4ABE5F26BA3182C11B55004527600, 0xD6B58067B44651A247A426C994F415412F23E141E56CEE02F2484EBD20C7A91B, NULL,
N'ALTER PROCEDURE [dbo].[uspAutomaticIndentHeaderReport]
@StatusID INT = 1,@FromDate DATE = ''2025-03-01'',@ToDate DATE = ''2025-06-21''
AS
SET NOCOUNT ON;
BEGIN
DECLARE @Sts AS TABLE(Status INT)
IF(@StatusID = 0)
BEGIN
INSERT INTO @Sts values (3),(5),(1)
END
ELSE
BEGIN
INSERT INTO @Sts values(@StatusID)
END
SELECT 
AI.ID [ID],
FORMAT(AI.Date, ''dd-MMM-yyy'') [Date],
AI.DocID [Doc ID],
BR.Name [Branch Name],
V.Code [Vendor Code],
V.Name [Vendor Name],
AI.RefNo [Ref No],
PO.DocID [PO ID],
AI.Remarks [Remarks],
AI.Narration [Narration],
CU.UserName [Created By],
CONVERT (NVARCHAR, AI.CDate) [Created Date],
MU.UserName [Modify By],
CONVERT (NVARCHAR, AI.MDate) [Modify Date],
CL.UserName [Cancel By],
CONVERT (NVARCHAR, AI.ClDate) [Cancel Date],
S.Description [Status]
FROM tblTransAutomaticIndentHeader AI
LEFT JOIN tblMasterBranchOffice BR
ON BR.ID = AI.BranchID
LEFT JOIN tblMasterVendor V
ON V.ID = AI.VendorID
LEFT JOIN tblPurchaseOrderHeader PO
ON PO.ID = AI.PoID
LEFT JOIN tblStatus S
ON S.ID = AI.Status
LEFT JOIN tblUsers CU
ON CU.ID = AI.CBy
LEFT JOIN tblUsers MU
ON CU.ID = AI.MBy
LEFT JOIN tblUsers CL
ON CU.ID = AI.ClBy
WHERE AI.Date BETWEEN @FromDate AND @ToDate AND AI.Status IN (SELECT * FROM @Sts)
ORDER BY AI.DocID
END;',
N'[export] nocount';
GO
/****** uspAutomaticIndentReportDetail ******/
EXEC #Apply07 N'dbo.uspAutomaticIndentReportDetail', 0x7B63361EC577892BDABAB9D3EDF36C456B53450CFDA5550EDE80985CF311088E, NULL, NULL, 0xFD9A2BB68259F6A7A9FA51C1A3B3E0086CB67842D0B418966E18430D63C9A658, 0xE9398E744CCD165DC759E082E7769EDD2EA2C3E9B251953C7BF73BEF6331C3E4, NULL,
N'ALTER PROCEDURE [dbo].[uspAutomaticIndentReportDetail]  
@ID INT  
AS  
