/****** uspAvailableBookStockDetail ******/
EXEC #Apply07 N'dbo.uspAvailableBookStockDetail', 0x0FE57406DF909065B1CF660F4E594E868D12BB69C2C746579BDA1B337E53BF4A, 0x15282F2A6ADB52D204DB03C53CE74137F989CEC47EC47CEC3DDB44DC979AB4FE, NULL, 0xE5D6797A4561145F9EA454A9D703757EE85DC07A92E913CC059422C7A084BF76, 0xF0D62906DB9338FFEC28755493B8D3D8B24F99E2754D4FE7D858C46247564A41, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspAvailableBookStockDetail]      
@QtyType NVARCHAR(10) = ''2'' ,@ProductId INT = 2,@BranchID int = 4    
as    
SET NOCOUNT ON;
begin    
DECLARE @query NVARCHAR(MAX)      
set @query = ''      
SELECT MP.Code [Product Code],MP.Name [Product Name],[PI].BatchNumber AS [Batch Number],CONVERT(NVARCHAR,[PI].pkdDate,103)AS [PKD Date],CONVERT(NVARCHAR,[PI].ExpiryDate,103)        
AS [Expiry Date],Uom.Name AS [Base UOM],dbo.fngetroundedvalue(isnull((SUM([PI].ActualQty + [PI].ActualFreeQty + [PI].ActualDmgQty)),0)) As [Total Qty],        
dbo.fngetroundedvalue(isnull((SUM([PI].ActualQty)),0)) AS [Saleable Qty],        
dbo.fngetroundedvalue(isnull((SUM([PI].ActualFreeQty)),0)) AS [Free Qty],        
dbo.fngetroundedvalue(isnull((SUM([PI].ActualDmgQty)),0) )AS[Damage Qty],        
dbo.fngetroundedvalue(isnull(([PI].PurchasePrice),0)) AS[Purchase Price],        
dbo.fngetroundedvalue(isnull(([PI].SalesPrice),0)) AS [Sales Price],        
dbo.fngetroundedvalue(isnull(([PI].ECP),0)) AS [ECP],        
dbo.fngetroundedvalue(isnull(([PI].SPLPrice),0)) AS [SPL Price],        
dbo.fngetroundedvalue(isnull(([PI].MRPONPrice),0)) AS [MRP] ,  dbo.fngetroundedvalue(isnull(([PI].ReturnPrice),0)) AS [Return Price] ,       
dbo.fngetroundedvalue(isnull((SUM([PI].ActualQty)* ([PI].PurchasePrice)),0)) AS [Stock Value],  
dbo.fngetroundedvalue(isnull((SUM([PI].ActualDmgQty)* ([PI].PurchasePrice)),0)) AS [Damage Stock Value]     
FROM tblProductInventory AS [PI]        
LEFT JOIN tblMasterProduct AS MP ON MP.ID = [PI].Prodid        
LEFT JOIN tblMasterUom AS Uom ON Uom.ID  = MP.BaseUomID       
WHERE  MP.ID = @ProductId  and [PI].Branchid =  @BranchID ''      
set @query += case when ISNULL(@QtyType,1) = 1 then '' and ([PI].ActualQty > 0 OR [PI].ActualFreeQty > 0 OR [PI].ActualDmgQty > 0)'' else '''' END        
 set @query += '' GROUP BY MP.Code,MP.Name,[PI].Prodid,[PI].BatchNumber,[PI].pkdDate,[PI].ExpiryDate,Uom.Name,        
[PI].PurchasePrice,[PI].SalesPrice,[PI].MRPONPrice,[PI].ECP,[PI].SPLPrice,[PI].ReturnPrice ''    
EXEC sys.sp_executesql @query, N''@QtyType NVARCHAR(10), @ProductId INT, @BranchID int'', @QtyType, @ProductId, @BranchID    
end',
N'[06] nocount';
GO
/****** uspAvailableBookStockHeader ******/
EXEC #Apply07 N'dbo.uspAvailableBookStockHeader', 0x6F8E5ACD99175E8FBE02956BB3F24B090CA87C7FF4D97DD48398122A025DBC7B, 0x230C101B4020E4D4717FA3732C0EB679D5D64090D20E2458DEE247FEBDF64742, NULL, 0xB764B4A6CE85F053B1DE958185F85823EEEDBDF5B067D77969E9E8432C4E1772, 0xE962820F83ABE2C26C1F8C067AB83F4219494D4B2C8D77AE09B424D462C7AE85, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspAvailableBookStockHeader]      
@BranchName NVARCHAR(255) = '''',  @ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255)='''',      
@QtyType int = 1      
AS      
SET NOCOUNT ON;
BEGIN      
DECLARE @query NVARCHAR(MAX)      
set @query = ''      
SELECT  @QtyType  QtyType,Prod.ID ProductID,isnull(PInv.BranchID,0) BranchID,MBO.Name [Branch Name],Prod.Code AS [Product Code],Prod.Name AS [Product Name],    
Prod.EAN,MF.Name as[Manufacture Name],MB.Name as [Brand Name],HI.Name as[Category Name],UOMBase.Name as [Base UOM],    
dbo.fngetroundedvalue(SUM(PInv.ActualQty)) AS [Saleable Qty],dbo.fngetroundedvalue(SUM(PInv.ActualFreeQty)) AS [Free Qty],    
dbo.fngetroundedvalue(SUM(PInv.ActualDmgQty)) AS [Damage Qty],dbo.fngetroundedvalue(SUM(PInv.ActualQty) / Prod.PurchaseCR) AS [Purchase UOM Qty],    
UOMPur.Name AS [Purchase UOM],dbo.fngetroundedvalue(SUM(PInv.ActualQty) / Prod.SalesCR) AS [Sales UOM Qty],    
UOMSale.Name AS [Sales UOM],    
dbo.fngetroundedvalue((SUM(PInv.ActualQty) / (CASE WHEN ISNULL(Prod.ReportingQty,0)=0 THEN 1 ELSE (Prod.ReportingQty) END))) AS [Reporting UOM Qty],    
UOMRep.Name AS [Reporting UOM],dbo.fngetroundedvalue(SUM((PInv.ActualQty) * (PInv.PurchasePrice))) AS [Actual Stock Value],    
dbo.fngetroundedvalue(SUM((PInv.ActualDmgQty) * (PInv.PurchasePrice))) AS [Damage Stock Value]    
FROM tblProductInventory AS PInv    
JOIN tblMasterProduct AS Prod ON Prod.ID =PInv.ProdId    
JOIN TBLMASTERBRANCHOFFICE MBO ON MBO.ID = PInv.BranchID     
JOIN tblMasterUOM AS UOMPur ON UOMPur.ID = Prod.PurchaseUomID    
JOIN tblMasterUOM AS UOMSale ON UOMSale.ID = Prod.SalesUomID    
JOIN tblMasterUOM AS UOMRep ON UOMRep.ID = Prod.ReportingUomID    
JOIN tblMasterUOM AS UOMBase ON UOMBase.ID = Prod.BaseUomID    
JOIN tblMasterManufacturer MF ON MF.ID =Prod.MfrID    
JOIN tblMasterCategory as HI ON HI.ID =Prod.CategoryID    
JOIN tblMasterBrand as MB on MB.ID = Prod.BrandID WHERE Prod.ID > 0''    
 set @query += case when ISNULL(@QtyType,1) = 1 then '' and (PInv.ActualQty > 0 OR PInv.ActualFreeQty > 0 OR PInv.ActualDmgQty > 0)'' else '''' END        
 set @query += case when ISNULL(@BranchName,0) = 0 then '''' else '' AND PInv.BranchID = ''+'' @BranchName ''+'''' END        
 set @query += case when ISNULL(@BrandName,'''') = '''' then '''' else '' AND MB.ID IN (SELECT * from dbo.fnSplitString( ''+'' @BrandName ,'''',''''))'' END        
 set @query += case when ISNULL(@CategoryName,'''') = '''' then '''' else '' AND HI.ID IN (SELECT * from dbo.fnSplitString( ''+'' @CategoryName ,'''',''''))'' END        
 set @query += case when ISNULL(@ManufName,'''') = '''' then '''' else '' AND MF.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ManufName ,'''',''''))'' END        
 set @query += case when ISNULL(@ProductName,'''') = '''' then '''' else '' AND Prod.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ProductName ,'''',''''))'' END        
 set @query += '' GROUP BY Prod.MfrID,MB.ID,HI.ID, Prod.ID,Prod.Code,Prod.EAN,Prod.Name,MF.Name,Mb.Name,HI.Name,    
Prod.PurchaseUomID,Prod.SalesUomID,Prod.ReportingUomID,Prod.ReportingQty,UOMPur.Name,    
UOMSale.Name,UOMRep.Name,UOMBase.Name,Prod.PurchaseCR ,Prod.SalesCR,PInv.BranchID,MBO.Name order by Prod.Name''    
EXEC sys.sp_executesql @query, N''@BranchName NVARCHAR(255), @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @QtyType int'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @QtyType    
END',
N'[06] nocount';
GO
/****** uspBMSWiseLoadingSlipReport ******/
EXEC #Apply07 N'dbo.uspBMSWiseLoadingSlipReport', 0xAB074C9DC4163E1F2DF2B73888652B92461A5369B1E8EB0BFA303F2E5F651D87, 0xD6B94E3E19AC2951EC7AD462E98F6891E903E17952B760055013D58B9DFD6605, NULL, 0xEA3BEC9CEC82C14BC669B328CFCA667D7B6A5C92E49F40467D17BB69E274770D, 0x7AA518FE865E982E94635F9FFE8599D787B1678F16540E73C8F642F9B085FFFB, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspBMSWiseLoadingSlipReport]                    
@BranchName NVARCHAR(255) = ''0'',@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255) = '''',@BeatName NVARCHAR(255) = '''',                  
@SalesmanName NVARCHAR(255) = '''',@DocRange NVARCHAR(MAX) = '''', @FromDate DATE = ''2024-08-01'',@ToDate DATE = ''2026-08-30''                  
AS                  
SET NOCOUNT ON;
BEGIN                  
CREATE TABLE #TempProducts (                
    [Product Code]       VARCHAR(50),                
    [Product Name]       VARCHAR(255),                
    EAN               VARCHAR(50),                
    [Mfr Name]           VARCHAR(255),                
    [Brand Name]         VARCHAR(255),                
    [Category Name]      VARCHAR(255),                
    [Base UOM Qty]        DECIMAL(18, 2),                
    [Base UOM]           VARCHAR(50),                
    [Sales UOM Qty]       DECIMAL(18, 2),                
    [Sales UOM]          VARCHAR(50),                
    [Reporting UOM 1 Qty]  DECIMAL(18, 2),                
    [Reporting UOM 1]     VARCHAR(50),                
    [Reporting UOM 2 Qty]  DECIMAL(18, 2),                
    [Reporting UOM 2]     VARCHAR(50),                
    [MRP On Price]       DECIMAL(18, 2),                
    [Value]             DECIMAL(18, 2)                
);                
                
declare @StrQuery nvarchar(max) = ''''                    
set @StrQuery = ''                  
SELECT  Temp.[Product Code],Temp.[Product Name],Temp.EAN,Temp.[Manufacturer Name] [Mfr Name],                  
[Brand Name],[Category Name],dbo.fnGetRoundedValue(SUM(Temp.[Base UOM Qty]))AS [Base UOM Qty],                  
[Base UOM],dbo.fnGetRoundedValue(SUM(Temp.[Sales UOM Qty]))AS [Sales UOM Qty],[Sales UOM],                  
dbo.fnGetRoundedValue(Left(SUM([Reporting UOM Qty]), CharIndex(''''.'''',SUM([Reporting UOM Qty]))-1))AS [Reporting UOM 1 Qty],[Reporting Uom] [Reporting UOM 1],                  
dbo.fnGetRoundedValue((((RIGHT(SUM([Reporting UOM Qty]), len(SUM([Reporting UOM Qty])) - CharIndex(''''.'''',SUM([Reporting UOM Qty]))+1))*ReportingQty)/ConvFact)) AS [Reporting UOM 2 Qty],                  
[Base UOM] [Reporting UOM 2],dbo.fnGetRoundedValue(ISNULL(Temp.[MRP On Price],0)) AS [MRP On Price],dbo.fnGetRoundedValue(SUM(Temp.Value)) AS [Value] FROM (                  
SELECT MP.Code AS [Product Code],MP.Name AS [Product Name],MP.EAN,                  
MMF.Name AS [Manufacturer Name],MBN.Name [Brand Name],PHL.Name [Category Name],                  
(CASE WHEN TSD.DocPrefix = 15 THEN SUM(TSH.UomQty * isnull(mp.BaseCR,1))                  
ELSE SUM(TSH.UomQty * isnull(mp.BaseCR,1) * -1) END) AS [Base UOM Qty],                  
sum(TSH.NetAmt) AS [Value],Uom.Name AS [Base UOM],Uom1.Name AS [Sales UOM],                  
(CASE WHEN TSD.DocPrefix = 15 THEN SUM((TSH.UomQty * isnull(mp.BaseCR,1)) /                  
isnull(MP.SalesCR,0))                  
ELSE SUM((TSH.UomQty * isnull(mp.BaseCR,1))                  
/ isnull(MP.SalesCR,0)) * -1 END) AS [Sales UOM Qty],                  
UOM2.Name AS [Reporting Uom],                  
CASE WHEN TSD.DocPrefix = 15 THEN (SUM((TSH.UomQty * isnull(mp.BaseCR,1)) / nullif(MP.ReportingQty,0)))                  
ELSE (SUM((TSH.UomQty * isnull(mp.BaseCR,1)) / nullif(MP.ReportingQty,0))) * -1 end as [Reporting UOM Qty],                  
TSH.DetailMRP AS [MRP On Price],MP.ReportingQty,isnull(mp.BaseCR,1) ConvFact                  
FROM tblTranSalesHeader AS TSD                  
JOIN tblTranSalesDetail AS TSH ON TSH.InvId = TSD.ID                  
JOIN tblMasterProduct AS MP ON MP.ID = TSH.ProdId                  
JOIN tblMasterManufacturer AS MMF ON MMF.ID = MP.MfrID                  
JOIN tblMasterBrand MBN ON MBN.ID = MP.BrandID                  
JOIN tblMasterCategory PHL ON PHL.ID = MP.CategoryID                  
JOIN tblMasterBranchOffice BOF ON BOF.ID = TSD.BranchID                  
LEFT JOIN tblProductInventory AS PInv ON PInv.InventoryId = TSH.InventoryId                  
LEFT JOIN tblMasterBeat AS MB ON MB.ID = TSD.BeatID                  
LEFT JOIN tblMasterSalesMan AS MSM ON MSM.ID = TSD.SalesManId                  
LEFT JOIN tblMasterUom AS Uom ON Uom.ID = MP.BaseUomID                  
LEFT JOIN tblMasterUom AS Uom1 ON Uom1.ID = MP.SalesUomID                  
left JOIN tblMasterUom AS [UOM2] ON UOM2.ID = mp.ReportingUomID                  
WHERE TSD.Status IN (1,3,5) AND DocPrefix=15 AND TSH.TaxID > 0 ''                  
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSD.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)        
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)                            
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND MSM.ID IN (SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)                         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ManufName,'''')='''' THEN '''' ELSE '' AND MMF.ID IN (SELECT * from dbo.fnSplitString(  @ManufName ,'''',''''))'' END)                         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BrandName,'''')='''' THEN '''' ELSE '' AND MBN.ID IN (SELECT * from dbo.fnSplitString(  @BrandName ,'''',''''))'' END)                            
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CategoryName,'''')='''' THEN '''' ELSE '' AND PHL.ID IN (SELECT * from dbo.fnSplitString(  @CategoryName ,'''',''''))'' END)                     
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ProductName,'''')='''' THEN '''' ELSE '' AND MP.ID IN (SELECT * from dbo.fnSplitString(  @ProductName ,'''',''''))'' END)                     
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BranchName,''0'')=''0'' THEN '''' ELSE '' AND BOF.ID =  @BranchName '' END)                     
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocRange,'''')='''' THEN '''' ELSE '' AND TSD.DocValue IN (SELECT DocValue FROM dbo.SplitDocRange( @DocRange )) '' END)     
SET @StrQuery = @StrQuery + ''                   
GROUP BY MP.Code,MP.ReportingQty,TSH.UomId,MP.Name,MP.EAN,MMF.Name,Uom.Name, Uom1.Name ,TSH.DetailMRP,TSD.DocPrefix,TSD.ID,MBN.Name,                  
PHL.Name,Uom2.Name,mp.BaseCR)AS Temp                  
GROUP BY Temp.[Product Code],Temp.[Product Name],Temp.EAN,Temp.[Manufacturer Name],                  
[Base UOM],[Sales UOM],[MRP On Price],[Brand Name],[Category Name],[Reporting Uom],ReportingQty,ConvFact''           
PRINT @StrQuery    
 EXEC sys.sp_executesql @StrQuery, N''@BranchName NVARCHAR(255), @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @DocRange NVARCHAR(MAX), @FromDate DATE, @ToDate DATE'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @BeatName, @SalesmanName, @DocRange, @FromDate, @ToDate                    
END',
N'[06] nocount';
GO
/****** uspBranchwiseABSQty ******/
EXEC #Apply07 N'dbo.uspBranchwiseABSQty', 0xF2102BE802100AEC4FA8781BCC43CE81C20719043B857273FE60E2E4BB04F9F0, NULL, NULL, 0xE88CF15400048883D3BF07C0AC0E8EC934A7A7D90DFECC77BB72AD23928EE80C, 0x69AF4B197566F6D4704D184457A4265D0EA0BF3885ECB65E664263212628F135, NULL,
N'--uspBranchwiseABSQty 34
ALTER proc [dbo].[uspBranchwiseABSQty]
@ProductID int
as
SET NOCOUNT ON;
begin
select PV.BranchID,MBO.Name Branch,dbo.fngetroundedvalue(SUM(ActualQty)) ActualQty,
dbo.fngetroundedvalue(SUM(ActualFreeQty)) ActualFreeQty,
dbo.fngetroundedvalue(SUM(ActualDmgQty)) ActualDmgQty,
MP.Name ProductName,MP.Code ProductCode 
from tblProductInventory PV 
JOIN tblMasterBranchOffice MBO ON MBO.ID = PV.BranchID 
JOIN tblMasterProduct MP ON MP.ID = PV.ProdID 
WHERE PRODID = @ProductID
GROUP BY PV.BranchID,MBO.Name,MP.Name,MP.Code
end',
N'[export] nocount';
GO
/****** uspBulkCollectionData ******/
EXEC #Apply07 N'dbo.uspBulkCollectionData', 0xC7FF172333119C30A37E3769DB58195C9E683C9CBA2A83AA455CB8726EA27FCD, NULL, NULL, 0x36203A4E8179399DBE67DA6AF134BF51023EBB2294315082148A3CE099659358, 0x573F09A01631E7FF2624889F34BD32A5EA142D705D9386C2C61A47CA1EF40220, NULL,
N'ALTER PROC [dbo].[uspBulkCollectionData]
@BranchID int = 4,  @BeatID NVARCHAR(255)='''',@SalesManID NVARCHAR(255)='''',@CustID NVARCHAR(255)='''',@AsonDate date = ''2026-06-17''
AS
SET NOCOUNT ON;
BEGIN
SELECT PartyName ,TransName,DocId,RefNo,FORMAT(TransDate,''dd-MMM-yyyy'') DocDate,NetAmt,	Balance,InvId,CustId,DocPrefix,DocValue,BeatName,SalesmanName,
BeatID,SalesmanID,IndexNo,FAID
 FROM (
--Invoice & SR
SELECT MC.Name PartyName,DS.TransName,TSH.DocId,DocRef RefNo,InvDate TransDate,                              
((CASE WHEN TSH.DocPrefix = 15 THEN NetAmt ELSE NetAmt * -1 END) ) NetAmt,              
((CASE WHEN TSH.DocPrefix = 15 THEN Balance ELSE Balance * -1 END)) Balance,TSH.ID InvId,TSH.CustId,TSH.DocPrefix,TSH.DocValue ,                        
mb.Name BeatName,MS.Name SalesmanName,TSH.BeatID,TSH.SalesmanID,
(CASE WHEN TSH.DocPrefix = 15 THEN 4 ELSE 1 END) IndexNo,MC.FAID             
 FROM tblTranSalesHeader TSH
JOIN tblMasterCustomer MC ON MC.ID = TSH.CustId                           
JOIN tblDocumentSeries DS ON DS.TransID = TSH.DocPrefix
LEFT join tblmasterbeat mb on mb.ID = TSH.BeatID                    
LEFT JOIN tblMasterSalesman MS ON MS.ID = TSH.SALESMANID                    
WHERE (TSH.BranchID = @BranchID AND TSH.InvDate <= @AsonDate AND Status IN (1,3,5,6,7) AND Balance > 0) AND
(@BeatID = '''' OR TSH.BeatID IN (SELECT value FROM string_split(@BeatID,'',''))) AND
(@SalesManID = '''' OR TSH.SalesManID IN (SELECT value FROM string_split(@SalesManID,'',''))) AND
(@CustID = '''' OR TSH.CustID IN (SELECT value FROM string_split(@CustID,'','')))
UNION ALL
--collection
SELECT MC.Name CustomerName,DS.TransName,TSH.DocId ,ColDocRefNo RefNo,ColDate DocDate,                              
(ColAmt * -1) NetAmt,(Balance* -1) Balance,ColID,MC.ID CustId,TSH.DocPrefix,TSH.DocValue ,                        
mb.Name BeatName,MS.Name SalesmanName,TSH.BeatID,TSH.SalesmanID,2,MC.FAID             
 FROM tblTranCollectionHeader TSH                              
JOIN tblMasterCustomer MC ON MC.FAID = TSH.AccID                           
JOIN tblDocumentSeries DS ON DS.TransID = TSH.DocPrefix
LEFT join tblmasterbeat mb on mb.ID = TSH.BeatID                    
LEFT JOIN tblMasterSalesman MS ON MS.ID = TSH.SALESMANID                     
WHERE TSH.BranchID = @BranchID AND TSH.ColDate <= @AsonDate AND Status IN (1,3,5) AND TSH.DocPrefix in (19) AND Balance > 0 AND
(@BeatID = '''' OR TSH.BeatID IN (SELECT value FROM string_split(@BeatID,'',''))) AND
(@SalesManID = '''' OR TSH.SalesManID IN (SELECT value FROM string_split(@SalesManID,'',''))) AND
(@CustID = '''' OR MC.ID IN (SELECT value FROM string_split(@CustID,'','')))
UNION ALL
--RV
select MC.Name CustomerName,DS.TransName,PV.DocID,RefNo ReferNo,PV.DocDate DocDate,                
(NetAmount) NetAmt,(Balance) Balance,PV.ID PRVID,MC.ID CustId,PV.TransID DocPrefix,PV.DocValue,                
NULL btname,NULL salesmanname,0,0,5,MC.FAID             
 from tblTranPRVoucher PV                
JOIN tblMasterCustomer MC ON MC.FAID = pv.PartyID       
JOIN tblDocumentSeries DS ON DS.TransID = PV.TransID
left join tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID
where PV.BranchID = @BranchID AND PV.DocDate <= @AsonDate AND PV.TransID = 7 and Status in (1,3,5) and Balance > 0 AND
(@BeatID = '''' OR BSM.BeatID IN (SELECT value FROM string_split(@BeatID,'',''))) AND
(@SalesManID = '''' OR BSM.SalesManID IN (SELECT value FROM string_split(@SalesManID,'',''))) AND
(@CustID = '''' OR MC.ID IN (SELECT value FROM string_split(@CustID,'','')))
UNION ALL
--CN
select MC.Name CustomerName,DS.TransName,ND.DocId,RefNo DocRefNo,ND.DocDate DocDate,    
(NoteValue * -1) NetAmt,(Balance * -1) Balance,ND.ID Ident,MC.ID CustId,ND.TransID DocPrefix,ND.DocValue,                
NULL btname,NULL salesmanname,0,0,3,MC.FAID from tblNoteDetails ND    
JOIN tblMasterCustomer MC ON MC.FAID = ND.PartyId     
JOIN tblDocumentSeries DS ON DS.TransID = ND.TransID
left join tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID
where ND.BranchID = @BranchID AND ND.DocDate <= @AsonDate AND ND.TransID = 4 and Status in (1,3,5) and Balance > 0 AND
(@BeatID = '''' OR BSM.BeatID IN (SELECT value FROM string_split(@BeatID,'',''))) AND
(@SalesManID = '''' OR BSM.SalesManID IN (SELECT value FROM string_split(@SalesManID,'',''))) AND
(@CustID = '''' OR MC.ID IN (SELECT value FROM string_split(@CustID,'','')))) AS REC
ORDER BY PartyName,IndexNo,TransDate,DocID
END',
N'[export] nocount';
GO
/****** uspBulkCollectionValidateDoc ******/
EXEC #Apply07 N'dbo.uspBulkCollectionValidateDoc', 0x0CB69B64695550C642724FA2ABF3FDCA3E7794FAF486F1CB75EFA86FEFCB6F97, NULL, NULL, 0xAD3CB8C369954A0214C0D8C99F599685F17F407B533C441FC50707B1C8033B9D, 0xCD4DE300B4097AA42D561D47758FBB003EAD23575B1FCE3FE8971472BC1D1716, NULL,
N'ALTER proc [dbo].[uspBulkCollectionValidateDoc]  
@tvpBulkCollectionDocVerify dbo.tvpBulkCollectionDocVerify READONLY  
as  
SET NOCOUNT ON;
begin  
declare @nCount int= (select count(*) from @tvpBulkCollectionDocVerify),@n int = 1  
declare @TransID int = 15,@ID int = 660,@FAID INT = 45,@Balance decimal(25,4) = 136  
DECLARE @Status INT,@DocBalance DECIMAL(25,4);  
create table #errordocs(TransID int,ID int,FAID int,Message nvarchar(100))  
while(@nCount >= @n)  
BEGIN  
select @TransID = TransID,@ID = ID,@FAID = FAID,@Balance = Balance from @tvpBulkCollectionDocVerify where Ident = @n  
if(@TransID  IN (15,16,17))--Invoice , SR  
BEGIN  
 SELECT @Status = Status,@DocBalance = Balance FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE ID = @ID AND DocPrefix = @TransID;  
END  
if(@TransID  IN (4,5)) --Credit, Debit Note  
BEGIN  
 SELECT @Status = Status,@DocBalance = Balance FROM tblnotedetails WITH (READCOMMITTEDLOCK) WHERE ID = @ID AND transid = @TransID;  
END  
if(@TransID  IN (6,7)) --PV, RV  
BEGIN  
 SELECT @Status = Status,@DocBalance = Balance FROM tbltranprvoucher WITH (READCOMMITTEDLOCK) WHERE ID = @ID AND transid = @TransID;  
END  
if(@TransID  IN (19)) --Collection  
BEGIN  
 SELECT @Status = Status,@DocBalance = Balance FROM tbltrancollectionheader WITH (READCOMMITTEDLOCK) WHERE ColID = @ID AND DocPrefix = @TransID;  
END  
IF @Status IS NULL  
        INSERT INTO #ErrorDocs  
        VALUES (@TransID,@ID,@FAID,''Document data not found'');  
  
    ELSE IF @Status IN (2,4)  
        INSERT INTO #ErrorDocs  
        VALUES (@TransID,@ID,@FAID,''Document status changed'');  
  
    ELSE IF @DocBalance <> @Balance  
        INSERT INTO #ErrorDocs  
        VALUES (@TransID,@ID,@FAID,''Document balance mismatch. Already Partially/Fully collected'');  
  
SET @n = @n + 1;  
END  
select * from #errordocs  
drop table #errordocs  
END',
N'[export] nocount;readcommittedlock=4';
GO
/****** uspBulkOrdertakendata ******/
EXEC #Apply07 N'dbo.uspBulkOrdertakendata', 0x86470C93DA779AFF61054EFA86228F43760E83F3DF87F7AF4F516465A8C0AB32, NULL, NULL, 0xFD785C985ACEF5BC79E7186CAA410D436880E0A1877FE8AF13DBEF4FF673DFF3, 0xBB80DDB956CDC742AA9A54599541E1F4727F9ABB84A9BC231087E47CE7169930, NULL,
N'--uspBulkOrdertakendata 2,0,0,null,0
ALTER proc [dbo].[uspBulkOrdertakendata]
@Mode int,@IDorBeatID INT = 0,@SalesmanID int = 0,@CustomerID INT = null,@ShowAll int = 0
AS
SET NOCOUNT ON;
BEGIN
IF(@Mode = 1)
BEGIN
select ID,Name from tblMasterSalesman where Active = 1 ORDER BY Name
               
SELECT ID,Name FROM tblMasterBeat WHERE Active = 1 ORDER BY Name                    
              
SELECT ID,Code,Name,Billadd1+'' ''+Billadd2+'' ''+Billadd3 Address FROM tblMasterCustomer WHERE Active = 1 ORDER BY Name 
END
IF(@Mode = 2)
BEGIN
SELECT OTH.ID,FORMAT(OTH.DocDate,''dd/MMM/yyyy'') OTDate,MBO.Name Branch,MB.Name Beat,SM.Name Salesman,MC.Name CustomerName,
convert(decimal(15,2),sum(OTD.Amount)) Value,count(OTD.ProdID) ItemCount,convert(decimal(15,2),sum(OTD.DisAmt)) DiscAmt,
STS.Description Status,OTH.Status StatusID,Remark,Narration FROM tblTranOrderTakenHeader OTH
JOIN tblTranOrderTakenDetail OTD ON OTD.ID = OTH.ID
JOIN tblMasterCustomer MC ON MC.ID = OTH.CustID
JOIN tblMasterBranchOffice MBO ON MBO.ID = OTH.BranchID
LEFT JOIN tblMasterBeat MB ON MB.ID = OTH.BeatID
LEFT JOIN tblMasterSalesman SM ON SM.ID = OTH.SalesManID
JOIN tblStatus STS ON STS.ID = OTH.Status
WHERE OTH.ActivityID = 1 AND OTH.Status = (CASE WHEN @ShowAll = 0 THEN 1 ELSE OTH.Status END) AND
(@IDorBeatID = 0 OR OTH.BeatID = @IDorBeatID) AND
(@SalesmanID = 0 OR OTH.SalesManID = @SalesmanID) AND
(isnull(@CustomerID,0) = 0 OR OTH.CustID = @CustomerID)
GROUP BY OTH.ID,DocDate,MBO.Name,MB.Name,SM.Name,MC.Name,STS.Description,OTH.Status,Remark,Narration
ORDER BY OTH.DocDate,MB.Name
END
IF(@Mode = 3)
BEGIN
SELECT MP.Code,MP.Name,dbo.fnGetRoundedValue(OTD.Qty) Qty,dbo.fnGetRoundedValue(OTD.Price) Price,
dbo.fnGetRoundedValue(OTD.DisPern) DiscPern,dbo.fnGetRoundedValue(OTD.DisAmt) DiscAmt,
dbo.fnGetRoundedValue(OTD.Amount) GrossAmt FROM tblTranOrderTakenDetail OTD
JOIN tblMasterProduct MP ON MP.ID = OTD.ProdID
where OTD.ID = @IDorBeatID
ORDER BY SerialNo
END
END',
N'[export] nocount';
GO
/****** uspCancelCollection ******/
EXEC #Apply07 N'dbo.uspCancelCollection', 0xC1993C15BE370A6231B8D81A10F1DA5510B511552C1DD4DEB5118ADAF9324375, NULL, NULL, 0x96B07213F9594EDA83B6A4D1F0D9BBEEC64143313B67DF2284A65DF0404E33E8, 0x2E7A3944FF40A01BB84E7A24812B476E37DD9C4BA93ACF5B1A690C0FCDD518AD, NULL,
N'ALTER PROC [dbo].[uspCancelCollection]          
@TranDocPrefix INT,@CollID INT,@UID INT,@AllowNegativeBal INT = NULL,@nStatus INT =null,@Remark nvarchar(255) = null,@Narration nvarchar(255) = null          
AS          
SET NOCOUNT ON;
BEGIN TRANSACTION          
BEGIN TRY          
DECLARE @PartyAcc INT, @ExpanceAcc INT,@AccCount INT,@AccountName NVARCHAR(255),          
@TempPaymentMode INT,@TempRecdAmt DECIMAL (25,6),          
@TempDocStatus INT,@PaymentModeStatus INT,@AccID INT,@ExpanceAccID INT          
-- Checking For Amount MissMatch          
DECLARE @RecdAmt DECIMAL (25,6),@BalanceAmt DECIMAL (25,6)          
DECLARE @AdjustedAmt DECIMAL (25,6),@AdjustmentAmt DECIMAL (25,6),@CollType INT,@DocExtraAdjustedAmt DECIMAL (25,6),@nCurrentStatus INT          
SET @nCurrentStatus = (CASE WHEN @TranDocPrefix IN (19,10) THEN (SELECT top 1 Status FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE ColID = @CollID)          
WHEN @TranDocPrefix IN (18,11) THEN (SELECT top 1 Status FROM tblTranPaymentHeader WITH (READCOMMITTEDLOCK) WHERE PYID = @CollID) END)          
--SELECT * FROM tblMastDocSeries          
--SELECT * FROM tblTranCollectionHeader order by 1 desc          
--SELECT * FROM tblTranPaymentHeader order by 1 desc          
IF(isnull(@nStatus,0) = isnull(@nCurrentStatus,0))          
BEGIn          
IF @TranDocPrefix = 19          
BEGIn          
IF ISNULL((SELECT COUNT(ColID) FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE ColID=@CollID AND Type=1),0)>0          
BEGIN          
RAISERROR(''TYPE'',16,1);          
END          
END          
CREATE TABLE #Temp(ID int identity ,CollID int,DocPrefix INT,DocValue INT, IdentID int, ColValue DECIMAL (25,6))          
IF @TranDocPrefix=19 OR @TranDocPrefix=10          
BEGIn          
SET @TempDocStatus=(SELECT [Status] FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) where ColID = @CollID)          
SELECT @PaymentModeStatus=(SELECT [Status] FROM tblCollPMDetails WITH (READCOMMITTEDLOCK) where ColID = @CollID)          
          
          
SELECT @PartyAcc=AccID,@ExpanceAcc=ExpanceAcc,@TempPaymentMode=ColMode,@TempRecdAmt=ColAmt FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) where ColID = @CollID          
          
          
-- Check Cash Acc Balance          
DECLARE @PYModeAmt DECIMAL (25,6),@PYFAType NVARCHAR(10),@CashBankAccID INT,@CurrentDate DATE=(SELECT GETDATE())          
DECLARE @PYOutputValue TABLE (Amt DECIMAL(25,6),FAType NVARCHAR(10)) --18.9          
IF ISNULL(@TempPaymentMode,0)=1          
BEGIn          
SET @CashBankAccID = (SELECT FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=''cash'')          
INSERT INTO @PYOutputValue(Amt,FAType) EXEC uspLoadClosingBalance 1,@CashBankAccID,@CurrentDate          
-- Get Value From Result          
SELECT @PYModeAmt=Amt,@PYFAType=FAType FROM @PYOutputValue          
IF @PYFAType=''Cr'' OR @PYModeAmt<@TempRecdAmt          
BEGIN          
IF ISNULL(@AllowNegativeBal,0)=0          
BEGIN          
RAISERROR(''Bal'',16,1)          
END          
END          
END          
-- Check Bank Acc Balance          
IF ISNULL(@TempPaymentMode,0)=4          
BEGIN          
SELECT @CashBankAccID=BankAccID FROM tblTranCollectionHeader AS Header WITH (READCOMMITTEDLOCK)          
JOIN tblCollPMDetails AS PM WITH (READCOMMITTEDLOCK)          
ON Header.ColID=PM.ColID          
WHERE Header.ColID=@CollID          
INSERT INTO @PYOutputValue(Amt,FAType) EXEC uspLoadClosingBalance 1,@CashBankAccID,@CurrentDate          
-- Get Value From Result          
SELECT @PYModeAmt=Amt,@PYFAType=FAType FROM @PYOutputValue          
IF @PYFAType=''Cr'' OR @PYModeAmt<@TempRecdAmt          
BEGIN          
IF ISNULL(@AllowNegativeBal,0)=0          
BEGIN          
RAISERROR(''Bal'',16,1)          
END          
END          
END          
-- Check Coupon Cancelling          
--IF ISNULL(@TempPaymentMode,0)=6          
--BEGIN          
--DECLARE @tempActualCount INT,@SettledCount INT          
--SELECT @tempActualCount=ISNULL(SUM(DCount),0),@SettledCount=ISNULL(SUM(SettlementCount),0)          
--FROM tblmasterdenominationPMDetails WHERE FormDocPrefix=@TranDocPrefix AND TransID=@CollID          
--IF @tempActualCount=@SettledCount          
--BEGIN          
--UPDATE tblmasterdenominationPMDetails SET Status=4 WHERE FormDocPrefix=@TranDocPrefix AND TransID=@CollID          
--END          
--ELSE          
--BEGIN          
--RAISERROR(''SETTLED'',16,1)          
--END          
--END          
          
IF @TranDocPrefix=19          
BEGIN          
--SELECT * FROM tblDocumentSeries     
--Collection          
-- Get Recd Amt And Balance Amt          
SELECT @RecdAmt=ISNULL(ColAmt,0),@BalanceAmt=ISNULL(Balance,0) FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE ColID=@CollID          
--SELECT * FROM tblTranCollectionHeader WHERE ColID=2899          
--Get Adjusted Amt          
SELECT @AdjustedAmt=ISNULL(SUM(ColValue),0) FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE ColID=@CollID AND DocPrefix IN(4,6,19,16,10)          
--SELECT ISNULL(SUM(ColValue),0) FROM tblTranCollectionDetail WHERE ColID=2899 AND DocPrefix IN(3,5,6)          
--Get AdjustMent Amt          
SELECT @AdjustmentAmt=ISNULL(SUM(ColValue),0) FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE ColID=@CollID AND DocPrefix IN (15,5,7)          
--SELECT ISNULL(SUM(ColValue),0) FROM tblTranCollectionDetail WHERE ColID=2899 AND DocPrefix IN(2,16,29)          
-- Get Adjusted amt          
SELECT @DocExtraAdjustedAmt=ISNULL(SUM(AdjAmt),0) FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE ColID=@CollID AND DocPrefix IN (15,5,7)          
--GROUP BY AdjAmt HAVING ISNULL(AdjAmt,0)>0          
AND AdjAmt > 0          
--SELECT ISNULL(SUM(AdjAmt),0) FROM tblTranCollectionDetail WHERE ColID=2899 AND DocPrefix IN(2,16,29) AND AdjAmt > 0          
--select * from tblMastDocSeries where DocID in (2,3,5,6,16,29)          
-------------------          
IF ISNULL((@RecdAmt+@AdjustedAmt),0)!=ISNULL((@BalanceAmt+@AdjustmentAmt+ISNULL(@DocExtraAdjustedAmt,0)),0)          
BEGIN          
RAISERROR(''PROC'',16,1)          
END          
END          
          
IF @TranDocPrefix=10          
BEGIN          
--Other Collection          
-- Get Recd Amt And Balance Amt          
SELECT @RecdAmt=ISNULL(ColAmt,0),@BalanceAmt=ISNULL(Balance,0),@CollType=COLLType FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE ColID=@CollID          
--Get Adjusted Amt          
SELECT @AdjustedAmt=ISNULL(SUM(ColValue),0) FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE ColID=@CollID AND DocPrefix IN(4,19,10,6)          
--Get AdjustMent Amt          
SELECT @AdjustmentAmt=ISNULL(SUM(ColValue),0) FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE ColID=@CollID AND DocPrefix IN(5,18,7,11)          
-- Get Adjusted amt          
SELECT @DocExtraAdjustedAmt=ISNULL(SUM(AdjAmt),0) FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE ColID=@CollID AND DocPrefix IN(8,18,7,11)          
--GROUP BY AdjAmt HAVING          
AND AdjAmt>0          
IF ISNULL(@CollType,0)!=2 AND ISNULL(@CollType,0)!=3          
BEGIN          
IF ISNULL((@RecdAmt+@AdjustedAmt),0)!=ISNULL((@BalanceAmt+@AdjustmentAmt+ISNULL(@DocExtraAdjustedAmt,0)),0)          
BEGIN          
RAISERROR(''PROC'',16,1)          
END          
END          
END          
IF @TempDocStatus=1 OR @TempDocStatus=3          
BEGIn          
IF ISNULL(@PaymentModeStatus,0)=0 OR @PaymentModeStatus=1 OR @PaymentModeStatus=3          
BEGIN          
UPDATE dbo.tblTranCollectionHeader set [Status] = 4,ClBy=@UID,ClDate=GETDATE(),Remarks = @Remark,Narration = @Narration where ColID = @CollID          
UPDATE dbo.tblCollPMDetails SET [Status]=4 WHERE ColID = @CollID          
INSERT INTO #Temp SELECT ColID,DocPrefix,DocValue ,DocID,TotalAmtAdj from dbo.tblTranCollectionDetail WITH (READCOMMITTEDLOCK) where ColID = @CollID          
END          
ELSE          
BEGIN          
RAISERROR(''PAYMENT'',16,1)          
END          
ENd          
ELSE          
BEGIN          
RAISERROR(''CANCELLED'',16,1)          
END          
END          
IF @TranDocPrefix=11 OR @TranDocPrefix=18          
BEGIN          
SET @TempDocStatus=(SELECT [Status] FROM tblTranPaymentHeader WITH (READCOMMITTEDLOCK) where PYID = @CollID)          
SET @PaymentModeStatus=(SELECT [Status] FROM tblPaymentPMDetail WITH (READCOMMITTEDLOCK) where PYID = @CollID)          
SELECT @PartyAcc=AccID,@ExpanceAcc=ExpanseAcc,@TempPaymentMode=PYMode FROM tblTranPaymentHeader WITH (READCOMMITTEDLOCK) where PYID = @CollID          
          
--IF ISNULL(@TempPaymentMode,0)=6          
--BEGIN          
--DECLARE @tempCancelSettled TABLE (D_ID INT,DenoID INT,StlCount INT)          
--INSERT INTO @tempCancelSettled          
--SELECT DID,DenoID,StlCount FROM tblSettlementDetailforCoupon          
--WHERE TrnDocPrefix=@TranDocPrefix AND STMID=@CollID AND Status=1 AND TransType=1          
          
--IF ISNULL((SELECT COUNT(*) FROM @tempCancelSettled),0)>0          
--BEGIN          
--UPDATE tblmastdenominationPMDetails SET SettlementCount = (SettlementCount+Temp.StlCount),Status=1          
--FROM @tempCancelSettled AS Temp          
--WHERE tblmastdenominationPMDetails.DId = Temp.D_ID AND tblmastdenominationPMDetails.DenoID = Temp.DenoID          
--UPDATE tblSettlementDetailforCoupon SET Status=4 WHERE TrnDocPrefix=@TranDocPrefix AND STMID=@CollID AND TransType=1          
--END          
--END          
          
IF @TranDocPrefix=18          
BEGIN          
--SELECT * FROM tblDocumentSeries WHERE TransID IN(5,18,12)      
--Payment          
-- Get Recd Amt And Balance Amt          
SELECT @RecdAmt=ISNULL(PYAmt,0),@BalanceAmt=ISNULL(Balance,0) FROM tblTranPaymentHeader WITH (READCOMMITTEDLOCK) WHERE PYID=@CollID          
--Get Adjusted Amt          
SELECT @AdjustedAmt=ISNULL(SUM(BillPYValue),0) FROM tblTranPaymentDetail WITH (READCOMMITTEDLOCK) WHERE PYID=@CollID AND DocPrefix IN (5,18,11,12)          
--Get AdjustMent Amt          
SELECT @AdjustmentAmt=ISNULL(SUM(BillPYValue),0) FROM tblTranPaymentDetail WITH (READCOMMITTEDLOCK) WHERE PYID=@CollID AND DocPrefix IN (1,4,6)          
-- Get Adjusted amt          
SELECT @DocExtraAdjustedAmt=ISNULL(SUM(AdjAmt),0) FROM tblTranPaymentDetail WITH (READCOMMITTEDLOCK) WHERE PYID=@CollID AND DocPrefix IN (1,4,6)          
--GROUP BY AdjAmt HAVING          
AND AdjAmt>0          
IF ISNULL((@RecdAmt+@AdjustedAmt),0)!=ISNULL((@BalanceAmt+@AdjustmentAmt+ISNULL(@DocExtraAdjustedAmt,0)),0)          
BEGIN          
RAISERROR(''PROC'',16,1)          
END          
END          
IF @TranDocPrefix=11          
BEGIN          
--Other Payment          
-- Get Recd Amt And Balance Amt          
SELECT @RecdAmt=ISNULL(PYAmt,0),@BalanceAmt=ISNULL(Balance,0),@CollType=PYType FROM tblTranPaymentHeader WITH (READCOMMITTEDLOCK) WHERE PYID=@CollID          
--Get Adjusted Amt          
SELECT @AdjustedAmt=ISNULL(SUM(BillPYValue),0) FROM tblTranPaymentDetail WITH (READCOMMITTEDLOCK) WHERE PYID=@CollID AND DocPrefix IN(5,18,7,11)          
--Get AdjustMent Amt          
SELECT @AdjustmentAmt=ISNULL(SUM(BillPYValue),0) FROM tblTranPaymentDetail WITH (READCOMMITTEDLOCK) WHERE PYID=@CollID AND DocPrefix IN(4,19,10,6)          
-- Get Adjusted amt          
SELECT @DocExtraAdjustedAmt=ISNULL(SUM(AdjAmt),0) FROM tblTranPaymentDetail WITH (READCOMMITTEDLOCK) WHERE PYID=@CollID AND DocPrefix IN(4,19,10,6)          
--GROUP BY AdjAmt HAVING          
AND AdjAmt>0          
IF ISNULL(@CollType,0)!=2 AND ISNULL(@CollType,0)!=3          
BEGIN          
IF ISNULL((@RecdAmt+@AdjustedAmt),0)!=ISNULL((@BalanceAmt+@AdjustmentAmt+ISNULL(@DocExtraAdjustedAmt,0)          
),0)          
BEGIN          
RAISERROR(''PROC'',16,1)          
END          
END          
END          
          
IF @TempDocStatus=1 OR @TempDocStatus=3          
BEGIN          
IF ISNULL(@PaymentModeStatus,0)=0 OR @PaymentModeStatus=1 OR @PaymentModeStatus=3          
BEGIN          
          
UPDATE dbo.tblTranPaymentHeader set [Status] = 4,ClBy=@UID,ClDate=GETDATE(),Remarks = @Remark,Narration = @Narration where PYID = @CollID          
UPDATE dbo.tblPaymentPMDetail SET [Status]=4 WHERE PYID = @CollID          
DECLARE @PaymentModeID INT=(SELECT PYMode FROM tblTranPaymentHeader WITH (READCOMMITTEDLOCK) where PYID = @CollID )          
IF @PaymentModeID=2          
BEGIN          
-- Cancel Cheque Status          
DECLARE @BankFAAccID INT,@ChequeNo INT,@ChequeRefNoWithChequeNo NVARCHAR(50),@BankAccID INT,@RefNo NVARCHAR(50)          
DECLARE @ChequeBookID INT          
SELECT @BankFAAccID=BankAccID,@ChequeNo=[Cheque/DD Number],@ChequeRefNoWithChequeNo=ChequeRefNoWithChequeNo          
FROM tblPaymentPMDetail WITH (READCOMMITTEDLOCK) WHERE PYID = @CollID          
          
SET @BankAccID=(SELECT ID FROM tblMasterBankAccount WITH (READCOMMITTEDLOCK) WHERE FAID=@BankFAAccID)          
SET @RefNo=(SELECT SUBSTRING(@ChequeRefNoWithChequeNo,0,(SELECT CHARINDEX(''-'', @ChequeRefNoWithChequeNo))-1))          
SET @ChequeBookID=(SELECT ChequebookId FROM tblMasterChequeBook WITH (READCOMMITTEDLOCK) WHERE BankAccountID=@BankAccID AND ChequeBookreferNo=@RefNo)          
UPDATE tblMasterChequeBookDetail SET [Status]=4 WHERE ChequebookId=@ChequeBookID AND ChequeNo=@ChequeNo          
END          
          
INSERT INTO #Temp SELECT PYID,DocPrefix,DocValue ,DocID,TotalAmtAdj from dbo.tblTranPaymentDetail WITH (READCOMMITTEDLOCK) where PYID = @CollID          
END          
ELSE          
BEGIN          
RAISERROR(''PAYMENT'',16,1)        END          
END          
ELSE          
BEGIN          
RAISERROR(''CANCELLED'',16,1)          
END          
--END          
-- ELSE          
-- BEGIN          
--RAISERROR(''PAYMENT'',16,1)          
-- END          
END          
UPDATE tblFAJournal SET [Status]=4,ClBy=@UID,ClDate=GETDATE(),Remarks = @Remark where TransId = @CollID AND DocPrefix=@TranDocPrefix--,Narration = @Narration          
DECLARE @DetailCount int          
DECLARE @Count int          
SET @DetailCount = (SELECT COUNT(CollID) FROM #Temp)          
SET @Count = 1          
          
WHILE (@Count <= @DetailCount)          
BEGIN          
CREATE TABLE #TEMP2 (DocValue INT)          
DECLARE @TempID INT,@TempAmt DECIMAL (25,6),@DocValue INT,@DocPrefix INT ,@DocCount INT          
SET @TempID = (SELECT IdentID FROM #Temp WHERE ID = @Count)          
SET @TempAmt = (SELECT ColValue FROM #Temp WHERE ID = @Count)          
SET @DocValue = (SELECT DocValue FROM #Temp WHERE ID = @Count)          
SET @DocPrefix = (SELECT DocPrefix FROM #Temp WHERE ID = @Count)          
          
IF @DocPrefix=19 OR @DocPrefix=10          
BEGIN          
UPDATE dbo.tblTranCollectionHeader SET Balance = Balance+@TempAmt WHERE ColID = @TempID          
          
INSERT INTO #TEMP2 SELECT DocValue FROM dbo.tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE DocValue = @DocValue AND DocPrefix=@DocPrefix          
AND (ColDate BETWEEN (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) AND (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)))          
SET @DocCount = (SELECT COUNT(DocValue) FROM #TEMP2)          
IF(@DocCount = 1)          
BEGIN          
UPDATE dbo.tblTranCollectionHeader SET [Status] = 1 WHERE ColID = @TempID          
END          
ELSE          
BEGIN          
UPDATE dbo.tblTranCollectionHeader SET [Status] = 3 WHERE ColID = @TempID          
END          
END          
          
IF @DocPrefix=18 OR @DocPrefix=11          
BEGIN          
UPDATE dbo.tblTranPaymentHeader SET Balance = Balance+@TempAmt WHERE PYID = @TempID          
          
INSERT INTO #TEMP2 SELECT DocValue FROM dbo.tblTranPaymentHeader WITH (READCOMMITTEDLOCK) WHERE DocValue = @DocValue AND PYPrefix=@DocPrefix          
AND (PYDate BETWEEN (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) AND (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)))          
SET @DocCount = (SELECT COUNT(DocValue) FROM #TEMP2)          
IF(@DocCount = 1)          
BEGIN          
UPDATE dbo.tblTranPaymentHeader SET [Status] = 1 WHERE PYID = @TempID          
END          
ELSE          
BEGIN          
UPDATE dbo.tblTranPaymentHeader SET [Status] = 3 WHERE PYID = @TempID          
END          
END          
          
IF @DocPrefix=15 OR @DocPrefix=16          
BEGIN          
UPDATE dbo.tblTranSalesHeader SET Balance = Balance+@TempAmt WHERE Id = @TempID          
INSERT INTO #TEMP2 SELECT DocValue FROM dbo.tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE DocValue = @DocValue AND DocPrefix=@DocPrefix          
AND (InvDate BETWEEN (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) AND (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)))          
SET @DocCount = (SELECT COUNT(DocValue) FROM #TEMP2)          
IF(@DocCount = 1)          
BEGIN          
IF @DocPrefix=15          
BEGIN          
UPDATE dbo.tblTranSalesHeader SET [Status] = 1 WHERE Id = @TempID          
END          
IF @DocPrefix=16          
BEGIN          
DECLARE @Type INT          
SELECT @Type=TransactionType FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id=@TempID          
-- Change document to Sales Return If Type=2          
IF @Type=2          
BEGIN          
UPDATE dbo.tblTranSalesHeader SET [Status] = 6 WHERE Id = @TempID          
END          
-- Change document to Damage Return If Type=2          
IF @Type=3          
BEGIN          
UPDATE dbo.tblTranSalesHeader SET [Status] = 7 WHERE Id = @TempID          
END          
END          
END          
ELSE          
BEGIN          
UPDATE dbo.tblTranSalesHeader SET [Status] = 3 WHERE Id = @TempID          
END          
END          
IF @DocPrefix=1 OR @DocPrefix=12          
BEGIN          
UPDATE dbo.tblTransPurchaseHeader SET Balance = Balance+@TempAmt WHERE ID = @TempID          
          
INSERT INTO #TEMP2 SELECT DocValue FROM dbo.tblTransPurchaseHeader WITH (READCOMMITTEDLOCK) WHERE DocValue = @DocValue AND TransID=@DocPrefix          
AND (Date BETWEEN (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) AND (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)))          
SET @DocCount = (SELECT COUNT(DocValue) FROM #TEMP2)          
IF(@DocCount = 1)          
BEGIN          
IF @DocPrefix=1          
BEGIN          
UPDATE dbo.tblTransPurchaseHeader SET [Status] = 1 WHERE ID = @TempID          
END          
IF @DocPrefix=12          
BEGIN          
UPDATE dbo.tblTransPurchaseHeader SET [Status] = 6 WHERE ID = @TempID          
END          
END          
ELSE          
BEGIN          
IF @DocPrefix=1          
BEGIN          
UPDATE dbo.tblTransPurchaseHeader SET [Status] = 3 WHERE ID = @TempID          
END          
IF @DocPrefix=12          
BEGIN          
UPDATE dbo.tblTransPurchaseHeader SET [Status] = 6 WHERE ID = @TempID          
END          
END          
END          
          
IF @DocPrefix=4 OR @DocPrefix=5          
BEGIN          
UPDATE dbo.tblNoteDetails SET Balance = Balance+@TempAmt WHERE ID = @TempID          
          
INSERT INTO #TEMP2   
SELECT DocValue FROM dbo.tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE DocValue = @DocValue AND TransID=@DocPrefix          
AND (DocDate BETWEEN (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) AND (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)))          
SET @DocCount = (SELECT COUNT(DocValue) FROM #TEMP2)    
  
UPDATE dbo.tblNoteDetails SET [Status] = (CASE WHEN (@DocCount = 1) THEN 1 ELSE 3 END) WHERE ID = @TempID          
END          
          
IF @DocPrefix=6 OR @DocPrefix=7          
BEGIN          
UPDATE dbo.tblTranPRVoucher SET Balance = Balance+@TempAmt WHERE ID = @TempID          
          
INSERT INTO #TEMP2 SELECT DocValue FROM dbo.tblTranPRVoucher WITH (READCOMMITTEDLOCK) WHERE DocValue = @DocValue AND TransID=@DocPrefix          
AND (DocDate BETWEEN (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) AND (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)))          
SET @DocCount = (SELECT COUNT(DocValue) FROM #TEMP2)          
UPDATE dbo.tblTranPRVoucher SET [Status] = (CASE WHEN (@DocCount = 1) THEN 1 ELSE 3 END) WHERE ID = @TempID          
END          
          
SET @Count = @Count+1          
DROP TABLE #TEMP2          
END          
DROP TABLE #Temp          
END          
ELSE          
BEGIN          
RAISERROR(''This document already processed'',16,1);          
END          
COMMIT TRANSACTION          
END TRy          
BEGIN CATCH          
ROLLBACK TRANSACTION          
SELECT ERROR_MESSAGE(),ERROR_LINE(),ERROR_PROCEDURE()          
END CATCH',
N'[export] nocount;readcommittedlock=53';
GO
/****** uspCancelPurchaseBill ******/
EXEC #Apply07 N'dbo.uspCancelPurchaseBill', 0x072C3C79A9DB6971C51354A61CEA66E971FF307199D0AB690CD8B50B743F96BC, NULL, NULL, 0x11F60A28AAF76820666F1D05569F958EA9B43CAC652A49798021C52425C8F50E, 0x1C7545F5D65543B4405A8A2FA40F5163068831E221E0651E8E19158143C92ADA, NULL,
N'ALTER PROC [dbo].[uspCancelPurchaseBill]                                
@GRNMode INT,@GRNID INT,@Uid INT,@CurrentStatus SMALLINT,@Remarks NVARCHAR(255) = NULL,@Narration NVARCHAR(MAX) = NULL              
AS                                  
SET NOCOUNT ON;
BEGIN TRY                             
 --GRN Cancel                               
 DECLARE @CheckStatus SMALLINT,@DocValue INT, @PreviousTranDate DATE,@BranchID INT,@Balance DECIMAL (25,6) ,  
 @NET DECIMAL (25,6),@InvoiceID INT,@Shinecode NVARCHAR(50)  
 SELECT @CheckStatus = [Status],@DocValue=DocValue,@PreviousTranDate=Date,@BranchID = BranchID,@Balance = Balance,  
 @NET = NetAmt,@InvoiceID = InvoiceID,@Shinecode = MV.Shinecode From tblTransPurchaseHeader PH WITH (READCOMMITTEDLOCK)   
 JOIN tblMasterVendor MV WITH (READCOMMITTEDLOCK) ON MV.ID = PH.VendorID  
 Where PH.ID = @GRNID                                       
 IF((@CheckStatus != @CurrentStatus) OR @CheckStatus IN (2,4))
 BEGIN                                            
  RAISERROR(''Status Already Changed'',16,1)                                           
 END                  
IF(@NET != @Balance)      
BEGIN        
RAISERROR(''Document partially payment'',16,1)        
END       
 DECLARE @Qty DECIMAL (25,6),@FreeQty  DECIMAL (25,6),@DmgQty  DECIMAL (25,6)                               
 --Get Qty Details In GRN Id Based From Inventory Table                              
 SELECT @Qty=ISNULL(SUM(IP.RecdQty),0)-(ISNULL(SUM(IP.ActualQty),0)-ISNULL(SUM(SRQty),0)),                                
 @FreeQty=ISNULL(SUM(IP.RecdFreeQty),0)-(ISNULL(SUM(IP.ActualFreeQty),0)-ISNULL(SUM(SRFreeQty),0)),                                
 @DmgQty=ISNULL(SUM(IP.RecdDmgQty),0)-(ISNULL(SUM(IP.ActualDmgQty),0)-ISNULL(SUM(SRFreeQty),0))                                
 FROM tblProductInventory IP WITH (READCOMMITTEDLOCK)               
 JOIN tblTransPurchaseDetail GRND WITH (READCOMMITTEDLOCK) ON GRND.InventoryId =IP.InventoryId                                   
 WHERE GRND.HID =@GRNID                                 
 --Verify Any One Qty Miss Matched If Not Allow to Modify                              
 IF(@Qty=0.000 AND @FreeQty=0.000 AND @DmgQty=0.000)                                  
 BEGIN                             
 --Update Inventory put qty SET 0                                 
  UPDATE tblProductInventory SET RecdQty = 0,RecdFreeQty = 0,RecdDmgQty = 0, ActualQty = ISNULL(SRQty,0) , ActualFreeQty =ISNULL(SRFreeQty,0),                            
  ActualDmgQty = ISNULL(SRDmgQty,0),ClBy = @Uid,ClDate = GETDATE()              
  FROM tblProductInventory IP WITH (READCOMMITTEDLOCK) JOIN  tblTransPurchaseDetail GRND WITH (READCOMMITTEDLOCK) ON GRND .InventoryId =IP.InventoryId                                   
  WHERE GRND.HID =@GRNID                                   
 END                                  
 ELSE                                  
 BEGIN                                  
  RAISERROR(''Qty Miss Matched'',16,1);                                
 END                    
 -- Check If GRN Created From PO AND Status                    
DECLARE @CurrentDocStatus INT,@GrnFromPo INT                            
select @CurrentDocStatus=Status from tblTransPurchaseHeader WITH (READCOMMITTEDLOCK) where ID = @GRNID            
IF ISNULL(@CurrentDocStatus,0)=1            
BEGIN                    
DECLARE @Serial INT,@Count INT                  
DECLARE @TempPOCancelDocs AS TABLE (ID INT IDENTITY(1,1), POID INT, PODocValue INT)                  
INSERT INTO @TempPOCancelDocs                  
SELECT ID,DocValue FROM tblPurchaseOrderHeader WITH (READCOMMITTEDLOCK) WHERE GRNId = @GRNID              
                  
SET @Serial = 1                  
SET @Count = (SELECT COUNT(*) FROM @TempPOCancelDocs)                  
                  
WHILE @Count > 0                  
BEGIN                  
DECLARE @PODocValue INT,@POID INT,@UpdateStatus SMALLINT                  
SELECT @POID=POID,@PODocValue=PODocValue FROM @TempPOCancelDocs WHERE ID=@Serial                  
SET @UpdateStatus = (CASE WHEN ISNULL((SELECT COUNT(*) FROM tblPurchaseOrderHeader WITH (READCOMMITTEDLOCK)              
WHERE DocValue=@PODocValue                
AND (DocDate BETWEEN (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) AND (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)))),0) = 1 THEN 1 ELSE 3 END)                 
UPDATE tblPurchaseOrderHeader SET [Status]=@UpdateStatus,GRNId=0 WHERE ID=@POID                  
                  
SET @Serial = @Serial + 1           
SET @Count = @Count - 1                  
END             
END                    
                     
                     
 --GRN Status to Change Cancel(4) Status                              
 UPDATE tblTransPurchaseHeader SET [Status] =4,Clby =@UId ,Cldate =GETDATE() ,Remarks = @Remarks,Narration = @Narration                                
 WHERE ID =@GRNID                                 
 --Posting Revort to Change Cancel(4) Status                                
 UPDATE tblFAJournal SET [Status] =4,Clby =@UId ,Cldate =GETDATE(),Remarks = @Remarks,Narration = @Narration                                 
 WHERE TransId  =@GRNID  AND DocPrefix =1                        
 --IF Cancel ON Back Dated Transaction to Insert Bactdate Transaction table                      
 EXEC uspCreateBackTran 3,@BranchID,@GRNID,@GRNID,1,@DocValue ,@PreviousTranDate,null,@Uid              
 select isnull(@InvoiceID,0) InvoiceID,@Shinecode Shinecode  
END TRY                                
BEGIN  CATCH                                
 SELECT ERROR_MESSAGE (),ERROR_PROCEDURE (),ERROR_LINE ();                                
END CATCH',
N'[export] nocount;readcommittedlock=11';
GO
/****** uspCancelQuatation ******/
EXEC #Apply07 N'dbo.uspCancelQuatation', 0x8E725501403C80466D71CFA3C2F07C5956E63EA72D64D39427341186976838E8, NULL, NULL, 0x42440FF7FED78C55A21BE75106195F7753472E088F2D802182E462D820D00B5C, 0xB1C2F28480ADAB8667070F4041FDAC08A060E76766D39B51AFE63E925C70E5FB, NULL,
N'ALTER PROC [dbo].[uspCancelQuatation]
@quatationId INT,@Uid INT,@CurrentStatus SMALLINT,@Remarks NVARCHAR(255) = NULL,@Narration NVARCHAR(MAX) = NULL
AS
SET NOCOUNT ON;
BEGIN TRY
BEGIN TRAN
--Purchase Cancel
DECLARE @CheckStatus SMALLINT,@DocValue INT, @PreviousTranDate DATE
SELECT @CheckStatus = [Status],@DocValue=DocValue,@PreviousTranDate=DocDate From tblQuotationHeader WITH (READCOMMITTEDLOCK) Where ID = @quatationId
IF((@CheckStatus != @CurrentStatus) OR @CheckStatus IN (2,4))
BEGIN
RAISERROR(''Document status already changed'',16,1)
END
DECLARE @Qty INT
-- Status to Change Cancel(4) Status
UPDATE tblQuotationHeader SET [Status] =4,Clby =@UId ,Cldate =GETDATE(),Remarks = @Remarks,Narration = @Narration
WHERE ID =@quatationId
COMMIT TRAN
END TRY
BEGIN CATCH
ROLLBACK TRAN
SELECT ERROR_MESSAGE (),ERROR_PROCEDURE (),ERROR_LINE ();
END CATCH',
N'[export] nocount;readcommittedlock=1';
GO
/****** uspCheckChequeStatusByNum ******/
EXEC #Apply07 N'dbo.uspCheckChequeStatusByNum', 0xC424664B4F8340D300E8BA07157B1AB0000A3B979754B1D75405470339FC545A, NULL, NULL, 0xE3287F1D97106DAE2BFAC2D3CFA32688D221DD4C32727D6AADB3CB8F58F77983, 0x8184704BD49B208B73B1FDF25860585BA7F61029F36E6EDB78FC22EF775BF0A3, NULL,
N'ALTER PROC [dbo].[uspCheckChequeStatusByNum]
@RefNo NVARCHAR(50),@ChequeNo INT,@BankAccID INT,@ContraID INT
AS
SET NOCOUNT ON;
BEGIN
IF @ContraID=0
BEGIN
SELECT ChequeNo FROM tblMasterChequeBookDetail AS Detail
JOIN tblMasterChequeBook AS Header
ON Detail.ChequebookId=Header.ChequebookId
WHERE Header.ChequeBookreferNo=@RefNo AND Header.BankAccountID=@BankAccID
AND Detail.ChequeNo=@ChequeNo AND Header.Active=1 AND Detail.[Status]=1
END
ELSE
BEGIN
DECLARE @TempBankAccID INT,@TempChequeNo INT
SELECT @TempChequeNo= ChequeNo,@TempBankAccID=FromFAID From tblTranContra WHERE ID=@ContraID
SELECT @TempBankAccID=ID FROM tblMasterBankAccount WHERE FAID= @TempBankAccID
IF @BankAccID=@TempBankAccID AND @ChequeNo=@TempChequeNo
BEGIN
SELECT ChequeNo FROM tblMasterChequeBookDetail AS Detail
JOIN tblMasterChequeBook AS Header
ON Detail.ChequebookId=Header.ChequebookId
WHERE Header.ChequeBookreferNo=@RefNo AND Header.BankAccountID=@BankAccID
AND Detail.ChequeNo=@ChequeNo AND Header.Active=1 AND Detail.[Status]!=4
END
ELSE
BEGIN
SELECT ChequeNo FROM tblMasterChequeBookDetail AS Detail
JOIN tblMasterChequeBook AS Header
ON Detail.ChequebookId=Header.ChequebookId
WHERE Header.ChequeBookreferNo=@RefNo AND Header.BankAccountID=@BankAccID
AND Detail.ChequeNo=@ChequeNo AND Header.Active=1 AND Detail.[Status]=1
END
END
END',
N'[export] nocount';
GO
