/****** uspChequeDepositDetailforPrint ******/
EXEC #Apply07 N'dbo.uspChequeDepositDetailforPrint', 0x025DD2E8B22CEA4E72CF4DF44EB5B4E9734BC23415CEFDFA35DB75D64727D601, NULL, NULL, 0x9F599FF80DC439482709FBF0138428673DFCE2ECF012A8B9D5A69B473B60300B, 0x5460011DAE133DD4DEB0037162B6E1ED5D6E37399BBADC32A980DA3416E1D14B, NULL,
N'--uspChequeDepositDetailforPrint 2    
ALTER PROC [dbo].[uspChequeDepositDetailforPrint]        
@IdentID INT = NULL         
AS         
SET NOCOUNT ON;
BEGIN        
SET DATEFORMAT DMY;         
DECLARE @identPrint INT = (SELECT ISNULL(identPrint,0) FROM tblTranChequeDeposit WHERE DepositID=@IdentID)        
SELECT ROW_NUMBER() OVER (ORDER BY Deposit.DocValue) AS SerialNo,        
Deposit.DocID AS [Doc ID],                
Cust.Name AS [Party Name],        
Cust.GSTIN AS [CD_GSTIN],        
Cust.AadharNo AS [Aadhar Number],        
Cust.Mob1 AS [Mobile Number],        
BAcc.IFSCCode AS [IFSC Code],         
ColPM.[Cheque/DD Number],         
CONVERT (NVARCHAR ,ColPM.DATE,103) AS [Cheque Date],         
ColPM.BankName AS [Bank Name],         
ColPM.BranchName AS [Branch Name],         
ColPM.CollAmt AS Amount,         
Paymode.PaymentMode AS [Payment Mode] 
   
FROM dbo.tblTranChequeDeposit AS Deposit         
LEFT JOIN dbo.tblMasterBankAccount AS BAcc ON BAcc.ID =Deposit.DepositAccountId                  
LEFT JOIN dbo.tblCollPMDetails AS ColPM on ColPM.ColID = Deposit.CollId         
LEFT JOIN dbo.tblMasterCustomer AS Cust on Cust.ID = ColPM.AccId         
LEFT JOIN dbo.tblPaymentMode AS Paymode on Paymode.Id = ColPM.PaymentTermID         
WHERE ISNULL(Deposit.identPrint,0) = @identPrint        
ORDER BY Deposit.DocValue        
END',
N'[export] nocount';
GO
/****** uspChequeDepositforPrint ******/
EXEC #Apply07 N'dbo.uspChequeDepositforPrint', 0x1C3BFDBD135271F8B1A8D4D7FA5A8F9C7217127713ED4B4F6FC190AF948E845A, NULL, NULL, 0xDBD70AAF5A680291378F4014331765B80ECDCD4631B617D75B9CB34F1BECA496, 0x1D2897C1FE951848F4866F67A1061F07F6B1DA6D5A9EC3183AD62CA9DF32A3E0, NULL,
N'--uspChequeDepositforPrint 22       
--select * from tblTranChequeDeposit where DepositID = 527 order by 1 desc    
ALTER PROC [dbo].[uspChequeDepositforPrint]        
@IdentID INT = NULL           
AS           
SET NOCOUNT ON;
BEGIN           
SET DATEFORMAT DMY;         
DECLARE @identPrint INT = (SELECT ISNULL(identPrint,0) FROM tblTranChequeDeposit WHERE DepositID=@IdentID)            
        
select [Doc Date],[Trans Name],[Deposit Account No],[Deposit Account Name],[Deposit Branch Name],      
[Salesman Name],[Salesman Mobile No], dbo.fngetroundedvalue(sum([Amt_in_Words])) as [Total Value] ,      
dbo.[fnConvertAmountinWords](sum([Amt_in_Words])) as [Amt_in_Words],[Deposit Bank Name] from(      
SELECT             
CONVERT (NVARCHAR ,Deposit.DocDate,103) AS [Doc Date],               
Doc.TransName AS [Trans Name],           
BAcc.AccountNo AS [Deposit Account No],           
BAcc.AccountName AS [Deposit Account Name],           
BANK.Name AS [Deposit Bank Name],           
BAcc.BranchName AS [Deposit Branch Name],           
SM.Name AS [Salesman Name],           
SM.MobileNo AS [Salesman Mobile No],           
(ColPM.CollAmt) AS [Amt_in_Words]
FROM dbo.tblTranChequeDeposit AS Deposit           
LEFT JOIN dbo.tblDocumentSeries AS Doc ON Deposit.DocPrefix = Doc.TransID           
LEFT JOIN dbo.tblMasterBankAccount AS BAcc ON BAcc.ID =Deposit.DepositAccountId                    
LEFT JOIN dbo.tblMasterBank AS BANK on BANK.ID = BAcc.BankID           
LEFT JOIN dbo.tblMasterSalesMan AS SM on SM.ID = Deposit.SalesManId           
LEFT JOIN dbo.tblCollPMDetails AS ColPM on ColPM.ColID = Deposit.CollId           
LEFT JOIN dbo.tblMasterCustomer AS Cust on Cust.ID = ColPM.AccId           
LEFT JOIN dbo.tblUsers AS UserTab on UserTab.ID = Deposit.CBy           
LEFT JOIN dbo.tblPaymentMode AS Paymode on Paymode.Id = ColPM.PaymentTermID           
WHERE Deposit.identprint = @identPrint) as  a       
group by [Doc Date],[Trans Name],[Deposit Account No],[Deposit Account Name],[Deposit Branch Name],      
[Salesman Name],[Salesman Mobile No],[Deposit Bank Name]  
END',
N'[export] nocount';
GO
/****** uspCollectionDetail ******/
EXEC #Apply07 N'dbo.uspCollectionDetail', 0x101C893AD7305D321B28B45C46C79583544330DC4E26D05D93213B33FEE340BA, NULL, NULL, 0x772052032FC2A14D85732E92DDC27A16E817F34C6577D2656525CE372BF72BFA, 0x427D5B1F2E15A6924D40669377D0241DB611F32D6C40218E11E1543CB8C36972, NULL,
N'ALTER PROC [dbo].[uspCollectionDetail]  
@CollId INT = 111  
AS  
SET NOCOUNT ON;
BEGIN  
SELECT Header.DocID [Coll Doc ID],MC.Name [Customer Name],DocSeries.TransName AS [Transaction],CASE WHEN Detail.DocPrefix=15 OR Detail.DocPrefix=16 THEN (SELECT DocId FROM tblTranSalesHeader WHERE ID=Detail.DocID)    
WHEN Detail.DocPrefix=4 THEN (SELECT DocId FROM tblNoteDetails WHERE ID=Detail.DocID)    
WHEN Detail.DocPrefix=19 THEN (SELECT DocId FROM tblTranCollectionHeader WHERE ColID = Detail.DocID)    
WHEN Detail.DocPrefix=6 THEN (SELECT DocId FROM tblTranPRVoucher WHERE ID=Detail.DocID)    
ELSE ''''  END AS [Doc Id],FORMAT(Detail.[Date],''dd-MMM-yyyy'') as [Doc Date],    
(CASE WHEN Detail.DocPrefix=15 OR Detail.DocPrefix=16 THEN (SELECT DocRef FROM tblTranSalesHeader WHERE ID = Detail.DocID)    
WHEN Detail.DocPrefix=4 THEN (SELECT RefNo FROM tblNoteDetails WHERE ID = Detail.DocID)    
WHEN Detail.DocPrefix=19 THEN (SELECT ColDocRefNo FROM tblTranCollectionHeader WHERE ColID = Detail.DocID)    
WHEN Detail.DocPrefix=6 THEN (SELECT RefNo FROM tblTranPRVoucher WHERE ID = Detail.DocID)    
ELSE ''''  END) AS [Ref No], dbo.fnGetRoundedValue(CASE WHEN Detail.DocPrefix=15 OR Detail.DocPrefix=16 THEN (SELECT NetAmt FROM tblTranSalesHeader WHERE ID = Detail.DocID)    
WHEN Detail.DocPrefix=4 THEN (SELECT NoteValue FROM tblNoteDetails WHERE ID = Detail.DocID)    
WHEN Detail.DocPrefix=19 THEN (SELECT ColAmt FROM tblTranCollectionHeader WHERE ColId=Detail.DocID)    
WHEN Detail.DocPrefix=6 THEN (SELECT NetAmount FROM tblTranPRVoucher WHERE ID = Detail.DocID)     
ELSE 0.00  END) AS [Doc Amount],[dbo].[fnGetRoundedValue](CONVERT(DECIMAL (25,6),Detail.ColValue ))AS [Collected Amount],    
[dbo].[fnGetRoundedValue](CONVERT(DECIMAL (25,6),Detail.AdjAmt))AS [Adjustment Amount],    
(CASE WHEN DiscPercentage LIKE ''%[%]'' THEN CAST([dbo].[fnGetRoundedValue](REPLACE(DiscPercentage,''%'','''')) AS NVARCHAR)+''%'' ELSE [dbo].[fnGetRoundedValue](DiscPercentage)    
END) AS [Discount %],[dbo].[fnGetRoundedValue](CONVERT(DECIMAL (25,6),Detail.DiscAmt))AS [Discount Amount],    
(CASE Detail.FullyAdj WHEN 1 THEN ''YES'' when 0 then (case when TS.Balance=0 then ''YES''  else ''NO'' end) end) [Fully Adjustment],    
[dbo].[fnGetRoundedValue](CONVERT(DECIMAL (25,6),detail.TotalAmtAdj)) AS [Total Amount Adjusted],    
[dbo].[fnGetRoundedValue](CONVERT(DECIMAL (25,6),Detail.FullyAdjAmt))AS [Fully Adjusted Amount],    
DATEDIFF(DAY,Detail.Date,Header.ColDate) AS [Ageing]    
FROM tblTranCollectionDetail AS Detail    
LEFT JOIN tblTranCollectionHeader AS Header ON Detail.ColID=Header.ColID    
LEFT join tblTranSalesHeader as  TS on TS.ID=Detail.DocID    
JOIN tblDocumentSeries AS DocSeries ON Detail.DocPrefix=DocSeries.TransID    
join tblMasterCustomer MC ON MC.FAID = Header.AccID
WHERE Detail.ColID=@CollId    
ORDER BY Detail.ColDetailID    
END',
N'[export] nocount';
GO
/****** uspCollectionHeader ******/
EXEC #Apply07 N'dbo.uspCollectionHeader', 0x34EA7611572C2FE1FF36A58CF465097614DBB1520454DEA1169538C5AF480EAA, NULL, NULL, 0xB8ACF7367F0FABA0B953A79F603027407A5BF27F0356D1DAF70FE224C09C1486, 0x14F54564FB5EE3191CA7DCA57D2C3A6193CA860C41A91A64787D56893B546C94, NULL,
N'--[uspCollectionHeader] 0,1,''2026-05-29'',''2026-06-01''
ALTER PROC [dbo].[uspCollectionHeader]      
@StatusID NVARCHAR(255)= 0,@DateType int = 0,@FromDate DATE = ''2020-04-01'',@ToDate DATE =''2026-09-30''      
AS      
SET NOCOUNT ON;
BEGIN      
DECLARE @Sts AS TABLE(Status INT)      
IF(@StatusID = 0)      
BEGIN      
INSERT INTO @Sts values (1),(3),(5)      
END      
ELSE      
BEGIN      
INSERT INTO @Sts values(@StatusID)      
END      
      
SELECT CollHeader.ColID,CollHeader.[DocID] AS[Doc ID],FORMAT(ColDate,''dd-MMM-yyyy'') AS [Date],Beat.Name AS [Beat Name],SMan.Name AS [Salesman Name],      
Customer.Code AS [Customer Code],Customer.Name AS [Customer Name], Customer.Mob1 AS [Mob No],      
ColDocRefNo AS [Ref No], PaymentMode AS [Collection Mode],[dbo].[fnGetRoundedValue](ColAmt) AS [Received Amount],      
[dbo].[fnGetRoundedValue](Balance) AS [Balance Amount],Bank.AccountName AS [Bank A/C Name],      
Bank.AccountNo AS [Bank A/C No],      
(CASE WHEN ISNULL(pm.PaymentTermID,0)=2 THEN pm.[Cheque/DD Number] WHEN ISNULL(pm.PaymentTermID,0)=3 THEN pm.[Cheque/DD Number]      
WHEN ISNULL(pm.PaymentTermID,0)=4 THEN pm.NeftID WHEN ISNULL(pm.PaymentTermID,0)=5 THEN pm.NeftID END) AS [Cheque/DD/NEFT],      
CASE WHEN pm.PaymentTermID IN (2,3) THEN FORMAT(pm.Date,''dd-MMM-yyyy'')WHEN pm.PaymentTermID IN (4,5) THEN FORMAT(pm.Date,''dd-MMM-yyyy'')      
ELSE NULL END AS [Cheque/DD/NEFT Date],dbo.fnGetRoundedValue(CollHeader.VisaPern) AS [Card (%)],      
dbo.fnGetRoundedValue(CollHeader.VisaAmt) AS [Card Amount],pm.BankName AS [Bank Name],      
pm.BranchName AS [Branch Name],pm.Ifsccode AS [IFSC COde],      
Users.username AS [User Name],FORMAT(CollHeader.CDate,''dd-MMM-yyyy hh:mm tt'') [Create Date],ST.Description AS [Status],CollHeader.Remarks,CollHeader.Narration      
FROM tblTranCollectionHeader AS CollHeader      
JOIN tblMasterCustomer AS Customer ON CollHeader.AccID=Customer.FAID      
JOIN tblDocumentSeries AS Doc On CollHeader.DocPrefix=Doc.TransID      
LEFT JOIN tblPaymentMode On CollHeader.ColMode=tblPaymentMode.Id      
LEFT JOIN tblStatus AS ST ON ST.ID = CollHeader.Status      
LEFT JOIN tblCollPMDetails as pm ON pm.ColID=CollHeader.ColID      
LEFT JOIN tblMasterBankAccount AS Bank ON Bank.FAID = pm.BankAccID      
LEFT JOIN tblMasterBeat AS Beat ON Beat.ID = CollHeader.BeatID      
LEFT JOIN tblMasterSalesMan AS SMan ON SMan.ID = CollHeader.SalesManID      
LEFT JOIN tblUsers AS Users ON Users.ID =CollHeader.CBy      
WHERE (@DateType = 0 AND CollHeader.ColDate BETWEEN @FromDate AND @ToDate)
        OR
      (@DateType = 1 AND convert(date,CollHeader.CDate) BETWEEN @FromDate AND @ToDate)
AND CollHeader.DocPrefix=19 and CollHeader.Status IN (SELECT * FROM @Sts)      
ORDER BY CollHeader.DocValue      
END',
N'[export] nocount';
GO
/****** uspCollectionPrintHeader ******/
EXEC #Apply07 N'dbo.uspCollectionPrintHeader', 0x0E451BE482088BAFB23CEDDEEC6A46618A5FD101918AD2DF9174239691D7F396, NULL, NULL, 0x8852AB5AC769B4CD45A762C4A0E668095D72ADB558E5317343A5239638FF07C0, 0xE8913CB7BB7EA14A06FCDF11850419E116807B67EA7811CC82C3E8B96679F8A9, NULL,
N'ALTER PROC [dbo].[uspCollectionPrintHeader]  
@ID NVARCHAR(255)= 0 
AS  
SET NOCOUNT ON;
BEGIN  
  
SELECT CollHeader.ColID,CollHeader.[DocID] AS[Doc ID],FORMAT(ColDate,''dd-MMM-yyyy'') AS [Date],Beat.Name AS [Beat Name],SMan.Name AS [Salesman Name],  
Customer.Code AS [Customer Code],Customer.Name AS [Customer Name], Customer.Mob1 AS [Mob No],  
ColDocRefNo AS [Ref No], PaymentMode AS [Collection Mode],[dbo].[fnGetRoundedValue](ColAmt) AS [Received Amount],  
[dbo].[fnGetRoundedValue](Balance) AS [Balance Amount],Bank.AccountName AS [Bank A/C Name],  
Bank.AccountNo AS [Bank A/C No],  
(CASE WHEN ISNULL(pm.PaymentTermID,0)=2 THEN pm.[Cheque/DD Number] WHEN ISNULL(pm.PaymentTermID,0)=3 THEN pm.[Cheque/DD Number]  
WHEN ISNULL(pm.PaymentTermID,0)=4 THEN pm.NeftID WHEN ISNULL(pm.PaymentTermID,0)=5 THEN pm.NeftID END) AS [Cheque/DD/NEFT],  
CASE WHEN pm.PaymentTermID IN (2,3) THEN FORMAT(pm.Date,''dd-MMM-yyyy'')WHEN pm.PaymentTermID IN (4,5) THEN FORMAT(pm.Date,''dd-MMM-yyyy'')  
ELSE NULL END AS [Cheque/DD/NEFT Date],dbo.fnGetRoundedValue(CollHeader.VisaPern) AS [Card (%)],  
dbo.fnGetRoundedValue(CollHeader.VisaAmt) AS [Card Amount],pm.BankName AS [Bank Name],  
pm.BranchName AS [Branch Name],pm.Ifsccode AS [IFSC COde],  
Users.username AS [User Name],ST.Description AS [Status]  
FROM tblTranCollectionHeader AS CollHeader  
JOIN tblMasterCustomer AS Customer ON CollHeader.AccID=Customer.FAID  
JOIN tblDocumentSeries AS Doc On CollHeader.DocPrefix=Doc.TransID  
LEFT JOIN tblPaymentMode On CollHeader.ColMode=tblPaymentMode.Id  
LEFT JOIN tblStatus AS ST ON ST.ID = CollHeader.Status  
LEFT JOIN tblCollPMDetails as pm ON pm.ColID=CollHeader.ColID  
LEFT JOIN tblMasterBankAccount AS Bank ON Bank.FAID = pm.BankAccID  
LEFT JOIN tblMasterBeat AS Beat ON Beat.ID = CollHeader.BeatID  
LEFT JOIN tblMasterSalesMan AS SMan ON SMan.ID = CollHeader.SalesManID  
LEFT JOIN tblUsers AS Users ON Users.ID =CollHeader.CBy  
WHERE (CollHeader.ColID = @ID)  
END',
N'[export] nocount';
GO
/****** uspCommonDocumentFilter ******/
EXEC #Apply07 N'dbo.uspCommonDocumentFilter', 0x6211A9CDA7C41AC1B2A4296FA5AC4BE36A576A8507C7663E6489A7C45DFDBB8C, 0x927A1BD904DB7892AFA5E8A9B9E4B3345FA5BE5AC04002F0AE7E13F94C06F9A6, NULL, 0xE7A746008EA86AD37F8C57CEF9B7835486881A976954B2BA702FE418B2BC7583, 0xDBD122D099FE7C933F9AA2622CFBD9BCEF7DB2B7E833EA4E6E4FFE10DB5D49B7, NULL,
N'-- Security fix: list-filter values are passed to sp_executesql as parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspCommonDocumentFilter]          
@Branch INT = 0,@DocPreix INT = 4,@FromDate DATE = ''2025-05-01'',@ToDate DATE = ''2025-11-11'',@DocRange NVARCHAR(MAX) = NULL,@CustID NVARCHAR(MAX) = NULL,        
@FilterBy int = 1        
as          
SET NOCOUNT ON;
begin          
declare @StrQuery NVARCHAR(MAX) = ''''            
if(@DocPreix = 4 or @DocPreix = 5)--4 : Invoice, 5 - SR          
BEGIN          
SET @StrQuery = ''select SH.DocValue,SH.DocId + (case when SH.ReturnsTransType = 2 then '''' - DR'''' when SH.ReturnsTransType = 1 THEN ''''- SR'''' ELSE '''''''' END) DocId,    
FORMAT(SH.InvDate,''''dd/MMM/yyyy'''') DocDate,MB.Name BeatName,MB.Name SalesmanName,MC.Name,SH.DocRef RefNo,dbo.fnGetRoundedValue(SH.NetAmt) NetAmt ,          
COUNT(SD.ProdID) ItemsCount          
from tblTranSalesHeader SH                    
JOIN tblMasterCustomer MC ON MC.Id = SH.CustId    
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID    
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesmanID    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID WHERE SD.TaxID > 0 AND SH.BranchID = ''+CONVERT(nvarchar(10),@Branch) +'' and ''  
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocPreix,0)=4 THEN ''SH.DocPrefix = 15 '' ELSE '' SH.DocPrefix = 16 '' END)                                  
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocPreix,0)=4 THEN ''AND Status IN (1,3,5) '' ELSE '' AND Status IN (3,5,6,7)'' END)               
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (SH.InvDate BETWEEN ''''''+CONVERT(NVARCHAR,CAST(@FromDate AS DATE))+'''''' AND ''''''+CONVERT(NVARCHAR,CAST(@ToDate AS DATE))+'''''')'' END)    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocRange,'''')='''' THEN '''' ELSE '' AND SH.DocValue IN (SELECT TRY_CAST(value AS int) FROM STRING_SPLIT(@DocRange, '''','''') WHERE LTRIM(RTRIM(value)) <> '''''''')'' END)                                  
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@FilterBy,0)=1 THEN '''' WHEN ISNULL(@FilterBy,0)=2 THEN '' AND IRN IS NOT NULL'' ELSE '' AND IRN IS NULL'' END)            
SET @StrQuery = @StrQuery +  '' GROUP BY SH.DocId,SH.InvDate,MC.Name,SH.DocValue,SH.DocRef,SH.NetAmt,SH.ReturnsTransType,MB.Name,MB.Name order by SH.DocValue''          
EXEC sys.sp_executesql @StrQuery, N''@Branch INT, @DocPreix INT, @FromDate DATE, @ToDate DATE, @DocRange NVARCHAR(MAX), @CustID NVARCHAR(MAX), @FilterBy int'', @Branch, @DocPreix, @FromDate, @ToDate, @DocRange, @CustID, @FilterBy          
END          
if(@DocPreix = 2 or @DocPreix = 3)--2 : Bill, 5 - PR          
BEGIN          
SET @StrQuery = ''select SH.DocValue,SH.DocId,FORMAT(SH.Date,''''dd/MMM/yyyy'''') DocDate,null BeatName,null SalesmanName,MC.Name,SH.RefNo RefNo,dbo.fnGetRoundedValue(SH.NetAmt) NetAmt ,          
COUNT(SD.ProdID) ItemsCount          
from tblTransPurchaseHeader SH                    
JOIN tblMastervendor MC ON MC.Id = SH.VendorID                    
JOIN tblTransPurchasedetail SD ON SD.HID = SH.ID WHERE SD.TaxID > 0 AND SH.BranchID = ''+CONVERT(nvarchar(10),@Branch) +'' and ''        
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocPreix,0)=2 THEN ''SH.TransID = 1 '' ELSE '' SH.TransID = 12 '' END)                                  
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocPreix,0)=2 THEN ''AND Status IN (1,3,5) '' ELSE '' AND Status IN (3,5,6,7)'' END)               
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (SH.Date BETWEEN ''''''+CONVERT(NVARCHAR,CAST(@FromDate AS DATE))+'''''' AND ''''''+CONVERT(NVARCHAR,CAST(@ToDate AS DATE))+'''''')'' END)    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocRange,'''')='''' THEN '''' ELSE '' AND SH.DocValue IN (SELECT TRY_CAST(value AS int) FROM STRING_SPLIT(@DocRange, '''','''') WHERE LTRIM(RTRIM(value)) <> '''''''')'' END)                                  
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@FilterBy,0)=1 THEN '''' WHEN ISNULL(@FilterBy,0)=2 THEN '' AND IRN IS NOT NULL'' ELSE '' AND IRN IS NULL'' END)            
SET @StrQuery = @StrQuery +  '' GROUP BY SH.DocId,SH.Date,MC.Name,SH.DocValue,SH.RefNo,SH.NetAmt order by SH.DocValue''          
EXEC sys.sp_executesql @StrQuery, N''@Branch INT, @DocPreix INT, @FromDate DATE, @ToDate DATE, @DocRange NVARCHAR(MAX), @CustID NVARCHAR(MAX), @FilterBy int'', @Branch, @DocPreix, @FromDate, @ToDate, @DocRange, @CustID, @FilterBy          
END       
if(@DocPreix = 23)--23 : Van Loading Slip
BEGIN          
SET @StrQuery = ''select SH.DocValue,SH.DocId,FORMAT(SH.DocDate,''''dd/MMM/yyyy'''') DocDate,null BeatName,MC.Name SalesmanName,
null Name,SH.RefNo RefNo,dbo.fnGetRoundedValue(SH.NetAmt) NetAmt ,COUNT(SD.ProdID) ItemsCount          
from tblvanloadingslipheader SH                    
JOIN tblMastersalesman MC ON MC.Id = SH.SalesmanID                    
JOIN tblvanloadingslipDetail SD ON SD.ID = SH.ID WHERE SD.TaxID > 0 AND SH.BranchID = ''+CONVERT(nvarchar(10),@Branch)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocPreix,0)=23 THEN ''AND Status IN (1,3,5) '' ELSE '' AND Status IN (3,5,6,7)'' END)               
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (SH.DocDate BETWEEN ''''''+CONVERT(NVARCHAR,CAST(@FromDate AS DATE))+'''''' AND ''''''+CONVERT(NVARCHAR,CAST(@ToDate AS DATE))+'''''')'' END)    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocRange,'''')='''' THEN '''' ELSE '' AND SH.DocValue IN (SELECT TRY_CAST(value AS int) FROM STRING_SPLIT(@DocRange, '''','''') WHERE LTRIM(RTRIM(value)) <> '''''''')'' END)                                  
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@FilterBy,0)=1 THEN '''' WHEN ISNULL(@FilterBy,0)=2 THEN '' AND IRN IS NOT NULL'' ELSE '' AND IRN IS NULL'' END)            
SET @StrQuery = @StrQuery +  '' GROUP BY SH.DocId,SH.DocDate,MC.Name,SH.DocValue,SH.RefNo,SH.NetAmt order by SH.DocValue''          
EXEC sys.sp_executesql @StrQuery, N''@Branch INT, @DocPreix INT, @FromDate DATE, @ToDate DATE, @DocRange NVARCHAR(MAX), @CustID NVARCHAR(MAX), @FilterBy int'', @Branch, @DocPreix, @FromDate, @ToDate, @DocRange, @CustID, @FilterBy          
END 
END',
N'[01] nocount';
GO
/****** uspContraforPrint ******/
EXEC #Apply07 N'dbo.uspContraforPrint', 0x14D3B7B816CF0F04ED07AC79ED06D0C3A705DAFFFC8D35863844C88D5AC3910F, NULL, NULL, 0x9B7C7318DE444AB68176BF52347C8FEEEA40F4CCE95D7B05888B3C0571CCD083, 0xA3AD849941CB834E0B889576F9F41A4A550BB845F2E538830B9D7EB8EA58DB9F, NULL,
N'--uspContraforPrint 73
 ALTER PROC [dbo].[uspContraforPrint]                  
@DocValue INT = null                      
as                      
SET NOCOUNT ON;
BEGIN                      
Select Contra.ID as [Contra ID],Contra.DocId as [Doc ID],CONVERT (NVARCHAR ,Contra.DocDate,103) as [Doc Date],  
Isnull(CONVERT(nvarchar(5),Contra.MDate,108),CONVERT(nvarchar(5),Contra.CDate,108)) as [Time],Doc.TransName as [Trans Name],Contra.RefNo as [Doc Ref],Type.TypeName AS [Type Name],  
mode.ModeName as [Mode Name],SM.Name as [Salesman Name], MBO.Name [Branch Name] ,Contra.Balance as [Balance],BAcc.AccountName as [From Account No],CONVERT (NVARCHAR ,Contra.DocDate,103) as [Doc Date],  
Contra.WDSlipNo as [WD Slip No],Contra.ChequeNo as [Cheque No],TranferBAcc.AccountName as [Transfer Account No],  
Contra.Narration as [Narration],Contra.Amount as [Amount],dbo.fnConvertAmountinWords(Contra.Amount) AS [Amt_in_Words],  
UserTab.username as [User Name]  
From dbo.tblTranContra as Contra  
join dbo.tblDocumentSeries AS Doc ON Contra.TransID = Doc.TransID  
Join dbo.tblUsers as UserTab on UserTab.ID = Contra.MBy or UserTab.ID  =  Contra.Cby  
Left Join dbo.tblContraType as Type on Type.ID = Contra.TypeId  
LEft Join dbo.tblContraMode as mode on mode.ID = Contra.ModeId  
Left Join dbo.tblMasterSalesMan as SM on SM.ID = Contra.SalesManId 
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = Contra.BranchID
Left Join dbo.tblFAAccount as BAcc on BAcc.FAID = Contra.FromFAID  
Left Join dbo.tblFAAccount as TranferBAcc on TranferBAcc.FAID = Contra.ToFAID  
Where Contra.ID = @DocValue AND Contra.TransID = 8  
END',
N'[export] nocount';
GO
/****** uspCreditNoteforPrint ******/
EXEC #Apply07 N'dbo.uspCreditNoteforPrint', 0x8CE092122083C0BFC5C131ADBE0D46D4497849DC19F0CDE3F6D7087AEB6CC5CE, NULL, NULL, 0xB7C548223919B2F71863393349D0AC5296F052B8ECB8C0F3CB21C723FBAEC39F, 0x78956309BB888DF2731FA74AB13D1AE8C1EDE80467E4F865997404A93DC346F4, NULL,
N'--uspCreditNoteforPrint 42 
 ALTER PROC [dbo].[uspCreditNoteforPrint]             
@DocValue INT = null                 
as                
SET NOCOUNT ON;
Declare @AccGrpid int             
Select  @AccGrpid = Faa.AccountGroup from dbo.tblNoteDetails  as note Join dbo.tblFAAccount as Faa on Faa.FAID = note.PartyId               
Where note.ID = @DocValue AND TransID = 4              
if(@AccGrpid = 35) -- customer            
BEGIN
Select Note.ID as [Credit Note ID],Note.DocId as [Doc ID],Convert (nvarchar ,Note.DocDate,103) as [Doc Date],  
Isnull(CONVERT(nvarchar(5),Note.MDate,108),CONVERT(nvarchar(5),Note.CDate,108)) as [Time],Doc.TransName as [Trans Name],  
Note.RefNo as [Doc Ref],FAParty.AccountName as [Party Name],FAAC.AccountName as [Account Name], MBO.Name [Branch Name] ,Note.Remark as [Remark],  
Note.Narration as [Narration],Customer.Ph1 AS [Party Prim Phone No],Customer.Mob1 as [Party Prim Mobile No],  
Customer.Billadd1  AS [Party Bill Address 1],Customer.Billadd2 as [Party Bill Address 2],Customer.Billadd3 as [Party Bill Address 3],      
Customer.GSTIN [Party GSTIN],Customer.AadharNo AS [Party Aadhar Number],Customer.PANNumber AS [Party PAN No],Note.NoteValue as [Note Value],  
Note.Balance as [Balance],dbo.fnConvertAmountinWords(Note.NoteValue) AS [Amt_in_Words],UserTab.username as [User Name]  
from dbo.tblNoteDetails as Note  
join dbo.tblDocumentSeries AS Doc ON Note.TransID = Doc.TransID  
Join dbo.tblFAAccount as FAParty on FAParty.FAID = Note.PartyId  
Join dbo.tblFAAccount as FAAC on FAAC.FAID = Note.FAID  
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = Note.BranchID
Join dbo.tblMasterCustomer as Customer on Customer.ID = FAParty.FAID  
Join dbo.tblUsers as UserTab on UserTab.ID = Note.MBy or UserTab.ID  =  Note.Cby  
where note.ID = @DocValue AND Note .TransID = 4  
END  
else if(@AccGrpid = 43) -- Vendor            
BEGIN            
Select Note.ID as [Credit Note ID],Note.DocId as [Doc ID],Note.UDFDocId [UDN Doc ID],Convert (nvarchar ,Note.DocDate,103) as [Doc Date],  
Isnull(CONVERT(nvarchar(5),Note.MDate,108),CONVERT(nvarchar(5),Note.CDate,108)) as [Time],Doc.TransName as [Trans Name],  
Note.RefNo as [Doc Ref],FAParty.AccountName as [Party Name],FAAC.AccountName as [Account Name], MBO.Name [Branch Name],Note.Remark as [Remark],  
Note.Narration as [Narration],Vendor.Ph1 AS [Party Prim Phone No],Vendor.Mob1 as [Party Prim Mobile No],  
Vendor.Billadd1  AS [Party Bill Address 1],Vendor.Billadd2 as [Party Bill Address 2],Vendor.Billadd3 as [Party Bill Address 3],        
Vendor.GSTIN [Party GSTIN],Vendor.AadharNo AS [Party Aadhar Number],Vendor.PANNumber AS [Party PAN No],Note.NoteValue as [Note Value],  
Note.Balance as [Balance],dbo.fnConvertAmountinWords(Note.NoteValue) AS [Amt_in_Words],UserTab.username as [User Name]                  
from dbo.tblNoteDetails as Note                
join dbo.tblDocumentSeries AS Doc ON Note.TransID = Doc.TransID                  
Join dbo.tblFAAccount as FAParty on FAParty.FAID = Note.PartyId 
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = Note.BranchID
Join dbo.tblFAAccount as FAAC on FAAC.FAID = Note.FAID                  
Join dbo.tblMasterVendor as Vendor on Vendor.FAID = FAParty.FAID            
Join dbo.tblUsers as UserTab on UserTab.ID = Note.MBy or UserTab.ID  =  Note.Cby                
where note.ID = @DocValue AND Note .TransID = 4           
END
else if(@AccGrpid = 33) -- SalesMan            
BEGIN            
Select Note.ID as [Credit Note ID],Note.DocId as [Doc ID],Note.UDFDocId [UDN Doc ID],Convert (nvarchar ,Note.DocDate,103) as [Date],                
Isnull(CONVERT(nvarchar(5),Note.MDate,108),CONVERT(nvarchar(5),Note.CDate,108)) as [Time],Doc.TransName as [Trans Name],  
Note.RefNo as [Doc Ref],FAParty.AccountName as [Party Name],FAAC.AccountName as [Account Name], MBO.Name [Branch Name],Note.Remark as [Remark],  
Note.Narration as [Narration],'''' AS [Party Prim Landline No],SalesMan.MobileNo as [Party Prim Mobile No],  
SalesMan.Address  AS [Party Bill Address 1],'''' as [Party Bill Address 2],'''' as [Party Bill Address 3],  
'''' [Party GSTIN],SalesMan.AadharNo AS [Party Aadhar Number],SalesMan.PANNumber AS [Party PAN No],Note.NoteValue as [Note Value],  
Note.Balance as [Balance],dbo.fnConvertAmountinWords(Note.NoteValue) AS [Amt_in_Words],UserTab.username as [User Name]                  
from dbo.tblNoteDetails as Note                
join dbo.tblDocumentSeries AS Doc ON Note. TransID = Doc.TransID                  
Join dbo.tblFAAccount as FAParty on FAParty.FAID = Note.PartyId                
Join dbo.tblFAAccount as FAAC on FAAC.FAID = Note.FAID   
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = Note.BranchID
Join dbo.tblMasterSalesMan as SalesMan on SalesMan.FAID = FAParty.FAID            
Join dbo.tblUsers as UserTab on UserTab.ID = Note.MBy or UserTab.ID  =  Note.Cby                
where note.ID = @DocValue AND Note .TransID = 4           
END            
else             
BEGIN            
Select Note.ID as [Credit Note ID],Note.DocId as [Doc ID],Note.UDFDocId [UDN Doc ID],Convert (nvarchar ,Note.DocDate,103) as [Doc Date],                
Isnull(CONVERT(nvarchar(5),Note.MDate,108),CONVERT(nvarchar(5),Note.CDate,108)) as [Time],Doc.TransName as [Trans Name],  
Note.RefNo as [Doc Ref],FAParty.AccountName as [Party Name],FAAC.AccountName as [Account Name], MBO.Name [Branch Name],Note.Remark as [Remark],Note.Narration as [Narration],  
'''' AS [Party Prim Phone No],'''' as [Party Prim Mobile No],'''' AS [Party Bill Address 1],'''' as [Party Bill Address 2],'''' as [Party Bill Address 3],  
'''' [Party GSTIN],'''' AS [Party Aadhar Number],'''' AS [Party PAN No],Note.NoteValue as [Note Value],Note.Balance as [Balance],              
dbo.fnConvertAmountinWords(Note.NoteValue) AS [Amt_in_Words],UserTab.username as [User Name]              
from dbo.tblNoteDetails as Note                
join dbo.tblDocumentSeries AS Doc ON Note. TransID = Doc.TransID                  
Join dbo.tblFAAccount as FAParty on FAParty.FAID = Note.PartyId                
Join dbo.tblFAAccount as FAAC on FAAC.FAID = Note.FAID
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = Note.BranchID
Join dbo.tblUsers as UserTab on UserTab.ID = Note.MBy or UserTab.ID  =  Note.Cby                
where note.ID = @DocValue AND Note .TransID = 4           
END',
N'[export] nocount';
GO
/****** uspCRepManufPurchaseClosingStockSheet1 ******/
EXEC #Apply07 N'dbo.uspCRepManufPurchaseClosingStockSheet1', 0xD84B359C5597CF3AF16A67E7A822D5D6BB1D0383393EDAA38E9B51098C69161A, NULL, NULL, 0xBE266ED6504F4D819591E6D72DDCA3E71D2BAA32FC0531571D6E66098758B70F, 0xE5FBDEA8A4B7D58AED0A385FCA9735AE6F96D80007C71F0CE0B8F19778D6BA45, NULL,
N'ALTER PROCEDURE [dbo].[uspCRepManufPurchaseClosingStockSheet1]                
@BranchName NVARCHAR(255) = null,                        
@MfrName NVARCHAR(255) = null,                        
@BrandName NVARCHAR(255) = null,                        
@CategoryName NVARCHAR(255) = null,                        
@ProductName NVARCHAR(255) = null,              
@FromDate DATE = ''2026-05-01'',                
@ToDate DATE = ''2026-05-30''                
AS                
SET NOCOUNT ON;
BEGIN                
SELECT DS.TransName [Transaction],MV.Name AS [Vendor Name],[RefNo] as [Ref No],BillHeader.DocID [Doc ID],      
FORMAT(BillHeader.Date,''dd-MMM-yyyy'') [Doc Date],Prod.Code AS [Product Code],Prod.Name AS [Product Name],Prod.EAN as EAN,                
UOM.Name AS [UOM Name],    
dbo.funTwoDecimalRoundOff(ISNULL(BD.UomQty,0)) AS Qty,dbo.funTwoDecimalRoundOff(ISNULL(BD.UomFreeQty,0)) AS [Free Qty],                
dbo.funTwoDecimalRoundOff(ISNULL(BD.UomDamageQty,0)) AS [Damage Qty],buom.name [Base UOM],    
dbo.funTwoDecimalRoundOff(ISNULL(BD.UomQty,0) * (CASE WHEN BD.UomID = Prod.BaseUomID THEN Prod.BaseCR else Prod.PurchaseCR end)) AS [Base Qty],    
dbo.funTwoDecimalRoundOff(ISNULL(BD.UomFreeQty,0) * (CASE WHEN BD.UomID = Prod.BaseUomID THEN Prod.BaseCR else Prod.PurchaseCR end)) AS [Base Free Qty],    
dbo.funTwoDecimalRoundOff(ISNULL(BD.UomDamageQty,0) * (CASE WHEN BD.UomID = Prod.BaseUomID THEN Prod.BaseCR else Prod.PurchaseCR end)) AS [Base Dmg Qty],    
dbo.fun4DecimalRoundOff(ISNULL(BD.UomPurchasePrice,0) /(CASE WHEN BD.UomID = Prod.BaseUomID THEN Prod.BaseCR else Prod.PurchaseCR end)) AS [Base Purchase Price],    
dbo.fun4DecimalRoundOff(ISNULL(BD.UomPurchasePrice,0)) AS [Purchase Price],                
dbo.funTwoDecimalRoundOff(ISNULL(BD.UomMRP,0)) AS MRP,Tax.TaxName AS [Tax Name],dbo.funTwoDecimalRoundOff(ISNULL(BD.[Tax%],0)) AS [Tax %],                
dbo.fun4DecimalRoundOff(ISNULL(BD.GoodsAmt,0)) AS [Goods Amount],dbo.fun4DecimalRoundOff(ISNULL(BD.[ProdDisc%],0)) AS [Prod Discount],                
dbo.fun4DecimalRoundOff(ISNULL((BD.GoodsAmt * ISNULL(BD.[ProdDisc%],0))/100 ,0)) AS [Prod Disc Amount],                
dbo.fun4DecimalRoundOff(ISNULL(BD.[TradeDisc%],0)) AS [Trade Disc %],dbo.fun4DecimalRoundOff(ISNULL(BD.[AddnlDisc%],0)) AS [Addnl Disc %],                
dbo.fun4DecimalRoundOff(ISNULL(BD.GrossAmt,0)) AS [Gross Amount],dbo.fun4DecimalRoundOff(ISNULL(BD.TaxAmt,0)) AS [Tax Amount],                
dbo.fun4DecimalRoundOff(ISNULL(BD.NetAmt,0)) AS [Net Amount]              
FROM tblTransPurchaseDetail BD                
JOIN tblTransPurchaseHeader as BillHeader on BillHeader.ID = BD.HID          
LEFT JOIN tblMasterProduct Prod ON Prod.ID=BD.ProdID                
JOIN tblMasterUom UOM ON UOM.ID=BD.UomID    
JOIN tblMasterUom BUOM ON BUOM.ID=Prod.BaseUomID    
LEFT JOIN tblMasterTax Tax ON Tax.TaxID=BD.TaxID                
LEFT JOIN tblMasterReason R ON R.ID=BD.ReasonId           
join tblDocumentSeries DS ON DS.TransID = BillHeader.TransID       
Join tblMasterVendor MV on BillHeader.VendorID = MV.ID         
WHERE BillHeader.Status NOT IN(2,4)      
AND BillHeader.Date BETWEEN @FromDate AND @ToDate                      
AND (isnull(@BranchName,'''') = '''' OR BillHeader.BranchID in (select value from string_split(@BranchName,'','')))                       
AND (isnull(@MfrName,'''') = '''' OR Prod.MfrID in (select value from string_split(@MfrName,'','')))                       
AND (isnull(@BrandName,'''') = '''' OR Prod.BrandID in (select value from string_split(@BrandName,'','')))                      
AND (isnull(@CategoryName,'''') = '''' OR Prod.CategoryID in (select value from string_split(@CategoryName,'','')))                      
AND (isnull(@ProductName,'''') = '''' OR Prod.ID in (select value from string_split(@ProductName,'','')))                
ORDER BY BillHeader.Date,BillHeader.DocID,BD.Serial       
END',
N'[export] nocount';
GO
/****** uspCRepManufPurchaseClosingStockSheet2 ******/
EXEC #Apply07 N'dbo.uspCRepManufPurchaseClosingStockSheet2', 0x8BF710B695223E185313E0C0C17BC8309FC1E6AE95169C38A14492A754A2E620, NULL, NULL, 0xE2724E86CB08DEAD62E837CBD0CAEA70EC90955124368AFDAEFE63AACCDB9BEE, 0xD50034122AE2F15D53D91048B5016815C8D88D138A9303A430BE1C6AC234885E, NULL,
N'ALTER PROCEDURE [dbo].[uspCRepManufPurchaseClosingStockSheet2]             
@BranchName NVARCHAR(255) = null,                      
@MfrName NVARCHAR(255) = null,                      
@BrandName NVARCHAR(255) = null,                      
@CategoryName NVARCHAR(255) = null,                      
@ProductName NVARCHAR(255) = null,            
@FromDate DATE = ''2024-08-01'',              
@ToDate DATE = ''2026-08-30''              
AS              
SET NOCOUNT ON;
BEGIN              
select Code [Product Code],[Product Name],EAN,HSNCode [HSN Code],[Manufacturer Name],[Brand Name],[Category Name],dbo.funTwoDecimalRoundOff(sum([Saleable Qty])) [Saleable Qty],              
dbo.funTwoDecimalRoundOff(sum([Damage Qty])) [Damage Qty],[Base UOM],dbo.funTwoDecimalRoundOff(sum([Reporting Qty])) [Reporting Qty],  
[Reporting UOM],              
dbo.fun4DecimalRoundOff(sum([Stock Value])) [Stock Value],dbo.fun4DecimalRoundOff(sum([Damage Stock Value])) [Damage Stock Value],      
dbo.fun4DecimalRoundOff([Purchase Price]) [Purchase Price],dbo.fun4DecimalRoundOff([Sales Price]) [Sales Price],      
dbo.funTwoDecimalRoundOff(MRP) MRP      
from (              
SELECT TMP.Name [Product Name],MM.Name[Manufacturer Name], MB.Name[Brand Name], MC.Name[Category Name], CS.ActualQty [Saleable Qty],               
CS.ActualDmgQty [Damage Qty],MU.Name[Base UOM],CS.ActualQty / TMP.[ReportingCR] [Reporting Qty] ,RMU.Name [Reporting UOM],              
CS.ActualQty * CS.PurchasePrice [Stock Value], CS.ActualDmgQty * CS.PurchasePrice [Damage Stock Value],      
CS.PurchasePrice [Purchase Price],CS.SalesPrice [Sales Price],CS.MRPONPrice MRP,TMP.Code,TMP.EAN,TMP.HSNCode
FROM tblProductInventory CS              
JOIN tblMasterProduct TMP on TMP.ID = CS.ProdId              
JOIN tblMasterManufacturer MM on MM.ID = TMP.MfrID              
JOIN tblMasterBrand MB on MB.ID = TMP.BrandID              
JOIN tblMasterCategory MC on MC.ID = TMP.CategoryID              
JOIN tblMasterUOM MU on MU.ID = TMP.BaseUomID              
JOIN tblMasterUOM RMU on RMU.ID = TMP.ReportingUomID              
WHERE (isnull(@BranchName,'''') = '''' OR CS.BranchID  in (select value from string_split(@BranchName,'','')))              
AND (isnull(@MfrName,'''') = '''' OR TMP.MfrID  in (select value from string_split(@MfrName,'','')))              
AND (isnull(@BrandName,'''') = '''' OR TMP.BrandID  in (select value from string_split(@BrandName,'','')))              
AND (isnull(@CategoryName,'''') = '''' OR TMP.CategoryID  in (select value from string_split(@CategoryName,'','')))              
AND (isnull(@ProductName,'''') = '''' OR TMP.Name  in (select value from string_split(@ProductName,'','')))) as rec    
group by [Product Name],[Manufacturer Name],[Brand Name],[Category Name],[Reporting UOM],[Base UOM],      
[Purchase Price],[Sales Price],MRP,Code,EAN,HSNCode      
HAVING (sum([Saleable Qty]) > 0 OR sum([Damage Qty]) > 0)    
order by [Product Name]     
END',
N'[export] nocount';
GO
/****** uspCRepManufSaleClosingStockSheet1 ******/
EXEC #Apply07 N'dbo.uspCRepManufSaleClosingStockSheet1', 0xAF4D354CF4E3A9E89DEFF3E49ED8DFF2F2C55DBB189C33FEDBFFCF282C0E3B57, NULL, NULL, 0xB6E945B62D860C992E7EF6FC0C3D3BFA4DFB99F40F85401EDD110ABFB3469B10, 0x35F91A0D1D40FB6C62AA79375CDCA320FDEB70502BEA94E3D46BA1E2A3EDBBA2, NULL,
N'--EXEC uspCRepManufSaleClosingStockSheet1 0,0,0,0,NULL,''2026-05-09'',''2026-05-09''        
ALTER PROCEDURE [dbo].[uspCRepManufSaleClosingStockSheet1]                    
@BranchName NVARCHAR(255) = null,                    
@MfrName NVARCHAR(255) = null,                    
@BrandName NVARCHAR(255) = null,                    
@CategoryName NVARCHAR(255) = null,                    
@ProductName NVARCHAR(255) = null,                    
@FromDate DATE = ''2024-08-01'',                                
@ToDate DATE = ''2026-08-30''            
AS                     
SET NOCOUNT ON;
BEGIN                    
SELECT TMC.Name[Customer Name], TSH.DocID[Doc ID],FORMAT(TSH.InvDate,''dd/MMM/yyyy'') [Doc Date],                     
TMP.Name[Product Name], MM.Name[Mfr Name], MB.Name[Brand Name], MC.Name[Category Name],               
dbo.funTwoDecimalRoundOff(TSD.DetailMRP)[MRP on Price],                    
dbo.funTwoDecimalRoundOff(TSD.UomQty / ISNULL(TSD.UOMCF,1))[Qty], MU.Name[UOM Name], dbo.funTwoDecimalRoundOff(TSD.BaseUomPrice)[Price],                    
dbo.funTwoDecimalRoundOff(TSD.ProdDiscAmt)[Prod Disc Amount], dbo.funTwoDecimalRoundOff(TSD.TradeDisc)[Trade Disc Amount],  
dbo.funTwoDecimalRoundOff(TSD.AddnlDisc)[Addtional Disc Amount],                    
dbo.funTwoDecimalRoundOff(TSD.AddnlDisc + TSD.TradeDisc + TSD.ProdDiscAmt) AS [ALL Discount Amount],                    
MT.TaxName[Tax%], dbo.funTwoDecimalRoundOff(TSD.TaxAmt)[Tax Amount], dbo.funTwoDecimalRoundOff(TSD.GrossAmt)[Gross Amount],dbo.funTwoDecimalRoundOff(TSD.NetAmt)[Net Amount]                    
FROM tblTranSalesHeader TSH                    
JOIN tblTranSalesDetail TSD on TSD.InvID = TSH.ID                    
LEFT JOIN tblMasterCustomer TMC on TMC.ID = TSH.CustID                    
LEFT JOIN tblMasterProduct TMP on TMP.ID = TSD.ProdID                    
JOIN tblMasterManufacturer MM on MM.ID = TMP.MfrID                    
JOIN tblMasterBrand MB on MB.ID = TMP.BrandID                    
JOIN tblMasterCategory MC on MC.ID = TMP.CategoryID                    
LEFT join tblMasterUOM MU on MU.ID = TSD.UomID                    
LEFT JOIN tblMasterTax MT on MT.TaxID = TSD.TaxID                    
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = TSH.BranchID                    
WHERE TSH.DocPrefix = 15 AND TSH.Status IN(1,3,5) AND TSD.TaxID > 0        
AND TSH.InvDate BETWEEN @FromDate AND @ToDate                    
AND (isnull(@BranchName,'''') = '''' OR TSH.BranchID in (select value from string_split(@BranchName,'','')))                     
AND (isnull(@MfrName,'''') = '''' OR TMP.MfrID in (select value from string_split(@MfrName,'','')))                     
AND (isnull(@BrandName,'''') = '''' OR TMP.BrandID in (select value from string_split(@BrandName,'','')))                    
AND (isnull(@CategoryName,'''') = '''' OR TMP.CategoryID in (select value from string_split(@CategoryName,'','')))                    
AND (isnull(@ProductName,'''') = '''' OR TMP.ID in (select value from string_split(@ProductName,'','')))          
order by TSH.InvDate,TSH.DocID,TSD.Serial        
END',
N'[export] nocount';
GO
/****** uspCRepManufSaleClosingStockSheet2 ******/
EXEC #Apply07 N'dbo.uspCRepManufSaleClosingStockSheet2', 0xC21D30E747FDDBCE4375453254F2045CF12C5B314D84ED5AECFD04BFA0F5DA59, NULL, NULL, 0xD820BB616D227B10D2048995A97D3756B413FFD9D6A7DD923FB2ADB310C05359, 0x0276D7CCBC8848FBFC71EF737841D679F0807E4A5897F5B5FBF2E57AD7709D6C, NULL,
N'ALTER PROCEDURE [dbo].[uspCRepManufSaleClosingStockSheet2]          
@BranchName NVARCHAR(255) = null,                  
@MfrName NVARCHAR(255) = null,                  
@BrandName NVARCHAR(255) = null,                  
@CategoryName NVARCHAR(255) = null,                  
@ProductName NVARCHAR(255) = null,        
@FromDate DATE = ''2024-08-01'',          
@ToDate DATE = ''2026-08-30''          
AS          
SET NOCOUNT ON;
BEGIN          
declare @today date = getdate()        
if(@ToDate = @today)        
BEGIN        
select [Product Name],[Manufacturer Name],[Brand Name],[Category Name],dbo.funTwoDecimalRoundOff(sum([Saleable Qty])) [Saleable Qty],          
dbo.funTwoDecimalRoundOff(sum([Damage Qty])) [Damage Qty],[Base UOM],dbo.funTwoDecimalRoundOff(sum([Reporting Qty])) [Reporting Qty],[Reporting UOM],          
dbo.funTwoDecimalRoundOff(sum([Stock Value])) [Stock Value],dbo.funTwoDecimalRoundOff(sum([Damage Stock Value])) [Damage Stock Value] from (          
SELECT TMP.Name [Product Name],MM.Name[Manufacturer Name], MB.Name[Brand Name], MC.Name[Category Name], CS.ActualQty [Saleable Qty],           
CS.ActualDmgQty [Damage Qty],MU.Name[Base UOM],CS.ActualQty / TMP.[ReportingCR] [Reporting Qty] ,RMU.Name [Reporting UOM],          
CS.ActualQty * CS.PurchasePrice [Stock Value], CS.ActualDmgQty * CS.PurchasePrice [Damage Stock Value]          
FROM tblProductInventory CS          
JOIN tblMasterProduct TMP on TMP.ID = CS.ProdId          
JOIN tblMasterManufacturer MM on MM.ID = TMP.MfrID          
JOIN tblMasterBrand MB on MB.ID = TMP.BrandID          
JOIN tblMasterCategory MC on MC.ID = TMP.CategoryID          
JOIN tblMasterUOM MU on MU.ID = TMP.BaseUomID          
JOIN tblMasterUOM RMU on RMU.ID = TMP.ReportingUomID          
WHERE (isnull(@BranchName,'''') = '''' OR CS.BranchID  in (select value from string_split(@BranchName,'','')))          
AND (isnull(@MfrName,'''') = '''' OR TMP.MfrID  in (select value from string_split(@MfrName,'','')))          
AND (isnull(@BrandName,'''') = '''' OR TMP.BrandID  in (select value from string_split(@BrandName,'','')))          
AND (isnull(@CategoryName,'''') = '''' OR TMP.CategoryID  in (select value from string_split(@CategoryName,'','')))          
AND (isnull(@ProductName,'''') = '''' OR TMP.Name  in (select value from string_split(@ProductName,'','')))) as rec          
group by [Product Name],[Manufacturer Name],[Brand Name],[Category Name],[Reporting UOM],[Base UOM]          
order by [Product Name]          
END        
ELSE        
BEGIN        
select [Product Name],[Manufacturer Name],[Brand Name],[Category Name],dbo.funTwoDecimalRoundOff(sum([Saleable Qty])) [Saleable Qty],          
dbo.funTwoDecimalRoundOff(sum([Damage Qty])) [Damage Qty],[Base UOM],dbo.funTwoDecimalRoundOff(sum([Reporting Qty])) [Reporting Qty],[Reporting UOM],          
dbo.funTwoDecimalRoundOff(sum([Stock Value])) [Stock Value],dbo.funTwoDecimalRoundOff(sum([Damage Stock Value])) [Saleable Qty] from (          
SELECT TMP.Name [Product Name],MM.Name[Manufacturer Name], MB.Name[Brand Name], MC.Name[Category Name], CS.SaleQty[Saleable Qty],           
CS.DmgQty[Damage Qty],MU.Name[Base UOM],CS.SaleQty / TMP.[ReportingCR] [Reporting Qty] ,RMU.Name [Reporting UOM],          
CS.SaleStockValue [Stock Value], CS.DmgStockValue [Damage Stock Value]          
FROM tblClosingStock CS          
LEFT JOIN tblMasterProduct TMP on TMP.ID = CS.ProdId          
LEFT JOIN tblMasterManufacturer MM on MM.ID = TMP.MfrID          
LEFT JOIN tblMasterBrand MB on MB.ID = TMP.BrandID          
LEFT JOIN tblMasterCategory MC on MC.ID = TMP.CategoryID          
LEFT JOIN tblMasterUOM MU on MU.ID = TMP.BaseUomID          
LEFT JOIN tblMasterUOM RMU on RMU.ID = TMP.ReportingUomID          
WHERE CS.ClsDate = @ToDate          
AND (isnull(@BranchName,'''') = '''' OR CS.BranchID  in (select value from string_split(@BranchName,'','')))          
AND (isnull(@MfrName,'''') = '''' OR TMP.MfrID  in (select value from string_split(@MfrName,'','')))          
AND (isnull(@BrandName,'''') = '''' OR TMP.BrandID  in (select value from string_split(@BrandName,'','')))          
AND (isnull(@CategoryName,'''') = '''' OR TMP.CategoryID  in (select value from string_split(@CategoryName,'','')))          
AND (isnull(@ProductName,'''') = '''' OR TMP.Name  in (select value from string_split(@ProductName,'','')))) as rec          
group by [Product Name],[Manufacturer Name],[Brand Name],[Category Name],[Reporting UOM],[Base UOM]          
order by [Product Name]          
END        
END',
N'[export] nocount';
GO
/****** uspCRepManufSaleClosingStockSheet3 ******/
EXEC #Apply07 N'dbo.uspCRepManufSaleClosingStockSheet3', 0x56212267E7D1E53B8D94F4F371D2D9D6A6D51361C5E94DEB9EB50E3ADB494DE1, NULL, NULL, 0x69220EEC35A4784485808F14C5708E87F44E1E112D129B50E621110196EBC1FC, 0x7EC224C1CCE1B1AEFA22F3BEC3542652E3516225ACBB3F1244CEB4AC08273E83, NULL,
N'ALTER PROCEDURE [dbo].[uspCRepManufSaleClosingStockSheet3]            
@BranchName NVARCHAR(255) = null,                    
@MfrName NVARCHAR(255) = null,                    
@BrandName NVARCHAR(255) = null,                    
@CategoryName NVARCHAR(255) = null,                    
@ProductName NVARCHAR(255) = null,          
@FromDate DATE = ''2026-05-01'',            
@ToDate DATE = ''2026-05-30''            
AS            
SET NOCOUNT ON;
BEGIN            
SELECT DS.TransName [Transaction],MV.Name AS [Vendor Name],[RefNo] as [Ref No],BillHeader.DocID [Doc ID],  
FORMAT(BillHeader.Date,''dd-MMM-yyyy'') [Doc Date],Prod.Code AS [Product Code],Prod.Name AS [Product Name],Prod.EAN as EAN,            
UOM.Name AS [UOM Name],
dbo.fnGetRoundedValue(ISNULL(BD.UomQty,0)) AS Qty,dbo.fnGetRoundedValue(ISNULL(BD.UomFreeQty,0)) AS [Free Qty],            
dbo.fnGetRoundedValue(ISNULL(BD.UomDamageQty,0)) AS [Damage Qty],buom.name [Base UOM],
dbo.fnGetRoundedValue(ISNULL(BD.UomQty,0) * (CASE WHEN BD.UomID = Prod.BaseUomID THEN Prod.BaseCR else Prod.PurchaseCR end)) AS [Base Qty],
dbo.fnGetRoundedValue(ISNULL(BD.UomFreeQty,0) * (CASE WHEN BD.UomID = Prod.BaseUomID THEN Prod.BaseCR else Prod.PurchaseCR end)) AS [Base Free Qty],
dbo.fnGetRoundedValue(ISNULL(BD.UomDamageQty,0) * (CASE WHEN BD.UomID = Prod.BaseUomID THEN Prod.BaseCR else Prod.PurchaseCR end)) AS [Base Dmg Qty],
dbo.fnGetRoundedValue(ISNULL(BD.UomPurchasePrice,0) /(CASE WHEN BD.UomID = Prod.BaseUomID THEN Prod.BaseCR else Prod.PurchaseCR end)) AS [Base Purchase Price],
dbo.fnGetRoundedValue(ISNULL(BD.UomPurchasePrice,0)) AS [Purchase Price],            
dbo.fnGetRoundedValue(ISNULL(BD.UomMRP,0)) AS MRP,Tax.TaxName AS [Tax Name],dbo.fnGetRoundedValue(ISNULL(BD.[Tax%],0)) AS [Tax %],            
dbo.fnGetRoundedValue(ISNULL(BD.GoodsAmt,0)) AS [Goods Amount],dbo.fnGetRoundedValue(ISNULL(BD.[ProdDisc%],0)) AS [Prod Discount],            
dbo.fnGetRoundedValue(ISNULL((BD.GoodsAmt * ISNULL(BD.[ProdDisc%],0))/100 ,0)) AS [Prod Disc Amount],            
dbo.fnGetRoundedValue(ISNULL(BD.[TradeDisc%],0)) AS [Trade Disc %],dbo.fnGetRoundedValue(ISNULL(BD.[AddnlDisc%],0)) AS [Addnl Disc %],            
dbo.fnGetRoundedValue(ISNULL(BD.GrossAmt,0)) AS [Gross Amount],dbo.fnGetRoundedValue(ISNULL(BD.TaxAmt,0)) AS [Tax Amount],            
dbo.fnGetRoundedValue(ISNULL(BD.NetAmt,0)) AS [Net Amount]          
FROM tblTransPurchaseDetail BD            
JOIN tblTransPurchaseHeader as BillHeader on BillHeader.ID = BD.HID      
LEFT JOIN tblMasterProduct Prod ON Prod.ID=BD.ProdID            
JOIN tblMasterUom UOM ON UOM.ID=BD.UomID
JOIN tblMasterUom BUOM ON BUOM.ID=Prod.BaseUomID
LEFT JOIN tblMasterTax Tax ON Tax.TaxID=BD.TaxID            
LEFT JOIN tblMasterReason R ON R.ID=BD.ReasonId       
join tblDocumentSeries DS ON DS.TransID = BillHeader.TransID   
Join tblMasterVendor MV on BillHeader.VendorID = MV.ID     
WHERE BillHeader.Status NOT IN(2,4)  
AND BillHeader.Date BETWEEN @FromDate AND @ToDate                  
AND (isnull(@BranchName,'''') = '''' OR BillHeader.BranchID in (select value from string_split(@BranchName,'','')))                   
AND (isnull(@MfrName,'''') = '''' OR Prod.MfrID in (select value from string_split(@MfrName,'','')))                   
AND (isnull(@BrandName,'''') = '''' OR Prod.BrandID in (select value from string_split(@BrandName,'','')))                  
AND (isnull(@CategoryName,'''') = '''' OR Prod.CategoryID in (select value from string_split(@CategoryName,'','')))                  
AND (isnull(@ProductName,'''') = '''' OR Prod.ID in (select value from string_split(@ProductName,'','')))            
ORDER BY BillHeader.Date,BillHeader.DocID,BD.Serial   
END',
N'[export] nocount';
GO
/****** uspCRepManufSaleClosingStockSheet4 ******/
EXEC #Apply07 N'dbo.uspCRepManufSaleClosingStockSheet4', 0xFA1B536A03508380414483DBEA79741E79172D6E2DFF48DC74065A8ED4330E04, NULL, NULL, 0x39A54BB1FA654A346FB25A22C369CD2F70FA7BA06B8FFB62ABE4C3A38C5903C1, 0x17AB2B7C13A3ABDD82BD54DE73E257FD553B17E77FF78237556A8CBF323DB271, NULL,
N'ALTER PROCEDURE [dbo].[uspCRepManufSaleClosingStockSheet4]       
@BranchName NVARCHAR(255) = null,                
@MfrName NVARCHAR(255) = null,                
@BrandName NVARCHAR(255) = null,                
@CategoryName NVARCHAR(255) = null,                
@ProductName NVARCHAR(255) = null,      
@FromDate DATE = ''2024-08-01'',        
@ToDate DATE = ''2026-08-30''        
AS        
SET NOCOUNT ON;
BEGIN        
declare @today date = getdate()      
if(@ToDate = @today)      
BEGIN      
select [Product Name],[Manufacturer Name],[Brand Name],[Category Name],dbo.funTwoDecimalRoundOff(sum([Saleable Qty])) [Saleable Qty],        
dbo.funTwoDecimalRoundOff(sum([Damage Qty])) [Damage Qty],[Base UOM],dbo.funTwoDecimalRoundOff(sum([Reporting Qty])) [Reporting Qty],[Reporting UOM],        
dbo.funTwoDecimalRoundOff(sum([Stock Value])) [Stock Value],dbo.funTwoDecimalRoundOff(sum([Damage Stock Value])) [Damage Stock Value],
dbo.funTwoDecimalRoundOff([Purchase Price]) [Purchase Price],dbo.funTwoDecimalRoundOff([Sales Price]) [Sales Price],
dbo.funTwoDecimalRoundOff(MRP) MRP
from (        
SELECT TMP.Name [Product Name],MM.Name[Manufacturer Name], MB.Name[Brand Name], MC.Name[Category Name], CS.ActualQty [Saleable Qty],         
CS.ActualDmgQty [Damage Qty],MU.Name[Base UOM],CS.ActualQty / TMP.[ReportingCR] [Reporting Qty] ,RMU.Name [Reporting UOM],        
CS.ActualQty * CS.PurchasePrice [Stock Value], CS.ActualDmgQty * CS.PurchasePrice [Damage Stock Value],
TMP.PurchasePrice [Purchase Price],TMP.SalesPrice [Sales Price],TMP.MRP
FROM tblProductInventory CS        
JOIN tblMasterProduct TMP on TMP.ID = CS.ProdId        
JOIN tblMasterManufacturer MM on MM.ID = TMP.MfrID        
JOIN tblMasterBrand MB on MB.ID = TMP.BrandID        
JOIN tblMasterCategory MC on MC.ID = TMP.CategoryID        
JOIN tblMasterUOM MU on MU.ID = TMP.BaseUomID        
JOIN tblMasterUOM RMU on RMU.ID = TMP.ReportingUomID        
WHERE (isnull(@BranchName,'''') = '''' OR CS.BranchID  in (select value from string_split(@BranchName,'','')))        
AND (isnull(@MfrName,'''') = '''' OR TMP.MfrID  in (select value from string_split(@MfrName,'','')))        
AND (isnull(@BrandName,'''') = '''' OR TMP.BrandID  in (select value from string_split(@BrandName,'','')))        
AND (isnull(@CategoryName,'''') = '''' OR TMP.CategoryID  in (select value from string_split(@CategoryName,'','')))        
AND (isnull(@ProductName,'''') = '''' OR TMP.Name  in (select value from string_split(@ProductName,'','')))) as rec        
group by [Product Name],[Manufacturer Name],[Brand Name],[Category Name],[Reporting UOM],[Base UOM],
[Purchase Price],[Sales Price],MRP
order by [Product Name]        
END      
ELSE      
BEGIN      
select [Product Name],[Manufacturer Name],[Brand Name],[Category Name],dbo.funTwoDecimalRoundOff(sum([Saleable Qty])) [Saleable Qty],        
dbo.funTwoDecimalRoundOff(sum([Damage Qty])) [Damage Qty],[Base UOM],dbo.funTwoDecimalRoundOff(sum([Reporting Qty])) [Reporting Qty],[Reporting UOM],        
dbo.funTwoDecimalRoundOff(sum([Stock Value])) [Stock Value],dbo.funTwoDecimalRoundOff(sum([Damage Stock Value])) [Saleable Qty],
dbo.funTwoDecimalRoundOff([Purchase Price]) [Purchase Price],dbo.funTwoDecimalRoundOff([Sales Price]) [Sales Price],
dbo.funTwoDecimalRoundOff(MRP) MRP from (        
SELECT TMP.Name [Product Name],MM.Name[Manufacturer Name], MB.Name[Brand Name], MC.Name[Category Name], CS.SaleQty[Saleable Qty],         
CS.DmgQty[Damage Qty],MU.Name[Base UOM],CS.SaleQty / TMP.[ReportingCR] [Reporting Qty] ,RMU.Name [Reporting UOM],        
CS.SaleStockValue [Stock Value], CS.DmgStockValue [Damage Stock Value],
TMP.PurchasePrice [Purchase Price],TMP.SalesPrice [Sales Price],TMP.MRP
FROM tblClosingStock CS        
LEFT JOIN tblMasterProduct TMP on TMP.ID = CS.ProdId        
LEFT JOIN tblMasterManufacturer MM on MM.ID = TMP.MfrID        
LEFT JOIN tblMasterBrand MB on MB.ID = TMP.BrandID        
LEFT JOIN tblMasterCategory MC on MC.ID = TMP.CategoryID        
LEFT JOIN tblMasterUOM MU on MU.ID = TMP.BaseUomID        
LEFT JOIN tblMasterUOM RMU on RMU.ID = TMP.ReportingUomID        
WHERE CS.ClsDate = @ToDate        
AND (isnull(@BranchName,'''') = '''' OR CS.BranchID  in (select value from string_split(@BranchName,'','')))        
AND (isnull(@MfrName,'''') = '''' OR TMP.MfrID  in (select value from string_split(@MfrName,'','')))        
AND (isnull(@BrandName,'''') = '''' OR TMP.BrandID  in (select value from string_split(@BrandName,'','')))        
AND (isnull(@CategoryName,'''') = '''' OR TMP.CategoryID  in (select value from string_split(@CategoryName,'','')))        
AND (isnull(@ProductName,'''') = '''' OR TMP.Name  in (select value from string_split(@ProductName,'','')))) as rec        
group by [Product Name],[Manufacturer Name],[Brand Name],[Category Name],[Reporting UOM],[Base UOM],
[Purchase Price],[Sales Price],MRP
order by [Product Name]        
END      
END',
N'[export] nocount';
GO
/****** uspCRepTransClosingStockSalesSheet ******/
EXEC #Apply07 N'dbo.uspCRepTransClosingStockSalesSheet', 0x23150C286F08203A1E72B5AC906010C59D1BD9B54FED50422EAC743FA7B30725, NULL, NULL, 0xF7D5D782D2BDD4379D4420916573CA2072032F8517F2D549EAA38BD5E150D529, 0xE25CE989C65D2D0E11C7096D0B1920857A17538F037CA409022D2FFF34F36FDC, NULL,
N'--EXEC uspCRepManufSaleClosingStockSheet1 0,0,0,0,NULL,''2026-05-09'',''2026-05-09''        
ALTER PROCEDURE [dbo].[uspCRepTransClosingStockSalesSheet]
@BranchName NVARCHAR(255) = null,                    
@MfrName NVARCHAR(255) = null,                    
@BrandName NVARCHAR(255) = null,                    
@CategoryName NVARCHAR(255) = null,                    
@ProductName NVARCHAR(255) = null,                    
@FromDate DATE = ''2024-08-01'',                                
@ToDate DATE = ''2026-08-30''            
AS                     
SET NOCOUNT ON;
BEGIN                    
SELECT TMC.Name[Customer Name], TSH.DocID[Doc ID],FORMAT(TSH.InvDate,''dd/MMM/yyyy'') [Doc Date],                     
TMP.Name[Product Name], MM.Name[Mfr Name], MB.Name[Brand Name], MC.Name[Category Name],               
dbo.funTwoDecimalRoundOff(TSD.DetailMRP)[MRP on Price],                    
dbo.funTwoDecimalRoundOff(TSD.UomQty / ISNULL(TSD.UOMCF,1))[Qty], MU.Name[UOM Name], dbo.fun4DecimalRoundOff(TSD.BaseUomPrice)[Price],                    
dbo.funTwoDecimalRoundOff(TSD.ProdDiscAmt)[Prod Disc Amount], dbo.fun4DecimalRoundOff(TSD.TradeDisc)[Trade Disc Amount],  
dbo.fun4DecimalRoundOff(TSD.AddnlDisc)[Addtional Disc Amount],                    
dbo.fun4DecimalRoundOff(TSD.AddnlDisc + TSD.TradeDisc + TSD.ProdDiscAmt) AS [ALL Discount Amount],                    
MT.TaxName[Tax%], dbo.fun4DecimalRoundOff(TSD.TaxAmt)[Tax Amount], dbo.fun4DecimalRoundOff(TSD.GrossAmt)[Gross Amount],dbo.fun4DecimalRoundOff(TSD.NetAmt)[Net Amount]                    
FROM tblTranSalesHeader TSH                    
JOIN tblTranSalesDetail TSD on TSD.InvID = TSH.ID                    
LEFT JOIN tblMasterCustomer TMC on TMC.ID = TSH.CustID                    
LEFT JOIN tblMasterProduct TMP on TMP.ID = TSD.ProdID                    
JOIN tblMasterManufacturer MM on MM.ID = TMP.MfrID                    
JOIN tblMasterBrand MB on MB.ID = TMP.BrandID                    
JOIN tblMasterCategory MC on MC.ID = TMP.CategoryID                    
LEFT join tblMasterUOM MU on MU.ID = TSD.UomID                    
LEFT JOIN tblMasterTax MT on MT.TaxID = TSD.TaxID                    
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = TSH.BranchID                    
WHERE TSH.DocPrefix = 15 AND TSH.Status IN(1,3,5) AND TSD.TaxID > 0        
AND TSH.InvDate BETWEEN @FromDate AND @ToDate                    
AND (isnull(@BranchName,'''') = '''' OR TSH.BranchID in (select value from string_split(@BranchName,'','')))                     
AND (isnull(@MfrName,'''') = '''' OR TMP.MfrID in (select value from string_split(@MfrName,'','')))                     
AND (isnull(@BrandName,'''') = '''' OR TMP.BrandID in (select value from string_split(@BrandName,'','')))                    
AND (isnull(@CategoryName,'''') = '''' OR TMP.CategoryID in (select value from string_split(@CategoryName,'','')))                    
AND (isnull(@ProductName,'''') = '''' OR TMP.ID in (select value from string_split(@ProductName,'','')))          
order by TSH.InvDate,TSH.DocID,TSD.Serial        
END',
N'[export] nocount';
GO
/****** uspCustomerHeaderReportDetail ******/
EXEC #Apply07 N'dbo.uspCustomerHeaderReportDetail', 0x97C8C39502546BE3F439A010EC1C636A58C09E0F9F4FBCF6CCA34EFFD5E9306F, 0xAE8CB0E35965B98B3942C1B4C575A48EF922E03E389CB8ED962C8783D317DEED, NULL, 0x37689397117C17B2BEB73E58F02D605CBA81E48617E41101FBDB189AE0D44332, 0x01EEA4063C9C5F003D42404EAF4B874D4F0687B64524D9FDEBAC355DF462F91E, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspCustomerHeaderReportDetail]    
@CustomerID int =356, @CustomerType nvarchar(255) = '''',@Ratings  nvarchar(255) = '''',@BeatName  nvarchar(255) = '''',
@SalesmanName  nvarchar(255) = '''',@Location nvarchar(255) = ''''
as    
SET NOCOUNT ON;
begin    
DECLARE @strQuery NVARCHAR(MAX) = ''''       
set @strQuery = ''    
select MC.Code [Customer Code],MC.Name [Customer Name],MB.Name [Beat Name],SM.Name [Salesman Name] from tblmastercustomer MC    
LEFT join tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID    
LEFT JOIN tblMasterBeat MB ON MB.ID = BSM.BeatID    
LEFT JOIN tblMasterSalesman SM ON SM.ID = BSM.SalesmanID    
WHERE mc.id =  @CustomerID ''    
SET @strQuery += CASE WHEN ISNULL(@BeatName,'''') = '''' THEN '''' ELSE '' AND MB.Name = ''+'' @BeatName '' END            
SET @strQuery += CASE WHEN ISNULL(@SalesmanName,'''') = '''' THEN '''' ELSE '' AND SM.Name = ''+'' @SalesmanName '' END      
EXEC sys.sp_executesql @strQuery, N''@CustomerID int, @CustomerType nvarchar(255), @Ratings nvarchar(255), @BeatName nvarchar(255), @SalesmanName nvarchar(255), @Location nvarchar(255)'', @CustomerID, @CustomerType, @Ratings, @BeatName, @SalesmanName, @Location    
end',
N'[06] nocount';
GO
/****** uspCustomerHeaderReportHeader ******/
EXEC #Apply07 N'dbo.uspCustomerHeaderReportHeader', 0xE71F31FC28F75C0B2DCD1B8552F72F1AD29543696752E9DF1750BC2D51BD7430, 0x78314BB06481BF64F7B0E98AF08C5B0532F63C7D09D70C134DCD2FED359FBE8A, NULL, 0xF4B38CD8E10279B3DCE2ADDE127274F2D45D4F5C0A44673DA8B1721717A61676, 0xE485B4AD3858B9F261B507402A1F0F3D19D7A4789F85FEF4B6479C4C4EACA3AA, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspCustomerHeaderReportHeader]    
 @CustomerType nvarchar(255) = '''',@Ratings  nvarchar(255) = '''',@BeatName  nvarchar(255) = '''',@SalesmanName  nvarchar(255) = '''',
 @Location INT = 1
 as    
 SET NOCOUNT ON;
begin    
DECLARE @strQuery NVARCHAR(MAX) = ''''       
 select MC.ID,MC.Code [Customer Code],MC.Name [Customer Name],MCT.Name [Customer Type],MCT.ID [Customer ID] ,MC.Billadd1   AS [Bill Add 1],MC.Billadd2   AS [Bill Add 2],    
MC.Billadd3   AS [Bill Add 3],MC.Shipadd1   AS [Ship Add 1],MC.Shipadd2   AS [Ship Add 2],MC.Shipadd3   AS [Ship Add 3],    
    MC.Pincode,    
    MC.ContactPerson AS [Contact Person],    
    MC.Ph1        AS [Phone  1],    
    MC.Ph2        AS [Phone 2],    
    MC.Mob1       AS [Mobile 1],    
    MC.Mob2       AS [Mobile 2],    
    MC.Email,    
    MC.PANNumber  AS [PAN No],    
    MC.AadharNo   AS [Aadhar No],    
    MC.DLNo20     AS [DL No 20],    
    MC.DLNo21     AS [DL No 21],    
    MC.FSSAINo    AS [FSSAI No],    
    GST.StateName [State Name],    
    MC.GSTIN,    
    PM.PaymentMode [Payment Mode],      
    CT.Name [Credit Term],      
    PT.PriceType       AS [Price Type],    
    MTT.TaxTypeName [Tax Type],      
    MC.OverDueInvCount   AS [OverDue Inv Count],    
    dbo.fngetroundedvalue(MC.CreditLimitValue)  AS [Credit Limit Value],    
    MC.CreditLimitCount  AS [Credit Limit Count],    
    dbo.fngetroundedvalue(MC.CreditlimitOS)     AS [Credit Limit OS],        
    MC.OwnerName         AS [Owner Name],    
    dbo.fngetroundedvalue(MC.DiscountPern)      AS [Discount %],    
    case when MC.TrackPoint = 1 then ''Yes'' ELSE ''No'' end AS [Track Point],    
    dbo.fngetroundedvalue(MC.ClosingTrackPoint) AS [Closing Track Point],    
    case when MC.TCSTax = 1 then ''Yes'' ELSE ''No'' end AS [TCS Tax],    
    MC.Distance,    
    MC.Remark,    
    RT.RatingName Ratings,  
    RT.ID RatingsID,  
     CASE WHEN (MC.Latitude IS NOT NULL AND MC.Latitude != '''') AND (MC.Longtitude IS NOT NULL AND MC.Longtitude != '''') THEN ''Yes'' ELSE ''No'' END AS Location,
 CASE WHEN IMG.Filename IS NOT NULL THEN ''Yes'' ELSE ''No'' END AS Images,
    case when MC.Active = 1 then ''Yes'' ELSE ''No'' end Active,        
 MU.UserName [Created By],CONVERT(NVARCHAR,MC.CDate) [Create Date],        
 MUM.UserName [Modify By],CONVERT(NVARCHAR,MC.MDate) [Modify Date],MB.Name BeatName,MB.ID [BeatID],SM.Name SalesmanName,SM.ID [SalesmanID] ,MC.FAID
    INTO #TEMP
    from tblmastercustomer MC    
LEFT JOIN tblGSTStateNameandCode GST ON GST.StateID = MC.StateID      
left join tblMasterCustomertype MCT ON MCT.ID = MC.Customertype    
LEFT JOIN tblMasterCreditTerm CT ON CT.ID = MC.CreditTermID      
LEFT JOIN tblPaymentMode PM ON PM.ID = MC.PaymentModeID      
JOIN tblMasterTaxType MTT ON MTT.TaxTypeID = MC.TaxTypeID      
join tblPriceType PT ON PT.ID = MC.PriceTypeID    
LEFT JOIN tblRatings RT ON RT.ID = MC.Rating      
JOIN tblUsers MU ON MU.ID = MC.CBy              
LEFT JOIN tblUsers MUM ON MUM.ID = MC.MBy     
LEFT join tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID    
LEFT JOIN tblMasterBeat MB ON MB.ID = BSM.BeatID    
LEFT JOIN tblMasterSalesman SM ON SM.ID = BSM.SalesmanID
left join tblImages IMG ON IMG.ID = MC.ID AND IMG.FormID = 2
    
SET @strQuery = ''SELECT DISTINCT [ID],    
[Customer Code],    
[Customer Name],    
[Customer Type],    
[Bill Add 1],    
[Bill Add 2],    
[Bill Add 3],    
[Ship Add 1],    
[Ship Add 2],    
[Ship Add 3],    
[Pincode],    
[Contact Person],    
[Phone  1],    
[Phone 2],    
[Mobile 1],    
[Mobile 2],    
[Email],    
[PAN No],    
[Aadhar No],    
[DL No 20],    
[DL No 21],    
[FSSAI No],    
[State Name],    
[GSTIN],    
[Payment Mode],    
[Credit Term],    
[Price Type],    
[Tax Type],    
[OverDue Inv Count],    
[Credit Limit Value],    
[Credit Limit Count],    
[Credit Limit OS],    
[Owner Name],    
[Discount %],    
[Track Point],    
[Closing Track Point],    
[TCS Tax],    
[Distance],    
[Remark],    
[Ratings],    
[dbo].[fnGetRoundedValue]((dbo.fnGetClosingBal(FAID))) [OutStanding Value],
[Location],
[Images],
[Active],    
[Created By],    
[Create Date],    
[Modify By],    
[Modify Date] FROM #TEMP WHERE ID > 0 ''    
--SET @strQuery += CASE WHEN ISNULL(@CustomerType,'''') = '''' THEN '''' ELSE '' AND [Customer Type] = ''+'' @CustomerType '' END            
--SET @strQuery += CASE WHEN ISNULL(@Ratings,'''') = '''' THEN '''' ELSE '' AND Ratings = ''+'' @Ratings '' END         
--SET @strQuery += CASE WHEN ISNULL(@BeatName,'''') = '''' THEN '''' ELSE '' AND [BeatName] = ''+'' @BeatName '' END            
--SET @strQuery += CASE WHEN ISNULL(@SalesmanName,'''') = '''' THEN '''' ELSE '' AND SalesmanName = ''+'' @SalesmanName '' END      
SET @strQuery += CASE WHEN ISNULL(@CustomerType,'''') = '''' THEN '''' ELSE '' AND   
[Customer ID] IN (SELECT * from dbo.fnSplitString(''+'' @CustomerType ,'''',''''))'' END            
SET @strQuery += CASE WHEN ISNULL(@Ratings,'''') = '''' THEN '''' ELSE '' AND   
RatingsID IN (SELECT * from dbo.fnSplitString(''+'' @Ratings ,'''',''''))'' END         
SET @strQuery += CASE WHEN ISNULL(@BeatName,'''') = '''' THEN '''' ELSE '' AND   
[BeatID] IN (SELECT * from dbo.fnSplitString(''+'' @BeatName ,'''',''''))'' END            
SET @strQuery += CASE WHEN ISNULL(@SalesmanName,'''') = '''' THEN '''' ELSE '' AND   
SalesmanID IN (SELECT * from dbo.fnSplitString(''+'' @SalesmanName ,'''',''''))'' END   

-- Location Filter mapping (1 = All, 2 = Yes, 3 = No)
SET @strQuery += CASE 
    WHEN @Location = 2 THEN '' AND [Location] = ''''Yes''''''
    WHEN @Location = 3 THEN '' AND [Location] = ''''No''''''
    ELSE '''' 
END

SET @strQuery += '' ORDER BY [Customer Name] ''      
EXEC sys.sp_executesql @strQuery, N''@CustomerType nvarchar(255), @Ratings nvarchar(255), @BeatName nvarchar(255), @SalesmanName nvarchar(255), @Location INT'', @CustomerType, @Ratings, @BeatName, @SalesmanName, @Location     
DROP TABLE #TEMP    
end',
N'[06] nocount';
GO
/****** uspCustomerLocations ******/
EXEC #Apply07 N'dbo.uspCustomerLocations', 0xB3676DF4733C1FEED4C7CD44C139AE7CE1C4083DE43B91BA997071A97FFD5A19, NULL, NULL, 0xB824729863836A48D8726BDD689BE1909DA6E88C783A65EBD5F26A0E20B4D68A, 0xEF57F3F08A4ACEAD02D8D0DD9728DE833ED57F4D4F15849925688E399D3EC0C4, NULL,
N'--uspCustomerLocations 3  
ALTER PROC [dbo].[uspCustomerLocations]    
@Type smallint = 1,@BeatIds nvarchar(max)=null,@SalesmanIds nvarchar(max)=null,@CustomerIds nvarchar(max)=null,    
@MyLat  FLOAT = 12.949383,@MyLong FLOAT = 80.240709    
as    
SET NOCOUNT ON;
begin    
DECLARE @MyLocation GEOGRAPHY =    
    geography::Point(@MyLat, @MyLong, 4326);    
    IF(@Type = 2)    
    BEGIN    
SELECT ID,Code,Name,Mob1,Latitude,Longtitude,    
    CASE    
        WHEN DistanceMeters > 1000    
            THEN CONCAT(CAST(DistanceMeters / 1000.0 AS DECIMAL(10, 2)), '' KM'')    
        ELSE    
            CONCAT(CAST(DistanceMeters AS DECIMAL(10, 0)), '' Meters'')    
    END AS Distance,Imagedata,ISNULL(Balance,0) Balance,InvCount,ISNULL(Aging,0) Aging    
FROM    
(    
    SELECT MC.ID,Code,Name,Mob1,Latitude,Longtitude,    
@MyLocation.STDistance(geography::Point(TRY_CONVERT(FLOAT, Latitude),TRY_CONVERT(FLOAT, Longtitude),4326)) AS DistanceMeters,    
IMG.Imagedata,SUM(Balance) Balance,count(SH.ID) InvCount,DATEDIFF(DD,MIN(InvDate),GETDATE()) Aging    
    FROM tblmastercustomer MC    
    LEFT JOIN tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID    
    LEFT JOIN tblTranSalesHeader SH ON SH.CustID = MC.ID     
    AND SH.Status in (1,3,5) and DocPrefix = 15 and balance > 0    
    LEFT JOIN tblImages IMG ON IMG.ID = MC.ID AND IMG.FormID = 2    
    WHERE (Latitude IS NOT NULL AND Longtitude IS NOT NULL) AND    
    (ISNULL(@BeatIds,''0'') = ''0'' OR BSM.BeatID IN (SELECT * FROM string_split(@BeatIds,'',''))) AND    
    (ISNULL(@SalesmanIds,''0'') = ''0'' OR BSM.SalesmanID IN (SELECT * FROM string_split(@SalesmanIds,'',''))) AND    
    (ISNULL(@CustomerIds,'''') = '''' OR MC.ID IN (SELECT * FROM string_split(@CustomerIds,'','')))    
      GROUP BY MC.ID,Code,Name,Mob1,Latitude,Longtitude,IMG.Imagedata    
) C    
GROUP BY ID,Code,Name,Mob1,Latitude,Longtitude,DistanceMeters,Imagedata,Balance,InvCount,Aging    
ORDER BY DistanceMeters;    
END    
ELSE IF(@Type = 1)    
BEGIN    
SELECT ID,Code,Name,Mob1,Latitude,Longtitude,    
    CASE    
        WHEN DistanceMeters > 1000    
            THEN CONCAT(CAST(DistanceMeters / 1000.0 AS DECIMAL(10, 2)), '' KM'')    
        ELSE    
            CONCAT(CAST(DistanceMeters AS DECIMAL(10, 0)), '' Meters'')    
    END AS Distance,Imagedata,ISNULL(Balance,0) Balance,InvCount,ISNULL(Aging,0) Aging    
FROM    
(    
select MC.ID,Code,Name,Mob1,Latitude,Longtitude,    
@MyLocation.STDistance(geography::Point(TRY_CONVERT(FLOAT, Latitude),TRY_CONVERT(FLOAT, Longtitude),4326)) AS DistanceMeters,    
IMG.Imagedata,SUM(Balance) Balance,count(SH.ID) InvCount,    
DATEDIFF(DD,MIN(InvDate),GETDATE()) Aging from tblAssignInvoicesHeader AH                      
JOIN tblAssignInvoicesDetail AD ON AD.HID = AH.ID                      
JOIN tblTransalesHeader SH ON SH.ID = AD.InvID                      
join tblmasterCustomer MC ON MC.ID = SH.CustID    
LEFT JOIN tblImages IMG ON IMG.ID = MC.ID AND IMG.FormID = 2    
where (Latitude IS NOT NULL AND Longtitude IS NOT NULL) AND 
AH.SalesmanID IN (SELECT * FROM string_split(@SalesmanIds,'','')) AND AH.Status in (1,3) and AD.Status IN (1,6)                       
AND SH.DocPrefix = 15 AND SH.Status IN (1,3,5) AND SH.Balance > 0 AND
 (ISNULL(@CustomerIds,'''') = '''' OR MC.ID IN (SELECT * FROM string_split(@CustomerIds,'','')))
 --AND (ISNULL(@BeatIds,''0'') = ''0'' OR SH.BeatID IN (SELECT * FROM string_split(@BeatIds,'','')))    
GROUP BY MC.ID,Code,Name,Mob1,Latitude,Longtitude,IMG.Imagedata  
) C    
GROUP BY ID,Code,Name,Mob1,Latitude,Longtitude,DistanceMeters,Imagedata,Balance,InvCount,Aging    
ORDER BY DistanceMeters;    
END    
ELSE IF(@Type = 3)    
BEGIN    
SELECT ID,Code,Name,Mob1,Latitude,Longtitude,    
    CASE    
        WHEN DistanceMeters > 1000    
            THEN CONCAT(CAST(DistanceMeters / 1000.0 AS DECIMAL(10, 2)), '' KM'')    
        ELSE    
            CONCAT(CAST(DistanceMeters AS DECIMAL(10, 0)), '' Meters'')    
    END AS Distance,Imagedata,ISNULL(Balance,0) Balance,InvCount,ISNULL(Aging,0) Aging    
FROM    
(    
select MC.ID,Code,Name,Mob1,MC.Latitude,MC.Longtitude,    
@MyLocation.STDistance(geography::Point(TRY_CONVERT(FLOAT, MC.Latitude),TRY_CONVERT(FLOAT, MC.Longtitude),4326)) AS DistanceMeters,    
IMG.Imagedata,SUM(Balance) Balance,count(SH.ID) InvCount,    
DATEDIFF(DD,MIN(InvDate),GETDATE()) Aging from tblDeliveryOrderHeader AH                      
JOIN tblDeliveryOrderDetail AD ON AD.DOID = AH.ID                      
JOIN tblTransalesHeader SH ON SH.ID = AD.InvIdentID                      
join tblmasterCustomer MC ON MC.ID = SH.CustID    
LEFT JOIN tblImages IMG ON IMG.ID = MC.ID AND IMG.FormID = 2    
where (MC.Latitude IS NOT NULL AND MC.Longtitude IS NOT NULL) AND AH.SalesmanID IN (SELECT * FROM string_split(@SalesmanIds,'','')) AND AH.Status in (1,3) and AD.Status IN (1,6)                       
AND AH.Status IN (1,3,5) AND
 (ISNULL(@CustomerIds,'''') = '''' OR MC.ID IN (SELECT * FROM string_split(@CustomerIds,'',''))) 
 --AND (ISNULL(@BeatIds,''0'') = ''0'' OR SH.BeatID IN (SELECT * FROM string_split(@BeatIds,'','')))  
GROUP BY MC.ID,Code,Name,Mob1,MC.Latitude,MC.Longtitude,IMG.Imagedata  
) C    
GROUP BY ID,Code,Name,Mob1,Latitude,Longtitude,DistanceMeters,Imagedata,Balance,InvCount,Aging    
ORDER BY DistanceMeters;    
END    
end',
N'[export] nocount';
GO
/****** uspDateWiseSaleReport ******/
EXEC #Apply07 N'dbo.uspDateWiseSaleReport', 0x993F4C5302F612B826AF5A53F65E324B086078E388F1CD2E3B7C903471BF18B4, 0xE15D769537A23370E0533222FAD6286380E47224D08C377D6B45728F5DE7FDE3, NULL, 0xACF64A46A0BBD1061DCC304A294D386A39B4C69948BCACCBF2B98394AE7DAE40, 0x0BA44945285288E5DDC0FF24496374BFBD185454A258FE6832BAC4FD070A86CD, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspDateWiseSaleReport]      
@BranchName NVARCHAR(255) = ''0'',@BeatName NVARCHAR(255) = '''',@SalesmanName NVARCHAR(255) = '''',@CustomerName NVARCHAR(255) = '''',@CustomerType NVARCHAR(255) = '''',    
@Ratings NVARCHAR(255) = '''',@FromDate DATE = ''2025-04-01'',@ToDate DATE = ''2025-08-30''          
AS    
SET NOCOUNT ON;
BEGIN    
SET DATEFORMAT dmy;        
declare @StrQuery nvarchar(max) = ''''      
 set @StrQuery = ''     
SELECT [Invoice Date] Date,                
FORMAT([Invoice Date],''''dd-MMM-yyyy'''') AS [Invoice Date],                
dbo.fnGetRoundedValue(SUM(iyan.[Total Sales])) AS [Total Sales Amount],                
dbo.fnGetRoundedValue(SUM(iyan.[Salable Return])) AS [Total Saleable Return],                
dbo.fnGetRoundedValue(SUM(iyan.[Damage Return])) AS [Total Damage Return],                
dbo.fnGetRoundedValue((SUM(iyan.[Total Sales]))-(SUM(iyan.[Salable Return]) + SUM(iyan.[Damage Return]))) AS [Net Effect Value],                
dbo.fnGetRoundedValue(sum(iyan.[Total Product Disc Amt])) AS  [Total Product Disc Amt],                
dbo.fnGetRoundedValue(sum(iyan.[Total Trade Disc Amt])) AS [Total Trade Disc Amt],                
dbo.fnGetRoundedValue(sum(iyan.[Additional Disc Amt])) AS [Additional Disc Amt]    
FROM (                
SELECT TSH.ID,TSH.InvDate AS [Invoice Date],                
CASE WHEN TransactionType IN (1,4,5,6) THEN (ISNULL(TSH.NetAmt,0)) ELSE ISNULL(0.00,0) END AS [Total Sales] ,                
CASE WHEN TransactionType=2 THEN (ISNULL(TSH.NetAmt,0)) ELSE ISNULL(0.00,0) END AS [Salable Return],                
CASE WHEN TransactionType=3 THEN (ISNULL(TSH.NetAmt,0)) ELSE ISNULL(0.00,0) END AS [Damage Return],                
(CASE WHEN DocPrefix=15 THEN SUM(ISNULL(TSH.TotalProdDiscAmt,0)) ELSE -1 * SUM(ISNULL(TSH.TotalProdDiscAmt,0)) END )as [Total Product Disc Amt],                
(CASE WHEN DocPrefix=15 THEN SUM(ISNULL(TSH.TotalTradeDiscAmt,0)) ELSE -1 * SUM(ISNULL(TSH.TotalTradeDiscAmt,0)) END) as [Total Trade Disc Amt],                
(CASE WHEN DocPrefix=15 THEN SUM(ISNULL(TSH.AdditionalDiscAmt,0)) ELSE -1* SUM(ISNULL(TSH.AdditionalDiscAmt,0)) END) as [Additional Disc Amt]    
FROM [tblTranSalesHeader] AS TSH          
JOIN tblMasterCustomer MC ON MC.ID= TSH.CustID    
LEFT JOIN tblMasterBeat AS Beat ON Beat.ID = TSH.BeatID          
LEFT JOIN tblMasterSalesMan AS SM ON SM.ID = TSH.SalesManId          
LEFT JOIN tblMasterCustomerType AS MCT ON MCT.ID = MC.CustomerType     
LEFT JOIN tblRatings AS RT ON RT.ID = MC.Rating    
WHERE TransactionType IN(1,2,3,4,5,6) AND TSH.Status IN (1,3,5,6,7) ''    
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)                  
  
    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BranchName,''0'')=''0'' THEN '''' ELSE '' AND TSH.BranchID =  @BranchName '' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND Beat.ID IN (SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)           
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND SM.ID IN (SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND MC.ID IN (SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND MCT.ID IN (SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RT.ID IN (SELECT * from dbo.fnSplitString(  @Ratings ,'''',''''))'' END)     
SET @StrQuery = @StrQuery + ''    
GROUP BY TSH.InvDate, TransactionType,TSH.ID,TSH.NetAmt,DocPrefix          
) AS iyan  GROUP BY  iyan.[Invoice Date] ORDER BY CONVERT(DATE,[Invoice Date])  ''    
EXEC sys.sp_executesql @StrQuery, N''@BranchName NVARCHAR(255), @BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BranchName, @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @FromDate, @ToDate    
END',
N'[06] nocount';
GO
/****** uspDebitNoteforPrint ******/
EXEC #Apply07 N'dbo.uspDebitNoteforPrint', 0xEBC451D99E9478AD0AE15692FEF8AE6F8AB3FD5720A14942587D2C0A46B582D3, NULL, NULL, 0x2770E8E62A5523C6E4C45B76B70E14ECE95D1D811A2B8C51D00C00E3AD1A08E7, 0xFB57352FEA1D56DD99B8436379D5A55B3B3A99FEEE5D4569A5A29054A5EDB43D, NULL,
N'ALTER PROC [dbo].[uspDebitNoteforPrint]               
@DocValue INT  = null                   
as                  
SET NOCOUNT ON;
Declare @AccGrpid int               
Select  @AccGrpid = Faa.AccountGroup from dbo.tblNoteDetails  as note Join dbo.tblFAAccount as Faa on Faa.FAID = note.PartyId                 
Where note.ID = @DocValue AND TransID = 5                
              
if(@AccGrpid = 35) -- customer              
BEGIN  
Select Note.ID as [Debit Note ID],Note.DocId as [Doc ID],Note.UDFDocId [UDN Doc ID],Convert (nvarchar ,Note.DocDate,103) as [Doc Date],  
Isnull(CONVERT(nvarchar(5),Note.MDate,108),CONVERT(nvarchar(5),Note.CDate,108)) as [Time],Doc.TransName as [Trans Name],  
Note.RefNo as [Doc Ref],FAParty.AccountName as [Party Name],FAAC.AccountName as [Account Name],Note.NoteValue as [Note Value],MBO.Name [Branch Name], 
Note.Remark as [Remark],Note.Narration as [Narration],Customer.Ph1 AS [Party Prim Phone No],Customer.Mob1 as [Party Prim Mobile No],  
Customer.Billadd1  AS [Party Bill Address 1],Customer.Billadd2 as [Party Bill Address 2],Customer.Billadd3 as [Party Bill Address 3],      
Customer.GSTIN [Party GSTIN],Customer.AadharNo AS [Party Aadhar Number],Customer.PANNumber AS [Party PAN No],      
Note.Balance as [Balance],           
dbo.fnConvertAmountinWords(Note.Balance) AS [Amt_in_Words],            
UserTab.username as [User Name]                
from dbo.tblNoteDetails as Note                  
join dbo.tblDocumentSeries AS Doc ON Note. TransID = Doc.TransID                    
Join dbo.tblFAAccount as FAParty on FAParty.FAID = Note.PartyId                  
Join dbo.tblFAAccount as FAAC on FAAC.FAID = Note.FAID
LEFT JOIN tblMasterBranchOffice MBO on  MBO.ID = Note.BranchID
Join dbo.tblMasterCustomer as Customer on Customer.FAID = FAParty.FAID              
Join dbo.tblUsers as UserTab on UserTab.ID = Note.MBy or UserTab.ID  =  Note.Cby                  
where  note.ID = @DocValue  AND Note .TransID = 5              
END              
else if(@AccGrpid = 43) -- Vendor              
BEGIN              
Select Note.ID as [Debit Note ID],Note.DocId as [Doc ID],Note.UDFDocId [UDN Doc ID],Convert (nvarchar ,Note.DocDate,103) as [Doc Date],  
Isnull(CONVERT(nvarchar(5),Note.MDate,108),CONVERT(nvarchar(5),Note.CDate,108)) as [Time],Doc.TransName as [Trans Name],  
Note.RefNo as [Doc Ref],FAParty.AccountName as [Party Name],FAAC.AccountName as [Account Name],Note.NoteValue as [Note Value],MBO.Name [Branch Name],  
Note.Remark as [Remark],Note.Narration as [Narration],Vendor.Ph1 AS [Party Prim Phone No],Vendor.Mob1 as [Party Prim Mobile No],  
Vendor.Billadd1  AS [Party Bill Address 1],Vendor.Billadd2 as [Party Bill Address 2],Vendor.Billadd3 as [Party Bill Address 3],        
Vendor.GSTIN [Party GSTIN],Vendor.AadharNo AS [Party Aadhar Number],Vendor.PANNumber AS [Party PAN No],  
Note.Balance as [Balance],dbo.fnConvertAmountinWords(Note.Balance) AS [Amt_in_Words],UserTab.username as [User Name]  
from dbo.tblNoteDetails as Note                  
join dbo.tblDocumentSeries AS Doc ON Note. TransID = Doc.TransID                    
Join dbo.tblFAAccount as FAParty on FAParty.FAID = Note.PartyId                  
Join dbo.tblFAAccount as FAAC on FAAC.FAID = Note.FAID 
LEFT JOIN tblMasterBranchOffice MBO on  MBO.ID = Note.BranchID
Join dbo.tblMasterVendor as Vendor on Vendor.FAID = FAParty.FAID              
Join dbo.tblUsers as UserTab on UserTab.ID = Note.MBy or UserTab.ID  =  Note.Cby                  
where  note.ID = @DocValue  AND Note .TransID = 5              
END              
else if(@AccGrpid = 33) -- SalesMan              
BEGIN              
Select Note.ID as [Debit Note ID],Note.DocId as [Doc ID],Note.UDFDocId [UDN Doc ID],Convert (nvarchar ,Note.DocDate,103) as [Doc Date],  
Isnull(CONVERT(nvarchar(5),Note.MDate,108),CONVERT(nvarchar(5),Note.CDate,108)) as [Time],Doc.TransName as [Trans Name],            
Note.RefNo as [Doc Ref],FAParty.AccountName as [Party Name],FAAC.AccountName as [Account Name],Note.NoteValue as [Note Value],MBO.Name [Branch Name],  
Note.Remark as [Remark],Note.Narration as [Narration],  
'''' AS [Party Prim Landline No],SalesMan.MobileNo as [Party Prim Mobile No],  
SalesMan.Address  AS [Party Bill Address 1],'''' as [Party Bill Address 2],'''' as [Party Bill Address 3],  
'''' [Party GSTIN],SalesMan.AadharNo AS [Party Aadhar Number],SalesMan.PANNumber AS [Party PAN No],  
Note.Balance as [Balance],  
dbo.fnConvertAmountinWords(Note.Balance) as [Amt_in_Words],  
UserTab.username as [User Name]  
from dbo.tblNoteDetails as Note                  
join dbo.tblDocumentSeries AS Doc ON Note. TransID = Doc.TransID                    
Join dbo.tblFAAccount as FAParty on FAParty.FAID = Note.PartyId                  
Join dbo.tblFAAccount as FAAC on FAAC.FAID = Note.FAID
LEFT JOIN tblMasterBranchOffice MBO on  MBO.ID = Note.BranchID
Join dbo.tblMasterSalesMan as SalesMan on SalesMan.FAID = FAParty.FAID              
Join dbo.tblUsers as UserTab on UserTab.ID = Note.MBy or UserTab.ID  =  Note.Cby                  
where  note.ID = @DocValue  AND Note .TransID = 5              
END              
else               
BEGIN              
Select Note.ID as [Debit Note ID],Note.DocId as [Doc ID],Note.UDFDocId [UDN Doc ID],Convert (nvarchar ,Note.DocDate,103) as [Doc Date],  
Isnull(CONVERT(nvarchar(5),Note.MDate,108),CONVERT(nvarchar(5),Note.CDate,108)) as [Time],Doc.TransName as [Trans Name],  
Note.RefNo as [Doc Ref],FAParty.AccountName as [Party Name],FAAC.AccountName as [Account Name],Note.NoteValue as [Note Value],MBO.Name [Branch Name],  
Note.Remark as [Remark],Note.Narration as [Narration],'''' AS [Party Prim Phone No],'''' as [Party Prim Mobile No],'''' AS [Party Bill Address 1],'''' as [Party Bill Address 2],'''' as [Party Bill Address 3],  
'''' [Party GSTIN],'''' AS [Party Aadhar Number],'''' AS [Party PAN No],Note.Balance as [Balance],  
dbo.fnConvertAmountinWords(Note.NoteValue) AS [Amt_in_Words],UserTab.username as [User Name]  
from dbo.tblNoteDetails as Note  
join dbo.tblDocumentSeries AS Doc ON Note. TransID = Doc.TransID  
Join dbo.tblFAAccount as FAParty on FAParty.FAID = Note.PartyId  
Join dbo.tblFAAccount as FAAC on FAAC.FAID = Note.FAID
LEFT JOIN tblMasterBranchOffice MBO on  MBO.ID = Note.BranchID
Join dbo.tblUsers as UserTab on UserTab.ID = Note.MBy or UserTab.ID  =  Note.Cby  
where  note.ID = @DocValue  AND Note .TransID = 5  
END',
N'[export] nocount';
GO
/****** uspDeliveryPrintDetail ******/
EXEC #Apply07 N'dbo.uspDeliveryPrintDetail', 0x130449C1EEFD3A3F91541D34242F0DBDD909575D5F931B18A15FE776261775AA, NULL, NULL, 0xE76E971D0F58C61293EF55DC1E901772B3E5FF7EC4FBA2E948D0F2B75BFF8E22, 0x70A31E079E37FE6C8103AA677F26575741C11E9BF2D08B68204A0A3DA3E08445, NULL,
N'ALTER proc [dbo].[uspDeliveryPrintDetail]
@DeliveryID int = 2
AS
SET NOCOUNT ON;
BEGIN
SELECT ROW_NUMBER() over(order by SH.DocID) SNo, SH.DocID [Invoice No],format(SH.InvDate,''dd/MM/yyyy'') [Invoice Date],MC.Name [Customer Name],STS.Description [Delivery Status],
ReceiverName [Receiver Name],
DVURS.UserName [Delivery By],format(DD.DelivTime,''dd/MM/yyyy hh:mm tt'') [Delivery Date],RTNURS.UserName [Return By],
format(DD.Rtndate,''dd/MM/yyyy hh:mm tt'') [Return Date],
CANURS.UserName [Cancel By],format(DD.CancelDate,''dd/MM/yyyy hh:mm tt'') [Cancel Date]
FROM tblDeliveryOrderDetail DD
JOIN tblTranSalesHeader SH ON SH.ID = DD.InvIdentID
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID
JOIN tblStatus STS ON STS.ID = DD.Status
LEFT JOIN tblUsers RTNURS ON RTNURS.ID = DD.RtnBy
LEFT JOIN tblUsers DVURS ON DVURS.ID = DD.DelivBy
LEFT JOIN tblUsers CANURS ON CANURS.ID = DD.CancelBy
WHERE DD.DOID = @DeliveryID
ORDER BY SNo
END',
N'[export] nocount';
GO
/****** uspDeliveryPrintHeader ******/
EXEC #Apply07 N'dbo.uspDeliveryPrintHeader', 0x675139017F4C3283ABE828D6D9DC81E6D8D48E49E13B5B10C0556C89608BB638, NULL, NULL, 0x9D33C0C35C938E0C721C6EBB3ABE5308609452A2396FBEDF2BFE0FA0D984434F, 0x1210B05C633021301471F77BC8488B52FCC7D8DA943267FCE4AA300FCB7216F8, NULL,
N'ALTER PROC [dbo].[uspDeliveryPrintHeader]
@DeliveryID int = 2
AS
SET NOCOUNT ON;
BEGIN
select DocID [Doc ID],format(DocDate,''dd/MM/yyyy'') [Doc Date],MBO.Name [Branch Name],SM.Name [Salesman Name],VH.VehicleNo [Vehicle No],
STS.Description Status,RefNo [Ref No],Remarks,Narration,ur.UserName [Create User],format(DH.CDate,''dd/MM/yyyy hh:mm tt'') [Create Time],
COUNT(DD.InvIdentID) [Total Invoices]
from tblDeliveryOrderHeader DH
join tblDeliveryOrderDetail DD ON DD.DOID = DH.ID
JOIN tblMasterBranchOffice MBO ON MBO.ID = DH.BranchID
JOIN tblMasterSalesman SM ON SM.ID = DH.SalesmanID
JOIN tblMasterVehicle VH ON VH.ID = DH.VehicleID
JOIN tblUsers UR ON UR.ID = DH.CBy
JOIN tblStatus STS ON STS.ID = DH.Status
where DH.ID = @DeliveryID
GROUP BY 
    DocID,
    DocDate,
    MBO.Name,
    SM.Name,
    VH.VehicleNo,
    STS.Description,
    RefNo,
    Remarks,
    Narration,
    UR.UserName,
    DH.CDate
END',
N'[export] nocount';
GO
/****** uspDiscountSchemeInfo ******/
EXEC #Apply07 N'dbo.uspDiscountSchemeInfo', 0x1548870243924D2303DFD7C63FCC297C13FB37A945E5358E9E27646DBE41BDEA, NULL, NULL, 0x6F394CFB8E23E18702FB8ACA42F3BD5B95AC32BE77CE13EBF604D0693201D7C0, 0xFA1AB71DC02CB2D98239C337D08A200474B73AD72B2F4EDF837B7DB9B3A82177, NULL,
N'--uspDiscountSchemeInfo ''2026-08-14'',258  
ALTER proc [dbo].[uspDiscountSchemeInfo]     
@DocDate DATE = ''2026-04-16'',@CustID INT=459    
as    
SET NOCOUNT ON;
begin    
select DSH.ID SchemeID,Name [Scheme Name],format(FromDate,''dd-MMM-yyyy'') [From Date],format(ToDate,''dd-MMM-yyyy'') [To Date],  
