/****** uspExportIRNData ******/
EXEC #Apply07 N'dbo.uspExportIRNData', 0x861C9BB6A3FD537FDC372E0167F185ED40CC306AEC99D4443F1BD2DF6171D7C8, 0x8A872A98E55C0B9E84BD40AC27101FED7EAD1840957271428BCE9BEB51D3FD0E, NULL, 0xFE8C23028C771F8851BA7DBE4310FA63D7616027F8F9C63EA0BC5DC44AFB0B47, 0x85A045AD670EFAD9C731677BFC81F93E50CF5D8F968A344ECCECC0E49153FD76, NULL,
N'--uspExportIRNData 1,''2025-01-01'',''2025-08-01'',NULL  
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspExportIRNData]  
@SheetMode INT,@FromDate date = ''2025-01-01'',@ToDate DATE= ''2025-08-01'',@DocIDs NVARCHAR(MAX)=NULL  
AS  
SET NOCOUNT ON;
BEGIN  
DECLARE @QRY NVARCHAR(MAX)  
IF(@SheetMode = 1)  
BEGIN  
--declare @FromDate DATE = ''2023-05-12'',@ToDate DATE = ''2023-05-13''  
SELECT TransID,TransIdentID,(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],  
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],  
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],  
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],  
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],  
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],  
SUM([GCESS Amount] + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #TaxHeaer  
FROM  
(  
SELECT SRI.TransID,SRI.TransIdentID,  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],  
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],  
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],  
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],  
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],  
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],  
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],  
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],  
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]  
FROM  
(  
SELECT * FROM  
(  
SELECT Temp.TransID,Temp.TransIdentID,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],  
Temp.TaxName AS TaxName,  
SUM(Temp.TaxValue) AS [TaxValue]  
FROM  
(  
SELECT GSTInfo.TransID,GSTInfo.TransIdentID,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,  
CASE  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''  
END AS [GST Comp]  
FROM tblTransGSTInfo AS GSTInfo  
JOIN tblTranSalesHeader SH ON SH.ID = GSTInfo.TransIdentID AND SH.DocPrefix = GSTInfo.TransID  
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID  
WHERE (TransID=15 or TransID=16) AND Status IN (1,3,5,6,7) AND InvDate BETWEEN @FromDate AND @ToDate  
) Temp  
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.TransID,Temp.TransIdentID  
) src  
PIVOT  
(  
SUM([TaxValue])  
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])  
) piv  
) AS SRI  
) AS RAM  
GROUP BY TransID,TransIdentID  
--SELECT * FROM #Tax  
-- PR  
SELECT TransID,TransIdentID,(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],  
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],  
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],  
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],  
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],  
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],  
SUM([GCESS Amount] + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #TaxPRHeaer  
FROM  
(  
SELECT SRI.TransID,SRI.TransIdentID,  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],  
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],  
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],  
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],  
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],  
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],  
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],  
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],  
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]  
FROM  
(  
SELECT * FROM  
(  
SELECT Temp.TransID,Temp.TransIdentID,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],  
Temp.TaxName AS TaxName,  
SUM(Temp.TaxValue) AS [TaxValue]  
FROM  
(  
SELECT GSTInfo.TransID,GSTInfo.TransIdentID,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,  
CASE  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''  
END AS [GST Comp]  
FROM tblTransGSTInfo AS GSTInfo  
JOIN tblTransPurchaseHeader SH ON SH.ID = GSTInfo.TransIdentID AND SH.TransID = GSTInfo.TransID  
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID  
WHERE (SH.TransID=1) AND Status IN (1,3,5,6,7) AND Date BETWEEN @FromDate AND @ToDate  
) Temp  
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.TransID,Temp.TransIdentID  
) src  
PIVOT  
(  
SUM([TaxValue])  
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])  
) piv  
) AS SRI  
) AS RAM  
GROUP BY TransID,TransIdentID  
SELECT * INTO #MainTaxHeaer FROM (  
SELECT * FROM #TaxHeaer  
UNION ALL  
SELECT * FROM #TaxPRHeaer) AS REC  
--select * from #MainTax  
  
SET @QRY = ''SELECT [Supply Type Code *],[Reverse Charge],[e-Comm GSTIN],[Igst On Intra],[Document Type *],[Document Number *],[Document Date (DD/MM/YYYY) *],  
[Buyer GSTIN *],[Buyer Legal Name *],[Buyer Trade Name ],[Buyer POS *],[Buyer Addr1 *],[Buyer Addr2],[Buyer Location *],  
[Buyer Pin Code],[Buyer State *],[Buyer Phone Number],[Buyer Email Id],[Dispatch Name ],[Dispatch Addr1 ],[Dispatch Addr2],  
[Dispatch Location ],[Dispatch Pin Code ],[Dispatch State ],[Shipping GSTIN ],[Shipping Legal Name ],[Shipping Trade Name ],  
[Shipping Addr1 ],[Shipping Addr2],[Shipping Location ],[Shipping Pin Code ],[Shipping State ],[Total Taxable value *],  
[Sgst Amt],[Cgst Amt],[Igst Amt],[Cess Amt],[State Cess Amt],[Discount],[Other charges],[Round off],[Total Invoice value *],  
[Shipping Bill No],[Shipping Bill Dt],[Port],[Refund claim],[Foreign Currency ],[Country Code ],[Export Duty Amount],  
[Trans ID],[Trans Name],[Trans Mode ],[Distance ],[Trans Doc No.] [Trans Doc No],[Trans Doc Date],[Vehicle No.] [Vehicle No],[Vehicle Type],[Error List] FROM (''  
SET @QRY += ''SELECT SH.DocPrefix,SH.InvDate,''''B2B'''' [Supply Type Code *],'''''''' [Reverse Charge],'''''''' [e-Comm GSTIN],'''''''' [Igst On Intra],  
CASE WHEN SH.DocPrefix = 15 THEN ''''Tax Invoice'''' ELSE ''''Credit Note'''' END [Document Type *],SH.DocId [Document Number *],  
CONVERT(NVARCHAR,SH.InvDate,103) [Document Date (DD/MM/YYYY) *],UPPER(MC.GSTIN) [Buyer GSTIN *],MC.Name [Buyer Legal Name *],MC.Name [Buyer Trade Name ],  
SCN.StateName [Buyer POS *],CONVERT(NVARCHAR(100),MC.Billadd1) [Buyer Addr1 *],CONVERT(NVARCHAR(100),MC.Billadd2 + '''' ''''+MC.Billadd3) [Buyer Addr2],  
CASE WHEN LEN(GHL.Name) >= 3 THEN GHL.Name ELSE ltrim(isnull(GHL.Name,'''''''') +'''' ''''+SCN.StateName) END [Buyer Location *],MC.Pincode [Buyer Pin Code],  
SCN.StateName [Buyer State *],MC.Mob1 [Buyer Phone Number],MC.Email [Buyer Email Id],'''''''' [Dispatch Name ],'''''''' [Dispatch Addr1 ],'''''''' [Dispatch Addr2],'''''''' [Dispatch Location ],'''''''' [Dispatch Pin Code ],  
'''''''' [Dispatch State ],'''''''' [Shipping GSTIN ],'''''''' [Shipping Legal Name ],'''''''' [Shipping Trade Name ],'''''''' [Shipping Addr1 ],'''''''' [Shipping Addr2],  
'''''''' [Shipping Location ],'''''''' [Shipping Pin Code ],'''''''' [Shipping State ],dbo.funTwoDecimalRoundOff(sum(SD.GrossAmt)) [Total Taxable value *],  
dbo.funTwoDecimalRoundOff(MT.[SGST Amount]) [Sgst Amt],dbo.funTwoDecimalRoundOff(MT.[CGST Amount]) [Cgst Amt],  
dbo.funTwoDecimalRoundOff(MT.[IGST Amount]) [Igst Amt],  
dbo.funTwoDecimalRoundOff(MT.[GCESS Amount] + MT.[GUOM Amount] + MT.[IUOM Amount]) [Cess Amt],'''''''' [State Cess Amt],  
(case when SH.OtherChargeAmt < 0 then dbo.funTwoDecimalRoundOff(ABS(SH.OtherChargeAmt)) else 0 end) [Discount],  
(case when SH.OtherChargeAmt >= 0 then dbo.funTwoDecimalRoundOff(SH.OtherChargeAmt + SH.TCSTaxAmt) else  
dbo.funTwoDecimalRoundOff(SH.TCSTaxAmt) end) [Other charges],  
dbo.funTwoDecimalRoundOff(dbo.fnGetRoundOffandRoundedNetAmount((dbo.funTwoDecimalRoundOff(sum(SD.GrossAmt)) +  
dbo.funTwoDecimalRoundOff(MT.[SGST Amount]) +  
dbo.funTwoDecimalRoundOff(MT.[CGST Amount]) +  
dbo.funTwoDecimalRoundOff(MT.[IGST Amount]) + dbo.funTwoDecimalRoundOff(MT.[GCESS Amount])),1)) [Round off],  
dbo.funTwoDecimalRoundOff(dbo.fnGetRoundOffandRoundedNetAmount((dbo.funTwoDecimalRoundOff(sum(SD.GrossAmt)) +  
dbo.funTwoDecimalRoundOff(MT.[SGST Amount]) +  
dbo.funTwoDecimalRoundOff(MT.[CGST Amount]) +  
dbo.funTwoDecimalRoundOff(MT.[IGST Amount]) + dbo.funTwoDecimalRoundOff(MT.[GCESS Amount])),0)+  
ISNULL(SH.OtherChargeAmt,0) + ISNULL(SH.TCSTaxAmt,0) + ISNULL(MT.[GUOM Amount],0) + ISNULL(MT.[IUOM Amount],0)) [Total Invoice value *],  
'''''''' [Shipping Bill No],'''''''' [Shipping Bill Dt],'''''''' [Port],'''''''' [Refund claim],'''''''' [Foreign Currency ],'''''''' [Country Code ],'''''''' [Export Duty Amount],  
SH.TransportID [Trans ID],SH.TransportName [Trans Name],
(case when ISNULL(SH.VehicleNo,0) = 0 THEN '''''''' ELSE SH.TransMode END) [Trans Mode ],
ISNULL(SH.Distance,'''''''') [Distance ],  
(CASE WHEN ISNULL(SH.Distance,'''''''') != '''''''' THEN SH.DocID ELSE '''''''' END) [Trans Doc No.],  
(CASE WHEN ISNULL(SH.Distance,'''''''') != '''''''' THEN CONVERT(NVARCHAR,SH.InvDate,103) ELSE '''''''' END) [Trans Doc Date],  
VH.VehicleNo [Vehicle No.],
(case when ISNULL(SH.VehicleNo,0) = 0 THEN '''''''' ELSE SH.VehicleType END) [Vehicle Type],'''''''' [Error List]  
FROM tblTranSalesHeader SH  
JOIN tblTranSalesDetail SD ON SD.InvID = SH.Id  
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId  
join #MainTaxHeaer MT ON MT.TransIdentID = SH.Id AND MT.TransID = SH.DocPrefix  
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId  
JOIN tblMasterUom MU ON MU.ID = SD.UomId  
LEFT JOIN tblGSTStateNameandCode SCN ON SCN.StateID = MC.StateID  
LEFT JOIN tblMasterBeat GHL ON GHL.ID = SH.BeatID  
left join tblMasterVehicle VH ON VH.ID = SH.VehicleNo  
WHERE ISNULL(SH.IRN,'''''''') = '''''''' AND DocPrefix IN (15,16) AND Status IN (1,3,5,6,7) AND SD.TaxId > 0 AND MC.StateID > 0 and ISNULL(MC.GSTIN,'''''''') != '''''''' and isnull(SH.DocId,'''''''') != ''''''''''  
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.InvDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)  
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)  
SET @QRY = @QRY + '' GROUP BY SH.InvDate,MC.GSTIN,MC.Name,MC.Name,SCN.StateName,MC.Mob1,MC.Email,  
MC.Billadd1,MC.Billadd2,MC.Billadd3,GHL.Name,MC.Pincode,SH.TaxTypeID,SH.TransportID,SH.TransportName,SH.TransMode,SH.Distance,VH.VehicleNo,SH.VehicleType,  
SH.OtherChargeAmt,SH.TCSTaxAmt,SH.RoundOfAmt,SH.NetAmt,SH.DocPrefix,SH.DocId,MT.[GCESS Amount],MT.[CGST Amount],
MT.[SGST Amount],MT.[IGST Amount],MT.[GUOM Amount],MT.[IUOM Amount],SH.DocId,SH.VehicleNo ''  
SET @QRY = @QRY + '' UNION ALL ''  
SET @QRY = @QRY + ''SELECT SH.TransID DocPrefix,SH.Date,''''B2B'''' [Supply Type Code *],'''''''' [Reverse Charge],'''''''' [e-Comm GSTIN],'''''''' [Igst On Intra],  
''''Debit Note'''' [Document Type *], ''  
SET @QRY += ''SH.DocId [Document Number *], CONVERT(NVARCHAR,SH.Date,103) [Document Date (DD/MM/YYYY) *],UPPER(MC.GSTIN) [Buyer GSTIN *],MC.Name [Buyer Legal Name *],  
MC.Name [Buyer Trade Name ],SCN.StateName [Buyer POS *],CONVERT(NVARCHAR(100),MC.Billadd1) [Buyer Addr1 *],  
CONVERT(NVARCHAR(100),MC.Billadd2 + '''' ''''+MC.Billadd3) [Buyer Addr2],  
SCN.StateName [Buyer Location *],  
MC.Pincode [Buyer Pin Code],SCN.StateName [Buyer State *],MC.Mob1 [Buyer Phone Number],MC.Email [Buyer Email Id],  
'''''''' [Dispatch Name ],'''''''' [Dispatch Addr1 ],'''''''' [Dispatch Addr2],'''''''' [Dispatch Location ],'''''''' [Dispatch Pin Code ],  
'''''''' [Dispatch State ],'''''''' [Shipping GSTIN ],'''''''' [Shipping Legal Name ],'''''''' [Shipping Trade Name ],'''''''' [Shipping Addr1 ],  
'''''''' [Shipping Addr2],'''''''' [Shipping Location ],'''''''' [Shipping Pin Code ],'''''''' [Shipping State ],  
dbo.funTwoDecimalRoundOff(sum(SD.GrossAmt)) [Total Taxable value *],  
dbo.funTwoDecimalRoundOff(MT.[SGST Amount]) [Sgst Amt],  
dbo.funTwoDecimalRoundOff(MT.[CGST Amount]) [Cgst Amt],  
dbo.funTwoDecimalRoundOff(MT.[IGST Amount]) [Igst Amt],  
dbo.funTwoDecimalRoundOff(MT.[GCESS Amount] + MT.[GUOM Amount] + MT.[IUOM Amount]) [Cess Amt],  
'''''''' [State Cess Amt],  
(case when SH.OtherChargeAmt < 0 then dbo.funTwoDecimalRoundOff(ABS(SH.OtherChargeAmt)) else 0 end) [Discount],  
(case when SH.OtherChargeAmt >= 0 then dbo.funTwoDecimalRoundOff(SH.OtherChargeAmt + SH.TCSTaxAmt) else  
dbo.funTwoDecimalRoundOff(SH.TCSTaxAmt) end) [Other charges],  
dbo.funTwoDecimalRoundOff(dbo.fnGetRoundOffandRoundedNetAmount((dbo.funTwoDecimalRoundOff(sum(SD.GrossAmt)) +  
dbo.funTwoDecimalRoundOff(MT.[SGST Amount]) +  
dbo.funTwoDecimalRoundOff(MT.[CGST Amount]) +  
dbo.funTwoDecimalRoundOff(MT.[IGST Amount]) + dbo.funTwoDecimalRoundOff(MT.[GCESS Amount])),1)) [Round off],  
dbo.funTwoDecimalRoundOff(dbo.fnGetRoundOffandRoundedNetAmount((dbo.funTwoDecimalRoundOff(sum(SD.GrossAmt)) +  
dbo.funTwoDecimalRoundOff(MT.[SGST Amount]) +  
dbo.funTwoDecimalRoundOff(MT.[CGST Amount]) +  
dbo.funTwoDecimalRoundOff(MT.[IGST Amount]) + dbo.funTwoDecimalRoundOff(MT.[GCESS Amount])),0)+  
ISNULL(SH.OtherChargeAmt,0) + ISNULL(SH.TCSTaxAmt,0) + ISNULL(MT.[GUOM Amount],0) + ISNULL(MT.[IUOM Amount],0))[Total Invoice value *],  
'''''''' [Shipping Bill No],'''''''' [Shipping Bill Dt],'''''''' [Port],'''''''' [Refund claim],'''''''' [Foreign Currency ],'''''''' [Country Code ],  
'''''''' [Export Duty Amount],SH.TransportID [Trans ID],SH.TransportName [Trans Name],SH.TransMode [Trans Mode ],  
ISNULL(SH.Distance,'''''''') [Distance ],(CASE WHEN ISNULL(SH.Distance,'''''''') != '''''''' THEN SH.DocID ELSE '''''''' END) [Trans Doc No.],  
(CASE WHEN ISNULL(SH.Distance,'''''''') != '''''''' THEN CONVERT(NVARCHAR,SH.Date,103) ELSE '''''''' END) [Trans Doc Date],  
VH.VehicleNo [Vehicle No.],SH.VehicleType [Vehicle Type],'''''''' [Error List]  
FROM tblTransPurchaseHeader SH  
JOIN tblTransPurchaseDetail SD ON SD.HID = SH.ID  
JOIN tblMasterVendor MC ON MC.id = SH.VendorID  
join #MainTaxHeaer MT ON MT.TransIdentID = SH.ID AND MT.TransID = SH.TransID  
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId  
JOIN tblMasterUom MU ON MU.ID = SD.UomId  
LEFT JOIN tblGSTStateNameandCode SCN ON SCN.StateID = MC.StateID  
left join tblMasterVehicle VH ON VH.ID = SH.VehicleNo  
WHERE ISNULL(SH.IRN,'''''''') = '''''''' AND SH.TransID IN (12) AND Status IN (3,5,6,7) AND SD.TaxId > 0 AND MC.StateID > 0  
and ISNULL(MC.GSTIN,'''''''') != '''''''' and isnull(SH.DocId,'''''''') != '''''''' and isnull(SH.DocId,'''''''') != '''''''' ''  
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.Date BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)  
--SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)  
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)  
SET @QRY = @QRY + '' GROUP BY SH.Date,MC.GSTIN,MC.Name,SCN.StateName,MC.Mob1,MC.Email,MC.Billadd1,MC.Billadd2,MC.Billadd3,  
MC.Pincode,SH.TaxTypeID,SH.TransportID,SH.TransportName,SH.TransMode,SH.Distance,VH.VehicleNo,SH.VehicleType,  
SH.OtherChargeAmt,SH.TCSTaxAmt,SH.RoundOffAmt,SH.NetAmt,SH.TransID,SH.DocId,SH.DocId,MT.[GCESS Amount],MT.[CGST Amount],MT.[SGST Amount],MT.[IGST Amount],MT.[GUOM Amount],MT.[IUOM Amount],SH.DocId ''  
SET @QRY = @QRY + '' ) AS REC ORDER BY DocPrefix,InvDate,[Document Number *]''  
EXEC sys.sp_executesql @QRY, N''@SheetMode INT, @FromDate date, @ToDate DATE, @DocIDs NVARCHAR(MAX)'', @SheetMode, @FromDate, @ToDate, @DocIDs  
DROP TABLE #TaxHeaer,#TaxPRHeaer,#MainTaxHeaer  
END  
ELSE  
BEGIN  
SELECT GSTSerial,ProdID,TransID,TransIdentID,(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],  
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],  
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],  
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],  
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],  
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],  
SUM([GCESS Amount] + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #TaxItems  
FROM  
(  
SELECT GSTSerial,ProdID,SRI.TransID,SRI.TransIdentID,  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 1),0)) AS [CGST %],  
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 2),0)) AS [SGST %],  
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 3),0)) AS [UTGST %],  
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 4),0)) AS [GCESS %],  
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 5),0)) AS [GUOM %],  
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 1),0)) AS [IGST %],  
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 2),0)) AS [ICESS %],  
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 3),0)) AS [IUOM %],  
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]  
FROM  
(  
SELECT * FROM  
(  
SELECT GSTSerial,ProdID,Temp.TransID,Temp.TransIdentID,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],  
Temp.TaxName AS TaxName,  
SUM(Temp.TaxValue) AS [TaxValue]  
FROM  
(  
SELECT Serial GSTSerial,ProdID,GSTInfo.TransID,GSTInfo.TransIdentID,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,  
CASE  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''  
END AS [GST Comp]  
FROM tblTransGSTInfo AS GSTInfo  
JOIN tblTranSalesHeader SH ON SH.ID = GSTInfo.TransIdentID AND SH.DocPrefix = GSTInfo.TransID  
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID  
WHERE (TransID=15 or TransID=16) AND Status IN (1,3,5,6,7) AND InvDate BETWEEN @FromDate AND @ToDate  
) Temp  
GROUP BY GSTSerial,ProdID,Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.TransID,Temp.TransIdentID  
) src  
PIVOT  
(  
SUM([TaxValue])  
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])  
) piv  
) AS SRI  
) AS RAM  
GROUP BY GSTSerial,ProdID,TransID,TransIdentID  
--SELECT * FROM #Tax  
-- PR  
SELECT GSTSerial,ProdID,TransID,TransIdentID,(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],  
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],  
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],  
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],  
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],  
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],  
SUM([GCESS Amount] + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #TaxPRItems  
FROM  
(  
SELECT GSTSerial,ProdID,SRI.TransID,SRI.TransIdentID,  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 1),0)) AS [CGST %],  
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 2),0)) AS [SGST %],  
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 3),0)) AS [UTGST %],  
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 4),0)) AS [GCESS %],  
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 5),0)) AS [GUOM %],  
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 1),0)) AS [IGST %],  
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 2),0)) AS [ICESS %],  
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 3),0)) AS [IUOM %],  
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]  
FROM  
(  
SELECT * FROM  
(  
SELECT GSTSerial,ProdID,Temp.TransID,Temp.TransIdentID,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],  
Temp.TaxName AS TaxName,  
SUM(Temp.TaxValue) AS [TaxValue]  
FROM  
(  
SELECT Serial GSTSerial,ProdID,GSTInfo.TransID,GSTInfo.TransIdentID,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,  
CASE  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''  
END AS [GST Comp]  
FROM tblTransGSTInfo AS GSTInfo  
JOIN tblTransPurchaseHeader SH ON SH.ID = GSTInfo.TransIdentID AND SH.TransID = GSTInfo.TransID  
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID  
WHERE (SH.TransID=12) AND Status IN (3,5,6,7) AND SH.Date BETWEEN @FromDate AND @ToDate  
) Temp  
GROUP BY GSTSerial,ProdID,Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.TransID,Temp.TransIdentID  
) src  
PIVOT  
(  
SUM([TaxValue])  
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])  
) piv  
) AS SRI  
) AS RAM  
GROUP BY GSTSerial,ProdID,TransID,TransIdentID  
SELECT * INTO #MainTaxItems FROM (  
SELECT * FROM #TaxItems  
UNION ALL  
SELECT * FROM #TaxPRItems) AS REC  
--select * from #MainTaxItems  
--uspExportIRNData 2,''2023-05-12'',''2023-12-30'','''',0,0  
SET @QRY = ''SELECT [Document Type *],[Document Number *],[Document Date (DD/MM/YYYY) *],[Sl.No. *] [Sl No *],[Product Description],[Is_Service *],  
[HSN code *],[Bar code ],[Quantity *],[Free Quantity],[Unit *],[Unit Price *],[Gross Amount *],[Discount],[Pre Tax Value],  
[Taxable value *],[GST Rate (%) *],[Sgst Amt(Rs)],[Cgst Amt (Rs)],[Igst Amt (Rs)],[Cess Rate (%)],[Cess Amt Adval (Rs)],  
[Cess Non Adval Amt (Rs)],[State Cess Rate (%)],[State Cess Adval Amt (Rs)],[State Cess Non-Adval Amt (Rs)],  
[Other Charges ],[Item Total *],[Batch Name],[Batch Expiry Dt],[Warranty Dt]  
FROM ( ''  
SET @QRY += ''SELECT SH.InvDate,SH.DocPrefix,SD.Serial,CASE WHEN SH.DocPrefix = 15 THEN ''''Tax Invoice'''' ELSE ''''Credit Note'''' END [Document Type *],SH.DocId [Document Number *],''  
SET @QRY += ''CONVERT(NVARCHAR,SH.InvDate,103) [Document Date (DD/MM/YYYY) *],SD.Serial [Sl.No. *],MP.Name [Product Description],  
''''NO'''' [Is_Service *],MP.HSNCode [HSN code *],'''''''' [Bar code ],  
CASE WHEN SD.QtyType != 2 THEN dbo.funTwoDecimalRoundOff(SD.UomQty) ELSE 0.00 END [Quantity *],CASE WHEN SD.QtyType = 2 THEN dbo.funTwoDecimalRoundOff(SD.UomQty) ELSE 0.00 END [Free Quantity],  
CASE WHEN MU.Name = ''''TIN'''' THEN ''''NOS'''' WHEN MU.Name = ''''KG'''' THEN ''''KGS'''' ELSE MU.Name END [Unit *],  
dbo.funTwoDecimalRoundOff(SD.UomPrice) [Unit Price *],dbo.funTwoDecimalRoundOff(SD.GoodsAmt) [Gross Amount *],  
dbo.funTwoDecimalRoundOff(((SD.ProdDisc * SD.GoodsAmt) / 100) + SD.TradeDisc + ((0 * SD.GoodsAmt) / 100) + SD.AddnlDisc) [Discount],'''''''' [Pre Tax Value],  
dbo.funTwoDecimalRoundOff(SD.GrossAmt) [Taxable value *],  
(CASE WHEN SH.TaxTypeId = 1 THEN dbo.funTwoDecimalRoundOff([CGST %] + [SGST %]) ELSE dbo.funTwoDecimalRoundOff([IGST %]) END) [GST Rate (%) *],  
(dbo.funTwoDecimalRoundOff([SGST Amount])) [Sgst Amt(Rs)],  
(dbo.funTwoDecimalRoundOff([CGST Amount])) [Cgst Amt (Rs)],  
(dbo.funTwoDecimalRoundOff([IGST Amount])) [Igst Amt (Rs)],  
(CASE WHEN SH.TaxTypeId = 1 THEN (dbo.funTwoDecimalRoundOff([GCESS %])) ELSE dbo.funTwoDecimalRoundOff([ICESS %]) END) [Cess Rate (%)],  
(CASE WHEN SH.TaxTypeId = 1 THEN (dbo.funTwoDecimalRoundOff([GCESS Amount])) ELSE dbo.funTwoDecimalRoundOff([ICESS Amount]) END) [Cess Amt Adval (Rs)],  
dbo.funTwoDecimalRoundOff([GUOM Amount] + [IUOM Amount]) [Cess Non Adval Amt (Rs)], '''''''' [State Cess Rate (%)],'''''''' [State Cess Adval Amt (Rs)],'''''''' [State Cess Non-Adval Amt (Rs)],'''''''' [Other Charges ],  
(dbo.funTwoDecimalRoundOff(SD.GrossAmt) + (dbo.funTwoDecimalRoundOff([SGST Amount])) +  
(dbo.funTwoDecimalRoundOff([CGST Amount])) +  
(dbo.funTwoDecimalRoundOff([IGST Amount])) + (dbo.funTwoDecimalRoundOff([GCESS Amount]))  
+ (dbo.funTwoDecimalRoundOff([GUOM Amount]))+ (dbo.funTwoDecimalRoundOff([IUOM Amount]))) [Item Total *],  
'''''''' [Batch Name],'''''''' [Batch Expiry Dt],'''''''' [Warranty Dt]  
FROM tblTranSalesHeader SH  
JOIN tblTranSalesDetail SD ON SD.InvId = SH.Id  
JOIN tblMasterCustomer MC ON MC.Id = SH.CustId  
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId  
join #MainTaxItems MT ON MT.TransIdentID = SH.Id AND MT.TransID = SH.DocPrefix AND MT.ProdID = SD.ProdID AND MT.GSTSerial = SD.Serial  
JOIN tblMasterUom MU ON MU.ID = SD.UomId  
LEFT JOIN tblGSTStateNameandCode SCN ON SCN.StateID = MC.StateID  
WHERE ISNULL(SH.IRN,'''''''') = '''''''' AND DocPrefix IN (15,16) AND  
Status IN (1,3,5,6,7) AND SD.TaxId > 0 AND MC.StateID > 0 and ISNULL(MC.GSTIN,'''''''') != '''''''' and isnull(SH.DocId,'''''''') != ''''''''''  
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.InvDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)  
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)  
SET @QRY = @QRY + '' UNION ALL ''  
SET @QRY = @QRY + '' SELECT SH.Date,SH.TransID DocPrefix,SD.Serial,''''Debit Note'''' [Document Type *],SH.DocId [Document Number *],''  
SET @QRY += '' CONVERT(NVARCHAR,SH.Date,103) [Document Date (DD/MM/YYYY) *],SD.Serial [Sl.No. *],MP.Name [Product Description],  
''''NO'''' [Is_Service *],MP.HSNCode [HSN code *],'''''''' [Bar code ],  
dbo.funTwoDecimalRoundOff(SD.UomQty) [Quantity *],dbo.funTwoDecimalRoundOff(SD.UomFreeQty) [Free Quantity],  
CASE WHEN MU.Name = ''''TIN'''' THEN ''''NOS'''' WHEN MU.Name = ''''KG'''' THEN ''''KGS'''' ELSE MU.Name END [Unit *],  
dbo.funTwoDecimalRoundOff(SD.UomPurchasePrice) [Unit Price *],dbo.funTwoDecimalRoundOff(SD.GoodsAmt) [Gross Amount *],  
dbo.funTwoDecimalRoundOff(((SD.[ProdDisc%] * SD.GoodsAmt) / 100) +  
(((SD.GoodsAmt - ((SD.[ProdDisc%] * SD.GoodsAmt) / 100)) * SD.[TradeDisc%]) / 100) +  
(((SD.GoodsAmt - ((SD.[ProdDisc%] * SD.GoodsAmt) / 100)) * SD.[AddnlDisc%]) / 100)) [Discount],'''''''' [Pre Tax Value],  
dbo.funTwoDecimalRoundOff(SD.GrossAmt) [Taxable value *],  
(CASE WHEN SH.TaxTypeId = 1 THEN dbo.funTwoDecimalRoundOff([CGST %] + [SGST %]) ELSE dbo.funTwoDecimalRoundOff([IGST %]) END) [GST Rate (%) *],  
(dbo.funTwoDecimalRoundOff([SGST Amount])) [Sgst Amt(Rs)],  
(dbo.funTwoDecimalRoundOff([CGST Amount])) [Cgst Amt (Rs)],  
(dbo.funTwoDecimalRoundOff([IGST Amount])) [Igst Amt (Rs)],  
(CASE WHEN SH.TaxTypeId = 1 THEN (dbo.funTwoDecimalRoundOff([GCESS %])) ELSE dbo.funTwoDecimalRoundOff([ICESS %]) END) [Cess Rate (%)],  
(CASE WHEN SH.TaxTypeId = 1 THEN (dbo.funTwoDecimalRoundOff([GCESS Amount]+ [GUOM Amount])) ELSE dbo.funTwoDecimalRoundOff([ICESS Amount]+ [GUOM Amount]) END) [Cess Amt Adval (Rs)],  
dbo.funTwoDecimalRoundOff([GUOM Amount] + [IUOM Amount]) [Cess Non Adval Amt (Rs)],'''''''' [State Cess Rate (%)],'''''''' [State Cess Adval Amt (Rs)],  
'''''''' [State Cess Non-Adval Amt (Rs)],'''''''' [Other Charges ],  
(dbo.funTwoDecimalRoundOff(SD.GrossAmt) + (dbo.funTwoDecimalRoundOff([SGST Amount])) +  
(dbo.funTwoDecimalRoundOff([CGST Amount])) +  
(dbo.funTwoDecimalRoundOff([IGST Amount])) + (dbo.funTwoDecimalRoundOff([GCESS Amount]))  
+ (dbo.funTwoDecimalRoundOff([GUOM Amount]))+ (dbo.funTwoDecimalRoundOff([IUOM Amount]))) [Item Total *],  
'''''''' [Batch Name],'''''''' [Batch Expiry Dt],'''''''' [Warranty Dt]  
FROM tblTransPurchaseHeader SH  
JOIN tblTransPurchaseDetail SD ON SD.HID= SH.ID  
JOIN tblMasterVendor MC ON MC.id = SH.VendorID  
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId  
join #MainTaxItems MT ON MT.TransIdentID = SH.ID AND MT.TransID = SH.TransID AND MT.ProdID = SD.HID AND MT.GSTSerial = SD.Serial  
JOIN tblMasterUom MU ON MU.ID = SD.UomId  
LEFT JOIN tblGSTStateNameandCode SCN ON SCN.StateID = MC.StateID  
WHERE ISNULL(SH.IRN,'''''''') = '''''''' AND SH.TransID IN (12) AND Status IN (3,5,6,7) AND SD.TaxId > 0 AND MC.StateID > 0 and isnull(SH.DocId,'''''''') != '''''''' ''  
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.Date BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)  
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)  
SET @QRY = @QRY + '' ) AS REC ORDER BY DocPrefix,InvDate,[Document Number *],Serial''  
EXEC sys.sp_executesql @QRY, N''@SheetMode INT, @FromDate date, @ToDate DATE, @DocIDs NVARCHAR(MAX)'', @SheetMode, @FromDate, @ToDate, @DocIDs  
drop table #TaxItems,#TaxPRItems,#MainTaxItems  
END  
END',
N'[06] nocount';
GO
/****** uspExportTransactionImport ******/
EXEC #Apply07 N'dbo.uspExportTransactionImport', 0xB527A75783B3AF4E98BE0BD05A2AA6DABF74D010135BBE9B65D4C7A316680BE1, NULL, NULL, 0x19FB80C2B0241858398F6AEA3A52C7856288C085769DA7B81A8803308F1B8B80, 0xBD361F08640B589B9A471BB0E1FFA7E6077AFA1C81A4D86102216CAEC7AC83CF, NULL,
N'--uspExportTransactionImport 1,1,''2026-01-01'',''2026-03-31''    
ALTER PROC [dbo].[uspExportTransactionImport]    
@TransName nvarchar(50),    
@Mode INT,    
@FromDate DATE,@ToDate DATE    
as    
SET NOCOUNT ON;
begin    
if(@TransName = 1)--Sales  
BEGIN    
IF(@Mode = 1)--Header  
BEGIN    
select SH.DocId [DOC ID *], CONVERT(NVARCHAR,SH.InvDate,103) [DOC DATE *],MBO.Name [BRANCH NAME *],    
MB.Name [BEAT NAME],SM.Name [SALESMAN NAME],MC.Name [PARTY NAME *],PM.PaymentMode [PAYMENT MODE *],MCT.Name [CREDIT TERM *],  
dbo.fnGetRoundedValue(SH.AdditionalDisc) [ADDITIONAL DISCOUNT %],  dbo.fnGetRoundedValue(SH.TradeDisc) [TRADE DISCOUNT %],  
dbo.fnGetRoundedValue(Frieght) FRIEGHT,  dbo.fnGetRoundedValue(SH.OtherChargeAmt) [OTHER CHARGE %],dbo.fnGetRoundedValue(0) [WRITEOFF AMT],  
dbo.fnGetRoundedValue(SH.NetAmt) [NET AMOUNT *],STS.Description [STATUS *],  SH.Remarks [REMARKS],    
SH.TransMode [TRANSPORT MODE],SH.VehicleType [TRANSPORT TYPE],MV.VehicleNo [VECHICLE NUMBER],SH.TransportID [TRANSPORT ID],    
SH.TransportName [TRANSPORT NAME],SH.Distance DISTANCE,SH.IRN [IRN],SH.AckNo [ACKNOWLEDGE NO],SH.AckDate [ACKNOWLEDGE DATE],    
SH.AckStatus [ACKNOWLEDGE STATUS],SH.SignedQRCode [SIGNED QRCODE],SH.EWBNo [EWAY BILL NO] from tblTranSalesHeader SH    
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId    
JOIN tblMasterBranchOffice MBO ON MBO.ID = SH.BranchID    
JOIN tblMasterTaxType MT ON MT.TaxTypeID = SH.TaxTypeId    
JOIN tblPaymentMode PM ON PM.Id = SH.PaymentModeId    
JOIN tblUsers MU ON MU.ID = SH.CBy or MU.ID = SH.MBy or MU.ID = SH.ClBy    
JOIN tblStatus STS ON STS.ID = SH.Status    
LEFT JOIN tblMasterCreditTerm MCT ON MCT.ID = SH.CreditTermId    
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatId    
LEFT JOIN tblMasterSalesMan SM ON SM.ID = SH.SalesManId    
LEFT JOIN tblMasterProductGroup PG ON PG.ID = SH.ProdGroupId    
LEFT JOIN TBLMasterReturnType MRT ON MRT.ID = SH.ReturnType    
left join tblMasterVehicle MV ON MV.ID = SH.VehicleNo    
WHERE DocPrefix = 15 AND SH.Status NOT IN (2) AND InvDate BETWEEN @FromDate AND @ToDate   
END    
    
IF(@Mode = 2)    
BEGIN    
select SH.DocId [DOC ID *],MP.Name [PRODUCT NAME *],PV.BatchNumber [BATCH NUMBER],    
PV.PKDDate [PKD DATE],    
PV.ExpiryDate [EXPIRY DATE],dbo.fnGetRoundedValue(SD.UomQty) [QTY *],dbo.fnGetRoundedValue(SD.UomPrice) [PRICE *],  
dbo.fnGetRoundedValue(PV.MRPONPrice) [MRP *],dbo.fnGetRoundedValue(SD.ProdDisc) [PRODUCT DISCOUNT],    
MT.TaxName [TAX NAME *],    
MR.Name [REASON NAME] from tblTranSalesDetail SD    
JOIN tblTranSalesHeader SH ON SH.ID = SD.InvId    
LEFT JOIN tblProductInventory PV ON PV.InventoryId = SD.InventoryId    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId    
JOIN tblMasterTax MT ON MT.TaxID = SD.TaxId    
LEFT JOIN tblMasterReason MR ON MR.ID = SD.ReasonId    
WHERE DocPrefix = 15 AND SH.Status NOT IN (2) AND InvDate BETWEEN @FromDate AND @ToDate    
end     
END   
if(@TransName = 2)--Bill  
BEGIN  
IF(@Mode = 1)--Header
BEGIN
select SH.DocId [DOC ID *],CONVERT(NVARCHAR,SH.Date,103) [DOC DATE *],MBO.Name [BRANCH NAME *],MC.Name [PARTY NAME *],  
PM.PaymentMode [PAYMENT MODE *],MCT.Name [CREDIT TERM *],dbo.fnGetRoundedValue(SH.[AddnlDisc%]) [ADDITIONAL DISCOUNT %],  
dbo.fnGetRoundedValue(SH.[TradeDisc%]) [TRADE DISCOUNT %],dbo.fnGetRoundedValue(Frieght) FRIEGHT,  
dbo.fnGetRoundedValue(SH.OtherChargeAmt) [OTHER CHARGE %],dbo.fnGetRoundedValue(0) [WRITEOFF AMT],dbo.fnGetRoundedValue(SH.NetAmt) [NET AMOUNT *],
STS.Description [STATUS *],SH.Remarks [REMARKS],SH.TransMode [TRANSPORT MODE],SH.VehicleType [TRANSPORT TYPE],  
MV.VehicleNo [VECHICLE NUMBER],SH.TransportID [TRANSPORT ID],  
SH.TransportName [TRANSPORT NAME],SH.Distance DISTANCE,SH.IRN [IRN],SH.AckNo [ACKNOWLEDGE NO],SH.AckDate [ACKNOWLEDGE DATE],  
SH.AckStatus [ACKNOWLEDGE STATUS],SH.SignedQRCode [SIGNED QRCODE],SH.EWBNo [EWAY BILL NO] from tblTransPurchaseHeader SH JOIN tblMasterVendor MC ON MC.ID = SH.VendorID  
JOIN tblMasterTaxType MT ON MT.TaxTypeID = SH.TaxTypeId  
JOIN tblPaymentMode PM ON PM.Id = SH.PaymentModeId  
LEFT JOIN tblMasterCreditTerm MCT ON MCT.ID = SH.PaymentTermID  
JOIN tblUsers MU ON MU.ID = SH.CBy or MU.ID = SH.MBy or MU.ID = SH.ClBy  
JOIN tblStatus STS ON STS.ID = SH.Status  
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = SH.BranchID  
LEFT JOIN tblMasterProductGroup PG ON PG.ID = SH.ProdGroupID  
LEFT JOIN TBLMasterReturnType MRT ON MRT.ID = SH.ReturnType  
left join tblMasterVehicle MV ON MV.ID = SH.VehicleNo  
WHERE TransID = 1 AND SH.Status NOT IN (2) AND Date BETWEEN @FromDate AND @ToDate  
END
IF(@Mode = 2)--DETAIL
BEGIN
select SH.DocId [DOC ID *],MP.Name [PRODUCT NAME *],SD.BatchNo [BATCH NUMBER],SD.PKD [PKD DATE],  
SD.Expiry [EXPIRY DATE],dbo.fnGetRoundedValue(SD.UomQty) [ACTUAL QTY],dbo.fnGetRoundedValue(SD.UomDamageQty) [DAMAGE QTY]  
,dbo.fnGetRoundedValue(SD.UomFreeQty) [FREE QTY],dbo.fnGetRoundedValue(SD.UomPurchasePrice) [PURCHASE PRICE]  
,dbo.fnGetRoundedValue(SD.UomSalePrice) [SALE PRICE],dbo.fnGetRoundedValue(SD.UomECP) [ECP PRICE],  
dbo.fnGetRoundedValue(SD.UomSPLPrice) [SPL PRICE],dbo.fnGetRoundedValue(SD.UomMRP) [MRP],  
dbo.fnGetRoundedValue(sd.UOMReturnPrice) [RETURN PRICE],  dbo.fnGetRoundedValue(SD.[ProdDisc%]) [PRODUCT DISCOUNT],  
MT.TaxName [TAX NAME *],
MR.Name [REASON NAME] from tblTransPurchaseDetail SD  
JOIN tblTransPurchaseHeader SH ON SH.ID = SD.HID   
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId  
JOIN tblMasterTax MT ON MT.TaxID = SD.TaxId  
LEFT JOIN tblMasterReason MR ON MR.ID = SD.ReasonId  
WHERE TransID = 1 AND SH.Status NOT IN (2) AND Date BETWEEN @FromDate AND @ToDate  
END
end
if(@TransName = 3)--Sales Return  
BEGIN  
IF(@Mode = 1)--Header
BEGIN
select SH.DocId [DOC ID *], CONVERT(NVARCHAR,SH.InvDate,103) [DOC DATE *],MBO.Name [BRANCH NAME *],    
MB.Name [BEAT NAME],SM.Name [SALESMAN NAME],MC.Name [PARTY NAME *],  
dbo.fnGetRoundedValue(SH.AdditionalDisc) [ADDITIONAL DISCOUNT %],  dbo.fnGetRoundedValue(SH.TradeDisc) [TRADE DISCOUNT %],  
dbo.fnGetRoundedValue(Frieght) FRIEGHT,  dbo.fnGetRoundedValue(SH.OtherChargeAmt) [OTHER CHARGE %],dbo.fnGetRoundedValue(0) [WRITEOFF AMT],  
dbo.fnGetRoundedValue(SH.NetAmt) [NET AMOUNT *],STS.Description [STATUS *],SH.TransactionType [TRANSACTION TYPE],MRT.Name [RETURN TYPE],
SH.Remarks [REMARKS],SH.TransMode [TRANSPORT MODE],SH.VehicleType [TRANSPORT TYPE],MV.VehicleNo [VECHICLE NUMBER],SH.TransportID [TRANSPORT ID],    
SH.TransportName [TRANSPORT NAME],SH.Distance DISTANCE,SH.IRN [IRN],SH.AckNo [ACKNOWLEDGE NO],SH.AckDate [ACKNOWLEDGE DATE],    
SH.AckStatus [ACKNOWLEDGE STATUS],SH.SignedQRCode [SIGNED QRCODE],SH.EWBNo [EWAY BILL NO]
 from tblTranSalesHeader SH    
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId    
JOIN tblMasterBranchOffice MBO ON MBO.ID = SH.BranchID    
JOIN tblMasterTaxType MT ON MT.TaxTypeID = SH.TaxTypeId    
JOIN tblPaymentMode PM ON PM.Id = SH.PaymentModeId    
JOIN tblUsers MU ON MU.ID = SH.CBy or MU.ID = SH.MBy or MU.ID = SH.ClBy    
JOIN tblStatus STS ON STS.ID = SH.Status    
LEFT JOIN tblMasterCreditTerm MCT ON MCT.ID = SH.CreditTermId    
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatId    
LEFT JOIN tblMasterSalesMan SM ON SM.ID = SH.SalesManId    
LEFT JOIN tblMasterProductGroup PG ON PG.ID = SH.ProdGroupId    
LEFT JOIN TBLMasterReturnType MRT ON MRT.ID = SH.ReturnType    
left join tblMasterVehicle MV ON MV.ID = SH.VehicleNo    
WHERE DocPrefix = 16 AND SH.Status NOT IN (2) AND InvDate BETWEEN @FromDate AND @ToDate  
END
IF(@Mode = 2)--DETAIL
BEGIN
select SH.DocId [DOC ID *],MP.Name [PRODUCT NAME *],PV.BatchNumber [BATCH NUMBER],    
PV.PKDDate [PKD DATE],    
PV.ExpiryDate [EXPIRY DATE],dbo.fnGetRoundedValue(SD.UomQty) [QTY *],dbo.fnGetRoundedValue(SD.UomPrice) [PRICE *],  
dbo.fnGetRoundedValue(PV.MRPONPrice) [MRP *],dbo.fnGetRoundedValue(SD.ProdDisc) [PRODUCT DISCOUNT],    
MT.TaxName [TAX NAME *],    
MR.Name [REASON NAME] from tblTranSalesDetail SD    
JOIN tblTranSalesHeader SH ON SH.ID = SD.InvId    
LEFT JOIN tblProductInventory PV ON PV.InventoryId = SD.InventoryId    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId    
JOIN tblMasterTax MT ON MT.TaxID = SD.TaxId    
LEFT JOIN tblMasterReason MR ON MR.ID = SD.ReasonId    
WHERE DocPrefix = 16 AND SH.Status NOT IN (2) AND InvDate BETWEEN @FromDate AND @ToDate    
END
end
if(@TransName = 4)--Purchase Return  
BEGIN  
IF(@Mode = 1)--Header
BEGIN
select SH.DocId [DOC ID *],CONVERT(NVARCHAR,SH.Date,103) [DOC DATE *],MBO.Name [BRANCH NAME *],MC.Name [PARTY NAME *],  
dbo.fnGetRoundedValue(SH.[AddnlDisc%]) [ADDITIONAL DISCOUNT %],  
dbo.fnGetRoundedValue(SH.[TradeDisc%]) [TRADE DISCOUNT %],dbo.fnGetRoundedValue(Frieght) FRIEGHT,  
dbo.fnGetRoundedValue(SH.OtherChargeAmt) [OTHER CHARGE %],dbo.fnGetRoundedValue(0) [WRITEOFF AMT],dbo.fnGetRoundedValue(SH.NetAmt) [NET AMOUNT *],
STS.Description [STATUS *],MRT.Name [RETURN TYPE],SH.Remarks [REMARKS],SH.TransMode [TRANSPORT MODE],SH.VehicleType [TRANSPORT TYPE],  
MV.VehicleNo [VECHICLE NUMBER],SH.TransportID [TRANSPORT ID],  
SH.TransportName [TRANSPORT NAME],SH.Distance DISTANCE,SH.IRN [IRN],SH.AckNo [ACKNOWLEDGE NO],SH.AckDate [ACKNOWLEDGE DATE],  
SH.AckStatus [ACKNOWLEDGE STATUS],SH.SignedQRCode [SIGNED QRCODE],SH.EWBNo [EWAY BILL NO] from tblTransPurchaseHeader SH JOIN tblMasterVendor MC ON MC.ID = SH.VendorID  
JOIN tblMasterTaxType MT ON MT.TaxTypeID = SH.TaxTypeId  
JOIN tblPaymentMode PM ON PM.Id = SH.PaymentModeId  
LEFT JOIN tblMasterCreditTerm MCT ON MCT.ID = SH.PaymentTermID  
JOIN tblUsers MU ON MU.ID = SH.CBy or MU.ID = SH.MBy or MU.ID = SH.ClBy  
JOIN tblStatus STS ON STS.ID = SH.Status  
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = SH.BranchID  
LEFT JOIN tblMasterProductGroup PG ON PG.ID = SH.ProdGroupID  
LEFT JOIN TBLMasterReturnType MRT ON MRT.ID = SH.ReturnType  
left join tblMasterVehicle MV ON MV.ID = SH.VehicleNo  
WHERE TransID = 12 AND SH.Status NOT IN (2) AND Date BETWEEN @FromDate AND @ToDate   
END
IF(@Mode = 2)--DETAIL
BEGIN
select SH.DocId [DOC ID *],MP.Name [PRODUCT NAME *],SD.BatchNo [BATCH NUMBER],SD.PKD [PKD DATE],  
SD.Expiry [EXPIRY DATE],dbo.fnGetRoundedValue(SD.UomQty) [ACTUAL QTY],dbo.fnGetRoundedValue(SD.UomDamageQty) [DAMAGE QTY]  
,dbo.fnGetRoundedValue(SD.UomFreeQty) [FREE QTY],dbo.fnGetRoundedValue(SD.UomPurchasePrice) [PURCHASE PRICE],
dbo.fnGetRoundedValue(SD.UomMRP) [MRP],  dbo.fnGetRoundedValue(SD.[ProdDisc%]) [PRODUCT DISCOUNT],  
MT.TaxName [TAX NAME *],
MR.Name [REASON NAME] from tblTransPurchaseDetail SD  
JOIN tblTransPurchaseHeader SH ON SH.ID = SD.HID   
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId  
JOIN tblMasterTax MT ON MT.TaxID = SD.TaxId  
LEFT JOIN tblMasterReason MR ON MR.ID = SD.ReasonId  
WHERE TransID = 12 AND SH.Status NOT IN (2) AND Date BETWEEN @FromDate AND @ToDate  
END
end
END',
N'[export] nocount';
GO
/****** uspFAAccOpenCloseBalance ******/
EXEC #Apply07 N'dbo.uspFAAccOpenCloseBalance', 0x0AF5007B312C16DEE16B87091B64997D7B8DCC2BF6C7AC1BBD9AB56AE48CC421, NULL, NULL, 0x4413C84E91164F2D4B65AB80F8586A079F48BD7EC232E44F4FA4B7DBB8D781BC, 0xD5DF7127AF545BEAACD2ED29D441FF6DD6139E54BC1396B2461FE2F66B5FF14F, NULL,
N'--[uspFAAccOpenCloseBalance] 1,159,4,''''                
ALTER PROC [dbo].[uspFAAccOpenCloseBalance]                
@Cond SMALLINT,@AccID INT,@BranchID int,@Date DATE=NULL,@IsBrs int = 0, @OpeningBalance DECIMAL (25,6)=NULL,@FAType INT=NULL,@TransId INT =NULL                
AS                
SET NOCOUNT ON;
BEGIN                
SET DATEFORMAT dmy                                          
IF ISNULL(@AccID,0)>0                                                
BEGIN                
DECLARE @Depit DECIMAL (25,6),@Credit DECIMAL (25,6),@DocSeriesID int = 0                
DECLARE @AccType INT,@AccOpeningBal DECIMAL (25,6),@TempBal DECIMAL (25,6),@Balance DECIMAL (25,6),@TempCustId INT                
DECLARE @lastDate DATE,@BookDate DATE                                                  
--Book Start Date                                                  
SELECT @BookDate = F_SD FROM dbo.tblCompanyRegistration WITH (READCOMMITTEDLOCK)                                                  
DECLARE @FDate DATE                                                  
IF ISNULL(@Date,'''')=''''                                                  
BEGIN                                                  
SET @FDate = GETDATE()                                                  
END                                                
ELSE                                                
BEGIN                                                
SET @FDate = @Date                                                
END                    
set @DocSeriesID = (select top(1) ID from tblYearwiseDocumentSeries WITH (READCOMMITTEDLOCK) where @FDate between FromDate and ToDate and BranchID = @BranchID)        
--Account Opening                                             
IF ISNULL(@OpeningBalance,0)=0                                            
BEGIN        
    
select  @AccOpeningBal=ISNULL(SUM(OpeningBalance),0),@AccType= MIN(FAType) from tblFAAccOpening WITH (READCOMMITTEDLOCK)         
where BranchID = case when isnull(@BranchID,0) = 0 then BranchID else @BranchID end and FAID = @AccID     
and ID =  case when isnull(@BranchID,0) = 0 then ID else @DocSeriesID end         
print ''Acc Open : ''+convert(nvarchar,@AccOpeningBal)
--SELECT @AccOpeningBal=ISNULL(OpeningBalance,0),@AccType=FATypeID  FROM tblFAAccount WHERE FAID =@AccID                                             
END                                            
ELSE                                            
BEGIN                                            
SET @AccOpeningBal=@OpeningBalance                                            
SET @AccType=@FAType                                            
END                                           
--Closing Balance                                                  
IF @Cond=1                                                 
BEGIN --Not Specify a Transaction                                
SELECT @Depit = ISNULL(SUM(Debit),0) , @Credit = ISNULL(SUM(Credit),0) FROM tblFAJournal WITH (READCOMMITTEDLOCK) WHERE [Status] IN(1,3,5,9,6,7)                                                   
AND AccountID = @AccID AND ((case when isnull(@IsBrs,0) = 0 then [DocDate] else BRSDate end) BETWEEN @BookDate AND  @FDate)  and  
BranchID = case when isnull(@BranchID,0) = 0 then BranchID else @BranchID end  
--Reduce Amount Sales Invoice Modify                                
IF @TransId >0                                                 
BEGIN                             
SELECT @TempBal=Balance,@TempCustId=CustId FROM dbo.tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id =@TransId                  
--Verify Same Customer or Not                  
IF ISNULL(@TempCustId,0) = (SELECT ISNULL(ID,0) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE FAID = @AccID)                  
BEGIN                             
SET @Depit = @Depit-ISNULL(@TempBal,0)                    
END                              
END                                
END                               
--Opening Balance                                                  
IF @Cond =2                                                  
BEGIn                                                  
--SELECT @lastDate               
SET @lastDate = DATEADD(DAY ,-1,@FDate)                                                   
SELECT @Depit = ISNULL(SUM(Debit),0) , @Credit = ISNULL(SUM(Credit),0) FROM tblFAJournal WITH (READCOMMITTEDLOCK) WHERE [Status] IN(1,3,5,9,6,7)                                                   
AND AccountID = @AccID AND ((case when isnull(@IsBrs,0) = 0 then [DocDate] else BRSDate end) BETWEEN @BookDate AND  @lastDate) and  
BranchID = case when isnull(@BranchID,0) = 0 then BranchID else @BranchID end        
END         

IF isnull(@AccType,1) = 1
BEGIN                       
SET @Credit= @Credit+@AccOpeningBal;                        
END                                                   
IF @AccType =2                                                  
BEGIN                                                  
SET @Depit= @Depit+@AccOpeningBal;                                               
END                                                   
--SELECT  @Depit,  @Credit, @Balance                                               
IF(@Depit < @Credit)                
BEGIN                               
SET @Balance = (@Credit - @Depit)                              
IF ISNULL(@OpeningBalance,0)=0                                            
BEGIN                                                    
SELECT ISNULL(@Balance,0) AS [Balance],''Cr'' AS [Dr/Cr]            
END                                                      
END                                                
ELSE                                                      
BEGIN                                                   
SET @Balance = (@Depit - @Credit)                                              
IF ISNULL(@OpeningBalance,0)=0                                            
BEGIN                                                   
SELECT ISNULL(@Balance,0) AS [Balance],''Dr'' AS [Dr/Cr]            
END                                                  
END                                           
IF ISNULL(@OpeningBalance,0)!=0                                            
BEGIN                                          
SELECT @Balance AS [Balance],'''' AS [Dr/Cr]            
END                                             
END                                                
END',
N'[export] nocount;readcommittedlock=7';
GO
/****** uspFilterCollectionPayment ******/
EXEC #Apply07 N'dbo.uspFilterCollectionPayment', 0xA9A124E9971791ABECD72A23C4CF10327421EBA1FAAD546DAF77F209E7AD0186, 0x0DB1BA4E6BB234421A8F57995607D740CB84F966625D2C5749FBC3290B8D85A2, NULL, 0x08FC8E531D21D62A878CA328C917CA89EA7801E5A9B43B8337867600DCF56BFA, 0x593B8A3AE1A4FE42F4B576F6D16F295E2FE56ABE70F491E21D3ACE62A22F4D91, NULL,
N'-- Security fix: list-filter values are passed to sp_executesql as parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspFilterCollectionPayment]                    
@Mode NVARCHAR(50),@DocPrefix INT,@Name NVARCHAR(255)=Null,@FromDate date,@ToDate date,@ShowAllStatus int = null                    
AS                    
SET NOCOUNT ON;
BEGIN                    
declare @StrQueryNew NVARCHAR(MAX)           
declare @DecVal int = (SELECT AppValue FROM tblAppConfig WHERE AppId = 8)    
IF @DocPrefix=19                    
BEGIN                    
SET @StrQueryNew = ''SELECT Collect.DocID DocID,CONVERT(nvarchar(40),Collect.ColDate,103) DocDate,Collect.ColDocRefNo RefNo,                    
Customer.Code,Customer.Name,convert(DECIMAL(18,''+convert(nvarchar(10), @DecVal)+''),Collect.ColAmt) Amount,PayMode.PaymentMode,StatusTable.[Description] Status,Collect.Status StatusID,Collect.ColID ID,Collect.UDFDocId AS [UDN],                    
convert(DECIMAL(18,''+convert(nvarchar(10), @DecVal)+''),Balance) Balance,Bank.AccountName AS [Bank A/C Name],                
Bank.AccountNo AS [Bank A/C No],          
(CASE WHEN ISNULL(pm.PaymentTermID,0)=2 THEN pm.[Cheque/DD Number] WHEN ISNULL(pm.PaymentTermID,0)=3 THEN pm.[Cheque/DD Number]                
WHEN ISNULL(pm.PaymentTermID,0)=4 THEN pm.NeftID WHEN ISNULL(pm.PaymentTermID,0)=5 THEN pm.NeftID END) AS [Cheque/DD/NEFT],                
CASE WHEN pm.PaymentTermID IN (2,3) THEN FORMAT(pm.Date,''''dd-MMM-yyyy'''')WHEN pm.PaymentTermID IN (4,5) THEN FORMAT(pm.Date,''''dd-MMM-yyyy'''')                
ELSE NULL END AS [Cheque/DD/NEFT Date],convert(DECIMAL(18,''+convert(nvarchar(10), @DecVal)+''),Collect.VisaPern) AS [Card (%)],                
convert(DECIMAL(18,''+convert(nvarchar(10), @DecVal)+''),Collect.VisaAmt) AS [Card Amount],  
pm.BankName AS [Bank Name],                
pm.BranchName AS [Branch Name],pm.Ifsccode AS [IFSC Code],          
CUR.UserName UserName,CONVERT(NVARCHAR(100),Collect.CDate) LastActionTime,              
Collect.Remarks,Collect.Narration,ISNULL(Collect.BranchID,0) BranchID,MBO.Name BranchName,CTM.ModeName                    
FROM tblTranCollectionHeader AS Collect                    
LEFT JOIN tblMasterCustomer AS Customer ON Customer.FAID =Collect.AccID          
LEFT JOIN tblCollPMDetails as pm ON pm.ColID=Collect.ColID           
LEFT JOIN tblMasterBankAccount AS Bank ON Bank.FAID = pm.BankAccID          
JOIN tblDocumentSeries AS Doc ON Doc.TransID=Collect.DocPrefix                    
JOIN tblPaymentMode AS PayMode ON PayMode.Id=Collect.ColMode      
JOIN tblStatus AS StatusTable ON StatusTable.[ID]=Collect.[Status]                   
JOIN tblUsers CUR ON CUR.ID = Collect.CBy      
JOIN tblMasterBranchOffice AS MBO ON MBO.Id = Collect.BranchID      
LEFT JOIN tblContraMode CTM ON CTM.ID = Collect.BTMode  
--LEFT JOIN tblMasterBank MBNK ON MBNK.ID = pm.BankName and ISNUMERIC(pm.BankName) = 1  
WHERE Collect.DocPrefix=  @DocPrefix AND ColDate BETWEEN @FromDate AND @ToDate''                    
SET @StrQueryNew = @StrQueryNew + (CASE WHEN @ShowAllStatus = 1 THEN '''' ELSE ''AND Collect.[Status] in (1,3,5)'' end)                    
SET @StrQueryNew = @StrQueryNew + (CASE WHEN ISNULL(@Name,'''')='''' THEN '''' ELSE ''AND Customer.Name =  @Name'' end)                    
SET @StrQueryNew = @StrQueryNew + '' ORDER BY Collect.ColDate DESC,Collect.DocValue DESC,Collect.ColID DESC''                    
EXEC sys.sp_executesql @StrQueryNew, N''@Mode NVARCHAR(50), @DocPrefix INT, @Name NVARCHAR(255), @FromDate date, @ToDate date, @ShowAllStatus int'', @Mode, @DocPrefix, @Name, @FromDate, @ToDate, @ShowAllStatus                    
  
END                    
ELSE IF @DocPrefix=18                    
BEGIN                    
SET @StrQueryNew = ''SELECT Payment.DocID DocID,CONVERT(nvarchar(40),Payment.PYDate,103) DocDate,Payment.PYDocRefNo RefNo,                    
Vendor.Code,Vendor.Name,convert(DECIMAL(18,''+convert(nvarchar(10), @DecVal)+''),Payment.PYAmt) Amount,PayMode.PaymentMode,StatusTable.[Description] Status,                    
Payment.Status StatusID,Payment.PYID ID,Payment.UDFDocId AS [UDN],convert(DECIMAL(18,''+convert(nvarchar(10), @DecVal)+''),Balance) Balance,       
Bank.AccountName AS [Bank A/C Name],                
Bank.AccountNo AS [Bank A/C No],      
(CASE WHEN ISNULL(pm.PaymentTermID,0)=2 THEN pm.[Cheque/DD Number] WHEN ISNULL(pm.PaymentTermID,0)=3 THEN pm.[Cheque/DD Number]                
WHEN ISNULL(pm.PaymentTermID,0)=4 THEN pm.NeftID WHEN ISNULL(pm.PaymentTermID,0)=5 THEN pm.NeftID END) AS [Cheque/DD/NEFT],       
CASE WHEN pm.PaymentTermID IN (2,3) THEN FORMAT(pm.Date,''''dd-MMM-yyyy'''')WHEN pm.PaymentTermID IN (4,5) THEN FORMAT(pm.Date,''''dd-MMM-yyyy'''')                
ELSE NULL END AS [Cheque/DD/NEFT Date],convert(DECIMAL(18,''+convert(nvarchar(10), @DecVal)+''),Payment.VisaPern) AS [Card (%)],                
convert(DECIMAL(18,''+convert(nvarchar(10), @DecVal)+''),Payment.VisaAmt) AS [Card Amount],pm.BankName AS [Bank Name],                
pm.BranchName AS [Branch Name],pm.Ifsccode AS [IFSC Code],      
CUR.UserName UserName,CONVERT(NVARCHAR(100),Payment.CDate) LastActionTime,Payment.Remarks,Payment.Narration,      
ISNULL(Payment.BranchID,0) BranchID,MBO.Name BranchName ,CTM.ModeName                    
FROM tblTranPaymentHeader AS Payment      
LEFT JOIN tblMasterVendor AS Vendor ON Vendor.FAID = Payment.AccID      
LEFT JOIN tblPaymentPMDetail as pm ON pm.PYID = Payment.PYID           
LEFT JOIN tblMasterBankAccount AS Bank ON Bank.FAID = pm.BankAccID        
JOIN tblDocumentSeries AS Doc ON Doc.TransID=Payment.PYPrefix                    
JOIN tblPaymentMode AS PayMode ON PayMode.Id=Payment.PYMode                    
JOIN tblStatus AS StatusTable ON StatusTable.ID=Payment.[Status]                   
JOIN tblUsers CUR ON CUR.ID = Payment.CBy                  
JOIN tblMasterBranchOffice AS MBO ON MBO.Id = Payment.BranchID     
LEFT JOIN tblContraMode CTM ON CTM.ID = Payment.BTMode  
WHERE Payment.PYPrefix = @DocPrefix AND PYDate BETWEEN @FromDate AND @ToDate''                    
SET @StrQueryNew = @StrQueryNew + (CASE WHEN @ShowAllStatus = 1 THEN '''' ELSE ''AND Payment.[Status] in (1,3,5)'' end)                    
SET @StrQueryNew = @StrQueryNew + (CASE WHEN ISNULL(@Name,'''')='''' THEN '''' ELSE ''AND Vendor.Name =  @Name'' end)                    
SET @StrQueryNew = @StrQueryNew + '' ORDER BY Payment.PYDate DESC, Payment.DocValue DESC,Payment.PYID DESC''                    
EXEC sys.sp_executesql @StrQueryNew, N''@Mode NVARCHAR(50), @DocPrefix INT, @Name NVARCHAR(255), @FromDate date, @ToDate date, @ShowAllStatus int'', @Mode, @DocPrefix, @Name, @FromDate, @ToDate, @ShowAllStatus                    
END                    
END',
N'[01] nocount';
GO
/****** uspFinancialReportPermission ******/
EXEC #Apply07 N'dbo.uspFinancialReportPermission', 0x6AE7E8D73FF9B887ECF22BB31DC65FDA1EA7ACABDF3AB83B0DEE806A2B91C09D, NULL, NULL, 0x795FFCC8D952D97E34EF5E01279100707E565239FBC091C0697FDED76F3AD139, 0x4396D7CA4C1E444352F63FDE4AAB0B66649F2A448D6C34792E660BA8FEDFD166, NULL,
N'--[uspFinancialReportPermission] 1,1,1                        
ALTER PROCEDURE [dbo].[uspFinancialReportPermission]                              
@Mode INT,@RoleID INT = NULL,@UserID INT=1                        
AS                                            
SET NOCOUNT ON;
BEGIN                                   
create table #tempFavPar(idx tinyint,ReportID smallint,ReportName nvarchar(255),ParentId smallint,          
LocationName  nvarchar(255),ProcedureName  nvarchar(255),DisplayIndex smallint)          
          
DECLARE @PERMISSION AS TABLE (USERID INT)                                                
INSERT INTO @PERMISSION SELECT PermissionFormId FROM tblRolePermissions WHERE Role=@RoleID                
IF ISNULL(@Mode,0)=1                              
BEGIn                              
IF isnull(@RoleID,0) = 1 AND ISNULL(@UserID,0) = 1                        
BEGIN          
          
if exists(select * from tblMenus where IsFincancialReport = 1 and Favourite = 1)          
begin          
insert into #tempFavPar values(1,(select max(ReportID) + 1 from tblFinancialReport),''Favourite'',0,''Reports'',null,0)          
end          
          
SELECT 2 idx,ReportID,ReportName,ParentId,''FinancialReports'' LocationName,ProcedureName,MM.DisplayIndex                
FROM tblFinancialReport RV          
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE ParentId=0 AND Permission = 1  and MM.Active = 1  
union all          
SELECT * from #tempFavPar          
ORDER BY idx,ParentID,DisplayIndex,ReportName ASC                          
          
END                                
ELSE              
BEGIN              
          
if exists(SELECT * FROM tblFinancialReport RV          
JOIN tblMenus MM ON MM.MenuId = RV.MenuID           
WHERE RV.Active = 1 AND Permission = 1 and RV.MenuId IN (SELECT * FROM @PERMISSION) AND RV.MenuId IN (                
SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2) AND IsFincancialReport = 1 and Favourite = 1)          
begin          
insert into #tempFavPar values(1,(select max(ReportID) + 1 from tblFinancialReport),''Favourite'',0,''FinancialReports'',null,0)          
end          
          
SELECT ReportID,ReportName,ParentId,LocationName,ProcedureName FROM (          
SELECT 2 idx,ReportID,ReportName,ParentId,''FinancialReports'' LocationName,ProcedureName,MM.DisplayIndex                
FROM tblFinancialReport RV          
JOIN tblMenus MM ON MM.MenuId = RV.MenuID          
WHERE ParentId=0 AND Permission = 1  and MM.Active = 1 and RV.Active = CASE WHEN @RoleID = 1 THEN RV.Active ELSE 1 END          
and RV.MenuId IN (SELECT * FROM @PERMISSION) AND RV.MenuId IN (                
SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2)          
UNION ALL          
SELECT * from #tempFavPar          
) AS REC          
ORDER BY idx,ParentID,DisplayIndex,ReportName ASC               
END              
END              
ELSE                              
BEGIn                              
IF isnull(@RoleID,0) = 1 AND ISNULL(@UserID,0) = 1                        
BEGIN                      
select ReportID,ReportName,ParentId,LocationName,ProcedureName from (          
SELECT 2 idx,ReportID,ReportName,ParentId,''FinancialReports'' LocationName,ProcedureName,MM.DisplayIndex                
FROM tblFinancialReport RV          
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE ParentId!=0 AND Permission = 1  and MM.Active = 1       
union all          
SELECT 1 idx,ReportID,ReportName,(select max(ReportID) + 1 from tblFinancialReport),''Favourite'' LocationName,ProcedureName,MM.DisplayIndex                
FROM tblFinancialReport RV          
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE ParentId!=0 AND Permission = 1 and MM.Active = 1 AND MM.IsFincancialReport = 1 AND MM.Favourite = 1) as rec          
ORDER BY idx,DisplayIndex,ParentID,ReportName ASC                          
END                                
ELSE                                
BEGIN                     
select * from (          
SELECT 2 idx,ReportID,ReportName,ParentId,''FinancialReports'' LocationName,ProcedureName,mm.DisplayIndex               
FROM tblFinancialReport RV          
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE ParentId!=0 AND Permission = 1 and MM.Active = 1 and RV.Active = 1 and RV.MenuId IN (SELECT * FROM @PERMISSION) AND           
RV.MenuId IN (SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2)          
UNION ALL          
SELECT 1 idx,ReportID,ReportName,(select max(ReportID) + 1 from tblFinancialReport),''Favourite'' LocationName,ProcedureName,0 DisplayIndex               
FROM tblFinancialReport RV          
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE (ParentId!=0 AND Permission = 1 and MM.Active = 1 and RV.Active = 1 and RV.MenuId IN (SELECT * FROM @PERMISSION) AND           
RV.MenuId IN (SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2)) AND MM.IsFincancialReport = 1 AND MM.Favourite = 1          
          
  ) as rec          
ORDER BY idx,ParentID,DisplayIndex,ReportName ASC                   
END                                          
END                    
drop table #tempFavPar          
END',
N'[export] nocount';
GO
/****** uspFinRepBankBook ******/
EXEC #Apply07 N'dbo.uspFinRepBankBook', 0x466B94C2C4D47D75B8B9841E859540262DB14E143C09FE8B1E163A56D2F3A12F, NULL, NULL, 0x4BE8391435D0D67DBC7C83053D557BABD6CF72144A8C4BE6857C3CE9C336E1C0, 0xC2716B069D3418039DAA0BA8745021AB0F7D08600C4ACEA93D6B68036477CA55, NULL,
N'ALTER proc [dbo].[uspFinRepBankBook]      
@AccID int = 0,@FromDate DATE = ''2026-01-01'',@ToDate DATE = ''2026-01-31'',@ShowDateWise INT = 0      
as      
SET NOCOUNT ON;
begin      
--select * from tblMasterBankAccount      
CREATE TABLE #MAINTEMP(ID INT IDENTITY(1,1),DocID NVARCHAR(255),DocDate date, DocRef NVARCHAR(255),UDFDocId NVARCHAR(255),TranName NVARCHAR(255),AccountName NVARCHAR(255),                      
Credit DECIMAL(25,6),Debit DECIMAL(25,6),Balance NVARCHAR(255),Remarks NVARCHAR(255),Narration NVARCHAR(255), DocPrefix INT,DocValue INT,                      
NoteID INT,JVID INT,ChequeInfo NVARCHAR(255))                      
                      
SELECT Distinct DocDate, JVID INTO #TP FROM tblFAJournal WHERE AccountID=@AccID AND Status NOT IN (2,4) AND DocDate BETWEEN @FromDate AND @ToDate  --Order BY DocPrefix,DocValue                                                       
SELECT ROW_NUMBER()                                                                       
OVER (ORDER BY tblFAJournal.DocDate,tblFAJournal.NoteID) AS RowID,Doc.DocDate,DocID,DocRef,UDFDocId,                                                                      
tblFAJournal.DocPrefix,AccountID,Debit,Credit,Remarks,Narration,tblFAJournal.DocValue,NoteID,tblFAJournal.JVID,tblFAJournal.ChequeInfo INTO #CopyOfLedger FROM dbo.tblFAJournal                                          
JOIN #TP Doc ON tblFAJournal.JVID=Doc.JVID                                                                    
WHERE AccountID!=@AccID AND DOC.DocDate BETWEEN @FromDate AND @ToDate AND tblFAJournal.Status NOT IN (2,4,8) Order BY DocDate,JVID                      
                  
--get Opening Balance                  
DECLARE @ReturnTable TABLE (ReturnValue DECIMAL (25,6),FaType NVARCHAR(10))                                                                      
DECLARE @ReturnValue DECIMAL (25,6),@FAType NVARCHAR(10),@TempDate DATE=(SELECT DATEADD(DAY,0, @FromDate))                                                                
INSERT INTO @ReturnTable EXEC uspFAAccOpenCloseBalance 2,@AccID,0,@TempDate,NULL,NULL                                                                    
                                  
SELECT @ReturnValue=ReturnValue,@FAType=FaType FROM @ReturnTable                                                                
IF ISNULL(@FaType,'''')=''Cr''                                                                
BEGIN                                                                
SET @ReturnValue= -1*ISNULL(@ReturnValue,0)                                                                
END                                                                
                                  
SELECT  OriginalTable.DocDate DocDate,OriginalTable.DocID DocID,OriginalTable.DocRef DocRef,OriginalTable.UDFDocId UDFDocId,                      
Doc.TransName TranName,tblFAAccount.AccountName,( OriginalTable.Debit) Credit,(OriginalTable.Credit) Debit,                                                      
CASE WHEN ISNULL(SUM(Temporary.Credit)- SUM(Temporary.Debit)+@ReturnValue,0)<0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ABS(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue))))+'' Cr''                      
WHEN ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit)+@ReturnValue,0)>=0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue)))+'' Dr''              
ELSE '''' END AS Balance,                      
OriginalTable.Remarks Remarks,OriginalTable.Narration Narration,OriginalTable.DocPrefix DocPrefix,OriginalTable.DocValue DocValue,OriginalTable.NoteID NoteID,OriginalTable.JVID JVID, OriginalTable.ChequeInfo ChequeInfo                      
into #temp                      
FROM #CopyOfLedger OriginalTable                                                                           
INNER JOIN #CopyOfLedger Temporary ON OriginalTable.RowID >= Temporary.RowID                      
JOIN tblFAAccount ON tblFAAccount.FAID=OriginalTable.AccountID                                                  
JOIN tblDocumentSeries Doc ON Doc.TransID=OriginalTable.DocPrefix                                                             
GROUP BY OriginalTable.RowID,OriginalTable.DocDate,OriginalTable.DocPrefix,OriginalTable.DocValue,OriginalTable.DocID,OriginalTable.JVID,OriginalTable.DocRef,OriginalTable.UDFDocId,                                                                          
Doc.TransName,tblFAAccount.AccountName, OriginalTable.Debit,OriginalTable.Credit,OriginalTable.Remarks,OriginalTable.Narration,OriginalTable.NoteID,OriginalTable.ChequeInfo                                                                         
Order BY OriginalTable.RowID                       
                    
  create table #getCB(ID INT IDENTITY(1,1),CB DECIMAL(25,6),Type varchar(10))          
 create table #getOB(ID INT IDENTITY(1,1),OB DECIMAL(25,6),Type varchar(10))          
IF(@ShowDateWise = 1)                        
BEGIN                      
DECLARE @FDATE DATE = @FromDate,@TDATE DATE = @ToDate                      
WHILE @FDATE <= @TDATE                        
BEGIN                  
--GET OPENING BAL FOR EVERY DAY                                                
INSERT INTO #getOB EXEC uspFAAccOpenCloseBalance 2,@AccID,0,@FDATE,NULL,NULL                   
DECLARE @OBType varchar(10) = (SELECT TOP 1 Type FROM #getOB ORDER BY ID DESC)          
DECLARE @OBVALUE DECIMAL(25,6) = (SELECT TOP 1 OB FROM #getOB ORDER BY ID DESC)                  
--GET CLOSING BAL FOR EVERY DAY                                                      
INSERT INTO #getCB EXEC uspFAAccOpenCloseBalance 1,@AccID,0,@FDATE,NULL,NULL                         
DECLARE @CBVALUE DECIMAL(25,6) = (SELECT TOP 1 CB FROM #getCB ORDER BY ID DESC)          
DECLARE @CBType NVARCHAR(20) = (SELECT TOP 1 Type FROM #getCB ORDER BY ID DESC)          
                     
INSERT INTO #MAINTEMP                      
 SELECT '''' AS DocID,@FDATE DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Opening Balance'' AccountName,                   
(CASE WHEN @OBType = ''Cr'' THEN ABS(@OBVALUE) ELSE 0  END) AS Credit,                          
(CASE WHEN @OBType = ''Dr'' THEN ABS(@OBVALUE) ELSE 0  END) AS Debit,          
'''' Balance,                        
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo                  
UNION ALL                  
select DocID,DocDate,DocRef,UDFDocId,TranName,AccountName,Credit,Debit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,                      
JVID,ChequeInfo from #temp WHERE DocDate =  @FDATE                      
UNION ALL                      
SELECT '''' AS DocID,DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Total'' AccountName,           
(CASE WHEN @OBType = ''Cr'' THEN ABS(@OBVALUE) + SUM(Credit) ELSE SUM(Credit)  END) AS Credit,                          
(CASE WHEN @OBType = ''Dr'' THEN ABS(@OBVALUE) + SUM(Debit) ELSE SUM(Debit)  END) AS Debit,          
'''' Balance,'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo                        
 FROM #temp WHERE DocDate = @FDATE                        
 GROUP BY DocDate                      
 UNION ALL                      
 SELECT '''' AS DocID,@FDATE DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Closing Balance'' AccountName,                    
(CASE WHEN @CBType = ''Cr'' THEN ABS(@CBVALUE) ELSE 0  END) AS Credit,                          
(CASE WHEN @CBType = ''Dr'' THEN ABS(@CBVALUE) ELSE 0  END) AS Debit,          
'''' Balance,'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo --FROM  #temp WHERE DocDate = @FDATE                      
          
SET @FDATE = DATEADD(DD,1,@FDATE)                      
END                      
END                      
ELSE                      
BEGIN                  
INSERT INTO #MAINTEMP                      
SELECT '''' AS DocID,@FromDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Opening Balance'' AccountName,(CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) ELSE 0  END) AS Credit,                    
(CASE WHEN @ReturnValue > 0 THEN ABS(@ReturnValue) ELSE 0  END)  AS Debit,'''' Balance,                        
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo                       
UNION ALL                  
select DocID,DocDate,DocRef,UDFDocId,TranName,AccountName,Credit,Debit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,                      
JVID,ChequeInfo from #temp                       
UNION ALL                      
SELECT '''' AS DocID,@ToDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Total'' AccountName,(CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0)  END) AS Credit,                    
(CASE WHEN @ReturnValue > 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0) END) AS Debit,'''' Balance,                        
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo                        
 FROM #temp --WHERE DocDate = @FDATE                        
 --GROUP BY DocDate                    
UNION ALL                    
 SELECT '''' AS DocID,@ToDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Closing Balance'' AccountName,                  
 ISNULL((CASE WHEN (CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0)  END) < (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0)  END)           
 THEN (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0)  END) -                    
(CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0)  END) ELSE 0 END),ABS(@ReturnValue)) AS Credit,                    
ISNULL((CASE WHEN (CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0)  END) >= (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0)  END)           
THEN (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0)  END) -                    
(CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0) END) ELSE 0 END),ABS(@ReturnValue))  AS Debit ,'''' Balance,                        
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo                        
 FROM #temp                     
END                      
select 
case when AccountName = ''Opening Balance'' then 1 when AccountName = ''Total'' then 3  when AccountName = ''Closing Balance'' then 4 else 2 end idx
,ISNULL(DocPrefix,0) DocPrefix,ISNULL(DocValue,0) DocValue,NoteID,JVID,DocID [DocID],      
FORMAT(DocDate,''dd-MMM-yyyy'') [DocDate],DocRef [Ref No],TranName [Transaction Name],                        
AccountName [Account Name],dbo.fnGetRoundedValue(ABS(Debit)) Debit,dbo.fnGetRoundedValue(ABS(Credit)) Credit,Balance                  
,Remarks,Narration,ChequeInfo from #MAINTEMP                  
 ORDER BY idx,DocDate ASC                      
DROP TABLE #CopyOfLedger,#TP,#temp,#MAINTEMP,#getOB,#getCB--,#OB                      
end',
N'[export] nocount';
GO
/****** uspFinRepBankStatement ******/
EXEC #Apply07 N'dbo.uspFinRepBankStatement', 0x87CD4176626AB59EB8FE02F42AC917AB29B870A41494E4B617A5FFA1670BBD89, NULL, NULL, 0x69B4EACE5A5B0C1D97F344282A7122CBE5E5CDC3E4CD81E88C473E51963EA159, 0x0FFE8FA14D94C731D98AD716B8D17398BD6A31610FC868C8D01CDECDB6A8B9E9, NULL,
N'--uspFinRepBankStatement 159  
ALTER proc [dbo].[uspFinRepBankStatement]      
@AccID int = 0,@FromDate DATE = ''2025-01-01'',@ToDate DATE = ''2026-01-31'',@ShowDateWise INT = 0      
as      
SET NOCOUNT ON;
begin      
CREATE TABLE #MAINTEMP(ID INT IDENTITY(1,1),DocID NVARCHAR(255),DocDate date, DocRef NVARCHAR(255),UDFDocId NVARCHAR(255),TranName NVARCHAR(255),AccountName NVARCHAR(255),      
Credit DECIMAL(25,6),Debit DECIMAL(25,6),Balance NVARCHAR(255),Remarks NVARCHAR(255),Narration NVARCHAR(255), DocPrefix INT,DocValue INT,      
NoteID INT,JVID INT,ChequeInfo NVARCHAR(255))      
create table #getCB(ID INT IDENTITY(1,1),CB DECIMAL(25,6),Type varchar(10))      
create table #getOB(ID INT IDENTITY(1,1),OB DECIMAL(25,6),Type varchar(10))      
SELECT Distinct BRSDate, JVID INTO #TP FROM tblFAJournal WHERE AccountID=@AccID AND Status NOT IN (2,4) AND BRSDate BETWEEN @FromDate AND @ToDate --Order BY DocPrefix,DocValue      
      
SELECT ROW_NUMBER()      
OVER (ORDER BY DOC.BRSDate,NoteID) AS RowID,Doc.BRSDate,DocID,DocRef,UDFDocId,      
tblFAJournal.DocPrefix,AccountID,Debit,Credit,Remarks,Narration,tblFAJournal.DocValue,NoteID,tblFAJournal.JVID,tblFAJournal.ChequeInfo INTO #CopyOfLedger FROM dbo.tblFAJournal      
JOIN #TP Doc ON tblFAJournal.JVID=Doc.JVID      
WHERE AccountID!=@AccID AND DOC.BRSDate BETWEEN @FromDate AND @ToDate AND tblFAJournal.Status NOT IN (2,4,8) Order BY BRSDate,JVID      
      
DECLARE @ReturnTable TABLE (ReturnValue DECIMAL (25,6),FaType NVARCHAR(10))      
DECLARE @ReturnValue DECIMAL (25,6),@FAType NVARCHAR(10),@TempDate DATE=(SELECT DATEADD(DAY,0, @FromDate))      
INSERT INTO @ReturnTable EXEC uspFAAccOpenCloseBalance 2,@AccID,0,@TempDate,1,NULL,NULL      
      
SELECT @ReturnValue=ReturnValue,@FAType=FaType FROM @ReturnTable      
IF ISNULL(@FaType,'''')=''Cr''      
BEGIN      
SET @ReturnValue= -1*ISNULL(@ReturnValue,0)      
END      
      
SELECT OriginalTable.BRSDate,OriginalTable.DocID,OriginalTable.DocRef,OriginalTable.UDFDocId,      
Doc.TransName TranName,tblFAAccount.AccountName,( OriginalTable.Debit) Credit,(OriginalTable.Credit) Debit,      
CASE WHEN ISNULL(SUM(Temporary.Credit)- SUM(Temporary.Debit)+@ReturnValue,0)<0.00 THEN CONVERT(NVARCHAR(50),[dbo].[fnGetRoundedValue](ABS(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue)))+'' Cr''      
WHEN ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit)+@ReturnValue,0)>=0.00 THEN CONVERT(NVARCHAR(50),[dbo].[fnGetRoundedValue](ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue))+'' Dr''      
ELSE '''' END AS Balance,      
OriginalTable.Remarks,OriginalTable.Narration,OriginalTable.DocPrefix,OriginalTable.DocValue,OriginalTable.NoteID,OriginalTable.JVID , OriginalTable.ChequeInfo      
into #temp      
FROM #CopyOfLedger OriginalTable      
INNER JOIN #CopyOfLedger Temporary ON OriginalTable.RowID >= Temporary.RowID      
JOIN tblFAAccount ON tblFAAccount.FAID=OriginalTable.AccountID      
JOIN tblDocumentSeries Doc ON Doc.TransID=OriginalTable.DocPrefix      
GROUP BY OriginalTable.RowID,OriginalTable.BRSDate,OriginalTable.DocPrefix,OriginalTable.DocValue,OriginalTable.DocID,OriginalTable.JVID,OriginalTable.DocRef,OriginalTable.UDFDocId,      
Doc.TransName,tblFAAccount.AccountName, OriginalTable.Debit,OriginalTable.Credit,OriginalTable.Remarks,OriginalTable.Narration,OriginalTable.NoteID,OriginalTable.ChequeInfo      
Order BY OriginalTable.RowID      
      
IF(@ShowDateWise = 1)      
BEGIN      
DECLARE @FDATE DATE = @FromDate,@TDATE DATE = @ToDate      
WHILE @FDATE <= @TDATE      
BEGIN      
--GET OPENING BAL FOR EVERY DAY      
INSERT INTO #getOB EXEC uspFAAccOpenCloseBalance 2,@AccID,0,@FDATE,1,NULL,NULL      
DECLARE @OBVALUE DECIMAL(25,6) = (SELECT TOP 1 OB FROM #getOB ORDER BY ID DESC)      
DECLARE @Type varchar(10) = (SELECT TOP 1 Type FROM #getOB ORDER BY ID DESC)      
--GET CLOSING BAL FOR EVERY DAY      
INSERT INTO #getCB EXEC uspFAAccOpenCloseBalance 1,@AccID,0,@FDATE,1,NULL,NULL      
DECLARE @CBVALUE DECIMAL(25,6) = (SELECT TOP 1 CB FROM #getCB ORDER BY ID DESC)      
DECLARE @CBType NVARCHAR(20) = (SELECT TOP 1 Type FROM #getCB ORDER BY ID DESC)      
PRINT @OBVALUE      
      
INSERT INTO #MAINTEMP      
SELECT '''' AS DocID,@FDATE DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Opening Balance'' AccountName,      
(CASE WHEN @Type = ''Cr'' THEN ABS(@OBVALUE) ELSE 0 END) AS Credit,      
(CASE WHEN @Type = ''Dr'' THEN ABS(@OBVALUE) ELSE 0 END) AS Debit,      
'''' Balance,'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
UNION ALL      
select DocID,BRSDate DocDate,DocRef,UDFDocId,TranName,AccountName,Credit,Debit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,      
JVID,ChequeInfo from #temp WHERE BRSDate = @FDATE      
UNION ALL      
SELECT '''' AS DocID,BRSDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Total'' AccountName,      
(CASE WHEN @Type = ''Cr'' THEN ABS(@OBVALUE) + SUM(Credit) ELSE SUM(Credit) END) AS Credit,      
(CASE WHEN @Type = ''Dr'' THEN ABS(@OBVALUE) + SUM(Debit) ELSE SUM(Debit) END) AS Debit,      
'''' Balance,'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
FROM #temp WHERE BRSDate = @FDATE      
GROUP BY BRSDate      
UNION ALL      
SELECT '''' AS DocID,@FDATE DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Closing Balance'' AccountName,      
(CASE WHEN @CBType = ''Cr'' THEN ABS(@CBVALUE) ELSE 0 END) AS Credit,      
(CASE WHEN @CBType = ''Dr'' THEN ABS(@CBVALUE) ELSE 0 END) AS Debit,      
'''' Balance,'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo-- FROM #temp WHERE BRSDate = @FDATE      
SET @FDATE = DATEADD(DD,1,@FDATE)      
END      
END      
ELSE      
BEGIN      
INSERT INTO #getOB EXEC uspFAAccOpenCloseBalance 1,@AccID,0,@ToDate,1,NULL,NULL      
DECLARE @OBVALUE1 DECIMAL(25,6) = (SELECT TOP 1 OB FROM #getOB ORDER BY ID DESC)      
INSERT INTO #MAINTEMP      
SELECT '''' AS DocID,@FromDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Opening Balance'' AccountName,(CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) ELSE 0 END) AS Credit,      
(CASE WHEN @ReturnValue > 0 THEN ABS(@ReturnValue) ELSE 0 END) AS Debit,'''' Balance,      
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
UNION ALL      
select DocID,BRSDate DocDate,DocRef,UDFDocId,TranName,AccountName,Credit,Debit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,      
JVID,ChequeInfo from #temp      
UNION ALL      
SELECT '''' AS DocID,@ToDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Total'' AccountName,      
isnull((CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + isnull(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0) END),0) AS Credit,      
isnull((CASE WHEN @ReturnValue > 0 THEN ABS(@ReturnValue) + isnull(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0) END),0) AS Debit,'''' Balance,      
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
FROM #temp      
UNION ALL      
SELECT '''' AS DocID,@ToDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Closing Balance'' AccountName,      
--(CASE WHEN @ReturnValue < 0 THEN @OBVALUE1 ELSE 0 END) Credit,(CASE WHEN @ReturnValue > 0 THEN @OBVALUE1 ELSE 0 END) Debit,      
ISNULL((CASE WHEN (CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + isnull(SUM(Debit),0) ELSE isnull(SUM(Debit),0) END) < (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + isnull(SUM(Credit),0) ELSE isnull(SUM(Credit),0) END)      
THEN (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + isnull(SUM(Credit),0) ELSE isnull(SUM(Credit),0) END) -      
(CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + isnull(SUM(Debit),0) ELSE isnull(SUM(Debit),0) END) ELSE 0 END),ABS(@ReturnValue)) AS Credit,      
ISNULL((CASE WHEN (CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + isnull(SUM(Debit),0) ELSE isnull(SUM(Debit),0) END) >= (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + isnull(SUM(Credit),0) ELSE isnull(SUM(Credit),0) END)      
THEN (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + isnull(SUM(Credit),0) ELSE isnull(SUM(Credit),0) END) -      
(CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + isnull(SUM(Debit),0) ELSE isnull(SUM(Debit),0) END) ELSE 0 END),ABS(@ReturnValue)) AS Debit      
,'''' Balance,      
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
FROM #temp      
END      
select case when AccountName = ''Opening Balance'' then 1 when AccountName = ''Total'' then 3  when AccountName = ''Closing Balance'' then 4 else 2 end idx,
ISNULL(DocPrefix,0) DocPrefix,ISNULL(DocValue,0) DocValue,NoteID,JVID,DocID [DocID],FORMAT(DocDate,''dd-MMM-yyyy'') [DocDate],DocRef [Ref No],      
TranName [Transaction Name],AccountName [Account Name],dbo.fnGetRoundedValue(ABS(isnull(Debit,0))) Debit,      
dbo.fnGetRoundedValue(ABS(isnull(Credit,0))) Credit,Balance,Remarks,Narration,ChequeInfo from #MAINTEMP      
ORDER BY idx,ID,DocDate ASC      
DROP TABLE #CopyOfLedger,#TP,#temp,#MAINTEMP,#getOB,#getCB--,#OB      
end',
N'[export] nocount';
GO
/****** uspFinRepCashBook ******/
EXEC #Apply07 N'dbo.uspFinRepCashBook', 0xD471AFCFADC0F27DF4DE5DF466730FED8ADCEB8200856193207713FB3692C33D, NULL, NULL, 0xA024B4B96ABC3DE15D1265DB2BFA6E774A60A37F899A04BE75FC556663FD9FBF, 0xB21C51817223FBE2DB72F80C31BA5BD0E6DB7B4B6743AC4983D4B34620B1EADA, NULL,
N'--uspFinRepCashBook 4  
ALTER proc [dbo].[uspFinRepCashBook]      
@BranchID int,@FromDate DATE = ''2025-01-01'',@ToDate DATE = ''2026-02-15'',@ShowDateWise INT = 1      
as      
SET NOCOUNT ON;
begin      
DECLARE @AccID INT = 13      
CREATE TABLE #MAINTEMP(ID INT IDENTITY(1,1),DocID NVARCHAR(255),DocDate date, DocRef NVARCHAR(255),UDFDocId NVARCHAR(255),TranName NVARCHAR(255),AccountName NVARCHAR(255),      
Credit DECIMAL(25,6),Debit DECIMAL(25,6),Balance NVARCHAR(255),Remarks NVARCHAR(255),Narration NVARCHAR(255), DocPrefix INT,DocValue INT,      
NoteID INT,JVID INT,ChequeInfo NVARCHAR(255))      
create table #getOB(ID INT IDENTITY(1,1),OB DECIMAL(25,6),Type varchar(10))      
create table #getCB(ID INT IDENTITY(1,1),CB DECIMAL(25,6),Type varchar(10))      
      
DECLARE @ReturnTable TABLE (ReturnValue DECIMAL (25,6),FaType NVARCHAR(10))      
DECLARE @ReturnValue DECIMAL (25,6),@FAType NVARCHAR(10),@TempDate DATE=(SELECT DATEADD(DAY,0, @FromDate))      
INSERT INTO @ReturnTable EXEC uspFAAccOpenCloseBalance 2,@AccID,@BranchID,@TempDate,NULL,NULL      
      
SELECT @ReturnValue=ReturnValue,@FAType=FaType FROM @ReturnTable      
      
SELECT Distinct DocDate, JVID INTO #TP FROM tblFAJournal WHERE AccountID=@AccID  AND BranchID = @BranchID AND Status NOT IN (2,4) AND DocDate BETWEEN @FromDate AND @ToDate --Order BY DocPrefix,DocValue      
SELECT ROW_NUMBER()      
OVER (ORDER BY tblFAJournal.DocDate,tblFAJournal.NoteID) AS RowID,Doc.DocDate,DocID,DocRef,UDFDocId,      
tblFAJournal.DocPrefix,AccountID,Debit,Credit,Remarks,Narration,tblFAJournal.DocValue,NoteID,tblFAJournal.JVID,tblFAJournal.ChequeInfo INTO #CopyOfLedger      
FROM dbo.tblFAJournal      
JOIN #TP Doc ON tblFAJournal.JVID=Doc.JVID      
WHERE AccountID!=@AccID AND DOC.DocDate BETWEEN @FromDate AND @ToDate AND tblFAJournal.Status NOT IN (2,4,8)      
Order BY DocDate,JVID      
      
IF ISNULL(@FaType,'''')=''Cr''      
BEGIN      
SET @ReturnValue= -1*ISNULL(@ReturnValue,0)      
END      
SELECT OriginalTable.RowID,Temporary.RowID trd,OriginalTable.DocDate DocDate,OriginalTable.DocID DocID,OriginalTable.DocRef DocRef,OriginalTable.UDFDocId UDFDocId,      
Doc.TransName TranName,tblFAAccount.AccountName,( OriginalTable.Debit * -1) Credit ,(OriginalTable.Credit) Debit,      
CASE WHEN ISNULL(SUM(Temporary.Credit)- SUM(Temporary.Debit)+@ReturnValue,0)<0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ABS(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue))))+'' Cr''      
WHEN ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit)+@ReturnValue,0)>=0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue)))+'' Dr''      
ELSE '''' END AS Balance,CASE WHEN ISNULL(SUM(Temporary.Credit)- SUM(Temporary.Debit)+@ReturnValue,0)<0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),((ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue))))      
WHEN ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit)+@ReturnValue,0)>=0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue)))      
ELSE '''' END AS CCBalance,      
OriginalTable.Remarks Remarks,OriginalTable.Narration Narration,OriginalTable.DocPrefix DocPrefix,OriginalTable.DocValue DocValue,OriginalTable.NoteID NoteID,OriginalTable.JVID JVID, OriginalTable.ChequeInfo ChequeInfo      
into #tempData      
FROM #CopyOfLedger OriginalTable      
INNER JOIN #CopyOfLedger Temporary ON OriginalTable.RowID = Temporary.RowID      
JOIN tblFAAccount ON tblFAAccount.FAID=OriginalTable.AccountID      
JOIN tblDocumentSeries Doc ON Doc.TransID=OriginalTable.DocPrefix      
GROUP BY OriginalTable.RowID,OriginalTable.DocDate,OriginalTable.DocPrefix,OriginalTable.DocValue,OriginalTable.DocID,OriginalTable.JVID,OriginalTable.DocRef,OriginalTable.UDFDocId,      
Doc.TransName,tblFAAccount.AccountName, OriginalTable.Debit,OriginalTable.Credit,OriginalTable.Remarks,OriginalTable.Narration,OriginalTable.NoteID,OriginalTable.ChequeInfo      
,Temporary.RowID      
Order BY OriginalTable.RowID      
      
CREATE TABLE #DOCWISE(DInt INT IDENTITY(1,1),Deb DECIMAL(25,6),Cre DECIMAL(25,6),Bals NVARCHAR(50),Df INT,DV INT,NID INT,JID INT)      
declare @cpTC int = (select count(distinct RowID) from #tempData),@incr INT = 1,@nCr DECIMAL(25,6),@nDr DECIMAL(25,6),      
@InitialDr DECIMAL(25,6) = (SELECT SUM(Credit) FROM #tempData WHERE RowID = 1) + isnull(@ReturnValue,0)      
DECLARE @DCCount int,@DCincr INT = 1,@DCCr DECIMAL(25,6)      
      
WHILE(@cpTC >= @incr)      
BEGIN      
SELECT @nCr = (case when @incr = 0 then 0 else Debit end),@nDr = (case when @incr = 0 then 0 else Credit end) FROM #tempData WHERE RowID = @incr      
--PRINT ''initial - ''+CONVERT(NVARCHAR,@InitialDr)+'' cr- '' + CONVERT(NVARCHAR,@nDr) +'' dr- '' + CONVERT(NVARCHAR,@nCr)      
INSERT INTO #DOCWISE      
SELECT Debit,Credit,      
case when @InitialDr >= @nDr THEN      
CASE WHEN @InitialDr >= ABS(@nDr) THEN CONVERT(NVARCHAR(50),dbo.fnGetRoundedValue(ABS(@InitialDr + @nCr + @nDr))) + '' Dr''      
ELSE CONVERT(NVARCHAR(50),dbo.fnGetRoundedValue(ABS(@InitialDr + @nCr + @nDr))) + '' Cr'' END ELSE      
CASE WHEN ABS(@InitialDr) >= @nCr THEN CONVERT(NVARCHAR(50),dbo.fnGetRoundedValue(ABS(@InitialDr + @nCr + @nDr))) + '' Cr''      
ELSE      
CONVERT(NVARCHAR(50),dbo.fnGetRoundedValue(ABS(@InitialDr + @nCr + @nDr))) + '' Dr'' END END BAL,DocPrefix,DocValue,NoteID,JVID      
FROM #tempData WHERE RowID = @incr      
      
SET @InitialDr = @InitialDr + @nCr + @nDr      
      
SET @incr = @incr + 1;      
END      
SELECT DocID,DocDate,DocRef,UDFDocId,TranName,AccountName,Debit,ABS(Credit) Credit,DW.Bals Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,      
JVID,ChequeInfo into #temp FROM #DOCWISE DW      
JOIN #tempData COL ON COL.NoteID = DW.NID      
ORDER BY DocDate      
      
IF(@ShowDateWise = 1)      
BEGIN      
DECLARE @FDATE DATE = @FromDate,@TDATE DATE = @ToDate      
WHILE @FDATE <= @TDATE      
BEGIN      
--GET OPENING BAL FOR EVERY DAY      
INSERT INTO #getOB EXEC uspFAAccOpenCloseBalance 2,@AccID,@BranchID,@FDATE,NULL,NULL      
DECLARE @OBVALUE DECIMAL(25,6) = (SELECT TOP 1 OB FROM #getOB ORDER BY ID DESC)      
DECLARE @OBType NVARCHAR(20) = (SELECT TOP 1 Type FROM #getOB ORDER BY ID DESC)      
--GET CLOSING BAL FOR EVERY DAY      
INSERT INTO #getCB EXEC uspFAAccOpenCloseBalance 1,@AccID,@BranchID,@FDATE,NULL,NULL      
DECLARE @CBVALUE DECIMAL(25,6) = (SELECT TOP 1 CB FROM #getCB ORDER BY ID DESC)      
DECLARE @CBType NVARCHAR(20) = (SELECT TOP 1 Type FROM #getCB ORDER BY ID DESC)      
      
PRINT ''initial - ''+CONVERT(NVARCHAR,@OBVALUE)+'' RTN VAL - '' + CONVERT(NVARCHAR,@ReturnValue)      
INSERT INTO #MAINTEMP      
SELECT '''' AS DocID,@FDATE DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Opening Balance'' AccountName,      
(CASE WHEN @OBType = ''Cr'' THEN ABS(@OBVALUE) ELSE 0 END) AS Credit,      
(CASE WHEN @OBType = ''Dr'' THEN ABS(@OBVALUE) ELSE 0 END) AS Debit      
,'''' Balance,      
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
UNION ALL      
select DocID,DocDate,DocRef,UDFDocId,TranName,AccountName,Credit,Debit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,      
JVID,ChequeInfo from #temp WHERE DocDate = @FDATE      
UNION ALL      
SELECT '''' AS DocID,DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Total'' AccountName,      
(CASE WHEN @OBType = ''Cr'' THEN ABS(@OBVALUE) + SUM(Credit) ELSE SUM(Credit) END) AS Credit,      
(CASE WHEN @OBType = ''Dr'' THEN ABS(@OBVALUE) + SUM(Debit) ELSE SUM(Debit) END) AS Debit,      
'''' Balance,      
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
FROM #temp WHERE DocDate = @FDATE      
GROUP BY DocDate      
UNION ALL      
SELECT '''' AS DocID,@FDATE DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Closing Balance'' AccountName,      
(CASE WHEN @CBType = ''Cr'' THEN ABS(@CBVALUE) ELSE 0 END) AS Credit,      
(CASE WHEN @CBType = ''Dr'' THEN ABS(@CBVALUE) ELSE 0 END) AS Debit,      
'''' Balance,      
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo --FROM #temp WHERE DocDate = @FDATE      
      
SET @FDATE = DATEADD(DD,1,@FDATE)      
END      
END      
ELSE      
BEGIN      
DECLARE @FinVal DECIMAL(25,6)      
      
select @FinVal = (SUM(Debit)-SUM(Credit))+@ReturnValue from #temp      
PRINT ''FinVal : '' +CONVERT(NVARCHAR,@FinVal)      
INSERT INTO #MAINTEMP      
SELECT '''' AS DocID,@FromDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Opening Balance'' AccountName,      
(CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) ELSE 0 END) AS Credit,      
(CASE WHEN @ReturnValue > 0 THEN ABS(@ReturnValue) ELSE 0 END) AS Debit,'''' Balance,      
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
UNION ALL      
select DocID,DocDate,DocRef,UDFDocId,TranName,AccountName,Credit,Debit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,      
JVID,ChequeInfo from #temp      
UNION ALL      
SELECT '''' AS DocID,@ToDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Total'' AccountName,      
(CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + SUM(Credit) ELSE SUM(Credit) END) AS Credit,      
(CASE WHEN @ReturnValue > 0 THEN ABS(@ReturnValue) + SUM(Debit) ELSE SUM(Debit) END) AS Debit,'''' Balance,      
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
FROM #temp      
UNION ALL      
SELECT '''' AS DocID,@ToDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Closing Balance'' AccountName,      
(CASE WHEN @FinVal < 0 THEN ABS(@FinVal)ELSE 0 END) AS Credit,      
(CASE WHEN @FinVal > 0 THEN ABS(@FinVal)ELSE 0 END) AS Debit,      
'''' Balance,'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo      
END      
select case when AccountName = ''Opening Balance'' then 1 when AccountName = ''Total'' then 3  when AccountName = ''Closing Balance'' then 4 else 2 end idx,
ISNULL(MT.DocPrefix,0) DocPrefix,ISNULL(MT.DocValue,0) DocValue,MT.NoteID,MT.JVID,MBO.Name BranchName,MT.DocID [DocID],      
FORMAT(MT.DocDate,''dd-MMM-yyyy'') [DocDate],MT.DocRef [Ref No],TranName [Transaction Name],      
AccountName [Account Name],dbo.fnGetRoundedValue(ABS(ISNULL(MT.Debit,0))) Debit,dbo.fnGetRoundedValue(ABS(ISNULL(MT.Credit,0))) Credit,MT.Balance      
,MT.Remarks,MT.Narration,MT.ChequeInfo from #MAINTEMP  MT  
LEFT JOIN tblFAJournal FAJ ON FAJ.DocPrefix = MT.DocPrefix AND FAJ.DocValue = MT.DocValue AND FAJ.DocDate = MT.DocDate  
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = FAJ.BranchID  
GROUP BY  
    ISNULL(MT.DocPrefix,0),  
    ISNULL(MT.DocValue,0),  
    MT.NoteID,  
    MT.JVID,  
    MT.DocID,  
    FORMAT(MT.DocDate,''dd-MMM-yyyy''),  
    MT.DocRef,  
    TranName,  
    AccountName,  
    dbo.fnGetRoundedValue(ABS(ISNULL(MT.Debit,0))),  
    dbo.fnGetRoundedValue(ABS(ISNULL(MT.Credit,0))),  
    MT.Balance,  
    MT.Remarks,  
    MT.Narration,  
    MT.ChequeInfo,  
    MBO.Name  
ORDER BY idx,DocDate ASC      
drop table #TP,#CopyOfLedger,#tempData,#temp,#DOCWISE,#getCB,#MAINTEMP,#getOB      
end',
N'[export] nocount';
GO
/****** uspFinRepDayBook ******/
EXEC #Apply07 N'dbo.uspFinRepDayBook', 0x77E86FFEE79ABED60FA372A8D3CBA016438E83DDFF1B5213DBFE09069F73543F, NULL, NULL, 0x0B6A935CC1D5BA2F4382DDC9A48429F9DFEFE72C013173A6D946A669AE1D348F, 0xDE8BD85CBB079EF009ACE5A6E3F0ED1FD2DBE41C8210537A1D6319BD6AFDDC07, NULL,
N'--uspFinRepDayBook 4      
ALTER proc [dbo].[uspFinRepDayBook]          
@BranchID int,@FromDate DATE = ''2026-01-01'',@ToDate DATE = ''2026-01-31'',@ShowGroupBy INT =0  ,@ShowDateWise INT = 0    
as          
SET NOCOUNT ON;
begin          
CREATE TABLE #MAINTEMP(Idx int,DocID NVARCHAR(255),DocDate date, DocRef NVARCHAR(255),TranName NVARCHAR(255),AccountName NVARCHAR(255),Debit DECIMAL(25,6),                    
Credit DECIMAL(25,6),Balance NVARCHAR(255),Remarks NVARCHAR(255),Narration NVARCHAR(255), DocPrefix NVARCHAR(255),DocValue NVARCHAR(255),                    
NoteID INT,JVID INT ,ChequeInfo NVARCHAR(255))                    
              
SELECT ROW_NUMBER()                  
OVER (ORDER BY DocDate,NoteID) AS RowID,DocDate,DocID,DocRef,                  
DocPrefix,AccountID,Debit,Credit,Remarks,Narration,DocValue,NoteID,JVID,ChequeInfo INTO #CopyOfJournal FROM dbo.tblFAJournal                  
WHERE DocDate BETWEEN @FromDate AND @ToDate AND BranchID = @BranchID AND Status NOT IN (2,4,8) Order BY DocDate ASC,NoteID  ASC                
CREATE INDEX idx_RID ON #CopyOfJournal(RowID)                
              
  select dense_rank()                  
OVER (ORDER BY docprefix,docvalue,jvid) AS RankID,(OriginalTable.Debit) Debit,(OriginalTable.Credit) Credit,              
0 AS Balance,OriginalTable.DocPrefix,                  
OriginalTable.DocValue,OriginalTable.NoteID,OriginalTable.JVID into #cp FROM #CopyOfJournal OriginalTable              
--INNER JOIN #CopyOfJournal Temporary ON OriginalTable.RowID >= Temporary.RowID              
group by OriginalTable.DocPrefix,                  
OriginalTable.DocValue,OriginalTable.NoteID,OriginalTable.JVID,OriginalTable.Debit,OriginalTable.Credit,OriginalTable.RowID              
Order BY OriginalTable.RowID ASC               
              
CREATE TABLE #DOCWISE(DInt INT IDENTITY(1,1),Deb DECIMAL(25,6),Cre DECIMAL(25,6),Bals NVARCHAR(50),Df INT,DV INT,NID INT,JID INT)              
CREATE TABLE #DOCWISEBAL(Bals NVARCHAR(50),Df INT,DV INT,NID INT,JID INT)              
--SELECT * FROM #cp ORDER BY RankID              
declare @cpTC int = (select count(distinct RankID) from #cp),@incr INT = 1,@InitialDr DECIMAL(25,6)              
DECLARE @DCCount int,@DCincr INT = 1,@DCCr  DECIMAL(25,6)              
WHILE(@cpTC >= @incr)              
BEGIN              
SELECT @InitialDr = SUM(Debit) FROM #cp WHERE RankID = @incr              
INSERT INTO #DOCWISE              
SELECT Debit,Credit * -1, '''' BAL,DocPrefix,DocValue,NoteID,JVID FROM #cp WHERE RankID = @incr              
SET @DCCount =(select count(*) from #DOCWISE) SET @DCincr  = 1              
WHILE(@DCCount >= @DCincr)              
BEGIN              
SELECT @DCCr = Cre FROM #DOCWISE WHERE DInt = @DCincr              
INSERT INTO #DOCWISEBAL              
SELECT case when @InitialDr >= @DCCr THEN CONVERT(NVARCHAR(50),dbo.fnGetRoundedValue(@InitialDr + @DCCr)) + '' Dr'' ELSE               
CONVERT(NVARCHAR(50),dbo.fnGetRoundedValue(@InitialDr + @DCCr)) + '' Cr'' END BAL,Df,DV,NID,JID  FROM #DOCWISE WHERE DInt = @DCincr              
SET @InitialDr =  @InitialDr + @DCCr              
SET @DCincr = @DCincr + 1;              
END              
TRUNCATE TABLE #DOCWISE              
--PRINT CONVERT(NVARCHAR,@InitialDr)              
SET @incr = @incr + 1;              
END              
--SELECT * FROM #DOCWISE              
              
SELECT OriginalTable.DocDate,OriginalTable.DocID,OriginalTable.DocRef,Doc.TransName TranName,              
tblFAAccount.AccountName,(OriginalTable.Debit) Debit,(OriginalTable.Credit) Credit,DWB.Bals AS Balance,              
OriginalTable.Remarks,OriginalTable.Narration ,OriginalTable.DocPrefix,              
OriginalTable.DocValue,OriginalTable.NoteID,OriginalTable.JVID ,OriginalTable.ChequeInfo INTO #MM                  
FROM #CopyOfJournal OriginalTable              
--INNER JOIN #CopyOfJournal Temporary ON OriginalTable.RowID >= Temporary.RowID                 
JOIN  #DOCWISEBAL DWB ON DWB.NID = OriginalTable.NoteID              
JOIN tblFAAccount ON tblFAAccount.FAID=OriginalTable.AccountID                  
JOIN tblDocumentSeries Doc ON Doc.TransID=OriginalTable.DocPrefix              
Order BY OriginalTable.RowID ASC                 
IF(@ShowDateWise = 1)                    
BEGIN       
DECLARE @FDATE DATE = @FromDate,@TDATE DATE = @ToDate                    
WHILE @FDATE <= @TDATE                    
BEGIN                    
INSERT INTO #MAINTEMP              
SELECT 1,DocID,DocDate,DocRef,TranName,AccountName,Debit,Credit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,JVID,ChequeInfo                    
FROM #MM WHERE DocDate =  @FDATE                    
UNION ALL                    
SELECT 2,'''' AS DocID,DocDate,'''' DocRef ,'''' TranName, ''Total'' AccountName,SUM(Debit) AS Debit,SUM(Credit) AS Credit,'''' Balance,                   
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo                    
 FROM #MM WHERE DocDate =  @FDATE                    
 GROUP BY DocDate                    
ORDER BY DocDate ASC                    
SET @FDATE = DATEADD(DD,1,@FDATE)                    
END                    
END                    
ELSE                            
BEGIN                    
INSERT INTO #MAINTEMP                    
SELECT 1,DocID,DocDate,DocRef,TranName,AccountName,Debit,Credit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,JVID,ChequeInfo                    
FROM #MM                    
UNION ALL                    
SELECT 2,'''' AS DocID,@ToDate DocDate,'''' DocRef ,'''' TranName, ''Total'' AccountName,SUM(Debit) AS Debit,SUM(Credit) AS Credit,'''' Balance,                    
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo                    
 FROM #MM                    
--ORDER BY DocDate,DocValue                    
END                    
IF(ISNULL(@ShowGroupBy,0) = 0)            
begIN            
SELECT MT.DocPrefix,MT.DocValue,MT.NoteID,MT.JVID,MBO.Name BranchName,MT.DocID [DocID],  
FORMAT(MT.DocDate,''dd-MMM-yyyy'') [DocumentDate],MT.DocRef [Doc Ref No],TranName [Transaction Name],                    
AccountName [Account Name],dbo.fnGetRoundedValue(MT.Debit) Debit,dbo.fnGetRoundedValue(MT.Credit) Credit,MT.Balance                    
,MT.Remarks,MT.Narration,MT.ChequeInfo  FROM #MAINTEMP MT  
LEFT JOIN tblFAJournal FAJ ON FAJ.DocPrefix = MT.DocPrefix AND FAJ.DocValue = MT.DocValue AND FAJ.DocDate = MT.DocDate  
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = FAJ.BranchID  
GROUP BY MT.DocPrefix,MT.DocValue,MT.NoteID,MT.JVID,MT.DocID,MT.DocDate,MT.DocRef,TranName,                    
AccountName,dbo.fnGetRoundedValue(MT.Debit),dbo.fnGetRoundedValue(MT.Credit),MT.Balance                    
,MT.Remarks,MT.Narration,MT.ChequeInfo,MBO.Name  
ORDER BY MT.DocDate,JVID,NoteID--,DocValue                    
END            
ELSE            
BEGIN            
SELECT DocPrefix,DocValue,NoteID,JVID,[DocID],BranchName,FORMAT(DocDate,''dd-MMM-yyyy'') [DocumentDate],[Doc Ref No],[Transaction Name],[Account Name],            
dbo.fnGetRoundedValue(SUM(Debit)) Debit,dbo.fnGetRoundedValue(SUM(Credit)) Credit,Balance,Remarks,Narration,            
ChequeInfo FROM (            
SELECT Idx,MT.DocID [DocID],MT.DocDate,MT.DocRef [Doc Ref No],TranName [Transaction Name],                    
case when AccountName = ''Total'' then AccountName else '''' end [Account Name],(SUM(MT.Debit)) Debit,(SUM( MT.Credit)) Credit,''0.00 Dr'' Balance                    
, MT.Remarks, MT.Narration, MT.DocPrefix, MT.DocValue,0 NoteID,0 JVID,''''ChequeInfo,MBO.Name BranchName  FROM #MAINTEMP MT  
LEFT JOIN tblFAJournal FAJ ON FAJ.DocPrefix = MT.DocPrefix AND FAJ.DocValue = MT.DocValue AND FAJ.DocDate = MT.DocDate  
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = FAJ.BranchID  
group by MT. DocID, MT.DocDate,MBO.Name, MT.DocRef,TranName, MT.Remarks, MT.DocPrefix, MT.DocValue, MT.ChequeInfo, MT.Narration,AccountName,Idx) AS REC            
GROUP BY [DocID],DocDate,[Doc Ref No],[Transaction Name],[Account Name],Balance,Remarks,Narration,            
DocPrefix,DocValue,NoteID,JVID,ChequeInfo,Idx,BranchName            
ORDER BY Idx,DocDate,JVID,NoteID --,DocValue              
END            
DROP TABLE #CopyOfJournal ,#MM,#MAINTEMP  ,#cp,#DOCWISE,#DOCWISEBAL          
end',
N'[export] nocount';
GO
/****** uspFinRepDetailedTrailBalance ******/
EXEC #Apply07 N'dbo.uspFinRepDetailedTrailBalance', 0x5B3519C3F894CB3C3EE4081ADF76B8B2E95DBB994BE766154F96385C63F6EEAB, 0x789A56DDEBA5069056AB0008698F51E904462D1E9FD9B1A5D240E872E8EE24FB, NULL, 0x25D3FE222EFEDAA4E812A1069451443E75CD920BDFBBCBD175A70E8A7E4F3474, 0xB08CDC70578DB5B0DE70EC0F2CC99F5028026D611B64D0CCAC1E1F7179DFF31A, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspFinRepDetailedTrailBalance] 
@BranchID int = 4,@Fromdate date = ''2025-09-01'',@ToDate date = ''2026-11-30''
as
SET NOCOUNT ON;
BEGIN
DECLARE @STRQRY NVARCHAR(MAX),@STRQRYJOIN NVARCHAR(MAX) = '''',@STRACCGRPNAME NVARCHAR(MAX)= '''',@STRGBY NVARCHAR(MAX)= '''',  
@SELCOLNM NVARCHAR(MAX) = '''',@TBLID INT = 0,@SelID INT ,@GETCOLNM NVARCHAR(255) = '''',@CombainCol NVARCHAR(MAX) = '''',  
@OPENAMT DECIMAL(25,6)  
SELECT @OPENAMT = [dbo].[fnGetRoundedValue](SUM(ISNULL(SaleStockValue + DmgStockValue,0)))      
FROM tblClosingStock WHERE ClsDate= DATEADD(DAY, -1, @Fromdate)        
declare @MaxLevel INT =(select MAX(LevelID) from tblFAGroup)  
SET @SelID = @MaxLevel  
WHILE(@MaxLevel >= 1)  
BEGIN  
SET @GETCOLNM = ''FAGPAR''+CONVERT(NVARCHAR,@SelID)   
SET @CombainCol +=  @GETCOLNM + ''+ (CASE WHEN ISNULL(''+@GETCOLNM+'','''''''') = '''''''' THEN '''''''' ELSE ''''->'''' END) +''  
SET @SELCOLNM += @GETCOLNM +'',''  
SET @STRGBY += '' FAG''+CONVERT(NVARCHAR,@SelID)+''.AccountGroupName,''  
SET @STRACCGRPNAME += '' ISNULL(FAG''+CONVERT(NVARCHAR,@SelID)+''.AccountGroupName,'''''''') AS FAGPAR''+CONVERT(NVARCHAR,@SelID) +'',''  
SET @STRQRYJOIN += '' left JOIN tblFAGroup FAG''+CONVERT(NVARCHAR,@TBLID+1)+'' ON FAG''+CONVERT(NVARCHAR,@TBLID+1)+''.FAGroup = FAG''+CONVERT(NVARCHAR,@TBLID)+''.ParentGroup  ''  
SET @MaxLevel = @MaxLevel - 1;  
SET @TBLID = @TBLID + 1;  
SET @SelID = @SelID - 1;  
END  
  
SET @STRQRY = ''SELECT * FROM (SELECT AccountID,[Account Type],''+@CombainCol+''AccountGroupName [Account Group],AccountName [Account Name],  
dbo.fnGetRoundedValue(case when SUM(Debit - Credit) >= 0 THEN  SUM(Debit - Credit) ELSE 0 END) Debit,        
dbo.fnGetRoundedValue(case when SUM(Debit - Credit) < 0 THEN  SUM(Credit - Debit) ELSE 0 END) Credit FROM(''  
SET @STRQRY += ''SELECT AccountID,[Account Type],''+@SELCOLNM+''AccountGroupName,AccountName,case when SUM(openbal) < 0 then SUM(Credit + abs(openbal)) else SUM(Credit) end  Credit,        
case when SUM(openbal) >= 0 then SUM(Debit + openbal) else SUM(Debit) end Debit FROM (SELECT FAJ.AccountId AccountID,TypeName [Account Type],''+ @STRACCGRPNAME+'' isnull(FAG0.AccountGroupName,'''''''') AccountGroupName,FAA.AccountName,        
SUM(Credit) Credit,SUM(Debit) Debit,0 openbal FROM tblFAJournal FAJ        
JOIN tblFAAccount FAA ON FAA.FAID = FAJ.AccountID        
JOIN tblFAGroup FAG0 ON FAG0.FAGroup = FAA.AccountGroup  
LEFT JOIN tblAccountType AT ON AT.TypeId=FAG0.TypeID''  
SET @STRQRY += @STRQRYJOIN  
SET @STRQRY += ''WHERE Status IN (1,3,5,6,7,9) AND DocDate BETWEEN ''+'' @Fromdate ''+'' AND ''+'' @ToDate ''  
SET @STRQRY += '' GROUP BY ''+@STRGBY+''FAG0.AccountGroupName,FAA.AccountName,TypeName,FAJ.AccountId''  
SET @STRQRY += '' ) AS REC group by AccountID,[Account Type],''+@SELCOLNM+''AccountGroupName,AccountName''  
SET @STRQRY += '' union all ''  
SET @STRQRY += '' SELECT AccountID,[Account Type],''+@SELCOLNM+''AccountGroupName,AccountName,case when SUM(openbal) < 0 then SUM(Credit + abs(openbal)) else SUM(Credit) end  Credit,        
case when SUM(openbal) >= 0 then SUM(Debit + openbal) else SUM(Debit) end Debit FROM (  
SELECT FAA.FAID AccountID,TypeName [Account Type],''+ @STRACCGRPNAME+'' isnull(FAG0.AccountGroupName,'''''''') AccountGroupName,FAA.AccountName,        
0 Credit,0 Debit,CASE WHEN FAA.FAID = 60 then ''+CONVERT(nvarchar(255),@OPENAMT)+'' else dbo.[uspReturnOpeningBalance]( @BranchID ,FAA.FAID,''+'' @Fromdate ''+'') end openbal 
FROM tblFAAccount FAA  
JOIN tblFAGroup FAG0 ON FAG0.FAGroup = FAA.AccountGroup  
LEFT JOIN tblAccountType AT ON AT.TypeId=FAG0.TypeID''  
SET @STRQRY += @STRQRYJOIN  
SET @STRQRY += '' GROUP BY ''+@STRGBY+''FAG0.AccountGroupName,FAA.AccountName,TypeName,FAA.FAID''  
SET @STRQRY += '' ) AS REC WHERE ISNULL(openbal,0) <> 0 group by AccountID,[Account Type],''+@SELCOLNM+''AccountGroupName,AccountName''  
SET @STRQRY += '') AS REC1 GROUP BY  ''+@SELCOLNM+''AccountID,[Account Type],AccountGroupName,AccountName ''  
SET @STRQRY += '' ) AS REC2 ORDER BY [Account Type],[Account Group],[Account Name]''  
EXEC sys.sp_executesql @STRQRY, N''@BranchID int, @Fromdate date, @ToDate date'', @BranchID, @Fromdate, @ToDate  
END',
N'[06] nocount';
GO
/****** uspFinRepDetailedTrailBalanceType2 ******/
EXEC #Apply07 N'dbo.uspFinRepDetailedTrailBalanceType2', 0x13E0B1B75226D868DE68C5FDE34E7E8A2DB64B8BE73C57E62892F165EA38C7E8, NULL, NULL, 0x6CA6558E2EE3A49D9C1A9AED94307D4A347D244A29A21E2ED47B913E01825C7E, 0x59DD05D263FF2807756E692069A869D0EF53B9F3ED9894A4210DDC3F70652127, NULL,
N'ALTER PROC [dbo].[uspFinRepDetailedTrailBalanceType2]  
@Mode INT = 1,@BranchID INT = 4  ,@Fromdate date = ''2025-09-01'',@ToDate date = ''2026-11-30''  
as  
SET NOCOUNT ON;
begin  
create table #tblFA(ID INT IDENTITY(1,1),AccGrpID INT,AccID INT,AccGrpName NVARCHAR(255),AccName NVARCHAR(255))        
create table #TEMP(AccGrpID INT,AccID INT,AccGrpName NVARCHAR(255),AccName NVARCHAR(255),Debit DECIMAL(25,6),Credit DECIMAL(25,6))        
CREATE TABLE #ClsBal(Bal DecIMAL(25,6),crdrType NVARCHAR(10))        
DECLARE @Date DATE = @ToDate    
--CLOSING BAL OR OPENING BAL    
DECLARE @BalType INT = (CASE WHEN @Mode = 1 THEN 1 else 2 END)    
INSERT INTO #tblFA        
select FAGroup,FAID,AccountGroupName,AccountName from tblFAAccount FA        
JOIN tblFAGroup FAG ON FAG.FAGroup = FA.AccountGroup        
DECLARE @nIncr INT = 1,@Cr DECIMAL(25,6) = 0,@Dr DECIMAL(25,6) = 0,@AccGrpID INT = 0,@AccID INT = 0,@AccGrpName NVARCHAR(255) = '''',        
@AccName NVARCHAR(255) = '''',@AccAmt DECIMAL(25,6)    
--    
DECLARE @nCount INT = (select COUNT(*) from #tblFA)        
WHILE(@nCount >= @nIncr)        
BEGIN        
SELECT @AccGrpID=AccGrpID,@AccID = AccID,@AccName = AccName,@AccGrpName = AccGrpName FROM #tblFA WHERE ID = @nIncr        
IF(@Mode = 1)    
BEGIN    
INSERT INTO #ClsBal        
exec [uspFAAccOpenCloseBalance] @BalType,@AccID,@BranchID,@Date        
END    
ELSE    
BEGIN    
EXEC uspGetOpeningBalance @BranchID,@AccID,@Fromdate,@AccAmt OUTPUT    
INSERT INTO #ClsBal VALUES(ABS(@AccAmt),CASE WHEN @AccAmt >=0 THEN ''Cr'' ELSE ''Dr'' END)    
END    
SELECT @Cr = (case WHEN crdrType = ''Cr'' THEN Bal ELSE 0 END),@Dr = (case WHEN crdrType = ''Dr'' THEN Bal ELSE 0 END) from #ClsBal        
INSERT INTO #TEMP VALUES(@AccGrpID,@AccID,@AccGrpName,@AccName,@Dr,@Cr)        
SET @nIncr = @nIncr + 1;        
TRUNCATE TABLE #ClsBal        
END        
SELECT AccGrpID,AccID,AccGrpName,AccName,dbo.funTwoDecimalRoundOff(Debit) Debit,dbo.funTwoDecimalRoundOff(Credit) Credit FROM #TEMP WHERE (Debit > 0 OR Credit > 0)        
ORDER BY AccGrpID,AccGrpName        
DROP TABLE #TEMP,#tblFA,#ClsBal          
end',
N'[export] nocount';
GO
/****** uspFinRepGroupLedger ******/
EXEC #Apply07 N'dbo.uspFinRepGroupLedger', 0xC063F37344A37661C2E87E000AED281946F5C284547E570A93F9E4D8E6D78DF4, NULL, NULL, 0xD5CEFBDA83E52EFAF2B63A1A1DE32209E8E37CEC75658ED39F9750EF4A55F1F2, 0x2B0EA6F744C0379580DBB8C08733ADD97969D006260E14DA3C4C500C0D801BFB, NULL,
N'--uspFinRepGroupLedger 19,0,''''      
--uspFinRepGroupLedger 0,''Current Assets''      
--uspFinRepGroupLedger 0,''Cash in Hand''      
--uspFinRepGroupLedger 0,''Cash''      
ALTER proc [dbo].[uspFinRepGroupLedger]        
@ReportID INT=15,@BranchID INT = 0,@AccountGroupName nvarchar(255)='''',@FromDate DATE = ''2026-02-01'',        
@ToDate DATE = ''2026-02-17'',@Mode INT =0        
as        
SET NOCOUNT ON;
begin        
  
declare @AccGroupID int        
select @AccGroupID = FAGroup from tblFAGroup where AccountGroupName = @AccountGroupName        
declare @GlobalDate DATE = GETDATE()        
IF ISNULL(@AccGroupID,0)!=0                  
BEGIN                  
PRINT ''ACC GRP ID : ''+CONVERT(NVARCHAR,@AccGroupID)            
-- If Mode => Opening Trial Balance Reduce 1 Day                   
--IF ISNULL(@Mode,0)=3 AND ISNULL(@ReportID,0)=19                  
--BEGIN                  
--SET @ToDate=DATEADD(DAY,-1,@ToDate)                  
--END                  
-- This Table Used For Geting Next Child Level Data Only                  
CREATE TABLE #tempLevel(IDENT INT IDENTITY(1,1),AccGrID INT,AccGrName NVARCHAR(255))                  
DECLARE @StockAmt DECIMAL (25,6), @AccAmt DECIMAL (25,6)                  
declare @fajbal decimal(25,6)              
-- Move Value Into #TempLevel Table From AccountGroup Table Based On Parent Acc Which Is Choosen By User                  
INSERT INTO #tempLevel                  
SELECT FAG.FAGroup,FAG.AccountGroupName FROM tblFAGroup FAG WHERE ParentGroup=@AccGroupID                  
-- @ChildRowCount => Initialize ChildGroups Count                  
-- @ChildGrID => Get ChildGroup ID                  
-- @ChildGrName => Get ChildGroup Name                  
DECLARE @ChildRowCount INT=1,@ChildGrID INT,@ChildGrName NVARCHAR(255)                  
-- Finally We Get OutPut From This Table Here Declaration Only                  
-- Here Balance Column Contains Child Group Closing Balance For To Date.                  
-- Group Has Account''s So That Closing Balance Stored In That Column                  
-- AccType Column Is Differenciate Which Is Account Group Or Account Name                  
DECLARE @MainTable TABLE(AccGroupID INT, AccGroupName NVARCHAR(255),Balance DECIMAL (25,6),AccType NVARCHAR(50))                  
-- Just Declare Variable                  
DECLARE @OpeningBalance DECIMAL (25,6)=0.00,@TempAccID INT,@TempBalance DECIMAL (25,6),@FaType NVARCHAR(10)                  
-- Getting Total Child''s For Given Parent Group                  
DECLARE @TotalRow INT=(SELECT COUNT(AccGrID) FROM #tempLevel)                  
PRINT ''@TotalRow : ''+CONVERT(NVARCHAR,@TotalRow)            
WHILE @ChildRowCount<=@TotalRow                  
BEGIN                  
-- Initialze The Variable Value WIth Default                  
SET @OpeningBalance=0.00                  
SELECT @ChildGrID=AccGrID,@ChildGrName=AccGrName FROM #tempLevel WHERE IDENT=@ChildRowCount;                  
-- Table For Storing Child Group For Given Group                  
CREATE TABLE #TempAccID (GroupIdent INT IDENTITY(1,1),AccGroupID INT,AccGroupName NVARCHAR(255));                  
CREATE TABLE #TEMP1(AccGrID int,AccGrName nvarchar(255),AccPGroup int,LevelData int)                  
                  
INSERT into  #TEMP1                  
SELECT FAG.FAGroup,FAG.AccountGroupName,FAG.ParentGroup,0                  
FROM tblFAGroup FAG                  
WHERE ParentGroup=@ChildGrID                  
cREATE TABLE #TEMP2(AccGrID int,AccGrName nvarchar(255),AccPGroup int,LevelData int)                  
INSERT into  #TEMP2                  
SELECT FA.FAGroup,FA.AccountGroupName,FA.ParentGroup,#TEMP1.LevelData+1 FROM tblFAGroup FA                  
INNER JOIN #TEMP1                  
ON #TEMP1.AccGrID=FA.ParentGroup                  
                  
CREATE TABLE #AccGroup2(AccGrID int,AccGrName nvarchar(255),AccPGroup int,LevelData int)                  
INSERT INTO  #AccGroup2                  
select AccGrID,AccGrName,AccPGroup,LevelData from (                  
SELECT * FROM #TEMP1                  
UNION       
SELECT * FROM #TEMP2                  
)as sasi                  
DROP TABLE  #TEMP1                  
DROP TABLE  #TEMP2                  
                  
-- Move Child Groups into Temp Table                  
INSERT INTO #TempAccID SELECT AccGrID,AccGrName FROM #AccGroup2                  
INSERT INTO #TempAccID VALUES(@ChildGrID,@ChildGrName)                  
drop table #AccGroup2                  
-- Initialise The Group ROws Count                  
DECLARE @GroupRow INT=1                  
-- Getting Total Group Rows Against Given Group                  
DECLARE @TotalGroupRow INT=(SELECT COUNT(AccGroupID) FROM #TempAccID)                  
-- Iterate All The Groups One By One                  
WHILE @GroupRow<=@TotalGroupRow                  
begin          DECLARE @AccGroupName NVARCHAR(255),@AccountGroupID INT                  
SELECT @AccountGroupID=AccGroupID,@AccGroupName=AccGroupName FROM #TempAccID WHERE GroupIdent=@GroupRow                  
CREATE TABLE  #AccTable (IdentAcc INT IDENTITY(1,1),AccID INT)                  
INSERT INTO #AccTable SELECT FAID FROM tblFAAccount WHERE AccountGroup=(SELECT AccGroupID FROM #TempAccID WHERE GroupIdent=@GroupRow)                  
                  
DECLARE @AccRow INT=1      DECLARE @TotalAccRow INT=(SELECT COUNT(AccID) From #AccTable)                  
WHILE @AccRow<=@TotalAccRow                  
BEGIN                  
SELECT @TempAccID=AccID FROM #AccTable WHERE IdentAcc=@AccRow                  
-- Check Closing Stock Or Opening Stock                  
IF @TempAccID=21 OR @TempAccID=60                  
BEGIN                  
IF @TempAccID=21                  
BEGIN                  
-- Dont Add Closing Stock Amt in Traial Balance                  
-- 19 => Traial Balance                  
-- 73 => Opening Stock                  
IF NOT(ISNULL(@ReportID,0)=19 AND @AccountGroupID=72)                  
BEGIN                  
EXEC uspGetClosingStockAmt @BranchID, @ToDate,@GlobalDate,@StockAmt OUTPUT                  
--IF ISNULL(@StockAmt,0)<0                  
--BEGIN                  
IF ISNULL(@ReportID,0)=20                  
BEGIN                  
SET @OpeningBalance=ABS(@StockAmt)+@OpeningBalance                  
END                  
ELSE                  
BEGIN                  
SET @OpeningBalance=(-1*@StockAmt)+@OpeningBalance                  
END                  
--END                  
--ELSE                  
--BEGIN                  
--SET @OpeningBalance=@StockAmt+@OpeningBalance                  
--END                  
END                  
END                  
IF @TempAccID=60                  
BEGIN                  
-- Dont Add Opening Stock Amt in Traial Balance                  
-- 20 => Balance Sheet                  
-- 72 => Closing Balance                  
IF NOT(ISNULL(@ReportID,0)=20 AND @AccountGroupID=73)                  
BEGIN                  
-- Alter by Ganga (Opening balance only for Trail balance with opening balance)                  
IF ISNULL(@Mode,0)!=2                  
BEGIN                  
EXEC uspGetOpeningStockAmt @BranchID,@FromDate,@StockAmt  OUTPUT                  
IF ISNULL(@StockAmt,0)<0                  
BEGIN                  
SET @OpeningBalance=(-1*@StockAmt)+@OpeningBalance                  
END                  
ELSE                  
BEGIN                  
SET @OpeningBalance=@StockAmt+@OpeningBalance                  
END                  
END                  
END                  
END                  
ENd                 
ELSE                  
BEGIN                  
CREATE TABLE #tblClosingBal(Balance DECIMAL (25,6),FAType NVARCHAR(10))                  
INSERT INTO #tblClosingBal EXEC uspLoadClosingBalance 1,@TempAccID,@ToDate                  
SELECT @TempBalance=Balance,@FaType=FAType FROM #tblClosingBal                 
if(@Mode != 4)--- CHANGE HERE....BEGIN              
BEGIN               
IF ISNULL(@FaType,'''')=''Cr''                  
BEGIN                  
SET @OpeningBalance=(-1*@TempBalance)+@OpeningBalance                  
END                  
ELSE         
BEGIN                  
SET @OpeningBalance=@TempBalance+@OpeningBalance                  
END                  
END              
ELSE              
BEGIN              
PRINT ''MODE 4 - WITH SPEIFIY DATE (Acc Group Basec)''              
              
CREATE TABLE #tblFAJBAL(Debit DECIMAL (25,6),Credit DECIMAL (25,6),Balance DECIMAL (25,6),CrDrin int)               
INSERT INTO #tblFAJBAL EXEC uspGetFAJBalbyAccID @BranchID,@TempAccID,@FromDate,@ToDate              
select @fajbal = SUM(Balance) from #tblFAJBAL              
SET @OpeningBalance= @fajbal+@OpeningBalance               
DROP TABLE #tblFAJBAL                
END              
IF ISNULL(@Mode,0)=2                  
BEGIN                  
SET @AccAmt=0.00                  
EXEC uspGetOpeningBalance @BranchID,@TempAccID,@FromDate,@AccAmt OUTPUT        
SET @OpeningBalance= @AccAmt+@OpeningBalance                  
END              
print ''Acc ID : ''+convert(nvarchar,@TempAccID)+'' ,Closing Bal : ''+convert(nvarchar,@TempBalance)              
DROP TABLE #tblClosingBal                  
END                  
SET @AccRow=@AccRow+1                  
END                  
DROP TABLE #AccTable                  
                  
SET @GroupRow=@GroupRow+1                  
END                  
DROP TABLE #TempAccID                  
-- Dont Add Closing Stock ANd Opening Stock Group For Trial Balance ANd Balance Sheet                  
PRINT ''CHILD GRP ID : ''+CONVERT(NVARCHAR,@ChildGrID)            
IF (ISNULL(@ChildGrID,0)!=72 AND ISNULL(@ReportID,0)!=20)  OR (ISNULL(@ChildGrID,0)!=73 AND ISNULL(@ReportID,0)!=19)                  
BEGIN              
PRINT ''0. Dont add CS & OS for Trail Bal , P&L - ''+@ChildGrName+'' Value : ''+convert(nvarchar,@OpeningBalance)              
INSERT INTO @MainTable VALUES(@ChildGrID,@ChildGrName,[dbo].[fnGetRoundedValue](ISNULL(ISNULL(@OpeningBalance,0),0)),''Group'')                  
END                  
SET @ChildRowCount=@ChildRowCount+1                  
END                  
DROP TABLE #tempLevel                  
-- Get Account Detail Against Selected Group                  
CREATE TABLE  #AccForSelectedGp (IdentAcc INT IDENTITY(1,1),AccID INT,AccName NVARCHAR(255))                  
INSERT INTO #AccForSelectedGp SELECT FAID,AccountName FROM tblFAAccount WHERE AccountGroup=@AccGroupID                  
DECLARE @SelectedGroupAcc INT=1                  
DECLARE @TotalSelectedGroupAcc INT=(SELECT COUNT(AccID) From #AccForSelectedGp)                  
PRINT ''@TotalSelectedGroupAcc : ''+CONVERT(NVARCHAR,@TotalSelectedGroupAcc)            
WHILE @SelectedGroupAcc<=@TotalSelectedGroupAcc                  
BEGIN                  
-- Initialze The Variable Value WIth Default                  
SET @OpeningBalance=0.00                  
DECLARE @AccountID INT,@AccountName NVARCHAR(255)                  
SELECT @TempAccID=AccID,@AccountID=AccID,@AccountName=AccName FROM #AccForSelectedGp WHERE IdentAcc=@SelectedGroupAcc                  
-- Checking Closing Stock Or Opening Stock                  
IF @AccountID=21 OR @AccountID=60                  
BEGIN                  
SET @StockAmt=0;                  
IF @AccountID=21                  
BEGIN                  
-- Dont Add Closing Stock Amt in Traial Balance                  
-- 19 => Traial Balance                  
IF NOT(ISNULL(@ReportID,0)=19  AND @AccountGroupID=72)                  
BEGIn                  
EXEC uspGetClosingStockAmt @BranchID, @ToDate,@GlobalDate,@StockAmt OUTPUT                  
                  
--IF ISNULL(@StockAmt,0)<0                  
--BEGIN                  
IF ISNULL(@ReportID,0)=20                  
BEGIN                  
SET @OpeningBalance=ABS(@StockAmt)+@OpeningBalance                  
END                  
ELSE                  
BEGIN                  
                  
SET @OpeningBalance=(-1*@StockAmt)+@OpeningBalance                  
END                  
--END                  
--ELSE                  
--BEGIN                  
-- SET @OpeningBalance=@StockAmt+@OpeningBalance                  
--END                  
print ''1. Acc Name : ''+@AccountName+'' Value : ''+convert(nvarchar,@OpeningBalance)              
INSERT INTO @MainTable VALUES(@AccountID,@AccountName,ISNULL(@OpeningBalance,0),''Account'')                  
END                  
END                  
IF @AccountID=60                  
BEGIN                  
-- Dont Add Opening Stock Amt in Traial Balance                  
-- 20 => Balance Sheet                  
IF NOT(ISNULL(@ReportID,0)=20  AND @AccountGroupID=73)           
BEGIN                  
                  
EXEC uspGetOpeningStockAmt @BranchID,@FromDate,@StockAmt OUTPUT                  
IF ISNULL(@StockAmt,0)<0                  
BEGIN                  
SET @OpeningBalance=(-1*@StockAmt)+@OpeningBalance                  
END                  
ELSE                  
BEGIN                  
SET @OpeningBalance=@StockAmt+@OpeningBalance                  
END                  
print ''2. Acc Name : ''+@AccountName+'' Value : ''+convert(nvarchar,@OpeningBalance)              
INSERT INTO @MainTable VALUES(@AccountID,@AccountName,ISNULL(@OpeningBalance,0),''Account'')                  
END                  
END                  
ENd                  
ELSE                  
BEGIN                  
PRINT ''3rd Print Part''              
CREATE TABLE #tblClosingBalAcc(Balance DECIMAL (25,6),FAType NVARCHAR(10))                  
INSERT INTO #tblClosingBalAcc EXEC uspLoadClosingBalance 1,@TempAccID,@ToDate                  
SELECT @TempBalance=Balance,@FaType=FAType FROM #tblClosingBalAcc                  
IF(@Mode != 4)              
BEGIN              
IF ISNULL(@FaType,'''')=''Cr''                  
BEGIN                  
SET @OpeningBalance=(-1*@TempBalance)+@OpeningBalance                  
END                  
ELSE                  
BEGIN                  
SET @OpeningBalance=@TempBalance+@OpeningBalance                  
END                  
END              
ELSE              
BEGIN              
PRINT ''MODE 4 - WITH SPEIFIY DATE (Account Based)''              
CREATE TABLE #tblFAJBAL1(Debit DECIMAL (25,6),Credit DECIMAL (25,6),Balance DECIMAL (25,6),CrDrin int)               
INSERT INTO #tblFAJBAL1 EXEC uspGetFAJBalbyAccID @BranchID,@TempAccID,@FromDate,@ToDate              
select @fajbal = SUM(Balance) from #tblFAJBAL1              
SET @OpeningBalance= @fajbal--+@OpeningBalance               
DROP TABLE #tblFAJBAL1                
END              
IF ISNULL(@Mode,0)=2                  
BEGIN                  
SET @AccAmt=0.00                  
EXEC uspGetOpeningBalance @BranchID,@TempAccID,@FromDate,@AccAmt OUTPUT                  
SET @OpeningBalance=@AccAmt+@OpeningBalance                  
END              
DROP TABLE #tblClosingBalAcc            
    print ''3. Acc ID : ''+convert(nvarchar,@TempAccID)+'' ,Acc Name : ''+@AccountName +'' Value : ''+convert(nvarchar,@OpeningBalance)              
            
INSERT INTO @MainTable VALUES(@AccountID,@AccountName,ISNULL(@OpeningBalance,0),''Account'')                  
END                  
SET @SelectedGroupAcc=@SelectedGroupAcc+1                  
END                  
DROP TABLE #AccForSelectedGp                  
                  
SELECT AccGroupID,AccGroupName,CASE WHEN BALANCE>0 THEN [dbo].[fnGetRoundedValue](ISNULL(Balance,0)) ELSE [dbo].[fnGetRoundedValue](0) END AS Debit,                                            
CASE WHEN BALANCE<0 THEN [dbo].[fnGetRoundedValue](ISNULL(ABS(Balance),0)) ELSE [dbo].[fnGetRoundedValue](0) END AS Credit,AccType,      
@AccGroupID SelAccGroupID,@AccountGroupName SelAccGroupName FROM @MainTable                                                              
                  
END                  
-- If Account Group Is Not Choosen                  
ELSE                  
BEGIN                  
CREATE TABLE #TempParent(IDENT INT IDENTITY(1,1),AccGrID INT,AccGrName NVARCHAR(255),AccPGroup INT)                  
DECLARE @ParentMainTable TABLE(AccGroupID INT, AccGroupName NVARCHAR(255),Balance DECIMAL (25,6),AccType NVARCHAR(50))                  
INSERT INTO #TempParent                  
SELECT FAG.FAGroup,FAG.AccountGroupName,FAG.ParentGroup FROM tblFAGroup FAG WHERE ParentGroup=0                  
DECLARE @ParentRowCount INT=1,@TopParentID INT,@TopParentName NVARCHAR(250)                  
DECLARE @ParentOpeningBalance DECIMAL (25,6)=0.00,@TempParentAccID INT,@TempParentBalance DECIMAL (25,6),@ParentFaType NVARCHAR(10)--,@Credit DECIMAL (25,6)                  
DECLARE @TotalParentRow INT=(SELECT COUNT(AccGrID) FROM #TempParent)                  
WHILE @ParentRowCount<=@TotalParentRow                  
BEGIN          
PRINT ''LOOP - 1'';          
SET @ParentOpeningBalance=0.00                  
CREATE TABLE #ParentTempAccID (GroupIdent INT IDENTITY(1,1),AccGroupID INT)                  
SELECT @TopParentID=AccGrID,@TopParentName=AccGrName FROM #TempParent WHERE IDENT=@ParentRowCount;                  
                  
CREATE TABLE #Temp4(AccGrID int,AccGrName nvarchar(255),AccPGroup int,LevelData int)                  
INSERT into  #Temp4                  
SELECT FAG.FAGroup,FAG.AccountGroupName,FAG.ParentGroup,0                  
FROM tblFAGroup FAG                  
WHERE ParentGroup=@TopParentID                    
                  
cREATE TABLE #TEMP3(AccGrID int,AccGrName nvarchar(255),AccPGroup int,LevelData int)                  
insert into  #TEMP3                  
SELECT FA.FAGroup,FA.AccountGroupName,FA.ParentGroup,#Temp4.LevelData+1 FROM tblFAGroup FA                  
INNER JOIN #Temp4                  
ON #Temp4.AccGrID=FA.ParentGroup                  
                  
                  
create table #AccGroup11(AccGrID int,AccGrName nvarchar(255),AccPGroup int,LevelData int)                  
insert into  #AccGroup11                  
select AccGrID,AccGrName,AccPGroup,LevelData from                   
(                           
sELECT * FROM #Temp4                  
UNION                  
sELECT * FROM #TEMP3                  
)as sasi                  
                  
DROP TABLE  #Temp4                  
DROP TABLE  #TEMP3                  
                  
INSERT INTO #ParentTempAccID SELECT AccGrID FROM #AccGroup11                  
INSERT INTO #ParentTempAccID VALUES(@TopParentID)                  
drop table  #AccGroup11                  
DECLARE @ParentGroupRow INT=1                  
DECLARE @TotalParentGroupRow INT=(SELECT COUNT(AccGroupID) FROM #ParentTempAccID)                  
WHILE @ParentGroupRow<=@TotalParentGroupRow                  
BEGIN          
PRINT ''LOOP - 2'';          
CREATE TABLE  #ParentAccTable (IdentAcc INT IDENTITY(1,1),AccID INT)                  
INSERT INTO #ParentAccTable SELECT FAID FROM tblFAAccount WHERE AccountGroup=(SELECT AccGroupID FROM #ParentTempAccID WHERE GroupIdent=@ParentGroupRow)                                          
                  
DECLARE @ParentAccRow INT=1                  
DECLARE @TotalParentAccRow INT=(SELECT COUNT(AccID) From #ParentAccTable)                  
WHILE @ParentAccRow<=@TotalParentAccRow                  
BEGIN          
PRINT ''LOOP - 3'';          
SET @TempParentBalance=0                  
SELECT @TempParentAccID=AccID FROM #ParentAccTable WHERE IdentAcc=@ParentAccRow                  
CREATE TABLE #tblParentClosingBal(Balance DECIMAL (25,6),FAType NVARCHAR(10))                  
INSERT INTO #tblParentClosingBal EXEC uspLoadClosingBalance 1,@TempParentAccID,@ToDate                  
                  
SELECT @TempParentBalance=Balance,@ParentFaType=FAType FROM #tblParentClosingBal                  
                  
--Alter for getting opening stock in trial balance                  
-- This is added by Ganga (AND ISNULL(@Mode,0)!=2)                  
--if isnull(@TempParentAccID,0)=60 AND ISNULL(@Mode,0)!=2  AND ISNULL(@Mode,0)!=1                  
if isnull(@TempParentAccID,0)=60 AND ISNULL(@Mode,0)=3                  
BEGIN                  
EXEC uspGetClosingStockAmt @BranchID, @Todate,@GlobalDate,@StockAmt OUTPUT                  
SET @ParentOpeningBalance=isnull(@stockamt,0)+@ParentOpeningBalance                  
end                  
Else if isnull(@TempParentAccID,0)=60  AND ISNULL(@Mode,0)=1       
BEGIN             
Declare @ToDate1 date                  
SET @ToDate1=DATEADD(DD,-1,@FromDate)                  
EXEC uspGetClosingStockAmt @BranchID, @ToDate1,@GlobalDate,@StockAmt OUTPUT                  
SET @ParentOpeningBalance=isnull(@stockamt,0)+@ParentOpeningBalance                  
END                  
ELSE                  
begin              
IF(@Mode != 4)              
BEGIN              
IF ISNULL(@ParentFaType,'''')=''Cr''                  
BEGIN                  
SET @ParentOpeningBalance=(-1*@TempParentBalance)+@ParentOpeningBalance                  
END                  
ELSE                                                              
BEGIN                  
SET @ParentOpeningBalance=@TempParentBalance+@ParentOpeningBalance                  
END                
END              
ELSE              
BEGIN              
PRINT ''MODE 4 - WITH SPEIFIY DATE (ALL Acc Grp) AccID '' +convert(nvarchar,@TempParentAccID)              
CREATE TABLE #tblFAJBAL2(Debit DECIMAL (25,6),Credit DECIMAL (25,6),Balance DECIMAL (25,6),CrDrin int)               
INSERT INTO #tblFAJBAL2 EXEC uspGetFAJBalbyAccID @BranchID,@TempParentAccID,@FromDate,@ToDate              
select @fajbal = SUM(Balance) from #tblFAJBAL2              
SET @ParentOpeningBalance= @fajbal+@ParentOpeningBalance               
DROP TABLE #tblFAJBAL2              
END              
end                  
                  
IF ISNULL(@Mode,0)=2                  
BEGIN                  
SET @AccAmt=0.00                  
EXEC uspGetOpeningBalance @BranchID,@TempParentAccID,@FromDate,@AccAmt OUTPUT                  
SET @ParentOpeningBalance=@AccAmt+@ParentOpeningBalance               
END                  
DROP TABLE #tblParentClosingBal                  
                  
SET @ParentAccRow=@ParentAccRow+1                  
END                  
DROP TABLE #ParentAccTable                  
                  
SET @ParentGroupRow=@ParentGroupRow+1                  
END                  
DROP TABLE #ParentTempAccID                  
INSERT INTO @ParentMainTable VALUES(@TopParentID,@TopParentName,ISNULL(@ParentOpeningBalance,0),''Group'')                  
SET @ParentRowCount=@ParentRowCount+1                  
END                  
SELECT AccGroupID,AccGroupName,CASE WHEN BALANCE>0.00 THEN [dbo].[fnGetRoundedValue](ISNULL(Balance,0)) ELSE [dbo].[fnGetRoundedValue](0) END AS Debit,                  
CASE WHEN BALANCE<0.00 THEN [dbo].[fnGetRoundedValue](ISNULL(ABS(Balance),0)) ELSE [dbo].[fnGetRoundedValue](0) END AS Credit,AccType,0 SelAccGroupID,      
null SelAccGroupName FROM @ParentMainTable                  
ORDER BY AccGroupName                
DROP TABLE #TempParent                  
END         
end',
N'[export] nocount';
