/****** uspgerFilterDates ******/
EXEC #Apply07 N'dbo.uspgerFilterDates', 0x7C4BB348F6E6027FD98AB86F4EAAF43768BB6B56CAEB2427DA675B6CFEED6507, NULL, NULL, 0xEAB64CA0E4A47FEBB5F59E960BB3F600DB5DCFDFE69DE708C8F6AE5E9FDA1EB6, 0x4DE47A193AB7CE4F525646C99ADEC9A41B5BE19E7C223EE6D0306B9FDE13D669, NULL,
N'ALTER PROc [dbo].[uspgerFilterDates]
as
SET NOCOUNT ON;
begin
DECLARE @FSD DATE = ''2025-04-01''   -- Financial Start Date
DECLARE @FED DATE = ''2027-03-31''   -- Financial End Date
SELECT @FSD = F_SD,@FED = F_ED FROM TBLCOMPANYREGISTRATION
DECLARE @Today DATE = GETDATE()

-- Raw From/To per period
DECLARE @Results TABLE (ID INT, Code VARCHAR(10), Name VARCHAR(50), RawFrom DATE, RawTo DATE)

-- 1. CD - Current Date
INSERT INTO @Results
SELECT 1, ''CD'', ''Current Date'', @Today, @Today

-- 2. TM - This Month
INSERT INTO @Results
SELECT 2, ''TM'', ''This Month'',
    DATEFROMPARTS(YEAR(@Today), MONTH(@Today), 1),
    EOMONTH(@Today)

-- 3. PM - Previous Month
INSERT INTO @Results
SELECT 3, ''PM'', ''Previous Month'',
    DATEFROMPARTS(YEAR(DATEADD(MONTH,-1,@Today)), MONTH(DATEADD(MONTH,-1,@Today)), 1),
    EOMONTH(DATEADD(MONTH, -1, @Today))

-- 4. All - Financial Date
INSERT INTO @Results
SELECT 4, ''All'', ''Financial Date'', @FSD, @FED

-- 5. TQ - This Quarter
DECLARE @TQNum INT = DATEPART(QUARTER, @Today)
INSERT INTO @Results
SELECT 5, ''TQ'', ''This Quarter'',
    DATEFROMPARTS(YEAR(@Today), (@TQNum - 1) * 3 + 1, 1),
    EOMONTH(DATEFROMPARTS(YEAR(@Today), @TQNum * 3, 1))

-- 6. PQ - Previous Quarter
DECLARE @PQRef DATE = DATEADD(MONTH, -3, @Today)
DECLARE @PQNum INT  = DATEPART(QUARTER, @PQRef)
INSERT INTO @Results
SELECT 6, ''PQ'', ''Previous Quarter'',
    DATEFROMPARTS(YEAR(@PQRef), (@PQNum - 1) * 3 + 1, 1),
    EOMONTH(DATEFROMPARTS(YEAR(@PQRef), @PQNum * 3, 1))

-- Final SELECT with new Min/Max/From/To logic
SELECT
    r.ID,
    r.Code,
    r.Name,

    -- MinDate: MIN(RawFrom, FSD) → lower of the two
    CASE WHEN r.RawFrom < @FSD THEN r.RawFrom ELSE @FSD END AS MinDate,

    -- MaxDate: Step 1 → MIN(RawTo, FED), Step 2 → MIN(result, Today)
	case when @FED < @Today then @FED ELSE  @Today END
     AS MaxDate,

    -- FromDate: same as MinDate
     CASE 
        WHEN CASE WHEN r.RawFrom >=  @FSD THEN r.RawFrom ELSE @FSD END  < @FED 
		THEN CASE WHEN r.RawFrom >=  @FSD THEN r.RawFrom ELSE @FSD END ELSE @FED END  AS FromDate,

    -- ToDate: same as MaxDate
    CASE 
        WHEN CASE WHEN r.RawTo < @FED THEN r.RawTo ELSE @FED END < @Today
        THEN CASE WHEN r.RawTo < @FED THEN r.RawTo ELSE @FED END
        ELSE @Today
    END AS ToDate

FROM @Results r
JOIN tblFilterDates FD ON FD.ID = R.ID
WHERE FD.Active = 1 
ORDER BY FD.DisplayIndex,r.ID
end',
N'[export] nocount';
GO
/****** uspGerPRManufProducts ******/
EXEC #Apply07 N'dbo.uspGerPRManufProducts', 0x3847FA6446D069E9EFBACEFD8BD0EFC73ED080B412DB5E388594E802DE685475, NULL, NULL, 0x47F61AEDCB25DCE83B4AE1668AA88995175CF5B33010EB76117524BF44E08C72, 0x5BE30A1E73822EE01666C84119B2BE500E53E7B725734D8A9EEEFEAA735DCA5F, NULL,
N'ALTER proc [dbo].[uspGerPRManufProducts]    
@ManufID int = 82,@BranchID INT = 4,@PriceType int = 1,@TransDate DATE = ''2026-12-20''    
as    
SET NOCOUNT ON;
begin    
select ProdID,UomID,Code,Name,HSNCode,UOM,Qty,FreeQty,sum(DmgQty) DmgQty,ProdPern,TradePern,AddnlPern,
sum(GrossAmt - ProdDiscAmt) GrossAmt,    
sum(((GrossAmt - ProdDiscAmt) * TaxPern) / 100) TaxAmt,
sum((GrossAmt - ProdDiscAmt)) + sum(((GrossAmt - ProdDiscAmt) * TaxPern) / 100)NetAmt,    
TaxName,TaxPern,ReasonId,ReasonName,PurchaseReturnPrice,0 DiffAmt,CumMRPonTax,SUM(MRPonTaxAmt) MRPonTaxAmt,
sum(GrossAmt) GoodsAmt,sum(ProdDiscAmt) ProdDiscAmt,0 TradeDiscAmt,0 AddnlDiscAmt
from (    
SELECT MP.ID ProdID,MP.BaseUomID UomID,MP.Code,MP.Name,MP.HSNCode,UOM.Name UOM,0 Qty,0 FreeQty,SUM(ActualDmgQty) DmgQty,                                            
MP.ProductDiscPerc ProdPern,0 TradePern,0 AddnlPern,    
sum(ActualDmgQty) * (case when @PriceType = 1 then PV.PurchasePrice ELSE PV.ReturnPrice END) GrossAmt,                                            
MT.TaxName,MT.GST TaxPern,0 ReasonId,null ReasonName,ISNULL(PTP.PurchaseReturnPrice,0) PurchaseReturnPrice,  
SUM(dbo.fngetMRPonCumValue(0,MP.PURCHASETAXID,1,0)) CumMRPonTax,  
SUM(dbo.fngetMRPonCumValue(1,MP.PURCHASETAXID,1,PV.MRP))* SUM(ISNULL(ActualDmgQty,0)) MRPonTaxAmt,
(MP.ProductDiscPerc * (sum(ActualDmgQty) * (case when @PriceType = 1 then PV.PurchasePrice ELSE PV.ReturnPrice END))) / 100
ProdDiscAmt
FROM  tblMasterProduct MP                                     
JOIN tblProductInventory PV ON PV.ProdID = MP.ID    
JOIN tblMasterUOM UOM ON UOM.ID = MP.BaseUomID                                            
JOIN tblMasterTax MT ON MT.TaxID = MP.PurchaseTaxID                                         
LEFT JOIN tblProductTransactionprices PTP ON PTP.ID = MP.ID                   
where MP.MfrID = @ManufID and ActualDmgQty > 0 AND BranchID = @BranchID AND PV.TransDate <= @TransDate    
group by MP.ID,MP.BaseUomID,MP.Code,MP.Name,MP.HSNCode,UOM.Name,MP.ProductDiscPerc,MT.TaxName,MT.GST,PV.PurchasePrice,PV.ReturnPrice,    
PTP.PurchaseReturnPrice) as Records    
group by  ProdID,UomID,Code,Name,HSNCode,UOM,Qty,FreeQty,ProdPern,TradePern,AddnlPern,TaxName,TaxPern,    
ReasonId,ReasonName,PurchaseReturnPrice ,CumMRPonTax  
    
                                          
SELECT InventoryId,ProdID AS ProdID,BatchNumber,PKDDate,ExpiryDate,(SUM(Qty)) Qty,(SUM(FreeQty)) FreeQty                                            
,(SUM(DmgQty)) DmgQty,MRP,PurchasePrice,ReturnPrice,(SUM(PRQty)) PRQty,(SUM(PRFree)) PRFree                                            
,(SUM(PRDmg)) PRDmg,TaxName,GSTPern,PurchaseTaxID,ConversionRate FROM (                                                                                    
SELECT 0 InventoryId,P.ProdID,P.BatchNumber BatchNumber,P.PKDDate PKDDate,P.ExpiryDate ExpiryDate,0 Qty,                              
0FreeQty,(SUM(p.ActualDmgQty)) DmgQty,                                            
(P.MRPONPrice) MRP,(case when @PriceType = 6 THEN P.ReturnPrice ELSE P.PurchasePrice end) PurchasePrice,                    
(case when @PriceType = 6 THEN P.ReturnPrice ELSE P.PurchasePrice end) ReturnPrice,(SUM(isnull(ActualQty,0))) PRQty,                                            
(SUM(isnull(ActualFreeQty,0))) PRFree,(SUM(isnull(ActualDmgQty,0))) PRDmg,MTT.TaxName,MTT.GST GSTPern,MP.PurchaseTaxID PurchaseTaxID,1 ConversionRate                                          
FROM  tblMasterProduct MP                                            
JOIN tblProductInventory P ON P.ProdID = MP.ID                                   
join tblMasterTax MTT ON MTT.TaxID = MP.PurchaseTaxID    
where MP.MfrID = @ManufID AND BranchID = @BranchID AND P.TransDate <= @TransDate                                          
GROUP BY P.BatchNumber,P.PKDDate,P.ExpiryDate,P.MRPONPrice,P.ProdID,P.ReturnPrice,MTT.TaxName,MTT.GST,MP.PurchaseTaxID,                    
(case when @PriceType = 6 THEN P.ReturnPrice ELSE P.PurchasePrice end),(case when @PriceType = 6 THEN P.ReturnPrice else P.PurchasePrice end)) AS REC                                            
group by InventoryId,ProdID,BatchNumber,PKDDate,ExpiryDate,MRP,PurchasePrice,ReturnPrice,TaxName,GSTPern,PurchaseTaxID,ConversionRate        
end',
N'[export] nocount';
GO
/****** uspGetABSQty ******/
EXEC #Apply07 N'dbo.uspGetABSQty', 0x98E2FBFAF5F19EE3B921A7D20D99A8F08B060C0A6AC68DE97DA1BF6862504FEC, NULL, NULL, 0x68DE144766050EFA6DEFEFFE643496C125A2A89E87B2FD70808FDB564AD2DAA0, 0x8CEEF4EA336E8811CCCE12CCD08D0801E4EDDFEBA96DDE5305D59FA06BF8B8C5, NULL,
N'--uspGetABSQty 2,4,GETDATE()
ALTER PROC [dbo].[uspGetABSQty]
@ProdID INT =2,@BranchID INT =4 ,@Date DATE = null
AS
SET NOCOUNT ON;
BEGIN
if(@Date = null)
begin
set @Date = GETDATE()
end
select ISNULL(SUM(ActualQty),0) ActualQty,ISNULL(SUM(ActualFreeQty),0) ActualFreeQty,ISNULL(SUM(ActualDmgQty),0) ActualDmgQty
from tblProductInventory WHERE ProdID = @ProdID AND BranchID = (CASE WHEN @BranchID > 0 THEN @BranchID ELSE BranchID END) 
AND TransDate <= @Date
END',
N'[export] nocount';
GO
/****** uspGetAccDetailsForOtherColl ******/
EXEC #Apply07 N'dbo.uspGetAccDetailsForOtherColl', 0xA6556A0E6DC8845EEECCA4B197C326E8AB2BB3CA0678CB5B6F36B657B97803A0, NULL, NULL, 0x206C4133D187CD7881F9B9B92FF35EDA3EB2BC31C1FE32353009560FED613D61, 0x81480017CAFBEAFE17BF718FF7012827D45B23C022E8ABFA38F3DE8533E23037, NULL,
N'--uspGetAccDetailsForOtherColl 239,''2026-10-12'',1,19  
ALTER PROC [dbo].[uspGetAccDetailsForOtherColl] --117                                       
@PartyID INT,                    
@Date DATE,@BranchID INT = 0,@DocPrefix int = 0  
AS                                      
SET NOCOUNT ON;
BEGIN      
DECLARE @AccId INT = 10000
--if(@DocPrefix = 18)  
--set @AccId = (SELECT FAID FROM tblMasterVendor WHERE id=@PartyID)  
--else  
--set @AccId = (SELECT FAID FROM tblMasterCustomer WHERE id=@PartyID)  
  
if(@AccId > 0)      
BEGIN      
SELECT Doc.TransName,PR.DocID,            
Convert(NVARCHAR(25),PR.DocDate,103) DocDate,PR.RefNo,PR.NetAmount,PR.Balance,'''',PR.ID, PR.TransID,PR.DocValue,PR.PartyID ,''Payable'' AS Voucher,                  
Narration,0.00,0.00,UDFDocId              
FROM tblTranPRVoucher PR JOIN tblDocumentSeries Doc            
ON PR.TransID=Doc.TransID WHERE PR.TransID=6 AND PR.PartyID=@AccId AND PR.Balance >0 AND PR.[Status] IN (1,3,9) AND PR.DocDate <= @Date            
UNION            
SELECT Doc.TransName,ColHeader.DocID,          
Convert(NVARCHAR(10),ColHeader.ColDate,103) DocDate,ColHeader.ColDocRefNo RefNo,ColHeader.ColAmt NetAmount,ColHeader.Balance,'''',ColHeader.ColID ID,ColHeader.DocPrefix TransID,ColHeader.DocValue,                        
ColHeader.AccID PartyID,''Payable'' AS Voucher,'''' AS Narration,0.00,0.00,UDFDocId            
FROM tblTranCollectionHeader ColHeader            
JOIN tblDocumentSeries Doc ON ColHeader.DocPrefix=Doc.TransID            
WHERE ColHeader.AccID=@AccId AND ColHeader.BranchID = @BranchID and ColHeader.DocPrefix = 10 AND ColHeader.Balance >0  AND ColHeader.[Status] IN (1,3,9) AND ColHeader.ColDate <= @Date                          
UNION ALL  
SELECT Doc.TransName,PR.DocID,--(Doc.DocPrefix +CONVERT (NVARCHAR,PR.DocValue)) AS DocID,            
Convert(NVARCHAR(10),PR.DocDate,103),PR.RefNo,PR.NetAmount,PR.Balance,'''',PR.ID, PR.TransID,PR.DocValue,PR.PartyID  ,''Receivable'' AS Voucher,            
Narration,0.00,0.00,UDFDocId            
FROM tblTranPRVoucher PR JOIN tblDocumentSeries Doc            
ON PR.TransID=Doc.TransID WHERE PR.TransID=7 AND PR.PartyID=@AccId AND PR.Balance >0 AND PR.[Status] IN (1,3,9) AND PR.DocDate <= @Date            
UNION ALL            
SELECT Doc.TransName,PayHeader.DocID,        
Convert(NVARCHAR(10),PayHeader.PYDate,103),PayHeader.PYDocRefNo,PayHeader.PYAmt,PayHeader.Balance,'''',PayHeader.PYID,PayHeader.PYPrefix,PayHeader.DocValue,            
PayHeader.AccID,''Receivable'' AS Voucher,'''' AS Narration,0.00,0.00,UDFDocId            
FROM tblTranPaymentHeader PayHeader            
JOIN tblDocumentSeries Doc            
ON PayHeader.PYPrefix=Doc.TransID            
WHERE PayHeader.AccID=@AccId AND PayHeader.BranchID = @BranchID and PayHeader.PYPrefix = 11 AND PayHeader.Balance >0  AND PayHeader.[Status] IN (1,3,9)  AND PayHeader.PYDate <= @Date            
END           
END    
  
--SELECT * FROM tblTranPRVoucher WHERE DocID = ''RV/2627/13''',
N'[export] nocount';
GO
/****** uspGetAdjusmentDoc ******/
EXEC #Apply07 N'dbo.uspGetAdjusmentDoc', 0xEFADA65B868D420B3B489102896023DEFF8C336E36BA7F023662F50443CE0F67, NULL, NULL, 0x2AEE2314DBE39585176D3D16D9EC1838C23488BE35D664A8B90B100D081164B1, 0x904B399DE635666F14F3F7E2E8B204D5D529035FFA7978E16BD85072167FD0CE, NULL,
N'--[uspGetAdjusmentDoc] 239,''2026-10-12'',0,4,1  
ALTER PROCEDURE [dbo].[uspGetAdjusmentDoc]                        
@CustID INT,                                                
@DocDate DATETIME,                                        
@nCollorPayID INT,                                      
@nMode INT,@BranchID int = 0  
AS                                                
SET NOCOUNT ON;
BEGIN                                                
DECLARE @AccID INT                          
SET @AccID=(SELECT FAID FROM tblMasterCustomer WHERE Id=@CustID)                                                                  
IF ISNULL(@nMode,0)!=4                          
BEGIn                        
IF ISNULL(@nCollorPayID,0)>0                                      
BEGIn                       
PRINT ''SELECT - 1''                          
SELECT * FROM (          
SELECT tblNoteDetails.DocId,          
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),tblNoteDetails.DocValue)  AS DocId,           
Convert(varchar,DocDate,103) as DocDate, NoteValue,          
tblNoteDetails.ID Ident,tblNoteDetails.TransID AS DocPrefix ,tblNoteDetails.DocValue AS DocValue  ,tblNoteDetails.PartyId,Balance,tblDocumentSeries.TransName,RefNo DocRefNo,UDFDocId                                  
FROM tblNoteDetails          
LEFT JOIN tblDocumentSeries ON tblNoteDetails.TransID=tblDocumentSeries.TransID          
WHERE PartyId=@AccId and BranchID = @BranchID AND tblNoteDetails.TransID=4 AND tblNoteDetails.Status in (1,3)          
AND DocDate<=@DocDate          
--UNION ALL        
--SELECT PRV.DocId,Convert(varchar,DocDate,103) as DocDate,PRV.NetAmount NoteValue,        
--PRV.ID Ident,PRV.TransID AS DocPrefix ,PRV.DocValue AS DocValue ,PRV.PartyId,Balance,tblDocumentSeries.TransName TransName,RefNo DocRefNo,UDFDocId        
--FROM tblTranPRVoucher PRV      
--JOIN tblDocumentSeries        
--ON PRV.TransID=tblDocumentSeries.TransID        
--WHERE PartyId=@AccId and BranchID = @BranchID AND PRV.TransID=700 AND PRV.Status IN (1,3) AND DocDate<=@DocDate        
UNION ALL          
SELECT Header.DocID,          
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),Header.DocValue)  AS DocId,          
Convert(varchar,ColDate,103) as DocDate, ColAmt,          
Header.ColID,Header.DocPrefix AS DocPrefix,Header.DocValue AS DocValue,Header.AccID,Header.Balance,tblDocumentSeries.TransName,Header.ColDocRefNo,Header.UDFDocId          
FROM tblTranCollectionHeader AS Header          
LEFT JOIN tblDocumentSeries          
ON Header.DocPrefix=tblDocumentSeries.TransID          
WHERE Header.AccID=@AccId and BranchID = @BranchID AND Header.Status IN (1,3) AND Header.DocPrefix=19 AND ColDate<=@DocDate          
UNION ALL          
SELECT SalesHeader.DocId,          
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),SalesHeader.DocValue)  AS DocId,           
Convert(varchar,InvDate,103) as DocDate, SalesHeader.NetAmt,          
SalesHeader.ID InvId,SalesHeader.DocPrefix AS DocPrefix,SalesHeader.DocValue AS DocValue,@AccId,SalesHeader.Balance,tblDocumentSeries.TransName,SalesHeader.DocRef,SalesHeader.UDFDocId          
FROM tblTranSalesHeader SalesHeader          
LEFT JOIN tblDocumentSeries          
ON SalesHeader.DocPrefix=tblDocumentSeries.TransID          
WHERE SalesHeader.CustId=@CustID and BranchID = @BranchID AND SalesHeader.DocPrefix=16 AND SalesHeader.[Status] IN (3,6,7) AND InvDate<=@DocDate          
) AS CrAdj          
Order By CrAdj.DocPrefix,Ident--,CrAdj.DocDate,CrAdj.DocValue                                        
END                                        
ELSE                                        
BEGIN                                 
PRINT ''SELECT - 2''                                 
SELECT * FROM (          
SELECT tblNoteDetails.DocId,          
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),tblNoteDetails.DocValue)  AS DocId,           
Convert(varchar,DocDate,103) as DocDate, NoteValue,tblNoteDetails.ID Ident,tblNoteDetails.TransID AS DocPrefix ,tblNoteDetails.DocValue AS DocValue,        
tblNoteDetails.PartyId,Balance,tblDocumentSeries.TransName,RefNo DocRefNo,UDFDocId                                
FROM tblNoteDetails                                                                      
LEFT JOIN tblDocumentSeries ON tblNoteDetails.TransID=tblDocumentSeries.TransID        
WHERE PartyId=@AccId and BranchID = @BranchID AND tblNoteDetails.TransID=4 AND tblNoteDetails.Status in (1,3)          
AND Balance>0 AND DocDate<=@DocDate            
--UNION ALL        
--SELECT PRV.DocId,Convert(varchar,DocDate,103) as DocDate,PRV.NetAmount NoteValue,        
--PRV.ID Ident,PRV.TransID AS DocPrefix ,PRV.DocValue AS DocValue ,PRV.PartyId,Balance,tblDocumentSeries.TransName TransName,RefNo DocRefNo,UDFDocId        
--FROM tblTranPRVoucher PRV      
--JOIN tblDocumentSeries        
--ON PRV.TransID=tblDocumentSeries.TransID        
--WHERE PartyId=@AccId and BranchID = @BranchID AND PRV.TransID=700 AND PRV.Status IN (1,3) AND DocDate<=@DocDate        
UNION ALL                                                      
SELECT Header.DocID,          
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),Header.DocValue)  AS DocId,           
Convert(varchar,ColDate,103) as DocDate, ColAmt,                                                      
Header.ColID,Header.DocPrefix AS DocPrefix,Header.DocValue AS DocValue,Header.AccID,Header.Balance,tblDocumentSeries.TransName,Header.ColDocRefNo,Header.UDFDocId                                  
FROM tblTranCollectionHeader AS Header
LEFT JOIN tblDocumentSeries                                                                          
ON Header.DocPrefix=tblDocumentSeries.TransID                                                           
WHERE Header.AccID=@AccId and BranchID = @BranchID AND Header.Balance>0 AND Header.Status IN (1,3) AND Header.DocPrefix=19 AND ColDate<=@DocDate                                                
UNION ALL                                                    
SELECT SalesHeader.DocID,          
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),SalesHeader.DocValue)  AS DocId,          
Convert(varchar,InvDate,103) as DocDate, SalesHeader.NetAmt,                                                    
SalesHeader.ID InvId,SalesHeader.DocPrefix AS DocPrefix,SalesHeader.DocValue AS DocValue,@AccId,SalesHeader.Balance,tblDocumentSeries.TransName,SalesHeader.DocRef,SalesHeader.UDFDocId                                  
FROM tblTranSalesHeader SalesHeader                                                    
LEFT JOIN tblDocumentSeries ON SalesHeader.DocPrefix=tblDocumentSeries.TransID                                                     
WHERE SalesHeader.CustId=@CustID and BranchID = @BranchID AND SalesHeader.DocPrefix=16 AND SalesHeader.[Status] IN (3,6,7) AND SalesHeader.Balance>0 AND InvDate<=@DocDate                                                    
) AS CrAdj                                            
Order By CrAdj.DocPrefix,Ident--,CrAdj.DocDate,CrAdj.DocValue                                                   
END                                        
END                                      
ELSE                                      
BEGIN                                     
PRINT ''SELECT - 3''                           
select * from (                        
select DocId,convert(nvarchar,InvDate,103) InvDate,NetAmt,InvId,DocPrefix,DocValue,ACCID,Balance + SUM(AdjAmt) Balance,TransName,DocRef,sum(ColValue) ColValue ,UDFDocId from (                        
SELECT Sales.DocID,convert(nvarchar,InvDate,103) InvDate,Sales.NetAmt,Sales.ID InvId,Sales.DocPrefix,Sales.DocValue,@AccID ACCID ,SALES.Balance,0 AdjAmt,                        
''Sales Return'' TransName,Sales.DocRef,0 ColValue,Sales.UDFDocId FROM tblTranSalesHeader AS Sales                                 
--JOIN tblMastCustomer AS Customer ON Sales.CustId=Customer.CustId                                 
Where Sales.CustId=@CustId and BranchID = @BranchID AND Sales.DocPrefix=600 AND InvDate <=@DocDate AND Sales.[Status] IN (3,6,7)                          
union                        
SELECT SH.DocID,convert(nvarchar,InvDate,103) InvDate,SH.NetAmt,SH.ID InvId,SH.DocPrefix,SH.DocValue,@AccID ACCID ,                        
 SH.Balance AS Balance,TD.TotalAmtAdj AdjAmt,                        
''Sales Return'' TransName,SH.DocRef,(CASE WHEN TD.ColID = @nCollorPayID THEN TD.ColValue ELSE 0 END) AS ColValue,SH.UDFDocId                         
FROM tblTranCollectionDetail TD                        
JOIN tblTranCollectionHeader TH ON TH.ColID =TD.ColID                        
LEFT JOIN tblTranSalesHeader SH ON SH.ID = TD.DocID AND SH.DocPrefix = TD.DocPrefix                        
WHERE TH.Status IN (1,3,5) and TD.ColID = @nCollorPayID AND SH.DocPrefix = 16) as NK                        
group by DocId,InvDate,NetAmt,InvId,DocPrefix,DocValue,ACCID,Balance,UDFDocId,TransName,DocRef                        
UNION ALL                        
SELECT DocId, Convert(varchar,DocDate,103) as DocDate,NoteValue,Ident,DocPrefix,DocValue,PartyId,Balance + SUM(ADJAMT),TransName,DocRefNo,                        
SUM(ColValue) ColValue,UDFDocId FROM (                        
SELECT DocId,Convert(varchar,DocDate,103) as DocDate,NoteValue,tblNoteDetails.ID Ident,TransID DocPrefix,DocValue,PartyId,Balance,0 ADJAMT,''Credit Note'' TransName,                        
RefNo DocRefNo,0 ColValue,UDFDocId FROM tblNoteDetails                        
WHERE PartyId=@AccId and BranchID = @BranchID AND tblNoteDetails.TransID=4 AND tblNoteDetails.Status IN (1,3) AND DocDate<=@DocDate                           
union                         
SELECT tblNoteDetails.DocId AS DocId, Convert(varchar,DocDate,103) as DocDate, NoteValue,                                                                      
tblNoteDetails.ID,tblNoteDetails.TransID AS DocPrefix ,tblNoteDetails.DocValue AS DocValue  ,tblNoteDetails.PartyId,                                      
(CASE WHEN CD.ColID = @nCollorPayID THEN (tblNoteDetails.Balance) ELSE tblNoteDetails.Balance END) AS Balance, CD.TotalAmtAdj TotalAmtAdj,                         
''Credit Note'' TransName,RefNo DocRefNo,                                    
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.ColValue ELSE 0 END) AS ColValue,tblNoteDetails.UDFDocId                                  
FROM tblNoteDetails                        
LEFT JOIN tblTranCollectionDetail AS CD ON CD.DocID = ID                        
LEFT JOIN tblTranCollectionHeader AS CH ON CH.ColID = CD.ColID   AND tblNoteDetails.TransID = CD.DocPrefix                        
WHERE tblNoteDetails.TransID=4 AND CH.Status IN (1,3,5) AND DocDate<=@DocDate                    
and CD.ColID = @nCollorPayID ) AS CN    --PartyId=@AccId and BranchID = @BranchID AND                     
group by DocId,DocDate,NoteValue,Ident,DocPrefix,DocValue,PartyId,Balance,UDFDocId,TransName,DocRefNo                        
UNION ALL      
SELECT DocId, Convert(varchar,DocDate,103) as DocDate,NoteValue,ID Ident,DocPrefix,DocValue,PartyId,Balance + SUM(ADJAMT) Balance,TranName TransName,DocRefNo,        
SUM(ColValue) ColValue,UDFDocId FROM (        
SELECT DocId,DocDate,PRV.NetAmount NoteValue,PRV.ID,TransID DocPrefix,DocValue,PartyId,Balance,0 ADJAMT,''Receivable Voucher'' TranName,        
RefNo DocRefNo,0 ColValue,UDFDocId FROM tblTranPRVoucher PRV      
WHERE PartyId=@AccId and BranchID = @BranchID AND PRV.TransID= 6 AND PRV.Status IN (1,3) AND DocDate<=@DocDate        
union        
SELECT tblNoteDetails.DocId AS DocId, DocDate,NetAmount NoteValue,        
tblNoteDetails.ID,tblNoteDetails.RefNo AS DocPrefix ,tblNoteDetails.DocValue AS DocValue ,tblNoteDetails.PartyId,        
(CASE WHEN CD.PYID = @nCollorPayID THEN (tblNoteDetails.Balance) ELSE tblNoteDetails.Balance END) AS Balance, CD.TotalAmtAdj TotalAmtAdj,        
''Receivable Voucher'' TranName,RefNo,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.BillPYValue ELSE 0 END) AS ColValue,tblNoteDetails.UDFDocId        
FROM tblTranPaymentDetail AS CD        
JOIN tblTranPaymentHeader CH ON CH.PYID = CD.PYID        
LEFT JOIN tblTranPRVoucher tblNoteDetails ON CD.DocID = tblNoteDetails.ID AND tblNoteDetails.TransID = CD.DocPrefix        
WHERE PartyId=@AccId and CH.BranchID = @BranchID AND tblNoteDetails.TransID= 6 AND CH.Status IN (1,3,5) AND DocDate<=@DocDate        
and CD.PYID = @nCollorPayID        
) AS RV      
GROUP BY DocId,DocDate,NoteValue,ID,DocPrefix,DocValue,PartyId,Balance,UDFDocId,TranName,DocRefNo      
union all                        
SELECT Header.DocID AS DocId, Convert(varchar,ColDate,103) as DocDate, ColAmt,                                                      
Header.ColID,Header.DocPrefix AS DocPrefix,Header.DocValue AS DocValue,Header.AccID,                                      
(CASE WHEN CD.ColID = @nCollorPayID THEN (Header.Balance + CD.TotalAmtAdj) ELSE Header.Balance END) AS Balance,''Collection'' TransName                        
,Header.ColDocRefNo,                          
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.ColValue ELSE 0 END) AS ColValue,UDFDocId                                    
FROM tblTranCollectionHeader AS Header                          
JOIN tblTranCollectionDetail AS CD ON CD.DocId = Header.ColID AND CD.DocPrefix = Header.DocPrefix            
WHERE Header.AccID=@AccId and BranchID = @BranchID  AND  Header.Status IN (1,3,5) AND Header.DocPrefix=19 AND ColDate<=@DocDate              
and CD.ColID = @nCollorPayID             
UNION ALL                                                      
SELECT Header.DocID AS DocId, Convert(varchar,ColDate,103) as DocDate, ColAmt,                                                      
Header.ColID,Header.DocPrefix AS DocPrefix,Header.DocValue AS DocValue,Header.AccID,Header.Balance,            
tblDocumentSeries.TransName,            
Header.ColDocRefNo,0,Header.UDFDocId                                  
FROM tblTranCollectionHeader AS Header            
LEFT JOIN tblDocumentSeries ON Header.DocPrefix=tblDocumentSeries.TransID                                                           
WHERE Header.AccID=@AccId and BranchID = @BranchID AND Header.Balance>0 AND Header.Status IN (1,3,5) AND Header.DocPrefix=19 AND ColDate<=@DocDate             
) as MainDoc                        
where Balance > 0      --Header.AccID=@AccId and BranchID = @BranchID  AND                 
group by DocId,InvDate,NetAmt,InvId,DocPrefix,DocValue,ACCID,Balance,TransName,DocRef,ColValue ,UDFDocId                  
order by DocPrefix,InvId                  
END                                      
END',
N'[export] nocount';
GO
/****** uspGetAdjusmentDocForPY ******/
EXEC #Apply07 N'dbo.uspGetAdjusmentDocForPY', 0x3FA22EE79DBB6A4F617A600065419E3C1B0C42AE1E35E55EEA5C678C9BB2352A, NULL, NULL, 0xF74BF282A39E7FED1E484B5F6FC334DFD3A628C55AC88B368DDEB5115F80EE39, 0xE91FCBE08E3DC48B6B425722BDB8FF169B0ADBB4970B27B90D0C17C31607F65E, NULL,
N'--[uspGetAdjusmentDocForPY] 11,''2026-09-30'',0,1,1
--[uspGetAdjusmentDocForPY] 1281,''2019-12-24'',0,1        
ALTER PROCEDURE [dbo].[uspGetAdjusmentDocForPY]        
@CustID INT,@DocDate DATE,@nCollorPayID INT,@nMode INT=NULL,@BranchID int  = 0      
AS        
SET NOCOUNT ON;
BEGIN        
DECLARE @AccID INT        
SET DATEFORMAT dmy        
SET @AccID=(SELECT FAID FROM tblMasterVendor WHERE id=@CustID)        
IF ISNULL(@nMode,0)!=4        
BEGIN        
IF ISNULL(@nCollorPayID,0) > 0        
BEGIN        
SELECT * FROM (        
SELECT tblNoteDetails.DocId,        
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),tblNoteDetails.DocValue) AS DocId,        
Convert(varchar,DocDate,103) as DocDate, NoteValue,tblNoteDetails.ID Ident,tblNoteDetails.TransID AS DocPrefix ,tblNoteDetails.DocValue AS DocValue ,        
tblNoteDetails.PartyId,Balance,tblDocumentSeries.TranSName TransName,RefNo DocRefNo,UDFDocId        
FROM tblNoteDetails        
JOIN tblDocumentSeries        
ON tblNoteDetails.TransID=tblDocumentSeries.TransID        
WHERE PartyId=@AccId AND tblNoteDetails.TransID=5 and BranchID = @BranchID AND tblNoteDetails.Status IN (1,3) AND DocDate<=@DocDate        
--UNION ALL        
--SELECT PRV.DocId,Convert(varchar,DocDate,103) as DocDate,PRV.NetAmount NoteValue,        
--PRV.ID Ident,PRV.TransID AS DocPrefix ,PRV.DocValue AS DocValue ,PRV.PartyId,Balance,tblDocumentSeries.TransName TransName,RefNo DocRefNo,UDFDocId        
--FROM tblTranPRVoucher PRV      
--JOIN tblDocumentSeries        
--ON PRV.TransID=tblDocumentSeries.TransID        
--WHERE PartyId=@AccId AND PRV.TransID=6 AND PRV.Status IN (1,3) AND DocDate<=@DocDate        
UNION ALL        
SELECT Header.DocID,        
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),Header.DocValue) AS DocId,        
Convert(varchar,PYDate,103) as DocDate, PYAmt,        
Header.PYID,Header.PYPrefix AS DocPrefix,Header.DocValue AS DocValue,Header.AccID,Header.Balance,tblDocumentSeries.TransName,Header.PYDocRefNo,UDFDocId        
FROM tblTranPaymentHeader AS Header        
JOIN tblDocumentSeries        
ON Header.PYPrefix=tblDocumentSeries.TransID        
WHERE Header.AccID=@AccId AND Header.Status IN (1,3) and BranchID = @BranchID AND Header.PYPrefix=18 AND PYDate<=@DocDate        
UNION ALL        
SELECT BillHeader.DocID,        
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),BillHeader.DocValue) AS DocId,        
Convert(varchar,Date,103) as DocDate, BillHeader.NetAmt,BillHeader.ID,BillHeader.TransID AS DocPrefix,BillHeader.DocValue AS DocValue,        
@AccId,BillHeader.Balance,tblDocumentSeries.TransName,BillHeader.RefNo,UDFDocId        
FROM tblTransPurchaseHeader BillHeader        
JOIN tblDocumentSeries        
ON BillHeader.TransID=tblDocumentSeries.TransID        
WHERE BillHeader.VendorID=@CustID AND BillHeader.TransID=12 and BranchID = @BranchID AND BillHeader.[Status] IN (1,3,6) AND Date<=@DocDate        
) AS CrAdj        
Order By CrAdj.DocPrefix,Ident--,CrAdj.DocDate,CrAdj.DocValue        
END        
ELSE        
BEGIN        
PRINT ''COND 2''
SELECT * FROM (        
SELECT tblNoteDetails.DocId,        
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),tblNoteDetails.DocValue) AS DocId,        
Convert(varchar,DocDate,103) as DocDate, NoteValue,        
tblNoteDetails.ID Ident,tblNoteDetails.TransID AS DocPrefix ,tblNoteDetails.DocValue AS DocValue ,tblNoteDetails.PartyId,Balance,tblDocumentSeries.TransName TransName,RefNo DocRefNo,UDFDocId        
FROM tblNoteDetails        
JOIN tblDocumentSeries        
ON tblNoteDetails.TransID=tblDocumentSeries.TransID        
WHERE PartyId=@AccId AND tblNoteDetails.TransID=5 and BranchID = @BranchID AND tblNoteDetails.Status IN (1,3) AND DocDate<=@DocDate        
--UNION ALL        
--SELECT PRV.DocId,      
--Convert(varchar,DocDate,103) as DocDate,PRV.NetAmount NoteValue,        
--PRV.ID Ident,PRV.TransID AS DocPrefix ,PRV.DocValue AS DocValue ,PRV.PartyId,Balance,tblDocumentSeries.TransName TransName,RefNo DocRefNo,UDFDocId        
--FROM tblTranPRVoucher PRV      
--JOIN tblDocumentSeries        
--ON PRV.TransID=tblDocumentSeries.TransID        
--WHERE PartyId=@AccId AND PRV.TransID= 7 AND PRV.Status IN (1,3) AND DocDate<=@DocDate        
UNION ALL       
SELECT Header.DocID,      
Convert(varchar,PYDate,103) as DocDate, PYAmt,        
Header.PYID,Header.PYPrefix AS DocPrefix,Header.DocValue AS DocValue,Header.AccID,Header.Balance,tblDocumentSeries.TransName,Header.PYDocRefNo,UDFDocId        
FROM tblTranPaymentHeader AS Header        
JOIN tblDocumentSeries        
ON Header.PYPrefix=tblDocumentSeries.TransID        
WHERE Header.AccID=@AccId AND Header.Balance>0 and BranchID = @BranchID AND Header.Status IN (1,3) AND Header.PYPrefix=18 AND PYDate<=@DocDate        
UNION ALL        
SELECT BillHeader.DocID,        
--tblDocumentSeries.DocPrefix+CONVERT(NVARCHAR(50),BillHeader.DocValue) AS DocId,        
Convert(varchar,Date,103) as DocDate, BillHeader.NetAmt,        
BillHeader.ID,BillHeader.TransID AS DocPrefix,BillHeader.DocValue AS DocValue,@AccId,BillHeader.Balance,tblDocumentSeries.TransName,BillHeader.RefNo,UDFDocId        
FROM tblTransPurchaseHeader BillHeader        
JOIN tblDocumentSeries        
ON BillHeader.TransID=tblDocumentSeries.TransID        
WHERE BillHeader.VendorID=@CustID AND BillHeader.TransID=12 and BranchID = @BranchID AND BillHeader.[Status] IN (1,3,6) AND BillHeader.Balance>0 AND Date<=@DocDate        
) AS CrAdj        
Order By CrAdj.DocPrefix,Ident--,CrAdj.DocDate,CrAdj.DocValue        
END        
END        
ELSE        
BEGIN        
SELECT * FROM (        
SELECT DocId, Convert(varchar,DocDate,103) as DocDate,NoteValue,ID Ident,DocPrefix,DocValue,PartyId,Balance + SUM(ADJAMT) Balance,TranName TransName,DocRefNo,        
SUM(ColValue) ColValue,UDFDocId FROM (        
SELECT DocId,DocDate,NoteValue,tblNoteDetails.ID,TransID DocPrefix,DocValue,PartyId,Balance,0 ADJAMT,''Debit Note'' TranName,        
RefNo DocRefNo,0 ColValue,UDFDocId FROM tblNoteDetails        
WHERE PartyId=@AccId AND tblNoteDetails.TransID=5 AND tblNoteDetails.Status IN (1,3) AND DocDate<=@DocDate        
union        
SELECT tblNoteDetails.DocId AS DocId, Convert(varchar,DocDate,103) as DocDate, NoteValue,        
tblNoteDetails.ID,tblNoteDetails.RefNo AS DocPrefix ,tblNoteDetails.DocValue AS DocValue ,tblNoteDetails.PartyId,        
(CASE WHEN CD.PYID = @nCollorPayID THEN (tblNoteDetails.Balance) ELSE tblNoteDetails.Balance END) AS Balance, CD.TotalAmtAdj TotalAmtAdj,        
''Debit Note'' TranName,RefNo,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.BillPYValue ELSE 0 END) AS ColValue,tblNoteDetails.UDFDocId        
FROM tblTranPaymentDetail AS CD        
JOIN tblTranPaymentHeader CH ON CH.PYID = CD.PYID        
LEFT JOIN tblNoteDetails ON CD.DocID = tblNoteDetails.ID AND tblNoteDetails.TransID = CD.DocPrefix        
WHERE PartyId=@AccId AND tblNoteDetails.TransID=5 AND CH.Status IN (1,3,5) AND DocDate<=@DocDate        
and CD.PYID = @nCollorPayID        
) AS CN        
group by DocId,DocDate,NoteValue,ID,DocPrefix,DocValue,PartyId,Balance,UDFDocId,TranName,DocRefNo        
union all        
SELECT Header.DocID AS DocId, Convert(varchar,PYDate,103) as DocDate, PYAmt,        
Header.PYID,Header.PYPrefix AS DocPrefix,Header.DocValue AS DocValue,Header.AccID,        
(CASE WHEN CD.PYID = @nCollorPayID THEN (Header.Balance + CD.BillPYValue) ELSE Header.Balance END) AS Balance,        
''Payment'' TranName,Header.PYDocRefNo,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.BillPYValue ELSE 0 END) AS ColValue,UDFDocId        
FROM tblTranPaymentHeader AS Header        
JOIN tblTranPaymentDetail AS CD ON CD.DocID = Header.PYID AND CD.DocPrefix = Header.PYPrefix        
WHERE Header.AccID=@AccId AND Header.Status IN (1,3,5) AND Header.PYPrefix=18 AND PYDate<=@DocDate        
UNION ALL        
SELECT DocId,DocDate,NetAmt,ID,DocPrefix,DocValue,AccId,Balance + SUM(BillPYValue),        
TranName,RefNo,SUM(ColValue) ColValue,UDFDocId FROM (        
SELECT SalesHeader.DocID AS DocId, Convert(varchar,Date,103) as DocDate, SalesHeader.NetAmt,        
SalesHeader.ID,SalesHeader.TransID AS DocPrefix,SalesHeader.DocValue AS DocValue,@AccId AccId,SalesHeader.Balance,0 BillPYValue,        
''Purchase Return'' TranName,SalesHeader.RefNo,        
0 AS ColValue,UDFDocId FROM tblTransPurchaseHeader SalesHeader        
WHERE SalesHeader.VendorID=@CustID AND SalesHeader.TransID=12 AND SalesHeader.[Status] IN (3,6)        
UNION        
SELECT SalesHeader.DocID AS DocId, Convert(varchar,SalesHeader.Date,103) as DocDate, SalesHeader.NetAmt,        
SalesHeader.ID,SalesHeader.TransID AS DocPrefix,SalesHeader.DocValue AS DocValue,@AccId,        
(CASE WHEN CD.PYID = @nCollorPayID THEN (SalesHeader.Balance) ELSE SalesHeader.Balance END) AS Balance,        
CD.BillPYValue BillPYValue,        
''Purchase Return'' TranName,SalesHeader.RefNo,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.BillPYValue ELSE 0 END) AS ColValue,SalesHeader.UDFDocId        
FROM tblTranPaymentDetail AS CD        
JOIN tblTranPaymentHeader AS CH ON CH.PYID = CD.PYID        
LEFT JOIN tblTransPurchaseHeader SalesHeader ON CD.DocID = SalesHeader.ID AND SalesHeader.TRANSID = CD.DocPrefix        
WHERE SalesHeader.VendorID=@CustID AND SalesHeader.TRANSID=12 AND CH.[Status] IN (1,3,5)        
AND SalesHeader.Date<=@DocDate and CD.PYID = @nCollorPayID ) AS PR        
GROUP BY DocId,DocDate,NetAmt,ID,DocPrefix,DocValue,AccId,Balance,UDFDocId,TranName,RefNo      
--UNION ALL      
--SELECT DocId, Convert(varchar,DocDate,103) as DocDate,NoteValue,ID Ident,DocPrefix,DocValue,PartyId,Balance + SUM(ADJAMT) Balance,TranName TransName,DocRefNo,        
--SUM(ColValue) ColValue,UDFDocId FROM (        
--SELECT DocId,DocDate,PRV.NetAmount NoteValue,PRV.ID,TransID DocPrefix,DocValue,PartyId,Balance,0 ADJAMT,''Payable Voucher'' TranName,        
--RefNo DocRefNo,0 ColValue,UDFDocId FROM tblTranPRVoucher PRV      
--WHERE PartyId=@AccId AND PRV.TransID= 6 AND PRV.Status IN (1,3) AND DocDate<=@DocDate        
--union        
--SELECT tblNoteDetails.DocId AS DocId, DocDate,NetAmount NoteValue,        
--tblNoteDetails.ID,tblNoteDetails.RefNo AS DocPrefix ,tblNoteDetails.DocValue AS DocValue ,tblNoteDetails.PartyId,        
--(CASE WHEN CD.PYID = @nCollorPayID THEN (tblNoteDetails.Balance) ELSE tblNoteDetails.Balance END) AS Balance, CD.TotalAmtAdj TotalAmtAdj,        
--''Payable Voucher'' TranName,RefNo,        
--(CASE WHEN CD.PYID = @nCollorPayID THEN CD.BillPYValue ELSE 0 END) AS ColValue,tblNoteDetails.UDFDocId        
--FROM tblTranPaymentDetail AS CD        
--JOIN tblTranPaymentHeader CH ON CH.PYID = CD.PYID        
--LEFT JOIN tblTranPRVoucher tblNoteDetails ON CD.DocID = tblNoteDetails.ID AND tblNoteDetails.TransID = CD.DocPrefix        
--WHERE PartyId=@AccId AND tblNoteDetails.TransID= 6 AND CH.Status IN (1,3,5) AND DocDate<=@DocDate        
--and CD.PYID = @nCollorPayID        
--) AS PV      
--GROUP BY DocId,DocDate,NoteValue,ID,DocPrefix,DocValue,PartyId,Balance,UDFDocId,TranName,DocRefNo      
) Main        
where Balance > 0        
ORDER BY DocPrefix,Ident -- DocDate,DocId        
END        
END',
N'[export] nocount';
GO
