/****** uspGetBranchByRoles ******/
EXEC #Apply07 N'dbo.uspGetBranchByRoles', 0x077F4FDD507CED708DDED9963E18E485A2208A54156B359B82DB15D525D2131D, NULL, NULL, 0xD83FA0CC79ADB0BF95515B6154823F104BD4F6B1B5752D96A7AFF4AF8FBF8CB9, 0xCDD0127F74AFBE80568D96EED1DF34765E504AB860A3DE9CBA5E27712EAA28C0, NULL,
N'--uspGetBranchByRoles 1    
ALTER Procedure [dbo].[uspGetBranchByRoles]    
@RoleID INT    
AS    
SET NOCOUNT ON;
BEGIN    
 IF(@RoleID = 1)  
 BEGIN  
  SELECT B.ID BranchID, B.Name[Branch Name], (CASE WHEN B.ID = 1 THEN 1 ELSE 0 END) SetAsDefault    
 FROM tblMasterBranchOffice B    
  WHERE  B.Active = 1    
  ORDER by  B.Name   
 END  
 ELSE  
 BEGIN  
 SELECT BM.BranchID, B.Name[Branch Name], BM.SetAsDefault    
 FROM tblBranchMapping BM    
 join tblMasterBranchOffice B on B.ID = BM.BranchID    
 WHERE BM.RoleID =  @RoleID AND BM.Active = 1    
 ORDER by BM.SetAsDefault DESC,B.Name    
 END  
END',
N'[export] nocount';
GO
/****** uspGetClosingBal ******/
EXEC #Apply07 N'dbo.uspGetClosingBal', 0x3C1481E1C464F10FE26B3DFD175DA31CC754FBE7E1E15F6E0755FB6A2CCBE9A0, NULL, NULL, 0x5F595A16E3C65EB33E26FC96660F167B1BDB6BBB9410C76B34755FFF8FA063D8, 0x248764220A646AA81C04667C6E3FDACBD93361AD1AB3A6D11F2C51AF8557659E, NULL,
N'ALTER PROC [dbo].[uspGetClosingBal]
@AccID INT,
@ReturnValue DECIMAL(18,9) OUTPUT
AS
SET NOCOUNT ON;
BEGIN
DECLARE @AccOpeningBal DECIMAL(18,9), @FSDate DATE, @FDDate DATE
DECLARE @Depit DECIMAL (25,6),@Credit DECIMAL (25,6),@Balance DECIMAL (25,6)
DECLARE @AccType INT

SELECT @FSDate = F_SD,@FDDate = F_ED FROM dbo.tblCompanyRegistration WITH (READCOMMITTEDLOCK)
SELECT @AccOpeningBal=ISNULL(OpeningBalance,0),@AccType=FATypeID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE FAID =@AccID
SELECT @Depit = ISNULL(SUM(Debit),0) , @Credit = ISNULL(SUM(Credit),0) FROM tblFAJournal WITH (READCOMMITTEDLOCK) WHERE [Status] IN(1,6,7,3,5,9)
AND AccountID = @AccID AND ([DocDate] BETWEEN @FSDate AND GETDATE())

IF @AccType =1
BEGIN
SET @Credit= @Credit+@AccOpeningBal;
END
IF @AccType =2
BEGIN
SET @Depit= @Depit+@AccOpeningBal;
END

--SELECT @Depit, @Credit, @Balance
IF(@Depit < @Credit)
BEGIN
SET @Balance = (@Credit - @Depit)
END
ELSE
BEGIN
SET @Balance = (@Depit - @Credit)
END

SET @ReturnValue=@Balance
END',
N'[export] nocount;readcommittedlock=3';
GO
/****** uspGetClosingStockAmt ******/
EXEC #Apply07 N'dbo.uspGetClosingStockAmt', 0x6648F5A5A104D5A4FB8A81AE0A221C8CA08C4FE6A60A8CAF0E17E19AAF3A8734, NULL, NULL, 0xCECD8016211E4C36C48CDBEE3608C52F07289B4A1AEDE4207E1E0E8950DBC8BE, 0x2A2AA925F3946093592335A3B1C2319671A5F73726443448DB6D48DCED3EBE35, NULL,
N'ALTER PROC [dbo].[uspGetClosingStockAmt]
@BranchID INT,
@ToDate DATETIME,           
@GlobalDate DATETIME,          
@ClosingAmt DECIMAL (25,6) OUTPUT          
AS          
SET NOCOUNT ON;
BEGIN          
--SET DATEFORMAT DMY          
DECLARE @TempToDate DATE,@TempGlobalDate DATE          
SET @TempGlobalDate=(SELECT DATEADD(D, 0, DATEDIFF(D, 0, @GlobalDate)))     
    
SET @TempToDate=(SELECT DATEADD(D, 0, DATEDIFF(D, 0, @ToDate)))          
IF @TempGlobalDate=@TempToDate          
BEGIN           
 SELECT @ClosingAmt=ISNULL([dbo].[fnGetRoundedValue](SUM(ISNULL(ActualQty,0)*ISNULL(PurchasePrice,0))),0) 
 FROM tblProductInventory WHERE (ActualQty>0) and BranchID = (case when @BranchID > 0 then @BranchID else BranchID END)
 SELECT @ClosingAmt +=ISNULL([dbo].[fnGetRoundedValue](SUM(ISNULL(ActualDmgQty,0)*ISNULL(PurchasePrice,0))),0) 
 FROM tblProductInventory WHERE (ActualDmgQty>0)      
END          
ELSE          
BEGIN          
 SELECT @ClosingAmt=ISNULL([dbo].[fnGetRoundedValue](SUM(ISNULL(SaleStockValue,0) + ISNULL(DmgStockValue,0))),0) 
 FROM tblClosingStock WHERE  ClsDate=@TempToDate  and BranchID = (case when @BranchID > 0 then @BranchID else BranchID END) --AND SaleStockValue>0           
END          
END',
N'[export] nocount';
GO
