/****** uspGetCustomerWiseSalesFooter ******/
EXEC #Apply07 N'dbo.uspGetCustomerWiseSalesFooter', 0xE3A8F5758442372FF4E84E10F60DE712364D5837E3B7855DE3FFB079B56368CE, NULL, NULL, 0xB1AB3183C7404D97389095D5B1B63882404509A3498943DD91537C42F3C3C088, 0x1598778EB2259F16CE30D60B3E286F04C0783DF49BD136CAA91E87B1B21385E1, NULL,
N'ALTER proc [dbo].[uspGetCustomerWiseSalesFooter]  
 @CustID INT = 299,@BeatID INT = 0,@SalesManID INT = 0,@BranchName NVARCHAR(255) = ''4'',@BeatName NVARCHAR(255) = '''',@SalesmanName NVARCHAR(255) = '''',  
 @CustomerName NVARCHAR(255) = '''',@CustomerType NVARCHAR(255) = '''',@Ratings NVARCHAR(255) = '''',@FromDate DATE = ''2025-08-01'',@ToDate DATE = ''2025-08-30''     
as  
SET NOCOUNT ON;
begin  
SELECT MC.Code [Customer Code],MC.Name [Customer Name],
DocId AS [Doc ID],CONVERT(NVARCHAR,InvDate,103) AS [Doc Date],DocRef AS [Doc Ref],MBO.Name [Branch Name],     
dbo.fnGetRoundedValue(TSH.NetAmt) AS [Net Amount],    
dbo.fnGetRoundedValue (TSH.Balance) AS [Balance]    
FROM tblTranSalesHeader AS TSH    
join tblMasterBranchoffice MBO ON MBO.ID = TSH.BRANCHID  
join tblMasterCustomer MC ON MC.ID = @CustID
WHERE TSH.[Status] IN (1,3,5) AND TSH.DocPrefix = 15 AND (TSH.InvDate BETWEEN @FromDate AND @ToDate) and  
TSH.BranchID = (case when isnull(@BranchName,''0'') = ''0'' THEN TSH.BranchID ELSE @BranchName END)  
AND TSH.CustId = @CustID AND ISNULL(TSH.BeAtId,0)=@BeatID AND ISNULL(TSH.SalesManId,0)=@SalesManID    
order by tsh.ID    
end',
N'[export] nocount';
GO
/****** uspGetCustomerWiseSalesHeader ******/
EXEC #Apply07 N'dbo.uspGetCustomerWiseSalesHeader', 0xD1470AAEF60D1F1E45410D328C8B5D0785549DA798E1081D59677FEE4B2E9A14, 0x1216B217D0C7ACE6E644D04ED7EBB3FAC97126F99660328042450766E0171116, NULL, 0x2841BF5B16ECF5477DCBFFB2ABD3682B96B7A4BC8F0AB78C11E220F39EDAF22E, 0x599BA7CBD93E72F9159891805638E48AFBD051682F6B05A3C66E85060071DF0E, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspGetCustomerWiseSalesHeader]      
@BranchName NVARCHAR(255) = ''0'',@BeatName NVARCHAR(255) = '''',@SalesmanName NVARCHAR(255) = '''',@CustomerName NVARCHAR(255) = '''',@CustomerType NVARCHAR(255) = '''',    
@Ratings NVARCHAR(255) = '''',@FromDate DATE = ''2025-08-01'',@ToDate DATE = ''2025-08-30''       
AS    
SET NOCOUNT ON;
BEGIN    
declare @StrQuery nvarchar(max) = ''''      
 set @StrQuery = '' SELECT MC.ID CustomerID,ISNULL(TSH.BeatId,0) AS [BeatID],ISNULL(TSH.SalesManId,0) AS SalesManID,    
MC.Code AS [Customer Code],MC.Name AS [Customer Name],Beat.Name AS [Beat Name],SM.Name AS [SalesMan Name],      
MCT.Name AS [Customer Type],RT.RatingName [Ratings],COUNT(TSH.ID) AS [Inv Count],                
dbo.fnGetRoundedValue(SUM(TSH.NetAmt)) AS [Net Amount],dbo.fnGetRoundedValue(SUM(TSH.Balance)) AS [Balance Amount]                
FROM tblTranSalesHeader AS TSH                
JOIN tblMasterCustomer AS MC ON MC.ID = TSH.CustId                
LEFT JOIN tblMasterBeat AS Beat ON Beat.ID = TSH.BeatID          
LEFT JOIN tblMasterSalesMan AS SM ON SM.ID = TSH.SalesManId          
LEFT JOIN tblMasterCustomerType AS MCT ON MCT.ID = MC.CustomerType     
LEFT JOIN tblRatings AS RT ON RT.ID = MC.Rating    
WHERE TSH.[Status] IN (1,3,5) AND TSH.DocPrefix = 15 ''    
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)                  
  
    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BranchName,''0'')=''0'' THEN '''' ELSE '' AND TSH.BranchID =  @BranchName '' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND Beat.ID IN (SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)           
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND SM.ID IN (SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND MC.ID IN (SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND MCT.ID IN (SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RT.ID IN (SELECT * from dbo.fnSplitString(  @Ratings ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + '' GROUP BY MC.ID,TSH.BeatId,TSH.SalesManId,MC.Code,MC.Name,Beat.Name,SM.Name,MCT.Name,RT.RatingName''    
EXEC sys.sp_executesql @StrQuery, N''@BranchName NVARCHAR(255), @BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BranchName, @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @FromDate, @ToDate    
END',
N'[06] nocount';
GO
/****** uspGetCustWiseMonthlySalesHeader ******/
EXEC #Apply07 N'dbo.uspGetCustWiseMonthlySalesHeader', 0x2E9907B9BAC220F83E9D666FD7BEFDAAF1D43F5EE566D687C67C30C2A83D8F0B, 0x2CC2ABBD654A2483585C6D8A7652FDB4FA7B4A619FC3380AAE4936245F9C0F3A, NULL, 0xF43A56F352B79B6A208519D6B72E58A401902F345AE5ABB1780BD22CF805CC23, 0x18ED8CFB712E35F8F10E2F5D9058738A6B9E3968DA250702160618505C950A22, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspGetCustWiseMonthlySalesHeader]      
@BeatName NVARCHAR(255) = '''',@SalesmanName NVARCHAR(255) = '''',@CustomerName NVARCHAR(255) = '''',@CustomerType NVARCHAR(255) = '''',@Ratings NVARCHAR(255)='''',      
@Type NVARCHAR(255) = ''1'',    @FilterBy NVARCHAR(255) = ''0'',@FromDate DATE = ''2025-07-01'',@ToDate DATE = ''2025-08-30''       
AS      
SET NOCOUNT ON;
BEGIN      
declare @StrQuery nvarchar(max) = ''''      
-- Create #TempTable1 for Get Need Records                                        
  CREATE TABLE #Temp (CustId INT,BeatId INT,SalesmanId INT,[Customer Code] NVARCHAR(255),[Customer Name] NVARCHAR(255),[Customer Type] NVARCHAR(255),[Ratings] NVARCHAR(255), [Beat Name] NVARCHAR(255)            
  ,[SalesMan Name] NVARCHAR(255),[Selected Amount] DECIMAL(25,2),MY NVARCHAR(20),Value DECIMAL(25,2))        
  CREATE TABLE #Temp1 (CustId INT,BeatId INT,SalesmanId INT,[Customer Code] NVARCHAR(255),[Customer Name] NVARCHAR(255),[Customer Type] NVARCHAR(255),[Ratings] NVARCHAR(255),[Beat Name] NVARCHAR(255)            
  ,[SalesMan Name] NVARCHAR(255),[Selected Amount] DECIMAL(25,2),MY NVARCHAR(20),Value DECIMAL(25,2))        
 Declare @exc Table(id int identity(1,1),DocID NVARCHAR(255),Name NVARCHAR(255),nIndex INT)         
  IF(@Type != ''3'')          
    BEGIN        
set @StrQuery = '' SELECT CustId,BeatID,SalesManID,[Customer Code],[Customer Name],[Customer Type],Ratings,[Beat Name],            
  [SalesMan Name],ISNULL(SUM([Selected Amount]),0) [Selected Amount],MY,SUM(ISNULL(Value,0)) Value FROM (            
 SELECT MC.ID CustId,ISNULL(MB.ID,0) AS BeatID,ISNULL(MSM.ID,0) AS SalesManID,MC.Code AS [Customer Code],              
MC.Name AS [Customer Name],mct.Name AS [Customer Type],              
ISNULL(MB.Name,''''Default Beat'''') AS [Beat Name], ISNULL(MSM.Name,''''Default SalesMan'''') AS [SalesMan Name],              
0 AS [Selected Amount],            
UPPER(CONVERT(nvarchar(3),DATENAME(month,InvDate))) +'''' ''''+ CONVERT(NVARCHAR(10),YEAR(InvDate)) AS MY,            
(CASE WHEN ''+ '' @Type ''+''=''''2'''' THEN (SUM(TSH.GrossAmt)) ELSE (SUM(TSH.NetAmt))END) AS Value,      
RT.RatingName Ratings      
FROM tblTranSalesHeader AS TSH             
JOIN tblMasterCustomer AS MC ON MC.ID = TSH.CustId              
left join tblMasterCustomerType as mct on mct.ID=MC.CustomerType              
LEFT JOIN tblMasterBeat AS MB ON MB.ID = TSH.BeatID              
LEFT JOIN tblMasterSalesMan AS MSM ON MSM.ID = TSH.SalesManId        
LEFT JOIN tblRatings AS RT ON RT.ID = MC.Rating        
WHERE TSH.DocPrefix=15 AND TSH.Status IN (1,3,5) ''            
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)                  
  
    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND MC.ID IN (SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)                          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND MSM.ID IN (SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)           
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND MCT.ID IN (SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RT.ID IN (SELECT * from dbo.fnSplitString(  @Ratings ,'''',''''))'' END)                     
SET @StrQuery = @StrQuery + '' GROUP BY MC.Code,MC.Name,mct.Name,MC.ID,MB.Name,MSM.Name,MB.ID,MSM.ID,            
InvDate,RT.RatingName) AS NK GROUP BY CustId,BeatID,SalesManID,[Customer Code],[Customer Name],[Customer Type],[Beat Name],             
 [SalesMan Name],MY,Ratings''         
 END      
 ELSE      
 BEGIN      
 set @StrQuery = '' SELECT CustId,BeatID,SalesManID,[Customer Code],[Customer Name],[Customer Type],Ratings,[Beat Name],            
  [SalesMan Name],ISNULL(SUM([Selected Amount]),0) [Selected Amount],MY,SUM(ISNULL(Value,0)) Value FROM (            
 SELECT MC.Id CustId,ISNULL(MB.Id,0) AS BeatID,ISNULL(MSM.Id,0) AS SalesManID,MC.Code AS [Customer Code],              
MC.Name AS [Customer Name],mct.Name AS [Customer Type],              
ISNULL(MB.Name,''''Default Beat'''') AS [Beat Name], ISNULL(MSM.Name,''''Default SalesMan'''') AS [SalesMan Name],              
0 AS [Selected Amount],            
UPPER(CONVERT(nvarchar(3),DATENAME(month,ColDate))) +'''' ''''+ CONVERT(NVARCHAR(10),YEAR(ColDate)) AS MY,            
SUM(TSH.ColAmt) AS Value,RT.RatingName Ratings            
FROM tblTranCollectionHeader AS TSH             
JOIN tblMasterCustomer AS MC ON MC.FAID = TSH.AccID              
left join tblMasterCustomerType as mct on mct.ID=MC.CustomerType              
LEFT JOIN tblMasterBeat AS MB ON MB.ID = TSH.BeatID              
LEFT JOIN tblMasterSalesMan AS MSM ON MSM.ID = TSH.SalesManId        
LEFT JOIN tblRatings AS RT ON RT.ID = MC.Rating             
WHERE TSH.DocPrefix= 19 AND TSH.Status IN (1,3,5)  ''            
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.ColDate BETWEEN  @FromDate  AND  @ToDate )'' END)                 
   
    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND MC.ID IN (SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)                          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND MSM.ID IN (SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)           
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND MCT.ID IN (SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RT.ID IN (SELECT * from dbo.fnSplitString(  @Ratings ,'''',''''))'' END)                   
SET @StrQuery = @StrQuery + '' GROUP BY MC.Code,MC.Name,mct.Name,MC.Id,MB.Name,MSM.Name,MB.Id,MSM.Id,            
ColDate,RT.RatingName) AS NK GROUP BY CustId,BeatID,SalesManID,[Customer Code],[Customer Name],[Customer Type],[Beat Name],             
 [SalesMan Name],MY,Ratings''        
 END      
  insert into #Temp1        
  EXEC sys.sp_executesql @StrQuery, N''@BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @Type NVARCHAR(255), @FilterBy NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @Type, @FilterBy, @FromDate, @ToDate      
      
        
 set @StrQuery = ''select '' + case when @FilterBy = ''1'' or  @FilterBy = ''0'' THEN ''CustId,BeatId,SalesmanId,[Customer Code],[Customer Name],        
 [Customer Type],Ratings,[Beat Name],[SalesMan Name],ISNULL(SUM([Selected Amount]),0),MY,SUM(ISNULL(Value,0)) Value''         
 WHEN @FilterBy = ''2'' THEN '' 0,BeatId,0,'''''''','''''''','''''''','''''''',[Beat Name],'''''''',ISNULL(SUM([Selected Amount]),0),MY,SUM(ISNULL(Value,0)) Value ''         
 WHEN @FilterBy = ''3'' THEN '' 0,0,SalesmanId,'''''''','''''''','''''''','''''''','''''''',[SalesMan Name],ISNULL(SUM([Selected Amount]),0),MY,SUM(ISNULL(Value,0)) Value ''        
 WHEN @FilterBy = ''4'' THEN '' CustId,0,0,[Customer Code],[Customer Name],[Customer Type],Ratings,'''''''','''''''',ISNULL(SUM([Selected Amount]),0),MY,SUM(ISNULL(Value,0)) Value ''         
 else '''''''' end  + '' from #Temp1 ''        
 set @StrQuery += '' GROUP BY ''+ case when @FilterBy = ''1'' or  @FilterBy = ''0'' THEN ''CustId,BeatId,SalesmanId,[Customer Code],[Customer Name],        
 [Customer Type],Ratings,[Beat Name],[SalesMan Name],MY''         
 WHEN @FilterBy = ''2'' THEN '' BeatId,[Beat Name],MY ''         
 WHEN @FilterBy = ''3'' THEN '' SalesmanId,[SalesMan Name],MY ''        
 WHEN @FilterBy = ''4'' THEN '' CustId,[Customer Code],[Customer Name],MY,Ratings,[Customer Type] ''         
 else '''''''' end        
 --select * from #Temp          
  insert into #Temp          
 EXEC sys.sp_executesql @StrQuery, N''@BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @Type NVARCHAR(255), @FilterBy NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @Type, @FilterBy, @FromDate, @ToDate             
CREATE TABLE #VNAMES (ID INT IDENTITY(1,1),MFD DATE,MY NVARCHAR(50))            
CREATE TABLE #VNAMESISNULL (ID INT IDENTITY(1,1),MFD DATE,MY NVARCHAR(50))            
INSERT INTO #vnames             
SELECT DISTINCT (DATEADD(mm, DATEDIFF(mm, 0, MY),0)), MY FROM #Temp            
INSERT INTO #VNAMESISNULL            
SELECT DISTINCT (DATEADD(mm, DATEDIFF(mm, 0, MY),0)), ''ISNULL([''+MY+''],0)'' FROM #Temp            
DECLARE @PCol NVARCHAR(MAX),@PCol1 NVARCHAR(MAX)            
SELECT @PCol = COALESCE(@PCol+'','','''') + QUOTENAME(MY) FROM #vnames GROUP BY MY,MFD ORDER BY MFD            
SELECT @PCol1 = COALESCE(@PCol1+''+'','''') +   (MY)  FROM #VNAMESISNULL GROUP BY MY,MFD ORDER BY MFD            
set @StrQuery = '' SELECT [Customer Code],[Customer Name],[Customer Type],Ratings,[Beat Name],[SalesMan Name],            
 ''+ @PCol1 +''  AS [Selected Amount],'' + @PCol +''  FROM #Temp            
PIVOT ( SUM(Value) FOR MY IN (''+ @PCol +'')) AS NKPIV ''            
EXEC sys.sp_executesql @StrQuery, N''@BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @Type NVARCHAR(255), @FilterBy NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @Type, @FilterBy, @FromDate, @ToDate            
DROP TABLE #Temp,#VNAMES,#VNAMESISNULL,#Temp1       
END',
N'[06] nocount';
GO
/****** uspGetCustWiseProdDisc ******/
EXEC #Apply07 N'dbo.uspGetCustWiseProdDisc', 0xBE9BEB593A13274FEBD47D33ADD50A9CB7D5362E5920B1525EB0A517AF2A86F7, NULL, NULL, 0xC65318C0E5BCCE00626D2310D599B61BE180DDE9CC28B2A7ED96A288D79434FB, 0xA0464F81F40950D67BCE71E8372023A0A6F43FD0B8EAF9E54059C1783232F9ED, NULL,
N'--uspGetCustWiseProdDisc ''2026-04-16'',459,27      
ALTER PROC [dbo].[uspGetCustWiseProdDisc]      
@DocDate DATE,@CustID INT,@ProdID INT      
AS      
SET NOCOUNT ON;
BEGIN  
DECLARE @IsReplaceCount INT, @IsReplace INT,@CustomerHaveScheme int = 0  
declare  @ManufID int,@BrandID int,@CategoryID int,@SalesTradeDiscbeforeProdDisc INT

SET @SalesTradeDiscbeforeProdDisc = (SELECT AppValue FROM tblAppConfig WHERE AppId = 46)

SET @CustomerHaveScheme = (select  COUNT(*) from tblMasterDiscountSchemeHeader DSH   
JOIN tblMasterDiscountSchemeCustomers DSC ON DSC.ID = DSH.ID   
WHERE DSC.CustomerID = @CustID  AND (@DocDate BETWEEN DSH.FromDate AND DSH.ToDate)      
AND DSH.Active = 1)  
IF(@CustomerHaveScheme = 0)  
BEGIN  
PRINT '' CUSTOMER HAVE NO SCHEME''  
RETURN;  
END  
PRINT '' CUSTOMER HAVE SCHEME''  
  
SELECT @ManufID = MfrID,@BrandID = BrandID,@CategoryID = CategoryID FROM TBLMASTERPRODUCT WHERE ID = @ProdID  
SET @IsReplaceCount = (SELECT SUM(CONVERT(INT,NK.IsReplace)) AS [COUNT] FROM      
(SELECT SH.IsReplace FROM tblMasterDiscountSchemeDetail AS SD      
JOIN tblMasterDiscountSchemeHeader AS SH ON SH.ID = SD.ID      
JOIN tblMasterDiscountSchemeCustomers AS DISCUS ON DISCUS.ID = SH.ID  
WHERE DISCUS.CustomerID = @CustID AND SD.ProdID = @ProdID and ApplyIn = 1 AND (@DocDate BETWEEN SH.FromDate AND SH.ToDate)      
AND SH.Active = 1   GROUP BY SH.IsReplace  
union  
SELECT SH.IsReplace FROM tblMasterDiscountSchemeDetail AS SD      
JOIN tblMasterDiscountSchemeHeader AS SH ON SH.ID = SD.ID      
JOIN tblMasterDiscountSchemeCustomers AS DISCUS ON DISCUS.ID = SH.ID  
WHERE DISCUS.CustomerID = @CustID AND SD.ProdID = @ManufID and ApplyIn = 2 AND (@DocDate BETWEEN SH.FromDate AND SH.ToDate)      
AND SH.Active = 1   GROUP BY SH.IsReplace  
union  
SELECT SH.IsReplace FROM tblMasterDiscountSchemeDetail AS SD      
JOIN tblMasterDiscountSchemeHeader AS SH ON SH.ID = SD.ID      
JOIN tblMasterDiscountSchemeCustomers AS DISCUS ON DISCUS.ID = SH.ID  
WHERE DISCUS.CustomerID = @CustID AND SD.ProdID = @BrandID and ApplyIn = 3 AND (@DocDate BETWEEN SH.FromDate AND SH.ToDate)      
AND SH.Active = 1   GROUP BY SH.IsReplace  
union  
SELECT SH.IsReplace FROM tblMasterDiscountSchemeDetail AS SD      
JOIN tblMasterDiscountSchemeHeader AS SH ON SH.ID = SD.ID      
JOIN tblMasterDiscountSchemeCustomers AS DISCUS ON DISCUS.ID = SH.ID  
WHERE DISCUS.CustomerID = @CustID AND SD.ProdID = @CategoryID and ApplyIn = 4 AND (@DocDate BETWEEN SH.FromDate AND SH.ToDate)      
AND SH.Active = 1   GROUP BY SH.IsReplace)   
AS NK)  
IF ISNULL(@IsReplaceCount,0) > 0      
BEGIN      
SET @IsReplace = 1      
END      
ELSE      
BEGIN      
SET @IsReplace = 0   
END      
declare @ApplyScheme INT    
SELECT @ApplyScheme = AppValue from tblAppConfig where AppId = 20    
  --ISNULL(@ApplyScheme,0) ApplySchemeinQTN,@IsReplace AS IsReplace,  
  
--SELECT SUM(SD.ProdDisc) AS ProdDisc,SUM(SD.ProdDiscAmt) ProdDiscAmt,SUM(SD.TradeDiscPern) AS TradeDisc,      
--SUM(SD.TradeDiscAmt) TradeDiscAmt      
--FROM tblMasterDiscountSchemeDetail AS SD      
--JOIN tblMasterDiscountSchemeHeader AS SH ON SH.ID = SD.ID      
--WHERE SD.CustID = @CustID AND SD.ProdID = @ProdID      
--AND (@DocDate BETWEEN SH.FromDate AND SH.ToDate) AND SH.Active = 1      
--GROUP BY SD.CustID,SD.ProdID      
  
SELECT ISNULL(@ApplyScheme,0) ApplySchemeinQTN,@IsReplace AS IsReplace, SUM(ISNULL(ProdDisc,0)) AS ProdDisc,SUM(ISNULL(ProdDiscAmt,0)) ProdDiscAmt,SUM(ISNULL(TradeDisc,0)) AS TradeDisc,      
SUM(ISNULL(TradeDiscAmt,0)) TradeDiscAmt,@SalesTradeDiscbeforeProdDisc SalesTradeDiscbeforeProdDisc  FROM (  
SELECT SUM(ISNULL(SD.ProdDisc,0)) AS ProdDisc,SUM(ISNULL(SD.ProdDiscAmt,0)) ProdDiscAmt,SUM(ISNULL(SD.TradeDiscPern,0)) AS TradeDisc,      
SUM(ISNULL(SD.TradeDiscAmt,0)) TradeDiscAmt      
FROM tblMasterDiscountSchemeDetail AS SD      
JOIN tblMasterDiscountSchemeHeader AS SH ON SH.ID = SD.ID      
JOIN tblMasterDiscountSchemeCustomers AS DISCUS ON DISCUS.ID = SH.ID  
WHERE DISCUS.CustomerID = @CustID AND SD.ProdID = @ProdID      
AND (@DocDate BETWEEN SH.FromDate AND SH.ToDate) AND SH.Active = 1    and ApplyIn = 1  
GROUP BY SD.CustID,SD.ProdID      
UNION ALL  
SELECT SUM(ISNULL(SD.ProdDisc,0)) AS ProdDisc,SUM(ISNULL(SD.ProdDiscAmt,0)) ProdDiscAmt,SUM(ISNULL(SD.TradeDiscPern,0)) AS TradeDisc,      
SUM(ISNULL(SD.TradeDiscAmt,0)) TradeDiscAmt      
FROM tblMasterDiscountSchemeDetail AS SD      
JOIN tblMasterDiscountSchemeHeader AS SH ON SH.ID = SD.ID      
JOIN tblMasterDiscountSchemeCustomers AS DISCUS ON DISCUS.ID = SH.ID  
WHERE DISCUS.CustomerID = @CustID AND SD.ProdID = @ManufID      
AND (@DocDate BETWEEN SH.FromDate AND SH.ToDate) AND SH.Active = 1    and ApplyIn = 2  
GROUP BY SD.CustID,SD.ProdID      
UNION ALL  
SELECT SUM(ISNULL(SD.ProdDisc,0)) AS ProdDisc,SUM(ISNULL(SD.ProdDiscAmt,0)) ProdDiscAmt,SUM(ISNULL(SD.TradeDiscPern,0)) AS TradeDisc,      
SUM(ISNULL(SD.TradeDiscAmt,0)) TradeDiscAmt      
FROM tblMasterDiscountSchemeDetail AS SD      
JOIN tblMasterDiscountSchemeHeader AS SH ON SH.ID = SD.ID      
JOIN tblMasterDiscountSchemeCustomers AS DISCUS ON DISCUS.ID = SH.ID  
WHERE DISCUS.CustomerID = @CustID AND SD.ProdID = @BrandID      
AND (@DocDate BETWEEN SH.FromDate AND SH.ToDate) AND SH.Active = 1    and ApplyIn = 3  
GROUP BY SD.CustID,SD.ProdID      
UNION ALL  
SELECT SUM(ISNULL(SD.ProdDisc,0)) AS ProdDisc,SUM(ISNULL(SD.ProdDiscAmt,0)) ProdDiscAmt,SUM(ISNULL(SD.TradeDiscPern,0)) AS TradeDisc,      
SUM(ISNULL(SD.TradeDiscAmt,0)) TradeDiscAmt      
FROM tblMasterDiscountSchemeDetail AS SD      
JOIN tblMasterDiscountSchemeHeader AS SH ON SH.ID = SD.ID      
JOIN tblMasterDiscountSchemeCustomers AS DISCUS ON DISCUS.ID = SH.ID  
WHERE DISCUS.CustomerID = @CustID AND SD.ProdID = @CategoryID      
AND (@DocDate BETWEEN SH.FromDate AND SH.ToDate) AND SH.Active = 1    and ApplyIn = 4  
GROUP BY SD.CustID,SD.ProdID    ) AS NK  
  
END',
N'[export] nocount';
GO
/****** uspGetDataforEInvoiceJSON ******/
EXEC #Apply07 N'dbo.uspGetDataforEInvoiceJSON', 0xDDF5B9CC7FF6AC018890177EBCEC006DE7769587B537D3202CC0F656A066BCE0, NULL, NULL, 0x7C13D9F2FCA4F9E5396FE76480BBBF12925EA92BB15A05536888DCDF9925F1DE, 0x8C1A85E383D673E5197DDD545CA933959236D233EFEEBF302BE43544E55DB1B1, NULL,
N'--[uspGetDataforEInvoiceJSON] 2,''INV/2627/JUL1'',''01/07/2026'',''Tax Invoice''
ALTER PROC [dbo].[uspGetDataforEInvoiceJSON]
@mode int, @docid nvarchar(50)= NULL,@DocDate DATE = NULL,@DocType NVARCHAR(255) = ''Tax Invoice''
as
SET NOCOUNT ON;
BEGIN
set dateformat dmy;
IF(@mode = 1)
BEGIN
--"TranDtls"
select ''GST'' "TaxSch",''B2B'' "SupTyp",''N'' "IgstOnIntra",null "RegRev",null "EcmGstin"
END
ELSE IF(@mode = 2)
BEGIN
--"DocDtls"
IF(@DocType = ''Tax Invoice'' OR @DocType = ''Credit Note'')
BEGIN
select (CASE WHEN DocPrefix = 15 THEN ''INV'' ELSE ''CRN'' END) "Typ", DocId "No",CONVERT(NVARCHAR,InvDate,103) "Dt"
from tblTranSalesHeader
WHERE DocId = @docid AND InvDate = @DocDate
and ISNULL(IRN,'''') = '''' AND DocPrefix IN (15,16) AND Status IN (1,3,5,6,7)
END
ELSE
BEGIN
select ''DBN'' "Typ", DocId "No",CONVERT(NVARCHAR,Date,103) "Dt" from tblTransPurchaseHeader WHERE DocId = @docid AND Date = @DocDate
and ISNULL(IRN,'''') = '''' AND TransID IN (12) AND Status IN (3,5,6,7)
END
END
ELSE IF(@mode = 3)
BEGIN
--"SellerDtls"
SELECT GSTIN "Gstin",LEFT(CompanyName,100) "LglNm",LEFT(CompanyName,100) "TrdNm",LEFT(Address,100) "Addr1",NULL "Addr2",
(case when isnull(City,'''') = '''' then null else LEFT(City,50) end) "Loc",CONVERT(int,Pincode) "Pin",
LEFT(GSTIN,2) "Stcd",(case when isnull(MobileNo,'''') = '''' then null else MobileNo end) "Ph",
(case when isnull(email,'''') = '''' then null else email end) "Em" FROM tblCompanyRegistration
END
ELSE IF(@mode = 4)
BEGIN
--"BuyerDtls" / CustoemrDetails
IF(@DocType = ''Tax Invoice'' OR @DocType = ''Credit Note'')
BEGIN
select MC.GSTIN Gstin,LEFT(MC.Name,100) LglNm,LEFT(MC.Name,100) TrdNm,LEFT(GSTIN,2) Pos,
(case when isnull(Billadd1,'''') = '''' then null else LEFT(Billadd1,100) end) Addr1,
(case when isnull(Billadd2,'''') = '''' then null else LEFT(Billadd2,100) end) Addr2,
(case when isnull(Billadd3,'''') = '''' OR LEN(Billadd3) < 3 then ''CHN'' else LEFT(Billadd3,100) end) Loc,
CONVERT(int,Pincode) Pin,LEFT(GSTIN,2) Stcd,
(case when isnull(MC.Mob1,'''') = '''' then null else MC.Mob1 end) Ph,
(case when isnull(MC.Email,'''') = '''' then null else MC.Email end) Em
from tblTranSalesHeader SH
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId
WHERE DocId = @docid AND InvDate = @DocDate and ISNULL(IRN,'''') = '''' AND DocPrefix IN (15,16) AND Status IN (1,3,5,6,7)
and ISNULL(MC.GSTIN,'''') != ''''
END
ELSE
BEGIN
select MC.GSTIN Gstin,LEFT(MC.name,100) LglNm,LEFT(MC.name,100) TrdNm,LEFT(GSTIN,2) Pos,
(case when isnull(Billadd1,'''') = '''' then null else LEFT(Billadd1,100) end) Addr1,
(case when isnull(Billadd2,'''') = '''' then null else LEFT(Billadd2,100) end) Addr2,
(case when isnull(Billadd3,'''') = '''' OR LEN(Billadd3) < 3 then ''CHN'' else LEFT(Billadd3,100) end) Loc,
CONVERT(int,Pincode) Pin,LEFT(GSTIN,2) Stcd,
(case when isnull(MC.Mob1,'''') = '''' then null else MC.Mob1 end) Ph,
(case when isnull(MC.Email,'''') = '''' then null else MC.Email end) Em
from tblTranspurchaseheader SH
JOIN tblMasterVendor MC ON MC.id = SH.VendorID
WHERE DocId = @docid AND Date = @DocDate and ISNULL(IRN,'''') = ''''
AND TransID IN (12) AND Status IN (3,5,6,7) and ISNULL(MC.GSTIN,'''') != ''''
END
END
else if(@mode = 5)
BEGIN

SELECT TransID,TransIdentID,(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],
SUM([GCESS Amount] + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #Tax
FROM
(
SELECT SRI.TransID,SRI.TransIdentID,
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]
FROM
(
SELECT * FROM
(
SELECT Temp.TransID,Temp.TransIdentID,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],
Temp.TaxName AS TaxName,
SUM(Temp.TaxValue) AS [TaxValue]--, SUM(Temp.[Gross Amount]) AS [Gross Amount]
FROM
(
SELECT GSTInfo.TransID,GSTInfo.TransIdentID,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,
CASE
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''
END AS [GST Comp]
FROM tblTransGSTInfo AS GSTInfo
JOIN tblTranSalesHeader SH ON SH.ID = GSTInfo.TransIdentID AND SH.DocPrefix = GSTInfo.TransID
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID
WHERE DocId = @docid AND (TransID=15 or TransID=16) AND Status IN (1,3,5,6,7) AND InvDate = @DocDate AND ISNULL(IRN,'''') = ''''
) Temp
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.TransID,Temp.TransIdentID
) src
PIVOT
(
SUM([TaxValue])
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])
) piv
) AS SRI
) AS RAM
GROUP BY TransID,TransIdentID
--SELECT * FROM #Tax
-- PR
SELECT TransID,TransIdentID,(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],
SUM([GCESS Amount] + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #TaxPR
FROM
(
SELECT SRI.TransID,SRI.TransIdentID,
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]
FROM
(
SELECT * FROM (
SELECT Temp.TransID,Temp.TransIdentID,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],
Temp.TaxName AS TaxName,
SUM(Temp.TaxValue) AS [TaxValue]
FROM
(
SELECT GSTInfo.TransID,GSTInfo.TransIdentID,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,
CASE
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''
END AS [GST Comp]
FROM tblTransGSTInfo AS GSTInfo
JOIN tblTransPurchaseHeader SH ON SH.ID = GSTInfo.TransIdentID AND SH.TransID = GSTInfo.TransID
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID
WHERE DocId = @docid AND (SH.TransID=12) AND Status IN (3,5,6,7) AND Date = @DocDate AND ISNULL(IRN,'''') = ''''
) Temp
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.TransID,Temp.TransIdentID
) src
PIVOT
(
SUM([TaxValue])
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])
) piv
) AS SRI
) AS RAM
GROUP BY TransID,TransIdentID
SELECT * INTO #MainTax FROM (
SELECT * FROM #Tax
UNION ALL
SELECT * FROM #TaxPR) AS REC
--select * from #MainTax MT


--"ValDtls"
IF(@DocType = ''Tax Invoice'' OR @DocType = ''Credit Note'')
BEGIN
select dbo.funTwoDecimalRoundOff(GrossAmt) "AssVal",dbo.funTwoDecimalRoundOff([IGST Amount]) "IgstVal",
dbo.funTwoDecimalRoundOff([CGST Amount]) "CgstVal",dbo.funTwoDecimalRoundOff([SGST Amount]) "SgstVal",
CASE WHEN SH.TaxTypeID = 1 THEN dbo.funTwoDecimalRoundOff([GCESS Amount] + [GUOM Amount]) ELSE
dbo.funTwoDecimalRoundOff([ICESS Amount]+ [IUOM Amount]) END "CesVal",0 "StCesVal",
(case when SH.OtherChargeAmt < 0 then dbo.funTwoDecimalRoundOff(ABS(SH.OtherChargeAmt)) else 0 end) "Discount",
(case when SH.OtherChargeAmt >= 0 then dbo.funTwoDecimalRoundOff(SH.OtherChargeAmt + SH.TCSTaxAmt) else
dbo.funTwoDecimalRoundOff(SH.TCSTaxAmt) end) "OthChrg",
dbo.funTwoDecimalRoundOff(RoundOfAmt) "RndOffAmt",
dbo.funTwoDecimalRoundOff(NetAmt) "TotInvVal" from tblTranSalesHeader SH
JOIN #MainTax TG ON TG.TransIdentID = SH.ID AND TG.TransID = SH.DocPrefix
WHERE DocId = @docid AND InvDate = @DocDate
and ISNULL(IRN,'''') = '''' AND DocPrefix IN (15,16) AND Status IN (1,3,5,6,7)
END
ELSE
BEGIN
select dbo.funTwoDecimalRoundOff(GrossAmt) "AssVal",(CASE WHEN TaxTypeID = 2 THEN dbo.funTwoDecimalRoundOff(TaxAmt) ELSE ''0'' END) "IgstVal",
dbo.funTwoDecimalRoundOff([CGST Amount]) "CgstVal",dbo.funTwoDecimalRoundOff([SGST Amount]) "SgstVal",
CASE WHEN SH.TaxTypeID = 1 THEN dbo.funTwoDecimalRoundOff([GCESS Amount]) ELSE
dbo.funTwoDecimalRoundOff([ICESS Amount]) END "CesVal",0 "StCesVal",
(case when SH.OtherChargeAmt < 0 then dbo.funTwoDecimalRoundOff(ABS(SH.OtherChargeAmt)) else 0 end) "Discount",
(case when SH.OtherChargeAmt >= 0 then dbo.funTwoDecimalRoundOff(SH.OtherChargeAmt + SH.TCSTaxAmt) else
dbo.funTwoDecimalRoundOff(SH.TCSTaxAmt) end) "OthChrg",
dbo.funTwoDecimalRoundOff(RoundOffAmt) "RndOffAmt",
dbo.funTwoDecimalRoundOff(NetAmt) "TotInvVal"
from tblTransPurchaseHeader SH
JOIN #MainTax TG ON TG.TransIdentID = SH.ID AND TG.TransID = SH.TransID
WHERE DocId = @docid
AND Date = @DocDate and ISNULL(IRN,'''') = '''' AND SH.TransID IN (12) AND Status IN (3,5,6,7)
END
DROP TABLE #Tax,#TaxPR,#MainTax
END
else if(@mode = 6)
BEGIN
--"ItemList"
SELECT GSTSerial,ProdID,TransID,TransIdentID,(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],
SUM([GCESS Amount] + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #TaxItems
FROM
(
SELECT GSTSerial,sri.ProdID,SRI.TransID,SRI.TransIdentID,--SRI.[Gross Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]
FROM
(
SELECT * FROM
(
SELECT GSTSerial,Temp.ProdID,Temp.TransID,Temp.TransIdentID,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],
Temp.TaxName AS TaxName,
SUM(Temp.TaxValue) AS [TaxValue]--, SUM(Temp.[Gross Amount]) AS [Gross Amount]
FROM
(
SELECT Serial GSTSerial,GSTInfo.ProdID,GSTInfo.TransID,GSTInfo.TransIdentID,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,
CASE
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''
END AS [GST Comp]--, GSTInfo.GrossAmt AS [Gross Amount]
FROM tblTransGSTInfo AS GSTInfo
JOIN tblTranSalesHeader SH ON SH.ID = GSTInfo.TransIdentID AND SH.DocPrefix = GSTInfo.TransID
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID
WHERE SH.DocId = @docid AND (TransID=15 or TransID=16)
AND Status IN (1,3,5,6,7) AND InvDate = @DocDate and ISNULL(IRN,'''') = ''''
) Temp
GROUP BY GSTSerial,Temp.ProdID,Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.TransID,Temp.TransIdentID
) src
PIVOT
(
SUM([TaxValue])
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])
) piv
) AS SRI
) AS RAM
GROUP BY GSTSerial,ProdID,TransID,TransIdentID
--SELECT * FROM #Tax
-- PR
SELECT GSTSerial,ProdID,TransID,TransIdentID,(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],
SUM([GCESS Amount] + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #TaxPRItems
FROM
(
SELECT GSTSerial,ProdID,SRI.TransID,SRI.TransIdentID,--SRI.[Gross Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]
FROM
(
SELECT * FROM
(
SELECT GSTSerial,ProdID,Temp.TransID,Temp.TransIdentID,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],
Temp.TaxName AS TaxName,
SUM(Temp.TaxValue) AS [TaxValue]--, SUM(Temp.[Gross Amount]) AS [Gross Amount]
FROM
(
SELECT Serial GSTSerial,ProdID,GSTInfo.TransID,GSTInfo.TransIdentID,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,
CASE
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''
END AS [GST Comp]--, GSTInfo.GrossAmt AS [Gross Amount]
FROM tblTransGSTInfo AS GSTInfo
JOIN tblTransPurchaseHeader SH ON SH.ID = GSTInfo.TransIdentID AND SH.TransID = GSTInfo.TransID
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID
WHERE SH.DocId = @docid AND (SH.TransID = 12) AND Status IN (3,5,6,7)
AND Date = @DocDate and ISNULL(IRN,'''') = ''''
) Temp
GROUP BY GSTSerial,ProdID,Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.TransID,Temp.TransIdentID
) src
PIVOT
(
SUM([TaxValue])
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])
) piv
) AS SRI
) AS RAM
GROUP BY GSTSerial,ProdID,TransID,TransIdentID
SELECT * INTO #MainTaxItems FROM (
SELECT * FROM #TaxItems
UNION ALL
SELECT * FROM #TaxPRItems) AS REC
--select * from #MainTaxItems MT


IF(@DocType = ''Tax Invoice'' OR @DocType = ''Credit Note'')
BEGIN
SELECT CONVERT(NVARCHAR,SD.Serial) SlNo,MP.Name PrdDesc,CASE WHEN MP.TrackInventory = 0 THEN ''Y'' ELSE ''N'' END IsServc,MP.HSNCode HsnCd,NULL Barcde,
CONVERT(DECIMAL(25,2),CASE WHEN SD.QtyType != 2 THEN ISNULL(SD.UomQty,0) ELSE 0 END) Qty,
CONVERT(DECIMAL(25,2),CASE WHEN SD.QtyType = 2 THEN ISNULL(SD.UomQty,0) ELSE 0 END) FreeQty,
CASE WHEN UM.Name = ''TIN'' THEN ''NOS'' WHEN UM.Name = ''KG'' THEN ''KGS'' WHEN upper(UM.Name) LIKE ''%GMS'' THEN ''NOS'' WHEN upper(UM.Name)
LIKE ''%KGS'' THEN ''NOS'' ELSE UM.Name END Unit,CONVERT(DECIMAL(25,2),SD.UomPrice) UnitPrice,CONVERT(DECIMAL(25,2),SD.GoodsAmt) TotAmt,
--CONVERT(DECIMAL(25,2),(SD.GoodsAmt * SD.ProdDisc) / 100)
dbo.funTwoDecimalRoundOff(((SD.ProdDisc * SD.GoodsAmt) / 100) + SD.TradeDisc + SD.AddnlDisc) Discount,
0 PreTaxVal, CONVERT(DECIMAL(25,2),SD.GrossAmt) AssAmt,
CASE WHEN SH.TaxTypeID = 1 THEN CONVERT(DECIMAL(25,2),[CGST %] + [SGST %]) ELSE CONVERT(DECIMAL(25,2),[IGST %]) END GstRt, CONVERT(DECIMAL(25,2),TG.[IGST Amount]) IgstAmt,CONVERT(DECIMAL(25,2),TG.[CGST Amount]) CgstAmt,





CONVERT(DECIMAL(25,2),TG.[SGST Amount]) SgstAmt,
CASE WHEN SH.TaxTypeID = 1 THEN CONVERT(DECIMAL(25,2),TG.[GCESS %]) ELSE CONVERT(DECIMAL(25,2),TG.[ICESS %]) END CesRt,
CASE WHEN SH.TaxTypeID = 1 THEN CONVERT(DECIMAL(25,2),TG.[GCESS Amount]) ELSE CONVERT(DECIMAL(25,2),TG.[ICESS Amount]) END CesAmt,
CASE WHEN SH.TaxTypeID = 1 THEN CONVERT(DECIMAL(25,2),TG.[GUOM Amount]) ELSE CONVERT(DECIMAL(25,2),TG.[IUOM Amount]) END CesNonAdvlAmt,0 StateCesRt,0 StateCesAmt,0 StateCesNonAdvlAmt,0 OthChrg,
CONVERT(DECIMAL(25,2),SD.NetAmt)TotItemVal,NULL BchDtls FROM tblTranSalesHeader SH
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId
JOIN #MainTaxItems TG ON TG.TransIdentID = SH.ID AND TG.TransID = SH.DocPrefix and TG.ProdID = SD.ProdId AND TG.GSTSerial = SD.Serial
JOIN tblMasterUom UM ON UM.ID = SD.UomId
WHERE SH.DocId = @docid AND InvDate = @DocDate and ISNULL(IRN,'''') = '''' AND DocPrefix IN (15,16) AND Status IN (1,3,5,6,7)
ORDER BY SD.Serial
END
ELSE
BEGIN
SELECT CONVERT(NVARCHAR,SD.Serial) SlNo,MP.Name PrdDesc,CASE WHEN MP.TrackInventory = 0 THEN ''Y'' ELSE ''N'' END IsServc,MP.HSNCode HsnCd,NULL Barcde,
CONVERT(DECIMAL(25,2),ISNULL(SD.UomQty,0)) Qty,CONVERT(DECIMAL(25,2),ISNULL(SD.UomFreeQty,0)) FreeQty,
CASE WHEN UM.Name = ''TIN'' THEN ''NOS'' WHEN UM.Name = ''KG'' THEN ''KGS'' WHEN upper(UM.Name) LIKE ''%GMS'' THEN ''NOS'' WHEN upper(UM.Name)
LIKE ''%KGS'' THEN ''NOS'' ELSE UM.Name END Unit,
CONVERT(DECIMAL(25,2),SD.UomPurchasePrice) UnitPrice,CONVERT(DECIMAL(25,2),SD.GoodsAmt) TotAmt,
--CONVERT(DECIMAL(25,2),(SD.GoodsAmt * SD.ProdDisc) / 100)
dbo.funTwoDecimalRoundOff(((SD.[ProdDisc%] * SD.GoodsAmt) / 100) +
(((SD.GoodsAmt - ((SD.[ProdDisc%] * SD.GoodsAmt) / 100)) * SD.[TradeDisc%]) / 100) +
(((SD.GoodsAmt - ((SD.[ProdDisc%] * SD.GoodsAmt) / 100)) * SD.[AddnlDisc%]) / 100)) Discount,
0 PreTaxVal, CONVERT(DECIMAL(25,2),SD.GrossAmt) AssAmt,
CASE WHEN SH.TaxTypeID = 1 THEN CONVERT(DECIMAL(25,2),[CGST %] + [SGST %]) ELSE CONVERT(DECIMAL(25,2),[IGST %]) END GstRt,
CONVERT(DECIMAL(25,2),TG.[IGST Amount]) IgstAmt,
CONVERT(DECIMAL(25,2),TG.[CGST Amount]) CgstAmt,
CONVERT(DECIMAL(25,2),TG.[SGST Amount]) SgstAmt,
CASE WHEN SH.TaxTypeID = 1 THEN CONVERT(DECIMAL(25,2),TG.[GCESS %]) ELSE CONVERT(DECIMAL(25,2),TG.[ICESS %]) END CesRt,
CASE WHEN SH.TaxTypeID = 1 THEN CONVERT(DECIMAL(25,2),TG.[GCESS Amount]) ELSE CONVERT(DECIMAL(25,2),TG.[ICESS Amount]) END CesAmt,
CASE WHEN SH.TaxTypeID = 1 THEN CONVERT(DECIMAL(25,2),TG.[GUOM Amount]) ELSE CONVERT(DECIMAL(25,2),TG.[IUOM Amount]) END CesNonAdvlAmt,0 StateCesRt,0 StateCesAmt,0 StateCesNonAdvlAmt,0 OthChrg,
CONVERT(DECIMAL(25,2),SD.NetAmt)TotItemVal,NULL BchDtls FROM tblTransPurchaseHeader SH
JOIN tblTransPurchaseDetail SD ON SD.HID = SH.ID
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId
JOIN #MainTaxItems TG ON TG.TransIdentID = SH.ID AND TG.TransID = SH.TransID and TG.ProdID = SD.ProdId AND TG.GSTSerial = SD.Serial
JOIN tblMasterUom UM ON UM.ID = SD.UomId
WHERE SH.DocId = @docid AND Date = @DocDate and ISNULL(IRN,'''') = '''' AND SH.TransID IN (12) AND Status IN (3,5,6,7)
ORDER BY SD.Serial
END
DROP TABLE #TaxItems,#TaxPRItems,#MainTaxItems
END
ELSE IF(@mode = 7)
BEGIN
--eway dtls
IF(@DocType = ''Tax Invoice'' OR @DocType = ''Credit Note'')
BEGIN
SELECT (case when isnull(TransportID,'''') = '''' then null else LEFT(TransportID,15) end) TransId,
(case when isnull(TransportName,'''') = '''' then null else LEFT(TransportName,100) end) TransName,CONVERT(VARCHAR,(CASE WHEN TransMode = ''Road'' THEN 1 WHEN TransMode = ''Rail'' THEN 2 WHEN TransMode = ''Air'' THEN 3
WHEN TransMode = ''Ship/Road cum Ship'' THEN 4 ELSE null END))TransMode,CONVERT(INT,ISNULL(Distance,0)) Distance ,
CASE WHEN ISNULL(SH.VehicleNo,0) > 0 THEN DocId ELSE NULL END TransDocNo,
CASE WHEN ISNULL(SH.VehicleNo,0) > 0 THEN CONVERT(NVARCHAR,InvDate,103) ELSE NULL END TransDocDt,
VH.VehicleNo VehNo,CASE WHEN SH.VehicleType = ''Regular'' THEN ''R'' WHEN SH.VehicleType = ''ODC'' THEN ''O'' ELSE NULL end VehType
FROM tblTranSalesHeader SH
LEFT JOIN tblMasterVehicle VH ON VH.ID = SH.VehicleNo
WHERE DocId = @docid AND InvDate = @DocDate and ISNULL(IRN,'''') = ''''
AND DocPrefix IN (15,16) AND Status IN (1,3,5,6,7)
END
ELSE
BEGIN
SELECT (case when isnull(TransportID,'''') = '''' then null else LEFT(TransportID,15) end) TransId,
(case when isnull(TransportName,'''') = '''' then null else LEFT(TransportName,100) end) TransName,CONVERT(VARCHAR,(CASE WHEN TransMode = ''Road'' THEN 1 WHEN TransMode = ''Rail'' THEN 2 WHEN TransMode = ''Air'' THEN 3
WHEN TransMode = ''Ship/Road cum Ship'' THEN 4 ELSE null END))TransMode,CONVERT(INT,ISNULL(Distance,0)) Distance ,
CASE WHEN ISNULL(SH.VehicleNo,0) > 0 THEN DocId ELSE NULL END TransDocNo,
CASE WHEN ISNULL(SH.VehicleNo,0) > 0 THEN CONVERT(NVARCHAR,Date,103) ELSE NULL END TransDocDt,
VH.VehicleNo VehNo,CASE WHEN SH.VehicleType = ''Regular'' THEN ''R'' WHEN SH.VehicleType = ''ODC'' THEN ''O'' ELSE NULL end VehType
FROM tblTranspurchaseheader SH
LEFT JOIN tblMasterVehicle VH ON VH.ID = SH.VehicleNo
WHERE DocId = @docid AND SH.Date = @DocDate and ISNULL(IRN,'''') = ''''
AND SH.TransID IN (12) AND Status IN (3,5,6,7)
END
END
ELSE IF(@mode = 8)
BEGIN
SELECT null "ShipBNo",null "ShipBDt",null "Port",null "RefClm",null "ForCur",NULL "CntCode",0 "ExpDuty"
END
END',
N'[export] nocount';
GO
/****** uspGetDataforShinecode ******/
EXEC #Apply07 N'dbo.uspGetDataforShinecode', 0x2518625AF9E27B21ADB57C29EEE2F8B041A1F0B4FA28DCE0871CA6FEE727C48F, NULL, NULL, 0x38E18EB00BDC93862465CA19B74D5678C0D511C365B2748284415D1DC9E6D4FC, 0xF8041A41AFFFC9B6AEA7FBC76639273A896F72237EF3E95140A2101E9C6AAD22, NULL,
N'ALTER proc [dbo].[uspGetDataforShinecode]
@TransID INT = 15, @ID INT = 942
AS
SET NOCOUNT ON;
BEGIN
DECLARE @CompCode NVARCHAR(50)
SELECT @CompCode = CompanyCode FROM tblCompanyRegistration

IF(@TransID = 15)
BEGIN
select @CompCode Sender,SH.ID,SH.InvDate DocDate,SH.DocID,SH.DocPrefix,MC.Shinecode,SH.TradeDisc TradePern,
SH.TotalTradeDiscAmt TradeAmt,SH.AdditionalDisc AddnlPern,SH.AdditionalDiscAmt AddnlAmt,SH.OtherCharge OtherPern,
SH.OtherChargeAmt OtherAmt,Frieght,SH.GrossAmt,SH.RoundOfAmt,SH.TotalTaxAmt TaxAmt,SH.NetAmt,SH.Remarks,SH.Narration,
SH.TotalProdDiscAmt ProdAmt,sh.TotalDiscountAmt
from tblTranSalesHeader SH
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID
where ISNULL(MC.Shinecode,'''') != '''' AND SH.ID = @ID

select SD.InvID,mp.ID ProdID,MP.Code,MP.Name,MP.Shinecode ItemShinecode,SD.UomPrice Price,SD.DetailMRP MRP,SD.UomQty Qty,SD.UomID,SD.TradeDiscPern TradePern,
SD.TradeDisc TradeAmt,SD.AddnlDiscPern AddnlPern,SD.AddnlDisc AddnlAmt,SD.ProdDisc ProdPern,SD.ProdDiscAmt ProdAmt,SD.TaxID,
SD.TaxValue TaxPern,SD.GoodsAmt,SD.GrossAmt,SD.TaxAmt,SD.NetAmt,SD.UOMCF,SD.ReasonID,SD.Serial,PV.BatchNumber,PV.PKDDate,
PV.ExpiryDate
from tblTranSalesDetail SD
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID
JOIN tblProductInventory PV ON PV.InventoryId = SD.InventoryID
where InvID = @ID
END
END',
N'[export] nocount';
GO
/****** uspGetDateofDocument ******/
EXEC #Apply07 N'dbo.uspGetDateofDocument', 0x3290E1529AEFE7582CCD013D4D2181DA43FD4F9DD2F0B364C0588D140C338DC3, NULL, NULL, 0xBB64CD8586FAA252B0550095CF6DCF7B9F0EBE8225C26633099C667FF4824881, 0xE63922AA34A0A3CEF34B1B140E36ACDB6DB3C76B868962961C044B201B8BC276, NULL,
N'--[uspGetDateofDocument] 4,175122    
ALTER proc [dbo].[uspGetDateofDocument]                     
@TranType INT,                        
@TranID INT                        
AS                        
SET NOCOUNT ON;
BEGIN                        
IF(@TranType = 15 or @TranType = 16 or @TranType = 17)    --INVOICE or SALES RETURN
BEGIN                        
select InvDate from tblTranSalesHeader where  ID = @TranID AND DocPrefix =  @TranType                       
END                                           
ELSE IF(@TranType = 1 or @TranType = 12) -- PURCHASE BILL or  PURCHASE RETURN    
BEGIN                    
select Date from tblTransPurchaseHeader where  ID = @TranID and TransID = @TranType                       
END                                                     
ELSE IF(@TranType = 13 or @TranType = 22) -- Inventory Adjustment  or Inventory Conversion                      
BEGIN                    
select InventoryDate from tblInventoryHeader where  InventoryID = @TranID AND TransID =@TranType                       
END                       
END',
N'[export] nocount';
GO
/****** uspGetDatewiseDetail ******/
EXEC #Apply07 N'dbo.uspGetDatewiseDetail', 0x1CEDC0AE2AA5D9F3E7617F344408DD2612C26E9AAFF7EFF9620DA3807F79F5B3, 0xBB136DA60942111C258A6BB7CC1738ABECF4606CFB7E01B820ECEB8570C90B07, NULL, 0x59A8C2B015212B141D2364EA51C2B903CB96ACC091E90E223AF1E7D6558B68EA, 0xA4D3BA162AE4A21308D5455D20BF9BDFC742672B8A207D0AB76FCD6B6B1ED699, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspGetDatewiseDetail]        
@InvDate DATE = ''2025-08-20'',@BranchName NVARCHAR(255) = ''4'',@BeatName NVARCHAR(255) = '''',@SalesmanName NVARCHAR(255) = '''',@CustomerName NVARCHAR(255) = '''',      
@CustomerType NVARCHAR(255) = '''',      
@Ratings NVARCHAR(255) = '''',@FromDate DATE = ''2025-04-01'',@ToDate DATE = ''2025-08-30''        
as      
SET NOCOUNT ON;
begin      
declare @StrQuery nvarchar(max) = ''''        
 set @StrQuery = ''       
SELECT CASE WHEN TransactionType IN (1,4,5,6) THEN ''''Sales'''' WHEN TransactionType=2 THEN ''''Sales Return''''              
WHEN TransactionType=3 THEN ''''Damage Return''''  END as [Type],format(Sh.InvDate,''''dd-MMM-yyyy'''')AS [Invoice Date],              
Sh.DocId AS [Doc ID],CONVERT(NVARCHAR,Sh.InvDate,103) AS [Doc Date],DocRef AS [Ref No],MBO.Name [Branch Name],Beat.Name AS [Beat Name],SM.Name AS [Salesman Name],              
MC.Name as [Customer Name],MCT.Name [Customer Type],RT.RatingName [Ratings],                     
case when DocPrefix=15 then dbo.fnGetRoundedValue(TotalProdDiscAmt) else  dbo.fnGetRoundedValue(-1 * TotalProdDiscAmt)END  AS [Total Product Disc Amt],             
case when DocPrefix=15 then dbo.fnGetRoundedValue(TotalTradeDiscAmt) ELSE dbo.fnGetRoundedValue(-1 * TotalTradeDiscAmt) END AS [Total Trade Disc Amt],             
case when DocPrefix=15 then dbo.fnGetRoundedValue(AdditionalDiscAmt) ELSE dbo.fnGetRoundedValue(-1 * AdditionalDiscAmt)END AS [Total Additional Disc amount],                   
case when DocPrefix=15 then dbo.fnGetRoundedValue(TotalDiscountAmt) ELSE dbo.fnGetRoundedValue(-1 * TotalDiscountAmt)END AS [Total Discount Amt],             
CASE WHEN TransactionType IN (1,4,5,6) THEN  [dbo].[fnGetRoundedValue](ISNULL((Sh.GrossAmt),0))              
WHEN TransactionType=2 THEN [dbo].[fnGetRoundedValue](ISNULL((Sh.GrossAmt),0)*-1)              
WHEN TransactionType=3 THEN [dbo].[fnGetRoundedValue](ISNULL((Sh.GrossAmt),0)*-1)              
END AS [Gross Amount],CASE WHEN TransactionType IN (1,4,5,6) THEN  [dbo].[fnGetRoundedValue](ISNULL((Sh.TotalTaxAmt),0))              
WHEN TransactionType=2 THEN [dbo].[fnGetRoundedValue](ISNULL((Sh.TotalTaxAmt),0)*-1)              
WHEN TransactionType=3 THEN [dbo].[fnGetRoundedValue](ISNULL((Sh.TotalTaxAmt),0)*-1)              
END AS [Tax Amount],dbo.fnGetRoundedValue(Frieght) as [Frieght],        
dbo.fnGetRoundedValue(OtherChargeAmt) as [Other Charge Amount],        
dbo.fnGetRoundedValue(RoundOfAmt) as [Round Of Amount],        
CASE WHEN TransactionType IN (1,4,5,6) THEN  [dbo].[fnGetRoundedValue](ISNULL((Sh.NetAmt),0))              
WHEN TransactionType=2 THEN [dbo].[fnGetRoundedValue](ISNULL((Sh.NetAmt),0)*-1)              
WHEN TransactionType=3 THEN [dbo].[fnGetRoundedValue](ISNULL((Sh.NetAmt),0)*-1)              
END AS [Net Amount]              
FROM tblTranSalesHeader SH              
JOIN tblMasterCustomer MC ON MC.ID= SH.CustID      
LEFT JOIN tblMasterBeat AS Beat ON Beat.ID = SH.BeatID            
LEFT JOIN tblMasterSalesMan AS SM ON SM.ID = SH.SalesManId            
LEFT JOIN tblMasterCustomerType AS MCT ON MCT.ID = MC.CustomerType       
LEFT JOIN tblRatings AS RT ON RT.ID = MC.Rating       
JOIN tblMasterBranchOffice AS MBO ON MBO.ID = SH.BranchID      
WHERE TransactionType in(1,2,3,4,5,6) AND Sh.Status IN (1,3,5,6,7) AND Sh.InvDate =  @InvDate ''      
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BranchName,''0'')=''0'' THEN '''' ELSE '' AND SH.BranchID =  @BranchName '' END)         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND Beat.ID IN ( SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)             
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND SM.ID IN ( SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)                
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND MC.ID IN ( SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND MCT.ID IN ( SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RT.ID IN ( SELECT * from dbo.fnSplitString(  @Ratings ,'''',''''))'' END)       
   SET @StrQuery = @StrQuery + '' order by Sh.DocId asc   ''     EXEC sys.sp_executesql @StrQuery, N''@InvDate DATE, @BranchName NVARCHAR(255), @BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @InvDate, @BranchName, @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @FromDate, @ToDate      
end',
N'[06] nocount';
GO
