/****** uspGetDocIDforPrint ******/
EXEC #Apply07 N'dbo.uspGetDocIDforPrint', 0x18562ED75A81D4ADE7DCCE1706133BA8310030106F4D2274924E658DB60C5E6C, NULL, NULL, 0xD335650B111EF293D4DD6D295FFF158F40013D15143AC1855CF50ADC130B5B93, 0x91A20FA68CD4B865D972106FE536114EC7E82EAB1B8A45ECB4A6744F3466F480, NULL,
N'ALTER PROC [dbo].[uspGetDocIDforPrint]              
@TransID INT,              
@TransTypeID INT              
AS              
SET NOCOUNT ON;
BEGIN    
    
declare @UPIID NVARCHAR(255) = (SELECT ISNULL(AppValue,'''') FROM tblAppConfig WHERE AppId = 15)    
declare @UPIName NVARCHAR(255) = (SELECT ISNULL(AppValue,'''') FROM tblAppConfig WHERE AppId = 16)    
    --SELECT * FROM tblTransName
IF ISNULL(@TransTypeID,0)=1 OR ISNULL(@TransTypeID,0)=12              
BEGIN              
SELECT DocID AS [Document ID],SignedQRCode,AckNo,EWBNo EWBNo,DocId+''/''+CONVERT(nvarchar,Date,104)+''/''+MC.Name UPItn,    
dbo.fnGetRoundedValue(SH.NetAmt) Amt,@UPIID UPIID,@UPIName UPIName FROM tblTransPurchaseHeader SH    
JOIN tblMasterVendor MC ON MC.ID = SH.VendorID WHERE SH.ID=@TransID              
END              
ELSE IF ISNULL(@TransTypeID,0)=4 OR ISNULL(@TransTypeID,0)=5              
BEGIN              
SELECT DocId AS [Document ID],SignedQRCode,AckNo,EWBNo EWBNo,DocId+''/''+CONVERT(nvarchar,InvDate,104)+''/''+MC.Name UPItn,    
dbo.fnGetRoundedValue(SH.NetAmt) Amt,@UPIID UPIID,@UPIName UPIName FROM tblTranSalesHeader SH    
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId WHERE SH.ID=@TransID              
END                          
ELSE IF ISNULL(@TransTypeID,0)=411 OR ISNULL(@TransTypeID,0)=511              
BEGIN              
SELECT DocId AS [Document ID],'''' IRN,'''' AckNo,'''' EWBNo,DocID+''/''+CONVERT(nvarchar,DocDate,104) UPItn,    
dbo.fnGetRoundedValue(NoteValue) Amt,@UPIID UPIID,@UPIName UPIName FROM tblNoteDetails WHERE ID=@TransID              
END              
ELSE IF ISNULL(@TransTypeID,0)=9              
BEGIN              
SELECT DocID AS [Document ID],'''' IRN,'''' AckNo,'''' EWBNo,DocID+''/''+CONVERT(nvarchar,DocDate,104) UPItn,    
dbo.fnGetRoundedValue(sum(Debit)) Amt,@UPIID UPIID,@UPIName UPIName FROM tblFAJournal WHERE NoteID=@TransID         
group by DocID,DocDate    
END              
ELSE IF ISNULL(@TransTypeID,0)=8    
BEGIN              
SELECT DocID AS [Document ID],'''' IRN,'''' AckNo,'''' EWBNo,DocID+''/''+CONVERT(nvarchar,DocDate,104) UPItn,    
dbo.fnGetRoundedValue(Amount) Amt,@UPIID UPIID,@UPIName UPIName FROM tblTranContra WHERE ID=@TransID              
END              
ELSE IF ISNULL(@TransTypeID,0)=611 OR ISNULL(@TransTypeID,0)=711              
BEGIN              
SELECT DocID AS [Document ID],'''' IRN,'''' AckNo,'''' EWBNo,DocID+''/''+CONVERT(nvarchar,DocDate,104) UPItn,    
dbo.fnGetRoundedValue(NetAmount) Amt,@UPIID UPIID,@UPIName UPIName FROM tblTranPRVoucher WHERE ID=@TransID              
END                       
ELSE IF ISNULL(@TransTypeID,0)=19-- OR ISNULL(@TransTypeID,0)=19              
BEGIN              
SELECT DocID AS [Document ID],'''' IRN,'''' AckNo,'''' EWBNo,DocId+''/''+CONVERT(nvarchar,ColDate,104)+''/''+MC.Name UPItn,    
dbo.fnGetRoundedValue(SH.ColAmt) Amt,@UPIID UPIID,@UPIName UPIName  FROM tblTranCollectionHeader SH    
JOIN tblMasterCustomer MC ON MC.FAID = SH.AccID  WHERE ColID=@TransID              
END              
ELSE IF ISNULL(@TransTypeID,0)=18-- OR ISNULL(@TransTypeID,0)=18              
BEGIN              
SELECT DocID AS [Document ID],'''' IRN,'''' AckNo,'''' EWBNo,DocId+''/''+CONVERT(nvarchar,PYDate,104)+''/''+MC.Name UPItn,    
dbo.fnGetRoundedValue(SH.PYAmt) Amt,@UPIID UPIID,@UPIName UPIName  FROM tblTranPaymentHeader SH    
JOIN tblMasterVendor MC ON MC.FAID = SH.AccID  WHERE PYID=@TransID              
END              
ELSE IF ISNULL(@TransTypeID,0)=3              
BEGIN              
SELECT DocID AS [Document ID],'''' IRN,'''' AckNo,'''' EWBNo,DocId+''/''+CONVERT(nvarchar,DocDate,104)+''/''+MC.Name UPItn,    
dbo.fnGetRoundedValue(SH.NetAmt) Amt,@UPIID UPIID,@UPIName UPIName  FROM tblPurchaseOrderHeader SH    
JOIN tblMasterVendor MC ON MC.ID = SH.VendorID  WHERE SH.ID=@TransID              
END              
ELSE IF ISNULL(@TransTypeID,0)=6              
BEGIN              
SELECT DocID AS [Document ID],'''' IRN,'''' AckNo,'''' EWBNo,DocId+''/''+CONVERT(nvarchar,DocDate,104)+''/''+MC.Name UPItn,    
dbo.fnGetRoundedValue(SH.NetAmt) Amt,@UPIID UPIID,@UPIName UPIName FROM tblQuotationHeader SH    
JOIN tblMasterCustomer MC ON MC.ID = SH.CustomerID WHERE SH.ID=@TransID              
END              
           
ELSE IF ISNULL(@TransTypeID,0)=2  
BEGIN              
SELECT DocId AS [Document ID],'''' IRN,'''' AckNo,'''' EWBNo,DocId+''/''+CONVERT(nvarchar,Date,104)+''/''+MC.Name UPItn,    
dbo.fnGetRoundedValue(0) Amt,@UPIID UPIID,@UPIName UPIName  FROM tblTransAutomaticIndentHeader SH    
JOIN tblMasterVendor MC ON MC.ID = SH.VendorID  WHERE SH.ID=@TransID              
END              
END',
N'[export] nocount';
GO
