/****** uspGetFAJBalbyAccID ******/
EXEC #Apply07 N'dbo.uspGetFAJBalbyAccID', 0xC2B345698E9A1C7C8A1FBA897BFECA3EEB1E21348158D43820BAA26438E90145, NULL, NULL, 0x54ED8AFDDE7D82F18A1C545844E9B7CD4894F565C143A6221BA265CF2E8E6261, 0xED39F823758D412C21CBE09DD721BC845B9AE534BEBDE3272F7D462F380EF5B4, NULL,
N'--uspGetFAJBalbyAccID 2947,''2023-04-01'',''2023-06-09''    
ALTER PROC [dbo].[uspGetFAJBalbyAccID]    
@BranchID INT,@AccID INT,@FromDate DATE,@ToDate date    
as    
SET NOCOUNT ON;
BEGIN    
SELECT isnull(SUM(Debit),0) Debit,isnull(SUM(Credit),0) Credit,isnull(SUM(isnull(Debit,0)-isnull(Credit,0)),0) Sumdiff,    
case when SUM(isnull(Debit,0)-isnull(Credit,0)) >= 0 then 1 else 2 END ValueinCRorDR    
FROM tblFAJournal WHERE Status NOT IN (2,4,8) AND AccountID = @AccID AND DocDate BETWEEN @FromDate AND @ToDate    
 AND BranchID = (CASE WHEN @BranchID > 0 THEN @BranchID ELSE BranchID END)
END',
N'[export] nocount';
GO
/****** uspGetFALegderReport ******/
EXEC #Apply07 N'dbo.uspGetFALegderReport', 0xF26CBC481E2E4224ACA8C4599FDFD1E2F3C85E5DBEB50FE09259BE2368997F97, NULL, NULL, 0x7735B8B6EDA1D0E61097C5E8B105EAEEC9C6EC9946B0E553D6153E13968F9BCF, 0x060864162FFE3B227C7E949F3D8CB5EF838105E728BCF3FA87781731A3B09D93, NULL,
N'--[uspGetFALegderReport] 0,''2025-01-01'',''2025-06-30'',157,0,0
ALTER PROC [dbo].[uspGetFALegderReport]
@LevelID INT,
@FromDate DATE,
@ToDate DATE,
@AccID INT,
@ShowDateWise INT,
@ShowGroupBy INT = 0
AS
SET NOCOUNT ON;
BEGIN
--CASH

CREATE TABLE #getOB(ID INT IDENTITY(1,1),OB DECIMAL(25,6),Type varchar(10))
create table #getCB(ID INT IDENTITY(1,1),CB DECIMAL(25,6),Type varchar(10))
--SELECT * FROM tblMastCustomer ORDER BY 1 DESC
declare @StrQuery NVARCHAR(MAX),@TypeID INT

CREATE TABLE #MAINTEMP(ID INT IDENTITY(1,1),DocID NVARCHAR(255),DocDate date, DocRef NVARCHAR(255),UDFDocId NVARCHAR(255),TranName NVARCHAR(255),AccountName NVARCHAR(255),
Credit DECIMAL(25,6),Debit DECIMAL(25,6),Balance NVARCHAR(255),Remarks NVARCHAR(255),Narration NVARCHAR(255), DocPrefix INT,DocValue INT,
NoteID INT,JVID INT,ChequeInfo NVARCHAR(255))
DECLARE @ReturnTable TABLE (ReturnValue DECIMAL (25,6),FaType NVARCHAR(10))
DECLARE @ReturnValue DECIMAL (25,6),@FAType NVARCHAR(10),@TempDate DATE=(SELECT DATEADD(DAY,0, @FromDate))
INSERT INTO @ReturnTable EXEC uspLoadClosingBalance 2,@AccID,@TempDate,NULL,NULL
SELECT @ReturnValue=ReturnValue,@FAType=FaType FROM @ReturnTable

SELECT Distinct DocDate, JVID INTO #TP FROM tblFAJournal WHERE AccountID=@AccID AND Status NOT IN (2,4) AND DocDate BETWEEN @FromDate AND @ToDate --Order BY DocPrefix,DocValue
CREATE TABLE #CopyOfLedger(RowID INT,DocDate DATE,DocID NVARCHAR(255),DocRef NVARCHAR(255),UDFDocId NVARCHAR(255),DocPrefix INT,
AccountID INT,Debit DECIMAL(25,6),Credit DECIMAL(25,6),Remarks NVARCHAR(255),Narration NVARCHAR(255),DocValue INT,
NoteID INT,JVID INT,ChequeInfo NVARCHAR(255))
if(ISNULL(@ShowGroupBy,0) = 0)
BEGIN
INSERT INTO #CopyOfLedger
SELECT ROW_NUMBER()OVER (ORDER BY tblFAJournal.DocDate,tblFAJournal.NoteID) AS RowID,Doc.DocDate,DocID,DocRef,UDFDocId,
tblFAJournal.DocPrefix,AccountID,Debit,Credit,Remarks,Narration,tblFAJournal.DocValue,NoteID,tblFAJournal.JVID,
tblFAJournal.ChequeInfo --INTO #CopyOfLedger
FROM dbo.tblFAJournal
JOIN #TP Doc ON tblFAJournal.JVID=Doc.JVID
WHERE AccountID!=@AccID AND DOC.DocDate BETWEEN @FromDate AND @ToDate AND tblFAJournal.Status NOT IN (2,4,8)
Order BY DocDate,JVID
END
ELSE
BEGIN
INSERT INTO #CopyOfLedger
SELECT ROW_NUMBER() OVER (ORDER BY DocDate,NoteID) AS RowID,DocDate,DocID,DocRef,UDFDocId,DocPrefix,AccountID,
SUM(Debit) Debit,SUM(Credit) Credit,Remarks,Narration,DocValue,NoteID,0 JVID,ChequeInfo FROM (
SELECT Doc.DocDate,DocID,DocRef,UDFDocId,tblFAJournal.DocPrefix,0 AccountID,Debit,Credit,Remarks,Narration,tblFAJournal.DocValue,0 NoteID,0 JVID,
tblFAJournal.ChequeInfo
FROM dbo.tblFAJournal
JOIN #TP Doc ON tblFAJournal.JVID=Doc.JVID
WHERE AccountID!=@AccID AND DOC.DocDate BETWEEN @FromDate AND @ToDate AND tblFAJournal.Status NOT IN (2,4,8)
)AS REC
GROUP BY DocDate,DocID,DocRef,UDFDocId,DocPrefix,AccountID,Remarks,Narration,DocValue,NoteID,ChequeInfo
Order BY DocDate,JVID
END
--SELECT * FROM #CopyOfLedger
IF ISNULL(@FaType,'''')=''Cr''
BEGIN
SET @ReturnValue= -1*ISNULL(@ReturnValue,0)
END
PRINT CONVERT(NVARCHAR,@ReturnValue)+'', FA TYPE - ''+ @FaType
CREATE TABLE #tempData(RowID INT,DocDate DATE,DocID NVARCHAR(255),DocRef NVARCHAR(255),UDFDocId NVARCHAR(255),TranName NVARCHAR(255),AccountName NVARCHAR(255),
Credit DECIMAL(25,6),Debit DECIMAL(25,6),Balance NVARCHAR(255),CCBalance DECIMAL(25,6),Remarks NVARCHAR(255),Narration NVARCHAR(255),DocPrefix INT,DocValue INT,
NoteID INT,JVID INT,ChequeInfo NVARCHAR(255))
if(ISNULL(@ShowGroupBy,0) = 0)
BEGIN
INSERT INTO #tempData
SELECT OriginalTable.RowID,OriginalTable.DocDate DocDate,OriginalTable.DocID DocID,OriginalTable.DocRef DocRef,OriginalTable.UDFDocId UDFDocId,
Doc.TransName,tblFAAccount.AccountName,( OriginalTable.Debit * -1) Credit ,(OriginalTable.Credit) Debit,
CASE WHEN ISNULL(SUM(Temporary.Credit)- SUM(Temporary.Debit)+@ReturnValue,0)<0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ABS(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue))))+'' Cr''
WHEN ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit)+@ReturnValue,0)>=0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue)))+'' Dr''
ELSE '''' END AS Balance,CASE WHEN ISNULL(SUM(Temporary.Credit)- SUM(Temporary.Debit)+@ReturnValue,0)<0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),((ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue))))

WHEN ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit)+@ReturnValue,0)>=0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue)))
ELSE '''' END AS CCBalance,
OriginalTable.Remarks Remarks,OriginalTable.Narration Narration,OriginalTable.DocPrefix DocPrefix,OriginalTable.DocValue DocValue,OriginalTable.NoteID NoteID,OriginalTable.JVID JVID, OriginalTable.ChequeInfo ChequeInfo
--into #tempData
FROM #CopyOfLedger OriginalTable
INNER JOIN #CopyOfLedger Temporary ON OriginalTable.RowID = Temporary.RowID
JOIN tblFAAccount ON tblFAAccount.FAID=OriginalTable.AccountID
JOIN tblDocumentSeries Doc ON Doc.TransID=OriginalTable.DocPrefix
GROUP BY OriginalTable.RowID,OriginalTable.DocDate,OriginalTable.DocPrefix,OriginalTable.DocValue,OriginalTable.DocID,OriginalTable.JVID,OriginalTable.DocRef,OriginalTable.UDFDocId,
Doc.TransName,tblFAAccount.AccountName, OriginalTable.Debit,OriginalTable.Credit,OriginalTable.Remarks,OriginalTable.Narration,OriginalTable.NoteID,OriginalTable.ChequeInfo
,Temporary.RowID
Order BY OriginalTable.RowID
end
ELSE
BEGIN
INSERT INTO #tempData
SELECT OriginalTable.RowID,OriginalTable.DocDate DocDate,OriginalTable.DocID DocID,OriginalTable.DocRef DocRef,OriginalTable.UDFDocId UDFDocId,
Doc.TransName,'''' AccountName,( OriginalTable.Debit * -1) Credit ,(OriginalTable.Credit) Debit,
CASE WHEN ISNULL(SUM(Temporary.Credit)- SUM(Temporary.Debit)+@ReturnValue,0)<0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ABS(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue))))+'' Cr''
WHEN ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit)+@ReturnValue,0)>=0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue)))+'' Dr''
ELSE '''' END AS Balance,CASE WHEN ISNULL(SUM(Temporary.Credit)- SUM(Temporary.Debit)+@ReturnValue,0)<0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),((ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue))))
WHEN ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit)+@ReturnValue,0)>=0.00 THEN dbo.[fnGetRoundedValue](CONVERT(NVARCHAR(50),(ISNULL(SUM(Temporary.Credit)-SUM(Temporary.Debit),0)+@ReturnValue)))
ELSE '''' END AS CCBalance,
OriginalTable.Remarks Remarks,OriginalTable.Narration Narration,OriginalTable.DocPrefix DocPrefix,OriginalTable.DocValue DocValue,OriginalTable.NoteID NoteID,OriginalTable.JVID JVID, OriginalTable.ChequeInfo ChequeInfo
FROM #CopyOfLedger OriginalTable
INNER JOIN #CopyOfLedger Temporary ON OriginalTable.RowID = Temporary.RowID
JOIN tblDocumentSeries Doc ON Doc.TransID=OriginalTable.DocPrefix
GROUP BY OriginalTable.RowID,OriginalTable.DocDate,OriginalTable.DocPrefix,OriginalTable.DocValue,OriginalTable.DocID,OriginalTable.JVID,OriginalTable.DocRef,OriginalTable.UDFDocId,
Doc.TransName, OriginalTable.Debit,OriginalTable.Credit,OriginalTable.Remarks,OriginalTable.Narration,OriginalTable.NoteID,OriginalTable.ChequeInfo
,Temporary.RowID
Order BY OriginalTable.RowID
END
PRINT @ReturnValue
CREATE TABLE #DOCWISE(DInt INT IDENTITY(1,1),Deb DECIMAL(25,6),Cre DECIMAL(25,6),Bals NVARCHAR(50),Df INT,DV INT,NID INT,JID INT)
declare @cpTC int = (select count(distinct RowID) from #tempData),@incr INT = 1,@nCr DECIMAL(25,6),@nDr DECIMAL(25,6),
@InitialDr DECIMAL(25,6) = (SELECT SUM(Credit) FROM #tempData WHERE RowID = 1) + @ReturnValue
DECLARE @DCCount int,@DCincr INT = 1,@DCCr DECIMAL(25,6)
--SELECT * FROM #temp
WHILE(@cpTC >= @incr)
BEGIN
SELECT @nCr = (case when @incr = 1 then Debit else Debit end),@nDr = (case when @incr = 1 then 0 else Credit end) FROM #tempData WHERE RowID = @incr
PRINT ''init: '' +CONVERT(NVARCHAR,@InitialDr)+'' (cr) : ''+CONVERT(NVARCHAR, @nCr)+'' (cr+dr) : ''+CONVERT(NVARCHAR, @nCr + @nDr)+'' allsum : ''+CONVERT(NVARCHAR,@InitialDr+ @nCr + @nDr)
INSERT INTO #DOCWISE
SELECT Debit,Credit, case when ((@InitialDr+ @nCr) + @nDr) >= 0 THEN CONVERT(NVARCHAR(50),dbo.fnGetRoundedValue(ABS(@InitialDr + @nCr + @nDr))) + '' Dr'' ELSE
CONVERT(NVARCHAR(50),dbo.fnGetRoundedValue(ABS(@InitialDr + @nCr + @nDr))) + '' Cr'' END BAL,DocPrefix,DocValue,NoteID,JVID FROM #tempData WHERE RowID = @incr
--PRINT CONVERT(NVARCHAR,@InitialDr)
SET @InitialDr = @InitialDr + @nCr + @nDr

SET @incr = @incr + 1;
END
create table #temp(DocID nvarchar(255),DocDate DATE,DocRef NVARCHAR(255),UDFDocId NVARCHAR(255),TranName NVARCHAR(255),
AccountName NVARCHAR(255),Debit DECIMAL(25,6),Credit DECIMAL(25,6),Balance NVARCHAR(255),Remarks NVARCHAR(255),
Narration NVARCHAR(255),DocPrefix INT,DocValue INT,NoteID INT,JVID INT,ChequeInfo NVARCHAR(255))
if(ISNULL(@ShowGroupBy,0) = 0)
BEGIN
INSERT INTO #temp
SELECT DocID,DocDate,DocRef,UDFDocId,TranName,AccountName,Debit,ABS(Credit) Credit,DW.Bals Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,JVID,ChequeInfo
--into #temp
FROM #DOCWISE DW
JOIN #tempData COL ON COL.NoteID = DW.NID
ORDER BY DocDate
END
ELSE
BEGIN
INSERT INTO #temp
SELECT DocID,DocDate,DocRef,UDFDocId,TranName,AccountName,Debit,ABS(Credit) Credit,DW.Bals Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,
JVID,ChequeInfo FROM #DOCWISE DW
JOIN #tempData COL ON COL.RowID = DW.DInt
ORDER BY DocDate
END

IF(@ShowDateWise = 1)
BEGIN
DECLARE @FDATE DATE = @FromDate,@TDATE DATE = @ToDate
WHILE @FDATE <= @TDATE
BEGIN
INSERT INTO #getOB EXEC uspLoadClosingBalance 2,@AccID,@FDATE,NULL,NULL
DECLARE @OBVALUE DECIMAL(25,6) = (SELECT TOP 1 OB FROM #getOB ORDER BY ID DESC)
DECLARE @Type varchar(10) = (SELECT TOP 1 Type FROM #getOB ORDER BY ID DESC)
--GET CLOSING BAL FOR EVERY DAY
INSERT INTO #getCB EXEC uspLoadClosingBalance 1,@AccID,@FDATE,NULL,NULL
DECLARE @CBVALUE DECIMAL(25,6) = (SELECT TOP 1 CB FROM #getCB ORDER BY ID DESC)
DECLARE @CBType NVARCHAR(20) = (SELECT TOP 1 Type FROM #getCB ORDER BY ID DESC)
IF ISNULL(@Type,'''')=''Cr''
BEGIN
SET @OBVALUE= -1*ISNULL(@OBVALUE,0)
END
PRINT CONVERT(NVARCHAR,@OBVALUE)+'', FA TYPE - ''+ @Type

INSERT INTO #MAINTEMP
SELECT '''' AS DocID,@FDATE DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Opening Balance'' AccountName,
(CASE WHEN @Type = ''Cr'' THEN ABS(@OBVALUE) ELSE 0 END) AS Credit,
(CASE WHEN @Type = ''Dr'' THEN ABS(@OBVALUE) ELSE 0 END) AS Debit,
'''' Balance,
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo
UNION ALL
select DocID,DocDate,DocRef,UDFDocId,TranName,AccountName,Credit,Debit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,
JVID,ChequeInfo from #temp WHERE DocDate = @FDATE 
UNION ALL
SELECT '''' AS DocID,DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Total'' AccountName,
(CASE WHEN @Type = ''Cr'' THEN ABS(@OBVALUE) + SUM(Credit) ELSE SUM(Credit) END) AS Credit,
(CASE WHEN @Type = ''Dr'' THEN ABS(@OBVALUE) + SUM(Debit) ELSE SUM(Debit) END) AS Debit,
'''' Balance,
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo
FROM #temp WHERE DocDate = @FDATE
GROUP BY DocDate
UNION ALL
SELECT '''' AS DocID,@FDATE DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Closing Balance'' AccountName,
(CASE WHEN @CBType = ''Cr'' THEN ABS(@CBVALUE) ELSE 0 END) AS Credit,
(CASE WHEN @CBType = ''Dr'' THEN ABS(@CBVALUE) ELSE 0 END) AS Debit,
'''' Balance,
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo --FROM #temp WHERE DocDate = @FDATE
SET @FDATE = DATEADD(DD,1,@FDATE)
END
END
ELSE
BEGIN
INSERT INTO #MAINTEMP
SELECT '''' AS DocID,@FromDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Opening Balance'' AccountName,(CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) ELSE 0 END) AS Credit,
(CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) ELSE 0 END) AS Debit,'''' Balance,
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo
UNION ALL
select DocID,DocDate,DocRef,UDFDocId,TranName,AccountName,Credit,Debit,Balance,Remarks,Narration,DocPrefix,DocValue,NoteID,
JVID,ChequeInfo from #temp
UNION ALL
SELECT '''' AS DocID,@ToDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Total'' AccountName,(CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0) END) AS Credit,
(CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0) END) AS Debit,'''' Balance,
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo
FROM #temp
UNION ALL
SELECT '''' AS DocID,@ToDate DocDate,'''' DocRef ,'''' UDFDocId,'''' TranName, ''Closing Balance'' AccountName,
ISNULL((CASE WHEN (CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0) END) < (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0) END)
THEN (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0) END) -
(CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0) END) ELSE 0 END),ABS(@ReturnValue)) AS Credit,
ISNULL((CASE WHEN (CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0) END) >= (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0) END)
THEN (CASE WHEN @ReturnValue < 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Credit),0) ELSE ISNULL(SUM(Credit),0) END) -
(CASE WHEN @ReturnValue >= 0 THEN ABS(@ReturnValue) + ISNULL(SUM(Debit),0) ELSE ISNULL(SUM(Debit),0) END) ELSE 0 END),ABS(@ReturnValue)) AS Debit,'''' Balance,
'''' Remarks,'''' Narration,'''' DocPrefix,'''' DocValue,'''' NoteID,'''' JVID,'''' ChequeInfo
FROM #temp
END

select DocID [Doc ID],CONVERT(NVARCHAR,DocDate,103) [Document Date],DocRef [Ref No],UDFDocId [UDN],TranName [Transaction Name],
AccountName [Account Name],dbo.fnGetRoundedValue(ABS(Debit)) Debit,dbo.fnGetRoundedValue(ABS(Credit)) Credit,Balance
,Remarks,Narration,ISNULL(DocPrefix,0) DocPrefix,ISNULL(DocValue,0) DocValue,NoteID,JVID,ChequeInfo from #MAINTEMP
ORDER BY DocDate ASC

--DROP TABLE #CopyOfLedger,#TP,#temp,#MAINTEMP,#TVP,#getOB,#JVTEMP--,#OB
drop table #TP,#CopyOfLedger,#tempData,#temp,#DOCWISE,#getCB
END',
N'[export] nocount';
GO
/****** uspGetFilterDates ******/
EXEC #Apply07 N'dbo.uspGetFilterDates', 0xE341A93C5662DF6A49EC4BB790FACE99499EF855F1AEFA849E9B914A7CBBE02F, NULL, NULL, 0x6BC6DAE3202B77885C2128F888647B38AE4F06949334262EB0F1008E88657D48, 0xBD99629BA45F789100BCE9360A54359098DFE1E65D765CCB2027D260A8008A4E, NULL,
N'ALTER PROc [dbo].[uspGetFilterDates]  
as  
SET NOCOUNT ON;
begin  
DECLARE @FSD DATE = ''2025-04-01''   -- Financial Start Date  
DECLARE @FED DATE = ''2027-03-31''   -- Financial End Date  
SELECT @FSD = F_SD,@FED = F_ED FROM TBLCOMPANYREGISTRATION  
DECLARE @Today DATE =  GETDATE()  

-- Raw From/To per period  
DECLARE @Results TABLE (ID INT, Code VARCHAR(10), Name VARCHAR(50), RawFrom DATE, RawTo DATE)  
  
-- 1. CD - Current Date  
INSERT INTO @Results  
SELECT 1, ''CD'', ''Current Date'', @Today, @Today  
  
-- 2. TM - This Month  
INSERT INTO @Results  
SELECT 2, ''TM'', ''This Month'',  
    DATEFROMPARTS(YEAR(@Today), MONTH(@Today), 1),  
    EOMONTH(@Today)  
  
-- 3. PM - Previous Month  
INSERT INTO @Results  
SELECT 3, ''PM'', ''Previous Month'',  
    DATEFROMPARTS(YEAR(DATEADD(MONTH,-1,@Today)), MONTH(DATEADD(MONTH,-1,@Today)), 1),  
    EOMONTH(DATEADD(MONTH, -1, @Today))  
  
-- 4. All - Financial Date  
INSERT INTO @Results  
SELECT 4, ''All'', ''Financial Date'', @FSD, @FED  
  
-- 5. TQ - This Quarter  
DECLARE @TQNum INT = DATEPART(QUARTER, @Today)  
INSERT INTO @Results  
SELECT 5, ''TQ'', ''This Quarter'',  
    DATEFROMPARTS(YEAR(@Today), (@TQNum - 1) * 3 + 1, 1),  
    EOMONTH(DATEFROMPARTS(YEAR(@Today), @TQNum * 3, 1))  
  
-- 6. PQ - Previous Quarter  
DECLARE @PQRef DATE = DATEADD(MONTH, -3, @Today)  
DECLARE @PQNum INT  = DATEPART(QUARTER, @PQRef)  
INSERT INTO @Results  
SELECT 6, ''PQ'', ''Previous Quarter'',  
    DATEFROMPARTS(YEAR(@PQRef), (@PQNum - 1) * 3 + 1, 1),  
    EOMONTH(DATEFROMPARTS(YEAR(@PQRef), @PQNum * 3, 1))  

INSERT INTO @Results  
SELECT 7, ''FY'', ''Financial Year'',  
    DATEFROMPARTS(YEAR(@Today),4, 1),
    DATEFROMPARTS(YEAR(@Today)+1,3,31)
  
-- Final SELECT with new Min/Max/From/To logic  
SELECT  
    r.ID,  
    r.Code,  
    r.Name,  
  
    -- MinDate: MIN(RawFrom, FSD) → lower of the two  
    CASE WHEN r.RawFrom < @FSD THEN r.RawFrom ELSE @FSD END AS MinDate,  
  
    -- MaxDate: Step 1 → MIN(RawTo, FED), Step 2 → MIN(result, Today)  
 case when @FED < @Today then @FED ELSE  @Today END  
     AS MaxDate,  
  
    -- FromDate: same as MinDate  
     CASE   
        WHEN CASE WHEN r.RawFrom >=  @FSD THEN r.RawFrom ELSE @FSD END  < @FED   
  THEN CASE WHEN r.RawFrom >=  @FSD THEN r.RawFrom ELSE @FSD END ELSE @FED END  AS FromDate,  
  
    -- ToDate: same as MaxDate  
    CASE   
        WHEN CASE WHEN r.RawTo < @FED THEN r.RawTo ELSE @FED END < @Today  
        THEN CASE WHEN r.RawTo < @FED THEN r.RawTo ELSE @FED END  
        ELSE @Today  
    END AS ToDate  
  
FROM @Results r  
JOIN tblFilterDates FD ON FD.ID = R.ID  
WHERE FD.Active = 1   
ORDER BY FD.DisplayIndex,r.ID  
end',
N'[export] nocount';
GO
/****** uspGetFullGSTInfoReport ******/
EXEC #Apply07 N'dbo.uspGetFullGSTInfoReport', 0x50FF7220BF4E3728A3326321F83DDA71BAF245D90010E2473214CCF2721C16CB, 0x78BAE3ECBA191432D6A519ED1AE482B8AE1A6F11C3FEA400449D7E5F81101926, NULL, 0x499FB5BA97F7AEBE27E8B234179F65005DACB3CB54AE97D6A7F55B3BE7E75D29, 0xF93B02B2107667E14A0A95ACBC44F414590678E085B99EFA1AED372A334F618A, NULL,
N'--uspGetFullGSTInfoReport ''S'',''2026-09-01'',''2026-09-30'',0,''1''   
--uspGetFullGSTInfoReport ''SR'',''2026-09-01'',''2026-09-30'',0,''1''     
--uspGetFullGSTInfoReport ''P'',''2026-09-01'',''2026-09-30'',0,''1''       
--uspGetFullGSTInfoReport ''PR'',''2026-09-01'',''2026-09-30'',0,''1''    
--uspGetFullGSTInfoReport ''PV'',''2026-09-01'',''2026-09-30'',0,''1''   
--uspGetFullGSTInfoReport ''RV'',''2026-09-01'',''2026-09-30'',0,''1''      
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspGetFullGSTInfoReport]      
@TransName NVARCHAR(255),@FromDate DATE,@ToDate DATE,@WOEinv int = 0,@BranchIDs NVARCHAR(255) = null  
AS      
SET NOCOUNT ON;
BEGIN      
--REPLACE(CONVERT(NVARCHAR,SH.InvDate,106), '' '', ''-'')      
SET DATEFORMAT dmy;      
DECLARE @Query NVARCHAR(MAX),@DocPrefix NVARCHAR(20)      
IF ISNULL(@TransName,'''')=''S'' OR ISNULL(@TransName,'''')=''SR''      
BEGIN      
SET @DocPrefix = (CASE WHEN @TransName=''S'' THEN 15 ELSE 16 END)      
SET @Query = ''SELECT SH.DocId AS [Inv ID],REPLACE(CONVERT(NVARCHAR,SH.InvDate,106), '''' '''', ''''-'''') AS [Inv Date],    
MBO.Name AS [Branch Name],SH.DocRef AS [Doc Ref],      
Cust.Name AS [Party Name],TT.TaxTypeName AS [Tax Type],Cust.GSTIN AS [GSTIN],Prod.Code AS [Product Code],Prod.Name AS [Product Name],      
Prod.EAN,Prod.HSNCode AS [HSN Code],UOM.Name AS [Base UOM],      
CONVERT(DECIMAL(15,2),SD.UomQty) AS [Base UOM Qty],      
CONVERT(DECIMAL(15,2),SD.GrossAmt) AS [Gross Amount],''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 1),0)) AS [CGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 1),0)) AS [CGST Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 2),0)) AS [SGST %],''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 2),0)) AS [SGST Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 3),0)) AS [UTGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 3),0)) AS [UTGST Amount],''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 4),0)) AS [GCESS %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID IN (4,5)),0)) AS [GCESS Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID = 1),0)) AS [IGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID = 1),0)) AS [IGST Amount],''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID = 2),0)) AS [ICESS %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = SD.InvId AND ProdID = SD.ProdId AND Serial = SD.Serial AND TaxID = SD.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID IN (2,3)),0)) AS [ICESS Amount],      
CONVERT(DECIMAL(15,2),SD.NetAmt) AS [Net Amount]''      
SET @Query = @Query + '' FROM tblTranSalesHeader AS SH      
JOIN tblTranSalesDetail AS SD ON SH.ID = SD.InvId      
JOIN tblMasterCustomer AS Cust ON Cust.ID = SH.CustId      
JOIN tblMasterTaxType AS TT ON TT.TaxTypeID = SH.TaxTypeId      
JOIN tblMasterProduct AS Prod ON Prod.ID = SD.ProdId      
JOIN tblMasterUom AS UOM ON Prod.BaseUomID=UOM.ID      
JOIN TblMasterBranchoffice MBO ON MBO.ID = SH.BranchID  
WHERE SH.DocPrefix= @DocPrefix  AND SH.Status IN (1,3,5,6,7) AND ISNULL(SD.TaxId,0)>0      
AND ISNULL(SH.IRN,'''''''') = (CASE WHEN  @WOEinv  = 0 THEN ISNULL(SH.IRN,'''''''') ELSE '''''''' END) ''  
SET @Query += case when isnull(@BranchIDs,'''') = '''' then '''' else '' AND SH.BranchID IN (SELECT value FROM STRING_SPLIT( @BranchIDs , '''',''''))'' END  
SET @Query += '' AND (SH.InvDate BETWEEN  @FromDate  AND  @ToDate )      
ORDER BY SH.InvDate,CASE WHEN SH.UDFId > 0 THEN SH.UDFDocId ELSE SH.DocId END ''      
PRINT @Query
EXEC sys.sp_executesql @Query, N''@TransName NVARCHAR(255), @FromDate DATE, @ToDate DATE, @WOEinv int, @BranchIDs NVARCHAR(255), @DocPrefix NVARCHAR(20)'', @TransName, @FromDate, @ToDate, @WOEinv, @BranchIDs, @DocPrefix      
END    
ELSE IF ISNULL(@TransName,'''')=''P'' OR ISNULL(@TransName,'''')=''PR''      
BEGIN      
SET @DocPrefix = (CASE WHEN @TransName=''P'' THEN 1 ELSE 12 END)      
    
SET @Query = ''SELECT BH.DocId AS [Inv ID],REPLACE(CONVERT(NVARCHAR,BH.Date,106), '''' '''', ''''-'''') AS [Inv Date],  
MBO.Name AS [Branch Name],BH.RefNo AS [Doc Ref],      
Ven.name AS [Party Name],TT.TaxTypeName AS [Tax Type],Ven.GSTIN AS [GSTIN],Prod.Code AS [Product Code],Prod.Name AS [Product Name],Prod.EAN     
,Prod.HSNCode AS [HSN Code],UOM.Name AS [Base UOM],CONVERT(DECIMAL(15,2),BD.UomQty) AS [Base UOM Qty],      
CONVERT(DECIMAL(15,2),BD.GrossAmt) AS [Gross Amount],''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 1),0)) AS [CGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 1),0)) AS [CGST Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 2),0)) AS [SGST %], ''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 2),0)) AS [SGST Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 3),0)) AS [UTGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 3),0)) AS [UTGST Amount],''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 4),0)) AS [GCESS %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID IN (4,5)),0)) AS [GCESS Amount],''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID = 1),0)) AS [IGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID = 1),0)) AS [IGST Amount],''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID = 2),0)) AS [ICESS %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID =  @DocPrefix  AND TransIdentID = BD.HID AND ProdID = BD.ProdId AND Serial = BD.Serial AND TaxID = BD.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID IN (2,3)),0)) AS [ICESS Amount],''      
SET @Query = @Query + ''CONVERT(DECIMAL(15,2),BD.NetAmt) AS [Net Amount]      
FROM tbltranspurchaseheader AS BH      
JOIN tbltranspurchasedetail AS BD ON BH.ID = BD.HID      
LEFT JOIN tblMasterProduct AS Prod ON Prod.ID = BD.ProdId      
LEFT JOIN tblMasterUom AS UOM ON Prod.BaseUomID=UOM.ID      
LEFT JOIN tblMasterVendor AS Ven ON Ven.id = BH.VendorID      
JOIN tblMasterTaxType AS TT ON TT.TaxTypeID = BH.TaxTypeId      
JOIN TblMasterBranchoffice MBO ON MBO.ID = BH.BranchID  
WHERE BH.TransID =  @DocPrefix  AND BH.Status IN (1,3,6,5) AND ISNULL(BD.UomID,0)>0      
AND ISNULL(BH.IRN,'''''''') = (CASE WHEN  @WOEinv  = 0 THEN ISNULL(BH.IRN,'''''''') ELSE '''''''' END)  ''  
SET @Query += case when isnull(@BranchIDs,'''') = '''' then '''' else '' AND BH.BranchID IN (SELECT value FROM STRING_SPLIT( @BranchIDs , '''',''''))'' END  
SET @Query += ''  AND (BH.Date BETWEEN  @FromDate  AND  @ToDate )      
ORDER BY BH.Date,CASE WHEN BH.UDFId > 0 THEN BH.UDFDocId ELSE BH.DocId END''      
EXEC sys.sp_executesql @Query, N''@TransName NVARCHAR(255), @FromDate DATE, @ToDate DATE, @WOEinv int, @BranchIDs NVARCHAR(255), @DocPrefix NVARCHAR(20)'', @TransName, @FromDate, @ToDate, @WOEinv, @BranchIDs, @DocPrefix      
END      
ELSE IF ISNULL(@TransName,'''')=''RV'' OR ISNULL(@TransName,'''')=''PV''     
BEGIN      
SET @DocPrefix = CASE WHEN ISNULL(@TransName,'''')=''PV'' THEN 6 ELSE 7 END      
SELECT BH.DocId AS [Doc ID],REPLACE(CONVERT(NVARCHAR,BH.DocDate,106), '' '', ''-'') AS [Doc Date],  
MBO.Name AS [Branch Name],RefNo AS [Doc Ref],      
Prod.AccountName AS [Party Name],''GST'' AS [Tax Type],'''' AS [GSTIN],      
Prod1.AccountName AS [Account Name],BH.SACorHSNCode AS [HSN Code],      
CONVERT(DECIMAL(15,2),BH.Amount) AS [Goods Amount],CONVERT(DECIMAL(15,2),BH.DiscPern) AS [Discount %],      
CONVERT(DECIMAL(15,2),BH.DiscAmt) AS [Discount Amount],CONVERT(DECIMAL(15,2),BH.TDSAmount) AS [TDS Amount],      
CONVERT(NVARCHAR,BH.TDSDate,103) AS [TDS Date],      
CONVERT(DECIMAL(15,2),BH.GrossAmount) AS [Gross Amount],      
--tblTranPRVoucher order by 1 desc      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 1),0)) AS [CGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 1),0)) AS [CGST Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 2),0)) AS [SGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 2),0)) AS [SGST Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 3),0)) AS [UTGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 3),0)) AS [UTGST Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID = 4),0)) AS [GCESS %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 1 AND GSTTaxTypeID IN (4,5)),0)) AS [GCESS Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID = 1),0)) AS [IGST %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID = 1),0)) AS [IGST Amount],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT DISTINCT TaxCompPern      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID = 2),0)) AS [ICESS %],      
CONVERT(DECIMAL(15,2),ISNULL((SELECT SUM(TaxValue)      
FROM tblTransGSTInfo      
WHERE TransID = @DocPrefix AND TransIdentID = BH.ID AND TaxID = BH.TaxId      
AND TaxTypeID = 2 AND GSTTaxTypeID IN (2,3)),0)) AS [ICESS Amount],      
CONVERT(DECIMAL(15,2),BH.NetAmount) AS [Net Amount]      
FROM tblTranPRVoucher AS BH      
LEFT JOIN tblFAAccount AS Prod ON Prod.FAID = BH.PartyID      
left JOIN tblFAAccount AS Prod1 ON Prod1.FAID = BH.FAID      
JOIN TblMasterBranchoffice MBO ON MBO.ID = BH.BranchID  
WHERE BH.TransID = @DocPrefix AND BH.Status IN (1,3,5)      
AND (BH.DocDate BETWEEN @FromDate AND @ToDate)      
AND (isnull(@BranchIDs,'''') = '''' OR BH.BranchID in (SELECT value FROM STRING_SPLIT(@BranchIDs, '','')))  
ORDER BY BH.DocDate,CASE WHEN BH.UDFId > 0 THEN BH.UDFDocId ELSE BH.DocId END      
END      
END',
N'[06] nocount';
GO
/****** uspGetGendralColumnSettings ******/
EXEC #Apply07 N'dbo.uspGetGendralColumnSettings', 0x42047BA327AD247C305181B92B221C49B715E6509F866706FC5B28F076B15D1E, NULL, NULL, 0xBF95F35B9992D0CEC74189B03082CB717FB21C67E1D05936824A3DAD804F8A9A, 0x589501D7AD3788C77692847C8B9487018C9494B7387532DCD71F7C98F21502F1, NULL,
N'--[uspGetGendralColumnSettings] 1,33,1,0
ALTER PROC [dbo].[uspGetGendralColumnSettings]        
@Mode INT,@FormID INT = 0,@TableID INT = 1,@FormorReport int = 0      
AS        
SET NOCOUNT ON;
BEGIN        
declare @DecimalValues int      
select @DecimalValues = AppValue from tblAppConfig where AppId = 8      
IF(@Mode = 1)        
begin        
select *,@DecimalValues precision from tblColumnSettings where Permission = 1 and IsHiddenColumn = 0 AND FormID = @FormID     
and TableID = @TableID and FormorReport = @FormorReport  order by DisplayIndex    
end        
IF(@Mode = 2)        
begin        
select *,@DecimalValues precision from tblColumnSettings where Permission = 1 and FormID = @FormID and TableID = @TableID     
and FormorReport = @FormorReport order by DisplayIndex        
end    
IF(@Mode = 3)        
begin        
select *,@DecimalValues precision from tblColumnSettings where FormID = @FormID     
and TableID = @TableID and FormorReport = @FormorReport  order by DisplayIndex    
end  
end',
N'[export] nocount';
GO
/****** uspGetGSTforPrinting ******/
EXEC #Apply07 N'dbo.uspGetGSTforPrinting', 0xA65B4D6F6C44ADEC458F28322C4F3EDE6E6F360A386760C33A87A87F2D7D85C6, NULL, NULL, 0xF2023D6A7A59BD403D5C4C5DAF44D257F417C12FD8B79CD9E3DDC64326DE926C, 0x8653E040D208173FD44157A21B7B024BBB96D5DBD1BBDD9E119F09D23D0547EA, NULL,
N'--uspGetGSTforPrinting 4,8705                
ALTER PROC [dbo].[uspGetGSTforPrinting]                          
@TransID INT,                          
@TransIdentID INT                          
AS                          
SET NOCOUNT ON;
BEGIN                          
--SET @TransID = (                          
--SELECT DocID FROM tblMastDocSeries                           
--WHERE TranName = (SELECT TransName FROM tblTransName WHERE Id = @TransID)                          
--)                          
                  
SELECT HSNCode,      
dbo.fnGetRoundedValue(RAM.[Gross Amount]) AS [GST Tax Amount],                          
dbo.fnGetRoundedValue(RAM.[CGST %]) AS [CGST %],                          
dbo.fnGetRoundedValue(RAM.[CGST Amount]) AS [CGST Amount],                          
dbo.fnGetRoundedValue(RAM.[SGST %]) AS [SGST %],                          
dbo.fnGetRoundedValue(RAM.[SGST Amount]) AS [SGST Amount],                          
dbo.fnGetRoundedValue(RAM.[UTGST %]) AS [UTGST %],                          
dbo.fnGetRoundedValue(RAM.[UTGST Amount]) AS [UTGST Amount],                          
dbo.fnGetRoundedValue(RAM.[GCESS %]) AS [GCESS %],                          
dbo.fnGetRoundedValue(RAM.[GCESS Amount] + RAM.[GUOM Amount] ) AS [Cumulative GCESS Amount],       
dbo.fnGetRoundedValue(RAM.[GCESS Amount]) AS [GCESS Amount],                   
dbo.fnGetRoundedValue(RAM.[IGST %]) AS [IGST %],                          
dbo.fnGetRoundedValue(RAM.[IGST Amount]) AS [IGST Amount],                  
dbo.fnGetRoundedValue(RAM.[ICESS %]) AS [ICESS %],                          
dbo.fnGetRoundedValue(RAM.[ICESS Amount] + RAM.[IUOM Amount]) AS [Cumulative ICESS Amount],    
dbo.fnGetRoundedValue(RAM.[ICESS Amount]) AS [ICESS Amount],    
dbo.fnGetRoundedValue(RAM.[GUOM Amount] ) AS [GUOM Amount],           
dbo.fnGetRoundedValue(RAM.[IUOM Amount]) AS [IUOM Amount]              
FROM                          
(                          
SELECT HSNCode,SRI.[Gross Amount],                      
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 1),0)) AS [CGST %],                          
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],                          
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 2),0)) AS [SGST %],                          
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],                          
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 3),0)) AS [UTGST %],                          
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],                   
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 4),0)) AS [GCESS %],                          
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],        
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 3 AND GSTTaxType = 5),0)) AS [GUOM],                          
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],                  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 1),0)) AS [IGST %],                          
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],                  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 2),0)) AS [ICESS %],                          
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],        
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 5 AND GSTTaxType = 3),0)) AS [IUOM],                          
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]         
FROM                          
(                          
SELECT * FROM                           
(                          
SELECT HSNCode,TaxTypeID,Temp.TaxID,Temp.[GST Comp],                          
Temp.TaxName AS TaxName,                          
SUM(Temp.TaxValue) AS [TaxValue], SUM(Temp.[Gross Amount]) AS [Gross Amount]                     
FROM                          
(                          
SELECT MP.HSNCode HSNCode, MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,                
CASE                  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 3 THEN ''CGST Amount''                   
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 3 THEN ''SGST Amount''                          
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 3 THEN ''UTGST Amount''                          
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 3 THEN ''GCESS Amount''           
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 3 THEN ''GUOM Amount''               
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 5 THEN ''IGST Amount''                  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 5 THEN ''ICESS Amount''           
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 5 THEN ''IUOM Amount''                  
               
END AS [GST Comp], GSTInfo.GrossAmt AS [Gross Amount]                      
FROM tblTransGSTInfo AS GSTInfo      
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID               
JOIN tblMasterProduct MP ON MP.ID = GSTInfo.ProdID      
WHERE TransIdentID=@TransIdentID AND TransID= (SELECT TransID FROM tblDocumentSeries                         
WHERE TransName = (SELECT TransName FROM tblTransName WHERE Id = @TransID)                          
)                          
--@TransID                  
) Temp                          
GROUP BY HSNCode,Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID                      
) src                          
PIVOT                          
(                          
SUM([TaxValue])                          
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])        
) piv                          
) AS SRI                          
) AS RAM                      
ORDER BY RAM.[CGST %] ASC                      
END',
N'[export] nocount';
GO
/****** uspGetGSTforPrintingWOHSN ******/
EXEC #Apply07 N'dbo.uspGetGSTforPrintingWOHSN', 0x71EF2C6B8A2A608A853297465F457303D3DF616ABDE8ADB3471444A320500FE7, NULL, NULL, 0x12B2CC2E8CA80D9258A9E166BE7F3E5C3C70AC2CA460C4D2CD097D3C6DACB066, 0x727A29DC4D0359FA58A4A767A45410121B67A045D4C470B58887F974C42BB1A2, NULL,
N'--[uspGetGSTforPrintingWOHSN] 1,143                    
ALTER PROC [dbo].[uspGetGSTforPrintingWOHSN]                              
@TransID INT,                              
@TransIdentID INT                              
AS                              
SET NOCOUNT ON;
BEGIN                                            
SELECT                          
dbo.fnGetRoundedValue(RAM.[Gross Amount]) AS [GST Tax Amount],dbo.fnGetRoundedValue(RAM.[CGST %]) AS [CGST %],      
dbo.fnGetRoundedValue(RAM.[CGST Amount]) AS [CGST Amount],dbo.fnGetRoundedValue(RAM.[SGST %]) AS [SGST %],      
dbo.fnGetRoundedValue(RAM.[SGST Amount]) AS [SGST Amount],dbo.fnGetRoundedValue(RAM.[UTGST %]) AS [UTGST %],      
dbo.fnGetRoundedValue(RAM.[UTGST Amount]) AS [UTGST Amount],dbo.fnGetRoundedValue(RAM.[GCESS %]) AS [GCESS %],      
dbo.fnGetRoundedValue(RAM.[GCESS Amount] + RAM.[GUOM Amount] ) AS [Cumulative GCESS Amount],dbo.fnGetRoundedValue(RAM.[GCESS Amount]) AS [GCESS Amount],      
dbo.fnGetRoundedValue(RAM.[IGST %]) AS [IGST %],dbo.fnGetRoundedValue(RAM.[IGST Amount]) AS [IGST Amount],      
dbo.fnGetRoundedValue(RAM.[ICESS %]) AS [ICESS %],dbo.fnGetRoundedValue(RAM.[ICESS Amount] + RAM.[IUOM Amount]) AS [Cumulative ICESS Amount],      
dbo.fnGetRoundedValue(RAM.[ICESS Amount]) AS [ICESS Amount],dbo.fnGetRoundedValue(RAM.[GUOM Amount] ) AS [GUOM Amount],      
dbo.fnGetRoundedValue(RAM.[IUOM Amount]) AS [IUOM Amount]      
FROM                              
(                              
SELECT SRI.[Gross Amount],                          
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],                              
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],                              
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],                              
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],                              
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],                              
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],                       
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],                              
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM],                              
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],                      
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],                              
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],                      
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],                              
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM],                              
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]             
FROM                              
(                              
SELECT * FROM                               
(                              
SELECT Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],Temp.TaxName AS TaxName,SUM(Temp.TaxValue) AS [TaxValue],SUM(Temp.[Gross Amount]) AS [Gross Amount]      
FROM              
(                              
SELECT MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,                    
CASE                      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''      
END AS [GST Comp], GSTInfo.GrossAmt AS [Gross Amount]      
FROM tblTransGSTInfo AS GSTInfo      
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID      
WHERE TransIdentID=@TransIdentID AND TransID = (SELECT DocID FROM tblTransName WHERE Id = @TransID)      
) Temp GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID      
) src PIVOT (SUM([TaxValue]) FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],      
[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])) piv) AS SRI) AS RAM ORDER BY RAM.[CGST %] ASC      
END',
N'[export] nocount';
GO
/****** uspGetIDfromDocIDforQuickAccess ******/
EXEC #Apply07 N'dbo.uspGetIDfromDocIDforQuickAccess', 0xD70CCC133C43285E3AB680BC58A17DC7828C4BD6F38DC8B5907C8179CF3E5F92, NULL, NULL, 0x37AAD3D1A8C1E91CBE39F72162414D1B31EA150E2FCE58FDAD130322CA4E5422, 0xA08B1B932CBA2DE3C7EACD39683084924854A263CF392101FF78B812C8F4F999, NULL,
N'ALTER proc [dbo].[uspGetIDfromDocIDforQuickAccess]      
@TransID INT,@DocID NVARCHAR(255)      
AS      
SET NOCOUNT ON;
BEGIN      
IF(@TransID = 1)      
BEGIN      
select TOP 1 ID from tblTransPurchaseHeader where TransID = 1 AND DocID = @DocID order by ID DESC      
END      
IF(@TransID = 12)      
BEGIN      
select TOP 1 ID from tblTransPurchaseHeader where TransID = 12 AND DocID = @DocID order by ID DESC      
END      
IF(@TransID = 2)      
BEGIN      
select TOP 1 ID from tblTransAutomaticIndentHeader where DocID = @DocID order by ID DESC      
END      
IF(@TransID = 15 or @TransID = 16)      
BEGIN      
select TOP 1 ID from tblTranSalesHeader where DocID = @DocID order by ID DESC      
END      
IF(@TransID = 19 or @TransID = 10)      
BEGIN      
select TOP 1 ColID ID from tblTranCollectionHeader where DocID = @DocID order by ID DESC      
END      
IF(@TransID = 18 or @TransID = 11)      
BEGIN      
select TOP 1 PYID ID from tblTranPaymentHeader where DocID = @DocID order by ID DESC      
END      
IF(@TransID = 3)      
BEGIN      
select TOP 1 ID from tblPurchaseOrderHeader where DocID = @DocID order by ID DESC      
END      
IF(@TransID = 14)      
BEGIN      
select TOP 1 ID from tblQuotationHeader where DocID = @DocID order by ID DESC      
END      
IF(@TransID = 13 or @TransID = 22)      
BEGIN      
select TOP 1 InventoryID ID from tblInventoryHeader where DocID = @DocID order by ID DESC      
END     
IF(@TransID = 4 or @TransID = 5)  
BEGIN      
select TOP 1 ID ID from tblNoteDetails where DocID = @DocID order by ID DESC      
END    
IF(@TransID = 6 or @TransID = 7)  
BEGIN      
select TOP 1 ID ID from tblTranPRVoucher where DocID = @DocID order by ID DESC      
END  
IF(@TransID = 8)  
BEGIN      
select TOP 1 ID ID from tblTranContra where DocID = @DocID order by ID DESC      
END  
IF(@TransID = 9)  
BEGIN      
select TOP 1 JVID ID from tblFAJournal where DocPrefix = 9 and DocID = @DocID order by ID DESC      
END  
IF(@TransID = 21)  
BEGIN      
select TOP 1 ID ID from tblAssignInvoicesHeader where DocID = @DocID order by ID DESC      
END  
END',
N'[export] nocount';
GO
/****** uspGetJsonDataforEWaybill ******/
EXEC #Apply07 N'dbo.uspGetJsonDataforEWaybill', 0x86600C0E187D2F4BD31B42BC870F8A14B2262225610393C78CBEDEB38612A6EE, 0xB356444A3F20CA4F41B361A43EF0296CB923D9A9B5D54C722061874E0119F494, NULL, 0xF4E1884010F10E2AE38821CFE1A7A524A732FB09A66488988A6925B55AA6240A, 0x91364A1B26837060341DC01109E7ED25D68C0F0BD55E3F37B939CB941E1D2C86, NULL,
N'--uspGetJsonDataforEWaybill 2,3,0,''2026-01-05'',''2026-12-30'',''''                    
--uspGetJsonDataforEWaybill 3,639,''2022-12-05'',''2026-12-30''                    
--uspGetJsonDataforEWaybill 3,1,''2627/JUL/31'',''2022-12-05'',''2026-12-30''                     
--uspGetJsonDataforEWaybill 5,3,'''',''2024-12-05'',''2026-12-30'',''VLS/2627/4''                      
--uspGetJsonDataforEWaybill 6,'''',''2022-12-05'',''2026-12-30'',''''                     
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspGetJsonDataforEWaybill]                      
@Mode INT,@TypeID INT,@InvID nvarchar(255) =null,@FromDate date = NULL,@ToDate DATE = NULL,@DocIDs NVARCHAR(MAX)=NULL                      
as                      
SET NOCOUNT ON;
begin                      
DECLARE @QRY NVARCHAR(MAX) = ''''                      
DECLARE @CompName NVARCHAR(255),@CompAddress NVARCHAR(255),@CompCity NVARCHAR(255),                      
@CompPIN NVARCHAR(255),@compState NVARCHAR(255),@compStateCode NVARCHAR(255),@compGSTIN NVARCHAR(255),@MainHSN nvarchar(50)                      
SELECT @CompName = CompanyName,@CompAddress = Address,@CompCity = City,@CompPIN = Pincode,@compState = State,                      
@compStateCode = LEFT(GSTIN,2),@compGSTIN = GSTIN FROM tblCompanyRegistration                     
DECLARE @DetailGross decimal(25,2)        
if(@Mode = 1)                      
BEGIN                      
SELECT ''version'' strver,''1.0.0621'' ver                      
END                      
IF(@Mode = 2)                      
BEGIN                      
IF(@TypeID = 1)--INVOICE E-WAY      
BEGIN      
SET @QRY = ''select SH.ID,SH.DocId,SH.InvDate FROM tblTranSalesHeader SH                      
JOIN tblTranSalesDetail SD ON SD.InvId = SH.ID                      
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId                      
WHERE SH.DocPrefix = 15 AND Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''''''') = '''''''' and isnull(SH.VehicleNo,0) > 0 and isnull(SH.DocId,'''''''') != ''''''''''                   
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.InvDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)                      
--SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)                      
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)                      
SET @QRY = @QRY + '' GROUP BY SH.ID,SH.DocId,SH.InvDate ''                      
SET @QRY = @QRY + '' ORDER BY DocId,SH.InvDate''        
END      
ELSE IF(@TypeID = 3)--VLS E-WAY      
BEGIN      
--select * from tblVanLoadingSlipHeader      
SET @QRY = ''select SH.ID,SH.DocId,SH.DocDate InvDate FROM tblVanLoadingSlipHeader SH       
WHERE Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''''''') = '''''''' and isnull(SH.VehicleNo,0) > 0 and isnull(SH.DocId,'''''''') != ''''''''''                   
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.DocDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)                      
--SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)                      
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)                      
SET @QRY = @QRY + '' GROUP BY SH.ID,SH.DocId,SH.DocDate ''                      
SET @QRY = @QRY + '' ORDER BY DocId,SH.DocDate''      
END      
EXEC sys.sp_executesql @QRY, N''@Mode INT, @TypeID INT, @InvID nvarchar(255), @FromDate date, @ToDate DATE, @DocIDs NVARCHAR(MAX), @CompName NVARCHAR(255), @CompAddress NVARCHAR(255), @CompCity NVARCHAR(255), @CompPIN NVARCHAR(255), @compStateCode NVARCHAR(255), @compGSTIN NVARCHAR(255)'', @Mode, @TypeID, @InvID, @FromDate, @ToDate, @DocIDs, @CompName, @CompAddress, @CompCity, @CompPIN, @compStateCode, @compGSTIN                      
END                      
ELSE IF(@Mode = 3)                      
BEGIN                      
IF(@TypeID = 1)--INVOICE E-WAY      
BEGIN      
SELECT @MainHSN = HSNCode FROM (                      
select TOP 1 MP.HSNCode from tblTranSalesDetail SD                      
JOIN tblTranSalesHeader SH ON SH.ID = SD.InvID                  
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId         
WHERE SH.DocPrefix = 15 AND Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''') = '''' and isnull(SH.VehicleNo,0) > 0 AND SD.TaxId > 0 AND SH.DocID = @InvID                   
ORDER BY SD.NetAmt ASC) AS NK                      
       
set @DetailGross = (                    
select  SUM(ROUND(SD.GrossAmt,2)) from tblTranSalesDetail SD              
JOIN tblTranSalesHeader SH ON SH.ID = SD.InvID              
WHERE SH.DocID = @InvID AND Status IN (1,3,5))                
              
select @compGSTIN userGstin,''O'' supplyType,1 subSupplyType,'''' "subSupplyDesc",''INV'' "docType",DocId "docNo",                      
CONVERT(NVARCHAR,InvDate,103) "docDate",1 "transType",@compGSTIN fromGstin,@CompName fromTrdName,@CompAddress fromAddr1,'''' fromAddr2,                      
@CompCity fromPlace,@CompPIN fromPincode,@compStateCode fromStateCode,@compStateCode actualFromStateCode,                      
CASE WHEN ISNULL(MC.GSTIN,'''') != '''' THEN MC.GSTIN ELSE ''URP'' END toGstin,MC.Name "toTrdName",MC.Billadd1 "toAddr1",                      
MC.Billadd2 +'' '' + MC.Billadd3 "toAddr2",CASE WHEN SH.BeatID = 0 THEN ''CHENNAI'' ELSE GHL.Name END "toPlace",MC.Pincode "toPincode",                      
GST.TINNo "toStateCode",GST.TINNo "actualToStateCode",@DetailGross "totalValue",--dbo.fnGetRoundedValue(ROUND(SH.GrossAmt,2)) "totalValue",                      
(CASE WHEN SH.TaxTypeId = 1 THEN dbo.fnGetRoundedValue(SH.TotalTaxAmt/2) ELSE ''0.00'' END) "cgstValue",                      
(CASE WHEN SH.TaxTypeId = 1 THEN dbo.fnGetRoundedValue(SH.TotalTaxAmt/2) ELSE ''0.00'' END) "sgstValue",                      
(CASE WHEN SH.TaxTypeId = 2 THEN dbo.fnGetRoundedValue(TotalTaxAmt) ELSE ''0.00'' END) "igstValue",0.00 "cessValue",                      
0.00 "TotNonAdvolVal",dbo.fnGetRoundedValue(ROUND(SH.NetAmt,2) - (@DetailGross + ROUND(SH.TotalTaxAmt,2))) "OthValue",              
dbo.fnGetRoundedValue(SH.NetAmt) "totInvValue",                      
(CASE WHEN TransMode = ''Road'' THEN 1 WHEN TransMode = ''Rail'' THEN 2                      
WHEN TransMode = ''Air'' THEN 3 WHEN TransMode = ''Ship/Road cum Ship'' THEN 4 ELSE '''' END) "transMode",                      
CASE WHEN MC.Pincode = @CompPIN THEN 1 ELSE isnull(SH.Distance,0) END "transDistance",(case when isnull(SH.TransportName,'''') = '''' then '''' else LEFT(TransportName,100) end) "transporterName",                      
(case when isnull(SH.TransportID,'''') = '''' then '''' else LEFT(SH.TransportID,15) end) "transporterId",SH.DocId "transDocNo",                      
CONVERT(NVARCHAR,SH.InvDate,103) "transDocDate",VH.VehicleNo "vehicleNo",                      
CASE WHEN SH.VehicleType = ''Regular'' THEN ''R'' WHEN SH.VehicleType = ''ODC'' THEN ''O'' ELSE '''' end "vehicleType",@MainHSN mainHsnCode                      
from tblTranSalesHeader SH                      
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId                      
LEFT JOIN tblMasterBeat GHL ON GHL.ID = SH.BeatID                      
LEFT JOIN tblMasterVehicle VH ON VH.ID = SH.VehicleNo                      
LEFT JOIN tblGSTStateNameandCode GST ON GST.StateID = MC.StateID                      
WHERE SH.DocPrefix =15 AND Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''') = '''' and isnull(SH.VehicleNo,0) > 0 AND SH.DocID = @InvID                      
END      
ELSE IF(@TypeID = 3)--VLS E-WAY      
BEGIN      
SELECT @MainHSN = HSNCode FROM (                      
select TOP 1 MP.HSNCode from tblVanLoadingSlipDetail SD                      
JOIN tblVanLoadingSlipHeader SH ON SH.ID = SD.ID                  
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId                      
WHERE Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''') = '''' and isnull(SH.VehicleNo,0) > 0 AND SD.TaxId > 0 AND SH.DocID = @InvID                   
ORDER BY SD.NetAmt ASC) AS NK                      
          
set @DetailGross = (                    
select  SUM(ROUND(SD.GrossAmt,2)) from tblVanLoadingSlipDetail SD              
JOIN tblVanLoadingSlipHeader SH ON SH.ID = SD.ID              
WHERE SH.DocID = @InvID AND Status IN (1,3,5))   
              
select @compGSTIN userGstin,''O'' supplyType,10 subSupplyType,'''' "subSupplyDesc",''CHL'' "docType",DocId "docNo",                      
CONVERT(NVARCHAR,DocDate,103) "docDate",1 "transType",@compGSTIN fromGstin,@CompName fromTrdName,@CompAddress fromAddr1,'''' fromAddr2,      
@CompCity fromPlace,@CompPIN fromPincode,@compStateCode fromStateCode,@compStateCode actualFromStateCode,      
@compGSTIN toGstin,'''' "toTrdName",'''' "toAddr1",      
'''' "toAddr2",'''' "toPlace",@CompPIN "toPincode",--MC.Pincode      
@compStateCode "toStateCode",@compStateCode "actualToStateCode",@DetailGross "totalValue",--dbo.fnGetRoundedValue(ROUND(SH.GrossAmt,2)) "totalValue",      
dbo.fnGetRoundedValue(SH.TaxAmt/2)"cgstValue",dbo.fnGetRoundedValue(SH.TaxAmt/2) "sgstValue",      
''0.00'' "igstValue",0.00 "cessValue",0.00 "TotNonAdvolVal",      
dbo.fnGetRoundedValue(ROUND(SH.NetAmt,2) - (@DetailGross + ROUND(SH.TaxAmt,2))) "OthValue",              
dbo.fnGetRoundedValue(SH.NetAmt) "totInvValue",                      
(CASE WHEN VehicleType = ''Road'' THEN 1 WHEN VehicleType = ''Rail'' THEN 2                      
WHEN VehicleType = ''Air'' THEN 3 WHEN VehicleType = ''Ship/Road cum Ship'' THEN 4 ELSE '''' END) "transMode",                      
1 "transDistance",(case when isnull(SH.TransportName,'''') = '''' then '''' else LEFT(TransportName,100) end) "transporterName",                      
(case when isnull(SH.TransportID,'''') = '''' then '''' else LEFT(SH.TransportID,15) end) "transporterId",SH.DocId "transDocNo",                      
CONVERT(NVARCHAR,SH.DocDate,103) "transDocDate",VH.VehicleNo "vehicleNo",                      
CASE WHEN SH.TransMode = ''Regular'' THEN ''R'' WHEN SH.TransMode = ''ODC'' THEN ''O'' ELSE '''' end "vehicleType",@MainHSN mainHsnCode                      
from tblVanLoadingSlipHeader SH                                    
LEFT JOIN tblMasterVehicle VH ON VH.ID = SH.VehicleNo      
WHERE Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''') = '''' and isnull(SH.VehicleNo,0) > 0 AND SH.DocID = @InvID       
END      
END                      
ELSE IF(@Mode = 4)                      
BEGIN                      
IF(@TypeID = 1)--INVOICE E-WAY      
BEGIN      
SELECT SD.Serial "itemNo",MP.Name "productName",'''' "productDesc",MP.HSNCode "hsnCode",dbo.fnGetRoundedValue(SD.UomQty) "quantity",                      
UOM.Name "qtyUnit",dbo.fnGetRoundedValue(SD.GrossAmt) "taxableAmount",dbo.fnGetRoundedValue(SD.TaxValue/2) "sgstRate",                
dbo.fnGetRoundedValue(SD.TaxValue/2) "cgstRate",0 "igstRate",0 "cessRate",                      
0 "cessNonAdvol" from tblTranSalesHeader SH                      
JOIN tblTranSalesDetail SD ON SD.InvId = SH.ID                      
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId                      
JOIN tblMasterUom UOM ON UOM.ID = SD.UomId                      
WHERE SH.DocPrefix = 15 AND Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''') = '''' and isnull(SH.VehicleNo,0) > 0 AND SD.TaxId > 0 AND SH.DocID = @InvID                      
ORDER BY SD.Serial            
END      
ELSE IF(@TypeID = 3)--VLS E-WAY      
BEGIN      
SELECT SD.Serial "itemNo",MP.Name "productName",'''' "productDesc",MP.HSNCode "hsnCode",dbo.fnGetRoundedValue(SD.UomQty) "quantity",                      
UOM.Name "qtyUnit",dbo.fnGetRoundedValue(SD.GrossAmt) "taxableAmount",dbo.fnGetRoundedValue(SD.TaxValue/2) "sgstRate",                
dbo.fnGetRoundedValue(SD.TaxValue/2) "cgstRate",0 "igstRate",0 "cessRate",                      
0 "cessNonAdvol" from tblVanLoadingSlipHeader SH                      
JOIN tblVanLoadingSlipDetail SD ON SD.ID = SH.ID                      
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId                      
JOIN tblMasterUom UOM ON UOM.ID = SD.UomId                      
WHERE Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''') = '''' and isnull(SH.VehicleNo,0) > 0 AND SD.TaxId > 0 AND SH.DocID = @InvID                      
ORDER BY SD.Serial       
END      
END                      
else if(@Mode = 5)                      
BEGIN                
IF(@TypeID = 1)--INVOICE E-WAY      
BEGIN      SET @QRY = '' select DocId "docNo",CONVERT(NVARCHAR,InvDate,103) "docDate",MC.Name "toTrdName",CASE WHEN ISNULL(MC.GSTIN,'''''''') != '''''''' THEN MC.GSTIN ELSE ''''URP'''' END toGstin,        
MC.Billadd1 "toAddr1",MC.Billadd2 +'''' '''' + MC.Billadd3 "toAddr2",CASE WHEN SH.BeatID = 0 THEN ''''CHENNAI'''' ELSE GHL.Name END "toPlace",MC.Pincode "toPincode",        
@compGSTIN userGstin,''''O'''' supplyType,1 subSupplyType,'''''''' "subSupplyDesc",''''INV'''' "docType",                      
1 "transType",@compGSTIN fromGstin,@CompName fromTrdName,@CompAddress fromAddr1,'''''''' fromAddr2,                      
@CompCity fromPlace,@CompPIN fromPincode,@compStateCode fromStateCode,@compStateCode actualFromStateCode,        
TINNo "toStateCode",TINNo "actualToStateCode",dbo.fnGetRoundedValue(SH.GrossAmt) "totalValue",                      
(CASE WHEN SH.TaxTypeId = 1 THEN dbo.fnGetRoundedValue(SH.TotalTaxAmt/2) ELSE ''''0.00'''' END) "cgstValue",                      
(CASE WHEN SH.TaxTypeId = 1 THEN dbo.fnGetRoundedValue(SH.TotalTaxAmt/2) ELSE ''''0.00'''' END) "sgstValue",                      
(CASE WHEN SH.TaxTypeId = 2 THEN dbo.fnGetRoundedValue(TotalTaxAmt) ELSE ''''0.00'''' END) "igstValue",0.00 "cessValue",                      
0.00 "TotNonAdvolVal",dbo.fnGetRoundedValue( NetAmt - (GrossAmt + TotalTaxAmt)) "OthValue",dbo.fnGetRoundedValue(SH.NetAmt) "totInvValue",                      
CONVERT(VARCHAR,(CASE WHEN TransMode = ''''Road'''' THEN 1 WHEN TransMode = ''''Rail'''' THEN 2 WHEN TransMode = ''''Air'''' THEN 3                      
WHEN TransMode = ''''Ship/Road cum Ship'''' THEN 4 ELSE '''''''' END)) "transMode",                      
CASE WHEN MC.Pincode = @CompPIN THEN 1 ELSE isnull(SH.Distance,0) END "transDistance",(case when isnull(SH.TransportName,'''''''') = '''''''' then '''''''' else LEFT(TransportName,100) end) "transporterName",                      
(case when isnull(SH.TransportID,'''''''') = '''''''' then '''''''' else LEFT(SH.TransportID,15) end) "transporterId",SH.DocId "transDocNo",                      
CONVERT(NVARCHAR,SH.InvDate,103) "transDocDate",VH.VehicleNo "vehicleNo",                      
CASE WHEN SH.VehicleType = ''''Regular'''' THEN ''''R'''' WHEN SH.VehicleType = ''''ODC'''' THEN ''''O'''' ELSE '''''''' end "vehicleType",'''''''' mainHsnCode                      
from tblTranSalesHeader SH                      
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId                      
LEFT JOIN tblMasterBeat GHL ON GHL.ID = SH.BeatID                         
LEFT JOIN tblMasterVehicle VH ON VH.ID = SH.VehicleNo                      
LEFT JOIN tblGSTStateNameandCode GST ON GST.StateID = MC.StateID                         
WHERE SH.DocPrefix =15 AND Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''''''') = '''''''' and isnull(SH.VehicleNo,0) > 0 and isnull(SH.DocId,'''''''') != '''''''' ''                  
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.InvDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)                      
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)                      
SET @QRY = @QRY + '' ORDER BY DocId ''      
END      
ELSE IF(@TypeID = 3)--VLS E-WAY      
BEGIN      
SET @QRY = '' select DocId "docNo",CONVERT(NVARCHAR,DocDate,103) "docDate",'''''''' "toTrdName",@compGSTIN toGstin,        
'''''''' "toAddr2",'''''''' "toPlace",@CompPIN "toPincode",      
@compGSTIN userGstin,''''O'''' supplyType,10 subSupplyType,'''''''' "subSupplyDesc",''''CHL'''' "docType",                      
1 "transType",@compGSTIN fromGstin,@CompName fromTrdName,@CompAddress fromAddr1,'''''''' fromAddr2,                      
@CompCity fromPlace,@CompPIN fromPincode,@compStateCode fromStateCode,@compStateCode actualFromStateCode,        
@compStateCode "toStateCode",@compStateCode "actualToStateCode",dbo.fnGetRoundedValue(SH.GrossAmt) "totalValue",                      
dbo.fnGetRoundedValue(SH.TaxAmt/2) "cgstValue",dbo.fnGetRoundedValue(SH.TaxAmt/2) "sgstValue",      
''''0.00'''' "igstValue",0.00 "cessValue",0.00 "TotNonAdvolVal",      
dbo.fnGetRoundedValue( NetAmt - (GrossAmt + TaxAmt)) "OthValue",dbo.fnGetRoundedValue(SH.NetAmt) "totInvValue",                      
CONVERT(VARCHAR,(CASE WHEN VehicleType = ''''Road'''' THEN 1 WHEN VehicleType = ''''Rail'''' THEN 2 WHEN VehicleType = ''''Air'''' THEN 3                      
WHEN VehicleType = ''''Ship/Road cum Ship'''' THEN 4 ELSE '''''''' END)) "transMode",                      
1 "transDistance",(case when isnull(SH.TransportName,'''''''') = '''''''' then '''''''' else LEFT(TransportName,100) end) "transporterName",                      
(case when isnull(SH.TransportID,'''''''') = '''''''' then '''''''' else LEFT(SH.TransportID,15) end) "transporterId",SH.DocId "transDocNo",                      
CONVERT(NVARCHAR,SH.DocDate,103) "transDocDate",VH.VehicleNo "vehicleNo",                      
CASE WHEN SH.TransMode = ''''Regular'''' THEN ''''R'''' WHEN SH.TransMode = ''''ODC'''' THEN ''''O'''' ELSE '''''''' end "vehicleType",'''''''' mainHsnCode                      
from tblVanLoadingSlipHeader SH                      
LEFT JOIN tblMasterVehicle VH ON VH.ID = SH.VehicleNo      
WHERE Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''''''') = '''''''' and isnull(SH.VehicleNo,0) > 0 and isnull(SH.DocId,'''''''') != '''''''' ''                  
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.DocDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)                      
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)                      
SET @QRY = @QRY + '' ORDER BY DocId ''      
END      
EXEC sys.sp_executesql @QRY, N''@Mode INT, @TypeID INT, @InvID nvarchar(255), @FromDate date, @ToDate DATE, @DocIDs NVARCHAR(MAX), @CompName NVARCHAR(255), @CompAddress NVARCHAR(255), @CompCity NVARCHAR(255), @CompPIN NVARCHAR(255), @compStateCode NVARCHAR(255), @compGSTIN NVARCHAR(255)'', @Mode, @TypeID, @InvID, @FromDate, @ToDate, @DocIDs, @CompName, @CompAddress, @CompCity, @CompPIN, @compStateCode, @compGSTIN                      
END                      
else if(@Mode = 6)                      
BEGIN               
IF(@TypeID = 1)--INVOICE E-WAY      
BEGIN      
SET @QRY = '' SELECT DocId "docNo",SD.Serial "itemNo",MP.Name "productName",'''''''' "productDesc",MP.HSNCode "hsnCode",dbo.fnGetRoundedValue(SD.UomQty) "quantity",                      
UOM.Name "qtyUnit",dbo.fnGetRoundedValue(SD.GrossAmt) "taxableAmount",dbo.fnGetRoundedValue(SD.TaxAmt / 2) "sgstRate",dbo.fnGetRoundedValue(SD.TaxAmt / 2) "cgstRate",0 "igstRate",0 "cessRate",                      
0 "cessNonAdvol" from tblTranSalesHeader SH                      
JOIN tblTranSalesDetail SD ON SD.InvId = SH.ID                      
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId                      
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId                      
JOIN tblMasterUom UOM ON UOM.ID = SD.UomId                      
WHERE SH.DocPrefix =15 AND Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''''''') = '''''''' AND SD.TaxId > 0  and isnull(SH.VehicleNo,0) > 0  and isnull(SH.DocId,'''''''') != ''''''''''--AND ISNULL(MC.GSTIN,'''''''') != ''''''''                       
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.InvDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)                      
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)                      
SET @QRY = @QRY + '' ORDER BY SH.InvDate,DocId,SD.Serial ''                      
END      
ELSE IF(@TypeID = 3)--VLS E-WAY      
BEGIN      
SET @QRY = '' SELECT DocId "docNo",SD.Serial "itemNo",MP.Name "productName",'''''''' "productDesc",MP.HSNCode "hsnCode",dbo.fnGetRoundedValue(SD.UomQty) "quantity",                      
UOM.Name "qtyUnit",dbo.fnGetRoundedValue(SD.GrossAmt) "taxableAmount",dbo.fnGetRoundedValue(SD.TaxAmt / 2) "sgstRate",dbo.fnGetRoundedValue(SD.TaxAmt / 2) "cgstRate",0 "igstRate",0 "cessRate",                      
0 "cessNonAdvol" from tblVanLoadingSlipHeader SH                      
JOIN tblVanLoadingSlipDetail SD ON SD.ID = SH.ID       
JOIN tblMasterProduct MP ON MP.ID = SD.ProdId                      
JOIN tblMasterUom UOM ON UOM.ID = SD.UomId                      
WHERE Status IN (1,3,5) AND ISNULL(SH.EWBNo,'''''''') = '''''''' AND SD.TaxId > 0  and isnull(SH.VehicleNo,0) > 0  and isnull(SH.DocId,'''''''') != ''''''''''--AND ISNULL(MC.GSTIN,'''''''') != ''''''''                       
SET @QRY = @QRY + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.DocDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)                      
SET @QRY = @QRY + (CASE WHEN ISNULL(@DocIDs,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(LEFT(@DocIDs,LEN(@DocIDs) - 1), N'''',''''))'' END)                      
SET @QRY = @QRY + '' ORDER BY SH.DocDate,DocId,SD.Serial ''       
END      
EXEC sys.sp_executesql @QRY, N''@Mode INT, @TypeID INT, @InvID nvarchar(255), @FromDate date, @ToDate DATE, @DocIDs NVARCHAR(MAX), @CompName NVARCHAR(255), @CompAddress NVARCHAR(255), @CompCity NVARCHAR(255), @CompPIN NVARCHAR(255), @compStateCode NVARCHAR(255), @compGSTIN NVARCHAR(255)'', @Mode, @TypeID, @InvID, @FromDate, @ToDate, @DocIDs, @CompName, @CompAddress, @CompCity, @CompPIN, @compStateCode, @compGSTIN                      
END                      
END',
N'[06] nocount';
GO
/****** uspGetMapRoleMenus ******/
EXEC #Apply07 N'dbo.uspGetMapRoleMenus', 0x620F06D42C73389D6C7D0BE14D90DD773D96E0F05EC65636B9543AAA8765ACC0, NULL, NULL, 0x041AD93D7BC6E55670090D16AF6BC148581988847DDE744ED8DE0D7E3ED2776D, 0xE51BCD7A0DBE4D159AEACBE2D319FED0586B680CFF8CF724D3FABB389C06E5DC, NULL,
N'--[uspGetMapRoleMenus] 79,2      
ALTER PROC [dbo].[uspGetMapRoleMenus]          
 @RoleId INT,@LoginUID INT,@Apptype int = 0
 AS                               
 SET NOCOUNT ON;
BEGIN                  
 if(@LoginUID = 1)--@userId      
 BEGIN          
SELECT MenuId,MenuName,MenuParentId,1 AS Permission        
    FROM tblMenus                       
    WHERE MenuId in (SELECT PermissionFormId  FROM tblRolePermissions WHERE Role=@RoleId) and IsMobileApp = @Apptype --AND Permission=1          
              
    union        
    SELECT MenuId,MenuName,MenuParentId,0                         
    FROM tblMenus                               
    WHERE MenuId not in (SELECT PermissionFormId  FROM tblRolePermissions WHERE Role=@RoleId) and IsMobileApp = @Apptype --AND Permission=1              
END          
ELSE          
BEGIN          
DECLARE @LOGINROLE INT = (SELECT RoleID FROM tblUsers WHERE ID = @LoginUID)    
    
SELECT MenuId,MenuName,MenuParentId INTO #LOGTEMP      
FROM tblMenus      
WHERE MenuId in (SELECT PermissionFormId  FROM tblRolePermissions WHERE Role=@LOGINROLE) and IsMobileApp = @Apptype --AND Permission=1          
      
        
SELECT MenuId,MenuName,MenuParentId INTO #UTEMP      
FROM tblMenus      
WHERE MenuId in (SELECT PermissionFormId  FROM tblRolePermissions WHERE Role=@RoleId) and IsMobileApp = @Apptype --AND Permission=1          
      
SELECT LT.MenuId,LT.MenuName,LT.MenuParentId,CASE WHEN ISNULL(UT.MenuId,0) = 0 THEN 0 ELSE 1 END Permission FROM #LOGTEMP LT      
LEFT JOIN #UTEMP UT ON UT.MenuId = LT.MenuId      
      
DROP TABLE #LOGTEMP,#UTEMP      
 END        
 END',
N'[export] nocount';
GO
/****** uspgetMasterlists ******/
EXEC #Apply07 N'dbo.uspgetMasterlists', 0xCEE62437C546699D932FC34CC754188932CB5BC2535E4D231E726ED169F60F67, NULL, NULL, 0xFFD27FC4FBBDA429F779B9AAADBF3F6A1DA84FC4139F649EF556BB5381817DE3, 0xC66742EB346D81BDB02702B45C06B8C602DCD1C552550D1B70BBBE1487D5182C, NULL,
N'ALTER PROC [dbo].[uspgetMasterlists]                
@FormName nvarchar(100),@SubField nvarchar(100) = null,@Value nvarchar(100) = null                
as                
SET NOCOUNT ON;
begin                
if(@FormName = ''vehicle'')                
begin                
select ID,VehicleNo Name from tblMasterVehicle where Active = 1 order by VehicleNo                
end              
if(@FormName = ''returntype'')              
begin              
select ID, Name from tblMasterReturnType where Active = 1 order by Name              
end              
if(@FormName = ''reason'')              
begin              
select ID, Name from tblMasterReason Where Active = 1  Order by Name              
end
if(@FormName = ''location'')              
begin              
select ID, Name from tblMasterLocation Where Active = 1  Order by Name              
end   
if(@FormName = ''accountno'')              
begin              
select ''BankAccNo'' Trans,MBA.ID,FAID Code,AccountNo+''|''+convert(nvarchar,MB.ID)+''|''+BranchName+''|''+IFSCCode+''|''+MICR+''|''+MB.Name  Name from tblMasterBankAccount MBA                                              
JOIN tblMasterBank MB ON MB.ID = MBA.BankID where MBA.Active = 1 AND FAID > 0                
end              
if(@FormName = ''creditterm'')              
begin              
select ID, Name from tblMasterCreditTerm where Active = 1 order by ID              
end              
if(@FormName = ''partyname'')              
begin              
select FAID, AccountName Name from tblFAAccount             
where Active = 1 and AccountGroup IN (44,2,25,3,29,6,12,13,39,1,19,33,43,35,18,20)  order by AccountName              
end             
if(@FormName = ''accountname'')              
begin              
select FAID,[Account Name] Name from [FACNAccountNames] order by [Account Name]              
end             
if(@FormName = ''tax'')            
begin            
select TaxID ID, TaxName Name from tblMasterTax where Active = 1 order by TaxID            
end            
if(@FormName = ''jvaccountname'')            
begin            
select FAID, AccountName Name FROM tblFAAccount FAA                                          
  JOIN tblFAGroup FAG ON FAG.FAGroup =FAA.AccountGroup AND FAG.UserGroup IN (0,1,2)                                           
  WHERE  FAA.Active =1            
end            
if(@FormName = ''salesman'')            
begin            
select ID, Name from tblMasterSalesman where Active = 1 order by Name            
end            
if(@FormName = ''fromaccountno'')              
begin              
select ID, AccountNo from tblMasterBankAccount where Active =1 order by ID              
end             
if(@FormName = ''toaccountno'')              
begin              
select ID, AccountNo from tblMasterBankAccount where Active =1 order by ID              
end             
if(@FormName = ''contraaccountno'')            
begin            
SELECT MBA.FAID,AccountNo+''|''+MB.Name+''|''+BranchName+''|''+IFSCCode+''|''+MICR+''|''+CONVERT(nvarchar,SetDefault)+''|''+CONVERT(nvarchar,MBA.ID) Name from tblMasterBankAccount MBA                            
JOIN tblMasterBank MB ON MB.ID = MBA.BankID where MBA.Active = 1 AND FAID > 0            
end            
if(@FormName = ''chequebook'')          
begin          
SELECT 1 Type,''ChequeBook'' Trans,CBD.ChequeNo ID,ChequeBookreferNo Code,CBH.ChequeBookreferNo+'' - ''+CBD.ChequeNo Name, CBH.ChequeBookID                           
FROM tblMasterChequeBook CBH                            
JOIN tblMasterChequeBookDetail CBD ON CBD.ChequeBookID = CBH.ChequeBookID                            
join tblMasterBankAccount MBA ON MBA.ID = CBH.BankAccountID          
end          
if(@FormName = ''users'')          
BEGIN      
SELECT ID,UserName Name FROM tblUsers WHERE ID <> 1 ORDER BY UserName      
END      
if(@FormName = ''taxtran'')          
BEGIN      
SELECT MT.TaxID ID,MT.TaxName Name,MT.GST TaxPern,CASE WHEN MTD.AppOn = -1 THEN SUM(CumulativeTax) ELSE 0 END MRPONTax  
FROM tblMasterTax MT  
JOIN tblMasterTaxDetail MTD ON MTD.TaxID = MT.TaxID  
GROUP BY MT.TaxID,MT.TaxName,MT.GST,MTD.AppOn  
order by 1   
END  
end',
N'[export] nocount';
GO
/****** uspGetMobileHomeDashboard ******/
EXEC #Apply07 N'dbo.uspGetMobileHomeDashboard', 0x60429F59692D0558E7FA295D6945C6CAEC2FF259077E36AAC6E109A39656C1F2, NULL, NULL, 0x4C0037CDAE10BFAE4B63C12B407FA1A84EC823FF861B55E6D0E923258F9E8C95, 0x1B99A1EB8A3B18908C17BA4B828FDE790C0D115D0932F45203D20BDAED616571, NULL,
N'--[uspGetMobileHomeDashboard] 2
ALTER PROC [dbo].[uspGetMobileHomeDashboard]                      
@UserID INT                      
AS                      
SET NOCOUNT ON;
BEGIN                      
  
create table #tempDB(DBValues nvarchar(max),Name nvarchar(max))                      
insert into #tempDB                      
select COUNT(distinct CustID),''Total Count'' as Name  from (                      
select distinct CustID from tblTranOrderTakenHeader WHERE CBy = @UserID AND Status in (1,3,8) and DocDate = CONVERT(DATE,GETDATE())                      
union all        
SELECT distinct CustID  FROM tblTranOrderCollectionHeader WHERE CBy = @UserID AND Status in (1,3,8) and DocDate = CONVERT(DATE,GETDATE())                              
union all        
SELECT distinct CustID FROM tblTranOrderReturnHeader WHERE CBy = @UserID AND DocDate = CONVERT(DATE,GETDATE())                    
) AS NK        
insert into #tempDB                      
SELECT  CONVERT(nvarchar(max),cast(dbo.fnGetRoundedValue(isnull(OTAmt,0)) as money),1) + '' / '' + CONVERT(nvarchar(max),OTCount) OTAmt,        
strVal FROM ( select  COUNT(DISTINCT CustID) OTCount,SUM(price * Qty) OTAmt,''OT Amt'' strVal  from tblTranOrderTakenHeader OTH    
JOIN tblTranOrderTakenDetail OTD ON OTD.ID = OTH.ID    
WHERE Status in (1,3,8) and CBy = @UserID AND DocDate = CONVERT(DATE,GETDATE())) AS BC        
insert into #tempDB                      
SELECT isnull(CONVERT(nvarchar(max),cast(dbo.fnGetRoundedValue(SUM(Amt))as money),1)+ '' / '' + CONVERT(nvarchar(max),COUNT(DISTINCT CustID)) ,0) ,''Coll Amt'' CollAmt     
FROM tblTranOrderCollectionHeader WHERE CBy = @UserID AND Status in (1,3,8) and DocDate = CONVERT(DATE,GETDATE())         
insert into #tempDB                      
SELECT  isnull(CONVERT(nvarchar(max),cast(dbo.fnGetRoundedValue(SUM(Amt)) as money),1),0) ,''Cash Count''  CashCollAmt     
FROM tblTranOrderCollectionHeader WHERE CBy = @UserID AND DocDate = CONVERT(DATE,GETDATE()) and Status in (1,3,8) and PaymentID = 1                      
insert into #tempDB                      
select TOP 1 SUBSTRING(CONVERT(NVARCHAR,CDate),len(CONVERT(NVARCHAR,CDate))-7,len(CONVERT(NVARCHAR,CDate))) fstdate,Hint  from (                      
select (isnull(CDate,GETDATE())) CDate,''Start TIme'' Hint from tblTranOrderTakenHeader WHERE CBy = @UserID  AND Status in (1,3,8) and DocDate = CONVERT(DATE,GETDATE())                      
union                      
SELECT (isnull(CDate,GETDATE())) CDate,''Start TIme'' Hint FROM tblTranOrderCollectionHeader WHERE CBy = @UserID AND Status in (1,3,8) and DocDate = CONVERT(DATE,GETDATE())                                 
union                      
SELECT (isnull(CDate,GETDATE())) CDate,''Start TIme'' Hint FROM tblTranOrderReturnHeader WHERE CBy = @UserID AND DocDate = CONVERT(DATE,GETDATE())    
) AS NK                      
order by CDate asc                
insert into #tempDB                      
select TOP 1 SUBSTRING(CONVERT(NVARCHAR,CDate),len(CONVERT(NVARCHAR,CDate))-7,len(CONVERT(NVARCHAR,CDate))) fstdate,Hint  from (                      
select (isnull(CDate,GETDATE())) CDate,''End TIme'' Hint from tblTranOrderTakenHeader WHERE CBy = @UserID AND Status in (1,3,8) and DocDate = CONVERT(DATE,GETDATE())                      
union                      
SELECT (isnull(CDate,GETDATE())) CDate,''End TIme'' Hint FROM tblTranOrderCollectionHeader WHERE CBy = @UserID AND Status in (1,3,8) and DocDate = CONVERT(DATE,GETDATE())                                   
union                      
SELECT (isnull(CDate,GETDATE())) CDate,''End TIme'' Hint FROM tblTranOrderReturnHeader WHERE CBy = @UserID AND DocDate = CONVERT(DATE,GETDATE())                    
) AS NK                      
order by CDate desc                   
select * from #tempDB                      
drop table #tempDB                      
END',
N'[export] nocount';
GO
/****** uspGetModifyHistoryData ******/
EXEC #Apply07 N'dbo.uspGetModifyHistoryData', 0x58A0F31BDB5E8B9E003841E2865927ADB7BDB963EA6DC3554AC4D3C59557304F, 0x5E29CAFF5032E45FAAD49C500C0F7CF6612C447024CDCCBCE32DB67E97317CD3, NULL, 0xBBA3B9A73AF3B97385E4CA9F0845668159DBF7E38747CABEAF4024CC5B292CF7, 0xC7D637773679098B913E887C7E354A25E912FD1C95DAF2C163CB7B225434E094, NULL,
N'ALTER PROCEDURE [dbo].[uspGetModifyHistoryData]          
@Mode INT,@TableID NVARCHAR(MAX) = NULL,@UserID NVARCHAR(MAX) = NULL,@FromDate date = null,@ToDate date = null,@ID NVARCHAR(255) = NULL          
AS          
SET NOCOUNT ON;
BEGIN          
declare @strQuery NVARCHAR(MAX),@FormID int          
IF(@Mode = 1)          
BEGIN          
select 1 Type,''Tables'' Trans,ID,'''' Code,FormName Name from tblTablesNames where ID <= 29 OR ID IN (42) OR FormType IN (1,2)    
union all          
SELECT 2 Type,''Users'' Trans,ID,'''',UserName FROM tblUsers WHERE Active = 1          
order by Type,Name          
END          
ELSE IF(@Mode = 2)          
BEGIN          
set @FormID = @TableID          
select MBy UserID,UPPER(UserName) UserName from (          
--SINGLE MASTER          
select MH.HisCBy MBy,U.UserName from tblMasterHistory MH          
JOIN tblUsers U ON U.ID = MH.HisCBy WHERE MH.HisCBy = (CASE WHEN @UserID = 0 THEN MH.HisCBy ELSE @UserID END) and          
CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate and FormID = (CASE WHEN @FormID = 0 THEN FormID ELSE @FormID END)          
GROUP BY MH.HisCBy,U.UserName          
UNION -- CUSTOMER,VENDOR          
SELECT MH.HisCBy,U.UserName FROM tblMasterCustomerVendorHistory MH          
JOIN tblUsers U ON U.ID = MH.HisCBy WHERE MH.HisCBy = (CASE WHEN @UserID = 0 THEN MH.HisCBy ELSE @UserID END) and          
CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate and FormID = (CASE WHEN @FormID = 0 THEN FormID ELSE @FormID END)          
GROUP BY MH.HisCBy,U.UserName          
UNION -- PRODUCT          
SELECT MH.HisCBy,U.UserName FROM tblMasterProductHistory MH          
JOIN tblUsers U ON U.ID = MH.HisCBy WHERE MH.HisCBy = (CASE WHEN @UserID = 0 THEN MH.HisCBy ELSE @UserID END) and          
CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate and FormID = (CASE WHEN @FormID = 0 THEN FormID ELSE @FormID END)          
GROUP BY MH.HisCBy,U.UserName          
UNION -- PRODUCT PRICE CHANGE         
SELECT MH.HisCBy,U.UserName FROM tblPriceChangeHistory MH          
JOIN tblUsers U ON U.ID = MH.HisCBy WHERE MH.HisCBy = (CASE WHEN @UserID = 0 THEN MH.HisCBy ELSE @UserID END) and          
CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate and FormID = (CASE WHEN @FormID = 0 THEN FormID ELSE @FormID END)      
GROUP BY MH.HisCBy,U.UserName       
--UNION -- AUTO INDENT          
--SELECT MH.MBy,U.UserName FROM tblTransAutomaticIndentHeader MH          
--JOIN tblUsers U ON U.ID = MH.MBy WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--GROUP BY MH.MBy,U.UserName          
--UNION -- PO          
--SELECT MH.MBy,U.UserName FROM tblPurchaseOrderHeader MH          
--JOIN tblUsers U ON U.ID = MH.MBy WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--GROUP BY MH.MBy,U.UserName          
--UNION -- BILL,PR          
--SELECT MH.MBy,U.UserName FROM tblTransPurchaseHeader MH          
--JOIN tblUsers U ON U.ID = MH.MBy WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--GROUP BY MH.MBy,U.UserName          
--UNION -- CN,DN          
--SELECT MH.MBy,U.UserName FROM tblNoteDetails MH          
--JOIN tblUsers U ON U.ID = MH.MBy WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--GROUP BY MH.MBy,U.UserName          
--UNION -- CONT          
--SELECT MH.MBy,U.UserName FROM tblTranContra MH          
--JOIN tblUsers U ON U.ID = MH.MBy WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--GROUP BY MH.MBy,U.UserName          
--UNION -- RV,PV    
--SELECT MH.MBy,U.UserName FROM tblTranPRVoucher MH          
--JOIN tblUsers U ON U.ID = MH.MBy WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--GROUP BY MH.MBy,U.UserName          
--UNION ALL -- JE          
--SELECT MH.MBy,U.UserName FROM tblFAJournal MH          
--JOIN tblUsers U ON U.ID = MH.MBy WHERE DocPrefix = 9 AND Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--GROUP BY MH.MBy,U.UserName          
--UNION ALL -- OTHER COLL          
--SELECT MH.MBy,U.UserName FROM tblTranCollectionHeader MH          
--JOIN tblUsers U ON U.ID = MH.MBy WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--GROUP BY MH.MBy,U.UserName          
--UNION ALL -- OTHER PAY          
--SELECT MH.MBy,U.UserName FROM tblTranPaymentHeader MH          
--JOIN tblUsers U ON U.ID = MH.MBy WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--GROUP BY MH.MBy,U.UserName          
) as rec          
GROUP BY MBy,UserName          
ORDER BY UserName          
END          
ELSE IF(@Mode = 3)          
BEGIN          
set @FormID = @TableID          
select FormID,UPPER(FormName) FormName into #tempForms from (          
--SINGLE MASTER          
select MH.FormID,U.FormName from tblMasterHistory MH          
JOIN tblTablesNames U ON U.ID = MH.FormID WHERE MH.HisCBy = (CASE WHEN @UserID = 0 THEN MH.HisCBy ELSE @UserID END) and          
CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate          
GROUP BY MH.FormID,U.FormName          
UNION ALL -- CUSTOMER,VENDOR          
SELECT MH.FormID,U.FormName FROM tblMasterCustomerVendorHistory MH          
JOIN tblTablesNames U ON U.ID = MH.FormID WHERE MH.HisCBy = (CASE WHEN @UserID = 0 THEN MH.HisCBy ELSE @UserID END) and          
CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate          
GROUP BY MH.FormID,U.FormName          
UNION ALL -- PRODUCT          
SELECT MH.FormID,U.FormName FROM tblMasterProductHistory MH          
JOIN tblTablesNames U ON U.ID = MH.FormID WHERE MH.HisCBy = (CASE WHEN @UserID = 0 THEN MH.HisCBy ELSE @UserID END) and          
CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate          
GROUP BY MH.FormID,U.FormName          
UNION ALL -- PRODUCT  PRICE CHANGE      
SELECT MH.FormID,U.FormName FROM tblPriceChangeHistory MH          
JOIN tblTablesNames U ON U.ID = MH.FormID WHERE MH.HisCBy = (CASE WHEN @UserID = 0 THEN MH.HisCBy ELSE @UserID END) and          
CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate          
GROUP BY MH.FormID,U.FormName         
--UNION ALL -- AUTO INDENT          
--SELECT 30,''Automatic Indent'' FROM tblTransAutomaticIndentHeader MH          
-- WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--UNION ALL -- PO          
--SELECT 31,''Purchase Order'' FROM tblPurchaseOrderHeader MH          
-- WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--UNION ALL -- BILL,PR          
--SELECT case when TransID = 1 then 32 ELSE 33 END,case when TransID = 1 then ''Purchase Bill'' ELSE ''Purchase Return'' END FROM tblTransPurchaseHeader MH          
-- WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--UNION ALL -- CN,DN          
--SELECT case when TransID = 4 then 34 ELSE 35 END,case when TransID = 4 then ''Credit Note'' ELSE ''Debit Note'' END FROM tblNoteDetails MH          
-- WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--UNION ALL -- CONT          
--SELECT 36,''Contra'' FROM tblTranContra MH          
-- WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--UNION ALL -- RV,PV          
--SELECT case when TransID = 6 then 37 ELSE 38 END,case when TransID = 6 then ''Payable Voucher'' ELSE ''Receivable Voucher'' END FROM tblTranPRVoucher MH          
-- WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--UNION ALL -- JE          
--SELECT 39,''Journal Entry'' FROM tblFAJournal MH          
-- WHERE DocPrefix = 9 AND Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--UNION ALL -- OTHER COLL          
--SELECT 40,''Other Collection'' FROM tblTranCollectionHeader MH          
-- WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
--UNION ALL -- OTHER PAY          
--SELECT 41,''Other Payment'' FROM tblTranPaymentHeader MH          
-- WHERE Status = 2 AND MH.Mby = (CASE WHEN @UserID = 0 THEN MH.MBy ELSE @UserID END) and          
--CONVERT(DATE,MH.MDATE) BETWEEN @FromDate AND @ToDate          
) as rec          
GROUP BY FormID,FormName          
order by FormName          
select * from #tempForms where FormID = (CASE WHEN @FormID = 0 THEN FormID ELSE @FormID END)          
drop table #tempForms          
END          
ELSE IF(@Mode = 4)          
BEGIN          
set @FormID = @TableID          
IF(@FormID <= 25 or @FormID = 29 OR @FormID = 43)          
BEGIN          
select MH.ID,MIN(Name) Name,COUNT(Ident) nCount from tblMasterHistory MH          
WHERE MH.HisCBy = @UserID and FormID = @FormID and CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate          
GROUP BY MH.ID          
END          
IF(@FormID = 26 OR @FormID = 27) -- customer,vendor          
BEGIN          
select MH.ID,MIN(Name) Name,COUNT(Ident) nCount from tblMasterCustomerVendorHistory MH          
WHERE MH.HisCBy = @UserID and FormID = @FormID and CONVERT(DATE,MH.HisCDate) BETWEEN @FromDate AND @ToDate          
GROUP BY MH.ID          
END          
