SELECT * INTO #MVEND FROM (          
SELECT 1 IDX,MS.ID,Code,MS.Name,Billadd1,Billadd2,Billadd3,Shipadd1,shipadd2,Shipadd3,Pincode,ContactPerson,Ph1,Ph2,Mob1,Mob2,Email,PANNumber,AadharNo,          
DLNo20,DLNo21,FSSAINo,GST.StateName [State],GSTIN,CRT.Name [Credit Term],PM.PaymentMode [Payment Mode],MTT.TaxTypeName [Tax Type],          
OSValue,RT.RatingName Rating,CASE WHEN MS.Active = 1 THEN ''YES'' else ''NO'' End Active,MUC.UserName [Created By],CONVERT(NVARCHAR,MS.CDate) [Created Date],          
MUM.UserName [Modified By],CONVERT(NVARCHAR,MS.MDate) [Modified Date],PLName [Pref Lang Name],
PLBillAdd1 [Pref Lang BillAdd1],PLBillAdd2 [Pref Lang BillAdd2],PLBillAdd3 [Pref Lang BillAdd3],
PLContactPerson [Pref Lang ContactPerson],Ident FROM tblMasterCustomerVendorHistory MS          
LEFT JOIN tblGSTStateNameandCode GST ON GST.StateID = MS.StateID          
LEFT JOIN tblMasterCreditTerm CRT ON CRT.ID = MS.CreditTermID          
LEFT JOIN tblPaymentMode PM ON PM.ID = MS.PaymentModeID          
LEFT JOIN tblMasterTaxType MTT ON MTT.TaxTypeID = MS.TaxTypeID          
LEFT JOIN tblRatings RT ON RT.ID = MS.Rating          
JOIN tblUsers MUC ON MUC.ID = MS.Cby          
LEFT JOIN tblUsers MUM ON MUM.ID = MS.Mby          
WHERE FormID = @FormID AND MS.HisCBy = @UserID and MS.ID = @ID AND CONVERT(DATE,MS.HisCDate) BETWEEN @FromDate and @ToDate          
UNION ALL          
select 2,MS.ID,Code,MS.Name,Billadd1,Billadd2,Billadd3,Shipadd1,shipadd2,Shipadd3,Pincode,ContactPerson,Ph1,Ph2,Mob1,Mob2,Email,PANNumber,AadharNo,          
DLNo20,DLNo21,FSSAINo,GST.StateName [State],GSTIN,CRT.Name [Credit Term],PM.PaymentMode [Payment Mode],MTT.TaxTypeName [Tax Type],          
OSValue,RT.RatingName Rating,CASE WHEN MS.Active = 1 THEN ''YES'' else ''NO'' End Active,MUC.UserName [Created By],CONVERT(NVARCHAR,MS.CDate) [Created Date],          
MUM.UserName [Modified By],CONVERT(NVARCHAR,MS.MDate) [Modified Date],PLName [Pref Lang Name],
PLBillAdd1 [Pref Lang BillAdd1],PLBillAdd2 [Pref Lang BillAdd2],PLBillAdd3 [Pref Lang BillAdd3],
PLContactPerson [Pref Lang ContactPerson],0          
from tblMasterVendor MS          
LEFT JOIN tblGSTStateNameandCode GST ON GST.StateID = MS.StateID          
LEFT JOIN tblMasterCreditTerm CRT ON CRT.ID = MS.CreditTermID          
LEFT JOIN tblPaymentMode PM ON PM.ID = MS.PaymentModeID          
LEFT JOIN tblMasterTaxType MTT ON MTT.TaxTypeID = MS.TaxTypeID          
LEFT JOIN tblRatings RT ON RT.ID = MS.Rating          
JOIN tblUsers MUC ON MUC.ID = MS.Cby          
LEFT JOIN tblUsers MUM ON MUM.ID = MS.Mby WHERE MS.ID = @ID) AS REC ORDER BY IDX,Ident          
ALTER TABLE #MVEND DROP COLUMN IDX,Ident          
SELECT * FROM #MVEND          
drop table #MVEND          
END          
ELSE IF(@FormID = 28)-- Product          
BEGIN          
--SaleonMRP SaleonpPern ECPonMRP ECPonpPern SPLonMRP SPLonpPern  
PRINT ''PRODUCT''          
SELECT * INTO #Mprod FROM (          
SELECT 1 IDX,MP.ID,MP.Code,MP.Name,EAN,MF.Name Mfr,MB.Name Brand,MB.Name Category,HSNCode,ProductDiscPerc,BUOM.Name BaseUom,BaseCR,PUOM.Name PurchaseUom,          
PurchaseCR,SUOM.Name SalesUom,SalesCR,RUOM.Name ReportingUom,ReportingCR,ReportingQty,PTAX.TaxName PurchaseTax,STAX.TaxName SalesTax,          
PurchasePrice,  
CASE WHEN MP.SaleonMRP = 1 THEN ''YES'' else ''NO'' End SaleonMRP,SaleonpPern,SalesPrice,  
CASE WHEN MP.ECPonMRP = 1 THEN ''YES'' else ''NO'' End ECPonMRP,ECPonpPern,ECP,  
CASE WHEN MP.SPLonMRP = 1 THEN ''YES'' else ''NO'' End SPLonMRP,SPLonpPern,SPLPrice,  
MRP,ReturnPrice,CASE WHEN MP.TrackInventory = 1 THEN ''YES'' else ''NO'' End TrackInventory,          
CASE WHEN MP.TrackBatch = 1 THEN ''YES'' else ''NO'' End TrackBatch,CASE WHEN MP.TrackSerial = 1 THEN ''YES'' else ''NO'' End TrackSerial,          
CASE WHEN MP.TrackPDK = 1 THEN ''YES'' else ''NO'' End TrackPDK,CASE WHEN MP.DateFormat = 1 THEN ''DMY'' else ''MY'' End DateFormat,      
CASE WHEN MP.BarcodeEnable = 1 THEN ''YES'' else ''NO'' End BarcodeYN,BARUOM.Name BarcodeUom,          
PTY.PriceType BarcodePriceD,MV.Name Vendor,MOH,MOQ,Weborder,Remarks,ML.Name Location,  
CASE WHEN MP.Active = 1 THEN ''YES'' else ''NO'' End Active,MUC.UserName [Created By],CONVERT(NVARCHAR,MP.CDate) [Created Date],          
MUM.UserName [Modified By],CONVERT(NVARCHAR,MP.MDate) [Modified Date],MP.PLName [Pref Lang Name],IdentID          
FROM tblMasterProductHistory MP          
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID          
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID          
JOIN tblMasterCategory MC ON MC.ID = MP.CategoryID          
JOIN tblMasterUOM BUOM ON BUOM.ID = MP.BaseUomID          
JOIN tblMasterUOM PUOM ON PUOM.ID = MP.PurchaseUomID          
JOIN tblMasterUOM SUOM ON SUOM.ID = MP.SalesUomID          
JOIN tblMasterUOM RUOM ON RUOM.ID = MP.ReportingUomID          
JOIN tblMasterTax PTAX ON PTAX.TaxID = MP.PurchaseTaxID          
JOIN tblMasterTax STAX ON STAX.TaxID = MP.SalesTaxID          
LEFT JOIN tblMasterUOM BARUOM ON BARUOM.ID = MP.BarcodeUomID          
LEFT JOIN tblPriceType PTY ON PTY.ID = MP.BarcodePriceID          
LEFT JOIN tblMasterVendor MV ON MV.ID = MP.VendorID          
LEFT JOIN tblMasterLocation ML ON ML.ID = MP.LocationID          
JOIN tblUsers MUC ON MUC.ID = MP.Cby          
LEFT JOIN tblUsers MUM ON MUM.ID = MP.Mby          
WHERE FormID = @FormID AND MP.HisCBy = @UserID and MP.ID = @ID AND CONVERT(DATE,MP.HisCDate) BETWEEN @FromDate and @ToDate          
UNION ALL          
SELECT 2 IDX,MP.ID,MP.Code,MP.Name,EAN,MF.Name Mfr,MB.Name Brand,MB.Name Category,HSNCode,ProductDiscPerc,BUOM.Name BaseUom,BaseCR,PUOM.Name PurchaseUom,          
PurchaseCR,SUOM.Name SalesUom,SalesCR,RUOM.Name ReportingUom,ReportingCR,ReportingQty,PTAX.TaxName PurchaseTax,STAX.TaxName SalesTax,          
PurchasePrice,CASE WHEN MP.SaleonMRP = 1 THEN ''YES'' else ''NO'' End SaleonMRP,SaleonpPern,SalesPrice,  
CASE WHEN MP.ECPonMRP = 1 THEN ''YES'' else ''NO'' End ECPonMRP,ECPonpPern,ECP,  
CASE WHEN MP.SPLonMRP = 1 THEN ''YES'' else ''NO'' End SPLonMRP,SPLonpPern,SPLPrice,MRP,ReturnPrice,CASE WHEN MP.TrackInventory = 1 THEN ''YES'' else ''NO'' End TrackInventory,          
CASE WHEN MP.TrackBatch = 1 THEN ''YES'' else ''NO'' End TrackBatch,CASE WHEN MP.TrackSerial = 1 THEN ''YES'' else ''NO'' End TrackSerial,          
CASE WHEN MP.TrackPDK = 1 THEN ''YES'' else ''NO'' End TrackPDK,CASE WHEN MP.DateFormat = 1 THEN ''DMY'' else ''MY'' End DateFormat,      
CASE WHEN MP.BarcodeEnable = 1 THEN ''YES'' else ''NO'' End BarcodeYN,BARUOM.Name BarcodeUom,          
PTY.PriceType BarcodePriceD,MV.Name Vendor,MOH,MOQ,Weborder,Remarks,ML.Name Location,CASE WHEN MP.Active = 1 THEN ''YES'' else ''NO'' End Active,MUC.UserName [Created By],CONVERT(NVARCHAR,MP.CDate) [Created Date],          
MUM.UserName [Modified By],CONVERT(NVARCHAR,MP.MDate) [Modified Date],MP.PLName [Pref Lang Name],0 IdentID          
FROM tblMasterProduct MP          
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID          
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID          
JOIN tblMasterCategory MC ON MC.ID = MP.CategoryID          
JOIN tblMasterUOM BUOM ON BUOM.ID = MP.BaseUomID          
JOIN tblMasterUOM PUOM ON PUOM.ID = MP.PurchaseUomID          
JOIN tblMasterUOM SUOM ON SUOM.ID = MP.SalesUomID          
JOIN tblMasterUOM RUOM ON RUOM.ID = MP.ReportingUomID          
JOIN tblMasterTax PTAX ON PTAX.TaxID = MP.PurchaseTaxID          
JOIN tblMasterTax STAX ON STAX.TaxID = MP.SalesTaxID          
LEFT JOIN tblMasterUOM BARUOM ON BARUOM.ID = MP.BarcodeUomID          
LEFT JOIN tblPriceType PTY ON PTY.ID = MP.BarcodePriceID          
LEFT JOIN tblMasterVendor MV ON MV.ID = MP.VendorID          
LEFT JOIN tblMasterLocation ML ON ML.ID = MP.LocationID          
JOIN tblUsers MUC ON MUC.ID = MP.Cby          
LEFT JOIN tblUsers MUM ON MUM.ID = MP.Mby WHERE MP.ID = @ID          
) AS REC ORDER BY IDX,IdentID          
ALTER TABLE #Mprod DROP COLUMN IDX,IdentID          
SELECT * FROM #Mprod          
drop table #Mprod          
END          
ELSE IF(@FormID = 42)-- Product PRICE CHANGE          
BEGIN          
SELECT InventoryId,BatchNumber Batch,PKDDate PKD,ExpiryDate Expiry,dbo.fnGetRoundedValue(PurchasePrice) [Purchase Price],dbo.fnGetRoundedValue(SalesPrice) [Sales Price],      
dbo.fnGetRoundedValue(ECP) ECP,dbo.fnGetRoundedValue(SPLPrice) [SPL Price],dbo.fnGetRoundedValue(ReturnPrice) [Return Price],      
dbo.fnGetRoundedValue(MRPONPrice) [MRP On] FROM (      
SELECT 1 IDX,InventoryId,BatchNumber,PKDDate,ExpiryDate,PurchasePrice,SalesPrice,ECP,SPLPrice,ReturnPrice,MRPONPrice       
FROM tblPriceChangeHistory WHERE InventoryId = @ID      
UNION ALL      
SELECT 2,InventoryId,BatchNumber,PKDDate,ExpiryDate,PurchasePrice,SalesPrice,ECP,SPLPrice,ReturnPrice,MRPONPrice       
FROM tblProductInventory WHERE InventoryId = @ID      
) AS REC      
ORDER BY IDX,InventoryId      
END      
END          
END',
N'[05] nocount';
GO
/****** uspGetOpeningBalance ******/
EXEC #Apply07 N'dbo.uspGetOpeningBalance', 0xEB83940E0210129156FE2812A128890AA50B3792BC69F6B345F8D9969DA9EDD6, NULL, NULL, 0x4877F348617C7C931C71F63715AFC019BE94B5A2D024A63D46A3D228D62F6A0E, 0x5BFE3432CB998BE8F50E39AAA39AA46E21A806AC0542883B1FA90ABADFD859C5, NULL,
N'ALTER PROC [dbo].[uspGetOpeningBalance]     
@BranchID INT,
@AccID INT,
@Date DATE,
@Amount DECIMAL (25,6) OUTPUT    
AS    
SET NOCOUNT ON;
BEGIN    
DECLARE @OpeningAmt DECIMAL (25,6),@FAType INT,@Docseriesid int
SELECT @Docseriesid = ID FROM tblYearwiseDocumentSeries WHERE @Date BETWEEN FromDate AND ToDate and BranchID = @BranchID
SELECT @OpeningAmt=OpeningBalance,@FAType=FAType FROM tblFAAccOpening WHERE FAID = @AccID and DocSeriesID = @Docseriesid and
BranchID = @BranchID
 IF ISNULL(@FaType,0)=2                  
 BEGIN                  
  SET @Amount=(-1*@OpeningAmt)               
 END                  
 ELSE                  
 BEGIN                  
  SET @Amount=@OpeningAmt                 
 END    
END',
N'[export] nocount';
GO
/****** uspGetOpeningStockAmt ******/
EXEC #Apply07 N'dbo.uspGetOpeningStockAmt', 0x1B8D01608AC3E26BC67AA516F6F9449AC2D9D81CA64B4FF4EB34DA370AB090EE, NULL, NULL, 0xF5777D4B92811825DAA510FEA615A75D7800DB422B73B450C3A312398466213C, 0x7A3948A7FC1E3CB1DC2A522110DD0E946F31F9D95C0DE21FBE9CA2CE08E4505A, NULL,
N'ALTER PROC [dbo].[uspGetOpeningStockAmt]
@BranchID INT,
@FromDate DATETIME,
@ClosingAmt DECIMAL (25,6) OUTPUT
AS
SET NOCOUNT ON;
BEGIN
SET DATEFORMAT DMY
DECLARE @TempDate DATETIME
SELECT @TempDate=DATEADD(DAY, -1, @FromDate)
SELECT @ClosingAmt=[dbo].[fnGetRoundedValue](SUM(ISNULL(SaleStockValue + DmgStockValue,0))) FROM
tblClosingStock WHERE ClsDate=@TempDate AND BranchID = (CASE WHEN @BranchID > 0 THEN @BranchID ELSE BranchID END)
END',
N'[export] nocount';
GO
/****** uspGetPendingBill ******/
EXEC #Apply07 N'dbo.uspGetPendingBill', 0xBAD827005F2FAFED380C95E0ECFDAB173AC8C78A6C3C52F71E282342A6DFCE60, NULL, NULL, 0x9251358F835D62F9DE630CE4D197544A00A88251626F734C1D771F05B647901F, 0x0A802395DB5EE220BAB2A94CE5F7598018A44EB8A5DE0949049BFEE302C278CD, NULL,
N'--uspGetPendingBill 3,''2025-03-20'',114,4        
--select * from tblTranPaymentheader order by 1 desc      
ALTER PROCEDURE [dbo].[uspGetPendingBill]        
@VendID INT,@DocDate Date,@nCollorPayID INT=NULL,@nMode INT=NULL,@BranchID int =0
AS        
SET NOCOUNT ON;
BEGIN        
DECLARE @AccID INT      
SET DATEFORMAT dmy      
SET @AccID=(SELECT FAID FROM tblMasterVendor WHERE id=@VendID)      
IF ISNULL(@nMode,0)!=4        
BEGIn        
IF ISNULL(@nCollorPayID,0) > 0        
BEGIN        
SELECT PAY.DocID,CONVERT(NVARCHAR,PAY.Tran_Date,103) AS Tran_Date,PAY.RefNo DocRef,PAY.TranName TransName,PAY.TotalNetAmt NetAmt,PAY.Balance,        
PAY.BillID ID,PAY.AccountID FAID,PAY.DocPrefix,PAY.DocValue,PAY.UDFDocId,Ageing      
FROM        
(        
SELECT Bill.DocID,        
Bill.Date as Tran_Date,Bill.RefNo,Doc.TransName TranName,Bill.NetAmt TotalNetAmt,Bill.Balance,Bill.ID BillID,        
Vendor.FAID AccountID,Bill.TransID DocPrefix,Bill.DocValue,Bill.UDFDocId,DATEDIFF(DD,Bill.Date,GETDATE()) Ageing        
FROM tblTranspurchaseheader AS Bill        
JOIN tblMasterVendor AS Vendor ON Bill.VendorID=Vendor.ID        
JOIN tblDocumentSeries AS Doc ON Bill.TransID=Doc.TransID        
WHERE Bill.VendorID=@VendID AND Bill.TransID=1 and BranchID = @BranchID AND Date <=@DocDate AND (Bill.[Status]=1 OR Bill.[Status]=3)        
UNION ALL      
SELECT ND.DocID,ND.DocDate,ND.RefNo,Doc.TransName,NetAmount,Balance,ND.ID,PartyID,ND.TransID,ND.DocValue,UDFDocId    
,DATEDIFF(DD,ND.DocDate,GETDATE()) Ageing FROM tblTranPRVoucher ND        
JOIN tblDocumentSeries AS Doc ON Doc.TransID=ND.TransID        
JOIN tblMasterVendor AS Cust ON Cust.id = ND.PartyId        
WHERE ND.TransID = 6 AND ND.Status IN (1,3) AND ND.Balance > 0 and BranchID = @BranchID AND DocDate <=@DocDate AND Cust.id = @VendID         
UNION        
SELECT ND.DocID,ND.DocDate,ND.RefNo,Doc.TransName,NoteValue,Balance,ND.ID,PartyID,ND.TransID,ND.DocValue,UDFDocId    
,DATEDIFF(DD,ND.DocDate,GETDATE()) Ageing FROM tblNoteDetails ND        
JOIN tblDocumentSeries AS Doc ON Doc.TransID=ND.TransID        
JOIN tblMasterVendor AS Cust ON Cust.id = ND.PartyId        
WHERE ND.TransID = 4 AND ND.Status IN (1,3) AND ND.Balance > 0 and BranchID = @BranchID AND DocDate <=@DocDate AND Cust.id = @VendID        
) PAY        
ORDER BY PAY.Tran_Date ASC,PAY.DocID ASC        
END        
ELSE        
BEGIN        
SELECT PAY.DocID,CONVERT(NVARCHAR,PAY.Tran_Date,103) AS Tran_Date,PAY.RefNo DocRef,PAY.TranName TransName,PAY.TotalNetAmt NetAmt,PAY.Balance,        
PAY.BillID ID,PAY.AccountID FAID,PAY.DocPrefix,PAY.DocValue,PAY.UDFDocId,Ageing        
FROM        
(        
SELECT Bill.DocID,        
Bill.Date as Tran_Date,Bill.RefNo,Doc.TransName TranName,Bill.NetAmt TotalNetAmt,Bill.Balance,Bill.ID BillID,        
Vendor.FAID AccountID,Bill.TransID DocPrefix,Bill.DocValue,Bill.UDFDocId,DATEDIFF(DD,Bill.Date,GETDATE()) Ageing        
FROM tblTransPurchaseHeader AS Bill        
JOIN tblMasterVendor AS Vendor ON Bill.VendorID=Vendor.ID        
JOIN tblDocumentSeries AS Doc ON Bill.TransID=Doc.TransID        
Where Bill.VendorID=@VendID AND Bill.TransID=1 and BranchID = @BranchID AND Bill.Date <=@DocDate AND (Bill.[Status]=1 OR Bill.[Status]=3)        
AND Balance > 0.00        
UNION ALL      
SELECT ND.DocID,ND.DocDate,ND.RefNo,Doc.TransName,NetAmount,Balance,ND.ID Ident,PartyID,ND.TransID DocPrefix,ND.DocValue,UDFDocId    
,DATEDIFF(DD,ND.DocDate,GETDATE()) Ageing FROM tblTranPRVoucher ND        
JOIN tblDocumentSeries AS Doc ON Doc.TransID=ND.TransID        
JOIN tblMasterVendor AS Cust ON Cust.FAID = ND.PartyId        
WHERE ND.TransID = 6 AND ND.Status IN (1,3,5) and BranchID = @BranchID AND ND.Balance > 0 AND DocDate <=@DocDate AND Cust.ID = @VendID    
UNION        
SELECT ND.DocID,ND.DocDate,ND.RefNo,Doc.TransName,NoteValue,Balance,ND.ID Ident,PartyID,ND.TransID DocPrefix,ND.DocValue,UDFDocId    
,DATEDIFF(DD,ND.DocDate,GETDATE()) Ageing FROM tblNoteDetails ND        
JOIN tblDocumentSeries AS Doc ON Doc.TransID=ND.TransID        
JOIN tblMasterVendor AS Cust ON Cust.FAID = ND.PartyId        
WHERE ND.TransID = 4 AND ND.Status IN (1,3,5) and BranchID = @BranchID AND ND.Balance > 0 AND DocDate <=@DocDate AND Cust.ID = @VendID        
) PAY        
ORDER BY PAY.Tran_Date ASC,DocPrefix--,PAY.DocID ASC        
END        
END        
ELSE        
BEGIN        
select DocID,CONVERT(NVARCHAR,Tran_Date,103) Tran_Date,RefNo DocRef,TranName TransName,TotalNetAmt NetAmt,Balance + DiscAmt + FullyAdjAmt Balance,BillID ID,AccountID FAID,DocPrefix,        
DocValue,ColValue,AdjAmt,DiscAmt,FullyAdj,FullyAdjAmt,TotalAmtAdj,UDFDocId,[CURR BAL],Ageing from (        
SELECT DocID,Tran_Date,RefNo,TranName,NetAmt TotalNetAmt,Balance + SUM(ColValue) Balance,billid,AccountID,TransID DocPrefix,DocValue,SUM(ColValue)ColValue,        
SUM(AdjAmt) AdjAmt,SUM(DiscAmt) DiscAmt,SUM(FullyAdj) FullyAdj,SUM(FullyAdjAmt) FullyAdjAmt,SUM(TotalAmtAdj) TotalAmtAdj,UDFDocId,    
Balance "CURR BAL",Ageing    
FROM (--,        
SELECT Sales.DocId AS DocID,Sales.Date as Tran_Date,Sales.RefNo,''Purchase Bill'' TranName,        
Sales.NetAmt,(Sales.Balance) AS Balance,        
Sales.ID BillID,Customer.FAID AccountID,Sales.TransID ,Sales.DocValue,0 ColValue,0 AdjAmt,0 DiscAmt,0 FullyAdj,0 FullyAdjAmt,0 TotalAmtAdj,    
Sales.UDFDocId,DATEDIFF(DD,Sales.Date,GETDATE()) Ageing    
FROM tblTransPurchaseHeader AS Sales      
LEFT JOIN tblMasterVendor AS Customer ON Sales.VendorID=Customer.ID        
JOIN tblDocumentSeries AS Doc ON Sales.TransID=Doc.TransID        
Where Sales.VendorID = @VendID AND Sales.TransID= 1 AND Sales.Date <=@DocDate AND Sales.[Status] IN (1,3)        
UNION        
SELECT SH.DocId,SH.Date,SH.RefNo,''Purchase Bill'' TranName,NetAmt,SH.Balance,CD.DocID,Customer.FAID AccountID,SH.TransID DocPrefix,SH.DocValue,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.BillPYValue ELSE 0 END) AS ColValue,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.AdjAmt ELSE 0 END) AS AdjAmt,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.DiscAmt ELSE 0 END) AS DiscAmt,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.FullyAdj ELSE 0 END) AS FullyAdj,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.FullyAdjAmt ELSE 0 END) AS FullyAdjAmt,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.TotalAmtAdj ELSE 0 END) AS TotalAmtAdj,SH.UDFDocId,DATEDIFF(DD,SH.Date,GETDATE()) Ageing        
FROM tblTranPaymentDetail AS CD        
--tblTranPaymentDetail ORDER BY 1 DESC        
left join tblTranPaymentHeader ch on ch.PYID = CD.PYID        
JOIN tblTransPurchaseHeader SH ON SH.ID = CD.DocID AND SH.TransID = CD.DocPrefix        
JOIN tblMasterVendor AS Customer ON SH.VendorID=Customer.id        
WHERE CH.Status IN (1,3,5) and CD.PYID = @nCollorPayID AND SH.TransID = 1) AS A        
GROUP BY DocID,Tran_Date,TransID,TranName,NetAmt,Balance,BillID,AccountID,TransID,DocValue,UDFDocId,RefNo,Ageing    
UNION ALL -- Credit Note        
SELECT DocID,Tran_Date,ReferNo,TranName,NetAmount,Balance + SUM(ColValue) Balance,PRVID,AccountID,DocPrefix,DocValue,SUM(ColValue)ColValue,        
SUM(AdjAmt) AdjAmt,SUM(DiscAmt) DiscAmt,SUM(FullyAdj) FullyAdj,SUM(FullyAdjAmt) FullyAdjAmt,SUM(TotalAmtAdj) TotalAmtAdj,UDFDocId,    
Balance "CURR BAL",Ageing FROM (        
SELECT PV.DocID AS DocID,PV.DocDate as Tran_Date,PV.RefNo ReferNo,''Credit Note'' TranName,        
PV.NoteValue NetAmount,(PV.Balance) AS Balance,        
PV.ID PRVID,PV.PartyID AccountID,PV.TransID DocPrefix,PV.DocValue,0 ColValue,0 AdjAmt,0 DiscAmt,0 FullyAdj,0 FullyAdjAmt,0 TotalAmtAdj,    
PV.UDFDocId,DATEDIFF(DD,PV.DocDate,GETDATE()) Ageing     
FROM tblNoteDetails AS PV        
JOIN tblMasterVendor AS Customer ON Customer.FAID = PV.PartyID        
Where Customer.ID = @VendID AND PV.TransID= 4 AND DocDate <=@DocDate AND PV.[Status] IN (1,3)        
UNION        
SELECT SH.DocId, DocDate ,SH.RefNo,''Credit Note'' TranName,NoteValue,SH.Balance,CD.DocID,SH.PartyID AccountID,SH.TransID DocPrefix,SH.DocValue,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.BillPYValue ELSE 0 END) AS ColValue,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.AdjAmt ELSE 0 END) AS AdjAmt,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.DiscAmt ELSE 0 END) AS DiscAmt,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.FullyAdj ELSE 0 END) AS FullyAdj,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.FullyAdjAmt ELSE 0 END) AS FullyAdjAmt,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.TotalAmtAdj ELSE 0 END) AS TotalAmtAdj,SH.UDFDocId,DATEDIFF(DD,SH.DocDate,GETDATE()) Ageing         
FROM tblTranPaymentDetail AS CD        
left join tblTranPaymentHeader ch on ch.PYID = CD.PYID        
LEFT JOIN tblNoteDetails SH ON SH.ID = CD.DocID AND SH.TransID = CD.DocPrefix        
LEFT JOIN tblMasterVendor AS Customer ON SH.PartyID=Customer.FAID        
WHERE CH.Status IN (1,3,5) and CD.PYID = @nCollorPayID AND SH.TransID = 4) AS DN        
GROUP BY DocID,Tran_Date,DocPrefix,TranName,NetAmount,Balance,PRVID,AccountID,DocPrefix,DocValue,UDFDocId,ReferNo,Ageing        
--UNION ALL    
--SELECT DocId, Convert(varchar,DocDate,103) as DocDate,NoteValue,ID Ident,DocPrefix,DocValue,PartyId,Balance + SUM(ADJAMT) Balance,  
--TranName TransName,DocRefNo,SUM(ColValue) ColValue,UDFDocId,Ageing FROM (      
--SELECT DocId,DocDate,PRV.NetAmount NoteValue,PRV.ID,TransID DocPrefix,DocValue,PartyId,Balance,0 ADJAMT,''Payable Voucher'' TranName,      
--RefNo DocRefNo,0 ColValue,UDFDocId,DATEDIFF(DD,PRV.DocDate,GETDATE()) Ageing FROM tblTranPRVoucher PRV    
--WHERE PartyId=@AccId AND PRV.TransID= 6 AND PRV.Status IN (1,3) AND DocDate<=@DocDate      
--union      
--SELECT tblNoteDetails.DocId AS DocId, DocDate,NetAmount NoteValue,      
--tblNoteDetails.ID,tblNoteDetails.RefNo AS DocPrefix ,tblNoteDetails.DocValue AS DocValue ,tblNoteDetails.PartyId,      
--(CASE WHEN CD.PYID = @nCollorPayID THEN (tblNoteDetails.Balance) ELSE tblNoteDetails.Balance END) AS Balance, CD.TotalAmtAdj TotalAmtAdj,      
--''Payable Voucher'' TranName,RefNo,      
--(CASE WHEN CD.PYID = @nCollorPayID THEN CD.BillPYValue ELSE 0 END) AS ColValue,tblNoteDetails.UDFDocId,  
--DATEDIFF(DD,tblNoteDetails.DocDate,GETDATE()) Ageing      
--FROM tblTranPaymentDetail AS CD      
--JOIN tblTranPaymentHeader CH ON CH.PYID = CD.PYID      
--LEFT JOIN tblTranPRVoucher tblNoteDetails ON CD.DocID = tblNoteDetails.ID AND tblNoteDetails.TransID = CD.DocPrefix      
--WHERE PartyId=@AccId AND tblNoteDetails.TransID= 6 AND CH.Status IN (1,3,5) AND DocDate<=@DocDate      
--and CD.PYID = @nCollorPayID      
--) AS PV    
--GROUP BY DocId,DocDate,NoteValue,ID,DocPrefix,DocValue,PartyId,Balance,UDFDocId,TranName,DocRefNo,Ageing  
UNION ALL -- Credit Note        
SELECT DocID,Tran_Date,ReferNo,TranName,NetAmount,Balance + SUM(ColValue) Balance,PRVID,AccountID,DocPrefix,DocValue,SUM(ColValue)ColValue,        
SUM(AdjAmt) AdjAmt,SUM(DiscAmt) DiscAmt,SUM(FullyAdj) FullyAdj,SUM(FullyAdjAmt) FullyAdjAmt,SUM(TotalAmtAdj) TotalAmtAdj,UDFDocId,    
Balance "CURR BAL",Ageing FROM (        
SELECT PV.DocID AS DocID,PV.DocDate as Tran_Date,PV.RefNo ReferNo,''Payable Voucher'' TranName,        
PV.NetAmount NetAmount,(PV.Balance) AS Balance,        
PV.ID PRVID,PV.PartyID AccountID,PV.TransID DocPrefix,PV.DocValue,0 ColValue,0 AdjAmt,0 DiscAmt,0 FullyAdj,0 FullyAdjAmt,0 TotalAmtAdj,    
PV.UDFDocId,DATEDIFF(DD,PV.DocDate,GETDATE()) Ageing     
FROM tblTranPRVoucher AS PV        
JOIN tblMasterVendor AS Customer ON Customer.FAID = PV.PartyID        
Where Customer.ID = @VendID AND PV.TransID= 6 AND DocDate <=@DocDate AND PV.[Status] IN (1,3)        
UNION        
SELECT SH.DocId, DocDate ,SH.RefNo,''Payable Voucher'' TranName,NetAmount,SH.Balance,CD.DocID,SH.PartyID AccountID,SH.TransID DocPrefix,SH.DocValue,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.BillPYValue ELSE 0 END) AS ColValue,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.AdjAmt ELSE 0 END) AS AdjAmt,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.DiscAmt ELSE 0 END) AS DiscAmt,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.FullyAdj ELSE 0 END) AS FullyAdj,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.FullyAdjAmt ELSE 0 END) AS FullyAdjAmt,        
(CASE WHEN CD.PYID = @nCollorPayID THEN CD.TotalAmtAdj ELSE 0 END) AS TotalAmtAdj,SH.UDFDocId,DATEDIFF(DD,SH.DocDate,GETDATE()) Ageing     
FROM tblTranPaymentDetail AS CD        
left join tblTranPaymentHeader ch on ch.PYID = CD.PYID        
LEFT JOIN tblTranPRVoucher SH ON SH.ID = CD.DocID AND SH.TransID = CD.DocPrefix        
LEFT JOIN tblMasterVendor AS Customer ON SH.PartyID=Customer.FAID        
WHERE CH.Status IN (1,3,5) and CD.PYID = @nCollorPayID AND SH.TransID = 6) AS DN        
GROUP BY DocID,Tran_Date,DocPrefix,TranName,NetAmount,Balance,PRVID,AccountID,DocPrefix,DocValue,UDFDocId,ReferNo,Ageing     
) as Main        
WHERE Balance > 0        
ORDER BY CONVERT(date,Tran_Date),DocPrefix        
END        
END',
N'[export] nocount';
GO
/****** uspGetPendingInv ******/
EXEC #Apply07 N'dbo.uspGetPendingInv', 0x02AD4D62287EA8E4488DD848C383FBC6796570270FFF98C3D8EBC93BF8314568, NULL, NULL, 0x5A36673AD40D3678FE2D6BA5743B412252A2710F117ABCFFE2D0318097026613, 0x74BDC7C85B56AF278BC03BA2A1E4DAEF51D190384BC02B8E6CC83223C8B24629, NULL,
N'--uspGetPendingInv 239,''2026-10-12'',0,1,1      
ALTER PROCEDURE [dbo].[uspGetPendingInv]      
@CustId INT = 18,@DocDate Date = ''2025-12-02'',@nCollorPayID INT=0,@nMode INT = 1,@BranchID int  = 0    
AS      
SET NOCOUNT ON;
BEGIN      
SET DATEFORMAT dmy;      
IF ISNULL(@nMode,0)!=4      
BEGIn      
IF ISNULL(@nCollorPayID,0) > 0      
BEGIN      
SELECT CollDocs.DocID,CONVERT(NVARCHAR,CollDocs.Tran_Date,103) AS Tran_Date,CollDocs.DocRef,CollDocs.TransName,CollDocs.NetAmt,CollDocs.Balance,      
CollDocs.ID,CollDocs.FAID,CollDocs.DocPrefix,CollDocs.DocValue,CollDocs.UDFDocId,Ageing      
FROM      
(      
SELECT Sales.DocId AS DocID,      
--Doc.DocPrefix+CONVERT(nvarchar(50),Sales.DocValue) AS DocID,      
Sales.InvDate as Tran_Date,Sales.DocRef,Doc.TransName,Sales.NetAmt,Sales.Balance,Sales.ID,Customer.FAID,      
Sales.DocPrefix,Sales.DocValue,UDFDocId,DATEDIFF(DD,Sales.InvDate,GETDATE()) Ageing      
FROM tblTranSalesHeader AS Sales      
JOIN tblMasterCustomer AS Customer ON Sales.CustId=Customer.ID      
JOIN tblDocumentSeries AS Doc ON Sales.DocPrefix=Doc.TransID      
WHERE Sales.CustId=@CustId and BranchID = @BranchID AND Sales.DocPrefix=15 AND InvDate <=@DocDate AND Sales.[Status] IN (1,3) AND Balance>0.00      
UNION      
SELECT PV.DocID,PV.DocDate,PV.RefNo,Doc.TransName,NetAmount,Balance,PV.ID,PartyID,PV.TransID,PV.DocValue,PV.UDFDocId,      
DATEDIFF(DD,PV.DocDate,GETDATE()) Ageing      
FROM tblTranPRVoucher AS PV      
JOIN tblDocumentSeries AS Doc ON PV.TransID=Doc.TransID      
JOIN tblMasterCustomer AS Cust ON Cust.FAID = PV.PartyID      
WHERE PV.TransID = 7 AND PV.Status IN (1,3) AND PV.DocDate <= @DocDate and BranchID = @BranchID      
AND Cust.ID = @CustId      
UNION      
SELECT ND.DocID,ND.DocDate,ND.RefNo,Doc.TransName,NoteValue,Balance,ND.ID,PartyID,ND.TransID,ND.DocValue,UDFDocId      
,DATEDIFF(DD,ND.DocDate,GETDATE()) Ageing FROM tblNoteDetails ND      
JOIN tblDocumentSeries AS Doc ON Doc.TransID=ND.TransID      
JOIN tblMasterCustomer AS Cust ON Cust.FAID = ND.PartyId      
WHERE ND.TransID = 5 AND ND.Status IN (1,3) AND ND.Balance > 0 AND DocDate <=@DocDate AND Cust.ID = @CustId and BranchID = @BranchID      
) AS CollDocs      
ORDER BY CollDocs.Tran_Date,DocPrefix      
END      
ELSE      
BEGIN      
SELECT CollDocs.DocID,CONVERT(NVARCHAR,CollDocs.Tran_Date,103) AS Tran_Date,CollDocs.DocRef,CollDocs.TransName,CollDocs.NetAmt,CollDocs.Balance,      
CollDocs.ID,CollDocs.FAID,CollDocs.DocPrefix,CollDocs.DocValue,CollDocs.UDFDocId,Ageing      
FROM      
(      
SELECT Sales.DocId AS DocID,      
--Doc.DocPrefix+CONVERT(nvarchar(50),Sales.DocValue) AS DocID,      
Sales.InvDate as Tran_Date,Sales.DocRef,Doc.TransName,Sales.NetAmt,Sales.Balance,Sales.ID,Customer.FAID,      
Sales.DocPrefix,Sales.DocValue,UDFDocId,DATEDIFF(DD,Sales.InvDate,GETDATE()) Ageing      
FROM tblTranSalesHeader AS Sales      
JOIN tblMasterCustomer AS Customer ON Sales.CustId=Customer.ID      
JOIN tblDocumentSeries AS Doc ON Sales.DocPrefix=Doc.TransID      
WHERE Sales.CustId=@CustId and BranchID = @BranchID AND Sales.DocPrefix=15 AND InvDate <=@DocDate AND Sales.[Status] IN (1,3) AND Balance>0.00      
UNION      
SELECT PV.DocID,PV.DocDate,PV.RefNo,Doc.TransName,NetAmount,Balance,PV.ID,PartyID,PV.TransID,PV.DocValue,UDFDocId      
,DATEDIFF(DD,PV.DocDate,GETDATE()) Ageing      
FROM tblTranPRVoucher AS PV      
JOIN tblDocumentSeries AS Doc ON PV.TransID=Doc.TransID      
JOIN tblMasterCustomer AS Cust ON Cust.FAID = PV.PartyID      
WHERE PV.TransID = 7 and BranchID = @BranchID AND PV.Status IN (1,3) AND PV.Balance > 0 AND PV.DocDate <= @DocDate      
AND Cust.ID = @CustId      
UNION      
SELECT ND.DocID,ND.DocDate,ND.RefNo,Doc.TransName,NoteValue,Balance,ND.ID,PartyID,ND.TransID,ND.DocValue,UDFDocId      
,DATEDIFF(DD,ND.DocDate,GETDATE()) Ageing FROM tblNoteDetails ND      
JOIN tblDocumentSeries AS Doc ON Doc.TransID=ND.TransID      
JOIN tblMasterCustomer AS Cust ON Cust.FAID = ND.PartyId      
WHERE ND.TransID = 5 and BranchID = @BranchID AND ND.Status IN (1,3,5) AND ND.Balance > 0 AND DocDate <=@DocDate AND Cust.ID = @CustId      
) AS CollDocs      
ORDER BY CollDocs.Tran_Date,DocPrefix      
END      
END      
ELSE      
BEGIN      
SELECT DocID,CONVERT(NVARCHAR,Tran_Date,103) Tran_Date,DocRef,TransName,NetAmt,Balance + DiscAmt + FullyAdjAmt Balance,ID,FAID,DocPrefix,DocValue,ColValue,      
AdjAmt,DiscAmt,FullyAdj,FullyAdjAmt,TotalAmtAdj,UDFDocId,[CURR BAL],Ageing FROM      
(      
SELECT DocID,Tran_Date,DocRef,TransName,NetAmt,Balance + SUM(ColValue) Balance,ID,FAID,DocPrefix,DocValue,SUM(ColValue)ColValue,      
SUM(AdjAmt) AdjAmt,SUM(DiscAmt) DiscAmt,SUM(FullyAdj) FullyAdj,SUM(FullyAdjAmt) FullyAdjAmt,SUM(TotalAmtAdj) TotalAmtAdj,UDFDocId,      
Balance "CURR BAL",Ageing FROM      
(      
SELECT Sales.DocId AS DocID,CONVERT(NVARCHAR,Sales.InvDate,103) as Tran_Date,Sales.DocRef,''Invoice'' TransName,      
Sales.NetAmt,(Sales.Balance) AS Balance,      
Sales.ID,Customer.FAID,Sales.DocPrefix ,Sales.DocValue,0 ColValue,0 AdjAmt,0 DiscAmt,0 FullyAdj,0 FullyAdjAmt,0 TotalAmtAdj,Sales.UDFDocId      
,DATEDIFF(DD,Sales.InvDate,GETDATE()) Ageing      
FROM tblTranSalesHeader AS Sales      
JOIN tblMasterCustomer AS Customer ON Sales.CustId=Customer.ID      
JOIN tblDocumentSeries AS Doc ON Sales.DocPrefix=Doc.TransID      
Where Sales.CustId=@CustId AND Sales.DocPrefix=15 AND InvDate <=@DocDate AND Sales.[Status] IN (1,3)      
UNION      
SELECT SH.DocId,CONVERT(NVARCHAR,InvDate,103) InvDate,SH.DocRef,''Invoice'' TransName,NetAmt,SH.Balance Balance,CD.DocID,Customer.FAID,SH.DocPrefix,SH.DocValue,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.ColValue ELSE 0 END) AS ColValue,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.AdjAmt ELSE 0 END) AS AdjAmt,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.DiscAmt ELSE 0 END) AS DiscAmt,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.FullyAdj ELSE 0 END) AS FullyAdj,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.FullyAdjAmt ELSE 0 END) AS FullyAdjAmt,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.TotalAmtAdj ELSE 0 END) AS TotalAmtAdj,SH.UDFDocId,DATEDIFF(DD,SH.InvDate,GETDATE()) Ageing      
FROM tblTranCollectionDetail AS CD      
left join tblTranCollectionHeader ch on ch.ColID = CD.ColID      
JOIN tblTranSalesHeader SH ON SH.ID = CD.DocID AND SH.DocPrefix = CD.DocPrefix      
JOIN tblMasterCustomer AS Customer ON SH.CustId=Customer.ID      
WHERE CH.Status IN (1,3,5) and CD.ColID = @nCollorPayID AND SH.DocPrefix = 15) AS A      
GROUP BY DocID,Tran_Date,DocPrefix,TransName,NetAmt,Balance,ID,FAID,DocPrefix,DocValue,UDFDocId,DocRef,Ageing      
UNION ALL      
SELECT DocID,Tran_Date,RefNo,TransName,NetAmount,Balance + SUM(ColValue) Balance,PRVID,FAID,DocPrefix,DocValue,SUM(ColValue)ColValue,      
SUM(AdjAmt) AdjAmt,SUM(DiscAmt) DiscAmt,SUM(FullyAdj) FullyAdj,SUM(FullyAdjAmt) FullyAdjAmt,SUM(TotalAmtAdj) TotalAmtAdj,UDFDocId,      
Balance "CURR BAL",Ageing FROM      
(      
SELECT PV.DocID AS DocID,PV.DocDate as Tran_Date,PV.RefNo,''Receivable Voucher'' TransName,      
PV.NetAmount,(PV.Balance) AS Balance,      
PV.ID PRVID,PV.PartyID FAID,PV.TransID DocPrefix,PV.DocValue,0 ColValue,0 AdjAmt,0 DiscAmt,0 FullyAdj,0 FullyAdjAmt,0 TotalAmtAdj,PV.UDFDocId      
,DATEDIFF(DD,PV.DocDate,GETDATE()) Ageing      
FROM tblTranPRVoucher AS PV      
JOIN tblMasterCustomer AS Customer ON Customer.FAID = PV.PartyID      
Where Customer.ID = @CustId and BranchID = @BranchID AND PV.TransID= 7 AND DocDate <=@DocDate AND PV.[Status] IN (1,3)      
UNION      
SELECT SH.DocId, DocDate ,SH.RefNo,''Receivable Voucher'' TransName,SH.NetAmount,SH.Balance,CD.DocID,SH.PartyID FAID,SH.TransID,SH.DocValue,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.ColValue ELSE 0 END) AS ColValue,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.AdjAmt ELSE 0 END) AS AdjAmt,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.DiscAmt ELSE 0 END) AS DiscAmt,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.FullyAdj ELSE 0 END) AS FullyAdj,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.FullyAdjAmt ELSE 0 END) AS FullyAdjAmt,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.TotalAmtAdj ELSE 0 END) AS TotalAmtAdj,SH.UDFDocId,DATEDIFF(DD,SH.DocDate,GETDATE()) Ageing      
FROM tblTranCollectionDetail AS CD      
left join tblTranCollectionHeader ch on ch.ColID = CD.ColID      
LEFT JOIN tblTranPRVoucher SH ON SH.Id = CD.DocID AND SH.TransID = CD.DocPrefix      
LEFT JOIN tblMasterCustomer AS Customer ON SH.PartyID=Customer.FAID      
WHERE CH.Status IN (1,3,5) and CD.ColID = @nCollorPayID AND SH.TransID = 7    
) AS A      
GROUP BY DocID,Tran_Date,DocPrefix,TransName,NetAmount,Balance,PRVID,FAID,DocPrefix,DocValue,UDFDocId,RefNo,Ageing      
UNION ALL -- Debit Note      
SELECT DocID,Tran_Date,ReferNo,TransName,NetAmount,Balance + SUM(ColValue) Balance,PRVID,FAID,DocPrefix,DocValue,SUM(ColValue)ColValue,      
SUM(AdjAmt) AdjAmt,SUM(DiscAmt) DiscAmt,SUM(FullyAdj) FullyAdj,SUM(FullyAdjAmt) FullyAdjAmt,SUM(TotalAmtAdj) TotalAmtAdj,UDFDocId,      
Balance "CURR BAL",Ageing FROM (      
SELECT PV.DocID AS DocID,PV.DocDate as Tran_Date,PV.RefNo ReferNo,''Debit Note'' TransName,      
PV.NetAmount,(PV.Balance) AS Balance,      
PV.ID PRVID,PV.PartyID FAID,PV.TransID DocPrefix,PV.DocValue,0 ColValue,0 AdjAmt,0 DiscAmt,0 FullyAdj,0 FullyAdjAmt,0 TotalAmtAdj,PV.UDFDocId      
,DATEDIFF(DD,PV.DocDate,GETDATE()) Ageing      
FROM tblTranPRVoucher AS PV      
JOIN tblMasterCustomer AS Customer ON Customer.FAID = PV.PartyID      
Where Customer.ID = @CustId AND PV.TransID= 7 AND DocDate <=@DocDate AND PV.[Status] IN (1,3)      
UNION      
SELECT SH.DocId, DocDate ,SH.RefNo,''Debit Note'' TransName,NoteValue,SH.Balance,CD.DocID,SH.PartyID FAID,SH.TransID,SH.DocValue,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.ColValue ELSE 0 END) AS ColValue,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.AdjAmt ELSE 0 END) AS AdjAmt,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.DiscAmt ELSE 0 END) AS DiscAmt,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.FullyAdj ELSE 0 END) AS FullyAdj,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.FullyAdjAmt ELSE 0 END) AS FullyAdjAmt,      
(CASE WHEN CD.ColID = @nCollorPayID THEN CD.TotalAmtAdj ELSE 0 END) AS TotalAmtAdj,SH.UDFDocId      
,DATEDIFF(DD,SH.DocDate,GETDATE()) Ageing      
FROM tblTranCollectionDetail AS CD      
left join tblTranCollectionHeader ch on ch.ColID = CD.ColID      
LEFT JOIN tblNoteDetails SH ON SH.ID = CD.DocID AND SH.TransID = CD.DocPrefix      
LEFT JOIN tblMasterCustomer AS Customer ON SH.PartyID=Customer.FAID      
WHERE CH.Status IN (1,3,5) and CD.ColID = @nCollorPayID AND SH.TransID = 5) AS DN      
GROUP BY DocID,Tran_Date,DocPrefix,TransName,NetAmount,Balance,PRVID,FAID,DocPrefix,DocValue,UDFDocId,ReferNo,Ageing      
) AS MAIN      
WHERE Balance > 0      
ORDER BY CONVERT(DATE,Tran_Date),DocPrefix      
END      
END',
N'[export] nocount';
GO
/****** UspGetPreferredLanguage ******/
EXEC #Apply07 N'dbo.UspGetPreferredLanguage', 0x412C94371C2262EF2EA177D7B0E8C3A22F5471AB2D0DC24873B3D07A10C82024, NULL, NULL, 0x11EE33C5DF3CFAE23817A59019DE22C0CCE16E8C08CCFE03381B3C8E13713B65, 0x4DFE40CE441BFA319A70040C38BF8331AEE06638B31F550FCFDFB59097AB74C9, NULL,
N'--UspGetPreferredLanguage 1,1
ALTER Procedure [dbo].[UspGetPreferredLanguage]
@Form INT,
@ShowAll TinyInt
AS
SET NOCOUNT ON;
BEGIN

IF @Form = 1
    BEGIN
        SELECT MC.ID, MC.Name [OriginalName], MC.PLName [Name],
               MC.PLBillAdd1 [BillAddress1], MC.PLBillAdd2 [BillAddress2],
               MC.PLBillAdd3 [BillAddress3], MC.PLContactPerson [ContactPerson]
        FROM tblMasterCustomer MC
        WHERE @ShowAll = 1
           OR (@ShowAll = 0 AND (ISNULL(MC.PLName, '''') <> ''''
                              OR ISNULL(MC.PLBillAdd1, '''') <> ''''
                              OR ISNULL(MC.PLBillAdd2, '''') <> ''''
                              OR ISNULL(MC.PLBillAdd3, '''') <> ''''
                              OR ISNULL(MC.PLContactPerson, '''') <> ''''))
           OR (@ShowAll = 2 AND ISNULL(MC.PLName, '''') = ''''
                            AND ISNULL(MC.PLBillAdd1, '''') = ''''
                            AND ISNULL(MC.PLBillAdd2, '''') = ''''
                            AND ISNULL(MC.PLBillAdd3, '''') = ''''
                            AND ISNULL(MC.PLContactPerson, '''') = '''')
    END

    ELSE IF @Form = 2  -- Vendor
    BEGIN
        SELECT MV.ID, MV.Name [OriginalName], MV.PLName [Name],
               MV.PLBillAdd1 [BillAddress1], MV.PLBillAdd2 [BillAddress2],
               MV.PLBillAdd3 [BillAddress3], MV.PLContactPerson [ContactPerson]
        FROM tblMasterVendor MV
        WHERE @ShowAll = 1
           OR (@ShowAll = 0 AND (ISNULL(MV.PLName, '''') <> ''''
                              OR ISNULL(MV.PLBillAdd1, '''') <> ''''
                              OR ISNULL(MV.PLBillAdd2, '''') <> ''''
                              OR ISNULL(MV.PLBillAdd3, '''') <> ''''
                              OR ISNULL(MV.PLContactPerson, '''') <> ''''))
           OR (@ShowAll = 2 AND ISNULL(MV.PLName, '''') = ''''
                            AND ISNULL(MV.PLBillAdd1, '''') = ''''
                            AND ISNULL(MV.PLBillAdd2, '''') = ''''
                            AND ISNULL(MV.PLBillAdd3, '''') = ''''
                            AND ISNULL(MV.PLContactPerson, '''') = '''')
    END

    ELSE IF @Form = 3
    BEGIN
        SELECT MP.ID, MP.Name [OriginalName], MP.PLName [Name]
        FROM tblMasterProduct MP
        WHERE @ShowAll = 1
           OR (@ShowAll = 0 AND ISNULL(MP.PLName, '''') <> '''')
           OR (@ShowAll = 2 AND ISNULL(MP.PLName, '''') = '''')
    END

    ELSE IF @Form = 4
    BEGIN
        SELECT MB.ID, MB.Name [OriginalName], MB.PLName [Name]
        FROM tblMasterBeat MB
        WHERE @ShowAll = 1
           OR (@ShowAll = 0 AND ISNULL(MB.PLName, '''') <> '''')
           OR (@ShowAll = 2 AND ISNULL(MB.PLName, '''') = '''')
    END

    ELSE IF @Form = 5
    BEGIN
        SELECT MS.ID, MS.Name [OriginalName], MS.PLName [Name]
        FROM tblMasterSalesman MS
        WHERE @ShowAll = 1
           OR (@ShowAll = 0 AND ISNULL(MS.PLName, '''') <> '''')
           OR (@ShowAll = 2 AND ISNULL(MS.PLName, '''') = '''')
    END
END',
N'[export] nocount';
GO
/****** uspGetPrintConfig ******/
EXEC #Apply07 N'dbo.uspGetPrintConfig', 0x95EB1AC18D6A1C16FE193D171B6A125F308070791C1D0909C0396AD87B69CF2C, NULL, NULL, 0xD0C1DA928F8F6084CE3909C47375FF1F9B07A446A6D3D7026311CD2B2890020A, 0x40CF4BDE3BBA5FA63646CCECFF2F1B8EDB3F26300A42BC237DA2343D0EE7B1EA, NULL,
N'ALTER PROCEDURE [dbo].[uspGetPrintConfig]
@PrintId INT
AS
SET NOCOUNT ON;
BEGIN
SELECT BoxW,BoxH,BoxX,BoxY,PrintMode,DetailItemPerPage,ContinuesPaper,HeaderOnEP,FooterOnEp ,
ctrlName,ctrlWidth,ctrlHeight,ctrlXposition,ctrlYposition,SourceName,FontName,FontSize,FontStyle,[Type],
Footer, PaperType,PaperSizeType,Bold , Italic ,Underline ,Align,pm.Id,BodyLineSpace,LineFeed,IncludeCut,ImageSource,
QRCodeValue,FontColor,isnull(WrapText,0) WrapText
FROM tblPrintConfig
JOIN tblPrintConfigDetail ON tblPrintConfig.PrintID=tblPrintConfigDetail.PrintID
JOIN [tblPrintMesureUnit] AS pm ON pm.Mesuring = tblPrintConfig.PaperSizeType
WHERE tblPrintConfig.PrintID=@PrintId
ORDER BY ctrlYposition ASC
END',
N'[export] nocount';
