/****** uspGetProductLastBatches ******/
EXEC #Apply07 N'dbo.uspGetProductLastBatches', 0xC40C1AED110C19AB14253E0A08C9EE7788420C0273551AF2F61FCE109E756378, NULL, NULL, 0x39A5C4DD046496ACFE50B549F96C064ACF6A36C9E0A092CF48E1DA286A3A985C, 0x40B50CDB2A99162E238E083AFE3FCDF9FA87FF6DA3BCA58CA21CA4309F64483B, NULL,
N'--uspGetProductLastBatches 3,4,123,''2025-05-20''  
ALTER proc [dbo].[uspGetProductLastBatches]    
@Mode int,@BranchID INT = 4,@ProdID INT =123,@Date DATE = NULL    
AS    
SET NOCOUNT ON;
BEGIN    
if(@Mode = 1)    
BEGIN    
SELECT PV.ProdID,MP.Code,MP.Name, dbo.fnGetRoundedValue(sum(actualqty)) ABSQty,    
dbo.fnGetRoundedValue(MP.PurchasePrice) PurchasePrice,dbo.fnGetRoundedValue(sum(actualqty * MP.PurchasePrice)) ABSValue,MP.MOH,MP.MOQ FROM tblProductInventory PV    
JOIN tblMasterProduct MP ON MP.ID = PV.Prodid    
where BranchID = @BranchID and ProdID = @ProdID    
group by MP.PurchasePrice,MP.MOH,MP.MOQ,PV.ProdID,MP.Code,MP.Name    
END    
ELSE IF(@Mode = 2)    
BEGIN    
CREATE TABLE #TempInventoryTransaction (    
    TransDate DATE,    
    PurchaseQty DECIMAL(18, 2),    
 PurchasePrice DECIMAL(18, 2),    
    SaleQty DECIMAL(18, 2)        
);    
SELECT top 5 PV.InventoryId,PV.TransDate,PV.PurchasePrice,ROW_NUMBER() OVER (ORDER BY PV.InventoryId DESC) AS Serial    
into  #temp FROM tblProductInventory PV    
where BranchID = @BranchID and PV.ProdID = @ProdID and transid = 1    
order by InventoryId desc    
declare @TDate DATE,@InvID INT,@Price DECIMAL(25,2)    
declare @nCount int = (select count(*) from #temp),@nID INT = 1    
WHILE(@nCount >= @nID)    
BEGIN    
SELECT @TDate = TransDate,@InvID = InventoryId,@Price = PurchasePrice FROM #temp WHERE Serial = @nID    
    
DECLARE @PurchaseQty decimal(18,2) = (select isnull(sum(UomQty * UOMCF),0) from   
tblTransPurchaseDetail SD   
JOIN tblTransPurchaseHeader SH ON SH.ID = SD.HID WHERE SH.Status IN (1,3,5) and TransID = 1 AND InventoryId = @InvID)    
DECLARE @SaleQty decimal(18,2) = (select isnull(sum(AdjustQty),0) from tblTranSalesDetail SD   
JOIN tblTranSalesHeader SH ON SH.ID = SD.InvID WHERE SH.Status IN (1,3,5) AND DocPrefix = 15 AND InventoryId = @InvID)    
    
INSERT INTO #TempInventoryTransaction (TransDate, PurchaseQty,PurchasePrice, SaleQty)    
VALUES (@TDate, @PurchaseQty,@Price, @SaleQty);    
SET @nID += 1;    
END    
SELECT top 5 FORMAT(TransDate,''dd-MMM-yyyy'') TransDate,dbo.fnGetRoundedValue((PurchaseQty)) PurchaseQty,    
dbo.fnGetRoundedValue((@Price)) PurchasePrice,    
dbo.fnGetRoundedValue((SaleQty)) SaleQty,TransDate TDate    
 FROM #TempInventoryTransaction    
--group by TransDate     
order by TransDate desc    
drop table #temp,#TempInventoryTransaction    
END    
if(@Mode = 3)    
BEGIN    
--dbo.fnGetRoundedValue  
SELECT dbo.fnGetRoundedValue(isnull(sum(SRQty),0)) SRQty,dbo.fnGetRoundedValue(isnull(sum(DRQty),0)) DRQty FROM (  
SELECT case when SH.DocPrefix = 16 and ReturnsTransType = 1 THEN sum(AdjustQty) ELSE 0 END SRQty,  
case when SH.DocPrefix = 16 and ReturnsTransType = 2 THEN sum(AdjustQty) ELSE 0 END DRQty FROM tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
WHERE SH.DocPrefix in (16,17) AND STATUS IN (3,5,6,7) AND SH.BranchID = @BranchID AND SD.ProdID = @ProdID AND    
InvDate BETWEEN @Date and CONVERT(date,GETDATE())    
GROUP BY SH.DocPrefix,ReturnsTransType) AS REC  
END    
IF(@Mode = 4)  
BEGIN  
SELECT       
    V.UOMName,  
    V.ConversionRate  
FROM tblMasterProduct MP  
JOIN tblMasterUOM MU1 ON MU1.ID = MP.BaseUomID  
JOIN tblMasterUOM MU2 ON MU2.ID = MP.PurchaseUomID  
JOIN tblMasterUOM MU3 ON MU3.ID = MP.SalesUOMID  
JOIN tblMasterUOM MU4 ON MU4.ID = MP.ReportingUomID  
CROSS APPLY (  
    VALUES  
        (MU1.Name + '' ('' + CONVERT(NVARCHAR, dbo.fnGetRoundedValue(MP.BaseCR)) + '') - Base'',      MP.BaseCR),  
        (MU2.Name + '' ('' + CONVERT(NVARCHAR, dbo.fnGetRoundedValue(MP.PurchaseCR)) + '') - Purchase'', MP.PurchaseCR),  
        (MU3.Name + '' ('' + CONVERT(NVARCHAR, dbo.fnGetRoundedValue(MP.SalesCR)) + '') - Sales'',     MP.SalesCR),  
        (MU4.Name + '' ('' + CONVERT(NVARCHAR, dbo.fnGetRoundedValue(MP.ReportingCR)) + '') - Reporting'', MP.ReportingCR)  
) AS V(UOMName, ConversionRate)  
WHERE MP.ID = @ProdID;  
END  
END',
N'[export] nocount';
GO
