BEGIN
IF(@Mode = 1)
BEGIN
SELECT MP.Code [Code *],MP.Name [Name *],EAN [EAN *],MF.Name [Mfr Name *],MB.Name [Brand Name *],MC.Name [Category Name *],HSNCode [HSN Code],
ProductDiscPerc [Discount %],BUOM.Name [Base Uom *],BaseCR [Base CR *],PUOM.Name [Purchase Uom *],PurchaseCR [Purchase CR *],SUOM.Name [Sales Uom *],
SalesCR [Sales CR *],RUOM.Name [Reporting Uom *],ReportingCR [Reporting CR *],
purtax.TaxName [Purchase Tax *],saletax.TaxName [Sales Tax *],PurchasePrice [Purchase Price *],
CASE WHEN SaleonMRP = 1 THEN ''Y'' ELSE ''N'' END [Sale on MRP],SaleonpPern [Sales Margin %],SalesPrice [Sales Price *],
CASE WHEN ECPonMRP = 1 THEN ''Y'' ELSE ''N'' END [ECP on MRP],ECPonpPern [ECP Margin %],ECP [ECP *],
CASE WHEN SPLonMRP = 1 THEN ''Y'' ELSE ''N'' END [SPL on MRP],SPLonpPern [SPL Margin %],SPLPrice [SPL Price *],MRP [MRP *],ReturnPrice [Return Price],
CASE WHEN TrackInventory = 1 THEN ''Y'' ELSE ''N'' END [Track Inventory],CASE WHEN TrackBatch = 1 THEN ''Y'' ELSE ''N'' END [Track Batch],
CASE WHEN TrackSerial = 1 THEN ''Y'' ELSE ''N'' END [Track Serial],CASE WHEN TrackPDK = 1 THEN ''Y'' ELSE ''N'' END [Track PKD],
CASE WHEN DateFormat = 1 THEN ''DMY'' ELSE ''MY'' END [Date Format],CASE WHEN BarcodeEnable = 1 THEN ''Y'' ELSE ''N'' END [Barcode Print],
baruom.name [Barcode Uom],pt.PriceType [Barcode Price],MV.Name [Vendor Name],MOH,MOQ,
Remarks,ML.Name [Location Name],Weborder,MPL.Name [Life Time],CASE WHEN MP.Active = 1 THEN ''Y'' ELSE ''N'' END Active from tblMasterProduct MP
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID
JOIN tblMasterCategory MC ON MC.ID = MP.CategoryID
JOIN tblMasterUOM BUOM ON BUOM.ID=MP.BASEUOMID
JOIN tblMasterUOM PUOM ON PUOM.ID=MP.PurchaseUomID
JOIN tblMasterUOM SUOM ON SUOM.ID=MP.SalesUomID
JOIN tblMasterUOM RUOM ON RUOM.ID=MP.ReportingUomID
JOIN tblmastertax purtax on purtax.taxid = mp.purchasetaxid
JOIN tblmastertax saletax on saletax.taxid = mp.salestaxid
left join tblmasteruom baruom on baruom.id = mp.BarcodeUomID
left join tblpricetype pt on pt.id = mp.barcodepriceid
left JOIN tblMasterVendor MV ON MV.ID = MP.VendorID
left JOIN tblMasterLocation ML ON ML.ID = MP.LocationID
LEFT JOIN TBLMASTERPRODUCTLIFETIME MPL ON MPL.ID = MP.LifeTime order by mp.nAME
