''N'' [ECP on MRP], ''10'' [ECP Margin %], ''212.3'' [ECP *], ''N'' [SPL on MRP], ''8'' [SPL Margin %], ''208.44'' [SPL Price *], ''250'' [MRP *], ''0'' [Return Price], ''Y'' [Track Inventory], 
''N'' [Track Batch], ''N'' [Track Serial], ''N'' [Track PKD], ''DMY'' [Date Format], ''
N'' [Barcode Print], '''' [Barcode Uom], '''' [Barcode Price], '''' [Vendor Name], ''0'' [MOH], ''0'' [MOQ],
''This item for hotels and supermarket only'' [Remarks], '''' [Location Name], ''0'' [Weborder], ''3 MONTHS'' [Life Time], ''Y'' [Active]
union all
select ''10011'' [Code *], ''CHAKRA GOLD 50GM'' [Name *], ''10011'' [EAN *], ''TATA'' [Mfr Name *], ''CHAKRA GOLD'' [Brand Name *], ''TEA/COFFEE'' [Category Name *], ''09024090'' [HSN Code], ''0'' [Discount %], 
''PCS'' [Base Uom *], ''1'' [Base CR *], ''PCS'' [Purchase Uom *],''1'' [Purchase CR *], ''PCS'' [Sales Uom *], ''1'' [Sales CR *], 
