''N''
[ECP on MRP], ''12'' [ECP Margin %], ''112'' [ECP *], ''Y'' [SPL on MRP], ''22'' [SPL Margin %], ''99.1525'' [SPL Price *], ''150'' [MRP *], ''95'' [Return Price], ''Y'' [Track Inventory], ''Y'' [Track Batch], ''N'' [Track Serial], ''N'' [Track PKD],
''DMY'' [Date Format], ''N'' [Barcode Print], '''' [Barcode Uom], '''' [Barcode Price], ''VASAN ENTERPRISES'' [Vendor Name], ''0'' [MOH], ''0'' [MOQ],
'''' [Remarks], '''' [Location Name], ''0'' [Weborder], '''' [Life Time], ''Y'' [Active]
union all
select 10025 [Code *], ''SAVORIT NOODLES 500GM'' [Name *], ''10025'' [EAN *], ''SAVORIT'' [Mfr Name *], ''NOODLES'' [Brand Name *], ''VERMICELLI/NOODLES'' [Category Name *], ''190219'' [HSN Code], ''0'' [Discount %], ''PCS'' [Base Uom *], ''1'' [Base CR *], 
''PCS'' [Purchase Uom *], ''1'' [Purchase CR *], ''BAG'' [Sales Uom *], ''2'' [Sales CR *], ''PCS'' [Reporting Uom *], ''1'' [Reporting CR *], ''GST 5%'' [Purchase Tax *], ''GST 5%'' [Sales Tax *], ''73.4'' [Purchase Price *], ''N'' [Sale on MRP],
''0'' [Sales Margin %], ''92.5'' [Sales Price*], ''N'' [ECP on MRP], ''0'' [ECP Margin %], ''92.5'' [ECP *], ''N'' [SPL on MRP], ''0'' [SPL Margin %], ''92.5'' [SPL Price *], ''99'' [MRP *], ''70'' [Return Price], ''Y'' [Track Inventory],
''N'' [Track Batch], ''N'' [Track Serial], ''Y'' [Track PKD], ''DMY'' [Date Format], ''N'' [Barcode Print], '''' [Barcode Uom], '''' [Barcode Price], ''RAVI AGENCIES'' [Vendor Name], ''25'' [MOH], ''10'' [MOQ],
'''' [Remarks],'''' [Location Name],''0'' [Weborder], ''1 MONTH'' [Life Time], ''Y'' [Active]
