/****** uspGetSinglemasterdata ******/
EXEC #Apply07 N'dbo.uspGetSinglemasterdata', 0x245ED8FBE01DA7853D563F71D1C18D56C5ADAE50453ADE976741F267C1E4C3D1, 0x3A97C5A77B3E1309FF7FCB543A70BB189652FF0B39E01C1E62F0CF775EC63679, NULL, 0x33D2E77AE1C643E1AD39AB0E5DEFB3FE11EB80952EE7457916DE612E26C3DE8D, 0x9C12B4C92FE0DBB1813C79B8C1276E48FFD3200BB7863E9BA8780C564309BF81, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspGetSinglemasterdata]
@FormID int
as
SET NOCOUNT ON;
begin
declare @TableName nvarchar(255) = (select TableName from tblTablesNames where ID = @FormID)                
declare @SafeTable NVARCHAR(600) = CASE WHEN OBJECT_ID(@TableName, ''U'') IS NOT NULL THEN QUOTENAME(OBJECT_SCHEMA_NAME(OBJECT_ID(@TableName, ''U''))) + ''.'' + QUOTENAME(OBJECT_NAME(OBJECT_ID(@TableName, ''U''))) END
IF @SafeTable IS NULL AND @TableName IS NOT NULL BEGIN RAISERROR(''Master table for this form was not found.'', 16, 1); RETURN; END
declare @strQuery NVARCHAR(MAX)
SET @strQuery = '' SELECT * FROM ''+@SafeTable+'' WHERE Active = 1 ORDER BY [Name]''
EXEC sys.sp_executesql @strQuery, N''@FormID int'', @FormID  
end',
N'[06] nocount';
GO
/****** uspgetSRExistsbatch ******/
EXEC #Apply07 N'dbo.uspgetSRExistsbatch', 0xBE1C4A30E03C2D341235E662FA5EA62C2FC677E2822AB2C95810A33F92BE417B, NULL, NULL, 0xD6738C14DCA2078195EDCFF27812C5BCD16918CE9FB4568F9994AA6D310999EC, 0xC350A00E69B57EC6E0407CBB7B7FEF1671A54D5BC7E4507CF975A1BAF3B6AE40, NULL,
N'ALTER PROC [dbo].[uspgetSRExistsbatch]  
@AppPriceId int = 2 ,@Branchid int = 4,@prodid int = 124,@BatchNumber nvarchar(255) = null,@PkgDate nvarchar(100) = null,@ExpiryDate nvarchar(100) = null,  
@InventoryPrice decimal(25,4) = 7,@mrp decimal(25,4) = 15  
as  
SET NOCOUNT ON;
begin  
set dateformat dmy;
declare @TrackInventory INT,@TrackBatch INT,@TrackPkd INT,@TrackSerial INT,@InvAdjId int   
  
SELECT @TrackInventory= TrackInventory,@TrackBatch =TrackBatch ,@TrackPkd =TrackPDK,@TrackSerial=TrackSerial   
FROM tblMasterProduct WHERE ID =@ProdId    
  
IF(@TrackInventory =1 AND @TrackBatch=0 AND @TrackPkd=0 )                                
BEGIN                                
SELECT @InvAdjId=MAX(InventoryId) FROM tblProductInventory WHERE BranchID = @BranchID and ProdId=@ProdId AND ISNULL(MRPONPrice,0) =@MRP AND                                
(CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP                       
WHEN @AppPriceId =4 THEN MRP  WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) = @InventoryPrice                         
  
END                     
IF(@TrackInventory =1 AND @TrackBatch=1 AND @TrackPkd=0)                                
BEGIN                                
SELECT @InvAdjId=MAX(InventoryId) FROM tblProductInventory WHERE BranchID = @BranchID and ProdId=@ProdId AND ISNULL(MRPONPrice,0) =@MRP AND BatchNumber =@BatchNumber AND                                
(CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP                       
WHEN @AppPriceId =4 THEN MRP  WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) =  @InventoryPrice                                
END                             
IF(@TrackInventory =1 AND @TrackBatch=0 AND @TrackPkd =1)                                
BEGIN                                
SELECT @InvAdjId=MAX(InventoryId) FROM tblProductInventory WHERE BranchID = @BranchID and ProdId=@ProdId AND ISNULL(MRPONPrice,0) =@MRP AND PKDDate=@PkgDate AND ExpiryDate =@ExpiryDate AND                                
(CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP                       
WHEN @AppPriceId =4 THEN MRP  WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) = @InventoryPrice                                
END                                
IF(@TrackInventory =1 AND @TrackBatch=1 AND @TrackPkd =1)                                
BEGIN                                
SELECT @InvAdjId=MAX(InventoryId) FROM tblProductInventory WHERE BranchID = @BranchID and ProdId=@ProdId AND ISNULL(MRPONPrice,0) =@MRP AND BatchNumber =@BatchNumber AND PKDDate=@PkgDate AND ExpiryDate =@ExpiryDate AND                                
(CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP                       
WHEN @AppPriceId =4 THEN MRP  WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) =@InventoryPrice                                
ENd  
  
select  InventoryID,ProdID,TransDate,BatchNumber,convert(nvarchar(25),PKDDate,103) PKDDate,convert(nvarchar(25),ExpiryDate,103) ExpiryDate,  
ActualQty,ActualFreeQty,ActualDmgQty,PurchasePrice,SalesPrice,ECP,MRP,SPLPrice,MRPONPrice,ReturnPrice,TaxId   
from tblProductInventory where inventoryid = @InvAdjId  
end',
N'[export] nocount';
GO
/****** uspGetStockAgeingHeader ******/
EXEC #Apply07 N'dbo.uspGetStockAgeingHeader', 0xB90182A28174A32F8EC4DE21231FF24995DD8834B3160358C691ADC59C47FEEC, 0x81A4C40FABEF3FF450345725A53CADDFB1CAD60B9D3133863DF180C42C7CB3F2, NULL, 0xD42A1A7119AE88DE4B07D40786D81BF7EC2C765CB642E00AC5997B4466233C6B, 0x663E5E61FF751F861D8C7CFF117426F98E97007A61DA7D99C3AEFB080C3411E2, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspGetStockAgeingHeader]        
@BranchName int = 0,@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255)=''''        
as        
SET NOCOUNT ON;
begin        
DECLARE @query NVARCHAR(MAX)        
set @query = ''        
SELECT Inv.ProdId ProductID,MBR.Name [Branch Name],pa.Code as [Product Code],pa.Name as [Product Name],pa.EAN as EAN,MM.Name as [Mfr Name],              
MB.Name as [Brand Name],MC.Name as [Category Name],FORMAT(Inv.TransDate,''''dd-MMM-yyyy'''')AS [Transaction Date],              
DATEDIFF(day,Inv.TransDate,GETDATE())AS [Stock Ageing],              
[dbo].fnGetRoundedvalue(SUM(Inv.ActualQty) + 
SUM(isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0))) AS [Actual Qty],
[dbo].fnGetRoundedvalue((SUM(Inv.Purchaseprice * (Inv.ActualQty))) + 
(sum(Inv.ActualQty) * SUM(isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0))))AS [Stock Value]
FROM tblProductInventory Inv              
LEFT JOIN tblMasterProduct pa ON pa.ID = Inv.ProdId              
LEFT JOIN tblMasterBranchOffice MBR ON MBR.ID = Inv.BranchID          
JOIN tblMasterManufacturer MM on MM.ID=pa.MfrID              
join tblMasterBrand MB on MB.ID=pa.BrandID              
JOIN TBLMASTERCATEGORY AS MC ON MC.ID = pa.CategoryID      
LEFT JOIN tblVanLoadingSlipDetail VLD ON VLD.InventoryID = Inv.InventoryId  
WHERE Inv.ActualQty > 0 ''        
 set @query += case when ISNULL(@BranchName,'''') = '''' then '''' else '' AND Inv.BranchID = ''+'' @BranchName ''+'''' END          
 set @query += case when ISNULL(@BrandName,'''') = '''' then '''' else '' AND MB.ID IN (SELECT * from dbo.fnSplitString( ''+'' @BrandName ,'''',''''))'' END          
 set @query += case when ISNULL(@CategoryName,'''') = '''' then '''' else '' AND MC.ID IN (SELECT * from dbo.fnSplitString( ''+'' @CategoryName ,'''',''''))'' END          
 set @query += case when ISNULL(@ManufName,'''') = '''' then '''' else '' AND MM.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ManufName ,'''',''''))'' END          
 set @query += case when ISNULL(@ProductName,'''') = '''' then '''' else '' AND pa.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ProductName ,'''',''''))'' END          
 set @query += '' GROUP BY  pa.Code,pa.Name,pa.EAN,MM.Name,MB.Name,MC.Name,Inv.TransDate,Inv.ProdId,MBR.Name
 order by pa.Name''       

 EXEC sys.sp_executesql @query, N''@BranchName int, @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255)'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName        
end',
N'[06] nocount';
GO
/****** uspGetSurroundingCustomer ******/
EXEC #Apply07 N'dbo.uspGetSurroundingCustomer', 0xA5EC292E6E3D50A588AE05DC02E1F629F37EB457F6B0F6437B17FEEABB643062, NULL, NULL, 0xE8E408217C0F6D2F29D754B7A03E5A3C4E43B4E585BFCF03EB19A17F968D41AA, 0xDEE0B229A281CC699FC1281B88D83191F897D751B3671425726EB8E06CA1F21D, NULL,
N'--uspGetSurroundingCustomer 12.965513,  80.208898,2      
ALTER PROC [dbo].[uspGetSurroundingCustomer]                  
@Latitude float, @Longitude float,@UID nvarchar(20) = ''0''      
AS                  
SET NOCOUNT ON;
BEGIN                  
BEGIN TRY      
--declare @Latitude float = 12.9654503, @Longitude float = 80.2089445;                  
declare @BeatID INT = 0,@SalesmanID INT = 0      
SELECT @BeatID = BeatID,@SalesmanID = SalesmanID FROM tblUsers WHERE ID = @UID      
IF(ISNULL(@BeatID,0) = 0 AND ISNULL(@SalesmanID,0) = 0)      
BEGIN      
RAISERROR(''Beat & Salesman not mapped in Today Route. Set Beat & Salesman in Today Route(Tools --> Today Route)'',16,1)      
END      
DECLARE @nRadius INT = (SELECT AppValue FROM tblAppConfig WHERE AppId = 41)                
declare @point geography = geography::Point(@Latitude, @Longitude, 4326);                  
declare @distance int = @nRadius;  
select * from ( select MC.ID,Code [Customer Code],Name AS [Customer Name],convert(nvarchar,CONVERT(DECIMAL(15,2),
@point.STDistance(geography::Point(latitude, Longtitude, 4326)))) + '' M'' Radius,IMG.Imagedata,
MC.BillAdd1+'' ''+MC.BillAdd2+'' ''+MC.BillAdd3 Address
from tblMasterCustomer MC      
left JOIN tblBeatSalesmanMapping CBM ON CBM.CustomerId = MC.ID     
LEFT JOIN tblImages IMG ON IMG.ID = MC.ID AND IMG.FormID = 2
where TRY_CONVERT(float, Latitude) IS NOT NULL
AND TRY_CONVERT(float, Longtitude) IS NOT NULL
AND CBM.BeatId = @BeatID
AND @point.STDistance(
        geography::Point(
            TRY_CONVERT(float, trim(Latitude)),
            TRY_CONVERT(float, trim(Longtitude)),
            4326
        )
    ) <= @distance
) as rec  
group by ID,[Customer Code],[Customer Name],Radius,Imagedata,Address
ORDER BY [Customer Name]                  
END TRY      
BEGIN CATCH      
SELECT ERROR_MESSAGE() MSG,ERROR_PROCEDURE() "PROC",ERROR_LINE() LINE      
END CATCH      
END',
N'[export] nocount';
GO
/****** uspGetTaxCompInfo ******/
EXEC #Apply07 N'dbo.uspGetTaxCompInfo', 0x61E13D218F9D1322B5C443F628A0311662B3B49DB735894241C4D31250673D53, NULL, NULL, 0xE7109EDEE6F9A9A6F2337BCA0A24D2DAAC143CEFF4487EAABACBF764D7F48837, 0x5A00BB50E0CE144E5F8FC6DB9D5941801E8DD1655700F871C7DD2B34BCC9C1CA, NULL,
N'--uspGetTaxCompInfo 3,1      
ALTER PROC [dbo].[uspGetTaxCompInfo]      
@TaxID INT,            
@TaxTypeID INT            
AS            
SET NOCOUNT ON;
BEGIN          
CREATE TABLE #TempTax (TaxCompID INT, GSTTaxTypeID INT, TaxCompPern DECIMAL(25,6))          
INSERT INTO #TempTax          
SELECT TaxCompID,GSTTaxType,(CASE WHEN TaxTypeID = @TaxTypeID THEN CumulativeTax ELSE 0 END)      
FROM tblMasterTaxDetail WITH (READCOMMITTEDLOCK) WHERE TaxID = @TaxID AND TaxTypeID = @TaxTypeID         
      
SELECT * FROM #TempTax          
          
DROP TABLE #TempTax          
END',
N'[export] nocount;readcommittedlock=1';
GO
/****** uspGetTaxCumulative ******/
EXEC #Apply07 N'dbo.uspGetTaxCumulative', 0x1B4A331292EF5339ED401F7D9CE4092B375F6952D8F15DBE1942CDCB25447C6D, NULL, NULL, 0x94168FCD62B5474E958CFE401397FDB4BCD082760A3570A7E875E4528288DD0A, 0xA511D76FECC6F75D12BEC050FE505A829AF27FD43E75708C74C80D8AB94ABAA8, NULL,
N'--[uspGetTaxCumulative] 159,3,1  
ALTER PROC [dbo].[uspGetTaxCumulative]        
@TaxID INT,        
@TaxTypeID INT,@Getall int = 0        
AS        
SET NOCOUNT ON;
BEGIN        
IF(@Getall = 0)  
begin  
SELECT ISNULL(SUM(CumulativeTax),0) FROM tblMasterTaxDetail WITH (READCOMMITTEDLOCK) WHERE TaxID=@TaxID AND TaxTypeID=@TaxTypeID     
 AND GSTTaxType NOT IN (5,3)    
 end  
 else  
 begin  
SELECT * FROM tblMasterTaxDetail WITH (READCOMMITTEDLOCK) WHERE TaxID=@TaxID AND TaxTypeID=@TaxTypeID     
 AND GSTTaxType NOT IN (5,3)    
 end  
END',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspGetTransIdentforMobilePrint ******/
EXEC #Apply07 N'dbo.uspGetTransIdentforMobilePrint', 0x761AD5ECFD1F14A0AA337D6023610A8216826BB3D70A435C5DAEFED2F0716FE8, NULL, NULL, 0x82467FF25FBDEEF94DC3503D5804A0DB8DF255F32BCB148DCE4153CFB626A53E, 0x0B7F69E43EF18345ED60B47A955F9EFD3F55B4E7BADD6BDEF83D11566372ADDA, NULL,
N'--[uspGetTransIdentforPrint] 2,36,7,null,null    
ALTER PROC [dbo].[uspGetTransIdentforMobilePrint]      
@TransID int,@DocValue nvarchar(50)  
as      
SET NOCOUNT ON;
begin      
IF(@TransID = 2)      
BEGIN      
SELECT MAX(ID) ID FROM dbo.tblTransPurchaseHeader WHERE DocID = @DocValue AND TransID = 1 AND Status IN (1,3,5)      
END      
IF(@TransID = 3)      
BEGIN      
SELECT MAX(ID) ID FROM dbo.tblTransPurchaseHeader WHERE DocID = @DocValue AND TransID = 12 AND Status IN (3,5,6)         
END      
IF(@TransID = 4)      
BEGIN      
SELECT MAX(ID) ID FROM dbo.tblTranSalesHeader WHERE DocID = @DocValue AND DocPrefix = 15 AND Status IN (1,3,5)      
END      
IF(@TransID = 5)      
BEGIN      
SELECT MAX(ID) ID FROM dbo.tblTranSalesHeader WHERE DocID = @DocValue AND DocPrefix = 16 AND Status IN (3,5,6,7)      
END      
IF(@TransID = 6)      
BEGIN      
SELECT MAX(ID) ID FROM dbo.tblQuotationHeader WHERE DocID = @DocValue AND DocPrefix = 14 AND Status IN (1,3,5)      
END      
IF(@TransID = 8)      
BEGIN      
SELECT MAX(ColID) ID FROM dbo.tblTranCollectionHeader WHERE DocID = @DocValue AND DocPrefix = 19 AND Status IN (1,3,5)      
END      
IF(@TransID = 23)      
BEGIN      
SELECT MAX(ID) ID FROM dbo.tblVanLoadingSlipHeader WHERE DocID = @DocValue AND TransID = 24 AND Status IN (1,3,5)      
END
end',
N'[export] nocount';
GO
/****** uspGetTransIdentforPrint ******/
EXEC #Apply07 N'dbo.uspGetTransIdentforPrint', 0x15EC61CFB6BF1E28ECE3F5A205A82DC117F1CC34C61888398B7DA3368E8ED7FF, NULL, NULL, 0xE197848FBE36A4F2C3D27B591F4DA3063CB511D71529743A0175EAFC0C9A6FDB, 0x981B262FB0A3226112E2D964F109D4D98C45A5B89973C5B89C2A03C4F825A2D2, NULL,
N'--[uspGetTransIdentforPrint] 2,36,7,null,null  
ALTER PROC [dbo].[uspGetTransIdentforPrint]    
@TransID int,@DocValue nvarchar(50),@Branch nvarchar(50) = '''',@FromDate date = null,@ToDate date = null  
as    
SET NOCOUNT ON;
begin    
IF(@TransID = 2)    
BEGIN    
SELECT MAX(ID) ID FROM dbo.tblTransPurchaseHeader WHERE DocValue = @DocValue AND TransID = 1 AND Status IN (1,3,5)    
AND BranchID = (case when isnull(@Branch,'''') = '''' THEN BranchID ELSE @Branch END)    
  AND (@FromDate IS NULL OR [Date] >= @FromDate)  
  AND (@ToDate IS NULL OR [Date] <= @ToDate)  
END    
IF(@TransID = 3)    
BEGIN    
SELECT MAX(ID) ID FROM dbo.tblTransPurchaseHeader WHERE DocValue = @DocValue AND TransID = 12 AND Status IN (3,5,6)    
AND BranchID = (case when isnull(@Branch,'''') = '''' THEN BranchID ELSE @Branch END)    
  AND (@FromDate IS NULL OR [Date] >= @FromDate)  
  AND (@ToDate IS NULL OR [Date] <= @ToDate)  
END    
IF(@TransID = 4)    
BEGIN    
SELECT MAX(ID) ID FROM dbo.tblTranSalesHeader WHERE DocValue = @DocValue AND DocPrefix = 15 AND Status IN (1,3,5)    
AND BranchID = (case when isnull(@Branch,'''') = '''' THEN BranchID ELSE @Branch END)    
  AND (@FromDate IS NULL OR InvDate >= @FromDate)  
  AND (@ToDate IS NULL OR InvDate <= @ToDate)  
END    
IF(@TransID = 5)    
BEGIN    
SELECT MAX(ID) ID FROM dbo.tblTranSalesHeader WHERE DocValue = @DocValue AND DocPrefix = 16 AND Status IN (3,5,6,7)    
AND BranchID = (case when isnull(@Branch,'''') = '''' THEN BranchID ELSE @Branch END)    
AND (@FromDate IS NULL OR InvDate >= @FromDate)  
  AND (@ToDate IS NULL OR InvDate <= @ToDate)  
END    
IF(@TransID = 6)    
BEGIN    
SELECT MAX(ID) ID FROM dbo.tblQuotationHeader WHERE DocValue = @DocValue AND DocPrefix = 14 AND Status IN (1,3,5)    
AND BranchID = (case when isnull(@Branch,'''') = '''' THEN BranchID ELSE @Branch END)    
AND (@FromDate IS NULL OR DocDate >= @FromDate)  
  AND (@ToDate IS NULL OR DocDate <= @ToDate)  
END    
IF(@TransID = 8)    
BEGIN    
SELECT MAX(ColID) ID FROM dbo.tblTranCollectionHeader WHERE DocValue = @DocValue AND DocPrefix = 19 AND Status IN (1,3,5)    
AND BranchID = (case when isnull(@Branch,'''') = '''' THEN BranchID ELSE @Branch END)    
AND (@FromDate IS NULL OR ColDate >= @FromDate)  
  AND (@ToDate IS NULL OR ColDate <= @ToDate)  
END   
IF(@TransID = 23)    
BEGIN    
SELECT MAX(ID) ID FROM dbo.tblVanLoadingSlipHeader WHERE DocValue = @DocValue AND Status IN (1,3,5)    
AND BranchID = (case when isnull(@Branch,'''') = '''' THEN BranchID ELSE @Branch END)    
AND (@FromDate IS NULL OR DocDate >= @FromDate)  
  AND (@ToDate IS NULL OR DocDate <= @ToDate)  
END  
end',
N'[export] nocount';
GO
/****** uspGetTransName ******/
EXEC #Apply07 N'dbo.uspGetTransName', 0x0A2B33853467869D85B31E64F81876550E804A879C99353F4BA511166359D51C, NULL, NULL, 0x179E4014C3149B7E15ACF2B38B851C6A441B8F9D4FE84913F09B5EF8FEF4F23D, 0xE111EC82E26D4AAC9C5A99D892BA3ABEBB3226D372111E86066FA2C492CDD5FB, NULL,
N'ALTER PROCEDURE [dbo].[uspGetTransName]          
@transID int = null              
AS                  
SET NOCOUNT ON;
BEGIN           
IF isnull(@transID, 0) = 0          
BEGIN             
SELECT Id,TransName,Header,Body,SpecialField From tblTransName TN  
JOIN tblRolePermissions MR ON MR.PermissionFormId = TN.MenuID WHERE Active = 1    
GROUP BY Id,TransName,Header,Body,SpecialField  
order by TransName  
END        
ELSE        
BEGIN        
SELECT Id,TransName,Header,Body,SpecialField From tblTransName TN  
JOIN tblRolePermissions MR ON MR.PermissionFormId = TN.MenuID         
WHERE Id = @transID AND Active = 1    
GROUP BY Id,TransName,Header,Body,SpecialField  
order by TransName  
END                
END',
N'[export] nocount';
GO
/****** uspGetTransVariantQuotationdata ******/
EXEC #Apply07 N'dbo.uspGetTransVariantQuotationdata', 0x7B24B5DE384C6CB76F008BC021FCB22AF591A9E0079825EA9AFA134476F6A492, NULL, NULL, 0x8C7D5E935D6812B49379CE0735C28217D419046DF13E99B3439AD8D31094FDFD, 0xA5DDF6DF4BDA5C7696754D5A95E68C3FFAE94A16C865C2FE7C2B88CAC049DD77, NULL,
N'ALTER PROC [dbo].[uspGetTransVariantQuotationdata]          
@VariantType INT,@Mode INT,@ID INT = 7          
AS          
SET NOCOUNT ON;
BEGIN          
IF(@VariantType = 1)-- INVOICE TO QUOTATION          
BEGIN          
IF(@Mode = 1)          
BEGIN          
SELECT PH.ID, PH.InvDate Date, PH.DocPrefix TransID, PH.BranchID, PH.DocID, PH.DocValue, PH.CustID CustomerID, PH.DocRef RefNo,0 ProdGroupID,          
PH.TaxTypeID, PH.Frieght FrightAmt, PH.OtherCharge OtherChrgPern,          
PH.OtherChargeAmt, PH.TradeDisc TradePern, PH.AdditionalDisc AddnlPern, PH.TotalProdDiscAmt, PH.TotalTradeDiscAmt TradeDiscAmt,          
PH.AdditionalDiscAmt AddnlDiscAmt, PH.RoundOfAmt RoundOffAmt, PH.GrossAmt, PH.TotalTaxAmt TaxAmt, PH.NetAmt,          
PH.Status, PH.UDFId, PH.UDFDocId, PH.UDFDocPrefix, PH.UDFDocValue, PH.Remarks, PH.Narration,PH.PriceID,                                                                  
PH.TCSTaxAmt,PH.TDSAmount,CreditNoteAdjAmt Writeoff,DiffValueGross,DiffValueNet                                                       
FROM tblTransalesheader PH          
JOIN tblMasterCustomer MV ON MV.ID = PH.CustID          
JOIN tblStatus STS ON STS.ID = PH.Status          
JOIN tblMasterBranchOffice MBO ON MBO.ID = PH.BranchID          
where PH.ID = @ID          
END          
ELSE IF(@Mode = 2)          
BEGIN          
SELECT PD.ProdID,PD.UomID,MP.Code,MP.Name,UOM.Name UOM,SUM(UomQty) Qty,PD.DetailMRP,PD.UomPrice ExclPrice,                
--(PD.UomPrice * (1 + (PD.TaxValue / 100))) InclPrice,    
dbo.fngetinclusivevalue(PD.TaxID,PD.DetailMRP,PD.UomPrice) InclPrice,    
PD.ProdDisc ProdPern,pd.ProdDiscAmt,PD.TradeDiscPern TradePern,TradeDisc TradeDiscAmt,                
PD.AddnlDiscPern AddnlPern,AddnlDisc AddnlDiscAmt,SUM(GrossAmt) GrossAmt,SUM(TaxAmt) TaxAmt,SUM(NetAmt) NetAmt,PD.TaxID,MT.TaxName,          
PD.TaxValue TaxPern,SUM(GoodsAmt) GoodsAmt,BaseUomPrice,PV.BatchNumber BatchNo,PV.PKDDate PKD,PV.ExpiryDate Expiry,PD.ReasonID,MP.TrackInventory,                                        
MP.TrackBatch,MP.TrackSerial,MP.TrackPDK,ISNULL(PTP.SalesReturnPrice,0) SalesReturnPrice,ISNULL(PD.DiffValue,0) DiffValue          
,0 NewBatchCreated,PV.PurchasePrice BtPPrice, PV.SalesPrice BtSPrice,PV.ECP BtECP,PV.MRP BtMRP          
, PV.SPLPrice BtSPLPrice, PV.ReturnPrice BtRtnPrice, PD.Serial HiddenRowID,  
SUM(dbo.fngetMRPonCumValue(0,PD.TaxID,1,0)) CumMRPonTax,    
SUM(dbo.fngetMRPonCumValue(1,PD.TaxID,1,PD.DetailMRP)) MRPonTaxAmt    INTO #INVTOQTNDATA
FROM tblTransalesDetail PD                          
JOIN tblMasterProduct MP ON MP.ID = PD.ProdID                          
JOIN tblMasterUOM UOM ON UOM.ID = PD.UomID                          
JOIN tblMasterTax MT ON MT.TaxID = PD.TaxID          
LEFT JOIN TBLProductInventory PV ON PV.InventoryId = PD.InventoryID       
LEFT JOIN tblProductTransactionprices PTP ON PTP.ID = PD.ProdID       
where PD.InvID = @ID                          
group by PD.ProdID,PD.UomID,MP.Code,MP.Name,MP.HSNCode,UOM.Name,PD.ProdDisc,PD.TradeDiscPern,PD.AddnlDiscPern,Serial,                
MT.TaxName,PD.TaxValue,PD.DetailMRP,PD.UomPrice,PD.TaxID,pd.ProdDiscAmt,AddnlDisc,TradeDisc,BaseUomPrice,PV.BatchNumber,PV.PKDDate,      
PV.ExpiryDate,PD.ReasonID,MP.TrackInventory,                                        
MP.TrackBatch,MP.TrackSerial,MP.TrackPDK,ISNULL(PTP.SalesReturnPrice,0),ISNULL(PD.DiffValue,0),PV.PurchasePrice,       
PV.SalesPrice,PV.ECP,PV.MRP , PV.SPLPrice, PV.ReturnPrice, PD.Serial                     
ORDER BY Serial          
SELECT * FROM #INVTOQTNDATA

select SalesUomID,Name,SalesCR,ProdID,UOMType from (  
select mp.SalesUomID,MU.Name,SalesCR,mp.ID ProdID,''SalesUOM'' UOMType,1 sno from tblMasterProduct mp              
JOIN tblMasterUOM MU ON MU.ID = mp.SalesUomID where MP.ID in (select prodid from #INVTOQTNDATA)  
UNION all              
select mp.PurchaseUomID,MU.Name,PurchaseCR,mp.ID ProdID,''PurchaseUOM'' UOMType,2 sno from tblMasterProduct mp              
JOIN tblMasterUOM MU ON MU.ID = mp.PurchaseUomID where MP.ID in (select prodid from #INVTOQTNDATA)         
UNION all              
select mp.BaseUomID,MU.Name,BaseCR CR,mp.ID ProdID,''BaseUOM'' UOMType,3 sno from tblMasterProduct mp              
JOIN tblMasterUOM MU ON MU.ID = mp.BaseUomID where MP.ID in (select prodid from #INVTOQTNDATA)  
) as uoms  
group by ProdID,SalesUomID,Name,SalesCR,UOMType,sno  
order by sno  

DROP TABLE #INVTOQTNDATA
END          
END         
ELSE IF(@VariantType = 2 OR @VariantType = 3)-- 2.INVOICE TO SR OR 3.INVOICE TO DR        
BEGIN        
IF(@Mode = 1)          
BEGIN          
SELECT PH.ID, PH.InvDate Date, PH.DocPrefix TransID, PH.BranchID, PH.DocID, PH.DocValue,PH.BeatID,PH.SalesManID, PH.CustID CustomerID, PH.DocRef RefNo,0 ProdGroupID,        
PH.TaxTypeID,PH.PriceID,PH.PaymentModeID,PH.CreditTermID, PH.Frieght FrightAmt, PH.OtherCharge OtherChrgPern,PH.OtherChargeAmt, PH.TradeDisc TradePern, PH.AdditionalDisc AddnlPern,        
PH.TotalProdDiscAmt, PH.TotalTradeDiscAmt TradeDiscAmt,PH.AdditionalDiscAmt AddnlDiscAmt, PH.RoundOfAmt RoundOffAmt, PH.GrossAmt,        
PH.TotalTaxAmt TaxAmt, PH.NetAmt,PH.Status, PH.UDFId, PH.UDFDocId, PH.UDFDocPrefix, PH.UDFDocValue, PH.Remarks, PH.Narration,        
PH.TCSTaxAmt,PH.TDSAmount,CreditNoteAdjAmt Writeoff,DiffValueGross,DiffValueNet  
  
FROM tblTranSalesHeader PH        
JOIN tblMasterCustomer MV ON MV.ID = PH.CustID        
JOIN tblStatus STS ON STS.ID = PH.Status        
JOIN tblMasterBranchOffice MBO ON MBO.ID = PH.BranchID        
where PH.ID = @ID        
END        
ELSE IF(@Mode = 2)        
BEGIN                                                                              
SELECT PD.ProdID,PD.UomID,MP.Code,MP.Name,UOM.Name UOM,SUM(UomQty) Qty,PD.DetailMRP,PD.UomPrice ExclPrice,                                                                    
(PD.UomPrice * (1 + (PD.TaxValue / 100))) InclPrice,PD.ProdDisc ProdPern,pd.ProdDiscAmt,PD.TradeDiscPern TradePern,TradeDisc TradeDiscAmt,                                                                    
PD.AddnlDiscPern AddnlPern,AddnlDisc AddnlDiscAmt,SUM(GrossAmt) GrossAmt,SUM(TaxAmt) TaxAmt,SUM(NetAmt) NetAmt,PD.TaxID,MT.TaxName,PD.TaxValue TaxPern,                                                                    
SUM(GoodsAmt) GoodsAmt,BaseUomPrice,PV.BatchNumber BatchNo,PV.PKDDate PKD,PV.ExpiryDate Expiry,PD.ReasonID,MP.TrackInventory,                                  
MP.TrackBatch,MP.TrackSerial,MP.TrackPDK,ISNULL(PTP.SalesReturnPrice,0) SalesReturnPrice,ISNULL(PD.DiffValue,0) DiffValue       
,0 NewBatchCreated,PV.PurchasePrice BtPPrice, PV.SalesPrice BtSPrice,PV.ECP BtECP,PV.MRP BtMRP          
, PV.SPLPrice BtSPLPrice, PV.ReturnPrice BtRtnPrice, PD.Serial HiddenRowID ,SUM(dbo.fngetMRPonCumValue(0,PD.TaxID,1,0)) CumMRPonTax,    
SUM(dbo.fngetMRPonCumValue(1,PD.TaxID,1,PD.DetailMRP)) MRPonTaxAmt  INTO #INVTOSRDATA
FROM tblTranSalesDetail PD                                                                              
JOIN tblMasterProduct MP ON MP.ID = PD.ProdID                                          
JOIN tblMasterUOM UOM ON UOM.ID = PD.UomID                                                                              
JOIN tblMasterTax MT ON MT.TaxID = PD.TaxID                                                        
LEFT JOIN TBLProductInventory PV ON PV.InventoryId = PD.InventoryID                                       
LEFT JOIN tblProductTransactionprices PTP ON PTP.ID = PD.ProdID                                   
where PD.InvID = @ID                                                                
group by PD.ProdID,PD.UomID,MP.Code,MP.Name,MP.HSNCode,UOM.Name,PD.ProdDisc,PD.TradeDiscPern,PD.AddnlDiscPern,Serial,                                                                    
MT.TaxName,PD.TaxValue,PD.DetailMRP,PD.UomPrice,PD.TaxID,pd.ProdDiscAmt,AddnlDisc,TradeDisc,BaseUomPrice,PD.ReasonID                                                         
,PV.BatchNumber,PV.PKDDate,PV.ExpiryDate,MP.TrackInventory,MP.TrackBatch,MP.TrackSerial,MP.TrackPDK,PTP.SalesReturnPrice,      
PD.DiffValue,PV.PurchasePrice, PV.SalesPrice,PV.ECP,PV.MRP, PV.SPLPrice, PV.ReturnPrice, PD.Serial                                            
ORDER BY Serial       

SELECT * FROM #INVTOSRDATA

select SalesUomID,Name,SalesCR,ProdID,UOMType from (  
select mp.SalesUomID,MU.Name,SalesCR,mp.ID ProdID,''SalesUOM'' UOMType,1 sno from tblMasterProduct mp              
JOIN tblMasterUOM MU ON MU.ID = mp.SalesUomID where MP.ID in (select prodid from #INVTOSRDATA)  
UNION all              
select mp.PurchaseUomID,MU.Name,PurchaseCR,mp.ID ProdID,''PurchaseUOM'' UOMType,2 sno from tblMasterProduct mp              
JOIN tblMasterUOM MU ON MU.ID = mp.PurchaseUomID where MP.ID in (select prodid from #INVTOSRDATA)         
UNION all              
select mp.BaseUomID,MU.Name,BaseCR CR,mp.ID ProdID,''BaseUOM'' UOMType,3 sno from tblMasterProduct mp              
JOIN tblMasterUOM MU ON MU.ID = mp.BaseUomID where MP.ID in (select prodid from #INVTOSRDATA)  
) as uoms  
group by ProdID,SalesUomID,Name,SalesCR,UOMType,sno  
order by sno  

DROP TABLE #INVTOSRDATA

END        
END        
END',
N'[export] nocount';
GO
/****** uspGetVGSTDataforPrinting ******/
EXEC #Apply07 N'dbo.uspGetVGSTDataforPrinting', 0x96CA5ECEADDDCE9402E8F6D7DAB6330C42C8A77B38110CC61F416BB52F2B97F1, NULL, NULL, 0xCC65995ED4F56E97FE2D8DC0C695C628B8FE6352FD749FF7F20537424A9DF312, 0xF38FB64818D49264EECE2DF77F218585E0C40E57A484FF9C236E0AEFEAC34B0C, NULL,
N'--EXEC [uspGetVGSTDataforPrinting] 4,25422  
ALTER PROC [dbo].[uspGetVGSTDataforPrinting]  
@TransID INT,                      
@TransIdentID INT                      
AS                      
SET NOCOUNT ON;
BEGIN   
SELECT [VGST Type],[VGST %],[VGST Amt],[VTaxableValue] FROM                       
(                      
SELECT TaxTypeID,GSTTaxTypeID,Temp.[GST Comp] AS [VGST Type],dbo.fnGetRoundedValue(TaxCompPern) [VGST %],  
dbo.fnGetRoundedValue(SUM(Temp.TaxValue)) AS [VGST Amt],   
dbo.fnGetRoundedValue(SUM(Temp.[Gross Amount])) AS [VTaxableValue]                 
FROM                      
(                      
SELECT GSTInfo.TaxTypeID,GSTInfo.GSTTaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,            
CASE              
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 3 THEN ''CGST''               
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 3 THEN ''SGST''                      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 3 THEN ''UTGST''                      
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 3 THEN ''GCESS''       
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 3 THEN ''GUOM''           
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 5 THEN ''IGST''              
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 5 THEN ''ICESS''       
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 5 THEN ''IUOM''              
           
END AS [GST Comp], GSTInfo.GrossAmt AS [Gross Amount]                  
FROM tblTransGSTInfo AS GSTInfo              
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID           
WHERE TransIdentID=@TransIdentID AND TransID= (SELECT TransID FROM tblDocumentSeries                
WHERE TransName = (SELECT TransName FROM tblTransName WHERE Id = @TransID)                      
)                      
--@TransID              
) Temp                      
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,TaxTypeID,GSTTaxTypeID  
) src       
ORDER BY TaxTypeID,GSTTaxTypeID                 
END',
N'[export] nocount';
GO
/****** uspgetVLSData ******/
EXEC #Apply07 N'dbo.uspgetVLSData', 0xA2C955A06DD1D051919EABEBB2A786959EF0BE77D4D9704BCF9F5606EFE49D8A, NULL, NULL, 0x7BB54BE54273E96B1C2049CF238FA0A91F77DF00E7AC1BC72542F39203ABDD5C, 0xDFF58A9C03F46F2152DE0166B21501A23AD3AA89B4339F98F7CB14F324254AB7, NULL,
N'--uspgetVLSData 2,8,3        
--uspgetVLSData 2,7,4,2       
ALTER PROC [dbo].[uspgetVLSData]                                
@Mode Int,@SalesmanID int = null,@VLSNo nvarchar(100) = null,@SpotSalePriceMode int = 1                           
as                                
SET NOCOUNT ON;
begin try                              
IF(@Mode = 1)                              
BEGIN                              
declare @TRBeatID INT,@TRSMID INT                          
select @TRBeatID = ISNULL(BeatID,0),@TRSMID = ISNULL(SalesmanID,0) from tblUsers WHERE ID = @SalesmanID                               
                          
select ''Today Route'' Trans,CONVERT(NVARCHAR,ISNULL(BranchID,0)) BranchID,CONVERT(NVARCHAR,ISNULL(BeatID,0)) BeatID,                                  
CONVERT(NVARCHAR,ISNULL(SalesmanID,0)) SalesmanID,CONVERT(NVARCHAR,ISNULL(BranchID,0)) BranchID                
,isnull(PrintProfileID,0) PrintProfileID ,UPIID from tblUsers WHERE ID = @SalesmanID                               
                              
SELECT ID,Name FROM tblMasterSalesman WHERE Active = 1 ORDER BY Name                              
                              
SELECT MC.ID id,Code code,Name label,mob1 MobileNo1,mob2 MobileNo2 FROM tblMasterCustomer MC                          
JOIN tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID                          
WHERE MC.Active = 1  AND BSM.SalesmanID = @TRSMID AND BSM.BeatID = @TRBeatID              
GROUP BY MC.ID,Code,Name,mob1,mob2                          
ORDER BY Name                              
END                              
IF(@Mode = 2)                              
BEGIN                              
DECLARE @VLSID INT = 0,@Sts int,@StsDesc nvarchar(255),@TotalAvlVLS decimal(15,4)          
      
CREATE TABLE #VLSItemData (IdentID INT,ProdID INT,ProductName NVARCHAR(255),UomQty DECIMAL(15,4),UomPrice DECIMAL(15,4),      
InclPrice DECIMAL(15,4),MRP DECIMAL(15,4),AdjustQty DECIMAL(15,4),AvlVLS DECIMAL(15,4),Imagedata VARBINARY(MAX),      
UomCF DECIMAL(15,4),BaseUomPrice DECIMAL(15,4),TaxValue DECIMAL(15,4),TaxID INT,UOMID INT,Weborder INT);      
      
if(ISNULL(@SpotSalePriceMode,0) = 1)--VLS PRICE      
BEGIN      
INSERT  into #VLSItemData      
select 0 IdentID,VD.ProdID,MP.Name ProductName,dbo.fnGetRoundedValue(sum(UomQty)) UomQty,(UomPrice) UomPrice,      
(dbo.fngetInclusiveValue(VD.TaxID,VD.MRP,VD.UomPrice)) InclPrice,(VD.MRP) MRP,      
dbo.fnGetRoundedValue(sum(ISNULL(VLSMQty,0))) AdjustQty,sum(CONVERT(DECIMAL(15,2),UomQty - (ISNULL(VLSMQty,0) + ISNULL(VD.VLSRetrunQty,0)))) AvlVLS,      
IMG.Imagedata,VD.UomCF,VD.BaseUomPrice,VD.TaxValue,VD.TaxID,VD.UOMID,MP.Weborder      
from tblVanLoadingSlipDetail VD      
JOIN tblVanLoadingSlipHeader VH ON VH.ID = VD.ID      
JOIN tblMasterProduct MP ON MP.ID = VD.PRODID      
left join tblImages IMG ON IMG.ID = VD.ProdID AND IMG.FORMID = 1      
WHERE VH.Status not in (4) AND VH.SalesmanID = @SalesmanID and VH.BranchID = @VLSNo      
group by VD.ProdID,MP.Name,UomPrice,VD.MRP,Imagedata,VD.UomCF,VD.BaseUomPrice,VD.TaxValue,VD.TaxID,VD.UOMID,MP.Weborder      
HAVING sum(UomQty) > 0      
--ORDER BY convert(int,isnull(weborder ,''0'')),MP.Name                       
END      
ELSE IF(ISNULL(@SpotSalePriceMode,0) = 2)-- INVENOTRY PRICE      
BEGIN      
INSERT  into #VLSItemData      
select 0 IdentID,VD.ProdID,MP.Name ProductName,dbo.fnGetRoundedValue(sum(UomQty)) UomQty,(PV.ECP) UomPrice,      
(dbo.fngetInclusiveValue(VD.TaxID,PV.MRPONPrice,PV.ECP)) InclPrice,(PV.MRPONPrice) MRP,      
dbo.fnGetRoundedValue(sum(ISNULL(VLSMQty,0))) AdjustQty,sum(CONVERT(DECIMAL(15,2),UomQty - (ISNULL(VLSMQty,0) + ISNULL(VD.VLSRetrunQty,0)))) AvlVLS,      
IMG.Imagedata,VD.UomCF,PV.ECP BaseUomPrice,VD.TaxValue,VD.TaxID,VD.UOMID,MP.Weborder      
from tblVanLoadingSlipDetail VD      
JOIN tblVanLoadingSlipHeader VH ON VH.ID = VD.ID      
JOIN tblMasterProduct MP ON MP.ID = VD.PRODID      
JOIN tblProductInventory PV ON PV.InventoryId = VD.InventoryID      
left join tblImages IMG ON IMG.ID = VD.ProdID AND IMG.FORMID = 1      
WHERE VH.Status not in (4) AND VH.SalesmanID = @SalesmanID and VH.BranchID = @VLSNo      
group by VD.ProdID,MP.Name,PV.ECP,PV.MRPONPrice,Imagedata,VD.UomCF,VD.TaxValue,VD.TaxID,VD.UOMID,MP.Weborder      
HAVING sum(UomQty) > 0      
END      
IF((select sum(CONVERT(DECIMAL(15,2),ISNULL(AvlVLS,0))) from #VLSItemData) = 0)                              
BEGIN                              
RAISERROR(''All Stock Cleared'',16,1);                              
END                              
                              
SELECT VH.ID,VH.DocID,FORMAT(VH.DocDate,''dd/MMM/yyyy'') DocDate,MBO.Name Branch,Remarks,Narration,VH.Status                              
FROM tblVanLoadingSlipHeader VH                              
JOIN tblMasterBranchOffice MBO ON  MBO.ID = VH.BranchID                              
where VH.ID = @VLSID                              
                              
SELECT * FROM #VLSItemData WHERE AvlVLS > 0  ORDER BY  convert(int,isnull(weborder ,''0'')),ProductName                       
                              
DROP TABLE #VLSItemData                              
enD                        
if(@Mode = 3)              
BEGIN              
SELECT MC.ID id,Code code,Name label,mob1 MobileNo1,mob2 MobileNo2 FROM tblMasterCustomer MC                          
JOIN tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID                          
WHERE MC.Active = 1  AND BSM.SalesmanID = @SalesmanID --AND BSM.BeatID = @TRBeatID              
GROUP BY MC.ID,Code,Name,mob1,mob2                          
ORDER BY Name                
END              
end try                              
begin catch                              
select ERROR_MESSAGE() EMsg,ERROR_LINE() ELine,ERROR_PROCEDURE() EProc                              
end catch',
N'[export] nocount';
GO
/****** UspGstReconciliationstatement ******/
EXEC #Apply07 N'dbo.UspGstReconciliationstatement', 0xCD58AB830E2D5925210FEE1A3A2A3EC37E8134848D2DBE4CC373DA58FDAFA1F2, NULL, NULL, 0x2F76AA9FFDB8C31C678A87F60F4CC34E468933082198033EF9CAEE2C226D71D8, 0xDAE83972F2C46DFAEED842DFA1F6C20DECA1D17F35B6B9539E21DED6B32EDE4D, NULL,
N'--UspGstReconciliationstatement 1, ''2026-05-01'', ''2026-10-01'', 0  
ALTER PROCEDURE [dbo].[UspGstReconciliationstatement]  
@Transaction INT,  
@FromDate Date,   
@ToDate Date,   
@ShowBlankDate TinyInt  
AS  
SET NOCOUNT ON;
BEGIN  
  
IF @Transaction = 1  
BEGIN  
SELECT PH.TransID,PH.ID, MBO.Name[Branch Name],PH.PortalDate [Portal Date],PH.Date [Trans Date], PH.DocID [Doc ID], PH.RefNo [Ref No],MV.Name [Party Name],dbo.fnGetRoundedValue(PH.GrossAmt) [Gross Amount],  
dbo.fnGetRoundedValue(PH.TaxAmt)[Tax Amount], dbo.fnGetRoundedValue(PH.NetAmt)[Net Amount]  
from tblTransPurchaseHeader PH  
JOIN tblMasterVendor MV on MV.ID = PH.VendorID  
JOIN tblMasterBranchOffice MBO on MBO.ID = PH.BranchID  
WHERE PH.TransID = 1  
AND PH.Date BETWEEN @FromDate AND @ToDate  
AND (@ShowBlankDate = 0 OR PH.PortalDate IS NULL)  
END  
  
ELSE IF @Transaction = 12  
BEGIN  
SELECT PH.TransID, PH.ID, MBO.Name[Branch Name],PH.PortalDate [Portal Date],PH.Date [Trans Date], PH.DocID [Doc ID], PH.RefNo [Ref No],MV.Name [Party Name],dbo.fnGetRoundedValue(PH.GrossAmt) [Gross Amount],  
dbo.fnGetRoundedValue(PH.TaxAmt)[Tax Amount], dbo.fnGetRoundedValue(PH.NetAmt)[Net Amount]  
from tblTransPurchaseHeader PH  
JOIN tblMasterVendor MV on MV.ID = PH.VendorID  
JOIN tblMasterBranchOffice MBO on MBO.ID = PH.BranchID  
WHERE PH.TransID = 12  
AND PH.Date BETWEEN @FromDate AND @ToDate  
AND (@ShowBlankDate = 0 OR PH.PortalDate IS NULL)  
END  
END',
N'[export] nocount';
GO
/****** uspHomeBrandSummaryDashboard ******/
EXEC #Apply07 N'dbo.uspHomeBrandSummaryDashboard', 0x75F1C002DA3B17C33444A6E45EC8DB225F4A57E7F2EE10107FD5CE7D9EC8B956, NULL, NULL, 0x1C3814EF64EB867DCBE832AC33F2FF9631A7909FCD16C6978D25C237672E15CD, 0x343397896E7FD745204CC4D05EB5CD326B4ED4F29BF6E3B59367B46BFB0B74B0, NULL,
N'ALTER proc [dbo].[uspHomeBrandSummaryDashboard]    
@BranchID int = 4,@FromDate date = ''2026-08-01'' ,@ToDate date = ''2026-08-17'',@WithTax int = 0  
as    
SET NOCOUNT ON;
begin    
DECLARE @OPENINGDATE DATE = (DATEADD(DD,-1,@FromDate))    
declare @todaydate date = getdate()    
/*    
    SUMMARY TABLE    
*/    
select MP.MfrID,SUM(SaleStockValue) OpenStockValue,    
SUM(dbo.fngetInclusiveValue(MP.PurchaseTaxID,MP.MRP * CS.SaleQty,SaleStockValue)) InclOpenStockValue    
into #OpenStock    
from tblClosingStock CS    
JOIN tblMasterProduct MP ON MP.ID = CS.ProdId    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
JOIN tblMasterTax MTT ON MTT.TaxID = MP.PurchaseTaxID    
WHERE ClsDate = @OPENINGDATE and CS.BranchID = (CASE WHEN @BranchID = 0 THEN CS.BranchID ELSE @BranchID END)    
GROUP BY MP.MfrID    
    
select MfrID,SUM(NetBillValue) NetBillValue,SUM(NetPRValue) NetPRValue,    
SUM(NetBillValue) - SUM(NetPRValue) NetNetPurchase,SUM(GrossBillValue) GrossBillValue,SUM(GrossPRValue) GrossPRValue,    
SUM(GrossBillValue) - SUM(GrossPRValue) GrossNetPurchase into #Purchase from (    
select MP.MfrID,CASE WHEN PH.TransID = 1 THEN SUM(PD.NetAmt) ELSE 0 END NetBillValue,    
CASE WHEN PH.TransID = 12 THEN SUM(PD.NetAmt) ELSE 0 END NetPRValue,    
CASE WHEN PH.TransID = 1 THEN SUM(PD.GrossAmt) ELSE 0 END GrossBillValue,    
CASE WHEN PH.TransID = 12 THEN SUM(PD.GrossAmt) ELSE 0 END GrossPRValue    
from tblTransPurchaseHeader PH    
JOIN tblTransPurchaseDetail PD ON PD.HID = PH.ID    
JOIN tblMasterProduct MP ON MP.ID = PD.ProdID    
WHERE Date BETWEEN @FromDate AND @ToDate AND Status NOT IN (2,4)    
 and PH.BranchID = (CASE WHEN @BranchID = 0 THEN PH.BranchID ELSE @BranchID END)    
GROUP BY MP.MfrID,PH.TransID) as PR    
GROUP BY MfrID    
    
    
select MfrID,SUM(NetSalesValue) NetSalesValue,SUM(NetSRValue) NetSRValue,SUM(NetDRValue) NetDRValue,    
SUM(NetSalesValue) - SUM(NetSRValue) - SUM(NetDRValue) NetNetSales,    
SUM(GrossSalesValue) GrossSalesValue,SUM(GrossSRValue) GrossSRValue,SUM(GrossDRValue) GrossDRValue,    
SUM(GrossSalesValue) - SUM(GrossSRValue) - SUM(GrossDRValue) GrossNetSales into #Sales    
from (    
select MP.MfrID,CASE WHEN PH.DocPrefix = 15 THEN SUM(PD.NetAmt) ELSE 0 END NetSalesValue,    
CASE WHEN PH.DocPrefix = 16 and PH.TransactionType = 2 THEN SUM(PD.NetAmt) ELSE 0 END NetSRValue,    
CASE WHEN PH.DocPrefix = 15 THEN SUM(PD.GrossAmt) ELSE 0 END GrossSalesValue,    
CASE WHEN PH.DocPrefix = 16 and PH.TransactionType = 2 THEN SUM(PD.GrossAmt) ELSE 0 END GrossSRValue,    
CASE WHEN PH.DocPrefix = 16 and PH.TransactionType = 3 THEN SUM(PD.NetAmt) ELSE 0 END NetDRValue,    
CASE WHEN PH.DocPrefix = 16 and PH.TransactionType = 3 THEN SUM(PD.GrossAmt) ELSE 0 END GrossDRValue    
from tblTranSalesHeader PH    
JOIN tblTranSalesDetail PD ON PD.InvID = PH.ID    
JOIN tblMasterProduct MP ON MP.ID = PD.ProdID    
WHERE InvDate BETWEEN @FromDate AND @ToDate AND Status NOT IN (2,4)    
 and PH.BranchID = (CASE WHEN @BranchID = 0 THEN PH.BranchID ELSE @BranchID END)    
GROUP BY MP.MfrID,PH.DocPrefix,PH.TransactionType) as PR    
GROUP BY MfrID    
create table #Closing(MfrID int,StockValue decimal(25,4),InclStockValue decimal(25,4),    
DmgStockValue decimal(25,4),InclDmgStockValue decimal(25,4))    
if(@ToDate = @todaydate)    
begin    
insert into #Closing    
select MP.MfrID,SUM(ActualQty * PV.PurchasePrice) StockValue,    
sum(dbo.fngetInclusiveValue(PV.TaxId,ActualQty * PV.MRPONPrice,    
ActualQty * PV.PurchasePrice)) InclStockValue,    
SUM(ActualDmgQty * PV.PurchasePrice) DmgStockValue,    
sum(dbo.fngetInclusiveValue(PV.TaxId,ActualDmgQty * PV.MRPONPrice,    
ActualDmgQty * PV.PurchasePrice)) InclDmgStockValue    
from tblProductInventory PV    
JOIN tblMasterProduct MP ON MP.ID = PV.ProdID    
 WHERE PV.BranchID = (CASE WHEN @BranchID = 0 THEN PV.BranchID ELSE @BranchID END)    
GROUP BY MP.MfrID    
end    
else    
begin    
insert into #Closing    
select MP.MfrID,SUM(SaleStockValue) StockValue,    
SUM(dbo.fngetInclusiveValue(MP.PurchaseTaxID,MP.MRP * CS.SaleQty,SaleStockValue)) InclStockValue    
,SUM(DmgStockValue) DmgStockValue,    
SUM(dbo.fngetInclusiveValue(MP.PurchaseTaxID,MP.MRP * CS.DmgQty,DmgStockValue)) InclDmgStockValue    
from tblClosingStock CS    
JOIN tblMasterProduct MP ON MP.ID = CS.ProdId    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
JOIN tblMasterTax MTT ON MTT.TaxID = MP.PurchaseTaxID    
WHERE ClsDate = @ToDate  and CS.BranchID = (CASE WHEN @BranchID = 0 THEN CS.BranchID ELSE @BranchID END)    
GROUP BY MP.MfrID    
end    
    
/*    
    OUTSTANDING TABLE    
*/    
    
select MfrID,MfrName,SUM(MfrOS) MfrOS into #MFROSVALUE from (    
select MP.MfrID,MF.Name MfrName,(SUM(SD.NetAmt) / SH.NetAmt) * SH.Balance MfrOS from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
WHERE DocPrefix = 15 and Status not in (2,4) AND Balance > 0 AND SD.TaxID > 0    
GROUP BY MP.MfrID,MF.Name,SH.NetAmt,SH.Balance) as rec    
GROUP BY MfrID,MfrName    
    
select count(ID) INVCOUNT,MfrID,MfrName into #MFRINVCOUNT from (    
select (SH.ID) ID,MP.MfrID,MF.Name MfrName from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
WHERE DocPrefix = 15 and Status not in (2,4) AND Balance > 0 AND SD.TaxID > 0    
GROUP BY SH.ID,MP.MfrID,MF.Name) as rec    
GROUP BY MfrID,MfrName    
    
select count(CustID) CustCOUNT,MfrID,MfrName into #MFRCUSTCOUNT from (    
select (SH.CustID) CustID,MP.MfrID,MF.Name MfrName from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
WHERE DocPrefix = 15 and Status not in (2,4) AND Balance > 0 AND SD.TaxID > 0     
GROUP BY SH.CustID,MP.MfrID,MF.Name) as rec    
GROUP BY MfrID,MfrName    
    
    
select MfrID,MfrName,SUM(MfrOS) MfrOS into #MFRL30OSVALUE from (    
select MP.MfrID,MF.Name MfrName,(SUM(SD.NetAmt) / SH.NetAmt) * SH.Balance MfrOS,
DATEDIFF(DD,SH.InvDate,GETDATE()) AGING from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
WHERE DocPrefix = 15 and Status not in (2,4) AND Balance > 0 AND SD.TaxID > 0       
GROUP BY MP.MfrID,MF.Name,SH.NetAmt,SH.Balance,SH.InvDate) as rec  
WHERE AGING > 30
GROUP BY MfrID,MfrName    
    
select count(ID) INVCOUNT,MfrID,MfrName into #MFRL30INVCOUNT from (    
select (SH.ID) ID,MP.MfrID,MF.Name MfrName,DATEDIFF(DD,SH.InvDate,GETDATE()) AGING  from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
WHERE DocPrefix = 15 and Status not in (2,4) AND Balance > 0 AND SD.TaxID > 0      
GROUP BY SH.ID,MP.MfrID,MF.Name,SH.InvDate) as rec    
WHERE AGING > 30
GROUP BY MfrID,MfrName    
    
select count(CustID) CustCOUNT,MfrID,MfrName into #MFRL30CUSTCOUNT from (    
select (SH.CustID) CustID,MP.MfrID,MF.Name MfrName,DATEDIFF(DD,SH.InvDate,GETDATE()) AGING  from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
WHERE DocPrefix = 15 and Status not in (2,4) AND Balance > 0 AND SD.TaxID > 0     
GROUP BY SH.CustID,MP.MfrID,MF.Name,SH.InvDate) as rec    
WHERE AGING > 30
GROUP BY MfrID,MfrName    
    
select count(CustID) CustCOUNT,MfrID,MfrName into #MFRTOTALCUSTCOUNT from (    
select (SH.CustID) CustID,MP.MfrID,MF.Name MfrName from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
WHERE DocPrefix = 15 and Status not in (2,4) AND SD.TaxID > 0     
GROUP BY SH.CustID,MP.MfrID,MF.Name) as rec    
GROUP BY MfrID,MfrName    
    
    
    
    
   
SELECT     
    MF.ID ManufID,MF.Name,    
    
    CONVERT(DECIMAL(18,2), ISNULL(OS.OpenStockValue, 0)) AS OpenStockValue,    
    CONVERT(DECIMAL(18,2), ISNULL(OS.InclOpenStockValue, 0)) AS InclOpenStockValue,    
    
    CONVERT(DECIMAL(18,2), ISNULL(GrossSalesValue, 0)) AS GrossSalesValue,    
    CONVERT(DECIMAL(18,2), ISNULL(GrossSRValue, 0)) AS GrossSRValue,    
    CONVERT(DECIMAL(18,2), ISNULL(GrossDRValue, 0)) AS GrossDRValue,    
    CONVERT(DECIMAL(18,2), ISNULL(GrossNetSales, 0)) AS GrossNetSales,    
    
    CONVERT(DECIMAL(18,2), ISNULL(NetSalesValue, 0)) AS NetSalesValue,    
    CONVERT(DECIMAL(18,2), ISNULL(NetSRValue, 0)) AS NetSRValue,    
    CONVERT(DECIMAL(18,2), ISNULL(NetDRValue, 0)) AS NetDRValue,    
    CONVERT(DECIMAL(18,2), ISNULL(NetNetSales, 0)) AS NetNetSales,    
    
    CONVERT(DECIMAL(18,2), ISNULL(GrossBillValue, 0)) AS GrossBillValue,    
    CONVERT(DECIMAL(18,2), ISNULL(GrossPRValue, 0)) AS GrossPRValue,    
    CONVERT(DECIMAL(18,2), ISNULL(GrossNetPurchase, 0)) AS GrossNetPurchase,    
    
    CONVERT(DECIMAL(18,2), ISNULL(NetBillValue, 0)) AS NetBillValue,    
    CONVERT(DECIMAL(18,2), ISNULL(NetPRValue, 0)) AS NetPRValue,    
    CONVERT(DECIMAL(18,2), ISNULL(NetNetPurchase, 0)) AS NetNetPurchase,    
    
    CONVERT(DECIMAL(18,2), ISNULL(CS.StockValue, 0)) AS StockValue,    
    CONVERT(DECIMAL(18,2), ISNULL(CS.InclStockValue, 0)) AS InclStockValue,    
    CONVERT(DECIMAL(18,2), ISNULL(CS.DmgStockValue, 0)) AS DmgStockValue,    
    CONVERT(DECIMAL(18,2), ISNULL(CS.InclDmgStockValue, 0)) AS InclDmgStockValue    
    into #transaction    
FROM tblMasterManufacturer MF    
LEFT JOIN #OpenStock OS ON OS.MfrID = MF.ID    
LEFT JOIN #Sales S ON S.MfrID = MF.ID    
LEFT JOIN #Purchase P ON P.MfrID = MF.ID    
LEFT JOIN #Closing CS ON CS.MfrID = MF.ID    
    
    
select MF.ID ManufID,MF.Name,CONVERT(nvarchar(50), CONVERT(DECIMAL(18,2), isnull(OS.MfrOS,0))) +'' / ''+    
CONVERT(nvarchar(50),isnull(S.INVCOUNT,0)) +'' / '' +CONVERT(nvarchar(50),isnull(P.CustCOUNT,0)) Outstandings ,    
CONVERT(nvarchar(50), CONVERT(DECIMAL(18,2), isnull(OSL30.MfrOS,0))) +'' / ''+    
CONVERT(nvarchar(50),isnull(SL30.INVCOUNT,0)) +'' / '' +CONVERT(nvarchar(50),isnull(PL30.CustCOUNT,0)) Last30DaysOS ,    
isnull(MTC.CustCOUNT,0) allsaleCustomers into #outstandings    
from tblMasterManufacturer MF    
LEFT JOIN #MFROSVALUE OS ON OS.MfrID = MF.ID    
LEFT JOIN #MFRINVCOUNT S ON S.MfrID = MF.ID    
LEFT JOIN #MFRCUSTCOUNT P ON P.MfrID = MF.ID    
LEFT JOIN #MFRL30OSVALUE OSL30 ON OSL30.MfrID = MF.ID    
LEFT JOIN #MFRL30INVCOUNT SL30 ON SL30.MfrID = MF.ID    
LEFT JOIN #MFRL30CUSTCOUNT PL30 ON PL30.MfrID = MF.ID    
LEFT JOIN #MFRTOTALCUSTCOUNT MTC ON MTC.MfrID = MF.ID    
    
drop table #Closing,#OpenStock,#Purchase,#Sales    
    
DROP TABLE #MFROSVALUE,#MFRINVCOUNT,#MFRCUSTCOUNT,#MFRL30OSVALUE,    
#MFRL30INVCOUNT,#MFRL30CUSTCOUNT,#MFRTOTALCUSTCOUNT    
    
select TT.*,OS.Outstandings,OS.Last30DaysOS,OS.allsaleCustomers from #transaction TT    
JOIN #outstandings OS ON OS.ManufID = TT.ManufID    
  
IF (@WithTax = 0)  
BEGIN  
    SELECT   
        TT.ManufID,  
        TT.Name,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2),ISNULL(TT.OpenStockValue, 0))) AS OpenStockValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.GrossSalesValue, 0))) AS SalesValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.GrossSRValue, 0))) AS SRValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.GrossDRValue, 0))) AS DRValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.GrossNetSales, 0))) AS NetSales,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.GrossBillValue, 0))) AS BillValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.GrossPRValue, 0))) AS PRValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.GrossNetPurchase, 0))) AS NetPurchase,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.StockValue, 0))) AS StockValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.DmgStockValue, 0))) AS DmgStockValue,  
        OS.Outstandings AS Outstandings,  
        OS.Last30DaysOS AS Last30DaysOS,  
        CONVERT(nvarchar(100),ISNULL(OS.allsaleCustomers,0)) AS allsaleCustomers  
  
    FROM #transaction TT  
    JOIN #outstandings OS   
        ON OS.ManufID = TT.ManufID;  
END  
ELSE  
BEGIN  
    SELECT   
        TT.ManufID,  
        TT.Name,  
  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.InclOpenStockValue, 0))) AS OpenStockValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.NetSalesValue, 0))) AS SalesValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.NetSRValue, 0))) AS SRValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.NetDRValue, 0))) AS DRValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.NetNetSales, 0))) AS NetSales,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.NetBillValue, 0))) AS BillValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.NetPRValue, 0))) AS PRValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.NetNetPurchase, 0))) AS NetPurchase,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.InclStockValue, 0))) AS StockValue,  
        CONVERT(nvarchar(100),CONVERT(DECIMAL(15,2), ISNULL(TT.InclDmgStockValue, 0))) AS DmgStockValue,  
        OS.Outstandings AS Outstandings,  
        OS.Last30DaysOS AS Last30DaysOS,  
        CONVERT(nvarchar(100),ISNULL(OS.allsaleCustomers,0)) AS allsaleCustomers  
  
    FROM #transaction TT  
    JOIN #outstandings OS   
        ON OS.ManufID = TT.ManufID;  
END  
DROP TABLE #transaction,#outstandings    
end',
N'[export] nocount';
GO
/****** uspHomescreenCollectionData ******/
EXEC #Apply07 N'dbo.uspHomescreenCollectionData', 0x10F8A7C3F6F1687E08E9F82B0F787A9E219871F7E9AAEF75EE28B3A2F66F4850, NULL, NULL, 0x930BC4F966FA45F7B32908F85039941F630BFFE1CA2F41EB02D6C2D8ADDB6854, 0x50888F069A798F7FA0C9604EF15EE9547838B34FB5DC649038556133F388C39C, NULL,
N'ALTER PROC [dbo].[uspHomescreenCollectionData]
@FilterMode INT = 2
AS
SET NOCOUNT ON;
BEGIN
DECLARE @FromDate DATE, @Todate DATE
IF @FilterMode = 1 -- 1 - Today only
BEGIN
    SET @FromDate = CAST(GETDATE() AS DATE);
    SET @Todate = CAST(GETDATE() AS DATE);
END
ELSE IF @FilterMode = 2 -- 2 - Current week (Monday to Sunday)
BEGIN
    -- Monday to Sunday of current week
    SET @FromDate = DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE));
    SET @Todate = DATEADD(DAY, 7 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE));
END
ELSE IF @FilterMode = 3 -- 3 - Current month
BEGIN
    -- First day to last day of current month
    SET @FromDate = DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1);
    SET @Todate = EOMONTH(GETDATE());
END
ELSE IF @FilterMode = 4 -- 4 - Last 4 full months (Quarterly-ish)
BEGIN
    -- Last 4 full months (excluding current month)
    SET @FromDate = DATEFROMPARTS(YEAR(DATEADD(MONTH, -4, GETDATE())), MONTH(DATEADD(MONTH, -4, GETDATE())), 1);
    SET @Todate = GETDATE()--EOMONTH(DATEADD(MONTH, -1, GETDATE()));
END
ELSE IF @FilterMode = 5
BEGIN    
    SET @FromDate = (SELECT F_SD FROM TblCompanyRegistration)
    SET @Todate = (SELECT F_ED FROM TblCompanyRegistration)
END
print convert(nvarchar,@FromDate) print convert(nvarchar,@Todate)
-- Main Query
SELECT 
    PM.PaymentMode,
    SUM(CH.ColAmt) AS ColAmt,PM.Orderby into #temp
FROM 
    tbltrancollectionheader CH
JOIN 
    tblPaymentMode PM ON PM.ID = CH.ColMode
WHERE 
    CH.DocPrefix = 19 
    AND CH.Status IN (1, 3, 5)
    AND CH.COLDATE BETWEEN @FromDate AND @Todate
GROUP BY 
    PM.PaymentMode,PM.Orderby

	if((select count(*) from #temp) > 0)
	BEGIN
	select PaymentMode,dbo.ConvertAmtINDFormat(ColAmt) ColAmt from (
	select 1 Sno,PaymentMode,
    SUM(ColAmt) AS ColAmt,Orderby from #temp
	group by PaymentMode,Orderby
	union
	select 2,''Total'',SUM(ColAmt),10 from #temp
	) as rec WHERE ColAmt > 0 order by Sno,Orderby
	END
	ELSE
	BEGIN
	SELECT * FROM #temp
	END
	drop table #temp
	
END',
N'[export] nocount';
GO
/****** uspHomescreenData ******/
EXEC #Apply07 N'dbo.uspHomescreenData', 0x6030884D63E711BADFB9E8065664C04AFA0882B212EB9B48328FA1A92772021D, NULL, NULL, 0x077D9D08E31551650CC70C9FC7D4A835398A41249D356B6071F710A67C8137A3, 0xE71A156DEED39538DF8E4DA0244E1B2C6A90C4A401470D6C7154507DF013B056, NULL,
N'--[uspHomescreenData] 6,1
ALTER proc [dbo].[uspHomescreenData]                                      
@Mode INT,@TransID NVARCHAR(MAX),@MfrID INT = 1        
AS                                      
SET NOCOUNT ON;
BEGIN                                      
DECLARE @Todate date = (select getdate())              
IF(@Mode = 1)--DRAFT COUNT                                      
BEGIN                                      
select PH.TransID,MU.MenuName,COUNT(PH.ID) DraftCount,MU.DisplayIndex,MenuTree from tblPurchaseDraftHeader PH                                      
JOIN tblDocumentSeries DS ON DS.TransID = PH.TransID                                      
join tblMenus MU ON MU.MenuId = DS.MenuID                                      
WHERE Status in (1,6)                                      
GROUP BY PH.TransID,MU.MenuName,MU.DisplayIndex,MenuTree                                
union all                                  
select PH.TransID,MU.MenuName,COUNT(PH.ID) DraftCount,MU.DisplayIndex,MenuTree from tblsalesdraftheader PH                                      
JOIN tblDocumentSeries DS ON DS.TransID = PH.TransID                                      
join tblMenus MU ON MU.MenuId = DS.MenuID                                      
WHERE Status in (1,6)                                     
GROUP BY PH.TransID,MU.MenuName,MU.DisplayIndex,MenuTree                                
ORDER BY MenuTree,MU.DisplayIndex                                
END                                      
ELSE IF(@Mode = 2)--DRAFT DOCUMENTS                                      
BEGIN                                      
--IF(@TransID = 1)--PURCHASE BILL DRAFT                                      
BEGIN                                      
SELECT * FROM (                                  
SELECT PH.ID,DocID,CONVERT(NVARCHAR,Date,103) DocDate,RefNo,MBO.Name Branch,'''' Bt,'''' Sm,MV.Name Party,dbo.fngetroundedvalue(isnull(PH.GrossAmt,0)) GrossAmt,                                    
dbo.fngetroundedvalue(isnull(PH.TaxAmt,0)) TaxAmt,dbo.fngetroundedvalue(isnull(PH.NetAmt,0)) NetAmt,TransID                                    
FROM tblPurchaseDraftHeader PH                                                  
JOIN tblMasterVendor MV ON MV.ID = PH.VendorID                                                        
left JOIN tblMasterBranchOffice MBO ON MBO.ID = PH.BranchID                                          
WHERE Status in (1,6)  AND TransID = @TransID                                      
union all                                  
SELECT PH.ID,DocID,CONVERT(NVARCHAR,Date,103) DocDate,RefNo,MBO.Name Branch,'''' Bt,'''' Sm,MV.Name Party,dbo.fngetroundedvalue(isnull(PH.GrossAmt,0)) GrossAmt,                                    
dbo.fngetroundedvalue(isnull(PH.TaxAmt,0)) TaxAmt,dbo.fngetroundedvalue(isnull(PH.NetAmt,0)) NetAmt,TransID                                    
FROM tblsalesdraftheader PH                                                  
JOIN tblMasterCustomer MV ON MV.ID = PH.CustomerID                                                        
left JOIN tblMasterBranchOffice MBO ON MBO.ID = PH.BranchID                                          
WHERE Status in (1,6)  AND TransID = @TransID) AS RED                                      
ORDER BY DocID,ID                                        
END                                      
END                              
ELSE  IF(@Mode = 4)--CHEQUE IN HAND                              
BEGIN                              
SELECT * INTO #TEMP FROM (                       
select 1 SNO,''Less than Today'' DateType,count(*) Counts,(isnull(sum(collAmt),0)) collAmt from tblCollPMDetails                               
where PaymentTermID = 2 and status in (1) and Date < CONVERT(date,GETDATE())             
union          
select 2 SNO,''As on Date'' DateType,count(*) Counts,(isnull(sum(collAmt),0)) collAmt from tblCollPMDetails                               
where PaymentTermID = 2 and status in (1) and Date = CONVERT(date,GETDATE())             
union                              
select 3 SNO,''Tommorrow'' DateType,count(*) Counts,(isnull(sum(collAmt),0)) collAmt from tblCollPMDetails                               
where PaymentTermID = 2 and status in (1) and Date = DATEADD(DD,1, CONVERT(date,GETDATE()))                              
union                     
select 4 SNO,''Greater than equal 2 days'' DateType,count(*) Counts,(isnull(sum(collAmt),0)) collAmt from tblCollPMDetails                               
where PaymentTermID = 2 and status in (1) and Date > DATEADD(DD,1, CONVERT(date,GETDATE()))) AS REC                              
select DateType,Counts,collAmt from (                              
SELECT SNO,DateType,Counts,dbo.ConvertAmtINDFormat(isnull((collAmt),0)) collAmt FROM #TEMP                              
UNION                              
SELECT 5,''Total ''DateType,sum(Counts) Countsv,dbo.ConvertAmtINDFormat(isnull(sum(collAmt),0)) collAmt FROM #TEMP) as a                              
order by SNO                              
DROP TABLE #TEMP                              
END                              
ELSE IF(@Mode = 5)--CASH AND BANK Closing Balance                              
BEGIN                              
                        
create table #CASHCB(Balance decimal(25,4),CrDr varchar(20))                              
insert into #CASHCB                              
exec uspFAAccOpenCloseBalance 1,13,0,@Todate            
create table #BANKCB(Balance decimal(25,4),CrDr varchar(20))                              
select FAID,ROW_NUMBER() OVER(ORDER BY FAID) SNO INTO #TEMPCBACC from tblFAAccount where AccountGroup in (44,24,30)                              
DECLARE @nCount INT = (SELECT COUNT(*) FROM #TEMPCBACC),@n int =1,@FAID INT                              
WHILE(@nCount >= @n)                              
BEGIN                              
SELECT @FAID = FAID FROM #TEMPCBACC WHERE SNO = @n                              
insert into #BANKCB                              
exec uspFAAccOpenCloseBalance 1,@FAID,0,@Todate                             
SET @n = @n+1                              
END                              
SELECT Paymode,(Balance) Balance FROM (                              
SELECT ''Cash'' Paymode,SUM(case when CrDr = ''Dr'' THEN Balance else Balance * -1 end) as Balance FROM #CASHCB                              
UNION                              
select ''Bank'' Paymode,SUM(case when CrDr = ''Dr'' THEN Balance * -1 else Balance end) as Balance from #BANKCB                              
) AS REC                              
drop table #BANKCB,#TEMPCBACC,#CASHCB                              
END                              
ELSE IF(@Mode = 6)--Quick Access Transaction Load                              
BEGIN                   
IF(@TransID = 1)
BEGIN
select DS.TransID,DS.TransName,COALESCE(YDS.Prefix,DS.DocPrefix) DocPrefix from tblDocumentSeries DS                              
LEFT JOIN tblYearwiseDocumentSeries YDS ON YDS.TransID = DS.TransID AND CONVERT(DATE,GETDATE()) between FromDate   
and ToDate AND BranchID = 1  
WHERE DS.Active = 1  AND DS.TransID not IN (17)  
ORDER BY TransName 
END
ELSE
BEGIN
select DS.TransID,DS.TransName,COALESCE(YDS.Prefix,DS.DocPrefix) DocPrefix from tblDocumentSeries DS                              
JOIN tblRolePermissions RP ON RP.PermissionFormId = DS.MenuID             
LEFT JOIN tblYearwiseDocumentSeries YDS ON YDS.TransID = DS.TransID AND CONVERT(DATE,GETDATE()) between FromDate   
and ToDate AND BranchID = 1  
WHERE DS.Active = 1 AND (RP.Role = @TransID) AND DS.TransID not IN (17)  
ORDER BY TransName 
END
        
SELECT ID,Name FROM tblMasterManufacturer WHERE Active = 1 ORDER BY Name        
END              
--7 : Transaction dashborad data (saperatescript)              
ELSE IF(@Mode = 8)              
BEGIN              
select MBO.Name BranchName,dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(sum(PurchasePrice * ActualQty) + sum(PurchasePrice * ActualDmgQty))) StockValue,              
dbo.fnGetRoundedValue(sum(PurchasePrice * ActualQty) + sum(PurchasePrice * ActualDmgQty)) orgStockValue              
from tblProductInventory PV              
JOIN tblMasterBranchOffice MBO ON MBO.ID = PV.BranchID              
where ActualQty > 0 OR ActualDmgQty > 0              
GROUP BY MBO.Name              
END              
ELSE IF(@Mode = 9)              
BEGIN   
SELECT [O/S Name] OSType,[Inv] ParyOS,OrgOS FROM (              
SELECT              
(CASE WHEN SUM(Cust.Invoice) < 0 THEN dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(ISNULL(SUM(Cust.Invoice),0)*-1)) + '' Cr''              
ELSE dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(ISNULL(SUM(Cust.Invoice),0))) + '' Dr''              
END) AS [Inv],''Receivable'' AS [O/S Name],SUM(Cust.Invoice) OrgOS              
FROM              
(              
SELECT ISNULL(SUM(Balance),0) AS Invoice FROM tblTranSalesHeader where Balance>0 and Status in(1,3) and DocPrefix=15        
Union ALL              
SELECT -SUM(Balance) FROM tblTranSalesHeader where Balance>0 and Status in(3,6,7) and DocPrefix=16              
) AS Cust              
Union All              
SELECT (CASE WHEN SUM(vendor.Bill) < 0              
THEN dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue (ISNULL(SUM(vendor.Bill),0)*-1)) + '' Cr''              
ELSE dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(ISNULL(SUM(vendor.Bill),0))) + '' Dr''              
END) AS [Inv] ,''Payable'',SUM(vendor.Bill)              
FROM              
(              
SELECT ISNULL(SUM(Balance),0) AS Bill FROM tblTransPurchaseHeader where Balance>0 and Status in(1,3) and TransID=1              
Union ALL              
SELECT -SUM(Balance) FROM tblTransPurchaseHeader where Balance>0 and Status in(3,6,7) and TransID=12              
)              
AS [vendor]) AS NK1              
END              
ELSE IF(@Mode = 10)            
BEGIN            
create table #BranchCASHCBWithBranch(BranchID int,BranchName nvarchar(255),Balance decimal(25,4),CrDr varchar(20))            
create table #BranchBankCBWithBranch(FAID int,AccountName nvarchar(255),Balance decimal(25,4),CrDr varchar(20),BranchID int,BranchName nvarchar(255),)                
select FAID,AccountName,ROW_NUMBER() OVER(ORDER BY FAID) SNO INTO #BankAccTEMPCB from tblFAAccount where AccountGroup in (44,24,30)              
            
create table #allbranches(id int identity(1,1),BranchID int,BranchName nvarchar(255))            
insert into #allbranches            
select ID,Name from tblMasterBranchOffice where Active = 1            
            
declare @TotBrCount int=(select count(*) from #allbranches),@nCR int = 1,@BranchID int,@BranchName nvarchar(255)            
while(@TotBrCount >= @nCR)            
BEGIN            
select @BranchID = BranchID,@BranchName = BranchName from #allbranches where id = @nCR            
insert into #BranchCASHCBWithBranch(Balance,CrDr)            
exec uspFAAccOpenCloseBalance 1,13,@BranchID,@Todate            
    UPDATE TOP (1) #BranchCASHCBWithBranch            
    SET BranchID = @BranchID,            
        BranchName = @BranchName            
    WHERE BranchID IS NULL;            
SET @nCR = @nCR + 1;            
END            
set @nCR = 1;            
declare @TotBankAccs int = (select count(*) from #BankAccTEMPCB),@nBAIncr int = 1,@BankAccID int,@AccountName nvarchar(255)            
while(@TotBrCount >= @nCR)            
BEGIN            
select @BranchID = BranchID,@BranchName = BranchName from #allbranches where id = @nCR            
print ''Branch Name : ''+@BranchName            
 set @nBAIncr = 1;            
while(@TotBankAccs >= @nBAIncr)            
BEGIN            
select @BankAccID = FAID,@AccountName = AccountName from #BankAccTEMPCB where SNO = @nBAIncr            
print ''Bank Acc No : ''+ @AccountName            
insert into #BranchBankCBWithBranch(Balance,CrDr)            
exec uspFAAccOpenCloseBalance 1,@BankAccID,@BranchID,@Todate            
    UPDATE TOP (1) #BranchBankCBWithBranch            
    SET FAID = @BankAccID,            
        AccountName = @AccountName,            
        BranchID = @BranchID,            
        BranchName = @BranchName            
    WHERE FAID IS NULL;            
            
    set @nBAIncr = @nBAIncr + 1;            
    end            
SET @nCR = @nCR + 1;            
END            
            
select BranchName,dbo.fnGetRoundedValue(Balance) Balance,CrDr from #BranchCASHCBWithBranch where Balance > 0     
            
select BranchName,AccountName,dbo.fnGetRoundedValue(Balance) Balance,CrDr from #BranchBankCBWithBranch where Balance > 0            
drop table #allbranches,#BankAccTEMPCB,#BranchCASHCBWithBranch,#BranchBankCBWithBranch            
            
END            
ELSE IF(@Mode = 11)            
BEGIN            
SELECT            
    -- Order Taken            
    (            
        SELECT dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(SUM(isnull(Amount,0))))            
             + ''/'' + CONVERT(nvarchar, COUNT(isnull(ID,0)))            
        FROM (            
            SELECT SH.ID, SUM(Amount) Amount            
            FROM tblTranOrderTakenHeader SH            
            JOIN tblTranOrderTakenDetail SD ON SD.ID = SH.ID            
            WHERE Status NOT IN (2,4)            
              AND DocDate = CONVERT(date, GETDATE())            
   GROUP BY SH.ID            
        ) A            
    ) AS OTAmount,            
            
    -- Cash            
    (            
        SELECT dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(SUM(isnull(Amt,0))))            
               + ''/'' + CONVERT(nvarchar, COUNT(isnull(ID,0)))            
        FROM tblTranOrderCollectionHeader            
        WHERE Status NOT IN (2,4)            
          AND DocDate = CONVERT(date, GETDATE())            
          AND PaymentID = 1            
    ) AS CashValue,            
            
    -- Cheque            
    (            
        SELECT dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(SUM(isnull(Amt,0))))            
               + ''/'' + CONVERT(nvarchar, COUNT(isnull(ID,0)))            
        FROM tblTranOrderCollectionHeader            
        WHERE Status NOT IN (2,4)            
          AND DocDate = CONVERT(date, GETDATE())            
          AND PaymentID = 2            
    ) AS CheqValue,            
            
    -- Bank Transfer            
   (            
        SELECT dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(SUM(isnull(Amt,0))))            
               + ''/'' + CONVERT(nvarchar, isnull(COUNT(ID),0))            
        FROM tblTranOrderCollectionHeader            
        WHERE Status NOT IN (2,4)            
          AND DocDate = CONVERT(date, GETDATE())            
          AND PaymentID = 4            
    ) AS BTValue;            
END            
ELSE IF(@Mode = 12)            
BEGIN         
        
SELECT        
    ''Saleable'' AS Type,        
    CONVERT(DECIMAL(18,2), ISNULL(SUM(ActualQty), 0)) AS ActualQty,        
    CONVERT(DECIMAL(18,2), ISNULL(SUM(ActualQty * PV.PurchasePrice), 0)) AS Price,        
    CONVERT(DECIMAL(18,2), ISNULL(SUM(dbo.fngetInclusiveValue(PV.TaxId, PV.MRP, PV.PurchasePrice) * ActualQty), 0)) AS InclPrice        
FROM tblProductInventory PV        
JOIN tblMasterProduct MP        
    ON MP.ID = PV.ProdID        
WHERE PV.BranchID = @TransID        
  AND MP.MfrID = (case when isnull(@MfrID,0) = 0 then MP.MfrID ELSE @MfrID  END)      
        
UNION ALL        
        
SELECT        
    ''Damage'' AS Type,        
    CONVERT(DECIMAL(18,2), ISNULL(SUM(ActualDmgQty), 0)) AS ActualQty,        
    CONVERT(DECIMAL(18,2), ISNULL(SUM(ActualDmgQty * PV.PurchasePrice), 0)) AS Price,        
    CONVERT(DECIMAL(18,2), ISNULL(SUM(dbo.fngetInclusiveValue(PV.TaxId, PV.MRP, PV.PurchasePrice) * ActualDmgQty), 0)) AS InclPrice        
FROM tblProductInventory PV        
JOIN tblMasterProduct MP        
    ON MP.ID = PV.ProdID        
WHERE PV.BranchID = @TransID        
  AND MP.MfrID = (case when isnull(@MfrID,0) = 0 then MP.MfrID ELSE @MfrID  END)        
        
UNION ALL        
        
SELECT        
    ''Free'' AS Type,        
    CONVERT(DECIMAL(18,2), ISNULL(SUM(ActualFreeQty), 0)) AS ActualQty,        
    CONVERT(DECIMAL(18,2), ISNULL(SUM(ActualFreeQty * PV.PurchasePrice), 0)) AS Price,        
    CONVERT(DECIMAL(18,2), ISNULL(SUM(dbo.fngetInclusiveValue(PV.TaxId, PV.MRP, PV.PurchasePrice) * ActualFreeQty), 0)) AS InclPrice        
FROM tblProductInventory PV        
JOIN tblMasterProduct MP            ON MP.ID = PV.ProdID        
WHERE PV.BranchID = @TransID        
  AND MP.MfrID = (case when isnull(@MfrID,0) = 0 then MP.MfrID ELSE @MfrID  END);        
END        
ELSE IF(@Mode = 13)            
BEGIN       
declare @Todaydate date = (select GETDATE())    
    
    
SELECT ''Overdue'' Descriptions,ISNULL(SUM(Balance),0) Balance,count(ID) InvCount    
FROM tblTranSalesHeader WHERE DocPrefix = 15 AND Status NOT IN (2,4) AND PaymentModeID = 7 AND Balance > 0    
and CreditDate < @Todaydate    
union all    
SELECT ''Today'',ISNULL(SUM(Balance),0) Balance ,count(ID) InvCount    
FROM tblTranSalesHeader WHERE DocPrefix = 15 AND Status NOT IN (2,4) AND PaymentModeID = 7 AND Balance > 0    
and CreditDate = @Todaydate    
union all    
SELECT ''Next 7 days'',ISNULL(SUM(Balance),0) Balance ,count(ID) InvCount    
FROM tblTranSalesHeader WHERE DocPrefix = 15 AND Status NOT IN (2,4) AND PaymentModeID = 7 AND Balance > 0    
and CreditDate between (dateadd(DD,1,@Todaydate)) and (dateadd(DD,8,@Todaydate))    
union all    
SELECT ''Greater 7 days'',ISNULL(SUM(Balance),0) Balance ,count(ID) InvCount    
FROM tblTranSalesHeader WHERE DocPrefix = 15 AND Status NOT IN (2,4) AND PaymentModeID = 7 AND Balance > 0    
and CreditDate > (dateadd(DD,8,@Todaydate))    
union all    
SELECT ''Total'',ISNULL(SUM(Balance),0) Balance ,count(ID) InvCount    
FROM tblTranSalesHeader WHERE DocPrefix = 15 AND Status NOT IN (2,4) AND Balance > 0  AND PaymentModeID = 7     
END    
END',
N'[export] nocount';
GO
/****** uspHomescreenTransactionsData ******/
EXEC #Apply07 N'dbo.uspHomescreenTransactionsData', 0x77400ED9D3882ECE96E61F8975D1B2CE01951A261CB8947745ED2C44B0260477, NULL, NULL, 0x15EC50193CE6560AE8F663C3FC647A9C907393B9E41743B097A6665877147EA1, 0xD1461426E8239D302897E037B87651384931A4421E01128EF909FEF926D2098E, NULL,
N'ALTER PROC [dbo].[uspHomescreenTransactionsData]  
@FilterMode INT = 2  
AS  
SET NOCOUNT ON;
BEGIN 

DECLARE  @FromDate DATE = ''2025-01-01'',@ToDate  DATE = ''2025-11-30''  

IF @FilterMode = 1 -- 1 - Today only  
BEGIN  
    SET @FromDate = CAST(GETDATE() AS DATE);  
    SET @Todate = CAST(GETDATE() AS DATE);  
END  
ELSE IF @FilterMode = 2 -- 2 - Current week (Monday to Sunday)  
BEGIN  
    -- Monday to Sunday of current week  
    SET @FromDate = DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE));  
    SET @Todate = DATEADD(DAY, 7 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE));  
END  
ELSE IF @FilterMode = 3 -- 3 - Current month  
BEGIN  
    -- First day to last day of current month  
    SET @FromDate = DATEFROMPARTS(YEAR(GETDATE()), MONTH(GETDATE()), 1);  
    SET @Todate = EOMONTH(GETDATE());  
END  
ELSE IF @FilterMode = 4 -- 4 - Last 4 full months (Quarterly-ish)  
BEGIN  
    -- Last 4 full months (excluding current month)  
    SET @FromDate = DATEFROMPARTS(YEAR(DATEADD(MONTH, -4, GETDATE())), MONTH(DATEADD(MONTH, -4, GETDATE())), 1);  
    SET @Todate = GETDATE()--EOMONTH(DATEADD(MONTH, -1, GETDATE()));  
END  
ELSE IF @FilterMode = 5  
BEGIN      
    SET @FromDate = (SELECT F_SD FROM TblCompanyRegistration)  
    SET @Todate = (SELECT F_ED FROM TblCompanyRegistration)  
END  
print convert(nvarchar,@FromDate) print convert(nvarchar,@Todate)  

SELECT [Transaction],dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(SUM(Value))) [Values] FROM (
select SH.DocPrefix TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.InvDate [Tran Date],  
DocRef [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remark,Narration from tblTranSalesHeader SH  
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix = 15 AND Status IN (1,3,5) AND InvDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--SR - sales  
select SH.DocPrefix TransID,SH.ID,''Sales Return'' [Transaction],SH.DocID [Doc ID],SH.InvDate [Tran Date],  
DocRef [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remark,Narration from tblTranSalesHeader SH  
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix = 16 AND TransactionType = 2 AND Status IN (3,5,6) AND InvDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--SR - damage  
select 17 TransID,SH.ID,''Damage Return'' [Transaction],SH.DocID [Doc ID],SH.InvDate [Tran Date],  
DocRef [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remark,Narration from tblTranSalesHeader SH  
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.DocPrefix  
WHERE SH.DocPrefix = 16 AND TransactionType = 3 AND Status IN (3,5,7) AND InvDate BETWEEN @FromDate AND @ToDate  
UNION ALL  
--PR  
select SH.TransID TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.Date [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remarks Remark,Narration from tblTransPurchaseHeader SH  
JOIN tblMasterVendor  MC ON MC.ID = SH.VendorID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID = 12 AND Status IN (3,5,6,7) AND Date BETWEEN @FromDate AND @ToDate  
UNION ALL  
--BILL  
select SH.TransID TransID,SH.ID,DS.TransName [Transaction],SH.DocID [Doc ID],SH.Date [Tran Date],  
RefNo [Ref No],MC.Name [Party Name],sh.NetAmt Value,Balance,STS.Description Status,Remarks Remark,Narration from tblTransPurchaseHeader SH  
JOIN tblMasterVendor  MC ON MC.ID = SH.VendorID  
JOIN tblStatus STS ON STS.ID = SH.Status  
join tblDocumentSeries DS ON DS.TransID = SH.TransID  
WHERE SH.TransID = 1 AND Status IN (1,3,5) AND Date BETWEEN @FromDate AND @ToDate  ) AS REC
group by [Transaction]
END',
N'[export] nocount';
GO
/****** uspImportBeatsalesmanMapping ******/
