/****** uspInActiveCustomerHeader ******/
EXEC #Apply07 N'dbo.uspInActiveCustomerHeader', 0xE754072ACAADD3DFBB4040279EF37CFD7E86EEC9950A596F614FD648F417A444, 0x3CA42ED0DF32D49371D5CF010962CBD52865709B7D92B4A26E00C2DE58A226B0, NULL, 0x1ED05346DC8559C2F16747987ECC807202853C14E3A1D7279EF91C70B5510CCF, 0xADD9DC4F4900916744F3E8E5FF8DEF755E343FC72B94277D3650E49B2E91F4FB, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspInActiveCustomerHeader]    
@BeatName NVARCHAR(255) = '''',@SalesmanName NVARCHAR(255) = '''',@CustomerName NVARCHAR(255) = '''',@CustomerType NVARCHAR(255) = '''',@Ratings NVARCHAR(255)='''',  
@Value INT = 2140,@FromDate DATE = ''2025-08-01'',@ToDate DATE = ''2025-08-30''  
as    
SET NOCOUNT ON;
begin      
declare @StrQuery NVARCHAR(MAX)     
select distinct nk.ID,isnull(nk.BeatId,0) as BeatId,isnull(nk.SalesmanId,0) as SalesmanId, 
cust.CustomerType as CustomerTypeId, cust.Rating as RatingId,
cust.Code as [Customer Code],cust.Name as [Customer Name],(b.Name) as [Beat Name],(s.Name) as [SalesMan Name],CT.NAME [Customer Type],RT.RatingName [Rating],       
cust.Ph1 as [Phone Number],cust.Mob1 as [Mobile Number],CUST.FAID AS AccountID,        
Net as [Net Amount],        
lsttrndate as [Last Trans Date] INTO #TEMP        
from            
(            
select  cust.ID,cbs.BeatId,cbs.SalesmanId,NULL  AS [Net],null as [lsttrndate]        
from tblMasterCustomer as cust            
left join tblBeatSalesmanMapping as cbs on cbs.CustomerId = cust.ID            
UNION ALL            
select tsh.CustId as custId,BeatID as BeatId,SalesManId as SalesmanId,isnull(sum(NetAmt),0) AS [Net],MAX(InvDate) as [lsttrndate]        
from tblTranSalesHeader TSH        
RIGHT JOIN tblMasterCustomer MC ON TSH.CustId = MC.ID         
where Status in (1,3,5) and DocPrefix=15 AND InvDate BETWEEN @FromDate AND @ToDate        
group by  TSH.CustId,BeatID,SalesManId            
) as nk            
left join tblMasterCustomer as cust on cust.ID = nk.ID            
left join tblMasterBeat as b on b.ID = nk.BeatId            
left join tblMasterSalesMan as s on s.ID = nk.SalesmanId     
left join tblMasterCustomerType CT ON CT.ID = cust.CustomerType  
left join tblRatings RT ON RT.ID = cust.Rating  
order by cust.Name         
select ID,BeatId,SalesmanId,CustomerTypeId, RatingId,[Customer Code],[Customer Name],[Beat Name],[SalesMan Name],[Customer Type],[Rating],[Phone Number],        
[Mobile Number],AccountID,ISNULL(sum([Net Amount]),0) as [Net Amount],FORMAT(MAX([Last Trans Date]),''dd-MMM-yyyy'') as [Last Trans Date]        
 INTO #MainTemp from #TEMP        
group by ID,BeatId,SalesmanId,CustomerTypeId, RatingId,[Customer Code],[Customer Name],[Beat Name],[SalesMan Name],[Phone Number],        
[Mobile Number],AccountID,[Customer Type],[Rating]         
set @StrQuery = ''SELECT [Customer Code] ,[Customer Name] ,[Beat Name] ,          
[SalesMan Name] ,[Customer Type],[Rating],[Phone Number] AS [Primary Phone No],[Mobile Number] AS [Primary Mob No] ,          
dbo.fnGetRoundedValue([Net Amount]) as [Doc Value],dbo.fnGetRoundedValue(DBO.fnGetClosingBal(AccountID)) as [Closing Balance],          
[Last Trans Date] FROM #MainTemp   
WHERE [Net Amount] <=  @Value ''    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND ID IN (SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)                    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND BeatId IN (SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)        
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND SalesmanId IN (SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)     
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND CustomerTypeId IN (SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)        
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RatingId IN(SELECT * from  dbo.fnSplitString(  @Ratings ,'''',''''))'' END)     
SET @StrQuery = @StrQuery + '' ORDER BY [Net Amount] DESC''      
EXEC sys.sp_executesql @StrQuery, N''@BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @Value INT, @FromDate DATE, @ToDate DATE'', @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @Value, @FromDate, @ToDate     
DROP TABLE #TEMP,#MainTemp  
end',
N'[06] nocount';
GO
/****** uspInsertInventory ******/
EXEC #Apply07 N'dbo.uspInsertInventory', 0x991427459BB12AF88CA0886C3E7AE1E32526A1927E0C3DBFCB5E06AB74133557, NULL, NULL, 0x20F75B1BC1276F38A339E7C3F3A981C547F79A9DB783FB41AB9F11284C2BA404, 0x2AF1218AED262D6ECB3233C7A74FF56BA11A31145746C479F39926BF4D6BB429, NULL,
N'--uspInsertInventory            
ALTER PROCEDURE [dbo].[uspInsertInventory]            
(@Action NVARCHAR(50),@TransId INT,@Date DATE ,@DocValue INT,@ProdId INT,@UomGrpID INT,@UOMID INT,@RecdQty DECIMAL (25,4)=NULL,@RecdFreeQty DECIMAL (25,4) =NULL,            
@RecdDmgQty DECIMAL (25,4) =NULL,@ActualQty DECIMAL (25,4)=NULL,@ActualFreeQty DECIMAL (25,4) =NULL,@ActualDmgQty DECIMAL (25,4) =NULL,@SRQty DECIMAL (25,4) =NULL,            
@SRFreeQty DECIMAL (25,4) =NULL,@SRDmgQty DECIMAL (25,4) =NULL,@BatchNumber NVARCHAR(255) =NULL ,@PkgDate DATE =NULL,            
@ExpiryDate DATE =NULL,@PurchasePrice DECIMAL (25,4) =NULL,@SalesPrice DECIMAL (25,4) =NULL,@ECP DECIMAL (25,4) =NULL,@SPLPrice DECIMAL (25,4) =NULL,            
@MRP DECIMAL (25,4) =NULL,@ReturnPrice DECIMAL (25,4) =NULL,@TaxId INT ,@TaxTypeId INT ,@TaxPercentage DECIMAL (25,4),            
@InventoryId INT =NULL ,@ScopeId INT OUT,@AdjOnly SMALLINT=NULL ,@InclusiveYesNo INT =NULL,@CBy INT =NULL,@BranchID int = 0,    
@SelectedUomCF DECIMAL (25,4) = 1,@PRQty decimal(25,4) = null,@PRFreeQty decimal(25,4) = null,@PRDmgQty decimal(25,4) = null,
@StkInQty decimal(25,4) = null,@StkInFreeQty decimal(25,4) = null,@StkInDmgQty decimal(25,4) = null,@StkOutQty decimal(25,4) = null,
@StkOutFreeQty decimal(25,4) = null,@StkOutDmgQty decimal(25,4) = null,@InvoiceQty decimal(25,4) = null,@InvoiceFreeQty decimal(25,4) = null,
@InvoiceDmgQty decimal(25,4) = null,@InvenoryAdjQty decimal(25,4) = null,@InvenoryAdjFreeQty decimal(25,4) = null,@InvenoryAdjDmgQty decimal(25,4) = null,
@InvenoryConvQty decimal(25,4) = null,@InvenoryConvFreeQty decimal(25,4) = null,@InvenoryConvDmgQty decimal(25,4) = null   
)            
AS            
BEGIN            
SET NOCOUNT ON;            
DECLARE @MRPUomID INT, @UOMCF DECIMAL(25, 5),@PriceOnUOMId INT,@ActualPurPrice DECIMAL (25,4),            
@ActualSalePrice DECIMAL (25,4),@ActualECPPrice DECIMAL (25,4),@ActualSPLPrice DECIMAL (25,4),            
@ActualMRPPrice DECIMAL (25,4),@ActualReturnPrice DECIMAL (25,4),@MRPOn DECIMAL (25,4),@dUOMTax DECIMAL(25,4)            
IF ISNULL(@InventoryId,0) =0 OR @Action=''UPDATE''            
BEGIN --New Batch Info            
--Product Detail            
--SELECT @UOMCF = BaseCR FROM dbo.tblMasterProduct WHERE ID =@ProdId            
            
--Inventory Updation Calculate Base Price            
SET @MRPOn =@MRP;            
set @UOMCF = @SelectedUomCF--(CASE WHEN @TransId = 16 THEN 1 ELSE @UOMCF END)            
SET @ActualPurPrice = (@PurchasePrice / @UOMCF)            
SET @ActualSalePrice = (@SalesPrice / @UOMCF )            
SET @ActualECPPrice = (@ECP / @UOMCF )            
SET @ActualSPLPrice = (@SPLPrice / @UOMCF)            
SET @ActualMRPPrice = (@MRP )            
SET @ActualReturnPrice = (@ReturnPrice)            
SET @dUOMTax = (SELECT (CASE WHEN @TaxTypeId = 1 then ISNULL((GUOM),0) WHEN @TaxTypeId = 2 THEN ISNULL((IUOM),0) ELSE 0 END) FROM tblMasterTax WITH (READCOMMITTEDLOCK) WHERE TaxID = @TaxId)            
--Inclusive Checked Calculation            
--IF ISNULL(@InclusiveYesNo,0)=1            
--BEGIN            
SET @ActualMRPPrice = (@ActualMRPPrice - @dUOMTax) / ((@TaxPercentage /100 )+ 1)            
--END            
END            
            
IF ISNULL(@InventoryId,0) >0 AND @Action=''INSERT''            
BEGIN --Get Batch info Existing            
SELECT @BatchNumber=BatchNumber,@PkgDate=PKDDate,@ExpiryDate=ExpiryDate,@ActualPurPrice =PurchasePrice ,@ActualSalePrice =SalesPrice,@ActualECPPrice=ECP,@ActualMRPPrice=MRP,            
@ActualSPLPrice=SPLPrice,@MRPOn = MRPONPrice,@ActualReturnPrice = ReturnPrice FROM tblProductInventory WITH (READCOMMITTEDLOCK) WHERE InventoryId=@InventoryId            
IF ISNULL(@TaxId,0) =0 AND ISNULL(@TaxTypeId,0) = 0            
BEGIN --Sales Return TranSaction Pass the Grid Tax and Tax Type And Tax Value            
SELECT @TaxId=TaxId,@TaxTypeId=TaxTypeId,@TaxPercentage=TaxValue            
FROM tblProductInventory WITH (READCOMMITTEDLOCK) WHERE InventoryId=@InventoryId            
END            
END            
--Batch info Existing            
IF ISNULL(@AdjOnly,0)=1            
BEGIN            
SET @ActualPurPrice =@PurchasePrice            
END            
--Using only For Insert in Inventory Table            
IF @Action=''INSERT''            
BEGIN            
INSERT INTO tblProductInventory(TransId,TransDate,DocValue,ProdId,RecdQty,RecdFreeQty,RecdDmgQty,ActualQty,ActualFreeQty,ActualDmgQty,SRQty ,            
SRFreeQty ,SRDmgQty,BatchNumber,PkdDate,ExpiryDate,PurchasePrice,SalesPrice,ECP,SPLPrice,MRP,MRPONPrice,TaxId,TaxTypeId,TaxValue,ReturnPrice,            
CBy,CDate,BranchID,PRQty,PRFreeQty,PRDmgQty,StkInQty,StkInFreeQty,StkInDmgQty,StkOutQty,StkOutFreeQty,StkOutDmgQty,InvoiceQty,InvoiceFreeQty,InvoiceDmgQty,
InvenoryAdjQty,InvenoryAdjFreeQty,InvenoryAdjDmgQty,InvenoryConvQty,InvenoryConvFreeQty,InvenoryConvDmgQty)
VALUES( @TransId,@Date ,@DocValue ,@ProdId ,ISNULL(@RecdQty,0) ,ISNULL(@RecdFreeQty,0) ,ISNULL(@RecdDmgQty,0),ISNULL(@ActualQty ,0),            
ISNULL(@ActualFreeQty ,0),ISNULL(@ActualDmgQty,0),ISNULL(@SRQty ,0),ISNULL(@SRFreeQty,0),ISNULL(@SRDmgQty ,0),(CASE WHEN @BatchNumber = '''' THEN NULL ELSE @BatchNumber END) ,@PkgDate,@ExpiryDate,ISNULL(@ActualPurPrice,0) ,ISNULL(@ActualSalePrice,0) ,ISNULL(@ActualECPPrice,0) ,ISNULL(@ActualSPLPrice,0),            
ISNULL(@ActualMRPPrice,0),ISNULL(@MRPOn,0) ,@TaxId ,@TaxTypeId ,ISNULL(@TaxPercentage,0),ISNULL(@ActualReturnPrice,0),@CBy,GETDATE(),  
@BranchID,isnull(@PRQty,0),isnull(@PRFreeQty,0),isnull(@PRDmgQty,0),isnull(@StkInQty,0),isnull(@StkInFreeQty,0),isnull(@StkInDmgQty,0),
isnull(@StkOutQty,0),isnull(@StkOutFreeQty,0),isnull(@StkOutDmgQty,0),isnull(@InvoiceQty,0),isnull(@InvoiceFreeQty,0),isnull(@InvoiceDmgQty,0),
isnull(@InvenoryAdjQty,0),isnull(@InvenoryAdjFreeQty,0),isnull(@InvenoryAdjDmgQty,0),isnull(@InvenoryConvQty,0),isnull(@InvenoryConvFreeQty,0),
isnull(@InvenoryConvDmgQty,0))
SET @ScopeId=(SELECT SCOPE_IDENTITY ())            
END            
--using only for Update in Inventroy Table            
ELSE IF @Action=''UPDATE''            
BEGIN            
UPDATE dbo.tblProductInventory SET DocValue =@docvalue, ProdId = @ProdId ,TransId=@TransId,TransDate=@Date,RecdQty=@RecdQty,RecdFreeQty=@RecdFreeQty,            
RecdDmgQty=@RecdDmgQty,ActualQty =@ActualQty,ActualFreeQty=@ActualFreeQty,ActualDmgQty=@ActualDmgQty            
,SRQty = ISNULL(@SRQty ,0),SRFreeQty = ISNULL(@SRFreeQty ,0),SRDmgQty = ISNULL(@SRDmgQty ,0), BatchNumber=(CASE WHEN @BatchNumber = '''' THEN NULL ELSE @BatchNumber END)            
,PkdDate= ISNULL(@PkgDate,null),ExpiryDate= ISNULL(@ExpiryDate,null),PurchasePrice=ISNULL(@ActualPurPrice,0),SalesPrice=ISNULL(@ActualSalePrice,0),ECP=ISNULL(@ActualECPPrice,0),            
MRP=ISNULL(@ActualMRPPrice,0) ,SPLPrice=ISNULL(@ActualSPLPrice,0),TaxId=@TaxId,TaxTypeId=@TaxTypeId,TaxValue=ISNULL(@TaxPercentage,0),      
MRPONPrice =ISNULL(@MRP,0),ReturnPrice = isnull(@ActualReturnPrice,0),MBy = @CBy,MDate = GETDATE(),BranchID = @BranchID,
PRQty = isnull(@PRQty,0),PRFreeQty = isnull(@PRFreeQty,0),PRDmgQty = isnull(@PRDmgQty,0),StkInQty = isnull(@StkInQty,0),
StkInFreeQty = isnull(@StkInFreeQty,0),StkInDmgQty = isnull(@StkInDmgQty,0),StkOutQty = isnull(@StkOutQty,0),
StkOutFreeQty = isnull(@StkOutFreeQty,0),StkOutDmgQty = isnull(@StkOutDmgQty,0),InvoiceQty = isnull(@InvoiceQty,0),
InvoiceFreeQty = isnull(@InvoiceFreeQty,0),InvoiceDmgQty = isnull(@InvoiceDmgQty,0),InvenoryAdjQty = isnull(@InvenoryAdjQty,0),
InvenoryAdjFreeQty = isnull(@InvenoryAdjFreeQty,0),InvenoryAdjDmgQty = isnull(@InvenoryAdjDmgQty,0),InvenoryConvQty = isnull(@InvenoryConvQty,0),
InvenoryConvFreeQty = isnull(@InvenoryConvFreeQty,0),InvenoryConvDmgQty = isnull(@InvenoryConvDmgQty,0)
WHERE InventoryId = @InventoryId            
SET @ScopeId =@InventoryId            
END            
END',
N'[export] readcommittedlock=3';
GO
/****** uspInvAdjHeader ******/
EXEC #Apply07 N'dbo.uspInvAdjHeader', 0x11BB1DB71576A5275F21329BC7B0FA96CA5EE437890B87A0190C147A335C7959, NULL, NULL, 0x80B0F31A6324B8069D01DBD15B25D508F892DA3F3F983464A2D01828F4E5FA60, 0x72A212D2EFD306DCEBB8F60071DDEFA1FD4AC3DD27983D031961323F226DECDE, NULL,
N'--[uspInvAdjHeader] 5
ALTER Proc [dbo].[uspInvAdjHeader]         
@DocValue INT = null        
As        
SET NOCOUNT ON;
Begin        
Select Inv.InventoryID as [Inv ID],format(Inv.InventoryDate,''dd/MMM/yyyy'') as [Doc Date],Isnull(CONVERT(nvarchar(5),Inv.MDate,108),
CONVERT(nvarchar(5),Inv .CDate,108)) as [Time], MBO.Name [Branch Name], 
Doc.TransName as [Trans Name],Inv.DocID as [Doc ID],DBO.fnGetRoundedValue(Inv.TotalAmt) as [Total Amount],  
dbo.fnConvertAmountinWords(Inv.TotalAmt) AS [Amt_in_Words],UserTab.username as [User Name],Remarks,Narration 
From dbo.tblInventoryHeader as Inv        
--Join dbo.tblInventoryDetail as Details on Inv.InventoryID = Details.InventoryID        
join dbo.tblDocumentSeries AS Doc ON Inv. TransID = Doc.TransID           
join tblMasterBranchOffice MBO ON MBO.ID = Inv.BranchID
Join dbo.tblUsers as UserTab on UserTab.ID = Inv.MBy or UserTab.ID  =  Inv.Cby         
Where Inv.InventoryID = @DocValue AND Inv.TransID = 13       
END',
N'[export] nocount';
GO
/****** uspInventoryAdjustmentProdHistory ******/
EXEC #Apply07 N'dbo.uspInventoryAdjustmentProdHistory', 0xB97B4642E83D26DEF2D43543AEBDC418069361677D2097C79B4AA9581FF6267F, NULL, NULL, 0xF43A63CEECE88E62D87256524ED7A4583C3E1D5F9E8BA286F7612FAA8CE5EE6F, 0x370C5C56E1E479B8647F71D76F539A11FAEBA4DA710545E1B39ACD086B2C9C3A, NULL,
N'ALTER proc [dbo].[uspInventoryAdjustmentProdHistory]  
@ProdID INT = 124 ,@BranchID INT = 4  
as  
SET NOCOUNT ON;
begin  
select DocID,format(InventoryDate,''dd-MMM-yyyy'') DocDate,  
''Org : ''+[Org Purchase Price]+''<br/>New : ''+[New Purchase Price]+''<br/><p style="font-weight:600">Diff : ''+[Purchase Price Diff]+''</p>'' PurchasePrice, 
''Org : ''+[Org Qty]+''<br/>New : ''+[New Qty]+''<br/><p style="font-weight:600">Diff : ''+[Qty Diff]+''</p>'' Qty,  
''Org : ''+[Org Free Qty]+''<br/>New : ''+[New Free Qty]+''<br/><p style="font-weight:600">Diff : ''+[Free Qty Diff] +''</p>'' FreeQty,  
''Org : ''+[Org Damage Qty]+''<br/>New : ''+[New Damage Qty]+''<br/><p style="font-weight:600">Diff : ''+[Damage Qty Diff]+''</p>'' DamageQty,Remarks,Narration  
from (  
SELECT IH.DocID,InventoryDate,  
[dbo].[fnGetRoundedValue](OrgPurPrice) AS [Org Purchase Price],      
[dbo].[fnGetRoundedValue](ActualPurPrice)as [New Purchase Price],     
[dbo].[fnGetRoundedValue]((ID.ActualPurPrice - ID.OrgPurPrice)) [Purchase Price Diff],  
[dbo].[fnGetRoundedValue](OrgQty) AS [Org Qty] ,  
[dbo].[fnGetRoundedValue](ID.ActualQty)AS[New Qty],   
[dbo].[fnGetRoundedValue]((ID.ActualQty - ID.OrgQty)) [Qty Diff],      
[dbo].[fnGetRoundedValue](OrgFreeQty) as [Org Free Qty],      
[dbo].[fnGetRoundedValue](ID.ActualFreeQty)AS[New Free Qty]  ,  
[dbo].[fnGetRoundedValue]((ID.ActualFreeQty - ID.OrgFreeQty)) [Free Qty Diff],      
[dbo].[fnGetRoundedValue](OrgDmgQty) as [Org Damage Qty],      
[dbo].[fnGetRoundedValue](ID.ActualDmgQty)AS [New Damage Qty],    
[dbo].[fnGetRoundedValue]((ID.ActualDmgQty - ID.OrgDmgQty)) [Damage Qty Diff],  
Remarks,Narration  
FROM tblInventoryDetail ID  
JOIN tblInventoryHeader IH ON IH.InventoryID = ID.InventoryID  
WHERE IH.TransID = 13 AND ID.ProdID = @ProdID AND IH.BranchID = @BranchID ) as Rec  
order by InventoryDate desc  
end',
N'[export] nocount';
GO
/****** uspInventoryConvertionDetailSave ******/
EXEC #Apply07 N'dbo.uspInventoryConvertionDetailSave', 0x5D70943FC4A385E3CC88F66CDC5DCDC6BC779ADAE249DB9283B5CE8D361530AB, NULL, NULL, 0x1B7166629B1BA2039BBE5FD1F94BD7232DF5F0205956420B14FE77322839BBC1, 0x775D83E1F6E9778DEDF98E9B3819B76B88CD0A2CEE302BBA23EE89CA47B1257B, NULL,
N'ALTER PROC [dbo].[uspInventoryConvertionDetailSave]  
@BranchID INT,@HeaderID INT,@Date DATE,@ProdID INT ,@Type NVARCHAR(255),@Qty DECIMAL(25, 9),@InvID INT,@GrossAmt DECIMAL (25,6),                  
@ReasonId INT,@CBy int = 0  
AS                                    
BEGIN TRY                          
SET NOCOUNT ON;                 
SET DATEFORMAT DMY;                                
DECLARE @TransDate Date,@BatchNo nvarchar(255),@PKD Date,@Expiry Date,@PurPrice DECIMAL (25,6),@SalePrice DECIMAL (25,6),@ECP DECIMAL (25,6),                          
@SPL DECIMAL (25,6),@MRP DECIMAL (25,6),@TaxID INT,@TaxTypeID INT,@TaxValue INT,@ScopeID INT,@AQty DECIMAL(25, 9),@AFQty DECIMAL(25, 9),                  
@ADQty DECIMAL(25, 9),@ActiveCheck NVARCHAR(255),                        
@GrossAmt1 DECIMAL (25,6) , @Qty1 DECIMAL(25, 9) ,@MRPonPrice DECIMAL (25,6),@DocValue INT    
  
--Get Inventory Table detail                                   
SELECT @AQty=ActualQty,@AFQty=ActualFreeQty,@ADQty=ActualDmgQty,@Transdate = TransDate, @BatchNo = BatchNumber,@PKD = PKDDate,                  
@Expiry = ExpiryDate,@PurPrice = PurchasePrice, @SalePrice = SalesPrice,@ECP = ECP,@MRP = MRP,@SPL = SPLPrice,@TaxID = TaxId,                  
@TaxTypeID = TaxTypeId,@TaxValue = TaxValue ,@MRPonPrice =MRPONPrice                          
FROM dbo.tblProductInventory WITH (READCOMMITTEDLOCK) WHERE InventoryId = @InvID    
SELECT @DocValue = DocValue FROM tblInventoryHeader WITH (READCOMMITTEDLOCK) WHERE InventoryID = @HeaderID    
IF(@Transdate > @Date)                                  
BEGIN                          
RAISERROR(''2'',16,1);                                
END               
--Validate Reason Active                                     
IF(@Type = 1 OR @Type = 2 OR @Type = 7)  
BEGIN --Convertion Type  Sale  to Other                         
IF(@Qty >@AQty)                                
BEGIN                           
RAISERROR(''3'',16,1);                           
END                           
ELSE                          
BEGIN                          
UPDATE tblProductInventory SET ActualQty = ActualQty - @Qty,InvenoryConvQty = isnull(InvenoryConvQty,0) + (isnull(@Qty,0) * -1) WHERE InventoryId = @InvID                                    
IF(@Type = ''1'')                                    
BEGIN                                    
INSERT INTO dbo.tblProductInventory (BranchID,ProdId,TransID,DocValue,TransDate,RecdFreeQty,ActualFreeQty,BatchNumber,PkdDate,    
ExpiryDate,PurchasePrice,SalesPrice,ECP,MRP,SPLPrice,TaxId ,TaxTypeId , TaxValue ,MRPONPrice,InvenoryConvFreeQty,CBy,CDate)Values (@BranchID,@ProdID,                                    
22,@DocValue,@Date,@Qty,@Qty,(CASE WHEN @BatchNo = '''' THEN NULL ELSE @BatchNo END),@PKD,@Expiry,@PurPrice, @SalePrice, @ECP ,@MRP ,  
@SPL,@TaxID,@TaxTypeID,@TaxValue,@MRPonPrice,@Qty,@CBy,GETDATE())                                    
END                                    
IF(@Type = ''2'')                                    
BEGIN                                    
INSERT INTO dbo.tblProductInventory (BranchID,ProdId,TransID,DocValue,TransDate,RecdDmgQty,ActualDmgQty,BatchNumber,PkdDate,    
ExpiryDate,PurchasePrice,SalesPrice,ECP,MRP,SPLPrice,TaxId ,TaxTypeId , TaxValue ,MRPONPrice,InvenoryConvDmgQty,CBy,CDate)Values (@BranchID,@ProdID,                                    
22,@DocValue,@Date,@Qty,@Qty,(CASE WHEN @BatchNo = '''' THEN NULL ELSE @BatchNo END),@PKD,@Expiry,@PurPrice, @SalePrice, @ECP ,@MRP ,  
@SPL,@TaxID,@TaxTypeID,@TaxValue,@MRPonPrice,@Qty,@CBy,GETDATE())                                    
END                               
END                          
END                          
IF(@Type = 3 OR @Type = 4)                                    
BEGIN  --Convertion Type Free To Other                        
IF(@Qty > @AFQty)                
BEGIN                           
RAISERROR(''3'',16,1);           
END                           
ELSE                          
BEGIN                                
UPDATE tblProductInventory SET ActualFreeQty = ActualFreeQty-@Qty,InvenoryConvFreeQty = isnull(InvenoryConvFreeQty,0) + (isnull(@Qty,0) * -1) WHERE InventoryId = @InvID                                    
IF(@Type = 3)                                    
BEGIN                                   
INSERT INTO dbo.tblProductInventory (BranchID,ProdId,TransID,DocValue,TransDate,RecdQty,ActualQty,BatchNumber,PkdDate,              
ExpiryDate,PurchasePrice,SalesPrice,ECP,MRP,SPLPrice,TaxId ,TaxTypeId , TaxValue,MRPONPrice,InvenoryConvQty,CBy,CDate )Values (@BranchID,@ProdID,                                    
22,@DocValue,@Date,@Qty,@Qty,(CASE WHEN @BatchNo = '''' THEN NULL ELSE @BatchNo END),@PKD,@Expiry,@PurPrice, @SalePrice, @ECP ,@MRP ,@SPL,  
@TaxID,@TaxTypeID,@TaxValue,@MRPonPrice,@Qty,@CBy,GETDATE())                                    
END                                    
IF(@Type = 4)                                    
BEGIN                                    
INSERT INTO dbo.tblProductInventory (BranchID,ProdId,TransID,DocValue,TransDate,RecdDmgQty,ActualDmgQty,BatchNumber,PkdDate,                                    
ExpiryDate,PurchasePrice,SalesPrice,ECP,MRP,SPLPrice,TaxId ,TaxTypeId , TaxValue,MRPONPrice,InvenoryConvDmgQty,CBy,CDate )Values (@BranchID,@ProdID,                                    
22,@DocValue,@Date,@Qty,@Qty,(CASE WHEN @BatchNo = '''' THEN NULL ELSE @BatchNo END),@PKD,@Expiry,@PurPrice, @SalePrice, @ECP ,@MRP ,@SPL,  
@TaxID,@TaxTypeID,@TaxValue,@MRPonPrice,@Qty,@CBy,GETDATE())                           
END                                   
END                              
END                           
IF(@Type = 5 OR @Type = 6)                                    
BEGIN  --Convertion Type Damage to Other                        
IF(@Qty > @ADQty)                                
BEGIN                           
RAISERROR(''3'',16,1);                           
END                           
ELSE                          
BEGIN                                
UPDATE tblProductInventory SET ActualDmgQty = ActualDmgQty-@Qty,InvenoryConvDmgQty = isnull(InvenoryConvDmgQty,0) + (isnull(@Qty,0) * -1) WHERE InventoryId = @InvID                                    
IF(@Type = 5)                           
BEGIN                                    
INSERT INTO dbo.tblProductInventory (BranchID,ProdId,TransID,DocValue,TransDate,RecdQty,ActualQty,BatchNumber,PkdDate,                                    
ExpiryDate,PurchasePrice,SalesPrice,ECP,MRP,SPLPrice,TaxId ,TaxTypeId , TaxValue ,MRPONPrice,InvenoryConvQty,CBy,CDate)Values (@BranchID,@ProdID,                                    
22,@DocValue,@Date,@Qty,@Qty,(CASE WHEN @BatchNo = '''' THEN NULL ELSE @BatchNo END),@PKD,@Expiry,@PurPrice, @SalePrice, @ECP ,@MRP ,  
@SPL,@TaxID,@TaxTypeID,@TaxValue,@MRPonPrice,@Qty,@CBy,GETDATE())                                    
END                                    
IF(@Type = 6)                                    
BEGIN                                    
INSERT INTO dbo.tblProductInventory (BranchID,ProdId,TransID,DocValue,TransDate,RecdFreeQty,ActualFreeQty,BatchNumber,PkdDate,                                    
ExpiryDate,PurchasePrice,SalesPrice,ECP,MRP,SPLPrice,TaxId ,TaxTypeId , TaxValue,MRPONPrice,InvenoryConvFreeQty,CBy,CDate)Values (@BranchID,@ProdID,                                    
22,@DocValue,@Date,@Qty,@Qty,(CASE WHEN @BatchNo = '''' THEN NULL ELSE @BatchNo END),@PKD,@Expiry,@PurPrice, @SalePrice, @ECP ,@MRP ,  
@SPL,@TaxID,@TaxTypeID,@TaxValue,@MRPonPrice,@Qty,@CBy,GETDATE())                                    
END                          
END                          
END                           
SET @ScopeID = SCOPE_IDENTITY()                                      
-- Detail table               
declare @orgConvType int = @Type
set @Type = (case when @Type = 1 OR @Type = 2 OR @Type = 7 then ''Sale'' when @Type = 3 OR @Type = 4 then ''Free'' else ''Damage'' END)  
SET @Qty1=(CASE WHEN  @Type = ''Sale'' THEN @AQty WHEN @Type =''Free'' THEN @AFQty ELSE @ADQty END)                             
SET @GrossAmt1 = @PurPrice * @Qty1                                           

INSERT INTO dbo.tblInventoryDetail(InventoryID,ProdID,UpdatedBatchID,OrgSalePrice,OrgSaleQty,GrossAmt,ReasonId,
 OrgQty,ActualQty,orgFreeQty,ActualFreeQty,OrgDmgQty,ActualDmgQty)                  
VALUES(@HeaderID,@ProdID,@InvID,@PurPrice,@Qty,@GrossAmt1,@ReasonId,
CASE WHEN  @Type = ''Sale'' THEN @Qty1 else 0 end,
CASE WHEN  @Type = ''Sale'' THEN @Qty1 - @Qty else 0 end,
CASE WHEN  @Type = ''Free'' THEN @Qty1 else 0 end,
CASE WHEN  @Type = ''Free'' THEN @Qty1 - @Qty else 0 end,
CASE WHEN  @Type = ''Damage'' THEN @Qty1 else 0 end,
CASE WHEN  @Type = ''Damage'' THEN @Qty1 - @Qty else 0 end)        

INSERT INTO dbo.tblInventoryDetail(InventoryID,ProdID,NewBatchID,OrgSalePrice,OrgSaleQty,GrossAmt,ReasonId,ActualQty,ActualFreeQty,ActualDmgQty)        
VALUES(@HeaderID,@ProdID,(CASE WHEN @Type <> ''Sample'' THEN @ScopeID ELSE @InvID END),@PurPrice,@Qty,@GrossAmt,@ReasonId,
CASE WHEN  @orgConvType in (3,5) THEN @Qty else 0 end,CASE WHEN  @orgConvType in (1,6) THEN @Qty else 0 end,
CASE WHEN  @orgConvType in (2,4) THEN @Qty else 0 end)
END TRY                          
BEGIN CATCH                          
SELECT ERROR_MESSAGE (),ERROR_PROCEDURE (),ERROR_LINE ()                          
END CATCH',
N'[export] readcommittedlock=2';
GO
/****** uspInventoryCopy ******/
EXEC #Apply07 N'dbo.uspInventoryCopy', 0xB022F20302C9A35C4D7D09BF9B8DB958694DC4900AD95A907B311D0B2BCD80BE, NULL, NULL, 0xBE0F897AE73EE906E22A6651262A3029EE2EBDDADE1F052D00BEBEE6CEC7AC98, 0xBD488D94A68073942CCF6996F201AC730C7E75D5CF276F79E37510816FD3E3B3, NULL,
N'--uspInventoryCopy ''2025-04-01'',''2026-10-07'',0,7
ALTER PROC [dbo].[uspInventoryCopy]
@FromDate DATE = ''2025-04-01'',@ToDate date = ''2026-10-07'',@ProdID int = 0,@MfrID int = 0
as
SET NOCOUNT ON;
begin
-- PB ,PR
select * into #rec from (
SELECT GH.TransID,GH.ID,GH.Date AS [Doc Date],GH.BranchID,GD.InventoryId AS [Inventory ID],MfrID,GD.ProdID,
PInv.BatchNumber BatchNumber,PInv.PKDDate AS [PKD Date],PInv.ExpiryDate AS [Expiry Date],
(case when GH.TransID = 1 THEN (GD.AdjQty) ELSE (GD.AdjQty) * -1 END) AS [Sales Qty],
(case when GH.TransID = 1 THEN (GD.AdjDmgQty) ELSE (GD.AdjDmgQty) * -1 END) AS [Free Qty],
(case when GH.TransID = 1 THEN (GD.AdjFreeQty) ELSE (GD.AdjFreeQty) * -1 END) AS [Damage Qty],PInv.PurchasePrice AS [Purchase Price],
(case when GH.TransID = 1 THEN 1 ELSE -1 END) * ((GD.AdjQty) * PInv.PurchasePrice) StockValue,
(case when GH.TransID = 1 THEN 1 ELSE -1 END) * ((GD.AdjDmgQty)* PInv.PurchasePrice) DmgStockValue
FROM tblTransPurchaseHeader AS GH
JOIN tblTransPurchaseDetail AS GD ON GD.HID = GH.ID
JOIN tblProductInventory AS PInv ON PInv.InventoryId = GD.InventoryId
JOIN tblMasterProduct MP ON MP.ID = GD.ProdID
WHERE GH.Status IN (1,3,5,6) AND GH.Date BETWEEN @FromDate AND @ToDate

UNION ALL
--INV
SELECT GH.DocPrefix,GH.ID,GH.InvDate AS [Doc Date],GH.BranchID,GD.InventoryId AS [Inventory ID],MfrID,GD.ProdID,
PInv.BatchNumber BatchNumber,PInv.PKDDate AS [PKD Date],PInv.ExpiryDate AS [Expiry Date],
(GD.AdjustQty) * -1 AS [Sales Qty],(case when QtyType = 2 THEN (GD.AdjustQty) * -1 ELSE 0 END) AS [Free Qty],
0 AS [Damage Qty],PInv.PurchasePrice AS [Purchase Price],
((GD.AdjustQty) * PInv.PurchasePrice) * -1 StockValue,
0 DmgStockValue
FROM tblTranSalesHeader AS GH
JOIN tblTranSalesDetail AS GD ON GD.InvID = GH.ID
JOIN tblProductInventory AS PInv ON PInv.InventoryId = GD.InventoryId
JOIN tblMasterProduct MP ON MP.ID = GD.ProdID
WHERE GH.Status IN (1,3,5) AND DocPrefix = 15 AND GH.InvDate BETWEEN @FromDate AND @ToDate
UNION ALL
--SR
SELECT GH.DocPrefix,GH.ID,GH.InvDate AS [Doc Date],GH.BranchID,GD.InventoryId AS [Inventory ID],MfrID,GD.ProdID,
PInv.BatchNumber BatchNumber,PInv.PKDDate AS [PKD Date],PInv.ExpiryDate AS [Expiry Date],
(GD.AdjustQty) AS [Sales Qty],(case when QtyType = 2 THEN (GD.AdjustQty) ELSE 0 END) AS [Free Qty],
0 AS [Damage Qty],PInv.PurchasePrice AS [Purchase Price],
((GD.AdjustQty) * PInv.PurchasePrice) StockValue,
0 DmgStockValue
FROM tblTranSalesHeader AS GH
JOIN tblTranSalesDetail AS GD ON GD.InvID = GH.ID
JOIN tblProductInventory AS PInv ON PInv.InventoryId = GD.InventoryId
JOIN tblMasterProduct MP ON MP.ID = GD.ProdID
WHERE GH.Status IN (3,6,5) AND GH.DocPrefix = 16 AND GH.TransactionType=2 AND            
GH.InvDate BETWEEN @FromDate AND @ToDate   
UNION ALL
--DR
SELECT GH.DocPrefix,GH.ID,GH.InvDate AS [Doc Date],GH.BranchID,GD.InventoryId AS [Inventory ID],MfrID,GD.ProdID,
PInv.BatchNumber BatchNumber,PInv.PKDDate AS [PKD Date],PInv.ExpiryDate AS [Expiry Date],
0 AS [Sales Qty],0 AS [Free Qty],(GD.AdjustQty) AS [Damage Qty],PInv.PurchasePrice AS [Purchase Price],
0 StockValue,
((GD.AdjustQty) * PInv.PurchasePrice)  DmgStockValue
FROM tblTranSalesHeader AS GH
JOIN tblTranSalesDetail AS GD ON GD.InvID = GH.ID
JOIN tblProductInventory AS PInv ON PInv.InventoryId = GD.InventoryId
JOIN tblMasterProduct MP ON MP.ID = GD.ProdID
WHERE GH.Status IN (3,5,7) AND GH.DocPrefix = 16 AND GH.TransactionType=3 AND            
GH.InvDate BETWEEN @FromDate AND @ToDate   
UNION ALL
--INVT ADJ OLD BATCH
SELECT InvH.TransID,InvH.InventoryID ,InventoryDate,InvH.BranchID,InvD.UpdatedBatchID,MfrID,InvD.ProdID,
PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,            
-InvD.OrgQty Qty,-InvD.OrgFreeQty Free,-InvD.OrgDmgQty Dmg,PInv.PurchasePrice ,
-InvD.OrgQty *PInv.PurchasePrice StockValue,
((-OrgDmgQty) * PInv.PurchasePrice)  DmgStockValue
FROM tblInventoryDetail AS InvD            
JOIN tblInventoryHeader AS InvH ON InvD.InventoryID=InvH.InventoryID            
JOIN tblProductInventory AS PInv ON PInv.InventoryId = InvD.UpdatedBatchID    
JOIN tblMasterProduct MP ON MP.ID = InvD.ProdID
WHERE InvH.TransID=13 AND InvH.Status = 1 AND InvH.InventoryDate BETWEEN @FromDate AND            
@ToDate 
UNION ALL
--INVT ADJ NEW BATCH
SELECT InvH.TransID,InvH.InventoryID ,InventoryDate,InvH.BranchID,InvD.UpdatedBatchID,MfrID,InvD.ProdID,
PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,            
InvD.ActualQty,InvD.ActualFreeQty,InvD.ActualDmgQty,PInv.PurchasePrice ,
InvD.ActualQty *PInv.PurchasePrice StockValue,
((InvD.ActualDmgQty) * PInv.PurchasePrice)  DmgStockValue
FROM tblInventoryDetail AS InvD            
JOIN tblInventoryHeader AS InvH ON InvD.InventoryID=InvH.InventoryID            
JOIN tblProductInventory AS PInv ON PInv.InventoryId = InvD.NewBatchID    
JOIN tblMasterProduct MP ON MP.ID = InvD.ProdID
WHERE InvH.TransID=13 AND InvH.Status = 1 AND InvH.InventoryDate BETWEEN @FromDate AND            
@ToDate 
UNION ALL
-- Get Inventory Conversion Old Batch Details -            
SELECT InvH.TransID,InvH.InventoryID ,InventoryDate,InvH.BranchID,InvD.UpdatedBatchID,MfrID,InvD.ProdID,PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,            
(CASE WHEN InvH.ConvertionTypeId=1 OR InvH.ConvertionTypeId=2 OR InvH.ConvertionTypeId=7 THEN -InvD.OrgSaleQty END) AS OrgQty,            
(CASE WHEN InvH.ConvertionTypeId=3 OR InvH.ConvertionTypeId=4 THEN -InvD.OrgSaleQty END) AS OrgFreeQty,            
(CASE WHEN InvH.ConvertionTypeId=5 OR InvH.ConvertionTypeId=6 THEN -InvD.OrgSaleQty END) AS OrgDmgQty,            
PInv.PurchasePrice,
(CASE WHEN InvH.ConvertionTypeId=1 OR InvH.ConvertionTypeId=2 OR InvH.ConvertionTypeId=7
THEN -InvD.OrgSaleQty ELSE 0 END)  * PInv.PurchasePrice   StockValue ,
(CASE WHEN InvH.ConvertionTypeId=5 OR InvH.ConvertionTypeId=6 THEN -InvD.OrgSaleQty END)* PInv.PurchasePrice   DmgStockValue 
FROM tblInventoryDetail AS InvD            
JOIN tblInventoryHeader AS InvH ON InvD.InventoryID=InvH.InventoryID            
JOIN tblProductInventory AS PInv ON PInv.InventoryId = InvD.NewBatchID --UpdatedBatchID    
JOIN tblMasterProduct MP ON MP.ID = InvD.ProdID
WHERE InvH.TransID=22 AND InvH.Status = 1 AND InvH.InventoryDate BETWEEN @FromDate AND     
@ToDate     
UNION ALL
-- Get Inventory Conversion New Batch Details +            
SELECT InvH.TransID,InvH.InventoryID ,InventoryDate,InvH.BranchID,InvD.NewBatchID,MfrID,InvD.ProdID,PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,            
(CASE WHEN InvH.ConvertionTypeId=3 OR InvH.ConvertionTypeId=5 THEN InvD.OrgSaleQty END) AS ActQty,            
(CASE WHEN InvH.ConvertionTypeId=1 OR InvH.ConvertionTypeId=6 THEN InvD.OrgSaleQty END) AS ActFreeQty,            
(CASE WHEN InvH.ConvertionTypeId=2 OR InvH.ConvertionTypeId=4 THEN InvD.OrgSaleQty END) AS ActDmgQty,            
PInv.PurchasePrice,
(CASE WHEN InvH.ConvertionTypeId=3 OR InvH.ConvertionTypeId=5 THEN InvD.OrgSaleQty END) * PInv.PurchasePrice StockValue,
(CASE WHEN InvH.ConvertionTypeId=2 OR InvH.ConvertionTypeId=4 THEN InvD.OrgSaleQty END) * PInv.PurchasePrice DmgStockValue
FROM tblInventoryDetail AS InvD            
JOIN tblInventoryHeader AS InvH ON InvD.InventoryID=InvH.InventoryID            
JOIN tblProductInventory AS PInv ON PInv.InventoryId = InvD.NewBatchID  
JOIN tblMasterProduct MP ON MP.ID = InvD.ProdID
WHERE InvH.TransID=22 AND InvH.Status = 1 AND InvH.InventoryDate BETWEEN @FromDate AND            
@ToDate ) as rec

select * from #rec where (isnull(@ProdID,0) = 0 or ProdID = @ProdID) and 
(isnull(@MfrID,0) = 0 or MfrID = @MfrID) 
order by [Doc Date]
drop table #rec
end',
N'[export] nocount';
GO
/****** uspInvoiceBody ******/
EXEC #Apply07 N'dbo.uspInvoiceBody', 0x9D85B2C85D3B0958DE18590C257DD2561EBFC11B1E1A54AC27DE279104EA274D, NULL, NULL, 0x267A3816362F8A8E4F18669D09BF7C138C35A6430624672BE9C646E7C9022572, 0x08A880CC2B5A743EB6A863D48F0879BCDAE53599991E937232F7E39CFBBB344B, NULL,
N'--[uspInvoiceBody] 1109,0                   
--SELECT * FROM tblTranSalesHeader ORDER BY 1 DESC              
ALTER PROC [dbo].[uspInvoiceBody]                                 
@InvId NVARCHAR(255)=NULL,                                                                                                                        
@Cond SMALLINT =NULL                                                                                                                        
AS                      
SET NOCOUNT ON;
BEGIN                                        
--DECLARE @InvId INT = 6730                                                              
CREATE TABLE #TempBaseQty (ProdID INT, BaseQty DECIMAL (25,6),SerialNo INT)                                                                                                    
INSERT INTO #TempBaseQty                                                                  
SELECT ProdId,SUM(AdjustQty) AS [AdjustQty],Serial FROM tblTranSalesDetail                                                                                                    
WHERE InvId = @InvId                                                              
GROUP BY ProdId,Serial                                                                  
ORDER BY Serial                                                                  
declare @oby NVARCHAR(10) = 0--(SELECT AppValue FROM tblAppConfig WHERE AppId = 167)                                
SELECT ProdID,Serial [Temp Serial],(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],                                  
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],                                  
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],                                  
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],                                  
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],                                  
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],                                  
SUM([GCESS Amount]  + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #Tax                                                      
FROM                                                                    
(                          
SELECT SRI.ProdID,SRI.Serial,--SRI.[Gross Amount],                                                                
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],                    
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],                                                                    
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],                    
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],                                                                    
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],                    
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],                    
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],                    
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],                    
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],                    
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],                            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],                    
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],                                     
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],                    
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],                      
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],                                                        
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]                                   
FROM                                                                    
(                          
SELECT * FROM                          
(                          
SELECT Temp.ProdID,Temp.Serial,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],                                                                    
Temp.TaxName AS TaxName,                                                  
SUM(Temp.TaxValue) AS [TaxValue]--, SUM(Temp.[Gross Amount]) AS [Gross Amount]                                                                
FROM                                                                    
(                                                                    
SELECT GSTInfo.ProdID,GSTInfo.SERIAL,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,                                                          
CASE                                                            
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''                                                             
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''                                                                    
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''                                                          
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''                                   
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''                                                 
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''                                                  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''                                   
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''                                                            
END AS [GST Comp]--, GSTInfo.GrossAmt AS [Gross Amount]                          
FROM tblTransGSTInfo AS GSTInfo                          
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID                          
WHERE TransIdentID=@InvId AND (TransID=15 or TransID=16)                          
) Temp                          
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.ProdID,Temp.Serial                                                      
) src                          
PIVOT                                                                    
(                                                                    
SUM([TaxValue])                                                                    
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])                                                                
 
     
) piv                                                             
) AS SRI                                                                    
) AS RAM                                                            
GROUP BY ProdID,Serial--,[CGST %]                  
--ORDER BY RAM.[CGST %] ASC                                                           
                                                              
--SELECT GST.TransID,TransIdentID,GST.ProdId,GST.Serial,GST.TaxId,GST.TaxTypeID,GST.GSTTaxTypeID,GST.TaxCompPern,GST.TaxValue FROM tblTranSalesDetail SD                                                      
--JOIN tblTransGSTInfo GST ON GST.TransIdentID = SD.InvId                                                              
--WHERE SD.InvId = 6730                                                         
                                                               
SELECT IDENTITY (INT, 1, 1) AS NEW_ID,PROD.ID ProdID,prod.Code AS [Product Code],prod.Name AS [Product Name],prod.HSNCode AS [HSN Code],                                                                  
Loc.Name AS [Location Name],prod.RemarkS AS [Remark1],prod.WebOrder AS [Web Order],                                        
'''' AS [Uom Group Name],INV.BaseQty AS [Base Qty],Sales.UomQty AS [Uom Qty],                            
(INV.BaseQty / prod.SalesCR) AS [Deft_S_UOM_Qty],                                                                  
Uom.Name AS [Uom Name],(Sales.UomPrice / prod.BaseCR) AS [Base Uom Price],                                                                  
Sales.UomPrice AS [Uom Price],prod.SalesCR AS [UOM CF],                                                                  
prod.SalesCR AS [Deft_S_UOM_CF],                                                                  
Sales.UomPrice + (Sales.UomPrice * (Sales.TaxValue / 100)) as [Rate],                                                                  
Sales.GrossAmt / Sales.UomQty as [Per Piece Exclusive Price],                                                                  
Sales.NetAmt / Sales.UomQty as [Per Piece Inclusive Price],                                                                  
--Case when (prod.TrackInventory = 0)then  (prod.MRP) ELSE (ProdInv.MRPONPrice) end As [MRP Price],                                                                  
Sales.DetailMRP As [MRP Price],MT.TaxName [Tax Name],                          
Sales.GoodsAmt AS [Goods Amount],0 AS [User Discount Percnt],                                                                  
0 AS [User Discount Amt],                                                                  
CAST(dbo.fnGetRoundedValue(0) AS NVARCHAR(255))+''%'' AS [UserDisc Discount %],                                                                  
Sales.ProdDisc AS [Product Discount Percnt],((Sales.GoodsAmt) * (Sales.ProdDisc) /100) as [Product Disc Amt],                                                                  
CAST(dbo.fnGetRoundedValue(ProdDisc) AS NVARCHAR(255))+''%'' AS [Product Discount %],                                                                  
Sales.TradeDisc AS [Trade Discount],Sales.AddnlDisc AS [Addnl Discount],                                                                  
(ISNULL(((Sales.GoodsAmt) *(1)/100),0)+ISNULL(((Sales.GoodsAmt) * (Sales.ProdDisc) /100),0)+ISNULL(Sales.TradeDisc,0)+ISNULL(Sales.AddnlDisc,0)) AS [Total Disc Amt],                                                                        
Sales.GrossAmt AS [Gross Amount],Sales.TaxValue AS [Tax percentage],Sales.TaxAmt AS [Tax Amount],                                                                                                                          
Sales.NetAmt AS [Net Amount],Sales.Serial  AS [Serial],Sales.IdentID Ident,              
'''' AS [ProdSerial],ROW_NUMBER() OVER (ORDER BY Sales.IdentID) AS [Serial No],                                                                                              
Header.DocPrefix AS [Doc Prefix],                          
prod.PLName [PL_Prod_Name],ISNULL(UDFDocId,DocId) DocId,'''' AS SR,TransactionType,         
1 [UOM 1 Qty CF],PROd.ReportingQty [Rep UOM CF],ProdInv.BatchNumber [Batch No]              
,Convert(nvarchar,ProdInv.PkDDate,103) [PKD Date],Convert(nvarchar,ProdInv.ExpiryDate,103) [EXP Date],            
dbo.fngetMRPonTaxValue(1,0,Sales.DetailMRP,Sales.TaxId,Header.TaxTypeId) MRPOnValue,          
dbo.fngetMRPonTaxValue(2,0,Sales.DetailMRP,Sales.TaxId,Header.TaxTypeId) MRPOnTaxAmt                    
INTO #Temp                          
FROM dbo.tblTranSalesDetail AS Sales                          
JOIN tblTranSalesHeader AS Header ON Header.Id =Sales.InvId                          
LEFT JOIN tblMasterProduct AS prod ON prod.ID=Sales.ProdId                          
join tblMasterTax MT ON MT.TaxID = Sales.TaxId                          
LEFT JOIN tblMasterLocation AS Loc ON Loc.Id=prod.LocationId                                       
JOIN dbo.tblMasterUom AS Uom ON Uom.ID = Sales.UomId                                                                                  
LEFT JOIN dbo.tblProductInventory AS ProdInv ON Sales.InventoryId = ProdInv.InventoryId                                                                  
LEFT JOIN #TempBaseQty AS INV ON INV.ProdID = Sales.ProdId AND INV.SerialNo = Sales.Serial                                                                                        
WHERE Sales.InvId = @InvId                                         
--ORDER BY Serial                                      
 ORDER BY (CASE WHEN @oby = ''0'' THEN Serial END) asc,                                
(CASE WHEN @oby = ''1'' THEN prod.Name END) asc                                                         
ALTER TABLE #Temp DROP COLUMN Ident                                                         
--Get Product with Ide                                                                                         
                                                               
SELECT [Product Code],[Product Name],[HSN Code],[Location Name],[Remark1],[Web Order],[Uom Group Name],[Base Qty],[Uom Qty],CONVERT(int,round([Uom Qty],0,0)) [UOM Qty (RD)],[Deft_S_UOM_Qty],              
[Uom Name],[Base Uom Price],[Uom Price],[UOM CF],[Deft_S_UOM_CF],[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price]                                                      
,[MRP Price],CONVERT(int,round([MRP Price],0,0)) [MRP Price (RD)],[Goods Amount],[User Discount Percnt],[User Discount Amt],[UserDisc Discount %],[Product Discount Percnt],                                                      
[Product Disc Amt],[Product Discount %],[Trade Discount],[Addnl Discount],[Total Disc Amt],[Gross Amount],                                                      
[Tax Name],[Tax percentage],[Tax Amount],[Net Amount],[Serial],[ProdSerial],NEW_ID AS [Serial No],[Doc Prefix],DocId,SR,TransactionType,                                            
dbo.fnGetRoundedValue(sum(t2.[CGST %])) [CGST %],dbo.fnGetRoundedValue(sum(t2.[CGST Amount])) [CGST Amount],                                                
dbo.fnGetRoundedValue(sum(t2.[SGST %])) [SGST %],                                                      
dbo.fnGetRoundedValue(sum(t2.[SGST Amount])) [SGST Amount],                                                      
dbo.fnGetRoundedValue(sum(t2.[UTGST %])) [UTGST %],dbo.fnGetRoundedValue(sum(t2.[UTGST Amount])) [UTGST Amount],                                                
dbo.fnGetRoundedValue(sum(t2.[GCESS %])) [GCESS %], dbo.fnGetRoundedValue(SUM(t2.[GCESS Amount])) [GCESS Amount],                                                
dbo.fnGetRoundedValue(sum(t2.[IGST %])) [IGST %],                                                      
dbo.fnGetRoundedValue(sum(t2.[IGST Amount])) [IGST Amount],                                          
dbo.fnGetRoundedValue(sum(t2.[ICESS %])) [ICESS %],dbo.fnGetRoundedValue(sum(t2.[ICESS Amount])) [ICESS Amount],                                  
dbo.fnGetRoundedValue(sum(t2.[GUOM %])) [GUOM %],dbo.fnGetRoundedValue(sum(t2.[GUOM Amount])) [GUOM Amount],                                  
dbo.fnGetRoundedValue(sum(t2.[IUOM %])) [IUOM %],dbo.fnGetRoundedValue(sum(t2.[IUOM Amount])) [IUOM Amount],                                  
dbo.fnGetRoundedValue(sum(t2.[Cumulative CESS Amount])) [Cumulative CESS Amount],0 [Def 0 Value],                    
convert(int,FLOOR([Base Qty] / NULLIF([UOM 1 Qty CF],0))) [UOM 1 Qty (RD)] ,              
convert(int,FLOOR([Base Qty]-(FLOOR([Base Qty]/NULLIF([UOM 1 Qty CF],0))*[UOM 1 Qty CF]))) [UOM 1 B Qty (RD)],                    
convert(int,FLOOR([Base Qty] / NULLIF([Rep UOM CF],0))) [Rep Qty (RD)] ,              
convert(int,FLOOR([Base Qty]-(FLOOR([Base Qty]/NULLIF([Rep UOM CF],0))*[Rep UOM CF]))) [Rep B Qty (RD)],        
dbo.fnGetRoundedValue(MRPOnValue) MRPOnValue,dbo.fnGetRoundedValue(MRPOnTaxAmt) MRPOnTaxAmt,[Batch No],[PKD Date],[EXP Date],
[PL_Prod_Name]
FROM #Temp t1                                                      
left join #Tax t2 on t2.ProdID = t1.ProdID and t1.[Serial No] = t2.[Temp Serial]                                          
GROUP BY [Product Code],[Product Name],[HSN Code],[Location Name],[Remark1],[Web Order],[Uom Group Name],[Base Qty],[Uom Qty],[Deft_S_UOM_Qty],                                                      
[Uom Name],[Base Uom Price],[Uom Price],[UOM CF],[Deft_S_UOM_CF],[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price]              
,[MRP Price],[Goods Amount],[User Discount Percnt],[User Discount Amt],[UserDisc Discount %],[Product Discount Percnt],                                                      
[Product Disc Amt],[Product Discount %],[Trade Discount],[Addnl Discount],[Total Disc Amt],[Gross Amount],                                                      
[Tax percentage],[Tax Amount],[Net Amount],[Serial],[ProdSerial],[Serial No],[Doc Prefix],[PL_Prod_Name],[UOM 1 Qty CF],[Rep UOM CF],                    
DocId,SR,TransactionType,NEW_ID,[Tax Name],        
MRPOnValue,MRPOnTaxAmt,[Batch No],[PKD Date],[EXP Date]--,[CGST %],[SGST %],[UTGST %],[GCESS %],[IGST %],[ICESS %]                                                      
 --ORDER BY [Serial No] ASC                              
 ORDER BY (CASE WHEN @oby = ''0'' THEN [Serial No] END) asc                              
 ,(CASE WHEN @oby = ''1'' THEN [Product Name] END) asc                              
 IF ISNULL(@Cond,0)=0                              
BEGIN                              
ALTER TABLE #Temp DROP COLUMN Serial                              
ALTER TABLE #Temp DROP COLUMN [ProdSerial]                              
ALTER TABLE #Temp DROP COLUMN [SR]                              
END                              
--SELECT * FROM #ORGTBL                                
--ORDER BY (CASE WHEN @oby = ''0'' THEN #ORGTBL.[Serial No] END) asc,                                
--(CASE WHEN @oby = ''1'' THEN #ORGTBL.[Product Name] END) asc                                
DROP TABLE #Temp--,#ORGTBL                                
DROP TABLE #TempBaseQty,#Tax                              
END',
N'[export] nocount';
