/****** uspInvoiceHeader ******/
EXEC #Apply07 N'dbo.uspInvoiceHeader', 0x7F51C0429D03B2EA3F8BA2919665BC5D26BC270C8E121627D8683458E2D8894B, NULL, NULL, 0xC9713767D198A926A944B93450B36C09C02FECF1309DCDECB904C862353871DF, 0x1863EC2FFD23CB645DC7027EB73545BDD3D47E43F67DA519BE45C45B241F8FA2, NULL,
N'--uspInvoiceHeader 140                                                  
ALTER PROC [dbo].[uspInvoiceHeader]                                                  
@IdentID INT =NULL                                    
AS                                    
SET NOCOUNT ON;
BEGIN                                    
declare @UPIID NVARCHAR(255) = (SELECT ISNULL(AppValue,'''') FROM tblAppConfig WHERE AppId = 15)        
declare @UPIName NVARCHAR(255) = (SELECT ISNULL(AppValue,'''') FROM tblAppConfig WHERE AppId = 16)     
-- Total Saving----------------                                    
Declare @TotalSaving DECIMAL(25,6) =                                                  
(select Sum((((MRP/MRPCF)*SelectedCF) - Rate)*qty)  as Diff From (select Case when (prod.TrackInventory = 0) then (prod.MRP) ELSE (ProdInv.MRPONPrice) end As MRP,                                                  
(detail.NetAmt / detail.UomQty) as Rate, detail.UomQty as qty, prod.SalesCR as SelectedCF,                                                  
prod.SalesCR as MRPCF From dbo.tblTranSalesDetail as detail                                                  
join dbo.tblProductInventory as prodinv on prodinv.InventoryId = detail.InventoryId                    
JOIN tblMasterProduct AS prod ON prod.ID=detail.ProdId                    
where InvId = @IdentID)as Fin)                                       
DECLARE @PGross DECIMAL(25,6),@PTaxAmt DECIMAL(25,6),@PNetAmt DECIMAL(25,6),@PGoodsAmt DECIMAL(25,6),@PSQty DECIMAL(25,2)                    
SELECT @PGoodsAmt = SUM(ISNULL((GoodsAmt),0)),@PGross = SUM(ISNULL((GrossAmt),0)),@PTaxAmt = SUM(ISNULL(TaxAmt,0)),                      
@PNetAmt = SUM(ISNULL(NetAmt,0)),@PSQty = SUM(ISNULL(UomQty,0))                      
FROM tblTranSalesDetail Sales WHERE InvId = @IdentID                     
                    
DECLARE @AdjQty DECIMAL(25,6),@UOMQty DECIMAL(25,6),@UOMCF DECIMAL(25,6),@RepCF DECIMAL(25,6),@SU1BQTY INT = 0,                      
@SU1QTY INT = 0,@REPU1BQTY INT = 0,@REPU1QTY INT = 0                    
                    
SELECT IDENTITY(INT,1,1) AS ID,Sales.ProdId,SUM(Sales.AdjustQty) AdjustQty,sum(Uomqty) UomQty,          
prod.SalesCR UOMCF,prod.ReportingCR REPUOMCF INTO #DPROD           
FROM tblTranSalesDetail Sales                    
LEFT JOIN tblMasterProduct AS prod ON prod.iD=Sales.ProdId  WHERE InvId = @IdentID --AND TaxId > 0                    
group by Sales.ProdId,prod.ReportingCR,prod.SalesCR          
                    
                    
DECLARE @CF DECIMAL(25,6),@nCount INT,@nInt INT = 1,@ProdID INT                    
SET @nCount = (SELECT COUNT(*) FROM #DPROD)                    
WHILE(@nCount >= @nInt)                    
BEGIN                    
SELECT  @SU1QTY = @SU1QTY + convert(int,FLOOR(AdjustQty / nullif(UOMCF,0))),@SU1BQTY = @SU1BQTY + convert(int,FLOOR(AdjustQty-(FLOOR(AdjustQty/UOMCF)*UOMCF))),                    
@REPU1QTY = @REPU1QTY + convert(int,FLOOR(AdjustQty / nullif(REPUOMCF,0))),@REPU1BQTY = @REPU1BQTY + convert(int,FLOOR(AdjustQty-(FLOOR(AdjustQty/REPUOMCF)*REPUOMCF)))  FROM #DPROD WHERE ID = @nInt                    
SET @nInt = @nInt + 1;                    
END                    
--SELECT @SU1QTY SU1QTY,@SU1BQTY SU1BQTY,@REPU1QTY REPU1QTY,@REPU1BQTY REPU1BQTY                    
DROP TABLE #DPROD                       
                    
--Payment Mode Name--------------                                                  
Declare @InvPaymode nvarchar(1000)                    
                    
Select @InvPaymode = Coalesce (@InvPaymode + '', '', '''') + mode.PaymentMode From dbo.tblTran_Sale_Bill_PaymentDetail as BS                    
left Join dbo.tblPaymentMode as mode on mode.Id = BS.PayModeId                    
where InvId = @IdentID and TransId = 15 Group by mode.PaymentMode                    
                                                  
--Cash Balance-----                                                  
DeClare @Amt DECIMAL(25,6), @Recdamt DECIMAL(25,6)                                                  
Select @Amt=SUM(Amt),@Recdamt = SUM(RecdAmt)  From dbo.tblTran_Sale_Bill_PaymentDetail as BS                                                  
where InvId = @IdentID  and TransId = 15                    
                    
Select Inv.Id As [Inv ID],convert (nvarchar,Inv.InvDate,103) as [Doc Date],Isnull(CONVERT(nvarchar(5),Inv.MDate,108),CONVERT(nvarchar(5),Inv .CDate,108)) as [Time],                    
Doc.TransName as [Trans Name],Inv.DocId as [Doc ID],UDN.DocName AS [UDN Name],Inv.UDFDocId AS [UDN Doc ID],                       
Beat.Name as [Beat Name],SM.Name as [Salesman Name],SM.MobileNo as [Salesman Mobile No],                                   
Cust.code as [Party Code],Cust.Name as [Party Name],                                                         
Cust.mob1 as [Party Prim Mobile No],Cust.ph1 as [Party Prim Phone No],Cust.Email as [Email ID],Cust.ContactPerson as [Contact Person],                                                  
Cust.billadd1 AS [Party Bill Address 1],Cust.billadd2 as [Party Bill Address 2],Cust.billadd3 as [Party Bill Address 3],                                    
Cust.billadd1+Cust.billadd2+Cust.billadd3 as [Party Full Address],                                    
Cust.shipadd1 AS [Party Ship Address 1],Cust.shipadd2 as [Party Ship Address 2],Cust.shipadd3 as [Party Ship Address 3],                                    
'''' AS [Party Area Name],cust.Pincode as [Party PinCode],'''' AS [Party Tin No],'''' AS [Party CST No],                                                  
NULL as [Party CST Date],Cust.GSTIN AS [Party GSTIN],GSTST.StateName [GST State Name],              
GSTST.TINNo [GST State Code],Cust.AadharNo AS [Party Aadhar Number],                                                  
Cust.PANNumber AS [Party PAN No],'''' AS [Party ServiceTax No],Cust.FSSAINo AS [Party FSSAI No],TaxType.TaxTypeName AS [Party TaxType],                                                  
PriceType.PriceType as [Price Type],Cust.OSValue AS [Party Outstanding value],cust.ClosingTrackPoint [Reward Points],Tax.TaxTypeName as [TaxType Name],                                    
--Invpaymode.PaymentMode as [Payment Mode],                                    
isnull(@InvPaymode,''CREDIT'') as [Payment Mode],                                    
--InvCreditTerm.CreditName as [CreditTerm Name],                                    
CONVERT (nvarchar,Inv.CreditDate,103) AS [CreditTerm Date],                                    
--PGrp.ProductGroupName as [Product Group Name],                                                  
Inv.DocRef as [Doc Ref],SUM(Detail.UomQty) As [Total Qty],                                    
SUM(Detail.AdjustQty / Prod.SalesCR) As [Deft_S_UOM_Total_Qty],                                
Inv.TradeDisc as [Trade Discount Percentage],Inv.AdditionalDisc as [Addnl Discount Percentage],                                                  
Inv.Frieght as [Frieght Amount],                                                  
Inv.OtherCharge as [OtherCharge Percentage],Inv.OtherChargeAmt as [OtherCharge Amount],                                    
Inv.CreditNoteAdjAmt as [Adjust Amount],0 as [T.User Discount Amount],                                    
Inv.TotalTradeDiscAmt as [T.Trade Discount Amount],Inv.TotalProdDiscAmt AS [T.Product Discount Amount],                                    
Inv.AdditionalDiscAmt as [T.Addnl Discount Amount],Inv.TotalDiscountAmt as [T.Discount Amount],            
dbo.fnGetRoundedValue(Inv.AdditionalDiscAmt)+'' (''+dbo.fnGetRoundedValue(Inv.AdditionalDisc)+''%)'' [Addnl Disc Pern Amt],        
dbo.fnGetRoundedValue(Inv.TotalTradeDiscAmt)+'' (''+dbo.fnGetRoundedValue(Inv.TradeDisc)+''%)''[Trade Disc Pern Amt],        
@TotalSaving AS [Total Saving Amount],(ISNULL(Inv.GrossAmt,0) + ISNULL(TotalDiscountAmt,0)) AS [Goods Amount],                                    
Inv.GrossAmt as [T.Gross Amount],Inv.TotalTaxAmt as [T.Total Tax Amount],Inv.RoundOfAmt as [Round Off Amount],                                    
Inv.NetAmt+(@Recdamt-@Amt) as [Received Amount],Inv.Balance AS [Balance Amount],@Recdamt-@Amt as [Cash Balance],                                    
Inv.NetAmt as [Rounded Net Amount],(inv.NetAmt - Inv.CreditNoteAdjAmt) AS [Aft Adj NetAmt],                                                  
[dbo].[fnConvertAmountinWords](Inv.NetAmt) AS [Amt_in_Words],UserTab.username as [User Name],         
null[PO Date],'''' [PO Doc Ref],                              
--'''' AS [Tax Value],'''' AS [Tax Percentage],'''' AS [Tax Amount] ,'''' AS [Doc Prefix],    
convert(nvarchar(255),MAX(Detail.Serial)) + '' / '' + convert(nvarchar(255),dbo.fnGetRoundedValue(SUM(Detail.UomQty))) as [Tot Count Qty],                                    
CH.VisaPern as [Visa %],((Inv.NetAmt * CH.VisaPern) / 100) AS [Visa Amt],(Inv.NetAmt + ((Inv.NetAmt * CH.VisaPern) / 100)) as [All Incl],                                  
Inv.TCSTaxPern [TCS %],TCSTaxAmt [TCS Amt],IRN,AckNo,AckDate,AckStatus,SignedQRCode,''B2B'' SupplyType,isnull(TDSAmount,0) TDSAmount,EWBNo,                                  
vh.VehicleNo,Inv.Distance,TransMode [Transport Mode],VehicleType [Vehicle Type],TransportID [Transport ID],TransportName [Transport Name],                          
0 [Def 0 Value],dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(Inv.GrossAmt)) [Gross Amt (WC)],dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(Inv.TotalTaxAmt)) [Total Tax Amt (WC)],                        
dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(Inv.NetAmt - RoundOfAmt - Inv.OtherChargeAmt - Inv.TotalDiscountAmt)) [Net Amt For TCS (WC)],                        
dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(Inv.NetAmt)) [Net Amt (WC)],@PGoodsAmt [PS Goods],@PGross [PS Gross],@PTaxAmt [PS Tax],                        
dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(@PNetAmt)) [PS Net Amt (WC)],CONVERT(int,round(@PSQty,0,0)) [PS UOM Qty (RD)],                        
dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(@PGoodsAmt)) [PS Goods (WC)],                    
@SU1QTY [Total UOM 1 Qty (RD)],@SU1BQTY [Total UOM 1 B Qty (RD)],@REPU1QTY [Total Rep Qty (RD)],@REPU1BQTY [Total Rep B Qty (RD)],  
Inv.DocId AS [Document ID],Inv.DocId+''/''+CONVERT(nvarchar,Inv.InvDate,104)+''/''+Cust.Name UPItn,        
dbo.fnGetRoundedValue(Inv.NetAmt) QRAmt,@UPIID UPIID,@UPIName UPIName,Cust.PLName [PL_Customer Name],Cust.PLBillAdd1 [PL_Bill_Address1],                                    
Cust.PLBillAdd2 [P_Bill_Address2],Cust.PLBillAdd3 [P_Bill_Address3],Cust.PLContactPerson [P_Cont Person],
Beat.PLName [P_Beat_Name],SM.PLName [P_SalesmanName]   
From dbo.tblTranSalesHeader as Inv                                                  
Join dbo.tblTranSalesDetail as Detail on Detail.InvId = Inv.ID                                    
left JOIN tblTranCollectionDetail CD ON CD.DocID = Inv.ID AND CD.DocPrefix = Inv.DocPrefix                                                  
left JOIN tblTranCollectionHeader CH ON CH.ColID = CD.ColID                                                  
LEFT JOIN tblMasterProduct AS Prod ON Prod.ID = Detail.ProdId                                                  
join dbo.tblDocumentSeries AS Doc ON Inv. DocPrefix = Doc.TransID                                                  
Join dbo.tblMasterCustomer as Cust ON Inv.CustId = Cust.ID                                                  
Join dbo.tblMasterTaxType as Tax on Inv.TaxTypeId = Tax.TaxTypeID                                                  
Left JOIN tblMasterUserDefineNoHeader AS UDN ON UDN.UDNId=Inv.UDFId                                                                      
--Left Join dbo.tblA as Area on Area.GeoID = Cust.areaid          
Left Join dbo.tblMasterTaxType as TaxType on TaxType.TaxTypeID = Cust.taxtypeid                                                  
Join dbo.tblUsers as UserTab on UserTab.ID = Inv.MBy or UserTab.ID  = Inv.Cby                                                  
Left Join tblMasterBeat as Beat on Beat.ID = Inv.BeatID                                                  
Left Join tblMasterSalesMan as SM on SM.ID = Inv.SalesManId                               
Left Join dbo.tblPriceType as PriceType on PriceType.Id = Cust.PriceTypeID                                                     
LEFT join tblMasterVehicle vh on vh.ID = Inv.VehicleNo                                        
LEFT JOIN tblGSTStateNameandCode GSTST ON GSTST.StateID = Cust.StateID              
WHERE  Inv.Id = @IdentID  AND Inv.DocPrefix = 15                                    
Group By Inv.Id,Inv.InvDate,Inv.MDate,Inv.CDate,Doc.TransName,Inv.DocId,Inv.DocValue,Beat.Name,SM.Name,                           
SM.MobileNo,Cust.Code,Cust.Name,Inv.UDFDocId,UDN.DocName,Cust.mob1,Cust.mob2,Cust.ph1,Cust.Ph2,Cust.Email,Cust.ContactPerson                                    
,Cust.Billadd1,Cust.Billadd2,Cust.Billadd3,Cust.shipadd1,Cust.shipadd2,Cust.Shipadd3                                    
,cust.Pincode,Cust.PANNumber,Cust.Fssaino,TaxType.TaxTypeName,                                    
PriceType.PriceType,Cust.OSValue,Cust.GSTIN,Cust.AadharNo,Tax.TaxTypeName,Inv.CreditDate,                                    
Inv.DocRef,Inv.TradeDisc,Inv.AdditionalDisc,Inv.Frieght,                                   
Inv.OtherCharge,Inv.OtherChargeAmt,Inv.CreditNoteAdjAmt,Inv.TotalTradeDiscAmt,                                    
Inv.TotalProdDiscAmt,Inv.AdditionalDiscAmt,Inv.TotalDiscountAmt,Inv.GrossAmt,Inv.TotalTaxAmt,Inv.RoundOfAmt,                                    
Inv.RecievedAmt,Inv.Balance,Inv.NetAmt,UserTab.username,(inv.NetAmt - Inv.CreditNoteAdjAmt),                                    
CH.VisaPern,Inv.TCSTaxPern,TCSTaxAmt,IRN,AckNo,AckDate,AckStatus,SignedQRCode,TDSAmount,EWBNo,                                  
vh.VehicleNo,Inv.Distance,TransMode,VehicleType,TransportID,TransportName,cust.ClosingTrackPoint,              
GSTST.TINNo,GSTST.StateName,SignedQRCode,AckNo,EWBNo,
Cust.PLName,Cust.PLBillAdd1,Cust.PLBillAdd2,Cust.PLBillAdd3,Cust.PLContactPerson,Beat.PLName,SM.PLName
END',
N'[export] nocount';
GO
/****** uspInvoiceTrackReportData ******/
EXEC #Apply07 N'dbo.uspInvoiceTrackReportData', 0xAD6C5F7142F22221B35030025A82838D2B4BA6614023BD427B629D3F9E51C4A7, NULL, NULL, 0x47FE46B028990D9E4031D8313A7D9DF0B1B5CCB0250F50EFE1F3F1DFD04D9A64, 0x88133F7D68B9E40847FDDCD6893B0DCF71096729F6C51B828660D45539B96345, NULL,
N'--uspInvoiceTrackReportData 1,0                
ALTER PROC [dbo].[uspInvoiceTrackReportData]                  
@Mode INT,@DocValue int = 1                
AS                  
SET NOCOUNT ON;
BEGIN                  
DECLARE @AssignInvCount INT,@CollectionCount INT,@InvID INT            
IF(@Mode = 1)                  
BEGIN             
/*  
Here @DocValue we taken as ShowAll condition  
*/  
DECLARE @STS AS TABLE(STS INT)    
    
IF(@DocValue = 1)    
INSERT INTO @STS VALUES (1),(3),(5)    
ELSE    
INSERT INTO @STS VALUES (1),(3)    
    
    
select DISTINCT SH.ID DocValue,SH.DocID,MC.Name Customer, (SELECT COUNT(*) FROM tblTranCollectionHeader CH JOIN tblTranCollectionDetail CD ON CD.ColID = CH.ColID AND CH.Status IN (1,3,5)            
WHERE CD.DocID = SH.ID) CollectionCount,      
 (select count(*)  from tblAssignInvoicesDETAIL AD JOIN tblAssignInvoicesHeader AH ON AH.ID = AD.HID AND AH.Status IN (1,3,5)                   
where AD.InvID = SH.ID) AssignInvCount,CONVERT(decimal(15,2),SH.Balance) Balance  from       
tblTranSalesHeader SH       
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID      
where SH.DocPrefix = 15 and SH.status in (SELECT * FROM @STS)    
--SH.status in (1,3,5)     
ORDER BY DocValue            
END            
IF(@Mode = 2)                  
BEGIN             
SET @InvID = @DocValue--(select top 1 ID from tblTranSalesHeader WHERE DocValue = @DocValue AND DocPrefix = 15 order by 1 desc)-- AND Status in (1,3,5)            
            
SET @AssignInvCount = (select count(*) from tblAssignInvoicesDETAIL AD JOIN tblAssignInvoicesHeader AH ON AH.ID = AD.HID AND AH.Status IN (1,3,5)                   
where AD.InvID = @InvID)            
SET @CollectionCount = (SELECT COUNT(*) FROM tblTranCollectionHeader CH JOIN tblTranCollectionDetail CD ON CD.ColID = CH.ColID AND CH.Status IN (1,3,5)            
WHERE CD.DocID = @InvID)            
            
SELECT @InvID InvID,MC.Name PartyName,DocID,FORMAT(InvDate,''dd-MMM-yyyy'') DocDate,(SH.NetAmt) Value,            
(SH.Balance) Balance,STS.Description Status,@AssignInvCount AssignInvCount,@CollectionCount CollectionCount,            
DATEDIFF(DD,InvDate,GETDATE()) Ageing            
FROM tblTranSalesHeader SH            
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID            
join tblStatus STS ON STS.ID = SH.Status            
WHERE DocPrefix = 15 AND SH.ID = @InvID            
END            
IF(@Mode = 3)                  
BEGIN             
SET @InvID =@DocValue-- (select top 1 ID from tblTranSalesHeader WHERE DocValue = @DocValue AND DocPrefix = 15 order by 1 desc)            
            
select DocID,FORMAT(DocDate,''dd-MMM-yyyy'') DocDate,Name Salesman,STS.Description Status from tblAssignInvoicesDETAIL AD JOIN tblAssignInvoicesHeader AH ON AH.ID = AD.HID AND AH.Status IN (1,3,5)              
JOIN tblMasterSalesman SM ON SM.ID = AH.SalesmanID            
JOIN tblStatus STS ON STS.ID = AD.Status            
where AD.InvID = @InvID            
END            
END',
N'[export] nocount';
GO
/****** uspInvoiceVariantData ******/
EXEC #Apply07 N'dbo.uspInvoiceVariantData', 0xD13A6D10089409434FB36E9EEEB11A1D93EF8E1B60FCA29E996B9C02B65D7844, NULL, NULL, 0x4C2980D293B985D8C9D0E97D3E9967ADB2895050DA4C309992C1F3EEDEC8431F, 0x79FC8B6882F6C6B67213DA017A4C03C3D632F4DD103AE3669BF80FF14376F2FA, NULL,
N'--uspInvoiceVariantData 4,759,262
ALTER proc [dbo].[uspInvoiceVariantData]
@VariantTypeID int = 4, @ID int = 759,@PartyID int	= 497
as
SET NOCOUNT ON;
begin
DECLARE @PriceType INT,@BeatID int,@SalesmanID int,@FAID INT,@currDocid nvarchar(50)

IF(@VariantTypeID = 4) -- Bill to Invoice
BEGIN
SELECT @PriceType = PriceTypeID,@FAID = FAID FROM tblMasterCustomer WHERE ID = @PartyID
--BEAT SALESMAN
SELECT top 1 @BeatID = BeatID,@SalesmanID = SalesmanID FROM tblBeatSalesmanMapping 
where CustomerID = @PartyID order by ID
--CUSOTMER DETAILS
SELECT ISNULL(@BeatID,0) BeatID,ISNULL(@SalesmanID,0) SalesmanID,(SELECT count(*) FROM tblMasterDiscountSchemeHeader AS SH
JOIN tblMasterDiscountSchemeCustomers AS DISCUS ON DISCUS.ID = SH.ID   
WHERE DISCUS.CustomerID = @PartyID and convert(date,getdate()) between FromDate and ToDate) CustomerSchemeCount,MC.*,
RT.RatingName
FROM tblMasterCustomer MC
 LEFT JOIN tblRatings RT ON RT.ID = MC.Rating  
WHERE MC.ID = @PartyID
--CUSTOMER REMARK
select * from tblMasterCustomerRemarks WHERE CustomerID = @PartyID
--CUSTOMER OS
EXEC uspPartyReportData 2,@FAID,1        
--BILL HEADER DATA
set @currDocid = (SELECT DocPrefix +DocValue FROM tblDocumentSeries WHERE Active = 1 and TransID = 15)          
SELECT PH.ID,convert(date,GETDATE()) Date,15 TransID, PH.BranchID,@currDocid DocID,null DocValue, 
0 BeatID,0 SalesManID, 0 CustomerID,PH.DocID RefNo,0 ProdGroupID,          
0 TaxTypeID,0 PriceID,0 PaymentModeID,0 CreditTermID,Frieght FrightAmt,[OtherCharge%] OtherChrgPern,OtherChargeAmt OtherChargeAmt,          
PH.[TradeDisc%] TradePern, PH.[AddnlDisc%] AddnlPern,PH.TotalProdDiscAmt TotalProdDiscAmt, PH.TotalTradeDiscAmt TradeDiscAmt,
PH.TotalAddnlDiscAmt AddnlDiscAmt,PH.RoundOffAmt RoundOffAmt,PH.GrossAmt GrossAmt,          
PH.TaxAmt TaxAmt,PH.NetAmt NetAmt,PH.Status,0 UDFId,NULL UDFDocId,          
NULL UDFDocPrefix,NULL UDFDocValue,PH.Remarks Remarks,PH.Narration Narration,          
PH.TCSTaxAmt TCSTaxAmt,0 TDSAmount,PH.WriteOffAmt Writeoff,0 VehicleNo,0 Distance,'''' VehicleType,'''' TransMode,'''' TransportID,'''' TransportName,       
DiffValueGross,DiffValueNet,dbo.fnTransactionPrefix(convert(date,GETDATE()),BranchID,15) Prefix,0 AS Balance,null IRN,null AckNo,null AckDate,null AckStatus,null EWBNo,null SignedQRCode          
FROM tblTransPurchaseHeader PH
--LEFT JOIN tblMasterCustomer MV ON MV.ID = @PartyID    
JOIN tblStatus STS ON STS.ID = PH.Status          
JOIN tblMasterBranchOffice MBO ON MBO.ID = PH.BranchID
where PH.ID = @ID          
--BILL Detail(Product) DATA
SELECT PD.ProdID,PD.UomID,MP.Code,MP.Name,UOM.Name UOM,SUM(UomQty) Qty,PD.MRP DetailMRP,
CASE WHEN @PriceType = 1 THEN PD.UomPurchasePrice WHEN @PriceType = 2 THEN PD.UomSalePrice WHEN @PriceType = 3 THEN PD.UomECP
WHEN @PriceType = 4 THEN PD.UomMRP WHEN @PriceType = 5 THEN PD.UomSPLPrice WHEN @PriceType = 6 THEN PD.UomReturnPrice ELSE 0
END ExclPrice,          
dbo.fngetinclusivevalue(PD.TaxID,PD.MRP,(CASE WHEN @PriceType = 1 THEN PD.UomPurchasePrice WHEN @PriceType = 2 THEN PD.UomSalePrice WHEN @PriceType = 3 THEN PD.UomECP
WHEN @PriceType = 4 THEN PD.UomMRP WHEN @PriceType = 5 THEN PD.UomSPLPrice WHEN @PriceType = 6 THEN PD.UomReturnPrice ELSE 0
END)) InclPrice,
PD.[ProdDisc%] ProdPern,pd.ProdDiscAmt,PD.[TradeDisc%] TradePern,TradeDiscAmt,          
PD.[AddnlDisc%] AddnlPern,AddnlDiscAmt,SUM(GrossAmt) GrossAmt,SUM(TaxAmt) TaxAmt,SUM(NetAmt) NetAmt,PD.TaxID,MT.TaxName,PD.[Tax%] TaxPern,          
SUM(GoodsAmt) GoodsAmt,CASE WHEN @PriceType = 1 THEN PD.UomPurchasePrice WHEN @PriceType = 2 THEN PD.UomSalePrice WHEN @PriceType = 3 THEN PD.UomECP
WHEN @PriceType = 4 THEN PD.UomMRP WHEN @PriceType = 5 THEN PD.UomSPLPrice WHEN @PriceType = 6 THEN PD.UomReturnPrice ELSE 0
END BaseUomPrice,PV.BatchNumber BatchNo,PV.PKDDate PKD,PV.ExpiryDate Expiry,MP.TrackInventory,MP.TrackBatch,          
MP.TrackPDK,mp.TrackSerial,ISNULL(PD.DiffAmt,0) DiffValue,ISNULL(PTP.InvoicePrice,0) InvoicePrice ,1 QtyType,          
SUM(dbo.fngetMRPonCumValue(0,PD.TaxID,1,0)) CumMRPonTax,          
SUM(dbo.fngetMRPonCumValue(1,PD.TaxID,1,PD.MRP)) MRPonTaxAmt,MP.Shinecode          
FROM tblTranSPurchasedetail PD          
JOIN tblProductInventory PV ON PV.InventoryId = PD.InventoryID          
JOIN tblMasterProduct MP ON MP.ID = PD.ProdID          
JOIN tblMasterUOM UOM ON UOM.ID = PD.UomID          
JOIN tblMasterTax MT ON MT.TaxID = PD.TaxID          
LEFT JOIN tblProductTransactionprices PTP ON PTP.ID = PD.ProdID          
where PD.HID = @ID          
group by PD.ProdID,PD.UomID,MP.Code,MP.Name,MP.HSNCode,UOM.Name,PD.[ProdDisc%],PD.[TradeDisc%],PD.[AddnlDisc%],Serial,          
MT.TaxName,PD.[Tax%],PD.MRP,CASE WHEN @PriceType = 1 THEN PD.UomPurchasePrice WHEN @PriceType = 2 THEN PD.UomSalePrice WHEN @PriceType = 3 THEN PD.UomECP
WHEN @PriceType = 4 THEN PD.UomMRP WHEN @PriceType = 5 THEN PD.UomSPLPrice WHEN @PriceType = 6 THEN PD.UomReturnPrice ELSE 0
END,PD.TaxID,pd.ProdDiscAmt,AddnlDiscAmt,TradeDiscAmt,MP.Shinecode,          
PV.BatchNumber,PV.PKDDate,PV.ExpiryDate,MP.TrackInventory,MP.TrackBatch,MP.TrackPDK,mp.TrackSerial,PD.DiffAmt,
PTP.InvoicePrice          
ORDER BY Serial      

select ID,Name from tblMasterReason where Active = 1 order by Name

END
end',
N'[export] nocount';
GO
/****** uspItemWiseSalesDetail ******/
EXEC #Apply07 N'dbo.uspItemWiseSalesDetail', 0xF9BFFE32F873E5F52ADC430F7269AE1BBA24FD43F7D5A1BBE85C52AD85917EA2, NULL, NULL, 0x94575D9AD067CE2A75699A07054E02BD7C7138801AD1B9EA719E42DAD4C1867B, 0x04886B91CBC104C4B934A1E7E795BB636228E1AC3A5972C7230ACA61B3FF0388, NULL,
N'ALTER PROCEDURE [dbo].[uspItemWiseSalesDetail]    
@FromDate DATE = ''2025-01-01'',    
@ToDate   DATE = ''2025-12-20'',    
@ProdID INT,    
@BranchID INT    
AS    
SET NOCOUNT ON;
BEGIN    
SELECT  MP.Name [Product Name],  
H.DocID [Doc ID],    
FORMAT(H.InvDate,''dd-MMM-yyy'') [Invoice Date],    
H.DocRef [Doc Ref],    
C.Code [Customer Code],    
C.Name [Customer Name],    
MBO.Name [Branch Name],    
dbo.fnGetRoundedValue(D.AdjustQty) AS [Base Qty],    
MU.Name  [Base UOM],    
dbo.fnGetRoundedValue(SUM( CASE WHEN H.DocPrefix = 15    
THEN ISNULL(D.UomQty,0) * ISNULL(MP.SalesCR,1)    
WHEN H.DocPrefix = 16    
THEN ISNULL(D.UomQty,0) * ISNULL(MP.SalesCR,1) * -1    
END    
)) AS [Sales UOM Qty],    
MS.Name  [Sales UOM],    
dbo.fnGetRoundedValue(SUM( CASE WHEN H.DocPrefix = 15    
Then ISNULL(D.UomQty,0) * ISNULL(MP.ReportingCR,1)    
WHEN H.DocPrefix = 16    
Then ISNULL(D.UomQty,0) * ISNULL(MP.ReportingCR,1) * -1    
END    
)) AS [Reporting UOM Qty],    
MR.Name  [Reporting UOM],    
dbo.fnGetRoundedValue(SUM(isnull(D.GrossAmt,0))) AS [Gross Amt],    
dbo.fnGetRoundedValue(sum(isnull(D.NetAmt,0))) as [Net Amt],    
dbo.fnGetRoundedValue(H.NetAmt) [Total Invoice Amt],    
H.Remarks [Remarks],    
H.Narration [Narration]  
FROM tblTranSalesHeader H    
JOIN tblTranSalesDetail D ON D.InvID = H.ID    
JOIN tblMasterProduct MP ON MP.ID = D.ProdID    
left join tblMasterCustomer C on C.ID = H.CustID    
left join tblMasterBranchOffice MBO on MBO.ID = H.BranchID    
left join tblMasterUom MU on MU.ID = MP.BaseUomID    
left join tblMasterUom MS on MS.ID = MP.SalesUomID    
left join tblMasterUom MR on MR.ID = MP.ReportingUomID    
WHERE H.InvDate BETWEEN @FromDate AND @ToDate    
AND H.status NOT IN (2,4)    
AND D.ProdID = @ProdID    
AND H.BranchID = @BranchID    
GROUP BY    
MP.Code,    
H.DocID,    
H.InvDate,    
H.DocRef,    
C.Code,    
C.Name,    
MP.Name,    
MU.Name,    
MS.Name,    
MR.Name,    
MBO.Name, 
D.AdjustQty,
H.NetAmt,    
H.Remarks,    
H.Narration    
END',
N'[export] nocount';
GO
/****** uspItemWiseSalesHeader ******/
EXEC #Apply07 N'dbo.uspItemWiseSalesHeader', 0x77148CE132A5DCEBDDF56448D83780444DEDFF6CE4E22B0D101E0BED0A726672, NULL, NULL, 0x269EBE4CE4F1CCEFC6E6AE3F55F0397A0BA584B8BBD3246718C41162D4E6BFA7, 0x628577AC55541EA0F16623D70D42B1134A6803077343227FC5882640C67F6083, NULL,
N'ALTER PROCEDURE [dbo].[uspItemWiseSalesHeader]      
@BranchName INT,      
@MfrName NVARCHAR(100) = '''',      
@BrandName NVARCHAR(100) = '''',      
@CategoryName NVARCHAR(100) = '''',      
@ProductName NVARCHAR(100) = '''',      
@FromDate DATE = ''2025-01-01'',      
@ToDate   DATE = ''2025-12-20''      
AS      
SET NOCOUNT ON;
BEGIN      
SELECT      
@FromDate [From Date],      
@ToDate [To Date],      
D.ProdID [Product ID],      
H.BranchID,      
MBO.Name [Branch Name],      
MP.Code  [Product Code],      
MP.Name  [Product Name],      
MM.Name  [Manufacturer Name],      
MB.Name  [Brand Name],      
MC.Name  [Category Name],      
dbo.fnGetRoundedValue(SUM(CASE WHEN H.DocPrefix = 15      
THEN ISNULL(D.UomQty,0) * ISNULL(MP.BaseCR,1)      
WHEN H.DocPrefix = 16      
THEN (ISNULL(D.UomQty,0) * ISNULL(MP.BaseCR,1)) * -1      
END      
)) AS [Base Qty],      
MU.Name  [Base UOM],      
dbo.fnGetRoundedValue(SUM( CASE WHEN H.DocPrefix = 15      
THEN ISNULL(D.UomQty,0) * ISNULL(MP.SalesCR,1)      
WHEN H.DocPrefix = 16      
THEN ISNULL(D.UomQty,0) * ISNULL(MP.SalesCR,1) * -1      
END      
)) AS [Sales UOM Qty],      
MS.Name  [Sales UOM],      
dbo.fnGetRoundedValue(SUM( CASE WHEN H.DocPrefix = 15      
Then ISNULL(D.UomQty,0) * ISNULL(MP.ReportingCR,1)      
WHEN H.DocPrefix = 16      
Then ISNULL(D.UomQty,0) * ISNULL(MP.ReportingCR,1) * -1      
END      
)) AS [Reporting UOM Qty],      
MR.Name  [Reporting UOM],      
dbo.fnGetRoundedValue(SUM(isnull(D.GrossAmt,0))) AS [Gross Amt],      
dbo.fnGetRoundedValue(sum(isnull(D.NetAmt,0))) as [Net Amt]      
FROM tblTranSalesHeader H      
JOIN tblTranSalesDetail D ON D.InvID = H.ID      
JOIN tblMasterProduct MP ON MP.ID = D.ProdID      
left join tblMasterBranchOffice MBO on MBO.ID = H.BranchID      
left Join tblMasterManufacturer MM on MM.ID = MP.MfrID      
left join tblMasterBrand MB on MB.ID = MP.BrandID      
left join tblMasterCategory MC on MC.ID = MP.CategoryID      
left join tblMasterUom MU on MU.ID = MP.BaseUomID      
left join tblMasterUom MS on MS.ID = MP.SalesUomID      
left join tblMasterUom MR on MR.ID = MP.ReportingUomID      
WHERE H.InvDate BETWEEN @FromDate AND @ToDate      
AND H.status NOT IN (2,4)      
AND (isnull(@MfrName,'''') = '''' or MM.ID IN (SELECT * from dbo.fnSplitString( @MfrName,'','')))      
AND (isnull(@BrandName,'''') = '''' or MB.ID IN (SELECT * from dbo.fnSplitString( @BrandName,'','')))      
AND (isnull(@CategoryName,'''') = '''' or MC.ID IN (SELECT * from dbo.fnSplitString( @CategoryName,'','')))      
AND (isnull(@ProductName,'''') = '''' OR MP.ID IN (SELECT * from dbo.fnSplitString( @ProductName,'','')))      
AND (isnull(@BranchName,'''') = 0  OR MBO.ID IN (SELECT * from dbo.fnSplitString( @BranchName,'','')))      
GROUP BY      
MP.Code,      
D.ProdID,      
H.BranchID,      
MP.Name,      
MM.Name,      
MB.Name,      
MC.Name,      
MU.Name,      
MS.Name,      
MR.Name,      
MBO.Name      
END',
N'[export] nocount';
GO
/****** uspJournalEntryBody ******/
EXEC #Apply07 N'dbo.uspJournalEntryBody', 0xF9383202EAFD20E6FED5C3DD6737C52F14BDBA0833BC69BA31D659AD2C33D186, NULL, NULL, 0x76C8E31C411EE20373AA693926CBEA64C888DA2EB9189493444FB85D9A8EB228, 0x206F51AE534331187CDEAA055280A48143C3595E6A0392998F91DB485980CAD4, NULL,
N'--[uspJournalEntryBody] 84
ALTER PROC [dbo].[uspJournalEntryBody]          
@DocValue INT = null           
AS          
SET NOCOUNT ON;
SELECT          
FAA.AccountName AS [Account Name],JE.Credit AS [Credit Amount],JE.Debit AS [Debit Amount],JE.Balance AS [Balance],        
JE.Remarks AS [Remarks]  
FROM dbo.tblFAJournal AS JE          
JOIN dbo.tblFAAccount AS FAA ON FAA.FAID = JE.AccountID        
WHERE JE.JVID = @DocValue AND JE .DocPrefix = 9',
N'[export] nocount';
GO
/****** uspJournalEntryHeader ******/
EXEC #Apply07 N'dbo.uspJournalEntryHeader', 0x67E183196C30DD643134BCE63F473FB8331CE24615A33579A1D2394AD53109D6, NULL, NULL, 0xBD599D8A45463042BFE6D8C5C4A0EB99FA226BA8E9E5A04114C970855F33E12A, 0x8CEA2B9B8ACD2151EAEF9ECFEFDC75E14C5F68D12FEDD7AE5BC93FB10BA87EC4, NULL,
N'ALTER PROC [dbo].[uspJournalEntryHeader]             
@DocValue INT = NULL               
AS       
SET NOCOUNT ON;
begin             
SELECT DISTINCT JE.DocValue AS [Doc Value],JE.DocId AS [Doc ID],CONVERT (NVARCHAR ,JE.DocDate,103) AS [Doc Date], MBO.Name [Branch Name],  
ISNULL(CONVERT(NVARCHAR(5),JE.MDate,108),CONVERT(NVARCHAR(5),JE.CDate,108)) AS [Time],Doc.TransName AS [Trans Name],JE.Narration AS [Narration],    
JE.DocRef AS [Doc Ref],UserTab.username AS [User Name]    
FROM dbo.tblFAJournal AS JE    
left JOIN dbo.tblDocumentSeries AS Doc ON JE. DocPrefix = Doc.TransID    
left JOIN dbo.tblUsers AS UserTab ON UserTab.ID = JE.MBy OR UserTab.ID  =  JE.Cby
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = JE.BranchID
WHERE JE.JVID = @DocValue AND JE .DocPrefix = 9    
end',
N'[export] nocount';
GO
/****** uspKillTran ******/
EXEC #Apply07 N'dbo.uspKillTran', 0x81EE0A1B1C11090C0D3951D0B65013DD0D276FDC5A5E56957A914EC714DC54F8, NULL, NULL, 0xA195409E70ED9F95E32657198D16166987EC2E4900E3338EED21EEF571772A47, 0x531AED67853EE41041F850D0D55894EF46CE7FE0A254A7FA5CD9325952E4E70C, NULL,
N'ALTER proc [dbo].[uspKillTran]
@TableName nvarchar(255)
as
SET NOCOUNT ON;
begin
Declare @SQL as Varchar(Max);
Set @SQL  = ''''
select @SQL = @SQL + ''KILL '' + cast(request_session_id as varchar) + '';''
from sys.dm_tran_locks Where resource_type=''OBJECT'' And resource_associated_entity_id = object_id(@TableName);
EXEC (@SQL)
end',
N'[export] nocount';
GO
/****** uspLatestGSTReportInfo ******/
EXEC #Apply07 N'dbo.uspLatestGSTReportInfo', 0x938E347D3B79D126E099B786BF36DD7632D8A72463E0A7A04B772CA325F93035, NULL, NULL, 0x3825B40B58D682DDAA750DCED95504EE0005C033105027DB01421BFDA4CC04D5, 0x9C1B7CB1C4F9AF6D53B96CE8F13126E627040DF67FBC14FDC19B2A1B4DF06F4F, NULL,
N'-- uspLatestGSTReportInfo ''b2b'',''2025-04-01'',''2026-10-30'',0,'''' (2.5L LESSER)                    
-- uspLatestGSTReportInfo ''b2cl'',''2020-06-01'',''2026-10-30'',0,''''  (2.5L GREATER)                    
-- uspLatestGSTReportInfo ''b2cs'',''2023-06-01'',''2026-10-30'',0,''''  (UN-REGISTERED PERSON SALES)                    
-- uspLatestGSTReportInfo ''cdnr'',''2025-05-01'',''2026-10-30'',0,''''   (REGISTERED PERSON SR)                    
-- uspLatestGSTReportInfo ''cdnur'',''2025-05-01'',''2026-10-30'',0,''''  (UN-REGISTERED PERSON SR)                    
-- uspLatestGSTReportInfo ''HSN'',''2025-05-01'',''2026-10-30'',0,''4,12''                   
-- uspLatestGSTReportInfo ''HSNB2B'',''2025-05-01'',''2026-10-30'',0,''12''              
-- uspLatestGSTReportInfo ''HSNB2C'',''2025-05-01'',''2026-10-30'',0,''12''          
-- uspLatestGSTReportInfo ''Extempted'',''2024-10-10'',''2026-10-30'',0,''12''                  
-- uspLatestGSTReportInfo ''Documents'',''2026-02-01'',''2026-10-30'',0,''12''  
ALTER PROC [dbo].[uspLatestGSTReportInfo]    
@SheetMode NVARCHAR(255),@FromDate DATE,@ToDate DATE,@WOEinv int = 0 ,@BranchIDs NVARCHAR(255) = null
AS    
SET NOCOUNT ON;
BEGIN    
DECLARE @RegionStateID int = (SELECT StateID FROM tblCompanyRegistration)    
IF ISNULL(@SheetMode,'''')=''b2b''    
BEGIN    
CREATE TABLE #TEMPb2bS ([Inv ID] NVARCHAR(255),[Inv Date] NVARCHAR(255),[Branch Name] NVARCHAR(255),[Doc Ref] NVARCHAR(255),    
[Party Name] NVARCHAR(255),[Tax Type] NVARCHAR(255),[GSTIN] NVARCHAR(255),[Product Code] NVARCHAR(255),    
[Product Name] NVARCHAR(255),[EAN] NVARCHAR(255),    
[HSN Code] NVARCHAR(255),[Base UOM] NVARCHAR(255),[Base UOM Qty] DECIMAL(25,2),[Gross Amount] DECIMAL(25,2),    
[CGST %] DECIMAL(25,2),[CGST Amount] DECIMAL(25,2),[SGST %] DECIMAL(25,2),[SGST Amount] DECIMAL(25,2),    
[UTGST %] DECIMAL(25,2),[UTGST Amount] DECIMAL(25,2),[GCESS %] DECIMAL(25,2),[GCESS Amount] DECIMAL(25,2),    
[IGST %] DECIMAL(25,2),[IGST Amount] DECIMAL(25,2),[ICESS %] DECIMAL(25,2),[ICESS Amount] DECIMAL(25,2),    
[Net Amount] DECIMAL(25,2))    
INSERT INTO #TEMPb2bS    
EXEC uspGetFullGSTInfoReport ''S'',@FromDate,@ToDate,0,@BranchIDs
    
    
SELECT UPPER(TT.GSTIN) [GSTIN/UIN of Recipient],[Party Name] [Receiver Name],[Inv ID] [Invoice Number],    
[Inv Date] [Invoice date],convert(decimal(25,2),SH.NetAmt) [Invoice Value],(CONVERT(NVARCHAR,SC.TINNo) + ''-'' + SC.StateName) "Place Of Supply",    
''N'' "Reverse Charge",'''' [Applicable % of Tax Rate],''Regular'' "Invoice Type",'''' "E-Commerce GSTIN",[CGST %]+[SGST %] Rate,    
SUM([Gross Amount]) [Taxable Value],SUM([GCESS Amount]) [CESS Amount],SUM([CGST Amount]) [CGST Amount],SUM([SGST Amount]) [SGST Amount],    
SUM([IGST Amount]) [IGST Amount] FROM #TEMPb2bS TT    
LEFT JOIN tblMasterCustomer AS Cust ON Cust.Name collate SQL_Latin1_General_CP1_CI_AS = TT.[Party Name] collate SQL_Latin1_General_CP1_CI_AS    
LEFT JOIN tblGSTStateNameandCode AS SC ON SC.StateID = Cust.StateID    
JOIN tblTranSalesHeader AS SH ON (CASE WHEN SH.UDFId > 0 THEN SH.UDFDocId ELSE SH.DocId END) collate SQL_Latin1_General_CP1_CI_AS = TT.[Inv ID] collate SQL_Latin1_General_CP1_CI_AS    
WHERE sh.Status IN (1,3,5) AND ISNULL(TT.GSTIN,'''') != '''' AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)

GROUP BY [Party Name],TT.GSTIN,[Inv ID],[CGST %],[SGST %],SC.TINNo,SC.StateName,SH.NetAmt,[Inv Date]
--ORDER BY [Inv Date]    
    
ORDER BY [Inv Date]    
DROP TABLE #TEMPb2bS    
END    
IF ISNULL(@SheetMode,'''')=''b2cl''    
BEGIN    
CREATE TABLE #TEMPb2clS ([Inv ID] NVARCHAR(255),[Inv Date] NVARCHAR(255),[Branch Name] NVARCHAR(255),[Doc Ref] NVARCHAR(255),                            
[Party Name] NVARCHAR(255),[Tax Type] NVARCHAR(255),[GSTIN] NVARCHAR(255),[Product Code] NVARCHAR(255),                            
[Product Name] NVARCHAR(255),[EAN] NVARCHAR(255),                            
[HSN Code] NVARCHAR(255),[Base UOM] NVARCHAR(255),[Base UOM Qty] DECIMAL(25,2),[Gross Amount] DECIMAL(25,2),                            
[CGST %] DECIMAL(25,2),[CGST Amount] DECIMAL(25,2),[SGST %] DECIMAL(25,2),[SGST Amount] DECIMAL(25,2),                            
[UTGST %] DECIMAL(25,2),[UTGST Amount] DECIMAL(25,2),[GCESS %] DECIMAL(25,2),[GCESS Amount] DECIMAL(25,2),                            
[IGST %] DECIMAL(25,2),[IGST Amount] DECIMAL(25,2),[ICESS %] DECIMAL(25,2),[ICESS Amount] DECIMAL(25,2),                            
[Net Amount] DECIMAL(25,2))                                                   
INSERT INTO #TEMPb2clS                            
EXEC uspGetFullGSTInfoReport ''S'',@FromDate,@ToDate,0,@BranchIDs
                            
SELECT [Inv ID] [Invoice Number],[Inv Date] [Invoice date],dbo.fnGetRoundedValue(SH.NetAmt) [Invoice Value],                
(CONVERT(NVARCHAR,SC.TINNo) + ''-'' + SC.StateName) "Place Of Supply",'''' [Applicable % of Tax Rate],                
[CGST %]+[SGST %] Rate,SUM([Gross Amount]) [Taxable Value],SUM([GCESS Amount]) [CESS Amount],'''' "E-Commerce GSTIN",SUM([CGST Amount]) [CGST Amount],SUM([SGST Amount]) [SGST Amount],                            
SUM([IGST Amount]) [IGST Amount],[Party Name] [Customer Name] FROM #TEMPb2clS TT                            
LEFT JOIN tblMasterCustomer AS Cust ON Cust.Name collate SQL_Latin1_General_CP1_CI_AS = TT.[Party Name] collate SQL_Latin1_General_CP1_CI_AS                    
LEFT JOIN tblGSTStateNameandCode AS SC ON SC.StateID = Cust.StateID                     
LEFT join tblTranSalesHeader SH ON (CASE WHEN SH.UDFId > 0 THEN SH.UDFDocId ELSE SH.DocId END) collate SQL_Latin1_General_CP1_CI_AS  = TT.[Inv ID] collate SQL_Latin1_General_CP1_CI_AS                    
WHERE sh.Status IN (1,3,5) AND ISNULL(TT.GSTIN,'''')  = '''' AND SH.NetAmt > 250000 and Cust.StateID != @RegionStateID                  
  AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)                  
GROUP BY [Party Name],TT.GSTIN,[Inv ID],[CGST %],[SGST %],SC.TINNo,SC.StateName,SH.NetAmt,[Inv Date]
--ORDER BY [Inv Date]                                                  
ORDER BY [Inv Date]                            
DROP TABLE #TEMPb2clS                                                        
END     
IF ISNULL(@SheetMode,'''')=''b2cs''    
BEGIN    
CREATE TABLE #TEMPb2csS ([Inv ID] NVARCHAR(255),[Inv Date] NVARCHAR(255),[Branch Name] NVARCHAR(255),[Doc Ref] NVARCHAR(255),    
[Party Name] NVARCHAR(255),[Tax Type] NVARCHAR(255),[GSTIN] NVARCHAR(255),[Product Code] NVARCHAR(255),    
[Product Name] NVARCHAR(255),[EAN] NVARCHAR(255),    
[HSN Code] NVARCHAR(255),[Base UOM] NVARCHAR(255),[Base UOM Qty] DECIMAL(25,2),[Gross Amount] DECIMAL(25,2),    
[CGST %] DECIMAL(25,2),[CGST Amount] DECIMAL(25,2),[SGST %] DECIMAL(25,2),[SGST Amount] DECIMAL(25,2),    
[UTGST %] DECIMAL(25,2),[UTGST Amount] DECIMAL(25,2),[GCESS %] DECIMAL(25,2),[GCESS Amount] DECIMAL(25,2),    
[IGST %] DECIMAL(25,2),[IGST Amount] DECIMAL(25,2),[ICESS %] DECIMAL(25,2),[ICESS Amount] DECIMAL(25,2),    
[Net Amount] DECIMAL(25,2))    
INSERT INTO #TEMPb2csS    
EXEC uspGetFullGSTInfoReport ''S'',@FromDate,@ToDate,0,@BranchIDs
    
SELECT Type,[Place Of Supply],[Applicable % of Tax Rate],Rate,SUM([Taxable Value]) [Taxable Value],    
SUM([CESS Amount]) [CESS Amount],[E-Commerce GSTIN],SUM([CGST Amount]) [CGST Amount],SUM([SGST Amount]) [SGST Amount],    
SUM([IGST Amount]) [IGST Amount] FROM (    
SELECT ''OE'' "Type",(CONVERT(NVARCHAR,SC.TINNo) + ''-'' + SC.StateName) "Place Of Supply",'''' [Applicable % of Tax Rate],[CGST %]+[SGST %] Rate,    
SUM([Gross Amount]) [Taxable Value],SUM([GCESS Amount]) [CESS Amount],'''' "E-Commerce GSTIN",SUM([CGST Amount]) [CGST Amount],    
SUM([SGST Amount]) [SGST Amount],SUM([IGST Amount]) [IGST Amount] FROM #TEMPb2csS TT    
LEFT JOIN tblMasterCustomer AS Cust ON Cust.Name collate SQL_Latin1_General_CP1_CI_AS = TT.[Party Name] collate SQL_Latin1_General_CP1_CI_AS    
LEFT JOIN tblGSTStateNameandCode AS SC ON SC.StateID = Cust.StateID    
LEFT join tblTranSalesHeader SH ON (CASE WHEN SH.UDFId > 0 THEN SH.UDFDocId ELSE SH.DocId END) collate SQL_Latin1_General_CP1_CI_AS = TT.[Inv ID] collate SQL_Latin1_General_CP1_CI_AS    
WHERE sh.Status IN (1,3,5) AND ISNULL(TT.GSTIN,'''') = '''' and SH.NetAmt < 250000 --and Cust.StateID != @RegionStateID    
AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)    
GROUP BY [CGST %]+[SGST %],SC.TINNo,SC.StateName    
--ORDER BY [CGST %]+[SGST %]    
    
) AS REC    
GROUP BY Type,[Place Of Supply],[Applicable % of Tax Rate],Rate,"E-Commerce GSTIN"    
ORDER BY Rate    
DROP TABLE #TEMPb2csS    
END    
