[HSN Code] NVARCHAR(255),[Base UOM] NVARCHAR(255),[Base UOM Qty] DECIMAL(25,2),[Gross Amount] DECIMAL(25,2),    
[CGST %] DECIMAL(25,2),[CGST Amount] DECIMAL(25,2),[SGST %] DECIMAL(25,2),[SGST Amount] DECIMAL(25,2),  [UTGST %] DECIMAL(25,2),[UTGST Amount] DECIMAL(25,2),[GCESS %] DECIMAL(25,2),[GCESS Amount] DECIMAL(25,2),    
[IGST %] DECIMAL(25,2),[IGST Amount] DECIMAL(25,2),[ICESS %] DECIMAL(25,2),[ICESS Amount] DECIMAL(25,2),    
[Net Amount] DECIMAL(25,2))    
