[Party Name] NVARCHAR(255),[Tax Type] NVARCHAR(255),[GSTIN] NVARCHAR(255),[Product Code] NVARCHAR(255),    
[Product Name] NVARCHAR(255),[EAN] NVARCHAR(255),    
[HSN Code] NVARCHAR(255),[Base UOM] NVARCHAR(255),[Base UOM Qty] DECIMAL(25,2),[Gross Amount] DECIMAL(25,2),    
[CGST %] DECIMAL(25,2),[CGST Amount] DECIMAL(25,2),[SGST %] DECIMAL(25,2),[SGST Amount] DECIMAL(25,2),    
[UTGST %] DECIMAL(25,2),[UTGST Amount] DECIMAL(25,2),[GCESS %] DECIMAL(25,2),[GCESS Amount] DECIMAL(25,2),    
[IGST %] DECIMAL(25,2),[IGST Amount] DECIMAL(25,2),[ICESS %] DECIMAL(25,2),[ICESS Amount] DECIMAL(25,2),    
[Net Amount] DECIMAL(25,2))    
INSERT INTO #TEMPhsnb2cS    
EXEC uspGetFullGSTInfoReport ''S'',@FromDate,@ToDate,@WOEinv,@BranchIDs     
INSERT INTO #TEMPhsnb2cSR    
EXEC uspGetFullGSTInfoReport ''SR'',@FromDate,@ToDate,@WOEinv,@BranchIDs     
    
SELECT [HSN Code] HSN,Description,UQC,dbo.fnGetRoundedValue(SUM([Base UOM Qty])) [Total Quantity],    
dbo.fnGetRoundedValue(SUM([Total Value])) [Total Value],    
dbo.fnGetRoundedValue((Rate)) Rate,    
dbo.fnGetRoundedValue(SUM([Taxable Value])) [Taxable Value],    
dbo.fnGetRoundedValue(SUM([IGST Amount])) [Integrated Tax Amount],    
dbo.fnGetRoundedValue(SUM([CGST Amount])) [Central Tax Amount],    
dbo.fnGetRoundedValue(SUM([SGST Amount])) [State/UT Tax Amount],    
dbo.fnGetRoundedValue(SUM([CESS Amount])) [CESS Amount] FROM (    
select [HSN Code],'''' "Description",[Base UOM] UQC,sum([Base UOM Qty]) [Base UOM Qty],    
SUM([Net Amount]) [Total Value],[CGST %]+[SGST %]+[IGST %] Rate,    
SUM([Gross Amount]) [Taxable Value],SUM([IGST Amount]) [IGST Amount],SUM([SGST Amount]) [SGST Amount],    
SUM([CGST Amount]) [CGST Amount],SUM([GCESS Amount]) [CESS Amount] from #TEMPhsnb2cS TT    
LEFT join tblTranSalesHeader SH ON (CASE WHEN SH.UDFId > 0 THEN SH.UDFDocId ELSE SH.DocId END) collate SQL_Latin1_General_CP1_CI_AS = TT.[Inv ID] collate SQL_Latin1_General_CP1_CI_AS    
LEFT JOIN tblMasterCustomer Cust on Cust.Id =SH.CustId    
where ISNULL(TT.GSTIN,'''') = '''' AND sh.Status IN (1,3,5)    
and (SH.NetAmt < 250000 or (SH.NetAmt > 250000 and Cust.StateID != @RegionStateID))    
group by [HSN Code],[Product Name],[Base UOM],[CGST %]+[SGST %]+[IGST %]    
UNION ALL    
select [HSN Code],'''' "Description",[Base UOM],sum([Base UOM Qty]* -1) [Base UOM Qty],    
SUM([Net Amount]* -1) [Net Amount],[CGST %]+[SGST %]+[IGST %] Rate,    
SUM([Gross Amount]* -1) Tabable,SUM([IGST Amount]* -1) [IGST Amount],SUM([SGST Amount]* -1) [SGST Amount],    
SUM([CGST Amount]* -1) [CGST Amount],SUM([GCESS Amount]* -1) [CESS Amount] from #TEMPhsnb2cSR TT    
LEFT join tblTranSalesHeader SH ON (CASE WHEN SH.UDFId > 0 THEN SH.UDFDocId ELSE SH.DocId END) collate SQL_Latin1_General_CP1_CI_AS = TT.[Inv ID] collate SQL_Latin1_General_CP1_CI_AS    
LEFT JOIN tblMasterCustomer Cust on Cust.Id =SH.CustId    
where ISNULL(TT.GSTIN,'''') = '''' AND sh.Status IN (3,5,6,7)    
and (SH.NetAmt < 250000 or (SH.NetAmt > 250000 and Cust.StateID != @RegionStateID))    
group by [HSN Code],[Product Name],[Base UOM],[CGST %]+[SGST %]+[IGST %]    
) AS REC    
group by [HSN Code],Description,UQC,RATE    
    
DROP TABLE #TEMPhsnb2cS,#TEMPhsnb2cSR    
