IF(ISNULL(@SheetMode,''''))=''Extempted''    
BEGIN    
select [Description],CONVERT(DECIMAL(25,2),(SUM(isnull([Nil Rated Supplies],0)))) [Nil Rated Supplies],    
CONVERT(DECIMAL(25,2),SUM(isnull([Exempted(other than nil rated/non GST supply)],0))) as    
[Exempted(other than nil rated/non GST supply)],[Non-GST Supplies] from (    
SELECT ''Intra-State supplies to registered persons'' [Description],SUM(SD.NetAmt) [Nil Rated Supplies],    
0 as [Exempted(other than nil rated/non GST supply)],'''' as [Non-GST Supplies] FROM tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvId = SH.ID    
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId    
join tblGSTStateNameandCode GC ON GC.StateID = MC.StateID    
WHERE SH.DocPrefix = 15 AND Status IN (1,3,5) AND SH.InvDate BETWEEN @FromDate AND @ToDate AND (SD.TaxValue = 0)    
AND ISNULL(GSTIN,'''') != '''' AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)    
AND TINNo = ''33'' AND (isnull(@BranchIDs,'''') = '''' OR SH.BranchID in (SELECT value FROM STRING_SPLIT(@BranchIDs, '','')))
GROUP BY TINNo    
union all    
SELECT ''Inter-State supplies to registered persons'' [Description],SUM(SD.NetAmt) [Nil Rated Supplies],    
0 as [Exempted(other than nil rated/non GST supply)],'''' as [Non-GST Supplies] FROM tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvId = SH.ID    
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId    
join tblGSTStateNameandCode GC ON GC.StateID = MC.StateID    
WHERE SH.DocPrefix = 15 AND Status IN (1,3,5) AND SH.InvDate BETWEEN @FromDate AND @ToDate AND (SD.TaxValue = 0)    
AND ISNULL(GSTIN,'''') != '''' AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)    
AND TINNo != ''33'' AND (isnull(@BranchIDs,'''') = '''' OR SH.BranchID in (SELECT value FROM STRING_SPLIT(@BranchIDs, '','')))    
GROUP BY TINNo    
UNION all    
SELECT ''Intra-State supplies to Unregistered persons'' [Description],SUM(SD.NetAmt) [Nil Rated Supplies],    
0 as [Exempted(other than nil rated/non GST supply)],'''' as [Non-GST Supplies] FROM tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvId = SH.ID    
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId    
join tblGSTStateNameandCode GC ON GC.StateID = MC.StateID    
WHERE SH.DocPrefix = 15 AND Status IN (1,3,5) AND SH.InvDate BETWEEN @FromDate AND @ToDate AND (SD.TaxValue = 0)    
AND ISNULL(GSTIN,'''') = '''' AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)    
AND TINNo = ''33'' AND (isnull(@BranchIDs,'''') = '''' OR SH.BranchID in (SELECT value FROM STRING_SPLIT(@BranchIDs, '','')))    
GROUP BY TINNo    
union all    
SELECT ''Inter-State supplies to Unregistered persons'' [Description],SUM(SD.NetAmt) [Nil Rated Supplies],    
0 as [Exempted(other than nil rated/non GST supply)],'''' as [Non-GST Supplies] FROM tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvId = SH.ID    
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId    
join tblGSTStateNameandCode GC ON GC.StateID = MC.StateID    
WHERE SH.DocPrefix = 15 AND Status IN (1,3,5) AND SH.InvDate BETWEEN @FromDate AND @ToDate AND (SD.TaxValue = 0)  
AND ISNULL(GSTIN,'''') = '''' AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)    
AND TINNo != ''33'' AND (isnull(@BranchIDs,'''') = '''' OR SH.BranchID in (SELECT value FROM STRING_SPLIT(@BranchIDs, '','')))   
GROUP BY TINNo) Data    
GROUP BY [Description],[Nil Rated Supplies],[Non-GST Supplies]    
END    
IF ISNULL(@SheetMode,'''')=''Documents''    
BEGIN    
DECLARE @TempUDNInfo AS TABLE (DocPrefix INT,UDNID INT,UDNName NVARCHAR(255))    

SELECT TransName,[From] [Sr. No. From],[To] [Sr. No. To],SUM([Total Count]) [Total Number],sum(Cancelled) Cancelled,Name FROM (    
SELECT ''Invoice'' "TransName",ISNULL(UDNInfo.UDNName,'''') "Name",ISNULL((SH.UDFDocPrefix + CONVERT(NVARCHAR,MIN(SH.UDFDocValue))),'''') "From",    
ISNULL((SH.UDFDocPrefix + CONVERT(NVARCHAR,MAX(SH.UDFDocValue))),'''') "To",    
(SELECT COUNT(Id) FROM tblTranSalesHeader WHERE InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix=15 AND Status IN (1,3,5) AND UDFId=UDNInfo.UDNID) "Total Count",    
(SELECT COUNT(Id) FROM tblTranSalesHeader WHERE InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix=15 AND Status IN (4) AND UDFId=UDNInfo.UDNID) "Cancelled"    
FROM tblTranSalesHeader AS SH    
JOIN @TempUDNInfo AS UDNInfo ON UDNInfo.UDNID = SH.UDFId AND UDNInfo.DocPrefix=15    
WHERE SH.InvDate BETWEEN @FromDate AND @ToDate AND SH.DocPrefix=15 AND Status IN (1,3,4,5)    
--AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)    
AND (isnull(@BranchIDs,'''') = '''' OR SH.BranchID in (SELECT value FROM STRING_SPLIT(@BranchIDs, '','')))
GROUP BY UDNInfo.UDNID,UDNInfo.UDNName,SH.UDFDocPrefix--,SH.IRN    
UNION ALL    
SELECT ''Invoice'' "TransName",'''',YDS.Prefix + CONVERT(NVARCHAR,MIN(SH.DocValue)),YDS.Prefix + CONVERT(NVARCHAR,MAX(SH.DocValue)),    
(SELECT COUNT(Id) FROM tblTranSalesHeader WHERE InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix=15 AND Status IN (1,3,5) AND BranchID = SH.BranchID),    
(SELECT COUNT(Id) FROM tblTranSalesHeader WHERE InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix=15 AND Status IN (4) AND BranchID = SH.BranchID)    
FROM tblTranSalesHeader AS SH    
--LEFT JOIN tblDocumentSeries MDS ON MDS.TransID=15    
JOIN tblYearwiseDocumentSeries YDS ON YDS.BranchID = SH.BranchID AND YDS.TransID = SH.DocPrefix AND SH.InvDate BETWEEN YDS.FromDate AND YDS.ToDate  
WHERE InvDate BETWEEN @FromDate AND @ToDate AND SH.DocPrefix=15 AND Status IN (1,3,4,5)    
--AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)    
AND (isnull(@BranchIDs,'''') = '''' OR SH.BranchID in (SELECT value FROM STRING_SPLIT(@BranchIDs, '','')))
GROUP BY YDS.Prefix,SH.BranchID--,SH.IRN    
UNION ALL    
SELECT ''Sales Return'' "TransName",ISNULL(UDNInfo.UDNName,'''') "Name",ISNULL((SH.UDFDocPrefix + CONVERT(NVARCHAR,MIN(SH.UDFDocValue))),'''') "From",    
ISNULL((SH.UDFDocPrefix + CONVERT(NVARCHAR,MAX(SH.UDFDocValue))),'''') "To",(SELECT COUNT(Id) FROM tblTranSalesHeader    
WHERE InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix=16 AND Status IN (3,5,6,7) AND UDFId=UDNInfo.UDNID) "Total Count",    
(SELECT COUNT(Id) FROM tblTranSalesHeader WHERE InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix=16 AND Status IN (4) AND UDFId=UDNInfo.UDNID) "Cancelled"    
FROM tblTranSalesHeader AS SH    
JOIN @TempUDNInfo AS UDNInfo ON UDNInfo.UDNID = SH.UDFId AND UDNInfo.DocPrefix=16    
WHERE SH.InvDate BETWEEN @FromDate AND @ToDate AND SH.DocPrefix=16 AND Status IN (1,3,4,5)    
--AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)   
AND (isnull(@BranchIDs,'''') = '''' OR SH.BranchID in (SELECT value FROM STRING_SPLIT(@BranchIDs, '','')))
GROUP BY UDNInfo.UDNID,UDNInfo.UDNName,SH.UDFDocPrefix--,SH.IRN    
UNION ALL    
SELECT ''Sales Return'' "TransName",'''',YDS.Prefix + CONVERT(NVARCHAR,MIN(SH.DocValue)),YDS.Prefix + CONVERT(NVARCHAR,MAX(SH.DocValue)),    
(SELECT COUNT(Id)FROM tblTranSalesHeader WHERE InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix=16 AND Status IN (3,5,6,7) AND BranchID = SH.BranchID),    
(SELECT COUNT(Id) FROM tblTranSalesHeader WHERE InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix=16 AND Status IN (4) AND BranchID = SH.BranchID)    
FROM tblTranSalesHeader AS SH    
--LEFT JOIN tblDocumentSeries MDS ON MDS.TransID=16    
JOIN tblYearwiseDocumentSeries YDS ON YDS.BranchID = SH.BranchID AND YDS.TransID = SH.DocPrefix AND SH.InvDate BETWEEN YDS.FromDate AND YDS.ToDate  
WHERE InvDate BETWEEN @FromDate AND @ToDate AND SH.DocPrefix=16 AND Status IN (1,3,4,5)    
--AND ISNULL(SH.IRN,'''') = (CASE WHEN @WOEinv = 0 THEN ISNULL(SH.IRN,'''') ELSE '''' END)    
AND (isnull(@BranchIDs,'''') = '''' OR SH.BranchID in (SELECT value FROM STRING_SPLIT(@BranchIDs, '','')))
GROUP BY YDS.Prefix,SH.BranchID--,SH.IRN    
) AS REC    
GROUP BY TransName,[From],[To],Name    
END    
END',
N'[export] nocount';
GO
/****** uspLoadBRSClosingBalance ******/
EXEC #Apply07 N'dbo.uspLoadBRSClosingBalance', 0xB5D411A6456E9398A140C857B56F64C5C134092D27FD7CB296C97DF8759F707D, NULL, NULL, 0xF8968B90A48B1276C69ADC8899566BDD361AEB9F2651A29D8C9CBA3C650E04C9, 0xDB0B31078BC6520E2CB50F8A3FF3636790D6595155B54BE638B596D43548A3BA, NULL,
N'--[uspLoadClosingBalance] 1,2098,''2018-03-22''
ALTER PROC [dbo].[uspLoadBRSClosingBalance]
@Cond SMALLINT,@AccID INT,@FromDate DATE=NULL, @OpeningBalance DECIMAL (25,6)=NULL,@FAType INT=NULL,@TransId INT =NULL
AS
SET NOCOUNT ON;
BEGIN
SET DATEFORMAT dmy
IF ISNULL(@AccID,0)>0
BEGIN
DECLARE @Depit DECIMAL (25,6),@Credit DECIMAL (25,6)
DECLARE @AccType INT,@AccOpeningBal DECIMAL (25,6),@TempBal DECIMAL (25,6),@Balance DECIMAL (25,6),@TempCustId INT
DECLARE @lastDate DATE,@BookDate DATE
--Book Start Date
SELECT @BookDate = F_SD FROM dbo.tblCompanyRegistration
DECLARE @FDate DATE
IF ISNULL(@FromDate,'''')=''''
BEGIN
SET @FDate = GETDATE()
END
ELSE
BEGIN
SET @FDate = @FromDate
END
--Account Opening
IF ISNULL(@OpeningBalance,0)=0
BEGIN
SELECT @AccOpeningBal=ISNULL(OpeningBalance,0),@AccType=FATypeID FROM tblFAAccount WHERE FAID =@AccID
END
ELSE
BEGIN
SET @AccOpeningBal=@OpeningBalance
SET @AccType=@FAType
END
--Closing Balance
IF @Cond=1
BEGIN --Not Specify a Transaction
SELECT @Depit = ISNULL(SUM(Debit),0) , @Credit = ISNULL(SUM(Credit),0) FROM tblFAJournal WHERE [Status] IN(1,3,5,9,6,7)
AND AccountID = @AccID AND (BRSDate BETWEEN @BookDate AND @FDate)
--Reduce Amount Sales Invoice Modify
IF @TransId >0
BEGIN
SELECT @TempBal=Balance,@TempCustId=CustId FROM dbo.tblTranSalesHeader WHERE ID =@TransId
--Verify Same Customer or Not
IF ISNULL(@TempCustId,0) = (SELECT ISNULL(ID,0) FROM tblMasterCustomer WHERE FAID = @AccID)
BEGIN
SET @Depit = @Depit-ISNULL(@TempBal,0)
END
END
END
--Opening Balance
IF @Cond =2
BEGIN
--SELECT @lastDate
SET @lastDate = DATEADD(DAY ,-1,@FromDate)
SELECT @Depit = ISNULL(SUM(Debit),0) , @Credit = ISNULL(SUM(Credit),0) FROM tblFAJournal WHERE [Status] IN(1,3,5,9,6,7)
AND AccountID = @AccID AND (BRSDate BETWEEN @BookDate AND @lastDate)
END
IF @AccType =1
BEGIN
SET @Credit= @Credit+@AccOpeningBal;
END
IF @AccType =2
BEGIN
SET @Depit= @Depit+@AccOpeningBal;
END
--SELECT @Depit, @Credit, @Balance
IF(@Depit < @Credit)
BEGIN
SET @Balance = (@Credit - @Depit)
IF ISNULL(@OpeningBalance,0)=0
BEGIN
SELECT ISNULL(@Balance,0) AS [Balance],''Cr'' AS [Dr/Cr]
END
END
ELSE
BEGIN
SET @Balance = (@Depit - @Credit)
IF ISNULL(@OpeningBalance,0)=0
BEGIN
SELECT ISNULL(@Balance,0) AS [Balance],''Dr'' AS [Dr/Cr]
END
END
IF ISNULL(@OpeningBalance,0)!=0
BEGIN
SELECT @Balance AS [Balance],'''' AS [Dr/Cr]
END
END
END',
N'[export] nocount';
GO
/****** uspLoadBulkExpeses ******/
EXEC #Apply07 N'dbo.uspLoadBulkExpeses', 0xD82C6CB3E6467ACF6FF7F11968192A80C3B7980F5D1551CF540A3084AB89F562, NULL, NULL, 0xDDE7F79D91D659507E3F6E0AF7E17090E4AAFAFDEB388CED3F448A41575470F5, 0xDD02434C84359D76180831FCBD133A68D6B834A3C73268077E819A3DBB0B3C5B, NULL,
N'ALTER proc [dbo].[uspLoadBulkExpeses]          
as          
SET NOCOUNT ON;
begin          
WITH CTE                     
  AS(                    
  SELECT FAGroup,AccountGroupName as [Account Group Name],ParentGroup  FROM tblFAGroup                     
  WHERE AccountGroupName IN (''Income (Direct)'', ''Income (Indirect)'', ''Expenditure (Direct)'', ''Expenditure (Indirect)'')                    
  UNION ALL                    
  SELECT  G.FAGroup,G.AccountGroupName,G.ParentGroup FROM tblFAGroup G                    
  INNER JOIN CTE ON G.ParentGroup=CTE.FAGroup)               
            
    SELECT FAID,AccountName FROM tblFAAccount WHERE AccountGroup IN (SELECT FAGroup FROM CTE)                    
  AND  Active =1                  
  --order by AccountName asc       

  select ID,Name from tblMasterBranchOffice where Active = 1 order by Name
end',
N'[export] nocount';
GO
/****** uspLoadClosingBalance ******/
EXEC #Apply07 N'dbo.uspLoadClosingBalance', 0x8C0419F606EF51CC873539BD86B86626E4506A58AEF56647800640740CF79CD1, NULL, NULL, 0xD0E6E7FB5528BEAE0BF67FEDB92CBED5B2F69A063EE7F756DDE0957C25EC1932, 0xC01150D7EDB40A693A1243AD5D91FEF9E2816805EDC30E0984DBB311E5553613, NULL,
N'--[uspLoadClosingBalance] 1,2098,''2018-03-22''      
ALTER PROC [dbo].[uspLoadClosingBalance]      
@Cond SMALLINT,@AccID INT,@FromDate DATE=NULL, @OpeningBalance DECIMAL (25,6)=NULL,@FAType INT=NULL,@TransId INT =NULL      
AS      
SET NOCOUNT ON;
BEGIN      
SET DATEFORMAT dmy                                
IF ISNULL(@AccID,0)>0                                      
BEGIN      
DECLARE @Depit DECIMAL (25,6),@Credit DECIMAL (25,6)      
DECLARE @AccType INT,@AccOpeningBal DECIMAL (25,6),@TempBal DECIMAL (25,6),@Balance DECIMAL (25,6),@TempCustId INT      
DECLARE @lastDate DATE,@BookDate DATE                                        
--Book Start Date                                        
SELECT @BookDate = F_SD FROM dbo.tblCompanyRegistration WITH (READCOMMITTEDLOCK)                                        
DECLARE @FDate DATE                                        
IF ISNULL(@FromDate,'''')=''''                                        
BEGIN                                        
SET @FDate = GETDATE()                                        
END                                      
ELSE                                      
BEGIN                                      
SET @FDate = @FromDate                                      
END                                       
--Account Opening                                   
IF ISNULL(@OpeningBalance,0)=0                                  
BEGIN                                   
SELECT @AccOpeningBal=ISNULL(OpeningBalance,0),@AccType=FATypeID  FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE FAID =@AccID                                   
END                                  
ELSE                                  
BEGIN                                  
SET @AccOpeningBal=@OpeningBalance                                  
SET @AccType=@FAType                                  
END                                 
--Closing Balance                                        
IF @Cond=1                                       
BEGIN --Not Specify a Transaction                      
SELECT @Depit = ISNULL(SUM(Debit),0) , @Credit = ISNULL(SUM(Credit),0) FROM tblFAJournal WITH (READCOMMITTEDLOCK) WHERE [Status] IN(1,3,5,9,6,7)                                         
AND AccountID = @AccID AND ([DocDate] BETWEEN @BookDate AND  @FDate)        
--Reduce Amount Sales Invoice Modify                      
IF @TransId >0                                       
BEGIN                   
SELECT @TempBal=Balance,@TempCustId=CustId FROM dbo.tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id =@TransId        
--Verify Same Customer or Not        
IF ISNULL(@TempCustId,0) = (SELECT ISNULL(ID,0) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE FAID = @AccID)        
BEGIN                   
SET @Depit = @Depit-ISNULL(@TempBal,0)          
END                    
END                      
END                     
--Opening Balance                                        
IF @Cond =2                                        
BEGIN                                        
--SELECT @lastDate                                       
SET @lastDate = DATEADD(DAY ,-1,@FromDate)                                         
SELECT @Depit = ISNULL(SUM(Debit),0) , @Credit = ISNULL(SUM(Credit),0) FROM tblFAJournal WITH (READCOMMITTEDLOCK) WHERE [Status] IN(1,3,5,9,6,7)                                         
AND AccountID = @AccID AND ([DocDate] BETWEEN @BookDate AND  @lastDate)                                        
END                                        
IF @AccType =1                                        
BEGIN                                        
SET @Credit= @Credit+@AccOpeningBal;                                    
END                                         
IF @AccType =2                                        
BEGIN                                        
SET @Depit= @Depit+@AccOpeningBal;                                     
END                                         
--SELECT  @Depit,  @Credit, @Balance                                     
IF(@Depit < @Credit)                                            
BEGIN                     
SET @Balance = (@Credit - @Depit)                    
IF ISNULL(@OpeningBalance,0)=0                                  
BEGIN                                          
SELECT ISNULL(@Balance,0) AS [Balance],''Cr'' AS [Dr/Cr]  
END                                            
END                                      
ELSE                                            
BEGIN                                         
SET @Balance = (@Depit - @Credit)                                    
IF ISNULL(@OpeningBalance,0)=0                                  
BEGIN                                         
SELECT ISNULL(@Balance,0) AS [Balance],''Dr'' AS [Dr/Cr]  
END                                        
END                                 
IF ISNULL(@OpeningBalance,0)!=0                                  
BEGIN                                
SELECT @Balance AS [Balance],'''' AS [Dr/Cr]  
END                                   
END                                      
END',
N'[export] nocount;readcommittedlock=6';
GO
/****** uspLoadCollPaymentDetail ******/
EXEC #Apply07 N'dbo.uspLoadCollPaymentDetail', 0x6A3DEAC6A2D3361B1253C900E1CB55F6261C28AEB9638205C749E441D5D45C53, NULL, NULL, 0x95598A236097E7083F6D4ECC8C0224CBB4BF21F03439B07806CC841796CABD2F, 0x2E52F352BA309B94441A455C6B249306F847D2581EE7C37E3A44E968CCD2BBE5, NULL,
N'-- uspLoadCollPaymentDetail 19,959,''Mop''                
ALTER PROCEDURE [dbo].[uspLoadCollPaymentDetail]                
@DocPrefix INT,                
@CollPaymentID INT,                
@Mode NVARCHAR(50)                
AS                
SET NOCOUNT ON;
BEGIN                
IF @DocPrefix=19                
BEGIN                
IF @Mode=''Header''                
BEGIN                
SELECT CollHeader.DocID AS DocID,CollHeader.ColDate DocDate,CollHeader.ColDocRefNo RefNo,                
ISNULL(CollHeader.ColAmt,0) AS RecdAmt,CollHeader.ColMode PaymentModeID,CollHeader.AccID,Customer.Code,Customer.Name,                
CollHeader.UDFId,CollHeader.UDFDocId,CollHeader.UDFDocPrefix ,CollHeader.UDFDocValue,UDN.DocName,CollHeader.BeatID,Beat.Name BeatName,                
CollHeader.SalesManID,SM.Name SalesmanName,CollHeader.VisaPern, CollHeader.VisaAmt,Customer.ID PartyID,BTMode,CollHeader.ColID ID,                
CollHeader.Status,CollHeader.Remarks,CollHeader.Narration,ISNULL(CollHeader.BranchID,0) BranchID,MBO.Name BranchName ,    
dbo.fnTransactionPrefix(CollHeader.ColDate,BranchID,CollHeader.DocPrefix) Prefix         
FROM tblTranCollectionHeader AS CollHeader                
JOIN tblDocumentSeries AS DocSeries ON CollHeader.DocPrefix=DocSeries.TransID                
JOIN tblMasterCustomer AS Customer ON CollHeader.AccID=Customer.FAID                
LEFT JOIN tblMasterUserDefineNoHeader UDN ON UDN.UDNId = CollHeader.UDFId                
LEFT JOIN tblMasterBeat AS Beat ON Beat.id = CollHeader.BeatID                
LEFT JOIN tblMasterSalesMan AS SM ON SM.Id = CollHeader.SalesManID                
LEFT JOIN tblMasterBranchOffice AS MBO ON MBO.Id = CollHeader.BranchID          
WHERE CollHeader.ColID=@CollPaymentID AND CollHeader.DocPrefix=@DocPrefix                
END                
IF @Mode=''Mop''                
BEGIN                
SELECT CollAmt RecdAmt,PaymentMode.Id PaymentModeID,Header.AccID ,[Cheque/DD Number] [ChequeDDNumber],NeftID,
CASE WHEN Date IS NULL THEN Header.ColDate ELSE Date end Date,PayAt,CollPMDetails.IfscCode IFSC,CollPMDetails.BankName,                
CollPMDetails.BranchName,CollPMDetails.CollAmt DocAmount,BankAccount.AccountNo,BankAccount.ID,0 ChequeRefNoWithChequeNo,isnull(BankAccount.FAID,0) BankFAID,isnull(BANK.ID,0) BankID                
FROM tblCollPMDetails AS CollPMDetails                
LEFT JOIN tblTranCollectionHeader AS Header ON Header.ColID=CollPMDetails.ColID                
LEFT JOIN tblMasterBankAccount AS BankAccount ON CollPMDetails.BankAccID=BankAccount.FAID                
LEFT JOIN tblMasterBank AS BANK ON BankAccount.BANKID=BANK.ID                
JOIN tblPaymentMode AS PaymentMode ON Header.ColMode=PaymentMode.Id WHERE CollPMDetails.ColID=@CollPaymentID                
END                
IF @Mode=''Detail''                
BEGIN                
SELECT --DocSeries.DocPrefix+Convert(NVARCHAR(50),Detail.DocValue) AS DocID,  
CASE WHEN Detail.DocPrefix=15 THEN Sales.DocID WHEN Detail.DocPrefix=16 THEN Sales.DocID WHEN Detail.DocPrefix=4 OR Detail.DocPrefix=5 THEN Notes.DocID                
WHEN Detail.DocPrefix=19 THEN Header.DocID WHEN Detail.DocPrefix=7 THEN PRVID.DocID ELSE '''' END AS DocID,  
Convert(varchar,Detail.[Date],103) as DocDate,                
CASE WHEN Detail.DocPrefix=15 THEN Sales.DocRef WHEN Detail.DocPrefix=16 THEN Sales.DocRef WHEN Detail.DocPrefix=4 OR Detail.DocPrefix=5 THEN Notes.RefNo                
WHEN Detail.DocPrefix=19 THEN Header.ColDocRefNo WHEN Detail.DocPrefix=7 THEN PRVID.RefNo ELSE '''' END AS RefNo,  
DocSeries.TransName,Detail.ColValue NetAmount,Detail.AdjAmt,Detail.DiscPercentage DiscPern,Detail.DiscAmt,Detail.FullyAdj,                
detail.TotalAmtAdj,Detail.FullyAdjAmt,Detail.DocID,Detail.DocValue,Detail.DocPrefix,                
CASE WHEN Detail.DocPrefix=15 THEN Sales.NetAmt WHEN Detail.DocPrefix=16 THEN Sales.NetAmt WHEN Detail.DocPrefix=4 OR Detail.DocPrefix=5 THEN Notes.NoteValue                
WHEN Detail.DocPrefix=19 THEN Header.ColAmt WHEN Detail.DocPrefix=7 THEN PRVID.NetAmount ELSE 0.00 END AS DocumentAmount,                
CASE WHEN Detail.DocPrefix=15 THEN Sales.UDFDocId WHEN Detail.DocPrefix=16 THEN Sales.UDFDocId WHEN Detail.DocPrefix=4 OR Detail.DocPrefix=5 THEN Notes.UDFDocId                
WHEN Detail.DocPrefix=19 THEN Header.UDFDocId WHEN Detail.DocPrefix=7 THEN PRVID.UDFDocId ELSE NULL END AS UDFDocId               
,DATEDIFF(DD,Detail.Date,GETDATE()) Ageing ,ISNULL(Detail.ReasonID,0) ReasonID,MRR.Name ReasonName            
FROM tblTranCollectionDetail AS Detail                
LEFT JOIN tblTranSalesHeader AS Sales ON Detail.DocID=Sales.ID                
LEFT JOIN tblNoteDetails AS Notes ON Detail.DocID=Notes.ID                
LEFT JOIN tblTranPRVoucher AS PRVID ON PRVID.ID = Detail.DocID                
LEFT JOIN tblTranCollectionHeader AS Header ON Detail.DocID=Header.ColID                
JOIN tblDocumentSeries AS DocSeries ON Detail.DocPrefix=DocSeries.TransID                
LEFT JOIN tblMasterReason MRR ON MRR.ID = Detail.ReasonID            
WHERE Detail.ColID=@CollPaymentID                
END                
END                
IF @DocPrefix=18                
BEGIN                
IF @Mode=''Header''                
BEGIN                
SELECT PYHeader.DocID AS DocID,PYHeader.PYDate DocDate,PYHeader.PYDocRefNo RefNo,                
ISNULL(PYHeader.PYAmt,0) AS RecdAmt,PYHeader.PYMode PaymentModeID,PYHeader.AccID,Vendor.Code,Vendor.name,PYHeader.UDFId,PYHeader.UDFDocId,          
PYHeader.UDFDocPrefix ,PYHeader.UDFDocValue,UDN.DocName,0 BeatID,null BeatName,0 SalesManID,null SalesmanName,PYHeader.VisaPern,          
PYHeader.VisaAmt,Vendor.id PartyID,BTMode,PYHeader.PYID ID,PYHeader.Status,PYHeader.Remarks,PYHeader.Narration,          
ISNULL(PYHeader.BranchID,0) BranchID,MBO.Name BranchName,dbo.fnTransactionPrefix(PYHeader.PYDate,BranchID,PYHeader.PYPrefix) Prefix                
FROM tblTranPaymentHeader AS PYHeader                
JOIN tblDocumentSeries AS DocSeries ON PYHeader.PYPrefix=DocSeries.TransID                
JOIN tblMasterVendor AS Vendor ON PYHeader.AccID=Vendor.FAID                
LEFT JOIN tblMasterUserDefineNoHeader UDN ON UDN.UDNId = PYHeader.UDFId            
LEFT JOIN tblMasterBranchOffice AS MBO ON MBO.Id = PYHeader.BranchID          
WHERE PYHeader.PYID=@CollPaymentID AND PYHeader.PYPrefix=@DocPrefix                
END                
IF @Mode=''Mop''                
BEGIN                
SELECT PMDetails.PYAmt RecdAmt,PaymentMode.Id PaymentModeID,Header.AccID ,[Cheque/DD Number] [ChequeDDNumber],NeftID,
CASE WHEN Date IS NULL THEN Header.PYDate ELSE Date end Date,PayAt,BankAccount.IfscCode IFSC,BANK.Name BankName,                
BankAccount.BranchName,PMDetails.PYAmt DocAmount,BankAccount.AccountNo,BankAccount.ID,isnull(ChequeRefNoWithChequeNo,0) ChequeRefNoWithChequeNo,isnull(BankAccount.FAID,0) BankFAID,isnull(BANK.ID,0) BankID                
FROM tblPaymentPMDetail AS PMDetails                
LEFT JOIN tblTranPaymentHeader AS Header ON Header.PYID=PMDetails.PYID                
LEFT JOIN tblMasterBankAccount AS BankAccount ON PMDetails.BankAccID=BankAccount.FAID                
LEFT JOIN tblMasterBank AS BANK ON BankAccount.Bankid=BANK.ID                
JOIN tblPaymentMode AS PaymentMode                
ON Header.PYMode=PaymentMode.Id WHERE PMDetails.PYID=@CollPaymentID                
END                
IF @Mode=''Detail''                
BEGIN                
SELECT --DocSeries.DocPrefix+Convert(NVARCHAR(50),Detail.DocValue) AS DocID,  
CASE WHEN Detail.DocPrefix=1 THEN Bill.DocID WHEN Detail.DocPrefix=12 THEN Bill.DocID                
WHEN Detail.DocPrefix=5 OR Detail.DocPrefix=4 THEN Notes.DocID  
WHEN Detail.DocPrefix=6 THEN PV.DocID WHEN Detail.DocPrefix=18 THEN Header.DocID ELSE '''' END AS DocID,  
Convert(varchar,Detail.[Date],103) as DocDate,                
CASE WHEN Detail.DocPrefix=1 THEN Bill.RefNo WHEN Detail.DocPrefix=12 THEN Bill.RefNo                
WHEN Detail.DocPrefix=5 OR Detail.DocPrefix=4 THEN Notes.RefNo WHEN Detail.DocPrefix=18 THEN Header.PYDocRefNo ELSE '''' END AS RefNo,                
  
DocSeries.TransName,Detail.BillPYValue NetAmount,Detail.AdjAmt,Detail.DiscPercentage DiscPern,Detail.DiscAmt,Detail.FullyAdj,detail.TotalAmtAdj,                
Detail.FullyAdjAmt,Detail.DocID,Detail.DocValue,Detail.DocPrefix,                
CASE WHEN Detail.DocPrefix=1 THEN Bill.NetAmt WHEN Detail.DocPrefix=12 THEN Bill.NetAmt                
WHEN Detail.DocPrefix=5 OR Detail.DocPrefix=4 THEN Notes.NoteValue WHEN Detail.DocPrefix=18 THEN Header.PYAmt                
ELSE 0.00 END AS DocumentAmount,                
CASE WHEN Detail.DocPrefix=1 THEN Bill.UDFDocId WHEN Detail.DocPrefix=12 THEN Bill.UDFDocId                
WHEN Detail.DocPrefix=5 OR Detail.DocPrefix=4 THEN Notes.UDFDocId WHEN Detail.DocPrefix=18 THEN Header.UDFDocId                
ELSE NULL END AS UDFDocId ,DATEDIFF(DD,Detail.Date,GETDATE()) Ageing ,ISNULL(Detail.ReasonID,0) ReasonID,MRR.Name ReasonName              
FROM tblTranPaymentDetail AS Detail                
LEFT JOIN tblTransPurchaseHeader AS Bill ON Detail.DocID=Bill.ID                
LEFT JOIN tblNoteDetails AS Notes ON Detail.DocID=Notes.ID                
LEFT JOIN tblTranPaymentHeader AS Header ON Detail.DocID=Header.PYID                
JOIN tblDocumentSeries AS DocSeries ON Detail.DocPrefix=DocSeries.TransID                
LEFT JOIN tblMasterReason MRR ON MRR.ID = Detail.ReasonID  
LEFT JOIN tblTranPRVoucher PV ON PV.ID = Detail.DocID  
WHERE Detail.PYID=@CollPaymentID                
END                
END                
END',
N'[export] nocount';
GO
/****** uspLoadDeliveryDocumentData ******/
EXEC #Apply07 N'dbo.uspLoadDeliveryDocumentData', 0x59280D10F4827801115D191C4C26CBB74FF6DF2250371D2EF6B34AF329A31508, NULL, NULL, 0xD5FFEEA80D113EABBBB8303F97D05FE286F75D83E9863C30C24A4706B52395A1, 0xC7B3B6AF6F26E7AE970402B42E0480B2BCC5B7AC2630E787FA9EC47E5E8978B5, NULL,
N'ALTER PROC [dbo].[uspLoadDeliveryDocumentData] 
@Branch INT = 4,@FromDate DATE = ''2025-05-01'',@ToDate DATE = ''2025-11-11'',@DocRange NVARCHAR(MAX) = NULL,
@CustID NVARCHAR(MAX) = NULL,@FilterBy int = 1,@TransMode int =0,@DeliveryID int = 0
as
SET NOCOUNT ON;
begin
CREATE table #DeliProcs1(InvIdentID INT,IsMods INT)      
CREATE table #DeliProcs(InvIdentID INT,IsMods INT)      
INSERT INTO #DeliProcs1      
select DD.InvIdentID,1 from tblDeliveryOrderHeader DH                    
JOIN tblDeliveryOrderDetail DD ON DD.DOID = DH.ID                    
JOIN tblTranSalesHeader DSH ON DSH.ID = DD.InvIdentID      
WHERE DD.Status in (1,5) AND DH.Status IN (1,3,5) group by DD.InvIdentID      
IF(@TransMode = 4)      
BEGIN      
INSERT INTO #DeliProcs1      
SELECT InvIdentID,2 FROM tblDeliveryOrderDetail WHERE DOID = @DeliveryID      
GROUP BY InvIdentID      
END      
INSERT INTO #DeliProcs      
SELECT InvIdentID,MAX(IsMods) FROM #DeliProcs1 GROUP BY InvIdentID      
DECLARE @StrQuery NVARCHAR(MAX)    

create table #docids(value int)
if(ISNULL(@DocRange,'''') <> '''')
BEGIN
INSERT INTO #docids
SELECT value FROM STRING_SPLIT(LEFT(@DocRange, LEN(@DocRange) - 1), '','')
END
select SH.DocValue,SH.DocId DocId,  
FORMAT(SH.InvDate,''dd/MMM/yyyy'') DocDate,MB.Name BeatName,MB.Name SalesmanName,MC.Name,SH.DocRef RefNo,dbo.fnGetRoundedValue(SH.NetAmt) NetAmt ,        
COUNT(SD.ProdID) ItemsCount        
from tblTranSalesHeader SH                  
JOIN tblMasterCustomer MC ON MC.Id = SH.CustId  
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID  
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesmanID  
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID WHERE SH.DocPrefix = 15 AND SH.BranchID = @Branch AND Status IN (1,3,5) 
AND SH.InvDate BETWEEN @FromDate and @ToDate   AND (
        ISNULL(@FilterBy,0) = 1
        OR (ISNULL(@FilterBy,0) = 2 AND IRN IS NOT NULL)
        OR (ISNULL(@FilterBy,0) NOT IN (1,2) AND IRN IS NULL)
    )
    AND (
        ISNULL(@DocRange,'''') = ''''
        OR SH.DocValue IN (SELECT value FROM #docids)
    ) and
SD.TaxID > 0 
 AND SH.ID NOT IN (SELECT InvIdentID FROM #DeliProcs WHERE IsMods = 1)
 GROUP BY SH.DocId,SH.InvDate,MC.Name,SH.DocValue,SH.DocRef,SH.NetAmt,SH.ReturnsTransType,MB.Name,MB.Name order by SH.DocValue
 drop table #DeliProcs,#DeliProcs1 
 end',
N'[export] nocount';
GO
/****** uspLoadDeliveryDocumentData_new ******/
EXEC #Apply07 N'dbo.uspLoadDeliveryDocumentData_new', 0xE6B2DA255B0CF241488A5880AF49BB1BFB6E7D993A2C5D5BA3AE16ED0EA13F16, 0xDF79E02EBBE930886ED415274D43902580CCABDF57DEE76E11DEAED85BBAC3C3, NULL, 0xF5974231EEC7C3AC553BA0E36643CB6D86DCFC3EB45F42129BAA122A420EA465, 0xD201BD67AC32AF37BB3F33907FB6E4E10537F0028D4F1DC7FCB0DD48F826B054, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspLoadDeliveryDocumentData_new]          
@Branch INT = 4,@nMode INT = 1,@DOID INT = 0 ,@CustID NVARCHAR(255)='''', @BeatID NVARCHAR(255)='''',@SalesManID NVARCHAR(255)='''',          
@FromDate DATE = NULL,@ToDate DATE = NULL ,@InclDoc INT = 0,        
@DocID NVARCHAR(MAX) = NULL         
AS          
SET NOCOUNT ON;
BEGIN          
CREATE table #DeliProcs1(InvIdentID INT,IsMods INT)          
CREATE table #DeliProcs(InvIdentID INT,IsMods INT)          
INSERT INTO #DeliProcs1          
select DD.InvIdentID,1 from tblDeliveryOrderHeader DH          
JOIN tblDeliveryOrderDetail DD ON DD.DOID = DH.ID          
JOIN tblTranSalesHeader DSH ON DSH.ID = DD.InvIdentID          
WHERE DD.Status in (1,5) AND DH.Status IN (1,3,5) group by DD.InvIdentID          
IF(@nMode = 4)          
BEGIN          
INSERT INTO #DeliProcs1          
SELECT InvIdentID,2 FROM tblDeliveryOrderDetail WHERE DOID = @DOID          
GROUP BY InvIdentID          
END          
INSERT INTO #DeliProcs          
SELECT InvIdentID,MAX(IsMods) FROM #DeliProcs1 GROUP BY InvIdentID          
DECLARE @StrQuery NVARCHAR(MAX)          
IF(ISNULL(@InclDoc,0) = 0)          
BEGIN          
set @StrQuery = ''SELECT SH.ID,SH.Status Status,DocId,CONVERT(NVARCHAR,InvDate,103) InvDate,DocRef,MC.Name,          
MB.Name BeatName,MB.Name SalesmanName,          
dbo.fnGetRoundedValue(SH.NetAmt) NetAmt,ISNULL(DP.IsMods,1) IsMods          
FROM tblTranSalesHeader SH          
JOIN tblMasterCustomer MC ON MC.Id = SH.CustId          
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID          
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesmanID          
LEFT JOIN #DeliProcs DP on DP.InvIdentID = SH.ID AND DP.IsMods = 2          
WHERE DocPrefix = 15 AND STATUS IN (1,3,5) AND SH.BranchID =  @Branch ''          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.InvDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocID,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(@DocID, N'''',''''))'' END)          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustID,'''')='''' THEN '''' ELSE '' AND SH.CustId in (SELECT id FROM dbo.fnSplitString(@CustID, N'''',''''))'' END)          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatID,'''')='''' THEN '''' ELSE '' AND SH.BeatID in (SELECT id FROM dbo.fnSplitString(@BeatID, N'''',''''))'' END)          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesManID,'''')='''' THEN '''' ELSE '' AND SH.SalesmanID in (SELECT id FROM dbo.fnSplitString(@SalesManID, N'''',''''))'' END)          
SET @StrQuery = @StrQuery + '' AND SH.ID NOT IN (SELECT InvIdentID FROM #DeliProcs WHERE IsMods = 1)''          
SET @StrQuery = @StrQuery + '' ORDER BY DocId,ID''          
EXEC sys.sp_executesql @StrQuery, N''@Branch INT, @nMode INT, @DOID INT, @CustID NVARCHAR(255), @BeatID NVARCHAR(255), @SalesManID NVARCHAR(255), @FromDate DATE, @ToDate DATE, @InclDoc INT, @DocID NVARCHAR(MAX)'', @Branch, @nMode, @DOID, @CustID, @BeatID, @SalesManID, @FromDate, @ToDate, @InclDoc, @DocID          
END          
ELSE          
BEGIN          
set @StrQuery = ''SELECT * FROM (SELECT SH.ID,SH.Status Status,DocId,CONVERT(NVARCHAR,InvDate,103) InvDate,DocRef,MC.Name,          
dbo.fnGetRoundedValue(SH.NetAmt) NetAmt,ISNULL(DP.IsMods,1) IsMods FROM tblTranSalesHeader SH          
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId          
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID          
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesmanID          
LEFT JOIN #DeliProcs DP on DP.InvIdentID = SH.ID AND DP.IsMods = 2          
WHERE DocPrefix = 15 AND STATUS IN (1,3) AND SH.BranchID =  @Branch '' -- AND SH.InvDate BETWEEN @FromDate AND @ToDate          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.InvDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustID,'''')='''' THEN '''' ELSE '' AND SH.CustId in (SELECT id FROM dbo.fnSplitString(@CustID, N'''',''''))'' END)          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatID,'''')='''' THEN '''' ELSE '' AND SH.BeatID in (SELECT id FROM dbo.fnSplitString(@BeatID, N'''',''''))'' END)          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesManID,'''')='''' THEN '''' ELSE '' AND SH.SalesmanID in (SELECT id FROM dbo.fnSplitString(@SalesManID, N'''',''''))'' END)          
SET @StrQuery = @StrQuery + '' AND SH.ID NOT IN (SELECT InvIdentID FROM #DeliProcs WHERE IsMods = 1)''          
SET @StrQuery = @StrQuery + '' union ''          
set @StrQuery = @StrQuery + ''SELECT InvId,SH.Status,DocId,CONVERT(NVARCHAR,InvDate,103) InvDate,DocRef,MC.Name,          
dbo.fnGetRoundedValue(SH.NetAmt) NetAmt,ISNULL(DP.IsMods,1) IsMods FROM tblTranSalesHeader SH          
JOIN tblMasterCustomer MC ON MC.ID = SH.CustId          
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID          
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesmanID          
LEFT JOIN #DeliProcs DP on DP.InvIdentID = SH.ID AND DP.IsMods = 2          
WHERE DocPrefix = 15 AND STATUS IN (1,3) AND SH.BranchID =  @Branch '' -- AND SH.InvDate BETWEEN @FromDate AND @ToDate          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@FromDate,'''')='''' and ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND SH.InvDate BETWEEN ''+'' @FromDate '' +'' AND '' +'' @ToDate '' +'''' END)          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@DocID,'''')='''' THEN '''' ELSE '' AND SH.DocValue in (SELECT id FROM dbo.fnSplitString(@DocID, N'''',''''))'' END)          
SET @StrQuery = @StrQuery + '' AND SH.ID NOT IN (SELECT InvIdentID FROM #DeliProcs WHERE IsMods = 1)) AS REC''          
SET @StrQuery = @StrQuery + '' ORDER BY DocId,Id''          
EXEC sys.sp_executesql @StrQuery, N''@Branch INT, @nMode INT, @DOID INT, @CustID NVARCHAR(255), @BeatID NVARCHAR(255), @SalesManID NVARCHAR(255), @FromDate DATE, @ToDate DATE, @InclDoc INT, @DocID NVARCHAR(MAX)'', @Branch, @nMode, @DOID, @CustID, @BeatID, @SalesManID, @FromDate, @ToDate, @InclDoc, @DocID          
          
END          
drop table #DeliProcs,#DeliProcs1          
END',
N'[06] nocount';
GO
/****** uspLoadDeliveryProductData ******/
EXEC #Apply07 N'dbo.uspLoadDeliveryProductData', 0xEED4D562F99FA04A9B40F405D7488EE7F3860EBD425C5B541F759C3599ED00F0, NULL, NULL, 0x3E83AF139D3CAF1C4593961DB681667B2EC44551F67246585484A4FB21352576, 0x21CF1AA5FADEE56B6C8E596CEE0828E6886295B37DBA1D876B708FB647D6FACF, NULL,
N'ALTER PROC [dbo].[uspLoadDeliveryProductData]                
 @BranchID int = 4,@TransMode int = 0,@DeliveryID int = 0,@tvpIdentId tvpIdentId READONLY  
 AS                
 SET NOCOUNT ON;
BEGIN          
 DECLARE @nCount INT = (SELECT COUNT(*) FROM @tvpIdentId),@nIncr INT = 1,@InvID INT    
  
CREATE TABLE #TempData(ProdID INT,Code NVARCHAR(255), Name NVARCHAR(255), [MfrName] NVARCHAR(255), [BrandName] NVARCHAR(255), [CategoryName] NVARCHAR(255),           
 [BaseUOMQty] DECIMAL(25,6), [BaseUOM] NVARCHAR(255), [SalesUOMQty] DECIMAL(25,6), [SalesUOM] NVARCHAR(255),           
 [ReportingUOMQty] DECIMAL(25,6), [ReportingUom] NVARCHAR(255), [MRP] DECIMAL(25,6), [Value] DECIMAL(25,6),           
 ProdRepQty DECIMAL(25,6),ConvFact DECIMAL(25,6))       
 WHILE(@nCount >= @nIncr)          
BEGIN          
SELECT @InvID = DocumentId FROM @tvpIdentId WHERE Status = @nIncr   
 INSERT INTO #TempData  
SELECT ProdID,Temp.[Product Code],Temp.[Product Name],Temp.[Manufacturer Name] [Mfr Name],[Brand Name],[Category Name],(SUM(Temp.[Base UOM Qty]))AS [Base UOM Qty],          
[Base UOM],(SUM(Temp.[Sales UOM Qty]))AS [Sales UOM Qty],[Sales UOM],          
(SUM(Temp.[Reporting UOM Qty])) AS [Reporting UOM Qty],[Reporting Uom],                  
(ISNULL(Temp.[MRP On Price],0)) AS [MRP On Price],(SUM(Temp.Value)) AS [Value],ReportingQty,ConvFact  
 FROM (                              
SELECT TSH.ProdID,MP.Code AS [Product Code],MP.Name AS [Product Name],MP.EAN,                              
MMF.Name AS [Manufacturer Name],MBN.Name [Brand Name],PHL.Name [Category Name],                      
SUM(TSH.UomQty * isnull(TSH.UOMCF,1)) AS [Base UOM Qty],                              
sum(TSH.NetAmt) AS [Value],Uom.Name AS [Base UOM],Uom1.Name AS [Sales UOM],                              
SUM(TSH.UomQty) AS [Sales UOM Qty],  
 UOM2.Name AS [Reporting Uom],                  
(SUM((TSH.UomQty * isnull(TSH.UOMCF,1)) / nullif(MP.ReportingQty,0))) as [Reporting UOM Qty],  
TSH.DetailMRP AS [MRP On Price],MP.ReportingQty,isnull(TSH.UOMCF,1) ConvFact            
FROM tblTranSalesHeader AS TSD WITH (READCOMMITTEDLOCK)  
JOIN tblTranSalesDetail AS TSH WITH (READCOMMITTEDLOCK) ON TSH.InvId = TSD.ID                
JOIN tblMasterProduct AS MP WITH (READCOMMITTEDLOCK) ON MP.ID = TSH.ProdId                      
JOIN tblMastERManufacturer AS MMF WITH (READCOMMITTEDLOCK) ON MMF.id = MP.MfrID                              
JOIN tblMasterBrand MBN WITH (READCOMMITTEDLOCK) ON MBN.ID = MP.BrandID                      
JOIN tblMasterCategory PHL WITH (READCOMMITTEDLOCK) ON PHL.ID = MP.CategoryID                      
LEFT JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = TSH.InventoryId          
LEFT JOIN tblMasterUom AS Uom WITH (READCOMMITTEDLOCK) ON Uom.ID = MP.BaseUomID                              
LEFT JOIN tblMasterUom AS Uom1 WITH (READCOMMITTEDLOCK) ON Uom1.ID = MP.SalesUomID  
left JOIN tblMasterUom AS [UOM2] WITH (READCOMMITTEDLOCK) ON UOM2.ID = mp.ReportingUomID                  
WHERE TSD.Status IN (1,3,5) AND DocPrefix = 15 AND TSD.ID = @InvID and TSD.BranchID = @BranchID and TSH.TaxId > 0               
GROUP BY  TSH.ProdID,MP.Code,MP.Name,MP.EAN,MMF.Name,Uom.Name, Uom1.Name ,                              
TSH.DetailMRP,TSD.DocPrefix,TSD.ID,MBN.Name,PHL.Name, Uom2.Name,MP.ReportingQty,TSH.UomId,TSH.UOMCF)AS Temp                            
GROUP BY ProdID,Temp.[Product Code],Temp.[Product Name],Temp.EAN,Temp.[Manufacturer Name],                              
[Base UOM],[Sales UOM],[MRP On Price],[Brand Name],[Category Name],[Reporting Uom],ReportingQty,ConvFact          
SET @nIncr = @nIncr + 1;          
END   
SELECT ProdID,Code,Name,MfrName,BrandName,CategoryName,dbo.fngetroundedvalue(MRP) MRP,concat(dbo.fngetroundedvalue(SUM(BaseUOMQty)),''/'',BaseUOM) BaseUOM  
,concat(dbo.fngetroundedvalue(SUM(SalesUOMQty)),''/'',SalesUOM) SalesUOM,concat(dbo.fngetroundedvalue(SUM(ReportingUOMQty)),''/'',ReportingUom) ReportingUom,  
dbo.fngetroundedvalue(sum(Value)) Value  
FROM #TempData  
group by ProdID,Code,Name,MfrName,BrandName,CategoryName,BaseUOM,SalesUOM,ReportingUom,MRP  
DROP TABLE #TempData  
end',
N'[export] nocount;readcommittedlock=10';
GO
/****** uspLoadManufItemsinPO ******/
EXEC #Apply07 N'dbo.uspLoadManufItemsinPO', 0x8DD46C57E6688E1162AF591971A94D4D53A742D2F456E3E1CDE932C863BFED8D, NULL, NULL, 0xB30397F90B3BDCCA92B81DE407E76A99070B6C07FB8D991CCB38181BDEBB7468, 0xF124F3A7A2F83FCE9AC6D8EF1ABCE4F8E706BC7FA2E5687C564491AB56C3E495, NULL,
N'ALTER proc [dbo].[uspLoadManufItemsinPO]    
@VendID INT = 6,@ManufID nvarchar(100) = ''21,25,39'',@Days INT = 25,@Avg INT = 2,@BaseorPurchaseUOM int = 1,
@BranchID int = 1
-- :-) 1 - base,2 - purchase    
as    
SET NOCOUNT ON;
begin    
DECLARE @FromDate DATE = CAST(DATEADD(DAY,(ISNULL(@Days,0) * -1),GETDATE()) AS DATE)    
DECLARE @ToDate DATE = CAST(GETDATE() AS DATE)    
select ProdID,Code,Name,UOMID,TaxID,TaxPern,ConvValue,UomName,Qty,ExclPrice,InclPrice,TaxName,ExclPrice * Qty GrossAmt,    
((ExclPrice * Qty) * TaxPern) / 100 TaxAmt,InclPrice * Qty NetAmt,MRPonTax,MRP,isnull(CumMRPonTax,0) CumMRPonTax,
ISNULL(ActualQty,0) ActualQty,isnull(ActualFreeQty,0) ActualFreeQty from (    
SELECT P.[Id] ProdID,P.[Code],P.[Name],CASE WHEN @BaseorPurchaseUOM = 1 THEN P.BaseUomID else [PurchaseUomID] end UOMID,    
tax.TaxID,tax.GST TaxPern,CASE WHEN @BaseorPurchaseUOM = 1 THEN  P.BaseCR ELSE P.PurchaseCR END ConvValue,    
CASE WHEN @BaseorPurchaseUOM = 1 THEN  BU.[Name] ELSE PU.[Name] END UomName,    
CASE WHEN @BaseorPurchaseUOM = 1 THEN  P.PurchasePrice ELSE ISNULL(P.PurchasePrice,0) * p.PurchaseCR END AS ExclPrice,    
dbo.fngetInclusiveValue(tax.TaxID,P.MRP,P.PurchasePrice)  * p.PurchaseCR AS InclPrice,    
tax.TaxName,    
Ceiling((SELECT ISNULL(SUM(UomQty),0)/ ISNULL(p.PurchaseCR,1) FROM tblTranSalesDetail AS SD    
JOIN tblTranSalesHeader AS SH ON SH.ID = SD.InvId    
WHERE Status IN (1,3,5) AND SH.DocPrefix=15 AND SD.ProdId=P.ID AND SH.InvDate BETWEEN @FromDate AND @ToDate) / ISNULL(@Avg,1)) AS [Qty],    
isnull(dbo.fngetMRPonCumValue(0,PurchaseTaxId,1,p.MRP),0) MRPonTax,P.MRP,SUM(dbo.fngetMRPonCumValue(0,PurchaseTaxId,1,0)) CumMRPonTax,
SUM(Inv.ActualQty) ActualQty,SUM(Inv.ActualFreeQty) ActualFreeQty
FROM tblMasterProduct P    
JOIN tblMasterUOM PU ON PU.ID =P.PurchaseUomID    
JOIN tblMasterUOM BU ON BU.ID =P.BaseUomID    
JOIN tblMasterTax as tax ON tax.TaxID = PurchaseTaxId    
LEFT JOIN tblProductInventory AS Inv ON Inv.ProdId= P.ID and Inv.BranchID = @BranchID
LEFT JOIN tblMasterVendor MV ON MV.ID = P.VendorID    
WHERE P.VendorID = @VendID AND P.MfrID in (select * from string_split(@ManufID,'','')) AND P.TrackInventory = 1 AND P.Active = 1    
GROUP BY P.[Id],P.[Code],P.[Name],[PurchaseUomID],PU.[Name],P.PurchasePrice,P.BaseCR,    
tax.TaxName,tax.TaxID,MV.taxtypeid,p.PurchaseCR,tax.GST,PurchaseTaxId,p.MRP,BU.[Name],P.BaseUomID)    
as Rec    
ORDER BY Name    
end',
N'[export] nocount';
GO
/****** uspLoginHistroy ******/
EXEC #Apply07 N'dbo.uspLoginHistroy', 0x64560DFFD165D2A4F115E825E625E8886F119BE7C0E8880F4817C878CB67CFDF, NULL, NULL, 0xD3A86EEF6951494A5473600870366CB82DBB0C2020FC5E03C4B64ADC7BE6ABE2, 0xD35CD11C52D1DA1E2FED73FB32AE309E97E6375B33F2642C73BFCE58A47800C8, NULL,
N'ALTER proc [dbo].[uspLoginHistroy]
@Mode INT = 2,@UserID int = 2,@FromDate date = ''2026-02-12'',@ToDate date = ''2026-08-15''
as
SET NOCOUNT ON;
begin
if(@Mode = 1)
BEGIN
select ID,UserName from tblUsers WHERE ID <> 1 AND Active = 1 ORDER BY UserName
END
ELSE IF(@Mode = 2)
BEGIN
select UserID,SessionID,FORMAT(LoginTime,''dd/MMM/yyyy hh:mm:ss tt'') LoginTime,
FORMAT(LogoutTime,''dd/MMM/yyyy hh:mm:ss tt'') LogoutTime,Latitude,Longtitude
from tblLoginHistory L where UserID = @UserID AND CONVERT(date,LoginTime) BETWEEN @FromDate AND @ToDate
ORDER BY L.LoginTime
END
end',
N'[export] nocount';
GO
/****** uspLoginInfoRecieve ******/
EXEC #Apply07 N'dbo.uspLoginInfoRecieve', 0x83E2EE939550A36802DCE6851FA9B0AE7145743B0F7FAD549C86EECA5DBB8E73, NULL, NULL, 0x1DDC7DEC2F54A348DD0DC66EBF14A96177D848A3A4069F26D960FF755F09889E, 0x29FE3B5997B0DD65C2D8EF7832B884599EFE8076C6857B742EEAFCB9BFE183FC, NULL,
N'ALTER proc [dbo].[uspLoginInfoRecieve]                            
@Mode SMALLINT,@TokenValue NVARCHAR(MAX) = NULL,@UserID SMALLINT = NULL,@DeviceIdent SMALLINT = NULL,  
@AllowMobDevCount int = 1  
AS                            
SET NOCOUNT ON;
BEGIN                            
IF(@Mode = 1)                            
BEGIN                            
select * from tblMobileLogin WITH (READCOMMITTEDLOCK) where TokenValue = @TokenValue                            
END                            
ELSE IF(@Mode = 2)                            
BEGIN                           
select * from tblMobileLogin WITH (READCOMMITTEDLOCK) where UserID = @UserID AND SessionStatus = 1                
ENd                        
else IF(@Mode = 3)                         
begin                
select lg.SessionStatus,lg.DataBaseName,UD.DeviceID,TokenValue from tblMobileDevicePermission PV WITH (READCOMMITTEDLOCK)                 
JOIN tblMobileDeviceInfo UD WITH (READCOMMITTEDLOCK) ON UD.ID = PV.DeviceIdent                
JOIN tblMobileLogin lg WITH (READCOMMITTEDLOCK) on lg.UserID = PV.UserID                
WHERE lg.userID = @UserID and PV.DeviceIdent = @DeviceIdent                
--select * from tblMobileDeviceInfo dv join tblMobileLogin lg on lg.UserID = dv.UserID where DeviceID = @TokenValue                         
end                      
else IF(@Mode = 4)                         
begin   
  
select DeviceName,UD.DeviceID,UserID,dv.Active,UR.UserName,DV.DeviceIdent,UR.MobileNumber  
from tblMobileDevicePermission dv WITH (READCOMMITTEDLOCK)                 
JOIN tblMobileDeviceInfo UD WITH (READCOMMITTEDLOCK) ON UD.ID = DV.DeviceIdent      
JOIN TBLUSERS UR WITH (READCOMMITTEDLOCK) ON UR.ID = DV.USERID      
where devicename is not null order by dv.requesttime       

select MobileDevices  from tblCompanyRegistration WITH (READCOMMITTEDLOCK) where CompanyId = 1  
end                      
else IF(@Mode = 5)                         
begin                        
if((SELECT count(*) MobCount FROM tblMobileDevicePermission WITH (READCOMMITTEDLOCK) where Active = 1) < @AllowMobDevCount)  
BEGIN  
update tblMobileDevicePermission set Active = 1,ActivatedTime = getdate(),DeActivatedTime = null           
where UserID = @UserID AND DeviceIdent = @DeviceIdent      
END  
ELSE  
BEGIN  
SELECT ''Maximum Device Approval Limit Reached. Please remove an existing approved device before approving a new device.''  
END  
end                      
else IF(@Mode = 6)                         
begin                        
--update tblMobileDevicePermission set Active = 0,DeActivatedTime = getdate() Where DBName = @TokenValue AND UserID = @UserID                
-- AND DeviceIdent = @DeviceIdent                   
 delete tblMobileDevicePermission Where UserID = @UserID                
 AND DeviceIdent = @DeviceIdent               
 --delete tblMobileDeviceInfo where ID = @DeviceIdent            
 delete tblMobileLogin Where UserID = @UserID                
 AND DeviceID = @DeviceIdent                   
end                      
else IF(@Mode = 7)                         
begin                        
--select Active from tblMobileDeviceInfo  where DBName = @TokenValue AND UserID = @UserID                      
UPDATE tblMobileLogin SET SessionStatus = 0,LogoutTime = GETDATE() WHERE UserID = @UserID               
AND DEVICEID = @DeviceIdent              
end                    
else IF(@Mode = 8)                         
begin                        
UPDATE tblMobileLogin SET SessionStatus = 0 WHERE UserID = @UserID                      
end              
else IF(@Mode = 9)                         
begin                        
select * from tblMobileLogin WITH (READCOMMITTEDLOCK) where UserID = @UserID              
end              
END',
N'[export] nocount;readcommittedlock=11';
GO
/****** uspMailmessagecontent ******/
EXEC #Apply07 N'dbo.uspMailmessagecontent', 0x60988B60906034BBE40BD7B2436239F2E3C6EB47CC7E55DEC93F50F89B323198, NULL, NULL, 0xA6172E6F753B6A1FF44833068315D14E61C49CCE531BFB92163659CDF9E800FA, 0x7BBDD90ED33AA48C070B90EAE355B68E70F05BA739BCB895FA40D48F387F1B84, NULL,
N'ALTER PROCEDURE [dbo].[uspMailmessagecontent]
@TransactionType INT = 4,@TransactionId INT =433
as
SET NOCOUNT ON;
begin
DECLARE @MAILMESSAGE NVARCHAR(MAX)
DECLARE @DueDate NVARCHAR(100),@OrgDocId NVARCHAR(100), @DocDate NVARCHAR(100), @DocValue nvarchar(100), @NetAmt NVARCHAR(255),
@PartyName NVARCHAR(255), @PartyMobileNo NVARCHAR(255), @ItemsCount int, @CompanyName nvarchar(255), @CompanyMobNo nvarchar(255), 
@CompanyEmail nvarchar(255),@WhatsAppMsg NVARCHAR(MAX) = '''',
@OSAmt DECIMAL(25,4)
select @CompanyName = CompanyName,@CompanyMobNo= MobileNo,@CompanyEmail = Email from tblCompanyRegistration where CompanyId = 1
--select * from tblTransName
if(@TransactionType = 4 or @TransactionType = 5)-- Invoice & Sales Return
BEGIN
SELECT @DueDate = case when CreditDate is null then null else FORMAT(CreditDate,''dd-MMM-yyyy'') end,@OrgDocId = DocId,@DocValue = DocValue,
@DocDate = FORMAT(InvDate,''dd-MMM-yyyy''),@PartyName = Name,@NetAmt = dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(SH.NetAmt)),
@ItemsCount = count(SD.ProdID),@PartyMobileNo = MC.Mob1 ,@OSAmt = dbo.fnGetClosingBal(MC.FAID)
FROM tblTranSalesHeader SH
join tblTranSalesDetail SD ON SD.InvID = SH.ID
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID
WHERE SH.ID = @TransactionId
GROUP BY CreditDate,InvDate,DocId,Name,SH.NetAmt, MC.Mob1,DocValue,MC.FAID

SELECT @MAILMESSAGE=  FORMATMESSAGE(
    N''Hello <b>%s,</b> 👋<br/><br/> ''+
    N''Greetings from <b>%s 😊.</b><br/><br/>''+
    N''Please find attached the invoice  <b>[%s]</b> dated  <b>[%s]</b> for your recent purchase with us.<br/><br/>''+
    N''We request you to kindly verify the details and let us know if you have any questions or require further clarification.
    The payment terms are as discussed, and we would appreciate your cooperation in processing the payment within the due date.<br/><br/>''+
    N''Thank you for your continued support and trust in our services🙏.<br/><br/>'',
    @PartyName,@CompanyName,@OrgDocId,@DocDate
);
END
else if(@TransactionType = 2 or @TransactionType = 3)-- Invoice & Sales Return
BEGIN
SELECT @DueDate = case when PaymentDate is null then null else FORMAT(PaymentDate,''dd-MMM-yyyy'') end,@OrgDocId = DocId,@DocValue = DocValue,
@DocDate = FORMAT(Date,''dd-MMM-yyyy''),@PartyName = Name,@NetAmt = dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(SH.NetAmt)),
@ItemsCount = count(SD.ProdID),@PartyMobileNo = MC.Mob1 ,@OSAmt = dbo.fnGetClosingBal(MC.FAID)
FROM tblTransPurchaseHeader SH
join tblTransPurchaseDetail SD ON SD.HID = SH.ID
JOIN tblMasterVendor MC ON MC.ID = SH.VendorID
WHERE SH.ID = @TransactionId
GROUP BY PaymentDate,Date,DocId,Name,SH.NetAmt, MC.Mob1,DocValue,MC.FAID

SELECT @MAILMESSAGE=  FORMATMESSAGE(
    N''Hello <b>%s,</b> 👋<br/><br/> ''+
    N''Greetings from <b>%s 😊.</b><br/><br/>''+
    N''Please find attached the invoice  <b>[%s]</b> dated  <b>[%s]</b> for your recent purchase with us.<br/><br/>''+
    N''We request you to kindly verify the details and let us know if you have any questions or require further clarification.
    The payment terms are as discussed, and we would appreciate your cooperation in processing the payment within the due date.<br/><br/>''+
    N''Thank you for your continued support and trust in our services🙏.<br/><br/>'',
    @PartyName,@CompanyName,@OrgDocId,@DocDate
);
END
ELSE
BEGIN
SELECT @MAILMESSAGE = ''Dear <b>Customer ,</b><br/><br/>''
END
SELECT FORMATMESSAGE(@MAILMESSAGE +''Warm regards,<br/><b>%s</b><br/>''+
N''📞<b>%s</b><br/>''+
N''📧<b>%s</b><br/>'',@CompanyName,@CompanyMobNo,@CompanyEmail)
END',
N'[export] nocount';
GO
/****** uspManageApplicationConfig ******/
EXEC #Apply07 N'dbo.uspManageApplicationConfig', 0xEA44F25D60B0E5D88974683E7637EE0A679CC13FF771A00CA7DCE91E0F0681DB, NULL, NULL, 0xFA671B647D79C6B0F78B9FA103C5F7587744F9D57C87EE47E3C76FE6E9FB94AA, 0x720E3D74C464AAA2B8F232FFA24CFA67210929657F71793A6BF88CD9EACEE06F, NULL,
N'ALTER proc [dbo].[uspManageApplicationConfig]            
@Mode INT = 1,@CaseType nvarchar(255) = null,@Confirmpopup nvarchar(255) = null,@Roundoff nvarchar(255) = null,@RoundoffValue nvarchar(255) = null,            
@SMTPHost nvarchar(255) = null,@EMail nvarchar(255) = null,@Password nvarchar(255) = null ,@DecimalValues nvarchar(255) = null,            
@Showallstatus nvarchar(255) = null,@ItemOrderby nvarchar(255) = null,@EnableReturnPrice nvarchar(255) = null,@VisaPern nvarchar(255) = null,            
@DefaultCustID nvarchar(255) = null,@UPIID nvarchar(255) = null,@UPIName nvarchar(255) = null,@WriteoffAmt nvarchar(255) = null,            
@AllSalesmanInvoice nvarchar(255) = null,@AllowPrint nvarchar(255) = NULL,@ApplySchemeinQuotation nvarchar(255)= null,            
@SelectinvoiceinSR nvarchar(255)= null,@ClearConfirmpopup nvarchar(255) = null,@CloseConfirmpopup NVARCHAR(255) = NULL,            
@BackupPath NVARCHAR(255) = NULL,@InvoiceStockOnlyProduct nvarchar(255)= null,@SalesOneView nvarchar(255)= null,            
@PurchaseOneView nvarchar(255)= null,@FilterDate nvarchar(255) = null,@ItemsperPage nvarchar(255) = null,            
@Invoiceallowduplicateitem nvarchar(255) = null,@CommonAgeingCreditDays nvarchar(255) = null,@RestrictBlocklistinInvoice nvarchar(255) = null,            
@RetainDate nvarchar(255) = null,@BeatMandatoryinCustomer nvarchar(255) = null,@DraftAutoSaveTimeInterval nvarchar(255) = null,            
@HomePeriod nvarchar(255) = null,@AutoRefresh nvarchar(255) = null,@CTPAmount nvarchar(255) = null,@CTPPoint nvarchar(255) = null,            
@CTPPerPointAmount nvarchar(255) = null,@UpdateVendorinProduct nvarchar(255) = null,@Radius nvarchar(255) = null,        
@SpotSalesPriceMode nvarchar(255) = null,@PurchaseAddnlDiscbeforeProdDisc nvarchar(255) = null,      
@PurchaseTradeDiscbeforeProdDisc nvarchar(255) = null,@SalesAddnlDiscbeforeProdDisc nvarchar(255) = null,      
@SalesTradeDiscbeforeProdDisc nvarchar(255) = null,@AllowPostChequeDaysColl nvarchar(255) = null,
@ALSearchstartwith nvarchar(255) = null,@AssignInvBeatSalesmanfrom nvarchar(255) = null
AS            
SET NOCOUNT ON;
BEGIN            
IF(@Mode = 1)            
BEGIN            
DECLARE @BAKPAT NVARCHAR(255) = ''''            
select @BAKPAT = BackupPath from tblcompanyregistration WITH (READCOMMITTEDLOCK) where CompanyID = 1            
SELECT CaseType,Confirmpopup,Roundoff,RoundoffValue,SMTPHost,EMail,Password,DecimalValues,ThemeID,Showallstatus,ItemOrderby,            
EnableReturnPrice,VisaPern,DefaultCustID,UPIID,UPIName,WriteoffAmt,AllSalesmanInvoice,AllowPrint,ApplySchemeinQuotation,            
SelectinvoiceinSR,ClearConfirmpopup,CloseConfirmpopup,@BAKPAT BackupPath,InvoiceStockOnlyProduct,SalesOneView,PurchaseOneView,FilterDate,            
ItemsperPage,Invoiceallowduplicateitem,CommonAgeingCreditDays,RestrictBlocklistinInvoice,RetainDate,BeatMandatoryinCustomer,            
DraftAutoSaveTimeInterval,HomePeriod,AutoRefresh,CTPAmount,CTPPoint,CTPPerPointAmount,UpdateVendorinProduct,Radius,SpotSalesPriceMode,      
PurchaseAddnlDiscbeforeProdDisc,PurchaseTradeDiscbeforeProdDisc,SalesAddnlDiscbeforeProdDisc,    
SalesTradeDiscbeforeProdDisc,AllowPostChequeDaysColl,ALSearchstartwith,AssignInvBeatSalesmanfrom   
from(            
SELECT AppName,AppValue FROM tblAppConfig WITH (READCOMMITTEDLOCK) ) AS Nar            
PIVOT(            
MAX(AppValue)FOR AppName in (CaseType,Confirmpopup,Roundoff,RoundoffValue,SMTPHost,EMail,Password,DecimalValues,ThemeID,Showallstatus,            
ItemOrderby,EnableReturnPrice,VisaPern,DefaultCustID,UPIID,UPIName,WriteoffAmt,AllSalesmanInvoice,AllowPrint,ApplySchemeinQuotation,            
SelectinvoiceinSR,ClearConfirmpopup,CloseConfirmpopup,InvoiceStockOnlyProduct,SalesOneView,PurchaseOneView,FilterDate,            
ItemsperPage,Invoiceallowduplicateitem,CommonAgeingCreditDays,RestrictBlocklistinInvoice,RetainDate,BeatMandatoryinCustomer,            
DraftAutoSaveTimeInterval,HomePeriod,AutoRefresh,CTPAmount,CTPPoint,CTPPerPointAmount,UpdateVendorinProduct,Radius,SpotSalesPriceMode,      
PurchaseAddnlDiscbeforeProdDisc,PurchaseTradeDiscbeforeProdDisc,SalesAddnlDiscbeforeProdDisc,    
SalesTradeDiscbeforeProdDisc,AllowPostChequeDaysColl,ALSearchstartwith,AssignInvBeatSalesmanfrom)            
) AS nk            
END            
IF(@Mode = 2)         
BEGIN            
UPDATE tblAppConfig SET AppValue = @CaseType where AppID = 1            
UPDATE tblAppConfig SET AppValue = @Confirmpopup where AppID = 2            
UPDATE tblAppConfig SET AppValue = @Roundoff where AppID = 3            
UPDATE tblAppConfig SET AppValue = @RoundoffValue where AppID = 4            
UPDATE tblAppConfig SET AppValue = @SMTPHost where AppID = 5            
UPDATE tblAppConfig SET AppValue = @EMail where AppID = 6            
UPDATE tblAppConfig SET AppValue = @Password where AppID = 7            
UPDATE tblAppConfig SET AppValue = @DecimalValues where AppID = 8            
UPDATE tblAppConfig SET AppValue = @Showallstatus where AppID = 10            
UPDATE tblAppConfig SET AppValue = @ItemOrderby where AppID = 11            
UPDATE tblAppConfig SET AppValue = @EnableReturnPrice where AppID = 12            
UPDATE tblAppConfig SET AppValue = @VisaPern where AppID = 13            
UPDATE tblAppConfig SET AppValue = @DefaultCustID where AppID = 14            
UPDATE tblAppConfig SET AppValue = @UPIID where AppID = 15            
UPDATE tblAppConfig SET AppValue = @UPIName where AppID = 16            
UPDATE tblAppConfig SET AppValue = @WriteoffAmt where AppID = 17            
UPDATE tblAppConfig SET AppValue = @AllSalesmanInvoice where AppID = 18            
UPDATE tblAppConfig SET AppValue = @AllowPrint where AppID = 19            
UPDATE tblAppConfig SET AppValue = @ApplySchemeinQuotation where AppID = 20            
UPDATE tblAppConfig SET AppValue = @SelectinvoiceinSR where AppID = 21            
UPDATE tblAppConfig SET AppValue = @ClearConfirmpopup where AppID = 22            
UPDATE tblAppConfig SET AppValue = @CloseConfirmpopup where AppID = 23            
UPDATE tblAppConfig SET AppValue = @InvoiceStockOnlyProduct where AppID = 24            
UPDATE tblAppConfig SET AppValue = @SalesOneView where AppID = 25            
UPDATE tblAppConfig SET AppValue = @PurchaseOneView where AppID = 26            
UPDATE tblAppConfig SET AppValue = @FilterDate where AppID = 27            
UPDATE tblAppConfig SET AppValue = @ItemsperPage where AppID = 28            
UPDATE tblAppConfig SET AppValue = @Invoiceallowduplicateitem where AppID = 29            
UPDATE tblAppConfig SET AppValue = @CommonAgeingCreditDays where AppID = 30            
UPDATE tblAppConfig SET AppValue = @RestrictBlocklistinInvoice where AppID = 31            
UPDATE tblAppConfig SET AppValue = @RetainDate where AppID = 32            
UPDATE tblAppConfig SET AppValue = @BeatMandatoryinCustomer where AppID = 33            
UPDATE tblAppConfig SET AppValue = @DraftAutoSaveTimeInterval where AppID = 34            
UPDATE tblAppConfig SET AppValue = @HomePeriod where AppID = 35            
UPDATE tblAppConfig SET AppValue = @AutoRefresh where AppID = 36            
UPDATE tblAppConfig SET AppValue = @CTPAmount where AppID = 37            
UPDATE tblAppConfig SET AppValue = @CTPPoint where AppID = 38            
UPDATE tblAppConfig SET AppValue = @CTPPerPointAmount where AppID = 39            
UPDATE tblAppConfig SET AppValue = @UpdateVendorinProduct where AppID = 40            
UPDATE tblAppConfig SET AppValue = @Radius where AppID = 41            
UPDATE tblAppConfig SET AppValue = @SpotSalesPriceMode where AppID = 42        
UPDATE tblAppConfig SET AppValue = @PurchaseAddnlDiscbeforeProdDisc where AppID = 43            
UPDATE tblAppConfig SET AppValue = @PurchaseTradeDiscbeforeProdDisc where AppID = 44            
UPDATE tblAppConfig SET AppValue = @SalesAddnlDiscbeforeProdDisc where AppID = 45            
UPDATE tblAppConfig SET AppValue = @SalesTradeDiscbeforeProdDisc where AppID = 46        
UPDATE tblAppConfig SET AppValue = @AllowPostChequeDaysColl where AppID = 47    
UPDATE tblAppConfig SET AppValue = @ALSearchstartwith where AppID = 48  
UPDATE tblAppConfig SET AppValue = @AssignInvBeatSalesmanfrom where AppID = 49 
update tblcompanyregistration set BackupPath = @BackupPath where CompanyId = 1            
select ''Saved Successfully''            
END            
IF(@Mode = 3)            
BEGIN            
SELECT ID,Name FROM tblMasterBranchOffice WITH (READCOMMITTEDLOCK) WHERE Active = 1 ORDER BY Name            
END            
IF(@Mode = 4)            
BEGIN            
SELECT *,1 Typeid FROM tblPaymentMode WITH (READCOMMITTEDLOCK) WHERE ID NOT IN (10)            
union all            
SELECT ID,Name,Active,0,Code,2 FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Active = 1            
UNION ALL            
select ID,TypeName,Active,0,'''',3 from tblContraType WITH (READCOMMITTEDLOCK)            
UNION ALL            
select ID,PriceType,Active,DisplayIndex,'''',4 from tblpricetype WITH (READCOMMITTEDLOCK)            
UNION ALL            
select ID,Code,Active,DisplayIndex,'''',5 from tblFilterDates WITH (READCOMMITTEDLOCK) where ID <> 4            
ORDER BY Typeid,Orderby,PaymentMode            
END            
IF(@Mode = 5)            
BEGIN            
UPDATE tblPaymentMode SET Active = @Confirmpopup,Orderby = @Roundoff WHERE ID = @CaseType            
END            
IF(@Mode = 6)            
BEGIN            
UPDATE tblContraType SET Active = @Confirmpopup WHERE ID = @CaseType            
END            
IF(@Mode = 7)            
BEGIN            
SELECT * FROM tblAppPasswordSettings WITH (READCOMMITTEDLOCK) WHERE Active = 1 ORDER BY Particulars            
END            
IF(@Mode = 8)            
BEGIN            
UPDATE tblAppPasswordSettings SET Password = @Confirmpopup WHERE pwdid = @CaseType            
END            
IF(@Mode = 9)            
BEGIN            
SELECT * FROM tblAppPasswordSettings WITH (READCOMMITTEDLOCK) WHERE Active = 1 AND pwdid = @CaseType ORDER BY Particulars            
END            
IF(@Mode = 10)            
BEGIN            
UPDATE tblPriceType SET Active = @Confirmpopup,DisplayIndex = @Roundoff WHERE ID = @CaseType            
END            
END',
N'[export] nocount;readcommittedlock=10';
GO
/****** uspManageAssignInvoices ******/
EXEC #Apply07 N'dbo.uspManageAssignInvoices', 0x483E1269D48D4421A06AEEF920801E51CA83C69A331B3B68E8545D829885D262, NULL, NULL, 0x86D8EB7DA922FC992AD7B1B4C9BFF0432894ABB83E3BA0512CAED72F8CFDEE56, 0xC266786324CFB492AFC5D8AB3FED142734C1B14AC276A762F5B6AA3D0506DDE2, NULL,
N'ALTER PROCEDURE [dbo].[uspManageAssignInvoices]
@Mode NVARCHAR(10),@TransID int,@IdentID INT=NULL,@DocDate date = null,@SalesmanID INT,@refNo NVARCHAR(255)=Null,@udfid INT = null,@cby NVARCHAR(255) =null,
@ChkStatus INT=NULL,@CurrentStatus INT = NULL,@tvpIdentId [tvpIdentId] READONLY ,@Remarks nvarchar(255) = null,
@Narration nvarchar(max) = null,@BranchID int = 0
--@tvpOrder AS [tvpPurchaseOrder] READONLY
AS
BEGIN
BEGIN TRY
SET NOCOUNT ON;
SET DATEFORMAT DMY
declare @InvStatus int,@DocumentId nvarchar(255) = ''''
create table #COLLECTEDINVOICES(ID INT)
DECLARE @udfDocId NVARCHAR(255)=null, @udfDocValue NVARCHAR(255)=null, @UdfDocPrefix NVARCHAR(255) =null, @DocPrefix NVARCHAR(255)=NULL
, @DocValue NVARCHAR(255)=null, @DocId NVARCHAR(255)=null, @CDate DATE =NULL, @scopeID INT, @ScopeID_PO INT,@nMode INT
DECLARE @serial INT, @NCountSerial INT, @InvID INT,@F_SD DATE,@F_ED DATE
declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))
DECLARE @DocSeriesIdent int
DECLARE @CLOSECOUNT INT,@RETURNCOUNT INT
SELECT @F_SD = F_SD,@F_ED = F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)
SET @NCountSerial = (SELECT COUNT(*) FROM @tvpIdentId)
SET @serial = 1
IF ISNULL(@Mode,'''')!=''4'' AND ISNULL(@Mode,'''')!=''6'' AND ISNULL(@Mode,'''')!=''7''
BEGIN

IF ISNULL(@Mode,'''')=''1''
BEGIn
SET @nMode =1

insert into @tblDocdetails
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate) and BranchID = @BranchID and TransID = @TransID
IF((select count(*) from @tblDocdetails) = 0)
BEGIN
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)
END

SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails

UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = @TransID and ID = @DocSeriesIdent
--SELECT @DocValue = DocValue,@DocId = DocPrefix+CONVERT(NVARCHAR(10),DocValue) FROM dbo.tblDocumentSeries WHERE TransID = @TransID
--UPDATE tblDocumentSeries SET DocValue = DocValue + 1 WHERE TransID = @TransID
IF ISNULL(@udfid,0)>0
BEGIN
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@udfid
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@udfid
END
if(@F_SD > @DocDate OR @F_ED < @DocDate)
BEGIN
RAISERROR(''Invalid Doc Date. Try again'',16,1);
END

IF(@Mode = 1)
BEGIN
IF((SELECT COUNT(DocValue) FROM tblAssignInvoicesHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and
DocDate BETWEEN @F_SD AND @F_ED and TransID = @TransID) != 0)-- and Status in (3,4,5,6)
BEGIN
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)
END
END
IF(@Mode = 2)
BEGIN
IF((SELECT COUNT(DocValue) FROM tblAssignInvoicesHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and
DocDate BETWEEN @F_SD AND @F_ED and TransID = @TransID) != 0)-- and Status in (3,4,5,6)
BEGIN
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)
END
END
--Header INSERT
INSERT INTO tblAssignInvoicesHeader (DocDate,DocId,TransID,DocValue,SalesmanID,RefNo,Cby,Cdate,[status],UDFId,UDFDocID,
UDFDocPrefix,UDFDOcValue,Remarks,Narration,BranchID)
VALUES (@DocDate,@DocId,@TransID,@DocValue,@SalesmanID,@refNo,@cby,GETDATE(),1,@udfid,@UDFDocId,@UDFDocPrefix,@UDFDocValue,
@Remarks,@Narration,@BranchID)
SET @scopeID = SCOPE_IDENTITY();
END
ELSE IF ISNULL(@Mode,'''')=''2''
BEGIN
SET @nMode =3
DECLARE @status INT,@ChkUdfID INT
SELECT @status=status,@ChkUdfID=UDFId FROM tblAssignInvoicesHeader WITH (READCOMMITTEDLOCK) WHERE ID=@IdentID
IF((ISNULL(@status,0) != ISNULL(@CurrentStatus,0)) or @status in (2,4))
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
set @CLOSECOUNT = 
(select COUNT(*) from tblAssignInvoicesDETAIL DD1 WITH (READCOMMITTEDLOCK) where DD1.HID = @IdentID AND DD1.Status = 5)   
set @RETURNCOUNT = 
(select COUNT(*) from tblAssignInvoicesDETAIL DD2 WITH (READCOMMITTEDLOCK) where DD2.HID = @IdentID AND DD2.Status = 6) 

IF((@CLOSECOUNT + @RETURNCOUNT) > 0)
BEGIN
RAISERROR(''Invoice status already changed in this document'',16,1);
END

UPDATE tblAssignInvoicesHeader SET status=2,MBy = @cby,MDate = GETDATE() WHERE ID=@IdentID
--DECLARE @DocIDemodify NVARCHAR(255), @DocPrefixemodify NVARCHAR(255), @Docvaluemodify NVARCHAR(255)
SELECT @DocId=DocId,@DocValue=DocValue FROM tblAssignInvoicesHeader WITH (READCOMMITTEDLOCK) WHERE ID=@IdentID

IF ISNULL(@udfid,0)>0
BEGIN
SELECT @udfDocValue=UDFDOcValue, @udfDocId=UDFDocID,@UdfDocPrefix=UDFDocPrefix
FROM tblAssignInvoicesHeader WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID

IF(@UDFId!=@ChkUdfID)
BEGIN
SELECT @udfDocValue=DocValue,@UdfDocPrefix=DocPrefix,@udfDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@udfid
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@udfid
END
END
if(@F_SD > @DocDate OR @F_ED < @DocDate)
BEGIN
RAISERROR(''Invalid Doc Date. Try again'',16,1);
END
INSERT INTO tblAssignInvoicesHeader (DocDate,DocId,TransID,DocValue,SalesmanID,RefNo,Cby,Cdate,[status],UDFId,UDFDocID,
UDFDocPrefix,UDFDOcValue,Remarks,Narration,BranchID)
VALUES (@DocDate,@DocId,@TransID,@DocValue,@SalesmanID,@refNo,@cby,GETDATE(),3,@udfid,@UDFDocId,@UDFDocPrefix,@UDFDocValue,
@Remarks,@Narration,@BranchID)

SET @scopeID = SCOPE_IDENTITY();
SET @ChkStatus = 3;
END
-----Detail Insert
--VALIDATE INVOICE STATUS
-- Point 11: set-based check replaces the DocumentCount cursor loop (same error; @DocumentId = first invoice that failed)
SELECT TOP (1) @DocumentId = CONVERT(NVARCHAR(255), T.DocumentId)
FROM @tvpIdentId AS T
JOIN tblTranSalesHeader AS H WITH (READCOMMITTEDLOCK) ON H.ID = T.DocumentId
WHERE H.Status <> T.Status OR H.Status IN (2, 4);
IF @@ROWCOUNT > 0
BEGIN
    RAISERROR(''Invoice status already changed'', 16, 1, @DocumentId);
END

-- VALIDATE INVOICE ALREADY ASSIGNED IN ANOTHER PLACE
CREATE table #DeliProcs1(InvIdentID INT,IsMods INT)
CREATE table #DeliProcs(InvIdentID INT,IsMods INT)

INSERT INTO #DeliProcs1
SELECT SD.InvID,1 FROM tblAssignInvoicesHeader SH WITH (READCOMMITTEDLOCK)
JOIN tblAssignInvoicesDetail SD WITH (READCOMMITTEDLOCK) ON SD.HID = SH.ID
WHERE SH.Status NOT IN (2,4) AND SD.InvID IN (SELECT DocumentId FROM @tvpIdentId) AND SD.Status IN (1,5)
GROUP BY InvID
if(@Mode = 3)--EDIT
BEGIN
INSERT INTO #DeliProcs1
SELECT InvID,2 FROM tblAssignInvoicesDetail WITH (READCOMMITTEDLOCK) WHERE HID = @IdentID
GROUP BY InvID
END
INSERT INTO #DeliProcs
SELECT InvIdentID,MAX(IsMods) FROM #DeliProcs1 GROUP BY InvIdentID

select SH.ID,SH.DocID,SH.DocValue,SH.InvDate into #Alreadyassigned from tblTranSalesHeader SH WITH (READCOMMITTEDLOCK)
JOIN @tvpIdentId TVPDOC ON TVPDOC.DocumentId = SH.ID
where SH.DocPrefix = 15 AND SH.BranchID = @BranchID AND SH.Status IN (1,3,5)
AND SH.ID IN (SELECT InvIdentID FROM #DeliProcs WHERE IsMods = 1)
if((select COUNT(*) from #Alreadyassigned) > 0)
begin
set @DocumentId = (select STRING_AGG(ID, '','') from #Alreadyassigned)
raiserror(''Invoice already assign'',16,1,@DocumentId)
end
drop table #Alreadyassigned

WHILE @NCountSerial > 0
BEGIN
SELECT @InvID=DocumentId from @tvpIdentId WHERE TransName= @serial
INSERT INTO tblAssignInvoicesDetail (HID,InvID,Status)
VALUES (@scopeID,@InvID,1)
SET @serial = @serial+1;
SET @NCountSerial = @NCountSerial -1;
END

SELECT @scopeID
ENd
ELSE IF ISNULL(@Mode,'''') =''4''
BEGIN
INSERT INTO #COLLECTEDINVOICES
SELECT ID FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK)
WHERE Status NOT IN (2,4) AND Balance = 0 AND ID IN (SELECT DocumentId FROM @tvpIdentId)
if((select COUNT(*) from #COLLECTEDINVOICES) > 0)
begin
set @DocumentId = (select STRING_AGG(ID, '','') from #COLLECTEDINVOICES)
raiserror(''Invoice already collected'',16,1,@DocumentId)
end

IF ISNULL(@IdentID,0)!=0 AND ISNULL(@ChkStatus,0)!=0
BEGIN
IF ISNULL((SELECT COUNT(ID) FROM tblAssignInvoicesHeader WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID AND status = @CurrentStatus),0)=0
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
IF ISNULL((SELECT COUNT(ID) FROM tblAssignInvoicesHeader WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID AND status in (2,4)),0) > 0
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
set @CLOSECOUNT = 
(select COUNT(*) from tblAssignInvoicesDETAIL DD1 WITH (READCOMMITTEDLOCK) where DD1.HID = @IdentID AND DD1.Status = 5)   
set @RETURNCOUNT = 
(select COUNT(*) from tblAssignInvoicesDETAIL DD2 WITH (READCOMMITTEDLOCK) where DD2.HID = @IdentID AND DD2.Status = 6) 

IF((@CLOSECOUNT + @RETURNCOUNT) > 0)
BEGIN
RAISERROR(''Invoice status already changed in this document'',16,1);
END

UPDATE tblAssignInvoicesHeader SET status=4,ClBy =@cby,ClDate =GETDATE(),Remarks =@Remarks, Narration =@Narration WHERE ID=@IdentID
END
END
ELSE IF ISNULL(@Mode,'''') =''6''
BEGIN
IF ISNULL(@IdentID,0)!=0 AND ISNULL(@ChkStatus,0)!=0
BEGIN
IF ISNULL((SELECT COUNT(ID) FROM tblAssignInvoicesHeader WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID AND status = @CurrentStatus),0)=0
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
IF ISNULL((SELECT COUNT(ID) FROM tblAssignInvoicesHeader WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID AND status in (2,4)),0) > 0
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
INSERT INTO #COLLECTEDINVOICES
SELECT ID FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK)
WHERE Status NOT IN (2,4) AND Balance = 0 AND ID IN (SELECT DocumentId FROM @tvpIdentId)
if((select COUNT(*) from #COLLECTEDINVOICES) > 0)
begin
set @DocumentId = (select STRING_AGG(ID, '','') from #COLLECTEDINVOICES)
raiserror(''Invoice already collected'',16,1,@DocumentId)
end

WHILE @NCountSerial > 0
BEGIN
SELECT @InvID=DocumentId from @tvpIdentId WHERE TransName= @serial
UPDATE tblAssignInvoicesDetail SET Status = 6 where InvID = @InvID and HID = @IdentID
SET @serial = @serial+1;
SET @NCountSerial = @NCountSerial -1;
END
SELECT @IdentID
END
END
ELSE IF ISNULL(@Mode,'''') =''7''
BEGIN
DECLARE @DETAILOPENCOUNT INT = (select COUNT(*) from tblAssignInvoicesDetail WITH (READCOMMITTEDLOCK) where HID = @IdentID AND Status = 1)
IF(@DETAILOPENCOUNT = 0)
BEGIN
UPDATE tblAssignInvoicesHeader SET Status = 5 WHERE ID = @IdentID
END
END
DROP TABLE #COLLECTEDINVOICES
END TRY
BEGIN CATCH
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(),ERROR_LINE(),@DocumentId
END CATCH
END',
N'[export] validation-cursor-removed=1;number-series-updlock=3;readcommittedlock=21';
GO
/****** uspManageAutomaticIndent ******/
EXEC #Apply07 N'dbo.uspManageAutomaticIndent', 0x7752440031BAEEA2105922D1F5C25D87AC49B09CB938E14BB03A346B9BFD6FD5, NULL, NULL, 0xF564AE61104F29E0B00203C7E39452CD5373D6C4448F998D370396655FBEF092, 0x3EB0CB8DD75869E1640082C21DA6D93D7DECB0577C864053A256E742B9071A78, NULL,
N'ALTER PROCEDURE [dbo].[uspManageAutomaticIndent]              
@Mode NVARCHAR(10),@IdentID INT=NULL,@VendID INT,@BranchID int,@Aidate Date,@refNo NVARCHAR(255)=Null,@udfid INT = null,              
@PoId INT=null,@cby NVARCHAR(255) =null,@ChkStatus INT=NULL,@SumNetAmount DECIMAL (25,6)=NULL,@Remarks nvarchar(max),@Narration nvarchar(max),              
@DraftID INT = 0,@tvpAutomaticIntent AS [tvpAutomaticIntent] READONLY,@tvpOrder AS [tvpPurchaseOrder] READONLY              
--@tvpOrder AS [tvpPurchaseOrder] READONLY              
AS              
BEGIN              
BEGIN TRY              
SET NOCOUNT ON;              
SET DATEFORMAT DMY              
DECLARE @udfDocId NVARCHAR(255)=null, @udfDocValue NVARCHAR(255)=null, @UdfDocPrefix NVARCHAR(255) =null, @DocPrefix NVARCHAR(255)=NULL              
, @DocValue NVARCHAR(255)=null, @DocId NVARCHAR(255)=null, @CDate DATE =NULL, @scopeID INT, @ScopeID_PO INT,@nMode INT,@TaxTypeID INT=1              
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)                        
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)        
      declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))                
      DECLARE @DocSeriesIdent int         
BEGIN              
DECLARE @ChkVendorActive INT = (SELECT active FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE ID=@VendID)              
IF ISNULL(@ChkVendorActive,0)=0              
BEGIN              
RAISERROR(''Vendor already deactivated'',16,1)              
END              
              
IF ISNULL(@Mode,'''')=''1''              
BEGIN              
SET @nMode =1              
  
IF(ISNULL(@DraftID,0) > 0)              
BEGIN              
exec uspValidateDraftData 1,2,@DraftID,@ChkStatus  
END    
  
insert into @tblDocdetails          
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@Aidate between FromDate and ToDate)     
and BranchID = @BranchID and TransID = 2        
 IF((select count(*) from @tblDocdetails) = 0)                      
   BEGIN                      
    RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)                      
   END               
          
   SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails          
        
UPDATE tblYearwiseDocumentSeries SET DocValue =  @DocValue + 1 WHERE TransID = 2 and ID = @DocSeriesIdent        
        
--SELECT @DocValue = DocValue,@DocId = DocPrefix+CONVERT(NVARCHAR(10),DocValue) FROM dbo.tblDocumentSeries WHERE TransID = 2              
--UPDATE tblDocumentSeries SET DocValue = DocValue + 1 WHERE TransID = 2                       
--Header INSERT                              
IF((SELECT COUNT(DocValue) FROM tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and         
Date BETWEEN @F_SD AND @F_ED  and TransID = 2) != 0)-- and Status in (3,4,5,6)    
BEGIN                        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)                        
END                           
        
INSERT INTO tblTransAutomaticIndentHeader (Date,DocId,TransID,DocValue,BranchID,VendorID,RefNo,Cby,Cdate,[status],UDFId,UDFDocID,UDFDocPrefix,UDFDOcValue,Remarks,Narration)              
VALUES (@Aidate,@DocId,2,@DocValue,@BranchID,@VendID,@refNo,@cby,GETDATE(),1,@udfid,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@Remarks,@Narration)              
SET @scopeID = SCOPE_IDENTITY();              
END              
ELSE IF ISNULL(@Mode,'''')=''2''              
BEGIN              
SET @nMode =3              
DECLARE @status INT,@ChkUdfID INT              
SELECT @status=status,@ChkUdfID=UDFId FROM tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE ID=@IdentID              
IF((ISNULL(@status,0) != ISNULL(@ChkStatus,0)) OR ISNULL(@status,0) IN (2,4))
BEGIN              
RAISERROR(''Document Status already changed'',16,1);              
END              
IF((SELECT COUNT(DocValue) FROM tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and         
Date not BETWEEN @F_SD AND @F_ED  and TransID = 2) != 0)-- and Status in (3,4,5,6)    
BEGIN                        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)                        
END     
UPDATE tblTransAutomaticIndentHeader SET status=2,MBy = @cby,MDate = GETDATE() WHERE ID=@IdentID              
--DECLARE @DocIDemodify NVARCHAR(255), @DocPrefixemodify NVARCHAR(255), @Docvaluemodify NVARCHAR(255)              
SELECT @DocId=DocId,@DocValue=DocValue FROM tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE ID=@IdentID                      
IF ISNULL(@udfid,0)>0              
BEGIN              
SELECT @udfDocValue=UDFDOcValue, @udfDocId=UDFDocID,@UdfDocPrefix=UDFDocPrefix              
FROM tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID              
              
IF(@UDFId!=@ChkUdfID)              
BEGIN              
SELECT @udfDocValue=DocValue,@UdfDocPrefix=DocPrefix,@udfDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)              
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@udfid              
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@udfid              
END              
END              
              
INSERT INTO tblTransAutomaticIndentHeader (Date,DocId,TransID,DocValue,BranchID,VendorID,RefNo,Cby,Cdate,[status],UDFId,UDFDocID,UDFDocPrefix,UDFDOcValue,Remarks,Narration)              
VALUES (@Aidate,@DocId,2,@DocValue,@BranchID,@VendID,@refNo,@cby,GETDATE(),3,@udfid,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@Remarks,@Narration)              
              
SET @scopeID = SCOPE_IDENTITY();              
SET @ChkStatus = 3;              
END              
END              
-----Detail Insert              
DECLARE @serial INT, @NCountSerial INT, @ProdId INT, @UOMgpId INT,@UOMId INT,@AvlQty DECIMAL (25,6),@MOH INT,@MOQ INT,              
@AutomaticIndent INT,@PurchasePrice DECIMAL (25,6)              
SET @NCountSerial = (SELECT COUNT(*) FROM @tvpAutomaticIntent)              
SET @serial = 1              
              
WHILE @NCountSerial > 0              
BEGIN              
SELECT @ProdId=ProdId,@UOMId=UomId,@PurchasePrice=PurchasePrice,@AvlQty=ABSQty,@MOH=MOH,@MOQ=MOQ,@AutomaticIndent=IndentQty              
from @tvpAutomaticIntent WHERE Serial= @serial              
              
INSERT INTO tblTransAutomaticIndentDetail (HID,ProdID,UomID,PurchasePrice,ABSQty,MOH,MOQ,IndentValue,Serial)              
VALUES (@scopeID,@ProdId,@UOMId,@PurchasePrice,@AvlQty,@MOH,@MOQ,@AutomaticIndent,@serial)              
SET @serial = @serial+1;              
SET @NCountSerial = @NCountSerial -1;              
END              
--select ROUND(45.66,0),floor(45.96)              
IF ISNULL(@PoId,0)=1              
BEGIN              
DECLARE @SumGrossAmount DECIMAL (25,4),@SumTaxAmount DECIMAL (25,4),@RoundOff DECIMAL (25,4),@RNet DECIMAL (25,4)              
SELECT @SumGrossAmount = SUM([GrossAmt]),@SumTaxAmount = SUM([TaxAmt]),@SumNetAmount = SUM([NetAmt]) FROM @tvpOrder              
set @RNet = floor(@SumNetAmount)              
set @RoundOff = @RNet - @SumNetAmount              
EXEC uspManagePurchaseOrder @tvpOrder,@nMode,0,@BranchID,@ChkStatus,@Aidate,@VendID,@refNo,@TaxTypeID,@RoundOff,              
@SumGrossAmount,@SumTaxAmount,@RNet,0,@Remarks,@Narration,@cBy,0,1,@scopeID,0,null              
END              
IF(ISNULL(@DraftID,0) > 0)              
BEGIN              
UPDATE tblPurchaseDraftHeader SET Status = 8,MBy = @cby,MDate = GETDATE() WHERE ID = @DraftID              
END              
SELECT @scopeID              
END TRY              
BEGIN CATCH              
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(),ERROR_LINE()              
END CATCH              
END',
N'[export] number-series-updlock=2;readcommittedlock=8';
GO
/****** uspManageAutomaticIndentCancel ******/
EXEC #Apply07 N'dbo.uspManageAutomaticIndentCancel', 0x8DEFFCD50B9424BEA265B7E50A301CD98BC7D31D7C21B9E4DCFB4D191DAC80A0, NULL, NULL, 0x85820B874F4753CE6E2336479F9980FE5720527A4B8E30587FF7A5BE479146AB, 0x72FE695048C8E487E80053290D55A244710C93CF2DA4D443B0E56EE6B7F67BE2, NULL,
N'ALTER PROC [dbo].[uspManageAutomaticIndentCancel]            
@IdentID INT,@Uid INT,@ChkStatus INT,@Remarks NVARCHAR(255) = NULL,@Narration NVARCHAR(MAX) = NULL      
AS            
SET NOCOUNT ON;
BEGIN            
BEGIN TRY            
DECLARE @CURRSTATUS INT
IF ISNULL(@IdentID,0)!=0 AND ISNULL(@ChkStatus,0)!=0            
BEGIN           
SELECT @CURRSTATUS = Status FROM tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID

IF((ISNULL((SELECT COUNT(ID) FROM tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID AND status = @ChkStatus),0)=0) OR
@CURRSTATUS IN (2,4))
BEGIN            
RAISERROR(''Document already status changed'',16,1);            
END            
UPDATE tblTransAutomaticIndentHeader SET status=4,ClBy =@Uid,ClDate =GETDATE(),Remarks = @Remarks,Narration = @Narration
WHERE ID=@IdentID            
END            
END TRY                                     
BEGIN CATCH                                        
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE()                                         
END CATCH            
END',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspManageBankAccount ******/
EXEC #Apply07 N'dbo.uspManageBankAccount', 0xE28E52A5A8A9EB4C8010F0457F7A3B5075DB822707D4513D3F4C47DA91C981CF, NULL, NULL, 0x851867D3753E5C81EC689DD4ACEBFB11AE1E0BB467728CB05815CB79F34F5978, 0x998A387276AFCC7EAA884F0BA5CD2619814C533A8783CBD3DF51FBB41C5D8C3C, NULL,
N'ALTER PROC [dbo].[uspManageBankAccount]        
@Mode INT,@ID SMALLINT = NULL,@AccountNo NVARCHAR(MAX) = NULL,@AccountName NVARCHAR(MAX) = NULL,@BankID SMALLINT = NULL,        
@BranchName NVARCHAR(MAX) = NULL,@IFSCCode NVARCHAR(MAX) = NULL,@MICR NVARCHAR(MAX) = NULL,@Active BIT = NULL,@SetDefault BIT = NULL,@CBy smallint = null        
as        
SET NOCOUNT ON;
begin        
BEGIN TRY        
DECLARE @ActiveCheck NVARCHAR(255), @SUNDRYDEBTORS INT ,@FATYPE INT,@AccID INT ,@ACCOUNTID INT,@CHECKID INT,@cstdate DATE,@ExistCount INT        
SELECT @SUNDRYDEBTORS = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName=''Bank Accounts''        
IF(@Mode = 1)        
BEGIN        
IF((SELECT count(*) FROM tblMasterBankAccount WITH (READCOMMITTEDLOCK) WHERE AccountNo = @AccountNo) > 0)        
BEGIN        
RAISERROR(''Already Exists'',16,1)        
END        
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@AccountNo        
IF(@ExistCount>0)        
BEGIN        
RAISERROR (''Account Name Already Exists in another master'',16,1)        
END        
IF(ISNULL(@SetDefault,0) = 1)        
BEGIN        
UPDATE tblMasterBankAccount SET SetDefault = 0        
END        
set @AccountNo =(select dbo.ProperCase(@AccountNo))        
set @AccountName =(select dbo.ProperCase(@AccountName))        
set @BranchName = (select dbo.ProperCase(@BranchName))        
        
INSERT INTO tblFAAccount(AccountName,AccountGroup,OpeningBalance,FATypeID,CBy,CDate,UserAccount,PANNumber,Active)        
VALUES(@AccountNo,@SUNDRYDEBTORS,0,1,@CBy,GETDATE(),0,null,@Active)        
        
SELECT @ACCOUNTID = FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @AccountNo        
        
insert into tblMasterBankAccount(AccountNo,AccountName,BankID,BranchName,IFSCCode,MICR,Active,SetDefault,CBy,CDate,FAID)        
Values (@AccountNo, @AccountName, @BankID, @BranchName, @IFSCCode, @MICR, @Active, @SetDefault, @CBy, GETDATE(),@ACCOUNTID)        
SELECT SCOPE_IDENTITY()        
END        
IF(@Mode = 2)        
BEGIN        
select @ACCOUNTID = FAID from tblMasterBankAccount WITH (READCOMMITTEDLOCK) where ID = @ID        
IF((SELECT count(*) FROM tblMasterBankAccount WITH (READCOMMITTEDLOCK) WHERE AccountNo = @AccountNo AND ID != @ID) > 0)        
BEGIN        
RAISERROR(''Already Exists'',16,1)        
END        
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@AccountNo and FAID != @ACCOUNTID        
IF(@ExistCount>0)        
BEGIN        
RAISERROR (''Account Name Already Exists in another master'',16,1)        
END        
IF(ISNULL(@SetDefault,0) = 1)        
BEGIN        
UPDATE tblMasterBankAccount SET SetDefault = 0        
END        
set @AccountNo =(select dbo.ProperCase(@AccountNo))        
set @AccountName =(select dbo.ProperCase(@AccountName))        
set @BranchName = (select dbo.ProperCase(@BranchName))        
        
INSERT INTO tblMasterHistory (FormID,ID,Name,Column1,Column2,Column3,Column4,Column5,Column6,Active,Column7,CBy,CDate,MBy,MDate,HisCBy,HisCDate)        
(select 22,*, @CBy, GETDATE() from tblMasterBankAccount WITH (READCOMMITTEDLOCK) where ID = @ID)        
UPDATE tblFAAccount        
SET AccountName=@AccountNo,AccountGroup=@SUNDRYDEBTORS,MBy=@CBy,MDate=GETDATE(),UserAccount=0,PANNumber=null,Active = @Active        
WHERE FAID=@ACCOUNTID        
        
UPDATE tblMasterBankAccount SET AccountNo = @AccountNo,AccountName = @AccountName,BankID = @BankID,BranchName = @BranchName,        
IFSCCode = @IFSCCode,MICR = @MICR,Active = @Active,SetDefault = @SetDefault,MBy = @CBy ,MDate = GETDATE() WHERE ID = @ID        
SELECT @ID        
END        
IF(@Mode = 3)        
BEGIN        
SELECT MBA.ID,MBA.AccountNo,MBA.AccountName,isnull(MBA.BankID,0) BankID,MB.Name BankName,BranchName,MBA.IFSCCode,MBA.MICR,      
MBA.Active,MBA.SetDefault,CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,      
 CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MBA.CDate) ELSE CONVERT(NVARCHAR(100),MBA.MDate) END LastActionTime      
 from tblMasterBankAccount MBA WITH (READCOMMITTEDLOCK)        
LEFT JOIN tblMasterBank MB WITH (READCOMMITTEDLOCK) ON MB.ID = MBA.BankID      
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MBA.CBy                
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MBA.MBy       
order by AccountName        
END        
IF(@Mode = 4)        
BEGIN        
SELECT * from tblMasterBankAccount WITH (READCOMMITTEDLOCK) where AccountNo = @AccountNo        
END        
IF(@Mode = 5)        
BEGIN        
SELECT * from tblMasterBank WITH (READCOMMITTEDLOCK) where Active = 1 order by Name        
END     
IF(@Mode = 6)        
BEGIN        
SELECT MBA.ID,MBA.AccountNo,MBA.AccountName,isnull(MBA.BankID,0) BankID,MB.Name BankName,BranchName,MBA.IFSCCode,MBA.MICR,      
MBA.Active,MBA.SetDefault,CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,      
 CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MBA.CDate) ELSE CONVERT(NVARCHAR(100),MBA.MDate) END LastActionTime      
 from tblMasterBankAccount MBA WITH (READCOMMITTEDLOCK)        
LEFT JOIN tblMasterBank MB WITH (READCOMMITTEDLOCK) ON MB.ID = MBA.BankID      
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MBA.CBy                
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MBA.MBy   where MBA.ID = @AccountNo        
order by AccountName   
--SELECT * from tblMasterBankAccount where ID = @AccountNo        
END
IF(@Mode = 7)
BEGIN
SELECT MBA.ID,MBA.AccountNo,MBA.AccountName,isnull(MBA.BankID,0) BankID,MB.Name BankName,BranchName,MBA.IFSCCode,MBA.MICR,      
MBA.Active,MBA.SetDefault,CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,      
 CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MBA.CDate) ELSE CONVERT(NVARCHAR(100),MBA.MDate) END LastActionTime      
 from tblMasterBankAccount MBA WITH (READCOMMITTEDLOCK)        
LEFT JOIN tblMasterBank MB WITH (READCOMMITTEDLOCK) ON MB.ID = MBA.BankID      
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MBA.CBy                
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MBA.MBy   where MBA.FAID = @AccountNo        
order by AccountName  
END
END TRY        
BEGIN CATCH        
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC]        
END CATCH        
END',
N'[export] nocount;readcommittedlock=22';
GO
/****** uspManageBranchMapping ******/
EXEC #Apply07 N'dbo.uspManageBranchMapping', 0x23D0A1C3EA7CFF2AF0DC7BD28C36D387A6A3D8FC30C8E0B8840A2F94FD9D6309, NULL, NULL, 0x8C553592C8D895645D4C052336D54C9301BD4CF2D3432AAF0250B48CD4740518, 0x53D3B65A7BC619C87473D27CA12AD105E7C8EEA18934D2F42173179FEEB875D9, NULL,
N'--uspManageBranchMapping 1,3
ALTER PROCEDURE [dbo].[uspManageBranchMapping]

@Mode INT, @RoleID INT = 0, @BranchID INT = 0, @Active INT = 0, @SetDef INT = 0, @UID INT = 0

AS
SET NOCOUNT ON;
BEGIN

IF (@Mode = 1)
BEGIN
        SELECT @RoleID AS RoleID,B.ID AS BranchID,B.Name AS BranchName,ISNULL(BM.Active, 0) AS Active,
        ISNULL(BM.SetAsDefault, 0) AS SetAsDefault

        FROM tblMasterBranchOffice B WITH (READCOMMITTEDLOCK)
        LEFT JOIN tblBranchMapping BM WITH (READCOMMITTEDLOCK) ON B.ID = BM.BranchID AND BM.RoleID = @RoleID
        ORDER BY B.Name
    END
END
IF (@Mode = 2)
BEGIN    
DECLARE @Exists int = (select count(*) from tblBranchMapping WITH (READCOMMITTEDLOCK) where RoleID = @RoleID AND BranchID = @BranchID) 
IF(@Exists = 0) -- FOR INSERT    
BEGIN    
INSERT INTO tblBranchMapping (RoleID,BranchID,Active,SetAsDefault, CBy,CDate)  
VALUES (@RoleID,@BranchID,@Active, @SetDef, @UID, GETDATE())    
END    
ELSE    
BEGIN    
UPDATE tblBranchMapping SET SetAsDefault = @SetDef, Active = @Active,MBy = @UID,MDate=GETDATE() WHERE RoleID = @RoleID AND BranchID = @BranchID
END    
END',
N'[export] nocount;readcommittedlock=3';
GO
/****** uspManageBranchOffice ******/
EXEC #Apply07 N'dbo.uspManageBranchOffice', 0x08943082316BC3C43A5550FD0BF00E9DCF0D47C217CA324C0426EB7B48FBC68F, NULL, NULL, 0xF782C8F0BD11A420233A0CAFE5CEFACE4DDF69BE3799D09124FB2EB715D877B2, 0x5A9F356068642CB23BC65B9B14DD25395413ABDFCB65B1EFC3858D2E4812F824, NULL,
N'ALTER PROC [dbo].[uspManageBranchOffice]        
@Mode INT,@ID smallint = NULL,@Code nvarchar(255) = NULL,@Name nvarchar(255) = NULL,@Billadd1 nvarchar(max) = NULL,@Billadd2 nvarchar(max) = NULL,        
@Billadd3 nvarchar(max) = NULL,@ContactPerson nvarchar(255) = NULL,@Ph1 nvarchar(25) = NULL,@Mob1 nvarchar(25) = NULL,@Email nvarchar(255) = NULL,        
@StateID tinyint = NULL,@GSTIN nvarchar(40) = NULL,@FAID int = NULL,@Active bit = NULL,@UserID smallint = NULL        
AS        
SET NOCOUNT ON;
begin        
BEGIN TRY        
DECLARE @ActiveCheck NVARCHAR(255), @SUNDRYDEBTORS INT ,@FATYPE INT,@AccID INT ,@ACCOUNTID INT,@CHECKID INT,@cstdate DATE,@ExistCount INT        
SELECT @SUNDRYDEBTORS = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName=''Branch Account''        
IF(@Mode = 1)         
BEGIN        
IF((SELECT count(*) FROM tblMasterBranchOffice WITH (READCOMMITTEDLOCK) WHERE Code = @Code) > 0)        
BEGIN        
RAISERROR(''Code'',16,1)        
END        
IF((SELECT count(*) FROM tblMasterBranchOffice WITH (READCOMMITTEDLOCK) WHERE Name = @Name) > 0)        
BEGIN        
RAISERROR(''Name'',16,1)        
END        
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@name        
IF(@ExistCount>0)        
BEGIN        
RAISERROR (''AccountName'',16,1)        
END        
set @Code =(select dbo.ProperCase(@Code))        
set @Name = (select dbo.ProperCase(@Name))        
        
INSERT INTO tblFAAccount(AccountName,AccountGroup,OpeningBalance,FATypeID,CBy,CDate,UserAccount,PANNumber,Active)        
VALUES(@Name,@SUNDRYDEBTORS,0,2,@UserID,GETDATE(),0,null,@Active)        
        
SELECT @FAID = FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @Name        
        
insert into tblMasterBranchOffice(Code,Name,Billadd1,Billadd2,Billadd3,ContactPerson,Ph1,Mob1,Email,StateID,        
GSTIN,Active,CBy,CDate,FAID) Values (@Code,@Name,@Billadd1,@Billadd2,@Billadd3,@ContactPerson,@Ph1,@Mob1,@Email,@StateID,        
@GSTIN,@Active,@UserID, GETDATE(),@FAID)        
SELECT SCOPE_IDENTITY()        
END        
IF(@Mode = 2)        
BEGIN        
select @ACCOUNTID = FAID from tblMasterBranchOffice WITH (READCOMMITTEDLOCK) where ID = @ID        
IF((SELECT count(*) FROM tblMasterBranchOffice WITH (READCOMMITTEDLOCK) WHERE Code = @Code AND ID != @ID) > 0)        
BEGIN        
RAISERROR(''Code'',16,1)        
END        
IF((SELECT count(*) FROM tblMasterBranchOffice WITH (READCOMMITTEDLOCK) WHERE Name = @Name AND ID != @ID) > 0)        
BEGIN        
RAISERROR(''Name'',16,1)        
END        
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@name and FAID != @ACCOUNTID        
IF(@ExistCount>0)        
BEGIN        
RAISERROR (''AccountName'',16,1)        
END        
        
INSERT INTO tblMasterHistory (FormID,ID,Column1,Name,Column2,Column3,Column4,Column5,Column6,Column7,Column8,Column9,Column10,Column11,        
Active,CBy,CDate,MBy,MDate,HisCBy,HisCDate) (select 21,*,@UserID, GETDATE() from tblMasterBranchOffice WITH (READCOMMITTEDLOCK) where ID = @ID)        
        
set @Code =(select dbo.ProperCase(@Code))        
set @Name = (select dbo.ProperCase(@Name))        
        
UPDATE tblFAAccount        
SET AccountName=@Name,AccountGroup=@SUNDRYDEBTORS,MBy=@UserID,MDate=GETDATE(),UserAccount=0,PANNumber=null,Active = @Active        
WHERE FAID=@ACCOUNTID        
        
UPDATE tblMasterBranchOffice SET Code = @Code,Name = @Name,Billadd1 = @Billadd1,Billadd2 = @Billadd2,Billadd3 = @Billadd3,ContactPerson = @ContactPerson,        
Ph1 = @Ph1,Mob1 = @Mob1,Email = @Email,StateID = @StateID,GSTIN = @GSTIN,Active = @Active,        
MBy = @UserID ,MDate = GETDATE() WHERE ID = @ID        
SELECT @ID        
END        
IF(@Mode = 3)        
BEGIN        
SELECT PH.*,CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,ST.StateName,
 CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),PH.CDate) ELSE CONVERT(NVARCHAR(100),PH.MDate) END LastActionTime     
 from tblMasterBranchOffice PH WITH (READCOMMITTEDLOCK)    
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = PH.CBy              
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = PH.MBy    
LEFT JOIN tblGSTStateNameandCode ST WITH (READCOMMITTEDLOCK) ON ST.StateID = PH.StateID
order by PH.Name        
END        
IF(@Mode = 4)        
BEGIN        
--SELECT * from tblMasterBranchOffice where ID = @ID     
SELECT PH.*,ST.StateName,CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,    
 CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),PH.CDate) ELSE CONVERT(NVARCHAR(100),PH.MDate) END LastActionTime     
 from tblMasterBranchOffice PH WITH (READCOMMITTEDLOCK)    
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = PH.CBy       
LEFT JOIN tblGSTStateNameandCode ST WITH (READCOMMITTEDLOCK) ON ST.StateID = PH.StateID
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = PH.MBy   
where PH.ID = @ID   
END        
IF(@Mode = 5)        
BEGIN        
SELECT StateID,CONVERT(NVARCHAR,TINNO)+'' - ''+ StateName StateName from tblGSTStateNameandCode WITH (READCOMMITTEDLOCK) WHERE Active = 1 order by StateName        
END        
END TRY        
BEGIN CATCH        
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC]        
END CATCH        
END',
N'[export] nocount;readcommittedlock=19';
GO
/****** uspManageBRS ******/
EXEC #Apply07 N'dbo.uspManageBRS', 0xF967DD5C0AF6163030EFCD721B5E33A3C67B2E98E6CDE2F7F1FDF72A064B637C, NULL, NULL, 0x48D25C1994AE105780668D1BB56BA7CFBA4F13A09E01DC3256EA8C7E270EB44F, 0x7EAD478F65265901E95CC017FCB91F86E427688A66ABA329536E1F169B958385, NULL,
N'ALTER Proc [dbo].[uspManageBRS]      
@tvpBRSSave AS [tvpBRSSave] READONLY      
AS      
SET NOCOUNT ON;
BEGIN    
begin try    
set dateformat dmy;      
DECLARE @DocValue NVARCHAR(255),@Date DATE,@TranDate date,@nJVID int,  
@nCount INT = (SELECT COUNT(*) FROM @tvpBRSSave),@Initial INT =1      
WHILE(@nCount >= @Initial)      
BEGIN      
SELECT @DocValue = DocValue,@Date= BRSDATE,@TranDate = CONVERT(date,TRANDATE),@nJVID  = JVID 
FROM @tvpBRSSave WHERE SNO = @Initial      

update dbo.tblFAJournal set BRSDate = (CASE WHEN isnull(@Date,'''') = '''' THEN NULL ELSE @Date END) where [Status] NOT IN (2,4)                 
AND DocDate = @TranDate  AND JVID = @nJVID AND DocValue = @DocValue  
AND DocDate between (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) and (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK))     

SET @Initial += 1;      
END      
end try    
begin catch    
select ERROR_LINE(),ERROR_PROCEDURE(),ERROR_MESSAGE()    
end catch    
END',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspManageChequeBook ******/
EXEC #Apply07 N'dbo.uspManageChequeBook', 0x50903DE9F3A33DC01DCBE2EED28F3DDBCF62F49EABB30EE7F6ECD8627BA055BF, NULL, NULL, 0x2C5D282EA5BBA8549F342745D6888BE3939D90A55AF08BD71C21DFC1FDC93179, 0xC2D01FCDE0DE911E548D7A738FE5696D2D604C88D033668698CB7C27BD6E422D, NULL,
N'ALTER PROC [dbo].[uspManageChequeBook]        
@Mode INT,@ID smallint = NULL,@ChequeBookreferNo nvarchar(50) = null,@StartingChequeNo nvarchar(50) = null,        
@NoofLeaves smallint = null,@BankAccountID smallint = null,@Active bit = null,@CBy smallint = null            
AS            
SET NOCOUNT ON;
begin                
BEGIN TRY                    
IF(@Mode = 1)                
BEGIN                
IF((SELECT count(*) FROM tblMasterChequeBook WITH (READCOMMITTEDLOCK) WHERE ChequeBookreferNo = @ChequeBookreferNo) > 0)                
BEGIN                
RAISERROR(''Code Already Exists'',16,1)                
END                    
set @ChequeBookreferNo = (select dbo.ProperCase(@ChequeBookreferNo))        
insert into tblMasterChequeBook(ChequeBookreferNo,StartingChequeNo,NoofLeaves,BankAccountID,Active,CBy,CDate) Values         
(@ChequeBookreferNo,@StartingChequeNo,@NoofLeaves,@BankAccountID,@Active,@CBy, GETDATE())                
SELECT SCOPE_IDENTITY()                
END        
IF(@Mode = 3)--DETAIL INSERT        
BEGIN        
if(ISNULL(@NoofLeaves,1) = 0)        
begin        
delete tblMasterChequeBookDetail WHERE ChequeBookID = @ID                
end        
insert into tblMasterChequeBookDetail(ChequeBookID,ChequeNo,Status) Values (@ID,@ChequeBookreferNo,@StartingChequeNo)                       
END        
IF(@Mode = 2)                
BEGIN                
IF((SELECT count(*) FROM tblMasterChequeBook WITH (READCOMMITTEDLOCK) WHERE ChequeBookreferNo = @ChequeBookreferNo AND ChequeBookID != @ID) > 0)                
BEGIN                
RAISERROR(''Code Already Exists'',16,1)                
END                       
set @ChequeBookreferNo =(select dbo.ProperCase(@ChequeBookreferNo))        
UPDATE tblMasterChequeBook SET ChequeBookreferNo = @ChequeBookreferNo,StartingChequeNo = @StartingChequeNo,NoofLeaves = @NoofLeaves,        
BankAccountID = @BankAccountID,Active = @Active,MBy = @CBy ,MDate = GETDATE() WHERE ChequeBookID = @ID                
SELECT @ID                
END                
IF(@Mode = 4)                
BEGIN                          
UPDATE tblMasterChequeBookDetail SET ChequeNo = @ChequeBookreferNo,Status = @StartingChequeNo WHERE ChequeBookID = @ID                
SELECT @ID                
END        
IF(@Mode = 5)                
BEGIN                
SELECT ChequeBookID,ChequeBookreferNo,StartingChequeNo,NoofLeaves,MC.BankAccountID,MB.AccountNo,MC.Active,CASE WHEN ISNULL(MC.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,  
 CASE WHEN ISNULL(MC.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MC.CDate) ELSE CONVERT(NVARCHAR(100),MC.MDate) END LastActionTime   
 from tblMasterChequeBook MC WITH (READCOMMITTEDLOCK)        
JOIN tblMasterBankAccount MB WITH (READCOMMITTEDLOCK) ON MB.ID = MC.BankAccountID  
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MC.CBy            
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MC.MBy   
order by ChequeBookreferNo        
END                
IF(@Mode = 6)                
BEGIN                
SELECT ChequeBookID ID,ChequeNo Name,Status from tblMasterChequeBookDetail WITH (READCOMMITTEDLOCK) where ChequeBookID = @ID             
END          
IF(@Mode = 7)                
BEGIN                
SELECT ID,AccountNo Name,'''' Status from tblMasterBankAccount WITH (READCOMMITTEDLOCK) where Active = 1 order by AccountNo        
END        
IF(@Mode = 8)                
BEGIN                
--SELECT 1 ID,''Open'' Name,'''' Status  union SELECT 4,''Cancel'','''' Status union SELECT 4,''Close'','''' Status      
SELECT ID,Description Name,'''' Status  FROM TBLSTATUS WITH (READCOMMITTEDLOCK) WHERE ACTIVE = 1 AND ID IN (1,4,5)     
END  
IF(@Mode = 9)
BEGIN
SELECT ChequeBookID,ChequeBookreferNo,StartingChequeNo,NoofLeaves,MC.BankAccountID,MB.AccountNo,MC.Active,CASE WHEN ISNULL(MC.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,  
 CASE WHEN ISNULL(MC.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MC.CDate) ELSE CONVERT(NVARCHAR(100),MC.MDate) END LastActionTime   
 from tblMasterChequeBook MC WITH (READCOMMITTEDLOCK)        
JOIN tblMasterBankAccount MB WITH (READCOMMITTEDLOCK) ON MB.ID = MC.BankAccountID  
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MC.CBy            
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MC.MBy
WHERE MC.ChequeBookID = @ID
order by ChequeBookreferNo    
END
END TRY                      
BEGIN CATCH                      
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC]                      
END CATCH                      
END',
N'[export] nocount;readcommittedlock=13';
GO
/****** uspManageChequeDeposit ******/
EXEC #Apply07 N'dbo.uspManageChequeDeposit', 0x8A2C278AF311E9495B451609B9C20F2E3F64230D58A7CAE4F62B148B9F3E9BF6, NULL, NULL, 0x75E536B62F6233D1D089168A2286BC32835BDA186746054DDE0FA266CFD59EF1, 0xDA67CDD4FA5F674F46E80FC276275C112A79A395CADF7B30D385BACC66FC6215, NULL,
N'--uspManageChequeDeposit 356,9,2,null,''2018-02-27'',null,null,12
ALTER PROCEDURE [dbo].[uspManageChequeDeposit]
@DepositID INT=NULL,@Condition SMALLINT,@UID INT,@CollId INT=NULL,@DocDate DATE=NULL,@AccountId INT=NULL,@SalesManID INT=NULL,
@BankCharges DECIMAL (25,6)=NULL,@BounceDate Date=Null,@CheckStatus INT=NULL,@UDFId INT=NULL
AS
BEGIN
BEGIN TRY
SET NOCOUNT ON;
DECLARE @CStatus INT,@ChargesVoucherId INT,@ChaqueVoucherId INT,@DepositRefId INT ,@CollectionId INT,
@CollectionDocID NVARCHAR(255),@PartyAccountID INT,@JVID INT,@BranchID int
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)
declare @maxPrintID int = (select ISNULL(MAX(identPrint),0) + 1 AS identPrint from tblTranChequeDeposit WITH (READCOMMITTEDLOCK))
--Cheque Debosit
IF(@Condition =1)
BEGIN
declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))
DECLARE @DocSeriesIdent int

DECLARE @DocId VARCHAR(50),@UDFDocValue INT,@UDFDocPrefix NVARCHAR(255) ,@UDFDocId NVARCHAR(255),@Amount DECIMAL (25,6)
DECLARE @DocValue INT,@Status SMALLINT ,@BankId INT,@ISActive NVARCHAR(255),@AccId INT,@ScopeID INT
SELECT @BranchID = ISNULL(BranchID,0) FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE ColID = @CollId

insert into @tblDocdetails
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate)
and BranchID = @BranchID and TransID = 20
IF((select count(*) from @tblDocdetails) = 0)
BEGIN
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)
END
SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails

UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = 20 and ID = @DocSeriesIdent

--SELECT @DocValue=DocValue FROM tblDocumentSeries WHERE TransID = 20
--SELECT @DocId =DocPrefix +CONVERT(NVARCHAR,DocValue) FROM tblDocumentSeries WHERE TransID =20
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId
--Get Cheque No, Cheque Date, IFSC Code
DECLARE @ChequeNo NVARCHAR(50),@ChequeDate NVARCHAR(50),@IFSC_Code NVARCHAR(50),@ChequeInfo NVARCHAR(100)
SELECT @ChequeNo=[Cheque/DD Number],@ChequeDate=CONVERT(NVARCHAR,Date,103),@IFSC_Code=IfscCode FROM tblCollPMDetails WITH (READCOMMITTEDLOCK) where ColID=@CollId
IF ISNULL(@IFSC_Code,'''')!=''''
BEGIN
SET @ChequeInfo = (@ChequeNo+'', ''+@ChequeDate+'' - ''+@IFSC_Code)
END
ELSE
BEGIN
SET @ChequeInfo = (@ChequeNo+'', ''+@ChequeDate)
END

SELECT @Status=[Status],@Amount=CollAmt FROM tblCollPMDetails WITH (READCOMMITTEDLOCK) WHERE ColID =@CollId
IF((ISNULL(@Status ,0) != ISNULL(@CheckStatus ,0)) or @Status in (2,4))
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
--Bounce Cheque Goes to Deposit at the Time Verify Interval Voucher Amount verify WithOut Bank Charges
IF ISNULL(@CheckStatus ,0) =9
BEGIN
SELECT @ChaqueVoucherId=ISNULL(ChaqueVoucherId,0),@ChargesVoucherId=ISNULL(ChargesVoucherId,0)
FROM tblTranChequeDeposit WITH (READCOMMITTEDLOCK) WHERE DepositID =@DepositID
--ValiDate Internal Voucher Amount
IF (SELECT ISNULL(Voucher.NetAmount,0) - ISNULL(Voucher.Balance,0) FROM tblTranPRVoucher Voucher WITH (READCOMMITTEDLOCK)
WHERE Voucher.ID =@ChaqueVoucherId)<>0
BEGIN
RAISERROR(''Document Amount mismatched'',16,1);
END
--Validate Internal Voucher Status
IF (SELECT Voucher .[Status] FROM tblTranPRVoucher Voucher WITH (READCOMMITTEDLOCK) WHERE Voucher.ID =@ChaqueVoucherId)<>1
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
-- Revert Cheque Amount Internal Voucher
UPDATE tblTranPRVoucher SET [Status] =4,ClBy =@UID ,ClDate =GETDATE ()
WHERE ID = @ChaqueVoucherId
--ARAVINDAN REWORK FOR CANCEL RV in FA
UPDATE dbo.tblFAJournal SET Status = 4 where TransId = @ChaqueVoucherId
END
--Get Deposit Financila Account ID
--SELECT @BankId=FAID FROM tblMasterBankAccount WHERE ID = @AccountId
IF((SELECT COUNT(DocValue) FROM tblQuotationHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocID and
DocDate BETWEEN @F_SD AND @F_ED and DocPrefix = 20) != 0)-- and Status in (3,4,5,6)
BEGIN
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocID)
END
set @BankId = @AccountId;
INSERT INTO tblTranChequeDeposit(DocID,DocPrefiX,DocValue,DocDate,DepositAccountId,SalesManId,CollId,[Status],
UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,DepositRefId,CBy,CDate,identPrint)
VALUES(@DocID,20,@DocValue,@DocDate,@BankId,@SalesManID,@CollId,1,
@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@DepositID,@UID,GETDATE(),@maxPrintID)
SET @ScopeID =(SELECT SCOPE_IDENTITY());
--Posting
SELECT @JVID=MAX(ISNULL(JVID,0))+1 FROM tblFAJournal WITH (READCOMMITTEDLOCK)
--Deposit Account
INSERT INTO tblFAJournal([JVID],[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],
[Status],UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy ,CDate,TransId,ChequeInfo,BranchID)
VALUES ( @JVID,@DocId, 20, @DocValue,@DocDate,NULL ,@BankId ,0,ISNULL(@Amount,0), 0,NULL,''Cheque Deposit'',
1,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID ,GETDATE (),@ScopeID,@ChequeInfo,@BranchID)
--Cheque in Hand
INSERT INTO tblFAJournal([JVID],[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],
[Status],UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy ,CDate ,TransId,ChequeInfo,BranchID)
VALUES ( @JVID,@DocId, 20, @DocValue,@DocDate ,NULL ,16,ISNULL(@Amount,0),0, 0,NULL,''Cheque Deposit'',
1,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID ,GETDATE (),@ScopeID,@ChequeInfo,@BranchID)
--Change Cheque Status Close
UPDATE tblCollPMDetails SET [Status] =5 WHERE ColID =@CollId
--Update Doc Series Table and User Define Header Series Table
UPDATE tblDocumentSeries SET DocValue =DocValue +1 WHERE TransID =20
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@UDFId
--SELECT Scope Ident Id
SELECT @ScopeID
END
---------------1 end
--Cheque Bounce
ELSE IF(@Condition =9)
BEGIN
SELECT @DocId = DocID,@DocValue=DocValue ,@DocDate =DocDate,@Status =[Status],@CollectionId =CollId,@Accid=DepositAccountId
FROM tblTranChequeDeposit WITH (READCOMMITTEDLOCK) WHERE DepositID =@DepositID
SET @ScopeID=@DepositID
IF ISNULL(@Status ,0)!=1
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
--Get Collection DocId
SELECT @CollectionDocID=DocID,@BranchID = ISNULL(BranchID,0) FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE ColID = @CollectionId
--Change Cheque Status Bounce
UPDATE tblCollPMDetails SET [Status] =9 WHERE ColID =@CollectionId
--Status Change as Bounce
UPDATE tblTranChequeDeposit SET [Status] =9,BounceDate=@BounceDate,Clby=@UID ,ClDate=GETDATE ()
WHERE DepositID =@DepositID
--UPDATE tblFAJournal SET [Status] =5 WHERE TransId = @DepositID AND DocPrefix =14
--reversal entry
SELECT @Amount=CollAmt,@PartyAccountID=AccId FROM tblCollPMDetails WITH (READCOMMITTEDLOCK) WHERE ColID =@CollectionId
--Cheque in Hand
SELECT @JVID=MAX(ISNULL(JVID,0))+1 FROM tblFAJournal WITH (READCOMMITTEDLOCK)
INSERT INTO tblFAJournal([JVID],[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],
[Status],UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy ,CDate ,TransId,BranchID)
VALUES (@JVID, @DocId, 20, @DocValue,@DocDate ,NULL ,16,0,ISNULL(@Amount,0),0,NULL,''Cheque Bounce'',
9,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID ,GETDATE (),@ScopeID,@BranchID)
--Deposit AccId
INSERT INTO tblFAJournal([JVID],[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],
[Status],UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy ,CDate,TransId,BranchID)
VALUES (@JVID,@DocId, 20, @DocValue,@DocDate,NULL ,@Accid,ISNULL(@Amount,0),0, 0,NULL,''Cheque Bounce'',
9,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID ,GETDATE (),@ScopeID,@BranchID)
-- Get UDN DOC ID Based on Permission
DECLARE @UDFCount INT,@UDNSingle INT
SET @UDFCount = (
SELECT COUNT(DISTINCT UDNId) FROM tblMasterUserDefineNoDetail WITH (READCOMMITTEDLOCK)
WHERE UDNId IN (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE TransId=7) AND UserId=@UID
)
IF ISNULL(@UDFCount,0)=1
BEGIN
SET @UDNSingle = (SELECT DISTINCT UDNId FROM tblMasterUserDefineNoDetail WITH (READCOMMITTEDLOCK)
WHERE UDNId IN (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE TransId=7) AND UserId=@UID)
END
declare @acname nvarchar(255),@partyaccname nvarchar(255)
select @acname = AccountName from tblFAAccount WITH (READCOMMITTEDLOCK) where FAID = @Accid
select @partyaccname = AccountName from tblFAAccount WITH (READCOMMITTEDLOCK) where FAID = @PartyAccountID
DECLARE @Narration NVARCHAR(255)=''Cheque Bounce : ''+@CollectionDocID+'' : ''+CONVERT(NVARCHAR,GETDATE(),103)
--Cheque Amount Create Payable Voucher
--@Accid
--EXEC [dbo].[uspManagePRVoucher] @DocDate,@PartyAccountID,@DocId,@Accid,@Amount,0,@Amount,@Narration,@UID,1,16,0,0,3,@UDNSingle,@DepositID,1
--@PartyAccountID,@Accid
EXEC [dbo].[uspManagePRVoucher] 1,7,0,@DocDate,@DocId,@partyaccname,@acname,@Amount,0,0,0,@Amount,0,@Amount,null,@Narration,
@UID,3,0,@DepositID,1,null,0,1,null,0,0,@BranchID
--Bank Charges Given
IF ISNULL(@BankCharges,0)>0
BEGIN
SET @Narration =''Bounce Charges : ''+@CollectionDocID+'' : ''+CONVERT(NVARCHAR,GETDATE(),103)
--EXEC [dbo].[uspManagePRVoucher] @DocDate,@PartyAccountID,@DocId,4,@BankCharges,0,@BankCharges,@Narration,@UID,1,16,0,0,3,@UDNSingle,@DepositID ,2
EXEC [dbo].[uspManagePRVoucher] 1,7,0,@DocDate,@DocId,@partyaccname,''BANK CHARGES'',@BankCharges,0,0,0,@BankCharges,0,
@BankCharges,null,@Narration,@UID,3,0,@DepositID,2,null,0,1,null,0,0,@BranchID
END
END
------------second end
--Cheque Realisation
ELSE IF(@Condition =5)
BEGIN
SELECT @Status =[Status] FROM tblTranChequeDeposit WITH (READCOMMITTEDLOCK) WHERE DepositID =@DepositID
IF ISNULL(@Status ,0)!=1
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
UPDATE tblTranChequeDeposit SET [Status] =5 ,ClearanceDate=@BounceDate WHERE DepositID =@DepositID
--UPDATE tblFAJournal SET [Status] =5 WHERE TransId = @DepositID AND DocPrefix =14 AND [Status] =1
END
-- Cheque Debosit Cancel
ELSE IF(@Condition =4)
BEGIN
DECLARE @PartyAcc INT ,@AccCount INT,@AccountName NVARCHAR(255)
--Get Deposit Detail
SELECT @PartyAcc=DepositAccountId,@Status =[Status], @DepositRefId=DepositRefId,
@ChaqueVoucherId=ISNULL(ChaqueVoucherId,0),@ChargesVoucherId=ISNULL(ChargesVoucherId,0)
FROM tblTranChequeDeposit WITH (READCOMMITTEDLOCK)
WHERE DepositID = @DepositID

-- Check Deposit Current Status
IF ISNULL(@Status ,0)!= 1
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
IF ISNULL(@DepositRefId,0)>0
BEGIN
--Already Bounce Cheque Re-open the Voucher
SELECT @ChaqueVoucherId=ISNULL(ChaqueVoucherId,0) FROM tblTranChequeDeposit WITH (READCOMMITTEDLOCK) WHERE DepositID = @DepositRefId
--Internal PR Voucher Open
UPDATE tblTranPRVoucher SET [Status] =1 WHERE ID = @ChaqueVoucherId
--ARAVINDAN REWORK FOR REOPEN RV IN FA
UPDATE dbo.tblFAJournal SET Status = 1 where TransId = @ChaqueVoucherId
--
END
--Cheque Revert Status 1 OR 9
UPDATE tblCollPMDetails SET [Status] = (CASE WHEN ISNULL(@DepositRefId,0)>0 THEN 9 ELSE 1 END)
FROM tblCollPMDetails CP WITH (READCOMMITTEDLOCK) JOIN tblTranChequeDeposit CD WITH (READCOMMITTEDLOCK) ON CD.CollId=CP.ColID
WHERE CD.DepositID =@DepositID
--Cancel Exist Deposit Cheque
UPDATE tblTranChequeDeposit SET [Status] =4,Clby=@UID ,ClDate=GETDATE ()
WHERE DepositID =@DepositID
--Revert Posting
UPDATE tblFAJournal SET [Status] =4,Clby=@UID ,ClDate=GETDATE ()
WHERE TransId = @DepositID AND DocPrefix =20 AND [Status] =1
END
--Cheque Bounce /Realisation Cancel Using Own Condition 2
ELSE IF(@Condition =2)
BEGIN
SELECT @Status=[Status] FROM tblTranChequeDeposit WITH (READCOMMITTEDLOCK) WHERE DepositID =@DepositID
IF((ISNULL(@CheckStatus,0)!=@Status) or @Status in (2,4))
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
--Cheque Realisation Cancel Revert
IF(@Status =5)
BEGIN
UPDATE tblTranChequeDeposit SET [Status] =1 WHERE DepositID =@DepositID
UPDATE tblFAJournal SET [Status] =1 WHERE TransId = @DepositID AND DocPrefix =20 AND [Status] =5
END
--Cheque Bounce Cancel Revert
IF(@Status =9)
BEGIN
SELECT @CStatus =CP.[Status] FROM tblCollPMDetails CP WITH (READCOMMITTEDLOCK) JOIN tblTranChequeDeposit CD WITH (READCOMMITTEDLOCK) ON CD.CollId=CP.ColID
WHERE CD.DepositID =@DepositID
IF ISNULL(@CStatus,0)!=9
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
SELECT @ChaqueVoucherId=ISNULL(ChaqueVoucherId,0),@ChargesVoucherId=ISNULL(ChargesVoucherId,0)
FROM tblTranChequeDeposit WITH (READCOMMITTEDLOCK) WHERE DepositID =@DepositID
--Internal Cheque PR Voucher Validate
IF ((SELECT COUNT(*) FROM tblTranPRVoucher WITH (READCOMMITTEDLOCK)
WHERE ID IN (@ChargesVoucherId,@ChaqueVoucherId) AND ISNULL([Balance],0) !=ISNULL([NetAmount],0)) >0)
BEGIN
RAISERROR(''Document amount mismatched'',16,1);
END
IF ((SELECT COUNT(*) FROM tblTranPRVoucher WITH (READCOMMITTEDLOCK) WHERE ID IN (@ChargesVoucherId,@ChaqueVoucherId) AND [Status] !=1) >0)
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
--Internal PR Voucher Cancel
UPDATE tblTranPRVoucher SET [Status] =4,Clby=@UID ,ClDate=GETDATE ()
WHERE ID IN (@ChargesVoucherId,@ChaqueVoucherId)
----Cheque Re-Open
--UPDATE tblFAJournal SET [Status] =1 WHERE TransId = @DepositID AND DocPrefix =14 AND [Status] =5--Cheque Status Close
UPDATE tblCollPMDetails SET [Status] =5
FROM tblCollPMDetails CP WITH (READCOMMITTEDLOCK) JOIN tblTranChequeDeposit CD WITH (READCOMMITTEDLOCK) ON CD.CollId=CP.ColID WHERE CD.DepositID =@DepositID
--Cheque Deposit Open
UPDATE tblTranChequeDeposit SET [Status] =1 WHERE DepositID =@DepositID
--Bounce Posting Revert
UPDATE tblFAJournal SET [Status] =4,Clby=@UID ,ClDate=GETDATE ()
WHERE TransId = @DepositID AND DocPrefix =20 AND [Status] =9
--Voucher Status Revert
UPDATE tblFAJournal SET [Status] =4,Clby=@UID ,ClDate=GETDATE ()
WHERE TransId IN (@ChargesVoucherId,@ChaqueVoucherId) AND DocPrefix = 7
END
END
END TRY
BEGIN CATCH
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE()
END CATCH
END',
N'[export] number-series-updlock=4;readcommittedlock=32';
GO
/****** uspManageColorSettings ******/
EXEC #Apply07 N'dbo.uspManageColorSettings', 0x8DE6214E99B72ED30A63E981DE4A3D2D2619DA245A73D9CD762A08D6E152BD06, NULL, NULL, 0xF3ADAC87C5B09C83C6718D1857FCE8D79D72026B7A7A9AB2151A4EE9A752E90B, 0x11AF00DE8E99061FA231A71FDA54A8434A7244BD801E3510D65F5A732B6BADAC, NULL,
N'--[uspManageColorSettings] 1,1  
ALTER proc [dbo].[uspManageColorSettings]                        
@Mode INT,@ThemeID INT = 0,@UID int = 2,@TransMode INT = 1,@NewThemeName nvarchar(255) = null,@MenuHeader NVARCHAR(100) = NULL,
@AddButton NVARCHAR(100) = NULL,@SaveButton NVARCHAR(100) = NULL,@ClearButton NVARCHAR(100) = NULL,                        
@CloseButton NVARCHAR(100) = NULL,@PDFButton NVARCHAR(100) = NULL,@PreviewButton NVARCHAR(100) = NULL,@PopupHeader NVARCHAR(100) = NULL,                        
@PopupFooter NVARCHAR(100) = NULL,@ConfirmPopupYes NVARCHAR(100) = NULL,@ConfirmPopupNo NVARCHAR(100) = NULL,@SubMenuColor NVARCHAR(100) = NULL,      
@SubMenuHover NVARCHAR(100) = NULL, @MenuColor NVARCHAR(100) = NULL,@CompanyNameColor NVARCHAR(100) = NULL,@GridHeaderBackGround NVARCHAR(100) = NULL,                  
@GridHeaderTextColor NVARCHAR(100) = NULL,@PopupHeaderText NVARCHAR(100) = NULL,@DraftButton NVARCHAR(100) = NULL,            
@AutoCompBG NVARCHAR(100) = NULL,@AutoCompLine1 NVARCHAR(100) = NULL,@AutoCompLine2 NVARCHAR(100) = NULL,        
@ButtonTextColor NVARCHAR(100) = NULL,@EditButton NVARCHAR(100) = NULL,@CancelButton NVARCHAR(100) = NULL,        
@VariantButton NVARCHAR(100) = NULL ,@AutocompleteFieldBG NVARCHAR(100) = NULL,@FilterButton NVARCHAR(100) = NULL,  
@MailButton NVARCHAR(100) = NULL,@PrintButton NVARCHAR(100) = NULL,@BatchButton NVARCHAR(100) = NULL,@AutoCompleteSelectBG NVARCHAR(100) = NULL             
AS                        
SET NOCOUNT ON;
BEGIN     
IF(@Mode = 0)                        
BEGIN 
SELECT DISTINCT ThemeID ID,ThemeName Name FROM tblColorSettings WITH (READCOMMITTEDLOCK)
END
IF(@Mode = 1)                        
BEGIN                        
SELECT MenuHeader,AddButton,SaveButton,ClearButton,CloseButton,PDFButton,PreviewButton,PopupHeader,PopupFooter,ConfirmPopupYes,                    
ConfirmPopupNo,SubMenuColor,SubMenuHover,MenuColor,CompanyNameColor,GridHeaderBackGround,GridHeaderTextColor,PopupHeaderText,DraftButton,            
AutocompleteBG,AutocompleteLine1,AutocompleteLine2,ButtonTextColor,EditButton,CancelButton,VariantButton,  
AutocompleteFieldBG,FilterButton,MailButton,PrintButton,BatchButton,AutoCompleteSelectBG  
from(                            
SELECT Name,Value FROM tblColorSettings WITH (READCOMMITTEDLOCK) where ThemeID = @ThemeID ) AS Nar                            
PIVOT(                            
MAX(Value)FOR Name in (MenuHeader,AddButton,SaveButton,ClearButton,CloseButton,PDFButton,PreviewButton,PopupHeader,PopupFooter,                    
ConfirmPopupYes,ConfirmPopupNo,SubMenuColor,SubMenuHover,MenuColor,CompanyNameColor,GridHeaderBackGround,GridHeaderTextColor,PopupHeaderText,DraftButton,            
AutocompleteBG,AutocompleteLine1,AutocompleteLine2,ButtonTextColor,EditButton,CancelButton,VariantButton,  
AutocompleteFieldBG,FilterButton,MailButton,PrintButton,BatchButton,AutoCompleteSelectBG)                            
) AS nk                          
END                        
IF(@Mode = 2)                        
BEGIN                                    
IF(@TransMode = 1)--Update in Existising Theme
BEGIN                
UPDATE tblColorSettings SET Value = @MenuHeader where ThemeID = @ThemeID and ID = 1                      
UPDATE tblColorSettings SET Value = @AddButton where ThemeID = @ThemeID and ID = 2                        
UPDATE tblColorSettings SET Value = @SaveButton where ThemeID = @ThemeID and ID = 3                        
UPDATE tblColorSettings SET Value = @ClearButton where ThemeID = @ThemeID and ID = 4                        
UPDATE tblColorSettings SET Value = @CloseButton where ThemeID = @ThemeID and ID = 5                        
UPDATE tblColorSettings SET Value = @PDFButton where ThemeID = @ThemeID and ID = 6                        
UPDATE tblColorSettings SET Value = @PreviewButton where ThemeID = @ThemeID and ID = 7                        
UPDATE tblColorSettings SET Value = @PopupHeader where ThemeID = @ThemeID and ID = 8                        
UPDATE tblColorSettings SET Value = @PopupFooter where ThemeID = @ThemeID and ID = 9                        
UPDATE tblColorSettings SET Value = @ConfirmPopupYes where ThemeID = @ThemeID and ID = 10                        
UPDATE tblColorSettings SET Value = @ConfirmPopupNo where ThemeID = @ThemeID and ID = 11                        
UPDATE tblColorSettings SET Value = @SubMenuColor where ThemeID = @ThemeID and ID = 12      
UPDATE tblColorSettings SET Value = @MenuColor where ThemeID = @ThemeID and ID = 13                    
UPDATE tblColorSettings SET Value = @CompanyNameColor where ThemeID = @ThemeID and ID = 14                  
UPDATE tblColorSettings SET Value = @GridHeaderBackGround where ThemeID = @ThemeID and ID = 15                   
UPDATE tblColorSettings SET Value = @GridHeaderTextColor where ThemeID = @ThemeID and ID = 16                
UPDATE tblColorSettings SET Value = @PopupHeaderText where ThemeID = @ThemeID and ID = 17                
UPDATE tblColorSettings SET Value = @DraftButton where ThemeID = @ThemeID and ID = 18              
            
UPDATE tblColorSettings SET Value = @AutoCompBG where ThemeID = @ThemeID and ID = 19              
UPDATE tblColorSettings SET Value = @AutoCompLine1 where ThemeID = @ThemeID and ID = 20              
UPDATE tblColorSettings SET Value = @AutoCompLine2 where ThemeID = @ThemeID and ID = 21              
UPDATE tblColorSettings SET Value = @ButtonTextColor where ThemeID = @ThemeID and ID = 22              
UPDATE tblColorSettings SET Value = @EditButton where ThemeID = @ThemeID and ID = 23              
UPDATE tblColorSettings SET Value = @CancelButton where ThemeID = @ThemeID and ID = 24              
UPDATE tblColorSettings SET Value = @VariantButton where ThemeID = @ThemeID and ID = 25         
UPDATE tblColorSettings SET Value = @SubMenuHover where ThemeID = @ThemeID and ID = 26      
  
UPDATE tblColorSettings SET Value = @AutocompleteFieldBG where ThemeID = @ThemeID and ID = 27              
UPDATE tblColorSettings SET Value = @FilterButton where ThemeID = @ThemeID and ID = 28              
UPDATE tblColorSettings SET Value = @MailButton where ThemeID = @ThemeID and ID = 29         
UPDATE tblColorSettings SET Value = @PrintButton where ThemeID = @ThemeID and ID = 30     
UPDATE tblColorSettings SET Value = @BatchButton where ThemeID = @ThemeID and ID = 31  
UPDATE tblColorSettings SET Value = @AutoCompleteSelectBG where ThemeID = @ThemeID and ID = 32  
END
ELSE IF(@TransMode = 2)--New Theme
BEGIN
set @ThemeID = (select max(distinct ThemeID) + 1 from tblColorSettings WITH (READCOMMITTEDLOCK))
INSERT INTO tblColorSettings VALUES 
(1,@ThemeID,''MenuHeader'',@MenuHeader,@NewThemeName),
(2,@ThemeID,''AddButton'',@AddButton,@NewThemeName),
(3,@ThemeID,''SaveButton'',@SaveButton,@NewThemeName),
(4,@ThemeID,''ClearButton'',@ClearButton,@NewThemeName),
(5,@ThemeID,''CloseButton'',@CloseButton,@NewThemeName),
(6,@ThemeID,''PDFButton'',@PDFButton,@NewThemeName),
(7,@ThemeID,''PreviewButton'',@PreviewButton,@NewThemeName),
(8,@ThemeID,''PopupHeader'',@PopupHeader,@NewThemeName),
(9,@ThemeID,''PopupFooter'',@PopupFooter,@NewThemeName),
(10,@ThemeID,''ConfirmPopupYes'',@ConfirmPopupYes,@NewThemeName),
(11,@ThemeID,''ConfirmPopupNo'',@ConfirmPopupNo,@NewThemeName),
(12,@ThemeID,''SubMenuColor'',@SubMenuColor,@NewThemeName),
(13,@ThemeID,''MenuColor'',@MenuColor,@NewThemeName),
(14,@ThemeID,''CompanyNameColor'',@CompanyNameColor,@NewThemeName),
(15,@ThemeID,''GridHeaderBackGround'',@GridHeaderBackGround,@NewThemeName),
(16,@ThemeID,''GridHeaderTextColor'',@GridHeaderTextColor,@NewThemeName),
(17,@ThemeID,''PopupHeaderText'',@PopupHeaderText,@NewThemeName),
(18,@ThemeID,''DraftButton'',@DraftButton,@NewThemeName),
(19,@ThemeID,''AutocompleteBG'',@AutoCompBG,@NewThemeName),
(20,@ThemeID,''AutocompleteLine1'',@AutoCompLine1,@NewThemeName),
(21,@ThemeID,''AutocompleteLine2'',@AutoCompLine2,@NewThemeName),
(22,@ThemeID,''ButtonTextColor'',@ButtonTextColor,@NewThemeName),
(23,@ThemeID,''EditButton'',@EditButton,@NewThemeName),
(24,@ThemeID,''CancelButton'',@CancelButton,@NewThemeName),
(25,@ThemeID,''VariantButton'',@VariantButton,@NewThemeName),
(26,@ThemeID,''SubMenuHover'',@SubMenuHover,@NewThemeName),
(27,@ThemeID,''AutocompleteFieldBG'',@AutocompleteFieldBG,@NewThemeName),
(28,@ThemeID,''FilterButton'',@FilterButton,@NewThemeName),
(29,@ThemeID,''MailButton'',@MailButton,@NewThemeName),
(30,@ThemeID,''PrintButton'',@PrintButton,@NewThemeName),
(31,@ThemeID,''BatchButton'',@BatchButton,@NewThemeName),
(32,@ThemeID,''AutoCompleteSelectBG'',@AutoCompleteSelectBG,@NewThemeName)
END
UPDATE tblAppConfig SET AppValue = @ThemeID where AppID = 9                 
select @ThemeID,''Saved Successful''                        
END                        
END',
N'[export] nocount;readcommittedlock=3';
GO
/****** uspManageCreditDebitNote ******/
EXEC #Apply07 N'dbo.uspManageCreditDebitNote', 0x84DFED438DF1CFD4517EE588F0C5E985EDFD851F171D363CD8492CE45A7E79CC, NULL, NULL, 0x1F299490DFBED34C3CA3C92FC31E1C38A1D8FF194AC88993560516B42B93D17A, 0xC1ACA252CE547F6FA3C7510268DB943B93B1FABAA582836F76C1AC8DF7B01E95, NULL,
N'ALTER PROCEDURE [dbo].[uspManageCreditDebitNote]    
@nMode INT,@ID int=NULL,@TransID NVARCHAR(50),@DocDate DATE,@DocRef NVARCHAR(50),@PartyName NVARCHAR(255),@AccountName NVARCHAR(255),    
@Credit DECIMAL (25,4)=NULL,@Debit DECIMAL (25,4)=NULL,@Remarks NVARCHAR(255)=NULL,@Narration NVARCHAR(255)=NULL,    
@UID INT,@Status INT=NULL ,@UDFId INT=NULL,@nCurruntStaus INT = NULL ,@BranchID INT ,@UDNDocID_Import NVARCHAR(255)=NULL,    
@ImportStatus INT = 0    
AS    
--IF ISNULL(@Status,0)=0    
SET NOCOUNT ON;
BEGIN TRY    
BEGIN TRAN    
Declare @DocValue INT, @JVID INT,@PartyId INT,@AccountID INT    
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)    
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)    
    
SELECT @PartyId = FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @PartyName    
SELECT @AccountID = FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @AccountName    
    
declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))    
DECLARE @DocSeriesIdent int    
Declare @DocId NVARCHAR(50),@UDFDocValue INT,@UDFDocPrefix NVARCHAR(255) ,@UDFDocId NVARCHAR(255),@CDUDFID nvarchar(255)    
DECLARE @SCOPID INT    
SELECT @DocValue=DocValue from tblDocumentSeries WITH (READCOMMITTEDLOCK) WHERE TransID=@TransID    
--insert into #temp(Docvalue) values (@DocValue)    
print @DocValue ----    
SELECT @DocId=DocPrefix + Convert(nvarchar, DocValue) from tblDocumentSeries WITH (READCOMMITTEDLOCK) WHERE TransID=@TransID    
    
print @DocId ----    
IF ISNULL(@UDFId,0)>0 --- UserDefine series.    
BEGIN    
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId    
END    
    
DECLARE @TempStatus INT ,@TempValue DECIMAL (25,6),@TempBalance DECIMAL (25,6)    
IF(ISNULL(@TransId,0) > 0)    
BEGIN    
SELECT @TempValue = NoteValue,@TempBalance = Balance,@TempStatus = Status FROM tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE ID = @ID    
END    
IF(@Status = 1 OR @ImportStatus = 4) -- CREATE    
BEGIN    
insert into @tblDocdetails    
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate) and BranchID = @BranchID and TransID = @TransID    
IF((select count(*) from @tblDocdetails) = 0)    
BEGIN    
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)    
END    
    
SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails    
    
UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = @TransID and ID = @DocSeriesIdent    
IF ISNULL(@UDFId,0)>0    
BEGIN    
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)    
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK)    
WHERE UDNId=@UDFId    
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@UDFId    
--PUT HERE    
END    
ELSE IF ISNULL(@UDFId,0)=0 AND ISNULL(@UDNDocID_Import,'''')!=''''    
BEGIN    
DECLARE @SALES_UDFDocValue INT,@SALES_UDFDocPrefix NVARCHAR(255),@SALES_UDNID INT,@SALES_CHKCOUNT INT    
SELECT @SALES_UDFDocPrefix = LEFT(@UDNDocID_Import, PATINDEX(''%[A-Z][^A-Z]%'', @UDNDocID_Import)),    
@SALES_UDFDocValue = RIGHT(@UDNDocID_Import, LEN(@UDNDocID_Import) - (PATINDEX(''%[A-Z][^A-Z]%'', @UDNDocID_Import)))    
SET @SALES_CHKCOUNT = (SELECT COUNT(UDNId) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE DocPrefix = @SALES_UDFDocPrefix AND TransId = @TransID)    
SET @SALES_UDNID = (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE DocPrefix = @SALES_UDFDocPrefix AND TransId = @TransID)    
IF ISNULL(@SALES_CHKCOUNT,0)=0    
BEGIN    
INSERT INTO tblMasterUserDefineNoHeader (TransId,DocName,DocPrefix,DocValue,CBy,CDate) VALUES    
(@TransID,@SALES_UDFDocPrefix,@SALES_UDFDocPrefix,1,@UID,CONVERT(DATE,GETDATE()))    
SET @SALES_UDNID = SCOPE_IDENTITY()    
INSERT INTO tblMasterUserDefineNoDetail (UDNId,UserId) VALUES (@SALES_UDNID,@UID)    
END    
UPDATE tblMasterUserDefineNoHeader SET DocValue = @SALES_UDFDocValue WHERE UDNId = @SALES_UDNID    
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)    
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@SALES_UDNID    
SET @UDFId = @SALES_UDNID    
END    
END    
ELSE -- MODIFY    
BEGIN    

IF((@TempStatus != @nCurruntStaus) OR @TempStatus in (2,4))    
BEGIN    
RAISERROR (''Document status already changed'',16,1)    
END    
IF(@TempValue != @TempBalance)    
BEGIN    
RAISERROR (''Document partially adjusted'',16,1)    
END    
SELECT @DocValue=DocValue,@DocId = DocID,@UDFDocValue=UDFDocValue,@UDFDocId=UDFId,@CDUDFID=UDFId FROM tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE ID = @ID    
--SELECT * FROM tblNoteDetails WHERE IDENT = 671    
--SELECT @DocId=DocPrefix + CONVERT(NVARCHAR, @DocValue) FROM tblDocumentSeries WHERE TransID=@TransID    
IF ISNULL(@UDFId,0)>0    
BEGIN    
IF(@UDFId=@UDFDocId)    
BEGIN    
SELECT @UDFDocId=DocPrefix + CONVERT(NVARCHAR, @UDFDocValue),@UDFDocPrefix=DocPrefix FROM tblMastERUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId    
END    
IF(@UDFId!=@CDUDFID)    
BEGIN    
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMastERUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId    
UPDATE tblMastERUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@UDFId    
END    
END    
UPDATE tblNoteDetails SET Status = 2,MBy=@UID,MDate=GETDATE() WHERE ID = @ID    
UPDATE tblFAJournal SET Status = 2,MBy=@UID,MDate=GETDATE()WHERE TransId = @ID AND DocPrefix = @TransID    
END    
--- Credit not insert and update    
DECLARE @ActiveCheck INT    
DECLARE @ACTIVEACC INT    
IF @TransID=''4''    
BEGIN    
    
IF(@nMode = 1)    
BEGIN    
IF((SELECT COUNT(DocValue) FROM tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and    
DocDate BETWEEN @F_SD AND @F_ED and TransID = @TransID) != 0)-- and Status in (1,3,5)  
BEGIN    
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)     
END    
ENd    
  IF(@nMode = 2)    
BEGIN    
IF((SELECT COUNT(DocValue) FROM tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and    
DocDate not BETWEEN @F_SD AND @F_ED and TransID = @TransID) != 0)-- and Status in (1,3,5)  
BEGIN    
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)     
END    
ENd   
INSERT INTO tblNoteDetails(DocId,TransID,DocValue,DocDate,RefNo,PartyId,FAID,NoteValue,Balance,Remark,Narration,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy,[Status],CDate,Clby,Cldate,BranchID)    
VALUES (@DocID,@TransID,@DocValue,@DocDate,@DocRef,@PartyId,@AccountID, @Credit,@Credit,@Remarks,@Narration,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID,    
ISNULL(@Status,1),GETDATE(),    
case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,@BranchID)    
SET @SCOPID=(SELECT SCOPE_IDENTITY())    
--SELECT SCOPE_IDENTITY()    
--Posting    
SELECT @JVID=ISNULL(MAX(JVID),0)+1 FROM tblFAJournal WITH (READCOMMITTEDLOCK)    
INSERT INTO tblFAJournal    
(DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy,CDate,[Status],TransId,JVID,Clby,Cldate,Adjusment,BranchID)    
VALUES    
(@DocID,@TransID,@DocValue,@DocDate,@DocRef,@AccountID,@Debit,@Credit,@Credit,@Remarks,@Narration,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@JVID    
,case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,0,@BranchID)    
INSERT INTO tblFAJournal    
( DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy,CDate,[Status],TransId,JVID,Clby,Cldate,Adjusment,BranchID)    
VALUES    
(@DocID,@TransID,@DocValue,@DocDate,@DocRef,@PartyId,@Credit,@Debit,@Credit,@Remarks,@Narration,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@JVID    
,case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,0,@BranchID)    
print @DocValue+1 ----    
ENd    ELSE ---- DeBit not insert and update    
BEGIN    
    
--------------------    
IF(@nMode = 1)    
BEGIN    
IF((SELECT COUNT(DocValue) FROM tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and    
DocDate BETWEEN @F_SD AND @F_ED and TransID = @TransID) != 0)-- and Status in (1,3,5)  
BEGIN    
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)     
END    
ENd    
IF(@nMode = 2)    
BEGIN    
IF((SELECT COUNT(DocValue) FROM tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and    
DocDate not BETWEEN @F_SD AND @F_ED and TransID = @TransID) != 0)-- and Status in (1,3,5)  
BEGIN    
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)     
END    
ENd   
INSERT INTO tblNoteDetails(DocId,TransID,DocValue,DocDate,RefNo,PartyId,FAID,NoteValue,Balance,Remark,Narration,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy,[Status],CDate,Clby,Cldate,BranchID)    
VALUES (@DocID,@TransID,@DocValue,@DocDate,@DocRef,@PartyId,@AccountID, @Debit,@Debit,@Remarks,@Narration,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID,ISNULL(@Status,1),GETDATE()    
,case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,@BranchID)    
    
SET @SCOPID=( SELECT SCOPE_IDENTITY())    
--SELECT SCOPE_IDENTITY()    
SELECT @JVID=ISNULL(MAX(JVID),0)+1 FROM tblFAJournal WITH (READCOMMITTEDLOCK)    
    
INSERT INTO tblFAJournal    
( DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy,CDate,[Status],TransId,JVID,Clby,Cldate,Adjusment,BranchID)    
VALUES    
(@DocID,@TransID,@DocValue,@DocDate,@DocRef,@PartyId,@Credit,@Debit,@Debit,@Remarks,@Narration,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@JVID    
,case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,0,@BranchID)    
INSERT INTO tblFAJournal    
(DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy,CDate,[Status],TransId,JVID,Clby,Cldate,Adjusment,BranchID)    
VALUES    
(@DocID,@TransID,@DocValue,@DocDate,@DocRef,@AccountID,@Debit,@Credit,@Debit,@Remarks,@Narration,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@JVID    
,case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,0,@BranchID)    
ENd    
SELECT @SCOPID    
COMMIT TRAN    
--drop table #temp    
END TRy    
BEGIN CATCH    
ROLLBACK TRAN    
SELECT ERROR_MESSAGE () MSG,ERROR_PROCEDURE () [PROC],ERROR_LINE () LINE    
END CATCH',
N'[export] nocount;number-series-updlock=8;readcommittedlock=14';
GO
/****** uspManageCreditDebitNoteCancel ******/
EXEC #Apply07 N'dbo.uspManageCreditDebitNoteCancel', 0xB190709B957356C0592B7687FFB51EBC2853955BF0B102960F8089C1E846660A, NULL, NULL, 0x09EAB2BA041629C5B485E89958139B6F87E37D29742436A7FB148D4835F8636A, 0xAB1D11C08A407968D37A710692A67D1D954AE79C3387D958A0B45024AF4C0E6B, NULL,
N'ALTER PROCEDURE [dbo].[uspManageCreditDebitNoteCancel]                          
@DocPrefix INT,@IdentID INT,@UID INT,@Status INT,@Remarks NVARCHAR(255) = NULL,@Narration NVARCHAR(MAX) = NULL     
AS    
SET NOCOUNT ON;
BEGIN    
BEGIN TRY    
BEGIN TRANSACTION            
               
DECLARE @TempStatus INT, @TempValue DECIMAL (25,6), @TempBalance DECIMAL (25,6), @PartyAcc INT, @AccID INT ,@nStatus INT    
      
SET @nStatus = (SELECT Status FROM tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID)      
IF(@Status != @nStatus)      
BEGIN             
RAISERROR (''Document Status already Changed'',16,1);      
END          
SELECT @TempStatus = Status,@TempValue = NoteValue,@TempBalance = Balance,@PartyAcc=PartyId,@AccID=FAID FROM tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE ID = @IdentID                    
DECLARE @AccCount INT,@AccountName NVARCHAR(255)    
IF @TempStatus=4                    
BEGIN                    
 RAISERROR(''Note Already Cancelled'',16,1)                    
END                     
ELSE                    
BEGIN                    
IF @TempBalance=@TempValue                    
BEGIN                    
UPDATE tblNoteDetails SET [Status]= 4,ClBy=@UID,ClDate=GETDATE(),Remark = @Remarks,Narration = @Narration WHERE ID = @IdentID               
UPDATE tblFAJournal SET [Status]= 4,ClBy=@UID,ClDate=GETDATE(),Remarks = @Remarks,Narration = @Narration WHERE TransId=@IdentID AND DocPrefix=@DocPrefix          
END                     
ELSE                    
BEGIN                    
 RAISERROR(''Amount Mismatched'',16,1)                    
END                    
END                  
COMMIT TRANSACTION                      
END TRY                 
BEGIN CATCH                 
ROLLBACK TRANSACTION                   
SELECT ERROR_MESSAGE(),ERROR_MESSAGE(),ERROR_LINE()                    
END CATCH                    
END',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspManageCustomerLocationVerification ******/
EXEC #Apply07 N'dbo.uspManageCustomerLocationVerification', 0x589D4C1B7552E9DD6F592116FBD5CC359E5D40A2D67F8772845FC048FD65216A, NULL, NULL, 0x00806AEDAAD1CCB41B8150EA3D8E6D50264EC7A93F1994DC77475C65EC19FBF4, 0x405B25454408DBDC2CF61B8EE6293C915815D2B8559FF9112AFD711469EB2CB6, NULL,
N'--uspManageCustomerLocationVerification 1     
ALTER PROCEDURE [dbo].[uspManageCustomerLocationVerification]      
      
@ShowAll bit = 0      
AS       
SET NOCOUNT ON;
BEGIN      
  SELECT CLV.ID,MC.ID [CustomerID],CLV.Status [StatusID], MC.Latitude,MC.Longtitude, MC.Name[Customer],format(CLV.RequestTime,''dd-MMM-yyyy hh:mm tt'') [DateTime],U.UserName[User],      
CASE WHEN ISNULL(MC.Latitude,'''') != '''' AND  ISNULL(MC.Longtitude,'''') != ''''  THEN 1 ELSE 0     END AS [Location],     
Case When I.Filename IS NOT NULL Then 1 Else 0 End As [Images],      
Case   When CLV.Status = 1 Then ''Open''   When CLV.Status = 2 Then ''Approved''   ELSE ''Rejected'' ENd as [Status], CLV.Remarks,      
UI.UserName AS [ApprovedOrRejectedBy],  format(CLV.ApproveorRejectTime,''dd-MMM-yyyy hh:mm tt'') AS ApproveorRejectTime      
FROM tblCustomerLocVerifyTracking as CLV      
join tblMasterCustomer as MC on MC.ID = CLV.CustomerID      
JOIN tblUsers U on U.ID = CLV.RequestBy      
LEFT JOIN tblUsers UI on UI.ID = CLV.ApproveorRejectBy      
LEFT JOIN tblImages I on I.ID = MC.ID and FormID = 2      
WHERE  CLV.Status = (CASE WHEN @ShowAll = 1 then CLV.Status else  1 end )      
  --AND (ISNULL(MC.Latitude,'''') != '''' AND  ISNULL(MC.Longtitude,'''') != '''')    
    
END',
N'[export] nocount';
GO
/****** uspManageCustomerMaster ******/
EXEC #Apply07 N'dbo.uspManageCustomerMaster', 0xBAB012805AB82883231165EE36ED8392DF6327FB04C78C999C5A427E2F1A268D, NULL, NULL, 0x44F71DBE8FF9FDE628A5B0D9141514E3725F1CCD9928AE4B263CE31D23DE5F24, 0xC9FF660B69BEBCA41B1054C682EA4C100ACDD373DBFB376BB7D2AE5AF0FE38C1, NULL,
N'--[uspManageCustomerMaster] 12,22
ALTER proc [dbo].[uspManageCustomerMaster]                      
@Mode int,@ID int = null,@Code nvarchar(255) = null,@Name nvarchar(255) = null,@Billadd1 nvarchar(MAX) = null,@Billadd2 nvarchar(MAX) = null,                      
@Billadd3 nvarchar(MAX) = null,@Shipadd1 nvarchar(MAX) = null,@shipadd2 nvarchar(MAX) = null,@Shipadd3 nvarchar(MAX) = null,@Pincode nvarchar(15) = null,                      
@ContactPerson nvarchar(255) = null,@Ph1 nvarchar(25) = null,@Ph2 nvarchar(25) = null,@Mob1 nvarchar(25) = null,@Mob2 nvarchar(25) = null,@Email nvarchar(255) = null,                      
@PANNumber nvarchar(25) = null,@AadharNo nvarchar(25) = null,@DLNo20 nvarchar(25) = null,@DLNo21 nvarchar(25) = null,@FSSAINo nvarchar(30) = null,@StateID tinyint = null,                      
@GSTIN nvarchar(40) = null,@CreditTermID tinyint = null,@PaymentModeID tinyint = null,@TaxTypeID tinyint = null,                      
@FAID int = null,@OverDueValue decimal(25, 4) = null,@OverDueInvCount smallint = null,@CreditLimitValue decimal(25, 4) = null,@CreditLimitCount smallint = null,                      
@CreditlimitOS decimal(25, 4) = null,@PriceTypeID tinyint = null,@OwnerName nvarchar(255) = null,@DiscountPern decimal(25, 4) = null,@TrackPoint smallint = null,                      
@ClosingTrackPoint decimal(25, 4) = null,@TCSTax smallint = null,@Latitude nvarchar(25) = null,@Longtitude nvarchar(25) = null,@Distance smallint = null,                      
@Remark nvarchar(MAX) = null,@Active smallint = null,@UserID smallint = null,@CustomerType SMALLINT = null,@Rating TINYINT = NULL,  
@Shinecode nvarchar(50) = null,@RemoveLocation smallint = 0  
AS                      
SET NOCOUNT ON;
BEGIN                      
BEGIN TRY                      
DECLARE @ActiveCheck NVARCHAR(255), @SUNDRYDEBTORS INT ,@FATYPE INT,@AccID INT ,@ACCOUNTID INT,@CHECKID INT,@cstdate DATE,@ExistCount INT                      
SELECT @SUNDRYDEBTORS = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName=''Sundry Debtors''                      
IF(@Mode = 1)                      
BEGIN                      
IF((SELECT count(*) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Code = @Code) > 0)                      
BEGIN                      
RAISERROR(''Code'',16,1)                      
END                      
IF((SELECT count(*) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Name = @Name) > 0)                      
BEGIN                      
RAISERROR(''Name'',16,1)                      
END                      
--IF((SELECT count(*) FROM tblFAAccount WHERE AccountName = @Name) > 0)                      
--BEGIN                      
--RAISERROR(''Account Name Already Exists'',16,1)                      
--END                      
                      
IF ISNULL(@ph1,'''')!=''''                      
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @ph1 OR Ph2 = @ph1 OR Mob1 = @ph1 OR Mob2 = @ph1 )                      
IF( @ExistCount >0)                      
BEGIN                      
RAISERROR (''Phone No 1 already exists'',16,1)                      
END                      
END                      
IF ISNULL(@ph2,'''')!=''''                      
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @ph2 OR Ph2 = @ph2 OR Mob1 = @ph2 OR Mob2 = @ph2 )                      
IF( @ExistCount >0) BEGIN                      
RAISERROR (''Phone No 2 already exists'',16,1)                      
END                      
END                      
                      
IF ISNULL(@mob1,'''')!=''''                      
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @mob1 OR Ph2 = @mob1 OR Mob1 = @mob1 OR Mob2 = @mob1 )                      
IF( @ExistCount >0)                      
BEGIN                      
RAISERROR (''Mobile No 1 already exists'',16,1)                      
END                      
END                      
                      
IF ISNULL(@mob2,'''')!=''''                      
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @mob2 OR Ph2 = @mob2 OR Mob1 = @mob2 OR Mob2 = @mob2 )                      
IF( @ExistCount >0)     
BEGIN                      
RAISERROR (''Mobile No 2 already exists'',16,1)                      
END                      
END                 
IF ISNULL(@Shinecode,'''')!=''''                      
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Shinecode = @Shinecode)                      
IF( @ExistCount >0)                      
BEGIN                      
RAISERROR (''Shine code already exists'',16,1)                      
END                      
END                      
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@name              
IF(@ExistCount>0)                      
BEGIN                      
RAISERROR (''AccountName'',16,1)                      
END                      
set @Code =(select dbo.ProperCase(@Code)); set @Name = (select dbo.ProperCase(@Name));                      
set @ContactPerson =(select dbo.ProperCase(@ContactPerson)); set @OwnerName = (select dbo.ProperCase(@OwnerName));                      
set @Billadd1 =(select dbo.ProperCase(@Billadd1)); set @Shipadd1 = (select dbo.ProperCase(@Shipadd1));                      
set @Billadd2 =(select dbo.ProperCase(@Billadd2)); set @Shipadd2 = (select dbo.ProperCase(@Shipadd2));                      
set @Billadd3 =(select dbo.ProperCase(@Billadd3)); set @Shipadd3 = (select dbo.ProperCase(@Shipadd3));                      
set @Remark =(select dbo.ProperCase(@Remark));                      
                      
INSERT INTO tblFAAccount(AccountName,AccountGroup,OpeningBalance,FATypeID,CBy,CDate,UserAccount,PANNumber,Active)                      
VALUES(@name,@SUNDRYDEBTORS,0,1,@UserID,GETDATE(),0,@PANNumber,@Active)                      
SELECT @FAID = FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @Name                      
INSERT INTO tblMasterCustomer(Code,Name,Billadd1,Billadd2,Billadd3,Shipadd1,shipadd2,Shipadd3,Pincode,ContactPerson,Ph1,Ph2,Mob1,Mob2,                      
Email,PANNumber,AadharNo,DLNo20,DLNo21,FSSAINo,StateID,GSTIN,CreditTermID,PaymentModeID,TaxTypeID,FAID,OverDueValue,OverDueInvCount,                      
CreditLimitValue,CreditLimitCount,CreditlimitOS,PriceTypeID,OwnerName,DiscountPern,TrackPoint,ClosingTrackPoint,TCSTax,Latitude,                      
Longtitude,Distance,Remark,Active,CBy,CDate,CustomerType,Rating,Shinecode) VALUES                      
(@Code,@Name,@Billadd1,@Billadd2,@Billadd3,@Shipadd1,@shipadd2,@Shipadd3,@Pincode,@ContactPerson,@Ph1,@Ph2,@Mob1,@Mob2,                      
LOWER(@Email),@PANNumber,@AadharNo,@DLNo20,@DLNo21,@FSSAINo,@StateID,UPPER(@GSTIN),@CreditTermID,@PaymentModeID,@TaxTypeID,                      
@FAID,@OverDueValue,@OverDueInvCount,@CreditLimitValue,@CreditLimitCount,@CreditlimitOS,@PriceTypeID,@OwnerName,                      
@DiscountPern,@TrackPoint,0,@TCSTax,@Latitude,@Longtitude,@Distance,@Remark,@Active,@UserID,GETDATE(),@CustomerType,@Rating,@Shinecode)                      
SELECT SCOPE_IDENTITY()                      
END                      
IF(@Mode = 2)                      
BEGIN                      
select @ACCOUNTID = FAID from tblMasterCustomer WITH (READCOMMITTEDLOCK) where ID = @ID                      
IF((SELECT count(*) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Code = @Code AND ID != @ID) > 0)                      
BEGIN                      
RAISERROR(''Code'',16,1)                      
END                      
IF((SELECT count(*) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Name = @Name AND ID != @ID) > 0)                      
BEGIN                      
RAISERROR(''Name'',16,1)                      
END                      
IF ISNULL(@ph1,'''')!=''''                      
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @ph1 OR Ph2 = @ph1 OR Mob1 = @ph1 OR Mob2 = @ph1 ) AND Id != @ID                      
IF( @ExistCount >0)                      
BEGIN                      
RAISERROR (''Phone No 1 already exists'',16,1)                      
END                      END                      
IF ISNULL(@ph2,'''')!=''''                      
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @ph2 OR Ph2 = @ph2 OR Mob1 = @ph2 OR Mob2 = @ph2 ) AND Id != @ID                     
IF( @ExistCount >0)                      
BEGIN                      
RAISERROR (''Phone No 2 already exists'',16,1)                      
END                      
END                      
                      
IF ISNULL(@mob1,'''')!=''''               
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @mob1 OR Ph2 = @mob1 OR Mob1 = @mob1 OR Mob2 = @mob1 ) AND Id != @ID                      
IF( @ExistCount >0)                      
BEGIN                      
RAISERROR (''Mobile No 1 already exists'',16,1)                      
END                      
END                      
                      
IF ISNULL(@mob2,'''')!=''''                      
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @mob2 OR Ph2 = @mob2 OR Mob1 = @mob2 OR Mob2 = @mob2 ) AND Id != @ID                      
IF( @ExistCount >0)                      
BEGIN                      
RAISERROR (''Mobile No 2 already exists'',16,1)                      
END                      
END                      
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@name and FAID != @ACCOUNTID                      
IF(@ExistCount>0)                      
BEGIN                      
RAISERROR (''AccountName'',16,1)                      
END                      
IF @active=0                      
BEGIN                      
DECLARE @ReturnValue DECIMAL(25,4)                      
EXEC uspGetClosingBal @ACCOUNTID,@ReturnValue OUTPUT                      
IF( @ReturnValue !=0)          BEGIN                      
RAISERROR (''OSPending'',16,1)                      
END                      
END                      
IF ISNULL(@Shinecode,'''')!=''''                      
BEGIN                      
SELECT @ExistCount=COUNT(Id) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE (Shinecode = @Shinecode AND ID != @ID)                      
IF( @ExistCount >0)                      
BEGIN                      
RAISERROR (''Shine code already exists'',16,1)                      
END                      
END                      
--IF((SELECT count(*) FROM tblFAAccount WHERE AccountName = @Name AND FAID != @FAID) > 0)                      
--BEGIN                      
--RAISERROR(''Account Name Already Exists'',16,1)                      
--END --Previous ID data Posting in History table                      
insert into tblMasterCustomerVendorHistory (FormID,ID,Code,Name,Billadd1,Billadd2,Billadd3,Shipadd1,shipadd2,Shipadd3,Pincode,                      
ContactPerson,Ph1,Ph2,Mob1,Mob2,Email,PANNumber,AadharNo,DLNo20,DLNo21,FSSAINo,StateID,GSTIN,CreditTermID,PaymentModeID,                      
TaxTypeID,OSValue,FAID,OverDueValue,OverDueInvCount,CreditLimitValue,CreditLimitCount,CreditlimitOS,PriceTypeWeekCycle,                      
OwnerName,DiscountPern,TrackPoint,ClosingTrackPoint,TCSTax,Latitude,Longtitude,Distance,Remark,CustomerType,Rating,                      
Active,CBy,CDate,MBy,MDate,HisCBy,HisCDate,Shinecode)                      
select 26,ID,Code,Name,Billadd1,Billadd2,Billadd3,Shipadd1,shipadd2,Shipadd3,Pincode,ContactPerson,Ph1,Ph2,Mob1,Mob2,Email,PANNumber,                      
AadharNo,DLNo20,DLNo21,FSSAINo,StateID,GSTIN,CreditTermID,PaymentModeID,TaxTypeID,OSValue,FAID,OverDueValue,OverDueInvCount,                      
CreditLimitValue,CreditLimitCount,CreditlimitOS,PriceTypeID,OwnerName,DiscountPern,TrackPoint,ClosingTrackPoint,TCSTax,                      
Latitude,Longtitude,Distance,Remark,CustomerType,Rating,Active,CBy,CDate,MBy,MDate,@UserID,GETDATE(),Shinecode from tblMasterCustomer WITH (READCOMMITTEDLOCK) where ID = @ID                      
                      
set @Code =(select dbo.ProperCase(@Code))                      
set @Name = (select dbo.ProperCase(@Name))                      
set @ContactPerson =(select dbo.ProperCase(@ContactPerson)); set @OwnerName = (select dbo.ProperCase(@OwnerName));                      
set @Billadd1 =(select dbo.ProperCase(@Billadd1)); set @Shipadd1 = (select dbo.ProperCase(@Shipadd1));                      
set @Billadd2 =(select dbo.ProperCase(@Billadd2)); set @Shipadd2 = (select dbo.ProperCase(@Shipadd2));                      
set @Billadd3 =(select dbo.ProperCase(@Billadd3)); set @Shipadd3 = (select dbo.ProperCase(@Shipadd3));                      
set @Remark =(select dbo.ProperCase(@Remark));                      
                      
UPDATE tblFAAccount                      
SET AccountName=@Name,AccountGroup=@SUNDRYDEBTORS,MBy=@UserID,MDate=GETDATE(),UserAccount=0,PANNumber=@PANNumber,Active = @Active                      
WHERE FAID=@ACCOUNTID                      
                      
UPDATE tblMasterCustomer SET Code = @Code,Name = @Name,Billadd1 = @Billadd1,Billadd2 = @Billadd2,Billadd3 = @Billadd3,Shipadd1 = @Shipadd1,shipadd2 = @shipadd2,                      
Shipadd3 = @Shipadd3,Pincode = @Pincode,ContactPerson = @ContactPerson,Ph1 = @Ph1,Ph2 = @Ph2,Mob1 = @Mob1,Mob2 = @Mob2,Email = LOWER(@Email),PANNumber = @PANNumber,                      
AadharNo = @AadharNo,DLNo20 = @DLNo20,DLNo21 = @DLNo21,FSSAINo = @FSSAINo,StateID = @StateID,GSTIN = UPPER(@GSTIN),CreditTermID = @CreditTermID,                      
PaymentModeID = @PaymentModeID,TaxTypeID = @TaxTypeID ,OverDueValue = @OverDueValue,OverDueInvCount = @OverDueInvCount,                      
CreditLimitValue = @CreditLimitValue,CreditLimitCount = @CreditLimitCount,CreditlimitOS = @CreditlimitOS,PriceTypeID = @PriceTypeID,OwnerName = @OwnerName,                      
DiscountPern = @DiscountPern,TrackPoint = @TrackPoint,TCSTax = @TCSTax,--Latitude = @Latitude,Longtitude = @Longtitude,                      
Distance = @Distance,Remark = @Remark,Active = @Active,MBy = @UserID,MDate = GETDATE(),CustomerType = @CustomerType,                      
Rating = @Rating,Shinecode = @Shinecode WHERE ID=@ID                      
  
IF(@RemoveLocation = 1)  
BEGIN  
UPDATE tblMasterCustomer SET Latitude = NULL,Longtitude = NULL,MobilePinAddress = NULL WHERE  ID=@ID      
END  
  
SELECT @ID                      
END                      
IF(@Mode = 3)                      
BEGIN                      
if(isnull(@Billadd1,1) = 0)                      
begin                      
delete from tblBeatSalesmanMapping where CustomerID = @ID                      
end                      
declare @BeatID smallint = (select ID from tblMasterBeat WITH (READCOMMITTEDLOCK) where Name = @Code)                      
declare @SMID smallint = (select ID from tblMasterSalesman WITH (READCOMMITTEDLOCK) where Name = @Name)                      
INSERT INTO tblBeatSalesmanMapping VALUES (@ID,@BeatID,@SMID)                      
END                      
IF(@Mode = 4)                      
BEGIN                      
SELECT TC.ID,TC.Code,TC.Name,MCT.Name CustomerType,PT.PriceType,TC.OwnerName,                      
TC.ContactPerson,TC.Email,TC.Ph1,Tc.Ph2,TC.Mob1 Mob1,TC.Mob2,                      
TC.Billadd1,TC.Billadd2,Tc.Billadd3,TC.Shipadd1,TC.Shipadd2,TC.Shipadd3,TC.Pincode,TC.Distance,                      
TC.CreditLimitValue,dbo.fnGetRoundedValue(TC.CreditLimitCount)CreditLimitCount,dbo.fnGetRoundedValue(TC.OverDueValue)OverDueValue,TC.OverDueInvCount,TC.PANNumber,TC.AadharNo,TC.FSSAINo,TC.DLNo20,TC.DLNo21,                      
SNTC.StateName,TC.GSTIN,MTT.TaxTypeName,PM.PaymentMode,MTCT.Name,dbo.fnGetRoundedValue(TC.DiscountPern)DiscountPern,TC.Remark,RT.RatingName Ratings,TC.TCSTax,TC.TrackPoint,                      
CASE WHEN TC.Active = 1 THEN ''Yes'' ELSE ''No'' END Active,CASE WHEN ISNULL(TC.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END CBy,                      
CASE WHEN ISNULL(TC.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),TC.CDate) ELSE CONVERT(NVARCHAR(100),TC.MDate) END CDate,                      
TC.Latitude,TC.Longtitude,Shinecode,(CASE WHEN IMG.Filename is null then 0 else 1 end) Imagestate         
,(CASE WHEN isnull(TC.Latitude,'''') = '''' or isnull(TC.Longtitude,'''') = '''' then ''No'' else ''Yes'' end) Location,        
(CASE WHEN IMG.Filename is null then ''No'' else ''Yes'' end) Images        
FROM tblMasterCustomer TC WITH (READCOMMITTEDLOCK)                      
LEFT JOIN tblMasterCustomerType MCT WITH (READCOMMITTEDLOCK) ON MCT.ID = TC.CustomerType                      
LEFT JOIN tblPriceType PT WITH (READCOMMITTEDLOCK) ON PT.ID = TC.PriceTypeID                      
LEFT JOIN tblGSTStateNameandCode SNTC WITH (READCOMMITTEDLOCK) ON SNTC.StateID = TC.StateID                      
LEFT JOIN tblMasterTaxType MTT WITH (READCOMMITTEDLOCK) ON MTT.TaxTypeID = TC.TaxTypeID                      
LEFT JOIN tblPaymentMode PM WITH (READCOMMITTEDLOCK) ON PM.ID = TC.PaymentModeID                      
LEFT JOIN tblMasterCreditTerm MTCT WITH (READCOMMITTEDLOCK) ON MTCT.ID = TC.CreditTermID                      
LEFT JOIN tblRatings RT WITH (READCOMMITTEDLOCK) ON RT.ID = TC.Rating                      
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = TC.CBy                      
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = TC.MBy                      
left join tblImages IMG WITH (READCOMMITTEDLOCK) ON IMG.ID = TC.ID AND IMG.FormID = 2                  
ORDER BY TC.Name                      
END                      
IF(@Mode = 5)                      
BEGIN                      
DECLARE @OSVAL DECIMAL(25,4),@FAI INT, @OSCOUNT INT                      
SELECT @FAI = FAID FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE ID = @ID                      
EXEC uspGetClosingBal @FAI,@ReturnValue OUTPUT                      
                      
SELECT @OSCOUNT = COUNT(ID), @OSVAL= SUM(Balance) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE CustID = @ID AND Status IN (1,3) AND Balance > 0                      
SELECT *,@ReturnValue OSVAL,@OSCOUNT OSCOUNT,Billadd1 MobilePinAddress from tblMasterCustomer TC WITH (READCOMMITTEDLOCK)              
WHERE TC.ID = @ID                      
END                      
IF(@Mode = 6)                      
BEGIN                      
DECLARE @PT AS TABLE(ID SMALLINT)                      
IF(@ID = 1 OR @ID = 2)                      
BEGIN                      
INSERT INTO @PT                      
SELECT ID FROM tblPriceType WITH (READCOMMITTEDLOCK)                      
END                      
ELSE                      
BEGIN                      
INSERT INTO @PT                      
SELECT ID FROM tblPriceType WITH (READCOMMITTEDLOCK) WHERE ID NOT IN (1,6)                      
END                      
select 1 FType,''Price Type'' Form,ID,PriceType Descriptions from tblPriceType WITH (READCOMMITTEDLOCK) WHERE Active = 1 and id IN (SELECT * FROM @PT)                      
union                      
select 2 FType,''Tax Type'' Form,TaxTypeID,TaxTypeName Descriptions from tblMasterTaxType WITH (READCOMMITTEDLOCK) WHERE Active = 1                      
union                      
select 3 FType,''Payment Mode'' Form,ID,PaymentMode Descriptions from tblPaymentMode WITH (READCOMMITTEDLOCK) WHERE Active = 1                      
union                      
select 4 FType,''Credit Term'' Form,ID,Name Descriptions from tblMasterCreditTerm WITH (READCOMMITTEDLOCK) WHERE Active = 1                      
union                      
select 5 FType,''State Names'' Form,StateID,CONVERT(NVARCHAR,TINNO)+'' - ''+ StateName Descriptions from tblGSTStateNameandCode WITH (READCOMMITTEDLOCK) WHERE Active = 1                      
union                      
select 6 FType,''Rating'' Form,ID,RatingName Descriptions from tblRatings WITH (READCOMMITTEDLOCK) WHERE Active = 1                      
union                      
select 7 FType,''Customer Type'' Form,ID,Name Descriptions from tblMasterCustomerType WITH (READCOMMITTEDLOCK) WHERE Active = 1                      
union                      
select 8 FType,''Beat'' Form,ID,Name from tblMasterBeat WITH (READCOMMITTEDLOCK) where Active = 1                      
union                      
select 9 FType,''Salesman'' Form,ID,Name from tblMasterSalesman WITH (READCOMMITTEDLOCK) where Active = 1                      
order by FType,Descriptions                      
END                      
IF(@Mode = 7)                      
BEGIN                      
select BSM.CustomerID,MB.Name Beat,SM.Name Salesman from tblBeatSalesmanMapping BSM WITH (READCOMMITTEDLOCK)                      
JOIN tblMasterBeat MB WITH (READCOMMITTEDLOCK) ON MB.ID = BSM.BeatID JOIN tblMasterSalesman SM WITH (READCOMMITTEDLOCK) ON SM.ID = BSM.SalesmanID                      
where CustomerID = @ID                      
ENd                      
IF(@Mode = 8)                      
BEGIN                      
if(isnull(@Name,1) = 0)                      
begin                      
delete from tblMasterCustomerRemarks where CustomerID = @ID                      
end                      
set @Code =(select dbo.ProperCase(@Code))                      
INSERT INTO tblMasterCustomerRemarks VALUES (@ID,@Code)                      
END                      
IF(@Mode = 9)                      
BEGIN                      
SELECT * FROM tblMasterCustomerRemarks WITH (READCOMMITTEDLOCK) WHERE CustomerID = @ID                      
END                      
IF(@Mode = 10)                    
BEGIN                    
SELECT * FROM tblImages WITH (READCOMMITTEDLOCK) WHERE FormID = 2 and ID = @ID                     
END                    
IF(@Mode = 11)                    
BEGIN                    
SELECT * FROM tblImages WITH (READCOMMITTEDLOCK) WHERE FormID = 2                  
end        
IF(@Mode = 12)                
BEGIN                
declare @TRBeatID INT,@TRSMID INT,@uRoleID INT = 0    
    
select @TRBeatID = ISNULL(BeatID,0),@TRSMID = ISNULL(SalesmanID,0),@uRoleID = isnull(RoleID,0) from tblUsers WITH (READCOMMITTEDLOCK) WHERE ID = @ID                   
    
DECLARE @MobShowAllCustomers int = (select COUNT(1) from tblRolePermissions WITH (READCOMMITTEDLOCK) where Role = @uRoleID and PermissionFormId = 567)    
    
declare @Query NVARCHAR(MAX)     
    
SET @Query = '' SELECT TC.ID,TC.Code,TC.Name,MCT.Name CustomerType,PT.PriceType,TC.OwnerName,                      
TC.ContactPerson,TC.Email,TC.Ph1,Tc.Ph2,TC.Mob1 Mob1,TC.Mob2,                      
TC.Billadd1,TC.Billadd2,Tc.Billadd3,TC.Shipadd1,TC.Shipadd2,TC.Shipadd3,TC.Pincode,TC.Distance,                      
TC.CreditLimitValue,dbo.fnGetRoundedValue(TC.CreditLimitCount)CreditLimitCount,dbo.fnGetRoundedValue(TC.OverDueValue)OverDueValue,    
TC.OverDueInvCount,TC.PANNumber,TC.AadharNo,TC.FSSAINo,TC.DLNo20,TC.DLNo21,SNTC.StateName,TC.GSTIN,MTT.TaxTypeName,PM.PaymentMode,MTCT.Name,    
dbo.fnGetRoundedValue(TC.DiscountPern)DiscountPern,TC.Remark,RT.RatingName Ratings,TC.TCSTax,TC.TrackPoint,                      
CASE WHEN TC.Active = 1 THEN ''''Yes'''' ELSE ''''No'''' END Active,CASE WHEN ISNULL(TC.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END CBy,                      
CASE WHEN ISNULL(TC.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),TC.CDate) ELSE CONVERT(NVARCHAR(100),TC.MDate) END CDate,                      
TC.Latitude,TC.Longtitude,Shinecode,(CASE WHEN IMG.Filename is null then 0 else 1 end) Imagestate                  
FROM tblMasterCustomer TC                      
LEFT JOIN tblMasterCustomerType MCT ON MCT.ID = TC.CustomerType                      
LEFT JOIN tblPriceType PT ON PT.ID = TC.PriceTypeID                      
LEFT JOIN tblGSTStateNameandCode SNTC ON SNTC.StateID = TC.StateID                      
LEFT JOIN tblMasterTaxType MTT ON MTT.TaxTypeID = TC.TaxTypeID                      
LEFT JOIN tblPaymentMode PM ON PM.ID = TC.PaymentModeID                      
LEFT JOIN tblMasterCreditTerm MTCT ON MTCT.ID = TC.CreditTermID                      
LEFT JOIN tblRatings RT ON RT.ID = TC.Rating                      
JOIN tblUsers CUR ON CUR.ID = TC.CBy                      
LEFT JOIN tblUsers MUR ON MUR.ID = TC.MBy                      
left join tblImages IMG ON IMG.ID = TC.ID AND IMG.FormID = 2                  
LEFT JOIN tblBeatSalesmanMapping BSM ON BSM.CustomerID = TC.ID                
WHERE TC.Active = 1 ''--AND BSM.BeatID = ''+CONVERT(nvarchar(20),@TRBeatID) + '' AND BSM.SalesmanID = ''+CONVERT(nvarchar(20),@TRSMID)
SET @Query += CASE WHEN @MobShowAllCustomers = 1 THEN     
(CASE WHEN @TRBeatID = 0 THEN '''' ELSE '' AND BSM.BeatID =  ''+CONVERT(nvarchar(20),@TRBeatID) END)    
ELSE '' AND BSM.BeatID =  ''+CONVERT(nvarchar(20),@TRBeatID) END    
SET @Query += CASE WHEN @MobShowAllCustomers = 1 THEN     
(CASE WHEN @TRSMID = 0 THEN '''' ELSE '' AND BSM.SalesmanID =  ''+CONVERT(nvarchar(20),@TRSMID) END)    
ELSE '' AND BSM.SalesmanID =  ''+CONVERT(nvarchar(20),@TRSMID) END
SET @Query += CASE WHEN @Code = 0 THEN '' AND (isnull(TC.Latitude,'''''''') != '''''''' and isnull(TC.Longtitude,'''''''') != '''''''' )''     
ELSE '''' END    
SET @Query += '' ORDER BY TC.Name   ''    
PRINT @Query
EXEC(@Query)    
    
              
END                
END TRY                      
BEGIN CATCH                      
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(), ERROR_LINE()                      
END CATCH                      
END',
N'[export] nocount;readcommittedlock=55';
GO
/****** uspManageCustomerMasterImport ******/
EXEC #Apply07 N'dbo.uspManageCustomerMasterImport', 0xDBA9A13D6788551001184AC4440E006CBB5713490A76E0F667E39B22C01629E9, NULL, NULL, 0x37787BD08A956661442518C894196EE871EF9FF375055915208E228F6D5C4320, 0x4C1A148188C0C1A00120BEEAEAF3E21DC37498D5A3D30C112B83D5886B1CD236, NULL,
N'ALTER proc [dbo].[uspManageCustomerMasterImport]  
@Code nvarchar(255),@Name nvarchar(255),@Billadd1 nvarchar(MAX) = null,@Billadd2 nvarchar(MAX) = null,                
@Billadd3 nvarchar(MAX) = null,@Shipadd1 nvarchar(MAX) = null,@shipadd2 nvarchar(MAX) = null,@Shipadd3 nvarchar(MAX) = null,@Pincode nvarchar(15) = null,                
@ContactPerson nvarchar(255) = null,@Ph1 nvarchar(255) = null,@Ph2 nvarchar(25) = null,@Mob1 nvarchar(25) = null,@Mob2 nvarchar(25) = null,@Email nvarchar(255) = null,                
@PANNumber nvarchar(25) = null,@AadharNo nvarchar(25) = null,@DLNo20 nvarchar(25) = null,@DLNo21 nvarchar(25) = null,@FSSAINo nvarchar(30) = null,@State nvarchar(255) = null,                
@GSTIN nvarchar(40) = null,@CreditTerm  nvarchar(255) = null,@PaymentMode nvarchar(255) = null,@TaxType nvarchar(255) = null,                
@OverDueValue decimal(25, 4) = null,@OverDueInvCount nvarchar(255) = null,@CreditLimitValue decimal(25, 4) = null,@CreditLimitCount nvarchar(255) = null,                
@CreditlimitOS decimal(25, 4) = null,@PriceType nvarchar(255) = null,@OwnerName nvarchar(255) = null,@DiscountPern decimal(25, 4) = null,@TrackPoint nvarchar(255) = null,                
@ClosingTrackPoint decimal(25, 4) = null,@TCSTax nvarchar(255) = null,@Latitude nvarchar(25) = null,@Longtitude nvarchar(25) = null,@Distance nvarchar(255) = null,                
@Remark nvarchar(MAX) = null,@Active nvarchar(255) = null,@UserID nvarchar(255) = null,@strCustomerType nvarchar(255) = null,@strRating nvarchar(255) = NULL    
AS                
SET NOCOUNT ON;
BEGIN                
BEGIN TRY                
DECLARE @ActiveCheck NVARCHAR(255), @SUNDRYDEBTORS INT ,@FATYPE INT,@AccID INT ,@ACCOUNTID INT,@CHECKID INT,@ExistCount INT,  
@CodeID int,@NameID int,@CustomerID INT,@FAID int  
  
DECLARE @StateID nvarchar(255) = null,@CreditTermID  nvarchar(255) = null,@PaymentModeID nvarchar(255) = null,@TaxTypeID nvarchar(255) = null,  
@PriceTypeID nvarchar(255) = null,@CustomerType nvarchar(255) = null,@Rating nvarchar(255)  
  
SELECT @SUNDRYDEBTORS = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName=''Sundry Debtors''       
SELECT @CodeID=ISNULL(ID,0) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE code=@Code     
SELECT @NameID=ISNULL(ID,0) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Name=@Name     
  
SET @CustomerID = (CASE WHEN ISNULL(@CodeID,0) = 0 THEN ISNULL(@NameID,0) ELSE ISNULL(@CodeID,0) END)  
  
declare @ErrorMsg nvarchar(max) = '''';  
SET @StateID = (SELECT StateID FROM tblGSTStateNameandCode WITH (READCOMMITTEDLOCK) WHERE StateName = @State)  
IF(@StateID = 0 and isnull(@State,'''') != '''')                
BEGIN                       
set @ErrorMsg += ''Invalid State Name\n'';  
END    
SET @CreditTermID = (SELECT ID FROM tblMasterCreditTerm WITH (READCOMMITTEDLOCK) WHERE Name = @CreditTerm)  
IF(@CreditTermID = 0 and isnull(@CreditTerm,'''') != '''')                
BEGIN                   
set @ErrorMsg += ''Invalid CreditTerm\n'';  
END   
SET @PaymentModeID = (SELECT ID FROM tblPaymentMode WITH (READCOMMITTEDLOCK) WHERE PaymentMode = @PaymentMode)  
IF(@PaymentModeID = 0 and isnull(@PaymentMode,'''') != '''')                
BEGIN                    
set @ErrorMsg += ''Invalid Payment Mode\n'';  
END   
SET @TaxTypeID = (SELECT TaxTypeID FROM tblMasterTaxType WITH (READCOMMITTEDLOCK) WHERE TaxTypeName = @TaxType)  
IF(@TaxTypeID = 0 and isnull(@TaxType,'''') != '''')                
BEGIN                
set @ErrorMsg += ''Invalid Tax Type\n'';  
END   
SET @PriceTypeID = (SELECT ID FROM tblPriceType WITH (READCOMMITTEDLOCK) WHERE PriceType = @PriceType)  
IF(@PriceTypeID = 0 and isnull(@PriceType,'''') != '''')                
BEGIN                 
set @ErrorMsg += ''Invalid Price Type\n'';  
END   
SET @Rating = (SELECT ID FROM tblRatings WITH (READCOMMITTEDLOCK) WHERE RatingName = @strRating)  
IF(@Rating = 0 and isnull(@strRating,'''') != '''')                
BEGIN                  
set @ErrorMsg += ''Invalid Rating\n'';  
END   
  
  
IF(@CustomerID = 0)--NEW  
BEGIN  
IF((SELECT count(*) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Code = @Code) > 0)                
BEGIN                
set @ErrorMsg += ''Code Already Exists\n'';               
END                
IF((SELECT count(*) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Name = @Name) > 0)                
BEGIN                             
set @ErrorMsg += ''Name Already Exists\n'';  
END    
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@name                
IF(@ExistCount>0)                
BEGIN                 
set @ErrorMsg += ''Account Name Already Exists\n'';  
END   
SET @CustomerType = (SELECT ID FROM tblMasterCustomerType WITH (READCOMMITTEDLOCK) WHERE name = @STRCustomerType)  
IF(@CustomerType = 0 and isnull(@STRCustomerType,'''') != '''')    -- CREATE CUST TYPE IF NO REC            
BEGIN                
insert into tblMasterCustomerType (Name,Active,CBy,CDate) VALUES (@STRCustomerType,1,@UserID,GETDATE())  
SELECT @CustomerType = ID FROM tblMasterCustomerType WITH (READCOMMITTEDLOCK) WHERE Name = @strCustomerType  
END   
  
  
IF(@ErrorMsg != '''')  
BEGIN  
RAISERROR(@ErrorMsg,16,1)       
END  
  
set @Code = (select dbo.ProperCase(@Code))                
set @Name = (select dbo.ProperCase(@Name))    
  
INSERT INTO tblFAAccount(AccountName,AccountGroup,OpeningBalance,FATypeID,CBy,CDate,UserAccount,PANNumber,Active)                
VALUES(@name,@SUNDRYDEBTORS,0,1,@UserID,GETDATE(),0,@PANNumber,@Active)                
SELECT @FAID = FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @Name   
  
INSERT INTO tblMasterCustomer(Code,Name,Billadd1,Billadd2,Billadd3,Shipadd1,shipadd2,Shipadd3,Pincode,ContactPerson,Ph1,Ph2,Mob1,Mob2,Email,PANNumber,AadharNo,                
DLNo20,DLNo21,FSSAINo,StateID,GSTIN,CreditTermID,PaymentModeID,TaxTypeID,FAID,OverDueValue,OverDueInvCount,CreditLimitValue,CreditLimitCount,CreditlimitOS,                
PriceTypeID,OwnerName,DiscountPern,TrackPoint,ClosingTrackPoint,TCSTax,Latitude,Longtitude,Distance,Remark,Active,CBy,CDate,CustomerType,Rating) VALUES                
(@Code,@Name,@Billadd1,@Billadd2,@Billadd3,@Shipadd1,@shipadd2,@Shipadd3,@Pincode,@ContactPerson,@Ph1,@Ph2,@Mob1,@Mob2,@Email,@PANNumber,@AadharNo,@DLNo20,@DLNo21,@FSSAINo,                
@StateID,@GSTIN,@CreditTermID,@PaymentModeID,@TaxTypeID,@FAID,@OverDueValue,@OverDueInvCount,@CreditLimitValue,@CreditLimitCount,@CreditlimitOS,                
@PriceTypeID,@OwnerName,@DiscountPern,@TrackPoint,@ClosingTrackPoint,@TCSTax,@Latitude,@Longtitude,@Distance,@Remark,@Active,@UserID,GETDATE(),@CustomerType,@Rating)      
SELECT SCOPE_IDENTITY(),''Insert''    
  
END  
ELSE--UPDATE  
BEGIN  
select @ACCOUNTID = FAID from tblMasterCustomer WITH (READCOMMITTEDLOCK) where ID = @CustomerID          
  
IF((SELECT count(*) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Code = @Code AND ID != @CustomerID) > 0)                
BEGIN                
set @ErrorMsg += ''Code Already Exists\n'';               
END                
IF((SELECT count(*) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Name = @Name AND ID != @CustomerID) > 0)                
BEGIN                             
set @ErrorMsg += ''Name Already Exists\n'';  
END    
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@name and FAID != @ACCOUNTID                
IF(@ExistCount>0)                
BEGIN                 
set @ErrorMsg += ''Account Name Already Exists\n'';  
END   
SET @CustomerType = (SELECT ID FROM tblMasterCustomerType WITH (READCOMMITTEDLOCK) WHERE name = @STRCustomerType)  
IF(@CustomerType = 0 and isnull(@STRCustomerType,'''') != '''')    -- CREATE CUST TYPE IF NO REC            
BEGIN                
insert into tblMasterCustomerType (Name,Active,CBy,CDate) VALUES (@STRCustomerType,1,@UserID,GETDATE())  
SELECT @CustomerType = ID FROM tblMasterCustomerType WITH (READCOMMITTEDLOCK) WHERE Name = @strCustomerType  
END   
  
  
IF @active=''0''                                              
BEGIN                                              
DECLARE @ReturnValue DECIMAL(25,4)                                              
EXEC uspGetClosingBal @ACCOUNTID,@ReturnValue OUTPUT                                              
IF( @ReturnValue !=0)                                              
BEGIN                                              
set @ErrorMsg += ''Cannot De-activate. Outstandings Pending\n'';  
END                                      
END     
  
IF(@ErrorMsg != '''')  
BEGIN  
RAISERROR(@ErrorMsg,16,1)       
END  
    
set @Code =(select dbo.ProperCase(@Code))                
set @Name = (select dbo.ProperCase(@Name))                
                
UPDATE tblFAAccount                
SET AccountName=@Name,AccountGroup=@SUNDRYDEBTORS,MBy=@UserID,MDate=GETDATE(),UserAccount=0,PANNumber=@PANNumber,Active = @Active                
WHERE FAID=@ACCOUNTID                
                
UPDATE tblMasterCustomer SET Code = @Code,Name = @Name,Billadd1 = @Billadd1,Billadd2 = @Billadd2,Billadd3 = @Billadd3,Shipadd1 = @Shipadd1,shipadd2 = @shipadd2,                
Shipadd3 = @Shipadd3,Pincode = @Pincode,ContactPerson = @ContactPerson,Ph1 = @Ph1,Ph2 = @Ph2,Mob1 = @Mob1,Mob2 = @Mob2,Email = @Email,PANNumber = @PANNumber,                
AadharNo = @AadharNo,DLNo20 = @DLNo20,DLNo21 = @DLNo21,FSSAINo = @FSSAINo,StateID = @StateID,GSTIN = @GSTIN,CreditTermID = @CreditTermID,                
PaymentModeID = @PaymentModeID,TaxTypeID = @TaxTypeID ,OverDueValue = @OverDueValue,OverDueInvCount = @OverDueInvCount,                
CreditLimitValue = @CreditLimitValue,CreditLimitCount = @CreditLimitCount,CreditlimitOS = @CreditlimitOS,PriceTypeID = @PriceTypeID,OwnerName = @OwnerName,                
DiscountPern = @DiscountPern,TrackPoint = @TrackPoint,ClosingTrackPoint = @ClosingTrackPoint,TCSTax = @TCSTax,Latitude = @Latitude,Longtitude = @Longtitude,                
Distance = @Distance,Remark = @Remark,Active = @Active,MBy = @UserID,MDate = GETDATE(),CustomerType = @CustomerType,Rating = @Rating   
WHERE ID=@CustomerID                
SELECT @CustomerID,''Update''  
ENd  
END TRY                
BEGIN CATCH                
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(), ERROR_LINE()                
END CATCH                
END',
N'[export] nocount;readcommittedlock=21';
GO
/****** uspManageCustomizeReport ******/
EXEC #Apply07 N'dbo.uspManageCustomizeReport', 0x08CF437509A07AB4DBB928C6C6102BF72C78CDB4236D92BE18C02218591FC5C6, NULL, NULL, 0xD7BB11A8EAFBF11BD057278B4E71E4EC16CE6FF94C57E8E778549EEFCFDF55BE, 0xCE6411F3F292FD0A6B9D92A82116A65AED2A93744A266A324B81CF8A57BC5D5A, NULL,
N'ALTER proc [dbo].[uspManageCustomizeReport]  
@Mode int,@ID int = 1,@ALName NVARCHAR(255) = NULL  
as  
SET NOCOUNT ON;
begin  
if(@Mode = 1)  
BEGIN  
if(@ID = 1)  
BEGIN  
select ReportID ID,ReportName Name from tblCustomizeReportNames  
order by ReportName  
END  
ELSE  
BEGIN  
select ReportID ID,ReportName Name from tblCustomizeReportNames CRN  
JOIN tblRolePermissions MN ON MN.PermissionFormId = CRN.MenuID  
where Role = @ID AND CRN.Active = 1  
order by ReportName  
END  
END  
ELSE IF(@Mode = 2)  
BEGIN  
SELECT * FROM tblCustomizeReportParameterInfo WHERE ReportID = @ID order by ParamOrder  
END  
ELSE IF(@Mode = 3)  
BEGIN  
SELECT * FROM tblCustomizeReportNames WHERE ReportID = @ID  
END  
ELSE IF(@Mode = 4)  
BEGIN  
IF(@ALName = ''ProductName'')  
BEGIN  
SELECT ID,Name FROM tblMasterProduct ORDER BY Name  
END  
IF(@ALName = ''ManufName'')  
BEGIN   
SELECT ID,Name FROM tblMasterManufacturer ORDER BY Name  
END  
IF(@ALName = ''BrandName'')  
BEGIN  
SELECT ID,Name FROM tblMasterBrand ORDER BY Name  
END  
IF(@ALName = ''CategoryName'')  
BEGIN  
SELECT ID,Name FROM tblMasterCategory ORDER BY Name  
END  
IF(@ALName = ''BranchName'')  
BEGIN  
SELECT ID,Name Name FROM tblMasterBranchOffice ORDER BY Name  
END  
END  
end',
N'[export] nocount';
GO
/****** uspManageDelivery ******/
EXEC #Apply07 N'dbo.uspManageDelivery', 0xBC098E2FF7D4F0A300F5524936256371B2FB740FDB3435D18062435BD4E1083C, NULL, NULL, 0x5D12C8E4F5C7AAC7BAFBDA0231E8321ED5AAC0C94B81C48D8CC39980C0F36B86, 0x1C7BB81165EA6A47AC29A019097A90DC5D54D02CC4725B38BBF399CAEDA716B8, NULL,
N'ALTER PROC [dbo].[uspManageDelivery]        
@Mode INT,@DeliveryID INT,@DocPrefix INT=0,@DocDate Date,@BranchID int ,@SalesmanID int,@VehicleID int,@DocumentsIDs nvarchar(max),        
@Status INT,@CurrentStatus INT,@RefNo NVARCHAR(255)=Null,@Remarks NVARCHAR (255)=null,@Narration NVARCHAR (255)=null,@cby NVARCHAR(255) =null        
as        
BEGIN        
BEGIN TRY        
SET NOCOUNT ON;        
SET DATEFORMAT DMY        
DECLARE @TempAIID int, @DocValue NVARCHAR(255)=null, @DocId NVARCHAR(255)=null, @CDate DATE =NULL,        
@scopeID INT, @CheckStatus INT        
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)        
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)        
declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))      
DECLARE @DocSeriesIdent int        
CREATE TABLE #InvoiceIds(Sno int identity(1,1), ID int,DocValue int)        
if(@Mode != 6) --Not Return      
begin      
if(@Mode = 2)        
BEGIn        
SELECT @CheckStatus = [Status] FROM tblDeliveryOrderHeader WITH (READCOMMITTEDLOCK) WHERE ID = @DeliveryID        
IF((@CheckStatus != @CurrentStatus) OR @CheckStatus IN (2,4))
BEGIN        
RAISERROR(''Document Status already changed'',16,1)        
END        
END        
insert into @tblDocdetails        
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate)   
and BranchID = @BranchID and TransID = 23        
IF((select count(*) from @tblDocdetails) = 0)        
BEGIN        
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)        
END        
if(@Mode = 1)        
BEGIN        
SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails        
UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = 23 and ID = @DocSeriesIdent        
END        
ELSE IF(@Mode = 2)        
BEGIN        
SELECT @DocValue = DocValue,@DocId = DocID FROM tblDeliveryOrderHeader WITH (READCOMMITTEDLOCK) WHERE ID = @DeliveryID        
UPDATE tblDeliveryOrderHeader SET Status=2,Mby=@cby,Mdate=GETDATE() WHERE ID = @DeliveryID        
END        
IF(@Mode = 1)        
BEGIN        
IF((SELECT COUNT(DocValue) FROM tblDeliveryOrderHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and        
DocDate BETWEEN @F_SD AND @F_ED and DocPrefix = 23) != 0)-- and Status in (3,4,5,6)  
BEGIN        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)       
END        
ENd        
IF(@Mode = 2)        
BEGIN        
IF((SELECT COUNT(DocValue) FROM tblDeliveryOrderHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and        
DocDate not BETWEEN @F_SD AND @F_ED and DocPrefix = 23) != 0)-- and Status in (3,4,5,6)  
BEGIN        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)       
END        
ENd   
  
INSERT INTO tblDeliveryOrderHeader(DocDate,DocPrefix,DocValue,DocID,BranchID,SalesmanID,VehicleID,Status,RefNo,Remarks,Narration,CBy,CDate) VALUES        
(@DocDate,@DocPrefix,@DocValue,@DocId,@BranchID,@SalesmanID,@VehicleID,@Status,@RefNo,@Remarks,@Narration,@cby,GETDATE())        
        
SET @ScopeID =(SELECT SCOPE_IDENTITY());         
      
insert into #InvoiceIds        
select DISTINCT ID,DocValue from tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Status IN (1,3,5) AND DocPrefix = 15 AND BranchID = @BranchID AND        
ID IN (select value from string_split(@DocumentsIDs,'',''))      
        
INSERT INTO tblDeliveryOrderDetail        
SELECT @ScopeID,ID,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL FROM #InvoiceIds        
        
SELECT @scopeID        
      
end      
else -- Return      
begin
SELECT @CheckStatus = [Status] FROM tblDeliveryOrderHeader WITH (READCOMMITTEDLOCK) WHERE ID = @DeliveryID        
IF((@CheckStatus != @CurrentStatus) OR @CheckStatus IN (2,4))
BEGIN        
RAISERROR(''Document Status already changed'',16,1)        
END 
insert into #InvoiceIds       
select DISTINCT ID,DocValue  from tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Status IN (1,3,5) AND DocPrefix = 15 AND BranchID = @BranchID AND        
ID IN (select value from string_split(@DocumentsIDs,'',''))      
declare @nCount int = (select count(*) from #InvoiceIds),@n int =1,@InvIdentID int,@InvDocValue nvarchar(10)      
--Validation Loop      
while(@nCount >= @n)      
begin      
select @InvIdentID = ID,@InvDocValue = DocValue from #InvoiceIds where Sno = @n      
if((select COUNT(*) from tblDeliveryOrderDetail WITH (READCOMMITTEDLOCK) WHERE DOID = @DeliveryID AND InvIdentID = @InvIdentID AND Status IN (5)) > 0)      
BEGIN      
RAISERROR(''Invoice already delivered(%s)'',16,1,@InvDocValue)      
END      
set @n =@n+1;      
end      
--Updation Loop      
set @n  =1      
while(@nCount >= @n)      
begin      
select @InvIdentID = ID,@InvDocValue = DocValue from #InvoiceIds where Sno = @n      
update tblDeliveryOrderDetail set Status = 6,RtnBy = @cby,Rtndate = GETDATE() WHERE DOID = @DeliveryID AND InvIdentID = @InvIdentID      
update tblDeliveryOrderHeader set Remarks = @Remarks,Narration = @Narration  WHERE ID = @DeliveryID      
set @n =@n+1;      
end      
select @DeliveryID      
end      
drop table #InvoiceIds      
END TRY        
BEGIN CATCH        
--ROLLBACK TRAN        
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(),ERROR_LINE()        
END CATCH        
END',
N'[export] number-series-updlock=1;readcommittedlock=10';
GO
/****** uspManageDeviceApproval ******/
EXEC #Apply07 N'dbo.uspManageDeviceApproval', 0x48A0060F6AD69D7552F85E5E500D299B76ABB56327640A4C8BF26D727CF6570B, NULL, NULL, 0x876CDCA8E4FA0BF609D5E30EF925F0E42177CCF4A3DCAF2D4476A7A26FAC0C84, 0x56488987355244D5E7D94426F3947BEEAE2532769901C948A0D72F8C35398D3B, NULL,
N'--uspManageDeviceApproval 1  
ALTER PROC [dbo].[uspManageDeviceApproval]  
@Mode int,@ID INT = 0
as  
SET NOCOUNT ON;
begin  
if(@Mode = 1)  
BEGIN  

select DI.UserID,UserName,Mobilenumber,count(*) DeviceCount from tblDeviceInfo DI WITH (READCOMMITTEDLOCK)  
JOIN tblUsers UR WITH (READCOMMITTEDLOCK) ON UR.ID = DI.UserID  
group by userid,UserName,Mobilenumber  
    
select DI.ID,UserID,FORMAT(DI.CDATE,''dd/MMM/yyyy hh:mm tt'') LoginTime,Pincode,DI.Active,Latitude,Longtitude from tblDeviceInfo DI WITH (READCOMMITTEDLOCK)  
JOIN tblUsers UR WITH (READCOMMITTEDLOCK) ON UR.ID = DI.UserID  
END  
if(@Mode = 2) -- Activate Device
BEGIN 
update tblDeviceInfo set Active = 1 where ID = @ID
END
if(@Mode = 3) -- Remove 1 device
BEGIN 
delete from tblDeviceInfo where ID = @ID
END
if(@Mode = 4) -- Remove All device
BEGIN 
delete from tblDeviceInfo where UserID = @ID
END
END',
N'[export] nocount;readcommittedlock=4';
GO
/****** uspManageDocumentSeries ******/
EXEC #Apply07 N'dbo.uspManageDocumentSeries', 0x397BCA1D3686F040EE09E1B7D1FC7B0166CCC745FD50D330BAB79D25728150A0, NULL, NULL, 0x499095627C9EC7D8431CE69EC62AACA5F94A2ADEDF0C35EBBE85E16B2587EC36, 0x8CD643735E2E4C8B7F3E7C7E7D1487BB7BD095AB392C8110C3C1E82B48E817B8, NULL,
N'--uspManageDocumentSeries 3,5  
ALTER proc [dbo].[uspManageDocumentSeries]             
@Mode INT,@ID int =0    
AS              
SET NOCOUNT ON;
BEGIN     
DECLARE @MTN INT = MONTH(GETDATE())  
declare @yr int = RIGHT(YEAR(GETDATE()),2)  
DECLARE @FINYR NVARCHAR(50)  
IF(@MTN <= 3)  
BEGIN  
SET @FINYR = CONCAT(CONVERT(NVARCHAR,(@yr - 1)),CONVERT(NVARCHAR,(@yr)))+''/''  
END  
ELSE  
BEGIN  
SET @FINYR = CONCAT(CONVERT(NVARCHAR,(@yr)),CONVERT(NVARCHAR,(@yr +1)))+''/''  
END  

IF ISNULL(@Mode,0)=1                                
BEGIN                                  
select  TransID,TransName,left(docprefix,charindex(''/'',DocPrefix))+@FINYR DocPrefix,DocValue from tblDocumentSeries where Active = 1  order by TransName        
END      
IF ISNULL(@Mode,0)=2                                
BEGIN                                  
select  YDS.ID hdID,YDS.BranchID hdBranchID,FromDate hdFromDate,ToDate hdToDate,FORMAT(FromDate,''dd/MMM/yyyy'') FromDate,FORMAT(ToDate,''dd/MMM/yyyy'') ToDate ,CU.UserName Createby,      
CONVERT(NVARCHAR,MAX(YDS.CDate)) CreateDate,MU.UserName ModifyBy,CONVERT(NVARCHAR,MAX(YDS.MDate)) ModifyDate,MBO.Name BranchName     
from tblYearwiseDocumentSeries YDS      
JOIN tblUsers CU ON CU.ID = YDS.CBy      
LEFT JOIN tblUsers MU ON MU.ID = YDS.MBy      
join tblMasterBranchOffice MBO ON MBO.ID = YDS.BranchID    
GROUP BY YDS.ID,FromDate,ToDate,CU.UserName,MU.UserName,YDS.BranchID,MBO.Name      
ORDER BY hdFromDate      
END      
IF ISNULL(@Mode,0)=3      
BEGIN 
declare @BranchID int,@From date,@To date
select @BranchID = BranchID,@From = FromDate,@To = ToDate from tblYearwiseDocumentSeries  WHERE ID = @ID  
SELECT ID,BranchID,FromDate,ToDate,YDS.TransID,DS.TransName ,YDS.Prefix DocPrefix,YDS.DocValue FROM tblYearwiseDocumentSeries yds      
left JOIN tblDocumentSeries DS ON DS.TransID = YDS.TransID WHERE ID = @ID    
union all
select @ID,@BranchID,@From,@To, TransID,TransName,left(docprefix,charindex(''/'',DocPrefix))+@FINYR DocPrefix,DocValue 
from tblDocumentSeries where Active = 1 and TransID not in (select TransID from tblYearwiseDocumentSeries WHERE ID = @ID)  order by TransName        
END        
IF ISNULL(@Mode,0)=4    
BEGIN       
SELECT ID,Name FROM tblMasterBranchOffice WHERE Active = 1 ORDER BY Name    
END    
END',
N'[export] nocount';
GO
/****** uspManageFAJournal ******/
EXEC #Apply07 N'dbo.uspManageFAJournal', 0xCD8CA8093B17645BC5AFF131F99BF46BA4F7B5FC58844CAC69306FBDCA458612, NULL, NULL, 0xDF29A63F9444EF056545E9713A3B5D8FDF0900794990A045FA196CFB2EFE2521, 0xDDC72BDC318A408154250AB2028F07FA39172AD2D524C418ACABAD096040F822, NULL,
N'ALTER PROCEDURE [dbo].[uspManageFAJournal]                                   
@DocDate DATE,@tvpManageJE AS [tvpManageJE] READONLY ,@tvpAdjNoteInJE AS [tvpAdjNoteInJE] READONLY ,@UDFId INT =NULL,                      
@nMode INT = 1,@CurrentStatus SMALLINT = null,@ModJVID INT = null,@ModUID INT = null,@ImportStatus INT = 0,            
@Narration NVARCHAR(MAX) = NULL,@BranchID  INT =0         
AS                    
SET NOCOUNT ON;
BEGIN TRY                      
DECLARE @DocValue INT,@DocId VARCHAR(255),@UDFDocValue INT,@UDFDocPrefix NVARCHAR(255) ,@UDFDocId NVARCHAR(255),                      
@ActiveCheck NVARCHAR(255),@Bal DECIMAL (25,6),@ScopeId INT,@AdjustedAmt DECIMAL(25,6),@RowIndex INT=0,@ChkStatus INT          
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)                    
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)    
      declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))          
      DECLARE @DocSeriesIdent int       
      DECLARE @CurrentAmount DECIMAL (25,6),@Balance DECIMAL (25,6)  
if(ISNULL(@nMode,0) = 3) -- IF VARIANT SET STATUS TO 1(create)                    
BEGIN                    
SET @nMode = 1;              
END                 
IF(@nMode = 1)-- CREATE & VARIANT                      
BEGIN      
insert into @tblDocdetails        
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate) and BranchID = @BranchID and TransID = 9      
 IF((select count(*) from @tblDocdetails) = 0)                    
   BEGIN                    
    RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)                    
   END             
        
   SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails        
      
UPDATE tblYearwiseDocumentSeries SET DocValue =  @DocValue + 1 WHERE TransID = 9 and ID = @DocSeriesIdent        
      
--SELECT @DocValue=DocValue ,@DocId=DocPrefix +CONVERT(NVARCHAR,DocValue) FROM tblDocumentSeries WHERE TransID = 9                      
--UPDATE tblDocumentSeries SET DocValue =ISNULL(DocValue,0)+1 WHERE TransID = 9                     
IF ISNULL(@UDFId,0)>0                      
BEGIN                      
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)                                   
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId                      
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@UDFId                      
END                      
END                      
ELSE -- Modify                      
BEGIN                      
  
SELECT @DocValue=DocValue,@DocId=DocID,  
@ChkStatus = Status ,@CurrentAmount=SUM(Credit)+SUM(Debit),@Balance=SUM(Balance)                     
 FROM tblFAJournal WITH (READCOMMITTEDLOCK) WHERE DocPrefix =9 AND JVID =@ModJVID           
 group by  DocValue,DocID,Status  

 IF (@CurrentStatus !=ISNULL(@ChkStatus,0)  OR @ChkStatus in (2,4))
BEGIN                 
RAISERROR(''Status Already Changed'',16,1)                 
END    
IF @CurrentAmount !=@Balance                 
BEGIN                 
RAISERROR(''Amount Miss Matched'',16,1)                 
END    
  
UPDATE tblFAJournal SET Status = 2,MBy = @ModUID,MDate=GETDATE() WHERE DocPrefix =9 AND JVID =@ModJVID                       
END    
IF(@nMode = 1 OR @nMode = 2)           
BEGIN                    
IF((SELECT COUNT(*) FROM tblFAJournal WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and     
DocDate BETWEEN @F_SD AND @F_ED and Status in (1,3,5) and DocPrefix = 9) != 0)                    
BEGIN                    
RAISERROR(''Document ID already exists(%s)'',16,1,@DocId)                    
END                    
ENd     
--Get maintaing JV Id                                   
DECLARE @JVID INT                                   
SELECT @JVID=MAX(ISNULL(JVID,0))+1 FROM tblFAJournal WITH (READCOMMITTEDLOCK)                                   
DECLARE @UID INT,@Date DATE ,@DocRef NVARCHAR(255)=NULL,@AccountID INT,@Debit DECIMAL (25,6),@Credit DECIMAL (25,6),                                   
@Remarks NVARCHAR(255)=NULL,@Adjustment NVARCHAR(10)                                   
DECLARE cursor_JE CURSOR LOCAL FAST_FORWARD FOR SELECT * FROM @tvpManageJE                                   
OPEN cursor_JE                                   
FETCH NEXT FROM cursor_JE INTO @Date,@DocRef,@AccountID,@Adjustment,@Debit,@Credit,@Remarks,@Narration,@UID                                   
WHILE @@FETCH_STATUS =0                   
BEGIN                                   
                                 
IF ISNULL (@Credit,0)<>0                                   
BEGIN                                   
SET @Bal = @Credit                          
END                                   
ELSE                                   
BEGIN                                   
SET @Bal = @Debit                                   
END               
                                    
                                   
INSERT INTO tblFAJournal(JVID,DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,[Status],             
Adjusment,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy,CDate,AdjValue,ClBy,ClDate,BranchID)                                   
VALUES(@JVID,@DocId,9,@DocValue,@Date,@DocRef,@AccountID,@Credit,@Debit,@Bal,@Remarks,@Narration,                    
CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN CASE WHEN ISNULL(@nMode,1) = 1 THEN 1 ELSE 3 END ELSE @ImportStatus END,                    
@Adjustment,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@UID,GETDATE(),@Bal,                    
case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,@BranchID)                                   
--Get Scope Id from header table                                   
SET @ScopeId=(SELECT SCOPE_IDENTITY ());                                   
                                   
                                   
DECLARE @NoteID INT,@AdjAmt DECIMAL (25,6),@Status SMALLINT ,@TrnasType NVARCHAR(255)                                
DECLARE cursor_JEAdjNote CURSOR LOCAL FAST_FORWARD FOR SELECT NoteId,[Balance],[TransType] FROM @tvpAdjNoteInJE WHERE AccID=@AccountID                     
OPEN cursor_JEAdjNote                                   
FETCH NEXT FROM cursor_JEAdjNote INTO @NoteID,@AdjAmt ,@TrnasType                                   
WHILE @@FETCH_STATUS =0                              
BEGIn                                   
update tblFAJournal SET TransType = @TrnasType WHERE AccountID=@AccountID                                   
IF ISNULL(@TrnasType ,'''')=''Sales''                                 
BEGIN                                   
select @TrnasType                  
--SELECT @CurrentAmount =Balance,@Status=[Status] FROM tblTranSalesHeader WHERE InvId =@NoteID AND DocPrefix=2                                   
END                                   
IF ISNULL(@TrnasType ,'''')=''Sales Return''                                   
BEGIN                                   
select @TrnasType                  
--SELECT @CurrentAmount =Balance,@Status=[Status] FROM tblTranSalesHeader WHERE InvId =@NoteID AND DocPrefix=6                                   
END                                   
IF ISNULL(@TrnasType,'''')=''Purchase''                                   
BEGIN                                   
SELECT @CurrentAmount=Balance,@Status=[Status] FROM tblTransPurchaseHeader WITH (READCOMMITTEDLOCK) WHERE ID=@NoteID AND TransID=1                                  
END                                   
IF ISNULL(@TrnasType,'''')=''Purchase Return''                                   
BEGIN                           
select @TrnasType                  
--SELECT @CurrentAmount=Balance,@Status=[Status] FROM tblTranBillHeader WHERE BillID=@NoteID AND DocPrefix=9                                   
END                                   
IF ISNULL(@TrnasType ,'''')=''Collection''                                   
BEGIN                                   
select @TrnasType                  
--SELECT @CurrentAmount =Balance,@Status=[Status] FROM tblTranCollectionHeader WHERE ColID =@NoteID AND DocPrefix=5                                   
END                                   
IF ISNULL(@TrnasType ,'''')=''Other Collection''                                   
BEGIN                                   
select @TrnasType                  
--SELECT @CurrentAmount =Balance,@Status=[Status] FROM tblTranCollectionHeader WHERE ColID =@NoteID AND DocPrefix=17                                   
END                                   
IF ISNULL(@TrnasType ,'''')=''Payment''                                   
BEGIN                                   
select @TrnasType                  
--SELECT @CurrentAmount =Balance,@Status=[Status] FROM tblTranPaymentHeader WHERE PYID =@NoteID AND PYPrefix=10                                   
END                                   
IF ISNULL(@TrnasType ,'''')=''Other Payment''                                   
BEGIN                           
select @TrnasType                  
--SELECT @CurrentAmount =Balance,@Status=[Status] FROM tblTranPaymentHeader WHERE PYID =@NoteID AND PYPrefix=18                                   
END                                   
IF ISNULL(@TrnasType ,'''')=''Payable Voucher''                                   
BEGIN                              
SELECT @CurrentAmount =Balance,@Status=[Status] FROM tblTranPRVoucher WITH (READCOMMITTEDLOCK) WHERE ID =@NoteID AND TransID=6                                  
END                                   
IF ISNULL(@TrnasType ,'''')=''Receivable Voucher''                                   
BEGIN                                   
SELECT @CurrentAmount =Balance,@Status=[Status] FROM tblTranPRVoucher WITH (READCOMMITTEDLOCK) WHERE ID =@NoteID AND TransID=7                                   
END                                   
IF ISNULL(@TrnasType ,'''')=''Contra''                                   
BEGIN                                   
SELECT @CurrentAmount =Balance,@Status= Status FROM tblTranContra WITH (READCOMMITTEDLOCK) WHERE ID =@NoteID                            
END                                   
IF ISNULL(@TrnasType ,'''')=''Credit Note'' OR ISNULL(@TrnasType ,'''')=''Debit Note''                                   
BEGIN                                   
SELECT @CurrentAmount =Balance,@Status=[Status] FROM tblNoteDetails WITH (READCOMMITTEDLOCK) WHERE ID =@NoteID                            
END                              
IF ISNULL(@TrnasType ,'''')=''Service Bill'' OR ISNULL(@TrnasType ,'''')=''Service Invoice''                                  
BEGIN                                   
select @TrnasType                  
--SELECT @CurrentAmount=Balance,@Status=[Status] FROM tblTranServiceHeader WHERE ServiceID=@NoteID                                  
END                                  
IF ISNULL(@TrnasType ,'''')=''Service Bill'' OR ISNULL(@TrnasType ,'''')=''Service Invoice''                                  
BEGIN                         
select @TrnasType                  
--SELECT @CurrentAmount=Balance,@Status=[Status] FROM tblTranServiceHeader WHERE ServiceID=@NoteID                                  
END                                 
                                                
ELSE                                   
BEGIN                                   
IF ISNULL(@TrnasType,'''')=''Sales''                               
BEGIN                                   
select @TrnasType                     
--UPDATE tblTranSalesHeader  SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE InvId =@NoteID AND DocPrefix=2                          
END                                   
IF ISNULL(@TrnasType,'''')=''Sales Return''                                   
BEGIN                                   
select @TrnasType                  
--UPDATE tblTranSalesHeader  SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE InvId =@NoteID AND DocPrefix=6                          
END                                   
IF ISNULL(@TrnasType,'''')=''Purchase''                                   
BEGIN                          
                  
UPDATE tblTransPurchaseHeader SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE ID=@NoteID AND TransID=7                            
--select * from tblTranBillHeader where DocValue = 509                          
END                                   
IF ISNULL(@TrnasType,'''')=''Purchase Return''                                   
BEGIN                                   
select @TrnasType                  
--UPDATE tblTranBillHeader SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE BillID=@NoteID AND DocPrefix=9                           
END                                   
IF ISNULL(@TrnasType,'''')=''Collection''                                   
BEGIN                                   
select @TrnasType                  
--UPDATE tblTranCollectionHeader SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE ColID=@NoteID AND DocPrefix=5                          
END                                   
IF ISNULL(@TrnasType,'''')=''Other Collection''                                   
BEGIN                                   
select @TrnasType                  
--UPDATE tblTranCollectionHeader SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE ColID=@NoteID AND DocPrefix=17                          
END                                   
IF ISNULL(@TrnasType,'''')=''Payment''                                   
BEGIN                                   
select @TrnasType                  
--UPDATE tblTranPaymentHeader SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE PYID=@NoteID AND PYPrefix = 10                          
END                                   
IF ISNULL(@TrnasType,'''')=''Other Payment''                                   
BEGIN                                   
select @TrnasType                  
--UPDATE tblTranPaymentHeader SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE PYID=@NoteID AND PYPrefix = 18                          
END                                   
IF ISNULL(@TrnasType ,'''')=''Payable Voucher''                                   
BEGIN                                   
select @TrnasType                  
UPDATE tblTranPRVoucher SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE ID =@NoteID AND TransID=15                           
END                                   
IF ISNULL(@TrnasType ,'''')=''Receivable Voucher''                                   
BEGIN                                   
--UPDATE tblTranPRVoucher SET [Status]=5,Balance=0.00 WHERE PRVID =@NoteID AND DocPrefix=16                            
UPDATE tblTranPRVoucher SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance= (Balance - @AdjAmt) WHERE ID =@NoteID AND TransID=16                       
END                                   
IF ISNULL(@TrnasType ,'''')=''Contra''                                   
BEGIN                                   
--UPDATE tblTranContra SET [Status]=5,Balance=0.00 WHERE ContraID =@NoteID                          
UPDATE tblTranContra SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance = (Balance - @AdjAmt) WHERE ID=@NoteID                          
--select * from tblTranContra where DocValue = 135                          
END                                   
IF ISNULL(@TrnasType ,'''')=''Credit Note'' OR ISNULL(@TrnasType ,'''')=''Debit Note''                      
BEGIN                                   
UPDATE tblNoteDetails SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance = (Balance - @AdjAmt) WHERE ID=@NoteID                          
                          
END                                 
IF ISNULL(@TrnasType ,'''')=''Service Bill'' OR ISNULL(@TrnasType ,'''')=''Service Invoice''                                   
BEGIN                                   
select @TrnasType                  
--UPDATE tblTranServiceHeader SET Status = (CASE WHEN @CurrentAmount = @AdjAmt THEN 5 ELSE @Status END),Balance = (Balance - @AdjAmt) WHERE ServiceID=@NoteID                          
END                                  
                                   
END                                   
FETCH NEXT FROM cursor_JEAdjNote INTO @NoteID,@AdjAmt,@TrnasType                           
END                                   
CLOSE cursor_JEAdjNote                                   
DEALLOCATE cursor_JEAdjNote                                   
SET @RowIndex= @RowIndex+1                                   
FETCH NEXT FROM cursor_JE INTO @Date,@DocRef,@AccountID,@Adjustment,@Debit,@Credit,@Remarks,@Narration,@UID                                   
END                                   
CLOSE cursor_JE                                   
DEALLOCATE cursor_JE                                   
                                   
DECLARE @FASerial INT=1,@FAnCount INT=(SELECT COUNT(*) FROM @tvpAdjNoteInJE)                                   
CREATE TABLE #TEMP1 (SNO INT IDENTITY,ACCid INT,NoteID INT,Balance DECIMAL(25,9),Docdate DATE,TransType NVARCHAR(255))                                 
WHILE @FAnCount>0                                   
BEGIN                                   
INSERT INTO #TEMP1 SELECT * FROM @tvpAdjNoteInJE                                   
SELECT @AccountID=ACCid,@DocValue=NoteID,@TrnasType=TransType,@Balance=Balance FROM #TEMP1 WHERE SNO =@FASerial                                   
INSERT INTO tblFAJournelCancel(JVID,Adjustment,AccountID,Status,NoteID,TransTpe)                                   
VALUES (@JVID,@Balance,@AccountID,1,@DocValue,@TrnasType)                      
SET @FAnCount =@FAnCount-1                                   
SET @FASerial =@FASerial+1                                   
END                                   
SELECT @ScopeId;                                   
                                   
END TRY                                   
BEGIN CATCH                                   
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE() ,ERROR_LINE(),@RowIndex ;                                   
END CATCH',
N'[export] nocount;cursor-local-fast_forward=2;number-series-updlock=2;readcommittedlock=10';
GO
