/****** uspManageFinancialAccount ******/
EXEC #Apply07 N'dbo.uspManageFinancialAccount', 0x542B16AF433057FA4FE2E557303BC3AE122C7E8430C9976A0FE424868C68FF9C, NULL, NULL, 0x502FD2E33540B39A71599ACC8C0C9D7327B0BABA84A7731E5D6AB25805A863D2, 0xE179FEC9FF295E396EC4BB5F727F065DD433E307492793AA22DCAB5920EA3545, NULL,
N'--uspManageFinancialAccount 6,0,502        
--uspManageFinancialAccount 8,122,1                      
ALTER PROC [dbo].[uspManageFinancialAccount]                      
@Mode INT,@FAID int = null,@AccountName nvarchar(MAX) = null,@AccountGroup nvarchar(MAX) = null,@OpeningBalance decimal(25, 4) = null,@SACCode nvarchar(25) = null,@PANNumber nvarchar(25) = null,                      
@FATypeID tinyint = null,@UserAccount tinyint = null,@Active bit = null,@CBy smallint = null                      
as                      
SET NOCOUNT ON;
begin                      
BEGIN TRY                      
DECLARE @AccGrpID SMALLINT         
declare @BranchID int    
select @BranchID = AppValue from tblAppConfig WITH (READCOMMITTEDLOCK) where AppId = 11    
IF(@Mode = 1)                      
BEGIn                      
IF((SELECT count(*) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @AccountName) > 0)                      
BEGIN                      
RAISERROR(''Already Exists'',16,1)                      
END                      
SELECT @AccGrpID = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName = @AccountGroup                      
if(ISNULL(@AccGrpID,0) = 0)                      
BEGIN                      
RAISERROR(''Account Group does not Exists'',16,1)                      
END                      
set @AccountName = (select dbo.ProperCase(@AccountName))                      
insert into tblFAAccount(AccountName,AccountGroup,OpeningBalance,FATypeID,UserAccount,SACCode,PANNumber,Active,CBy,CDate)                      
Values (@AccountName,@AccGrpID,@OpeningBalance,@FATypeID,@UserAccount,@SACCode,@PANNumber,@Active,@CBy, GETDATE())                      
SELECT SCOPE_IDENTITY()                      
END                      
IF(@Mode = 2)                      
BEGIn                      
IF((SELECT count(*) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @AccountName AND FAID != @FAID) > 0)                      
BEGIN                      
RAISERROR(''Already Exists'',16,1)                      
END                      
SELECT @AccGrpID = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName = @AccountGroup                      
if(ISNULL(@AccGrpID,0) = 0)                      
BEGIN                      
RAISERROR(''Account Group does not Exists'',16,1)                      
END                      
IF @Active=0                                                        
BEGIN                                                        
DECLARE @ReturnValue DECIMAL(25,4)                                                        
EXEC uspGetClosingBal @FAID,@ReturnValue OUTPUT                                                        
IF( @ReturnValue !=0)                                                        
BEGIN                                                        
RAISERROR (''OSPending'',16,1)                                                         
END                                                
END                     
INSERT INTO tblMasterHistory (FormID,ID,Name,Column1,Column2,Column3,Column4,Column5,Column6,Active,CBy,CDate,MBy,MDate,HisCBy,HisCDate)                      
(select 24,*,@CBy, GETDATE() from tblFAAccount WITH (READCOMMITTEDLOCK) where FAID = @FAID)                      
                      
set @AccountName = (select dbo.ProperCase(@AccountName))                      
UPDATE tblFAAccount SET AccountName = @AccountName,AccountGroup = @AccGrpID,OpeningBalance = @OpeningBalance,FATypeID = @FATypeID,                      
SACCode = @SACCode,PANNumber = @PANNumber,Active = @Active,MBy = @CBy ,MDate = GETDATE() WHERE FAID = @FAID                      
SELECT @FAID                      
END                      
IF(@Mode = 3)                      
BEGIN                      
SELECT MBA.FAID ID,MBA.AccountName,MB.AccountGroupName FaGroup,dbo.fngetroundedvalue(0) OpenBalance,SACCode,PANNumber PAN,              
 null FAType,CASE WHEN MBA.Active = 1 THEN ''Yes'' else ''No'' end Active,0 CloseBal,'''' CrDr,UserAccount,CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,            
 CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MBA.CDate) ELSE CONVERT(NVARCHAR(100),MBA.MDate) END LastActionTime             
 from tblFAAccount MBA WITH (READCOMMITTEDLOCK)                    
JOIN tblFAGroup MB WITH (READCOMMITTEDLOCK) ON MB.FAGroup = MBA.AccountGroup              
JOIN tblFAType FT WITH (READCOMMITTEDLOCK) ON FT.FATypeID = MBA.FATypeID              
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MBA.CBy                      
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MBA.MBy             
order by AccountName                      
END                      
IF(@Mode = 4)                      
BEGIN               
SELECT *,0 CloseBal,'''' CrDr from tblFAAccount WITH (READCOMMITTEDLOCK) where @AccountName = @AccountName                      
END                      
IF(@Mode = 5)                      
BEGIN                      
SELECT * from tblFAGroup WITH (READCOMMITTEDLOCK) where Active = 1 order by AccountGroupName                      
END                     
IF(@Mode = 6)                      
BEGIN           
    
create table #temp(Bal decimal(25,4),crdr nvarchar(10))                  
insert into #temp                  
exec [uspFAAccOpenCloseBalance] 1,@AccountName,@BranchID             
SELECT MBA.FAID ID,MBA.AccountName,MB.AccountGroupName FaGroup,dbo.fngetroundedvalue(OpeningBalance) OpenBalance,SACCode,PANNumber PAN,              
MBA.FATypeID FAType,MBA.Active,MB.AccountGroupName,(select dbo.fnGetRoundedValue(Bal) from #temp) CloseBal,(select crdr from #temp) CrDr,              
UserAccount,CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,            
 CASE WHEN ISNULL(MBA.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MBA.CDate) ELSE CONVERT(NVARCHAR(100),MBA.MDate) END LastActionTime from tblFAAccount MBA WITH (READCOMMITTEDLOCK)                  
JOIN tblFAGroup MB WITH (READCOMMITTEDLOCK) ON MB.FAGroup = MBA.AccountGroup                  
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MBA.CBy                      
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MBA.MBy             
where FAID = @AccountName                     
drop table #temp                  
END    
IF(@Mode = 7)                      
BEGIN                      
SELECT ID,Name from tblMasterBranchOffice WITH (READCOMMITTEDLOCK) where Active = 1 order by Name    
END      
IF(@Mode = 8)                      
BEGIN      
DECLARE @Date date = getdate(),@DocSeriesID int = 0    
set @DocSeriesID = (select top(1) ID from tblYearwiseDocumentSeries WITH (READCOMMITTEDLOCK) where @Date between 
FromDate and ToDate and BranchID = @AccountName)    
    
    
create table #tempcb(Bal decimal(25,4),crdr nvarchar(10))                  
insert into #tempcb                  
exec [uspFAAccOpenCloseBalance] 1,@FAID,@AccountName      
    
select isnull(FAType,0) FAType,OpeningBalance,(select dbo.fnGetRoundedValue(Bal) +'' ''+ crdr from #tempcb) ClosingBalance 
from tblFAAccOpening WITH (READCOMMITTEDLOCK)     
where BranchID = @AccountName and FAID = @FAID and DocSeriesID = @DocSeriesID     
    
drop table #tempcb    
END    
END TRY                      
BEGIN CATCH                      
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC]                      
END CATCH                      
END',
N'[export] nocount;readcommittedlock=20';
GO
/****** uspManageFinancialAccountGroup ******/
EXEC #Apply07 N'dbo.uspManageFinancialAccountGroup', 0x446C3EFA1C9F40601C68A47AFB3F6534D2C1BC0BBE344CE675BB5D3FCCCCBFB4, NULL, NULL, 0xD4062D9AED2B5B94F9F97FC5FA02CCC38D0029B6D2F594E62A3749A380E9972E, 0xFC5294BB716A6E435924FF495C3756F5D1099B3DFC7F4A99039DFBED955BDB37, NULL,
N'ALTER PROC [dbo].[uspManageFinancialAccountGroup]            
@Mode INT,@ID int = null,@AccountGroupName nvarchar(MAX) = null,@ParentGroup nvarchar(MAX) = null,@TypeID tinyint = null,            
@UserGroup tinyint = null,@LevelID tinyint = null,@Active bit = null,@CBy int = null            
as            
SET NOCOUNT ON;
begin            
BEGIN TRY            
DECLARE @AccGrpParID SMALLINT = 0         
set @LevelID  = 0              
IF(@Mode = 1)            
BEGIN            
IF((SELECT count(*) FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName = @AccountGroupName) > 0)            
BEGIN            
RAISERROR(''Already Exists'',16,1)            
END            
IF(ISNULL(@ParentGroup,'''') != '''')            
BEGIN            
SELECT @AccGrpParID = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName = @ParentGroup and TypeID = @TypeID            
if(ISNULL(@AccGrpParID,0) = 0)            
BEGIN            
RAISERROR(''Parent Group does not Exists'',16,1)            
END            
IF ISNULL(@AccGrpParID,0)>0                  
BEGIN              
SELECT @LevelID = LevelID FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE FAGroup = @AccGrpParID         
END        
END            
set @AccountGroupName = (select dbo.ProperCase(@AccountGroupName))            
insert into tblFAGroup(AccountGroupName,ParentGroup,TypeID,UserGroup,LevelID,Active,CBy,CDate)            
Values (@AccountGroupName,@AccGrpParID,@TypeID,@UserGroup,(@LevelID+1),@Active,@CBy, GETDATE())            
SELECT SCOPE_IDENTITY()            
END            
IF(@Mode = 2)            
BEGIN            
IF((SELECT count(*) FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName = @AccountGroupName AND FAGroup != @ID) > 0)            
BEGIN            
RAISERROR(''Already Exists'',16,1)            
END            
IF(ISNULL(@ParentGroup,'''') != '''')            
BEGIN            
SELECT @AccGrpParID = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName = @ParentGroup and TypeID = @TypeID            
if(ISNULL(@AccGrpParID,0) = 0)            
BEGIN            
RAISERROR(''Parent Group does not Exists'',16,1)            
END        
IF ISNULL(@AccGrpParID,0)>0                  
BEGIN              
SELECT @LevelID = LevelID FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE FAGroup = @AccGrpParID         
END        
END            
INSERT INTO tblMasterHistory (FormID,ID,Name,Column1,Column2,Column3,Column4,Active,CBy,CDate,MBy,MDate,HisCBy,HisCDate)            
(select 25,*,@CBy, GETDATE() from tblFAGroup WITH (READCOMMITTEDLOCK) where FAGroup = @ID)            
set @AccountGroupName = (select dbo.ProperCase(@AccountGroupName))            
UPDATE tblFAGroup SET AccountGroupName = @AccountGroupName,ParentGroup = @AccGrpParID,TypeID = @TypeID,UserGroup = @UserGroup,            
LevelID = (@LevelID+1),Active = @Active,MBy = @CBy ,MDate = GETDATE() WHERE FAGroup = @ID            
SELECT @ID            
END            
IF(@Mode = 3)            
BEGIN            
SELECT FAG.FAGroup ID,FAG.AccountGroupName FAGrpName,FAG.TypeID,ACT.TypeName,FAGPAR.AccountGroupName ParentGrp,      
CASE WHEN FAG.Active = 1 THEN ''Yes'' else ''No'' end Active ,FAG.UserGroup UserAccount ,CASE WHEN ISNULL(FAG.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,  
 CASE WHEN ISNULL(FAG.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),FAG.CDate) ELSE CONVERT(NVARCHAR(100),FAG.MDate) END LastActionTime   
 from tblFAGroup FAG WITH (READCOMMITTEDLOCK)            
JOIN tblAccountType ACT WITH (READCOMMITTEDLOCK) ON ACT.TypeID = FAG.TypeID            
LEFT JOIN tblFAGroup FAGPAR WITH (READCOMMITTEDLOCK) ON FAGPAR.FAGroup = FAG.ParentGroup       
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = FAG.CBy            
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = FAG.MBy   
order by FAG.AccountGroupName            
END            
IF(@Mode = 4)            
BEGIN            
SELECT * from tblFAGroup WITH (READCOMMITTEDLOCK) where AccountGroupName = @AccountGroupName            
END            
IF(@Mode = 5)            
BEGIN            
SELECT * from tblAccountType WITH (READCOMMITTEDLOCK) where Active = 1 order by TypeName            
END            
IF(@Mode = 6)            
BEGIN            
SELECT * from tblFAGroup WITH (READCOMMITTEDLOCK) where TypeID = @AccountGroupName order by AccountGroupName            
END            
END TRY            
BEGIN CATCH            
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC]            
END CATCH            
END',
N'[export] nocount;readcommittedlock=15';
GO
/****** uspManageFinancialReports ******/
EXEC #Apply07 N'dbo.uspManageFinancialReports', 0xD865B71A576027346EDACEA6C1E9288A997E14103326C6F36F3BC52321895B7C, NULL, NULL, 0x8535A4FF98D2B0684D88C091F665D94CFA8C6A047613BF28E57FE58088993C4F, 0x49D0EFCF9CD3EF268292D4AB458E87AABD7ABABA022C1A2103303C9FFA69D631, NULL,
N'ALTER proc [dbo].[uspManageFinancialReports]                                        
@Mode INT,@ReportID INT = NULL,@ALName NVARCHAR(255) = NULL                                        
AS                                        
SET NOCOUNT ON;
BEGIN                                        
IF(@Mode = 0)                                        
BEGIN                                        
select * from tblFinancialReport WHERE ReportID = @ReportID                                   
END                                   
IF(@Mode = 1)                                        
BEGIN                                        
select * from tblFinancialParameterInfo WHERE ReportID = @ReportID order by ParamOrder                                        
END                                        
IF(@Mode =2 )                                        
BEGIn                                        
IF(@ALName = ''Bankaccountno'')                                        
BEGIN                                        
SELECT FAID ID,AccountNo Name FROM tblMasterBankAccount where FAID > 0 ORDER BY Name                                        
END           
IF(@ALName = ''FAAccountNames'')                                        
BEGIN                                        
SELECT FAID ID,AccountName Name FROM tblFAAccount ORDER BY Name                                        
END         
IF(@ALName = ''BranchNameAL'')                                        
BEGIN                                        
SELECT ID,Name Name FROM tblMasterBranchOffice ORDER BY Name                                        
END       
IF(@ALName = ''BranchName'')                                        
BEGIN                              
select 0 ID,''-- SELECT --'' Name  
union all  
SELECT ID,Name Name FROM tblMasterBranchOffice ORDER BY Name  
END   
IF(@ALName = ''FAAccountGroups'')                                        
BEGIN                                        
SELECT FAGroup ID,AccountGroupName Name FROM tblFAGroup ORDER BY AccountGroupName                                        
END       
IF(@ALName = ''DTBT2'')                                        
BEGIN                              
select 1 ID,''Trail Balance With Opening Balance'' Name  
union all  
select 3 ID,''Opening Trial Balance'' Name  
END
IF(@ALName = ''TrailBalance'')                                        
BEGIN                              
select 1 ID,''Trail Balance With Opening Balance'' Name  
union all  
select 2 ID,''Trail Balance Without Opening Balance'' Name  
union all  
select 3 ID,''Opening Trial Balance'' Name  
union all  
select 4 ID,''Trail Balance with specific date range'' Name  
END
IF(@ALName = ''ProfitLoss'')                                        
BEGIN                              
select 1 ID,''Profit & Loss'' Name  
union all  
select 4 ID,''Profit & Loss with specific date range'' Name  
END
IF(@ALName = ''BalanceSheet'')                                        
BEGIN                              
select 1 ID,''Balance sheet'' Name  
union all  
select 4 ID,''Balance sheet with specific date range'' Name  
END
END
END',
N'[export] nocount';
GO
/****** uspManageFullColl ******/
EXEC #Apply07 N'dbo.uspManageFullColl', 0xF207156840637AFCE3F4BA3BFA4609633B9F65185CD29BC00AD6FC6F25A11979, NULL, NULL, 0x1B75D7978C495F7DA57FBAEDC23755B6CE278DC89DDFCC6B18C092A4D36EC405, 0xC82A575930CDF80704C70A8BBAF22D91C0C99FA3A15F1743DD22032C5819D6E3, NULL,
N'--uspManageFullColl
ALTER PROCEDURE [dbo].[uspManageFullColl]
@DocPrefix INT,@UDFId INT=NULL,@Header dbo.tvpCollHeader READONLY,@Detail dbo.tvpCollDetail READONLY,
@Mop dbo.tvpCollMop READONLY,@IsImplicit INT=NULL,@BeatID INT=NULL,@SalesManID INT=NULL,@nAllowNegativeBal INT=NULL,
@tvpSaveDenomination dbo.tvpSaveDenomination READONLY,@nStatus INT = NULL,@nCollID INT = NULL,@CurruntStatus INT = NULL,
@BTMode INT = 0,@Remarks NVARCHAR(MAX)=NULL,@Narration NVARCHAR(MAX) = NULL ,@BranchID INT
AS
SET NOCOUNT ON;
BEGIN
BEGIN TRY
SET DATEFORMAT dmy;
DECLARE @ScopeIdent INT
--To Count Header TempTable Rows Count
DECLARE @TempHeader TABLE(HeaderIdent INT IDENTITY(1,1),[DATE] DATE,[CollPYType] INT,RefNo NVARCHAR(255),AccID INT,
ColAmt DECIMAL (25,6),Balance DECIMAL (25,6),ColMode NVARCHAR(50),[Status] INT,ExAccID INT,[UID] INT,[Type] INT,[SerialNo] INT,
VisaPern DECIMAL (25,6),VisaAmt DECIMAL (25,6));--Create Table Variable
DECLARE @PaymentStatusChange INT
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)
declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))
DECLARE @DocSeriesIdent int
CREATE TABLE #TempDetail (DetailIdent INT IDENTITY(1,1),AccID INT,DocPrefix INT,DocValue INT,DocID INT,DocDate NVARCHAR(50),
Balance DECIMAL (25,6),ColValue DECIMAL (25,6),AdjAmt DECIMAL (25,6),DiscPerc NVARCHAR(50),DiscAmt DECIMAL (25,6),
FullyAdj INT,FullyAdjAmt DECIMAL (25,6),TotalAmtAdj DECIMAL (25,6),[SerialNo] INT,ReasonID INT);--Create Table Variable

INSERT INTO @TempHeader SELECT [DATE],[CoLLPYType],RefNo,AccId,ColAmt,Balance,ColMode,[Status],ExAccId,[UID],[Type],[SerialNo],[VisaPern],[VisaAmt]
FROM @Header ORDER BY AccId,[SerialNo]
--Declare TempVariable
DECLARE @HeaderCount INT ,@UDFDocValue INT,@UDFDocPrefix NVARCHAR(255) ,@UDFDocId NVARCHAR(255),@CheckUDFId INT
SET @HeaderCount=(SELECT COUNT(*) FROM @TempHeader)
DECLARE @TempHeaderRowCount INT = 1


--Checking Rows Count IN Header TempTable
WHILE(@TempHeaderRowCount<=@HeaderCount)
BEGIn
--Declaration Parat
DECLARE @DocValue int,@WriteOffAmt DECIMAL (25,6),@AddAdjAmt DECIMAL (25,6),@AddDisAmt DECIMAL (25,6)
DECLARE @DocID NVARCHAR(50),@ColDate DATE,@ColModeId INT,@CollPYType INT,@PreviousTranDate DATE
DECLARE @CollAmt DECIMAL (25,6),@AccId INT ,@ExpanceAccID INT,@DocRefNo NVARCHAR(255),@SerialNo INT,@UID INT,@VisaPern DECIMAL (25,6), @VisaAmt DECIMAL (25,6)
SELECT @UID=[UID],@ColDate=[Date] FROM @TempHeader WHERE HeaderIdent=@TempHeaderRowCount
IF(ISNULL(@nStatus,1) = 1)
BEGIN

insert into @tblDocdetails
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@ColDate between FromDate and ToDate) and BranchID = @BranchID and TransID = @DocPrefix
IF((select count(*) from @tblDocdetails) = 0)
BEGIN
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)
END

SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails

UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = @DocPrefix and ID = @DocSeriesIdent

--Get The DocValue From tblDocumentSeries
--SET @DocValue=(SELECT DocValue FROM tblDocumentSeries WHERE TransID=@DocPrefix)
----Get The DocID From Concatination
--SET @DocID=(SELECT DocPrefix+CONVERT(NVARCHAR(50), DocValue) FROM tblDocumentSeries WHERE TransID=@DocPrefix)
----Update tblDocumentSeries
--UPDATE tblDocumentSeries SET DocValue=DocValue+1 WHERE TransID=@DocPrefix
--User Defin Number Doc Serise
IF ISNULL(@UDFId,0)>0
BEGIN
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@UDFId
END
END
ELSE
BEGIN
DECLARE @CollPayStatus INT
IF @DocPrefix=19 OR @DocPrefix=10
BEGIn
SELECT @CollPayStatus = Status FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE DocPrefix =@DocPrefix AND ColID = @nCollID
IF((@CollPayStatus != @CurruntStatus) OR @CollPayStatus IN (2,4))
BEGIN
RAISERROR(''Document status already changed'',16,1)
END
-- check DD,CHEQUE,BANK TRANSFER,VISA STATUS
SET @PaymentStatusChange = (SELECT COUNT(*) from tblCollPMDetails WITH (READCOMMITTEDLOCK) where ColID = @nCollID and PaymentTermID in (2,3,4,5) and Status NOT IN (1,3))
IF(@PaymentStatusChange > 0)
BEGIN
RAISERROR(''Document status already changed'',16,1)
END

UPDATE tblTranCollectionHeader SET Status = 2,MBy = @UID,MDate = GETDATE()WHERE DocPrefix =@DocPrefix AND ColID =@nCollID
UPDATE tblCollPMDetails SET Status = 2 WHERE ColID =@nCollID
SELECT @DocValue= SH.DocValue,@DocId=DocId,@PreviousTranDate=ColDate,@UDFDocValue=UDFDocValue,@CheckUDFId=UDFId
FROM tblTranCollectionHeader SH WITH (READCOMMITTEDLOCK) WHERE SH .DocPrefix =@DocPrefix AND SH.ColID =@nCollID
END
ELSE
BEGIN
SELECT @CollPayStatus = Status FROM tblTranPaymentHeader WITH (READCOMMITTEDLOCK) WHERE PYPrefix =@DocPrefix AND PYID =@nCollID
IF((@CollPayStatus != @CurruntStatus) OR @CollPayStatus IN (2,4))
BEGIN
RAISERROR(''Document status already changed'',16,1)
END
-- check DD,CHEQUE,BANK TRANSFER,VISA STATUS
SET @PaymentStatusChange = (select COUNT(*) StatusChanges from tblPaymentPMDetail WITH (READCOMMITTEDLOCK) where PYID = @nCollID and PaymentTermID in (2,3,4,5) and Status NOT IN (1,3))
IF(@PaymentStatusChange > 0)
BEGIN
RAISERROR(''Document status already changed'',16,1)
END


UPDATE tblTranPaymentHeader SET Status = 2,MBy = @UID,MDate = GETDATE()WHERE PYPrefix =@DocPrefix AND PYID =@nCollID
UPDATE tblPaymentPMDetail SET Status = 2 WHERE PYID = @nCollID
SELECT @DocValue= SH.DocValue,@DocId=DocId,@PreviousTranDate=PYDATE,@UDFDocValue=UDFDocValue,@CheckUDFId=UDFId
FROM tblTranPaymentHeader SH WITH (READCOMMITTEDLOCK) WHERE SH .PYPrefix =@DocPrefix AND SH.PYID =@nCollID
END
update tblFAJournal set Status = 2 ,MBy = @UID,MDate = GETDATE()WHERE DocPrefix =@DocPrefix AND TransId = @nCollID

--User Document and if Changes made
IF ISNULL(@UDFId,0)>0
BEGIN
IF(@UDFId=@CheckUDFId)
BEGIN
SELECT @UDFDocId=DocPrefix + CONVERT(NVARCHAR, @UDFDocValue),@UDFDocPrefix=DocPrefix FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId
END
IF(@UDFId!=@CheckUDFId)
BEGIN
