INSERT INTO #TempDetail SELECT AccId,DocPrefix,DocValue, DocID,DocDate,Balance,ColValue,AdjAmt,DiscPer,DiscAmt,FullyAdj,FullyAdjAmt,
TotalAmtAdj,[SerialNo],ReasonID FROM @Detail AS Detail WHERE Detail.AccId=@AccId AND Detail.[SerialNo]=@SerialNo ORDER BY Detail.[SerialNo]
--Get The Rows Count
