DECLARE @TempBalance DECIMAL (25,6)=0,@OriginalBalance DECIMAL (25,6)=0,@TempDocID INT=0,@TempDocPrefix INT=0,@TempStatus INT=0,
@UpdateStatus INT,@TotAdjAmt DECIMAL (25,6)=0

--Move Data To Temp Variables
SELECT @TempDocID=DocID,@TempDocPrefix=DocPrefix,@TempBalance=Balance,@TotAdjAmt = TotalAmtAdj FROM #TempDetail WHERE DetailIdent=@TempDetailCount

-- Take Original Balance A.nd Original Status
-- Sales And SalesReturn
IF(@TempDocPrefix=15 OR @TempDocPrefix=16)
BEGIN
print ''Sales And SalesReturn''
IF(ISNULL(@nStatus,1) != 1)
BEGIN
SET @UpdateStatus = (SELECT COUNT(DocValue) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE DocValue IN (SELECT DocValue FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id = @TempDocID and DocPrefix = @TempDocPrefix))
UPDATE tblTranSalesHeader SET Balance = @TempBalance,
Status = (CASE WHEN @UpdateStatus = 1 THEN (CASE WHEN @TempDocPrefix = 15 THEN 1 ELSE 6 END) ELSE 3 END),CDate = GETDATE() WHERE Id = @TempDocID
END
SELECT @OriginalBalance=Balance,@TempStatus=[Status] FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id=@TempDocID
END
