SELECT @Balance=Balance FROM tblTranPaymentHeader WITH (READCOMMITTEDLOCK) WHERE PYID=@TempDocID
IF(@Balance=0.00)
BEGIN
UPDATE tblTranPaymentHeader SET [STATUS]=5 WHERE PYID=@TempDocID
END
END
--Payable Voucher And Receivable Voucher
IF(@TempDocPrefix=6 OR @TempDocPrefix=7)
BEGIN
UPDATE tblTranPRVoucher SET Balance=Balance-@TotalAmtAdj,CDate = GETDATE() WHERE ID=@TempDocID --Alter by SRIRAM ",MBy=@UID,MDate=GETDATE()"
SELECT @Balance=Balance FROM tblTranPRVoucher WITH (READCOMMITTEDLOCK) WHERE ID=@TempDocID
IF(@Balance=0.00)
BEGIN
UPDATE tblTranPRVoucher SET [STATUS]=5 WHERE ID=@TempDocID
END
END
END
ELSE
BEGIN
DECLARE @II1 INT = CONVERT(INT,@OriginalBalance)
DECLARE @II2 INT = CONVERT(INT,@TempBalance)
RAISERROR(''Document Amount Already changed $ %d $%d OB -%d TC -%d'',16,1,@TempDocPrefix,@TempDocID,@II1,@II2) --,@OriginalBalance,@TempBalance
END ENd

ELSE
BEGIN
RAISERROR(''Document Status Already changed $ %d $%d'',16,1,@TempDocPrefix,@TempDocID)
END
SET @TempDetailCount+=1
END

