IF(ISNULL(@Status,0) =1) OR (ISNULL(@Status,0) =3 OR ISNULL(@ImportStatus,0) =4)
BEGIN

IF(@nStatus = 1 OR @nStatus= 2)
BEGIN
IF((SELECT COUNT(DocValue) FROM tblTranPRVoucher WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and
DocDate BETWEEN @F_SD AND @F_ED and Status in (1,3,5) and TransID = @FormMode ) != 0)
BEGIN
RAISERROR(''Document ID already exists(%s)'',16,1,@DocId)
END
ENd

