@HSNorSACCode,@GrossAmt,@TaxID,@TaxPern,@TaxAmt,@TDSAmount,
case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,@RoundoffAmt,@BranchID)
