BEGIN
--Round Off Acount Negative Dr
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],
CBy ,CDate ,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )
VALUES (@JVID, @DocId, @FormMode, @DocValue,@DocDate ,@ReferNo ,82,0,ABS(@RoundoffAmt), 0,NULL,CASE WHEN @FormMode = 6 THEN ''Payable Voucher'' ELSE ''Receivable Voucher'' END,@Status,
@UID ,GETDATE (),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID )
--Customer Account Cr
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue ,BranchID)
VALUES ( @JVID,@DocId, @FormMode, @DocValue,@DocDate ,@ReferNo ,@PartyID,ABS(@RoundoffAmt),0,0,NULL,CASE WHEN @FormMode = 6 THEN ''Payable Voucher'' ELSE ''Receivable Voucher'' END,@Status,
@UID ,GETDATE (),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID )
END
END
--TDS Amount
IF ISNULL(@TDSAmount,0)>0
BEGIN
-- ''Discount Account''
INSERT INTO tblFAJournal([JVID],[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,
ClBy,ClDate,Adjusment,BranchID)
VALUES ( @JVID,@DocId, @FormMode, @DocValue,@DocDate ,@ReferNo ,12,0,ISNULL(@TDSAmount,0),0,NULL,@Narration,@Status,@UID ,GETDATE (),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue
,case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,0,@BranchID)
--Party Account
INSERT INTO tblFAJournal([JVID],[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,
ClBy,ClDate,Adjusment,BranchID)
VALUES ( @JVID,@DocId, @FormMode, @DocValue,@DocDate ,@ReferNo ,@PartyID,ISNULL(@TDSAmount,0),0,0,NULL,@Narration,@Status,@UID ,GETDATE (),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue
,case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,0,@BranchID)
END
--Noraml Reciable Voucher Discount Amount
IF ISNULL(@Discount,0)>0
BEGIN
SET @JVID=@JVID+1;
--Discount Account
INSERT INTO tblFAJournal([JVID],[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,
ClBy,ClDate,Adjusment,BranchID)
VALUES ( @JVID,@DocId, @FormMode, @DocValue,@DocDate ,@ReferNo ,30,0,ISNULL(@Discount,0),0,NULL,@Narration,@Status,@UID ,GETDATE (),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue
,case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,0,@BranchID)
--Party Account
INSERT INTO tblFAJournal([JVID],[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,
ClBy,ClDate,Adjusment,BranchID)
VALUES ( @JVID,@DocId, @FormMode, @DocValue,@DocDate ,@ReferNo ,@PartyID,ISNULL(@Discount,0),0,0,NULL,@Narration,@Status,@UID ,GETDATE (),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue
,case when isnull(@ImportStatus,0) = 0 then null else @UID end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,0,@BranchID)
END
END
END
ENd
--Cancel mode
ELSE IF(ISNULL(@Status,0) =4)
BEGIN
--Update Status Cancel (4) and Revert Posting
UPDATE tblTranPRVoucher SET [Status]=@Status,ClBy =@UID ,ClDate =GETDATE(),[Type]=@Type,Remarks = @Remarks,Narration = @Narration WHERE ID =@ID AND TransID =@FormMode
UPDATE tblFAJournal SET [Status] =@Status,ClBy =@UID ,ClDate =GETDATE(),Remarks = @Remarks,Narration = @Narration WHERE TransId =@ID AND DocPrefix =@FormMode
SELECT @ID
END
--Normal Voucher Create and Modify Time Get Transaction Id
IF ((ISNULL(@Type,0)=0 AND ISNULL(@Status,0) <>4) OR isnull(@ImportStatus,0) = 4)
BEGIN
SELECT @SCOPID
END

END TRY
BEGIN CATCH
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(),ERROR_LINE()
END CATCH',
N'[export] number-series-updlock=7;readcommittedlock=11';
GO
/****** uspManagePurchaseCancel ******/
EXEC #Apply07 N'dbo.uspManagePurchaseCancel', 0x6139F983339DAFC87F2CC8FE9ED48E8243C5017EAB1CDDD9B930E48A0D407808, NULL, NULL, 0xE591347B267967A4C0183E84A74D0FFC8CAE4FDF5350245727B63DDA511A6D2D, 0xB9E604D851F320AF6F1DA348C12D657D217EDC414EEC6306AE6EA0729F1E3C61, NULL,
N'ALTER PROC [dbo].[uspManagePurchaseCancel]                            
@PurchaseMode INT,@purchaseid INT,@Uid INT,@CurrentStatus SMALLINT,@Remarks NVARCHAR(255) = NULL,@Narration NVARCHAR(MAX) = NULL                              
AS                              
SET NOCOUNT ON;
BEGIN TRY                         
 --Purchase Cancel                           
 DECLARE @CheckStatus SMALLINT,@DocValue INT, @PreviousTranDate DATE                          
 SELECT @CheckStatus = [Status],@DocValue=DocValue,@PreviousTranDate=DocDate From tblPurchaseOrderHeader WITH (READCOMMITTEDLOCK) Where ID = @purchaseid                                   
 IF((@CheckStatus != @CurrentStatus) OR @CheckStatus IN (2,4))
 BEGIN                                        
  RAISERROR(''Status Already Changed'',16,1)                                       
 END                                        
 DECLARE @Qty INT                        
 -- Status to Change Cancel(4) Status                            
 UPDATE tblPurchaseOrderHeader SET [Status] =4,Clby =@UId ,Cldate =GETDATE(),Remarks = @Remarks,Narration = @Narration                             
 WHERE ID =@purchaseid              
               
  --Checking Purchase Order ID present in Automatic Indent              
 DECLARE @AiIDCount INT = (Select COUNT(*) from tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) where DocID IN          
 (SELECT DocID FROM tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE PoID=@purchaseid)        
 --AND (Date BETWEEN (SELECT F_SD FROM tblCompanyRegistration) AND (SELECT F_ED FROM tblCompanyRegistration))      
 )          
      
 UPDATE tblTransAutomaticIndentHeader SET [Status]= (CASE WHEN @AiIDCount = 1 THEN 1 else 3 END) WHERE PoID=@purchaseid          
                       
END TRY                            
BEGIN  CATCH                            
 SELECT ERROR_MESSAGE (),ERROR_PROCEDURE (),ERROR_LINE ();                            
END CATCH',
N'[export] nocount;readcommittedlock=3';
GO
/****** uspManagePurchaseDraft ******/
EXEC #Apply07 N'dbo.uspManagePurchaseDraft', 0xE8C1E48E43472C1758610C087F4EE38FC5E6F10B51D7C87CAC0F9EF579DF51E2, NULL, NULL, 0x790BB59DB3D3DC6A576A4BE32625B8E9A4AC1AEACBCAF3FE77A5BFCEC7E29DE8, 0x006A5EC92FE6000F14630225BDD5FDBC03569789AA270309A08DA756BC63154A, NULL,
N'ALTER PROC [dbo].[uspManagePurchaseDraft]--2000                                                           
(@Mode INT,@BillId INT = NULL,@BranchID INT = NULL,@nCurrStatus int,@BillDate DATE,@VendorId INT,@TotalGrossAmt DECIMAL (25,6),            
@TotalTaxAmt DECIMAL (25,6),@TotalNetAmt DECIMAL (25,6),@GRNRefNo NVARCHAR(255)=NULL,@PGroupID INT=NULL,@TaxTypeID INT,            
@PaymentTermId INT=NULL,@paymentDate NVARCHAR(25)=NULL,@PaymentModeId INT=NULL ,@vehicleno NVARCHAR(255)=NULL,            
@Frieght DECIMAL (25,6)= NULL,@OtherCharge DECIMAL(25,6)=NULL,@OtherChargeamt DECIMAL (25,6)=NULL,@ProdDisc DECIMAL(25,6)=NULL,                  
@TradeDisc DECIMAL(25,6)=NULL,@AddnlDisc DECIMAL(25,6)=NULL,@TotalProdDiscAmt DECIMAL (25,6)= NULL,@TotalTradeDiscAmt DECIMAL (25,6)= NULL,            
@TotalAddnlDiscAmt DECIMAL (25,6)= NULL,@WrightOffAmt DECIMAL (25,6)= NULL,@UID INT,@RoundOffAmt DECIMAL (25,6)= NULL,            
@tvpTranBillDetail AS [tvpTranBillDetail] READONLY,@tvpTranBillMop AS [tvpTranBillMop] READONLY,@UDFId INT =NULL ,@IFBIll SMALLINT=1,            
@nAllowNegativeBal INT=NULL,@IS_IMPORT INT=NULL,@DateBill DATE=NULL,@TCSPern DECIMAL(25,6) = NULL,@TCSAmt DECIMAL(25,6) = NULL,            
@TDSAmt DECIMAL(25,6) = NULL,@ImportStatus INT = 0,@Remarks NVARCHAR(25)=NULL,@Narration NVARCHAR(25)=NULL,@DraftID INT = 0  
,@DiffValueGross DECIMAL(25,4) = 0,@DiffValueNet DECIMAL(25,4) = 0)                    
AS                                                           
BEGIN TRY                                                           
SET DATEFORMAT dmy;            
SET NOCOUNT ON;            
DECLARE @AccId INT,@ScopeID INT                  
DECLARE @docvalue INT ,@Status INT,@DocID NVARCHAR(255),@GRNDocID NVARCHAR(255),@UDFDocId NVARCHAR(255),@UDFDocValue INT,            
@UDFDocPrefix NVARCHAR(255),@CheckUDFId INT            
DECLARE @CheckStatus INT,@DrDetbitNote DECIMAL(25,6)                  
IF(ISNULL(@DraftID,0) > 0)            
BEGIN            
exec uspValidateDraftData 1,1,@DraftID,@nCurrStatus  

UPDATE tblPurchaseDraftHeader SET Status = 2 WHERE ID = @DraftID            
END         
-----TDSamount value for Balance                                                   
Declare @TDSBalance decimal(25,4)            
IF ISNULL(@Mode,0)=1 OR ISNULL(@Mode,0)=2            
BEGIN            
Set @TDSBalance=(@TotalNetAmt-@TDSAmt)            
END                          
SET @TotalNetAmt = (ISNULL(@TotalNetAmt,0) )                                                          
--Insert bill header            
INSERT INTO tblPurchaseDraftHeader(Date,DocID,TransID,BranchID,DocValue,VENDorID,[Status],GrossAmt,TaxAmt,NetAmt,RefNo,ProdGroupID,TaxTypeID,PaymentTermID,PaymentDate,            
PaymentModeId, VehicleNo,Frieght,[OtherChargePern],OtherChargeAmt,[ProdDiscPern],[TradeDiscPern],[AddnlDiscPern],TotalProdDiscAmt,TotalTradeDiscAmt,            
TotalAddnlDiscAmt,WriteOffAmt,RoundOffAmt, Balance,OrgId,Cby,Cdate,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,TCSTaxPern,TCSTaxAmt,TDSAmount,  
Remarks,Narration,DiffValueGross,DiffValueNet)            
VALUES(@BillDate, @DocID,1 ,@BranchID,@docvalue,@VendorId,1,@TotalGrossAmt,@TotalTaxAmt,@TotalNetAmt,@GRNRefNo,@PGroupID,@TaxTypeID,            
@PaymentTermId,(CASE WHEN ISNULL(@paymentDate,'''')='''' THEN NULL ELSE @paymentDate END),@PaymentModeId,@vehicleno,@Frieght,@OtherCharge,            
@OtherChargeamt,@ProdDisc,@TradeDisc,@AddnlDisc,@TotalProdDiscAmt,@TotalTradeDiscAmt,@TotalAddnlDiscAmt,@WrightOffAmt,@RoundOffAmt,            
@TDSBalance,@BillId,@UID,GETDATE (),@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,            
@TCSPern,@TCSAmt,@TDSAmt,@Remarks,@Narration,@DiffValueGross,@DiffValueNet)                                                           
--Scope Indentity for Bill Header Table                                                           
            
SET @ScopeID=(SELECT SCOPE_IDENTITY())            
                     
--Variable declaration for Loop bill detail            
DECLARE @ProdID INT,@UOMID INT,@UomGrpID INT,@BatchNo NVARCHAR(255) = NULL,@PKD NVARCHAR(255) = NULL,@Expiry NVARCHAR(255) = NULL,@UomQty DECIMAL(25, 9) ,@UomFreeQty DECIMAL(25,9),                                                           
@UomDamageQty DECIMAL(25, 9) ,@PurchasePrice DECIMAL (25,6),@SalePrice DECIMAL (25,6),@ECP DECIMAL (25,6),@MRP DECIMAL (25,6),@SPLPrice DECIMAL (25,6),@TaxID INT,@BTaxTypeId INT,                                                           
@TaxPercentage DECIMAL (25,6),@GoodsAmt DECIMAL (25,6),@ProdDiscPercent DECIMAL (25,6) = NULL,@TradeDiscPercent DECIMAL (25,6) = NULL,@AddnlDiscPercent DECIMAL (25,6) = NULL,                                                           
@BGrossAmt DECIMAL (25,6),@BTaxAmt DECIMAL (25,6),@BNetAmt DECIMAL (25,6),@InvId INT,@InclusiveYesNo INT,@IsChrgProd INT = 0                   
,@ReturnPrice DECIMAL (25,6),@InvScopeID INT = 0,@LocationID INT,@DiffAmt DECIMAL (25,4) = 0    
--Loop Detail using CURSOR                                                           
DECLARE @PKDDate DATE,@ExpiryDate DATE                                                           
DECLARE @PriceOnUomCF DECIMAL (25,6),@MRPOnUomCF DECIMAL (25,6),@SelectedUomCF DECIMAL (25,6),              
@Qty DECIMAL(25, 9),@FreeQty DECIMAL(25, 9),@DamageQty  DECIMAL(25, 9)                 
DECLARE @PUomId INT,@MRPUomId INT,@TrackPKD INT                  
DECLARE @InventoryID INT =0                  
DECLARE cursor_Temp CURSOR LOCAL FAST_FORWARD FOR (SELECT [ProdID] ,[UOMID],[UomGrpID],[BatchNo] ,[PKD] ,[Expiry], [Qty] , [FreeQty] , [DamageQty],                                                           
[PurchasePrice],[SalePrice] ,[ECP] ,[MRP] ,[SPLPrice] , [TaxID] ,[TaxTypeId] ,[TaxPercentage] ,[GoodsAmt] ,[ProdDiscPercent],                                                           
[TradeDiscPercent], [AddnlDiscPercent],[GrossAmt] ,[TaxAmt],[NetAmt] ,[InventoryId],InclusiveYesNo,ReturnPrice,UOMCR    
,LocationID,DiffAmt FROM @tvpTranBillDetail)                                                           
OPEN cursor_Temp                                                           
FETCH NEXT FROM cursor_Temp INTO @ProdID , @UOMID ,@UomGrpID ,@BatchNo ,@PKD ,@Expiry ,@UomQty ,                                           
@UomFreeQty,@UomDamageQty ,@PurchasePrice ,@SalePrice ,@ECP ,@MRP ,@SPLPrice ,@TaxID ,@BTaxTypeId ,@TaxPercentage ,                                                           
@GoodsAmt ,@ProdDiscPercent ,@TradeDiscPercent ,@AddnlDiscPercent ,@BGrossAmt ,@BTaxAmt ,@BNetAmt ,@InvId ,@InclusiveYesNo,                  
@ReturnPrice,@SelectedUomCF,@LocationID,@DiffAmt      
DECLARE @GTaxAmt DECIMAL (25,6),@InclMRP DECIMAL (25,6)                                                           
--SET @GTaxAmt =( @MRP * @TaxPercentage /100)                                                           
--SET @InclMRP = (@MRP + @GTaxAmt)                                                           
              
DECLARE @BillDetailSerial INT = 1                                                           
WHILE @@FETCH_STATUS =0                                                           
BEGIN                                                           
            
--Get Price On,MRP ON from Product Table                                                           
SELECT @PUomId=PurchaseUomID,@PriceOnUomCF=PurchaseCR,@TrackPKD = TrackPDK--,@IsChrgProd = (CASE WHEN TrackInventory = 0 AND ChargesPern > 0 THEN 1 ELSE 0 END)                   
FROM tblMasterProduct WITH (READCOMMITTEDLOCK) WHERE ID =@ProdID                                   
      
--SELECT * FROM tblPurchaseDraftDetail ORDER BY 1 DESC      
INSERT INTO tblPurchaseDraftDetail(HID,ProdID,UOMID,BatchNo,PKD,Expiry,UomQty,UomFreeQty,UomDamageQty,                                                           
UomPurchasePrice, UomSalePrice,UomECP,UomMRP,UomSPLPrice,UomReturnPrice,PurchasePrice,SalePrice,ECP,MRP,SPLPrice,ReturnPrice,                                                           
TaxID,TaxPern,GoodsAmt,ProdDiscPern,TradeDiscPern,AddnlDiscPern, GrossAmt,TaxAmt,NetAmt,Serial,UOMCF,LocationID,DiffAmt)                            
VALUES                                                           
(@ScopeID,@ProdID ,@UOMID,@BatchNo,@PKDDate,@ExpiryDate,@UomQty , @UomFreeQty , @UomDamageQty,                                                           
@PurchasePrice,@SalePrice,@ECP, @MRP,@SPLPrice,ISNULL((@ReturnPrice) ,0),ISNULL((@PurchasePrice / @SelectedUomCF ),0),ISNULL((@SalePrice / @SelectedUomCF) ,0),                                            
ISNULL((@ECP / @SelectedUomCF) ,0),ISNULL((@MRP) ,0),ISNULL((@SPLPrice / @SelectedUomCF) ,0),ISNULL((@ReturnPrice) ,0),             
@TaxID,@TaxPercentage,@GoodsAmt , @ProdDiscPercent,@TradeDiscPercent,@AddnlDiscPercent,@BGrossAmt,@BTaxAmt,@BNetAmt,                                                           
@BillDetailSerial,@SelectedUomCF,@LocationID,@DiffAmt )                  
                                                           
SET @BillDetailSerial = @BillDetailSerial + 1                                                           
                                                       
FETCH NEXT FROM cursor_Temp INTO @ProdID , @UOMID ,@UomGrpID ,@BatchNo ,@PKD ,@Expiry ,@UomQty ,@UomFreeQty,@UomDamageQty ,                  
@PurchasePrice ,@SalePrice ,@ECP ,@MRP ,@SPLPrice ,@TaxID ,@BTaxTypeId ,@TaxPercentage ,@GoodsAmt ,@ProdDiscPercent ,                  
@TradeDiscPercent ,@AddnlDiscPercent ,@BGrossAmt ,@BTaxAmt ,@BNetAmt ,@InvId ,@InclusiveYesNo ,@ReturnPrice,@SelectedUomCF,@LocationID,@DiffAmt                                                           
END                                                           
CLOSE cursor_Temp                                                           
DEALLOCATE cursor_Temp                                                           
              
SELECT @ScopeID AS IdentId                                                             
END TRY                                                           
BEGIN CATCH                                                           
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE()                                                           
END CATCH',
N'[export] cursor-local-fast_forward=1;readcommittedlock=1';
GO
/****** uspManagePurchaseOrder ******/
EXEC #Apply07 N'dbo.uspManagePurchaseOrder', 0xC60FD98E67965C6D68A814A4F90E2D36DE0364052BF59D5CCCDA6AED87CC2AB6, NULL, NULL, 0xC1AE899D576896545B74AF4925DD514E6B0818ABD6498D07171F7661AE393497, 0xBD2C0ACD76AB6AEB59136237F5A0D869C5162E61ABF12A8CD74E610EC4BC1A06, NULL,
N'ALTER PROCEDURE [dbo].[uspManagePurchaseOrder]              
@tvpOrder AS [tvpPurchaseOrder] READONLY,@Mode INT,@PurchaseID INT,@BranchID int ,@CurrentStatus INT,@Docdate Date,@VendID INT,              
@refNo NVARCHAR(255)=Null,@taxtypeID INT = null,@roundOff DECIMAL (25,6) =null,@TotalgrossAmt DECIMAL (25,6)=null ,@totalTaxAmt DECIMAL (25,6)=null,              
@TotalNetAMt DECIMAL (25,6) =null ,@udfid INT = null,@Remarks NVARCHAR (255)=null,@Narration NVARCHAR (255)=null,@cby NVARCHAR(255) =null ,              
@DraftID INT = 0,@UOMType INT = 0,@FromIndent INT=NULL,@ImportStatus INT = 0,@UDNDocID_Import NVARCHAR(255)=NULL,@FilterType INT = 1    
AS              
BEGIN              
BEGIN TRY              
--BEGIN TRAN              
SET NOCOUNT ON;              
SET DATEFORMAT DMY              
DECLARE @udfDocId NVARCHAR(255)=null, @udfDocValue NVARCHAR(255)=null,@UdfDocPrefix NVARCHAR(255) =null,@TempAIID int              
, @DocPrefix NVARCHAR(255)=NULL, @DocValue NVARCHAR(255)=null, @DocId NVARCHAR(255)=null, @CDate DATE =NULL, @scopeID INT, @CheckStatus INT              
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)                            
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)                   
      declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))                    
      DECLARE @DocSeriesIdent int              
--Mode insert              
IF @Mode = 1 OR @Mode = 5 OR @Mode =3              
BEGIN              
if(@mode = 1)              
BEGIN      
      
SET @TempAIID = @PurchaseID              
SET @PurchaseID = 0       
IF(ISNULL(@DraftID,0) > 0 and isnull(@FilterType,0) = 2)--Validate draft      
BEGIN              
exec uspValidateDraftData 1,3,@DraftID,@CurrentStatus           
END       
IF(ISNULL(@FilterType,0) = 3 and isnull(@TempAIID,0) > 0)--Validate Auto Indent         
BEGIN              
select @CheckStatus = Status from tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE ID = @TempAIID       
if((@CheckStatus != @CurrentStatus) OR @CheckStatus IN (2,4))      
begin      
RAISERROR (''This Document status already changed'',16,1)                          
end      
      
END        
END              
IF @Mode =5 OR @Mode =3              
BEGIN              
SELECT @CheckStatus = [Status] FROM tblTransAutomaticIndentHeader WITH (READCOMMITTEDLOCK) WHERE ID = @FromIndent              
--SELECT * FROM tblTranAutomaticIndentHeader WHERE AIID =448              
IF((@CheckStatus != @CurrentStatus)  OR @CheckStatus IN (2,4))              
BEGIN              
RAISERROR(''Document status already changed'',16,1)              
END              
END              
insert into @tblDocdetails              
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate) and BranchID = @BranchID and TransID = 3              
 IF((select count(*) from @tblDocdetails) = 0)                          
   BEGIN                          
    RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)                          
   END                   
              
   SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails              
            
UPDATE tblYearwiseDocumentSeries SET DocValue =  @DocValue + 1 WHERE TransID = 3 and ID = @DocSeriesIdent             
--SELECT @DocValue = DocValue,@DocId = DocPrefix+CONVERT(NVARCHAR(10),DocValue) FROM dbo.tblDocumentSeries WHERE TransID = 3              
--UPDATE tblDocumentSeries SET DocValue = DocValue+1 WHERE TransID = 3              
IF ISNULL(@udfid,0)>0              
BEGIN              
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@udfid              
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@udfid              
END              
ELSE              
BEGIN              
IF @Mode = 1 OR @Mode = 3              
BEGIN              
DECLARE @UDFCount INT,@UDNSingle INT        
IF ISNULL(@UDFId,0)=0 AND ISNULL(@UDNDocID_Import,'''')!='''' -- IMPORT              
BEGIN              
DECLARE @CHECKUDFDOCID NVARCHAR(255) = LEFT(@UDNDocID_Import, PATINDEX(''%[A-Z][^A-Z]%'', @UDNDocID_Import))+CONVERT(NVARCHAR,              
CONVERT(INT,RIGHT(@UDNDocID_Import, LEN(@UDNDocID_Import) - (PATINDEX(''%[A-Z][^A-Z]%'', @UDNDocID_Import)))))              
IF((SELECT COUNT(*) FROM tblPurchaseOrderHeader WITH (READCOMMITTEDLOCK) WHERE UDFDocId = @CHECKUDFDOCID) > 0)              
BEGIN              
RAISERROR(''10'',16,1)              
END              
DECLARE @SALES_UDFDocValue INT,@SALES_UDFDocPrefix NVARCHAR(255),@SALES_UDNID INT,@SALES_CHKCOUNT INT              
              
SELECT @SALES_UDFDocPrefix = LEFT(@UDNDocID_Import, PATINDEX(''%[A-Z][^A-Z]%'', @UDNDocID_Import)),              
@SALES_UDFDocValue = RIGHT(@UDNDocID_Import, LEN(@UDNDocID_Import) - (PATINDEX(''%[A-Z][^A-Z]%'', @UDNDocID_Import)))              
              
SET @SALES_CHKCOUNT = (SELECT COUNT(UDNId) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE DocPrefix = @SALES_UDFDocPrefix AND TransId = 3)              
SET @SALES_UDNID = (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE DocPrefix = @SALES_UDFDocPrefix AND TransId = 3)              
IF ISNULL(@SALES_CHKCOUNT,0)=0              
BEGIn              
INSERT INTO tblMasterUserDefineNoHeader (TransId,DocName,DocPrefix,DocValue,CBy,CDate) VALUES              
(3,@SALES_UDFDocPrefix,@SALES_UDFDocPrefix,1,@cby,CONVERT(DATE,GETDATE()))              
SET @SALES_UDNID = SCOPE_IDENTITY()              
INSERT INTO tblMasterUserDefineNoDetail (UDNId,UserId) VALUES (@SALES_UDNID,@cby)              
END              
UPDATE tblMasterUserDefineNoHeader SET DocValue = @SALES_UDFDocValue WHERE UDNId = @SALES_UDNID              
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)              
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@SALES_UDNID              
SET @UDFId = @SALES_UDNID              
END              
ELSE              
BEGIN              
SET @UDFCount = (              
SELECT COUNT(DISTINCT UDNId) FROM tblMasterUserDefineNoDetail WITH (READCOMMITTEDLOCK)              
WHERE UDNId IN (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE TransId=3) AND UserId=@cby              
)              
IF ISNULL(@UDFCount,0)=1              
BEGIN              
SET @UDNSingle = (SELECT DISTINCT UDNId FROM tblMasterUserDefineNoDetail WITH (READCOMMITTEDLOCK) WHERE UDNId IN (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE TransId=3)AND UserId=@cby )              
END              
SELECT @udfid=UDNId,@UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)              
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE TransId=3 AND UDNId=@UDNSingle              
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId=@UDNSingle              
END        
END        
END        
        
IF((SELECT COUNT(DocValue) FROM tblPurchaseOrderHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and        
DocDate BETWEEN @F_SD AND @F_ED and TransID = 3) != 0)-- and Status in (3,4,5,6)        
BEGIN        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)        
END        
        
--Header INSERT        
INSERT INTO tblPurchaseOrderHeader(DocDate,DocID,TransID,DocValue,VendorID,BranchID,RefNo,TaxTypeID,GrossAmt,TaxAmt,NetAmt,RoundoffAmt,UDFId,UDFDocID,              
UDFDocPrefix,UDFDocValue,Narration,Cby,CDate,Status,Clby,Cldate,Remarks,UomType)              
Values (@Docdate,@DocID,3,@DocValue,@VendID,@BranchID,@refNo,@taxtypeID,@TotalgrossAmt,@totalTaxAmt,@TotalNetAMt,              
@roundOff,@udfid,@udfDocId,@UdfDocPrefix,@udfDocValue,@Narration,@cby,GETDATE() ,case when isnull(@ImportStatus,0) = 0 then 1 else @ImportStatus end,              
case when isnull(@ImportStatus,0) = 0 then null else @cby end,case when isnull(@ImportStatus,0) = 0 then null else GETDATE() end,@Remarks,@UomType)              
SET @scopeID = SCOPE_IDENTITY();              
              
-- This is from frmAutomaticIndent Check Generate PO    
-- Added by Sriram G              
IF ISNULL(@FromIndent,0)!=0              
BEGIN              
UPDATE tblTransAutomaticIndentHeader SET status=5,PoID=@scopeID WHERE ID=@FromIndent              
END              
              
END              
IF @Mode =2              
BEGIN              
DECLARE @CheckUDFId INT              
SELECT @CheckStatus = [Status],@CheckUDFId=UDFId FROM tblPurchaseOrderHeader WITH (READCOMMITTEDLOCK) WHERE iD = @PurchaseID              
IF((@CheckStatus != @CurrentStatus) OR @CheckStatus IN (2,4))
BEGIN              
RAISERROR(''Document status already changed'',16,1)              
END              
        
IF((SELECT COUNT(DocValue) FROM tblPurchaseOrderHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and        
DocDate not BETWEEN @F_SD AND @F_ED and TransID = 3) != 0)-- and Status in (3,4,5,6)        
BEGIN        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)        
END        
        
UPDATE tblPurchaseOrderHeader SET Status=2,Mby=@cby,Mdate=GETDATE() WHERE iD = @PurchaseID              
DECLARE @DocIDemodify NVARCHAR(255)              
DECLARE @DocPrefixemodify NVARCHAR(255)              
DECLARE @Docvaluemodify NVARCHAR(255)              
SELECT @DocIDemodify=DocId,@DocPrefixemodify=TransID,@Docvaluemodify=DocValue FROM tblPurchaseOrderHeader WITH (READCOMMITTEDLOCK) where iD = @PurchaseID              
              
IF ISNULL(@UDFId,0)>0              
BEGIN              
IF(@UDFId=@CheckUDFId)              
BEGIN            
SELECT @UDFDocValue=UDFDocValue, @UDFDocId=UDFDocId,@UDFDocPrefix=UDFDocPrefix              
FROM tblPurchaseOrderHeader WITH (READCOMMITTEDLOCK) WHERE iD = @PurchaseID              
END              
ELSE IF(@UDFId!=@CheckUDFId)              
BEGIN              
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)              
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK)              
WHERE UDNId=@UDFId              
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@UDFId              
END              
END              
-----------------Purchase Order------INSERT--------------              
INSERT INTO tblPurchaseOrderHeader(DocDate,DocId,TransID,DocValue,VendorID,BranchID,RefNo,TaxTypeID,GrossAmt,TaxAmt,NetAmt,RoundoffAmt,UDFId,UDFDocID,              
UDFDocPrefix,UDFDocValue,Narration,Cby,CDate,Status,Remarks,UomType)              
Values (@Docdate,@DocIDemodify,@DocPrefixemodify,@Docvaluemodify,@VendID,@BranchID,@refNo,@taxtypeID,@TotalgrossAmt,@totalTaxAmt,@TotalNetAMt,              
@roundOff,@udfid,@udfDocId,@UdfDocPrefix,@udfDocValue,@Narration,@cby,GETDATE() ,3,@Remarks,@UomType)              
SET @scopeID =SCOPE_IDENTITY();              
END              
-----Detail Insert              
DECLARE @serial INT              
DECLARE @NCountSerial INT              
DECLARE @ProdId INT,@nUomID INT,@nTaxId INT,@Inventoryid INT,@UomCR DECIMAL(25,4) = 1              
DECLARE @status INT              
SET @NCountSerial = (SELECT COUNT(*) FROM @tvpOrder)              
SET @serial =1              
DECLARE @Qty DECIMAL (25,6),@PPRice DECIMAL (25,6),@TaxPer DECIMAL (25,6),@nGrossAmt DECIMAL (25,6),@nTaxAmt DECIMAL (25,6),@nNetAmt DECIMAL (25,6)              
WHILE @NCountSerial >0              
BEGIN              
              
SELECT @ProdId =ProdId,@nUomID = UomID,@PPRice = PurchasePrice,@Qty = Qty,@TaxPer =TaxPercentge,@nTaxAmt =TaxAmt,@nGrossAmt =GrossAmt,              
@nNetAmt = NetAmt,@nTaxId = TaxId,@Inventoryid =InventoryId,@UomCR = UomCR              
FROM @tvpOrder WHERE Serial= @serial              
              
INSERT INTO tblPurchaseOrderDetail(HID,ProdID,PurchasePrice,Qty,UomID,TaxID,TaxPern,GrossAmt,TaxAmt,NetAmt,Serial,UomCR)              
Values(@scopeID,@ProdId,@PPRice,@Qty,@nUomID,@nTaxId,@TaxPer,@nGrossAmt,@nTaxAmt,@nNetAmt,@serial,@UomCR)              
SET @serial = @serial+1;              
SET @NCountSerial = @NCountSerial -1;              
SELECT @scopeID              
--COMMIT TRAN              
END             
IF(ISNULL(@DraftID,0) > 0)              
BEGIN              
UPDATE tblPurchaseDraftHeader SET Status = 8,MBy = @cby,MDate = GETDATE() WHERE ID = @DraftID              
END              
IF(ISNULL(@TempAIID,0) > 0)              
BEGIN              
UPDATE tblTransAutomaticIndentHeader SET Status = 5,PoID = @scopeID WHERE ID = @TempAIID              
END              
END TRY              
BEGIN CATCH              
--ROLLBACK TRAN              
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(),ERROR_LINE()              
END CATCH              
END',
N'[export] number-series-updlock=9;readcommittedlock=12';
GO
/****** uspManageQuatation ******/
EXEC #Apply07 N'dbo.uspManageQuatation', 0x6BD4F63FC4C4F4DD87B260AF88E87BB6EE4D2CF55D47FC8CD8EFC760BCA2B9EC, NULL, NULL, 0x79B43D60770D3041D932E5B3AC01EE99EFB68A94B08FA91EB29BF2E166C04BAB, 0x8A905E13D47148EEE7E35567B9CDF62EA6C69D7A0CEB1FDD85CB536839D40214, NULL,
N'ALTER PROC [dbo].[uspManageQuatation]                    
@tvpTranSaleDetail AS [tvpTranSaleDetail] READONLY,@Mode INT,@ID int = null,@DocDate date = null,                
@DocPrefix tinyint = null,@BranchID smallint = null,@CustomerID int = null,@RefNo nvarchar(255) = null,                
@PriceID tinyint = null,@TaxTypeID tinyint = null,@TradeDiscPern decimal(25, 4) = null,@TradeDiscAmt decimal(25, 4) = null,                
@AddnlDiscPern decimal(25, 4) = null,@AddnlDiscAmt decimal(25, 4) = null,@OtherChargePern decimal(25, 4) = null,                
@OtherChargeAmt decimal(25, 4) = null,@FrightAmt decimal(25, 4) = null,@TotalProdDiscAmt decimal(25, 4) = null,                
@TotalDiscAmt decimal(25, 4) = null,@GrossAmt decimal(25, 4) = null,@TaxAmt decimal(25, 4) = null,@NetAmt decimal(25, 4) = null,                
@RoundOffAmt decimal(25, 4) = null,@Status tinyint = null,@UDFId smallint = null,@CBy smallint = null,@Remarks nvarchar(MAX) = null,              
@Narration nvarchar(MAX) = null,@DraftID INT = NULL,@CurrentStatus INT = NULL,@BeatID smallint = 0,@SalesmanID smallint = 0                
AS                    
BEGIN TRY                    
SET NOCOUNT ON;                    
SET DATEFORMAT DMY;                    
DECLARE @strudfDocId NVARCHAR(255)=null,@strudfDocValue NVARCHAR(255)=null,@strUdfDocPrefix NVARCHAR(255) =null,@strDocPrefix NVARCHAR(255)=NULL                    
,@strDocValue NVARCHAR(255)=null,@strDocId NVARCHAR(255)=null,@CDate DATE =NULL,@scopeID INT,@CheckStatus INT                   
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)                        
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)               
      declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))                
      DECLARE @DocSeriesIdent int           
IF @Mode = 3                    
BEGIN                 
SET @Mode = 1;              
END              
--Mode insert                    
IF @Mode = 1                    
BEGIN  
IF(ISNULL(@DraftID,0) > 0)                  
BEGIN                  
exec uspValidateDraftData 1,14,@DraftID,@CurrentStatus   
END    
insert into @tblDocdetails          
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate) and BranchID = @BranchID and TransID = 14         
 IF((select count(*) from @tblDocdetails) = 0)                      
   BEGIN                      
    RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)                      
   END               
          
   SELECT @strDocValue = DocValue,@strDocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails          
        
UPDATE tblYearwiseDocumentSeries SET DocValue =  @strDocValue + 1 WHERE TransID = 14 and ID = @DocSeriesIdent         
--SELECT @strDocValue = DocValue,@strDocId = DocPrefix+CONVERT(NVARCHAR(10),DocValue)                    
--FROM dbo.tblDocumentSeries WHERE TransID = 14                    
--UPDATE tblDocumentSeries SET DocValue = DocValue+1 WHERE TransID = 14                
IF ISNULL(@UDFId,0)>0                    
BEGIN                    
SELECT @strUDFDocValue=DocValue,@strUDFDocPrefix=DocPrefix,@strUDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)                    
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId                    
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@UDFId                    
END                    
END                    
--Modify                    
ELSE IF @Mode =2                    
BEGIN                    
DECLARE @CheckUDFId INT                    
SELECT @CheckStatus = [Status] ,@CheckUDFId=UDFId,@strDocValue=DocValue ,@strDocId=DocId                    
FROM tblQuotationHeader WITH (READCOMMITTEDLOCK) WHERE ID = @ID                    
IF((@CheckStatus != @CurrentStatus) OR @CheckStatus IN (2,4))
BEGIN                    
RAISERROR(''Document status already changed'',16,1)                    
END       
UPDATE tblQuotationHeader SET Status = 2,Mby=@cby,Mdate=GETDATE() WHERE ID = @ID                    
                    
IF ISNULL(@UDFId,0)>0                    
BEGIN                    
IF(@UDFId=@CheckUDFId)                    
BEGIN                    
SELECT @strUDFDocValue=UDFDocValue, @strUDFDocId=UDFDocId,@strUDFDocPrefix=UDFDocPrefix
FROM tblQuotationHeader WITH (READCOMMITTEDLOCK) WHERE ID = @ID                    
END                    
ELSE IF(@UDFId!=@CheckUDFId)                    
BEGIN                    
SELECT @strUDFDocValue=DocValue,@strUDFDocPrefix=DocPrefix,@strUDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)                    
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId                    
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@UDFId                    
END                    
END                    
END                    

IF(@Mode = 1)               
BEGIN                        
IF((SELECT COUNT(DocValue) FROM tblQuotationHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @strDocId and         
DocDate BETWEEN @F_SD AND @F_ED and DocPrefix = 14) != 0)-- and Status in (3,4,5,6)    
BEGIN                        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@strDocId)                         
END                        
ENd         
IF(@Mode = 2)               
BEGIN                        
IF((SELECT COUNT(DocValue) FROM tblQuotationHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @strDocId and         
DocDate not BETWEEN @F_SD AND @F_ED and DocPrefix = 14) != 0)-- and Status in (3,4,5,6)    
BEGIN                        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@strDocId)                         
END                        
ENd       
--Header INSERT                    
INSERT INTO tblQuotationHeader (DocDate,DocId,DocPrefix,DocValue,BranchID,CustomerID,RefNo,PriceID,TaxTypeID,TradeDiscPern,TradeDiscAmt,                
AddnlDiscPern,AddnlDiscAmt,OtherChargePern,OtherChargeAmt,FrightAmt,TotalProdDiscAmt,TotalDiscAmt,GrossAmt,TaxAmt,NetAmt,RoundOffAmt,                
Status,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CBy,CDate,Remarks,Narration)                    
Values (@DocDate,@strDocId,@DocPrefix,@strDocValue,@BranchID,@CustomerID,@RefNo,@PriceID,@TaxTypeID,@TradeDiscPern,@TradeDiscAmt,@AddnlDiscPern,                
@AddnlDiscAmt,@OtherChargePern,@OtherChargeAmt,@FrightAmt,@TotalProdDiscAmt,@TotalDiscAmt,@GrossAmt,@TaxAmt,@NetAmt,@RoundOffAmt,                
CASE WHEN ISNULL(@Mode,0) = 1 THEN 1 ELSE 3 END,@UDFId,@strUDFDocId,@strUdfDocPrefix,@strUDFDocValue,@CBy,getdate(),@Remarks,@Narration)                    
SET @scopeID = SCOPE_IDENTITY();                    
--Detail Insert                    
DECLARE @serial INT,@NCountSerial INT,@ProdId INT,@UomGrpId INT,@nUomID INT,@nTaxId INT                    
SET @NCountSerial = (SELECT COUNT(*) FROM @tvpTranSaleDetail)                    
SET @serial =1                    
DECLARE @Qty DECIMAL (25,6),@PPRice DECIMAL (25,6),@TaxPer DECIMAL (25,6), @dGoodsAmt DECIMAL(25,6),@dProdDiscPern DECIMAL(25,6),@dTradeDiscAmt DECIMAL(25,6),@dAddnlDiscAmt DECIMAL(25,6),                    
@nGrossAmt DECIMAL (25,6),@nTaxAmt DECIMAL (25,6),@nNetAmt DECIMAL (25,6),@MRP DECIMAL(25,6),@dProdDiscAmt DECIMAL(25,6),@dTradeDiscPern DECIMAL(25,6),@dAddnlDiscPern DECIMAL(25,6)                    
WHILE @NCountSerial >0                    
BEGIN                    
SELECT @ProdId =ProdId,@nUomID = UomID,@PPRice = BaseUomPrice,@Qty = UomQty,@TaxPer =TaxPercentage,@nTaxAmt =TaxAmt,@dGoodsAmt=GoodsAmt,                    
@dProdDiscPern=ProdDisc,@dTradeDiscAmt=TradeDisc,@dAddnlDiscAmt=AddnlDisc, @nGrossAmt=GrossAmt,@nNetAmt=NetAmt,@nTaxId=TaxId,                    
@MRP = MRP,@dProdDiscAmt=ProdDiscAmt,@dTradeDiscPern=TradeDiscPern,@dAddnlDiscPern=AddnlDiscPern                    
FROM @tvpTranSaleDetail WHERE Serial= @serial                    
--Insert Detail Table                    
INSERT INTO tblQuotationDetail(QuationID,ProdID,SalesPrice,Qty,UomID,TaxID,TaxPercentage,GoodsAmt,ProdDiscPern,TradeDiscAmt,AddnlDiscAmt,                    
GrossAmt,TaxAmt,NetAmt,Serial,DetailMRP,ProdDiscAmt,TradeDiscPern,AddnlDiscPern)                    
VALUES(@scopeID,@ProdId,@PPRice,@Qty,@nUomID,@nTaxId,@TaxPer,@dGoodsAmt,@dProdDiscPern,@dTradeDiscAmt,@dAddnlDiscAmt,                    
@nGrossAmt,@nTaxAmt,@nNetAmt,@serial,@MRP,@dProdDiscAmt,@dTradeDiscPern,@dAddnlDiscPern)                    
SET @serial = @serial+1;                    
SET @NCountSerial = @NCountSerial -1;                    
END                    
IF(ISNULL(@DraftID,0) > 0)                  
BEGIN                  
UPDATE tblSalesDraftHeader SET Status = 8,MBy = @CBy,MDate = GETDATE() WHERE ID = @DraftID                  
END               
SELECT @scopeID                    
END TRY                    
BEGIN CATCH                    
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(),ERROR_LINE()                    
END CATCH',
N'[export] number-series-updlock=3;readcommittedlock=6';
GO
/****** uspManageReports ******/
EXEC #Apply07 N'dbo.uspManageReports', 0xF4A4771EB811E7E3E9C513FE284A656CAF737E30B0C1C4A50F913FC65FDDFD46, NULL, NULL, 0x4DE035D391736DC0712F785B80835726678C16160C7CF235E374AC0CEEE6102D, 0xC504FB3D76F645B1677064D62D7221BAB82570991E26FDACC719A5D0F6002916, NULL,
N'ALTER proc [dbo].[uspManageReports]                                        
@Mode INT,@ReportID INT = NULL,@ALName NVARCHAR(255) = NULL                                                        
AS                                                        
SET NOCOUNT ON;
BEGIN                                                        
IF(@Mode = 0)                                                        
BEGIN                                                        
select * from tblReportViewer WHERE ReportID = @ReportID                                                   
END                                                   
IF(@Mode = 1)                                                        
BEGIN                                                        
select * from tblParameterInfo WHERE ReportID = @ReportID order by ParamOrder                                                        
END                                                        
IF(@Mode =2 )                                                        
BEGIn                                                        
IF(@ALName = ''BankName'')                                                        
BEGIN                                                        
SELECT ID,Name FROM tblMasterBank ORDER BY Name                                                        
END                                                        
IF(@ALName = ''UserName'')                                                        
BEGIN                                       
select 0 ID,''-- Select --'' Name                                      
union all                                      
SELECT ID,UserName Name FROM tblUsers WHERE ID > 1 ORDER BY Name                                                        
END                                                        
IF(@ALName = ''CustomerName'')                                                        
BEGIN                                                        
SELECT ID,Name Name FROM tblMasterCustomer ORDER BY Name                                                        
END                                 
IF(@ALName = ''VendorName'')                                                        
BEGIN                                                        
SELECT ID,Name Name FROM tblMasterVendor ORDER BY Name                                                        
END                            
IF(@ALName = ''BeatName'')                                                        
BEGIN                                                        
SELECT ID,Name FROM tblMasterBeat ORDER BY Name                                                        
END                                                        
IF(@ALName = ''SalesmanName'')                                                        
BEGIN          
SELECT ID,Name FROM tblMasterSalesman ORDER BY Name                                                        
END            
IF(@ALName = ''SalesmanNameDD'')                                                        
BEGIN          
SELECT 0 ID,''-- Select --'' Name          
union          
SELECT ID,Name FROM tblMasterSalesman ORDER BY Name                                                        
END           
IF(@ALName = ''SalesmanGroupName'')                                                        
BEGIN                                                        
SELECT ID,Name FROM tblMasterSalesmanGroup ORDER BY Name                                                        
END                                                        
IF(@ALName = ''ProductName'')                                                        
BEGIN                                                        
SELECT ID,Name FROM tblMasterProduct ORDER BY Name                                                        
END                                                        
IF(@ALName = ''ManufName'')                                                        
BEGIN                                                        
SELECT ID,Name FROM tblMasterManufacturer ORDER BY Name                                                        
END                                            
IF(@ALName = ''BrandName'')                                                        
BEGIN                                                        
SELECT ID,Name FROM tblMasterBrand ORDER BY Name                                        
END                                                        
IF(@ALName = ''CategoryName'')                                             
BEGIN                                                        
SELECT ID,Name FROM tblMasterCategory ORDER BY Name                                                        
END                                                        
IF(@ALName = ''AccountName'')                                                        
BEGIN                                                        
SELECT FAID ID,AccountName Name FROM tblFAAccount ORDER BY AccountName                                                        
END                     
IF(@ALName = ''BranchName'')                                                        
BEGIN                                                        
select 0 ID,''-- Select --'' Name                                      
union all                                      
SELECT ID,Name Name FROM tblMasterBranchOffice ORDER BY Name                                                  
END                          
IF(@ALName = ''BranchNameAL'')                                                        
BEGIN                            
SELECT ID,Name Name FROM tblMasterBranchOffice ORDER BY Name                                                        
END                               
IF(@ALName = ''AnaProdCustRepType'')                                 
BEGIN                                                        
SELECT 1 ID,''Customer wise'' Name union select 2 ID,''Product wise'' Name                                                      
END                                                        
IF(@ALName = ''AnaProdCustValueType'')                                                        
BEGIN                                                        
SELECT 1 ID,''Net Amount'' Name union select 2 ID,''Gross Amount'' Name union select 3 ID,''Qty'' Name                                                      
END                                                        
IF(@ALName = ''TransStatus'')                                                        
BEGIN                                                        
SELECT 0 ID,''All Status'' Name FROM tblStatus where ID in (1,2,4) and Active = 1                                     
UNION                                                    
SELECT ID,Description FROM tblStatus where ID in (1,2,4) and Active = 1                    
END                    
IF(@ALName = ''MobileTransStatus'')                                                        
BEGIN                                                        
SELECT 0 ID,''All Status'' Name                                
UNION                                                    
SELECT ID,Description FROM tblStatus where ID in (1,4,8) and Active = 1                    
END                      
IF(@ALName = ''QtyType'')                                                        
BEGIN                                                        
SELECT 1 ID,''Stock Only'' Name union select 2 ID,''All'' Name                                          
END   
IF(@ALName = ''QtyValue'')                                                        
BEGIN                                                        
SELECT 1 ID,''Qty'' Name union select 2 ID,''Value'' Name                                          
END   
IF(@ALName = ''CustomerType'')                                                        
BEGIN                                                        
SELECT ID,Name FROM tblMasterCustomerType ORDER BY Name                                                        
END         
IF(@ALName = ''PriceType'')                                                        
BEGIN                                                        
SELECT ID,PriceType Name FROM tblPriceType ORDER BY DisplayIndex        
END        
IF(@ALName = ''Ratings'')                                                
BEGIN                                      
select 0 ID,''-- Select --'' Name                                      
union all                                      
SELECT ID,RatingName Name FROM tblRatings ORDER BY Name                                                
END                                       
IF(@ALName = ''RatingsAL'')                                                        
BEGIN        
SELECT ID,RatingName Name FROM tblRatings ORDER BY Name                                                
END                                      
IF(@ALName = ''GrossNetCollAmt'')                                                        
BEGIN                                                    
SELECT 1 ID,''Net Amount'' Name union select 2 ID,''Gross Amount'' Name union select 3 ID,''Collected Amount'' Name                                                   
END                                 
IF(@ALName = ''GrossNetOnly'')                                                        
BEGIN                                                        
SELECT 1 ID, ''Gross Amount'' Name union select 2 ID,''Net Amount'' Name                                                   
END                             
IF(@ALName = ''AnaMonthlybyCustomerGB'')                                                        
BEGIN                                                        
SELECT 1 ID,''All'' Name union select 2 ID,''Beat'' Name union select 3 ID,''Salesman'' union select 4 ID,''Customer'' Name                        
END                                    
IF(@ALName = ''Reasons'')                                                        
BEGIN                                      
select 0 ID,''-- Select --'' Name                                      
union all                                      
SELECT ID,Name FROM tblMasterReason ORDER BY Name                                                
END                                              
IF(@ALName = ''Weekcycle'')                                                    
BEGIN                                               
select 0 ID,''-- Select --'' Name                               
union all                                      
SELECT ID,WeekDays Name FROM tblWeekCycle ORDER BY Name                                                
END                                              
IF(@ALName = ''AllTransactions'')                                                        
BEGIN                     
select 0 ID,''-- Select --'' Name                                      
union all                               
SELECT TransID ID,TransName Name FROM tblDocumentSeries ORDER BY Name                                                
END                                              
IF(@ALName = ''Singlemasterforms'')                         
BEGIN                                                        
SELECT ID,FormName Name FROM tblTablesNames where FormType = 1 ORDER BY Name                                                
END                                          
IF(@ALName = ''Doublemasterforms'')                                                        
BEGIN                                                        
SELECT ID,FormName Name FROM tblTablesNames where FormType = 2 ORDER BY Name                                                
END                                      
IF(@ALName = ''Paymentmodes'')                        
BEGIN                                       
SELECT ID,PaymentMode Name FROM tblPaymentMode where Active = 1 and ID IN (1) ORDER BY Name                                                
END                           
IF(@ALName = ''ChequeHand'')                                                        
BEGIN                                                        
SELECT 0 ID, ''All Status'' Name union select 1 ID,''Open'' Name union select 5 ID,''Close'' Name union select 9 ID,''Bounce'' Name                                        
END                          
IF(@ALName = ''ChequeHandNo'')        
BEGIN                                                        
SELECT DISTINCT [Cheque/DD Number] AS [ID],[Cheque/DD Number] AS Name                            
FROM tblCollPMDetails                              
WHERE PaymentTermID IN (2,3) AND Status IN (1,5,9) and isnull([Cheque/DD Number],'''') != ''''                      
ORDER BY [Cheque/DD Number] ASC                                        
END                       
IF(@ALName = ''SaleSRColl'')                                                        
BEGIN                                                        
SELECT 1 ID, ''Sales'' Name union select 2 ID,''Sales Return'' Name union select 3 ID,''Collection'' Name                  
END                  
IF(@ALName = ''FilterBY'')                
BEGIN                
SELECT 0 ID, ''ALL'' Name union select 1 ID,''Beat'' name union select 2 ID,''Salesman'' Name union select 3 ID,''Customer'' Name                
END               
IF(@ALName = ''AnaTransaction'')              
BEGIN              
SELECT 1 ID,''Yes'' Name union select 2 ID,''No'' Name              
END              
IF(@ALName = ''DateType'')              
BEGIN              
SELECT 0 ID,''Transaction Date'' Name union select 1 ID,''Create Date'' Name              
END          
IF(@ALName = ''Period'')                                                        
BEGIN                                      
SELECT ID,Name FROM tblMasterPeriod ORDER BY Name                                                
END      
IF(@ALName = ''AllYesNo'')                                                        
BEGIN                                                        
SELECT 1 ID,''All'' Name union select 2 ID,''Yes'' Name  union select 3 ID,''No'' Name  
END   
END                                                     
END',
N'[export] nocount';
GO
/****** uspManageSalesHeader ******/
EXEC #Apply07 N'dbo.uspManageSalesHeader', 0xFCEA0DC0EB6AB6E83C691857D2EB7EFB57954CAFCBA7199AF2897AF9AA053C83, NULL, NULL, 0x05E4A2CD8EF96ECB1CBE9DB78FD348899F6C5E285650E603FC8EB5EB694FC321, 0x463096D9679F071EA94D291DC4076D3A89F460BAAF87B0D667AEC9D64DBAC007, NULL,
N'ALTER PROC [dbo].[uspManageSalesHeader]                              
@Status INT,@UID INT,@DocRefId INT,@InvId INT=NULL,@InvDate DATE =NULL,@CreditDate NVARCHAR(25) =NULL,@BeatId INT=NULL,@SalesManId INT=NULL,                              
@BranchId INT=NULL,@CustId INT=NULL,@AppPriceId SMALLINT,@TaxTypeId INT=NULL,@PaymentModeId INT=NULL,@CreditTermId INT=NULL,@ProductGroupId INT=NULL,                              
@DocRef NVARCHAR(255)=NULL,@Frieght DECIMAL (25,6) =NULL,@OtherCharge DECIMAL(25,6)=NULL,@OtherChargeAmt DECIMAL (25,6)=NULL,@RoundOfAmt DECIMAL (25,6) =NULL,                              
@TCrNoteAdjValue DECIMAL (25,6)=NULL,@TUserDis DECIMAL (25,6)=NULL,@TrValue DECIMAL (25,6)=NULL,@TTradeDis DECIMAL (25,6)=NULL,@TProdDis DECIMAL (25,6)=NULL,                              
@AddnlValue DECIMAL (25,6)=NULL,@TAddnlDisc DECIMAL (25,6)=NULL,@TotalGrossAmt DECIMAL (25,6)=NULL,@ToatlTaxAmt DECIMAL (25,6)=NULL,@TotalDiscountAmount DECIMAL (25,6)=NULL,                              
@TotalNetAmt DECIMAL (25,6)=NULL,@UDFId INT=NULL,@tvpIdentId [tvpIdentId] READONLY ,@tvpTranSaleDetail [tvpTranSaleDetail] READONLY,@tvpProdSerialInfo tvpProdSerialInfo READONLY,                              
@TransType INT,@CurrentStatus INT,@UDNDocID_Import NVARCHAR(255)=NULL,@TCSTaxPern DECIMAL(25,6) = null,@TCSTaxAmt DECIMAL(25,6) = null,                              
@TDSAmt DECIMAL(25,6) = null,@ImportStatus INT = 0,@Remarks NVARCHAR(max)=NULL,@Narration NVARCHAR(max)=NULL,@DraftID INT = 0,                          
@FilterTypeID int = 1,@VehicleNo SMALLINT = 0,@Distance NVARCHAR(255)=''0'',@TransportType NVARCHAR(255)=NULL,@TransportMode NVARCHAR(255)=NULL,                      
@TransportID NVARCHAR(255)=NULL,@TransportName NVARCHAR(255)=NULL,@DiffValueGross DECIMAL(25,4) = 0,@DiffValueNet DECIMAL(25,4) = 0                  
AS                              
BEGIN TRY                              
BEGIN TRAN                              
SET DATEFORMAT dmy;                              
SET NOCOUNT ON;                              
DECLARE @ActiveCheck INT,@DocValue INT,@DocID NVARCHAR(255),@UDFDocValue INT,@UDFDocPrefix NVARCHAR(255),@UDFDocId NVARCHAR(255),                              
@PreviousTranDate DATE, @CheckUDFId INT,@ScopeID INT ,@Accid INT, @nCurrStatus INT,@OldNetAmt decimal(25,4)        
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)                              
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)                     
      declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))                      
      DECLARE @DocSeriesIdent int                             
                              
--Invoice Creation                              
IF(@Status =1)                              
BEGIN      
IF(ISNULL(@DraftID,0) > 0 AND ISNULL(@FilterTypeID,0) = 2)-- Draft status CHECK                          
begin                              
exec uspValidateDraftData 1,15,@DraftID,@CurrentStatus                              
END          
IF(ISNULL(@DraftID,0) > 0 AND ISNULL(@FilterTypeID,0) = 3)-- Quotation status CHECK                           
begin                              
SELECT @nCurrStatus = [Status] From tblQuotationHeader WITH (READCOMMITTEDLOCK) Where ID = @DraftID        
IF((@nCurrStatus != @CurrentStatus) or @nCurrStatus in (2,4))
BEGIN        
RAISERROR(''Document status already changed'',16,1)        
END      
ENd     
IF(ISNULL(@DraftID,0) > 0 AND ISNULL(@FilterTypeID,0) = 4)-- Order Taken status CHECK                           
begin                              
exec uspValidateDraftData 1,100,@DraftID,@CurrentStatus      
END     
--set @DocValue = 0                              
--PRINT (N''1'' @DocValue)                
insert into @tblDocdetails                
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@InvDate between FromDate and ToDate) and BranchID = @BranchID and TransID = @DocRefId               
 IF((select count(*) from @tblDocdetails) = 0)           
   BEGIN                            
    RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)                            
   END                     
                
   SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails                
              
UPDATE tblYearwiseDocumentSeries SET DocValue =  @DocValue + 1 WHERE TransID = @DocRefId and ID = @DocSeriesIdent                
--print ''Before Select '' + cast(@DocValue as Varchar)                              
--SELECT @DocValue=Doc.DocValue ,@DocId = Doc.DocPrefix+CONVERT(NVARCHAR,Doc.DocValue)                              
--FROM tblDocumentSeries Doc WHERE Doc.TransID =@DocRefId                              
----select top 2* from tblTranSalesHeader where docvalue= 49268 order by 1 desc                              
----PRINT 2 @DocValue                              
--print ''After Select '' + cast(@DocValue as Varchar)                  
--UPDATE tblDocumentSeries SET DocValue=ISNULL(DocValue,0) +1 WHERE TransID = @DocRefId --ISNULL(@DocValue,0)                              
                              
--declare @a1 int = (select DocValue from tblDocumentSeries Doc WHERE Doc.TransID =@DocRefId)                             
--print ''After Update '' + cast(@a1 as Varchar)                              
--User Define Document                              
IF ISNULL(@UDFId,0)>0                              
BEGIN                              
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)                              
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId                              
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@UDFId                              
END                              
ELSE IF ISNULL(@UDFId,0)=0 AND ISNULL(@UDNDocID_Import,'''')!=''''                              
BEGIN                              
DECLARE @PaymentDays INT                              
SET @PaymentDays = (SELECT Value FROM tblMasterCreditTerm WITH (READCOMMITTEDLOCK) WHERE ID = @CreditTermId)                              
SET @CreditDate = CONVERT(NVARCHAR,DATEADD(DAY,@PaymentDays,@InvDate))                              
                              
DECLARE @SALES_UDFDocValue INT,@SALES_UDFDocPrefix NVARCHAR(255),@SALES_UDNID INT,@SALES_CHKCOUNT INT                             
SELECT @SALES_UDFDocPrefix = LEFT(@UDNDocID_Import, PATINDEX(''%[A-Z][^A-Z]%'', @UDNDocID_Import)),                              
@SALES_UDFDocValue = RIGHT(@UDNDocID_Import, LEN(@UDNDocID_Import) - (PATINDEX(''%[A-Z][^A-Z]%'', @UDNDocID_Import)))                     
SET @SALES_CHKCOUNT = (SELECT COUNT(UDNId) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE DocPrefix = @SALES_UDFDocPrefix AND TransId = 15)                              
SET @SALES_UDNID = (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE DocPrefix = @SALES_UDFDocPrefix AND TransId = 15)                              
IF ISNULL(@SALES_CHKCOUNT,0)=0                              
BEGIN                              
INSERT INTO tblMasterUserDefineNoHeader (TransId,DocName,DocPrefix,DocValue,CBy,CDate) VALUES                              
(2,@SALES_UDFDocPrefix,@SALES_UDFDocPrefix,1,@UID,CONVERT(DATE,GETDATE()))                              
SET @SALES_UDNID = SCOPE_IDENTITY()                              
INSERT INTO tblMasterUserDefineNoDetail (UDNId,UserId) VALUES (@SALES_UDNID,@UID)                              
END                              
UPDATE tblMasterUserDefineNoHeader SET DocValue = @SALES_UDFDocValue WHERE UDNId = @SALES_UDNID                              
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)                              
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@SALES_UDNID                              
SET @UDFId = @SALES_UDNID                              
END                              
END                              
--Invoice Modification                              
IF(@Status =3)                              
BEGIN      
--DECLARE @Bool VARCHAR(100)                              
--SET @Bool=[dbo].[funValidateSalesTran](@CurrentStatus ,@InvId)                              
--SELECT * FROM tblTranSalesHeader WHERE InvId = 5392                              
                              
--SELECT @nCurrStatus                              
                              
--SELECT * FROM tblTranSalesHeader WHERE InvId = 5352                              
--SELECT @nCurrStatus                              
SELECT @DocValue= SH.DocValue,@DocId=DocId,@PreviousTranDate=InvDate,@UDFDocValue=UDFDocValue,@CheckUDFId=UDFId,@OldNetAmt = NetAmt        
FROM tblTranSalesHeader SH WITH (READCOMMITTEDLOCK)                              
WHERE SH .DocPrefix =@DocRefId AND SH.ID =@InvId                              
                              
--User Document and if Changes made                              
IF ISNULL(@UDFId,0)>0                              
BEGIN                              
IF(@UDFId=@CheckUDFId)                              
BEGIN                              
SELECT @UDFDocId=DocPrefix + CONVERT(NVARCHAR, @UDFDocValue),@UDFDocPrefix=DocPrefix FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId                              
END                              
IF(@UDFId!=@CheckUDFId)                              
BEGIN                  
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId                              
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@UDFId                              
END                              
END            
--Revert Track Point when Modify        
EXEC [uspAddTrackPoint] @OldNetAmt,2,@CustId        
END                              
--IF(@Status = 1 OR @Status = 3)                              
--BEGIN               
--IF((SELECT COUNT(DocValue) FROM tblTranSalesHeader WHERE DocValue = @DocValue and InvDate BETWEEN @F_SD AND @F_ED and Status in (1,3,4,5) and DocPrefix = 2) != 0)                              
--BEGIN                              
--RAISERROR(''UDocId'',16,1)                              
--END                              
--END                              
--Credit Term Date Vefiry                              
IF ISDATE(@CreditDate)=0                              
BEGIN                              
SET @CreditDate=NULL;                              
END                              
--Invoice Total Amount Include Adjusted Amount                              
SET @TotalNetAmt=(ISNULL(@TotalNetAmt,0)+ISNULL(@TCrNoteAdjValue,0));                              
print ''Before insert '' + cast(@DocValue as Varchar)                              
---------TDSamount value for Balance                              
Declare @TDSBalance decimal(25,6)                              
IF ISNULL(@Status,0)=1 OR ISNULL(@Status,0)=3                              
BEGIN                              
Set @TDSBalance=(@TotalNetAmt-isnull(@TDSAmt,0))                              
END                              
IF(ISNULL(@CreditTermId,0) > 0)                            
BEGIN                            
SET @CreditDate = ( select DATEADD(DD,CONVERT(INT, Value),CONVERT(DATE,@InvDate)) ADDEDDATE from tblmastercreditterm WITH (READCOMMITTEDLOCK) WHERE id = @CreditTermID)                            
END                            
ELSE                 
BEGIN                            
SET @CreditDate = null                            
END                            
              
IF(@Status = 1)                     
BEGIN                              
IF((SELECT COUNT(DocValue) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and               
InvDate BETWEEN @F_SD AND @F_ED and DocPrefix = 15) != 0)-- and Status in (3,4,5,6)      
BEGIN                              
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)                              
END                              
ENd          
IF(@Status = 3)                     
BEGIN                              
IF((SELECT COUNT(DocValue) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and               
InvDate NOT BETWEEN @F_SD AND @F_ED and DocPrefix = 15) != 0)-- and Status in (3,4,5,6)      
BEGIN                              
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)                             
END                              
ENd       
  
declare @TempTransportType nvarchar(255) = null,@TempTransportMode nvarchar(255) = null,  
@TempTransportID nvarchar(255) = null,@TempTransportName nvarchar(255) = null  
if(isnull(@VehicleNo,0) > 0)  
BEGIN  
SET @TempTransportType = @TransportType;  
SET @TempTransportMode = @TransportMode;  
SET @TempTransportID = @TransportID;  
SET @TempTransportName = @TransportName;  
END  
--Header Level Info                              
INSERT INTO tblTranSalesHeader ([InvDate] ,[DocPrefix],[DocId],[DocValue],[BeatID],[SalesManId],[CustId],BranchID,[PriceID],[TaxTypeId],[PaymentModeId],[CreditTermId]                              
,[CreditDate],[ProdGroupId],[DocRef],[Frieght],[OtherCharge],[RoundOfAmt],[CreditNoteAdjAmt],[TotalTradeDiscAmt],                              
[TotalProdDiscAmt],[AdditionalDiscAmt],[GrossAmt],[TotalTaxAmt],[TotalDiscountAmt],[NetAmt],[Balance],[Status],[OrgId],[CBY],[CDate],[TradeDisc],                              
[AdditionalDisc],[OtherChargeAmt],UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,TransactionType,TCSTaxPern,TCSTaxAmt,TDSAmount,Remarks,Narration,                      
VehicleNo,Distance,VehicleType,TransMode,TransportID,TransportName,DiffValueGross,DiffValueNet)                              
VALUES(@InvDate,@DocRefId,@DocId,@DocValue ,@BeatId,@SalesManId,@CustId,@BranchId,@AppPriceId,@TaxTypeId,@PaymentModeId,@CreditTermId,                         
@CreditDate,@ProductGroupId,@DocRef,@Frieght  ,@OtherCharge ,@RoundOfAmt ,@TCrNoteAdjValue  ,@TTradeDis ,                              
@TProdDis ,@TAddnlDisc ,@TotalGrossAmt,@ToatlTaxAmt,@TotalDiscountAmount ,@TotalNetAmt,@TDSBalance,                              
case when ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,@InvId,@UID ,GETDATE(),@TrValue,                              
@AddnlValue  ,@OtherChargeAmt,                              
@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@TransType,isnull(@TCSTaxPern,0),isnull(@TCSTaxAmt,0),isnull(@TDSAmt,0),@Remarks,@Narration,                      
@VehicleNo,@Distance,@TempTransportType,@TempTransportMode,@TempTransportID,@TempTransportName,@DiffValueGross,@DiffValueNet)                              
--Invoice Header Indentity Get At Scope                              
SET @ScopeID =(SELECT SCOPE_IDENTITY());                              
--Update Track Point when Save        
EXEC [uspAddTrackPoint] @TotalNetAmt,1,@CustId        
--detail and qty reduce                              
EXEC dbo.uspQtyReduceInventory ''DIRECT_SALE'',@BranchId, @AppPriceId,@ScopeID,0,@InvDate ,@tvpTranSaleDetail,@tvpProdSerialInfo                               
                              
--Back Dated Transaction Stored In Initial Table(tblBackDateTran)                              
--disp begin                              
--IF(@Status = 1)                              
--BEGIN                              
--IF ISNULL(@TransType,0) =5 AND (SELECT COUNT(*) FROM @tvpIdentId)>0                              
--BEGIN                              
--DECLARE @Ident INT,@ProdId INT,@UomGroupId INT ,@BaseUomPrice DECIMAL (25,6),@UomQty DECIMAL (25,6),@UomId INT ,@InventoryId INT ,                              
--@AdjustQty DECIMAL (25,6),@ProdSerial NVARCHAR(255),@QtyType INT,@ProdPrice DECIMAL (25,6),@Serial INT,@GoodsAmt DECIMAL (25,6) ,                              
--@UserDisc DECIMAL (25,6),@ProdDisc DECIMAL (25,6) ,@TradeDisc DECIMAL (25,6) ,@AddnlDisc DECIMAL (25,6) , @GrossAmt DECIMAL (25,6),                              
--@TaxId INT ,@TaxPern DECIMAL (25,6),@TaxAmt DECIMAL (25,6),@NetAmt DECIMAL (25,6),@TempSerial1 INT,@TempSerial2 INT,@TempDoc1 INT,                              
--@TempDoc2 INT,@UserDiscAmt DECIMAL (25,6),@ProdDiscAmt DECIMAL (25,6) ,@TradeDiscPerc DECIMAL (25,6) ,@AddnlDiscPerc DECIMAL (25,6)                              
--SET @Serial=0;                              
--SET @TempSerial2=0;                              
