--DECLARE @BPrice DECIMAL (25,6)                              
----For Row All PRoduct details only stored                              
--IF (SELECT COUNT(*) FROM @tvpTranSaleDetail WHERE DisbatchDetailId =@Ident)>0                              
--BEGIN                              
--DECLARE @ConvRate DECIMAL (25,6)                              
--SET @ConvRate =1--dbo.fnGetConvertionFact (@UomGroupId,@UomId)                              
                              
--SELECT @ProdPrice=ProdPrice ,@GoodsAmt=GoodsAmt ,@UserDisc=UserDisc,@ProdDisc=ProdDisc ,@TradeDisc=TradeDisc ,@AddnlDisc=AddnlDisc,                              
