--disp end                              
--DISPATCH Modify InvID Update                    
--Back Dated Transaction Stored In Initial Table(tblBackDateTran)                              
                      
IF(@Status = 1)                     
BEGIN                
EXEC uspCreateBackTran 1,@BranchID,@ScopeID,0,@DocRefId,@DocValue ,@InvDate,NULL,@UID                 
END                
IF(@Status = 3)                              
BEGIN                              
declare @DispID INT,@QtnID INT,@OrgDispID INT ,@OrgInvID INT                              
if(@InvId > 0) -- CHECK HERE                              
begiN                                    
IF((SELECT count(*) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE OrgInvID = @InvId) > 0)                              
BEGIN                              
UPDATE tblTranSalesHeader SET OrgInvID = @ScopeID WHERE OrgInvID = @InvId                              
END                              
enD                              
EXEC uspCreateBackTran 2,@BranchID,@ScopeID,@InvId,@DocRefId,@DocValue ,@InvDate,@PreviousTranDate,@UID                              
END                              
--Get Customer Account Id                              
SELECT @Accid=FAID FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE ID =@CustId                              
--Account Posting FA Journal Table                              
DECLARE @JVID INT                              
SET @JVID=(SELECT (MAX(ISNULL(JVID,0))+1) FROM dbo.tblFAJournal WITH (READCOMMITTEDLOCK))                              
SET @Status = (case when ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END)                              
IF ISNULL(@JVID,0)=0                              
BEGIn                              
SET @JVID =1                              
END                              
--Total Net Amount                              
IF ISNULL(@TotalNetAmt,0)>0                              
BEGIn                              
DECLARE @RAmt DECIMAL (25,6)                     
SET @RAmt =-1* @RoundOfAmt                              
--Customer Account Dr                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )                              
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,@Accid,0,(ISNULL(@TotalNetAmt,0)+ISNULL(@RAmt,0)), 0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                              
END                              
--Total Tax Amount                              
IF ISNULL(@ToatlTaxAmt,0)>0                              
BEGIN                              
--VAT Payable Cr                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID)                              
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,112,@ToatlTaxAmt,0, 0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                              
END                              
--Total Gross Amount                              
IF ISNULL(@TotalGrossAmt,0)>0                              
BEGIN                              
--Sales Account Debit Cr                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId ,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )                              
VALUES ( @JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,84,ISNULL(@TotalGrossAmt,0),0, 0,NULL,''Sales Invoice'',@Status, @UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                              
END                              
--TCS Amount                              
IF ISNULL(@TCSTaxAmt,0)>0                              
BEGIN                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID)                       
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,57,@TCSTaxAmt,0, 0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                              
END--tcs                              
--TDS Amount                              
IF ISNULL(@TDSAmt,0)>0                              
BEGIN                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID)                              
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,12,0,@TDSAmt, 0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                              
END--TDS                              
--Freight Outwards                              
IF ISNULL(@Frieght,0)>0                              
BEGIN                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID)                              
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,40,ISNULL(@Frieght,0),0,0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID )                              
END                              
--Other Charges                              
IF ISNULL(@OtherChargeAmt,0)<>0                              
BEGIN                              
IF ISNULL(@OtherChargeAmt,0)<0                              
BEGIN --Other Charges Positive                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID)                              
VALUES ( @JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,61,0,ABS(ISNULL(@OtherChargeAmt,0)),0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID )                              
END                              
ELSE IF ISNULL(@OtherChargeAmt,0)>0                              
BEGIN --Other Charges Negative                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )                              
VALUES ( @JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,61,ISNULL(@OtherChargeAmt,0),0,0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID )                             
END                              
END                              
IF ISNULL(@TotalDiscountAmount,0)>0                              
BEGIN                              
SET @JVID=@JVID+1;                              
--Discount On Sales Dr                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate ,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )                              
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,32,0,ISNULL(@TotalDiscountAmount,0), 0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                              
--Sales Account Cr                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )             
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,84,ISNULL(@TotalDiscountAmount,0),0, 0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID )                              
END                              
IF ISNULL(@RoundOfAmt,0)<>0                              
BEGIN--Round Off Amt                              
SET @JVID=@JVID+1;                              
IF ISNULL(@RoundOfAmt,0)>0                              
BEGIN                              
--Customer Account Dr                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )                              
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,@Accid,0,@RoundOfAmt,0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID )                              
--Round Off Acount Postive Cr                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )                              
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,82,@RoundOfAmt,0, 0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID )                              
END                              
ELSE IF ISNULL(@RoundOfAmt,0)<0                              
BEGIN                              
--Round Off Acount Negative Dr                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate ,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )                              
VALUES (@JVID, @DocId, 15, @DocValue,@InvDate ,@DocRef ,82,0,ABS(@RoundOfAmt), 0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID )                              
--Customer Account Cr                              
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],                              
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )                              
VALUES ( @JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,@Accid,ABS(@RoundOfAmt),0,0,NULL,''Sales Invoice'',@Status,                              
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue ,@BranchID)                              
END                              
END                              
IF(ISNULL(@DraftID,0) > 0 AND ISNULL(@FilterTypeID,0) = 2)-- Draft status change                          
begin                              
UPDATE tblSalesdraftheader set Status = 5 where id = @DraftID                              
END                              
IF(ISNULL(@DraftID,0) > 0 AND ISNULL(@FilterTypeID,0) = 3)-- Quotation status CHECK                           
begin       
UPDATE tblQuotationHeader set Status = 5 where ID = @DraftID    
END    
IF(ISNULL(@DraftID,0) > 0 AND ISNULL(@FilterTypeID,0) = 4)-- Order Taken status change                           
begin                              
UPDATE tblTranOrderTakenHeader set Status = 8,InvoiceID = @ScopeID  where id = @DraftID                              
END                          
    
SELECT @ScopeID AS IdentId                  
COMMIT TRAN                              
END TRY                              
BEGIN CATCH                              
ROLLBACK TRAN                              
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE();                              
END CATCH',
N'[export] number-series-updlock=7;readcommittedlock=11';
GO
/****** uspManageSalesman ******/
EXEC #Apply07 N'dbo.uspManageSalesman', 0x5732FB7D03C38F4E860A585B450E4CDE27AE2179845369BA60F609212F601938, NULL, NULL, 0x7CB5FEC79EDD8A73388CD4257096B0A65E70B8765CD887C7AC816CB4B8F4AC20, 0x8703C9A66DC498F22D5CAC47B52E0D162D75FFFCFA959F844CE7B0BAED280C26, NULL,
N'ALTER proc [dbo].[uspManageSalesman]            
@Mode INT,@ID smallint = null,@Name nvarchar(255) = null,@DOB date = null,@DOJ date = null,@MobileNo nvarchar(25) = null,            
@AadharNo nvarchar(25) = null,@PANNumber nvarchar(25) = null,@Address nvarchar(max) = null,@SalesmanGroupID smallint = null,            
@Active bit = null,@UserID smallint = null            
AS            
SET NOCOUNT ON;
BEGIN TRY            
set @Name = (select dbo.ProperCase(@Name))            
DECLARE @ActiveCheck NVARCHAR(255), @SUNDRYDEBTORS INT ,@FATYPE INT,@AccID INT ,@ACCOUNTID INT,@CHECKID INT,@cstdate DATE,@ExistCount INT            
SELECT @SUNDRYDEBTORS = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName=''Staff''            
IF(@Mode = 1)            
BEGIN            
IF((SELECT count(*) FROM tblMasterSalesman WITH (READCOMMITTEDLOCK) WHERE Name = @Name) > 0)            
BEGIN            
RAISERROR(''Salesman Name Already Exists'',16,1)            
END            
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@name            
IF(@ExistCount>0)            
BEGIN            
RAISERROR (''Account Name Already Exists'',16,1)            
END            
            
set @Name = (select dbo.ProperCase(@Name))            
INSERT INTO tblFAAccount(AccountName,AccountGroup,OpeningBalance,FATypeID,CBy,CDate,UserAccount,PANNumber,Active)            
VALUES(@name,@SUNDRYDEBTORS,0,1,@UserID,GETDATE(),0,@PANNumber,@Active)            
            
SELECT @AccID = FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @Name            
            
insert into tblMasterSalesman(Name,DOB,DOJ,MobileNo,AadharNo,PANNumber,Address,SalesmanGroupID,Active,CBy,CDate,FAID)            
Values (@Name,@DOB,@DOJ,@MobileNo,@AadharNo,@PANNumber,@Address,@SalesmanGroupID,@Active,@UserID, GETDATE(),@AccID)            
SELECT SCOPE_IDENTITY()            
END            
IF(@Mode = 2)            
BEGIN            
select @ACCOUNTID = FAID from tblMasterSalesman WITH (READCOMMITTEDLOCK) where ID = @ID            
IF((SELECT count(*) FROM tblMasterSalesman WITH (READCOMMITTEDLOCK) WHERE Name = @Name AND ID != @ID) > 0)            
BEGIN            
RAISERROR(''Salesman Name Already Exists'',16,1)            
END            
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@name and FAID != @ACCOUNTID            
IF(@ExistCount>0)            
BEGIN            
RAISERROR (''Account Name Already Exists'',16,1)            
END            
IF @Active=0                                              
BEGIN                                              
DECLARE @ReturnValue DECIMAL(25,4)                                              
EXEC uspGetClosingBal @ACCOUNTID,@ReturnValue OUTPUT                                              
IF( @ReturnValue !=0)                                              
BEGIN                                              
RAISERROR (''OSPending'',16,1)                                               
END                                      
END           
INSERT INTO tblMasterHistory (FormID,ID,Name,Column1,Column2,Column3,Column4,Column5,Column6,Column7,Column8,Active,CBy,CDate,MBy,MDate,PLName,HisCBy,HisCDate)            
(select 20,*,@UserID, GETDATE() from tblMasterSalesman WITH (READCOMMITTEDLOCK) where ID = @ID)            
            
set @Name = (select dbo.ProperCase(@Name))            
            
UPDATE tblFAAccount            
SET AccountName=@name,AccountGroup=@SUNDRYDEBTORS,MBy=@UserID,MDate=GETDATE(),UserAccount=0,PANNumber=@PANNumber,Active = @Active            
WHERE FAID=@ACCOUNTID            
            
UPDATE tblMasterSalesman SET Name = @Name,DOB = @DOB,DOJ = @DOJ,MobileNo = @MobileNo,AadharNo = @AadharNo,PANNumber = @PANNumber,            
Address = @Address,SalesmanGroupID = @SalesmanGroupID,Active = @Active,MBy = @UserID,MDate = GETDATE() WHERE ID = @ID            
SELECT @ID            
END            
IF(@Mode = 3)            
BEGIN            
SELECT MS.ID,MS.Name,MS.DOB,MS.DOJ,MobileNo,AadharNo,PANNumber,Address,ISNULL(MS.SalesmanGroupID,0) SalesmanGroupID,    
MSG.Name SalesmanGroupName,MS.Active,CASE WHEN ISNULL(MS.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,    
 CASE WHEN ISNULL(MS.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MS.CDate) ELSE CONVERT(NVARCHAR(100),MS.MDate) END LastActionTime from tblMasterSalesman MS WITH (READCOMMITTEDLOCK)           
LEFT JOIN tblMasterSalesmanGroup MSG WITH (READCOMMITTEDLOCK) ON MSG.ID = MS.SalesmanGroupID     
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MS.CBy              
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MS.MBy     
order by MS.Name            
END            
IF(@Mode = 4)            
BEGIN            
SELECT  MS.ID,MS.Name,MS.DOB,MS.DOJ,MobileNo,AadharNo,PANNumber,Address,ISNULL(MS.SalesmanGroupID,0) SalesmanGroupID,  
MSG.Name SalesmanGroupName,MS.Active,CASE WHEN ISNULL(MS.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,    
 CASE WHEN ISNULL(MS.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MS.CDate) ELSE CONVERT(NVARCHAR(100),MS.MDate) END LastActionTime from tblMasterSalesman MS WITH (READCOMMITTEDLOCK)      
LEFT JOIN tblMasterSalesmanGroup MSG WITH (READCOMMITTEDLOCK) ON MSG.ID = MS.SalesmanGroupID   
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MS.CBy              
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MS.MBy    
where MS.ID = @Name            
END            
IF(@Mode = 5)            
BEGIN            
SELECT * from tblMasterSalesmanGroup WITH (READCOMMITTEDLOCK) where Active = 1 order by Name            
END            
END TRY            
BEGIN CATCH            
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC] END CATCH',
N'[export] nocount;readcommittedlock=17';
GO
/****** uspManageSalesReturn ******/
EXEC #Apply07 N'dbo.uspManageSalesReturn', 0x00CE471E7C0D3238F284DC79DB648F47B4BC8E770FC672DADEB3E43B9C0322B2, NULL, NULL, 0xB6678F23221E0D61775CAC0C86F5EFA9AC648F779F937F6B9A6E5D473DB944DA, 0xA4085FDB8AE52DFC3879F389F0D53A3DA870639876FE32F1A6925F2351113774, NULL,
N'ALTER PROC [dbo].[uspManageSalesReturn]                                                  
@Status INT,@UID INT,@DocRefId INT,@InvId INT=NULL,@InvDate DATE =NULL,@CreditDate DATE =NULL,@BeetId INT=NULL,@SalesManId INT=NULL,                                                  
@BranchId INT=NULL,@CustId INT=NULL,@AppPriceId SMALLINT,@TaxTypeId INT=NULL,@PaymentModeId INT=NULL,@CreditTermId INT=NULL,@ProductGroupId INT=NULL,                                                  
@DocRef NVARCHAR(255)=NULL,@Frieght DECIMAL (25,6) =NULL,@OtherCharge DECIMAL(25,6)=NULL,@OtherChargeAmt DECIMAL (25,6)=NULL,@RoundOfAmt DECIMAL (25,6) =NULL,                                                  
@TCrNoteAdjValue DECIMAL (25,6)=NULL,@TUserDis DECIMAL (25,6)=NULL,@TrValue DECIMAL(25,6)=NULL,@TTradeDis DECIMAL (25,6)=NULL,@TProdDis DECIMAL (25,6)=NULL,                                                  
@AddnlValue DECIMAL(25,6)=NULL,@TAddnlDisc DECIMAL (25,6)=NULL,@TotalGrossAmt DECIMAL(25,6)=NULL,@ToatlTaxAmt DECIMAL (25,6)=NULL,@TotalDiscountAmount DECIMAL (25,6)=NULL,                                                  
@TotalNetAmt DECIMAL (25,6)=NULL,@UDFId INT =NULL,@tvpTranSaleDetail tvpTranSaleDetail READONLY,@tvpTranSRPopUpDetail tvpTranSRPopUpDetail READONLY,                                                  
@TransType INT=NULL,@ReturnType INT=NULL,@SRUDFDocID NVARCHAR(255)=NULL,@OrgInvID INT = NULL,@TCSPern DECIMAL(25,6) = NULL,@TCSAmt DECIMAL(25,6) = NULL,                                              
@ImportStatus INT = 0,@Remarks NVARCHAR(max)=NULL,@Narration NVARCHAR(max)=NULL,@DraftID INT = 0,@DiffValueGross DECIMAL(25,4) = 0,          
@DiffValueNet DECIMAL(25,4) = 0,@FilterTypeID INT = 0,@CurrentStatus INT = 1                                                   
AS                                                  
BEGIN TRY                                                  
SET NOCOUNT ON;                                                  
SET DATEFORMAT DMY;                                                  
--Variable Declaration                                                  
DECLARE @DocId NVARCHAR(20),@DocValue INT,@Accid INT,@TempAccID INT,@UDFDocId NVARCHAR(255),@UDFDocValue INT,@UDFDocPrefix NVARCHAR(255),@CheckUDFId INT,@ScopeID INT,                                                  
@ProdId NVARCHAR(20) ,@BaseUomPrice DECIMAL (25,6) ,@UomId INT ,@UomQty DECIMAL(25, 9) ,@UomPrice DECIMAL (25,6) , @GoodsAmt DECIMAL (25,6) ,@UserDisc DECIMAL (25,6) ,@ProdDisc DECIMAL (25,6) ,                                                  
@TradeDisc DECIMAL (25,6) ,@AddnlDisc DECIMAL (25,6) ,@GrossAmt DECIMAL (25,6) ,@TaxId INT,@TaxPercentage DECIMAL (25,6) ,@TaxAmt DECIMAL (25,6) ,@NetAmt DECIMAL (25,6) ,@Serial INT ,                                                  
@BatchNumber NVARCHAR(25) ,@PkgDate NVARCHAR(25) ,@ExpiryDate NVARCHAR(25) ,@InventoryPrice NVARCHAR(25) ,@MRP NVARCHAR(25) ,@InvQtyType INT ,@tvpCount INT,@tvpIndex INT ,                                                  
@TempBatchInvId INT,@TrackInventory INT,@TrackBatch INT,@TrackPkd INT,@TrackSerial INT ,@cursor_Inventory CURSOR ,@SaleQty DECIMAL (25,6),@BaseUomId INT ,@UomGroupId INT,@Qty DECIMAL (25,6),                                                  
@BaseUomCRate DECIMAL (25,6),@SaleUomCRate DECIMAL (25,6),@InvAdjId INT,@InvPurchasePrice DECIMAL (25,6),@InvSalesPrice DECIMAL (25,6),@InvECP DECIMAL (25,6),                                                  
@InvMRP DECIMAL (25,6),@InvSPLPrice DECIMAL (25,6),@InvMRPOn DECIMAL (25,6),@ReturnPrice DECIMAL (25,6),@InvScopeId INT,@TempUomGroupId INT,@TempInventoryYesNo INT,@TempBatchYesNo INT,@TempPKDYesNo INT,                                                  
@TempSerialYesNo INT,@ActiveCheck NVARCHAR(255),@ReasonId INT,@nCurruntStatus INT,@Id INT,@nCount INT,@Sno INT = 1,@IsChrgProd INT                                                 
 ,@UserDiscAmt DECIMAL (25,6) ,@ProdDiscAmt DECIMAL (25,6) ,@TradeDiscPern DECIMAL (25,6) ,@AddnlDiscPern DECIMAL (25,6) ,@DiffVal DECIMAL (25,4),                      
@PreviousTranDate DATE,@OldNetAmt decimal(25,4)            
 declare @EnableReturnPrice int = (select AppValue from tblAppConfig WITH (READCOMMITTEDLOCK) where AppId = 12)                    
 DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)                         
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)                       
      declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))                        
      DECLARE @DocSeriesIdent int                 
--Get Customer Accid                                                  
SELECT @Accid=FAID FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE ID =@CustId                                                  
IF ISNULL(@Status,0)=3                                                  
BEGIN                      
DECLARE @temp_NetAmount DECIMAL(25,6),@temp_Balance DECIMAL(25,6),@temp_Status int                                                  
SELECT @temp_NetAmount=NetAmt,@temp_Balance=Balance,@PreviousTranDate = InvDate,@temp_Status = Status  
FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id=@InvId                                                
  --SELECT *FROM tblTranSalesHeader WHERE Id= 1198  
--IF((ISNULL(@CurrentStatus,0)!=ISNULL(@temp_Status,0)) or @temp_Status in (2,4))    
--BEGIN                                  
--set @tvpIndex = @temp_Status  
--RAISERROR(''Document Status already changed'',16,1,@tvpIndex);                                                  
--END                                            
    
IF ISNULL(@temp_NetAmount,0)!=ISNULL(@temp_Balance,0)    
BEGIN                                  
RAISERROR(''13'',16,1);                                                  
END                                            
END                                                  
                                              
--Get Current Scope Doc Value and Doc Id                                                  
IF ISNULL(@Status,0)=3                                                
BEGIN                                                  
SELECT @DocValue=SH.DocValue,@DocId=DocId,@OldNetAmt = NetAmt FROM tblTranSalesHeader SH WITH (READCOMMITTEDLOCK)                                                  
WHERE SH .DocPrefix =@DocRefId AND SH.ID =@InvId                                                  
END                                                  
ELSE                                                  
BEGIN                     
                
insert into @tblDocdetails                  
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@InvDate between FromDate and ToDate) and BranchID = @BranchID and TransID = @DocRefId                  
 IF((select count(*) from @tblDocdetails) = 0)                              
   BEGIN                              
    RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)                              
   END                       
                  
   SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails                  
                
UPDATE tblYearwiseDocumentSeries SET DocValue =  @DocValue + 1 WHERE TransID = @DocRefId and ID = @DocSeriesIdent                  
                
--SELECT @DocValue=Doc .DocValue FROM tblDocumentSeries Doc WHERE Doc.TransID =@DocRefId                                                  
--SELECT @DocId = Doc .DocPrefix+CONVERT(NVARCHAR,Doc .DocValue) FROM tblDocumentSeries Doc WHERE Doc.TransID =@DocRefId                                                  
----Update Doc Value                                                  
--UPDATE tblDocumentSeries SET DocValue=@DocValue +1 WHERE TransID=@DocRefId                                                  
END                                                  
                                                  
--User Define Document                                                  
IF ISNULL(@UDFId,0)>0                                                  
BEGIN                                                  
IF ISNULL(@Status,0)=3                                                  
BEGIN                                                  
SELECT @UDFDocValue=UDFDocValue,@CheckUDFId=UDFId FROM tblTranSalesHeader SH WITH (READCOMMITTEDLOCK)                                                  
WHERE SH .DocPrefix =@DocRefId AND SH.ID =@InvId                                                  
--User Document and if Changes made                                                  
IF ISNULL(@UDFId,0)>0                                                  
BEGIN                                                  
IF(@UDFId=@CheckUDFId)          
BEGIN                                                  
SELECT @UDFDocId=DocPrefix + CONVERT(NVARCHAR, @UDFDocValue),@UDFDocPrefix=DocPrefix FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId                                                  
END                                                  
IF(@UDFId!=@CheckUDFId)                                          BEGIN                                                  
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId                                                  
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@UDFId                                                  
END                                   
END                                                  
END                                                  
ELSE                                                  
BEGIN                        
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)                                                  
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId                                                  
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@UDFId                                                  
END                                                  
END                                                  
ELSE IF ISNULL(@UDFId,0)=0 AND ISNULL(@SRUDFDocID,'''')!=''''                                                  
BEGIn                                                  
DECLARE @PaymentDays INT                                                  
SET @PaymentDays = (SELECT Value FROM tblMasterCreditTerm WITH (READCOMMITTEDLOCK) WHERE ID = @CreditTermId)                                                  
SET @CreditDate = DATEADD(DAY,@PaymentDays,@InvDate)                                                  
                                                  
DECLARE @SR_UDFDocValue INT,@SR_UDFDocPrefix NVARCHAR(255),@SR_UDNID INT,@SR_CHKCOUNT INT                                                  
SELECT @SR_UDFDocPrefix = LEFT(@SRUDFDocID, PATINDEX(''%[A-Z][^A-Z]%'', @SRUDFDocID)),                                                  
@SR_UDFDocValue = RIGHT(@SRUDFDocID, LEN(@SRUDFDocID) - (PATINDEX(''%[A-Z][^A-Z]%'', @SRUDFDocID)))                            
SET @SR_CHKCOUNT = (SELECT COUNT(UDNId) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE DocPrefix = @SR_UDFDocPrefix AND TransID = 16)                                                  
SET @SR_UDNID = (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE DocPrefix = @SR_UDFDocPrefix AND TransID = 16)                                                  
IF ISNULL(@SR_CHKCOUNT,0)=0                                                  
BEGIN                                                  
INSERT INTO tblMasterUserDefineNoHeader (TransID,DocName,DocPrefix,DocValue,CBy,CDate) VALUES                                                  
(16,@SR_UDFDocPrefix,@SR_UDFDocPrefix,1,@UID,CONVERT(DATE,GETDATE()))                                                  
SET @SR_UDNID = SCOPE_IDENTITY()                                                  
INSERT INTO tblMasterUserDefineNoDetail (UDNId,UserId) VALUES (@SR_UDNID,@UID)                                                  
END                                          
UPDATE tblMasterUserDefineNoHeader SET DocValue = @SR_UDFDocValue WHERE UDNId = @SR_UDNID                                                  
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+CONVERT(NVARCHAR, DocValue)                                                 
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@SR_UDNID                                                  
SET @UDFId = @SR_UDNID                                                  
END                                                  
                    
IF(@Status = 6 OR @Status = 7)                       
BEGIN       
IF(ISNULL(@DraftID,0) > 0 AND ISNULL(@FilterTypeID,0) = 2)-- Draft status CHECK                            
begin                                
exec uspValidateDraftData 1,16,@DraftID,@CurrentStatus                                
END            
IF(ISNULL(@DraftID,0) > 0 AND ISNULL(@FilterTypeID,0) = 3)-- WSR status CHECK                             
begin                                
exec uspValidateDraftData 1,101,@DraftID,@CurrentStatus          
ENd       
      
IF((SELECT COUNT(DocValue) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and                 
InvDate BETWEEN @F_SD AND @F_ED and DocPrefix = @DocRefId) != 0)-- and Status in (3,4,5,6)        
BEGIN                                
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)                                  
END                                
ENd                 
IF(@Status = 3)                       
BEGIN                       
IF((SELECT COUNT(DocValue) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and                 
InvDate NOT BETWEEN @F_SD AND @F_ED and DocPrefix = @DocRefId) != 0)-- and Status in (3,4,5,6)        
BEGIN                                
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)                                  
END                                
ENd         
--Header Installation                                                  
INSERT INTO tblTranSalesHeader ( [InvDate],[DocPrefix],[DocId],[DocValue],BranchID,[BeatId],[SalesManId],[CustId],[TaxTypeId]                                                  
,[PaymentModeId],[CreditTermId],[CreditDate],[ProdGroupId],[DocRef],[Frieght],[OtherCharge],[RoundOfAmt]                                                  
,[CreditNoteAdjAmt],[TotalTradeDiscAmt],[TotalProdDiscAmt],[AdditionalDiscAmt],[GrossAmt],[TotalTaxAmt]                                                  
,[TotalDiscountAmt],[NetAmt],[Balance],[Status],[CBY],[CDate],[TradeDisc],[AdditionalDisc],[OtherChargeAmt]                                                  
,[RecievedAmt],UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,TransactionType,ReturnsTransType,ReturnType,                                                  
PriceID,OrgId,OrgInvID,TCSTaxPern,TCSTaxAmt,Remarks,Narration,DiffValueGross,DiffValueNet)                                                  
VALUES (@InvDate,@DocRefId,@DocId,@DocValue,@BranchId ,@BeetId,@SalesManId,@CustId,@TaxTypeId,@PaymentModeId,@CreditTermId,@CreditDate,                                                  
@ProductGroupId,@DocRef,@Frieght ,@OtherCharge ,@RoundOfAmt ,@TCrNoteAdjValue ,@TTradeDis ,@TProdDis,                                                  
@TAddnlDisc ,@TotalGrossAmt,@ToatlTaxAmt,@TotalDiscountAmount ,(ISNULL(@TotalNetAmt,0)+ISNULL(@TCrNoteAdjValue,0)),                                                  
(ISNULL(@TotalNetAmt,0)+ISNULL(@TCrNoteAdjValue,0)),case when ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,                                                  
@UID ,GETDATE (),@TrValue ,@AddnlValue ,@OtherChargeAmt,0,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,                                                  
(CASE WHEN @Status=6 THEN 2 ELSE (CASE WHEN @Status=3 THEN (CASE WHEN @TransType=1 THEN 2 ELSE 3 END) ELSE 3 END) END),                                                  
@TransType,@ReturnType,@AppPriceId,@InvId,@OrgInvID,isnull(@TCSPern,0),isnull(@TCSAmt,0),@Remarks,@Narration,@DiffValueGross,@DiffValueNet)                                                  
--Scope Identity Id                                                  
SET @ScopeID =(SELECT SCOPE_IDENTITY());                                                  
if(@Status = 3)                                                  
BEGIN                                                UPDATE tblTranSalesHeader SET OrgInvID = null where ID = @InvId            
EXEC uspCreateBackTran 2,@BranchID,@ScopeID,@InvId,16,@DocValue ,@InvDate,@PreviousTranDate,@UID                       
--Revert Track Point when Modify            
EXEC [uspAddTrackPoint] @OldNetAmt,1,@CustId            
END                      
ELSE                      
BEGIN                      
            
EXEC uspCreateBackTran 1,@BranchID,@ScopeID,0,16,@DocValue ,@InvDate,NULL,@UID                       
END                      
--Reduce Track Point when Save            
EXEC [uspAddTrackPoint] @TotalNetAmt,2,@CustId            
