@TempInventoryYesNo =[InventoryYesNo] ,@TempBatchYesNo=[BatchYesNo] ,@TempPKDYesNo=[PKDYesNo] ,@TempSerialYesNo =[SerialYesNo],@UserDiscAmt =[UserDiscAmt] , @ProdDiscAmt =[ProdDiscAmt],            
