(CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP                                         
WHEN @AppPriceId =4 THEN MRP  WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) = @InventoryPrice                                                  
