TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue ,BranchID)                                                  
VALUES (@JVID, @DocId, @DocRefId, @DocValue,@InvDate ,@DocRef ,61,0,ISNULL(@OtherChargeAmt,0),0,NULL,''Sales Return'',@Status,@UID ,GETDATE (),                                                  
