VALUES ( @JVID,@DocId, @DocRefId, @DocValue,@InvDate ,@DocRef ,@TempAccID,0,ISNULL(@TotalDiscountAmount,0),0,NULL,''Sales Return'',@Status,@UID ,GETDATE (),                                                  
@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                                                  
