TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID)                                                  
VALUES (@JVID, @DocId, @DocRefId, @DocValue,@InvDate ,@DocRef ,32,ISNULL(@TotalDiscountAmount,0),0,0,NULL,''Sales Return'',@Status,@UID ,GETDATE (),                                        
@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                                                  
END                                                  
--RoundOff                                                  
IF ISNULL(@RoundOfAmt,0)<>0                                                  
BEGIN                                                  
SET @JVID=@JVID+1;                                                  
IF ISNULL(@RoundOfAmt,0)>0                                                  
BEGIN                                                  
