@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                                                  
--Customer Account Cr                                                  
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],CBy ,CDate,                                                  
TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID )                                                  
VALUES (@JVID, @DocId, @DocRefId, @DocValue,@InvDate ,@DocRef ,@Accid,@RoundOfAmt,0,0,NULL,''Sales Return'',@Status,@UID ,GETDATE (),                                                  
@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                                                  
END                                                  
IF ISNULL(@RoundOfAmt,0)<0                                               
BEGIN                                                  
--Customer Account Dr                                                  
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],CBy ,CDate,                                                  
TransId ,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID)                                                  
VALUES (@JVID, @DocId, @DocRefId, @DocValue,@InvDate ,@DocRef ,@Accid,0,ABS(@RoundOfAmt),0,NULL,''Sales Return'',@Status,@UID ,GETDATE (),                                                  
@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                                                  
--Round Off Acount Negative Cr                                                  
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],CBy ,CDate ,                                                  
TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,BranchID)                                                  
VALUES (@JVID, @DocId, @DocRefId, @DocValue,@InvDate ,@DocRef ,82,ABS(@RoundOfAmt),0,0,NULL,''Sales Return'',@Status,@UID ,GETDATE (),                                        
@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@BranchID)                                                  
END                                                  
END                                              
IF(ISNULL(@DraftID,0) > 0 AND ISNULL(@FilterTypeID,0) = 2)-- Draft status change                                 
begin                                
UPDATE tblSalesdraftheader set Status = 5 where id = @DraftID                                
END          
