/****** uspManageService ******/
EXEC #Apply07 N'dbo.uspManageService', 0xE7099C682666A90DC83B500F28D8251B3A88480A82BA7D5A412B3A6C89605496, NULL, NULL, 0x1E12C214A0692A10D5F002D773512063655C507911D36E195582BD64CAB5D216, 0x5186DD7A09D5C34DD427CC64664FC779992C70229A33F52BCCCDFC7D4C5F370C, NULL,
N'ALTER PROC [dbo].[uspManageService]                  
@Mode INT,@ID smallint = null,@Name nvarchar(255) = null,@TaxID tinyint = null,@SACCode nvarchar(20) = null,@Inwardprice decimal(25,4) = null,                
@Outwardprice decimal(25,4) = null,@Active bit = null,@UserID smallint = null                
as                      
SET NOCOUNT ON;
begin                      
BEGIN TRY                          
set @Name = (select dbo.ProperCase(@Name))             
IF(@Mode = 1)                      
BEGIN                      
IF((SELECT count(*) FROM tblMasterService WITH (READCOMMITTEDLOCK) WHERE Name = @Name) > 0)                      
BEGIN                      
RAISERROR(''Already Exists'',16,1)                      
END                      
          
 set @Name = (select dbo.ProperCase(@Name))           
insert into tblMasterService(Name,TaxID,SACCode,Inwardprice,Outwardprice,Active,CBy,CDate)                       
Values (@Name,@TaxID,@SACCode,ISNULL(@Inwardprice,0),isnull(@Outwardprice,0),@Active,@UserID, GETDATE())                      
SELECT SCOPE_IDENTITY()                      
END                      
IF(@Mode = 2)                      
BEGIN                      
IF((SELECT count(*) FROM tblMasterService WITH (READCOMMITTEDLOCK) WHERE Name = @Name AND ID != @ID) > 0)                      
BEGIN                      
RAISERROR(''Already Exists'',16,1)                      
END                      
   INSERT INTO tblMasterHistory (FormID,ID,Name,Column1,Column2,Column3,Column4,Active,CBy,CDate,MBy,MDate,HisCBy,HisCDate)        
(select 18,*,@UserID, GETDATE() from tblMasterService WITH (READCOMMITTEDLOCK) where ID = @ID)         
 set @Name = (select dbo.ProperCase(@Name))           
UPDATE tblMasterService SET Name = @Name,TaxID = @TaxID,SACCode = @SACCode,Inwardprice = ISNULL(@Inwardprice,0),Outwardprice = isnull(@Outwardprice,0),                
Active = @Active,MBy = @UserID ,MDate = GETDATE() WHERE ID = @ID                      
SELECT @ID                      
END                      
IF(@Mode = 3)                      
BEGIN                      
SELECT MS.ID,Name,MT.TaxID,MT.TaxName,SACCode,dbo.fngetroundedvalue(Inwardprice) Inwardprice,dbo.fngetroundedvalue(Outwardprice) Outwardprice,    
MS.Active,CASE WHEN ISNULL(MS.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,  
 CASE WHEN ISNULL(MS.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MS.CDate) ELSE CONVERT(NVARCHAR(100),MS.MDate) END LastActionTime from tblMasterService MS WITH (READCOMMITTEDLOCK)              
JOIN tblMasterTax MT WITH (READCOMMITTEDLOCK) ON MT.TaxID = MS.TaxID   
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MS.CBy            
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MS.MBy    
order by MS.Name                      
END                      
IF(@Mode = 4)                      
BEGIN                      
SELECT MS.ID,Name,MT.TaxID,MT.TaxName,SACCode,dbo.fngetroundedvalue(Inwardprice) Inwardprice,dbo.fngetroundedvalue(Outwardprice) Outwardprice,    
MS.Active,CASE WHEN ISNULL(MS.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,  
 CASE WHEN ISNULL(MS.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),MS.CDate) ELSE CONVERT(NVARCHAR(100),MS.MDate) END LastActionTime
 from tblMasterService MS WITH (READCOMMITTEDLOCK)              
JOIN tblMasterTax MT WITH (READCOMMITTEDLOCK) ON MT.TaxID = MS.TaxID 
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = MS.CBy            
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = MS.MBy  
where MS.ID = @Name                
END                
IF(@Mode = 5)                      
BEGIN                      
SELECT * from tblMasterTax WITH (READCOMMITTEDLOCK) order by TaxName                      
END               
END TRY                            
BEGIN CATCH                            
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC]                            
END CATCH                            
END',
N'[export] nocount;readcommittedlock=12';
GO
/****** uspManageSingleMaster ******/
EXEC #Apply07 N'dbo.uspManageSingleMaster', 0xB13F847802F02AE323DA0BD69DCEDFDB00AE184BFB3505A9CEBC016530BCDFCA, 0x386BD53B267CEF0E4887616ECC0AF272883A86266ECA0273EFA662406B3590AD, NULL, 0x099548B07454803A8307123E1E882FD749DFEA019A05EFF59E6BC776F812E876, 0xAF2FAF73EC89B29889B8BAB2F0B9078E0CE6048B4FD74BB065330DF3133F1681, NULL,
N'--exec uspManageSingleMaster 1,3,2,''AXIS BANK PVT LTD'',1,3                        
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspManageSingleMaster]                    
@FormID int,@Mode int,@ID Smallint = NULL,@Name NVARCHAR(MAX) = NULL,@Active BIT = NULL,@CBy SMALLINT = NULL                        
AS                        
SET NOCOUNT ON;
BEGIN                        
BEGIN TRY                        
          
set @Name = (select dbo.ProperCase(@Name))                 
declare @TableName nvarchar(255) = (select TableName from tblTablesNames where ID = @FormID)                    
declare @strQuery NVARCHAR(MAX)                    
if EXISTS (select * from sys.tables where name = ''''+@TableName+'''')                    
BEGIN                    
IF(@Mode = 1)-- CREATE/ADD NEW Data                        
BEGIN                        
SET @strQuery = ''  IF ISNULL((SELECT COUNT(*) FROM dbo.''+QUOTENAME(@TableName)+'' WHERE [Name]= @Name ),0) >0                          
 BEGIN                          
  RAISERROR(''''Name Already Exists'''',16,1)                          
 END                         
INSERT INTO dbo.''+QUOTENAME(@TableName)+''([Name],Active,CBy,CDate) VALUES ( @Name , @Active , @CBy ,GETDATE())                        
select SCOPE_IDENTITY()  ''                    
EXEC sys.sp_executesql @strQuery, N''@FormID int, @Mode int, @ID Smallint, @Name NVARCHAR(MAX), @Active BIT, @CBy SMALLINT'', @FormID, @Mode, @ID, @Name, @Active, @CBy                    
END                        
IF(@Mode = 2)-- Modify Existing Data                        
BEGIN                        
SET @strQuery = ''  IF ISNULL((SELECT COUNT(*) FROM dbo.''+QUOTENAME(@TableName)+'' WHERE [Name]=  @Name  and ID !=  @ID ),0) >0                          
 BEGIN                          
  RAISERROR(''''Name Already Exists'''',16,1)                          
 END                         
 INSERT INTO tblMasterHistory (FormID,ID,Name,Active,CBy,CDate,MBy,MDate''+
 (case when CONVERT(nvarchar(50),@FormID) = ''2'' then '',PLName'' else '''' end)+'',HisCBy,HisCDate)          
(select  @FormID ,*, @CBy ,GETDATE() from dbo.''+QUOTENAME(@TableName)+'' where ID =  @ID )           
UPDATE dbo.''+QUOTENAME(@TableName)+'' SET [Name]= @Name ,Active= @Active ,MBy= @CBy ,MDate=GETDATE() WHERE ID = @ID ''                        
set @strQuery = @strQuery + '' SELECT  @ID ''                     
EXEC sys.sp_executesql @strQuery, N''@FormID int, @Mode int, @ID Smallint, @Name NVARCHAR(MAX), @Active BIT, @CBy SMALLINT'', @FormID, @Mode, @ID, @Name, @Active, @CBy                    
END                        
IF(@Mode = 3)-- Get All details                        
BEGIN                        
SET @strQuery = '' SELECT PH.*,CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,    
 CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),PH.CDate) ELSE CONVERT(NVARCHAR(100),PH.MDate) END LastActionTime FROM dbo.''+QUOTENAME(@TableName)+'' PH    
JOIN tblUsers CUR ON CUR.ID = PH.CBy              
LEFT JOIN tblUsers MUR ON MUR.ID = PH.MBy      
WHERE PH.ID != ''+(CASE WHEN @FormID = 12 THEN '' 1 '' ELSE ''0'' END)+'' ORDER BY PH.[Name]''                        
EXEC sys.sp_executesql @strQuery, N''@FormID int, @Mode int, @ID Smallint, @Name NVARCHAR(MAX), @Active BIT, @CBy SMALLINT'', @FormID, @Mode, @ID, @Name, @Active, @CBy                    
END                        
IF(@Mode = 4)-- Get Particular  details by  Name                        
BEGIN                        
SET @strQuery = ''  SELECT * FROM dbo.''+QUOTENAME(@TableName)+'' WHERE [Name] =  @Name ''                    
EXEC sys.sp_executesql @strQuery, N''@FormID int, @Mode int, @ID Smallint, @Name NVARCHAR(MAX), @Active BIT, @CBy SMALLINT'', @FormID, @Mode, @ID, @Name, @Active, @CBy                    
END                    
END                    
ELSE                    
BEGIN                    
DECLARE @ERR NVARCHAR(255) = ''Table ( ''+@TableName+'') Not Found''                    
RAISERROR(@ERR,16,1)                    
END                    
END TRY                        
BEGIN CATCH                        
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC]                        
END CATCH                        
END',
N'[06] nocount';
GO
/****** uspManageTax ******/
EXEC #Apply07 N'dbo.uspManageTax', 0x670890E67731CA8AA3C341800AA5E4C8093D6D7523185884EA91B585E83126AE, NULL, NULL, 0x2F34799EED2F83785B3CB86BB8229C63C981221B46C6B4F71621BF25D9D81F25, 0x9D96568A6A36B32FB622FEF1B8C3CF6693D94BE3EE100E7A68106E2C59A763E0, NULL,
N'ALTER PROCEDURE [dbo].[uspManageTax]
@Mode int,@ID INT=NULL, @TaxName NVARCHAR(255),@GST DECIMAL (25,6),@IGST DECIMAL (25,6),@GSTUOM DECIMAL (25,6) = NULL,
@IGSTUOM DECIMAL (25,6) = NULL ,@tvpTaxDetail dbo.tvpTaxDetail READONLY,@Uid INT,@Active INT
AS
SET NOCOUNT ON;
BEGIN TRY
DECLARE @ScopeID INT
if(@Mode = 1)--new
BEGIN
IF ISNULL((SELECT COUNT(*) FROM dbo.tblMasterTax WITH (READCOMMITTEDLOCK) WHERE TaxName= @TaxName),0) >0
BEGIN
RAISERROR(''Tax Name Already Exists'',16,1)
END
set @TaxName = (select dbo.ProperCase(@TaxName))  
INSERT INTO tblMasterTax(TaxName,GST,IGST,GUOM,IUOM,CBy,CDate,Active)
VALUES (@TaxName,@GST,@IGST,@GSTUOM,@IGSTUOM,@Uid,GETDATE (),@Active)
set @ScopeID =(SELECT SCOPE_IDENTITY());
END
ELSE
BEGIN
IF ISNULL((SELECT COUNT(*) FROM dbo.tblMasterTax WITH (READCOMMITTEDLOCK) WHERE TaxName= @TaxName AND TaxID != @ID ),0) >0
BEGIN
RAISERROR(''Tax Name Already Exists'',16,1)
END
set @TaxName = (select dbo.ProperCase(@TaxName))  
UPDATE tblMasterTax SET TaxName=@TaxName,GST=@GST,IGST=@IGST,GUOM = @GSTUOM,IUOM = @IGSTUOM,
Active=@Active,Mby=@Uid,Mdate=GETDATE()
WHERE TaxID = @ID
SET @ScopeID = @ID;
END
DELETE FROM tblMasterTaxDetail where TaxID = @ScopeID

INSERT INTO tblMasterTaxDetail
SELECT @ScopeID,TaxTypeID,TaxCompID,TaxRate,AppOn,PartOff,CumulativeTax,GSTTaxType FROM @tvpTaxDetail
SELECT @ScopeID
END TRY
BEGIN CATCH
SELECT ERROR_MESSAGE(),ERROR_LINE(),ERROR_PROCEDURE()
END CATCH',
N'[export] nocount;readcommittedlock=2';
GO
