/****** uspManageTodayRoute ******/
EXEC #Apply07 N'dbo.uspManageTodayRoute', 0xB56168137503AFFD763D29075C64DFCBB0D42EF37C4160287AD1ED035CB041D5, NULL, NULL, 0x94801DBE88D715D3799DBE2A606626E6EF87E043EA1E98DC22D0E3F3D1146B68, 0x981F8D9B52E9A03487FC790B98673E3AAD8A47B2CE6F979F093C5034CF0800DD, NULL,
N'ALTER PROC [dbo].[uspManageTodayRoute]      
@Mode INT,@UserID INT = 0,@BeatID INT = 0,@SalesmanID INT= 0 ,@BranchID int = 0     
AS      
SET NOCOUNT ON;
BEGIN      
IF(@Mode = 1)      
BEGIN      
SELECT 1 Type,''Beat'' Trans,ID,Name FROM tblMasterBeat WITH (READCOMMITTEDLOCK) WHERE Active = 1                            
union all                            
SELECT 2 Type,''Salesman'' Trans,ID,Name FROM tblMasterSalesman WITH (READCOMMITTEDLOCK) WHERE Active = 1         
union all                            
SELECT 3 Type,''Branch'' Trans,ID,Name FROM tblMasterBranchOffice WITH (READCOMMITTEDLOCK) WHERE Active = 1     
union all                            
SELECT 4 Type,''User'' Trans,ID,UserName Name FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE Active = 1  and ID <> 1  
order by Type,Name      
END      
IF(@Mode = 2)      
BEGIN      
SELECT isnull(BeatID,0) BeatID,isnull(SalesmanID,0) SalesmanID,isnull(BranchID,0) BranchID,
isnull(PrintProfileID,0) PrintProfileID ,UPIID  FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE ID = @UserID      
END      
IF(@Mode = 3)      
BEGIN      
UPDATE TBLUSERS SET BeatID = @BeatID,SalesmanID = @SalesmanID,BranchID = @BranchID WHERE ID = @UserID      
END      
END',
N'[export] nocount;readcommittedlock=5';
GO
/****** uspManageTranContra ******/
EXEC #Apply07 N'dbo.uspManageTranContra', 0x96AA9C518FBA8961EB39D3FEF8C540FB8C11FAC282476B5311395B0BFC55005A, NULL, NULL, 0x55C6B47ACBACB56F89D7C5F7757A104D65B66C5F6F4127DF91646DC92BF84745, 0x45560277F53984839AAC1A8EF6832C88DD999D99D2814C19FC0DB39EA1935851, NULL,
N'ALTER PROCEDURE [dbo].[uspManageTranContra]
@Status INT,@ContraID INT=NULL,@DocDate DATE,@TypeId INT,@ModeId INT=NULL,@SalesManId INT=NULL,@Amount DECIMAL (25,6),@RefernceNo NVARCHAR(255)=NULL,
@AIAccountID INT,@WDSlipNo NVARCHAR(50)=NULL,@ChequeNo INT=NULL,@ChequeNoWithRef NVARCHAR(255)=NULL,@TAAccountID INT=NULL,
@Narration NVARCHAR(255)=NULL,@Remarks NVARCHAR(255)=NULL,@UID INT,@UDFId INT=NULL,@nAllowNegativeBal INT=NULL,
@strIFSC_Code NVARCHAR(255)=NULL,@nCurrentStatus INT , @BranchID INT
AS
SET NOCOUNT ON;
BEGIN TRAN
BEGIN TRY
DECLARE @DocValue INT, @SCOPID INT,@DocId NVARCHAR(50),@PartyAcc INT,@AccID INT,@nStatus INT
DECLARE @AccCount INT,@AccountName NVARCHAR(255),@UDFDocId NVARCHAR(255),@UDFDocValue INT,@UDFDocPrefix NVARCHAR(255),@CheckUDFId INT
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)

DECLARE @BankFAAccID INT,@TempChequeNo INT,@ChequeRefNoWithChequeNo NVARCHAR(50),@BankAccID INT,@RefNo NVARCHAR(50)
DECLARE @ChequeBookID INT , @TempModeID INT,@ChequeInfo NVARCHAR(255)

declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))
DECLARE @DocSeriesIdent int

DECLARE @TempBankAccID INT
if(ISNULL(@Status,0) = 3) -- IF VARIANT SET STATUS TO 1(create)
BEGIN
SET @Status = 1
END
IF ISNULL(@TypeId,0) = 2 AND ISNULL(@ModeId,0) = 2
BEGIN
SET @ChequeInfo = @ChequeNoWithRef+'', ''+CONVERT(NVARCHAR,@DocDate,103)+(CASE WHEN ISNULL(@strIFSC_Code,'''')='''' THEN '''' ELSE '' - ''+@strIFSC_Code END)
END

IF(@Status =1)
BEGIN
insert into @tblDocdetails
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate) and BranchID = @BranchID and TransID = 8
IF((select count(*) from @tblDocdetails) = 0)
BEGIN
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)
END

SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails

UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = 8 and ID = @DocSeriesIdent
--SELECT @DocValue=DocValue,@DocId=DocPrefix + CONVERT(NVARCHAR, DocValue) FROM tblDocumentSeries WHERE TransID=8
--UPDATE tblDocumentSeries SET DocValue=1+ISNULL(DocValue,0) WHERE TransID = 8
IF ISNULL(@UDFId,0)>0
BEGIN
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@UDFId
END
END
print @Status---
IF(@Status =2)
BEGIN
SELECT @nStatus = Status FROM tblTranContra WITH (READCOMMITTEDLOCK) WHERE ID = @ContraID
--SELECT * FROM tblTranContra WHERE ContraID = 328
print @nStatus
print @nCurrentStatus
IF((@nStatus != @nCurrentStatus) OR @nStatus IN (2,4))
BEGIN
RAISERROR(''Document status already changed'',16,1);
END
SELECT @DocValue=DocValue,@UDFDocValue=UDFDocValue,@CheckUDFId=UDFId,@DocId = DocId FROM tblTranContra WITH (READCOMMITTEDLOCK) WHERE ID =@ContraID
--SELECT @DocId=DocPrefix + CONVERT(NVARCHAR, @DocValue) FROM tblDocumentSeries WHERE TransID=8
IF ISNULL(@UDFId,0)>0
BEGIN
IF(@UDFId=@CheckUDFId)
BEGIN
SELECT @UDFDocId=DocPrefix + CONVERT(NVARCHAR, @UDFDocValue),@UDFDocPrefix=DocPrefix FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId
END
IF(@UDFId!=@CheckUDFId)
BEGIN
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue) FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@UDFId
END
END
-- Cancel Cheque If Modify

SELECT @TempModeID=ModeId FROM tblTranContra WITH (READCOMMITTEDLOCK) WHERE ID = @ContraID
IF @TempModeID=2
BEGIN
SELECT @BankAccID = FromFAID,@TempChequeNo=ChequeNo,@ChequeRefNoWithChequeNo=ChequeNumberWithRef
FROM tblTranContra WITH (READCOMMITTEDLOCK) where ID = @ContraID

SELECT @TempBankAccID = ID FROM tblMasterBankAccount WITH (READCOMMITTEDLOCK) WHERe FAID = @BankAccID
SET @RefNo=(SELECT SUBSTRING(@ChequeRefNoWithChequeNo,0,(SELECT CHARINDEX(''-'', @ChequeRefNoWithChequeNo))-1))
SET @ChequeBookID=(SELECT ChequebookId FROM tblMasterChequeBook WITH (READCOMMITTEDLOCK) WHERE BankAccountID=@TempBankAccID AND ChequeBookreferNo=@RefNo)
UPDATE tblMasterChequeBookDetail SET [Status]=4 WHERE ChequebookId=@ChequeBookID AND ChequeNo=@TempChequeNo
END
END

IF @Status=1 OR @Status=2
BEGIN
-- Cheque Status
IF @ModeId=2
BEGIN
SET @RefNo=(SELECT SUBSTRING(@ChequeNoWithRef,0,(SELECT CHARINDEX(''-'', @ChequeNoWithRef))-1))
SET @ChequeBookID=(SELECT ChequebookId FROM tblMasterChequeBook CBH WITH (READCOMMITTEDLOCK)
join tblMasterBankAccount MBA WITH (READCOMMITTEDLOCK) ON MBA.ID = CBH.BankAccountID
WHERE FAID=@AIAccountID AND ChequeBookreferNo=@RefNo)
UPDATE tblMasterChequeBookDetail SET [Status]=5 WHERE ChequebookId=@ChequeBookID AND ChequeNo=@ChequeNo
END
--GET Cash ID
--Get Financial Acc ID''s
DECLARE @FromAccID INT,@ToAccID INT
--DECLARE @CASHID INT
DECLARE @PYModeAmt DECIMAL (25,6),@PYFAType NVARCHAR(10)
DECLARE @PYOutputValue TABLE (Amt DECIMAL(18,9),FAType NVARCHAR(10))

IF @TypeId=1
BEGIN
SELECT @FromAccID= FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=''Cash'';
--SELECT @ToAccID= FAID FROM tblMasterBankAccount WHERE ID=@AIAccountID
SET @ToAccID=@AIAccountID
--INSERT INTO @PYOutputValue(Amt,FAType) EXEC uspLoadClosingBalance 1,@FromAccID,@DocDate
---- Get Value From Result
--SELECT @PYModeAmt=Amt,@PYFAType=FAType FROM @PYOutputValue
---- Check Balance < Collected Amount
--IF ISNULL(@nAllowNegativeBal,0)=0
--BEGIN
--IF @PYFAType=''Cr'' OR @PYModeAmt<@Amount
--BEGIN
--RAISERROR(''CASH'' ,16,1)
--END
--END
END
IF @TypeId=2
BEGIN
--SELECT @FromAccID= FAID FROM tblMasterBankAccount WHERE ID=@AIAccountID
SET @FromAccID=@AIAccountID
SELECT @ToAccID=FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=''Cash'';
--INSERT INTO @PYOutputValue(Amt,FAType) EXEC uspLoadClosingBalance 1,@FromAccID,@DocDate
---- Get Value From Result
--SELECT @PYModeAmt=Amt,@PYFAType=FAType FROM @PYOutputValue
---- Check Balance < Collected Amount
--IF ISNULL(@nAllowNegativeBal,0)=0
--BEGIN
--IF @PYFAType=''Cr'' OR @PYModeAmt<@Amount
--BEGIN
--RAISERROR(''BALANCE'' ,16,1)
--END
--END

END

IF @TypeId=3
BEGIN
--SELECT @FromAccID= FAID FROM tblMasterBankAccount WHERE ID=@AIAccountID
--SELECT @ToAccID= FAID FROM tblMasterBankAccount WHERE ID=@TAAccountID
SET @FromAccID=@AIAccountID
SET @ToAccID=@TAAccountID
--INSERT INTO @PYOutputValue(Amt,FAType) EXEC uspLoadClosingBalance 1,@FromAccID,@DocDate
---- Get Value From Result
--SELECT @PYModeAmt=Amt,@PYFAType=FAType FROM @PYOutputValue
---- Check Balance < Collected Amount
--IF ISNULL(@nAllowNegativeBal,0)=0
--BEGIN
--IF @PYFAType=''Cr'' OR @PYModeAmt<@Amount
--BEGIN
--RAISERROR(''BALANCE'' ,16,1)
--END
--END

END
IF @TypeId=4 -- Branch Transfer
BEGIN
----SELECT @FromAccID= AccountID FROM tblMasterBankAccount WHERE ID=@AIAccountID
SELECT @FromAccID= FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=''Cash''
SET @ToAccID=@AIAccountID
--SELECT @ToAccID= AccountID FROM tblMasterBankAccount WHERE ID=''Cash''

--INSERT INTO @PYOutputValue(Amt,FAType) EXEC uspLoadClosingBalance 1,@AIAccountID,@DocDate
---- Get Value From Result
--SELECT @PYModeAmt=Amt,@PYFAType=FAType FROM @PYOutputValue
---- Check Balance < Collected Amount
--IF ISNULL(@nAllowNegativeBal,0)=0
--BEGIN
--IF @PYFAType=''Cr'' OR @PYModeAmt<@Amount
--BEGIN
--RAISERROR(''BALANCE'' ,16,1)
--END
--END
END
END

IF(@Status =2)
BEGIN
UPDATE tblTranContra SET [Status]=@Status,MBy =@UID ,MDate =GETDATE() WHERE ID =@ContraID AND TransID =8
UPDATE tblFAJournal SET [Status] =@Status,MBy =@UID ,MDate =GETDATE() WHERE TransId =@ContraID AND DocPrefix =8
SET @Status =@Status +1;
END

IF(@Status =4)
BEGIN
SELECT @nStatus = Status FROM tblTranContra WITH (READCOMMITTEDLOCK) WHERE ID = @ContraID
print @nStatus
print @nCurrentStatus
IF((@nStatus != @nCurrentStatus) OR @nStatus IN (2,4))
BEGIN
RAISERROR(''Document status already changed'',16,1);
END

UPDATE tblTranContra SET [Status]=@Status,ClBy =@UID ,ClDate =GETDATE(),Remarks = @Remarks,Narration = @Narration WHERE ID =@ContraID AND TransID =8
UPDATE tblFAJournal SET [Status] =@Status,ClBy =@UID ,ClDate =GETDATE(),Remarks = @Remarks,Narration = @Narration WHERE TransId =@ContraID AND DocPrefix =8
-- Cancel Cheque Status
SELECT @TempModeID=ModeId FROM tblTranContra WITH (READCOMMITTEDLOCK) WHERE ID = @ContraID
IF @TempModeID=2
BEGIN
SELECT @BankAccID=FromFAID,@TempChequeNo=ChequeNo,@ChequeRefNoWithChequeNo=ChequeNumberWithRef FROM tblTranContra WITH (READCOMMITTEDLOCK) where ID = @ContraID
SELECT @TempBankAccID=ID FROM tblMasterBankAccount WITH (READCOMMITTEDLOCK) WHERe FAID=@BankAccID
SET @RefNo=(SELECT SUBSTRING(@ChequeRefNoWithChequeNo,0,(SELECT CHARINDEX(''-'', @ChequeRefNoWithChequeNo))-1))
SET @ChequeBookID=(SELECT ChequebookId FROM tblMasterChequeBook WITH (READCOMMITTEDLOCK) WHERE BankAccountID=@TempBankAccID AND ChequeBookreferNo=@RefNo)
UPDATE tblMasterChequeBookDetail SET [Status]=4 WHERE ChequebookId=@ChequeBookID AND ChequeNo=@TempChequeNo
END
END

IF(@Status !=4)
BEGIN
IF(@Status = 1)
BEGIN
IF((SELECT COUNT(DocValue) FROM tblTranContra WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and
DocDate BETWEEN @F_SD AND @F_ED and TransID = 8) != 0)-- and Status in (1,3,5)
BEGIN
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)
END
ENd
IF(@Status = 2)
BEGIN
IF((SELECT COUNT(DocValue) FROM tblTranContra WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and
DocDate not BETWEEN @F_SD AND @F_ED and TransID = 8) != 0)-- and Status in (1,3,5)
BEGIN
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)
END
ENd
-- Bank Transfer
IF @TypeId=3
BEGIN
INSERT INTO tblTranContra(DocDate,TypeId,ModeId,SalesManId,Amount,RefNo,FromFAID,WDSlipNo,ChequeNo,
ChequeNumberWithRef,ToFAID,Narration,CBy,DocID,TransID,DocValue,Balance,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CDate,[Status],Remarks,BranchID)
VALUES(@DocDate,@TypeId,@ModeId,@SalesManId,@Amount,@RefernceNo,@FromAccID,@WDSlipNo,@ChequeNo,
@ChequeNoWithRef,@ToAccID,@Narration,@UID,@DocID,8,@DocValue,@Amount,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,GETDATE(),@Status,@Remarks,@BranchID)
END
-- Cash WithDraw
IF @TypeId=2
BEGIN
INSERT INTO tblTranContra(DocDate,TypeId,ModeId,SalesManId,Amount,RefNo,FromFAID,WDSlipNo,ChequeNo,
ChequeNumberWithRef,ToFAID,Narration,CBy,DocID,TransID,DocValue,Balance,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CDate,[Status],Remarks,BranchID)
VALUES(@DocDate,@TypeId,@ModeId,@SalesManId,@Amount,@RefernceNo,@FromAccID,@WDSlipNo,@ChequeNo,
@ChequeNoWithRef,@ToAccID,@Narration,@UID,@DocID,8,@DocValue,@Amount,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,GETDATE(),@Status,@Remarks,@BranchID)
END
--Cash Deposit
IF @TypeId=1
BEGIN
INSERT INTO tblTranContra(DocDate,TypeId,ModeId,SalesManId,Amount,RefNo,FromFAID,WDSlipNo,ChequeNo,
ChequeNumberWithRef,ToFAID,Narration,CBy,DocID,TransID,DocValue,Balance,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CDate,[Status],Remarks,BranchID)
VALUES(@DocDate,@TypeId,@ModeId,@SalesManId,@Amount,@RefernceNo,@FromAccID,@WDSlipNo,@ChequeNo,
@ChequeNoWithRef,@ToAccID,@Narration,@UID,@DocID,8,@DocValue,@Amount,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,GETDATE(),@Status,@Remarks,@BranchID)
END
--Branch Transfer
IF @TypeId=4
BEGIN
INSERT INTO tblTranContra(DocDate,TypeId,ModeId,SalesManId,Amount,RefNo,FromFAID,WDSlipNo,ChequeNo,
ChequeNumberWithRef,ToFAID,Narration,CBy,DocID,TransID,DocValue,Balance,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,CDate,[Status],Remarks,BranchID)
VALUES(@DocDate,@TypeId,@ModeId,@SalesManId,@Amount,@RefernceNo,@ToAccID,@WDSlipNo,@ChequeNo,
@ChequeNoWithRef,@FromAccID,@Narration,@UID,@DocID,8,@DocValue,@Amount,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,GETDATE(),@Status,@Remarks,@BranchID)
END
SET @SCOPID=( SELECT SCOPE_IDENTITY())
-- Posting
DECLARE @JVID INT
SELECT @JVID=ISNULL(MAX(JVID),0)+1 FROM tblFAJournal WITH (READCOMMITTEDLOCK)
IF (@TypeId=1 OR @TypeId=4)
BEGIN
INSERT INTO tblFAJournal (DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,
CBy,CDate,[Status],TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)
VALUES(@DocID,8,@DocValue,@DocDate,@RefernceNo,@ToAccID,0,@Amount,@Amount,'''',@Narration,
@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)

INSERT INTO tblFAJournal(DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,
CBy,CDate,[Status],TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)
VALUES (@DocID,8,@DocValue,@DocDate,@RefernceNo,@FromAccID,@Amount,0,@Amount,'''',@Narration,
@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)
END
IF (@TypeId=2)
BEGIN
INSERT INTO tblFAJournal (DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,
CBy,CDate,[Status],TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,ChequeInfo,Adjusment,BranchID)
VALUES(@DocID,8,@DocValue,@DocDate,@RefernceNo,@FromAccID,@Amount,0,@Amount,'''',@Narration,
@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,@ChequeInfo,0,@BranchID)
INSERT INTO tblFAJournal(DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,
CBy,CDate,[Status],TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,ChequeInfo,Adjusment,BranchID)
VALUES (@DocID,8,@DocValue,@DocDate,@RefernceNo,ISNULL(@ToAccID,0),0,@Amount,@Amount,'''',@Narration,
@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,@ChequeInfo,0,@BranchID)
END
IF (@TypeId=3)
BEGIN
INSERT INTO tblFAJournal(DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,
CBy,CDate,[Status],TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)
VALUES (@DocID,8,@DocValue,@DocDate,@RefernceNo,@FromAccID,@Amount,0,@Amount,'''',@Narration,
@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)

INSERT INTO tblFAJournal (DocID,DocPrefix,DocValue,DocDate,DocRef,AccountID,Credit,Debit,Balance,Remarks,Narration,
CBy,CDate,[Status],TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)
VALUES(@DocID,8,@DocValue,@DocDate,@RefernceNo,@ToAccID,0,@Amount,@Amount,'''',@Narration,
@UID,GETDATE(),ISNULL(@Status,1),@SCOPID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)
END
END
--IF @Status != 4
BEGIN
SELECT @SCOPID
END
COMMIT TRAN
END TRY
BEGIN CATCH
ROLLBACK TRAN
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(),ERROR_LINE()
END CATCH',
N'[export] nocount;number-series-updlock=4;readcommittedlock=21';
GO
/****** uspManageTransactionPrint ******/
EXEC #Apply07 N'dbo.uspManageTransactionPrint', 0x787724D12D1AC9175238CDC8CBC8E9ED60F314F1F2AF23722E3688D2DAE02853, NULL, NULL, 0xCC97DD9ABB4D3136442019E5B33104F929EB0D66B9795D8C1B59BAC5C5AC7147, 0xA22C58A6583D4646B96E971EA27BBFA82FB2F1F80B9226DEB8AF2CB7B302604C, NULL,
N'--[uspManageTransactionPrint] 1,2     
ALTER proc [dbo].[uspManageTransactionPrint]        
@Mode INT,@UID int = 0      
AS        
SET NOCOUNT ON;
begin
IF(@Mode = 1)        
BEGIN        
DECLARE @DefBranchID int = 0,@RoleID int      
if(isnull(@UID,0) > 0)      
BEGIN      
SELECT @DefBranchID = BranchID,@RoleID =RoleID FROM tblUsers WHERE ID = @UID      
END      
  
SELECT * INTO #TranPrefixs      
FROM tblYearwiseDocumentSeries WHERE BranchID = @DefBranchID AND CONVERT(DATE,GETDATE()) BETWEEN FromDate AND ToDate      
  
CREATE TABLE #TempData(Type INT,Trans VARCHAR(50),ID INT,Name VARCHAR(100),TransID INT,DefaultConfig INT,NoCopies INT,  
Prefix VARCHAR(50));  
  
--537  
INSERT INTO #TempData  
select 1 Type,''Transaction'' Trans,TN.Id ID,TransName Name,0 TransID,0 DefaultConfig,0 NoCopies,TP.Prefix from tblTransName TN      
LEFT JOIN #TranPrefixs TP ON TP.TransID = TN.DocID      
join tblRolePermissions RP ON RP.PermissionFormId = TN.MenuID    
where Active = 1 and (@RoleID = 1 OR RP.Role = @RoleID)    
GROUP BY TN.Id,TransName,TP.Prefix  
  
INSERT INTO #TempData  
SELECT 2 Type,''Profiles'' Trans,PrintID,ConfigName,TransactionID TransID,      
ISNULL(PRT.DefaultConfig,0) DefaultConfig,ISNULL(PRT.NoCopies,1) NoCopies,NULL Prefix FROM tblPrintConfig PC      
LEFT JOIN tblPrinterConfig PRT ON PRT.ConfigID = PC.PrintID      
WHERE Active = 1   
  
IF((SELECT COUNT(*) FROM tblRolePermissions WHERE Role = @RoleID AND PermissionFormId = 537) > 0)  
BEGIN  
INSERT INTO #TempData  
select 1 Type,''Transaction'' Trans,TN.Id ID,TransName Name,0 TransID,0 DefaultConfig,0 NoCopies,TP.Prefix   
from tblTransName TN      
LEFT JOIN #TranPrefixs TP ON TP.TransID = TN.DocID      
join tblRolePermissions RP ON RP.PermissionFormId = TN.MenuID    
where Active = 1 AND TN.Id = 4  
GROUP BY TN.Id,TransName,TP.Prefix  
  
INSERT INTO #TempData  
SELECT 2 Type,''Profiles'' Trans,PrintID,ConfigName,TransactionID TransID,      
ISNULL(PRT.DefaultConfig,0) DefaultConfig,ISNULL(PRT.NoCopies,1) NoCopies,NULL Prefix FROM tblPrintConfig PC      
LEFT JOIN tblPrinterConfig PRT ON PRT.ConfigID = PC.PrintID      
WHERE Active = 1 AND PC.TransactionID = 4  
END  
  
SELECT * FROM #TempData  
GROUP BY Type,Trans,ID,Name,TransID,DefaultConfig,NoCopies,Prefix  
ORDER BY Type,Name  
  
drop table #TranPrefixs   ,#TempData   
END   
  IF(@Mode = 2)        
  BEGIN
  SELECT ID,UserName Name FROM tblUsers WHERE ID <> 1 ORDER BY UserName
  END
END',
N'[export] nocount';
GO
/****** uspManageTranSalesCancel ******/
EXEC #Apply07 N'dbo.uspManageTranSalesCancel', 0x0B927730030608D0A214E88C3E730484E25750A0FD5034FB7A2CE58775CE29CB, NULL, NULL, 0x219B1B92CB3B3EAC92991393FC566D60AEABE3F54B09B1B6E7BD64C39551EF49, 0x28F6A1ECFB5656A9BABFB285DCCCE3D4CDC184B63D27486222873E4F84A702D9, NULL,
N'-- uspManageTranSalesCancel 3,9469,2,5                
ALTER PROC [dbo].[uspManageTranSalesCancel]                
@CurrentStatus SMALLINT,@InvId INT,@UID INT,@Mode SMALLINT,@Remarks NVARCHAR(255) = NULL,@Narration NVARCHAR(MAX) = NULL                 
AS                
SET NOCOUNT ON;
BEGIN TRY                
DECLARE @Bool VARCHAR(100), @Status INT, @TransType INT,@TempId INT,@TempDocValue INT,@TempSalesDocValue INT,@nStatus INT                
DECLARE @SalesDate DATE,@SelesOrSRDocPrefix INT,@DispatchId INT,@TempDispatchDocValue INT,@DispatchDate DATE ,@BoolCancel SMALLINT=0                
DECLARE @nDocPrefix INT,@OldNetAmt decimal(25,4),@CustId int        
                
--check THIS inv document is used in SR or not                
IF((SELECT COUNT(*) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE OrgInvID = @InvId) > 0 AND @Mode != 2)                
BEGIN                
RAISERROR(''21'',16,1);                
END                
SELECT @nStatus = [Status] From tblTranSalesHeader WITH (READCOMMITTEDLOCK) Where ID = @InvId          
IF((@nStatus != @CurrentStatus) or @nStatus in (2,4))  
BEGIN          
RAISERROR(''Document Status already changed'',16,1)          
END     
    
if((isnull((SELECT COUNT(*) AS DeliveryCount FROM tblDeliveryOrderHeader DH WITH (READCOMMITTEDLOCK)    
JOIN tblDeliveryOrderDetail DD WITH (READCOMMITTEDLOCK) ON DD.DOID = DH.ID    
WHERE DH.Status IN (1,3,5) AND DD.Status IN (1,5) AND DD.InvIdentID = @InvId    
GROUP BY DD.InvIdentID),0)) > 0)    
BEGIN    
RAISERROR(''This document already processed in Delivery'',16,1)      
END    

if((isnull((SELECT COUNT(*) AS DeliveryCount FROM tblAssignInvoicesHeader DH WITH (READCOMMITTEDLOCK)    
JOIN tblAssignInvoicesDetail DD WITH (READCOMMITTEDLOCK) ON DD.HID = DH.ID    
WHERE DH.Status IN (1,3,5) AND DD.Status IN (1,5) AND DD.InvID = @InvId    
GROUP BY DD.InvID),0)) > 0)    
BEGIN    
RAISERROR(''This document already processed in Assigned Invoice'',16,1)      
END   

SET @Bool=[dbo].[funValidateSalesTran](@CurrentStatus ,@InvId)                
-- Check and Update Collection Status = 4                
                
SELECT @nDocPrefix = DocPrefix,@OldNetAmt = NetAmt,@CustId = CustID FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id=@InvId                
IF @Bool = ''TRUE'' AND (SELECT DocPrefix FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id=@InvId)=15                
BEGIN                
DECLARE @CollIDs AS TABLE (Serial INT IDENTITY(1,1), TempColID INT)                
DECLARE @SalesRtnCollID AS TABLE (DocPrefix INT, SRID INT, AdjAmt DECIMAL(25,6))                
-- Revert Collection Status for Inserting                
INSERT INTO @CollIDs                
SELECT ColID FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK)                
WHERE ColID IN (SELECT ColID FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE DocID = @InvId) AND Type=1                
-- Revert Sales Return Status for Inserting                
INSERT INTO @SalesRtnCollID                
SELECT DocPrefix,DocID,TotalAmtAdj                
FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE ColID IN (SELECT TempColID FROM @CollIDs) AND DocPrefix IN (3,6)                
                
IF (SELECT PaymentModeId FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id = @InvId)=8                
BEGIN                
IF (SELECT COUNT(*) FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE DocID = @InvId) > 0                
BEGIN                
IF (SELECT COUNT(ColID) FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE ColID IN                
(SELECT ColID FROM tblTranCollectionDetail WITH (READCOMMITTEDLOCK) WHERE DocID = @InvId AND DocPrefix = @nDocPrefix) AND Type=0 AND Status IN (1,5)) > 0                
BEGIn                
SET @Bool = ''16''                
END                
ELSE                
BEGIN                
SET @Bool = ''TRUE''                
END                
END                
END                
                
IF @Bool = ''TRUE''                
BEGIN                
DECLARE @ColSerial INT = 1, @ColCount INT = (SELECT COUNT(TempColID) FROM @CollIDs)                
WHILE @ColCount > 0                
BEGIN                
DECLARE @CollID INT = (SELECT TempColID FROM @CollIDs WHERE Serial = @ColSerial)                
DECLARE @PayModeID INT = (SELECT ColMode FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE ColID = @CollID)                
IF (SELECT Status FROM tblTranCollectionHeader WITH (READCOMMITTEDLOCK) WHERE ColID = @CollID) != 1 OR                
(SELECT Status FROM tblCollPMDetails WITH (READCOMMITTEDLOCK) WHERE ColID = @CollID) != 1                
BEGIN                
SET @Bool = ''16''                
BREAK;                
END                
--IF ISNULL(@PayModeID,0)=6 -- DENOMINATION                
--BEGIN                
--DECLARE @tempActualCount INT,@SettledCount INT                
--SELECT @tempActualCount=ISNULL(SUM(DCount),0),@SettledCount=ISNULL(SUM(SettlementCount),0)                
--FROM tblmastdenominationPMDetails WHERE FormDocPrefix=5 AND TransID=@CollID                
--IF @tempActualCount=@SettledCount                
--BEGIN                
--UPDATE tblmastdenominationPMDetails SET Status=4 WHERE FormDocPrefix=5 AND TransID=@CollID                
--END                
--ELSE                
--BEGIN                
--RAISERROR(''17'',16,1)                
--END                
--END                
                
-- Updating Collection Status = 4                
UPDATE tblTranCollectionHeader SET Status=4,ClBy=@UID,ClDate=GETDATE(),Remarks = @Remarks,Narration = @Narration WHERE ColID = @CollID                
UPDATE tblCollPMDetails SET Status=4 WHERE ColID = @CollID                
UPDATE tblFAJournal SET Status=4,ClBy=@UID,ClDate=GETDATE(),Remarks = @Remarks,Narration = @Narration WHERE TransId=@CollID AND DocPrefix=19--COLL                
                
SET @ColSerial = @ColSerial + 1;                
SET @ColCount = @ColCount - 1;                
END                
-- Update Sales Return Status = 6 or 7 and Revert Net Amount                
UPDATE tblTranSalesHeader SET Balance=NetAmt WHERE Id=@InvId                
IF (SELECT COUNT(*) FROM @SalesRtnCollID) > 0                
BEGIN                
UPDATE tblTranSalesHeader SET Balance=(Balance+SR.AdjAmt),Status=(                
CASE              
WHEN (SELECT COUNT(DocId) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK)                
WHERE DocId IN (SELECT DocId FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id = SR.SRID)                
AND (InvDate BETWEEN (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) AND (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)))) = 1                
THEN (CASE WHEN TransactionType=2 THEN 6 ELSE 7 END)                
ELSE 3                
END)                
FROM @SalesRtnCollID AS SR WHERE Id = SR.SRID AND SR.DocPrefix=6                
UPDATE tblNoteDetails SET Balance=(Balance+SR.AdjAmt),Status=1                
FROM @SalesRtnCollID AS SR WHERE ID = SR.SRID AND SR.DocPrefix=3  END                
END                
END                
                
IF @Bool !=''TRUE''                
BEGIN                
RAISERROR(@Bool,16,1);                
END                
ELSE                
BEGIN --Revert Qty and Posting                
SELECT @Status=[Status],@TransType=TransactionType,@TempSalesDocValue=DocValue,@SalesDate=InvDate,@SelesOrSRDocPrefix=DocPrefix                
FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id =@InvId                
END                
IF @Mode =2 OR @Mode=5                
BEGIN                
SET @BoolCancel=1;                
END                
ELSE IF @Mode =4 AND ISNULL(@TransType,0)<>5                
BEGIN                
SET @BoolCancel=1;                
END                
--Direct Sales or Saleable Return or Damage Return                
IF ISNULL(@BoolCancel,0)=1                
BEGIN                
DECLARE CursorCancelSR CURSOR LOCAL FAST_FORWARD                
FOR (SELECT InventoryId ,QtyType ,AdjustQty FROM tblTranSalesDetail WHERE InvID=@InvId AND ISNULL(InventoryId ,0)>0 )                
DECLARE @CancelQty DECIMAL(25,6),@CancelQtyT INT,@CancelInvId INT                
OPEN CursorCancelSR                
FETCH NEXT FROM CursorCancelSR INTO @CancelInvId,@CancelQtyT,@CancelQty                
WHILE @@FETCH_STATUS =0                
BEGIN /*All Record loop and verify based on Invoice Id*/                
                
IF ISNULL(@SelesOrSRDocPrefix,0)=15                
BEGIN                
IF(@Status =1 OR @Status =3 OR @Status =5)                
BEGIN /*Sales Invoice Cancel Update*/                
IF(@CancelQtyT =1)                
BEGIN                
UPDATE tblProductInventory SET ActualQty =ISNULL(ActualQty,0)+ISNULL(@CancelQty,0),InvoiceQty = ISNULL(InvoiceQty,0)-ISNULL(@CancelQty,0) WHERE InventoryId =@CancelInvId                
END                
IF(@CancelQtyT =2)                
BEGIN                
UPDATE tblProductInventory SET ActualFreeQty =ISNULL(ActualFreeQty,0)+ISNULL(@CancelQty,0),InvoiceFreeQty = ISNULL(InvoiceFreeQty,0)-ISNULL(@CancelQty,0) WHERE InventoryId =@CancelInvId                
END                
SET @CancelQty=0                
END                
END                
ELSE                
BEGIN                
IF(@Status=6 OR @Status=3)                
BEGIN /*Sales Return Saleable Cancel*/                
PRINT CONVERT(NVARCHAR(255),@CancelInvId)                
IF(@CancelQtyT =1)                
BEGIN                
IF(@CancelQty<= ISNULL((SELECT ActualQty FROM tblProductInventory WITH (READCOMMITTEDLOCK) WHERE InventoryId= @CancelInvId),0))                
BEGIN                
UPDATE tblProductInventory SET ActualQty=ISNULL(ActualQty,0)-ISNULL(@CancelQty,0),SRQty =ISNULL(SRQty,0) -ISNULL(@CancelQty,0),                
RecdQty =ISNULL(RecdQty,0) -ISNULL(@CancelQty,0)                
WHERE InventoryId=@CancelInvId                
SET @CancelQty=0                
END                
END                
IF(@CancelQtyT =2)                
BEGIN                
IF(@CancelQty<= ISNULL((SELECT ActualFreeQty FROM tblProductInventory WITH (READCOMMITTEDLOCK) WHERE InventoryId= @CancelInvId),0))                
BEGIN UPDATE tblProductInventory SET ActualFreeQty=ISNULL(ActualFreeQty,0)-ISNULL(@CancelQty,0),SRFreeQty =ISNULL(SRFreeQty,0)-ISNULL(@CancelQty,0),                
RecdFreeQty =ISNULL(RecdFreeQty,0) -ISNULL(@CancelQty,0)                
WHERE InventoryId=@CancelInvId                
SET @CancelQty=0                
END                
END                
END                
IF(@Status =7 OR @Status=3)                
BEGIN /* Sales Return Damage Cancel */                
IF(@CancelQty<= ISNULL((SELECT ActualDmgQty FROM tblProductInventory WITH (READCOMMITTEDLOCK) WHERE InventoryId= @CancelInvId),0))                
BEGIN                
UPDATE tblProductInventory SET ActualDmgQty=ISNULL(ActualDmgQty,0)-ISNULL(@CancelQty,0),SRDmgQty =ISNULL(SRDmgQty,0)-ISNULL(@CancelQty,0),                
RecdDmgQty =ISNULL(RecdDmgQty,0) -ISNULL(@CancelQty,0)                
WHERE InventoryId=@CancelInvId                
SET @CancelQty=0                
END                
END                
END                
IF(@CancelQty!=0)                
BEGIN /* Any one Qty miss matched Revert */                
CLOSE CursorCancelSR                
DEALLOCATE CursorCancelSR                
RAISERROR(''10'',16,1);                
END                
FETCH NEXT FROM CursorCancelSR INTO @CancelInvId,@CancelQtyT,@CancelQty                
END                
CLOSE CursorCancelSR                
DEALLOCATE CursorCancelSR                
END                
--Update Mode Wise Modify OR cancel                
IF(@Mode=2)                
BEGIN /*Sales Header Table Status Change Modify(3)*/                
UPDATE tblTranSalesHeader SET [Status]=2,MBy =@UID ,MDate =GETDATE () WHERE Id=@InvId                
END                
/*Sales Header Table Status Change Cancel(4)*/                
IF(@Mode=4 OR @Mode=5)                
BEGIN                
                
IF ISNULL(@Mode,0)=4                
BEGIN        
--Revert Track Point when Cancel        
declare @nTPMode int = (case when @nDocPrefix = 15 then 2 else 1 end)        
EXEC [uspAddTrackPoint] @OldNetAmt,@nTPMode,@CustId        
UPDATE tblTranSalesHeader SET [Status]=4,ClBy=@UID,ClDate=GETDATE() ,Remarks = @Remarks,Narration = @Narration               
WHERE Id=@InvId                
END                
ELSE                
BEGIN                
UPDATE tblTranSalesHeader SET [Status]=2,MBy=@UID,MDate=GETDATE()               
WHERE Id=@InvId                
END                
--cancel denomination                
DECLARE @Paymode INT                
SET @Paymode=(SELECT PaymentModeId FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id=@InvId)                
--IF @Paymode=8                
--BEGIN                
--UPDATE tblmastdenominationPMDetails                
--SET [Status]=4,Cby =@UID ,Cdate =GETDATE ()                
--WHERE TransID=@InvId and FormDocPrefix=@SelesOrSRDocPrefix                
--END                
END                
                
--Invoice or Sales Return Posting Status Change Cancel(4)                
IF ISNULL(@Mode,0)!=5                
BEGIN                
UPDATE tblFAJournal SET [Status]= @Mode,ClBy =@UID ,ClDate=GETDATE(),Remarks = @Remarks,Narration = @Narration                
WHERE TransId=@InvId AND DocPrefix =@SelesOrSRDocPrefix                
END                
ELSE                
BEGIN                
UPDATE tblFAJournal SET [Status]=2,MBy =@UID ,MDate =GETDATE()                
WHERE TransId=@InvId AND DocPrefix =@SelesOrSRDocPrefix                
END                
END TRY                
BEGIN CATCH                
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE();                
END CATCH',
N'[export] nocount;cursor-local-fast_forward=1;readcommittedlock=27';
GO
/****** uspManageTranSalesColl ******/
EXEC #Apply07 N'dbo.uspManageTranSalesColl', 0x5901115585481BF82E58C646BCC6B290F9D2574AD08C0826D9ACDD09863641CF, NULL, NULL, 0x1483C7FEB464DC21186C2ACC09283E0EE2230D815CC9B9E6D7D941514275B5CF, 0x12E53740A1A801034042625356EEDBC2CA1925E68C589211B0B5FD553861A392, NULL,
N'ALTER PROC [dbo].[uspManageTranSalesColl]    
@UID INT,@InvId INT,@tvpAdjInvCrNote tvpAdjInvCrNote READONLY,@tvpTranSalesMop tvpTranSalesMop READONLY,    
@BeatID INT=NULL,@SalesManID INT=NULL,@tvpSaveDenomination dbo.tvpSaveDenomination READONLY,@BranchID int
AS    
BEGIN TRY    
SET DATEFORMAT DMY;    
SET NOCOUNT ON;    
--Declaration of variable    
DECLARE @CustId INT,@Accid INT,@PaymentModeId INT,@CrAdjCount INT,@Index INT,@InvDate DATE,@DocRef NVARCHAR(255),@DocId NVARCHAR(255),    
@DocValue INT,@NoteId INT,@CrDocPrefix INT,@CrDocValue INT ,@CrDate NVARCHAR(25),@CrAdjAmt DECIMAL (25,6),@ActiveCheck INT,    
@TotalNetAmt DECIMAL (25,6),@TCrNoteAdjValue DECIMAL (25,6)    
--Get Invoice Details    
SELECT @CustId=CustId,@PaymentModeId=PaymentModeId,@InvDate=InvDate,@DocRef=DocRef,@DocId=DocId,    
@DocValue=DocValue,@TCrNoteAdjValue=CreditNoteAdjAmt,@TotalNetAmt=NetAmt    
FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id =@InvId    
--Get Customer Account Id    
SELECT @Accid=FAID FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE ID =@CustId    
SET @CrAdjCount=(SELECT COUNT(*) FROM @tvpAdjInvCrNote)    
DECLARE @Header tvpCollHeader,@Detail tvpCollDetail,@Mop tvpCollMop    
--IF PaymentMode Credit but Adjusted Credit Note or Sales Return    
IF (@PaymentModeId = 7 AND ISNULL(@CrAdjCount,0)>0)    
BEGIN    
--IF Credit Adjust Amt their is Payment Mode store in 9    
IF ISNULL(@CrAdjCount,0)>0    
BEGIN    
SET @PaymentModeId =9    
END    
--Collection Header    
INSERT INTO @Header VALUES(CONVERT(NVARCHAR(50),@InvDate,103),1,@DocRef ,@Accid,0 ,0,@PaymentModeId,1,0,@UID,1,1,null,null)    
--Collection Detail    
INSERT INTO @Detail VALUES(@Accid,15,@DocValue, @InvId,@InvDate,ISNULL(@TotalNetAmt,0),    
ISNULL(@TCrNoteAdjValue,0),0,0,0,0,0,ISNULL(@TCrNoteAdjValue,0),0,1,0)    
--Credit Note Adjustment    
IF ISNULL(@CrAdjCount,0) >0    
BEGIN    
DECLARE CursorAdjCrNote CURSOR LOCAL FAST_FORWARD FOR (SELECT NoteID,DocPrefix,DocValue,CrNoteDate,Balance FROM @tvpAdjInvCrNote)    
OPEN CursorAdjCrNote    
FETCH NEXT FROM CursorAdjCrNote INTO @NoteId,@CrDocPrefix,@CrDocValue,@CrDate ,@CrAdjAmt    
WHILE @@FETCH_STATUS =0    
BEGIN    
INSERT INTO @Detail VALUES(@Accid ,@CrDocPrefix,@CrDocValue,@NoteId,CONVERT(DATE,@CrDate,103) ,@CrAdjAmt,@CrAdjAmt,0,0,0,0,0,@CrAdjAmt,0,1,0)    
--Credit Note Value Store in Sales Transaction Adjment Table    
INSERT INTO tblTransSaleAdjDetail (InvId ,NoteId ,DocPrefix ,DocValue,DocDate,Balance )    
VALUES(@InvId , @NoteId,@CrDocPrefix,@CrDocValue, @CrDate, @CrAdjAmt)    
FETCH NEXT FROM CursorAdjCrNote INTO @NoteId,@CrDocPrefix,@CrDocValue,@CrDate ,@CrAdjAmt    
END    
CLOSE CursorAdjCrNote    
DEALLOCATE CursorAdjCrNote    
END    
END    
--Collection Implicit Posting Sales Transaction Multi payment mode Only    
ELSE IF(@PaymentModeId = 8)    
BEGIN    
DECLARE @PaymentCount INT, @PaymentIndex INT,@InvCurrentAmt DECIMAL (25,6),@AddAdjustmentIndex INT =0 ,@MOPCount INT =0    
SET @PaymentCount=(SELECT COUNT(*) FROM @tvpTranSalesMop)    
SET @MOPCount= @PaymentCount    
SET @PaymentIndex=1    
SELECT @InvCurrentAmt=ISNULL(Balance,0) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE Id =@InvId    
WHILE @PaymentCount >0    
BEGIN    
DECLARE @ReceivedAmt DECIMAL (25,6),@ChqDDNo NVARCHAR(25), @chqDate NVARCHAR(25),@BankAccNo NVARCHAR(255),@BankAccID INT ,    
@IFSCCode NVARCHAR(25),@Bank NVARCHAR(255),@Branch NVARCHAR(255),@PayAt NVARCHAR(255),@Balance DECIMAL (25,6),@VisaPern DECIMAL (25,6), @VisaAmt DECIMAL (25,6)    
--Get Record    
SELECT @PaymentModeId=[PayModeId],@ChqDDNo=[Cheque_OR_DDNumber_OR_NEFTId],@BankAccNo=[BankAccNo],@BankAccID=[BankAccID],@chqDate=[PMDate],    
@PayAt=[PayAt],@IFSCCode=[IfscCode],@Bank=[Bank] ,@Branch=[Branch] ,@ReceivedAmt=[Amt] , @Balance = isnull([Balance],0),@VisaPern = [VisaPern], @VisaAmt =[VisaAmt]    
FROM @tvpTranSalesMop WHERE [SerialNo]=@PaymentIndex    
    
--Transaction Sales payment detail    
INSERT INTO tblTran_Sale_Bill_PaymentDetail(TransId,InvId,[PayModeId],[Cheque_OR_DDNumber_OR_NEFTId],Acc_OR_PaytermId,[PMDate],[PayAt],[IfscCode],[Bank] ,    
[Branch] ,[Amt] ,[SerialNo],RecdAmt,VisaPer,VisaAmt )VALUES(15,@InvId,@PaymentModeId,@ChqDDNo,@BankAccID,@chqDate,@PayAt,@IFSCCode,@Bank,@Branch,@ReceivedAmt ,@PaymentIndex,@Balance,@VisaPern,@VisaAmt)    
--Restrict Credit Mode    
IF ISNULL(@PaymentModeId,0) != 7    
BEGIN    
--Collection Header    
INSERT INTO @Header VALUES(CONVERT(NVARCHAR(50),@InvDate,103),1,@DocRef ,@Accid,@ReceivedAmt ,0,@PaymentModeId,1 ,0,@UID,1,@PaymentIndex,@VisaPern,@VisaAmt)    
--Mop Detail    
INSERT INTO @Mop VALUES(@Accid,@PaymentModeId,@ChqDDNo,CONVERT(NVARCHAR(50),@chqDate,103),@BankAccID,@ChqDDNo ,@ReceivedAmt,@IFSCCode ,@Bank ,    
@Branch ,@PayAt,@BankAccNo,null,0,@PaymentIndex,@Balance)    
IF (ISNULL(@TCrNoteAdjValue,0)>0 AND @AddAdjustmentIndex=0)    
BEGIN    
--Credit Note Adjustment    
IF ISNULL(@CrAdjCount,0) >0    
BEGIN    
DECLARE CursorAdjCrNote CURSOR LOCAL FAST_FORWARD FOR (SELECT NoteID,DocPrefix,DocValue,CrNoteDate,Balance FROM @tvpAdjInvCrNote)    
OPEN CursorAdjCrNote    
FETCH NEXT FROM CursorAdjCrNote INTO @NoteId,@CrDocPrefix,@CrDocValue,@CrDate ,@CrAdjAmt    
WHILE @@FETCH_STATUS =0    
BEGIN    
-- Col Detail    
INSERT INTO @Detail VALUES(@Accid ,@CrDocPrefix,@CrDocValue,@NoteId,CONVERT(DATE,@CrDate,103) ,@CrAdjAmt,@CrAdjAmt,0,0,0,0,0,@CrAdjAmt,0,@PaymentIndex,0)    
--Credit Note Value Store in Sales Transaction Adjment Table    
INSERT INTO tblTransSaleAdjDetail (InvId ,NoteId ,DocPrefix ,DocValue,DocDate,Balance )    
VALUES(@InvId, @NoteId,@CrDocPrefix,@CrDocValue, @CrDate, @CrAdjAmt)    
FETCH NEXT FROM CursorAdjCrNote INTO @NoteId,@CrDocPrefix,@CrDocValue,@CrDate ,@CrAdjAmt    
END    
CLOSE CursorAdjCrNote    
DEALLOCATE CursorAdjCrNote    
END    
-- Col Detail    
INSERT INTO @Detail VALUES(@Accid,15,@DocValue, @InvId,@InvDate,@InvCurrentAmt,ISNULL(@ReceivedAmt,0)+ISNULL(@TCrNoteAdjValue,0),0,0,0,0,0,    
ISNULL(@ReceivedAmt,0)+ISNULL(@TCrNoteAdjValue,0),0,@PaymentIndex,0)    
SET @InvCurrentAmt=@InvCurrentAmt-(ISNULL(@ReceivedAmt,0)+ISNULL(@TCrNoteAdjValue,0))    
SET @AddAdjustmentIndex=1;    
END    
ELSE    
BEGIN    
-- Col Detail    
INSERT INTO @Detail VALUES(@Accid,15,@DocValue, @InvId,@InvDate,@InvCurrentAmt,@ReceivedAmt,0,0,0,0,0,@ReceivedAmt,0,@PaymentIndex,0)    
SET @InvCurrentAmt=@InvCurrentAmt-@ReceivedAmt;    
END    
END    
--Only Credit Mode and MOP Detail Count 1 and Adjustment is Adjust    
ELSE IF (@PaymentModeId = 7 AND @MOPCount=1 AND ISNULL(@CrAdjCount,0) >0)    
BEGIN    
--Collection Header    
INSERT INTO @Header VALUES(CONVERT(NVARCHAR(50),@InvDate,103),1,@DocRef ,@Accid,0 ,0,@PaymentModeId,1,0,@UID,1,1,null,null)    
--Collection Detail    
INSERT INTO @Detail VALUES(@Accid,15,@DocValue, @InvId,@InvDate,ISNULL(@TotalNetAmt,0),    
ISNULL(@TCrNoteAdjValue,0),0,0,0,0,0,ISNULL(@TCrNoteAdjValue,0),0,1,0)    
--Adjustment    
IF ISNULL(@CrAdjCount,0) >0    
BEGIN    
DECLARE CursorAdjCrNote CURSOR LOCAL FAST_FORWARD FOR (SELECT NoteID,DocPrefix,DocValue,CrNoteDate,Balance FROM @tvpAdjInvCrNote)    
OPEN CursorAdjCrNote    
FETCH NEXT FROM CursorAdjCrNote INTO @NoteId,@CrDocPrefix,@CrDocValue,@CrDate ,@CrAdjAmt    
WHILE @@FETCH_STATUS =0    
BEGIN    
INSERT INTO @Detail VALUES(@Accid ,@CrDocPrefix,@CrDocValue,@NoteId,CONVERT(DATE,@CrDate,103) ,@CrAdjAmt,@CrAdjAmt,0,0,0,0,0,@CrAdjAmt,0,1,0)    
--Credit Note Value Store in Sales Transaction Adjment Table    
INSERT INTO tblTransSaleAdjDetail (InvId ,NoteId ,DocPrefix ,DocValue,DocDate,Balance )    
VALUES(@InvId, @NoteId,@CrDocPrefix,@CrDocValue, @CrDate, @CrAdjAmt)    
FETCH NEXT FROM CursorAdjCrNote INTO @NoteId,@CrDocPrefix,@CrDocValue,@CrDate ,@CrAdjAmt    
END    
CLOSE CursorAdjCrNote    
DEALLOCATE CursorAdjCrNote    
END    
END    
SET @PaymentCount=@PaymentCount-1;    
SET @PaymentIndex=@PaymentIndex+1;    
END    
END    
    
IF ((SELECT ISNULL(COUNT(*),0) FROM @Header)>0)    
BEGIN    
-- Get UDN for Collection    
DECLARE @UDFCount INT,@UDNSingle INT    
SET @UDFCount = (SELECT COUNT(DISTINCT UDNId) FROM tblMasterUserDefineNoDetail WITH (READCOMMITTEDLOCK)    
WHERE UDNId IN (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (READCOMMITTEDLOCK) WHERE TransID=19) AND UserId=@UID)    
IF ISNULL(@UDFCount,0)=1    
BEGIN    
SET @UDNSingle = (SELECT DISTINCT UDNId FROM tblMasterUserDefineNoDetail WITH (READCOMMITTEDLOCK) WHERE UDNId IN (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (READCOMMITTEDLOCK) WHERE TransId=19)AND UserId=@UID )    
END    
    
EXEC uspManageFullColl 19,@UDNSingle,@Header,@Detail,@Mop,1,@BeatID,@SalesManID,NULL,@tvpSaveDenomination ,1,0,1,0,null,null,@BranchID    
END    
    
SET NOCOUNT OFF;    
END TRY    
BEGIN CATCH    
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE();    
END CATCH',
N'[export] cursor-local-fast_forward=3;readcommittedlock=7';
GO
/****** uspManageTransPurchaseBill ******/
EXEC #Apply07 N'dbo.uspManageTransPurchaseBill', 0x8070D6BCFD8C1E47BD7B47EF7C758FD42DF3979050BE5A0D4F2F36D6E5A9B114, NULL, NULL, 0xE377C0945C1E34C7CBE1AC9331F1FC38B3C6A3D7AEAA0E2AFB074D00D0BDCF9B, 0xB32A5DAB30F7485DE460ADFD388428869407E3276685FCA4572012566A7825CE, NULL,
N'ALTER PROC [dbo].[uspManageTransPurchaseBill]--2000            
(@Mode INT,@BillId INT = NULL,@BranchID INT = NULL,@nCurrStatus int,@BillDate DATE,@VendorId INT,@TotalGrossAmt DECIMAL (25,6),@TotalTaxAmt DECIMAL (25,6),@TotalNetAmt DECIMAL (25,6),            
@GRNRefNo NVARCHAR(255)=NULL,@PGroupID INT=NULL,@TaxTypeID INT,@PaymentTermId INT=NULL,@paymentDate NVARCHAR(25)=NULL,            
@PaymentModeId INT=NULL ,@vehicleno NVARCHAR(255)=NULL,@Frieght DECIMAL (25,6)= NULL,@OtherCharge DECIMAL(25,6)=NULL,            
@OtherChargeamt DECIMAL (25,6)=NULL,@ProdDisc DECIMAL(25,6)=NULL,@TradeDisc DECIMAL(25,6)=NULL,@AddnlDisc DECIMAL(25,6)=NULL,            
@TotalProdDiscAmt DECIMAL (25,6)= NULL,@TotalTradeDiscAmt DECIMAL (25,6)= NULL,@TotalAddnlDiscAmt DECIMAL (25,6)= NULL,            
@WrightOffAmt DECIMAL (25,6)= NULL,@UID INT,@RoundOffAmt DECIMAL (25,6)= NULL,@tvpTranBillDetail AS [tvpTranBillDetail] READONLY,            
@tvpTranBillMop AS [tvpTranBillMop] READONLY,@UDFId INT =NULL ,@IFBIll SMALLINT=1,@nAllowNegativeBal INT=NULL,@IS_IMPORT INT=NULL,            
@DateBill DATE=NULL,@TCSPern DECIMAL(25,6) = NULL,@TCSAmt DECIMAL(25,6) = NULL,@TDSAmt DECIMAL(25,6) = NULL,@ImportStatus INT = 0,            
@Remarks NVARCHAR(25)=NULL,@Narration NVARCHAR(25)=NULL,@DraftID INT = 0,@tvpSaveDenomination dbo.tvpSaveDenomination READONLY,            
@DiffValueGross DECIMAL(25,4) = 0,@DiffValueNet DECIMAL(25,4) = 0,@UpdateVendor INT = 0,@FilterType INT = 1)            
AS            
BEGIN TRY            
SET DATEFORMAT dmy;            
SET NOCOUNT ON;            
DECLARE @AccId INT,@ScopeID INT            
DECLARE @docvalue INT ,@Status INT,@DocID NVARCHAR(255),@GRNDocID NVARCHAR(255),@UDFDocId NVARCHAR(255),@UDFDocValue INT,@UDFDocPrefix NVARCHAR(255),@CheckUDFId INT            
DECLARE @CheckStatus INT,@DrDetbitNote DECIMAL(25,6),@TempPOID int,@PreviousTranDate DATE,@Balance DECIMAL (25,6) ,@NET DECIMAL (25,6)           
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)            
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)            
declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))            
DECLARE @DocSeriesIdent int,@InvoiceID int      
SELECT @Accid=FAID FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE ID =@VendorId            
IF(@Mode = 1)            
BEGIN            
--SELECT @CheckStatus = [Status] FROM tblTranGRNHeader WHERE GRNID = @GRNID            
--IF(@CheckStatus != @nCurrStatus)            
--BEGIN            
--RAISERROR(''PROC'',16,1)            
--END            
--USER$ DEFINE NUMBER DOC VALIDATIONS            
insert into @tblDocdetails            
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@BillDate between FromDate and ToDate) and BranchID = @BranchID and TransID = 1            
IF((select count(*) from @tblDocdetails) = 0)            
BEGIN            
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)            
END            
IF(ISNULL(@GRNRefNo,'''') != '''')        
BEGIN        
IF((SELECT COUNT(*) FROM tblTransPurchaseHeader WITH (READCOMMITTEDLOCK) WHERE VendorID = @VendorId AND RefNo = @GRNRefNo) > 0)        
BEGIN        
RAISERROR (''Ref No already exists'',16,1)            
END        
END        
SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails            
            
UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = 1 and ID = @DocSeriesIdent            
            
IF ISNULL(@BillId,0)>0 -- PO to Bill            
BEGIN            
set @TempPOID = @BillId            
SET @BillId = 0            
END            
          
            
IF(ISNULL(@DraftID,0) > 0 and isnull(@FilterType,0) = 2)            
BEGIN            
exec uspValidateDraftData 1,1,@DraftID,@nCurrStatus             
END            
IF(ISNULL(@TempPOID,0) > 0 and isnull(@FilterType,0) = 3)            
BEGIN            
select @CheckStatus = Status from tblPurchaseorderheader WITH (READCOMMITTEDLOCK) WHERE ID = @TempPOID       
if((@CheckStatus != @nCurrStatus) OR @CheckStatus IN (2,4))
begin            
RAISERROR (''This Document status already changed'',16,1)                           
end          
ENd           
IF(ISNULL(@DraftID,0) > 0 and isnull(@FilterType,0) = 4)            
BEGIN            
set @InvoiceID = @DraftID;      
END       
IF ISNULL(@UDFId,0)>0            
BEGIN            
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)            
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId            
IF ISNULL(@IS_IMPORT,0)=0            
BEGIN            
UPDATE tblMasterUserDefineNoHeader SET DocValue=1+ISNULL(DocValue,0) WHERE UDNId=@UDFId            
END            
END           
--Set Status            
SET @Status=1            
SET @BillId=0   
ENd            
ELSE            
BEGIN            
            
--Get Difference Inentory Id From GRN Table            
CREATE TABLE #Temp(InvId INT)            
INSERT INTO #Temp SELECT GRND.InventoryId FROM tblTransPurchaseDetail GRND WITH (READCOMMITTEDLOCK)            
WHERE GRND.InventoryId NOT IN(SELECT InventoryId FROM @tvpTranBillDetail) AND GRND.HID =@BillId            
            
DECLARE @TempQty DECIMAL(25, 9),@TempFreeQty DECIMAL(25, 9),@TempDmgQty DECIMAL(25, 9),@TempInvId INT            
DECLARE Temp CURSOR LOCAL FAST_FORWARD FOR(SELECT InvId FROM #Temp)            
OPEN Temp            
FETCH NEXT FROM Temp INTO @TempInvId            
WHILE @@FETCH_STATUS =0            
BEGIN            
--Get Datail Inventory Id if Modify GRN            
SELECT @TempQty= (ISNULL(RecdQty,0)-ISNULL(ActualQty,0)),            
@TempFreeQty= (ISNULL(RecdFreeQty,0)-ISNULL(ActualFreeQty,0)),            
@TempDmgQty= (ISNULL(RecdDmgQty,0)-ISNULL(ActualDmgQty,0))            
FROM tblProductInventory WITH (READCOMMITTEDLOCK) WHERE InventoryId=@TempInvId            
--Any One Qty Miss Matched To Not Allow Modify A Batch            
IF(@TempQty=0 AND @TempFreeQty=0 AND @TempDmgQty=0)            
BEGIN            
UPDATE tblProductInventory SET RecdQty = 0,RecdFreeQty = 0,RecdDmgQty = 0, ActualQty = ISNULL(ActualQty,0)-ISNULL(RecdQty,0) ,            
ActualFreeQty =ISNULL(ActualFreeQty,0)-ISNULL(RecdFreeQty,0),ActualDmgQty = ISNULL(ActualDmgQty,0)-ISNULL(RecdDmgQty,0)            
WHERE InventoryId=@TempInvId            
END            
ELSE            
BEGIN            
RAISERROR(''Qty Miss Matched,Cannot Delete Product/Batch'',16,1);            
END            
FETCH NEXT FROM Temp INTO @TempInvId            
END            
            
SELECT @CheckStatus = [Status],@Balance = Balance,@NET = NetAmt FROM tblTransPurchaseHeader WITH (READCOMMITTEDLOCK) WHERE ID = @BillId          
IF((@CheckStatus != @nCurrStatus) OR @CheckStatus IN (2,4))            
BEGIN            
RAISERROR(''Document status already changed'',16,1)            
END            
IF(@NET != @Balance)          
BEGIN            
RAISERROR(''Document partially payment'',16,1)            
END              
--select [Status] from tblTranBillHeader where BillID = 2876            
UPDATE tblTransPurchaseHeader SET [Status]=2 ,Mby =@UID ,Mdate =GETDATE () Where ID = @BillId            
UPDATE tblFAJournal SET [Status]=2 ,Mby =@UID ,Mdate =GETDATE () WHERE TransId =@BillId AND DocPrefix =1            
            
            
--exec uspValidateBillModifyORCancel @nCurrStatus,@GRNId,@Mode,            
--Modify Bill Get Doc Value Amended Bill            
SELECT @docvalue=DocValue ,@DocID =DocID,@UDFDocValue=ISNULL(UDFDocValue,0),@CheckUDFId=ISNULL(UDFId,0),@InvoiceID = InvoiceID            
FROM tblTransPurchaseHeader WITH (READCOMMITTEDLOCK) WHERE ID =@BillId            
SET @Status=3            
IF ISNULL(@UDFId,0)>0            
BEGIn            
IF(@UDFId=@CheckUDFId)            
BEGIN            
SELECT @UDFDocId=DocPrefix + CONVERT(NVARCHAR, @UDFDocValue),@UDFDocPrefix=DocPrefix FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId            
END            
IF(@UDFId!=@CheckUDFId)            
BEGIN            
SELECT @UDFDocValue=DocValue,@UDFDocPrefix=DocPrefix,@UDFDocId=DocPrefix+ CONVERT(NVARCHAR, DocValue)            
FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE UDNId=@UDFId            
UPDATE tblMasterUserDefineNoHeader SET DocValue = ISNULL(DocValue,0)+1 WHERE UDNId =@UDFId            
END            
END            
END            
IF(@Mode = 1)-- OR @Mode = 2            
BEGIN            
IF((SELECT COUNT(DocValue) FROM tblTransPurchaseHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocID and             
Date BETWEEN @F_SD AND @F_ED and TransID = 1) != 0)-- and Status in (1,3,4,5)            
BEGIN            
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)              
END            
ENd            
IF(@Mode = 2)            
BEGIN            
IF((SELECT COUNT(DocValue) FROM tblTransPurchaseHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocID and             
Date not BETWEEN @F_SD AND @F_ED and TransID = 1) != 0)-- and Status in (1,3,4,5)            
BEGIN            
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)              
END            
ENd            
-----TDSamount value for Balance            
IF(ISNULL(@PaymentTermId,0) > 0)            
BEGIN            
SELECT @paymentDate = DATEADD(DD,Value,@BillDate) FROM tblMasterCreditTerm WITH (READCOMMITTEDLOCK) WHERE ID = @PaymentTermId            
END            
Declare @TDSBalance decimal(25,4)            
IF ISNULL(@Mode,0)=1 OR ISNULL(@Mode,0)=2            
BEGIN            
Set @TDSBalance=(@TotalNetAmt-@TDSAmt)            
END            
SET @TotalNetAmt = (ISNULL(@TotalNetAmt,0) )            
--Insert bill header            
INSERT INTO tblTransPurchaseHeader(Date,DocID,TransID,BranchID,DocValue,VENDorID,[Status],GrossAmt,TaxAmt,NetAmt,RefNo,ProdGroupID,TaxTypeID,PaymentTermID,PaymentDate,            
PaymentModeId, VehicleNo,Frieght,[OtherCharge%],OtherChargeAmt,[ProdDisc%],[TradeDisc%],[AddnlDisc%],TotalProdDiscAmt,TotalTradeDiscAmt,            
TotalAddnlDiscAmt,WriteOffAmt,RoundOffAmt, Balance,OrgId,Cby,Cdate,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,            
DateBill,TCSTaxPern,TCSTaxAmt,TDSAmount,Remarks,Narration,PriceType,DiffValueGross,DiffValueNet,InvoiceID)            
VALUES(@BillDate, @DocID,1 ,@BranchID,@docvalue,@VendorId,CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END ,            
@TotalGrossAmt,@TotalTaxAmt,@TotalNetAmt,@GRNRefNo,@PGroupID,@TaxTypeID,@PaymentTermId,            
(CASE WHEN ISNULL(@paymentDate,'''')='''' THEN NULL ELSE @paymentDate END),@PaymentModeId,@vehicleno,@Frieght,@OtherCharge,@OtherChargeamt,@ProdDisc,@TradeDisc,@AddnlDisc,@TotalProdDiscAmt,@TotalTradeDiscAmt,            
@TotalAddnlDiscAmt,@WrightOffAmt,@RoundOffAmt,@TDSBalance,@BillId,@UID,GETDATE (),@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,            
(CASE WHEN ISNULL(@DateBill,'''')='''' THEN @BillDate ELSE @DateBill END),@TCSPern,@TCSAmt,@TDSAmt,@Remarks,@Narration,1,@DiffValueGross,@DiffValueNet,@InvoiceID)            
--Scope Indentity for Bill Header Table            
            
SET @ScopeID=(SELECT SCOPE_IDENTITY())            
            
IF(@Mode = 1)            
BEGIN            
EXEC uspCreateBackTran 1,@BranchID,@ScopeID,0,1,@DocValue ,@BillDate,NULL,@UID            
END            
IF(@Mode = 2)            
BEGIN            
EXEC uspCreateBackTran @Mode,@BranchID,@ScopeID,@BillId,1,@DocValue ,@BillDate,@PreviousTranDate,@UID            
END            
--Variable declaration for Loop bill detail            
DECLARE @ProdID INT,@UOMID INT,@UomGrpID INT,@BatchNo NVARCHAR(255) = NULL,@PKD NVARCHAR(255) = NULL,@Expiry NVARCHAR(255) = NULL,@UomQty DECIMAL(25, 9) ,@UomFreeQty DECIMAL(25,9),            
@UomDamageQty DECIMAL(25, 9) ,@PurchasePrice DECIMAL (25,6),@SalePrice DECIMAL (25,6),@ECP DECIMAL (25,6),@MRP DECIMAL (25,6),@SPLPrice DECIMAL (25,6),@TaxID INT,@BTaxTypeId INT,            
@TaxPercentage DECIMAL (25,6),@GoodsAmt DECIMAL (25,6),@ProdDiscPercent DECIMAL (25,6) = NULL,@TradeDiscPercent DECIMAL (25,6) = NULL,@AddnlDiscPercent DECIMAL (25,6) = NULL,    
@ProdDiscAmount DECIMAL (25,6) = NULL,@TradeDiscAmount DECIMAL (25,6) = NULL,@AddnlDiscAmount DECIMAL (25,6) = NULL,    
@BGrossAmt DECIMAL (25,6),@BTaxAmt DECIMAL (25,6),@BNetAmt DECIMAL (25,6),@InvId INT,@InclusiveYesNo INT,@IsChrgProd INT = 0     
,@ReturnPrice DECIMAL (25,6),@InvScopeID INT = 0,@HSNCode NVARCHAR(255) = NULL,@ReasonID INT,@LocationID INT,@DiffAmt DECIMAL (25,4) = 0            
--Loop Detail using CURSOR            
DECLARE @PKDDate DATE,@ExpiryDate DATE            
DECLARE @PriceOnUomCF DECIMAL (25,6),@MRPOnUomCF DECIMAL (25,6),@SelectedUomCF DECIMAL (25,6) = 1,            
@Qty DECIMAL(25, 9),@FreeQty DECIMAL(25, 9),@DamageQty DECIMAL(25, 9)            
DECLARE @PUomId INT,@MRPUomId INT,@TrackPKD INT            
DECLARE @InventoryID INT =0            
DECLARE cursor_Temp CURSOR LOCAL FAST_FORWARD FOR (SELECT [ProdID] ,[UOMID],[UomGrpID],[BatchNo] ,[PKD] ,[Expiry], [Qty] , [FreeQty] , [DamageQty],            
[PurchasePrice],[SalePrice] ,[ECP] ,[MRP] ,[SPLPrice] , [TaxID] ,[TaxTypeId] ,[TaxPercentage] ,[GoodsAmt] ,[ProdDiscPercent],            
[TradeDiscPercent], [AddnlDiscPercent],[GrossAmt] ,[TaxAmt],[NetAmt] ,[InventoryId],InclusiveYesNo,ReturnPrice,UOMCR,HSN,ReasonID,LocationID,DiffAmt,    
ProdDiscAmount ,TradeDiscAmount ,AddnlDiscAmount    
FROM @tvpTranBillDetail)            
OPEN cursor_Temp            
FETCH NEXT FROM cursor_Temp INTO @ProdID , @UOMID ,@UomGrpID ,@BatchNo ,@PKD ,@Expiry ,@UomQty ,            
@UomFreeQty,@UomDamageQty ,@PurchasePrice ,@SalePrice ,@ECP ,@MRP ,@SPLPrice ,@TaxID ,@BTaxTypeId ,@TaxPercentage ,            
@GoodsAmt ,@ProdDiscPercent ,@TradeDiscPercent ,@AddnlDiscPercent ,@BGrossAmt ,@BTaxAmt ,@BNetAmt ,@InvId ,@InclusiveYesNo,            
@ReturnPrice,@SelectedUomCF,@HSNCode,@ReasonID,@LocationID,@DiffAmt,@ProdDiscAmount ,@TradeDiscAmount ,@AddnlDiscAmount            
DECLARE @GTaxAmt DECIMAL (25,6),@InclMRP DECIMAL (25,6)            
--SET @GTaxAmt =( @MRP * @TaxPercentage /100)            
--SET @InclMRP = (@MRP + @GTaxAmt)            
IF(@Status = 1 AND @Mode = 1)  
BEGIN  
SET @InvId = 0  
END  
DECLARE @BillDetailSerial INT = 1            
WHILE @@FETCH_STATUS =0            
BEGIN            
IF(@IFBIll=1)            
BEGIN --Direct Bill Screen            
IF ISDATE(CONVERT(NVARCHAR,@PKD,103))=1            
BEGIN            
SET @PKDDate=@PKD            
END            
ELSE            
BEGIN            
SET @PKDDate=NULL            
END            
IF ISDATE(CONVERT(NVARCHAR,@Expiry,103))=1            
BEGIN            
SET @ExpiryDate=@Expiry            
END            
ELSE            
BEGIN            
SET @ExpiryDate=NULL            
END            
END            
ELSE            
BEGIN --GRN wise Bill Create            
IF @PKD !=NULL OR @PKD !=''''            
BEGIN            
SET @PKDDate=@PKD            
END            
ELSE            
BEGIN            
SET @PKDDate=NULL            
END            
IF @Expiry!=NULL OR @Expiry!=''''            
BEGIN            
SET @ExpiryDate=@Expiry            
END            
ELSE            
BEGIN            
SET @ExpiryDate=NULL            
END            
END            
--Get Price On,MRP ON from Product Table            
SELECT @PUomId=PurchaseUomID,@PriceOnUomCF=PurchaseCR,@TrackPKD = TrackPDK--,@IsChrgProd = (CASE WHEN TrackInventory = 0 AND ChargesPern > 0 THEN 1 ELSE 0 END)            
FROM tblMasterProduct WITH (READCOMMITTEDLOCK) WHERE ID =@ProdID            
            
SET @Qty=@UomQty *@SelectedUomCF;            
SET @FreeQty=@UomFreeQty *@SelectedUomCF;            
SET @DamageQty=@UomDamageQty *@SelectedUomCF;            
            
-- Uom Convertion            
--SELECT @PriceOnUomCF=ConversionRate FROM tblMastUomGroupDetail WHERE UOMGroupID =@UomGrpID AND UOMMastID =@PUomId            
--SELECT @MRPOnUomCF=ConversionRate FROM tblMastUomGroupDetail WHERE UOMGroupID =@UomGrpID AND UOMMastID =@MRPUomId            
--SELECT @SelectedUomCF=ConversionRate FROM tblMastUomGroupDetail WHERE UOMGroupID =@UomGrpID AND UOMMastID =@UOMID            
--Insert In Purchase Bill Bill Detail Table            
--New Batch Insertion            
IF ISNULL(@InvId,0)=0            
BEGIn            
IF(@IsChrgProd = 0)            
BEGIN            
EXEC uspInsertInventory ''INSERT'',1,@BillDate,@DocValue,@ProdId,@UomGrpID,@UOMID,@Qty,@FreeQty,@DamageQty,@Qty,@FreeQty,            
@DamageQty,0,0,0,@Batchno ,@PKDDate,@ExpiryDate,@PurchasePrice,@SalePrice,@ECP,@SPLPrice,@MRP,@ReturnPrice,@TaxId ,@TaxTypeId ,            
@TaxPercentage,0,@InvScopeId OUT,0,@InclusiveYesNo,@UID,@BranchID,@SelectedUomCF            
END            
END            
ELSE            
BEGIN            
DECLARE @CheckBatchVerify INT            
IF(@TrackPKD =1)            
BEGIN            
SET @CheckBatchVerify =(SELECT COUNT(*) FROM tblProductInventory IP WITH (READCOMMITTEDLOCK)            
JOIN @tvpTranBillDetail TVP ON TVP .InventoryId =IP.InventoryId            
WHERE IP.InventoryId =@InvId AND ISNULL(IP.BatchNumber,'''')=ISNULL(TVP.BatchNo,'''')            
AND IP.PkdDate =CONVERT(DATE,TVP.PKD,103) AND IP.ExpiryDate =CONVERT(DATE,TVP.Expiry,103))            
END            
ELSE            
BEGIN            
SET @CheckBatchVerify =(SELECT COUNT(*) FROM tblProductInventory IP WITH (READCOMMITTEDLOCK)            
JOIN @tvpTranBillDetail TVP ON TVP .InventoryId =IP.InventoryId            
WHERE IP.InventoryId =@InvId AND ISNULL(IP.BatchNumber,'''')=ISNULL(TVP.BatchNo,''''))            
END            
            
--iyan----            
--If Change Batch Info To Verify Changes Allow or Not            
--IF(ISNULL(@CheckBatchVerify,0)=0)            
--BEGIN            
-- SELECT @TempQty=ISNULL(RecdQty,0)-(ISNULL(ActualQty,0)-ISNULL(SRQty,0)),            
-- @TempFreeQty=ISNULL(RecdFreeQty,0)-(ISNULL(ActualFreeQty,0)-ISNULL(SRFreeQty,0)),            
-- @TempDmgQty=ISNULL(RecdDmgQty,0)-(ISNULL(ActualDmgQty,0)-ISNULL(SRFreeQty,0))            
-- FROM tblProdInventory WHERE InventoryId=@InventoryID            
-- IF(@TempQty !=0 OR @TempFreeQty !=0 OR @TempDmgQty !=0)            
-- BEGIN            
-- RAISERROR(''Batch Cannot Change'',16,1);            
-- END            
--END            
--Find Required Qty            
DECLARE @RQTY DECIMAL(25, 9),@RFQTY DECIMAL(25, 9),@RDQTY DECIMAL(25, 9),@AQty DECIMAL(25, 9)            
DECLARE @AFQty DECIMAL(25, 9),@ADQty DECIMAL(25, 9),@SRQty DECIMAL(25, 9),@SRFQty DECIMAL(25, 9),@SRDQty DECIMAL(25, 9)            
            
SELECT @RQTY = RecdQty,@RFQTY =RecdFreeQty ,@RDQTY = RecdDmgQty,            
@AQty =ActualQty ,@AFQty =ActualFreeQty ,@ADQty =ActualDmgQty ,            
@SRQty =SRQty,@SRFQty = SRFreeQty ,@SRDQty = SRDmgQty            
FROM dbo.tblProductInventory WITH (READCOMMITTEDLOCK) WHERE InventoryId = @InvId            
            
DECLARE @FinalQty DECIMAL(25, 9),@FinalFreeQty DECIMAL(25, 9),@FinalDmgQty DECIMAL(25, 9)            
            
SET @FinalQty = @RQTY - (@AQty - @SRQty )            
SET @FinalFreeQty = @RFQTY - (@AFQty - @SRFQty)            
SET @FinalDmgQty = @RDQTY - (@ADQty - @SRDQty )            
            
DECLARE @QtyDiff DECIMAL(25, 9)            
DECLARE @EM NVARCHAR(MAX) = ''Qty : ''+convert(NVARCHAR(50),isnull(@Qty,0))+'' , Final Qty : ''+convert(NVARCHAR(50),isnull(@FinalQty,0))            
--Verify Required Qty If Pass to Update the Qty In Inventory Table            
IF(isnull(@Qty,0) >= isnull(@FinalQty,0) AND isnull(@FreeQty,0) >= isnull(@FinalFreeQty,0) AND isnull(@DamageQty,0) >= isnull(@FinalDmgQty,0) )            
BEGIN            
IF(@RQTY < @Qty)            
BEGIN SET @QtyDiff = @Qty - @RQTY            
SET @RQTY = @RQTY + @QtyDiff            
SET @AQty = @AQty + @QtyDiff            
END            
ELSE IF(@Qty < @RQTY )            
BEGIN            
SET @QtyDiff = @RQTY - @Qty            
SET @RQTY = @RQTY - @QtyDiff            
set @AQty = @AQty - @QtyDiff            
END            
IF(@RFQTY < @FreeQty)            
BEGIN            
SET @QtyDiff = @FreeQty - @RFQTY            
SET @RFQTY = @RFQTY + @QtyDiff            
SET @AFQty = @AFQty + @QtyDiff            
END            
ELSE IF(@RFQTY >@FreeQty)            
BEGIN            
SET @QtyDiff = @RFQTY - @FreeQty            
SET @RFQTY = @RFQTY - @QtyDiff            
SET @AFQty = @AFQty - @QtyDiff END            
IF(@RDQTY < @DamageQty)            
BEGIN            
Set @QtyDiff = @DamageQty - @RDQTY            
Set @RDQTY = @RDQTY + @QtyDiff            
set @ADQty = @ADQty + @QtyDiff            
END            
ELSE IF(@RDQTY > @DamageQty )            
BEGIN         
SET @QtyDiff = @RDQTY - @DamageQty            
SET @RDQTY = @RDQTY - @QtyDiff            
set @ADQty = @ADQty - @QtyDiff            
END            
IF(@IsChrgProd = 0)            
BEGIN            
EXEC uspInsertInventory ''UPDATE'',1,@BillDate,@DocValue,@ProdId,@UomGrpID,@UOMID,@RQTY,@RFQTY,@RDQTY,@AQty,@AFQty,@ADQty,0,0,0,            
@Batchno ,@PKDDate,@ExpiryDate,@PurchasePrice,@SalePrice,@ECP,@SPLPrice,@MRP,@ReturnPrice,@TaxId ,@TaxTypeId ,@TaxPercentage,            
@InvId,@InvScopeId OUT ,0,@InclusiveYesNo,@UID,@BranchID,@SelectedUomCF            
END            
END            
ELSE            
BEGIN            
declare @MG NVARCHAR(MAX) = ''Qty Miss Matched.%s''            
RAISERROR(@MG,16,1,@EM);            
END            
END            
--SELECT * FROM tblTransPurchaseDetail ORDER BY 1 DESC          
--SELECT * FROM tblproductinventory ORDER BY 1 DESC            
INSERT INTO tblTransPurchaseDetail(HID,InventoryId,ProdID,UOMID,BatchNo,PKD,Expiry,UomQty,UomFreeQty,UomDamageQty,            
UomPurchasePrice, UomSalePrice,UomECP,UomMRP,UomSPLPrice,UomReturnPrice,PurchasePrice,SalePrice,ECP,MRP,SPLPrice,ReturnPrice,            
TaxID,TaxTypeId,[Tax%],GoodsAmt,[ProdDisc%],[TradeDisc%],[AddnlDisc%], GrossAmt,TaxAmt,NetAmt,Serial,UOMCF,ReasonId,LocationID,DiffAmt,            
AdjQty,AdjFreeQty,AdjDmgQty,ProdDiscAmt,TradeDiscAmt,AddnlDiscAmt)            
VALUES            
(@ScopeID,@InvScopeId,@ProdID ,@UOMID,@BatchNo,@PKDDate,@ExpiryDate,@UomQty , @UomFreeQty , @UomDamageQty,            
@PurchasePrice,@SalePrice,@ECP, @MRP,@SPLPrice,@ReturnPrice,ISNULL((@PurchasePrice / @SelectedUomCF ),0),ISNULL((@SalePrice / @SelectedUomCF) ,0),            
ISNULL((@ECP / @SelectedUomCF) ,0),ISNULL(@MRP ,0),ISNULL((@SPLPrice / @SelectedUomCF) ,0),ISNULL(@ReturnPrice,0),            
@TaxID ,@TaxTypeId,@TaxPercentage,@GoodsAmt , @ProdDiscPercent,@TradeDiscPercent,@AddnlDiscPercent,@BGrossAmt,@BTaxAmt,@BNetAmt,            
@BillDetailSerial,@SelectedUomCF,@ReasonID,@LocationID,@DiffAmt,ISNULL((@UomQty * @SelectedUomCF) ,0),ISNULL((@UomFreeQty * @SelectedUomCF) ,0),            
ISNULL((@UomDamageQty * @SelectedUomCF) ,0),@ProdDiscAmount ,@TradeDiscAmount ,@AddnlDiscAmount)            
            
SET @BillDetailSerial = @BillDetailSerial + 1            
--Direct Bill Only Update Inventory and Product Table            
IF(@IFBIll=1)            
BEGIN            
--UPDATE PRICE In Inventory            
DECLARE @MP DECIMAL (25,6)            
--SET @MP =ISNULL(@MRP ,0)            
--IF ISNULL(@InclusiveYesNo,0)=1            
--BEGIN            
SET @MP = (@MRP / ((@TaxPercentage /100 )+ 1))            
--SET @MP = @NPrice            
--END            
IF(@IsChrgProd = 0 AND ISNULL(@ImportStatus,0) = 0)            
BEGIN            
--Product Price Updation            
EXEC uspUpdatePriceInProductMaster @ProdID ,@PurchasePrice,@SalePrice,@ECP,@SPLPrice,@MRP,@ReturnPrice,@SelectedUomCF ,1,@HSNCode,@LocationID--@PriceOnUomCF            
if(@UpdateVendor = 1)            
begin            
update tblmasterproduct set VendorID = @vendorid where id = @ProdID            
end            
END            
END            
FETCH NEXT FROM cursor_Temp INTO @ProdID , @UOMID ,@UomGrpID ,@BatchNo ,@PKD ,@Expiry ,@UomQty ,@UomFreeQty,@UomDamageQty ,            
@PurchasePrice ,@SalePrice ,@ECP ,@MRP ,@SPLPrice ,@TaxID ,@BTaxTypeId ,@TaxPercentage ,@GoodsAmt ,@ProdDiscPercent ,            
@TradeDiscPercent ,@AddnlDiscPercent ,@BGrossAmt ,@BTaxAmt ,@BNetAmt ,@InvId ,@InclusiveYesNo ,@ReturnPrice,@SelectedUomCF,@HSNCode,            
@ReasonID,@LocationID,@DiffAmt,@ProdDiscAmount ,@TradeDiscAmount ,@AddnlDiscAmount            
END            
CLOSE cursor_Temp            
DEALLOCATE cursor_Temp            
BEGIN --Posting Tamil            
DECLARE @JVID INT            
SELECT @JVID=ISNULL(MAX(JVID),0)+1 FROM tblFAJournal WITH (READCOMMITTEDLOCK)            
IF ISNULL(@TotalGrossAmt,0)>0            
BEGIN --Gross Amt Posting            
-- Puchase Account            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,76,0,(ISNULL(@TotalGrossAmt,0)), 0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID) --(ISNULL(@TotalGrossAmt,0)+ISNULL(@WrightOffAmt,0))            
END            
IF ISNULL(@TotalTaxAmt,0)>0            
BEGIN --Tax Amt Posting            
-- VAT Receivable (Input Tax Credit)            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,113,0,@TotalTaxAmt, 0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,@UID ,GETDATE (),@ScopeID,            
@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
IF ISNULL(@TCSAmt,0)>0            
BEGIN --TCS Amt Posting            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,57,0,@TCSAmt, 0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,@UID ,GETDATE (),@ScopeID,            
@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
IF ISNULL(@TDSAmt,0)>0            
BEGIN --TDS Amt Posting            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,107,@TDSAmt,0, 0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,@UID ,GETDATE (),@ScopeID,            
@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
IF ISNULL(@Frieght,0)>0 BEGIN--Fright            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId ,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,39,0,ISNULL(@Frieght,0),0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
IF ISNULL(@OtherChargeAmt,0)>0            
BEGIN--Other Charges            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue ,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,61,0,ISNULL((@OtherChargeAmt),0),0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
IF ISNULL(@OtherChargeAmt,0)<0            
BEGIN            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue ,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,61,ISNULL(-(@OtherChargeAmt),0),0,0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
IF ISNULL(@WrightOffAmt,0)>0 -- Writeoff Amount Gives Positive (+)            
BEGIN            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue ,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,117,0,ISNULL((@WrightOffAmt),0),0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
IF ISNULL(@WrightOffAmt,0)<0 -- Writeoff Amount Gives Negative (-)            
BEGIN            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue ,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,117,ISNULL(-(@WrightOffAmt),0),0,0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
IF ISNULL(@TotalNetAmt,0)>0            
BEGIN --Net Amt Posting            
--Remove Round Of From Net Amount            
DECLARE @RAmt DECIMAL (25,6)            
SET @RAmt=-1*ISNULL(@RoundOffAmt,0)            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,@Accid,ISNULL(@TotalNetAmt,0)+@RAmt,0, 0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
SELECT @JVID=ISNULL(MAX(JVID),0)+1 FROM tblFAJournal WITH (READCOMMITTEDLOCK)       
IF ISNULL(@RoundOffAmt,0)<>0            
BEGIn --Round Off Amt Posting            
IF ISNULL(@RoundOffAmt,0)>0            
BEGIN            
--Round Value Positive(+)            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue ,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate,@GRNRefNo ,82,0,@RoundOffAmt,0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
--Opposite Vendor Account Id            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue ,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,@Accid,@RoundOffAmt,0,0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
IF ISNULL(@RoundOffAmt,0)<0            
BEGIN            
--Opposite Vendor Account Id            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,@Accid,0,ABS(@RoundOffAmt),0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
--Round Value Negative(-)            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate ,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,82,ABS(@RoundOffAmt),0,0,'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,            
@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
            
END            
END            
IF(ISNULL(@TotalAddnlDiscAmt,0) +ISNULL(@TotalProdDiscAmt,0) +ISNULL(@TotalTradeDiscAmt,0))>0            
BEGIN            
SELECT @JVID=ISNULL(MAX(JVID),0)+1 FROM tblFAJournal WITH (READCOMMITTEDLOCK)            
--All Discount Sum Of posting            
--Purchase Account            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate,TransId ,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,76,0,(ISNULL(@TotalAddnlDiscAmt,0) +ISNULL(@TotalProdDiscAmt,0) +ISNULL(@TotalTradeDiscAmt,0)),0,            
'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
--Discout On Purchase            
INSERT INTO tblFAJournal([DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],            
CBy ,CDate ,TransId,UDFId,UDFDocId,UDFDocPrefix,UDFDocValue,JVID,Adjusment,BranchID)            
VALUES (@DocId, 1, @DocValue,@BillDate ,@GRNRefNo ,31,(ISNULL(@TotalAddnlDiscAmt,0) +ISNULL(@TotalProdDiscAmt,0) +ISNULL(@TotalTradeDiscAmt,0)),0, 0,            
'''',''Purchase Bill'',CASE WHEN ISNULL(@ImportStatus,0) = 0 THEN @Status ELSE @ImportStatus END,@UID ,GETDATE (),@ScopeID,@UDFId,@UDFDocId,@UDFDocPrefix,@UDFDocValue,@JVID,0,@BranchID)            
END            
            
END            
IF @PaymentModeId != 7            
BEGIN            
DECLARE @Header tvpCollHeader,@Detail tvpCollDetail,@Mop tvpCollMop,@ReceivedAmt DECIMAL (25,6) ,@BankAccNo NVARCHAR(20),            
@BankAccId INT ,@CDNumber NVARCHAR(255) ,@CDId INT ,@CDDate NVARCHAR(25),@PayAt NVARCHAR(20),@IFSC NVARCHAR(20),@Bank NVARCHAR(255),            
@Branch NVARCHAR(255),@NEFTId NVARCHAR(255),@VMId NVARCHAR(20),@VMTransID NVARCHAR(20),@PaymentCount INT, @PaymentIndex INT,          
@InvCurrentAmt DECIMAL (25,6),@VisaPern DECIMAL (25,6), @VisaAmt DECIMAL (25,6)            
SET @InvCurrentAmt=@TotalNetAmt - ISNULL(@TDSAmt,0);            
--Get Vendor Acc Id            
SELECT @Accid=FAID FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE id =@VendorId            
--Collection            
SET @PaymentCount=(SELECT COUNT(*) FROM @tvpTranBillMop)            
SET @PaymentIndex=1            
WHILE @PaymentCount >0            
BEGIN            
SELECT @PaymentModeId=[PayModeId],@CDId=[ChequeId],@CDNumber=[Cheque_OR_DDNumber_OR_NEFTId],@BankAccNo=[BankAccNo],@BankAccID=[BankAccID],            
@CDDate=[PMDate],@PayAt=[PayAt],@IFSC=[IfscCode],@Bank=[Bank] ,@Branch=[Branch] ,@ReceivedAmt=[Amt],@Balance=[RecdAmt],@VisaPern = [VisaPern], @VisaAmt = [VisaAmt]            
FROM @tvpTranBillMop WHERE [SerialNo]=@PaymentIndex            
--Transaction Bill payment detail            
INSERT INTO tblTran_Sale_Bill_PaymentDetail(TransId,InvId,[PayModeId],[ChequeNo],[Cheque_OR_DDNumber_OR_NEFTId],Acc_OR_PaytermId,[PMDate],[PayAt],[IfscCode],[Bank] ,            
[Branch] ,[Amt] ,[SerialNo],RecdAmt,Visaper,VisaAmt )VALUES(1,@ScopeID,@PaymentModeId,@CDId,@CDNumber,@BankAccID,@CDDate,@PayAt,@IFSC,@Bank,@Branch,@ReceivedAmt ,@PaymentIndex,@Balance,@VisaPern,@VisaAmt)            
            
IF @PaymentModeId !=7            
BEGIN            
--Col Header            
INSERT INTO @Header VALUES(CONVERT(NVARCHAR(50),@BillDate,103),0 ,@GRNRefNo ,@Accid,@ReceivedAmt ,0,@PaymentModeId,1 ,0,@UID,1,@PaymentIndex,@VisaPern,@VisaAmt) --Mop Detail            
IF @PaymentModeId !=3            
BEGIN            
INSERT INTO @Mop VALUES(@Accid,@PaymentModeId,@CDId ,CONVERT(NVARCHAR(50),@CDDate,103),@BankAccId ,@CDNumber,@ReceivedAmt,@IFSC ,@Bank ,@Branch ,@PayAt,@BankAccNo,            
(CASE WHEN @PaymentModeId =3 THEN NULL ELSE @CDNumber END), @CDId,@PaymentIndex,@Balance)            
END            
ELSE            
BEGIN            
INSERT INTO @Mop VALUES(@Accid,@PaymentModeId,@CDNumber ,CONVERT(NVARCHAR(50),@CDDate,103),@BankAccId ,'''',@ReceivedAmt,@IFSC ,@Bank ,@Branch ,@PayAt,@BankAccNo,            
(CASE WHEN @PaymentModeId =3 THEN NULL ELSE @CDNumber END), @CDId,@PaymentIndex,@Balance)            
END            
-- Col Detail            
INSERT INTO @Detail VALUES(@Accid,1,@DocValue, @ScopeID,@BillDate,ISNULL(@InvCurrentAmt,0),ISNULL(@ReceivedAmt,0),0,0,0,0,0,ISNULL(@ReceivedAmt,0),1,@PaymentIndex,0)            
--Amount Calculate            
SET @InvCurrentAmt=@InvCurrentAmt-@ReceivedAmt;            
END            
SET @PaymentCount=@PaymentCount-1;            
SET @PaymentIndex=@PaymentIndex+1;            
END            
            
-- Get UDN for Payment            
DECLARE @UDFCount INT,@UDNSingle INT            
SET @UDFCount = (            
SELECT COUNT(DISTINCT UDNId) FROM tblMasterUserDefineNoDetail WITH (READCOMMITTEDLOCK)            
WHERE UDNId IN (SELECT UDNId FROM tblMastERUserDefineNoHeader WITH (UPDLOCK) WHERE TransID=18) AND UserId=@UID            
)            
IF ISNULL(@UDFCount,0)=1            
BEGIN            
SET @UDNSingle = (SELECT DISTINCT UDNId FROM tblMasterUserDefineNoDetail WITH (READCOMMITTEDLOCK) WHERE UDNId IN (SELECT UDNId FROM tblMasterUserDefineNoHeader WITH (UPDLOCK) WHERE TransId=18)AND UserId=@UID )            
END            
            
--Payment Implicit Posting            
EXEC uspManageFullColl 18,@UDNSingle,@Header,@Detail,@Mop,1,0,0,@nAllowNegativeBal,@tvpSaveDenomination,NULL,NULL,NULL,0,@Remarks,@Narration,@BranchID            
            
            
ENd            
            
IF(ISNULL(@DraftID,0) > 0 and isnull(@FilterType,0) = 2)            
BEGIN            
UPDATE tblPurchaseDraftHeader SET Status = 8,MBy = @UID,MDate = GETDATE() WHERE ID = @DraftID            
END            
IF(ISNULL(@TempPOID,0) > 0 and isnull(@FilterType,0) = 3)            
BEGIN            
UPDATE tblPurchaseOrderHeader SET GRNId=@ScopeID,Status=5,Mby=@UID,Mdate=GETDATE() WHERE ID=@TempPOID            
END            
SELECT @ScopeID AS IdentId            
            
END TRY            
BEGIN CATCH            
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE()            
END CATCH',
N'[export] cursor-local-fast_forward=2;number-series-updlock=6;readcommittedlock=22';
GO
/****** uspManageTransVariant ******/
EXEC #Apply07 N'dbo.uspManageTransVariant', 0x6F6CC79C974EBA6DE11656516BE23779F4375A4AE1FC4304E8F5B3D978921C28, NULL, NULL, 0x97549A777E66D98FC6423D36052A33F6827B566B027D63AFAB0C1C3DCDB4B282, 0xBDA57B405AAF474D1A354076F19FC0C03E5C0A5AD40B54A041B8617F58003B69, NULL,
N'ALTER proc [dbo].[uspManageTransVariant]    
@Mode INT,@PartyType nvarchar(50) = null    
AS    
SET NOCOUNT ON;
BEGIN    
IF(@Mode = 1)    
BEGIN    
SELECT TVT.ID,TVT.Name,TVT.MainForm,COALESCE(YDS.Prefix,DS.DocPrefix) DocPrefix,TVT.TransID FROM tblTransVariantType TVT    
JOIN tblDocumentSeries DS ON DS.TransID = TVT.TransID
LEFT JOIN tblYearwiseDocumentSeries YDS ON YDS.TransID = DS.TransID AND CONVERT(DATE,GETDATE()) between FromDate 
and ToDate AND BranchID = 1
where TVT.Active = 1    
END    
IF(@Mode = 2)    
BEGIN    
if(@PartyType = 1)    
begin    
SELECT ID,Code,Name FROM tblMasterCustomer WHERE Active = 1 ORDER BY Name    
END    
ELSE if(@PartyType = 2)    
begin    
SELECT ID,Code,Name FROM tblMasterVendor WHERE Active = 1 ORDER BY Name    
END    
END    
END',
N'[export] nocount';
GO
/****** uspManageUpdateCompanyDetail ******/
EXEC #Apply07 N'dbo.uspManageUpdateCompanyDetail', 0x3B21B0651A93981593B13E3CE50516160537A73F2D2FC18E4F0F649F97B69889, NULL, NULL, 0x0E4061693F76E6BDE93C6ADD248A8C81754EE8133C0CFD62E6C866D4701BD89C, 0x8C1B51F7CB06BFA95D274EF134B6AA5D78AB8C134D947F8BB0248168FF44A4E8, NULL,
N'ALTER proc [dbo].[uspManageUpdateCompanyDetail]      
@Mode INT,@CompanyId int= null,@CompanyCode nvarchar(255)= null,@CompanyName nvarchar(255)= null,@StateID smallint= null,      
@Address nvarchar(MAX)= null,@Country nvarchar(255)= null,@State nvarchar(255)= null,@City nvarchar(255)= null,@Pincode nvarchar(25)= null,      
@Contact_Person nvarchar(255)= null,@MobileNo nvarchar(25)= null,@PhoneNo nvarchar(25)= null,@Website nvarchar(255)= null,      
@Email nvarchar(255)= null,@FSSAI nvarchar(50)= null,@AadharNo nvarchar(25)= null,@PANNo nvarchar(25)= null,@GSTIN nvarchar(50)= null,      
@Dl_20 nvarchar(255)= null,@Dl_21 nvarchar(255)= null ,@CCEmail nvarchar(255)= null,@FSD DATE= null ,@FED DATE= null,
@WebDevices nvarchar(255)= null ,@MobileDevices nvarchar(255)= null
AS      
SET NOCOUNT ON;
BEGIN      
IF(@Mode = 1)      
BEGIN      
select * from tblCompanyRegistration WITH (READCOMMITTEDLOCK)        
END      
ELSE IF(@Mode = 2)      
BEGIN      
select StateID,CONVERT(NVARCHAR,TINNO)+'' - ''+ StateName StateName from tblGSTStateNameandCode WITH (READCOMMITTEDLOCK) WHERE Active = 1              
END      
ELSE IF(@Mode = 3)      
BEGIN      
UPDATE tblCompanyRegistration SET CompanyCode =  @CompanyCode,CompanyName =  @CompanyName,StateID =  @StateID,Address =  @Address,Country =  @Country,      
State =  @State,City =  @City,Pincode =  @Pincode,Contact_Person =  @Contact_Person,MobileNo =  @MobileNo,PhoneNo =  @PhoneNo,Website =  @Website,      
Email =  @Email,FSSAI =  @FSSAI,AadharNo =  @AadharNo,PANNo =  @PANNo,GSTIN =  @GSTIN,Dl_20 = @Dl_20,Dl_21 = @Dl_21,    
CCEmail = @CCEmail,F_SD=@FSD,F_ED=@FED,WebDevices=@WebDevices,MobileDevices=@MobileDevices  WHERE CompanyId =  @CompanyId      
END      
END',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspManageUpdateproductlocation ******/
EXEC #Apply07 N'dbo.uspManageUpdateproductlocation', 0x7FCEF04F90DC7F1BAAA677A6D8C7018D23A43BCE85B140F188F06399B9825CCE, NULL, NULL, 0xA01E94C1F0E52EAD9CABC735AFAC45A02AC01504AE2089403C6F33F70396794D, 0xDDAF5CD5CB8DF40811B2FA46CDA840FAE8F1B88C372CCA39FB899D085F5A695F, NULL,
N'--[uspManageUpdateproductlocation] 2,1    
ALTER proc [dbo].[uspManageUpdateproductlocation]          
@Mode INT,@BranchID int = 0,@tvpProdSerialInfo [tvpProdSerialInfo] readonly    
AS          
SET NOCOUNT ON;
BEGIN          
IF (@Mode = 1)      
BEGIN       
SELECT 1 AS FType,ID,Name FROM tblMasterLocation WITH (READCOMMITTEDLOCK) WHERE Active = 1      
UNION ALL      
SELECT 2 AS FType,ID,Name FROM tblMasterBranchOffice WITH (READCOMMITTEDLOCK) WHERE Active = 1      
ORDER BY FType, Name      
END         
ELSE IF(@Mode = 2)          
BEGIN          
SELECT MP.ID ProductID,ISNULL(PLM.LocationID,0) LocationID,ML.Name LocationName  INTO #MAPPROD    
FROM tblProductLocationMapping PLM WITH (READCOMMITTEDLOCK)       
join tblMasterProduct MP WITH (READCOMMITTEDLOCK) ON PLM.ProductID = MP.ID    
JOIN tblMasterCategory MCT WITH (READCOMMITTEDLOCK) ON MCT.ID = MP.CategoryID          
LEFT JOIN tblMasterLocation ML WITH (READCOMMITTEDLOCK) ON ML.ID = PLM.LocationID        
WHERE PLM.BranchID = @BranchID        
    
SELECT MP.ID ProductID,MP.Code,MP.Name,MCT.Name CategoryName INTO #MAINPROD    
FROM tblMasterProduct MP WITH (READCOMMITTEDLOCK)          
JOIN tblMasterCategory MCT WITH (READCOMMITTEDLOCK) ON MCT.ID = MP.CategoryID          
ORDER BY Name          
    
SELECT MAIN.ProductID ID,MAIN.Code,MAIN.Name,MAIN.CategoryName,ISNULL(MAP.LocationID,0) LocationID,map.LocationName,ISNULL(MAP.LocationID,0) OrgLocationID FROM #MAINPROD MAIN    
LEFT JOIN #MAPPROD MAP ON MAP.ProductID = MAIN.ProductID    
    
DROP TABLE  #MAINPROD,#MAPPROD    
END          
ELSE IF(@Mode = 3)          
BEGIN          
--UPDATE tblMasterProduct set LocationID = @LocationID WHERE ID = @ProdID       
DECLARE @PRODID INT,@LOCATIONID INT,@NSERIAL INT = 1,@NTOTCOUNT INT =(SELECT COUNT(*) FROM @tvpProdSerialInfo)    
WHILE(@NTOTCOUNT >= @NSERIAL)    
BEGIN    
SELECT @PRODID = ProdId,@LOCATIONID = Serial FROM @tvpProdSerialInfo WHERE RowIndex = @NSERIAL    
if((select count(*) from  tblProductLocationMapping WITH (READCOMMITTEDLOCK) where ProductID = @PRODID and BranchID = @BranchID) > 0)    
begin    
update tblProductLocationMapping set LocationID = @LocationID where ProductID = @PRODID and BranchID = @BranchID    
end    
else    
begin    
insert into tblProductLocationMapping values (@PRODID,@BranchID,@LocationID)      
end    
SET @NSERIAL += 1;    
END    
    
END          
END',
N'[export] nocount;readcommittedlock=9';
GO
/****** uspManageUsers ******/
EXEC #Apply07 N'dbo.uspManageUsers', 0x2A3A3D605BFFC25BF9D2A15AF50A0A7CD0685005ACC4D8AED4B9DCC99FFB8984, 0x114199AD4683069BF1BA0B4234FC8CD5F1D9BA20A6B0161D4EED595868E2BB0B, NULL, 0x24E14C10BAB2D2E8990DB0D8BBF3356F8A4A200D1C66105D3692B4385792A629, 0xB7E84A06FBE1C628E502899E9BCEBDABB191498409862380C861932E6B61B935, NULL,
N'ALTER PROCEDURE [dbo].[uspManageUsers]      
@Mode INT,@ID smallint = null,@UserName nvarchar(MAX) = null,@Password nvarchar(MAX) = null,@Mobilenumber nvarchar(MAX) = null,@EMailID nvarchar(MAX) = null,      
@RoleID smallint = null,@PwdResetCount tinyint = null,@PwdResetTime datetime = null,@LPin int = null,@Active bit = null,@UserID smallint = null      
as      
SET NOCOUNT ON;
begin      
BEGIN TRY      
IF(@Mode = 1)      
BEGIN      
IF((SELECT count(*) FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE UserName = @UserName) > 0)      
BEGIN      
RAISERROR(''User Name already exists'',16,1)      
END      
IF((SELECT count(*) FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE Mobilenumber = @Mobilenumber and isnull(Mobilenumber,'''') != '''') > 0)      
BEGIN      
RAISERROR(''Mobile No already exists'',16,1)      
END      
IF((SELECT count(*) FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE EMailID = @EMailID and isnull(EMailID,'''') != '''') > 0)      
BEGIN      
RAISERROR(''EMail ID already exists'',16,1)      
END      
SET @UserName = (select dbo.ProperCase(@UserName))      
insert into tblUsers(UserName,Password,Mobilenumber,EMailID,RoleID,Active,CBy,CDate)      
Values (@UserName,@Password,@Mobilenumber,lower(@EMailID),ISNULL(@RoleID,0),@Active,@UserID, GETDATE())      
SELECT SCOPE_IDENTITY()      
END      
IF(@Mode = 2)      
BEGIN      
IF((SELECT count(*) FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE UserName = @UserName and ID != @ID) > 0)      
BEGIN      
RAISERROR(''User Name already exists'',16,1)      
END      
IF((SELECT count(*) FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE Mobilenumber = @Mobilenumber and ID != @ID and isnull(@Mobilenumber,'''') != '''') > 0)      
BEGIN      
RAISERROR(''Mobile No already exists'',16,1)      
END      
IF((SELECT count(*) FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE EMailID = @EMailID and ID != @ID and isnull(EMailID,'''') != '''') > 0)      
BEGIN      
RAISERROR(''EMail ID already exists'',16,1)      
END      
INSERT INTO tblMasterHistory (FormID,ID,Name,Column1,Column2,Column3,Column4,Column5,Column6,Column7,Active,CBy,CDate,MBy,MDate,HisCBy,HisCDate)      
(select 29,ID, UserName, NULL, Mobilenumber, EMailID, RoleID, PwdResetCount, PwdResetTime, LPin, Active, CBy, CDate, MBy, MDate,      
@UserID, GETDATE() from tblUsers WITH (READCOMMITTEDLOCK) where ID = @ID)      
SET @UserName = (select dbo.ProperCase(@UserName))      
UPDATE tblUsers SET UserName = @UserName,Password = COALESCE(NULLIF(@Password, N''''), Password), Mobilenumber = @Mobilenumber,EMailID = lower(@EMailID),      
Active = @Active,MBy = @UserID ,MDate = GETDATE(), RoleID = (CASE WHEN @UserID = @ID THEN RoleID ELSE @RoleID END) WHERE ID = @ID      
  
UPDATE tblMobileLogin SET SessionStatus = 0 WHERE UserID = @ID      
SELECT @ID      
END      
IF(@Mode = 3)      
BEGIN      
SELECT UR.ID,UR.UserName,UR.Password,UR.Mobilenumber,UR.EMailID,UR.RoleID,MR.Name RoleName,UR.PwdResetCount,UR.PwdResetTime,UR.LPin,      
UR.CBy,UR.Active,CASE WHEN ISNULL(UR.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END AUserName,      
CASE WHEN ISNULL(UR.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),UR.CDate) ELSE CONVERT(NVARCHAR(100),UR.MDate) END LastActionTime,      
UR.ImgData      
from tblUsers UR WITH (READCOMMITTEDLOCK)      
LEFT JOIN tblMasterRole MR WITH (READCOMMITTEDLOCK) ON MR.ID = UR.RoleID      
LEFT JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = UR.CBy      
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = UR.MBy      
where UR.ID > 1 order by UR.UserName      
END      
IF(@Mode = 4)      
BEGIN      
SELECT UR.ID,UR.UserName,UR.Password,UR.Mobilenumber,UR.EMailID,UR.RoleID,MR.Name RoleName,UR.PwdResetCount,UR.PwdResetTime,      
UR.LPin,UR.CBy,UR.Active,CASE WHEN ISNULL(UR.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END AUserName,      
CASE WHEN ISNULL(UR.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),UR.CDate) ELSE CONVERT(NVARCHAR(100),UR.MDate) END LastActionTime,      
UR.ImgData      
from tblUsers UR WITH (READCOMMITTEDLOCK)      
LEFT JOIN tblMasterRole MR WITH (READCOMMITTEDLOCK) ON MR.ID = UR.RoleID      
left JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = UR.CBy      
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = UR.MBy      
where UR.ID = @ID --and UR.ID > 1      
END      
IF(@Mode = 5)      
BEGIN      
update tblUsers set Active = 1 where ID = @ID    
select UserName from tblUsers WITH (READCOMMITTEDLOCK) where ID = @ID    
END      
IF(@Mode = 6)      
BEGIN      
SELECT *,(select UpdateClsDate from tblCompanyRegistration WITH (READCOMMITTEDLOCK) where CompanyId = 1) UpdateClsDate,      
(select ExpiryDate from tblCompanyRegistration WITH (READCOMMITTEDLOCK) where CompanyId = 1) ExpiryDate ,
(select WebDevices from tblCompanyRegistration WITH (READCOMMITTEDLOCK) where CompanyId = 1) WebDevices 
from tblUsers WITH (READCOMMITTEDLOCK) where Active = 1 and UserName = @UserName and Password = @Password      
--update tblUsers set pwdresettime = GETDATE() where UserName = @UserName and Password = @Password      
END      
IF(@Mode = 7)      
BEGIn      
if(isnull(@ID,0) = 1)      
begin      
SELECT * from tblMasterRole WITH (READCOMMITTEDLOCK) order by Name      
end      
else if(isnull(@ID,0) >= 2)      
begin      
SELECT * from tblMasterRole WITH (READCOMMITTEDLOCK) WHERE ID > 2 order by Name      
end      
END      
IF(@Mode = 8)      
BEGIN      
SELECT * from tblUsers WITH (READCOMMITTEDLOCK) where UserName = @UserName and EMailID = @Password      
END      
IF(@Mode = 9)      
BEGIN      
update tblUsers set Password = @Password where UserName = @UserName and EMailID = @EMailID      
END      
END TRY      
BEGIN CATCH      
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC]      
END CATCH      
END',
N'[05] nocount;readcommittedlock=23';
GO
/****** uspManageVanloadingSlip ******/
EXEC #Apply07 N'dbo.uspManageVanloadingSlip', 0xCFB8370E0706F4EB705574283C9066979A43DC3C15756B828363A7E2DA2AE978, NULL, NULL, 0x1F26C88D09E2BCCDA34E02BC2E67EF2F960A3F83598324C85B41632373378BD5, 0x60D98927C290F5C4A5B5EFB331D88A53241639D71D5BCCC95B93E7854DC1BBDB, NULL,
N'ALTER PROC [dbo].[uspManageVanloadingSlip]        
@TransMode int,@TransID INT,@ID int,@DocDate DATE,@BranchID iNT,@SalesmanID int,@RefNo nvarchar(100),@PriceType int,        
@GrossAmt DECIMAL (15,4)=NULL,@TaxAmt DECIMAL (15,4)=NULL,@RoundoffAmt DECIMAL (15,4)=NULL,@NetAmt DECIMAL (15,4)=NULL,        
@CurrentStatus int,@Remarks NVARCHAR(max)=NULL,@Narration NVARCHAR(max)=NULL,@UserID int,        
@tvpTranSaleDetail [tvpTranSaleDetail] READONLY,@VehicleNo SMALLINT = 0,@Distance NVARCHAR(255)=''0'',@TransportType NVARCHAR(255)=NULL,@TransportMode NVARCHAR(255)=NULL,                          
@TransportID NVARCHAR(255)=NULL,@TransportName NVARCHAR(255)=NULL    
AS        
BEGIN TRY        
BEGIN TRAN        
SET DATEFORMAT dmy;        
SET NOCOUNT ON;        
DECLARE @ActiveCheck INT,@DocValue INT,@DocID NVARCHAR(255),@PreviousTranDate DATE,@ScopeID INT ,@nCurrStatus INT        
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)        
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)        
declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))        
DECLARE @DocSeriesIdent int        
        
IF(@TransMode = 1)        
BEGIN        
PRINT ''Create''        
insert into @tblDocdetails        
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate) and BranchID = @BranchID        
and TransID = @TransID        
IF((select count(*) from @tblDocdetails) = 0)        
BEGIN        
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)        
END        
IF((SELECT COUNT(DocValue) FROM tblVanLoadingSlipHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and        
DocDate BETWEEN @F_SD AND @F_ED and TransID = 24) != 0)-- and Status in (3,4,5,6)        
BEGIN        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)        
END        
SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails        
UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = @TransID and ID = @DocSeriesIdent        
  
INSERT INTO tblVanLoadingSlipHeader(DocDate,TransID,DocID,DocValue,BranchID,SalesmanID,RefNo,GrossAmt,TaxAmt,        
RoundoffAmt,NetAmt,Status,CBy,CDate,Remarks,Narration,VehicleNo,Distance,TransMode,VehicleType,TransportID,    
TransportName,PriceType) VALUES        
(@DocDate,@TransID,@DocID,@DocValue,@BranchID,@SalesmanID,@RefNo,@GrossAmt,@TaxAmt,@RoundoffAmt,@NetAmt,        
(CASE WHEN @TransMode = 1 THEN 1 ELSE 3 END),@UserID,GETDATE(),        
@Remarks,@Narration,@VehicleNo,@Distance,@TransportType,@TransportMode,@TransportID,@TransportName,@PriceType)        
SET @ScopeID =(SELECT SCOPE_IDENTITY());        
  
EXEC dbo.uspQtyReduceFromVanloading ''DIRECT_SALE'',@BranchId, @PriceType,@ScopeID,0,@DocDate ,        
@tvpTranSaleDetail        
  
EXEC uspCreateBackTran 1,@BranchID,@ScopeID,0,@TransID,@DocValue ,@DocDate,NULL,@UserID        
END        
ELSE IF(@TransMode = 2)        
BEGIN        
PRINT ''Modify''   
SET @ScopeID = @ID  
IF((SELECT COUNT(DocValue) FROM tblVanLoadingSlipHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and        
DocDate NOT BETWEEN @F_SD AND @F_ED and TransID = 24) != 0)-- and Status in (3,4,5,6)        
BEGIN        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)        
END        
SELECT @DocValue= SH.DocValue,@DocId=DocId,@PreviousTranDate=DocDate,@nCurrStatus =Status FROM tblVanLoadingSlipHeader SH WITH (READCOMMITTEDLOCK)        
WHERE SH.TransID =@TransID AND SH.ID =@ID        
  IF((@nCurrStatus != @CurrentStatus) OR @nCurrStatus IN (2,4))  
 BEGIN                                              
  RAISERROR(''Document Status Already Changed'',16,1)                                             
 END  
--update tblVanLoadingSlipHeader set Status = 3,MBy = @UserID,MDate = GETDATE() WHERE ID = @ID  
  
if(@ID > 0) -- CHECK HERE        
begiN            
EXEC uspCreateBackTran 2,@BranchID,@ScopeID,@ID,@TransID,@DocValue ,@DocDate,@PreviousTranDate,@UserID        
END    
END  
SELECT @ScopeID AS IdentId        
COMMIT TRAN        
END TRY        
BEGIN CATCH        
ROLLBACK TRAN        
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE();        
END CATCH',
N'[export] number-series-updlock=1;readcommittedlock=5';
GO
/****** uspManageVanloadingSlipCancel ******/
EXEC #Apply07 N'dbo.uspManageVanloadingSlipCancel', 0x8B3C5D0CC356A59ED62E7E920D61C1A5A61B6CB077F6E2D85FD46221D5370D8F, NULL, NULL, 0x64D9296D3C19995C62ACF3D7AC52E825C930A22CB551B1107C4C8BE040598A19, 0xE7EBE6C5DF8E96E1241FF989ACAF31635128A6274229FE213EB024F3D7583E8E, NULL,
N'ALTER proc [dbo].[uspManageVanloadingSlipCancel]    
@VLSID int = 34,@Status int = 1,@UserID int = 2,@Remarks nvarchar(100) = null,@Narration nvarchar(255) = null    
as    
SET NOCOUNT ON;
begin try    
DECLARE @CurrentStatus int,@VLSSaleQty decimal(15,4)    
DECLARE @ProdIDs NVARCHAR(MAX) = ''0'';    
    
select @CurrentStatus = Status from tblVanLoadingSlipHeader WITH (READCOMMITTEDLOCK) WHERE ID = @VLSID    
IF((@Status != @CurrentStatus) or @CurrentStatus in (2,4))    
BEGIN    
RAISERROR(''This document status already changed'',16,1,0);    
END    
    
SELECT @VLSSaleQty = (ISNULL(SUM(VD.VLSMQty),0) + ISNULL(SUM(VD.VLSRetrunQty),0)) FROM tblVanLoadingSlipHeader VH WITH (READCOMMITTEDLOCK)    
JOIN tblVanLoadingSlipDetail VD WITH (READCOMMITTEDLOCK) ON VD.ID = VH.ID    
WHERE VH.ID = @VLSID    
IF(@VLSSaleQty > 0)    
BEGIN    
set @ProdIDs =(SELECT  STRING_AGG(CAST(VD.ProdID AS VARCHAR(20)), '','') AS ProdIDs FROM tblVanLoadingSlipHeader VH WITH (READCOMMITTEDLOCK)    
JOIN tblVanLoadingSlipDetail VD WITH (READCOMMITTEDLOCK) ON VD.ID = VH.ID    
WHERE VH.ID = @VLSID and ISNULL(VD.VLSMQty,0) > 0)    
RAISERROR(''This invoice cannot be cancelled because one or more items in the Loading Slip have already been sold/return.'',16,1,@ProdIDs);    
END    
    
SELECT IDENTITY(INT,1,1) AS Idx,VD.ProdID,VD.InventoryID,VD.UomQty,VD.UomCF INTO #VLSITEMS FROM tblVanLoadingSlipHeader VH WITH (READCOMMITTEDLOCK)    
JOIN tblVanLoadingSlipDetail VD WITH (READCOMMITTEDLOCK) ON VD.ID = VH.ID    
WHERE VH.ID = @VLSID    
    
declare @ProdID int,@InventoryID int,@UomQty decimal(15,4),@UOMCF decimal(15,4),@ActQty decimal(15,4)    
    
DECLARE @ITEMSCOUNT INT = (SELECT COUNT(*) FROM #VLSITEMS),@n INT = 1    
WHILE(@ITEMSCOUNT >= @n)    
begin    
select @ProdID = ProdID,@InventoryID = InventoryID,@UomQty = UomQty,@UOMCF = UomCF from #VLSITEMS where Idx = @n    
set @ActQty = @UomQty / @UOMCF    
UPDATE tblProductInventory SET ActualQty = ActualQty + @ActQty,VLSQty = VLSQty - @ActQty WHERE ProdID = @ProdID AND    
InventoryId = @InventoryID    
set @n = @n + 1    
end    
drop table #VLSITEMS    
    
update tblVanLoadingSlipHeader set Status = 4,ClBy = @UserID,ClDate = GETDATE(),Remarks = @Remarks,Narration = @Narration    
WHERE ID = @VLSID    
SELECT @VLSID    
    
end try    
begin catch    
select ERROR_MESSAGE(),ERROR_LINE(),ERROR_PROCEDURE(),@ProdIDs ErrorIds    
end catch',
N'[export] nocount;readcommittedlock=7';
GO
/****** uspManageVanloadingSlipReturn ******/
EXEC #Apply07 N'dbo.uspManageVanloadingSlipReturn', 0xB88FB42224F79971213A9996CB9817BB23DA6B6AF7D85D7DDAF379461007C7F7, NULL, NULL, 0x479EB35687EF542D53988016F712E0B56815278B4931888CABBE2F7DB37846B1, 0xC0D8B024AEEE839581D801689C70CC468BB9C832715A5D715F3D9837492F8075, NULL,
N'--uspManageVanloadingSlipReturn  
ALTER PROC [dbo].[uspManageVanloadingSlipReturn]  
@BranchID int = 4,@SalesmanID int = 17,@SpotSalePriceMode int = 2 ,@UserID int = 2,  
@tvpVLSItemdetails dbo.tvpVLSItemdetails READONLY  
AS  
SET NOCOUNT ON;
BEGIN TRY  
--INSERT INTO @tvpVLSItemdetails([Index],ProdID,AvailableQty,UOMPrice,MRP)  
--VALUES (1,622,5.0000,12.0000,20.0000)--,(2,318,15.0000,49.1600,65.0000);  
-- Verify  
--SELECT * FROM @tvpVLSItemdetails;  
----  
declare @tvpCount INT, @tvpIndex INT,@TempSerial int  
DECLARE @InsertIdent INT SET @InsertIdent=1;  
DECLARE @InvAdjId INT,@InvAdjQty DECIMAL(25, 4),@InvAdjVLSID INT  
SET @tvpCount =(SELECT COUNT(*) FROM @tvpVLSItemdetails)  
SET @tvpIndex =1  
SET @TempSerial=1  
DECLARE @IdentID INT,@ProdID INT,@AvailableQty DECIMAL(15,4),@AdjustQty DECIMAL(15,4),@UOMPrice DECIMAL(15,4),  
@MRP DECIMAL(15,4),@SaleUomCRate DECIMAL(15,4) = 1,@TaxPercentage DECIMAL(15,4),@BaseUomPrice decimal(15,4);  
declare @TaxID smallint,@UOMID smallint  
--Loop through Table Value Parameter(TVP)  
WHILE @tvpCount >0  
BEGIN  
CREATE TABLE #InventoryId (Ident INT IDENTITY ,TempInvId INT,TempInvQty DECIMAL (15,4),TempVLAID int)  
CREATE TABLE #DATA1(ID INT,InventoryID INT,ProdID INT,UomQty DECIMAL (15,4),VLSMQty DECIMAL (15,4),UomPrice DECIMAL (15,4),  
MRP DECIMAL (15,4))  
  
select @ProdID = ProdID,@AvailableQty = AvailableQty,@UOMPrice = UOMPrice,@MRP = MRP from @tvpVLSItemdetails  
where [Index] = @tvpIndex  
  
IF(ISNULL(@SpotSalePriceMode,1) = 1)--VLS PRICE BASE QTY REDUCE(ECP/other price & MRP)  
BEGIN  
INSERT INTO #DATA1  
select VD.ID,VD.InventoryID,VD.ProdID,SUM(VD.UomQty - (ISNULL(VD.VLSMQtY,0) + ISNULL(VD.VLSRetrunQty,0))) UomQty,  
SUM(VD.VLSMQty) VLSMQty,VD.UomPrice,VD.MRP  
from tblVanLoadingSlipHeader VH WITH (READCOMMITTEDLOCK)  
JOIN tblVanLoadingSlipDetail VD WITH (READCOMMITTEDLOCK) ON VD.ID = VH.ID  
WHERE Status NOT IN (2,4) AND VH.BranchID = @BranchID AND VH.SalesmanID = @SalesmanID AND ProdID = @ProdID  
AND UomPrice = @UOMPrice AND VD.MRP = @MRP  
AND (UomQty - (ISNULL(VLSMQty,0) + ISNULL(VD.VLSRetrunQty,0))) > 0  
GROUP BY VD.ID,VD.InventoryID,VD.ProdID,VD.UomPrice,VD.MRP  
ORDER BY VD.ID  
END  
ELSE IF(ISNULL(@SpotSalePriceMode,1) = 2)--INVENTORY PRICE BASE QTY REDUCE(MRP)  
BEGIN  
INSERT INTO #DATA1  
select VD.ID,VD.InventoryID,VD.ProdID,SUM(VD.UomQty - (ISNULL(VD.VLSMQtY,0) + ISNULL(VD.VLSRetrunQty,0))) UomQty,  
SUM(VD.VLSMQty) VLSMQty,VD.UomPrice,VD.MRP  
from tblVanLoadingSlipHeader VH WITH (READCOMMITTEDLOCK)  
JOIN tblVanLoadingSlipDetail VD WITH (READCOMMITTEDLOCK) ON VD.ID = VH.ID  
WHERE Status NOT IN (2,4) AND VH.BranchID = @BranchID AND VH.SalesmanID = @SalesmanID AND ProdID = @ProdID AND VD.MRP = @MRP  
AND (UomQty - (ISNULL(VLSMQty,0) + ISNULL(VD.VLSRetrunQty,0))) > 0  
GROUP BY VD.ID,VD.InventoryID,VD.ProdID,VD.UomPrice,VD.MRP  
ORDER BY VD.ID
END  
SET @AvailableQty = @SaleUomCRate * @AvailableQty  
  
DECLARE @InventoryId INT,@InventoryQty DECIMAL(25, 4),@VLSID INT  
DECLARE cursor_Inventory CURSOR LOCAL FAST_FORWARD FOR (SELECT InventoryId,UomQty,ID AS Qty FROM #DATA1)  
OPEN cursor_Inventory  
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty,@VLSID  
WHILE @@FETCH_STATUS =0  
BEGIN  
--Loop Exist Qty Adjusted After  
IF(@AvailableQty =0)  
BEGIN  
BREAK;  
END  
--Qty Type SALE  
  
UPDATE tblVanLoadingSlipDetail SET VLSRetrunQty = ISNULL(VLSRetrunQty,0)+ISNULL(@InventoryQty,0),FullyAdjusted = 0  
WHERE InventoryId = @InventoryId AND ID = @VLSID    
  
  
update tblProductInventory set ActualQty = ActualQty + @InventoryQty,VLSQty = isnull(VLSQty,0) - @InventoryQty  
where InventoryId = @InventoryId  
  
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty,@VLSID  
END  
CLOSE cursor_Inventory  
DEALLOCATE cursor_Inventory  
  
DROP TABLE #DATA1,#InventoryId  
SET @tvpIndex =@tvpIndex+1  
SET @tvpCount =@tvpCount-1;  
END  
END TRY  
BEGIN CATCH  
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() PRO  
END CATCH',
N'[export] nocount;cursor-local-fast_forward=1;readcommittedlock=4';
GO
/****** uspManageVehicle ******/
EXEC #Apply07 N'dbo.uspManageVehicle', 0xBB58D1711969186A459330FDEC54BC731D8897EB77A134575163E230CE50C6AC, NULL, NULL, 0x7299D747A62FA1C16A5CC6DE05BEBE54A8C47AED733F2D41664B123C554ED3C5, 0x568E3D643351A3940B05C632C78E09668942F8BB8750E9CCD986F5E5436536EF, NULL,
N'ALTER PROC [dbo].[uspManageVehicle]                
@Mode INT,@ID tinyint = null,@VehicleNo nvarchar(30) = null,@VehicleName nvarchar(255) = null,@DOPurchase date = null,                
@InsuranceDate date = null,@InsuranceExpire date = null,@FCDate date = null,@Active bit = null,@UserID smallint = null                
as                    
SET NOCOUNT ON;
begin                    
BEGIN TRY                     
set @VehicleNo = (select dbo.ProperCase(@VehicleNo))               
set @VehicleName = (select dbo.ProperCase(@VehicleName))               
IF(@Mode = 1)                    
BEGIN                    
IF((SELECT count(*) FROM tblMasterVehicle WITH (READCOMMITTEDLOCK) WHERE VehicleNo = @VehicleNo) > 0)                    
BEGIN                    
RAISERROR(''Vehicle No Already Exists'',16,1)                    
END                    
 set @VehicleNo =(select dbo.ProperCase(@VehicleNo))               
 set @VehicleName = (select dbo.ProperCase(@VehicleName))             
insert into tblMasterVehicle(VehicleNo,VehicleName,DOPurchase,InsuranceDate,InsuranceExpire,FCDate,Active,CBy,CDate)                     
Values (@VehicleNo,@VehicleName,@DOPurchase,@InsuranceDate,@InsuranceExpire,@FCDate,@Active,@UserID, GETDATE())                    
SELECT SCOPE_IDENTITY()                    
END                    
IF(@Mode = 2)                    
BEGIN                    
IF((SELECT count(*) FROM tblMasterVehicle WITH (READCOMMITTEDLOCK) WHERE VehicleNo = @VehicleNo AND ID != @ID) > 0)                    
BEGIN                    
RAISERROR(''Vehicle No Already Exists'',16,1)                    
END          
          
INSERT INTO tblMasterHistory (FormID,ID,Name,Column1,Column2,Column3,Column4,Column5,Active,CBy,CDate,MBy,MDate,HisCBy,HisCDate)          
(select 19,*,@UserID, GETDATE() from tblMasterVehicle WITH (READCOMMITTEDLOCK) where ID = @ID)          
          
 set @VehicleNo =(select dbo.ProperCase(@VehicleNo))               
 set @VehicleName = (select dbo.ProperCase(@VehicleName))             
UPDATE tblMasterVehicle SET VehicleNo = @VehicleNo,VehicleName = @VehicleName,DOPurchase = @DOPurchase,InsuranceDate = @InsuranceDate,                
InsuranceExpire = @InsuranceExpire,FCDate = @FCDate,Active = @Active,MBy = @UserID ,MDate = GETDATE() WHERE ID = @ID                    
SELECT @ID                    
END                    
IF(@Mode = 3)                    
BEGIN                    
SELECT PH.ID,VehicleNo,VehicleName,FORMAT(DOPurchase,''dd-MMM-yyyy'') DOPurchase,FORMAT(InsuranceDate,''dd-MMM-yyyy'') InsuranceDate,FORMAT(InsuranceExpire,''dd-MMM-yyyy'') InsuranceExpire,    
FORMAT(FCDate,''dd-MMM-yyyy'') FCDate,PH.Active,PH.CBy,CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,  
 CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),PH.CDate) ELSE CONVERT(NVARCHAR(100),PH.MDate) END LastActionTime from tblMasterVehicle PH WITH (READCOMMITTEDLOCK)  
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = PH.CBy            
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = PH.MBy   
order by VehicleNo                    
END                    
IF(@Mode = 4)                    
BEGIN                    
--SELECT * from tblMasterVehicle where ID = @VehicleNo                    
SELECT PH.ID,VehicleNo,VehicleName,FORMAT(DOPurchase,''dd-MMM-yyyy'') DOPurchase,FORMAT(InsuranceDate,''dd-MMM-yyyy'') InsuranceDate,FORMAT(InsuranceExpire,''dd-MMM-yyyy'') InsuranceExpire,    
FORMAT(FCDate,''dd-MMM-yyyy'') FCDate,PH.Active,PH.CBy,CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END  UserName,  
 CASE WHEN ISNULL(PH.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),PH.CDate) ELSE CONVERT(NVARCHAR(100),PH.MDate) END LastActionTime from tblMasterVehicle PH WITH (READCOMMITTEDLOCK)  
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = PH.CBy            
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = PH.MBy   
  where PH.ID = @VehicleNo
END                    
END TRY                          
BEGIN CATCH                          
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() [PROC]                          
END CATCH                          
END',
N'[export] nocount;readcommittedlock=9';
GO
/****** uspManageVendorMaster ******/
EXEC #Apply07 N'dbo.uspManageVendorMaster', 0xBBD5E6595E55FE2437A7ECEC8C9BD341AD27E2911A35B800B5BA67280A4EEDB2, NULL, NULL, 0xCD5B1628B02191991740717FFD2CCF17825BBF5B6101DC8DAA056FFFEC97DEB9, 0xF5DC832AA041603C4D05C5C502CA8E4CEFEE3FEDCC26B67175FB2CF1D10B4BE5, NULL,
N'ALTER proc [dbo].[uspManageVendorMaster]
@Mode int,@ID int = null,@Code nvarchar(255) = null,@Name nvarchar(255) = null,@Billadd1 nvarchar(MAX) = null,@Billadd2 nvarchar(MAX) = null,
@Billadd3 nvarchar(MAX) = null,@Shipadd1 nvarchar(MAX) = null,@shipadd2 nvarchar(MAX) = null,@Shipadd3 nvarchar(MAX) = null,@Pincode nvarchar(15) = null,
@ContactPerson nvarchar(255) = null,@Ph1 nvarchar(25) = null,@Ph2 nvarchar(25) = null,@Mob1 nvarchar(25) = null,@Mob2 nvarchar(25) = null,@Email nvarchar(255) = null,
@PANNumber nvarchar(25) = null,@AadharNo nvarchar(25) = null,@DLNo20 nvarchar(25) = null,@DLNo21 nvarchar(25) = null,@FSSAINo nvarchar(30) = null,@StateID tinyint = null,
@GSTIN nvarchar(40) = null,@CreditTermID tinyint = null,@PaymentModeID tinyint = null,@TaxTypeID tinyint = null,
@FAID int = null,@WeekCycle TINYINT = null,@Active smallint = null,@UserID smallint = null,@Rating TINYINT = NULL,@Shinecode nvarchar(50) = null
AS
SET NOCOUNT ON;
BEGIN
BEGIN TRY
DECLARE @ActiveCheck NVARCHAR(255), @SUNDRYDEBTORS INT ,@FATYPE INT,@AccID INT ,@ACCOUNTID INT,@CHECKID INT,@cstdate DATE,@ExistCount INT
SELECT @SUNDRYDEBTORS = FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE AccountGroupName=''Sundry Creditors''

IF(@Mode = 1)
BEGIN
IF((SELECT count(*) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE Code = @Code) > 0)
BEGIN
RAISERROR(''Code'',16,1)
END
IF((SELECT count(*) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE Name = @Name) > 0)
BEGIN
RAISERROR(''Name'',16,1)
END
IF ISNULL(@ph1,'''')!=''''
BEGIN
SELECT @ExistCount=COUNT(Id) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @ph1 OR Ph2 = @ph1 OR Mob1 = @ph1 OR Mob2 = @ph1 )
IF( @ExistCount >0)
BEGIN
RAISERROR (''Phone No 1 already exists'',16,1)
END
END
IF ISNULL(@ph2,'''')!=''''
BEGIN
SELECT @ExistCount=COUNT(Id) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @ph2 OR Ph2 = @ph2 OR Mob1 = @ph2 OR Mob2 = @ph2 )
IF( @ExistCount >0)
BEGIN
RAISERROR (''Phone No 2 already exists'',16,1)
END
END

IF ISNULL(@mob1,'''')!=''''
BEGIN
SELECT @ExistCount=COUNT(Id) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @mob1 OR Ph2 = @mob1 OR Mob1 = @mob1 OR Mob2 = @mob1 )
IF( @ExistCount >0)
BEGIN
RAISERROR (''Mobile No 1 already exists'',16,1)
END
END

IF ISNULL(@mob2,'''')!=''''
BEGIN
SELECT @ExistCount=COUNT(Id) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @mob2 OR Ph2 = @mob2 OR Mob1 = @mob2 OR Mob2 = @mob2 )
IF( @ExistCount >0)
BEGIN
RAISERROR (''Mobile No 2 already exists'',16,1)
END
END
SELECT @ExistCount=COUNT(FAID) FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName=@name
IF(@ExistCount>0)
BEGIN
RAISERROR (''AccountName'',16,1)
END
IF ISNULL(@Shinecode,'''')!=''''
BEGIN
SELECT @ExistCount=COUNT(Id) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE (Shinecode = @Shinecode)
IF( @ExistCount >0)
BEGIN
RAISERROR (''Shine code already exists'',16,1)
END
END
set @Code =(select dbo.ProperCase(@Code))
set @Name = (select dbo.ProperCase(@Name))
set @ContactPerson = (select dbo.ProperCase(@ContactPerson))
set @Billadd1 = (select dbo.ProperCase(@Billadd1))
set @Billadd2 =(select dbo.ProperCase(@Billadd2))
set @Billadd3 = (select dbo.ProperCase(@Billadd3))
set @Shipadd1 =(select dbo.ProperCase(@Shipadd1))
set @Shipadd2 = (select dbo.ProperCase(@Shipadd2))
set @Shipadd3 = (select dbo.ProperCase(@Shipadd3))

INSERT INTO tblFAAccount(AccountName,AccountGroup,OpeningBalance,FATypeID,CBy,CDate,UserAccount,PANNumber,Active)
VALUES(@name,@SUNDRYDEBTORS,0,1,@UserID,GETDATE(),0,@PANNumber,@Active)

SELECT @FAID = FAID FROM tblFAAccount WITH (READCOMMITTEDLOCK) WHERE AccountName = @Name

INSERT INTO tblMasterVendor(Code,Name,Billadd1,Billadd2,Billadd3,Shipadd1,shipadd2,Shipadd3,Pincode,ContactPerson,Ph1,Ph2,Mob1,Mob2,Email,PANNumber,AadharNo,
DLNo20,DLNo21,FSSAINo,StateID,GSTIN,CreditTermID,PaymentModeID,TaxTypeID,FAID,WeekCycle,Active,CBy,CDate,Rating,Shinecode) VALUES
(@Code,@Name,@Billadd1,@Billadd2,@Billadd3,@Shipadd1,@shipadd2,@Shipadd3,@Pincode,@ContactPerson,@Ph1,@Ph2,@Mob1,@Mob2,
lower(@Email),@PANNumber,@AadharNo,@DLNo20,@DLNo21,@FSSAINo,
@StateID,UPPER(@GSTIN),@CreditTermID,@PaymentModeID,@TaxTypeID,@FAID,@WeekCycle,@Active,@UserID,GETDATE(),@Rating,@Shinecode)
SELECT SCOPE_IDENTITY()
END
IF(@Mode = 2)
BEGIN
select @ACCOUNTID = FAID from tblMasterVendor WITH (READCOMMITTEDLOCK) where ID = @ID
IF((SELECT count(*) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE Code = @Code AND ID != @ID) > 0)
BEGIN
RAISERROR(''Code'',16,1)
END
IF((SELECT count(*) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE Name = @Name AND ID != @ID) > 0)
BEGIN
RAISERROR(''Name'',16,1)
END
IF ISNULL(@ph1,'''')!=''''
BEGIN
SELECT @ExistCount=COUNT(Id) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @ph1 OR Ph2 = @ph1 OR Mob1 = @ph1 OR Mob2 = @ph1 ) AND Id != @ID
IF( @ExistCount >0)
BEGIN
RAISERROR (''Phone No 1 already exists'',16,1)
END
END
IF ISNULL(@ph2,'''')!=''''
BEGIN
SELECT @ExistCount=COUNT(Id) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @ph2 OR Ph2 = @ph2 OR Mob1 = @ph2 OR Mob2 = @ph2 ) AND Id != @ID
IF( @ExistCount >0)
BEGIN
RAISERROR (''Phone No 2 already exists'',16,1)
END
END

IF ISNULL(@mob1,'''')!=''''
BEGIN
SELECT @ExistCount=COUNT(Id) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE (Ph1 = @mob1 OR Ph2 = @mob1 OR Mob1 = @mob1 OR Mob2 = @mob1 ) AND Id != @ID
IF( @ExistCount >0)
BEGIN
RAISERROR (''Mobile No 1 already exists'',16,1)
END
END
SELECT @ExistCount=COUNT(FAID) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE Name=@name and FAID != @ACCOUNTID
IF(@ExistCount>0)
BEGIN
RAISERROR (''AccountName'',16,1)
END
IF @Active=0
BEGIN
DECLARE @ReturnValue DECIMAL(25,4)
EXEC uspGetClosingBal @ACCOUNTID,@ReturnValue OUTPUT
IF( @ReturnValue !=0)
BEGIN
RAISERROR (''OSPending'',16,1)
END
END
IF ISNULL(@Shinecode,'''')!=''''
BEGIN
SELECT @ExistCount=COUNT(Id) FROM tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE (Shinecode = @Shinecode AND ID != @ID)
IF( @ExistCount >0)
BEGIN
RAISERROR (''Shine code already exists'',16,1)
END
END
--Previous ID data Posting in History table
insert into tblMasterCustomerVendorHistory (FormID,ID,Code,Name,Billadd1,Billadd2,Billadd3,Shipadd1,shipadd2,Shipadd3,Pincode,
ContactPerson,Ph1,Ph2,Mob1,Mob2,Email,PANNumber,AadharNo,DLNo20,DLNo21,FSSAINo,StateID,GSTIN,CreditTermID,PaymentModeID,
TaxTypeID,OSValue,FAID,PriceTypeWeekCycle,Active,CBy,CDate,MBy,MDate,Rating,HisCBy,HisCDate,Shinecode)
select 27,ID,Code,Name,Billadd1,Billadd2,Billadd3,Shipadd1,shipadd2,Shipadd3,Pincode,ContactPerson,Ph1,Ph2,Mob1,Mob2,Email,PANNumber,
AadharNo,DLNo20,DLNo21,FSSAINo,StateID,GSTIN,CreditTermID,PaymentModeID,TaxTypeID,OSValue,FAID,WeekCycle,Active,CBy,
CDate,MBy,MDate,Rating,@UserID,GETDATE(),Shinecode from tblMasterVendor WITH (READCOMMITTEDLOCK) where ID = @ID

set @Code =(select dbo.ProperCase(@Code))
set @Name = (select dbo.ProperCase(@Name))
set @ContactPerson = (select dbo.ProperCase(@ContactPerson))
set @Billadd1 = (select dbo.ProperCase(@Billadd1))
set @Billadd2 =(select dbo.ProperCase(@Billadd2))
set @Billadd3 = (select dbo.ProperCase(@Billadd3))
set @Shipadd1 =(select dbo.ProperCase(@Shipadd1))
set @Shipadd2 = (select dbo.ProperCase(@Shipadd2))
set @Shipadd3 = (select dbo.ProperCase(@Shipadd3))
UPDATE tblFAAccount
SET AccountName=@name,AccountGroup=@SUNDRYDEBTORS,MBy=@UserID,MDate=GETDATE(),UserAccount=0,PANNumber=@PANNumber,Active = @Active
WHERE FAID=@ACCOUNTID

UPDATE tblMasterVendor SET Code = @Code,Name = @Name,Billadd1 = @Billadd1,Billadd2 = @Billadd2,Billadd3 = @Billadd3,Shipadd1 = @Shipadd1,shipadd2 = @shipadd2,
Shipadd3 = @Shipadd3,Pincode = @Pincode,ContactPerson = @ContactPerson,Ph1 = @Ph1,Ph2 = @Ph2,Mob1 = @Mob1,Mob2 = @Mob2,
Email = lower(@Email),PANNumber = @PANNumber, AadharNo = @AadharNo,DLNo20 = @DLNo20,DLNo21 = @DLNo21,FSSAINo = @FSSAINo,
StateID = @StateID,GSTIN = UPPER(@GSTIN),CreditTermID = @CreditTermID, PaymentModeID = @PaymentModeID,TaxTypeID = @TaxTypeID,
WeekCycle = @WeekCycle,Active = @Active,MBy = @UserID,MDate = GETDATE(),Rating = @Rating,Shinecode = @Shinecode WHERE ID=@ID

SELECT @ID
END
IF(@Mode = 3)
BEGIN
SELECT TC.ID,TC.Code,TC.Name,TC.ContactPerson,TC.Email,Ph1,TC.Ph2,TC.Mob1 Mob1,TC.Mob2,TC.Billadd1,TC.Billadd2,TC.Billadd3,TC.Shipadd1,TC.Shipadd2,TC.Shipadd3,
TC.Pincode,TC.PANNumber,TC.AadharNo,TC.FSSAINo,TC.DLNo20,TC.DLNo21,SNC.StateName,TC.GSTIN,TT.TaxTypeName,PM.PaymentMode,MCT.Name [CreditTerm],WC.WeekDays[WeekCycle],RT.RatingName Ratings,
Case when TC.Active = 1 then ''Yes'' else ''No'' end Active,CASE WHEN ISNULL(TC.MBy,0) = 0 THEN CUR.UserName ELSE MUR.UserName END CBy,
CASE WHEN ISNULL(TC.MBy,0) = 0 THEN CONVERT(NVARCHAR(100),TC.CDate) ELSE CONVERT(NVARCHAR(100),TC.MDate) END CDate,Shinecode
FROM tblMasterVendor TC WITH (READCOMMITTEDLOCK)
LEFT JOIN tblRatings RT WITH (READCOMMITTEDLOCK) ON RT.ID = TC.Rating
JOIN tblUsers CUR WITH (READCOMMITTEDLOCK) ON CUR.ID = TC.CBy
LEFT JOIN tblUsers MUR WITH (READCOMMITTEDLOCK) ON MUR.ID = TC.MBy
LEFT JOIN tblMasterTaxType TT WITH (READCOMMITTEDLOCK) ON TT.TaxTypeID = TC.TaxTypeID
LEFT JOIN tblMasterCreditTerm MCT WITH (READCOMMITTEDLOCK) ON MCT.ID = TC.CreditTermID
LEFT JOIN tblWeekCycle WC WITH (READCOMMITTEDLOCK) ON WC.ID = TC.WeekCycle
LEFT JOIN tblPaymentMode PM WITH (READCOMMITTEDLOCK) ON PM.ID = TC.PaymentModeID
LEFT JOIN tblGSTStateNameandCode SNC WITH (READCOMMITTEDLOCK) ON SNC.StateID = TC.StateID
ORDER BY TC.Code,TC.Name
END
IF(@Mode = 4)
BEGIN
DECLARE @OSVAL DECIMAL(25,4),@FAI INT, @OSCOUNT INT
SELECT @FAI = FAID FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE ID = @ID
EXEC uspGetClosingBal @FAI,@ReturnValue OUTPUT

SELECT @OSCOUNT = COUNT(ID), @OSVAL= SUM(Balance) FROM tblTransPurchaseHeader WITH (READCOMMITTEDLOCK) WHERE VendorID = @ID AND Status IN (1,3) AND Balance > 0
SELECT *,@ReturnValue OSVAL,@OSCOUNT OSCOUNT from tblMasterVendor WITH (READCOMMITTEDLOCK) WHERE ID = @ID
END
IF(@Mode = 5)
BEGIN
select 1 FType,''Tax Type'' Form,TaxTypeID,TaxTypeName Descriptions from tblMasterTaxType WITH (READCOMMITTEDLOCK) WHERE Active = 1
union
select 2 FType,''Payment Mode'' Form,ID,PaymentMode Descriptions from tblPaymentMode WITH (READCOMMITTEDLOCK) WHERE Active = 1
union
select 3 FType,''Credit Term'' Form,ID,Name Descriptions from tblMasterCreditTerm WITH (READCOMMITTEDLOCK) WHERE Active = 1
union
select 4 FType,''State Names'' Form,StateID,CONVERT(NVARCHAR,TINNO)+'' - ''+ StateName Descriptions from tblGSTStateNameandCode WITH (READCOMMITTEDLOCK) WHERE Active = 1
union
select 5 FType,''Rating'' Form,ID,RatingName Descriptions from tblRatings WITH (READCOMMITTEDLOCK) WHERE Active = 1
union
select 6 FType,''WeekCycle'' Form,ID,WeekDays Descriptions from tblWeekCycle WITH (READCOMMITTEDLOCK) WHERE Active = 1
order by FType,Descriptions
END
END TRY
BEGIN CATCH
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(), ERROR_LINE()
END CATCH
END',
N'[export] nocount;readcommittedlock=37';
GO
/****** uspManufSalesableDmgReturnAnalysis ******/
EXEC #Apply07 N'dbo.uspManufSalesableDmgReturnAnalysis', 0x40E51EB75E8CF87D0D805B7095511DCD6ABF24887A80C621A6E4F1C81359E1FC, 0xE999992BF6A188597B72681C2D26772FACDF9DD55E15B3BEA7F936F5C6B6D26F, NULL, 0xB31EF956442D9388D91823642D832E00C89762E3DD6C51577AED9123BDC93ACC, 0xE5B36A42B1AF8A6276AABC0889B8EF41886BE2888E9BE2D6A6CF1146504AC966, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspManufSalesableDmgReturnAnalysis]        
@BranchName int = 0,@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255)='''',       
@FromDate DATE = ''2025-05-01'',@ToDate DATE = ''2025-08-30''      
as      
SET NOCOUNT ON;
begin      
SET DATEFORMAT dmy;    
DECLARE @DiffMonthCount INT,@TempFromDate NVARCHAR(50),@DateSerial INT,@FD DATE,@TD DATE,                
@Query NVARCHAR(MAX) ,@SR DEcimal(25,6),@DR DEcimal(25,6),@GSR  DECIMAL(25,6),@GDR DECIMAL(25,6),@StrQuery NVARCHAR(max) = ''''        
  
SET @DiffMonthCount = (SELECT DATEDIFF(MONTH,@FromDate,@ToDate)+1)                
SET @DateSerial = 0                  
CREATE TABLE #TEMP (MFID INT,MFNAME NVARCHAR(255),[MONTH] NVARCHAR(255),InvSale  DECIMAL(25,6),                
GInvSale  DECIMAL(25,6),SR DECIMAL(25,6),GSR DECIMAL(25,6),DR DECIMAL(25,6),GDR DECIMAL(25,6),TRANTYPE INT)      
WHILE @DiffMonthCount > 0                                                              
BEGIN                 
SET @FD = (CASE WHEN (DATEADD(mm, DATEDIFF(mm, 0, DATEADD(MONTH,@DateSerial,@FromDate)),0)) < @FromDate THEN @FromDate ELSE (DATEADD(mm, DATEDIFF(mm, 0, DATEADD(MONTH,@DateSerial,@FromDate)),0)) END)                
SET @TD = (CASE WHEN  DATEADD(dd, -1, DATEADD(mm, DATEDIFF(mm, 0, DATEADD(MONTH,@DateSerial,@FromDate)) + 1, 0)) > @ToDate THEN @ToDate ELSE  DATEADD(dd, -1, DATEADD(mm, DATEDIFF(mm, 0, DATEADD(MONTH,@DateSerial,@FromDate)) + 1, 0)) END)                  
  
    
      
SET @Query = (CONVERT(NVARCHAR(3), UPPER(DATENAME(MONTH,DATEADD(MONTH,@DateSerial,@FromDate)))) +'' ''+ CAST(DATEPART(YYYY,DATEADD(MONTH,@DateSerial,@FromDate)) AS VARCHAR))                
  print @Query+ '' , From : ''+convert(nvarchar(50),@FD)+ '' , To : ''+convert(nvarchar(50),@TD)  
SET @StrQuery = '' SELECT  MF.ID ,MF.Name, @Query ,              
(case when TransactionType in (1,4,5,6) then ISNULL(sum(TSD.NetAmt),0)   END) AS InvSale,(case when TransactionType in (1,4,5,6) then ISNULL(sum(TSD.GrossAmt),0)  end) AS GInvSale,                
(case when TransactionType = 2 then ISNULL(sum(TSD.NetAmt),0)   END) AS SR,(case when TransactionType = 2 then ISNULL(sum(TSD.GrossAmt),0)  end) AS GSR,                
(case when TransactionType = 3 then ISNULL(sum(TSD.NetAmt),0)  end) as DR,(case when TransactionType = 3 then ISNULL(sum(TSD.GrossAmt),0) end) AS GDR,TransactionType                
 FROM tblTranSalesDetail TSD                
 JOIN tblTranSalesHeader AS TSH ON TSH.ID=TSD.InvId                
 JOIN tblMasterProduct AS MP ON MP.ID = TSD.ProdId                
 JOIN tblMasterManufacturer AS MF ON MF.ID  =MP.MfrID       
 left join tblMasterBrand MB ON  MB.ID = MP.BrandID      
left join tblMasterCategory MC ON  MC.ID = MP.CategoryID      
left join tblMasterBranchOffice MBO ON  MBO.ID = TSH.BranchID      
WHERE  Status IN (1,3,6,5,7) ''    
 SET @StrQuery += (CASE WHEN ISNULL(@FD,'''')='''' AND ISNULL(@TD,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @FD  AND  @TD )'' END)                    
 set @StrQuery += case when ISNULL(@BranchName,'''') = '''' then '''' else '' AND TSH.BranchID  = ''+'' @BranchName ''+'''' END          
 set @StrQuery += case when ISNULL(@BrandName,'''') = '''' then '''' else '' AND MB.ID IN (SELECT * from dbo.fnSplitString( ''+'' @BrandName ,'''',''''))'' END          
 set @StrQuery += case when ISNULL(@CategoryName,'''') = '''' then '''' else '' AND MC.ID IN (SELECT * from dbo.fnSplitString( ''+'' @CategoryName ,'''',''''))'' END          
 set @StrQuery += case when ISNULL(@ManufName,'''') = '''' then '''' else '' AND MF.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ManufName ,'''',''''))'' END          
 set @StrQuery += case when ISNULL(@ProductName,'''') = '''' then '''' else '' AND MP.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ProductName ,'''',''''))'' END           
 set @StrQuery += '' group by TransactionType,MF.ID,MF.Name,TSH.InvDate ORDER BY TSH.InvDate ASC ''    
INSERT INTO #TEMP         
EXEC sys.sp_executesql @StrQuery, N''@BranchName int, @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @FromDate DATE, @ToDate DATE, @FD DATE, @TD DATE, @Query NVARCHAR(MAX)'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @FromDate, @ToDate, @FD, @TD, @Query        
SET @DateSerial = @DateSerial + 1                                                              
SET @DiffMonthCount = @DiffMonthCount - 1                 
END          
SELECT                
MFID ManufID,MFNAME as [Mfr Name],[MONTH] AS [MM/YYYY], dbo.fnGetRoundedValue(ISNULL(SUM(GInvSale),0)) AS [Gross Sales Value],                
dbo.fnGetRoundedValue(ISNULL(SUM(InvSale),0)) AS [Net Sales Value],dbo.fnGetRoundedValue(ISNULL(SUM(GSR),0)) AS [Gross SR Value],                
dbo.fnGetRoundedValue(ISNULL(SUM(SR),0)) AS [Net SR Value],dbo.fnGetRoundedValue(ISNULL(SUM(GDR),0)) AS [Gross DR Value],                
dbo.fnGetRoundedValue(ISNULL(SUM(DR),0)) AS [Net DR Value] FROM #TEMP                
GROUP BY MFNAME,[MONTH],MFID         
ORDER BY CONVERT(date,CONVERT(nvarchar,DATEADD(month, DATEDIFF(month, 0, [MONTH]), 0),103)) ASC,MFNAME ASC          
DROP TABLE #TEMP    
END',
N'[06] nocount';
GO
/****** uspManufwiseStockHoldingHeader ******/
EXEC #Apply07 N'dbo.uspManufwiseStockHoldingHeader', 0x79697FEC412D428276802C7FD1C587FDDDEA33E8FFDA7B5086AB32E7FEDDF171, 0x3B1E63EE2C3299EFCA8D51BF5C2B9CABA32B66E2CB09FEE4D85203FB58EDEA7A, NULL, 0x71B2CBE7105E46CD8DCAB879AF32346DB4D2EBFF00D5ABBAFD3F40357EF42082, 0x617FE992A2F64C6C729CE48E776CEEA446D80ABF3A04B5A3E53255E992C504C5, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspManufwiseStockHoldingHeader]        
@BranchName int = 0,@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255)='''',       
@FromDate DATE = ''2025-07-01'',@ToDate DATE = ''2025-08-30''      
as      
SET NOCOUNT ON;
begin      
SET DATEFORMAT dmy;          
select BranchID,NK.ManufID AS [ManufID],BrandID,CategoryID,ProdID,NK.[Manufacture Name],NK.[Stock In hand] into #Temp1 from (                  
SELECT PIN.BranchID,MF.ID as [ManufID],MP.BrandID,MP.CategoryID,MP.ID ProdID ,MF.Name AS [Manufacture Name],                  
(sum(PIN.ActualQty * PIN.PurchasePrice)) AS  [Stock In hand]                  
FROM tblProductInventory AS PIN                  
LEFT JOIN tblMasterProduct as MP on MP.ID = PIN.ProdId                  
JOIN tblMasterManufacturer as MF on MF.ID = MP.MfrID      
GROUP BY MF.ID,MF.Name,BrandID,CategoryID,MP.ID,PIN.BranchID) AS NK                  
--Temp Table 2                  
SELECT BranchID,JNK.ManufacturerId,JNK.[Month Sales],JNK.[Perday sales] into #Temp2   FROM(                  
SELECT  PIN.BranchID,MF.ID ManufacturerId,                  
(SUM((TSD.UomQty * isnull(MP.BaseCR,0))  * PIN.PurchasePrice)) AS [Month Sales],                  
(SUM((TSD.UomQty * isnull(MP.BaseCR,0)  * PIN.PurchasePrice) /(DATEDIFF(DAY,@FromDate,@ToDate) + 1))) AS [Perday sales]                  
FROM tblProductInventory AS PIN                  
LEFT JOIN tblTranSalesDetail as TSD on TSD.InventoryId = PIN.InventoryId                  
LEFT JOIN tblTranSalesHeader AS TSH ON TSH.ID = TSD.InvId                  
JOIN tblMasterProduct as MP on MP.ID = PIN.ProdId                  
JOIN tblMasterManufacturer as MF on MF.ID = MP.MfrID                  
WHERE TSH.InvDate BETWEEN @FromDate AND @ToDate AND Status IN (1,3,5) and TSH.DocPrefix = 15                  
GROUP BY MF.ID,PIN.BranchID)as JNK                  
--SELECT VALUES                  
SELECT TMP5.BranchID,TMP5.ManufID AS [ManufID],BrandID,CategoryID,ProdID,[Manufacture Name] AS [Manufacture Name],                  
ISNULL(sum([Month Sales]),0) as [Month Sales],ISNULL(sum([Perday sales]),0) as [Perday Sales],                  
ISNULL(sum([Stock In hand]),0) as [Stock In Hand],ISNULL(sum([Stock In hand] / NULLIF([Perday sales],0)),0) as [Stock Hold]               
INTO #MAINTEMP from #Temp1 as TMP5            
LEFT join #Temp2 as Temp6 on Temp6.ManufacturerId=TMP5.ManufID                  
GROUP BY TMP5.ManufID,TMP5.[Manufacture Name],BrandID,CategoryID,ProdID,TMP5.BranchID        
DECLARE @query NVARCHAR(MAX) = ''''      
set @query = ''      
SELECT ManufID,[Manufacture Name] [Mfr Name],dbo.fnGetRoundedValue(([Month Sales])) [Month Sales],dbo.fnGetRoundedValue(([Perday Sales])) [Perday Sales],              
dbo.fnGetRoundedValue(SUM([Stock In Hand])) [Stock In Hand],dbo.fnGetRoundedValue(SUM([Stock Hold])) [Stock Hold]               
FROM #MAINTEMP MT      
left join tblMasterProduct MP ON MP.ID = MT.ProdID      
left join tblMasterBrand MB ON  MB.ID = MT.BrandID      
left join tblMasterCategory MC ON  MC.ID = MT.CategoryID      
left join tblMasterBranchOffice MBO ON  MBO.ID = MT.BranchID      
WHERE (MANUFID != 0 OR MANUFID = 0) ''      
 set @query += case when ISNULL(@BranchName,'''') = '''' then '''' else '' AND MT.BranchID = ''+'' @BranchName ''+'''' END          
 set @query += case when ISNULL(@BrandName,'''') = '''' then '''' else '' AND MB.ID IN (SELECT * from dbo.fnSplitString( ''+'' @BrandName ,'''',''''))'' END          
 set @query += case when ISNULL(@CategoryName,'''') = '''' then '''' else '' AND MC.ID IN (SELECT * from dbo.fnSplitString( ''+'' @CategoryName ,'''',''''))'' END          
 set @query += case when ISNULL(@ManufName,'''') = '''' then '''' else '' AND [ManufID] IN (SELECT * from dbo.fnSplitString( ''+'' @ManufName ,'''',''''))'' END          
 set @query += case when ISNULL(@ProductName,'''') = '''' then '''' else '' AND MP.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ProductName ,'''',''''))'' END              
SET @query = @query + '' GROUP BY ManufID,[Manufacture Name],[Month Sales],[Perday Sales] ORDER BY SUM([Stock Hold]) DESC ''          
EXEC sys.sp_executesql @query, N''@BranchName int, @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @FromDate, @ToDate            
drop table #Temp1,#Temp2,#MAINTEMP         
end',
N'[06] nocount';
GO
/****** uspMenuPermission ******/
EXEC #Apply07 N'dbo.uspMenuPermission', 0x3DB7D613ED4AE157A28B9D31159294C39436450070163F373E10631AC8A39CB6, NULL, NULL, 0x78858262993D12702D0A73851FBA5407F91F5362309CB745AA65BB33282F422B, 0x89DB7C19CBEF177C5E6B2564159FB97F1E39D8109FC60C4C6A14DB27AC061425, NULL,
N'--[uspMenuPermission] 2,2,2                        
ALTER PROCEDURE [dbo].[uspMenuPermission]                              
@Mode INT,@RoleID INT = NULL,@UserID INT=NULL,@WeborMobile int = 0                        
AS                                            
SET NOCOUNT ON;
BEGIN                                          
IF ISNULL(@Mode,0)=1                              
BEGIN        
create table #tempFavPar(idx tinyint,MenuId smallint,MenuName nvarchar(255),MenuParentId smallint,MenuChildLevel smallint,MenuTree smallint,        
LocationName  nvarchar(255),Permission smallint,IsMenu tinyint,FormID smallint,EncMenuID  nvarchar(max),EncMenuName  nvarchar(max),        
EncFormID  nvarchar(max),IsMobileApp tinyint,DisplayIndex smallint)        
if exists(select * from tblMenus where IsMenu = 1 and Favourite = 1 and IsMobileApp = @WeborMobile)        
begin        
insert into #tempFavPar values(1,(select max(menuid) + 1 from tblMenus where IsMobileApp = @WeborMobile),''Favourite'',0,1,0,        
''Favourite'',1,1,0,null,null,null,0,(select count(*) + 1 from tblMenus WHERE MenuParentId=0 and IsMobileApp = @WeborMobile ))        
end        
select MenuId,MenuName,MenuParentId,MenuChildLevel,MenuTree,LocationName,Permission,IsMenu,FormID,EncMenuID,EncMenuName,EncFormID,IsMobileApp from (        
SELECT 2 idx,MenuId,MenuName,MenuParentId,MenuChildLevel,MenuTree,LocationName,Permission,IsMenu,FormID,EncMenuID,EncMenuName,EncFormID,IsMobileApp,DisplayIndex        
FROM tblMenus WHERE MenuParentId=0 and IsMobileApp = @WeborMobile  
union all        
SELECT * from #tempFavPar) as rec        
ORDER BY idx,MenuTree,DisplayIndex ASC
drop table #tempFavPar        
END                              
ELSE                              
BEGIn                              
DECLARE @PERMISSION AS TABLE (USERID INT)                                          
INSERT INTO @PERMISSION SELECT PermissionFormId FROM tblRolePermissions WHERE Role=@RoleID                                
BEGIN                                           
IF isnull(@RoleID,0) = 1 AND ISNULL(@UserID,0) = 1                        
BEGIN                                      
select MenuId,MenuName,MenuParentId,MenuChildLevel,MenuTree,LocationName,Permission,IsMenu,FormID,EncMenuID,EncMenuName,EncFormID,        
IsMobileApp,Favourite Favourites,DisplayIndex from (         
SELECT 2 idx,MenuId,MenuName,MenuParentId,MenuChildLevel,MenuTree,LocationName,Permission,IsMenu,FormID,EncMenuID,EncMenuName,EncFormID,        
IsMobileApp,DisplayIndex,Favourite    
FROM tblMenus WHERE MenuParentId!=0 and IsMobileApp = @WeborMobile  
union all        
SELECT 1 idx,MenuId,MenuName,(select max(menuid) + 1 from tblMenus where IsMobileApp = @WeborMobile),2 MenuChildLevel,0,LocationName,  
Permission,IsMenu,FormID,EncMenuID,EncMenuName,EncFormID,IsMobileApp,DisplayIndex,Favourite        
FROM tblMenus WHERE MenuParentId!=0  and Favourite = 1 AND IsMenu = 1 and IsMobileApp = @WeborMobile) as rec        
ORDER BY idx ,MenuTree ASC ,DisplayIndex ASC      
END                                
ELSE                                
BEGIN            
select MenuId,MenuName,MenuParentId,MenuChildLevel,MenuTree,LocationName,Permission,IsMenu,FormID,EncMenuID,EncMenuName,EncFormID,        
IsMobileApp,Favourite Favourites,DisplayIndex from (         
SELECT 2 IDX,MenuId,MenuName,MenuParentId,MenuChildLevel,MenuTree,LocationName,Permission,IsMenu,FormID,EncMenuID,EncMenuName,EncFormID,IsMobileApp,    
DisplayIndex,Favourite    
FROM tblMenus WHERE MenuId IN (SELECT * FROM @PERMISSION) AND MenuParentId!=0 and IsMobileApp = @WeborMobile  
AND MenuId IN (SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2)          
union all        
SELECT 1 idx,MenuId,MenuName,(select max(menuid) + 1 from tblMenus where IsMobileApp = @WeborMobile),2 MenuChildLevel,0,LocationName,Permission,IsMenu,        
FormID,EncMenuID,EncMenuName,EncFormID,        
IsMobileApp,DisplayIndex ,Favourite    
FROM tblMenus WHERE Favourite = 1 AND IsMenu = 1 and IsMobileApp = @WeborMobile AND  MenuId IN (SELECT * FROM @PERMISSION) AND MenuParentId!=0           
AND MenuId IN (SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2)) as rec        
ORDER BY idx,MenuTree ASC,DisplayIndex ASC
END                                          
END                                
END                              
END',
N'[export] nocount';
GO
/****** uspMfrwiseDatewiseclosingDetail ******/
EXEC #Apply07 N'dbo.uspMfrwiseDatewiseclosingDetail', 0x7DF5B522CB9F3911ECD962376EADB5DB8B90E649D6FA24539887285D3D5E16B0, NULL, NULL, 0x889281EA9D393CA06AB574EA750D03EF2AE0B52BC614F87C94B5E7BA20DFAC91, 0xD3ADAF3C30A39275E14A21CE92A836CE1D8F54C2C1ECEDA8B5DBCC0C4B84403F, NULL,
N'--uspMfrwiseDatewiseclosingDetail 
ALTER PROC [dbo].[uspMfrwiseDatewiseclosingDetail]
@MfrID INT = 2,@FilterMfrID nvarchar(255) = '''',@FilterProdID nvarchar(255) = '''',@QtyorValue INT = 2,
@FromDate DATE = ''2026-09-01'',@ToDate DATE = ''2026-10-01''
as
SET NOCOUNT ON;
begin
SET DATEFORMAT dmy;        

--select * from tblMasterProduct where (@ttmfr = '''' OR MfrID IN (SELECT * FROM string_split(@ttmfr,'',''))) AND 
--(@ttprd = '''' OR ID IN (SELECT * FROM string_split(@ttprd,'','')))

CREATE TABLE #Temp( Serial INT IDENTITY,Date DATE,OpeningStock DECIMAL(25,6),PQty DECIMAL(25,6),PRQty DECIMAL(25,6),    
SaleQty DECIMAL(25,6),SRQty DECIMAL(25,6),AdjQty DECIMAL(25,6),ConQty DECIMAL(25,6),RepackQty DECIMAL(25,6),    
StockINQty DECIMAL(25,6),StockOUTQty DECIMAL(25,6),ClosingStock DECIMAL(25,6))        
DECLARE @MfrName nvarchar(255)
set @MfrName=(select Name from tblMasterManufacturer where ID=@MfrID)        

DECLARE @DateCount INT=(SELECT DATEDIFF(DAY,@FromDate,@Todate)),@DateSerial INT=1        
INSERT INTO #Temp (Date)VALUES(CAST(@FromDate AS DATE))        
WHILE @DateCount>0        
BEGIN        
INSERT INTO #Temp (Date)VALUES(CAST(DATEADD(DAY,@DateSerial,@FromDate)AS DATE))        
SET @DateCount=@DateCount-1        
SET @DateSerial=@DateSerial+1        
END        
DECLARE @Serail INT=1,@Count INT=(SELECT COUNT(*) FROM #Temp)        
WHILE @Count >0        
BEGIN        
DECLARE @TempDate DATE =(SELECT Date FROM #Temp WHERE Serial =@Serail)        
DECLARE @TempOpeningStock DECIMAL(25,6),@TempGRNStock DECIMAL(25,6),@TempPRStock DECIMAL(25,6),@TempSalesStock DECIMAL(25,6),        
@TempSRStock DECIMAL(25,6),@TempAdjStock DECIMAL(25,6),@TempConverStock DECIMAL(25,6),@TempRepackStock DECIMAL(25,6),@ClosingStock DECIMAL(25,6)        
,@TempStockIN DECIMAL(25,6),@TempStockOUT DECIMAL(25,6)    
SELECT @TempOpeningStock=OpeningStock,@TempGRNStock=PQty,@TempPRStock=PRQty,@TempSalesStock=SaleQty,        
@TempSRStock=SRQty,@TempAdjStock=AdjQty,@TempConverStock=ConQty,@TempRepackStock=RepackQty,@ClosingStock=ClosingQty,    
@TempStockIN = StockINQty,@TempStockOUT = StockOUTQty    
FROM dbo.fnGetMfrStockMovementValues(@MfrID,@FilterProdID,@TempDate,NULL,2,@QtyorValue)        
UPDATE #Temp        
SET OpeningStock=ISNULL(@TempOpeningStock,0),PQty=@TempGRNStock,PRQty=@TempPRStock,SaleQty=@TempSalesStock,SRQty=@TempSRStock,        
AdjQty=@TempAdjStock,ConQty=ISNULL(@TempConverStock,0),RepackQty=ISNULL(@TempRepackStock,0),ClosingStock=@ClosingStock ,    
StockINQty = ISNULL(@TempStockIN,0),StockOUTQty = ISNULL(@TempStockOUT,0)       
WHERE Serial =@Serail        
SET @Serail = @Serail +1        
SET @Count = @Count-1        
END        
SELECT      
@MfrName as  [Manuf Name],CONVERT(NVARCHAR,Date,103)AS [DATE],      
(OpeningStock) AS [Opening Stock],(PQty) AS [Purchase Qty],        
(PRQty) AS [Purchase Return Qty],(SaleQty) AS [Sales Qty],        
(SRQty) AS [Sales Return Qty],(AdjQty) AS [Adjust Qty],        
(ConQty) AS [Conversion Qty],(RepackQty) AS [Repacking Qty],        
(StockINQty) AS [Stock IN Qty],(StockOUTQty) AS [Stock OUT Qty],    
(ClosingStock) AS [Closing Stock Qty] FROM #Temp        
DROP TABLE #Temp       
end',
N'[export] nocount';
GO
/****** uspMfrwiseDatewiseclosingHeader ******/
EXEC #Apply07 N'dbo.uspMfrwiseDatewiseclosingHeader', 0x6D47C5145B7FE4E9A8BBEA9216EEE23C27C95181125381BF0525482CEB0B060D, NULL, NULL, 0x1A28885D372E19E70D4F5B9EF7968D45D243A7B04E4905107FD3966413A7E66C, 0x0317F0B7618FC2BAB195A9E763668A7BFD7F8854FF352FAF17C215E54225F044, NULL,
N'ALTER PROC [dbo].[uspMfrwiseDatewiseclosingHeader]
@MfrID nvarchar(255) = '''',@ProdID nvarchar(255) = '''',@QtyorValue INT = 1 ,@FromDate DATE = ''2026-10-01'',
@ToDate DATE = ''2026-10-01''
AS
SET NOCOUNT ON;
BEGIN
SET DATEFORMAT dmy;        

--declare @ttmfr nvarchar(255) = ''2,4,9''
--declare @ttprd nvarchar(255) = ''''

CREATE TABLE #Temp(Serial INT IDENTITY,MfrID INT,[Manufacturer Name] NVARCHAR(255),
OpeningStock DECIMAL(25,6),PQty DECIMAL(25,6),PRQty DECIMAL(25,6),SaleQty DECIMAL(25,6),SRQty DECIMAL(25,6),AdjQty DECIMAL(25,6),ConQty DECIMAL(25,6),RepackQty DECIMAL(25,6),    
StockINQty DECIMAL(25,6),StockOUTQty DECIMAL(25,6),ClosingStock DECIMAL(25,6))    

INSERT INTO #Temp(MfrID,[Manufacturer Name])
select DISTINCT MP.MfrID,MF.Name from tblMasterProduct MP
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID
where (@MfrID = '''' OR MfrID IN (SELECT * FROM string_split(@MfrID,'',''))) AND 
(@ProdID = '''' OR MP.ID IN (SELECT * FROM string_split(@ProdID,'','')))
DECLARE @Serail INT=1,@Count INT=(SELECT COUNT(*) FROM #Temp)              
WHILE @Count > 0              
BEGIN 
DECLARE @TempManufID INT =(SELECT MfrID FROM #Temp WHERE Serial =@Serail)  
DECLARE @TempOpeningStock DECIMAL(25,6),@TempGRNStock DECIMAL(25,6),@TempPRStock DECIMAL(25,6),@TempSalesStock DECIMAL(25,6),        
@TempSRStock DECIMAL(25,6),@TempAdjStock DECIMAL(25,6),@TempConverStock DECIMAL(25,6),@TempRepackStock DECIMAL(25,6),@ClosingStock DECIMAL(25,6)        
,@TempStockIN DECIMAL(25,6),@TempStockOUT DECIMAL(25,6)    
SELECT @TempOpeningStock=OpeningStock,@TempGRNStock=PQty,@TempPRStock=PRQty,@TempSalesStock=SaleQty,        
@TempSRStock=SRQty,@TempAdjStock=AdjQty,@TempConverStock=ConQty,@TempRepackStock=RepackQty,@ClosingStock=ClosingQty,    
@TempStockIN = StockINQty,@TempStockOUT = StockOUTQty    
FROM dbo.fnGetMfrStockMovementValues(@TempManufID,@ProdID,@FromDate,@ToDate,1,@QtyorValue)  

UPDATE #Temp              
SET OpeningStock=ISNULL(@TempOpeningStock,0),PQty=ISNULL(@TempGRNStock,0),PRQty=ISNULL(@TempPRStock,0),              
SaleQty=ISNULL(@TempSalesStock,0),SRQty=ISNULL(@TempSRStock,0),AdjQty=ISNULL(@TempAdjStock,0),              
ConQty=ISNULL(@TempConverStock,0),RepackQty=ISNULL(@TempRepackStock,0),StockINQty =ISNULL(@TempStockIN,0),    
StockOUTQty = ISNULL(@TempStockOUT,0),ClosingStock = ISNULL(@ClosingStock,0)  WHERE Serial =@Serail              
SET @Serail = @Serail + 1              
SET @Count = @Count - 1              
END              
alter table #temp drop column serial
SELECT * FROM #Temp

DROP TABLE #Temp
END',
N'[export] nocount';
GO
/****** uspMfrwisesalesDetail ******/
EXEC #Apply07 N'dbo.uspMfrwisesalesDetail', 0xAB0D1330ED612DB536B0FCE1DC8EEDFCFA82CD7E5AB3C62E3E0519CD0BDBDB4F, 0xEFE706C09955FC06F746441A50E00F2B11BF2546A662BAA5971515F2E962BDEF, NULL, 0x98D0AF8759B3B24F380EFE034AD9A1594AD6BF477F2C3D7774A9FEE8434703BB, 0x624298A79A35C1123B2C7CD96FA5BB9BBAADB3109B765F752B249F6849B5320D, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspMfrwisesalesDetail]      
@ManufID INT = 8,@BranchName NVARCHAR(255) = ''0'',@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255) = '''',      
@FromDate DATE = ''2025-08-01'',@ToDate DATE = ''2025-08-30''        
AS      
SET NOCOUNT ON;
BEGIN      
declare @StrQuery nvarchar(max) = ''''        
 set @StrQuery = '' SELECT MP.Code AS [Product Code],MP.Name AS [Product Name],MP.EAN,MF.Name [Mfr Name],          
MB.Name [Brand Name],PHL.Name [Category Name],        
(CASE WHEN TSH.DocPrefix = 15 THEN dbo.fnGetRoundedValue(SUM(TSD.AdjustQty))end) AS [Base Qty],          
dbo.fnGetRoundedValue(SUM(TSD.GrossAmt)) AS [Gross Amount],          
dbo.fnGetRoundedValue(SUM(TSD.NetAmt)) AS [Net Amount]          
FROM tblMasterManufacturer MM          
JOIN tblmasterProduct MP ON MP.MfrID=MM.ID          
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID        
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID      
JOIN tblMasterCategory PHL ON PHL.ID = MP.CategoryID        
JOIN tblTranSalesDetail TSD ON TSD.ProdId=MP.ID          
JOIN tblTranSalesHeader TSH ON TSH.ID=TSD.InvId          
WHERE TSH.Status IN (1,3,5) AND TSH.DocPrefix = 15 AND ISNULL(TSD.TaxId,0)>0 AND MP.MfrID =  @ManufID ''      
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)                  
  
    
      
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BranchName,''0'')=''0'' THEN '''' ELSE '' AND TSH.BranchID =  @BranchName '' END)         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BrandName,'''')='''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString(  @BrandName ,'''',''''))'' END)                
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CategoryName,'''')='''' THEN '''' ELSE '' AND PHL.ID IN (SELECT * from dbo.fnSplitString(  @CategoryName ,'''',''''))'' END)         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ProductName,'''')='''' THEN '''' ELSE '' AND MP.ID IN (SELECT * from dbo.fnSplitString(  @ProductName ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + '' GROUP BY MP.Code,MP.Name,MP.EAN,TSH.DocPrefix,MB.Name,PHL.Name,MF.Name''      
EXEC sys.sp_executesql @StrQuery, N''@ManufID INT, @BranchName NVARCHAR(255), @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @ManufID, @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @FromDate, @ToDate      
 END',
N'[06] nocount';
GO
/****** uspMfrwisesalesHeader ******/
EXEC #Apply07 N'dbo.uspMfrwisesalesHeader', 0x1CB6E8A8E63EB6289948FF80B39293AB35A78EAAF938313018BECFE6D9459C0A, 0x310211927FD8EBEC71C21140D2542FE9E9F12333E724F1C17A37A5338EFCBE74, NULL, 0x56621F47045FD598C847CF7E6B8A71ACBD1C388250ACBD19185BB415E4572E01, 0x9767ACFD793376FF03156C61E103865CF757C265E5AACB71AC88F571D7229AB9, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspMfrwisesalesHeader]    
@BranchName NVARCHAR(255) = ''0'',@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255) = '''',  
@FromDate DATE = ''2025-08-01'',@ToDate DATE = ''2025-08-30''     
AS  
SET NOCOUNT ON;
BEGIN  
declare @StrQuery nvarchar(max) = ''''    
 set @StrQuery = '' SELECT MP.MfrID, MM.Name AS [Mfr Name],          
(CASE WHEN TSH.DocPrefix = 15 THEN dbo.fnGetRoundedValue(SUM(TSD.UomQty * MP.BaseCR))end) AS [Base Qty],             
dbo.fnGetRoundedValue(sum(TSD.GrossAmt)) AS [Gross Amount],dbo.fnGetRoundedValue(sum(TSD.NetAmt)) AS [Net Amount]          
FROM tblTranSalesDetail TSD          
JOIN tblTranSalesHeader TSH ON TSH.ID=TSD.InvId          
JOIN tblmasterProduct MP ON MP.ID = TSD.ProdId          
JOIN tblMasterManufacturer MM ON MM.ID=MP.MfrID      
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID    
JOIN tblMasterCategory PHL ON PHL.ID = MP.CategoryID    
WHERE TSH.Status IN (1,3,5) AND  TSH.DocPrefix = 15 AND ISNULL(TSD.TaxId,0)>0''  
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)                  
  
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BranchName,''0'')=''0'' THEN '''' ELSE '' AND TSH.BranchID =  @BranchName '' END)     
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ManufName,'''')='''' THEN '''' ELSE '' AND MM.ID IN (SELECT * from dbo.fnSplitString (  @ManufName ,'''',''''))'' END)         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BrandName,'''')='''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString (  @BrandName ,'''',''''))'' END)            
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CategoryName,'''')='''' THEN '''' ELSE '' AND PHL.ID IN (SELECT * from dbo.fnSplitString (  @CategoryName ,'''',''''))'' END)     
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ProductName,'''')='''' THEN '''' ELSE '' AND MP.ID IN (SELECT * from dbo.fnSplitString (  @ProductName ,'''',''''))'' END)     
SET @StrQuery = @StrQuery + '' GROUP BY MP.MfrID,MM.Name,TSH.DocPrefix order by MM.Name''  
EXEC sys.sp_executesql @StrQuery, N''@BranchName NVARCHAR(255), @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @FromDate, @ToDate  
 END',
N'[06] nocount';
GO
/****** uspMobileCustomerOS ******/
EXEC #Apply07 N'dbo.uspMobileCustomerOS', 0xC65915FF41336F83D028A8861885DF2E921891CFE7089939BAABFBB026EF292E, NULL, NULL, 0xBF5C446D48BF3D02CF10DE1C7850DAA7A582E2E2CAC4F5B2A8138593C94B6E86, 0x00C65B2C3A999835C5F4B6CFF3A9BAA51F3148D02986AFB3A06F8E9C712DC7F2, NULL,
N'--uspMobileCustomerOS 2,0,0,'''',''15,30,45''  
ALTER PROC [dbo].[uspMobileCustomerOS]  
@Mode int, @BeatName int=0,@SalesmanName int=0,@CustomerName NVARCHAR(255)='''',  
@fnSplitString NVARCHAR(MAX) = ''10'',@CustomerType int = 0,@Rating int = 0  
AS  
SET NOCOUNT ON;
BEGIN  
IF(@Mode = 1)  
BEGIN  
SELECT ID,Name FROM tblMasterBeat WHERE Active = 1 ORDER BY Name  
SELECT ID,Name FROM tblMasterSalesman WHERE Active = 1 ORDER BY Name  
SELECT ID,Name FROM tblMasterCustomer WHERE Active = 1 ORDER BY Name  
SELECT ID,Name FROM tblMasterCustomerType WHERE Active = 1 ORDER BY Name  
SELECT ID,RatingName Name FROM tblRatings WHERE Active = 1 ORDER BY Name  
SELECT ID, Name FROM tblmasterPeriod WHERE Active = 1 ORDER BY Name  
END  
ELSE IF(@Mode = 2)  
BEGIN  
DECLARE @Serial INT,@Count INT, @Query NVARCHAR(MAX),@Count1 INT,@MainSerial INT, @MainCount INT,@AlterColumnName0 NVARCHAR(255),@AlterColumnName1 NVARCHAR(255)  
DECLARE @Ageing INT,@nCount INT,@nCount1 INT,@nSerial INT,@IsTrueFalse NVARCHAR(10),@nF INT,@nT INT,@nColumnName NVARCHAR(255)  
DECLARE @AsOnDate DATE = getdate()  
SELECT CD.DocID,ISNULL(SUM(TotalAmtAdj),0) TotalAmtAdj INTO #COLTEMP  
FROM tblTranCollectionHeader CH  
JOIN tblTranCollectionDetail CD ON CD.ColID = CH.ColID  
WHERE ColDate > @AsOnDate AND Status IN (1,3,5)  
GROUP BY CD.DocID  
  
--select * from #COLTEMP  
  
SELECT FAC.NoteID,FAC.Adjustment INTO #JVTEMP  
FROM tblFAJournal FA  
JOIN tblFAJournelCancel FAC ON FAC.JVID = FA.JVID  
WHERE DocPrefix = 8 AND DocDate > @AsOnDate AND FA.Status IN (1,3,5)  
GROUP BY FAC.NoteID,FAC.Adjustment  
  
--select * from #JVTEMP  
  
-- Create #TempTable1 for Moving Original Data  
CREATE TABLE #TempTable (DocPrefix int,ID INT,CustomerID int,[Customer Name] NVARCHAR(255)  
,[Opening Amount] DECIMAL(25,6),[Pending Amount] DECIMAL(25,6),[SR Balance] DECIMAL(25,6),[Ageing] INT)  
  
CREATE TABLE #TempTable1 (ID INT IDENTITY(1,1),DocPrefix int,CustomerID int,[Customer Name] NVARCHAR(255)  
,[Net Amt] NVARCHAR(255),[Balance] NVARCHAR(255),[SR Balance] NVARCHAR(255),[Ageing] INT)  
  
SELECT DocPrefix,SRI.[ID],[Customer ID],SRI.[Customer Name],SRI.[Opening Amount],SRI.[Pending Amount],SRI.[SR Balance],SRI.Ageing  
INTO #TEMPDATA  
FROM  
(  
SELECT SH.DocPrefix,SH.ID,FORMAT(SH.InvDate,''dd/MMM/yyyy'')[Doc Date],ISNULL(MC.ID,0)[Customer ID],MC.Name[Customer Name],  
SH.NetAmt[Opening Amount],  
CASE WHEN SH.DocPrefix = 15 THEN SH.Balance ELSE 0 END AS [Pending Amount],  
CASE WHEN SH.DocPrefix = 16 THEN SH.Balance ELSE 0 END AS [SR Balance],  
DATEDIFF(DAY,InvDate,@AsOnDate) AS [Ageing]  
FROM tblTranSalesHeader SH  
JOIN tblMasterCustomer MC on MC.ID = SH.CustID  
WHERE SH.DocPrefix in (15,16) AND SH.InvDate <= @AsOnDate AND SH.Status IN (1,3,5,6,7)  
and (@BeatName = 0 or sh.BeatID = @BeatName) and (@SalesmanName = 0 or sh.SalesManID = @SalesmanName)  
and (@CustomerType = 0 or MC.CustomerType = @CustomerType) and (@Rating = 0 or MC.Rating = @Rating)  
and (@CustomerName = '''' or MC.Name = @CustomerName)  
UNION ALL  
SELECT SH.DocPrefix,SH.ColID ID,FORMAT(SH.ColDate,''dd/MMM/yyyy'')[Doc Date],ISNULL(MC.ID,0)[Customer ID],MC.Name[Customer Name],  
SH.ColAmt [ColAmt],  
0 AS [Pending Amount],  
CASE WHEN SH.DocPrefix = 19 THEN SH.Balance ELSE 0 END AS [SR Balance],  
DATEDIFF(DAY,ColDate,@AsOnDate) AS [Ageing]  
FROM tblTranCollectionHeader SH  
JOIN tblMasterCustomer MC on MC.FAID = SH.AccID  
  
WHERE SH.DocPrefix in (19) AND SH.ColDate <= @AsOnDate AND SH.Status IN (1,3,5)  
and (@BeatName = 0 or sh.BeatID = @BeatName) and (@SalesmanName = 0 or sh.SalesManID = @SalesmanName)  
and (@CustomerType = 0 or MC.CustomerType = @CustomerType) and (@Rating = 0 or MC.Rating = @Rating)  
and (@CustomerName = '''' or MC.Name = @CustomerName)  
UNION ALL  
SELECT SH.TransID,SH.ID ID,FORMAT(SH.DocDate,''dd/MMM/yyyy'')[Doc Date],ISNULL(MC.ID,0)[Customer ID],MC.Name[Customer Name],  
SH.NetAmount [ColAmt],  
CASE WHEN SH.TransID = 7 THEN SH.Balance ELSE 0 END AS [Pending Amount],  
0 AS [SR Balance],  
--DATEDIFF(DAY,DocDate,@AsOnDate) AS [Ageing]  
(DATEDIFF(DD,ISNULL((select MIN(Date) from tblTranChequeDeposit CHQD  
JOIN tblTranCollectionDetail CH ON CH.ColID = CHQD.CollId  
where ChargesVoucherId = SH.ID OR ChaqueVoucherId = SH.ID),DocDate),@AsOnDate)) Ageing  
FROM tblTranPRVoucher SH  
JOIN tblMasterCustomer MC on MC.FAID = SH.PartyID  
LEFT JOIN tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID  
WHERE SH.TransID in (7) AND SH.DocDate <= @AsOnDate AND SH.Status IN (1,3,5,6,7)  
and (@BeatName = 0 or BSM.BeatID = @BeatName) and (@SalesmanName = 0 or BSM.SalesManID = @SalesmanName)  
and (@CustomerType = 0 or MC.CustomerType = @CustomerType) and (@Rating = 0 or MC.Rating = @Rating)  
and (@CustomerName = '''' or MC.Name = @CustomerName)  
UNION ALL  
SELECT SH.TransID,SH.ID ID,FORMAT(SH.DocDate,''dd/MMM/yyyy'')[Doc Date],ISNULL(MC.ID,0)[Customer ID],MC.Name[Customer Name],  
SH.NoteValue [ColAmt],  
0 AS [Pending Amount],  
CASE WHEN SH.TransID = 4 THEN SH.Balance ELSE 0 END AS [SR Balance],  
DATEDIFF(DAY,DocDate,@AsOnDate) AS [Ageing]  
FROM tblNoteDetails SH  
JOIN tblMasterCustomer MC on MC.FAID = SH.PartyID  
LEFT JOIN tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID  
WHERE SH.TransID in (4) AND SH.DocDate <= @AsOnDate AND SH.Status IN (1,3,5,6,7)  
and (@BeatName = 0 or BSM.BeatID = @BeatName) and (@SalesmanName = 0 or BSM.SalesManID = @SalesmanName)  
and (@CustomerType = 0 or MC.CustomerType = @CustomerType) and (@Rating = 0 or MC.Rating = @Rating)  
and (@CustomerName = '''' or MC.Name = @CustomerName)  
)SRI  
-- Create #TempID for Split String Ageing Wise  
CREATE TABLE #TempID (IdentID INT IDENTITY(1,1),ID INT)  
  
-- Create #TempAlterColumns for Identifying Column and Checking Range Between  
CREATE TABLE #TempAlterColumns (IdentID INT IDENTITY(1,1),[From] INT,[To] INT,OriginalColumn NVARCHAR(MAX))  
  
-- Insert Spliting String Datas  
INSERT INTO #TempID  
SELECT * FROM (SELECT DISTINCT id FROM dbo.fnSplitString(@fnSplitString,'','') WHERE ISNULL(id,'''')!='''') AS SRI ORDER BY CAST(SRI.id AS INT)  
  
--select * from #TEMPDATA  
INSERT INTO #TempTable  
SELECT DocPrefix,ID,[Customer ID],[Customer Name],SUM([Opening Amount]) [Opening Amount],SUM([Pending Amount]) [Pending Amount],  
SUM([SR Balance]) [SR Balance],Ageing  
FROM #TEMPDATA  
WHERE (Ageing = 0 OR Ageing != 0)  
AND(@CustomerName = '''' OR [Customer Name] = @CustomerName)  
GROUP BY DocPrefix,ID,[Customer ID],[Customer Name],Ageing  
ORDER BY [Customer Name]  
  
--select * from #TempTable  
  
INSERT INTO #TempTable1  
SELECT DocPrefix,CustomerID,[Customer Name],  
DBO.fnGetRoundedValue([Opening Amount]) [Opening Amount],DBO.fnGetRoundedValue([Pending Amount]) [Pending Amount],  
DBO.fnGetRoundedValue([SR Balance]) [SR Balance],Ageing FROM (  
SELECT DocPrefix,CustomerID,TT.[ID],TT.[Customer Name],  
SUM((TT.[Opening Amount])) [Opening Amount],SUM(((TT.[Pending Amount] + ISNULL(CT.TotalAmtAdj,0)+ ISNULL(Adjustment,0)))) AS [Pending Amount],  
SUM(TT.[SR Balance] *-1) AS [SR Balance],Ageing  
FROM #TempTable TT  
LEFT JOIN #COLTEMP CT ON CT.DocID = TT.ID  
LEFT JOIN #JVTEMP JV ON JV.NoteID = TT.ID  
--WHERE (TT.[Pending Amount] + ISNULL(CT.TotalAmtAdj,0)+ ISNULL(Adjustment,0)) <> 0  
GROUP BY DocPrefix,ID,[SR Balance],CustomerID,[Customer Name],Ageing  
) AS NK  
WHERE ((cast(([Pending Amount]) as numeric(26,2))) <> 0 or (cast(([SR Balance]) as numeric(26,2))) <> 0 )  
order by [Customer Name]  
  
SET @Count1 = (SELECT COUNT(*) FROM #TempID);  
SET @Count = (SELECT COUNT(*) FROM #TempID);  
SET @Serial = 1  
-- Looping for Alter and Spliting Columns using Ageing Wise  
IF ISNULL(@Count1,0)>1  
BEGIN  
print ''aaaaaaaaaaaaaaaaaa''  
WHILE (@Count > 0)  
BEGIN  
SET @AlterColumnName0 = (SELECT ID FROM #TempID WHERE IdentID = @Serial-1)  
SET @AlterColumnName1 = (SELECT ID FROM #TempID WHERE IdentID = @Serial)  
SET @AlterColumnName0 = @AlterColumnName0+1  
IF ISNULL(@Count,0)=1  
BEGIN  
SET @Query = ''ALTER TABLE #TempTable1 ADD [''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days] VARCHAR(100) NULL,[>''+@AlterColumnName1+'' Days] VARCHAR(100) NULL''  
EXEC(@Query)  
INSERT INTO #TempAlterColumns VALUES ((@AlterColumnName0),@AlterColumnName1,''[''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days]'')  
INSERT INTO #TempAlterColumns VALUES ((@AlterColumnName1),0,''[>''+@AlterColumnName1+'' Days]'')  
END  
ELSE IF ISNULL(@Count,0)= @Count1  
BEGIN  
SET @Query = ''ALTER TABLE #TempTable1 ADD [0-''+@AlterColumnName1+'' Days] VARCHAR(100) NULL''  
EXEC(@Query)  
INSERT INTO #TempAlterColumns VALUES (0,@AlterColumnName1,''[0-''+@AlterColumnName1+'' Days]'')  
END  
ELSE  
BEGIN  
SET @Query = ''ALTER TABLE #TempTable1 ADD [''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days] VARCHAR(100) NULL''  
EXEC(@Query)  
INSERT INTO #TempAlterColumns VALUES ((@AlterColumnName0),@AlterColumnName1,''[''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days]'')  
END  
SET @Count = @Count - 1;  
SET @Serial = @Serial + 1;  
END  
END  
ELSE  
BEGIN  
SET @AlterColumnName0 = (SELECT ID FROM #TempID WHERE IdentID = 1)  
SET @Query = ''ALTER TABLE #TempTable1 ADD [0-''+@AlterColumnName0+'' Days] VARCHAR(100) NULL,[>''+@AlterColumnName0+'' Days] VARCHAR(100) NULL''  
EXEC(@Query)  
INSERT INTO #TempAlterColumns VALUES (0,@AlterColumnName0,''[0-''+@AlterColumnName0+'' Days]'')  
INSERT INTO #TempAlterColumns VALUES (@AlterColumnName0,0,''[>''+@AlterColumnName0+'' Days]'')  
END  
SET @MainCount = (SELECT COUNT(*) FROM #TempTable1);  
SET @MainSerial = 1  
-- Looping for Get Ageing Information from #TempTable1  
WHILE (@MainCount > 0)  
BEGIN  
SET @Ageing = (SELECT Ageing FROM #TempTable1 WHERE ID = @MainSerial)  
SET @nCount = (SELECT COUNT(*) FROM #TempAlterColumns)  
SET @nCount1 = (SELECT COUNT(*) FROM #TempAlterColumns)  
SET @nSerial = 1  
-- Looping for Check Ageing and From and To Between Ageing Range  
WHILE (@nCount > 0)  
BEGIN  
SET @nF = (SELECT [From] FROM #TempAlterColumns WHERE IdentID = @nSerial)  
SET @nT = (SELECT [to] FROM #TempAlterColumns WHERE IdentID = @nSerial)  
SET @nColumnName = (SELECT OriginalColumn FROM #TempAlterColumns WHERE IdentID = @nSerial)  
IF ISNULL(@nCount1,0) = ISNULL(@nSerial,0)  
BEGIN  
SELECT @IsTrueFalse = (CASE WHEN @Ageing > @nF THEN ''TRUE'' ELSE ''FALSE'' END)  
END  
ELSE  
BEGIN  
SELECT @IsTrueFalse = (CASE WHEN @Ageing BETWEEN @nF AND @nT THEN ''TRUE'' ELSE ''FALSE'' END)  
END  
  
-- IF TRUE Updating Pending Amount to Specific Columns  
IF ISNULL(@IsTrueFalse,'''')=''TRUE''  
BEGIN  
SET @Query = ''UPDATE #TempTable1 SET ''+@nColumnName+'' = (CASE WHEN DocPrefix = 16 then [SR Balance] ELSE [Balance] END) WHERE ID=''+CAST(@MainSerial AS NVARCHAR)+''''  
EXEC (@Query)  
BREAK;  
END  
  
SET @nCount = @nCount - 1;  
SET @nSerial = @nSerial + 1;  
END  
SET @MainCount = @MainCount - 1;  
SET @MainSerial = @MainSerial + 1;  
END  
  
declare @Name varchar(max)  
Select @Name = Coalesce(@Name + '','', '''') + ''dbo.fnGetRoundedValue(SUM(CONVERT(DECIMAL(25,4), ISNULL(['' + Ltrim(name) + ''],0)))) AS '' + ''['' + Ltrim(name) + '']''  
from tempdb.sys.columns  
where object_id = object_id(''tempdb..#TempTable1'') and name not in (''ID'',''CustomerID'',''Customer Name'',''Ageing'',  
''DocPrefix'',''SR Balance'',''Net Amt'',''Balance'') --  
ORDER BY column_id  
--SELECT @Name  
  
-- Select all data from #TempTable1 Finally  
--alter table #TempTable1 drop column ID  
--alter table #TempTable1 drop column DocPrefix  
--SELECT * FROM #TempTable1  
set @Query = ''SELECT CustomerID,[Customer Name],''+@Name +'',  
dbo.fnGetRoundedValue(SUM(CONVERT(DECIMAL(25,4), ISNULL(Balance - ABS([SR Balance]),0))))[Net Balance],  
dbo.fnGetRoundedValue(SUM(CONVERT(DECIMAL(25,4), ISNULL([Net Amt],0))))[Net Amt],  
dbo.fnGetRoundedValue(SUM(CONVERT(DECIMAL(25,4), ISNULL(Balance,0)))) Balance,  
dbo.fnGetRoundedValue(SUM(CONVERT(DECIMAL(25,4), ISNULL(ABS([SR Balance]),0)))) [Payable] FROM #TempTable1 GROUP BY CustomerID,[Customer Name] ORDER BY [Customer Name]''  
EXEC(@Query)  
-- Drop all #Temp Tables  
DROP TABLE #TempTable1,#TempTable,#TempID,#COLTEMP,#JVTEMP ,#TempAlterColumns,#TEMPDATA  
END  
ELSE IF(@Mode = 3)  
BEGIN  
select DocID,DocDate,NetAmt,OSAmt,Ageing from (  
SELECT CASE WHEN DocPrefix = 15 THEN 1 ELSE 2 END SerialNo,DocID,FORMAT(InvDate,''dd/MMM/yyyy'') DocDate,NetAmt,  
CASE WHEN DocPrefix = 15 THEN Balance ELSE Balance *-1 END OSAmt,  
DATEDIFF(DD,InvDate,GETDATE()) Ageing  
FROM tblTranSalesHeader WHERE Status NOT IN (2,4) AND CustID = @BeatName AND Balance > 0  
UNION ALL  
SELECT 3 SerialNo,DocID,FORMAT(DocDate,''dd/MMM/yyyy'') DocDate,NetAmount NetAmt,Balance OSAmt,  
(DATEDIFF(DD,ISNULL((select MIN(Date) from tblTranChequeDeposit CHQD  
JOIN tblTranCollectionDetail CH ON CH.ColID = CHQD.CollId  
where ChargesVoucherId = PV.ID OR ChaqueVoucherId = PV.ID),DocDate),GETDATE())) Ageing  
FROM tblTranPRVoucher PV  
JOIN tblMasterCustomer MC ON MC.FAID = PV.PartyID  
WHERE TransID = 7 AND Status NOT IN (2,4) AND MC.ID = @BeatName AND Balance > 0  
UNION ALL  
SELECT 4 SerialNo,DocID,FORMAT(DocDate,''dd/MMM/yyyy'') DocDate,NoteValue NetAmt,Balance *-1 OSAmt,  
DATEDIFF(DD,DocDate,GETDATE()) Ageing  
FROM tblNoteDetails PV  
JOIN tblMasterCustomer MC ON MC.FAID = PV.PartyID  
WHERE TransID = 4 AND Status NOT IN (2,4) AND MC.ID = @BeatName AND Balance > 0  
UNION ALL  
SELECT 5 SerialNo,DocID,FORMAT(ColDate,''dd/MMM/yyyy'') DocDate,ColAmt NetAmt,Balance *-1 OSAmt,  
DATEDIFF(DD,ColDate,GETDATE()) Ageing  
FROM tblTranCollectionHeader PV  
JOIN tblMasterCustomer MC ON MC.FAID = PV.AccID  
WHERE DocPrefix = 19 AND Status NOT IN (2,4) AND MC.ID = @BeatName AND Balance > 0  
) as rec  
order by SerialNo,Ageing desc  
  
SELECT CD.DocPrefix,CD.DocId [Doc ID],CONVERT(NVARCHAR,CPM.[DATE],103) AS [Cheque Date],[Cheque/DD Number],  
(dbo.fnGetRoundedValue(CollAmt)) [Value]  
FROM tblCollPMDetails CPM  
JOIN tblTranCollectionHeader CD ON CD.ColID = CPM.ColID  
JOIN tblMasterCustomer MC ON MC.FAID = CD.AccID  
WHERE (CPM.[DATE] <= convert(date,getdate())) AND CPM .[Status] IN (1,3) AND CPM.PaymentTermID IN (2) AND MC.ID = @BeatName  
END  
END',
N'[export] nocount';
GO
/****** uspMobileDACollSRFilterdata ******/
EXEC #Apply07 N'dbo.uspMobileDACollSRFilterdata', 0x1A452D3C55A243B9785BDE3510E869EDC39F846C921FC24956E0F707BABD31EA, NULL, NULL, 0xB474DADB644F74E986D36BF1A30250FB55E7FCB3029FC0D030E8F63FBF558D87, 0x09748C8E0895A2B6BB8629AD2C2DDF38B7C0DF8F1D5066ED3753823E122A6202, NULL,
N'ALTER proc [dbo].[uspMobileDACollSRFilterdata]
@TransactionID int = 2,@UserID int = 2,@FromDate date = ''2026-08-01'',@ToDate date = ''2026-08-30'',@Showall int = 0,
@TransType INT
as
SET NOCOUNT ON;
begin
DECLARE @sts as table(StatusID int)              
if(isnull(@Showall,0) = 0)              
begin              
insert into @sts values(1),(3)              
end              
ELSE              
BEGIN              
insert into @sts values(1),(2),(3),(4),(8)              
END  
IF(@TransactionID = 1)--Daily Activity
BEGIN
SELECT OCH.ID,FORMAT(OCH.DocDate,''dd-MMM-yyyy'') DocDate,MB.Name BeatName,MS.Name SalesmanName,MC.Name CustomerName,                  
dbo.fnGetRoundedValue(SUM(OCD.Amount)) Value,count(*) ItemsCount,MBO.Name BranchName,sts.Description Status,OCH.Status StatusID,                  
OCH.Narration,CU.UserName,CONVERT(NVARCHAR(50),OCH.CDate) CreateDate,            
case when ActivityID = 1 then ''Order Taken'' when ActivityID = 2  then ''Feedback'' else ''No Order'' end Activity,            
FeedBack            
FROM tblTranOrderTakenHeader OCH                  
LEFT join tblTranOrderTakenDetail OCD ON OCD.ID = OCH.ID            
JOIN tblMasterCustomer MC ON MC.ID = OCH.CustID                  
LEFT JOIN TBLMasterBeat MB ON MB.ID = OCH.BeatID          
LEFT JOIN tblMasterSalesman MS ON MS.ID = OCH.SalesManID                        
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = OCH.BranchID                  
join tblStatus sts ON sts.ID = OCH.Status                  
JOIN tblUsers CU ON CU.ID = OCH.CBy              
WHERE DocDate between @FromDate and @ToDate and OCH.Status IN (SELECT StatusID FROM @sts) and
(OCH.CBy = (case when @UserID = 0 then OCH.CBy ELSE @UserID END) OR
OCH.MBy = (case when @UserID = 0 then OCH.MBy ELSE @UserID END))
GROUP BY OCH.ID,OCH.DocDate,MB.Name,MS.Name,MC.Name,MBO.Name,sts.Description,OCH.Status,OCH.Narration,CU.UserName,OCH.CDate,            
ActivityID,FeedBack            
ORDER BY OCH.DocDate DESC,OCH.ID desc  
END
ELSE IF(@TransactionID = 2)--Collection
BEGIN
SELECT OCH.ID,FORMAT(OCH.DocDate,''dd-MMM-yyyy'') DocDate,MB.Name BeatName,MS.Name SalesmanName,MC.Name CustomerName,        
dbo.fnGetRoundedValue(Amt) CollectionValue,PM.PaymentMode,MBO.Name BranchName,sts.Description Status,OCH.Status StatusID,        
OCH.Remarks,OCH.Narration,CU.UserName,CONVERT(NVARCHAR(50),OCH.CDate) CreateDate        
FROM tblTranOrderCollectionHeader OCH        
JOIN tblMasterCustomer MC ON MC.ID = OCH.CustID        
LEFT JOIN TBLMasterBeat MB ON MB.ID = OCH.BeatID        
LEFT JOIN tblMasterSalesman MS ON MS.ID = OCH.SalesManID        
JOIN tblPaymentMode PM ON PM.ID = OCH.PaymentID        
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = OCH.BranchID        
join tblStatus sts ON sts.ID = OCH.Status        
JOIN tblUsers CU ON CU.ID = OCH.CBy    
WHERE DocDate between @FromDate and @ToDate and OCH.Status IN (SELECT StatusID FROM @sts) and
(OCH.CBy = (case when @UserID = 0 then OCH.CBy ELSE @UserID END) OR
OCH.MBy = (case when @UserID = 0 then OCH.MBy ELSE @UserID END))
ORDER BY OCH.DocDate DESC,OCH.ID desc  
END
ELSE IF(@TransactionID = 3)--SR,DR
BEGIN
SELECT OCH.ID,FORMAT(OCH.DocDate,''dd-MMM-yyyy'') DocDate,MB.Name BeatName,MS.Name SalesmanName,MC.Name CustomerName,                
dbo.fnGetRoundedValue(SUM(OCD.Amount)) Value,count(*) ItemsCount,MBO.Name BranchName,sts.Description Status,OCH.Status StatusID,                
OCH.Narration,CU.UserName,CONVERT(NVARCHAR(50),OCH.CDate) CreateDate      
FROM tblTranOrderReturnHeader OCH                
LEFT join tblTranOrderReturnDetail OCD ON OCD.ID = OCH.ID          
JOIN tblMasterCustomer MC ON MC.ID = OCH.CustID                
LEFT JOIN TBLMasterBeat MB ON MB.ID = OCH.BeatID        
LEFT JOIN tblMasterSalesman MS ON MS.ID = OCH.SalesManID                      
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = OCH.BranchID                
join tblStatus sts ON sts.ID = OCH.Status                
JOIN tblUsers CU ON CU.ID = OCH.CBy            
WHERE ReturnTransType = @TransType
and DocDate between @FromDate and @ToDate and OCH.Status IN (SELECT StatusID FROM @sts) and
(OCH.CBy = (case when @UserID = 0 then OCH.CBy ELSE @UserID END) OR
OCH.MBy = (case when @UserID = 0 then OCH.MBy ELSE @UserID END))
GROUP BY OCH.ID,OCH.DocDate,MB.Name,MS.Name,MC.Name,MBO.Name,sts.Description,OCH.Status,OCH.Narration,CU.UserName,OCH.CDate         
ORDER BY OCH.ID desc 
END
end',
N'[export] nocount';
GO
/****** uspMobileDeviceSaveLoginInfo ******/
EXEC #Apply07 N'dbo.uspMobileDeviceSaveLoginInfo', 0x7ACB139D29616DE9D9F45DB95BF2D8FFF5DB6E844A3855C45DF921CAE61880D2, NULL, NULL, 0x5F446D5747B36D0FBB13257DB3CEA566C1200428CA50E50332BCFB871DB3A463, 0x4822C4502DA5580A386B4B3FB17197BF95E62E7536BAD5617B0ADEB2A0364D70, NULL,
N'ALTER proc [dbo].[uspMobileDeviceSaveLoginInfo]          
@LoginMode SMALLINT,@IPAddress nvarchar(50) = null,@DeviceName nvarchar(255) = null,          
@TokenValue nvarchar(max) = null,@SessionStatus int,@UserID smallint = null,          
@DatabaseName NVARCHAR(50) = null,@DeviceID SMALLINT        
as          
SET NOCOUNT ON;
begin          
if(@LoginMode = 1)          
begin          
update tblMobileLogin set LogoutTime = getdate(),SessionStatus = 0 where UserID = @UserID AND DeviceID = @DeviceID  AND SessionStatus = 1 
  
insert into tblMobileLogin(LoginTime,IPAddress,DeviceName,TokenValue,ConnectionString,USERID,DataBaseName,SessionStatus,DeviceID) VALUES          
(getdate(),@IPAddress,@DeviceName,@TokenValue,null,@UserID,@DatabaseName,@SessionStatus,@DeviceID)          
SELECT SCOPE_IDENTITY()          
end          
else if(@LoginMode = 2)           
begin          
update tblMobileLogin set LogoutTime = getdate(),SessionStatus = 0 where TokenValue = @TokenValue         
select @TokenValue      
end      
else if(@LoginMode = 3)           
begin          
update tblMobileLogin set LogoutTime = getdate(),SessionStatus = 0 where UserID = @UserID AND DeviceID = @DeviceID AND SessionStatus = 1         
select @DeviceID      
end 
end',
N'[export] nocount';
GO
/****** uspMobileSpotinvoicesreport ******/
EXEC #Apply07 N'dbo.uspMobileSpotinvoicesreport', 0x8151AE89FF15EFE6961D9AAC5011C8067EEE1CA628EF00ED68BA8807982A2E0B, NULL, NULL, 0xEFC57ED6C4951AA24D96EE85F982E738F051F34BCE96DB8C34F9CE04D9F0DC73, 0x34B2FDE46116BC15671A439DCAC1E5C440E0A5512DB7DAB224862E57D3B4490D, NULL,
N'--uspMobileSpotinvoicesreport 2,1016,''2026-07-27''  
ALTER PROC [dbo].[uspMobileSpotinvoicesreport]  
@Mode int, @SalesmanID int = 0,@Date date = NULL  
AS  
SET NOCOUNT ON;
IF(@Mode = 1)  
BEGIN  
select SH.ID,SH.DocID,format(SH.InvDate,''dd/MMM/yyyy'') DocDate,MB.Name Beat,SM.Name Salesman,MC.Name Customer,  
mc.Mob1,SH.NetAmt,SUM(SD.UomQty) TotalQty,  
count(SD.ProdID) ItemCount  
from tbltransalesheader SH  
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID  
JOIN tblMasterSalesman SM ON SM.ID = SH.SalesManID  
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID  
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID  
where SH.InvDate = @Date and SH.SalesManID = @SalesmanID and DocPrefix = 15 and Status IN (1,3,5) AND SD.TaxID > 0  
group by SH.ID,SH.DocID,SH.InvDate,MB.Name,SM.Name,MC.Name,SH.NetAmt,mc.Mob1  
END  
ELSE IF(@Mode = 2)  
BEGIN  
select SD.InvID ID,MP.Code,MP.Name,MP.HSNCode,SD.DetailMRP MRP,SD.UomQty from tblTranSalesDetail SD   
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID AND SD.TaxID > 0  
WHERE SD.InvID = @SalesmanID  
ORDER BY  convert(int,isnull(weborder ,''0'')), Name  
END',
N'[export] nocount';
GO
/****** uspMobileTransPrintFilter ******/
EXEC #Apply07 N'dbo.uspMobileTransPrintFilter', 0x08C71E9247EF83616513DF6B5E119C59FDBE5CF96FA5B5D3537BB2755327D749, NULL, NULL, 0x10B0C05CEE1BE8C9654DBE8B33B9E55FA4F70C70401C63C3B969732CE1561297, 0xB8C7ED9266D78D5522063FBE8E82EC07ADF2AA46CB622D68C75AB16AACE3A8E8, NULL,
N'--uspMobileTransPrintFilter 19,2,''2026-01-27'' ,''2026-08-30'' 
ALTER proc [dbo].[uspMobileTransPrintFilter]
@TransID int = 4,@UserID int = 2,@FromDate date =''2026-08-27'' ,@ToDate date=''2026-08-30''
as
SET NOCOUNT ON;
begin
if(@TransID = 4 or @TransID = 5)--4 : Invoice, 5 - SR            
BEGIN   
select SH.DocId [Doc ID],
FORMAT(SH.InvDate,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name],--isnull(mb.Name,''--'') [Beat Name],isnull(sm.Name,''--'') Salesman,
dbo.fnGetRoundedValue(SH.NetAmt) NetValue,US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblTranSalesHeader SH                      
JOIN tblMasterCustomer MC ON MC.Id = SH.CustId      
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesManID
JOIN tblUsers US ON US.ID = SH.CBy
where DocPrefix = (CASE WHEN @TransID = 4 THEN 15 ELSE 16 END) AND Status NOT IN (2,4) AND InvDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.InvDate,DocValue
END
if(@TransID = 2 or @TransID = 3)--2 : Bill, 5 - PR            
BEGIN    
select SH.DocId [Doc ID],FORMAT(SH.Date,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name],
dbo.fnGetRoundedValue(SH.NetAmt) NetValue,US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblTransPurchaseHeader SH                      
JOIN tblMasterVendor MC ON MC.Id = SH.VendorID      
JOIN tblUsers US ON US.ID = SH.CBy
where TransID = (CASE WHEN @TransID = 2 THEN 1 ELSE 12 END) AND Status NOT IN (2,4) AND Date	 BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.Date,DocValue
end
if(@TransID = 23)--23 : Van Loading Slip  
BEGIN  
select SH.DocId [Doc ID],FORMAT(SH.DocDate,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name]
--,SH.RefNo RefNo,dbo.fnGetRoundedValue(SH.NetAmt) NetAmt          
from tblvanloadingslipheader SH                      
JOIN tblMastersalesman MC ON MC.Id = SH.SalesmanID
where Status NOT IN (2,4) AND DocDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.DocDate,DocValue
end
if(@TransID = 7)--Automatic Indent      
BEGIN    
select SH.DocId [Doc ID],FORMAT(SH.Date,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name],
US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblTransAutomaticIndentHeader SH                      
JOIN tblMasterVendor MC ON MC.Id = SH.VendorID      
JOIN tblUsers US ON US.ID = SH.CBy
where Status NOT IN (2,4) AND Date BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.Date,DocValue
end
if(@TransID = 1)--Purchase Order  
BEGIN    
select SH.DocId [Doc ID],FORMAT(SH.DocDate,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name],
US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblPurchaseOrderHeader SH                      
JOIN tblMasterVendor MC ON MC.Id = SH.VendorID      
JOIN tblUsers US ON US.ID = SH.CBy
where Status NOT IN (2,4) AND DocDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.DocDate,DocValue
end
if(@TransID = 9 OR @TransID = 17)--9 : Payment, 17 - Other Payment
BEGIN 
select SH.DocId [Doc ID],FORMAT(SH.PYDate,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name],
US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblTranPaymentHeader SH                      
JOIN tblMasterVendor MC ON MC.FAID = SH.AccID      
JOIN tblUsers US ON US.ID = SH.CBy
where Status NOT IN (2,4) AND PYPrefix = (CASE WHEN @TransID = 9 THEN 18 ELSE 11 END) AND 
PYDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.PYDate,DocValue
END
if(@TransID = 6)--Quotation     
BEGIN   
select SH.DocId [Doc ID],FORMAT(SH.DocDate,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name],
dbo.fnGetRoundedValue(SH.NetAmt) NetValue,US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblQuotationHeader SH                      
JOIN tblMasterCustomer MC ON MC.Id = SH.CustomerID      
JOIN tblUsers US ON US.ID = SH.CBy
where Status NOT IN (2,4) AND DocDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.DocDate,DocValue
END
if(@TransID = 8 OR @TransID = 16)--8 : Collection, 16 - Other Collection
BEGIN 
select SH.DocId [Doc ID],FORMAT(SH.ColDate,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name],
US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblTranCollectionHeader SH                      
JOIN tblMasterCustomer MC ON MC.FAID = SH.AccID      
JOIN tblUsers US ON US.ID = SH.CBy
where Status NOT IN (2,4) AND DocPrefix = (CASE WHEN @TransID = 8 THEN 19 ELSE 10 END) AND 
ColDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.ColDate,DocValue
END
if(@TransID = 10)--Assign Invoices
BEGIN  
select SH.DocId [Doc ID],FORMAT(SH.DocDate,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name]
--,SH.RefNo RefNo,dbo.fnGetRoundedValue(SH.NetAmt) NetAmt          
from tblAssignInvoicesHeader SH                      
JOIN tblMastersalesman MC ON MC.Id = SH.SalesmanID
where Status NOT IN (2,4) AND DocDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.DocDate,DocValue
end
if(@TransID = 22)--Delivery
BEGIN  
select SH.DocId [Doc ID],FORMAT(SH.DocDate,''dd/MMM/yyyy'') [Doc Date],MC.Name [Party Name]
,VH.VehicleNo
from tblDeliveryOrderHeader SH                      
JOIN tblMastersalesman MC ON MC.Id = SH.SalesmanID
JOIN tblMasterVehicle VH ON VH.ID = SH.VehicleID
where Status NOT IN (2,4) AND DocDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.DocDate,DocValue
end
if(@TransID = 12 OR @TransID = 13)--12 : Credit Note, 13 - Debit Note
BEGIN 
select SH.DocId [Doc ID],FORMAT(SH.DocDate,''dd/MMM/yyyy'') [Doc Date],PARTY.AccountName [Party Name],
ACC.AccountName [Account Name],dbo.fnGetRoundedValue(NoteValue) Value,US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblNoteDetails SH                      
JOIN tblFAAccount PARTY ON PARTY.FAID = SH.PartyID
JOIN tblFAAccount ACC ON ACC.FAID = SH.FAID
JOIN tblUsers US ON US.ID = SH.CBy
where Status NOT IN (2,4) AND TransID = (CASE WHEN @TransID = 12 THEN 4 ELSE 5 END) AND 
DocDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.DocDate,DocValue
END
if(@TransID = 14 OR @TransID = 15)--14 :Payable Voucher, 15 - Receivable Voucher
BEGIN 
select SH.DocId [Doc ID],FORMAT(SH.DocDate,''dd/MMM/yyyy'') [Doc Date],PARTY.AccountName [Party Name],
ACC.AccountName [Account Name],dbo.fnGetRoundedValue(NetAmount) Value,US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblTranPRVoucher SH                      
JOIN tblFAAccount PARTY ON PARTY.FAID = SH.PartyID
JOIN tblFAAccount ACC ON ACC.FAID = SH.FAID
JOIN tblUsers US ON US.ID = SH.CBy
where Status NOT IN (2,4) AND TransID = (CASE WHEN @TransID = 14 THEN 6 ELSE 7 END) AND 
DocDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.DocDate,DocValue
END
if(@TransID = 18)--Contra
BEGIN 
select SH.DocId [Doc ID],FORMAT(SH.DocDate,''dd/MMM/yyyy'') [Doc Date],PARTY.AccountName [Party Name],
ACC.AccountName [Account Name],dbo.fnGetRoundedValue(Amount) Value,US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblTranContra SH                      
JOIN tblFAAccount PARTY ON PARTY.FAID = SH.FromFAID
JOIN tblFAAccount ACC ON ACC.FAID = SH.ToFAID
JOIN tblUsers US ON US.ID = SH.CBy
where Status NOT IN (2,4) AND 
DocDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   
ORDER BY SH.DocDate,DocValue
END
if(@TransID = 19)--Journal Entry
BEGIN 
select SH.DocId [Doc ID],FORMAT(SH.DocDate,''dd/MMM/yyyy'') [Doc Date],PARTY.AccountName [Party Name],
dbo.fnGetRoundedValue(Credit) Value,US.UserName ,FORMAT(SH.CDate,''dd/MMM/yyyy hh:mm tt'') CreateTime
from tblFAJournal SH                      
JOIN tblFAAccount PARTY ON PARTY.FAID = SH.AccountID
JOIN tblUsers US ON US.ID = SH.CBy
where Status NOT IN (2,4) AND DocPrefix = 9 and
DocDate BETWEEN @FromDate AND @ToDate AND 
SH.CBy = (CASE WHEN @UserID = 0 THEN SH.CBy ELSE @UserID END)   and Credit > 0
ORDER BY SH.DocDate,DocValue
END
end',
N'[export] nocount';
GO
/****** uspMobileUserActivity ******/
EXEC #Apply07 N'dbo.uspMobileUserActivity', 0xFDD7E975E227D0F0658CD9D186AF3DDD078DF37903C81CB7C2BBD60A4D7CBD18, NULL, NULL, 0x410AC6A8F3B705A7CFE755A3B81276F99A77D31AF537264CB4E0F2984D43955A, 0x405CB6D1B2705D5766D19B5AF46AF18167D80468697AC8A0EB18783D3851815B, NULL,
N'--uspMobileUserActivity 2,'''',''2026-08-10''  
ALTER proc [dbo].[uspMobileUserActivity]  
@Mode int,@UserID nvarchar(255) = '''',@Date date = null  
as  
SET NOCOUNT ON;
begin  
if(@Mode = 1)  
BEGIN  
SELECT ID value,UserName label FROM tblUsers WHERE ID > 1 ORDER BY UserName  
END  
if(@Mode = 2)  
BEGIN  
create table #users(UserID int)  
if(isnull(@UserID,'''') != '''')  
begin  
insert into #users  
SELECT * FROM string_split(@UserID,'','')  
end  
else  
begin  
insert into #users  
SELECT ID FROM tblUsers   
end  
create table #tempDB(DBValues nvarchar(max),Name nvarchar(max),UserID int)                        
insert into #tempDB                        
select COUNT(distinct CustID),''Total Count'' as Name,CBy  from (                        
select distinct CustID,CBy from tblTranOrderTakenHeader WHERE CBy IN (SELECT * FROM #users) AND Status in (1,3,8) and DocDate = @Date                        
union          
SELECT distinct CustID,CBy  FROM tblTranOrderCollectionHeader WHERE CBy IN (SELECT * FROM #users) AND Status in (1,3,8) and DocDate = @Date                                
union          
SELECT distinct CustID,CBy FROM tblTranOrderReturnHeader WHERE CBy IN (SELECT * FROM #users) AND DocDate = @Date                      
) AS NK          
group by CBy  
insert into #tempDB                        
SELECT  CONVERT(nvarchar(max),cast(dbo.fnGetRoundedValue(isnull(OTAmt,0)) as money),1) + '' / '' + CONVERT(nvarchar(max),OTCount) OTAmt,          
strVal,CBy FROM (select COUNT(DISTINCT CustID) OTCount,SUM(price * Qty) OTAmt,''OT Amt'' strVal,CBy  from tblTranOrderTakenHeader OTH      
JOIN tblTranOrderTakenDetail OTD ON OTD.ID = OTH.ID      
WHERE Status in (1,3,8) and CBy IN (SELECT * FROM #users) AND DocDate = @Date  
group by CBy) AS BC     
  
insert into #tempDB                        
SELECT CONVERT(nvarchar(max),OTCount) OTCount,          
strVal,CBy FROM (select COUNT(DISTINCT CustID) OTCount,''Feedback'' strVal,CBy  from tblTranOrderTakenHeader OTH        
WHERE Status in (1,3,8) and ActivityID = 2 and CBy IN (SELECT * FROM #users) AND DocDate = @Date  
group by CBy) AS BC     
  
insert into #tempDB                        
SELECT CONVERT(nvarchar(max),OTCount) OTCount,          
strVal,CBy FROM (select COUNT(DISTINCT CustID) OTCount,''NoOrders'' strVal,CBy  from tblTranOrderTakenHeader OTH       
WHERE Status in (1,3,8) and ActivityID = 3 and CBy IN (SELECT * FROM #users) AND DocDate = @Date  
group by CBy) AS BC     
  
insert into #tempDB                        
SELECT  CONVERT(nvarchar(max),cast(dbo.fnGetRoundedValue(isnull(SRAmt,0)) as money),1) + '' / '' + CONVERT(nvarchar(max),SRCount) OTAmt,          
strVal,CBy FROM (select  COUNT(DISTINCT CustID) SRCount,SUM(Amount) SRAmt,''SR Amt'' strVal,CBy  from tblTranOrderReturnHeader OTH      
JOIN tblTranOrderReturnDetail OTD ON OTD.ID = OTH.ID      
WHERE Status in (1,3,8) and CBy IN (SELECT * FROM #users) AND DocDate = @Date  
GROUP BY CBy  
) AS BC  

insert into #tempDB                        
SELECT  CONVERT(nvarchar(max),cast(dbo.fnGetRoundedValue(isnull(NetAmt,0)) as money),1) + '' / '' + CONVERT(nvarchar(max),SalesCount) OTAmt,          
strVal,CBy FROM (select  COUNT(DISTINCT CustID) SalesCount,SUM(OTH.NetAmt) NetAmt,''Sales'' strVal,CBy  
from tblTranSalesHeader OTH      
JOIN tblTranSalesDetail OTD ON OTD.InvID = OTH.ID      
WHERE Status in (1,3,8) and CBy IN (SELECT * FROM #users) AND InvDate = @Date  
GROUP BY CBy  
) AS BC  

insert into #tempDB                        
SELECT isnull(CONVERT(nvarchar(max),cast(dbo.fnGetRoundedValue(SUM(Amt))as money),1)+ '' / '' + CONVERT(nvarchar(max),COUNT(DISTINCT CustID)) ,0) ,  
''Total Collection'' CollAmt,CBy       
FROM tblTranOrderCollectionHeader WHERE CBy IN (SELECT * FROM #users) AND Status in (1,3,8) and DocDate = @Date     
GROUP BY CBy  
  
insert into #tempDB                        
SELECT  isnull(CONVERT(nvarchar(max),cast(dbo.fnGetRoundedValue(SUM(Amt)) as money),1),0) ,PM.PaymentMode  PaymentMode,CBy       
FROM tblTranOrderCollectionHeader CH  
JOIN tblPaymentMode PM ON PM.ID = CH.PaymentID  
WHERE CBy IN (SELECT * FROM #users) AND DocDate = @Date and Status in (1,3,8)  
GROUP BY PM.PaymentMode,CBy  
  
insert into #tempDB                        
select format(CDate,''hh:mm tt'') fstdate,Hint,CBy  from (                        
select (isnull(CDate,GETDATE())) CDate,''Start Time'' Hint,CBy from tblTranOrderTakenHeader WHERE CBy IN (SELECT * FROM #users) AND  
Status in (1,3,8) and DocDate = @Date                        
union                        
SELECT (isnull(CDate,GETDATE())) CDate,''Start Time'' Hint,CBy FROM tblTranOrderCollectionHeader WHERE CBy IN (SELECT * FROM #users)   
AND Status in (1,3,8) and DocDate = @Date                                   
union                        
SELECT (isnull(CDate,GETDATE())) CDate,''Start Time'' Hint,CBy FROM tblTranOrderReturnHeader WHERE CBy IN (SELECT * FROM #users)   
AND DocDate = @Date      
) AS NK                        
order by CDate asc                  
insert into #tempDB                        
select format(CDate,''hh:mm tt'') fstdate,Hint,CBy  from (                        
select (isnull(CDate,GETDATE())) CDate,''End Time'' Hint,CBy from tblTranOrderTakenHeader WHERE CBy IN (SELECT * FROM #users) AND Status in (1,3,8) and DocDate = @Date                        
union                        
SELECT (isnull(CDate,GETDATE())) CDate,''End Time'' Hint,CBy FROM tblTranOrderCollectionHeader WHERE CBy IN (SELECT * FROM #users) AND Status in (1,3,8) and DocDate = @Date                                     
union                        
SELECT (isnull(CDate,GETDATE())) CDate,''End Time'' Hint,CBy FROM tblTranOrderReturnHeader WHERE CBy IN (SELECT * FROM #users) AND DocDate = @Date                      
) AS NK                        
order by CDate desc                     
--select * from #tempDB                        
SELECT TD.UserID,UR.UserName,  
    MAX(CASE WHEN Name = ''Total Count'' THEN ISNULL(DBValues,0) END) AS [TotalCount],  
    MAX(CASE WHEN Name = ''OT Amt'' THEN ISNULL(DBValues,''0.00 / 0'') END) AS [OTAmt],  
    MAX(CASE WHEN Name = ''NoOrders'' THEN ISNULL(DBValues,''0'') END) AS NoOrders,  
    MAX(CASE WHEN Name = ''Feedback'' THEN ISNULL(DBValues,0) END) AS [Feedback],  
    MAX(CASE WHEN Name = ''SR Amt'' THEN DBValues END) AS [SRAmt],  
    MAX(CASE WHEN Name = ''Sales'' THEN DBValues END) AS [Sales],  
    MAX(CASE WHEN Name = ''Total Collection'' THEN DBValues END) AS [TotalCollection],  
    MAX(CASE WHEN Name = ''Cash'' THEN DBValues END) AS [Cash],  
    MAX(CASE WHEN Name = ''Cheque'' THEN DBValues END) AS [Cheque],  
    MAX(CASE WHEN Name = ''BANK TRANSFER'' THEN DBValues END) AS [BankTransfer],  
    MAX(CASE WHEN Name = ''Start Time'' THEN DBValues END) AS [StartTime],  
    MAX(CASE WHEN Name = ''End Time'' THEN DBValues END) AS [EndTime]  
FROM #tempDB TD  
JOIN tblUsers UR ON UR.ID = TD.UserID  
GROUP BY TD.UserID,UR.UserName  
drop table #tempDB,#users  
  
end  
end',
N'[export] nocount';
GO
/****** uspMobileVLSReport ******/
EXEC #Apply07 N'dbo.uspMobileVLSReport', 0x2FFFF2ABEB12BBED3F1900267B896075E9D766EB934718DDF92EA1DE91E3DEC2, NULL, NULL, 0x25784648D7A423FD4A5800853568853295A0B7A4E675800276FA6C3C10213E14, 0x58B7E31327B60D498065040834D66DC6CBEAB7FBB5D769D88222B0913F294059, NULL,
N'--[uspMobileVLSReport] 1,16
ALTER proc [dbo].[uspMobileVLSReport]              
 @BranchID int = 4,@SalesmanID int = 17              
 AS              
 SET NOCOUNT ON;
BEGIN              
declare @Today date = getdate()              
/*  OLD  
--GET PREVIOUS SALES    
SELECT ProdID,sum(PreviousSoldQty) PreviousSoldQty,0 TotalQty,0 TodaySoldQty,0 TodayVLS,MRP INTO #PreviousSales FROM (    
select SD.ProdID,SUM(SD.UomQty) * -1 PreviousSoldQty,PV.MRPONPrice MRP from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
join tblVanLoadingSlipHeader VH ON VH.ID = SD.VLSID    
join tblProductInventory PV ON PV.InventoryId = SD.InventoryID    
WHERE SH.VLSID in (1) AND SH.BranchID = @BranchID AND SH.SalesManID = @SalesmanID and VH.Docdate < @Today    
AND SH.InvDate < @Today and SD.TaxID > 0    
GROUP BY SD.ProdID,PV.MRPONPrice    
UNION ALL    
select VD.ProdID,SUM(UomQty) PreviousVLSABSQty,PV.MRPONPrice    
from tblVanLoadingSlipHeader VH    
JOIN tblVanLoadingSlipDetail VD ON VD.ID = VH.ID    
JOIN tblMasterProduct MP ON MP.ID = VD.ProdID    
join tblProductInventory PV ON PV.InventoryId = VD.InventoryID    
WHERE VH.BranchID = @BranchID AND VH.SalesmanID = @SalesmanID and VH.Docdate < @Today    
GROUP BY VD.ProdID,PV.MRPONPrice) AS PVDATA    
GROUP BY ProdID,MRP    
--select * from #PreviousSales    
    
    
SELECT ProdID,TotalQty,SUM(TodaySoldQty) TodaySoldQty,PreviousSoldQty,TodayVLS,MRP INTO #TodaySales FROM (    
select SD.ProdID,0 TotalQty,(SD.UomQty - ISNULL(VD.VLSRetrunQty,0)) TodaySoldQty,0 PreviousSoldQty,    
0 TodayVLS,PV.MRPONPrice MRP from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
join tblVanLoadingSlipDetail VD ON VD.ID = SD.VLSID    
join tblProductInventory PV ON PV.InventoryId = SD.InventoryID    
WHERE SH.VLSID = 1 AND SH.BranchID = @BranchID AND SH.SalesManID = @SalesmanID and SH.InvDate = @Today    
and SD.TaxID > 0    
GROUP BY SD.InvID,SD.ProdID,PV.MRPONPrice,SD.UomQty,VD.VLSRetrunQty--,VD.MRP    
) AS REC    
GROUP BY ProdID,TotalQty,PreviousSoldQty,TodayVLS,MRP    
    
--GET TODAY VLS QTY    
select VD.ProdID,0 TotalQty,0 TodaySoldQty,0 PreviousSoldQty,SUM(UomQty) TodayVLS,PV.MRPONPrice MRP into #TodayVLS    
from tblVanLoadingSlipHeader VH    
JOIN tblVanLoadingSlipDetail VD ON VD.ID = VH.ID    
JOIN tblMasterProduct MP ON MP.ID = VD.ProdID    
join tblProductInventory PV ON PV.InventoryId = VD.InventoryID    
WHERE VH.Status not in (4) AND VH.BranchID = @BranchID AND VH.SalesmanID = @SalesmanID and VH.Docdate = @Today    
GROUP BY VD.ProdID,PV.MRPONPrice    
    
--GET OVERALL VLS    
select VD.ProdID,SUM(UomQty - ISNULL(VD.VLSRetrunQty,0)) TotalQty,0 TodaySoldQty,0 PreviousSoldQty,    
0 TodayVLS,PV.MRPONPrice MRP into #Overall    
from tblVanLoadingSlipHeader VH    
JOIN tblVanLoadingSlipDetail VD ON VD.ID = VH.ID    
JOIN tblMasterProduct MP ON MP.ID = VD.ProdID    
join tblProductInventory PV ON PV.InventoryId = VD.InventoryID    
WHERE VH.Status not in (4) AND VH.BranchID = @BranchID AND VH.SalesmanID = @SalesmanID    
GROUP BY VD.ProdID,PV.MRPONPrice    
    
--MERGE ALL DATA    
SELECT ProdID,MP.Code ProductCode,MP.Name ProductName,sum(PreviousSoldQty) PreviousSoldQty,SUM(TodayVLS) TodayVLS,    
sum(TodaySoldQty) TodaySoldQty, SUM(PreviousSoldQty - TodaySoldQty + TodayVLS) AvailVLSQty,NK.MRP,IMG.Imagedata,weborder FROM (    
select ProdID,sum(TotalQty) TotalQty,sum(TodaySoldQty) TodaySoldQty,sum(PreviousSoldQty) PreviousSoldQty    
,sum(TodayVLS) TodayVLS,MRP from #PreviousSales    
GROUP BY ProdID,MRP    
union all    
select ProdID,sum(TotalQty) TotalQty,sum(TodaySoldQty) TodaySoldQty,sum(PreviousSoldQty) PreviousSoldQty    
,sum(TodayVLS) TodayVLS,MRP from #TodaySales    
GROUP BY ProdID,MRP    
union all    
select ProdID,sum(TotalQty) TotalQty,sum(TodaySoldQty) TodaySoldQty,sum(PreviousSoldQty) PreviousSoldQty    
,sum(TodayVLS) TodayVLS,MRP from #TodayVLS    
GROUP BY ProdID,MRP    
union all    
select ProdID,sum(TotalQty) TotalQty,sum(TodaySoldQty) TodaySoldQty,sum(PreviousSoldQty) PreviousSoldQty    
,sum(TodayVLS) TodayVLS,MRP from #Overall    
GROUP BY ProdID,MRP) AS NK    
JOIN tblMasterProduct MP ON MP.ID = NK.ProdID    
LEFT JOIN tblImages IMG ON IMG.ID = NK.ProdID AND IMG.FormID = 1    
GROUP BY ProdID,NK.MRP,MP.Code,MP.Name,IMG.Imagedata,weborder    
HAVING (sum(PreviousSoldQty)+SUM(TodayVLS)+sum(TodaySoldQty)+SUM(PreviousSoldQty - TodaySoldQty + TodayVLS)) > 0    
ORDER BY convert(int,isnull(weborder ,''0'')), Name    
drop table #TodaySales,#Overall,#PreviousSales,#TodayVLS    
*/  
  
  
SELECT ProdID,MRP,SUM(TodaySoldPrevVLSQty) PreviousClosing INTO #PreviousSales FROM (  
SELECT ProdID,MRP,SUM(TodaySoldQty) TodaySoldPrevVLSQty FROM (    
select SD.ProdID,(SD.AdjustQty - ISNULL(VD.VLSRetrunQty,0)) TodaySoldQty,PV.MRPONPrice MRP from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
join tblVanLoadingSlipDetail VD ON VD.ID = SD.VLSID    
join tblProductInventory PV ON PV.InventoryId = SD.InventoryID    
WHERE SH.VLSID = 1 AND SH.BranchID = @BranchID AND SH.SalesManID = @SalesmanID and SH.InvDate =@Today  
AND SD.VLSID IN (select VH.ID  
from tblVanLoadingSlipHeader VH    
JOIN tblVanLoadingSlipDetail VD ON VD.ID = VH.ID    
WHERE VH.BranchID = @BranchID AND VH.SalesmanID = @SalesmanID and VH.Docdate < @Today  
)  
GROUP BY SD.InvID,SD.ProdID,PV.MRPONPrice,SD.AdjustQty,VD.VLSRetrunQty--,VD.MRP    
) AS REC    
GROUP BY ProdID,MRP    
UNION ALL  
select VD.ProdID,PV.MRPONPrice,  
sum(CONVERT(DECIMAL(15,2),UomQty - (ISNULL(VLSMQty,0) + ISNULL(VD.VLSRetrunQty,0)))) AvlVLS    
from tblVanLoadingSlipHeader VH    
JOIN tblVanLoadingSlipDetail VD ON VD.ID = VH.ID    
JOIN tblMasterProduct MP ON MP.ID = VD.ProdID    
join tblProductInventory PV ON PV.InventoryId = VD.InventoryID    
WHERE VH.BranchID = @BranchID AND VH.SalesmanID = @SalesmanID and VH.Docdate <@Today  
GROUP BY VD.ProdID,PV.MRPONPrice) AS PREVIOUSCLOSING  
GROUP BY ProdID,MRP  
  
SELECT ProdID,MRP,SUM(TodaySoldQty) TodaySoldQty INTO #TodaySales  FROM (    
select SD.ProdID,(SD.UomQty - ISNULL(VD.VLSRetrunQty,0)) TodaySoldQty,PV.MRPONPrice MRP from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
join tblVanLoadingSlipDetail VD ON VD.ID = SD.VLSID    
join tblProductInventory PV ON PV.InventoryId = SD.InventoryID    
WHERE SH.VLSID = 1 AND SH.BranchID = @BranchID AND SH.SalesManID = @SalesmanID and SH.InvDate = @Today  
and SD.TaxID > 0    
GROUP BY SD.InvID,SD.ProdID,PV.MRPONPrice,SD.UomQty,VD.VLSRetrunQty--,VD.MRP    
) AS REC    
GROUP BY ProdID,MRP    
  
select VD.ProdID,PV.MRPONPrice MRP,SUM(UomQty) TodayVLS   into #TodayVLS   
from tblVanLoadingSlipHeader VH    
JOIN tblVanLoadingSlipDetail VD ON VD.ID = VH.ID    
JOIN tblMasterProduct MP ON MP.ID = VD.ProdID    
join tblProductInventory PV ON PV.InventoryId = VD.InventoryID    
WHERE VH.Status not in (4) AND VH.BranchID = @BranchID AND VH.SalesmanID = @SalesmanID and VH.Docdate =@Today  
GROUP BY VD.ProdID,PV.MRPONPrice    
  
SELECT ProdID,MRP,sum(PreviousClosing) PreviousClosing,sum(TodaySold) TodaySold,sum(TodayVLS) TodayVLS,  
(sum(PreviousClosing) + sum(TodayVLS)) - sum(TodaySold) ABSQty  
--,sum(PreviousClosing) + (sum(TodaySold) - sum(TodayVLS)) ABSQtyOLD  
INTO #MergedData FROM (  
select ProdID,MRP,SUM(PreviousClosing) PreviousClosing,0 TodaySold,0 TodayVLS from #PreviousSales  
GROUP BY ProdID,MRP  
UNION ALL  
select ProdID,MRP,0 PreviousClosing,SUM(TodaySoldQty) TodaySold,0 TodayVLS from #TodaySales  
GROUP BY ProdID,MRP  
UNION ALL  
select ProdID,MRP,0 PreviousClosing,0 TodaySold,SUM(TodayVLS) TodayVLS from #TodayVLS  
GROUP BY ProdID,MRP) AS COMABINED  
group by ProdID,MRP  
--having (sum(PreviousClosing) + (sum(TodaySold) - sum(TodayVLS))) <> 0  
having (sum(PreviousClosing) + sum(TodayVLS)) - sum(TodaySold) > 0  
--select * from #MergedData  

select ProdID,MP.Code ProductCode,MP.Name ProductName,NK.MRP,sum(NK.PreviousClosing) PreviousSoldQty,  
sum(NK.TodaySold) TodaySoldQty,sum(NK.TodayVLS) TodayVLS,sum(NK.ABSQty) AvailVLSQty,IMG.Imagedata,weborder 
from #MergedData NK  
JOIN tblMasterProduct MP ON MP.ID = NK.ProdID    
LEFT JOIN tblImages IMG ON IMG.ID = NK.ProdID AND IMG.FormID = 1    
GROUP BY ProdID,MP.Code,MP.Name,NK.MRP,IMG.Imagedata,weborder  
ORDER BY convert(int,isnull(weborder ,''0'')), Name    
drop table #TodaySales,#PreviousSales,#TodayVLS ,#MergedData  
END',
N'[export] nocount';
GO
/****** uspMonthlyWiseSalesFooter ******/
EXEC #Apply07 N'dbo.uspMonthlyWiseSalesFooter', 0xD1741F448BF0A617857033BB37C61B373CFC524BB076C1FECBC01309BD5C61B7, 0x30B0B39AA9A22EFF1B8D183CE58E7AC0B62A4A5A6E6EA07BA884474DF8C9BC28, NULL, 0x0413D240FA5F3CDAC5DFCEF0458781FDCFE508D2DD6B3A306ED80D73FE0D0BC1, 0xF87C787C2AB12A6257B8F4A3250C244AEA81785EB712F65E69D6D4BC70B17094, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspMonthlyWiseSalesFooter]      
@MFD DATE = ''2025-08-01'',@MED DATE = ''2025-08-30'',@BranchName NVARCHAR(255) = ''0'',@BeatName NVARCHAR(255) = '''',@SalesmanName NVARCHAR(255) = '''',@CustomerName NVARCHAR(255) = '''',@CustomerType NVARCHAR(255) = '''',    
@Ratings NVARCHAR(255) = '''',@FromDate DATE = ''2025-04-01'',@ToDate DATE = ''2025-08-30''       
AS    
SET NOCOUNT ON;
BEGIN    
declare @StrQuery nvarchar(max) = ''''      
 set @StrQuery = ''     
SELECT [MMM/YYYY] ,[Trans Name],[Doc ID],format(InvDate,''''dd-MMM-yyyy'''') [Doc Date],[Reference Number] [Ref No],[Customer Name],[Customer Type],Ratings,    
[Beat Name],[Salesman Name],[Gross Amount],[Tax Amount],Charges,[Net Amount] FROM (    
SELECT CONVERT(NVARCHAR(3), UPPER(DATENAME(MONTH,TSH.InvDate))) +'''' ''''+ CAST(DATEPART(YYYY,TSH.InvDate) AS VARCHAR) AS [MMM/YYYY],    
CASE WHEN  TransactionType in(1,4,5,6) then ''''Invoice''''  WHEN  TransactionType=2 then ''''Sales Return''''  WHEN  TransactionType=3 then ''''Damage Return''''  END AS [Trans Name],    
TSH.DocId AS [Doc ID],TSH.InvDate,TSH.UDFDocId AS [UDN],TSH.DocRef AS [Reference Number],      
MC.Name AS [Customer Name],ISNULL(Beat.Name,'''''''') AS [Beat Name],ISNULL(SM.Name,'''''''') AS [Salesman Name],      
dbo.fnGetRoundedValue(CASE WHEN DocPrefix=15 then (TSH.GrossAmt) ELSE (TSH.GrossAmt)*-1  END ) AS [Gross Amount],      
dbo.fnGetRoundedValue(CASE WHEN DocPrefix=15 then (TSH.TotalTaxAmt) ELSE (TSH.TotalTaxAmt*-1)  END ) AS [Tax Amount],      
dbo.fnGetRoundedValue(ISNULL(TSH.Frieght,0) + ISNULL(TSH.OtherChargeAmt,0)) AS [Charges],      
dbo.fnGetRoundedValue(CASE WHEN DocPrefix=15 then (TSH.NetAmt) ELSE (TSH.NetAmt)*-1  END ) AS [Net Amount],MCT.Name [Customer Type],RT.RatingName Ratings    
FROM tblTranSalesHeader AS TSH      
LEFT JOIN tblMasterCustomer AS MC ON MC.ID = TSH.CustId      
LEFT JOIN tblMasterBeat AS Beat ON Beat.ID = TSH.BeatID          
LEFT JOIN tblMasterSalesMan AS SM ON SM.ID = TSH.SalesManId          
LEFT JOIN tblMasterCustomerType AS MCT ON MCT.ID = MC.CustomerType     
LEFT JOIN tblRatings AS RT ON RT.ID = MC.Rating      
WHERE TSH.Status IN (1,3,5,6,7) ''    
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @MFD  AND  @MED )'' END)                      
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BranchName,''0'')=''0'' THEN '''' ELSE '' AND TSH.BranchID =  @BranchName '' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND Beat.ID IN (SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)           
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND SM.ID IN (SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND MC.ID IN (SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND MCT.ID IN (SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RT.ID IN (SELECT * from dbo.fnSplitString(  @Ratings ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + '' ) as rec ORDER BY InvDate''    
EXEC sys.sp_executesql @StrQuery, N''@MFD DATE, @MED DATE, @BranchName NVARCHAR(255), @BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @MFD, @MED, @BranchName, @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @FromDate, @ToDate    
end',
N'[06] nocount';
GO
/****** uspMonthlyWiseSalesHeader ******/
EXEC #Apply07 N'dbo.uspMonthlyWiseSalesHeader', 0x8CD50537C4A58CA312CAB7F27FE27AC2451A3BE22C4C633D639DCAB3B740FC58, 0x76C0D86B0A4C106DEAE856E52E43725313FBF01E22DEDEC181CDCE4FB0F1FDBF, NULL, 0x305763C2A3B63C2E6E842540217967680138E665445FE3E8AB7AC239740F665E, 0x8C95CDFB85EBD91000338E8DD433AB372D3A0F7928D11753C4D55EECE2533D32, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspMonthlyWiseSalesHeader]      
@BranchName NVARCHAR(255) = ''0'',@BeatName NVARCHAR(255) = '''',@SalesmanName NVARCHAR(255) = '''',@CustomerName NVARCHAR(255) = '''',@CustomerType NVARCHAR(255) = '''',    
@Ratings NVARCHAR(255) = '''',@FromDate DATE = ''2025-04-01'',@ToDate DATE = ''2025-08-30''       
AS    
SET NOCOUNT ON;
BEGIN    
declare @StrQuery nvarchar(max) = ''''      
 set @StrQuery = ''     
SELECT [From Date],[To Date],[MMM/YYYY],dbo.fnGetRoundedValue(SUM([Sales Value]))  AS [Sales Value],      
dbo.fnGetRoundedValue(SUM([SR Saleable Value])) AS [SR Saleable Value],      
dbo.fnGetRoundedValue(SUM([SR Damage Value])) AS [SR Damage Value] FROM (    
SELECT InvDate,CONVERT(date,SRIRAM.[From Date]) AS [From Date],                
CONVERT(DATE,SRIRAM.[To Date]) AS [To Date],      
SRIRAM.[MMM/YYYY],                
SUM(isnull(SRIRAM.[Net Amount],0)) AS [Sales Value] ,            
SUM(isnull(SRIRAM.[SR Saleable Value],0)) AS [SR Saleable Value] ,            
SUM(isnull(SRIRAM.[SR Damage Value],0)) AS [SR Damage Value] --INTO #TEMP            
FROM             
(             
SELECT InvDate,      
(CASE WHEN (DATEADD(mm, DATEDIFF(mm, 0, InvDate),0)) <  @FromDate         
THEN  @FromDate  ELSE DATEADD(mm, DATEDIFF(mm, 0, InvDate),0) END) AS [From Date],      
(CASE WHEN (DATEADD (dd, -1, DATEADD(mm, DATEDIFF(mm, 0, InvDate) + 1, 0))) >  @ToDate             
 THEN  @ToDate  ELSE DATEADD(dd, -1, DATEADD(mm, DATEDIFF(mm, 0, InvDate) + 1, 0))END) AS [To Date],            
CONVERT(NVARCHAR(3), UPPER(DATENAME(MONTH,InvDate))) +'''' ''''+ CAST(DATEPART(YYYY,InvDate) AS VARCHAR) AS [MMM/YYYY],             
 (CASE WHEN DocPrefix=15 then isnull(NetAmt,0)END ) AS [Net Amount],               
CASE WHEN DocPrefix=16 AND TransactionType=2  then  (isnull(NetAmt,0))*-1 END AS [SR Saleable Value],            
CASE WHEN DocPrefix=16 AND TransactionType=3  then  (isnull(NetAmt,0))*-1 END AS [SR Damage Value]            
FROM tblTranSalesHeader TSH    
JOIN tblMasterCustomer MC ON MC.ID= TSH.CustID    
LEFT JOIN tblMasterBeat AS Beat ON Beat.ID = TSH.BeatID          
LEFT JOIN tblMasterSalesMan AS SM ON SM.ID = TSH.SalesManId          
LEFT JOIN tblMasterCustomerType AS MCT ON MCT.ID = MC.CustomerType     
LEFT JOIN tblRatings AS RT ON RT.ID = MC.Rating    
WHERE Status in(1,3,5,6,7) ''    
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)                  
  
    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BranchName,''0'')=''0'' THEN '''' ELSE '' AND TSH.BranchID =  @BranchName '' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND Beat.ID IN (SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)           
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND SM.ID IN (SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND MC.ID IN (SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND MCT.ID IN (SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RT.ID IN (SELECT * from dbo.fnSplitString(  @Ratings ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + '')  AS SRIRAM                
GROUP BY SRIRAM.InvDate,SRIRAM.[MMM/YYYY],SRIRAM.[From Date],SRIRAM.[To Date]) as main    
 GROUP BY [From Date],[To Date],[MMM/YYYY] ORDER BY CONVERT(DATETIME,[MMM/YYYY]) ''    
 EXEC sys.sp_executesql @StrQuery, N''@BranchName NVARCHAR(255), @BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BranchName, @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @FromDate, @ToDate    
 end',
N'[06] nocount';
GO
/****** uspMonthwisesalesAnalticsReport ******/
EXEC #Apply07 N'dbo.uspMonthwisesalesAnalticsReport', 0x07B657979542615FD640C0164A62E42C6972C7965C0A6F105974B3214DB0CBFC, 0x54201022D2C3F78AEB787A6DE92AD4377A9F62C70DA202999F0EA8C9D1DC13E5, NULL, 0x928CB41515C0B22DF2EBF1D9035E3AB099F0885AE636AD55759850CBA070FF6A, 0x4D68110382F9829211DD2769403F3BA4E794110EE330331A600C30EA39D7A780, NULL,
N'--uspMonthwisesalesAnalticsReport 3,5,1,'''',1,'''',1,''2026-05-28'',''2026-08-28''
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspMonthwisesalesAnalticsReport]
@Mode int = 1,@Grp1Type int = 1,@Grp2Type int = 3,@Grp2ID NVARCHAR(MAX) = '''', @Grp3Type int = 1,@Grp3ID NVARCHAR(MAX) = '''',
@Grp4Type int = 1,@FromDate date = ''2026-01-01'',@ToDate date = ''2026-05-30''
as
SET NOCOUNT ON;
begin
if(@Mode = 1)-- FOR PARTY FILTER
BEGIN
IF(@Grp1Type = 1 and @Grp2Type not in (6,7))--Beat
BEGIN
SELECT ID value,Name label FROM tblMasterBeat ORDER BY Name
END
IF(@Grp1Type = 2 and @Grp2Type not in (6,7))--Salesman
BEGIN
SELECT ID value,Name label FROM tblMasterSalesman ORDER BY Name
END
IF(@Grp1Type = 3 and @Grp2Type not in (6,7))--Customer
BEGIN
SELECT ID value,Name label FROM tblMasterCustomer ORDER BY Name
END
IF(@Grp1Type = 4 and @Grp2Type not in (6,7))--CustomerType
BEGIN
SELECT ID value,Name label FROM tblMasterCustomerType ORDER BY Name
END
IF(@Grp1Type = 1 and @Grp2Type in (6,7))--Beat
BEGIN
SELECT ID value,Name label FROM tblMasterVendor ORDER BY Name
END
END
ELSE if(@Mode = 2)-- FOR Product FILTER
BEGIN
IF(@Grp1Type = 1)--manuf
BEGIN
SELECT ID value,Name label FROM tblMasterManufacturer ORDER BY Name
END
IF(@Grp1Type = 2)--brand
BEGIN
SELECT ID value,Name label FROM tblMasterBrand ORDER BY Name
END
IF(@Grp1Type = 3)--Category
BEGIN
SELECT ID value,Name label FROM tblMasterCategory ORDER BY Name
END
IF(@Grp1Type = 4)--product
BEGIN
SELECT ID value,Name label FROM tblMasterProduct ORDER BY Name
END
END
ELSE if(@Mode = 3)--Main Data
BEGIN

declare @Group1TypeName nvarchar(100) = (case when @Grp1Type = 1 then ''[Sales Value'' when @Grp1Type = 2 then ''[SR Value'' when
@Grp1Type = 3 then ''[DR Value'' when @Grp1Type = 4 then ''[Collection'' when @Grp1Type = 5 then ''[Outstandings''
when @Grp1Type = 6 then ''[Purchase Value'' when @Grp1Type = 7 then ''[PR Value'' else ''A'' end)
declare @Group2TypeName nvarchar(100) = case when @Grp1Type in (1,2,3,4,5) then
(case when @Grp2Type = 1 then ''[Beat Name]'' when @Grp2Type = 2 then ''[Salesman Name]'' when
@Grp2Type = 3 then ''[Customer Name]'' else ''[Customer Type]'' end) else
(case when @Grp2Type = 1 then ''[Vendor Name]'' else '''' end) end

declare @Group3TypeName nvarchar(100) = (case when @Grp3Type = 1 then ''[Manuf Name]'' when @Grp3Type = 2 then ''[Brand Name]'' when
@Grp3Type = 3 then ''[Category Name]'' else ''[Product Name]'' end)
declare @Group4TypeName nvarchar(100) = (case when @Grp4Type = 1 then ''(Qty)'' when @Grp4Type = 2 then ''(Gross)'' when
@Grp4Type = 3 then ''(Net)'' else '''' end)

DECLARE @query NVARCHAR(MAX),@InitialQuery NVARCHAR(MAX), @PCol NVARCHAR(MAX),@PColWithisnull nvarchar(max),@CumativeCol nvarchar(max);

;WITH ALLMonthsCTE AS (
SELECT DATEFROMPARTS(YEAR(@FromDate), MONTH(@FromDate), 1) AS MonthStart
UNION ALL
SELECT DATEADD(MONTH, 1, MonthStart)
FROM ALLMonthsCTE
WHERE DATEADD(MONTH, 1, MonthStart) <= DATEFROMPARTS(YEAR(@Todate), MONTH(@Todate), 1)
)
SELECT @PCol = MonthList FROM (SELECT STRING_AGG(FORMAT(MonthStart, ''[MMM yyyy]''), '', '') WITHIN GROUP (ORDER BY MonthStart) AS MonthList FROM ALLMonthsCTE) AS RR

;WITH ALLMonthsCTE AS (
SELECT DATEFROMPARTS(YEAR(@FromDate), MONTH(@FromDate), 1) AS MonthStart
UNION ALL
SELECT DATEADD(MONTH, 1, MonthStart)
FROM ALLMonthsCTE
WHERE DATEADD(MONTH, 1, MonthStart) <= DATEFROMPARTS(YEAR(@Todate), MONTH(@Todate), 1)
)
SELECT @PColWithisnull = MonthList FROM (SELECT STRING_AGG(''(ISNULL(['' + FORMAT(MonthStart, ''MMM yyyy'')+ ''],0)) AS ['' + FORMAT(MonthStart, ''MMM yyyy'')+ '']'', '', '')

WITHIN GROUP (ORDER BY MonthStart) AS MonthList FROM ALLMonthsCTE) AS RR
;WITH ALLMonthsCTE AS (
SELECT DATEFROMPARTS(YEAR(@FromDate), MONTH(@FromDate), 1) AS MonthStart
UNION ALL
SELECT DATEADD(MONTH, 1, MonthStart)
FROM ALLMonthsCTE
WHERE DATEADD(MONTH, 1, MonthStart) <= DATEFROMPARTS(YEAR(@Todate), MONTH(@Todate), 1)
)
SELECT @CumativeCol = MonthList FROM (SELECT STRING_AGG(''ISNULL(''+FORMAT(MonthStart, ''[MMM yyyy]'')+'',0)'', ''+ '') WITHIN GROUP (ORDER BY MonthStart) AS MonthList FROM ALLMonthsCTE) AS RR
create table #t1(InvDate nvarchar(50),Grp1ID int,Grp1Name nvarchar(255),Grp2ID int,Grp2Name nvarchar(255),Grp3Value decimal(25,4))
IF(@Grp1Type IN (1,2,3))--SALES,SR,DR
BEGIN
set @InitialQuery = ''
SELECT InvDate,Grp1ID,Grp1Name,Grp2ID,Grp2Name,SUM(Grp3Value) Grp3Value FROM (
select UPPER(FORMAT(SH.InvDate,''''MMM yyyy'''')) InvDate''
set @InitialQuery += case when @Grp3Type = 0 then '',0 Grp1ID,null Grp1Name'' when @Grp3Type = 1 then '',MP.MfrID Grp1ID,MANUF.Name Grp1Name'' when @Grp3Type = 2 then '',MP.BrandID Grp1ID,MBR.Name Grp1Name''
when @Grp3Type = 3 then '',MP.CategoryID Grp1ID,MCAT.Name Grp1Name'' else '',MP.ID Grp1ID,MP.Name Grp1Name'' END

set @InitialQuery += case when @Grp2Type = 0 then '',0 Grp2ID,null Grp2Name'' when @Grp2Type = 1 then '',ISNULL(SH.BeatID,0) Grp2ID,MB.Name Grp2Name'' when @Grp2Type = 2 then '',ISNULL(SH.SalesmanID,0) Grp2ID,SM.Name Grp2Name''
when @Grp2Type = 3 then '',MC.ID Grp2ID,MC.Name Grp2Name'' else '',ISNULL(MCAT.ID,0) Grp2ID,MCAT.Name Grp2Name'' END

set @InitialQuery += case when @Grp4Type = 1 then '',SUM(SD.UOMQty) Grp3Value '' when @Grp4Type = 2 then '',SUM(SD.GrossAmt) Grp3Value '' else
'',SUM(SD.NetAmt) Grp3Value'' end
-- AND SH.DocPrefix = 15
set @InitialQuery += '' from tblTranSalesHeader SH
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesManID
LEFT JOIN tblMasterCustomerType MCT ON MCT.ID = MC.CustomerType
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID
JOIN tblMasterManufacturer MANUF ON MANUF.ID = MP.MfrID
JOIN tblMasterBrand MBR ON MBR.ID = MP.BrandID
JOIN tblMasterCategory MCAT ON MCAT.ID = MP.CategoryID
WHERE SH.STATUS NOT IN (2,4) AND SH.InvDate BETWEEN ''+'' @FromDate ''+'' AND ''+'' @ToDate ''+''''
-- AND ISNULL(SD.TaxId,0)>0
set @InitialQuery += case when @Grp1Type = 1 then '' and SH.DocPrefix = 15 '' when @Grp1Type = 2 then '' and SH.DocPrefix = 16 and SH.TransactionType = 2 ''
else '' and SH.DocPrefix = 16 and SH.TransactionType = 3 '' end

set @InitialQuery += (case when ISNULL(@Grp3ID,'''') = '''' or @Grp3Type = 0 then '''' else
case when @Grp3Type = 1 then '' and MP.MfrID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
when @Grp3Type = 2 then '' and MP.BrandID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
when @Grp3Type = 3 then '' and MP.CategoryID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
when @Grp3Type = 4 then '' and MP.ID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
END
END)

set @InitialQuery += (case when ISNULL(@Grp2ID,'''') = '''' or @Grp2Type = 0 then '''' else
case when @Grp2Type = 1 then '' and MB.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
when @Grp2Type = 2 then '' and SM.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
when @Grp2Type = 3 then '' and MC.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
when @Grp2Type = 4 then '' and MCT.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
END
END)

set @InitialQuery += ''GROUP BY SH.InvDate'' +(case when @Grp3Type = 0 then '''' when @Grp3Type = 1 then '',MP.MfrID,MANUF.Name'' when @Grp3Type = 2 then '',MP.BrandID,MBR.Name''
when @Grp3Type = 3 then '',MP.CategoryID,MCAT.Name'' else '',MP.ID,MP.Name'' END)

set @InitialQuery += case when @Grp2Type = 0 then '''' when @Grp2Type = 1 then '',SH.BeatID,MB.Name'' when @Grp2Type = 2 then '',SH.SalesmanID,SM.Name''
when @Grp2Type = 3 then '',MC.ID,MC.Name'' else '',MCAT.ID,MCAT.Name'' END

set @InitialQuery += '') as rec group by InvDate,Grp1ID,Grp1Name,Grp2ID,Grp2Name''--Grp1ID,Grp1Name,Grp2ID,Grp2Name''

--select @InitialQuery

insert into #t1
EXEC sys.sp_executesql @InitialQuery, N''@Mode int, @Grp1Type int, @Grp2Type int, @Grp2ID NVARCHAR(MAX), @Grp3Type int, @Grp3ID NVARCHAR(MAX), @Grp4Type int, @FromDate date, @ToDate date'', @Mode, @Grp1Type, @Grp2Type, @Grp2ID, @Grp3Type, @Grp3ID, @Grp4Type, @FromDate, @ToDate

SET @query = ''SELECT ''+
case when @Grp3Type = 0 then '''' else '' Grp1ID,'' end +
case when @Grp2Type = 0 then '''' else '' Grp2ID,'' end +
case when @Grp3Type = 0 then '''' else ''Grp1Name''+@Group3TypeName+'','' end +
case when @Grp2Type = 0 then '''' else ''Grp2Name''+@Group2TypeName+'','' end +
''(''+@CumativeCol+'') AS ''+@Group1TypeName+@Group4TypeName+''],''+@PColWithisnull+
'' FROM #t1 PIVOT (SUM(Grp3Value) FOR InvDate IN ('' + @PCol + '')) AS PivotTable 
ORDER BY ''+case when @Grp3Type = 0 then '''' else @Group3TypeName end +
case when @Grp2Type > 0 and @Grp3Type > 0 then '','' else '''' end+
case when @Grp2Type = 0 then '''' else @Group2TypeName end
EXEC sys.sp_executesql @query, N''@Mode int, @Grp1Type int, @Grp2Type int, @Grp2ID NVARCHAR(MAX), @Grp3Type int, @Grp3ID NVARCHAR(MAX), @Grp4Type int, @FromDate date, @ToDate date'', @Mode, @Grp1Type, @Grp2Type, @Grp2ID, @Grp3Type, @Grp3ID, @Grp4Type, @FromDate, @ToDate

END
ELSE IF(@Grp1Type = 4) -- COLLECTION
BEGIN
create table #t2(ColDate nvarchar(50),Grp2ID int,Grp2Name nvarchar(255),Grp3Value decimal(25,4))
set @InitialQuery = ''SELECT ColDate,Grp2ID,Grp2Name,SUM(Grp3Value) Grp3Value FROM ( SELECT UPPER(FORMAT(TSH.ColDate,''''MMM yyyy'''')) ColDate,''
set @InitialQuery += case when @Grp2Type = 1 then ''ISNULL(TSH.BeatID,0) Grp2ID,MB.Name Grp2Name,'' when @Grp2Type = 2 then ''ISNULL(TSH.SalesmanID,0) Grp2ID,MSM.Name Grp2Name,''
when @Grp2Type = 3 then ''MC.ID Grp2ID,MC.Name Grp2Name,'' else ''ISNULL(mct.ID,0) Grp2ID,mct.Name Grp2Name,'' END
set @InitialQuery +=''SUM(TSH.ColAmt) AS Grp3Value
FROM tblTranCollectionHeader AS TSH
JOIN tblMasterCustomer AS MC ON MC.FAID = TSH.AccID
left join tblMasterCustomerType as mct on mct.ID=MC.CustomerType
LEFT JOIN tblMasterBeat AS MB ON MB.ID = TSH.BeatID
LEFT JOIN tblMasterSalesMan AS MSM ON MSM.ID = TSH.SalesManId
WHERE TSH.DocPrefix= 19 AND TSH.Status IN (1,3,5) AND TSH.ColDate BETWEEN ''+'' @FromDate ''+'' AND ''+'' @ToDate ''+''''
set @InitialQuery += (case when ISNULL(@Grp2ID,'''') = '''' then '''' else
case when @Grp2Type = 1 then '' and MB.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
when @Grp2Type = 2 then '' and MSM.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
when @Grp2Type = 3 then '' and MC.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
when @Grp2Type = 4 then '' and MCT.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
END
END)
set @InitialQuery +=''GROUP BY TSH.ColDate,'' + case when @Grp2Type = 1 then ''TSH.BeatID,MB.Name'' when @Grp2Type = 2 then ''TSH.SalesmanID,MSM.Name''
when @Grp2Type = 3 then ''MC.ID,MC.Name'' else ''mct.ID,mct.Name'' END
set @InitialQuery += '') as rec group by ColDate,Grp2Name,Grp2ID''

insert into #t2
EXEC sys.sp_executesql @InitialQuery, N''@Mode int, @Grp1Type int, @Grp2Type int, @Grp2ID NVARCHAR(MAX), @Grp3Type int, @Grp3ID NVARCHAR(MAX), @Grp4Type int, @FromDate date, @ToDate date'', @Mode, @Grp1Type, @Grp2Type, @Grp2ID, @Grp3Type, @Grp3ID, @Grp4Type, @FromDate, @ToDate

SET @query = ''SELECT Grp2ID,Grp2Name''+@Group2TypeName+'',(''+@CumativeCol+'') AS ''+@Group1TypeName+''],''+@PColWithisnull+
'' FROM #t2 PIVOT (SUM(Grp3Value) FOR ColDate IN ('' + @PCol + '')) AS PivotTable ORDER BY ''+@Group2TypeName+'' ''
EXEC sys.sp_executesql @query, N''@Mode int, @Grp1Type int, @Grp2Type int, @Grp2ID NVARCHAR(MAX), @Grp3Type int, @Grp3ID NVARCHAR(MAX), @Grp4Type int, @FromDate date, @ToDate date'', @Mode, @Grp1Type, @Grp2Type, @Grp2ID, @Grp3Type, @Grp3ID, @Grp4Type, @FromDate, @ToDate

DROP TABLE #t2

END
ELSE IF(@Grp1Type = 5) -- Outstandings
BEGIN
;WITH ALLMonthsCTE AS (
SELECT DATEFROMPARTS(YEAR(@FromDate), MONTH(@FromDate), 1) AS MonthStart
UNION ALL
SELECT DATEADD(MONTH, 1, MonthStart)
FROM ALLMonthsCTE
WHERE DATEADD(MONTH, 1, MonthStart) <= DATEFROMPARTS(YEAR(@Todate), MONTH(@Todate), 1)
)
SELECT @PCol = MonthList FROM (SELECT STRING_AGG(FORMAT(MonthStart, ''[MMM yyyy]''), '', '') WITHIN GROUP (ORDER BY MonthStart) AS MonthList FROM ALLMonthsCTE) AS RR

;WITH ALLMonthsCTE AS (
SELECT DATEFROMPARTS(YEAR(@FromDate), MONTH(@FromDate), 1) AS MonthStart
UNION ALL
SELECT DATEADD(MONTH, 1, MonthStart)
FROM ALLMonthsCTE
WHERE DATEADD(MONTH, 1, MonthStart) <= DATEFROMPARTS(YEAR(@Todate), MONTH(@Todate), 1)
)
SELECT @PColWithisnull = MonthList FROM (SELECT STRING_AGG(''SUM((ISNULL(['' + FORMAT(MonthStart, ''MMM yyyy'')+ ''],0))) AS ['' + FORMAT(MonthStart, ''MMM yyyy'')+ '']'', '', '')

WITHIN GROUP (ORDER BY MonthStart) AS MonthList FROM ALLMonthsCTE) AS RR
;WITH ALLMonthsCTE AS (
SELECT DATEFROMPARTS(YEAR(@FromDate), MONTH(@FromDate), 1) AS MonthStart
UNION ALL
SELECT DATEADD(MONTH, 1, MonthStart)
FROM ALLMonthsCTE
WHERE DATEADD(MONTH, 1, MonthStart) <= DATEFROMPARTS(YEAR(@Todate), MONTH(@Todate), 1)
)
SELECT @CumativeCol = MonthList FROM (SELECT STRING_AGG(''sum(ISNULL(''+FORMAT(MonthStart, ''[MMM yyyy]'')+'',0))'', ''+ '') WITHIN GROUP (ORDER BY MonthStart) AS MonthList FROM ALLMonthsCTE) AS RR


create table #t3(InvDate nvarchar(50),Grp1ID int,Grp1Name nvarchar(255),Grp2ID int,Grp2Name nvarchar(255),Grp3Value decimal(25,4),NetAmt decimal(25,4))

set @InitialQuery = '' SELECT InvDate,Grp1ID,Grp1Name,Grp2ID,Grp2Name,SUM(Grp3Value) Grp3Value,SUM(NetAmt) NetAmt FROM (
select UPPER(FORMAT(SH.InvDate,''''MMM yyyy'''')) InvDate,round((SUM(SD.NetAmt) / NULLIF(SH.NetAmt,0)) * SH.Balance,0) Grp3Value,
round(SUM(SD.NetAmt),0) NetAmt''
set @InitialQuery += case when @Grp3Type = 0 then '',0 Grp1ID,null Grp1Name'' when @Grp3Type = 1 then '',MP.MfrID Grp1ID,MANUF.Name Grp1Name'' when @Grp3Type = 2 then '',MP.BrandID Grp1ID,MBR.Name Grp1Name''
when @Grp3Type = 3 then '',MP.CategoryID Grp1ID,MCAT.Name Grp1Name'' else '',MP.ID Grp1ID,MP.Name Grp1Name'' END
set @InitialQuery += case when @Grp2Type = 0 then '',0 Grp2ID,null Grp2Name'' when @Grp2Type = 1 then '',ISNULL(SH.BeatID,0) Grp2ID,MB.Name Grp2Name'' when @Grp2Type = 2 then '',ISNULL(SH.SalesmanID,0) Grp2ID,SM.Name Grp2Name''
when @Grp2Type = 3 then '',MC.ID Grp2ID,MC.Name Grp2Name'' else '',ISNULL(MCT.ID,0) Grp2ID,MCT.Name Grp2Name'' END
set @InitialQuery += '' from tblTranSalesHeader SH
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesManID
LEFT JOIN tblMasterCustomerType MCT ON MCT.ID = MC.CustomerType

JOIN tblMasterProduct MP ON MP.ID = SD.ProdID
JOIN tblMasterManufacturer MANUF ON MANUF.ID = MP.MfrID
JOIN tblMasterBrand MBR ON MBR.ID = MP.BrandID
JOIN tblMasterCategory MCAT ON MCAT.ID = MP.CategoryID
WHERE SH.STATUS NOT IN (2,4) and SH.DocPrefix = 15 AND  SH.Balance > 0 AND SD.TaxID > 0 AND 
SH.InvDate BETWEEN ''+'' @FromDate ''+'' AND ''+'' @ToDate ''+''''
set @InitialQuery += (case when ISNULL(@Grp2ID,'''') = '''' or @Grp2Type = 0 then '''' else
case when @Grp2Type = 1 then '' and MB.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
when @Grp2Type = 2 then '' and SM.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
when @Grp2Type = 3 then '' and MC.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
when @Grp2Type = 4 then '' and MCT.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
END END)
set @InitialQuery += (case when ISNULL(@Grp3ID,'''') = '''' or @Grp3Type = 0 then '''' else
case when @Grp3Type = 1 then '' and MP.MfrID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
when @Grp3Type = 2 then '' and MP.BrandID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
when @Grp3Type = 3 then '' and MP.CategoryID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
when @Grp3Type = 4 then '' and MP.ID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
END
END)
set @InitialQuery += ''GROUP BY SH.InvDate'' + case when @Grp2Type = 0 then ''''
when @Grp2Type = 1 then '',SH.BeatID,MB.Name,SH.Balance,SH.NetAmt''
when @Grp2Type = 2 then '',SH.SalesmanID,SM.Name,SH.Balance,SH.NetAmt''
when @Grp2Type = 3 then '',MC.ID,MC.Name,SH.Balance,SH.NetAmt'' else '',MCT.ID,MCT.Name,SH.Balance,SH.NetAmt'' END

set @InitialQuery +=  (case when @Grp3Type = 0 then '''' 
when @Grp3Type = 1 then '',MP.MfrID,MANUF.Name,SH.Balance,SH.NetAmt'' 
when @Grp3Type = 2 then '',MP.BrandID,MBR.Name,SH.Balance,SH.NetAmt''
when @Grp3Type = 3 then '',MP.CategoryID,MCAT.Name,SH.Balance,SH.NetAmt'' 
else '',MP.ID,MP.Name,SH.Balance,SH.NetAmt'' END)

set @InitialQuery += '') as rec group by InvDate,Grp1ID,Grp1Name,Grp2ID,Grp2Name''

insert into #t3
EXEC sys.sp_executesql @InitialQuery, N''@Mode int, @Grp1Type int, @Grp2Type int, @Grp2ID NVARCHAR(MAX), @Grp3Type int, @Grp3ID NVARCHAR(MAX), @Grp4Type int, @FromDate date, @ToDate date'', @Mode, @Grp1Type, @Grp2Type, @Grp2ID, @Grp3Type, @Grp3ID, @Grp4Type, @FromDate, @ToDate

    SET @query = ''SELECT ''+
case when @Grp3Type = 0 then '''' else '' Grp1ID,'' end +
case when @Grp2Type = 0 then '''' else '' Grp2ID,'' end +
case when @Grp3Type = 0 then '''' else ''Grp1Name''+@Group3TypeName+'','' end +
case when @Grp2Type = 0 then '''' else ''Grp2Name''+@Group2TypeName+'','' end +''SUM(NetAmt) [Invoice Value],(''+@CumativeCol+'') AS ''+@Group1TypeName+''],''+@PColWithisnull+
    '' FROM #t3 PIVOT (SUM(Grp3Value) FOR InvDate IN ('' + @PCol + '')) AS PivotTable ''
    SET @query += (CASE WHEN @Grp2Type = 0 AND @Grp3Type = 0 THEN ''''
    WHEN @Grp2Type = 0 AND @Grp3Type != 0 THEN ''GROUP BY Grp1ID,Grp1Name''
    WHEN @Grp2Type != 0 AND @Grp3Type = 0 THEN ''GROUP BY Grp2ID,Grp2Name''
    WHEN @Grp2Type != 0 AND @Grp3Type != 0 THEN ''GROUP BY Grp1ID,Grp1Name,Grp2ID,Grp2Name''
    ELSE '''' END)+''    
    HAVING (''+@CumativeCol+'') > 0
    ORDER BY ''+case when @Grp3Type = 0 then '''' else @Group3TypeName end +
case when @Grp2Type > 0 and @Grp3Type > 0 then '','' else '''' end+
case when @Grp2Type = 0 then '''' else @Group2TypeName end
    EXEC sys.sp_executesql @query, N''@Mode int, @Grp1Type int, @Grp2Type int, @Grp2ID NVARCHAR(MAX), @Grp3Type int, @Grp3ID NVARCHAR(MAX), @Grp4Type int, @FromDate date, @ToDate date'', @Mode, @Grp1Type, @Grp2Type, @Grp2ID, @Grp3Type, @Grp3ID, @Grp4Type, @FromDate, @ToDate

drop table #t3
END
ELSE IF(@Grp1Type in (6,7)) -- Purchase,PR
BEGIN

set @InitialQuery = ''
SELECT InvDate,Grp1ID,Grp1Name,Grp2ID,Grp2Name,SUM(Grp3Value) Grp3Value FROM (
select UPPER(FORMAT(SH.Date,''''MMM yyyy'''')) InvDate''
set @InitialQuery += case when @Grp3Type = 0 then '',0 Grp1ID,null Grp1Name'' when @Grp3Type = 1 then '',MP.MfrID Grp1ID,MANUF.Name Grp1Name'' when @Grp3Type = 2 then '',MP.BrandID Grp1ID,MBR.Name Grp1Name''
when @Grp3Type = 3 then '',MP.CategoryID Grp1ID,MCAT.Name Grp1Name'' else '',MP.ID Grp1ID,MP.Name Grp1Name'' END

set @InitialQuery += case when @Grp2Type = 0 then '',0 Grp2ID,null Grp2Name'' when @Grp2Type = 1 then '',ISNULL(SH.VendorID,0) Grp2ID,MC.Name Grp2Name''
else '''' END

set @InitialQuery += case when @Grp4Type = 1 then '',SUM(SD.UOMQty) Grp3Value '' when @Grp4Type = 2 then '',SUM(SD.GrossAmt) Grp3Value '' else
'',SUM(SD.NetAmt) Grp3Value'' end
-- AND SH.DocPrefix = 15
set @InitialQuery += '' from tblTransPurchaseHeader SH
JOIN tblTransPurchaseDetail SD ON SD.HID = SH.ID
JOIN tblMasterVendor MC ON MC.ID = SH.VendorID
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID
JOIN tblMasterManufacturer MANUF ON MANUF.ID = MP.MfrID
JOIN tblMasterBrand MBR ON MBR.ID = MP.BrandID
JOIN tblMasterCategory MCAT ON MCAT.ID = MP.CategoryID
WHERE SH.STATUS NOT IN (2,4) AND SH.Date BETWEEN ''+'' @FromDate ''+'' AND ''+'' @ToDate ''+''''
-- AND ISNULL(SD.TaxId,0)>0
set @InitialQuery += case when @Grp1Type = 6 then '' and SH.TransID = 1 '' when @Grp1Type = 7 then '' and TransID = 12 ''
else '''' end

set @InitialQuery += (case when ISNULL(@Grp3ID,'''') = '''' or @Grp3Type = 0 then '''' else
case when @Grp3Type = 1 then '' and MP.MfrID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
when @Grp3Type = 2 then '' and MP.BrandID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
when @Grp3Type = 3 then '' and MP.CategoryID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
when @Grp3Type = 4 then '' and MP.ID IN (SELECT * FROM string_split(''+'' @Grp3ID ''+'',''+'''''',''''''+''))''
END
END)

set @InitialQuery += (case when ISNULL(@Grp2ID,'''') = '''' or @Grp2Type = 0 then '''' else
case when @Grp2Type = 1 then '' and MC.ID IN (SELECT * FROM string_split(''+'' @Grp2ID ''+'',''+'''''',''''''+''))''
END
END)

set @InitialQuery += ''GROUP BY SH.Date'' +(case when @Grp3Type = 0 then '''' when @Grp3Type = 1 then '',MP.MfrID,MANUF.Name'' when @Grp3Type = 2 then '',MP.BrandID,MBR.Name''
when @Grp3Type = 3 then '',MP.CategoryID,MCAT.Name'' else '',MP.ID,MP.Name'' END)

set @InitialQuery += case when @Grp2Type = 0 then '''' when @Grp2Type = 1 then '',SH.VendorID,MC.Name''
else '''' END

set @InitialQuery += '') as rec group by InvDate,Grp1ID,Grp1Name,Grp2ID,Grp2Name''--Grp1ID,Grp1Name,Grp2ID,Grp2Name''

--select @InitialQuery

insert into #t1
EXEC sys.sp_executesql @InitialQuery, N''@Mode int, @Grp1Type int, @Grp2Type int, @Grp2ID NVARCHAR(MAX), @Grp3Type int, @Grp3ID NVARCHAR(MAX), @Grp4Type int, @FromDate date, @ToDate date'', @Mode, @Grp1Type, @Grp2Type, @Grp2ID, @Grp3Type, @Grp3ID, @Grp4Type, @FromDate, @ToDate

SET @query = ''SELECT ''+
case when @Grp3Type = 0 then '''' else '' Grp1ID,'' end +
case when @Grp2Type = 0 then '''' else '' Grp2ID,'' end +
case when @Grp3Type = 0 then '''' else ''Grp1Name''+@Group3TypeName+'','' end +
case when @Grp2Type = 0 then '''' else ''Grp2Name''+@Group2TypeName+'','' end +
''(''+@CumativeCol+'') AS ''+@Group1TypeName+@Group4TypeName+''],''+@PColWithisnull+
'' FROM #t1 PIVOT (SUM(Grp3Value) FOR InvDate IN ('' + @PCol + '')) AS PivotTable ORDER BY ''+case when @Grp3Type = 0 then '''' else @Group3TypeName end +
case when @Grp2Type > 0 and @Grp3Type > 0 then '','' else '''' end+
case when @Grp2Type = 0 then '''' else @Group2TypeName end
EXEC sys.sp_executesql @query, N''@Mode int, @Grp1Type int, @Grp2Type int, @Grp2ID NVARCHAR(MAX), @Grp3Type int, @Grp3ID NVARCHAR(MAX), @Grp4Type int, @FromDate date, @ToDate date'', @Mode, @Grp1Type, @Grp2Type, @Grp2ID, @Grp3Type, @Grp3ID, @Grp4Type, @FromDate, @ToDate
END
drop table #t1
END
END',
N'[06] nocount';
GO
/****** uspNilStockDetail ******/
EXEC #Apply07 N'dbo.uspNilStockDetail', 0x6DB67844276BE5B69F8323B0078001AE4FA42E06CC072A170E178694AF70B0DB, NULL, NULL, 0x5C57F34CBAD7D4F1124E5C8CC6E7F10CB977D56AF44EA21E124AFE11376B43D8, 0x900CA8AD3C5C75D28B4AD06E017535DD5500D30DA1D0727B48398F31DBE19068, NULL,
N'--uspNilStockDetail 126,4
ALTER proc [dbo].[uspNilStockDetail]        
@ProductID INT,@BranchID INT        
as        
SET NOCOUNT ON;
begin        
SELECT [Product Code],[Product Name],[Batch Number],[PKD Date],[Expiry Date],[dbo].[fnGetRoundedValue](SUM([Actual Qty])) [Actual Qty],
[dbo].[fnGetRoundedValue](SUM([Actual Free Qty])) [Actual Free Qty],[dbo].[fnGetRoundedValue](SUM([Actual Damage Qty])) [Actual Damage Qty],
[Purchase Price],[Sales Price],[End Consumer Price],[MRP],[Special Price],[Return Price]
FROM (
SELECT MP.Code [Product Code],MP.Name [Product Name],BatchNumber as[Batch Number],CONVERT(NVARCHAR,PkdDate,103) as[PKD Date],          
CONVERT(NVARCHAR,ExpiryDate,103) as[Expiry Date],          
(sum(isnull(Prod.ActualQty,0)) + SUM(isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0))) as [Actual Qty],      
sum(isnull(Prod.ActualFreeQty,0)) as [Actual Free Qty],          
sum(isnull(Prod.ActualDmgQty,0)) as [Actual Damage Qty],          
[dbo].[fnGetRoundedValue](Prod.PurchasePrice)as[Purchase Price],          
[dbo].[fnGetRoundedValue](Prod.SalesPrice) as[Sales Price],          
[dbo].[fnGetRoundedValue](Prod.ECP) as [End Consumer Price],          
[dbo].[fnGetRoundedValue](Prod.MRPONPrice) as[MRP],          
[dbo].[fnGetRoundedValue](Prod.SPLPrice) as [Special Price],        
[dbo].[fnGetRoundedValue](Prod.ReturnPrice) as [Return Price]          
FROM tblProductInventory as Prod          
join tblMasterProduct MP ON MP.ID = Prod.ProdID    
LEFT JOIN tblVanLoadingSlipDetail VLD ON VLD.InventoryID = Prod.InventoryId  
WHERE Prod.ProdId= @ProductID AND BranchID =  @BranchID        
--AND ((ISNULL(Prod.ActualQty,0)>0) or (ISNULL(Prod.ActualFreeQty,0)>0) or (ISNULL(Prod.ActualDmgQty,0)>0))          
GROUP BY MP.Code,MP.Name,BatchNumber,PkdDate,ExpiryDate,
Prod.PurchasePrice,Prod.SalesPrice,Prod.ECP,Prod.MRPONPrice,Prod.SPLPrice,Prod.ReturnPrice) AS REC
group by  [Product Code],[Product Name],[Batch Number],[PKD Date],[Expiry Date],[Purchase Price],[Sales Price],
[End Consumer Price],[MRP],[Special Price],[Return Price]
having sum([Actual Qty] + [Actual Free Qty] + [Actual Damage Qty]) > 0
end',
N'[export] nocount';
GO
/****** uspNilStockHeader ******/
EXEC #Apply07 N'dbo.uspNilStockHeader', 0x0C6F5ED6F61FF87E2FA7743CDF27B0528CF2402C87B5CF61238DB71175EA5DD0, 0xBB066427B7973A915BD255FF73371339657130E350E6C02588C7A85004233053, NULL, 0x228576111EBE95E99EE74BB806AA48E40C7C7BA2D5D29580BC8DC205D86FD46C, 0x1A8208D234B8427B5E4EDE664C1BAE408D0AF4B67B4B2F4DE1A57A6C9F288862, NULL,
N'--uspNilStockHeader 0,'''','''','''',''126'',1500 
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspNilStockHeader]      
@BranchName int = 0,@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255)='''',        
@Qty DECIMAL(25,4) = 0      
as      
SET NOCOUNT ON;
begin      
DECLARE @query NVARCHAR(MAX)      
set @query = ''      
SELECT ProductID,BranchID,[Branch Name],Code,Name,EAN,[MfrID],[Mfr Name],[BrandID],[Brand Name],[CategoryID],[Category Name],      
dbo.fngetroundedvalue(isnull(SUM(Qty),0)) Qty,dbo.fngetroundedvalue(isnull(SUM([Free Qty]),0)) [Free Qty],    
dbo.fngetroundedvalue(isnull(SUM([Dmg Qty]),0)) [Dmg Qty],      
format(MAX([Last Sale Date]),''''dd-MMM-yyyy'''') [Last Sale Date]  FROM (    
SELECT PIN.ProdId ProductID,PIN.BranchID,MBR.Name [Branch Name],mp.Code,mp.Name,mp.EAN,MF.ID[MfrID],MF.Name [Mfr Name],MB.ID[BrandID],MB.Name [Brand Name],MC.ID[CategoryID],MC.Name [Category Name],      
(isnull(SUM(ActualQty),0)) + isnull(SUM(isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0)),0) Qty,
(isnull(SUM(ActualFreeQty),0)) [Free Qty],    
(isnull(SUM(ActualDmgQty),0)) [Dmg Qty],      
(SELECT (MAX(SH.InvDate)) FROM TBLTRANSALESDETAIL SD
LEFT JOIN TBLTRANSALESHEADER SH ON SH.ID = SD.InvID AND STATUS IN (1,3,5)
AND DocPrefix = 15 WHERE SD.PRODID = PIN.PRODID ) [Last Sale Date]      
FROM tblProductInventory PIN      
JOIN tblMasterProduct MP ON MP.ID = PIN.ProdId      
JOIN tblMasterBranchOffice MBR ON MBR.ID = PIN.BranchID      
JOIN TBLMASTERMANUFACTURER AS MF ON MF.ID = MP.MfrID      
JOIN tblMasterBrand AS MB ON MB.ID = MP.BrandID      
JOIN TBLMASTERCATEGORY AS MC ON MC.ID = MP.CategoryID    
LEFT JOIN tblVanLoadingSlipDetail VLD ON VLD.InventoryID = PIN.InventoryId  
GROUP BY PIN.ProdId,mp.Code,mp.Name,mp.EAN,MF.Name,MB.Name,MC.Name,MBR.Name,PIN.BranchID,MF.ID,MC.ID,MB.ID ) AS REC ''    
set @query += '' WHERE (ISNULL(Qty,0) <=  @Qty )''    
 set @query += case when ISNULL(@BranchName,'''') = '''' then '''' else '' AND BranchID = ''+'' @BranchName ''+'''' END        
 set @query += case when ISNULL(@BrandName,'''') = '''' then '''' else '' AND [BrandID] IN (SELECT * from dbo.fnSplitString( ''+'' @BrandName ,'''',''''))'' END        
 set @query += case when ISNULL(@CategoryName,'''') = '''' then '''' else '' AND [CategoryID] IN (SELECT * from dbo.fnSplitString( ''+'' @CategoryName ,'''',''''))'' END        
 set @query += case when ISNULL(@ManufName,'''') = '''' then '''' else '' AND [MfrID] IN (SELECT * from dbo.fnSplitString( ''+'' @ManufName ,'''',''''))'' END        
 set @query += case when ISNULL(@ProductName,'''') = '''' then '''' else '' AND ProductID IN (SELECT * from dbo.fnSplitString( ''+'' @ProductName ,'''',''''))'' END      
 set @query += '' GROUP BY ProductID,BranchID,[Branch Name],Code,Name,EAN,[Mfr Name],[Brand Name],[Category Name],[MfrID],[CategoryID],[BrandID]    
order by Name ''    
PRINT @query
 EXEC sys.sp_executesql @query, N''@BranchName int, @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @Qty DECIMAL(25,4)'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @Qty      
end',
N'[06] nocount';
GO
/****** uspOneView ******/
EXEC #Apply07 N'dbo.uspOneView', 0xE3674E121A5632AE422F41DE97DDAF0EB98C89182234B372BBAB8599F6E47D97, NULL, NULL, 0x58867D14ACEFE3B206D98C4FEA25B3F495E621B80B859FA4970311EB5B7952DD, 0x08D3E96DC6E58145196922DC44AC2CADF2F5F1A9B9507273BD771631F1AA2C4C, NULL,
N'--uspOneView 7,9,1            
ALTER PROC [dbo].[uspOneView]                                
@nMode INT = 2,@PartyID INT = 279,@Type INT = 1                        
as                                
SET NOCOUNT ON;
begin                             
DECLARE @MonthCount INT;                
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration)                                                          
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration)                                                          
DECLARE @M_FD DATE = DATEADD(dd,-(DAY(GETDATE())-1),GETDATE())                                                          
DECLARE @M_ED DATE = DATEADD(dd,-(DAY(DATEADD(mm,1,GETDATE()))),DATEADD(mm,1,GETDATE()))                                
DECLARE @YRSPValue DECIMAL(25,6),@YRRtnValue DECIMAL(25,6),@MntSPValue DECIMAL(25,6),@MntRtnValue DECIMAL(25,6),@YRDmgRtnValue DECIMAL(25,6),                                
@YRRtnPern DECIMAL(25,6),@MntRtnPern DECIMAL(25,6),@AccID INT,@MntDmgRtnValue DECIMAL(25,6),                          
@YRDmgRtnPern DECIMAL(25,6),@MntDmgRtnPern DECIMAL(25,6),@AccountName nvarchar(255),@NoofMonth int,                    
@AvgSaleValue decimal(25,4),@AvgRTNValue decimal(25,4),@Acc INT                 
                      
CREATE TABLE #TEMPOPEN(Balance DECIMAL(25,2),CRDR NVARCHAR(10))                      
CREATE TABLE #TEMPCLOSE(Balance DECIMAL(25,2),CRDR NVARCHAR(10))                      
DECLARE @OPENBAL DECIMAL(18,2),@OPENCRDR NVARCHAR(10)                      
DECLARE @CLOSEBAL DECIMAL(18,2),@CLOSECRDR NVARCHAR(10)      
      
IF(@nMode = 0)                        
BEGIN                       
IF(@Type = 1)                        
BEGIN                        
SELECT ID,Code,Name FROM tblMasterCustomer ORDER BY Name                        
END                        
ELSE IF(@Type = 2)                        
BEGIN                        
SELECT ID,Code,Name FROM tblMasterVendor ORDER BY Name                        
END                        
END      
ELSE IF(@Type = 1) --For Customer                                
BEGIN                                
SELECT @AccID = FAID,@AccountName = Name FROM tblMasterCustomer WHERE Id = @PartyID                                
IF(@nMode = 1)--cust code,Name,last sale date                                
BEGIN              
              
select @Acc = sum(ageing) / count(ID) from (              
SELECT ID,DocID,DATEDIFF(DD,InvDate,ColDate) Ageing FROM (              
select SH.ID,SH.DocID,MIN(SH.InvDate) InvDate,(MAX(CH.ColDate)) ColDate from tblTranSalesHeader SH              
JOIN tblTranCollectionDetail CD ON CD.DocID = sh.ID              
join tblTranCollectionHeader CH ON CH.ColID = CD.ColID              
where SH.DocPrefix = 15 and SH.status in (5) and CustID = @PartyID and SH.Balance = 0              
GROUP BY SH.ID,SH.DocID,sh.NetAmt,sh.Balance) AS REC              
) as rec1              
              
SELECT Code,Name,Billadd1+'' ''+BillAdd2+'' ''+Billadd3 Address,Pincode,Mob1,Ph1,Email,GSTIN,MC.Rating RatingValue,RT.RatingName,              
CONVERT(NVARCHAR(30),MAX(InvDate),103) LastTranDate,@Acc Acc              
FROM tblMasterCustomer MC                         
LEFT JOIN tblTranSalesHeader SH ON MC.Id = SH.CustId                        
LEFT JOIN tblRatings RT ON RT.ID = MC.Rating                        
WHERE MC.ID = @PartyID                                
GROUP BY Code,Name,Billadd1,Billadd2,Billadd3,Mob1,Ph1,Email,GSTIN,MC.Rating,RT.RatingName,Pincode                        
END                                
IF(@nMode = 2)--YR,MNT SALE/PURCHASE,RTN VALUE                                
BEGIN                                
set @NoofMonth = (SELECT (DATEDIFF(MM,MIN(InvDate),GETDATE()) + 1) MONTHS FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status in (1,3,5)                    
 AND InvDate BETWEEN @F_SD AND @F_ED)                    
                    
SELECT @YRSPValue = ISNULL(SUM(NetAmt),0) FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status in (1,3,5) AND DocPrefix = 15 AND InvDate BETWEEN @F_SD AND @F_ED                    
SELECT @MntSPValue = ISNULL(SUM(NetAmt),0) FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status in (1,3,5) AND DocPrefix = 15 AND InvDate BETWEEN @M_FD AND @M_ED                                              
                          
SELECT @YRRtnValue = ISNULL(SUM(NetAmt),0) FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status in (3,5,6) and ReturnsTransType = 1 AND DocPrefix = 16 AND InvDate BETWEEN @F_SD AND @F_ED                          
SELECT @YRDmgRtnValue = ISNULL(SUM(NetAmt),0) FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status in (3,5,7) and ReturnsTransType = 2 AND DocPrefix = 16 AND InvDate BETWEEN @F_SD AND @F_ED                          
                          
SELECT @MntRtnValue = ISNULL(SUM(NetAmt),0)  FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status in (3,5,6) and ReturnsTransType = 1 AND DocPrefix = 16 AND InvDate BETWEEN @M_FD AND @M_ED                                
SELECT @MntDmgRtnValue = ISNULL(SUM(NetAmt),0)  FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status in (3,5,7) and ReturnsTransType = 2 AND DocPrefix = 16 AND InvDate BETWEEN @M_FD AND @M_ED                                
                          
SET @YRRtnPern = (@YRRtnValue * 100) / nullif(@YRSPValue,0)                                
SET @MntRtnPern = (@MntRtnValue * 100) / nullif(@MntSPValue,0)                              
                          
SET @YRDmgRtnPern = (@YRDmgRtnValue * 100) / nullif(@YRSPValue,0)                                
SET @MntDmgRtnPern = (@MntDmgRtnValue * 100) / nullif(@MntSPValue,0)                           
--@AvgSaleValue decimal(25,4),@AvgRTNValue decimal(25,4)                    
SELECT @AvgSaleValue = nullif(SUM(NetAmt),0) / @NoofMonth FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status in (1,3,5) AND DocPrefix = 15 AND InvDate BETWEEN @F_SD AND @F_ED                    
SELECT @AvgRTNValue = nullif(SUM(NetAmt),0) / @NoofMonth FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status in (3,5,6) and ReturnsTransType = 1 AND DocPrefix = 16 AND InvDate BETWEEN @F_SD AND @F_ED                          
                    
SELECT (DBO.fnGetRoundedValue(ISNULL(@YRSPValue,0))) YRSALE,                                
(DBO.fnGetRoundedValue(ISNULL(@MntSPValue,0))) MNTSALE,                                
(DBO.fnGetRoundedValue(ISNULL(@YRRtnValue+@YRDmgRtnValue,0)))+''(''+DBO.fnGetRoundedValue(ISNULL(@YRRtnPern,0))+''% / ''+DBO.fnGetRoundedValue(ISNULL(@YRDmgRtnPern,0))+''%)'' YRRTN,                                
(DBO.fnGetRoundedValue(ISNULL(@MntRtnValue+@MntDmgRtnValue,0)))+''(''+DBO.fnGetRoundedValue(ISNULL(@MntRtnPern,0))+''% / ''+DBO.fnGetRoundedValue(ISNULL(@MntDmgRtnPern,0))+''%)'' MNTRTN,                    
DBO.fnGetRoundedValue(ISNULL(@AvgSaleValue,0)) AvgSaleValue,                                
DBO.fnGetRoundedValue(ISNULL(@AvgRTNValue,0)) AvgRTNValue                    
--DBO.fnGetRoundedValue(@YRRtnPern) YRRTNPern,DBO.fnGetRoundedValue(ISNULL(@MntRtnPern,0)) MNTRTNPern                                
END                                
IF(@nMode = 3)-- OS                                
BEGIN                                
                            
--SELECT 2 Sno,DocPrefix,(CASE WHEN UDFId > 0 THEN UDFDocId ELSE DocId END) [Doc ID],CONVERT(NVARCHAR(30),InvDate,103) [Doc Date],                      
--CASE WHEN DocPrefix = 15 THEN NetAmt ELSE (NetAmt * -1) END [Net Amount],                                
--CASE WHEN DocPrefix = 15 THEN Balance ELSE (Balance * -1) END Balance,                                
--CONVERT(NVARCHAR,DATEDIFF(DD,InvDate,GETDATE())) Ageing INTO #OSC                              
-- FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status IN (1,3,5,6,7) AND Balance > 0                                
-- order by CONVERT(date,InvDate),(CASE WHEN UDFId > 0 THEN UDFDocId ELSE DocId END)              
     
 SELECT 2 Sno,DocPrefix, [Doc ID],convert(nvarchar(25),DocDate,103) [Doc Date],[Net Amount],Balance,Ageing INTO #OSC FROM (    
SELECT DocPrefix,DocId [Doc ID],InvDate DocDate,                      
CASE WHEN DocPrefix = 15 THEN NetAmt ELSE (NetAmt * -1) END [Net Amount],              
CASE WHEN DocPrefix = 15 THEN Balance ELSE (Balance * -1) END Balance,                                
CONVERT(NVARCHAR,DATEDIFF(DD,InvDate,GETDATE())) Ageing                          
 FROM tblTranSalesHeader WHERE CustId = @PartyID AND Status IN (1,3,5,6,7) AND Balance > 0     
 UNION ALL    
 SELECT DocPrefix,DocId [Doc ID],ColDate DocDate,(ColAmt * -1)[Net Amount],(Balance * -1) Balance,                                
CONVERT(NVARCHAR,DATEDIFF(DD,ColDate,GETDATE())) Ageing                          
 FROM tblTranCollectionHeader SH    
 JOIN tblMasterCustomer MC ON MC.FAID = SH.AccID    
 WHERE ID = @PartyID AND DocPrefix =  19 AND Status IN (1,3,5) AND Balance > 0    
  UNION ALL    
 SELECT TransID,DocId [Doc ID],DocDate,(NoteValue * -1)[Net Amount],(Balance * -1) Balance,                                
CONVERT(NVARCHAR,DATEDIFF(DD,DocDate,GETDATE())) Ageing                          
 FROM tblNoteDetails SH    
 JOIN tblMasterCustomer MC ON MC.FAID = SH.PartyID    
 WHERE MC.ID = @PartyID AND TransID =  4 AND Status IN (1,3,5) AND Balance > 0    
   UNION ALL    
 SELECT TransID,DocId [Doc ID],DocDate,(NetAmount)[Net Amount],(Balance) Balance,                                
CONVERT(NVARCHAR,DATEDIFF(DD,DocDate,GETDATE())) Ageing                          
 FROM tblTranPRVoucher SH    
 JOIN tblMasterCustomer MC ON MC.FAID = SH.PartyID    
 WHERE MC.ID = @PartyID AND TransID =  7 AND Status IN (1,3,5) AND Balance > 0    
 ) AS REC    
 order by CONVERT(date,DocDate),[Doc ID]    
    
 IF((SELECT COUNT(*) FROM #OSC) > 0)                              
 BEGIN                              
 select DocPrefix,[Doc ID],[Doc Date],(dbo.fnGetRoundedValue([Net Amount])) [Net Amount]                              
 ,(dbo.fnGetRoundedValue(Balance)) Balance,Ageing from (                              
 SELECT 1 Sno,0 DocPrefix,'''' [Doc ID],''Total'' [Doc Date],SUM([Net Amount]) [Net Amount],SUM(Balance) Balance,'''' Ageing FROM #OSC                              
 UNION ALL                              
 SELECT * FROM #OSC) as rec                              
 ORDER BY Sno                              
 END                       
 DROP TABLE #OSC                              
END                                
IF(@nMode = 4)-- TOP 10 PRODS                                
BEGIN                                
 SELECT TOP 10 [Product Name],dbo.fnGetRoundedValue(SUM(Qty)) Qty, (dbo.fnGetRoundedValue(SUM(NetAmt))) [Value]  FROM (                                
 select MP.Name [Product Name],SUM(SD.UomQty) Qty,                                
SUM(SD.NetAmt) NetAmt from tblTranSalesHeader SH                                
 JOIN tblTranSalesDetail SD ON SD.InvId = SH.ID                                
 JOIN tblMasterProduct MP ON MP.ID = SD.ProdId                                
 WHERE CustId = @PartyID AND DocPrefix = 15 AND Status IN (1,3,5)                                
 GROUP BY MP.Name) as rec  GROUP BY [Product Name] order by SUM(NetAmt) desc                                
 END                                
IF(@nMode = 5)--cheque info                                
BEGIN                                
SELECT CD.DocPrefix,CD.DocId [Doc ID],CONVERT(NVARCHAR,CPM.[DATE],103) AS [Cheque Date],[Cheque/DD Number],                                
(dbo.fnGetRoundedValue(CollAmt)) [Value]                                
FROM tblCollPMDetails CPM                                 
JOIN tblTranCollectionHeader CD ON CD.ColID = CPM.ColID                   
WHERE (CPM.[DATE] <= @F_ED) AND CPM .[Status] IN (1,3) AND CPM.PaymentTermID IN (2) AND CPM.AccId = @AccID                                   
END                                
IF(@nMode = 6)-- get ledger data                                
BEGIN                         
                      
--exec uspRepAccountLedger @AccountName,@F_SD,@F_ED        
--select DS.TransName [Transaction],DocID [Doc ID],CONVERT(nvarchar,FAJ.DocDate,103) Date,FAA.AccountName [Account Name],                        
--(Credit) Credit,(Debit) Debit,Remarks,Narration,STS.Description Status                      
--INTO #TEMP from tblFAJournal FAJ               
--JOIN tblFAAccount FAA ON FAA.FAID = FAJ.AccountID                              
--JOIN tblDocumentSeries DS ON DS.TransID = FAJ.DocPrefix                              
--JOIN tblStatus STS ON STS.ID = FAJ.Status                              
--WHERE FAJ.Status NOT IN (2,4) and FAJ.AccountID = @AccID and FAJ.DocDate BETWEEN @F_SD AND @F_ED                         
                      
--INSERT INTO #TEMPOPEN                      
--exec uspLoadClosingBalance 1,@AccID,@F_SD                      
                      
--SELECT @OPENBAL = Balance,@OPENCRDR = CRDR FROM #TEMPOPEN                      
                      
--INSERT INTO #TEMPCLOSE                      
--exec uspLoadClosingBalance 2,@AccID,@F_ED                      
                      
--SELECT @CLOSEBAL = Balance,@CLOSECRDR = CRDR FROM #TEMPCLOSE                      
                      
--SELECT [Transaction],[Doc ID],Date,[Account Name],dbo.fnGetRoundedValue(Credit) Credit,dbo.fnGetRoundedValue(Debit) Debit,Remarks,Narration,Status FROM (                      
--SELECT 1 SNO,''Opening Balance'' [Transaction],'''' [Doc ID],'''' Date,'''' [Account Name],                      
--(CASE WHEN @OPENCRDR = ''Cr'' then (@OPENBAL) ELSE 0 END) Credit,                      
--(CASE WHEN @OPENCRDR = ''Dr'' then (@OPENBAL) ELSE 0 END) Debit,'''' Remarks,'''' Narration,'''' Status                      
--UNION                       
--SELECT 2,* FROM #TEMP                      
--UNION                       
--select 3,''Total'' [Transaction],''''[Doc ID],'''' [Date],''''[Account Name],dbo.fnGetRoundedValue(sum([Credit])) [Credit],                        
--dbo.fnGetRoundedValue(sum([Debit])) [Debit],'''' [Remarks],'''' [Narration],'''' [Status] from #TEMP                       
--UNION                      
--SELECT 4,''Closing Balance'' [Transaction],'''' [Doc ID],'''' Date,'''' [Account Name],(CASE WHEN @CLOSECRDR = ''Cr'' then @CLOSEBAL ELSE 0 END) Credit,              
--(CASE WHEN @CLOSECRDR = ''Dr'' then @CLOSEBAL ELSE 0 END) Debit,'''' Remarks,'''' Narration,'''' Status) AS REC                      
--drop table #TEMP                      
exec uspGetFALegderReport 0,@F_SD,@F_ED,@AccID,0,1          
END                              
IF(@nMode = 7)                  
BEGIN                  
SELECT MonthYear, (SUM(SalesAmount)) SalesAmount,          
       (SUM(ReturnAmount)) ReturnAmount,                  
       (SUM(DamageAmount)) DamageAmount,SaleYear,SaleMonth                
INTO #monthsales                 
FROM (                  
    SELECT                   
        FORMAT(InvDate, ''MMM yyyy'') AS MonthYear,                  
        CASE WHEN DocPrefix = 15 THEN SUM(NetAmt) ELSE 0 END AS SalesAmount,                  
        CASE WHEN DocPrefix = 16 and ReturnsTransType  = 1 THEN SUM(NetAmt) ELSE 0 END AS ReturnAmount,                  
  CASE WHEN DocPrefix = 16 and ReturnsTransType  = 2 THEN SUM(NetAmt) ELSE 0 END AS DamageAmount,                  
        YEAR(InvDate) AS SaleYear,                  
        MONTH(InvDate) AS SaleMonth                  
    FROM tbltransalesheader                  
    WHERE CustID = @PartyID AND status IN (1,3,5,6,7)                  
    GROUP BY FORMAT(InvDate, ''MMM yyyy''), YEAR(InvDate), MONTH(InvDate), DocPrefix,ReturnsTransType  
) AS rec                  
GROUP BY MonthYear, SaleYear, SaleMonth                  
ORDER BY SaleYear, SaleMonth;                  
set @MonthCount = (SELECT COUNT(*) FROM #monthsales);                
if(@MonthCount > 0)                
BEGIN                
SELECT MonthYear,                
       SalesAmount,                
       ReturnAmount + '' ('' + SRPern + '')'' AS ReturnAmount,                
       DamageAmount + '' ('' + DmgPern + '')'' AS DamageAmount                 
FROM (   
    SELECT 1 AS sno,                
           MonthYear,                
           dbo.fnGetRoundedValue(SalesAmount) AS SalesAmount,                  
           dbo.fnGetRoundedValue(ReturnAmount) AS ReturnAmount,                  
           dbo.fnGetRoundedValue(CASE WHEN SalesAmount = 0 THEN 0 ELSE (ReturnAmount * 100.0) / SalesAmount END) AS SRPern,                
           dbo.fnGetRoundedValue(DamageAmount) AS DamageAmount,                  
  dbo.fnGetRoundedValue(CASE WHEN SalesAmount = 0 THEN 0 ELSE (DamageAmount * 100.0) / SalesAmount END) AS DmgPern,SaleYear,SaleMonth                 
    FROM #monthsales                  
                
    UNION                  
                
    SELECT 2 AS sno,                
           ''Total'',                
           dbo.fnGetRoundedValue(SUM(SalesAmount)),                  
           dbo.fnGetRoundedValue(SUM(ReturnAmount)),                  
           dbo.fnGetRoundedValue(CASE WHEN SUM(SalesAmount) = 0 THEN 0 ELSE (SUM(ReturnAmount) * 100.0) / SUM(SalesAmount) END),                 
           dbo.fnGetRoundedValue(SUM(DamageAmount)),                  
           dbo.fnGetRoundedValue(CASE WHEN SUM(SalesAmount) = 0 THEN 0 ELSE (SUM(DamageAmount) * 100.0) / SUM(SalesAmount) END) ,0 SaleYear,0 SaleMonth                
    FROM #monthsales                  
                
    UNION                  
                
    SELECT 3 AS sno,                
           ''Average'',                
           dbo.fnGetRoundedValue(SUM(SalesAmount) / NULLIF(@MonthCount, 0)),                  
           dbo.fnGetRoundedValue(SUM(ReturnAmount) / NULLIF(@MonthCount, 0)),                  
           dbo.fnGetRoundedValue(                
               CASE WHEN SUM(SalesAmount) = 0 THEN 0                 
                    ELSE (SUM(ReturnAmount) / NULLIF(@MonthCount, 0)) / (SUM(SalesAmount) / NULLIF(@MonthCount, 0)) * 100                 
               END),                 
           dbo.fnGetRoundedValue(SUM(DamageAmount) / NULLIF(@MonthCount, 0)),                  
           dbo.fnGetRoundedValue(                
               CASE WHEN SUM(SalesAmount) = 0 THEN 0                                 ELSE (SUM(DamageAmount) / NULLIF(@MonthCount, 0)) / (SUM(SalesAmount) / NULLIF(@MonthCount, 0)) * 100                 
               END) ,0 SaleYear,0 SaleMonth                
    FROM #monthsales                  
) AS rec                
--ORDER BY sno,SaleYear,SaleMonth                
ORDER BY Sno desc,SaleYear desc,SaleMonth desc;                
END                
                
DROP TABLE #monthsales;                
          
END                  
END                                
ELSE IF(@Type = 2) -- For Vendor                                
BEGIN                                       
SELECT @AccID = FAID,@AccountName = Name FROM tblMasterVendor WHERE Id = @PartyID                             
IF(@nMode = 1)--cust code,Name,last sale date                                
BEGIN                                
            
select @Acc = sum(ageing) / count(ID) from (              
SELECT ID,DocID,DATEDIFF(DD,InvDate,ColDate) Ageing FROM (              
select SH.ID,SH.DocID,MIN(SH.DateBill) InvDate,(MAX(CH.PYDate)) ColDate from tblTransPurchaseHeader SH              
JOIN tblTranPaymentDetail CD ON CD.DocID = sh.ID              
join tblTranPaymentHeader CH ON CH.PYID = CD.PYID              
where SH.TransID = 1 and SH.status in (5) and VendorID = @PartyID and SH.Balance = 0              
GROUP BY SH.ID,SH.DocID,sh.NetAmt,sh.Balance) AS REC              
) as rec1              
            
SELECT Code,Name,Billadd1+'' ''+BillAdd2+'' ''+Billadd3 Address,Pincode,Mob1,Ph1,Email,GSTIN,MC.Rating RatingValue,RT.RatingName,              
CONVERT(NVARCHAR(30),MAX(Date),103) LastTranDate,@Acc Acc FROM tblMasterVendor MC                        
LEFT JOIN tblTransPurchaseHeader SH  ON MC.id = SH.VendorID                         
LEFT JOIN tblRatings RT ON RT.ID = MC.Rating                        
WHERE MC.ID = @PartyID                               
GROUP BY code,name,Billadd1,Billadd2,Billadd3,Mob1,Ph1,Email,GSTIN,MC.Rating,RT.RatingName,Pincode                        
                                
END                                
IF(@nMode = 2)--YR,MNT SALE/PURCHASE,RTN VALUE                                
BEGIN                                
                    
set @NoofMonth = (SELECT (DATEDIFF(MM,MIN(Date),GETDATE()) + 1) MONTHS FROM tblTransPurchaseHeader WHERE VendorID = @PartyID AND Status in (1,3,5,6)                    
 AND Date BETWEEN @F_SD AND @F_ED)                    
         
select @YRSPValue = ISNULL(SUM(NetAmt),0) from tblTransPurchaseHeader where VendorID = @PartyID AND Status in (1,3,5) AND TransID = 1 AND Date BETWEEN @F_SD AND @F_ED                                
select @YRSPValue = ISNULL(SUM(NetAmt),0) from tblTransPurchaseHeader where VendorID = @PartyID AND Status in (1,3,5) AND TransID = 1 AND Date BETWEEN @F_SD AND @F_ED                                
select @MntSPValue = ISNULL(SUM(NetAmt),0) from tblTransPurchaseHeader where VendorID = @PartyID AND  Status in (1,3,5) AND TransID = 1 AND Date BETWEEN @M_FD AND @M_ED                             
select @YRRtnValue = ISNULL(SUM(NetAmt),0) from tblTransPurchaseHeader where VendorID = @PartyID AND  Status in (3,5,6) AND TransID = 12 AND Date BETWEEN @F_SD AND @F_ED                                                         
select @MntRtnValue = ISNULL(SUM(NetAmt),0) from tblTransPurchaseHeader where VendorID = @PartyID AND  Status in (3,5,6) AND TransID = 12 AND Date BETWEEN @M_FD AND @M_ED                                
SET @YRRtnPern = (ISNULL(@YRRtnValue,0) * 100) / nullif(@YRSPValue,0)                                
SET @MntRtnPern = (ISNULL(@MntRtnValue,0) * 100) / nullif(@MntSPValue,0)                                
                    
SELECT @AvgSaleValue = nullif(SUM(NetAmt),0) / @NoofMonth FROM tblTransPurchaseHeader where VendorID = @PartyID AND Status in (1,3,5) AND TransID = 1 AND Date BETWEEN @F_SD AND @F_ED                                
SELECT @AvgRTNValue = nullif(SUM(NetAmt),0) / @NoofMonth FROM tblTransPurchaseHeader where VendorID = @PartyID AND  Status in (3,5,6) AND TransID = 12 AND Date BETWEEN @F_SD AND @F_ED                                                         
                    
                    
SELECT (DBO.fnGetRoundedValue(ISNULL(@YRSPValue,0))) YRSALE,                                
(DBO.fnGetRoundedValue(ISNULL(@MntSPValue,0))) MNTSALE,                                
(DBO.fnGetRoundedValue(ISNULL(@YRRtnValue,0)))+''(''+DBO.fnGetRoundedValue(ISNULL(@YRRtnPern,0))+''%)'' YRRTN,                                
(DBO.fnGetRoundedValue(ISNULL(@MntRtnValue,0)))+''(''+DBO.fnGetRoundedValue(ISNULL(@MntRtnPern,0))+''%)'' MNTRTN                                
--DBO.fnGetRoundedValue(@YRRtnPern) YRRTNPern,DBO.fnGetRoundedValue(ISNULL(@MntRtnPern,0)) MNTRTNPern                                
END                                
IF(@nMode = 3)-- OS                                
BEGIN                                
                              
SELECT 2 Sno,TransID DocPrefix,(CASE WHEN UDFId > 0 THEN UDFDocId ELSE DocId END) [Doc ID],CONVERT(NVARCHAR(30),Date,103) [Doc Date],                      
CASE WHEN TransID = 1 THEN NetAmt ELSE (NetAmt * -1) END [Net Amount],                                
CASE WHEN TransID = 1 THEN Balance ELSE (Balance * -1) END Balance,                                
CONVERT(NVARCHAR,DATEDIFF(DD,Date,GETDATE())) Ageing INTO #OSV                              
 FROM tblTransPurchaseHeader WHERE VendorID = @PartyID AND Status IN (1,3,5,6,7) AND Balance > 0                                
 order by CONVERT(date,Date),(CASE WHEN UDFId > 0 THEN UDFDocId ELSE DocId END)                                
 IF((SELECT COUNT(*) FROM #OSV) > 0)                              
 BEGIN                              
 select DocPrefix,[Doc ID],[Doc Date],(dbo.fnGetRoundedValue([Net Amount])) [Net Amount]                              
 ,(dbo.fnGetRoundedValue(Balance)) Balance,Ageing from (                              
 SELECT 1 Sno,0 DocPrefix,'''' [Doc ID],''Total'' [Doc Date],SUM([Net Amount]) [Net Amount],SUM(Balance) Balance,'''' Ageing FROM #OSV                              
 UNION ALL                              
 SELECT * FROM #OSV) as rec                              
 ORDER BY Sno                              
 END                              
 DROP TABLE #OSV                              
--SELECT DocId [Doc ID],CONVERT(NVARCHAR(30),Date,103) [Doc Date],                                
--(dbo.fnGetRoundedValue(NetAmt)) [Net Amount],                                
--CASE WHEN TransID = 1 THEN (dbo.fnGetRoundedValue(Balance))                                 
--ELSE (dbo.fnGetRoundedValue(Balance * -1)) END Balance,                                
--DATEDIFF(DD,Date,GETDATE()) Ageing                                
-- FROM tblTransPurchaseHeader WHERE VendorID = @PartyID AND Status IN (1,3,5,6,7) AND Balance > 0                                
-- order by CONVERT(date,Date),DocId                                
END                                
IF(@nMode = 4)-- TOP 10 PRODS                                
BEGIN                                
 SELECT TOP 10 [Product Name],dbo.fnGetRoundedValue(SUM(Qty)) Qty,                                
 (dbo.fnGetRoundedValue(SUM(NetAmt))) [Value]  FROM (                                
 select MP.Name [Product Name],SUM(SD.UomQty) Qty,SUM(SD.NetAmt) NetAmt                                
 from tblTransPurchaseHeader SH                                
 JOIN tblTransPurchaseDetail SD ON SD.HID = SH.ID                        
 JOIN tblMasterProduct MP ON MP.ID = SD.ProdId                                
 WHERE SH.VendorID = @PartyID AND TransID = 1 AND Status IN (1,3,5)                                
 GROUP BY MP.Name) as rec  GROUP BY [Product Name] order by SUM(NetAmt) desc                                
 END                                
IF(@nMode = 5)--cheque info                                
BEGIN                                
SELECT PH.PYPrefix DocPrefix,PH.DocId [Doc ID],CONVERT(NVARCHAR,CPM.[DATE],103) AS [Cheque Date],[Cheque/DD Number],                                
(dbo.fnGetRoundedValue(CPM.PYAmt)) [Value]                                
FROM tblPaymentPMDetail CPM                                 
JOIN tblTranPaymentHeader PH ON PH.PYID = CPM.PYID                                
WHERE (CPM.[DATE] <= @F_ED) AND CPM .[Status] IN (1,3) AND CPM.PaymentTermID IN (2) AND PH.AccId = @AccID                                   
END                         
IF(@nMode = 6)-- get ledger data                                
BEGIN                                
--exec uspRepAccountLedger @AccountName,@F_SD,@F_ED                        
--select DS.TransName [Transaction],DocID [Doc ID],CONVERT(nvarchar,FAJ.DocDate,103) Date,FAA.AccountName [Account Name],                        
--(Credit) Credit,(Debit) Debit,Remarks,Narration,STS.Description Status                      
--INTO #TEMP1 from tblFAJournal FAJ                              
--JOIN tblFAAccount FAA ON FAA.FAID = FAJ.AccountID                              
--JOIN tblDocumentSeries DS ON DS.TransID = FAJ.DocPrefix                              
--JOIN tblStatus STS ON STS.ID = FAJ.Status                              
--WHERE FAJ.Status NOT IN (2,4) and FAJ.AccountID = @AccID and FAJ.DocDate BETWEEN @F_SD AND @F_ED                         
                      
--INSERT INTO #TEMPOPEN                      
--exec uspLoadClosingBalance 1,@AccID,@F_SD                      
                      
--SELECT @OPENBAL = Balance,@OPENCRDR = CRDR FROM #TEMPOPEN                      
                      
--INSERT INTO #TEMPCLOSE                      
--exec uspLoadClosingBalance 2,@AccID,@F_ED                      
                      
--SELECT @CLOSEBAL = Balance,@CLOSECRDR = CRDR FROM #TEMPCLOSE                      
                      
--SELECT [Transaction],[Doc ID],Date,[Account Name],dbo.fnGetRoundedValue(Credit) Credit,dbo.fnGetRoundedValue(Debit) Debit,Remarks,Narration,Status FROM (                      
--SELECT 1 SNO,''<label color="brown">Opening Balance</label>'' [Transaction],'''' [Doc ID],'''' Date,'''' [Account Name],(CASE WHEN @OPENCRDR = ''Cr'' then @OPENBAL ELSE 0 END) Credit,                      
--(CASE WHEN @OPENCRDR = ''Dr'' then @OPENBAL ELSE 0 END) Debit,'''' Remarks,'''' Narration,'''' Status                      
--UNION                       
--SELECT 2,* FROM #TEMP1                      
--UNION                       
--select 3,''Total'' [Transaction],''''[Doc ID],'''' [Date],''''[Account Name],dbo.fnGetRoundedValue(sum([Credit])) [Credit],                        
--dbo.fnGetRoundedValue(sum([Debit])) [Debit],'''' [Remarks],'''' [Narration],'''' [Status] from #TEMP1      
--UNION                      
--SELECT 4,''Closing Balance'' [Transaction],'''' [Doc ID],'''' Date,'''' [Account Name],(CASE WHEN @CLOSECRDR = ''Cr'' then @CLOSEBAL ELSE 0 END) Credit,                      
--(CASE WHEN @CLOSECRDR = ''Dr'' then @CLOSEBAL ELSE 0 END) Debit,'''' Remarks,'''' Narration,'''' Status) AS REC                      
--drop table #TEMP1                
exec uspGetFALegderReport 0,@F_SD,@F_ED,@AccID,0,1    
END                     
IF(@nMode = 7)                  
BEGIN                  
SELECT                 
    MonthYear,                 
    SUM(SalesAmount) AS SalesAmount,                  
    SUM(ReturnAmount) AS ReturnAmount,                
    MIN(SaleYear) AS SaleYear,                
    MIN(SaleMonth) AS SaleMonth                
INTO #monthsales1                 
FROM (                  
    SELECT                   
        FORMAT(Date, ''MMM yyyy'') AS MonthYear,                  
        CASE WHEN TransID = 1 THEN SUM(NetAmt) ELSE 0 END AS SalesAmount,                  
        CASE WHEN TransID = 12 THEN SUM(NetAmt) ELSE 0 END AS ReturnAmount,                   
        YEAR(Date) AS SaleYear,                  
        MONTH(Date) AS SaleMonth                  
    FROM tblTransPurchaseHeader                  
    WHERE VendorID = @PartyID AND status IN (1,3,5,6)                  
    GROUP BY FORMAT(Date, ''MMM yyyy''), YEAR(Date), MONTH(Date), TransID                  
) AS rec                  
GROUP BY MonthYear                  
ORDER BY MIN(SaleYear), MIN(SaleMonth);  -- Chronological ordering                
                
-- Declare @MonthCount                
                
SET @MonthCount = (SELECT COUNT(*) FROM #monthsales1);                
-- Final result                
SELECT                 
    upper(MonthYear) MonthYear,                
    SalesAmount,                
    ReturnAmount + '' ('' + Pern + '')'' AS ReturnAmount,                
    DamageAmount                
FROM (                
    SELECT                 
        1 AS Sno,                 
        MonthYear,                
        dbo.fnGetRoundedValue(SalesAmount) AS SalesAmount,                
        dbo.fnGetRoundedValue(ReturnAmount) AS ReturnAmount,                
        dbo.fnGetRoundedValue(CASE WHEN SalesAmount = 0 THEN 0 ELSE (ReturnAmount * 100.0) / SalesAmount END) AS Pern,                    
        dbo.fnGetRoundedValue(0) AS DamageAmount ,SaleYear,SaleMonth                
    FROM #monthsales1                   
    UNION                  
                
    SELECT                 
        2 AS Sno,                
        ''Total'',                
        dbo.fnGetRoundedValue(SUM(SalesAmount)),                 
        dbo.fnGetRoundedValue(SUM(ReturnAmount)),                
        dbo.fnGetRoundedValue(CASE WHEN SUM(SalesAmount) = 0 THEN 0 ELSE (SUM(ReturnAmount) * 100.0) / SUM(SalesAmount) END),                
        dbo.fnGetRoundedValue(0) ,0 SaleYear,0 SaleMonth                 
    FROM #monthsales1                  
    UNION                  
                
    SELECT                 
        3 AS Sno,          
        ''Average'',                
        dbo.fnGetRoundedValue(SUM(SalesAmount) / NULLIF(@MonthCount, 0)),                 
        dbo.fnGetRoundedValue(SUM(ReturnAmount) / NULLIF(@MonthCount, 0)),                
        dbo.fnGetRoundedValue(                
            CASE                 
                WHEN SUM(SalesAmount) = 0 THEN 0                 
                ELSE (SUM(ReturnAmount) / NULLIF(@MonthCount, 0)) / (SUM(SalesAmount) / NULLIF(@MonthCount, 0)) * 100                 
            END                
        ),                
        dbo.fnGetRoundedValue(0)  ,0 SaleYear,0 SaleMonth                
    FROM #monthsales1                  
) AS rec                
ORDER BY Sno desc,SaleYear desc,SaleMonth desc;                
                
DROP TABLE #monthsales1;                
                
END                  
END                                
DROP TABLE #TEMPOPEN,#TEMPCLOSE                      
END',
N'[export] nocount';
GO
/****** uspOtherCollectionDetail ******/
EXEC #Apply07 N'dbo.uspOtherCollectionDetail', 0xAD58BD4D75DFE834D001536C32DF7DB32EF9539CA6F12BDC82FFCE58F3821873, NULL, NULL, 0x0AB7A7B2A598B2F597A0F0D6DD73D9C0F86C5D8EF5CAAFAD5067B6E513982213, 0xE99EB03CCBCAB0CD5E12C4A1919AF819016CE0CDE1A1D97B7BF9B5E6D4B731AE, NULL,
N'--[uspOtherCollectionDetail] 1  
ALTER Proc [dbo].[uspOtherCollectionDetail]  
@CollID INT=null  
AS  
SET NOCOUNT ON;
BEGIN  
SELECT TransName [Trans Name],DocID [Doc ID],[Doc Date],DocRefNo [Doc Ref],OutStandingAmt,Balance,ColValue [Coll Amt],  
AdjAmt [Adjustment Amt],TotalAmtAdj [Total Amt Adjusted],Narration FROM(  
SELECT 1 Indx,DocSeries.TransName,DocSeries.DocPrefix+Convert(NVARCHAR(20),CollDetail.DocValue) AS DocID,  
CONVERT(NVARCHAR(50), CollDetail.Date ,103) as [Doc Date], 
CASE WHEN CollDetail.DocPrefix=6 THEN PR.RefNo WHEN CollDetail.DocPrefix=19 THEN Header.ColDocRefNo  
WHEN CollDetail.DocPrefix=4 THEN Notes.RefNo WHEN CollDetail.DocPrefix=10 THEN Header.ColDocRefNo ELSE ''''  END AS DocRefNo,  
CASE WHEN CollDetail.DocPrefix=6 THEN PR.NetAmount WHEN CollDetail.DocPrefix=19 THEN Header.ColAmt  
WHEN CollDetail.DocPrefix=4 THEN Notes.NoteValue WHEN CollDetail.DocPrefix=10 THEN Header.ColAmt ELSE ''''  END AS OutStandingAmt,  
0.00 AS Balance,CollDetail.ColValue * -1 ColValue,CollDetail.DocID DocID1, CollDetail.DocPrefix,CollDetail.DocValue,  
CASE WHEN CollDetail.DocPrefix=6 THEN PR.Narration WHEN CollDetail.DocPrefix=19 THEN ''''  
WHEN CollDetail.DocPrefix=4 THEN Notes.Narration WHEN CollDetail.DocPrefix=10 THEN '''' ELSE ''''  END AS Narration,  
CollDetail.AdjAmt,CollDetail.TotalAmtAdj * -1 TotalAmtAdj FROM tblTranCollectionDetail AS CollDetail  
LEFT JOIN tblNoteDetails AS Notes ON CollDetail.DocID=Notes.ID  
LEFT JOIN tblTranCollectionHeader AS Header ON CollDetail.DocID=Header.ColID  
LEFT JOIN tblTranPRVoucher AS PR ON CollDetail.DocID=PR.ID  
JOIN tblDocumentSeries AS DocSeries ON CollDetail.DocPrefix=DocSeries.TransID  
WHERE CollDetail.ColID=@CollID AND CollDetail.DocPrefix IN (6,4,19,10)  
UNION ALL  
SELECT 2 Indx,DocSeries.TransName,DocSeries.DocPrefix+Convert(NVARCHAR(20),CollDetail.DocValue) AS DocID,  
CONVERT(NVARCHAR(50), CollDetail.Date ,103),   
CASE WHEN CollDetail.DocPrefix=7 THEN PR.RefNo WHEN CollDetail.DocPrefix=18 THEN Header.PYDocRefNo  
WHEN CollDetail.DocPrefix=5 THEN Notes.RefNo WHEN CollDetail.DocPrefix=11 THEN Header.PYDocRefNo ELSE ''''  END AS DocRefNo,  
CASE WHEN CollDetail.DocPrefix=7 THEN PR.NetAmount WHEN CollDetail.DocPrefix=18 THEN Header.PYAmt  
WHEN CollDetail.DocPrefix=5 THEN Notes.NoteValue WHEN CollDetail.DocPrefix=11 THEN Header.PYAmt ELSE ''''  END AS OutStandingAmt,  
0.00 AS Balance,CollDetail.ColValue,CollDetail.DocID DocID1, CollDetail.DocPrefix,CollDetail.DocValue,  
CASE WHEN CollDetail.DocPrefix=7 THEN PR.Narration WHEN CollDetail.DocPrefix=18 THEN '''' WHEN CollDetail.DocPrefix=5 THEN Notes.Narration  
WHEN CollDetail.DocPrefix=11 THEN '''' ELSE ''''  END AS OutStandingAmt,  
CollDetail.AdjAmt,CollDetail.TotalAmtAdj 
FROM tblTranCollectionDetail AS CollDetail  
LEFT JOIN tblNoteDetails AS Notes ON CollDetail.DocID=Notes.ID  
LEFT JOIN tblTranPaymentHeader AS Header ON CollDetail.DocID=Header.PYID  
LEFT JOIN tblTranPRVoucher AS PR ON CollDetail.DocID=PR.ID  
JOIN tblDocumentSeries AS DocSeries ON CollDetail.DocPrefix=DocSeries.TransID  
WHERE CollDetail.ColID=@CollID AND CollDetail.DocPrefix IN (7,5,18,11)) AS REC  
END',
N'[export] nocount';
GO
/****** uspOtherCollectionHeader ******/
EXEC #Apply07 N'dbo.uspOtherCollectionHeader', 0x05B4AECA2DBA0696ABD83210742130107E89F8642B730678B599756FCDBEBA90, NULL, NULL, 0x5466712C20B89B44D4742121C17A83E91A6820DDB348BC93F5C6C2BFA6531CE2, 0xB4951D24183A7C707EC0D21856E5F65F2B027B6D50383C6539A9F5D242EBC6E4, NULL,
N'ALTER PROC [dbo].[uspOtherCollectionHeader]
@StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2024-01-01'',@ToDate DATE =''2025-09-30''
AS
SET NOCOUNT ON;
BEGIN
DECLARE @Sts AS TABLE(Status INT)
IF(@StatusID = 0)
BEGIN
INSERT INTO @Sts values (1),(3),(5)
END
ELSE
BEGIN 
INSERT INTO @Sts values(@StatusID)
END

SELECT CollHeader.ColID as [CollID],CollHeader.[DocID] AS [Doc ID],FORMAT(ColDate,''dd-MMM-yyyy'') AS [Date],                                                                           
CASE WHEN CollHeader.COLLType=1 then ''From Party'' WHEN CollHeader.COLLType=2 THEN ''From Expense'' ELSE ''From Party For an Expense'' END AS [Type],          
ColDocRefNo AS [Ref No],FAA.AccountName AS [Party Name],Expe.AccountName as [Expense Account],PaymentMode AS [Payment Mode],                                                
[dbo].[fnGetRoundedValue](ColAmt) AS [Collection Amount],[dbo].[fnGetRoundedValue](Balance)as Balance,                            
MBA.AccountName AS [Bank A/C Name],MBA.AccountNo AS [Bank A/C No],case when CPMD.PaymentTermID in (4,5) then BNK.Name ELSE CPMD.BankName END AS [Bank Name],                            
CPMD.BranchName AS [Branch Name],CPMD.IfscCode AS [IFSC Code],    
CASE WHEN CPMD.PaymentTermID IN (2,3) THEN CPMD.[Cheque/DD Number]    
WHEN CPMD.PaymentTermID IN (4,5) THEN CPMD.NeftID ELSE NULL END AS [Cheque/DD/NEFT/CC],    
CASE WHEN CPMD.PaymentTermID IN (2,3) THEN FORMAT(CPMD.Date,''dd-MMM-yyyy'')    
WHEN CPMD.PaymentTermID IN (4,5) THEN FORMAT(CPMD.Date,''dd-MMM-yyyy'') ELSE NULL END AS [Cheque/DD/NEFT Date],    
dbo.fnGetRoundedValue(CollHeader.VisaPern) AS [Card (%)],dbo.fnGetRoundedValue(CollHeader.VisaAmt) AS [Card Amount],
CollHeader.Remarks,CollHeader.Narration,
s.Description AS [Status],    
CASE WHEN ISNULL(us.username,'''')='''' THEN u.username ELSE us.username END as [User Name]                                    
FROM tblTranCollectionHeader AS CollHeader                            
LEFT JOIN tblCollPMDetails AS CPMD ON CPMD.ColID = CollHeader.ColID    
LEFT JOIN tblMasterBankAccount AS MBA ON MBA.FAID = CPMD.BankAccID    
LEFT JOIN tblFAAccount AS FAA ON CollHeader.AccID=FAA.FAID    
LEFT JOIN tblFAAccount AS Expe ON  CollHeader.ExpanceAcc=Expe.FAID
JOIN tblDocumentSeries AS Doc ON CollHeader.DocPrefix=Doc.TransID    
JOIN tblPaymentMode ON CollHeader.ColMode=tblPaymentMode.Id    
JOIN tblUsers AS u ON u.ID = CollHeader.CBy    
LEFT JOIN tblUsers AS us ON us.ID = CollHeader.ClBy    
LEFT JOIN tblStatus as s ON s.ID = CollHeader.Status    
LEFT JOIN tblMasterBank AS BNK ON BNK.ID = MBA.BankID   
WHERE CollHeader.DocPrefix=10 AND (CollHeader.ColDate BETWEEN @FromDate AND @ToDate) AND CollHeader.[Status] IN (SELECT * FROM @Sts)    
ORDER BY CollHeader.DocValue 
END',
N'[export] nocount';
GO
/****** uspOtherCollHeader ******/
EXEC #Apply07 N'dbo.uspOtherCollHeader', 0x21C265E3E4928E4B1AA8DFD02FC954D08A8425147B6439FA8474A932EE7FC616, NULL, NULL, 0xE8D27B8A8908DFE6D57826244B7556AC971C2D78FD4E81AB816A78765A7D419B, 0xA0AB81E33F5C68DC9991B59B761865EE1C972B0A2EB6E6E9AE73E2EB8281E9BB, NULL,
N'--[uspOtherCollHeader] 572     
ALTER PROCEDURE [dbo].[uspOtherCollHeader] --17,23                           
@OtherCollId INT  =NULL                          
AS                            
SET NOCOUNT ON;
BEGIN              
SELECT ISNULL(@OtherCollId,0) AS [Coll ID],DocSeries.DocPrefix+Convert(NVARCHAR(50),CollHeader.DocValue) AS [Doc ID],      
CONVERT(NVARCHAR,CollHeader.ColDate,103) AS [Doc Date], CollHeader.ColDocRefNo [Doc Ref],FAAccount.AccountName [Account Name],    
FAExAcc.AccountName AS [Ex Account Name], PayMode.PaymentMode [Payment Mode], MBO.Name [Branch Name] ,dbo.fnConvertAmountinWords(CollHeader.ColAmt) AS [Amt_in_Words],    
ISNULL(CollHeader.ColAmt,0) AS RecdAmt,  
CASE WHEN COLLType = 1 THEN ''From Party'' WHEN COLLType = 2 THEN ''For Income'' ELSE ''From Party for an Income'' END [PaymentType]  
FROM tblTranCollectionHeader AS CollHeader      
JOIN tblDocumentSeries AS DocSeries  ON CollHeader.DocPrefix=DocSeries.TransID      
LEFT JOIN tblFAAccount AS FAAccount ON CollHeader.AccID=FAAccount.FAID      
LEFT JOIN tblFAAccount AS FAExAcc ON CollHeader.ExpanceAcc=FAExAcc.FAID 
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = CollHeader.BranchID
JOIN tblPaymentMode AS PayMode ON CollHeader.ColMode=PayMode.Id      
WHERE CollHeader.ColID=@OtherCollId      
END',
N'[export] nocount';
GO
/****** uspOtherPaymentDetail ******/
EXEC #Apply07 N'dbo.uspOtherPaymentDetail', 0x4C8164BF687768C0FFDD277D943AB9693F970909321EFE955E1CCF68410C4732, NULL, NULL, 0xCC78F563AB8BC1C0A04CB6A37903BDB736BE3604BB598B3946940CB6506F15CA, 0x310442845CFA0FE04C1971C46D609400128765B6D8E4AD0F912CAD159B0F4E09, NULL,
N'--[uspOtherPaymentDetail] 323
 ALTER Proc [dbo].[uspOtherPaymentDetail]              
@PYId INT=null  
AS  
SET NOCOUNT ON;
BEGIN      
SELECT TransName [Trans Name],DocID [Doc ID],[Doc Date],DocRefNo [Doc Ref],OutStandingAmt,Balance,ColValue [Coll Amt],  
AdjAmt [Adjustment Amt],TotalAmtAdj [Total Amt Adjusted],Narration FROM(                  
SELECT 1 Indx,DocSeries.TransName,DocSeries.DocPrefix+Convert(NVARCHAR(20),PMDetail.DocValue) AS DocID,  
CONVERT(NVARCHAR(50), PMDetail.Date,103) as [Doc Date],  
CASE WHEN PMDetail.DocPrefix=6 THEN PR.RefNo WHEN PMDetail.DocPrefix=19 THEN Header.ColDocRefNo  
WHEN PMDetail.DocPrefix=4 THEN Notes.RefNo WHEN PMDetail.DocPrefix=10 THEN Header.ColDocRefNo ELSE ''''  END AS DocRefNo,   
CASE WHEN PMDetail.DocPrefix=6 THEN PR.NetAmount WHEN PMDetail.DocPrefix=19 THEN Header.ColAmt  
WHEN PMDetail.DocPrefix=4 THEN Notes.NoteValue WHEN PMDetail.DocPrefix=10 THEN Header.ColAmt  
ELSE ''''  END AS OutStandingAmt,0.00 AS Balance,PMDetail.BillPYValue* -1 ColValue,  
CASE WHEN PMDetail.DocPrefix=6 THEN PR.Narration WHEN PMDetail.DocPrefix=19 THEN ''''  
WHEN PMDetail.DocPrefix=4 THEN Notes.Narration WHEN PMDetail.DocPrefix=10 THEN ''''  
ELSE ''''  END AS Narration,PMDetail.AdjAmt,PMDetail.TotalAmtAdj* -1 TotalAmtAdj FROM tblTranPaymentDetail AS PMDetail  
LEFT JOIN tblNoteDetails AS Notes ON PMDetail.DocID=Notes.ID  
LEFT JOIN tblTranCollectionHeader AS Header ON PMDetail.DocID=Header.ColID  
LEFT JOIN tblTranPRVoucher AS PR ON PMDetail.DocID=PR.ID  
JOIN tblDocumentSeries AS DocSeries ON PMDetail.DocPrefix=DocSeries.TransID  
WHERE PMDetail.PYID=@PYId AND PMDetail.DocPrefix IN (6,4,19,10)  
UNION ALL  
SELECT 2 Indx,DocSeries.TransName,DocSeries.DocPrefix+Convert(NVARCHAR(20),CollDetail.DocValue) AS DocID,  
CONVERT(NVARCHAR(50),CollDetail.Date,103),  
CASE WHEN CollDetail.DocPrefix=7 THEN PR.RefNo WHEN CollDetail.DocPrefix=18 THEN Header.PYDocRefNo   
WHEN CollDetail.DocPrefix=5 THEN Notes.RefNo WHEN CollDetail.DocPrefix=11 THEN Header.PYDocRefNo ELSE ''''  END AS DocRefNo,  
CASE WHEN CollDetail.DocPrefix=7 THEN PR.NetAmount WHEN CollDetail.DocPrefix=18 THEN Header.PYAmt  
WHEN CollDetail.DocPrefix=5 THEN Notes.NoteValue WHEN CollDetail.DocPrefix=11 THEN Header.PYAmt ELSE ''''  END AS OutStandingAmt,  
0.00 AS Balance,CollDetail.BillPYValue,  
CASE WHEN CollDetail.DocPrefix=7 THEN PR.Narration WHEN CollDetail.DocPrefix=18 THEN ''''  
WHEN CollDetail.DocPrefix=5 THEN Notes.Narration WHEN CollDetail.DocPrefix=11 THEN '''' ELSE ''''  END AS OutStandingAmt,  
CollDetail.AdjAmt,CollDetail.TotalAmtAdj FROM tblTranPaymentDetail AS CollDetail  
LEFT JOIN tblNoteDetails AS Notes ON CollDetail.DocID=Notes.ID  
LEFT JOIN tblTranPaymentHeader AS Header ON CollDetail.DocID=Header.PYID  
LEFT JOIN tblTranPRVoucher AS PR ON CollDetail.DocID=PR.ID  
JOIN tblDocumentSeries AS DocSeries ON CollDetail.DocPrefix=DocSeries.TransID  
WHERE CollDetail.PYID=@PYId AND CollDetail.DocPrefix IN (7,5,18,11)) AS REC  
END',
N'[export] nocount';
GO
/****** uspOtherPaymentHeader ******/
EXEC #Apply07 N'dbo.uspOtherPaymentHeader', 0xCF22B5EF4375D0AA1BAD296296706F9500E3BE49BFA5D02497D1D43BDFBC5084, NULL, NULL, 0xA965F3FA25455D765EFBDD396575BEED2BC97A710694C695B56FFBD1E0665CB8, 0xD1345365803694A986685D0445592A5582EB8A32A805081258CBAF3AD1449EBF, NULL,
N'ALTER PROC [dbo].[uspOtherPaymentHeader]   
 @StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2024-01-01'',@ToDate DATE =''2025-09-30''  
 AS  
 SET NOCOUNT ON;
BEGIN  
 DECLARE @Sts AS TABLE(Status INT)  
IF(@StatusID = 0)  
BEGIN  
INSERT INTO @Sts values (1),(3),(5)  
END  
ELSE  
BEGIN   
INSERT INTO @Sts values(@StatusID)  
END  
SELECT CollHeader.PYID,CollHeader.DocID AS [Doc ID],FORMAT(PYDate,''dd-MMM-yyyy'') AS [Date],          
CASE WHEN CollHeader.PYType=1 then ''From Party'' WHEN CollHeader.PYType=2 THEN ''From Expense'' ELSE ''From Party For an Expense'' END AS [Type],          
PYDocRefNo AS [Doc Ref No],FAA.AccountName AS [Party Name],EX.AccountName as [Expense Account],          
PaymentMode AS [Payment Mode],[dbo].[fnGetRoundedValue](CollHeader.PYAmt) as [Payment Amount],                                
[dbo].[fnGetRoundedValue](Balance)as Balance,MBA.AccountName AS [Bank A/C Name],MBA.AccountNo AS [Bank A/C No],                          
BNK.Name AS [Bank Name],PMD.BranchName AS [Branch Name],PMD.IfscCode AS [IFSC Code],                          
(CASE WHEN PMD.PaymentTermID IN (2,3) THEN (CASE                          
WHEN LEN(ISNULL(PMD.[Cheque/DD Number],''''))=1 THEN ''00000''+CAST(PMD.[Cheque/DD Number] AS NVARCHAR)                          
WHEN LEN(ISNULL(PMD.[Cheque/DD Number],''''))=2 THEN ''0000''+CAST(PMD.[Cheque/DD Number] AS NVARCHAR)                          
WHEN LEN(ISNULL(PMD.[Cheque/DD Number],''''))=3 THEN ''000''+CAST(PMD.[Cheque/DD Number] AS NVARCHAR)                          
WHEN LEN(ISNULL(PMD.[Cheque/DD Number],''''))=4 THEN ''00''+CAST(PMD.[Cheque/DD Number] AS NVARCHAR)                          
WHEN LEN(ISNULL(PMD.[Cheque/DD Number],''''))=5 THEN ''0''+CAST(PMD.[Cheque/DD Number] AS NVARCHAR)                          
ELSE PMD.[Cheque/DD Number] END) WHEN PMD.PaymentTermID IN (4,5) THEN PMD.NeftID ELSE NULL END) AS [Cheque/DD/NEFT/CC],          
CASE WHEN PMD.PaymentTermID IN (2,3) THEN FORMAT(PMD.Date,''dd-MMM-yyyy'') WHEN PMD.PaymentTermID IN (4,5) THEN FORMAT(PMD.Date,''dd-MMM-yyyy'')                              
ELSE NULL END AS [Cheque/DD/NEFT Date],dbo.fnGetRoundedValue(CollHeader.VisaPern) AS [Card (%)],                      
dbo.fnGetRoundedValue(CollHeader.VisaAmt) AS [Card Amount],PMD.PayAt AS [Pay At],s.Description as [Status],                                            
(CASE WHEN ISNULL(us.username,'''')='''' THEN u.username ELSE us.username END) as [User Name],CollHeader.Remarks,CollHeader.Narration     
FROM tblTranPaymentHeader AS CollHeader      
LEFT JOIN tblPaymentPMDetail AS PMD ON PMD.PYID = CollHeader.PYID      
LEFT JOIN tblMasterBankAccount AS MBA ON MBA.FAID = PMD.BankAccID      
LEFT JOIN tblFAAccount AS FAA ON CollHeader.AccID=FAA.FAID      
LEFT JOIN tblFAAccount AS EX ON  CollHeader.ExpanseAcc=EX.FAID      
JOIN tblDocumentSeries AS Doc ON CollHeader.PYPrefix=Doc.TransID      
LEFT JOIN tblPaymentMode ON CollHeader.PYMode=tblPaymentMode.Id      
LEFT JOIN tblStatus as s ON s.ID = CollHeader.Status      
JOIN tblUsers as u ON u.ID = CollHeader.CBy      
LEFT JOIN tblUsers as us ON us.ID = CollHeader.ClBy      
LEFT JOIN tblMasterBank AS BNK ON BNK.ID = PMD.BankName    
WHERE CollHeader.PYPrefix=11 and CollHeader.PYDate BETWEEN @FromDate AND @ToDate      
AND CollHeader.Status IN (SELECT * FROM @Sts) ORDER BY PYID      
END',
N'[export] nocount';
GO
/****** uspOtherPYHeader ******/
EXEC #Apply07 N'dbo.uspOtherPYHeader', 0xF52713C47296C67FFD2257E2FD525210C5D6B590163ED6DB42E6722A9397FF82, NULL, NULL, 0x481B3EF305ED1C4D7D9B61BBFB528EE0EBB29BFA5E89D67FEB78C02050C1E63B, 0x74BEF7DE9AB69434AF005A5541E20C9AF7798D7F523ABEECF87D1CAE261C763E, NULL,
N'--[uspOtherPYHeader] 323  
ALTER PROCEDURE [dbo].[uspOtherPYHeader] --  10                         
@OtherCollId INT =NULL                         
AS                          
SET NOCOUNT ON;
BEGIN                      
SELECT  ISNULL(@OtherCollId,0) AS [PY ID],DocSeries.DocPrefix+Convert(NVARCHAR(50),PaymentHeader.DocValue) AS [Doc ID],  
CONVERT(NVARCHAR,PaymentHeader.PYDate,103) AS [Doc Date],PaymentHeader.PYDocRefNo [Doc Ref],  
FAAccount.AccountName [Account Name],FAExAcc.AccountName AS [Ex Account Name],  
PayMode.PaymentMode [Payment Mode],MBO.Name [Branch Name],
(CASE WHEN LEN(PYModeDetail.[Cheque/DD Number])=1 THEN ''00000''+CAST(PYModeDetail.[Cheque/DD Number] AS NVARCHAR)  
WHEN LEN(PYModeDetail.[Cheque/DD Number])=2 THEN ''0000''+CAST(PYModeDetail.[Cheque/DD Number] AS NVARCHAR)  
WHEN LEN(PYModeDetail.[Cheque/DD Number])=3 THEN ''000''+CAST(PYModeDetail.[Cheque/DD Number] AS NVARCHAR)  
WHEN LEN(PYModeDetail.[Cheque/DD Number])=4 THEN ''00''+CAST(PYModeDetail.[Cheque/DD Number] AS NVARCHAR)  
WHEN LEN(PYModeDetail.[Cheque/DD Number])=5 THEN ''0''+CAST(PYModeDetail.[Cheque/DD Number] AS NVARCHAR)  
ELSE PYModeDetail.[Cheque/DD Number] END)  AS [ChequeNo],Bankacc.AccountNo,CONVERT(NVARCHAR,PYModeDetail.Date,103) as [ChequeDate],  
dbo.fnConvertAmountinWords(PaymentHeader.PYAmt) AS [Amt_in_Words],ISNULL(PaymentHeader.PYAmt,0) AS RecdAmt,  
(CASE WHEN ISNULL(PYMode,0)=1 THEN ''To Party'' WHEN ISNULL(PYMode,0)=2 THEN ''For Expanse''        
WHEN ISNULL(PYMode,0)=3 THEN ''To Party For An Expanse'' END) AS [PaymentType],PYModeDetail.BankName        
FROM tblTranPaymentHeader AS PaymentHeader  
JOIN tblDocumentSeries AS DocSeries ON PaymentHeader.PYPrefix=DocSeries.TransID  
LEFT JOIN tblFAAccount AS FAAccount ON PaymentHeader.AccID=FAAccount.FAID  
LEFT JOIN tblFAAccount AS FAExAcc ON PaymentHeader.ExpanseAcc=FAExAcc.FAID  
JOIN tblPaymentMode AS PayMode ON PaymentHeader.PYMode=PayMode.Id  
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = PaymentHeader.BranchID
left Join dbo.tblPaymentPMDetail as PYModeDetail on PYModeDetail.PYID = PaymentHeader.PYID  
LEft Join [tblMasterBankAccount] as Bankacc on Bankacc.ID = PYModeDetail.BankAccID  
WHERE PaymentHeader.PYID=@OtherCollId  
END',
N'[export] nocount';
GO
/****** uspPartyInfo ******/
EXEC #Apply07 N'dbo.uspPartyInfo', 0x2C092AAAC13F83196640A43DD22F236D9EC00A079E1B984B078256742E4C5487, NULL, NULL, 0x0DFAD52004B152E13C4057CF75CC2C7221E9CD8280EC82121F5758F49C1542C9, 0x2661A7C443D5E9B106387FE93644CC89B9FD4EC49D072C87CCCC93F34FAF618E, NULL,
N'--uspPartyInfo 88,4
ALTER proc [dbo].[uspPartyInfo]
@PartyID int = 18,@BranchID int = 4
AS
SET NOCOUNT ON;
BEGIN
DECLARE @FAID INT,@Date DATE =GETDATE(),@OSCount int,@LastSaleDate date,@LastCollDate date,
@ACD INT,@FAOpenID int,@OpenBalance decimal(15,4) = 0

CREATE TABLE #OSDetail(OSValue decimal(18,4),CrDr nvarchar(10))

select @FAID = FAID from tblMasterCustomer where ID = @PartyID 

SELECT @OSCount = count(*),@LastSaleDate = MAX(InvDate) FROM tblTranSalesHeader WHERE DocPrefix = 15 and Status in (1,3,5)
and Balance > 0 and CustID = @PartyID

SELECT @LastCollDate = MAX(ColDate) FROM tblTranCollectionHeader WHERE DocPrefix = 19 and Status in (1,3,5)
and Balance > 0 and AccID = @FAID

select @ACD = sum(ageing) / count(ID) from (
SELECT ID,DocID,DATEDIFF(DD,InvDate,ColDate) Ageing FROM (
select SH.ID,SH.DocID,MIN(SH.InvDate) InvDate,(MAX(CH.ColDate)) ColDate from tblTranSalesHeader SH
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID
JOIN tblTranCollectionDetail CD ON CD.DocID = sh.ID
join tblTranCollectionHeader CH ON CH.ColID = CD.ColID
where SH.DocPrefix = 15 and SH.status in (5) and FAID = @FAID and SH.Balance = 0
GROUP BY SH.ID,SH.DocID,sh.NetAmt,sh.Balance) AS REC
) as rec1

insert into #OSDetail
EXEC uspLoadClosingBalance 1,@FAID,@Date

select @FAOpenID = ID from tblYearwiseDocumentSeries where BranchID = @BranchID and @Date between FromDate and ToDate

select @OpenBalance = OpeningBalance from tblFAAccOpening where DocSeriesID = @FAOpenID AND FAID = @FAID

select @OSCount OSCount,FORMAT(@LastSaleDate,''dd/MMM/yyyy'') LastSaleDate,FORMAT(@LastCollDate,''dd/MMM/yyyy'') LastCollDate,
ISNULL(@ACD,0) ACD,dbo.fngetroundedvalue((isnull(OSValue,0) + isnull(@OpenBalance,0))) OSValue,CrDr from #OSDetail
SELECT * from tblMasterCustomer MC
WHERE MC.ID = @PartyID

SELECT * FROM tblImages WHERE FormID = 2 and ID = @PartyID 
drop table #OSDetail
END',
N'[export] nocount';
GO
/****** uspPartyReportData ******/
EXEC #Apply07 N'dbo.uspPartyReportData', 0x2A6B0E20B8FD7AEA6C2C80392E69C4C1C09C1FDC6E0029F25079614CFF35057F, NULL, NULL, 0x63383DDB82562600D11EE0FB68C3EB205077433D023D8ACDB8997D1EEC8DFF0B, 0x2069706BE215C43BDDEC966ABE255DC35BBD26F979DF5DA2F44EE0B06156736D, NULL,
N'--EXEC uspLoadClosingBalance 1,291                        
--uspPartyReportData 1,1,0                      
ALTER PROC [dbo].[uspPartyReportData]                        
@Mode INT,@FAID INT = 0,@PartyType INT = 0                       
AS                        
SET NOCOUNT ON;
BEGIN                       
IF(@Mode = 1)                        
BEGIn                   
if(@FAID = 1)            
BEGIN          
/*  
Here @PartyType we taken as ShowAll condition  
*/  
select 1 PartyType,MC.FAID,MC.ID,Code,MC.Name,((DBO.[fnGetClosingBal](MC.FAID))) CB,            
MCT.Name CustomerType into #CustomerData  
from tblMasterCustomer MC            
LEFT JOIN tblMasterCustomerType MCT ON MCT.ID = MC.CustomerType             
order by MC.Name  
if(@PartyType = 0)  
select * from #CustomerData where CB <> 0 order by Name  
else  
select * from #CustomerData order by Name   
drop table #CustomerData  
END            
ELSE IF(@FAID = 2)            
BEGIN            
select 2 PartyType,FAID,ID,Code,Name,((DBO.[fnGetClosingBal](FAID))) CB,null CustomerType into #vendordata  
from tblMasterVendor                        
order by Name                
if(@PartyType = 0)  
select * from #vendordata where CB <> 0 order by Name  
else  
select * from #vendordata order by Name   
drop table #vendordata  
  
END            
END                        
IF(@Mode = 2)                        
BEGIN                        
CREATE TABLE #tempOS(Balance DECIMAL(25,4),CrDr NVARCHAR(10))                      
INSERT INTO #tempOS                      
EXEC uspLoadClosingBalance 1,@FAID                      
DECLARE @OSBAL DECIMAL(25,4),@CrDr NVARCHAR(10),@Acc INT = 0                      
SELECT  @OSBAL = Balance,@CrDr = CrDr FROM #tempOS                      
                      
IF(@PartyType = 1)                      
BEGIN                      
select @Acc = sum(ageing) / count(ID) from (                              
SELECT ID,DocID,DATEDIFF(DD,InvDate,ColDate) Ageing FROM (                              
select SH.ID,SH.DocID,MIN(SH.InvDate) InvDate,(MAX(CH.ColDate)) ColDate from tblTranSalesHeader SH                       
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID                      
JOIN tblTranCollectionDetail CD ON CD.DocID = sh.ID                              
join tblTranCollectionHeader CH ON CH.ColID = CD.ColID                              
where SH.DocPrefix = 15 and SH.status in (5) and FAID = @FAID and SH.Balance = 0                              
GROUP BY SH.ID,SH.DocID,sh.NetAmt,sh.Balance) AS REC                              
) as rec1                      
select 1 PartyType,FAID,MC.ID,Code,Name,Mob1,Ph1,Email,Billadd1+'' ''+Billadd2+'' ''+Billadd2 [BillingAddress]                      
,Shipadd1+'' ''+Shipadd2+'' ''+Shipadd3 [ShippingAddress],Pincode,ST.StateName,GSTIN,isnull(MC.Rating,0) RatingValue,RT.RatingName,                      
(dbo.fnGetRoundedValue(@OSBAL)) + '' ''+@CrDr  Balance,@CrDr CrDr,@Acc Acc,@OSBAL OSBAL  from tblMasterCustomer MC                      
LEFT JOIN tblGSTStateNameandCode ST ON ST.StateID = MC.StateID                      
LEFT JOIN tblRatings RT ON RT.ID = MC.Rating WHERE FAID = @FAID                      
END                      
ELSE                      
BEGIN                      
select FAID,MC.ID,Code,Name,Mob1,Ph1,Email,Billadd1+'' ''+Billadd2+'' ''+Billadd2 [BillingAddress]                      
,Shipadd1+'' ''+Shipadd2+'' ''+Shipadd3 [ShippingAddress],Pincode,ST.StateName,GSTIN,isnull(MC.Rating,0) RatingValue,RT.RatingName,                      
(dbo.fnGetRoundedValue(@OSBAL)) + '' ''+@CrDr  Balance,@CrDr CrDr,@Acc Acc,@OSBAL OSBAL  from tblMasterVendor MC                      
LEFT JOIN tblGSTStateNameandCode ST ON ST.StateID = MC.StateID                      
LEFT JOIN tblRatings RT ON RT.ID = MC.Rating  WHERE FAID = @FAID                        
END                      
DROP TABLE #tempOS                      
END                      
ELSE IF(@Mode = 3)                        
BEGIN                        
SELECT TransID,TransName [Transaction],DocID [Doc ID],FORMAT(DocDate,''dd-MMM-yyyy'') [Doc Date],                        
(dbo.fnGetRoundedValue(NetAmt)) Value,(dbo.fnGetRoundedValue(Balance)) Balance,                
Ageing,(dbo.fnGetRoundedValue(OtherCharges)) [Other Charges]        
,(dbo.fnGetRoundedValue(DiscountAmt)) DiscountAmt  FROM (                        
SELECT DS.TransID,DS.TransCode TransName,DocID,InvDate DocDate,((NetAmt)) NetAmt,                        
((Balance)) Balance,                        
DATEDIFF(DD,InvDate,GETDATE()) Ageing,OtherChargeAmt OtherCharges,TotalDiscountAmt DiscountAmt FROM tblTranSalesHeader SH                        
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID                        
JOIN tblDocumentSeries DS ON DS.TransID = SH.DocPrefix WHERE FAID = @FAID and status in (1,3,5,6,7)        
UNION                        
SELECT DS.TransID,DS.TransCode,DocID,Date DocDate,((NetAmt)) NetAmt,           
((Balance)) Balance,                        
DATEDIFF(DD,Date,GETDATE()) Ageing,OtherChargeAmt OtherCharges,        
isnull(TotalAddnlDiscAmt,0) + isnull(TotalProdDiscAmt,0) + isnull(TotalTradeDiscAmt,0) DiscountAmt FROM tblTransPurchaseHeader SH                        
JOIN tblMasterVendor MC ON MC.ID = SH.VendorID                        
JOIN tblDocumentSeries DS ON DS.TransID = SH.TransID WHERE FAID = @FAID and status in (1,3,5,6,7)                        
UNION                        
select DS.TransID,DS.TransCode TransName,NS.DocID,ColDate DocDate,((ColAmt)) NetAmt,                        
((Balance)) Balance,                        
DATEDIFF(DD,ColDate,GETDATE()) Ageing,SUM(AdjAmt) OtherCharges,SUM(DiscAmt) DiscAmt from tblTranCollectionHeader NS                        
LEFT JOIN tblTranCollectionDetail ND ON ND.ColID = NS.ColID                
JOIN tblDocumentSeries DS ON DS.TransID = NS.DocPrefix                        
WHERE (AccID = @FAID OR ExpanceAcc = @FAID) and status in (1,3,5)                        
GROUP BY DS.TransID,DS.TransCode,NS.DocID,ColDate,ColAmt,Balance                
UNION                        
select DS.TransID,DS.TransCode TransName,NS.DocID,PYDate DocDate,((PYAmt)) NetAmt,                        
((Balance)) Balance,                        
DATEDIFF(DD,PYDate,GETDATE()) Ageing,SUM(AdjAmt) OtherCharges,SUM(DiscAmt) DiscAmt from tblTranPaymentHeader NS                        
LEFT JOIN tblTranPaymentDetail ND ON ND.PYID = NS.PYID                
JOIN tblDocumentSeries DS ON DS.TransID = NS.PYPrefix                        
WHERE (AccID = @FAID OR ExpanseAcc = @FAID) and status in (1,3,5)                    
GROUP BY DS.TransID,DS.TransCode,NS.DocID,PYDate,PYAmt,Balance                
UNION                        
select DS.TransID,DS.TransCode TransName,DocID,DocDate DocDate,((NoteValue)) NetAmt,                        
((Balance)) Balance,                        
DATEDIFF(DD,DocDate,GETDATE()) Agein,0 OtherChargesg,0 DiscAmt from tblNoteDetails NS                        
JOIN tblDocumentSeries DS ON DS.TransID = NS.TransID                        
WHERE PartyID = @FAID and status in (1,3,5)                        
UNION                        
SELECT DS.TransID,DS.TransCode TransName,DocID,DocDate DocDate,((NetAmount)) NetAmt,                        
((Balance)) Balance,                        
DATEDIFF(DD,DocDate,GETDATE()) Ageing,0 OtherCharges,DiscAmt DiscAmt FROM tblTranPRVoucher SH                        
JOIN tblDocumentSeries DS ON DS.TransID = SH.TransID WHERE (PartyID = @FAID OR FAID = @FAID) and status in (1,3,5)                        
UNION                        
select DS.TransID,DS.TransCode TransName,DocID,DocDate DocDate,((Amount)) NetAmt,((Balance)) Balance,                        
DATEDIFF(DD,DocDate,GETDATE()) Ageing,0 OtherCharges,0 DiscAmt from tblTranContra NS                        
JOIN tblDocumentSeries DS ON DS.TransID = NS.TransID                        
WHERE FromFAID = @FAID and status in (1,3,5)                        
UNION                        
select DS.TransID,DS.TransCode TransName,DocID,DocDate DocDate,((Credit)) NetAmt,((Balance)) Balance,                        
DATEDIFF(DD,DocDate,GETDATE()) Ageing,0 OtherCharges,0 DiscAmt from tblfajournal NS                        
JOIN tblDocumentSeries DS ON DS.TransID = NS.TransID                        
WHERE AccountID = @FAID and NS.DocPrefix = 9 and status in (1,3,5)) AS REC                        
ORDER BY DocDate  desc                      
END                        
END',
N'[export] nocount';
GO
/****** uspPaymentDetail ******/
EXEC #Apply07 N'dbo.uspPaymentDetail', 0x7DE9D29CF6E5147776D2DF862FB2EE908D51A3A303105020FC9459D589387914, NULL, NULL, 0xBE4E46BD16777B48A1C736E0BF2074CA23F9DF2DFB00C4F4BC27B8CF0378034F, 0xBE2BCB031BA8E449F4AE5039D436E663F5113D3C10D2CC62F9DC05D0F539919D, NULL,
N'ALTER PROC [dbo].[uspPaymentDetail]  
@PYID INT = 132  
AS  
SET NOCOUNT ON;
BEGIN  
SELECT Header.DocID [Pay Doc ID],MC.Name [Vendor Name],Doc.TransName AS [Doc Type],(CONVERT(NVARCHAR,Doc1.DocPrefix) + CONVERT(NVARCHAR,PaymentDetail.DocValue)) AS [Doc ID],                        
CONVERT(NVARCHAR,PaymentDetail.Date,103) AS [Doc Date],    
(CASE WHEN PaymentDetail.DocPrefix=1 OR PaymentDetail.DocPrefix=12 THEN (SELECT RefNo FROM tblTransPurchaseHeader WHERE ID=PaymentDetail.DocID)                
WHEN PaymentDetail.DocPrefix=5 THEN (SELECT RefNo FROM tblNoteDetails WHERE ID=PaymentDetail.DocID)                
WHEN PaymentDetail.DocPrefix=18 THEN (SELECT PYDocRefNo FROM tblTranPaymentHeader WHERE PYID=PaymentDetail.DocID)                                
ELSE ''''  END) AS [Doc ref],  
dbo.fnGetRoundedValue(CASE WHEN PaymentDetail.DocPrefix=1 OR PaymentDetail.DocPrefix=12 THEN (SELECT NetAmt FROM tblTransPurchaseHeader WHERE ID=PaymentDetail.DocID)                
WHEN PaymentDetail.DocPrefix=5 THEN (SELECT NoteValue FROM tblNoteDetails WHERE ID=PaymentDetail.DocID)    
WHEN PaymentDetail.DocPrefix=18 THEN (SELECT PYAmt FROM tblTranPaymentHeader WHERE PYID=PaymentDetail.DocID)                                   
ELSE 0.00  END) AS [Doc Value],[dbo].[fnGetRoundedValue](PaymentDetail.BillPYValue) AS [Collected Amount],                        
[dbo].[fnGetRoundedValue]((AdjAmt)) AS [Adjust Amount],CASE WHEN ISNULL(DiscPercentage,'''') LIKE ''%[%]''                  
THEN CAST([dbo].[fnGetRoundedValue](REPLACE(DiscPercentage,''%'','''')) AS NVARCHAR)+''%'' ELSE [dbo].[fnGetRoundedValue]((DiscPercentage)) END AS [Discount %],                  
[dbo].[fnGetRoundedValue]((DiscAmt)) AS [Discount Amount],Case(FullyAdj) WHEN 0 THEN ''No'' WHEN 1 THEN ''Yes''  END AS [Fully Adjusted],                                                
[dbo].[fnGetRoundedValue]((FullyAdjAmt)) AS [Fully Adjust Amount],[dbo].[fnGetRoundedValue]((TotalAmtAdj)) AS [Total Adjust Amount]                                                
FROM tblTranPaymentDetail AS PaymentDetail    
LEFT JOIN tblTransPurchaseHeader AS BillHeader ON BillHeader.ID=PaymentDetail.DocID    
LEFT JOIN tblTranPaymentHeader AS Header ON PaymentDetail.PYID=Header.PYID   
LEFT JOIN tblDocumentSeries AS Doc1 On PaymentDetail.DocPrefix=Doc1.TransID    
LEFT JOIN tblDocumentSeries AS Doc  On PaymentDetail.DocPrefix=Doc.TransID    
join tblMasterVendor MC ON MC.FAID = Header.AccID
WHERE PaymentDetail.PYID=@PYID   
END',
N'[export] nocount';
GO
/****** uspPaymentHeader ******/
EXEC #Apply07 N'dbo.uspPaymentHeader', 0x73459A21ED140B4B909352AECB638ED5155943D31675C6E1D0B555FF04006FA5, NULL, NULL, 0xFD823D480876E17881B77FCF1D83BD09DB6CD6ED85B012902CDF84CF32FFC5AD, 0xDFB261775A8F60C0914373C724C9C8D450C2F92446F466EBC20493E896781A57, NULL,
N'ALTER PROC [dbo].[uspPaymentHeader]
@StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2025-04-01'',@ToDate DATE =''2025-09-30''
AS
SET NOCOUNT ON;
BEGIN
DECLARE @Sts AS TABLE(Status INT)
IF(@StatusID = 0)
BEGIN
INSERT INTO @Sts values (1),(3),(5)
END
ELSE
BEGIN 
INSERT INTO @Sts values(@StatusID)
END
SELECT PaymentHeader.PYID,PaymentHeader.[DocID] AS [Doc ID],FORMAT(PYDate,''dd-MMM-yyyy'') AS [Doc Date],                                    
Vendor.code AS [Vendor Code],Vendor.name AS [Vendor Name],Vendor.mob1 AS [Mob No],    
PaymentHeader.PYDocRefNo AS [Ref No],PaymentMode AS [Payment Mode],[dbo].[fnGetRoundedValue]((PaymentHeader.PYAmt)) AS [Payment Amount],    
[dbo].[fnGetRoundedValue]((PaymentHeader.Balance))as [Balance],Bank.AccountName AS [Bank A/C Name],    
Bank.AccountNo AS [Bank A/C No],BNK.Name AS [Bank Name],Bank.BranchName AS[Branch Name],Bank.Ifsccode AS [IFSC Code],    
(CASE WHEN PaymentHeader.PYMode = 2 THEN CAST(PayD.ChequeRefNoWithChequeNo AS NVARCHAR)    
WHEN PaymentHeader.PYMode = 3 THEN CAST(PayD.[Cheque/DD Number] AS NVARCHAR)    
WHEN PaymentHeader.PYMode IN (4,5) THEN CAST(PayD.NeftID AS NVARCHAR)    
END) AS [Cheque/DD/NEFT],CASE WHEN PayD.PaymentTermID IN (2,3,4,5) THEN FORMAT(PayD.Date,''dd-MMM-yyyy'')    
ELSE NULL END AS [Cheque/DD/NEFT Date],dbo.fnGetRoundedValue(PaymentHeader.VisaPern) AS [Card (%)],    
dbo.fnGetRoundedValue(PaymentHeader.VisaAmt) AS [Card Amount],    
s.Description as [Status],ISNULL((SELECT dbo.fnGetRoundedValue(sum(AdjAmt)) FROM tblTranPaymentDetail WHERE PYID=PaymentHeader.PYID),dbo.fnGetRoundedValue(''0.000000000'')) AS [Adjustment Amount],                      
u.username as [User Name]    
FROM tblTranPaymentHeader AS PaymentHeader    
LEFT JOIN tblMasterVendor AS Vendor ON PaymentHeader.AccID=Vendor.FAID    
LEFT JOIN tblDocumentSeries AS Doc On PaymentHeader.PYPrefix=Doc.TransID    
LEFT JOIn tblPaymentMode On PaymentHeader.PYMode=tblPaymentMode.Id    
LEFT JOIN tblStatus as s ON s.ID=PaymentHeader.Status    
LEFT JOIN tblUsers u ON u.ID = PaymentHeader.CBy    
JOIN tblPaymentPMDetail AS PayD ON PayD.PYID = PaymentHeader.PYID    
LEFT JOIN tblMasterBankAccount AS Bank ON Bank.FAID = PayD.BankAccID      
LEFT JOIN tblMasterChequeBook AS chek ON chek.BankAccountID =Bank.ID    
LEFT JOIN tblMasterBank AS BNK ON BNK.ID = Bank.Bankid    
WHERE PaymentHeader.PYDate BETWEEN @FromDate AND @ToDate AND PaymentHeader.Status IN (select * from @Sts)    
AND PaymentHeader.PYPrefix = 18   
GROUP BY  PaymentHeader.PYID,PaymentHeader.[DocID],Vendor.code,Vendor.name,Vendor.mob1,PaymentHeader.PYDocRefNo ,PYDate,    
Bank.AccountName,Bank.AccountNo,Bank.BranchName,PaymentHeader.PYMode,PayD.[Cheque/DD Number],PayD.NeftID,    
BNK.Name,PayD.ChequeRefNoWithChequeNo,Bank.Ifsccode,PYDocRefNo,PaymentMode,UDFDocId,s.Description,u.username,    
PaymentHeader.PYAmt,PaymentHeader.Balance,PaymentHeader.VisaPern,PaymentHeader.VisaAmt,PayD.PayAt,PayD.PaymentTermID,PayD.Date  
END',
N'[export] nocount';
GO
/****** uspProductBatchHistoryDetail ******/
EXEC #Apply07 N'dbo.uspProductBatchHistoryDetail', 0xDAD9AB4CAF8F9FA6DFF6E3C5B1B52D4876F56564BDA56A363CAB6039B1132F13, NULL, NULL, 0x91BB647DDEE877821DEC8CD6E9D27E4D64F296F1D89D7A5C8285D266573377F8, 0xA5E6BCA24DD870528BA2EDDA8A6BFBEFD6E6FCFAB9C812A1EF6FA841C2A99CE2, NULL,
N'--uspProductBatchHistoryDetail 632
ALTER PROC [dbo].[uspProductBatchHistoryDetail]               
@ProdID INT = 318    
AS            
SET NOCOUNT ON;
BEGIN            
SET DATEFORMAT dmy;                  
SELECT   
    MP.Code,  
    MP.Name,  
    MBO.Name AS Branch,  
    DS.TransName [Transaction],  
    FORMAT(TransDate,''dd/MMM/yyyy'') [Date],  
    BatchNumber [Batch Number],  
    FORMAT(PKDDate,''dd/MMM/yyyy'') AS [PKD],  
    FORMAT(ExpiryDate,''dd/MMM/yyyy'') AS [Expiry],  
    dbo.fnGetRoundedValue(ISNULL(PV.PurchasePrice,0)) AS [Purchase Price],  
    dbo.fnGetRoundedValue(ISNULL(PV.SalesPrice,0)) AS [Sales Price],  
    dbo.fnGetRoundedValue(ISNULL(PV.ECP,0)) AS ECP,  
    dbo.fnGetRoundedValue(ISNULL(PV.SPLPrice,0)) AS [SPL Price],  
    dbo.fnGetRoundedValue(ISNULL(PV.MRP,0)) AS [MRP Excl],  
    dbo.fnGetRoundedValue(ISNULL(PV.MRPONPrice,0)) AS [MRP Incl],  
    dbo.fnGetRoundedValue(ISNULL(PV.ReturnPrice,0)) AS [Return Price],    
    dbo.fnGetRoundedValue(ISNULL(RecdQty,0)) AS [Recd Qty],  
    dbo.fnGetRoundedValue(ISNULL(RecdFreeQty,0)) AS [Recd Free Qty],  
    dbo.fnGetRoundedValue(ISNULL(RecdDmgQty,0)) AS [Recd Dmg Qty],    
    dbo.fnGetRoundedValue(ISNULL(ActualQty,0)) AS [Actual Qty],  
    dbo.fnGetRoundedValue(ISNULL(ActualFreeQty,0)) AS [Actual Free Qty],  
    dbo.fnGetRoundedValue(ISNULL(ActualDmgQty,0)) AS [Actual Dmg Qty],    
    dbo.fnGetRoundedValue(ISNULL(InvoiceQty,0)) AS [Invoice Qty],  
    dbo.fnGetRoundedValue(ISNULL(InvoiceFreeQty,0)) AS [Invoice Free Qty],  
    dbo.fnGetRoundedValue(ISNULL(InvoiceDmgQty,0)) AS [Invoice Dmg Qty],    
    dbo.fnGetRoundedValue(ISNULL(PRQty,0)) AS [PR Qty],  
    dbo.fnGetRoundedValue(ISNULL(PRFreeQty,0)) AS [PR Free Qty],  
    dbo.fnGetRoundedValue(ISNULL(PRDmgQty,0)) AS [PR Dmg Qty],   
    dbo.fnGetRoundedValue(ISNULL(SRQty,0)) AS [SR Qty],  
    dbo.fnGetRoundedValue(ISNULL(SRFreeQty,0)) AS [SR Free Qty],  
    dbo.fnGetRoundedValue(ISNULL(SRDmgQty,0)) AS [SR Dmg Qty],  
    dbo.fnGetRoundedValue(ISNULL(InvenoryAdjQty,0)) AS [Inv Adj Qty],  
    dbo.fnGetRoundedValue(ISNULL(InvenoryAdjFreeQty,0)) AS [Inv Adj Free],  
    dbo.fnGetRoundedValue(ISNULL(InvenoryAdjDmgQty,0)) AS [Inv Adj Dmg],  
    dbo.fnGetRoundedValue(ISNULL(InvenoryConvQty,0)) AS [Inv Conv Qty],  
    dbo.fnGetRoundedValue(ISNULL(InvenoryConvFreeQty,0)) AS [Inv Conv Free],  
    dbo.fnGetRoundedValue(ISNULL(InvenoryConvDmgQty,0)) AS [Inv Conv Dmg],  
    dbo.fnGetRoundedValue(ISNULL(StkInQty,0)) AS [StkIn Qty],  
    dbo.fnGetRoundedValue(ISNULL(StkInFreeQty,0)) AS [StkIn Free Qty],  
    dbo.fnGetRoundedValue(ISNULL(StkInDmgQty,0)) AS [StkIn Dmg Qty],  
    dbo.fnGetRoundedValue(ISNULL(StkOutQty,0)) AS [StkOut Qty],  
    dbo.fnGetRoundedValue(ISNULL(StkOutFreeQty,0)) AS [StkOut Free Qty],  
    dbo.fnGetRoundedValue(ISNULL(StkOutDmgQty,0)) AS [StkOut Dmg Qty],  
    dbo.fnGetRoundedValue(SUM(isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0))) AS [VLS Qty],
    dbo.fnGetRoundedValue(ISNULL(PV.TaxValue,0)) AS [Tax Pern]  
FROM tblProductInventory PV  
JOIN tblMasterProduct MP ON MP.ID = PV.ProdID  
JOIN tblDocumentSeries DS ON DS.TransID = PV.TransID  
JOIN tblMasterBranchOffice MBO ON MBO.ID = PV.BranchID  
LEFT JOIN tblVanLoadingSlipDetail VLD ON VLD.InventoryID = PV.InventoryId
WHERE PV.ProdID = @ProdID  
GROUP BY MP.Code,MP.Name,MBO.Name,DS.TransName,TransDate,BatchNumber,PKDDate,ExpiryDate,PV.PurchasePrice,
PV.SalesPrice,PV.ECP,PV.SPLPrice,PV.MRP,PV.MRPONPrice,PV.ReturnPrice,RecdQty,RecdFreeQty,RecdDmgQty,
ActualQty,ActualFreeQty,ActualDmgQty,InvoiceQty,InvoiceFreeQty,InvoiceDmgQty,PRQty,PRFreeQty,PRDmgQty,
SRQty,SRFreeQty,SRDmgQty,InvenoryAdjQty,InvenoryAdjFreeQty,InvenoryAdjDmgQty,InvenoryConvQty,InvenoryConvFreeQty,
InvenoryConvDmgQty,StkInQty,StkInFreeQty,StkInDmgQty,StkOutQty,StkOutFreeQty,StkOutDmgQty,PV.TaxValue
ORDER BY TransDate;  
END',
N'[export] nocount';
GO
/****** uspProductBatchHistoryHeader ******/
EXEC #Apply07 N'dbo.uspProductBatchHistoryHeader', 0x34484852B273D9F4580063214F2C41781B3A88AB454914164DAF485EB03ECA8B, 0x079BB028199F8F8ECDE73C42888C09415F859D0EBCF1481C05521F31350B4992, NULL, 0xDDF9A11E7E9B0A4FBEA2BBB55364693664882855ED7E21023E64608A523EAE02, 0x89B21D42655D64F2EF3873A81BF6ED034DF4B7721D1850FD9A6CD3F8BE407AA4, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspProductBatchHistoryHeader]    
 @ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255) = ''''    
 AS    
 SET NOCOUNT ON;
BEGIN    
declare @StrQuery nvarchar(max) = ''''        
 set @StrQuery = ''     
select MP.ID ProductID,MP.Code,MP.Name,MF.Name [Mfr Name],MB.Name Brand,MC.Name Category,    
dbo.fngetroundedvalue(sum(ISNULL(PV.ActualQty,0))) [Actual Qty],
dbo.fngetroundedvalue((ISNULL([VLS Closing],0))) [VLS Closing],
dbo.fngetroundedvalue(sum(ISNULL(PV.ActualFreeQty,0))) [Actual Free Qty],    
dbo.fngetroundedvalue(sum(ISNULL(PV.ActualDmgQty,0))) [Actual Dmg Qty] from tblMasterProduct MP    
LEFT join tblProductInventory PV ON PV.ProdID = MP.ID    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID    
JOIN tblMasterCategory MC ON MC.ID = MP.CategoryID
LEFT JOIN vVLSQty ViewVLS ON ViewVLS.ProductID = MP.ID
WHERE MP.ACTIVE IN (0,1) ''    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ManufName,'''')='''' THEN '''' ELSE '' AND MF.ID IN (SELECT * from dbo.fnSplitString (  @ManufName ,'''',''''))'' END)             
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BrandName,'''')='''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString (   @BrandName ,'''',''''))'' END)                
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CategoryName,'''')='''' THEN '''' ELSE '' AND MC.ID IN (SELECT * from dbo.fnSplitString (   @CategoryName ,'''',''''))'' END)         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ProductName,'''')='''' THEN '''' ELSE '' AND MP.ID IN (SELECT * from dbo.fnSplitString (   @ProductName ,'''',''''))'' END)       
SET @StrQuery = @StrQuery +  '' group by MP.ID,MP.Code,MP.Name,MF.Name,MB.Name,MC.Name,[VLS Closing] order BY MP.Name ''    
EXEC sys.sp_executesql @StrQuery, N''@ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255)'', @ManufName, @BrandName, @CategoryName, @ProductName    
 END',
N'[06] nocount';
GO
/****** uspProductReportData ******/
EXEC #Apply07 N'dbo.uspProductReportData', 0x86B74C2DA8B6AD5C9C48D9F77AEB75626FF8D165AD93FB68A2A32AF134CEFFED, NULL, NULL, 0xB2B78848E70CB2F808AB5BD8BADE94FDB53104612566CE15A4197EF4C465AEE2, 0xC993B7CC31755DFB56A40640AA198C3A86CE8AA105ED94B2D5991A4000BD926D, NULL,
N'--EXEC uspLoadClosingBalance 1,291                                      
--uspProductReportData 1,102                
ALTER PROC [dbo].[uspProductReportData]                                      
@Mode INT,@ProductID INT = 0                                    
AS                                      
SET NOCOUNT ON;
BEGIN                                      
IF(@Mode = 1)                                      
BEGIN        
/*    
Here @ProductID we taken as ShowAll condition    
*/    
select MP.ID,MP.Code,MP.Name,dbo.funTwoDecimalRoundOff(isnull(ActualQty,0)) ActualQty,dbo.funTwoDecimalRoundOff(isnull(ActualDmgQty,0)) ActualDmgQty,                  
MF.Name Manuf,MB.Name Brand,MC.Name Category,dbo.funTwoDecimalRoundOff(isnull(MP.MRP,0)) MRP               
from tblMasterProduct MP                                    
LEFT JOIN vProdInventory PV ON PV.ProdID = MP.ID                    
join tblMasterBrand MB ON MB.ID = MP.BrandID                  
join tblMasterCategory MC ON MC.ID = MP.CategoryID                  
join tblMasterManufacturer MF ON MF.ID = MP.MfrID    
WHERE isnull(ActualQty,0) > (CASE WHEN @ProductID = 0 THEN 0 ELSE -1 END)    
order by MP.Name                  
END                                      
IF(@Mode = 2)                                      
BEGIN                                      
select MP.ID,MP.Code,MP.Name,MP.HSNCode,MB.Name Brand,MC.Name Category,MF.Name Manuf,MT.TaxName,(MP.PurchasePrice) PurchasePrice,                                    
(MP.SalesPrice) SalesPrice,dbo.fnGetRoundedValue((MP.ECP)) ECP,dbo.fnGetRoundedValue((MP.MRP)) MRP,                                    
dbo.fnGetRoundedValue((MP.SPLPrice)) SPLPrice,dbo.fnGetRoundedValue((MP.ReturnPrice)) ReturnPrice,                              
(isnull(ActualQty,0)) ActualQty,                              
(isnull(ActualValue,0)) ActualValue ,(isnull(ActualDmgQty,0)) ActualDmgQty,                              
(isnull(ActualDmgValue,0)) ActualDmgValue,(isnull(ActualFreeQty,0)) ActualFreeQty,
BU.Name[BaseUom],dbo.fnGetRoundedValue(MP.BaseCR)[BaseUomQty],PU.Name[PurchaseUom], dbo.fnGetRoundedValue(MP.PurchaseCR)[PurchaseUomQty],
SU.Name[SalesUom],dbo.fnGetRoundedValue(MP.SalesCR)[SalesUomQty],RU.Name[ReportingUom],dbo.fnGetRoundedValue(MP.ReportingCR)[ReportingUomQty]
from tblMasterProduct MP                                    
LEFT JOIN vProdInventory PV ON PV.ProdID = MP.ID                                    
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID                                    
JOIN tblMasterCategory MC ON MC.ID = MP.CategoryID                                    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID                                    
JOIN tblMasterTax MT ON MT.TaxID = MP.PurchaseTaxID    
JOIN tblMasterUOM BU on BU.ID = MP.BaseUomID
JOIN tblMasterUOM PU on PU.ID = MP.PurchaseUomID
JOIN tblMasterUOM SU on SU.ID = MP.SalesUomID
JOIN tblMasterUOM RU on RU.ID = MP.ReportingUomID
where MP.ID = @ProductID                                    
END                                    
ELSE IF(@Mode = 3)                                      
BEGIN                                      
SELECT TransID, TransName [Transaction],DocID [Doc ID],FORMAT(DocDate,''dd-MMM-yyyy'') [Doc Date],Party,                                      
((Qty)) Qty,((FreeQty)) [Free Qty],                
((DmgQty)) [Dmg Qty],                      
((isnull(nullif(GrossAmt,0) / nullif((isnull(Qty,0) + isnull(DmgQty,0)),0),0))) [Unit Price],                                
((GrossAmt)) Value,            
((MRP)) MRP FROM (                
select TransID,TransName,DocID,DocDate,Party,sum(Qty) Qty,sum(FreeQty) FreeQty,sum(DmgQty) DmgQty,            
sum(GrossAmt) GrossAmt,CDate,MRP from (                
SELECT DS.TransID,DS.TransCode TransName,DocID,InvDate DocDate,MC.Name Party,                
CASE WHEN SD.QtyType = 1 THEN (case when SH.DocPrefix = 15 THEN sum(AdjustQty) * -1 ELSE sum(AdjustQty) END) ELSE 0 END Qty,                
CASE WHEN SD.QtyType = 2 THEN (case when SH.DocPrefix = 15 THEN sum(AdjustQty) * -1 ELSE sum(AdjustQty) END) ELSE 0 END FreeQty,                
CASE WHEN SH.TRANSACTIONTYPE = 3 THEN (case when SH.DocPrefix = 15 THEN sum(AdjustQty) * -1 ELSE sum(AdjustQty) END) ELSE 0 END DmgQty,      
(case when SH.DocPrefix = 15 THEN sum(SD.GrossAmt) * -1 ELSE sum(SD.GrossAmt) END) GrossAmt,SH.CDate,SD.DetailMRP MRP            
FROM tblTranSalesHeader SH                                      
join tblTranSalesdetail SD ON SD.InvID = SH.ID                                    
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID                          
join tblMasterProduct MP ON MP.ID = SD.ProdID                         
JOIN tblDocumentSeries DS ON DS.TransID = SH.DocPrefix WHERE SD.ProdID = @ProductID and status in (1,3,5,6,7) --AND SH.TransactionType IN (1,2)                            
group by SH.DocPrefix,DS.TransID,DS.TransCode,DocID,InvDate,MC.Name,SH.CDate,SD.QtyType,SH.TRANSACTIONTYPE,SD.DetailMRP) as Sale                 
group by CDate,TransID,TransName,DocID,DocDate,Party,MRP                
UNION                                    
SELECT SH.TransID,DS.TransCode,DocID,Date DocDate,MC.Name Party,      
(case when SH.TransID = 12 THEN sum(AdjQty) * -1 ELSE sum(AdjQty) END) Qty,                      
(case when SH.TransID = 12 THEN sum(AdjFreeQty) * -1 ELSE sum(AdjFreeQty) END) UomFreeQty,      
(case when SH.TransID = 12 THEN sum(AdjDmgQty) * -1 ELSE sum(AdjDmgQty) END) UomDamageQty,            
(case when SH.TransID = 12 THEN sum(SD.GrossAmt) * -1 ELSE sum(SD.GrossAmt) END) NetAmt,SH.CDate,SD.UomMRP MRP                      
FROM tblTransPurchaseHeader SH                                      
join tblTransPurchaseDetail SD ON SD.HID = SH.ID                                    
JOIN tblMasterVendor MC ON MC.ID = SH.VendorID                            
join tblMasterProduct MP ON MP.ID = SD.ProdID                          
JOIN tblDocumentSeries DS ON DS.TransID = SH.TransID WHERE SD.ProdID = @ProductID and status in (1,3,5,6)                                      
group by SH.TransID,DS.TransCode,DocID,Date,MC.Name,SH.CDate,SD.UomMRP                                    
UNION      
select TransID,TransCode,DocID,DocDate,Party,SUM(Qty) Qty,SUM(ActualFreeQty) ActualFreeQty,SUM(ActualDmgQty) ActualDmgQty,      
SUM((Qty + ActualDmgQty) * ActualPurPrice) NetAmt,CDate,MRP      
from (      
SELECT DS.TransID,DS.TransCode,DocID,InventoryDate DocDate,null Party,sum((SD.ActualQty - SD.Orgqty) * isnull(MP.BaseCR,1)) Qty,      
sum((isnull(SD.ActualFreeQty,0) - SD.OrgFreeQty) * isnull(MP.BaseCR,1)) ActualFreeQty,                      
sum((isnull(SD.ActualDmgQty,0) - SD.OrgDmgQty) * isnull(MP.BaseCR,1)) ActualDmgQty,      
sum(SD.GrossAmt) NetAmt,SH.CDate,0 MRP,isnull(SD.ActualPurPrice,0) ActualPurPrice FROM tblInventoryHeader SH                                      
join tblInventoryDetail SD ON SD.InventoryID = SH.InventoryID                            
join tblMasterProduct MP ON MP.ID = SD.ProdID                          
JOIN tblDocumentSeries DS ON DS.TransID = SH.TransID            
--left join tblProductInventory PV ON PV.InventoryId = SD.NewBatchID            
WHERE SD.ProdID = @ProductID and status in (1,3,5)                                      
group by DS.TransID,DS.TransCode,DocID,InventoryDate,SH.CDate,SD.ActualPurPrice--,PV.MRPONPrice              
) as invent group by TransID,TransCode,DocID,DocDate,Party,CDate,MRP      
) AS REC                                      
ORDER BY DocDate desc,CDate ASC                                    
END                                      
END',
N'[export] nocount';
GO
/****** uspProductWiseCustomerWiseSalesDetail ******/
EXEC #Apply07 N'dbo.uspProductWiseCustomerWiseSalesDetail', 0x6C3746021369729129C3067FD2F66937570605F3E714F3A6FB21149FFB453944, 0x29B3CCF99A6BFB5DC8567D204EB63B785EA57BED291A82E449D4A95C7159BB4B, NULL, 0x3E70399749A18F3C303F1E221D79B165735B459FEAEAC5D9DC885496C90E7A27, 0x7C175D35377204515760E24A4774FA53E9261575524CADFC92A3EA88606E4354, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspProductWiseCustomerWiseSalesDetail]        
@ProductID int = 123,@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255) = '''',@BeatName NVARCHAR(255) = '''',      
@SalesmanName NVARCHAR(255) = '''',@CustomerName NVARCHAR(255) = '''',@CustomerType NVARCHAR(255) = '''',@Ratings NVARCHAR(255)='''', @FromDate DATE = ''2025-07-01'',      
@ToDate DATE = ''2025-08-30''         
AS        
SET NOCOUNT ON;
BEGIN        
declare @StrQuery nvarchar(max) = ''''        
set @StrQuery = '' SELECT MP.Name [Product Name],(tsh.DocId) [Doc ID],            
FORMAT(TSH.InvDate,''''dd-MMM-yyyy'''') as [Doc Date],TSH.DocRef as [Ref No],mb.name [Beat Name],sm.name [Salesman Name],MC.Name as [Customer Name],mct.Name [Customer Type]      
,RT.Ratingname Ratings,         
dbo.fnGetRoundedValue(sum(TSD.UomQty * MP.BaseCR)) as [Qty],dbo.fnGetRoundedValue(sum(TSD.NetAmt)) as [Net Amount]             
FROM tblTranSalesHeader TSH             
JOIN tblTranSalesDetail TSD ON TSD.InvId = TSH.ID            
LEFT JOIN tblMasterCustomer MC ON MC.ID = TSH.CustId            
LEFT JOIN tblMasterProduct MP ON MP.ID = TSD.ProdId            
LEFT JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID            
LEFT JOIN tblMasterBeat MB ON MB.ID = TSH.BeatID        
LEFT JOIN tblMasterSalesman SM ON SM.ID = TSH.SalesmanID        
left join tblMasterCustomerType as mct on mct.ID=MC.CustomerType       
LEFT JOIN tblRatings AS RT ON RT.ID = MC.Rating       
WHERE TSH.DocPrefix = 15 AND Status IN (1,3,5) and TSD.ProdID =  @ProductID ''       
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)                  
  
    
      
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND MC.ID IN (SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)                            
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)                
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND SM.ID IN (SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)             
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND MCT.ID IN (SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)                
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RT.ID IN (SELECT * from dbo.fnSplitString(  @Ratings ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + '' group by MC.ID,MC.Name,TSH.DocId,TSH.InvDate,TSH.DocRef,mb.name,sm.name,mct.Name,RT.Ratingname,MP.Name ''      
EXEC sys.sp_executesql @StrQuery, N''@ProductID int, @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @ProductID, @ManufName, @BrandName, @CategoryName, @ProductName, @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @FromDate, @ToDate      
end',
N'[06] nocount';
GO
/****** uspProductWiseCustomerWiseSalesHeader ******/
EXEC #Apply07 N'dbo.uspProductWiseCustomerWiseSalesHeader', 0x9900975696200DFDA54A6326D7FCFBB3FFB080BE744ED3BEC05C47B77CA5E658, 0x48735B04293FA7BB84D513116F362AE856941E7B546E845A5F769F48E6B3012A, NULL, 0xD1C36215EA028E1061D4D4EB2142592324947B3A8998E84618A4CAE57103B422, 0x8CD116CEEB2DDF0B195405F79390239A54F7BEA12E9E6B82DEF9273A10A7F6F8, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspProductWiseCustomerWiseSalesHeader]      
@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255) = '''',@BeatName NVARCHAR(255) = '''',    
@SalesmanName NVARCHAR(255) = '''',@CustomerName NVARCHAR(255) = '''',@CustomerType NVARCHAR(255) = '''',@Ratings NVARCHAR(255)='''', @FromDate DATE = ''2025-07-01'',    
@ToDate DATE = ''2025-08-30''       
AS    
SET NOCOUNT ON;
BEGIN    
declare @StrQuery nvarchar(max) = ''''      
set @StrQuery = ''select ProdID ProductID,[Mfr Name],[Brand Name],[Category Name],[Product Name]      
,COUNT([Inv Count]) as [Inv Count],dbo.fnGetRoundedValue(SUM([Total Qty])) AS [Total Qty],dbo.fnGetRoundedValue(SUM([Net Amt])) [Net Amount] from (      
SELECT MP.ID AS ProdID,MF.Name as  [Mfr Name] ,      
MB.Name [Brand Name],PHL.Name [Category Name],mp.Name as [Product Name],(tsh.ID) [Inv Count],      
SUM(TSD.UomQty * MP.BaseCR) as [Total Qty],sum(TSD.NetAmt) as [Net Amt]      
FROM tblTranSalesHeader TSH      
JOIN tblTranSalesDetail TSD ON TSD.InvId = TSH.ID      
JOIN tblMasterCustomer MC ON MC.ID = TSH.CustId      
JOIN tblMasterProduct MP ON MP.ID = TSD.ProdId      
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID      
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID      
JOIN tblMasterCategory PHL ON PHL.ID = MP.CategoryID      
left join tblMasterCustomerType as mct on mct.ID=MC.CustomerType     
LEFT JOIN tblRatings AS RT ON RT.ID = MC.Rating     
LEFT JOIN TBLMASTERBEAT Beat ON Beat.ID = TSH.BeatID    
LEFT JOIN tblMasterSalesman SM ON SM.ID = TSH.SalesManID    
WHERE TSH.DocPrefix = 15 AND Status IN (1,3,5) ''    
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (TSH.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)                  
  
    
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerName,'''')='''' THEN '''' ELSE '' AND MC.ID IN(SELECT * from dbo.fnSplitString(  @CustomerName ,'''',''''))'' END)                          
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BeatName,'''')='''' THEN '''' ELSE '' AND Beat.ID IN(SELECT * from dbo.fnSplitString(  @BeatName ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@SalesmanName,'''')='''' THEN '''' ELSE '' AND SM.ID IN(SELECT * from dbo.fnSplitString(  @SalesmanName ,'''',''''))'' END)           
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CustomerType,'''')='''' THEN '''' ELSE '' AND MCT.ID IN(SELECT * from dbo.fnSplitString(  @CustomerType ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@Ratings,'''')='''' THEN '''' ELSE '' AND RT.ID IN(SELECT * from dbo.fnSplitString(  @Ratings ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ManufName,'''')='''' THEN '''' ELSE '' AND MF.ID IN(SELECT * from dbo.fnSplitString(  @ManufName ,'''',''''))'' END)           
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BrandName,'''')='''' THEN '''' ELSE '' AND MB.ID IN(SELECT * from dbo.fnSplitString(  @BrandName ,'''',''''))'' END)              
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CategoryName,'''')='''' THEN '''' ELSE '' AND PHL.ID IN(SELECT * from dbo.fnSplitString(  @CategoryName ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ProductName,'''')='''' THEN '''' ELSE '' AND MP.ID IN(SELECT * from dbo.fnSplitString(  @ProductName ,'''',''''))'' END)       
SET @StrQuery = @StrQuery + '' group by MP.ID,MF.ID,MF.Name,mp.Name,tsh.ID,MB.Name,PHL.Name) as nk      
group by ProdID,[Mfr Name],[Product Name],[Brand Name],[Category Name]''    
EXEC sys.sp_executesql @StrQuery, N''@ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @BeatName NVARCHAR(255), @SalesmanName NVARCHAR(255), @CustomerName NVARCHAR(255), @CustomerType NVARCHAR(255), @Ratings NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @ManufName, @BrandName, @CategoryName, @ProductName, @BeatName, @SalesmanName, @CustomerName, @CustomerType, @Ratings, @FromDate, @ToDate    
END',
N'[06] nocount';
GO
/****** uspProdwiseDatewiseclosingDetail ******/
EXEC #Apply07 N'dbo.uspProdwiseDatewiseclosingDetail', 0xE7DF7076991C1878FE311E86EFCFC2DE00E7A9E98BBE133B2E93C9580A3DD282, NULL, NULL, 0xC0D78819F3B6B173622B8DC0932793709740C17A3CB8FBF5D55358289931F3FA, 0x06FFAB3EA67CBC6FA0C0C022F3350C06747DD5A3D8941FF9AE3478DB7022F30E, NULL,
N'ALTER proc [dbo].[uspProdwiseDatewiseclosingDetail]
@ProdID INT = 0,@FilterMfrID nvarchar(255) = '''',@FilterBrandID nvarchar(255) = '''',
@FilterCategoryID nvarchar(255) = '''',@FilterProdID nvarchar(255) = '''',@QtyorValue INT = 2,    
@FromDate DATE = ''2026-10-01'',@ToDate DATE = ''2026-10-06'' 
as
SET NOCOUNT ON;
begin
SET DATEFORMAT dmy;            
    
CREATE TABLE #Temp( Serial INT IDENTITY,Date DATE,OpeningStock DECIMAL(25,6),PQty DECIMAL(25,6),PRQty DECIMAL(25,6),        
SaleQty DECIMAL(25,6),SRQty DECIMAL(25,6),AdjQty DECIMAL(25,6),ConQty DECIMAL(25,6),RepackQty DECIMAL(25,6),        
StockINQty DECIMAL(25,6),StockOUTQty DECIMAL(25,6),ClosingStock DECIMAL(25,6))            
DECLARE @ProdCode nvarchar(255),@ProdName nvarchar(255)     
select @ProdName = Name,@ProdCode = Code from tblMasterProduct where ID=@ProdID
    
DECLARE @DateCount INT=(SELECT DATEDIFF(DAY,@FromDate,@Todate)),@DateSerial INT=1            
INSERT INTO #Temp (Date)VALUES(CAST(@FromDate AS DATE))            
WHILE @DateCount>0            
BEGIN            
INSERT INTO #Temp (Date)VALUES(CAST(DATEADD(DAY,@DateSerial,@FromDate)AS DATE))            
SET @DateCount=@DateCount-1            
SET @DateSerial=@DateSerial+1            
END            
DECLARE @Serail INT=1,@Count INT=(SELECT COUNT(*) FROM #Temp)            
WHILE @Count >0            
BEGIN            
DECLARE @TempDate DATE =(SELECT Date FROM #Temp WHERE Serial =@Serail)            
DECLARE @TempOpeningStock DECIMAL(25,6),@TempGRNStock DECIMAL(25,6),@TempPRStock DECIMAL(25,6),@TempSalesStock DECIMAL(25,6),            
@TempSRStock DECIMAL(25,6),@TempAdjStock DECIMAL(25,6),@TempConverStock DECIMAL(25,6),@TempRepackStock DECIMAL(25,6),@ClosingStock DECIMAL(25,6)            
,@TempStockIN DECIMAL(25,6),@TempStockOUT DECIMAL(25,6)        
SELECT @TempOpeningStock=OpeningStock,@TempGRNStock=PQty,@TempPRStock=PRQty,@TempSalesStock=SaleQty,            
@TempSRStock=SRQty,@TempAdjStock=AdjQty,@TempConverStock=ConQty,@TempRepackStock=RepackQty,@ClosingStock=ClosingQty,        
@TempStockIN = StockINQty,@TempStockOUT = StockOUTQty        
FROM dbo.fnGetProdStockMovementValues(@ProdID,@TempDate,NULL,2,@QtyorValue)            
UPDATE #Temp            
SET OpeningStock=ISNULL(@TempOpeningStock,0),PQty=@TempGRNStock,PRQty=@TempPRStock,SaleQty=@TempSalesStock,SRQty=@TempSRStock,            
AdjQty=@TempAdjStock,ConQty=ISNULL(@TempConverStock,0),RepackQty=ISNULL(@TempRepackStock,0),ClosingStock=@ClosingStock ,        
StockINQty = ISNULL(@TempStockIN,0),StockOUTQty = ISNULL(@TempStockOUT,0)           
WHERE Serial =@Serail            
SET @Serail = @Serail +1            
SET @Count = @Count-1            
END            
SELECT          
@ProdCode as  [Product Code],@ProdName as  [Product Name],CONVERT(NVARCHAR,Date,103)AS [DATE],          
(OpeningStock) AS [Opening Stock],(PQty) AS [Purchase Qty],            
(PRQty) AS [Purchase Return Qty],(SaleQty) AS [Sales Qty],            
(SRQty) AS [Sales Return Qty],(AdjQty) AS [Adjust Qty],            
(ConQty) AS [Conversion Qty],(RepackQty) AS [Repacking Qty],            
(StockINQty) AS [Stock IN Qty],(StockOUTQty) AS [Stock OUT Qty],        
(ClosingStock) AS [Closing Stock Qty] FROM #Temp            
DROP TABLE #Temp      
end',
N'[export] nocount';
GO
/****** uspProdwiseDatewiseclosingHeader ******/
EXEC #Apply07 N'dbo.uspProdwiseDatewiseclosingHeader', 0x0671D05B0BC3618249DD186BBFB5DFECA9653FB7686429B567185EEF7A7EC137, NULL, NULL, 0xCD501FBE668F2A4C72134138D240CE68FFDEE4D75870DA731F9161352B4DD3A3, 0x646DBD8A4C13CA72890FC468669B3393615667EDE656FDC61F38B2C2E4200437, NULL,
N'--exec uspProdwiseDatewiseclosingHeader ''1,2,4''
ALTER proc [dbo].[uspProdwiseDatewiseclosingHeader]
@MfrID nvarchar(255) = '''',@BrandID nvarchar(255) = '''',@CategoryID nvarchar(255) = '''',@ProdID nvarchar(255) = '''',
@QtyorValue INT = 1 ,@FromDate DATE = ''2026-10-01'',@ToDate DATE = ''2026-10-06''  
as
SET NOCOUNT ON;
begin
CREATE TABLE #Temp(Serial INT IDENTITY,ProdID INT,[Product Code] NVARCHAR(255),[Product Name] NVARCHAR(255),
[Mfr Name] NVARCHAR(255),[Brand Name] NVARCHAR(255),[Category Name] NVARCHAR(255),   
OpeningStock DECIMAL(25,6),PQty DECIMAL(25,6),PRQty DECIMAL(25,6),SaleQty DECIMAL(25,6),SRQty DECIMAL(25,6),AdjQty DECIMAL(25,6),ConQty DECIMAL(25,6),RepackQty DECIMAL(25,6),        
StockINQty DECIMAL(25,6),StockOUTQty DECIMAL(25,6),ClosingStock DECIMAL(25,6))        
    
INSERT INTO #Temp(ProdID,[Product Code],[Product Name],[Mfr Name],[Brand Name],[Category Name])    
select DISTINCT MP.ID,MP.Code,MP.Name,MF.Name,MB.Name,MC.Name from tblMasterProduct MP    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID
JOIN tblMasterCategory MC ON MC.ID = MP.CategoryID
where (@MfrID = '''' OR MfrID IN (SELECT * FROM string_split(@MfrID,'',''))) AND     
(@BrandID = '''' OR BrandID IN (SELECT * FROM string_split(@BrandID,'',''))) AND     
(@CategoryID = '''' OR MP.CategoryID IN (SELECT * FROM string_split(@CategoryID,'','')))  AND
(@ProdID = '''' OR MP.ID IN (SELECT * FROM string_split(@ProdID,'','')))  

DECLARE @Serail INT=1,@Count INT=(SELECT COUNT(*) FROM #Temp)                  
WHILE @Count > 0                  
BEGIN     
DECLARE @TempProdID INT =(SELECT ProdID FROM #Temp WHERE Serial =@Serail)      
DECLARE @TempOpeningStock DECIMAL(25,6),@TempGRNStock DECIMAL(25,6),@TempPRStock DECIMAL(25,6),@TempSalesStock DECIMAL(25,6),            
@TempSRStock DECIMAL(25,6),@TempAdjStock DECIMAL(25,6),@TempConverStock DECIMAL(25,6),@TempRepackStock DECIMAL(25,6),@ClosingStock DECIMAL(25,6)            
,@TempStockIN DECIMAL(25,6),@TempStockOUT DECIMAL(25,6)        
SELECT @TempOpeningStock=OpeningStock,@TempGRNStock=PQty,@TempPRStock=PRQty,@TempSalesStock=SaleQty,            
@TempSRStock=SRQty,@TempAdjStock=AdjQty,@TempConverStock=ConQty,@TempRepackStock=RepackQty,@ClosingStock=ClosingQty,        
@TempStockIN = StockINQty,@TempStockOUT = StockOUTQty        
FROM dbo.fnGetProdStockMovementValues(@TempProdID,@FromDate,@ToDate,1,@QtyorValue)      
    
UPDATE #Temp                  
SET OpeningStock=ISNULL(@TempOpeningStock,0),PQty=ISNULL(@TempGRNStock,0),PRQty=ISNULL(@TempPRStock,0),                  
SaleQty=ISNULL(@TempSalesStock,0),SRQty=ISNULL(@TempSRStock,0),AdjQty=ISNULL(@TempAdjStock,0),                  
ConQty=ISNULL(@TempConverStock,0),RepackQty=ISNULL(@TempRepackStock,0),StockINQty =ISNULL(@TempStockIN,0),        
StockOUTQty = ISNULL(@TempStockOUT,0),ClosingStock = ISNULL(@ClosingStock,0)  WHERE Serial =@Serail                  
SET @Serail = @Serail + 1                  
SET @Count = @Count - 1                  
END                  
alter table #temp drop column serial    
SELECT * FROM #Temp    
    
DROP TABLE #Temp   
end',
N'[export] nocount';
GO
/****** uspPurchaseBillBody ******/
EXEC #Apply07 N'dbo.uspPurchaseBillBody', 0x94B100BAE1997C922BFCA242A615ACEADEACE01B592FA3DC3A9A1E472BFABD45, NULL, NULL, 0x1FEE83255633F9418100BD65BEB45522EB68869201D0358AE19C95094B217771, 0x5C42C45001B458C21A000E6A335F1218DAB035735E94910E97A1AE41428B1887, NULL,
N'--uspPurchaseBillBody 755      
ALTER PROC [dbo].[uspPurchaseBillBody]      
@BillId NVARCHAR(255) = 365      
AS      
SET NOCOUNT ON;
BEGIN      
SELECT ProdID,Serial [Temp Serial],(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],                                
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],                                
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],                                
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],                                
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],                                
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],                                
SUM([GCESS Amount]  + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #Tax                                                    
FROM                                                                  
(                        
SELECT SRI.ProdID,SRI.Serial,--SRI.[Gross Amount],                                                              
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],                  
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],                                                                  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],                  
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],                                                                  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],                  
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],                  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],                  
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],                  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],                  
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],                                                       
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],                  
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],                                   
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],                  
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],                    
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],                                                      
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]                                 
FROM                                                                  
(                        
SELECT * FROM                        
(                        
SELECT Temp.ProdID,Temp.Serial,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],                                                           
Temp.TaxName AS TaxName,                                                
SUM(Temp.TaxValue) AS [TaxValue]--, SUM(Temp.[Gross Amount]) AS [Gross Amount]                                                              
FROM                                                                  
(                                                                  
SELECT GSTInfo.ProdID,GSTInfo.SERIAL,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,                                                        
CASE                                                          
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''                                                           
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''                                                                  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''                                                        
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''                                 
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''                                               
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''                                                
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''                                 
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''                                                          
END AS [GST Comp]--, GSTInfo.GrossAmt AS [Gross Amount]                        
FROM tblTransGSTInfo AS GSTInfo                        
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID                        
WHERE TransIdentID = @BillId AND (TransID=1 or TransID=12)                        
) Temp                        
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.ProdID,Temp.Serial                                                    
) src                        
PIVOT                                                                  
(                                                                  
SUM([TaxValue])                                                                  
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])                                                                
 
   
) piv                                                                  
) AS SRI                                                                  
) AS RAM                                                              
GROUP BY ProdID,Serial      
         
              
SELECT IDENTITY (INT, 1, 1) AS NEW_ID,Bill.ProdID,prod.Code AS [Product Code],prod.Name as [Product Name],prod.HSNCode AS [HSN Code],                      
Uom.Name as [Uom Name],Bill.BatchNo as [Batch No],                                
Convert(nvarchar,Bill.PKD,103) as [PKD Date],Convert (nvarchar,Bill.Expiry,103) as [Expiry Date],                                      
Bill.UomQty as [Uom Qty],Bill.UomFreeQty as [Uom Free Qty],Bill.UomDamageQty as [Uom Damage Qty],                                
Bill.UomPurchasePrice as [Uom Purchase Price],Bill.UomSalePrice AS [Uom Sales Price],Bill.UomECP as [Uom ECP],                                
Bill.UomMRP as [Uom MRP],Bill.UomSPLPrice AS [Uom SPL Price],Bill.PurchasePrice AS [Base Purchase Price],                                
Bill.SalePrice AS [Base Sales Price],Bill.ECP AS [Base ECP Price],Bill.MRP AS [Base MRP Price],                                
Bill.SPLPrice AS [Base SPL Price],Tax.TaxName as [Tax Name],TaxType.TaxTypeName as [TaxType Name],                               
Bill.[Tax%] as [Tax Percentage],Bill.GoodsAmt as [Goods Amount],                    
CAST(dbo.fnGetRoundedValue(Bill.[ProdDisc%]) AS NVARCHAR(255)) AS [Product Discount %],                          
Bill.ProdDiscAmt as [Product Disc Amt],Bill.[TradeDisc%] as [Trade Discount %],          
Bill.TradeDiscAmt [Trade Discount],      
Bill.[AddnlDisc%] as [Addnl Discount %],      
BILL.AddnlDiscAmt [Addnl Discount],      
Bill.GrossAmt as [Gross Amount],                         
Bill.GrossAmt as [Tax Value],Bill.TaxAmt as [Tax Amount],                                
Bill.NetAmt as [Net Amount],Row_number() OVER (order by Bill.HID) as [Serial No],            
Loc.Name AS [Location Name],RSN.Name [Reason Name],prod.Remarks AS [Remark1],prod.WebOrder AS [Web Order],            
(Bill.UomQty /  NULLIF(ISNULL(Bill.UOMCF,1), 0)) AS [Base Qty],                                                
(Bill.UomQty /  NULLIF(ISNULL(Bill.UOMCF,1), 0)) AS [Deft_S_UOM_Qty],              
(Bill.UomQty /  NULLIF(ISNULL(Bill.UOMCF,1), 0)) AS [Base Uom Price], Bill.UomPurchasePrice AS [Uom Price],isnull(Bill.UOMCF,1) AS [UOM CF],                                                    
isnull(Bill.UOMCF,1) AS [Deft_S_UOM_CF],                                           
Bill.UomPurchasePrice + (Bill.UomPurchasePrice * (Bill.[Tax%] / 100)) as [Rate],                                                    
Bill.GrossAmt / NULLIF(Bill.UomQty,0) as [Per Piece Exclusive Price],                                                    
Bill.NetAmt / NULLIF(Bill.UomQty,0) as [Per Piece Inclusive Price], Bill.UomMRP [MRP Price],            
((Bill.GoodsAmt) * (Bill.[ProdDisc%]) /100) +       
ISNULL(((((Bill.GoodsAmt) - ((Bill.GoodsAmt) * (Bill.[ProdDisc%]) /100)) * Bill.[TradeDisc%]) / 100),0) +       
ISNULL(((((Bill.GoodsAmt) - ((Bill.GoodsAmt) * (Bill.[ProdDisc%]) /100)) * Bill.[AddnlDisc%]) / 100),0) as [Total Disc Amt]            
INTO #BILL            
From dbo.TBLTRANSPURCHASEDETAIL as Bill            
JOIN tblMasterProduct as prod ON prod.ID=Bill.ProdId               
JOIN dbo.tblMasterUom as Uom on Uom.ID = Bill.UomId            
Join dbo.tblMasterTax as Tax on Bill.TaxID = Tax.TaxID            
Join dbo.tblMasterTaxType as TaxType on Bill.TaxTypeId  = TaxType.TaxTypeID            
LEFT JOIN tblMasterLocation AS Loc ON Loc.ID=Bill.LocationID      
LEFT JOIN tblMasterReason AS RSN ON RSN.ID=Bill.ReasonId      
WHERE Bill.HID = @BillId order by Bill.Serial                    
           
            
SELECT [Product Code],[Product Name],[HSN Code],[Uom Name],[Batch No],[PKD Date],[Expiry Date] [EXP Date],                  
[Uom Qty],[Uom Free Qty],[Uom Damage Qty],[Uom Purchase Price],[Uom Sales Price],[Uom ECP],[Uom MRP],                  
[Uom SPL Price],[Base Purchase Price],[Base Sales Price],[Tax Name],[TaxType Name],[Tax Percentage],[Goods Amount],                  
[Product Discount %],[Product Disc Amt],[Trade Discount %],[Trade Discount],[Addnl Discount %],[Addnl Discount],                  
[Gross Amount],[Tax Value],[Tax Amount],[Net Amount],NEW_ID AS [Serial],            
[Location Name],[Reason Name],[Remark1],[Web Order],[Base Qty],[Deft_S_UOM_Qty],[Base Uom Price],[Uom Price],[UOM CF],            
[Deft_S_UOM_CF],[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price],[MRP Price],[Total Disc Amt],            
dbo.fnGetRoundedValue(sum([CGST %])) [CGST %],            
dbo.fnGetRoundedValue(sum([CGST Amount])) [CGST Amount],            
dbo.fnGetRoundedValue(sum([SGST %])) [SGST %],            
dbo.fnGetRoundedValue(sum([SGST Amount])) [SGST Amount],            
dbo.fnGetRoundedValue(sum([UTGST %])) [UTGST %],dbo.fnGetRoundedValue(sum([UTGST Amount])) [UTGST Amount],            
dbo.fnGetRoundedValue(sum([GCESS %])) [GCESS %], dbo.fnGetRoundedValue(SUM([GCESS Amount])) [GCESS Amount],            
dbo.fnGetRoundedValue(sum([IGST %])) [IGST %],            
dbo.fnGetRoundedValue(sum([IGST Amount])) [IGST Amount],            
dbo.fnGetRoundedValue(sum([ICESS %])) [ICESS %],dbo.fnGetRoundedValue(sum([ICESS Amount])) [ICESS Amount],            
dbo.fnGetRoundedValue(sum(TX.[GUOM %])) [GUOM %],dbo.fnGetRoundedValue(sum(TX.[GUOM Amount])) [GUOM Amount],            
dbo.fnGetRoundedValue(sum(TX.[IUOM %])) [IUOM %],dbo.fnGetRoundedValue(sum(TX.[IUOM Amount])) [IUOM Amount],            
dbo.fnGetRoundedValue(sum(TX.[Cumulative CESS Amount])) [Cumulative CESS Amount]  FROM #BILL BILL                  
LEFT JOIN #Tax TX ON TX.ProdID = BILL.ProdID                  
GROUP BY [Product Code],[Product Name],[HSN Code],[Uom Name],[Batch No],[PKD Date],[Expiry Date],                  
[Uom Qty],[Uom Free Qty],[Uom Damage Qty],[Uom Purchase Price],[Uom Sales Price],[Uom ECP],[Uom MRP],                  
[Uom SPL Price],[Base Purchase Price],[Base Sales Price],[Tax Name],[TaxType Name],[Tax Percentage],[Goods Amount],                  
[Product Discount %],[Product Disc Amt],[Trade Discount],[Addnl Discount],[Gross Amount],[Tax Value],[Tax percentage],[Tax Amount],[Net Amount],[Serial No],NEW_ID,            
[Location Name],[Reason Name],[Remark1],[Web Order],[Base Qty],[Deft_S_UOM_Qty],[Base Uom Price],[Uom Price],[UOM CF],            
[Deft_S_UOM_CF],[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price],[MRP Price],[Total Disc Amt], [Trade Discount %],[Addnl Discount %]           
order by [Serial]      
DROP TABLE #Tax,#BILL      
END',
N'[export] nocount';
GO
/****** uspPurchaseBillHeader ******/
EXEC #Apply07 N'dbo.uspPurchaseBillHeader', 0x1E465459ABE6A0F8A3210F47FE273163F87B6AE6F27E37E744E88D24AB69AA9C, NULL, NULL, 0xD9751C4121F3F357242ED0DD61A4666D1C72BE9222D49F6AD895AF6720319A0B, 0xD5EB759533748A88B6A4FF36BFBFACE9DC102A288C4A2EC4BC7943971C311BDA, NULL,
N'ALTER proc [dbo].[uspPurchaseBillHeader]
@BillID INT = 73           
AS
SET NOCOUNT ON;
BEGIN
--Payment Mode                    
 Declare @BillPaymode nvarchar(1000)           
 Select @BillPaymode = Coalesce (@BillPaymode + '', '', '''') + mode.PaymentMode From dbo.tblTran_Sale_Bill_PaymentDetail as BS                      
 left Join dbo.tblPaymentMode as mode on mode.Id = BS.PayModeId where InvId = @BillID and TransId = 18 Group by mode.PaymentMode                      
 --Cash Balance-----          
 DeClare @Amt DECIMAL (25,6), @Recdamt DECIMAL (25,6)          
  Select @Amt=SUM(Amt),@Recdamt = SUM(RecdAmt)  From dbo.tblTran_Sale_Bill_PaymentDetail as BS          
 where InvId = @BillID and TransId = 18          
    
SELECT Bill.ID As [Bill ID],CONVERT(nvarchar,Bill.Date,103) as [Doc Date],  
Isnull(CONVERT(nvarchar(5),Bill.MDate,108),CONVERT(nvarchar(5),Bill .CDate,108)) as [Time],    
Doc.TransName as [Trans Name],Bill.DocId as [Doc ID],Bill.UDFDocId [UDN Doc ID],UDN.DocName AS [UDN Name],Vendor.name as [Party Name],    
Vendor.code as [Party Code],Vendor.mob1 as [Party Prim Mobile No],  
Vendor.ph1 as [Party Prim Phone No],Vendor.email as [Email ID],  
Vendor.billadd1 AS [Party Bill Address 1],Vendor.billadd2 as [Party Bill Address 2],Vendor.billadd3 as [Party Bill Address 3],          
Vendor.billadd1+Vendor.billadd2+Vendor.billadd3 as [Party Full Address],  
Vendor.shipadd1 AS [Party Ship Address 1],Vendor.shipadd2 as [Party Ship Address 2],Vendor.shipadd3 as [Party Ship Address 3],  
Vendor.ContactPerson [Contact Person],Vendor.pincode [Party PinCode],Vendor.GSTIN AS [Party GSTIN],  
Vendor.AadharNo AS [Party Aadhar Number],Vendor.PANNumber AS [Party PAN No],Vendor.FSSAINo AS [Party FSSAI No],     
Bill.RefNo as [Doc Ref],  
--PGrp.ProductGroupName as [Prod Group Name],          
Tax.TaxTypeName as [TaxType Name],Vendor.OSValue [Party Outstanding value],  
--paymodeBill.PaymentMode AS [Payment Mode],            
isnull(@BillPaymode ,''CREDIT'') as [Payment Mode],  CreditTermBill.Name as [Payment Term],            
Convert (nvarchar,Bill.PaymentDate,103) as [CreditTerm Date],Bill.VehicleNo as [Vehicle No],          
MBO.Name as [Branch Name],SUM(Detail.UomQty) As [Total Qty],          
SUM(Detail.UomFreeQty) As [Total Free Qty],SUM(Detail.UomDamageQty) As [Total Damage Qty],  
SUM(Detail.UomQty) As [Deft_S_UOM_Total_Qty],   
Bill.Frieght as [Frieght Amount],Bill.[OtherCharge%] as [OtherCharge Percentage],Bill.OtherChargeAmt as [OtherCharge Amount],    
Bill.[TradeDisc%] as [Trade Discount Percentage],  
Bill.[AddnlDisc%] as [Addnl Discount Percentage],  
Bill.TotalProdDiscAmt as [T.Product Discount Amount],  
Bill.TotalTradeDiscAmt as [T.Trade Discount Amount],Bill.TotalAddnlDiscAmt as [T.Addnl Discount Amount],          
(Bill.TotalProdDiscAmt + Bill.TotalTradeDiscAmt + Bill.TotalAddnlDiscAmt) AS [T.Discount Amount],  
dbo.fnGetRoundedValue(Bill.TotalAddnlDiscAmt)+'' (''+dbo.fnGetRoundedValue(Bill.[AddnlDisc%])+''%)'' [Addnl Disc Pern Amt],      
dbo.fnGetRoundedValue(Bill.TotalTradeDiscAmt)+'' (''+dbo.fnGetRoundedValue(Bill.[TradeDisc%])+''%)''[Trade Disc Pern Amt], 
0 [Adjust Amount],Bill.WriteOffAmt as [Write Off Amount],Bill.RoundOffAmt as [Round Off Amount],  
Bill.NetAmt+(@Recdamt-@Amt) as [Received Amount],  
@Recdamt-@Amt AS [Cash Balance],    
Bill.GrossAmt + (Bill.TotalProdDiscAmt + Bill.TotalTradeDiscAmt + Bill.TotalAddnlDiscAmt) [Goods Amount],  
Bill.GrossAmt as [T.Gross Amount],Bill.TaxAmt as [T.Total Tax Amount],Bill.NetAmt as [Rounded Net Amount],   
CH.VisaPern as [Visa %],((Bill.NetAmt * CH.VisaPern) / 100) AS [Visa Amt],(Bill.NetAmt + ((Bill.NetAmt * CH.VisaPern) / 100)) as [All Incl],       
Bill.Balance AS [Balance Amount],Bill.NetAmt as [Aft Adj NetAmt],        
dbo.fnConvertAmountinWords(Bill.NetAmt) AS [Amt_in_Words],UserTab.username as [User Name],
convert(nvarchar(255),MAX(Detail.Serial)) + '' / '' + convert(nvarchar(255),dbo.fnGetRoundedValue(SUM(Detail.UomQty))) as [Tot Count Qty],        
TCSTaxPern [TCS %],TCSTaxAmt [TCS Amt],isnull(TDSAmount,0) TDSAmount,Bill.Remarks,Bill.Narration,RTNTYPE.Name [Return Type]  
FROM dbo.tblTransPurchaseHeader AS Bill          
JOIN dbo.tblTransPurchaseDetail as Detail on Bill.ID = Detail.HID  
LEFT JOIN tblMasterProduct AS Prod ON Prod.ID = Detail.ProdId   
JOIN TBLMASTERBRANCHOFFICE MBO ON MBO.ID = Bill.BranchID
LEFT JOIN dbo.tblDocumentSeries AS Doc ON Bill.TransID = Doc.TransID                                              
LEFT JOIN dbo.tblMasterVendor AS Vendor ON Bill.VendorID = Vendor.ID                                            
LEFT JOIN dbo.tblMasterTaxType as Tax on Bill.TaxTypeId = Tax.TaxTypeID                         
LEFT JOIN dbo.tblMasterProductGroup as PGrp on Bill.ProdGroupID = PGrp.ID                                                                                 
LEFT JOIN dbo.tblMasterTaxType as TaxType on TaxType.TaxTypeID = Bill.taxtypeid                                                                                 
LEFT JOIN dbo.tblPaymentMode as paymode on paymode.Id = Bill.PaymentModeID                                     
--LEFT JOIN dbo.tblPaymentMode as paymodeBill on paymodeBill.Id = Bill.PaymentModeId                                         
LEFT JOIN dbo.tblMasterCreditTerm as CreditTermBill on CreditTermBill.ID = Bill.PaymentTermID                                        
JOIN dbo.tblUsers as UserTab on UserTab.ID = Bill.MBy or UserTab.ID  =  Bill.Cby  
left JOIN tblTranPaymentDetail CD ON CD.DocID = Bill.ID AND CD.DocPrefix = Bill.TransID                      
left JOIN tblTranPaymentHeader CH ON CH.PYID = CD.PYID   
Left JOIN tblMasterUserDefineNoHeader AS UDN ON UDN.UDNId=Bill.UDFId                                   
Left JOIN tblMasterReturnType AS RTNTYPE ON RTNTYPE.ID=Bill.ReturnType                                   
WHERE  Bill.ID = ISNULL(@BillID,0)                      
GROUP BY Bill.ID,Bill.Date,Bill.MDate,MBO.Name,Bill .CDate,Doc.TransName,Bill.DocId,Vendor.name,Vendor.code,Vendor.mob1,                                        
Vendor.mob2,Vendor.ph1,Vendor.ph2,Vendor.email,Vendor.billadd1,Vendor.billadd2,Vendor.billadd3,Vendor.shipadd1,Vendor.shipadd2,                                        
Vendor.shipadd3,Vendor.GSTIN,Vendor.AadharNo,Bill.RefNo,Tax.TaxTypeName,                                      
CreditTermBill.Name,Bill.PaymentDate,Bill.VehicleNo,    
Bill.Frieght,Bill.[OtherCharge%],Bill.OtherChargeAmt,Bill.[TradeDisc%],Bill.[AddnlDisc%],                                      
Bill.TotalProdDiscAmt,Bill.TotalTradeDiscAmt,Bill.TotalAddnlDiscAmt,Bill.WriteOffAmt,Bill.RoundOffAmt,Bill.GrossAmt,                                      
Bill.TaxAmt,Bill.NetAmt,UserTab.username,   
TCSTaxPern,TCSTaxAmt,TDSAmount,Vendor.pincode,Vendor.GSTIN,    
Vendor.AadharNo,Vendor.PANNumber,Vendor.FSSAINo,Bill.UDFDocId,Vendor.ContactPerson,UDN.DocName,TaxType.TaxTypeName,  
Vendor.OSValue,CH.VisaPern,Bill.Balance,Bill.Remarks,Bill.Narration,RTNTYPE.Name  
END',
N'[export] nocount';
GO
/****** uspPurchaseBillTransactionDetail ******/
EXEC #Apply07 N'dbo.uspPurchaseBillTransactionDetail', 0x39B2BAF2F16522B3058C9C2A456F11E608EC87C8EE8A7D2A78DEC6384EE33E8F, NULL, NULL, 0x1846CE266545A76D45F2D974E1BEA2DCE794CAC01C2B4B0ED4EDE8A247821682, 0x14E69FE08D144133757E83975C0D9A707F605054653B062F4D7D1CB17C08FBA2, NULL,
N'ALTER PROCEDURE [dbo].[uspPurchaseBillTransactionDetail] -- 1
@BillID int  = 1
AS
SET NOCOUNT ON;
BEGIN
SELECT BillHeader.DocID [Doc ID],FORMAT(BillHeader.Date,''dd-MMM-yyyy'') [Doc Date],Product.Code AS [Product Code],Product.Name AS [Product Name],Product.EAN as EAN,
BatchNo as [Batch Number],CONVERT(NVARCHAR,PKD,103)AS  [PKD Date],
CONVERT(NVARCHAR,Expiry,103)AS [Expiry Date],
Uom.Name as [Uom Name] ,
[dbo].[fnGetRoundedValue](UomQty)AS[Qty],
[dbo].[fnGetRoundedValue](UomDamageQty)AS[Damage Qty],
[dbo].[fnGetRoundedValue](UomFreeQty)AS[Free Qty],
dbo.fnGetRoundedValue(ISNULL(BillDetail.UomPurchasePrice / NULLIF(BillDetail.UOMCF, 0), 0)) AS [Base Uom Price],
(BillDetail.AdjQty) [Base Qty], BaseUOM.Name [Base UOM],
[dbo].[fnGetRoundedValue](BillDetail.UomPurchasePrice) as [Purchase Price],
[dbo].[fnGetRoundedValue](UomSalePrice) as [Sales Price],
[dbo].[fnGetRoundedValue](UomECP) as [ECP],
[dbo].[fnGetRoundedValue](BillDetail.UomMRP) as [MRP],
[dbo].[fnGetRoundedValue](BillDetail.UomSPLPrice) as [Special Price],
[dbo].[fnGetRoundedValue](BillDetail.[ProdDisc%])as [Product Discount %],
[dbo].[fnGetRoundedValue](BillDetail.[ProdDiscAmt])as [Product Discount Amount],
[dbo].[fnGetRoundedValue](BillDetail.[TradeDisc%]) as [Trade Discount %],
[dbo].[fnGetRoundedValue](BillDetail.[TradeDiscAmt]) as [Trade Discount Amount],
[dbo].[fnGetRoundedValue](BillDetail.[AddnlDisc%]) as [Additional Discount %],
[dbo].[fnGetRoundedValue](BillDetail.[AddnlDiscAmt]) as [Additional Discount Amount],
ta.TaxTypeName [Tax Type Name],
[dbo].[fnGetRoundedValue]([Tax%])as [Tax %],
[dbo].[fnGetRoundedValue](BillDetail.TaxAmt) AS [Tax Amount],
[dbo].[fnGetRoundedValue](GoodsAmt)as [Goods Amount],
[dbo].[fnGetRoundedValue](BillDetail.GrossAmt)as [Gross Amount],
[dbo].[fnGetRoundedValue](BillDetail.NetAmt) AS [Net Amount] ,ML.Name [Location],[dbo].[fnGetRoundedValue](DiffAmt) AS [Diff Value],
MR.Name Reason
FROM tblTransPurchaseDetail AS BillDetail
JOIN tblTransPurchaseHeader as BillHeader on BillHeader.ID = BillDetail.HID
JOIN tblMasterProduct AS Product ON BillDetail.ProdID=Product.ID
LEFT JOIN tblMasterUom as Uom ON  Uom.ID = BillDetail.UomID
JOIN tblMasterUom BaseUOM ON BaseUOM.ID=Product.BaseUomID
LEFT JOIN tblMasterTaxType as ta ON ta.TaxTypeID = BillDetail .TaxTypeId
LEFT JOIN tblMasterLocation ML ON ML.ID = BillDetail.LocationID
LEFT JOIN tblMasterReason MR ON MR.ID = BillDetail.ReasonId
WHERE HID=@BillID  ORDER BY BillDetail.Serial
END',
N'[export] nocount';
GO
/****** uspPurchaseBillTransactionHeader ******/
EXEC #Apply07 N'dbo.uspPurchaseBillTransactionHeader', 0x4170A4D8208DFB82AD688EF19B533B3075774871EDCE5ED36324E5DFDBC088C6, NULL, NULL, 0x94FDEC5E026628762595AE7D52D3668366443F80A9A02BC24BEF82566933FABE, 0x08EE8D99A9A7A2EE0BAD766CCD1B7BFB4E7A912A5A4C4A001DFD70DCAC4E18E8, NULL,
N'ALTER proc [dbo].[uspPurchaseBillTransactionHeader]
@StatusID INT = 1,@FromDate DATE = ''2025-03-01'',@ToDate DATE = ''2025-06-21''
as
SET NOCOUNT ON;
begin
DECLARE @Sts AS TABLE(Status INT)
IF(@StatusID = 0)
BEGIN
INSERT INTO @Sts values (3),(5),(1)
END
ELSE
BEGIN
INSERT INTO @Sts values(@StatusID)
END
SELECT BillHeader.ID, BillHeader.[DocID] AS [Doc ID],FORMAT(Date,''dd-MMM-yyyy'') AS [Doc Date],BO.Name [Branch Name],
Vendor.code AS [Vendor Code],Vendor.name AS [Vendor Name],Vendor.GSTIN,BillHeader.RefNo as [Ref No],
Tax.TaxTypeName as [Tax Type Name],mode.PaymentMode AS [Payment Mode],BillHeader.VehicleNo AS [Vechicle No],
CR.Name as [Credit Term],CONVERT(NVARCHAR,PaymentDate, 103)as [Payment Due Date],
(CASE WHEN BillHeader.Frieght LIKE ''%[%]'' THEN CAST([dbo].[fnGetRoundedValue](REPLACE(BillHeader.Frieght,''%'',''''))+''%'' AS NVARCHAR)
ELSE [dbo].[fnGetRoundedValue](ISNULL(BillHeader.Frieght,0)) END) AS [Freight],
(CASE WHEN BillHeader.[OtherCharge%] LIKE ''%[%]'' THEN CAST([dbo].[fnGetRoundedValue](REPLACE(BillHeader.[OtherCharge%],''%'',''''))+''%'' AS NVARCHAR)
ELSE [dbo].[fnGetRoundedValue](ISNULL(BillHeader.[OtherCharge%],0)) END) [Other Charges %],[dbo].[fnGetRoundedValue](ISNULL (BillHeader.OtherChargeAmt,0)) AS [Other Charges Amount],
[dbo].[fnGetRoundedValue](ISNULL (BillHeader.WriteOffAmt,0))AS [Write off Amt],[dbo].[fnGetRoundedValue](ISNULL (BillHeader.[TradeDisc%],0)) AS [Trade Disc %],---
[dbo].[fnGetRoundedValue](ISNULL (TotalTradeDiscAmt,0))AS[Total Trade Discount],[dbo].[fnGetRoundedValue](ISNULL (BillHeader.[AddnlDisc%],0)) AS [Addnl Disc %], ---
[dbo].[fnGetRoundedValue](ISNULL (TotalAddnlDiscAmt,0))AS [Total Additional Discount Amount],dbo.fnGetRoundedValue(ISNULL(OtherChargeAmt,0)) AS [Total Other Charges Discount Amount],
[dbo].[fnGetRoundedValue](ISNULL (TotalProdDiscAmt,0))AS[Total Product Discount Amount],
[dbo].[fnGetRoundedValue](ISNULL (TCSTaxAmt,0)) AS [TCS Amount],[dbo].[fnGetRoundedValue](ISNULL (TDSAmount,0)) AS [TDS Amount],[dbo].[fnGetRoundedValue](ISNULL (GrossAmt,0)) AS [Gross Amount],
[dbo].[fnGetRoundedValue](ISNULL (TaxAmt,0)) AS [Tax Amount],[dbo].[fnGetRoundedValue](ISNULL (NetAmt,0)) AS [Total Net Amount],
[dbo].[fnGetRoundedValue](ISNULL (Balance,0)) AS [Balance],
dbo.fngetroundedvalue(isnull(DiffValueGross,0)) [Diff Excl],dbo.fngetroundedvalue(isnull(DiffValueNet,0)) [Diff Incl],USERS.username AS [User Name],Sa.Description as[Status]
FROM tblTransPurchaseHeader AS BillHeader
JOIN tblMasterVendor AS Vendor ON BillHeader.VendorID=Vendor.ID
JOIN tblMasterBranchOffice BO ON BO.ID = BillHeader.BranchID
JOIN tblPaymentMode as mode ON mode.Id = BillHeader.PaymentModeId
JOIN tblMasterTaxType AS Tax ON Tax.TaxTypeID = BillHeader.TaxTypeID
LEFT JOIN tblMasterCreditTerm as CR ON CR.ID = BillHeader.PaymentTermID
JOIN tblStatus AS Sa ON Sa.ID =BillHeader.Status
JOIN tblUsers AS USERS ON USERS.ID = BillHeader.CBy
WHERE BillHeader.Date BETWEEN @FromDate AND @ToDate AND BillHeader.Status IN (SELECT * FROM @Sts) AND
BillHeader.TransID = 1 order by BillHeader.DocValue ASC
end',
N'[export] nocount';
GO
