EXEC #Apply07 N'dbo.uspPurchaseOrderHeaderReport', 0x5F5C2E6FDD308B45C0DD36ABFBE732493ACAF5E4FA40090016734056255F1617, NULL, NULL, 0xCCE921AFBBE2E18C037C9AF3FF3E551F726937C9DD5A8D7145BF0CC606D5CA96, 0x8CE282FCADD7D7A02BC4EEA3CF5871053E44E39BACB72B129C691ABC6F035124, NULL,
N'ALTER PROCEDURE [dbo].[uspPurchaseOrderHeaderReport]  
@StatusID INT = 1,@FromDate DATE = ''2025-03-01'',@ToDate DATE = ''2025-06-21''  
AS  
SET NOCOUNT ON;
BEGIN  
DECLARE @Sts AS TABLE(Status INT)  
IF(@StatusID = 0)  
BEGIN  
INSERT INTO @Sts values (3),(5),(1)  
END  
ELSE  
BEGIN  
INSERT INTO @Sts values(@StatusID)  
END  
SELECT  
POH.ID [ID],  
POH.DocID [Doc ID],  
format(POH.DocDate,''dd-MMM-yyyy'') [Doc Date],  
B.Name [Branch Name],  
v.Code [Vendor Code],  
V.Name [Vendor Name],  
POH.RefNo [Ref No],  
CASE WHEN POH.UomType = 1 THEN ''BASE''ELSE ''Purchase'' END AS [Uom Type],  
TT.TaxTypeName [Tax Type],  
CONVERT (NVARCHAR,POH.DeliveryDate) [Delivery Date],  
(POH.GrossAmt) [Gross Amt],  
(POH.TaxAmt) [Tax Amt],  
(POH.RoundOffAmt) [Round Off Amt],  
(POH.NetAmt) [Net Amt],  
S.Description [Status],  
POH.Remarks [Remarks],  
POH.Narration [Narration],  
GRN.DocID [Bill Doc ID],  
CU.UserName [Created By],  
CONVERT(NVARCHAR, POH.CDate) [Created Date],  
MU.UserName [Modify By],  
CONVERT(NVARCHAR, POH.MDate) [Modify Date],  
CL.UserName [Cancel By],  
CONVERT(NVARCHAR, POH.ClDate) [Cancel Date]  
FROM tblPurchaseOrderHeader POH  
LEFT JOIN tblMasterBranchOffice B  
ON B.ID = POH.BranchID  
LEFT JOIN tblMasterVendor V  
ON V.ID = POH.VendorID  
LEFT JOIN tblStatus S  
ON S.ID = POH.Status  
LEFT JOIN tblMasterTaxType TT  
ON TT.TaxTypeID = POH.TaxTypeID  
LEFT JOIN tblTransPurchaseHeader GRN  
ON GRN.ID = POH.GRNid  
LEFT JOIN tblUsers CU  
ON CU.ID = POH.CBy  
LEFT JOIN tblUsers MU  
ON MU.ID = POH.MBy  
LEFT JOIN tblUsers CL  
ON CL.ID = POH.ClBy  
WHERE POH.DocDate BETWEEN @FromDate AND @ToDate AND POH.Status IN (SELECT * FROM @Sts)  
ORDER BY POH.DocID  
END;',
N'[export] nocount';
GO
