/****** uspPurchaseRegisterHeader ******/
EXEC #Apply07 N'dbo.uspPurchaseRegisterHeader', 0xD5FBBBEA7F6BD7A9679EBE9333A78FD6B3CAA7A570AC65B5620552934BA31904, NULL, NULL, 0x23F44C06CCE6F6C4A2893A5C634E67C6EBBC7A376623409E645AF372CA02E5D2, 0xDD758A5BDB0BE1BDB3B503A686C166710801381A64738E248404C25F8F1DA8CC, NULL,
N'ALTER proc [dbo].[uspPurchaseRegisterHeader]
@StatusID INT = 1,@FromDate DATE = ''2025-03-01'',@ToDate DATE = ''2025-06-21''
AS
SET NOCOUNT ON;
BEGIN
DECLARE @Sts AS TABLE(Status INT)
IF(@StatusID = 0)
BEGIN
INSERT INTO @Sts values (1),(3),(5),(6),(7)
END
ELSE IF(@StatusID = 1)
BEGIN
INSERT INTO @Sts values (1),(6),(7)
END
ELSE
BEGIN
INSERT INTO @Sts values(@StatusID)
END
SELECT  BIL.ID  AS [BillID],DS.TransName [Transaction], DocId AS [Doc ID],FORMAT(Date,''dd-MMM-yyyy'') AS [Doc Date],BO.Name as [Branch Name],MV.Code AS [Vendor Code],
MV.Name AS [Vendor Name],
[RefNo] as [Ref No],Tax.TaxTypeName as [Tax Type Name],
[dbo].[fnGetRoundedValue](BIL.[TradeDisc%])AS [Trade Disc %],
[dbo].[fnGetRoundedValue](BIL.[AddnlDisc%])AS [Additional Disc %],[dbo].[fnGetRoundedValue](BIL.Frieght)AS [Freight],
[dbo].[fnGetRoundedValue](BIL.[OtherCharge%])AS[Other Charges %],[dbo].[fnGetRoundedValue](BIL.WriteOffAmt)AS [Write off Amt],
[dbo].[fnGetRoundedValue](BIL.TotalTradeDiscAmt)AS[Total Trade Disc Amount],[dbo].[fnGetRoundedValue](BIL.TotalAddnlDiscAmt)AS [Total Additional Disc Amount],
[dbo].[fnGetRoundedValue](BIL.OtherChargeAmt)AS [Total Other Charges Disc Amount],[dbo].[fnGetRoundedValue](BIL.TotalProdDiscAmt)AS[Total Prod Disc Amount],
[dbo].[fnGetRoundedValue](SUM([GrossAmt])) AS [Gross Amount],[dbo].[fnGetRoundedValue](SUM(TaxAmt)) as [Tax Amount],
[dbo].[fnGetRoundedValue](SUM(RoundOffAmt)) as [Round Off Amount],[dbo].[fnGetRoundedValue](SUM([NetAmt]) )as  [Net Amount],
dbo.fngetroundedvalue(isnull(SUM(DiffValueGross),0)) [Diff Excl],dbo.fngetroundedvalue(isnull(SUM(DiffValueNet),0)) [Diff Incl],
CASE WHEN BIL.Status = 6 THEN ''Open'' ELSE s.Description END as [Status],MRT.Name AS [Return Type],u.username as [User Name]
from [tblTransPurchaseHeader] AS BIL
Join tblMasterVendor MV on BIL.VendorID = MV.ID
join tblMasterBranchOffice BO ON BO.ID = BIL.BranchID
join tblDocumentSeries DS ON DS.TransID = BIL.TransID
LEFT JOIN tblMasterTaxType as Tax ON Tax.TaxTypeID = BIL.TaxTypeID
JOIN tblUsers as u ON u.ID = BIL.Cby
JOIN tblStatus as s ON s.ID =BIL.Status
LEFT JOIN tblMasterReturnType AS MRT ON MRT.ID = BIL.ReturnType
WHERE  Date BETWEEN @FromDate AND @ToDate AND BIL.Status IN (select * from @Sts)
GROUP BY BIL.ID,DS.TransName,Date,DocId,MV.code,MV.name,[RefNo],Tax.TaxTypeName,PaymentDate,
BO.Name,UDFDocId,s.Description ,u.username,MRT.Name,
BIL.[TradeDisc%],BIL.[AddnlDisc%],BIL.Frieght,BIL.[OtherCharge%],BIL.WriteOffAmt,BIL.TotalTradeDiscAmt,
BIL.TotalAddnlDiscAmt,BIL.OtherChargeAmt,BIL.TotalProdDiscAmt, BIL.Status,BIL.DocValue  ORDER BY BIL.DocValue
END',
N'[export] nocount';
GO
/****** uspPurchaseReturnBody ******/
EXEC #Apply07 N'dbo.uspPurchaseReturnBody', 0xABF9117330348C162848947149A42E7684519FD7BC09CC87FB01CDFA5B9F3DFF, NULL, NULL, 0x100BE4B0EAC0757371233188A9D3A36739568EB032EB24D9CBFD3A560A710486, 0xFB930397C8B2C274EA135141580351C2B2E42591AC79D980B58A3FBE6440D846, NULL,
N'--[uspPurchaseReturnBody] 96
ALTER PROC [dbo].[uspPurchaseReturnBody]  
@BillId NVARCHAR(255)= 365  
AS  
SET NOCOUNT ON;
BEGIN  
SELECT ProdID,Serial [Temp Serial],(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],  
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],  
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],  
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],  
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],  
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],  
SUM([GCESS Amount] + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #Tax  
FROM  
(  
SELECT SRI.ProdID,SRI.Serial,--SRI.[Gross Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],  
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],  
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],  
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],  
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],  
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],  
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],  
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],  
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]  
FROM  
(  
SELECT * FROM  
(  
SELECT Temp.ProdID,Temp.Serial,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],  
Temp.TaxName AS TaxName,  
SUM(Temp.TaxValue) AS [TaxValue]--, SUM(Temp.[Gross Amount]) AS [Gross Amount]  
FROM  
(  
SELECT GSTInfo.ProdID,GSTInfo.SERIAL,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,  
CASE  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''  
END AS [GST Comp]--, GSTInfo.GrossAmt AS [Gross Amount]  
FROM tblTransGSTInfo AS GSTInfo  
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID  
WHERE TransIdentID = @BillId AND (TransID=1 or TransID=12)  
) Temp  
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.ProdID,Temp.Serial  
) src  
PIVOT  
(  
SUM([TaxValue])  
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])  
) piv  
) AS SRI  
) AS RAM  
GROUP BY ProdID,Serial  
  
  
SELECT IDENTITY (INT, 1, 1) AS NEW_ID,Bill.ProdID,prod.Code AS [Product Code],prod.Name as [Product Name],prod.HSNCode AS [HSN Code],  
Uom.Name as [Uom Name],Bill.BatchNo as [Batch No],Convert(nvarchar,Bill.PKD,103) as [PKD Date],  
Convert (nvarchar,Bill.Expiry,103) as [Expiry Date],Bill.UomQty as [Uom Qty],Bill.UomFreeQty as [Uom Free Qty],  
Bill.UomDamageQty as [Uom Damage Qty],Bill.UomPurchasePrice as [Uom Purchase Price],  
Bill.UomSalePrice AS [Uom Sales Price],Bill.UomECP as [Uom ECP],  
Bill.UomMRP as [Uom MRP],Bill.UomSPLPrice AS [Uom SPL Price],Bill.PurchasePrice AS [Base Purchase Price],  
Bill.SalePrice AS [Base Sales Price],Bill.ECP AS [Base ECP Price],  
Bill.SPLPrice AS [Base SPL Price],Tax.TaxName as [Tax Name],TaxType.TaxTypeName as [TaxType Name],  
Bill.[Tax%] as [Tax Percentage],Bill.GoodsAmt as [Goods Amount],  
CAST(dbo.fnGetRoundedValue(Bill.[ProdDisc%]) AS NVARCHAR(255))+''%'' AS [Product Discount %],  
Bill.ProdDiscAmt as [Product Disc Amt],Bill.[TradeDisc%] as [Trade Discount %],  
Bill.TradeDiscAmt [Trade Discount],Bill.[AddnlDisc%] as [Addnl Discount %],  
BILL.AddnlDiscAmt [Addnl Discount],Bill.GrossAmt as [Gross Amount],  
Bill.GrossAmt as [Tax Value],Bill.TaxAmt as [Tax Amount],  
Bill.NetAmt as [Net Amount],Row_number() OVER (order by Bill.HID) as [Serial No],  
Loc.Name AS [Location Name],RSN.Name [Reason Name],prod.Remarks AS [Remark1],prod.WebOrder AS [Web Order],  
(Bill.UomQty / isnull(Bill.UOMCF,1)) AS [Base Qty],  
(Bill.UomQty / isnull(Bill.UOMCF,1)) AS [Deft_S_UOM_Qty],  
(Bill.UomQty / isnull(Bill.UOMCF,1)) AS [Base Uom Price], Bill.UomPurchasePrice AS [Uom Price],isnull(Bill.UOMCF,1) AS [UOM CF],  
isnull(Bill.UOMCF,1) AS [Deft_S_UOM_CF],  
Bill.UomPurchasePrice + (Bill.UomPurchasePrice * (Bill.[Tax%] / 100)) as [Rate],  
Bill.GrossAmt / Bill.UomQty as [Per Piece Exclusive Price],  
Bill.NetAmt / Bill.UomQty as [Per Piece Inclusive Price], Bill.MRP [MRP Price],  
((Bill.GoodsAmt) * (Bill.[ProdDisc%]) /100) +  
ISNULL(((((Bill.GoodsAmt) - ((Bill.GoodsAmt) * (Bill.[ProdDisc%]) /100)) * Bill.[TradeDisc%]) / 100),0) +  
ISNULL(((((Bill.GoodsAmt) - ((Bill.GoodsAmt) * (Bill.[ProdDisc%]) /100)) * Bill.[AddnlDisc%]) / 100),0) as [Total Disc Amt]  
INTO #BILL  
From dbo.TBLTRANSPURCHASEDETAIL as Bill  
JOIN tblMasterProduct as prod ON prod.ID=Bill.ProdId  
JOIN dbo.tblMasterUom as Uom on Uom.ID = Bill.UomId  
Join dbo.tblMasterTax as Tax on Bill.TaxID = Tax.TaxID  
Join dbo.tblMasterTaxType as TaxType on Bill.TaxTypeId = TaxType.TaxTypeID  
LEFT JOIN tblMasterLocation AS Loc ON Loc.ID=Bill.LocationID  
LEFT JOIN tblMasterReason AS RSN ON RSN.ID=Bill.ReasonId  
WHERE Bill.HID = @BillId order by Bill.Serial  
  
  
SELECT [Product Code],[Product Name],[HSN Code],[Uom Name],[Batch No],[PKD Date],[Expiry Date] [EXP Date],  
[Uom Qty],[Uom Free Qty],[Uom Damage Qty],[Uom Purchase Price],[Uom Sales Price],[Uom ECP],[Uom MRP],  
[Uom SPL Price],[Base Purchase Price],[Base Sales Price],[Tax Name],[TaxType Name],[Tax Percentage],[Goods Amount],  
[Product Discount %],[Product Disc Amt],[Trade Discount %],[Trade Discount],[Addnl Discount %],[Addnl Discount],  
[Gross Amount],[Tax Value],[Tax Amount],[Net Amount],NEW_ID AS [Serial],  
[Location Name],[Reason Name],[Remark1],[Web Order],[Base Qty],[Deft_S_UOM_Qty],[Base Uom Price],[Uom Price],[UOM CF],  
[Deft_S_UOM_CF],[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price],[MRP Price],[Total Disc Amt],  
dbo.fnGetRoundedValue(sum([CGST %])) [CGST %],  
dbo.fnGetRoundedValue(sum([CGST Amount])) [CGST Amount],  
dbo.fnGetRoundedValue(sum([SGST %])) [SGST %],  
dbo.fnGetRoundedValue(sum([SGST Amount])) [SGST Amount],  
dbo.fnGetRoundedValue(sum([UTGST %])) [UTGST %],dbo.fnGetRoundedValue(sum([UTGST Amount])) [UTGST Amount],  
dbo.fnGetRoundedValue(sum([GCESS %])) [GCESS %], dbo.fnGetRoundedValue(SUM([GCESS Amount])) [GCESS Amount],  
dbo.fnGetRoundedValue(sum([IGST %])) [IGST %],  
dbo.fnGetRoundedValue(sum([IGST Amount])) [IGST Amount],  
dbo.fnGetRoundedValue(sum([ICESS %])) [ICESS %],dbo.fnGetRoundedValue(sum([ICESS Amount])) [ICESS Amount],  
dbo.fnGetRoundedValue(sum(TX.[GUOM %])) [GUOM %],dbo.fnGetRoundedValue(sum(TX.[GUOM Amount])) [GUOM Amount],  
dbo.fnGetRoundedValue(sum(TX.[IUOM %])) [IUOM %],dbo.fnGetRoundedValue(sum(TX.[IUOM Amount])) [IUOM Amount],  
dbo.fnGetRoundedValue(sum(TX.[Cumulative CESS Amount])) [Cumulative CESS Amount] FROM #BILL BILL  
LEFT JOIN #Tax TX ON TX.ProdID = BILL.ProdID  
GROUP BY [Product Code],[Product Name],[HSN Code],[Uom Name],[Batch No],[PKD Date],[Expiry Date],  
[Uom Qty],[Uom Free Qty],[Uom Damage Qty],[Uom Purchase Price],[Uom Sales Price],[Uom ECP],[Uom MRP],  
[Uom SPL Price],[Base Purchase Price],[Base Sales Price],[Tax Name],[TaxType Name],[Tax Percentage],[Goods Amount],  
[Product Discount %],[Product Disc Amt],[Trade Discount],[Addnl Discount],[Gross Amount],[Tax Value],[Tax percentage],[Tax Amount],[Net Amount],[Serial No],NEW_ID,  
[Location Name],[Reason Name],[Remark1],[Web Order],[Base Qty],[Deft_S_UOM_Qty],[Base Uom Price],[Uom Price],[UOM CF],  
[Deft_S_UOM_CF],[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price],[MRP Price],[Total Disc Amt], [Trade Discount %],[Addnl Discount %]  
order by [Serial No]  
DROP TABLE #Tax,#BILL  
END',
N'[export] nocount';
GO
/****** uspPurchaseReturnHeader ******/
EXEC #Apply07 N'dbo.uspPurchaseReturnHeader', 0x12FF97AB067ACD65B0867723F0CB5FD684F61E105BA05561D2930F33950D0924, NULL, NULL, 0xC1104EEEE6E48E17C52765F4E78D59764AE086BC203E84EC045C6FBA91814110, 0xBF45F70FA9B4C9A7097380BC9062B0A0D4744F37B3D9E2395AF1D5B5B6F14119, NULL,
N'ALTER proc [dbo].[uspPurchaseReturnHeader]
@BillID INT = 73           
AS
SET NOCOUNT ON;
BEGIN
--Payment Mode                    
 Declare @BillPaymode nvarchar(1000)           
 Select @BillPaymode = Coalesce (@BillPaymode + '', '', '''') + mode.PaymentMode From dbo.tblTran_Sale_Bill_PaymentDetail as BS                      
 left Join dbo.tblPaymentMode as mode on mode.Id = BS.PayModeId where InvId = @BillID and TransId = 18 Group by mode.PaymentMode                      
 --Cash Balance-----          
 DeClare @Amt DECIMAL (25,6), @Recdamt DECIMAL (25,6)          
  Select @Amt=SUM(Amt),@Recdamt = SUM(RecdAmt)  From dbo.tblTran_Sale_Bill_PaymentDetail as BS          
 where InvId = @BillID and TransId = 18          
    
SELECT Bill.ID As [Bill ID],CONVERT(nvarchar,Bill.Date,103) as [Doc Date],  
Isnull(CONVERT(nvarchar(5),Bill.MDate,108),CONVERT(nvarchar(5),Bill .CDate,108)) as [Time],    
Doc.TransName as [Trans Name],Bill.DocId as [Doc ID],Bill.UDFDocId [UDN Doc ID],UDN.DocName AS [UDN Name],Vendor.name as [Party Name],    
Vendor.code as [Party Code],Vendor.mob1 as [Party Prim Mobile No],  
Vendor.ph1 as [Party Prim Phone No],Vendor.email as [Email ID],  
Vendor.billadd1 AS [Party Bill Address 1],Vendor.billadd2 as [Party Bill Address 2],Vendor.billadd3 as [Party Bill Address 3],          
Vendor.billadd1+Vendor.billadd2+Vendor.billadd3 as [Party Full Address],  
Vendor.shipadd1 AS [Party Ship Address 1],Vendor.shipadd2 as [Party Ship Address 2],Vendor.shipadd3 as [Party Ship Address 3],  
Vendor.ContactPerson [Contact Person],Vendor.pincode [Party PinCode],Vendor.GSTIN AS [Party GSTIN],  
Vendor.AadharNo AS [Party Aadhar Number],Vendor.PANNumber AS [Party PAN No],Vendor.FSSAINo AS [Party FSSAI No],     
Bill.RefNo as [Doc Ref],  
--PGrp.ProductGroupName as [Prod Group Name],          
Tax.TaxTypeName as [TaxType Name],Vendor.OSValue [Party Outstanding value],  
--paymodeBill.PaymentMode AS [Payment Mode],            
isnull(@BillPaymode ,''CREDIT'') as [Payment Mode],  CreditTermBill.Name as [Payment Term],            
Convert (nvarchar,Bill.PaymentDate,103) as [CreditTerm Date],Bill.VehicleNo as [Vehicle No],          
MBO.Name as [Branch Name],SUM(Detail.UomQty) As [Total Qty],          
SUM(Detail.UomFreeQty) As [Total Free Qty],SUM(Detail.UomDamageQty) As [Total Damage Qty],  
SUM(Detail.UomQty) As [Deft_S_UOM_Total_Qty],   
Bill.Frieght as [Frieght Amount],Bill.[OtherCharge%] as [OtherCharge Percentage],Bill.OtherChargeAmt as [OtherCharge Amount],    
Bill.[TradeDisc%] as [Trade Discount Percentage],  
Bill.[AddnlDisc%] as [Addnl Discount Percentage],  
Bill.TotalProdDiscAmt as [T.Product Discount Amount],  
Bill.TotalTradeDiscAmt as [T.Trade Discount Amount],Bill.TotalAddnlDiscAmt as [T.Addnl Discount Amount],          
(Bill.TotalProdDiscAmt + Bill.TotalTradeDiscAmt + Bill.TotalAddnlDiscAmt) AS [T.Discount Amount],  
dbo.fnGetRoundedValue(Bill.TotalAddnlDiscAmt)+'' (''+dbo.fnGetRoundedValue(Bill.[AddnlDisc%])+''%)'' [Addnl Disc Pern Amt],      
dbo.fnGetRoundedValue(Bill.TotalTradeDiscAmt)+'' (''+dbo.fnGetRoundedValue(Bill.[TradeDisc%])+''%)''[Trade Disc Pern Amt], 
0 [Adjust Amount],Bill.WriteOffAmt as [Write Off Amount],Bill.RoundOffAmt as [Round Off Amount],  
Bill.NetAmt+(@Recdamt-@Amt) as [Received Amount],  
@Recdamt-@Amt AS [Cash Balance],    
Bill.GrossAmt + (Bill.TotalProdDiscAmt + Bill.TotalTradeDiscAmt + Bill.TotalAddnlDiscAmt) [Goods Amount],  
Bill.GrossAmt as [T.Gross Amount],Bill.TaxAmt as [T.Total Tax Amount],Bill.NetAmt as [Rounded Net Amount],   
CH.VisaPern as [Visa %],((Bill.NetAmt * CH.VisaPern) / 100) AS [Visa Amt],(Bill.NetAmt + ((Bill.NetAmt * CH.VisaPern) / 100)) as [All Incl],       
Bill.Balance AS [Balance Amount],Bill.NetAmt as [Aft Adj NetAmt],        
dbo.fnConvertAmountinWords(Bill.NetAmt) AS [Amt_in_Words],UserTab.username as [User Name],
convert(nvarchar(255),MAX(Detail.Serial)) + '' / '' + convert(nvarchar(255),dbo.fnGetRoundedValue(SUM(Detail.UomQty))) as [Tot Count Qty],        
TCSTaxPern [TCS %],TCSTaxAmt [TCS Amt],isnull(TDSAmount,0) TDSAmount,Bill.Remarks,Bill.Narration,RTNTYPE.Name [Return Type]  
FROM dbo.tblTransPurchaseHeader AS Bill          
JOIN dbo.tblTransPurchaseDetail as Detail on Bill.ID = Detail.HID  
LEFT JOIN tblMasterProduct AS Prod ON Prod.ID = Detail.ProdId   
JOIN TBLMASTERBRANCHOFFICE MBO ON MBO.ID = Bill.BranchID
LEFT JOIN dbo.tblDocumentSeries AS Doc ON Bill.TransID = Doc.TransID                                              
LEFT JOIN dbo.tblMasterVendor AS Vendor ON Bill.VendorID = Vendor.ID                                            
LEFT JOIN dbo.tblMasterTaxType as Tax on Bill.TaxTypeId = Tax.TaxTypeID                         
LEFT JOIN dbo.tblMasterProductGroup as PGrp on Bill.ProdGroupID = PGrp.ID                                                                                 
LEFT JOIN dbo.tblMasterTaxType as TaxType on TaxType.TaxTypeID = Bill.taxtypeid                                                                                 
LEFT JOIN dbo.tblPaymentMode as paymode on paymode.Id = Bill.PaymentModeID                                     
--LEFT JOIN dbo.tblPaymentMode as paymodeBill on paymodeBill.Id = Bill.PaymentModeId                                         
LEFT JOIN dbo.tblMasterCreditTerm as CreditTermBill on CreditTermBill.ID = Bill.PaymentTermID                                        
JOIN dbo.tblUsers as UserTab on UserTab.ID = Bill.MBy or UserTab.ID  =  Bill.Cby  
left JOIN tblTranPaymentDetail CD ON CD.DocID = Bill.ID AND CD.DocPrefix = Bill.TransID                      
left JOIN tblTranPaymentHeader CH ON CH.PYID = CD.PYID   
Left JOIN tblMasterUserDefineNoHeader AS UDN ON UDN.UDNId=Bill.UDFId                                   
Left JOIN tblMasterReturnType AS RTNTYPE ON RTNTYPE.ID=Bill.ReturnType                                   
WHERE  Bill.ID = ISNULL(@BillID,0)                      
GROUP BY Bill.ID,Bill.Date,Bill.MDate,MBO.Name,Bill .CDate,Doc.TransName,Bill.DocId,Vendor.name,Vendor.code,Vendor.mob1,                                        
Vendor.mob2,Vendor.ph1,Vendor.ph2,Vendor.email,Vendor.billadd1,Vendor.billadd2,Vendor.billadd3,Vendor.shipadd1,Vendor.shipadd2,                                        
Vendor.shipadd3,Vendor.GSTIN,Vendor.AadharNo,Bill.RefNo,Tax.TaxTypeName,                                      
CreditTermBill.Name,Bill.PaymentDate,Bill.VehicleNo,    
Bill.Frieght,Bill.[OtherCharge%],Bill.OtherChargeAmt,Bill.[TradeDisc%],Bill.[AddnlDisc%],                                      
Bill.TotalProdDiscAmt,Bill.TotalTradeDiscAmt,Bill.TotalAddnlDiscAmt,Bill.WriteOffAmt,Bill.RoundOffAmt,Bill.GrossAmt,                                      
Bill.TaxAmt,Bill.NetAmt,UserTab.username,   
TCSTaxPern,TCSTaxAmt,TDSAmount,Vendor.pincode,Vendor.GSTIN,    
Vendor.AadharNo,Vendor.PANNumber,Vendor.FSSAINo,Bill.UDFDocId,Vendor.ContactPerson,UDN.DocName,TaxType.TaxTypeName,  
Vendor.OSValue,CH.VisaPern,Bill.Balance,Bill.Remarks,Bill.Narration,RTNTYPE.Name  
END',
N'[export] nocount';
GO
/****** uspPurchaseReturnTransactionDetail ******/
EXEC #Apply07 N'dbo.uspPurchaseReturnTransactionDetail', 0x256ECCF94896AD5E60D5E3A9E60E60456DC77C155A2CAA54E57999719EDA737B, NULL, NULL, 0xD0470B58ECE06B4F3A971E512812598DC85AC09F1B24430C8C097ED7EDD88C40, 0x2521EAF2EB9C95D4DD3480EA2E8858D59BBED166FBABF3951919192BA459E3D7, NULL,
N'ALTER proc [dbo].[uspPurchaseReturnTransactionDetail]
@PRID INT = 123
AS
SET NOCOUNT ON;
BEGIN
SELECT BillHeader.DocID [Doc ID],FORMAT(BillHeader.Date,''dd-MMM-yyyy'') [Doc Date],Prod.Code AS [Product Code],Prod.Name AS [Product Name],Prod.EAN as EAN,BD.BatchNo AS [Batch No],BD.PKD,BD.Expiry,
UOM.Name AS [UOM Name],
dbo.fnGetRoundedValue(ISNULL(BD.UomQty,0)) AS Qty,dbo.fnGetRoundedValue(ISNULL(BD.UomFreeQty,0)) AS [Free Qty],
dbo.fnGetRoundedValue(ISNULL(BD.UomDamageQty,0)) AS [Damage Qty],
dbo.fnGetRoundedValue(ISNULL(BD.UomPurchasePrice / NULLIF(BD.UOMCF, 0), 0)) AS [Base Uom Price],
(BD.AdjQty) [Base Qty], BaseUOM.Name [Base UOM],
dbo.fnGetRoundedValue(ISNULL(BD.UomPurchasePrice,0)) AS [Purchase Price],
dbo.fnGetRoundedValue(ISNULL(BD.UomMRP,0)) AS MRP,Tax.TaxName AS [Tax Name],dbo.fnGetRoundedValue(ISNULL(BD.[Tax%],0)) AS [Tax %],
dbo.fnGetRoundedValue(ISNULL(BD.GoodsAmt,0)) AS [Goods Amount],dbo.fnGetRoundedValue(ISNULL(BD.[ProdDisc%],0)) AS [Product Discount %],
dbo.fnGetRoundedValue(ISNULL(BD.ProdDiscAmt ,0)) AS [Product Discount Amount],
dbo.fnGetRoundedValue(ISNULL(BD.[TradeDisc%],0)) AS [Trade Discount %],dbo.fnGetRoundedValue(ISNULL(BD.[TradeDiscAmt],0)) as [Trade Discount Amount],
dbo.fnGetRoundedValue(ISNULL(BD.[AddnlDisc%],0)) AS [Additional Discount %],dbo.fnGetRoundedValue(ISNULL(BD.[AddnlDiscAmt],0)) as [Additional Discount Amount],
dbo.fnGetRoundedValue(ISNULL(BD.GrossAmt,0)) AS [Gross Amount],dbo.fnGetRoundedValue(ISNULL(BD.TaxAmt,0)) AS [Tax Amount],
dbo.fnGetRoundedValue(ISNULL(BD.NetAmt,0)) AS [Net Amount],R.Name AS [Reason Name] ,dbo.fnGetRoundedValue(ISNULL(BD.DiffAmt,0)) AS [Diff Value]
FROM tblTransPurchaseDetail BD
JOIN tblTransPurchaseHeader as BillHeader on BillHeader.ID = BD.HID
LEFT JOIN tblMasterProduct Prod ON Prod.ID=BD.ProdID
JOIN tblMasterUom UOM ON UOM.ID=BD.UomID
JOIN tblMasterUom BaseUOM ON BaseUOM.ID=Prod.BaseUomID
LEFT JOIN tblMasterTax Tax ON Tax.TaxID=BD.TaxID
LEFT JOIN tblMasterReason R ON R.ID=BD.ReasonId
WHERE HID = @PRID
ORDER BY BD.Serial
end',
N'[export] nocount';
GO
/****** uspPurchaseReturnTransactionHeader ******/
EXEC #Apply07 N'dbo.uspPurchaseReturnTransactionHeader', 0x0EC448E21D7660365F8F5BC9EF5A2947BA61B2802BC24212AC59A3AAC346A975, NULL, NULL, 0x67474E73611C6C030893FE5480C53BB460B2E7AB0EB131F3652F430BA7518397, 0xD0E17A81534BE3D82C9B25900C092A9C05C044527690D6D8339001672EB054A2, NULL,
N'ALTER proc [dbo].[uspPurchaseReturnTransactionHeader]
@StatusID INT = 1,@FromDate DATE = ''2025-03-01'',@ToDate DATE = ''2025-06-21''
AS
SET NOCOUNT ON;
BEGIN
DECLARE @Sts AS TABLE(Status INT)
IF(@StatusID = 0)
BEGIN
INSERT INTO @Sts values (3),(5),(6),(7)
END
ELSE IF(@StatusID = 1)
BEGIN
INSERT INTO @Sts values (6),(7)
END
ELSE
BEGIN
INSERT INTO @Sts values(@StatusID)
END
SELECT  BIL.ID  AS [BillID], DocId AS [Doc ID],FORMAT(Date,''dd-MMM-yyyy'') AS [Doc Date],BO.Name as [Branch Name],MV.Code AS [Vendor Code],
MV.Name AS [Vendor Name],
[RefNo] as [Ref No],Tax.TaxTypeName as [Tax Type Name],
[dbo].[fnGetRoundedValue](BIL.[TradeDisc%])AS [Trade Disc %],
[dbo].[fnGetRoundedValue](BIL.[AddnlDisc%])AS [Additional Disc %],[dbo].[fnGetRoundedValue](BIL.Frieght)AS [Freight],
[dbo].[fnGetRoundedValue](BIL.[OtherCharge%])AS[Other Charges %],[dbo].[fnGetRoundedValue](BIL.WriteOffAmt)AS [Write off Amt],
[dbo].[fnGetRoundedValue](BIL.TotalTradeDiscAmt)AS[Total Trade Disc Amount],[dbo].[fnGetRoundedValue](BIL.TotalAddnlDiscAmt)AS [Total Additional Disc Amount],
[dbo].[fnGetRoundedValue](BIL.OtherChargeAmt)AS [Total Other Charges Disc Amount],[dbo].[fnGetRoundedValue](BIL.TotalProdDiscAmt)AS[Total Prod Disc Amount],
[dbo].[fnGetRoundedValue](SUM([GrossAmt])) AS [Gross Amount],[dbo].[fnGetRoundedValue](SUM(TaxAmt)) as [Tax Amount],
[dbo].[fnGetRoundedValue](SUM(RoundOffAmt)) as [Round Off Amount],
[dbo].[fnGetRoundedValue](SUM([NetAmt]) )as  [Net Amount],
dbo.fngetroundedvalue(isnull(sum(DiffValueGross),0)) [Diff Excl],dbo.fngetroundedvalue(isnull(sum(DiffValueNet),0)) [Diff Incl],
s.Description as [Status],MRT.Name AS [Return Type],u.username as [User Name]
from [tblTransPurchaseHeader] AS BIL
Join tblMasterVendor MV on BIL.VendorID = MV.ID
join tblMasterBranchOffice BO ON BO.ID = BIL.BranchID
LEFT JOIN tblMasterTaxType as Tax ON Tax.TaxTypeID = BIL.TaxTypeID
JOIN tblUsers as u ON u.ID = BIL.Cby
JOIN tblStatus as s ON s.ID =BIL.Status
LEFT JOIN tblMasterReturnType AS MRT ON MRT.ID = BIL.ReturnType
WHERE  Date BETWEEN @FromDate AND @ToDate AND TransID=12 AND BIL.Status IN (select * from @Sts)
GROUP BY BIL.ID,Date,DocId,MV.code,MV.name,[RefNo],Tax.TaxTypeName,PaymentDate,
BO.Name,UDFDocId,s.Description ,u.username,MRT.Name,
BIL.[TradeDisc%],BIL.[AddnlDisc%],BIL.Frieght,BIL.[OtherCharge%],BIL.WriteOffAmt,BIL.TotalTradeDiscAmt,
BIL.TotalAddnlDiscAmt,BIL.OtherChargeAmt,BIL.TotalProdDiscAmt,DocValue  ORDER BY DocValue
END',
N'[export] nocount';
GO
/****** uspPurchaseReturnVariantData ******/
EXEC #Apply07 N'dbo.uspPurchaseReturnVariantData', 0x61A6CF36FC1EE35C5E3B488EF6E2401E6577373EAA4D296C6F2C556573300DC3, NULL, NULL, 0xF4BDAC26A7485F2B9EAE4D4A61404AFA759616A44B9F817621F6C1B20AD45A68, 0xCD3F54141523C168244488CE8C0D08873CF956EACFF0E29DE56C887A8594E456, NULL,
N'ALTER proc [dbo].[uspPurchaseReturnVariantData]
@VariantTypeID int = 5, @ID int = 1101,@PartyID int	= 9
as
SET NOCOUNT ON;
begin
SELECT * FROM tblMasterVendor WHERE ID = @PartyID ORDER BY Name

SELECT PH.ID, PH.InvDate Date, 12 TransID, PH.BranchID, PH.DocID, PH.DocValue, 0 VendorID, PH.DocID RefNo, PH.ProdGroupID,
PH.TaxTypeID, 7 PaymentModeID, 0 PaymentTermID,NULL PaymentDate, PH.VehicleNo, PH.Frieght, PH.OtherCharge OtherChrgPern,
PH.OtherChargeAmt, 0 ProdPern, PH.TradeDisc TradePern, PH.AdditionalDisc AddnlPern, PH.TotalProdDiscAmt, PH.TotalTradeDiscAmt,
PH.AdditionalDiscAmt TotalAddnlDiscAmt, 0 WriteOffAmt, PH.RoundOfAmt RoundOffAmt, PH.GrossAmt, PH.TotalTaxAmt TaxAmt, 
PH.NetAmt,dbo.fnGetRoundedValue(PH.Balance) Balance, 0 PymtID,
PH.Status, PH.OrgId, PH.UDFId, PH.UDFDocId, PH.UDFDocPrefix, PH.UDFDocValue, PH.CBy, PH.CDate,
PH.MBy, PH.MDate, PH.ClBy, PH.ClDate, PH.ReturnType, PH.TransactionType,null DateBill, PH.PortalDate,
PH.TCSTaxPern, PH.TCSTaxAmt, PH.TDSAmount, PH.IRN, PH.AckNo, PH.AckDate, PH.AckStatus, PH.SignedQRCode,
PH.EWBNo, PH.Distance, PH.TransMode, PH.VehicleType, PH.TransportID, PH.TransportName, PH.Remarks, PH.Narration,1 PriceType,
DiffValueGross,DiffValueNet,dbo.fnTransactionPrefix(convert(date,getdate()),BranchID,12) Prefix
FROM tblTranSalesHeader PH
JOIN tblStatus STS ON STS.ID = PH.Status
JOIN tblMasterBranchOffice MBO ON MBO.ID = PH.BranchID
where PH.ID = @ID

SELECT PD.ProdID,PD.UomID,MP.Code,MP.Name,MP.HSNCode,UOM.Name UOM,
(case when PH.TransactionType = 2 THEN SUM(UomQty) ELSE 0 END) Qty,0 FreeQty,
(case when PH.TransactionType = 3 THEN SUM(UomQty) ELSE 0 END) DmgQty,
PD.ProdDisc ProdPern,PD.TradeDiscPern TradePern,PD.AddnlDiscPern AddnlPern,SUM(pd.GrossAmt) GrossAmt,SUM(TaxAmt) TaxAmt,SUM(pd.NetAmt) NetAmt,
MT.TaxName,PD.TaxValue TaxPern,isnull(PD.ReasonId,0) ReasonId,MR.Name ReasonName,ISNULL(PTP.PurchaseReturnPrice,0) PurchaseReturnPrice
,ISNULL(PD.DiffValue,0) DiffAmt,SUM(dbo.fngetMRPonCumValue(0,PD.TaxID,1,0)) CumMRPonTax,
SUM(dbo.fngetMRPonCumValue(1,PD.TaxID,1,PD.DetailMRP))* SUM(UomQty) MRPonTaxAmt,SUM(GoodsAmt) GoodsAmt,
ProdDiscAmt,PD.TradeDisc TradeDiscAmt,PD.AddnlDisc AddnlDiscAmt
FROM tblTranSalesDetail PD
JOIN tblTranSalesHeader PH ON PH.ID = PD.InvID
JOIN tblMasterProduct MP ON MP.ID = PD.ProdID
JOIN tblMasterUOM UOM ON UOM.ID = PD.UomID
JOIN tblMasterTax MT ON MT.TaxID = PD.TaxID
LEFT JOIN TBLMASTERREASON MR ON MR.ID = PD.ReasonId
LEFT JOIN tblProductTransactionprices PTP ON PTP.ID = MP.ID
where PD.InvID = @ID
group by PD.ProdID,PD.UomID,MP.Code,MP.Name,MP.HSNCode,UOM.Name,PD.ProdDisc,PD.TradeDiscPern,PD.AddnlDiscPern,
Serial,MT.TaxName,PD.TaxValue,isnull(PD.ReasonId,0),MR.Name,PTP.PurchaseReturnPrice,PD.DiffValue,
ProdDiscAmt,pd.TradeDisc,PD.AddnlDisc,PH.TransactionType
ORDER BY Serial

SELECT InventoryId,ProdID,BatchNumber,PKDDate,ExpiryDate,(SUM(Qty)) Qty,(SUM(FreeQty)) FreeQty
,(SUM(DmgQty)) DmgQty,MRP,PurchasePrice,ReturnPrice,(SUM(PRQty)) PRQty,(SUM(PRFree)) PRFree
,(SUM(PRDmg)) PRDmg,TaxName,GSTPern,PurchaseTaxID,ConversionRate,UOMPrice FROM (
SELECT 0 InventoryId,PV.ProdID,P.BatchNumber BatchNumber,P.PKDDate PKDDate,P.ExpiryDate ExpiryDate,
(case when PH.TransactionType = 2 THEN SUM(UomQty) ELSE 0 END) Qty,
0 FreeQty,(case when PH.TransactionType = 3 THEN SUM(UomQty) ELSE 0 END) DmgQty,
(P.MRPONPrice) MRP,P.PurchasePrice PurchasePrice,
PV.UomPrice ReturnPrice,(case when PH.TransactionType = 2 THEN SUM(UomQty) ELSE 0 END)  PRQty,
0 PRFree,(case when PH.TransactionType = 3 THEN SUM(UomQty) ELSE 0 END)  PRDmg,MTT.TaxName,PV.TaxValue GSTPern,PV.TaxID PurchaseTaxID,
isnull(UOMCF,1) ConversionRate,PV.UomPrice UOMPrice
FROM tblTranSalesDetail PV
JOIN tblTranSalesHeader PH ON PH.ID = PV.InvID
JOIN tblProductInventory P ON P.InventoryId = PV.InventoryId
join tblMasterTax MTT ON MTT.TaxID = PV.TaxID
WHERE PV.InvID = @ID
GROUP BY P.BatchNumber,P.PKDDate,P.ExpiryDate,P.MRPONPrice,PV.ProdID,P.ReturnPrice,MTT.TaxName,PV.TaxValue,PV.TaxID,UOMCF,
P.PurchasePrice,PV.UomPrice,PH.TransactionType) AS REC
group by InventoryId,ProdID,BatchNumber,PKDDate,ExpiryDate,MRP,PurchasePrice,ReturnPrice,TaxName,GSTPern,
PurchaseTaxID,ConversionRate,UOMPrice

select ID,Name from tblMasterReason WHERE Active = 1 ORDER BY Name
end',
N'[export] nocount';
GO
/****** uspQtyReduceFromVanloading ******/
EXEC #Apply07 N'dbo.uspQtyReduceFromVanloading', 0x8C8717A5225F791192F295A2FA1800670CB2E5182F7144F05CE827CE5468C128, NULL, NULL, 0x743D2A8B41A0B4CAC5BDA2BBA1C532611BC94BE254DCBD62AED7B3954126660C, 0xD187DC5130B772B3268D0DB10F64487DDB73177384C154D41C504C67BB0A8E8A, NULL,
N'ALTER PROC [dbo].[uspQtyReduceFromVanloading]    
@Transaction VARCHAR(50),@BranchID INT,@AppPriceId INT,@InvoiceScopeId INT=NULL,@DispathScopeId INT=NULL,@DocDate DATE,    
@tvpTranSaleDetail tvpTranSaleDetail READONLY    
AS    
SET NOCOUNT ON;
BEGIN TRY    
DECLARE @ProdId INT,@BaseUomPrice DECIMAL (15,4),@UomId INT,@UomQty DECIMAL (15,4) ,@UomPrice DECIMAL (15,4),@GoodsAmt DECIMAL (15,4),    
@GrossAmt DECIMAL (15,4),    
@TaxId INT , @TaxPercentage DECIMAL (15,4) ,@TaxAmt DECIMAL (15,4),@NetAmt DECIMAL (15,4),@BatchNumber NVARCHAR(255),    
@PkgDate NVARCHAR(25),@ExpiryDate NVARCHAR(25),@InventoryPrice DECIMAL (15,4),@MRP DECIMAL (15,4),@InvQtyType INT ,@TempUomGroupId INT,    
@TempInventoryYesNo INT ,@TempBatchYesNo INT,@TempPKDYesNo INT,@TempSerialYesNo INT,@tvpCount INT, @tvpIndex INT,@ActiveCheck INT,    
@SaleUomCRate DECIMAL (15,4),@Qty DECIMAL (15,4),@SaleQty DECIMAL (15,4),@Index INT,@TrackInventory INT,@TrackBatch INT,@TrackPkd INT,    
@TrackSerial INT ,@UomGroupId INT,@PSerial NVARCHAR(255),@TempSerial INT ,    
@ProdSchemeID INT    
declare @dtluomqty decimal(15,4),@dtluomprice decimal(15,4),@dtlgross decimal(15,4),@dtltax decimal(15,4),@dtlnet decimal(15,4)  
--Detail stored in SalesDetail Table    
SET @tvpCount =(SELECT COUNT(*) FROM @tvpTranSaleDetail)    
SET @tvpIndex =1    
SET @TempSerial=1    
--Invoice Detail Using Table Value Parameter(TVP)    
--Loop through Table Value Parameter(TVP)    
WHILE @tvpCount >0    
BEGIN    
SELECT @ProdId=[ProdId],@BaseUomPrice =[BaseUomPrice] ,@UomId =[UomId] ,@UomQty =[UomQty] ,@UomPrice =[UomPrice] , @GoodsAmt =[GoodsAmt] ,    
@GrossAmt =[GrossAmt] ,@TaxId =[TaxId],    
@TaxPercentage =[TaxPercentage] ,@TaxAmt =[TaxAmt] ,@NetAmt =[NetAmt] ,@BatchNumber=[BatchNumber] ,@PkgDate =[PkgDate] ,    
@ExpiryDate =[ExpiryDate] ,@InventoryPrice =[InventoryPrice],@MRP =[MRP] ,@InvQtyType =[InvQtyType] ,--,@TempUomGroupId =[UomGroupId],    
@TempInventoryYesNo =[InventoryYesNo] ,@TempBatchYesNo=[BatchYesNo] ,@TempPKDYesNo=[PKDYesNo] ,@TempSerialYesNo =[SerialYesNo],    
@SaleUomCRate= isnull(UomCR,1)    
--,@ProdSchemeID = SecondarySchemeID    
FROM @tvpTranSaleDetail WHERE [Serial]=@tvpIndex    
--Verify Empty Row    
IF ISNULL(@ProdId,0)>0 AND ISNULL(@UomQty,0)>0    
BEGIN    
    
--Get Product Classification    
SELECT @TrackInventory= TrackInventory,@TrackBatch =TrackBatch ,@TrackPkd =TrackPDK,@TrackSerial=TrackSerial--,@SaleUomCRate=SalesCR--,@UomGroupId=UomGroupID    
FROM tblMasterProduct WITH (READCOMMITTEDLOCK) WHERE ID =@ProdId    
IF (ISNULL(@TrackInventory,0) != ISNULL(@TempInventoryYesNo,0) OR ISNULL(@TrackBatch,0) != ISNULL(@TempBatchYesNo,0) OR    
ISNULL(@TempPKDYesNo,0) != ISNULL(@TrackPkd,0) OR ISNULL(@TrackSerial,0) != ISNULL(@TempSerialYesNo,0))    
BEGIN    
RAISERROR(''Product classification already changed'',16,1);    
END    
--Convert Qty as Base UOM    
--SELECT @SaleUomCRate=ISNULL(ConversionRate,0) FROM tblMastUomGroupDetail WHERE UOMGroupID =@UomGroupId AND UOMMastID =@UomId    
IF ISNULL(@SaleUomCRate,0)=0    
BEGIN    
RAISERROR(''Selected UOM changed for that product'',16,1);    
END    
SET @Qty=@SaleUomCRate*@UomQty    
SET @SaleQty =@SaleUomCRate*@UomQty    
--Inventory Yes Procduct Only    
IF ISNULL(@TrackInventory,0) =1    
BEGIN    
--Inventory Base Uom Price    
--SET @InventoryPrice =(@InventoryPrice /@SaleUomCRate)    
--Check Date Weather NULL OR NOT NULL    
IF(ISNULL(@TrackPkd,0) =1)    
BEGIN    
SET @PkgDate =CONVERT(NVARCHAR,@PkgDate ,103)    
SET @ExpiryDate =CONVERT(NVARCHAR,@ExpiryDate ,103)    
END    
ELSE    
BEGIN    
SET @PkgDate =NULL    
SET @ExpiryDate=NULL    
END    
CREATE TABLE #InventoryId (Ident INT IDENTITY ,TempInvId INT,TempInvQty DECIMAL (15,4))    
    
    
CREATE TABLE #Temp (TDate DATE,TInventoryId INT,TInventoryQty DECIMAL (15,4))    
CREATE TABLE #TempReduceQty (TInventoryId INT,TInventoryQty DECIMAL (15,4))    
/*Sale Qty Only Get From Inventory Table */    
IF(@InvQtyType=1)    
BEGIN    
--Product Classification    
IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)=0 AND ISNULL(@TrackPkd,0)=0    
BEGIN    
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)    
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualQty>0 AND TransDate<=@DocDate AND MRPONPrice =@MRP    
AND (CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP    
WHEN @AppPriceId =4 THEN MRP WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END)=@InventoryPrice    
ORDER BY TransDate    
END    
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)<>0 AND ISNULL(@TrackPkd,0)=0    
BEGIN    
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)    
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualQty>0 AND TransDate<=@DocDate AND BatchNumber =@BatchNumber AND MRPONPrice =@MRP    
AND (CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP    
WHEN @AppPriceId =4 THEN MRP WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) =@InventoryPrice    
ORDER BY TransDate    
END    
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)<>0 AND ISNULL(@TrackPkd,0)<>0    
BEGIN    
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)    
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualQty>0 AND TransDate<=@DocDate AND BatchNumber =@BatchNumber AND PkdDate =@PkgDate AND ExpiryDate =@ExpiryDate AND MRPONPrice =@MRP AND    
(CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP    
WHEN @AppPriceId =4 THEN MRP WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) =@InventoryPrice    
ORDER BY TransDate    
END    
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)=0 AND ISNULL(@TrackPkd,0)<>0    
BEGIN    
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)    
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualQty>0 AND TransDate<=@DocDate AND PkdDate =@PkgDate AND ExpiryDate =@ExpiryDate AND MRPONPrice =@MRP AND    
(CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP    
WHEN @AppPriceId =4 THEN MRP WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) =@InventoryPrice    
ORDER BY TransDate    
END    
END    
/*Free Qty Only Get From Invnetory */    
ELSE IF(@InvQtyType=2)    
BEGIN    
--Product Classification    
IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)=0 AND ISNULL(@TrackPkd,0)=0    
BEGIN    
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualFreeQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)    
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualFreeQty>0 AND TransDate<=@DocDate    
ORDER BY TransDate    
END    
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)<>0 AND ISNULL(@TrackPkd,0)=0    
BEGIN    
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualFreeQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)    
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualFreeQty>0 AND TransDate<=@DocDate AND BatchNumber=@BatchNumber    
ORDER BY TransDate    
END    
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)<>0 AND ISNULL(@TrackPkd,0)<>0    
BEGIN    
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualFreeQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)    
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualFreeQty>0 AND TransDate<=@DocDate AND BatchNumber=@BatchNumber    
AND PkdDate=@PkgDate AND ExpiryDate=@ExpiryDate    
ORDER BY TransDate    
END    
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)=0 AND ISNULL(@TrackPkd,0)<>0    
BEGIN    
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualFreeQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)    
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualFreeQty>0 AND TransDate<=@DocDate AND PkdDate=@PkgDate AND ExpiryDate=@ExpiryDate    
ORDER BY TransDate    
END    
END    
-- Changed by Sriram G (Reduce Qty Order by Trans Date)    
INSERT INTO #TempReduceQty SELECT TInventoryId,SUM(TInventoryQty) FROM #Temp GROUP BY TDate,TInventoryId ORDER BY TDate    
/*Inventory Detail Adjustment in Inventory Table*/    
DECLARE @InventoryId INT,@InventoryQty DECIMAL(25, 9)    
DECLARE cursor_Inventory CURSOR LOCAL FAST_FORWARD FOR (SELECT TInventoryId,TInventoryQty AS Qty FROM #TempReduceQty)    
OPEN cursor_Inventory    
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty    
WHILE @@FETCH_STATUS =0    
BEGIN    
--Loop Exist Qty Adjusted After    
IF(@SaleQty =0)    
BEGIN    
BREAK;    
END    
--Qty Type SALE    
IF(@InvQtyType=1)    
BEGIN  IF @SaleQty >@InventoryQty    
BEGIN    
UPDATE tblProductInventory SET ActualQty =ISNULL(ActualQty,0)-ISNULL(@InventoryQty,0),VLSQty = ISNULL(VLSQty,0)+ISNULL(@InventoryQty,0),    
mdate = getdate() WHERE InventoryId =@InventoryId    
SET @SaleQty =@SaleQty -@InventoryQty    
INSERT INTO #InventoryId VALUES (@InventoryId,@InventoryQty)    
END    
ELSE IF @SaleQty <@InventoryQty    
BEGIN    
UPDATE tblProductInventory SET ActualQty =ISNULL(@InventoryQty,0)-ISNULL(@SaleQty,0),VLSQty = ISNULL(VLSQty,0)+ISNULL(@SaleQty,0),    
mdate = getdate() WHERE InventoryId =@InventoryId    
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)    
SET @SaleQty =0    
END    
ELSE IF @SaleQty=@InventoryQty    
BEGIN    
UPDATE tblProductInventory SET ActualQty =ISNULL(@InventoryQty,0)-ISNULL(@SaleQty,0),VLSQty = ISNULL(VLSQty,0)+ISNULL(@SaleQty,0),    
mdate = getdate() WHERE InventoryId =@InventoryId    
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)    
SET @SaleQty =0    
END    
END    
--Qty Type FREE    
ELSE IF(@InvQtyType=2)    
BEGIN    
IF @SaleQty >@InventoryQty    
BEGIN    
UPDATE tblProductInventory SET ActualFreeQty =ISNULL(ActualFreeQty,0)-ISNULL(@InventoryQty,0),VLSFreeQty = ISNULL(VLSFreeQty,0)+ISNULL(@SaleQty,0),    
mdate = getdate() WHERE InventoryId =@InventoryId    
SET @SaleQty =@SaleQty -@InventoryQty    
INSERT INTO #InventoryId VALUES (@InventoryId,@InventoryQty)    
END    
ELSE IF @SaleQty <@InventoryQty    
BEGIN    
UPDATE tblProductInventory SET ActualFreeQty =ISNULL(@InventoryQty,0)-ISNULL(@SaleQty,0),VLSFreeQty = ISNULL(VLSFreeQty,0)+ISNULL(@SaleQty,0),    
mdate = getdate() WHERE InventoryId =@InventoryId    
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)    
SET @SaleQty =0    
END    
ELSE IF @SaleQty=@InventoryQty    
BEGIN    
UPDATE tblProductInventory SET ActualFreeQty =ISNULL(@InventoryQty,0)-ISNULL(@SaleQty,0),VLSFreeQty = ISNULL(VLSFreeQty,0)+ISNULL(@SaleQty,0),    
mdate = getdate() WHERE InventoryId =@InventoryId    
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)    
SET @SaleQty =0    
END    
END    
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty    
END    
CLOSE cursor_Inventory    
DEALLOCATE cursor_Inventory    
/*Sales Detail Table Store the Detail Based On Serial and Inventory Adjusted Row wies*/    
IF ISNULL(@SaleQty,0) !=0    
BEGIN    
RAISERROR(''Qty Mismatched'',16,1);    
END    
ELSE    
BEGIN    
DECLARE @InsertCount INT=(SELECT COUNT(*) FROM #InventoryId )    
DECLARE @InsertIdent INT SET @InsertIdent=1;    
DECLARE @InvAdjId INT,@InvAdjQty DECIMAL(25, 9)    
SET @Index=1    
--loop Inentory Adjustment Qty    
  
WHILE @InsertCount>0    
BEGIn    
SET @InvAdjId=(SELECT TempInvId FROM #InventoryId WHERE Ident=@InsertIdent)    
SET @InvAdjQty=(SELECT TempInvQty FROM #InventoryId WHERE Ident=@InsertIdent)    
IF @Index=@Index--1    
BEGIN    
set @dtluomqty = (@InvAdjQty / @SaleUomCRate)  
set @dtluomprice = (@BaseUomPrice * @SaleUomCRate)  
set @dtlgross = (@dtluomqty * @dtluomprice)  
set @dtltax = (select dbo.fngetMRPonTaxValue(2,@dtlgross,@MRP,@TaxId,1))  
SET @dtltax = @dtltax * @dtluomqty
--(@dtlgross * @TaxPercentage) / 100  
set @dtlnet = @dtlgross + @dtltax  
INSERT INTO dbo.tblVanLoadingSlipDetail(Id,InventoryId,AdjustQty,ProdId,BaseUomPrice,UomId,UomQty,UomPrice,    
UOMCF,MRP,GrossAmt,TaxId,TaxValue,TaxAmt,NetAmt,Serial,QtyType)    
VALUES(@InvoiceScopeId,@InvAdjId ,@InvAdjQty,@ProdId ,@BaseUomPrice,@UomId,@dtluomqty,  
@dtluomprice, --@UomQty ,@UomPrice,    
@SaleUomCRate,@MRP,@dtlgross ,@TaxId,@TaxPercentage,@dtltax,@dtlnet,@TempSerial,@InvQtyType)    
    
ENd    
ELSE    
BEGIN    
IF @Transaction =''DIRECT_SALE''    
BEGIN    
--Sales    
INSERT INTO tblVanLoadingSlipDetail(Id,ProdId,InventoryId,AdjustQty,QtyType,Serial,MRP,UOMCF)    
VALUES(@InvoiceScopeId,@ProdId,@InvAdjId,@InvAdjQty,@PSerial,@InvQtyType,@MRP,@SaleUomCRate)    
END    
END    
SET @Index=@Index+1    
--Insert Loop Increment    
SET @InsertIdent=@InsertIdent+1;    
SET @InsertCount=@InsertCount-1;    
END    
--Destroy Table    
DROP TABLE #Temp;    
DROP TABLE #TempReduceQty;    
DROP TABLE #InventoryId;    
END    
END    
SET @TempSerial =@TempSerial+1 ;    
END    
SET @tvpIndex =@tvpIndex+1    
SET @tvpCount =@tvpCount-1;    
END    
END TRY    
BEGIN CATCH    
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE(),@ProdId;    
END CATCH',
N'[export] nocount;cursor-local-fast_forward=1;readcommittedlock=9';
GO
/****** uspQtyReduceInventory ******/
EXEC #Apply07 N'dbo.uspQtyReduceInventory', 0x293256FAEA40C4AB54776B51E1670AC8F508842EB5C6420235857BFB03BE9BD5, NULL, NULL, 0x1FD2D67F2AC9EC078155617D295B36B47BB65EF69E01B1FE2FE0DB824CA4A04E, 0x977723B536C8BD75A36F3B1D2E420CE04517C3F06D2E85E8EFC58C4A94D11FB0, NULL,
N'ALTER PROCEDURE [dbo].[uspQtyReduceInventory]                  
@Transaction VARCHAR(50),@BranchID INT,@AppPriceId INT,@InvoiceScopeId INT=NULL,@DispathScopeId INT=NULL,@DocDate DATE,                  
@tvpTranSaleDetail tvpTranSaleDetail READONLY,@tvpProdSerialInfo tvpProdSerialInfo READONLY                  
AS                  
SET NOCOUNT ON;
BEGIN TRY                  
DECLARE @ProdId INT,@BaseUomPrice DECIMAL (25,6),@UomId INT,@UomQty DECIMAL (25,6) ,@UomPrice DECIMAL (25,6),@GoodsAmt DECIMAL (25,6),                  
@GrossAmt DECIMAL (25,6),@UserDisc DECIMAL (25,6),@ProdDisc DECIMAL (25,6),@TradeDisc DECIMAL (25,6),@AddnlDisc DECIMAL (25,6),                  
@TaxId INT , @TaxPercentage DECIMAL (25,6) ,@TaxAmt DECIMAL (25,6),@NetAmt DECIMAL (25,6),@BatchNumber NVARCHAR(255),                  
@PkgDate NVARCHAR(25),@ExpiryDate NVARCHAR(25),@InventoryPrice DECIMAL (25,6),@MRP DECIMAL (25,6),@InvQtyType INT ,@TempUomGroupId INT,                  
@TempInventoryYesNo INT ,@TempBatchYesNo INT,@TempPKDYesNo INT,@TempSerialYesNo INT,@tvpCount INT, @tvpIndex INT,@ActiveCheck INT,                  
@SaleUomCRate DECIMAL (25,6),@Qty DECIMAL (25,6),@SaleQty DECIMAL (25,6),@Index INT,@TrackInventory INT,@TrackBatch INT,@TrackPkd INT,                  
@TrackSerial INT ,@UomGroupId INT,@PSerial NVARCHAR(255),@TempSerial INT,@UserDiscAmt DECIMAL (25,6)=NULL,@ProdDiscAmt DECIMAL (25,6)=NULL ,                  
@TradeDiscPerc DECIMAL (25,6)=NULL,@AddnlDiscPerc DECIMAL (25,6)=NULL ,@ProdSchemeID INT,@DiffVal DECIMAL(25,4) = 0,
@ReasonID INT
--Detail stored in SalesDetail Table                  
SET @tvpCount =(SELECT COUNT(*) FROM @tvpTranSaleDetail)                  
SET @tvpIndex =1                  
SET @TempSerial=1                  
--Invoice Detail Using Table Value Parameter(TVP)                  
--Loop through Table Value Parameter(TVP)                  
WHILE @tvpCount >0                  
BEGIN                  
SELECT @ProdId=[ProdId],@BaseUomPrice =[BaseUomPrice] ,@UomId =[UomId] ,@UomQty =[UomQty] ,@UomPrice =[UomPrice] , @GoodsAmt =[GoodsAmt] ,                  
@UserDisc =[UserDisc] ,@ProdDisc =[ProdDisc] ,@TradeDisc =[TradeDisc] ,@AddnlDisc =[AddnlDisc] ,@GrossAmt =[GrossAmt] ,@TaxId =[TaxId],                  
@TaxPercentage =[TaxPercentage] ,@TaxAmt =[TaxAmt] ,@NetAmt =[NetAmt] ,@BatchNumber=[BatchNumber] ,@PkgDate =[PkgDate] ,                  
@ExpiryDate =[ExpiryDate] ,@InventoryPrice =[InventoryPrice],@MRP =[MRP] ,@InvQtyType =[InvQtyType] ,--,@TempUomGroupId =[UomGroupId],                  
@TempInventoryYesNo =[InventoryYesNo] ,@TempBatchYesNo=[BatchYesNo] ,@TempPKDYesNo=[PKDYesNo] ,@TempSerialYesNo =[SerialYesNo],                  
@UserDiscAmt=UserDiscAmt,@ProdDiscAmt=ProdDiscAmt ,@TradeDiscPerc=TradeDiscPern ,@AddnlDiscPerc=AddnlDiscPern,@SaleUomCRate= UomCR  ,        
@DiffVal = DiffVal,@ReasonID = ReasonId
--,@ProdSchemeID = SecondarySchemeID          
FROM @tvpTranSaleDetail WHERE [Serial]=@tvpIndex                  
--Verify Empty Row                  
IF ISNULL(@ProdId,0)>0 AND ISNULL(@UomQty,0)>0                  
BEGIN                  
                  
--Get Product Classification                  
SELECT @TrackInventory= TrackInventory,@TrackBatch =TrackBatch ,@TrackPkd =TrackPDK,@TrackSerial=TrackSerial--,@SaleUomCRate=SalesCR--,@UomGroupId=UomGroupID                  
FROM tblMasterProduct WITH (READCOMMITTEDLOCK) WHERE ID =@ProdId                  
IF (ISNULL(@TrackInventory,0) != ISNULL(@TempInventoryYesNo,0) OR ISNULL(@TrackBatch,0) != ISNULL(@TempBatchYesNo,0) OR                  
ISNULL(@TempPKDYesNo,0) != ISNULL(@TrackPkd,0)  OR ISNULL(@TrackSerial,0) != ISNULL(@TempSerialYesNo,0))                  
BEGIN                  
RAISERROR(''6'',16,1);                  
END                  
--Convert Qty as Base UOM                  
--SELECT @SaleUomCRate=ISNULL(ConversionRate,0) FROM tblMastUomGroupDetail WHERE UOMGroupID =@UomGroupId AND UOMMastID =@UomId                  
IF ISNULL(@SaleUomCRate,0)=0                  
BEGIN                  
RAISERROR(''12'',16,1);                  
END              
SET @Qty=@SaleUomCRate*@UomQty                  
SET @SaleQty =@SaleUomCRate*@UomQty                 
--Inventory Yes Procduct Only                  
IF ISNULL(@TrackInventory,0) =1       
BEGIN                  
--Inventory Base Uom Price                  
--SET @InventoryPrice =(@InventoryPrice /@SaleUomCRate)                  
--Check Date Weather NULL OR NOT NULL                  
IF(ISNULL(@TrackPkd,0) =1)                  
BEGIN                  
SET @PkgDate =CONVERT(NVARCHAR,@PkgDate ,103)                  
SET @ExpiryDate =CONVERT(NVARCHAR,@ExpiryDate ,103)                  
END                  
ELSE                  
BEGIN                  
SET @PkgDate =NULL                  
SET @ExpiryDate=NULL              
END                  
CREATE TABLE #InventoryId (Ident INT IDENTITY ,TempInvId INT,TempInvQty DECIMAL (25,6))                  
                  
                  
CREATE TABLE #Temp (TDate DATE,TInventoryId INT,TInventoryQty DECIMAL (25,6))                  
CREATE TABLE #TempReduceQty (TInventoryId INT,TInventoryQty DECIMAL (25,6))                  
/*Sale Qty Only Get From Inventory Table */                  
IF(@InvQtyType=1)                  
BEGIN                  
--Product Classification                  
IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)=0 AND ISNULL(@TrackPkd,0)=0                  
BEGIN                  
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)                  
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualQty>0 AND TransDate<=@DocDate AND MRPONPrice =@MRP                  
AND (CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP                 
WHEN @AppPriceId =4 THEN MRP  WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END)=@InventoryPrice                  
ORDER BY TransDate                  
END                  
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)<>0 AND ISNULL(@TrackPkd,0)=0                  
BEGIN                  
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)                  
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualQty>0 AND TransDate<=@DocDate AND BatchNumber =@BatchNumber AND MRPONPrice =@MRP                  
AND (CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP                 
WHEN @AppPriceId =4 THEN MRP  WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) =@InventoryPrice                  
ORDER BY TransDate                  
END                  
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)<>0 AND ISNULL(@TrackPkd,0)<>0                  
BEGIN                  
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)                  
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualQty>0 AND TransDate<=@DocDate AND BatchNumber =@BatchNumber AND PkdDate =@PkgDate AND ExpiryDate =@ExpiryDate AND MRPONPrice =@MRP AND                  
(CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP                 
WHEN @AppPriceId =4 THEN MRP  WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) =@InventoryPrice                  
ORDER BY TransDate                  
END                  
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)=0 AND ISNULL(@TrackPkd,0)<>0                  
BEGIN                  
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)                  
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualQty>0 AND TransDate<=@DocDate AND PkdDate =@PkgDate AND ExpiryDate =@ExpiryDate AND MRPONPrice =@MRP AND                  
(CASE WHEN @AppPriceId =1 THEN PurchasePrice WHEN @AppPriceId =2 THEN SalesPrice WHEN @AppPriceId =3 THEN ECP                 
WHEN @AppPriceId =4 THEN MRP  WHEN @AppPriceId =5 THEN SPLPrice ELSE ReturnPrice END) =@InventoryPrice                  
ORDER BY TransDate                  
END                  
END                  
/*Free Qty Only Get From Invnetory */                  
ELSE IF(@InvQtyType=2)                  
BEGIN                  
--Product Classification      
IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)=0 AND ISNULL(@TrackPkd,0)=0                  
BEGIN                  
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualFreeQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)            
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualFreeQty>0 AND TransDate<=@DocDate                  
ORDER BY TransDate                  
END                  
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)<>0 AND ISNULL(@TrackPkd,0)=0                  
BEGIN                  
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualFreeQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)                  
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualFreeQty>0 AND TransDate<=@DocDate AND BatchNumber=@BatchNumber                  
ORDER BY TransDate                  
END                  
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)<>0 AND ISNULL(@TrackPkd,0)<>0                  
BEGIN                  
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualFreeQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)                  
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualFreeQty>0 AND TransDate<=@DocDate AND BatchNumber=@BatchNumber                  
AND PkdDate=@PkgDate AND ExpiryDate=@ExpiryDate                  
ORDER BY TransDate                  
END                  
ELSE IF ISNULL(@TrackInventory,0)<>0 AND ISNULL(@TrackBatch,0)=0 AND ISNULL(@TrackPkd,0)<>0                  
BEGIN                  
INSERT INTO #Temp SELECT TransDate,InventoryId,ActualFreeQty FROM tblProductInventory WITH (READCOMMITTEDLOCK)                  
WHERE ProdId =@ProdId and BranchID = @BranchID AND ActualFreeQty>0 AND TransDate<=@DocDate AND PkdDate=@PkgDate AND ExpiryDate=@ExpiryDate                  
ORDER BY TransDate                  
END                  
END                  
-- Changed by Sriram G (Reduce Qty Order by Trans Date)                  
INSERT INTO #TempReduceQty SELECT TInventoryId,SUM(TInventoryQty) FROM #Temp GROUP BY TDate,TInventoryId ORDER BY TDate                  
/*Inventory Detail Adjustment in Inventory Table*/                  
DECLARE @InventoryId INT,@InventoryQty DECIMAL(25, 9)                  
DECLARE cursor_Inventory CURSOR LOCAL FAST_FORWARD FOR (SELECT TInventoryId,TInventoryQty AS Qty FROM #TempReduceQty)                  
OPEN cursor_Inventory                  
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty                  
WHILE @@FETCH_STATUS =0                  
BEGIN                  
--Loop Exist Qty Adjusted After                  
IF(@SaleQty =0)                  
BEGIN                  
BREAK;                  
END                  
--Qty Type SALE                  
IF(@InvQtyType=1) BEGIN                  
IF @SaleQty >@InventoryQty                  
BEGIN                  
UPDATE tblProductInventory SET ActualQty =ISNULL(ActualQty,0)-ISNULL(@InventoryQty,0),InvoiceQty = ISNULL(InvoiceQty,0)+ISNULL(@SaleQty,0),      
mdate = getdate() WHERE InventoryId =@InventoryId                  
SET @SaleQty =@SaleQty -@InventoryQty                  
INSERT INTO #InventoryId VALUES (@InventoryId,@InventoryQty)                  
END                  
ELSE IF @SaleQty <@InventoryQty                  
BEGIN                  
UPDATE tblProductInventory SET ActualQty =ISNULL(@InventoryQty,0)-ISNULL(@SaleQty,0),InvoiceQty = ISNULL(InvoiceQty,0)+ISNULL(@SaleQty,0),      
mdate = getdate() WHERE InventoryId =@InventoryId                  
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)                  
SET @SaleQty =0                  
END                  
ELSE IF @SaleQty=@InventoryQty                  
BEGIN      
UPDATE tblProductInventory SET ActualQty =ISNULL(@InventoryQty,0)-ISNULL(@SaleQty,0),InvoiceQty = ISNULL(InvoiceQty,0)+ISNULL(@SaleQty,0),      
mdate = getdate() WHERE InventoryId =@InventoryId                  
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)                  
SET @SaleQty =0                  
END                  
END                  
--Qty Type FREE                  
ELSE IF(@InvQtyType=2)                  
BEGIN                  
IF @SaleQty >@InventoryQty                  
BEGIN                  
UPDATE tblProductInventory SET ActualFreeQty =ISNULL(ActualFreeQty,0)-ISNULL(@InventoryQty,0),InvoiceFreeQty = ISNULL(InvoiceFreeQty,0)+ISNULL(@SaleQty,0),      
mdate = getdate() WHERE InventoryId =@InventoryId                  
SET @SaleQty =@SaleQty -@InventoryQty                  
INSERT INTO #InventoryId VALUES (@InventoryId,@InventoryQty)                  
END                  
ELSE IF @SaleQty <@InventoryQty           
BEGIN                  
UPDATE tblProductInventory SET ActualFreeQty =ISNULL(@InventoryQty,0)-ISNULL(@SaleQty,0),InvoiceFreeQty = ISNULL(InvoiceFreeQty,0)+ISNULL(@SaleQty,0),      
mdate = getdate() WHERE InventoryId =@InventoryId                  
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)                  
SET @SaleQty =0                  
END                  
ELSE IF @SaleQty=@InventoryQty                  
BEGIN                  
UPDATE tblProductInventory SET ActualFreeQty =ISNULL(@InventoryQty,0)-ISNULL(@SaleQty,0),InvoiceFreeQty = ISNULL(InvoiceFreeQty,0)+ISNULL(@SaleQty,0),      
mdate = getdate() WHERE InventoryId =@InventoryId                  
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty)                  
SET @SaleQty =0                  
END                  
END                  
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty            END                  
CLOSE cursor_Inventory                  
DEALLOCATE cursor_Inventory                  
/*Sales Detail Table Store the Detail Based On Serial and Inventory Adjusted Row wies*/                  
IF ISNULL(@SaleQty,0) !=0                  
BEGIN                  
RAISERROR(''13'',16,1);                  
END                  
ELSE                  
BEGIN                  
DECLARE @InsertCount INT=(SELECT COUNT(*) FROM #InventoryId )                  
DECLARE @InsertIdent INT SET @InsertIdent=1;                  
DECLARE @InvAdjId INT,@InvAdjQty DECIMAL(25, 9)                  
SET @Index=1                  
--loop Inentory Adjustment Qty                  
WHILE @InsertCount>0                  
BEGIn                  
SET @InvAdjId=(SELECT TempInvId FROM #InventoryId WHERE Ident=@InsertIdent)                  
SET @InvAdjQty=(SELECT TempInvQty FROM #InventoryId WHERE Ident=@InsertIdent)                  
IF @Index=1                  
BEGIN                  
--EXEC uspInsertSalesHeaderDetail @Transaction,@InvoiceScopeId,@DispathScopeId,@InvAdjId ,@InvAdjQty,@ProdId,@UomGroupId ,@BaseUomPrice,@UomQty,@UomId ,@UomPrice,--@InventoryPrice REPLACED @BaseUomPrice                  
--@GoodsAmt,@UserDisc ,@ProdDisc ,@TradeDisc ,@AddnlDisc,@GrossAmt,@TaxId,@TaxPercentage,@TaxAmt,@NetAmt,@TempSerial,@InvQtyType,NULL,NULL,@MRP,                  
--@UserDiscAmt,@ProdDiscAmt,@TradeDiscPerc,@AddnlDiscPerc                  
                  
INSERT INTO dbo.tblTranSalesDetail(InvId,InventoryId,AdjustQty,ProdId,BaseUomPrice,UomQty,UomId,UomPrice,GoodsAmt,                  
ProdDisc,TradeDisc,AddnlDisc,GrossAmt,TaxId,TaxValue,TaxAmt,NetAmt,Serial,QtyType,ProdSerial,ReasonId,DetailMRP,ProdDiscAmt,          
TradeDiscPern,AddnlDiscPern,DiffValue,UOMCF)--,SecondarySchemeID          
VALUES(@InvoiceScopeId,@InvAdjId ,@InvAdjQty,@ProdId ,@BaseUomPrice,@UomQty,@UomId ,@UomPrice,@GoodsAmt ,                  
@ProdDisc ,@TradeDisc ,@AddnlDisc,@GrossAmt ,@TaxId,@TaxPercentage,@TaxAmt,@NetAmt,@TempSerial,@InvQtyType,null,@ReasonID,ISNULL(@MRP,0),                  
@ProdDiscAmt,@TradeDiscPerc,@AddnlDiscPerc,@DiffVal,@SaleUomCRate)--,@ProdSchemeID          
                  
END                  
ELSE                  
BEGIN                  
IF @Transaction =''DIRECT_SALE''                  
BEGIN                  
--Sales                  
INSERT INTO tblTranSalesDetail(InvId,ProdId,InventoryId,AdjustQty,ProdSerial,QtyType,Serial,DetailMRP,UOMCF)                  
VALUES(@InvoiceScopeId,@ProdId,@InvAdjId,@InvAdjQty,@PSerial,@InvQtyType,@TempSerial,@MRP,@SaleUomCRate)                  
END                  
END                  
SET @Index=@Index+1                  
--Insert Loop Increment                  
SET @InsertIdent=@InsertIdent+1;                  
SET @InsertCount=@InsertCount-1;                  
END                  
--Destroy Table                  
DROP TABLE #Temp;                  
DROP TABLE #TempReduceQty;       
DROP TABLE #InventoryId;                  
IF ISNULL(@TrackSerial,0)=1                  
BEGIN                  
--Get Serial as Per Row wise                  
DECLARE @SerialCount INT,@SerialIdent INT                  
SET @SerialIdent =1                  
CREATE TABLE #tblTempSerial (Ident INT IDENTITY,ProductSerial NVARCHAR(255))                  
INSERT INTO #tblTempSerial(ProductSerial) SELECT Serial FROM @tvpProdSerialInfo WHERE ProdId=@ProdId AND RowIndex=@tvpIndex-1                  
SET @SerialCount =(SELECT COUNT(*) FROM #tblTempSerial)                  
--loop Inentory Adjustment Qty                  
WHILE @SerialCount>0                  
BEGIN                  
SET @PSerial =(SELECT ProductSerial FROM #tblTempSerial WHERE Ident =@SerialIdent)                  
IF @Transaction =''DIRECT_SALE''                  
BEGIN                  
                  
--Sales                  
INSERT INTO tblTranSalesDetail(InvId,ProdId,ProdSerial,QtyType,Serial,DetailMRP,UOMCF)                  
VALUES(@InvoiceScopeId,@ProdId,@PSerial,@InvQtyType,@TempSerial,@MRP,@SaleUomCRate)                  
END                  
--Insert Loop Increment                  
SET @SerialIdent=@SerialIdent+1;                  
SET @SerialCount=@SerialCount-1;                  
END                  
DROP TABLE #tblTempSerial                  
SET @PSerial=NULL;                  
END                  
END                  
END                  
--Inventory No Procduct Only                  
ELSE IF ISNULL(@TrackInventory,0)=0                  
BEGIN                  
--EXEC uspInsertSalesHeaderDetail @Transaction,@InvoiceScopeId,@DispathScopeId,NULL ,NULL,@ProdId,@UomGroupId ,@BaseUomPrice,@UomQty,@UomId ,                  
--@UomPrice,@GoodsAmt, @UserDisc ,@ProdDisc ,@TradeDisc ,@AddnlDisc,@GrossAmt ,@TaxId,@TaxPercentage,@TaxAmt,@NetAmt,@TempSerial,NULL,NULL,NULL,@MRP,                  
--@UserDiscAmt,@ProdDiscAmt,@TradeDiscPerc,@AddnlDiscPerc                  
INSERT INTO dbo.tblTranSalesDetail(InvId,InventoryId,AdjustQty,ProdId,BaseUomPrice,UomQty,UomId,UomPrice,GoodsAmt,                  
ProdDisc,TradeDisc,AddnlDisc,GrossAmt,TaxId,TaxValue,TaxAmt,NetAmt,Serial,QtyType,ProdSerial,ReasonId,DetailMRP,ProdDiscAmt,TradeDiscPern,          
AddnlDiscPern,DiffValue,UOMCF)        --,SecondarySchemeID          
VALUES(@InvoiceScopeId,@InvAdjId ,@InvAdjQty,@ProdId ,@BaseUomPrice,@UomQty,@UomId ,@UomPrice,@GoodsAmt ,                  
@ProdDisc ,@TradeDisc ,@AddnlDisc,@GrossAmt ,@TaxId,@TaxPercentage,@TaxAmt,@NetAmt,@TempSerial,@InvQtyType,null,@ReasonID,ISNULL(@MRP,0),                  
@ProdDiscAmt,@TradeDiscPerc,@AddnlDiscPerc,@DiffVal,@SaleUomCRate)--,@ProdSchemeID          
--Track Inventory No but Track Serial Yes                  
IF ISNULL(@TrackSerial,0)=1                  
BEGIN                  
DECLARE cursor_ProdSerial CURSOR LOCAL FAST_FORWARD FOR SELECT Serial FROM @tvpProdSerialInfo WHERE ProdId=@ProdId AND RowIndex=@tvpIndex-1                  
OPEN cursor_ProdSerial                  
FETCH NEXT FROM cursor_ProdSerial INTO @PSerial                  
WHILE @@FETCH_STATUS =0                  
BEGIN                  
IF @Transaction =''DIRECT_SALE''                  
BEGIN                  
--Sales                  
INSERT INTO tblTranSalesDetail(InvId,ProdId,AdjustQty,ProdSerial,Serial,DetailMRP,UOMCF)                  
VALUES(@InvoiceScopeId,@ProdId,1,@PSerial,@TempSerial,@MRP,@SaleUomCRate)                  
END                  
FETCH NEXT FROM cursor_ProdSerial INTO @PSerial                  
END     
CLOSE cursor_ProdSerial                  
DEALLOCATE cursor_ProdSerial                  
SET @PSerial=NULL                  
END                  
END                  
SET @TempSerial =@TempSerial+1 ;                  
END                  
SET @tvpIndex =@tvpIndex+1                  
SET @tvpCount =@tvpCount-1;                  
END                  
END TRY                  
BEGIN CATCH                  
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE(),@ProdId;                  
END CATCH',
N'[export] nocount;cursor-local-fast_forward=2;readcommittedlock=9';
GO
/****** uspQuotationDetail ******/
EXEC #Apply07 N'dbo.uspQuotationDetail', 0x8BD9E8F958AF92D7D99A68A027AC8BC4D1BD7E1D053BA645A202EDAF65C35148, NULL, NULL, 0xD6FD347A30FB92EDF4D46FD34C23D635EF5002A071361114E02D779DDA2D4CF1, 0xD915CB137AE0F958E2BAAEE61BB5A7D35FEBFF8DC1A19421E19756FEC0D80445, NULL,
N'--[uspQuotationDetail] 2                
ALTER PROC [dbo].[uspQuotationDetail]                                                          
@QUID NVARCHAR(255)=NULL                                                            
AS                                                          
SET NOCOUNT ON;
BEGIN                            
                            
SELECT ProdID,Serial [Temp Serial],(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],                                                  
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],                                                  
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],                                           
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],                                                  
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],                    
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],                    
SUM([GCESS Amount]  + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount]  INTO #Tax                            
FROM                                                  
(                                    
                                    
SELECT SRI.ProdID,SRI.Serial,--SRI.[Gross Amount],                                              
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],                                                  
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],                                                  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],                                                  
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],                                                  
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],                                                  
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],                                           
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],                                                  
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],                     
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],                                          
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],                                         
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],                                                  
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],                                          
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],                                                  
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],                    
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],                                
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]                     
FROM                                                  
(                                                
SELECT * FROM                                    
(                                                  
SELECT Temp.ProdID,Temp.Serial,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],                                              
Temp.TaxName AS TaxName,                                
SUM(Temp.TaxValue) AS [TaxValue]--, SUM(Temp.[Gross Amount]) AS [Gross Amount]                                      
FROM                                                  
(                               
SELECT GSTInfo.ProdID,GSTInfo.SERIAL,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,                                        
CASE                                          
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''                                           
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''                                                  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''                                                  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''                     
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''                                   
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''                                    
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''                     
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''                                   
END AS [GST Comp]--, GSTInfo.GrossAmt AS [Gross Amount]                               
FROM tblTransGSTInfo AS GSTInfo                                          
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID                                       
WHERE TransIdentID=@QUID AND TransID=14                            
) Temp                                       
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.ProdID,Temp.Serial                                    
) src                                                  
PIVOT                                                  
(                                                  
SUM([TaxValue])                                                  
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])                    
) piv                                                  
) AS SRI                                                  
) AS RAM                                              
GROUP BY ProdID,Serial--,[CGST %]                              
--ORDER BY RAM.[CGST %] ASC                                
declare @oby NVARCHAR(10) = 0--(SELECT AppValue FROM tblAppConfig WHERE AppId = 167)                  
                  
SELECT IDENTITY (INT, 1, 1) AS NEW_ID,QUDETAIL.ProdID,PROD.CODE AS [Product Code],PROD.NAME AS [Product Name],PROD.HSNCode AS [HSN Code],                            
Loc.Name AS [Location Name],PROD.Remarks AS [Remark1],prod.WebOrder AS [Commodity Code],'''' AS [Uom Group Name],                            
UOM.Name AS [Uom Name],QUDETAIL.QTY AS [Uom Qty],RepUom.Name [Reporting UOM],TAX.TAXNAME AS [Tax Name],          
--QUDETAIL.SalesPrice AS [Per Piece Exclusive Price],            
QUDETAIL.GrossAmt / QUDETAIL.Qty AS [Per Piece Exclusive Price],          
QUDETAIL.SalesPrice AS [Uom Price],QUDETAIL.SalesPrice + (QUDETAIL.SalesPrice * (QUDETAIL.TaxPercentage / 100)) as [Rate],            
QUDETAIL.GoodsAmt AS [Goods Amount],QUDETAIL.ProdDiscPern AS [Product Discount %],                           
(QUDETAIL.GoodsAmt * QUDETAIL.ProdDiscPern)/100 AS [Product Disc Amt],QUDETAIL.TradeDiscAmt AS [Trade Discount],                       
QUDETAIL.AddnlDiscAmt AS [Addnl Discount],QUDETAIL.GROSSAMT AS [Gross Amount],QUDETAIL.GROSSAMT AS [Tax Value],                            
QUDETAIL.TAXPERCENTAGE AS [Tax percentage],QUDETAIL.TAXAMT AS [Tax Amount],QUDETAIL.NETAMT AS [Net Amount],                            
--((QUDETAIL.SalesPrice * QUDETAIL.TaxPercentage) / 100) + QUDETAIL.SalesPrice as [Per Piece Inclusive Price],            
(QUDETAIL.NetAmt / QUDETAIL.Qty) as [Per Piece Inclusive Price],          
PROD.SalesCR AS [UOM CF],            
((QUDETAIL.ProdDiscPern * QUDETAIL.GoodsAmt) / 100) + QUDETAIL.TradeDiscAmt + QUDETAIL.AddnlDiscAmt as [Total Disc Amt],            
--QUDETAIL.SalesPrice - ((QUDETAIL.SalesPrice * QUDETAIL.TaxPercentage) / 100)   as [Exclu Price],                            
QUDETAIL.SalesPrice as [Exclu Price],QUDETAIL.DetailMRP [MRP],                        
(QUDETAIL.GrossAmt / QUDETAIL.Qty) as [Per Qty Amt],QUDETAIL.Serial AS [Serial],'''' AS [ProdSerial],                            
ROW_NUMBER() OVER (ORDER BY QUDETAIL.QUATIONID) AS [Serial No],Header.DocPrefix AS [Doc Prefix],                            
'''' [T_Prod_Code],'''' [T_Prod_Name],                              
'''' [T_EAN],'''' [T_UD_Code],'''' [T_UD_Name],(Qty / PROD.ReportingQty) [Reporting Qty],(Qty * SalesCR) AS [Base Qty],                
SalesCR AS [Deft_S_UOM_CF],                
(Qty * SalesCR)  AS [Deft_S_UOM_Qty],                
(QUDETAIL.SalesPrice / SalesCR) AS [Base Uom Price],  
--dbo.fngetMRPonCumValue(1,QUDETAIL.TaxId,Header.TaxTypeId,QUDETAIL.DetailMRP) MRPOnValue,        
--dbo.fngetMRPonCumValue(2,QUDETAIL.TaxId,Header.TaxTypeId,QUDETAIL.DetailMRP) MRPOnTaxAmt   
dbo.fngetMRPonTaxValue(1,(QUDETAIL.GrossAmt / QUDETAIL.Qty),QUDETAIL.DetailMRP,QUDETAIL.TaxId,Header.TaxTypeId) MRPOnValue,      
dbo.fngetMRPonTaxValue(2,(QUDETAIL.GrossAmt / QUDETAIL.Qty),QUDETAIL.DetailMRP,QUDETAIL.TaxId,Header.TaxTypeId) MRPOnTaxAmt 
INTO  #QTN                            
FROM DBO.tblQuotationDetail AS QUDETAIL                                  
Join tblQuotationHeader AS Header ON Header.ID=QUDETAIL.QuationID                                                           
JOIN tblMasterProduct AS PROD ON PROD.ID=QUDETAIL.PRODID                                    
JOIN DBO.TBLMASTERUOM AS UOM ON UOM.ID = QUDETAIL.UOMID                                 
JOIN DBO.TBLMASTERTAX AS TAX ON QUDETAIL.TAXID = TAX.TAXID        
JOIN dbo.tblMastERUom AS RepUom ON RepUom.ID = prod.ReportingUomID        
LEFT JOIN tblMastERLocation AS Loc ON Loc.ID=prod.LocationId                                        
WHERE QUDETAIL.QUATIONID= @QUID --ORDER BY QUDETAIL.SERIAL                            
                  
 ORDER BY (CASE WHEN @oby = ''0'' THEN Serial END) asc,                  
(CASE WHEN @oby = ''1'' THEN Prod.Name END) asc                   
                            
select [Product Code],[Product Name],[HSN Code],[Location Name],[Remark1],[Commodity Code],[Uom Group Name],                            
[Uom Name],[Uom Qty],[Reporting UOM],[Reporting Qty],[Tax Name],[Per Piece Exclusive Price],MRP as [MRP Price],[UOM CF],Rate,[Uom Price],[Goods Amount],[Product Discount %],[Product Disc Amt],                            
[Trade Discount],[Addnl Discount],[Total Disc Amt],[Gross Amount],[Tax Value],[Tax percentage],[Tax Amount],[Net Amount],[Per Piece Inclusive Price],                            
[Exclu Price],[Per Qty Amt],[Serial],[ProdSerial],NEW_ID AS [Serial No],[Doc Prefix],[T_Prod_Code],[T_Prod_Name],[T_EAN],                            
[T_UD_Code],[T_UD_Name],dbo.fnGetRoundedValue(sum([CGST %])) [CGST %],dbo.fnGetRoundedValue(sum([CGST Amount])) [CGST Amount],                              
dbo.fnGetRoundedValue(sum([SGST %])) [SGST %],                                    
dbo.fnGetRoundedValue(sum([SGST Amount])) [SGST Amount],                                    
dbo.fnGetRoundedValue(sum([UTGST %])) [UTGST %],dbo.fnGetRoundedValue(sum([UTGST Amount])) [UTGST Amount],                              
dbo.fnGetRoundedValue(sum([GCESS %])) [GCESS %], dbo.fnGetRoundedValue(SUM([GCESS Amount])) [GCESS Amount],                              
dbo.fnGetRoundedValue(sum([IGST %])) [IGST %],                                    
dbo.fnGetRoundedValue(sum([IGST Amount])) [IGST Amount],                              
dbo.fnGetRoundedValue(sum([ICESS %])) [ICESS %],dbo.fnGetRoundedValue(sum([ICESS Amount])) [ICESS Amount],                    
dbo.fnGetRoundedValue(sum(TX.[GUOM %])) [GUOM %],dbo.fnGetRoundedValue(sum(TX.[GUOM Amount])) [GUOM Amount],                    
dbo.fnGetRoundedValue(sum(TX.[IUOM %])) [IUOM %],dbo.fnGetRoundedValue(sum(TX.[IUOM Amount])) [IUOM Amount],                    
dbo.fnGetRoundedValue(sum(TX.[Cumulative CESS Amount])) [Cumulative CESS Amount],[Base Qty],[Deft_S_UOM_CF],[Deft_S_UOM_Qty],                
[Base Uom Price],dbo.fnGetRoundedValue(ISNULL(MRPOnValue,0)) MRPOnValue,dbo.fnGetRoundedValue(ISNULL(MRPOnTaxAmt,0)) MRPOnTaxAmt from #QTN qtn                  
left join #Tax tx on tx.ProdID = qtn.ProdID                            
group by  [Product Code],[Product Name],[HSN Code],[Location Name],[Remark1],[Commodity Code],[Uom Group Name],                            
[Uom Name],[Uom Qty],[Tax Name],[Per Piece Exclusive Price],[Goods Amount],[Product Discount %],[Product Disc Amt],                            
[Trade Discount],[Addnl Discount],[Gross Amount],[Tax Value],[Tax percentage],[Tax Amount],[Net Amount],[Per Piece Inclusive Price],                            
[Exclu Price],[Per Qty Amt],[Serial],[ProdSerial],[Serial No],[Doc Prefix],[T_Prod_Code],[T_Prod_Name],[T_EAN],                            
[T_UD_Code],[T_UD_Name],MRP,NEW_ID,[Base Qty],[Deft_S_UOM_CF],[Deft_S_UOM_Qty],[Base Uom Price] ,[UOM CF],[Total Disc Amt],Rate,[Uom Price]        
,[Reporting UOM],[Reporting Qty],MRPOnValue,MRPOnTaxAmt  
--ORDER BY [Serial No]                            
 ORDER BY (CASE WHEN @oby = ''0'' THEN NEW_ID END) asc,                  
(CASE WHEN @oby = ''1'' THEN [Product Name] END) asc                              
END',
N'[export] nocount';
GO
/****** uspQuotationHeader ******/
EXEC #Apply07 N'dbo.uspQuotationHeader', 0xB03BCC5989380B35BED4C53167DA56F92B17A0B922B63B4311069146B286D6EE, NULL, NULL, 0x0ABA645730941B65FF003722748B7B60CDD155FF833EFCBDB36AD2440B268DD7, 0x3B290C80CDD63477C2913D0A10A82038C847DB0FA4A86CCCEFD9AA4F0E5CEABB, NULL,
N'--uspQuotationHeader 15        
ALTER PROC [dbo].[uspQuotationHeader]                                                  
@DocValue INT =NULL                                                    
AS                                                  
SET NOCOUNT ON;
BEGIN          
SELECT QT.ID As [QT ID],Convert (nvarchar, QT.DocDate,103) as [Doc Date],Isnull(CONVERT(nvarchar(5),QT.MDate,108),CONVERT(nvarchar(5),QT .CDate,108)) as [Time],          
Doc.TransName as [Trans Name],QT.DocId as [Doc ID],UDN.DocName AS [UDN Name],QT.UDFDocId AS [UDN Doc ID],QT.DocValue as [Doc Value],       
Customer.Code as [Party Code],Customer.Name as [Party Name],Customer.mob1 as [Party Prim Mobile No],      
Customer.ph1 as [Party Prim Phone No],Customer.email as [Email ID] ,Customer.ContactPerson as [Contact Person],      
Customer.billadd1 AS [Party Bill Address 1],Customer.billadd2 as [Party Bill Address 2],Customer.billadd3 as [Party Bill Address 3],      
Customer.billadd1+Customer.billadd2+Customer.billadd3 as [Party Full Address],      
Customer.shipadd1 AS [Party Ship Address 1],Customer.shipadd2 as [Party Ship Address 2],Customer.shipadd3 as [Party Ship Address 3],      
QT.Remarks AS [Remark 1],'''' AS [Party Area Name]        
,(SELECT TOP 1 MB.Name FROM tblBeatSalesmanMapping CBS        
LEFT JOIN  tblMasterBeat MB ON MB.ID = CBS.BeatId WHERE CBS.CustomerId = QT.CustomerID ORDER BY CBS.Id) [Beat Name],        
(SELECT TOP 1 MB.Name FROM tblBeatSalesmanMapping CBS        
LEFT JOIN tblMasterSalesMan MB ON MB.ID = CBS.SalesmanId WHERE CBS.CustomerId = QT.CustomerID ORDER BY  CBS.Id) [Salesman Name],    
(SELECT TOP 1 MB.MobileNo FROM tblBeatSalesmanMapping CBS        
LEFT JOIN tblMasterSalesman MB ON MB.ID = CBS.SalesmanId WHERE CBS.CustomerId = QT.CustomerID ORDER BY  CBS.Id) [Salesman Mobile No],    
Customer.Pincode as [Party PinCode],'''' AS [Party Tin No],          
'''' AS [Party CST No],'''' as [Party CST Date],Customer.GSTIN AS [Party GSTIN],          
Customer.AadharNo AS [Party Aadhar Number],Customer.PANNumber AS [Party PAN No],'''' AS [Party ServiceTax No],          
Customer.FSSAINo AS [Party FSSAI No],TaxType.TaxTypeName AS [Party TaxType],PriceType.PriceType as [Price Type],          
--TaxType.TaxTypeName AS [Customer TaxType],--CreditTerm.CreditName as [Customer CreditTerm],--paymode.PaymentMode AS [Customer Paymentmode],          
QT.RefNo as [Doc Ref],Qt.Narration as [Narration],'''' as [Valid till Date],          
Tax.TaxTypeName as [TaxType Name],SUM(Detail.Qty) As [Total Qty],SUM(Detail.Qty / Prod.SalesCR) As [Deft_S_UOM_Total_Qty],     
QT.TradeDiscPern AS [Trade Discount Percentage],          
QT.AddnlDiscPern AS [Addnl Discount Percentage],QT.OtherChargePern AS [OtherCharge Percentage],QT.FrightAmt as [Frieght Amount],          
QT.OtherChargeAmt AS [OtherCharge Amount],QT.TradeDiscAmt AS [T.Trade Discount Amount],QT.AddnlDiscAmt AS [T.Addnl Discount Amount],          
QT.TotalProdDiscAmt AS [T.Product Discount Amount],    
CONVERT(decimal(25,6),0) AS [T. User Discount Amount],    
QT.TotalDiscAmt AS [T.Discount Amount],    
(ISNULL(QT.GrossAmt,0) + ISNULL(QT.TotalDiscAmt,0)) AS [Goods Amount],    
QT.GrossAmt as [T.Gross Amount],          
QT.TaxAmt as [T.Total Tax Amount],QT.RoundOffAmt as [Round Off Amount],QT.NetAmt as [Rounded Net Amount],    
QT.NetAmt as [Received Amount],QT.NetAmt as [Aft Adj NetAmt], CONVERT(decimal(25,6),0) as [Balance Amount],    
dbo.fnConvertAmountinWords(QT.NetAmt) AS [Amt_in_Words],UserTab.username as [User Name],          
'''' AS [Tax Value],'''' AS [Tax Percentage],'''' AS [Tax Amount] ,'''' AS [Doc Prefix],'''' [T_Customer Name],'''' [T_Bill_Address1]            
,'''' [T_Bill_Address2],'''' [T_Bill_Address3],'''' [T_Cont Person],'''' [T_Beat_Name],        
'''' [T_SalesmanName],    
convert(nvarchar(255),MAX(Detail.Serial)) + '' / '' + convert(nvarchar(255),dbo.fnGetRoundedValue(SUM(Detail.Qty))) as [Tot Count Qty]      
FROM dbo.tblQuotationHeader AS QT          
Join dbo.tblQuotationDetail as Detail on QT.ID = Detail.QuationID          
join dbo.tblDocumentSeries AS Doc ON QT. DocPrefix = Doc.TransID          
Join  dbo.tblMasterCustomer AS Customer ON QT.CustomerID = Customer.ID          
Join dbo.tblMasterTaxType as Tax on QT.TaxTypeId = Tax.TaxTypeID          
LEFT JOIN tblMasterProduct AS Prod ON Prod.ID = Detail.ProdID    
Left JOIN tblMasterUserDefineNoHeader AS UDN ON UDN.UDNId=QT.UDFId          
--LEFT JOIN tblCustBeatAndSalesman CBS ON CBS.CustomerId = QT.CustomerID        
Left Join dbo.tblPriceType as PriceType on PriceType.Id = Customer.PriceTypeID                
Left Join dbo.tblMasterTaxType as TaxType on TaxType.TaxTypeID = Customer.taxtypeid          
LEft Join dbo.tblMasterCreditTerm as CreditTerm on CreditTerm.ID = Customer.credittermid          
Left Join dbo.tblPaymentMode as paymode on paymode.Id = Customer.PaymentModeId          
Join dbo.tblUsers as UserTab on UserTab.ID = QT.MBy or UserTab.ID  =  QT.Cby          
WHERE  QT.ID = @DocValue          
Group By QT.ID,QT.DocDate,QT.MDate,QT .CDate,Doc.TransName,QT.DocId,Customer.Name,Customer.Code,Customer.mob1,          
Customer.mob2,Customer.ph1,Customer.ph2,Customer.email,Customer.billadd1,Customer.billadd2,Customer.billadd3,Customer.shipadd1,Customer.shipadd2,          
Customer.shipadd3,Customer.GSTIN,Customer.AadharNo,          
RefNo,Qt.Narration,Tax.TaxTypeName,QT.GrossAmt,QT.TaxAmt,          
QT.RoundOffAmt,QT.NetAmt,UserTab.username,QT.TradeDiscPern,QT.TradeDiscAmt,QT.AddnlDiscPern,QT.AddnlDiscAmt,QT.OtherChargePern,          
QT.OtherChargeAmt,QT.TotalProdDiscAmt,QT.TotalDiscAmt,QT.Remarks,UDN.DocName,QT.UDFDocId,QT.DocValue,          
Customer.ContactPerson,Customer.Pincode,Customer.PANNumber,Customer.FSSAINo,PriceType.PriceType,          
TaxType.TaxTypeName,QT.FrightAmt,QT.CustomerID        
END',
N'[export] nocount';
GO
/****** uspQuotationReportDetails ******/
EXEC #Apply07 N'dbo.uspQuotationReportDetails', 0x09E4086F90AC0175AEE33256CE6EB24B85E6EC52BE2C21898409D699078D2596, NULL, NULL, 0x9B12E377275F4C2D6C38FE2FB441443EAD1B8F8AC3A141361A40F3505C7F5A97, 0x74D2E8753174AAD0FFF51254AD513F75AA55B3B3CA76F05A8BB6742002E611E4, NULL,
N'ALTER PROC [dbo].[uspQuotationReportDetails]  
@QuotationID INT  
AS  
SET NOCOUNT ON;
BEGIN  
SELECT QoHeader.DocId [Doc ID],format(QoHeader.DocDate,''dd-MMM-yyyy'') [Doc Date],Product.Code AS [Product Code],Product.Name AS [Product Name],Product.EAN AS EAN,[dbo].[fnGetRoundedValue](QoDetail.DetailMRP) MRP,        
[dbo].[fnGetRoundedValue](QoDetail.SalesPrice) as [Price],        
[dbo].[fnGetRoundedValue](((QoDetail.SalesPrice * QoDetail.TaxPercentage) / 100) + (QoDetail.SalesPrice)) as [Incl Price],      
[dbo].[fnGetRoundedValue] (Qty) as [Qty],Uom.Name as [UOM],[dbo].[fnGetRoundedValue] (Qty / nullif(ReportingQty,0)) as [Reporting Qty],      
RepUom.Name as [Reporting UOM],ta.TaxName as [Tax Name],[dbo].[fnGetRoundedValue](TaxPercentage)[Tax %],  
[dbo].[fnGetRoundedValue](QoDetail.TaxAmt)[Tax Amount],            
[dbo].[fnGetRoundedValue](QoDetail.GoodsAmt) as [Goods Amount],[dbo].[fnGetRoundedValue](QoDetail.ProdDiscPern) as [Prod Disc %],            
[dbo].[fnGetRoundedValue](QoDetail.TradeDiscAmt) as [Trade Disc Amount],[dbo].[fnGetRoundedValue](QoDetail.AddnlDiscAmt) as [Addnl Disc Amount],            
[dbo].[fnGetRoundedValue](QoDetail.GrossAmt) as [Gross Amount],[dbo].[fnGetRoundedValue](QoDetail.NetAmt) [Net Amount],    
MF.Name [Mfr Name],mb.Name [Brand Name],MC.Name [Category Name],MV.Name [Vendor Name]     
from tblQuotationDetail as QoDetail          
JOIN tblQuotationHeader as QoHeader on QoHeader.ID = QoDetail.QuationID
JOIN tblMasterProduct AS Product ON QoDetail.ProdID=Product.ID            
JOIN tblMasterUom as Uom ON  Uom.ID = QoDetail.UomID         
JOIN tblMasterUom as RepUom ON  RepUom.ID = Product.ReportingUomID      
join tblMasterManufacturer AS MF ON MF.ID = Product.MfrID    
join tblMasterBrand AS MB ON MB.ID = Product.BrandID    
join tblMasterCategory AS MC ON MC.ID = Product.CategoryID    
LEFT join tblMasterVendor AS MV ON MV.ID = Product.VendorID              
LEFT JOIN tblMasterTax as ta ON ta.TaxID = QoDetail.TaxID                  
WHERE QoDetail.QuationID = @QuotationID  
ORDER BY QoDetail.Serial            
END',
N'[export] nocount';
GO
/****** uspQuotationReportHeader ******/
EXEC #Apply07 N'dbo.uspQuotationReportHeader', 0x8AD67E19B2186691820DABC69EF865B2D5FDC07E78B9075372670B7D59F85FA1, NULL, NULL, 0xEC89AED676B169008A30E0359C1070C0EF5047226D31ACAFA00711057FA2AA4E, 0x2E8C16B85718F41AA0FA59360175A7E6AD262EA80336D9024E1D370DC2C4885B, NULL,
N'ALTER proc [dbo].[uspQuotationReportHeader]
@StatusID INT = 0,@FromDate DATE = ''2025-04-01'',@ToDate DATE = ''2025-09-30''
as
SET NOCOUNT ON;
begin
DECLARE @Sts AS TABLE(Status INT)          
IF(@StatusID = 0)          
BEGIN          
INSERT INTO @Sts values (1),(3),(5)          
END          
ELSE          
BEGIN          
INSERT INTO @Sts values(@StatusID)          
END 
SELECT qo.ID QuationID,DocId as [DOC ID],FORMAT(DocDate,''dd-MMM-yyyy'')AS [Doc Date],qo.RefNo AS [Ref No], BO.Name [Branch], 
cust.Code AS [Customer Code],cust.Name AS [Customer Name],cust.Mob1 AS [Mob No],cust.email AS [E-Mail ID],  
cust.GSTIN as [GSTIN],Tax.TaxTypeName as [Tax Type Name],         
[dbo].[fnGetRoundedValue](TradeDiscPern) AS [Trade Disc %],[dbo].[fnGetRoundedValue](SUM(TradeDiscAmt)) AS [Trade Disc Amount],          
     
[dbo].[fnGetRoundedValue] (AddnlDiscPern) AS [Addnl Disc %],[dbo].[fnGetRoundedValue](SUM(AddnlDiscAmt)) AS [Addnl Disc Amount],                 
[dbo].[fnGetRoundedValue] (OtherChargePern) AS [Other Charges %],[dbo].[fnGetRoundedValue](SUM(OtherChargeAmt)) AS [Other Charges Amount]
,[dbo].[fnGetRoundedValue] (FrightAmt) as [Freight Amount],    
[dbo].[fnGetRoundedValue](SUM(TotalProdDiscAmt)) AS [Total Prod Disc Amount],[dbo].[fnGetRoundedValue](SUM(TotalDiscAmt)) AS [Total Disc Amount],      
[dbo].[fnGetRoundedValue](SUM(GrossAmt)) AS [Gross Amount],[dbo].[fnGetRoundedValue](SUM(TaxAmt)) AS [Tax Amount],        
 [dbo].[fnGetRoundedValue](SUM(RoundOffAmt)) AS [Round Off Amount], [dbo].[fnGetRoundedValue](SUM(NetAmt)) AS [Net Amount],  
Narration,Remarks,(CASE ISNULL(USERSS.username,'''') WHEN '''' THEN  USERS.username  ELSE  USERSS.username END)as [User Name] ,                                       
Sa.Description as [Status]                      
from tblQuotationHeader as qo  
JOIN tblMasterCustomer AS cust ON qo.CustomerID=cust.ID  
join tblmasterbranchoffice AS BO ON BO.ID = qo.BranchID
JOIN tblMasterTaxType AS Tax ON Tax.TaxTypeID = qo.TaxTypeID  
JOIN tblUsers AS USERS ON USERS.ID = qo.Cby  
LEFT JOIN tblUsers AS USERSS ON USERSS.ID = qo.Mby  
JOIN tblStatus AS Sa ON Sa.ID =qo.Status  
WHERE qo.DocDate BETWEEN @FromDate AND @ToDate and qo.Status in (select * from @Sts)             
GROUP BY qo.ID,DocId,DocDate,cust.Code,cust.Name,cust.Mob1,cust.email,cust.GSTIN ,Tax.TaxTypeName,qo.RefNo,Narration,USERSS.username,USERS.username,Sa.Description,  
qo.TradeDiscPern,qo.TradeDiscAmt,qo.AddnlDiscPern,qo.AddnlDiscAmt,FrightAmt ,qo.OtherChargePern,qo.OtherChargeAmt,  
qo.TotalProdDiscAmt,qo.TotalDiscAmt,Narration,Remarks,Qo.UDFDocId ,DocValue, BO.Name 
ORDER BY DocValue ASC  
end',
N'[export] nocount';
GO
/****** uspReasonwiseAnalysisDetail ******/
EXEC #Apply07 N'dbo.uspReasonwiseAnalysisDetail', 0x0AF12F812744B6AAB7A222B88344EC5011E9DF7126010762247C249DAA9BEF3B, NULL, NULL, 0xFB386689F135864D7B6D1CCF60FA32D340A00CB2441CCEA2B528618086E10605, 0xEECA1637EB6BD31FABF5CBCED9A5382D1A654A672C1632319511E9AFC167A310, NULL,
N'ALTER proc [dbo].[uspReasonwiseAnalysisDetail]    
 @ReasonID int = 9,@ReasonName nvarchar(255) = ''0'',@FromDate date =''2025-08-01'',@ToDate date = ''2025-08-30''    
 as    
 SET NOCOUNT ON;
begin    
select RSN.Name [Reason Name],SH.DocID [Doc ID],format(SH.InvDate,''dd-MMM-yyyy'') [Doc Date],MP.Code [Product Code],    
MP.Name [Product Name],MF.Name [Mfr Name],MB.Name [Brand Name],MC.Name [Category Name],    
dbo.fnGetRoundedValue(sum(isnull(SD.DiffValue,0))) [Excl Diff Amt],    
dbo.fnGetRoundedValue(sum(isnull(SD.DiffValue,0) + ((isnull(SD.DiffValue,0) * TaxValue) / 100))) [Incl Diff Amt] from tblTranSalesHeader SH    
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID    
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID    
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID    
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID    
JOIN tblMasterCategory MC ON MC.ID = MP.CategoryID    
left JOIN tblMasterReason RSN ON RSN.ID = @ReasonID  
WHERE DocPrefix = 15 AND Status IN (1,3,5) AND Isnull(reasonID,0) = @ReasonID and SH.InvDate between @FromDate AND @ToDate    
group by MP.Code,MP.Name,SH.DocID,SH.InvDate,MF.Name,MB.Name,MC.Name,RSN.Name    
order by SH.DocID    
end',
N'[export] nocount';
GO
/****** uspReasonwiseAnalysisHeader ******/
EXEC #Apply07 N'dbo.uspReasonwiseAnalysisHeader', 0x6FE6C3EEF0683ECC57365493D196B9C710E8E44C4178C748EF7EF5B728CCDC1D, 0x344556B9AA6C0087309FDB2BA4D3ECB63AA5F4D7557054BB0085F6F038E49972, NULL, 0x0305B162D9464F519CE2C4FEE3609F1F0170D5DA1A2899173AB100432CE38751, 0xC20DF0F6D92586642D3575A4E2EC59C80CBA5E7E944CB9613925A9A14AEBDD5C, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspReasonwiseAnalysisHeader]  
@ReasonName nvarchar(255) = ''0'',@FromDate date =''2025-08-01'',@ToDate date = ''2025-12-30''  
as  
SET NOCOUNT ON;
begin  
SET DATEFORMAT dmy;        
declare @StrQuery nvarchar(max) = ''''      
 set @StrQuery = ''   
select SD.ReasonID,RSN.Name,dbo.fnGetRoundedValue(sum(isnull(SD.DiffValue,0))) [Excl Diff Amt],  
dbo.fnGetRoundedValue(sum(isnull(SD.DiffValue,0) + ((isnull(SD.DiffValue,0) * TaxValue) / 100))) [Incl Diff Amt] from tblTranSalesHeader SH  
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID  
left JOIN tblMasterReason RSN ON RSN.ID = SD.ReasonID  
WHERE DocPrefix = 15 AND Status IN (1,3,5) ''  
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (SH.InvDate BETWEEN  @FromDate  AND  @ToDate )'' END)                   
   
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ReasonName,''0'')=''0'' THEN '''' ELSE '' AND SD.ReasonID =  @ReasonName '' END)     
SET @StrQuery = @StrQuery + '' group by SD.ReasonID,RSN.Name ORDER BY RSN.Name''  
EXEC sys.sp_executesql @StrQuery, N''@ReasonName nvarchar(255), @FromDate date, @ToDate date'', @ReasonName, @FromDate, @ToDate  
end',
N'[06] nocount';
GO
/****** uspRepAccountLedger ******/
EXEC #Apply07 N'dbo.uspRepAccountLedger', 0x5252C146DF15D2DA36E9FE529C0E12152E0CF2C2D336EB3B0D41006C8CBE4F42, 0x29E7AD6379C41D1AC766D075254999727FF1EEF76A535BDF502E05E8C342C859, NULL, 0xB430A28D6FD1F44975E64DC791A0D37CB86B350884006A4A4D7CE10634809A44, 0xADCD656DBC5BA0AB370233463B533C24156FBB1AF089A852C783A38E6133C383, NULL,
N'--uspRepAccountLedger ''1,2'',''2025-02-01'',''2025-12-01''            
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspRepAccountLedger]          
@AccountName nvarchar(max) = null ,@FromDate date = null,@ToDate DATE = NULL,@Showall nvarchar(max) = null      
as              
SET NOCOUNT ON;
begin              
DECLARE @strQuery NVARCHAR(MAX) = ''''           
CREATE TABLE #temp([Transaction] nvarchar(255),[Doc ID] nvarchar(255),[Date] nvarchar(255),[Account Name] nvarchar(255),    
[Credit] decimal(25,2),[Debit] decimal(25,2),[Remarks] nvarchar(255),[Narration] nvarchar(255),[Status] nvarchar(255))    
SET @strQuery = ''  select DS.TransName [Transaction],DocID [Doc ID],CONVERT(nvarchar,FAJ.DocDate,103) Date,FAA.AccountName [Account Name],    
dbo.fnGetRoundedValue(Credit) Credit,dbo.fnGetRoundedValue(Debit) Debit,Remarks,Narration,STS.Description Status from tblFAJournal FAJ          
JOIN tblFAAccount FAA ON FAA.FAID = FAJ.AccountID          
  JOIN tblDocumentSeries DS ON DS.TransID = FAJ.DocPrefix          
  JOIN tblStatus STS ON STS.ID = FAJ.Status          
 WHERE FAA.Active IN (0,1)  ''            
 SET @strQuery += CASE WHEN ISNULL(@Showall,'''') = ''true'' THEN '''' ELSE '' and FAJ.Status NOT IN (2,4) '' END       
SET @strQuery += CASE WHEN ISNULL(@FromDate,'''') = '''' OR ISNULL(@ToDate,'''') = '''' THEN '''' ELSE '' AND FAJ.DocDate BETWEEN ''+'' @FromDate  AND ''+'' @ToDate '' END            
SET @strQuery += CASE WHEN ISNULL(@AccountName,'''') = '''' THEN '''' ELSE '' AND FAA.FAID IN (SELECT * from  dbo.fnSplitString( ''+'' @AccountName ,'''',''''))'' END         
insert into #temp    
EXEC sys.sp_executesql @strQuery, N''@AccountName nvarchar(max), @FromDate date, @ToDate DATE, @Showall nvarchar(max)'', @AccountName, @FromDate, @ToDate, @Showall           
if((select count(*) from #temp) > 0)    
BEGIN    
SELECT * INTO  #DATA FROM(  
select [Transaction],[Doc ID],[Date],[Account Name],[Credit],[Debit],[Remarks],[Narration],[Status] from #temp    
union    
select ''Total'' [Transaction],''''[Doc ID],'''' [Date],''''[Account Name],dbo.fnGetRoundedValue(sum([Credit])) [Credit],    
dbo.fnGetRoundedValue(sum([Debit])) [Debit],'''' [Remarks],'''' [Narration],'''' [Status] from #temp  ) AS REC  
SELECT * FROM #DATA  
DROP TABLE #DATA  
END    
drop table #temp    
end',
N'[06] nocount';
GO
/****** uspRepAssignInvoicesDetail ******/
EXEC #Apply07 N'dbo.uspRepAssignInvoicesDetail', 0xAD64694A5DBF056D94A5A7CECB1CE7BB9351D80D49D5AC5325ADAB40FD701BA2, NULL, NULL, 0xE2C7F3DD6DC8274D8BF434186A607E93479E0CD34B2817879018E328FF27C972, 0x07F4B70C5D24048F240181E3EC61A917EE086FE1988C76A2EA1CD526F94D9B1F, NULL,
N'--uspRepAssignInvoicesDetail ''18''
ALTER PROCEDURE [dbo].[uspRepAssignInvoicesDetail]

@ID INT

AS
SET NOCOUNT ON;
BEGIN

SELECT TSH.DocID, FORMAT(TSH.InvDate,''dd/MMM/yyyy'')[Invoice Date], MC.Name[Customer Name], TSH.NetAmt[Net Amount], TSH.Balance[Balance], S.Description[Status]

FROM tblAssignInvoicesHeader AIH                                   
JOIN tblAssignInvoicesDETAIL AIHD ON AIHD.HID = AIH.ID 
LEFT JOIN tblTranSalesHeader TSH on TSH.ID = AIHD.InvID
