/****** uspRepAssignInvoicesHeader ******/
EXEC #Apply07 N'dbo.uspRepAssignInvoicesHeader', 0xC4E934EE527FF92D68154AC1A56B0D9ED7F5D2A5BD518ACBE172570A06465F27, NULL, NULL, 0xA2B19B7C01E9C692977D1E7B60D41AD0056B3C0A16B14ECD15AF20F615932F78, 0x2E90FE084FF7531DBF40128A5504251DBD43085740DE36FA6DA2F582171F785A, NULL,
N'--uspRepAssignInvoicesHeader ''4'','''','''',''2025-08-01'',''2026-08-01''      
ALTER PROCEDURE [dbo].[uspRepAssignInvoicesHeader]      
    
@BranchName INT,    
@SalesmanName NVARCHAR(255) = '''',    
@CustomerName NVARCHAR(255) = '''',    
@FromDate DATE = ''2024-08-01'',    
@ToDate DATE = ''2026-08-30''    
      
AS       
SET NOCOUNT ON;
BEGIN      
      
SELECT AIH.ID, AIH.DocID[Doc ID], FORMAT(AIH.DocDate,''dd/MMM/yyyy'') [Doc Date], AIH.RefNo[Ref No], MS.Name[Salesman Name],      
MBO.Name[Branch Name], COUNT(AIHD.InvID) AS InvoiceCount,      
CAST(COUNT(CASE WHEN AIHD.Status = 1 THEN 1 END) AS NVARCHAR(10))+ '' - '' +      
CAST(COUNT(CASE WHEN AIHD.Status = 5 THEN 1 END) AS NVARCHAR(10))+ '' - '' +      
CAST(COUNT(CASE WHEN AIHD.Status = 6 THEN 1 END) AS NVARCHAR(10))AS OCR,      
CU.UserName AS [Created By],  CONVERT(NVARCHAR,AIH.CDate) AS [Created Date],      
MU.UserName AS [Modified By],  CONVERT(NVARCHAR,AIH.MDate) AS [Modify Date],      
S.Description[Status],AIH.Remarks[Remarks], AIH.Narration[Narration]      
      
      
FROM tblAssignInvoicesHeader AIH                                         
JOIN tblAssignInvoicesDETAIL AIHD ON AIHD.HID = AIH.ID        
LEFT JOIN tblTranSalesHeader TSH on TSH.ID = AIHD.InvID      
LEFT JOIN tblMasterCustomer MC on MC.ID = TSH.CustID      
LEFT JOIN tblMasterSalesman MS on MS.ID = AIH.SalesmanID      
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = AIH.BranchID      
JOIN tblUsers CU  ON CU.ID = AIH.CBy              
LEFT JOIN tblUsers MU  ON MU.ID = AIH.MBy        
LEFT JOIN tblStatus S on S.ID = AIH.Status      
WHERE (AIH.DocDate BETWEEN @FromDate AND @ToDate)AND AIH.Status IN(1,3,5)       
AND (@CustomerName = '''' OR MC.ID IN (SELECT * from dbo.fnSplitString( @CustomerName,'','')))      
AND (@BranchName = 0 OR MBO.ID = @BranchName)      
AND (@SalesmanName = '''' OR MS.ID IN (SELECT * from dbo.fnSplitString(@SalesmanName,'','')))         
      
      
GROUP BY       
AIH.ID, AIH.DocID, AIH.DocDate, AIH.RefNo, MS.Name, MBO.Name,CU.UserName,AIH.CDate,MU.UserName,AIH.MDate,S.Description      
,AIH.Remarks, AIH.Narration      
      
END',
N'[export] nocount';
GO
/****** uspRepBankAccountreport ******/
EXEC #Apply07 N'dbo.uspRepBankAccountreport', 0x105E490E1600375B592F6D09E1C7F342D54D5F7891ED8AE878958418C73D5673, NULL, NULL, 0x002117D8A49354068F063DF827C2FDDC10F194D148DE76E4C36108D3189E6EE1, 0x8E77B4CBB68D3F589D1F29E5826BB6AD32C465355DE4ABE096D239F4C213F5D6, NULL,
N'ALTER PROCEDURE [dbo].[uspRepBankAccountreport]
AS
SET NOCOUNT ON;
BEGIN
SELECT
BA.AccountNO AS [Account No],
BA.AccountName AS [Account Name],
B.Name AS [Bank Name],
BA.BranchName AS [Branch Name],
BA.IFSCCode AS [IFSC Code],
BA.MICR AS [MICR],
CASE WHEN BA.Active = 1 Then  ''Yes'' ELSE ''No'' END AS [Active],
CASE WHEN BA.SetDefault = 1 THEN ''yes'' ELSE ''No'' END AS [Set Default],
CU.UserName AS [Created By],
CONVERT(NVARCHAR, BA.CDate) AS [Create Date],
MU.UserName AS [Modified By],
CONVERT(NVARCHAR, BA.MDate) AS [Modify Date]
FROM tblMasterBankAccount BA
LEFT JOIN tblMasterBank B
ON B.ID = BA.BankID
LEFT JOIN tblUsers CU
ON CU.ID = BA.CBy
LEFT JOIN tblUsers MU
ON MU.ID = BA.MBy
Order by BA.AccountName
END',
N'[export] nocount';
