/****** uspRepBeatSalesmanWiseAgeingHeader ******/
EXEC #Apply07 N'dbo.uspRepBeatSalesmanWiseAgeingHeader', 0xB1067E53EC65A5699B7F8E29C969AD6E44F8504DFEBAF85B6D0551C5EC53D5EB, NULL, NULL, 0x77E61E38647F8B693C789A5B657F8272196EBEE43AF8E4B7EFA8C31D92AB23C1, 0x16572D7FC37D768AA1F8A23EDE78DB1BBAAE62720F9372DD6625A57FCDBBFCE0, NULL,
N'--uspRepBeatSalesmanWiseAgeingHeader '''','''','''',''15'',''12/02/2026''    
ALTER PROCEDURE [dbo].[uspRepBeatSalesmanWiseAgeingHeader]    
@BeatName NVARCHAR(255)='''',    
@SalesmanName NVARCHAR(255)='''',    
@CustomerName NVARCHAR(255)='''',    
@fnSplitString NVARCHAR(MAX),    
@AsOnDate DATE    
AS    
SET NOCOUNT ON;
BEGIN    
    
DECLARE @Serial INT,@Count INT, @Query NVARCHAR(MAX),@Count1 INT,@MainSerial INT, @MainCount INT,@AlterColumnName0 NVARCHAR(255),@AlterColumnName1 NVARCHAR(255)    
DECLARE @Ageing INT,@nCount INT,@nCount1 INT,@nSerial INT,@IsTrueFalse NVARCHAR(10),@nF INT,@nT INT,@nColumnName NVARCHAR(255)    
    
SELECT CD.DocID,ISNULL(SUM(TotalAmtAdj),0) TotalAmtAdj INTO #COLTEMP    
FROM tblTranCollectionHeader CH    
JOIN tblTranCollectionDetail CD ON CD.ColID = CH.ColID    
WHERE ColDate > @AsOnDate AND Status IN (1,3,5)    
GROUP BY CD.DocID    
    
--select * from #COLTEMP    
    
SELECT FAC.NoteID,FAC.Adjustment INTO #JVTEMP    
FROM tblFAJournal FA    
JOIN tblFAJournelCancel FAC ON FAC.JVID = FA.JVID    
WHERE DocPrefix = 8 AND DocDate > @AsOnDate AND FA.Status IN (1,3,5)    
GROUP BY FAC.NoteID,FAC.Adjustment    
    
--select * from #JVTEMP    
    
-- Create #TempTable1 for Moving Original Data    
CREATE TABLE #TempTable (ID INT,[Doc ID] NVARCHAR(255),[Doc Date] NVARCHAR(25),    
[Customer Name] NVARCHAR(255),[Customer Type] NVARCHAR(255),[Beat Name] NVARCHAR(255),[SalesMan Name] NVARCHAR(255)    
,[Opening Amount] DECIMAL(25,6),[Pending Amount] DECIMAL(25,6),[SR Balance] DECIMAL(25,6),[Ageing] INT)    
    
CREATE TABLE #TempTable1 (ID INT IDENTITY(1,1),[Doc ID] NVARCHAR(255),[Doc Date] NVARCHAR(25),    
[Customer Name] NVARCHAR(255),[Customer Type] NVARCHAR(255),[Beat Name] NVARCHAR(255),[SalesMan Name] NVARCHAR(255)    
,[Opening Amount] NVARCHAR(255),[Pending Amount] NVARCHAR(255),[SR Balance] NVARCHAR(255),[Ageing] INT)    
    
SELECT SRI.[ID],SRI.[Doc ID],SRI.[Doc Date],SRI.[Customer Name],SRI.[Customer Type],SRI.[Beat Name],    
SRI.[Salesman Name],SRI.[Opening Amount],SRI.[Pending Amount],SRI.[SR Balance],SRI.Ageing,SRI.[Beat ID],SRI.[Salesman ID],SRI.[Customer ID]    
INTO #TEMPDATA    
FROM    
(    
SELECT    
SH.ID[ID],SH.DocID[Doc ID],FORMAT(SH.InvDate,''dd/MMM/yyyy'')[Doc Date],ISNULL(MC.ID,0)[Customer ID],MC.Name[Customer Name],MCT.Name[Customer Type],    
ISNULL(MB.ID,0)[Beat ID],MB.Name[Beat Name],ISNULL(MS.ID,0)[Salesman ID],MS.Name[Salesman Name],SH.NetAmt[Opening Amount],    
CASE WHEN SH.DocPrefix = 15 THEN SH.Balance ELSE 0 END AS [Pending Amount],    
CASE WHEN SH.DocPrefix = 16 THEN SH.Balance ELSE 0 END AS [SR Balance],    
DATEDIFF(DAY,InvDate,@AsOnDate) AS [Ageing]    
FROM tblTranSalesHeader SH    
JOIN tblMasterCustomer MC on MC.ID = SH.CustID    
LEFT JOIN tblMasterCustomerType MCT on MCT.ID = MC.CustomerType    
LEFT JOIN tblMasterBeat MB on MB.ID = SH.BeatID    
LEFT JOIN tblMasterSalesman MS on MS.ID = SH.SalesManID    
WHERE SH.DocPrefix in (15,16) AND SH.InvDate <= @AsOnDate AND SH.Status IN (1,3,5,6,7)    
UNION ALL    
SELECT  RV.ID[ID],RV.DocID[Doc ID],FORMAT(RV.DocDate,''dd/MMM/yyyy'')[Doc Date],ISNULL(MC.ID,0)[Customer ID],MC.Name[Customer Name],MCT.Name[Customer Type],    
ISNULL(MB.ID,0)[Beat ID],MB.Name[Beat Name],ISNULL(MS.ID,0)[Salesman ID],MS.Name[Salesman Name],RV.NetAmount[Opening Amount],RV.Balance[Pending Amount],    
0 AS [SR Balance],    
DATEDIFF(DAY, RV.DocDate, @AsOnDate) AS [Ageing]    
FROM tblTranPRVoucher RV    
JOIN tblMasterCustomer MC on MC.FAID = RV.PartyID    
LEFT JOIN tblMasterCustomerType MCT on MCT.ID = MC.CustomerType    
LEFT JOIN tblBeatSalesmanMapping AS CBS ON CBS.CustomerId = MC.ID    
LEFT JOIN tblMasterBeat MB on MB.ID = CBS.BeatID    
LEFT JOIN tblMasterSalesman MS on MS.ID = CBS.SalesmanID    
WHERE RV.TransID IN(7)  AND RV.DocDate <= @AsOnDate  AND RV.Status IN (1,3,5)    
UNION ALL    
SELECT  RV.ID[ID],RV.DocID[Doc ID],FORMAT(RV.DocDate,''dd/MMM/yyyy'')[Doc Date],ISNULL(MC.ID,0)[Customer ID],MC.Name[Customer Name],MCT.Name[Customer Type],    
ISNULL(MB.ID,0)[Beat ID],MB.Name[Beat Name],ISNULL(MS.ID,0)[Salesman ID],MS.Name[Salesman Name],RV.NoteValue [Opening Amount],0 [Pending Amount],    
RV.Balance AS [SR Balance],    
DATEDIFF(DAY, RV.DocDate, @AsOnDate) AS [Ageing]    
FROM tblNoteDetails RV    
JOIN tblMasterCustomer MC on MC.FAID = RV.PartyID    
LEFT JOIN tblMasterCustomerType MCT on MCT.ID = MC.CustomerType    
LEFT JOIN tblBeatSalesmanMapping AS CBS ON CBS.CustomerId = MC.ID    
LEFT JOIN tblMasterBeat MB on MB.ID = CBS.BeatID  
LEFT JOIN tblMasterSalesman MS on MS.ID = CBS.SalesmanID    
WHERE RV.TransID IN (4)  AND RV.DocDate <= @AsOnDate  AND RV.Status IN (1,3,5)    
UNION ALL    
SELECT  RV.ColID [ID],RV.DocID[Doc ID],FORMAT(RV.ColDate,''dd/MMM/yyyy'')[Doc Date],ISNULL(MC.ID,0)[Customer ID],MC.Name[Customer Name],MCT.Name[Customer Type],    
ISNULL(MB.ID,0)[Beat ID],MB.Name[Beat Name],ISNULL(MS.ID,0)[Salesman ID],MS.Name[Salesman Name],  
RV.ColAmt [Opening Amount],0 [Pending Amount],    
RV.Balance AS [SR Balance],    
DATEDIFF(DAY, RV.ColDate, @AsOnDate) AS [Ageing]    
FROM tblTranCollectionHeader RV    
JOIN tblMasterCustomer MC on MC.FAID = RV.AccID    
LEFT JOIN tblMasterCustomerType MCT on MCT.ID = MC.CustomerType     
LEFT JOIN tblMasterBeat MB on MB.ID = RV.BeatID  
LEFT JOIN tblMasterSalesman MS on MS.ID = RV.SalesmanID    
WHERE RV.DocPrefix IN (19)  AND RV.ColDate <= @AsOnDate  AND RV.Status IN (1,3,5)  
)SRI    
-- Create #TempID for Split String Ageing Wise    
CREATE TABLE #TempID (IdentID INT IDENTITY(1,1),ID INT)    
    
-- Create #TempAlterColumns for Identifying Column and Checking Range Between    
CREATE TABLE #TempAlterColumns (IdentID INT IDENTITY(1,1),[From] INT,[To] INT,OriginalColumn NVARCHAR(MAX))    
    
-- Insert Spliting String Datas    
INSERT INTO #TempID    
SELECT * FROM (SELECT DISTINCT id FROM dbo.fnSplitString(@fnSplitString,'','') WHERE ISNULL(id,'''')!='''') AS SRI ORDER BY CAST(SRI.id AS INT)    
    
--select * from #TEMPDATA    
INSERT INTO #TempTable    
SELECT ID,[Doc ID],[Doc Date],[Customer Name],[Customer Type],    
[Beat Name],[SalesMan Name],SUM([Opening Amount]) [Opening Amount],SUM([Pending Amount]) [Pending Amount],    
SUM([SR Balance]) [SR Balance],Ageing    
FROM #TEMPDATA    
WHERE (Ageing = 0 OR Ageing != 0)    
AND(@BeatName = '''' OR [Beat ID] IN(SELECT * from dbo.fnSplitString(@BeatName,'','')))
AND(@SalesmanName = '''' OR [Salesman ID] IN (SELECT * from dbo.fnSplitString(@SalesmanName,'','')))
AND(@CustomerName = '''' OR [Customer ID] IN (SELECT * from dbo.fnSplitString (@CustomerName,'','')))
GROUP BY ID,[Doc ID],[Doc Date],[Customer Name],[Customer Type],    
[Beat Name],[SalesMan Name],Ageing    
ORDER BY [Customer Name]    
    
--select * from #TempTable    
    
INSERT INTO #TempTable1    
SELECT [Doc ID],[Doc Date],[Customer Name],[Customer Type],[Beat Name],[SalesMan Name],    
DBO.fnGetRoundedValue([Opening Amount]) [Opening Amount],DBO.fnGetRoundedValue([Pending Amount]) [Pending Amount],    
DBO.fnGetRoundedValue([SR Balance]) [SR Balance],Ageing FROM (    
SELECT TT.[ID],TT.[Doc ID],TT.[Doc Date],TT.[Customer Name],TT.[Customer Type],[Beat Name],[SalesMan Name],    
SUM((TT.[Opening Amount])) [Opening Amount],SUM(((TT.[Pending Amount] + ISNULL(CT.TotalAmtAdj,0)+ ISNULL(Adjustment,0)))) AS [Pending Amount],    
SUM(TT.[SR Balance]) AS [SR Balance],Ageing    
FROM #TempTable TT    
LEFT JOIN #COLTEMP CT ON CT.DocID = TT.ID    
LEFT JOIN #JVTEMP JV ON JV.NoteID = TT.ID    
--WHERE (TT.[Pending Amount] + ISNULL(CT.TotalAmtAdj,0)+ ISNULL(Adjustment,0)) <> 0    
GROUP BY ID,[Doc ID],[Doc Date],[Customer Name],[Customer Type],[Beat Name],[SalesMan Name],Ageing    
) AS NK    
WHERE ((cast(([Pending Amount]) as numeric(26,2))) <> 0 or (cast(([SR Balance]) as numeric(26,2))) <> 0 )    
order by [Customer Name]    
    
SET @Count1 = (SELECT COUNT(*) FROM #TempID);    
SET @Count = (SELECT COUNT(*) FROM #TempID);    
SET @Serial = 1    
-- Looping for Alter and Spliting Columns using Ageing Wise    
IF ISNULL(@Count1,0)>1    
BEGIN    
print ''aaaaaaaaaaaaaaaaaa''    
WHILE (@Count > 0)    
BEGIN    
SET @AlterColumnName0 = (SELECT ID FROM #TempID WHERE IdentID = @Serial-1)    
SET @AlterColumnName1 = (SELECT ID FROM #TempID WHERE IdentID = @Serial)    
SET @AlterColumnName0 = @AlterColumnName0+1    
IF ISNULL(@Count,0)=1    
BEGIN    
SET @Query = ''ALTER TABLE #TempTable1 ADD [''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days] VARCHAR(100) NULL,[>''+@AlterColumnName1+'' Days] VARCHAR(100) NULL''    
EXEC(@Query)    
INSERT INTO #TempAlterColumns VALUES ((@AlterColumnName0),@AlterColumnName1,''[''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days]'')    
INSERT INTO #TempAlterColumns VALUES ((@AlterColumnName1),0,''[>''+@AlterColumnName1+'' Days]'')    
END    
ELSE IF ISNULL(@Count,0)= @Count1    
BEGIN    
SET @Query = ''ALTER TABLE #TempTable1 ADD [0-''+@AlterColumnName1+'' Days] VARCHAR(100) NULL''    
EXEC(@Query)    
INSERT INTO #TempAlterColumns VALUES (0,@AlterColumnName1,''[0-''+@AlterColumnName1+'' Days]'')    
END    
ELSE    
BEGIN    
SET @Query = ''ALTER TABLE #TempTable1 ADD [''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days] VARCHAR(100) NULL''    
EXEC(@Query)    
INSERT INTO #TempAlterColumns VALUES ((@AlterColumnName0),@AlterColumnName1,''[''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days]'')    
END    
SET @Count = @Count - 1;    
SET @Serial = @Serial + 1;    
END    
END    
ELSE    
BEGIN    
SET @AlterColumnName0 = (SELECT ID FROM #TempID WHERE IdentID = 1)    
SET @Query = ''ALTER TABLE #TempTable1 ADD [0-''+@AlterColumnName0+'' Days] VARCHAR(100) NULL,[>''+@AlterColumnName0+'' Days] VARCHAR(100) NULL''    
EXEC(@Query)    
INSERT INTO #TempAlterColumns VALUES (0,@AlterColumnName0,''[0-''+@AlterColumnName0+'' Days]'')    
INSERT INTO #TempAlterColumns VALUES (@AlterColumnName0,0,''[>''+@AlterColumnName0+'' Days]'')    
END    
SET @MainCount = (SELECT COUNT(*) FROM #TempTable1);    
SET @MainSerial = 1    
-- Looping for Get Ageing Information from #TempTable1    
WHILE (@MainCount > 0)    
BEGIN    
SET @Ageing = (SELECT Ageing FROM #TempTable1 WHERE ID = @MainSerial)    
SET @nCount = (SELECT COUNT(*) FROM #TempAlterColumns)    
SET @nCount1 = (SELECT COUNT(*) FROM #TempAlterColumns)    
SET @nSerial = 1  -- Looping for Check Ageing and From and To Between Ageing Range    
WHILE (@nCount > 0)    
BEGIN    
SET @nF = (SELECT [From] FROM #TempAlterColumns WHERE IdentID = @nSerial)    
SET @nT = (SELECT [to] FROM #TempAlterColumns WHERE IdentID = @nSerial)    
SET @nColumnName = (SELECT OriginalColumn FROM #TempAlterColumns WHERE IdentID = @nSerial)    
IF ISNULL(@nCount1,0) = ISNULL(@nSerial,0)    
BEGIN    
SELECT @IsTrueFalse = (CASE WHEN @Ageing > @nF THEN ''TRUE'' ELSE ''FALSE'' END)    
END    
ELSE    
BEGIN    
SELECT @IsTrueFalse = (CASE WHEN @Ageing BETWEEN @nF AND @nT THEN ''TRUE'' ELSE ''FALSE'' END)    
END    
    
-- IF TRUE Updating Pending Amount to Specific Columns    
IF ISNULL(@IsTrueFalse,'''')=''TRUE''    
BEGIN    
SET @Query = ''UPDATE #TempTable1 SET ''+@nColumnName+'' = (case when isnull(CAST([SR Balance] AS DECIMAL(25,2)),0) > 0 then [SR Balance] ELSE [Pending Amount] END) WHERE ID=''+CAST(@MainSerial AS NVARCHAR)+''''    
EXEC (@Query)    
BREAK;    
END    
    
SET @nCount = @nCount - 1;    
SET @nSerial = @nSerial + 1;    
END    
SET @MainCount = @MainCount - 1;    
SET @MainSerial = @MainSerial + 1;    
END    
-- Select all data from #TempTable1 Finally    
alter table #TempTable1 drop column ID    
SELECT * FROM #TempTable1    
ENd    
-- Drop all #Temp Tables    
DROP TABLE #TempTable1,#TempTable,#TempID,#COLTEMP,#JVTEMP ,#TempAlterColumns,#TEMPDATA',
N'[export] nocount';
GO
/****** uspRepBeatSalesmanWiseInvoiceDetail ******/
EXEC #Apply07 N'dbo.uspRepBeatSalesmanWiseInvoiceDetail', 0x929F901BDB7E9222E91109344A63B9C8B149BCA278AAC02B56E714A7CB7F4DCE, NULL, NULL, 0xE4D6EC0746233629DB2F9F9C207866EB4661C984ECA0E06D7D6FC9442E8DE621, 0x9FC26FF6F7F927F1BC7EA0A506E39BA4D0745E72E65B50C3D3F480A41BACB80D, NULL,
N'ALTER PROCEDURE [dbo].[uspRepBeatSalesmanWiseInvoiceDetail]
@BeatName INT,
@SalesmanName INT,
@DocRange NVARCHAR(MAX) = '''',
@FromDate DATE,
@ToDate DATE
AS 
SET NOCOUNT ON;
BEGIN
SELECT
SHD.DocID[Doc ID],FORMAT(SHD.InvDate,''dd/MMM/yyyy'')[Doc Date],SHD.DocRef[Ref No],MC.Name[Customer Name],
dbo.fnGetRoundedValue(SHD.TotalProdDiscAmt)[Total Product Discount Amount],dbo.fnGetRoundedValue(SHD.TotalDiscountAmt)[Total Discount Amount],
dbo.fnGetRoundedValue(SHD.NetAmt)[Net Amount],dbo.fnGetRoundedValue(SHD.Balance)[Balance]
FROM tblTranSalesHeader SHD
left join tblMasterCustomer MC on MC.ID = SHD.CustID
WHERE
        SHD.DocPrefix = 15
        AND SHD.Status IN (1,3,5)
        AND SHD.InvDate BETWEEN @FromDate AND @ToDate
        AND SHD.BeatID = @BeatName
        AND SHD.SalesManID = @SalesmanName
    AND (
        @DocRange = '''' 
        OR SHD.DocValue IN (SELECT DocValue FROM dbo.SplitDocRange(@DocRange))
    )
END',
N'[export] nocount';
GO
/****** uspRepBeatSalesmanWiseInvoiceHeader ******/
EXEC #Apply07 N'dbo.uspRepBeatSalesmanWiseInvoiceHeader', 0xE91C9C7FD5CB53139F453B39502853A41FC281E224AC3C4CD56702BCE0383786, NULL, NULL, 0x8AF6C313FDE6F66B3ECF7F6C7885CB1003295617E1DC7545FB47754EC3F5B3F9, 0xE08A33F2B1931992CED267BFFA841ACB9A5BB8221F071B4610A9E150D8E7BF66, NULL,
N'ALTER procedure [dbo].[uspRepBeatSalesmanWiseInvoiceHeader]  
@BeatName NVARCHAR(255) = '''',  
@SalesmanName NVARCHAR(255) = '''',  
@DocRange NVARCHAR(MAX) = '''',  
@FromDate DATE = ''2024-08-01'',  
@ToDate DATE = ''2026-08-30''     
AS  
SET NOCOUNT ON;
BEGIN  
  
SELECT  
SH.BeatID[Beat ID],SH.SalesManID [Salesman ID],  
@DocRange AS [Doc Range],  
@FromDate AS [FromDate],@ToDate AS [ToDate]  
,MS.Name[Salesman Name],MB.Name[Beat Name],dbo.fnGetRoundedValue(SUM(SH.NetAmt))[Net Amount],dbo.fnGetRoundedValue(SUM(SH.Balance))[Balance]  
FROM tblTranSalesHeader SH  
LEFT JOIN tblMasterSalesman MS on MS.ID = SH.SalesManID  
LEFT JOIN tblMasterBeat MB on MB.ID = SH.BeatID  
 WHERE  
    SH.DocPrefix = 15   
    AND SH.Status IN (1,3,5)  
    AND SH.InvDate BETWEEN @FromDate AND @ToDate  
    AND (  
        @DocRange = ''''   
        OR SH.DocValue IN (SELECT DocValue FROM dbo.SplitDocRange(@DocRange))  
    )  
    AND (@BeatName = '''' OR MB.ID IN(SELECT * from dbo.fnSplitString(@BeatName,'','')))  
    AND (@SalesmanName = '''' OR MS.ID IN(SELECT * from dbo.fnSplitString(@SalesmanName,'','')))  
    GROUP BY  
    SH.BeatID,  
    SH.SalesManID,  
    MS.Name,  
    MB.Name  
END',
N'[export] nocount';
GO
/****** uspRepBeatwiseOutstandingsHeader ******/
EXEC #Apply07 N'dbo.uspRepBeatwiseOutstandingsHeader', 0x1DA57BFAD927C78CF36AF47B1CB8346FF70FD50B7E9A6D530BC0FDE13A5CBDBA, NULL, NULL, 0x70EDB0E3C941E3287574CEDA1270245E605B7096D5DD37A8E609C4DE8CE7BFA7, 0xE5617B409BC62216CCC242389D4DAC16636D275D588E3C61A7C855F76D57EBB3, NULL,
N'--uspRepBeatwiseOutstandingsHeader '''','''',''0,10,20'',''12/02/2026''          
ALTER PROCEDURE [dbo].[uspRepBeatwiseOutstandingsHeader]          
@BeatName NVARCHAR(255)='''',          
@SalesmanName NVARCHAR(255)='''',           
@fnSplitString NVARCHAR(MAX),          
@AsOnDate DATE          
AS        
SET NOCOUNT ON;
BEGIN          
          
DECLARE @Serial INT,@Count INT, @Query NVARCHAR(MAX),@Count1 INT,@MainSerial INT, @MainCount INT,@AlterColumnName0 NVARCHAR(255),@AlterColumnName1 NVARCHAR(255)          
DECLARE @Ageing INT,@nCount INT,@nCount1 INT,@nSerial INT,@IsTrueFalse NVARCHAR(10),@nF INT,@nT INT,@nColumnName NVARCHAR(255)          
          
SELECT CD.DocID,ISNULL(SUM(TotalAmtAdj),0) TotalAmtAdj INTO #COLTEMP          
FROM tblTranCollectionHeader CH          
JOIN tblTranCollectionDetail CD ON CD.ColID = CH.ColID          
WHERE ColDate > @AsOnDate AND Status IN (1,3,5)          
GROUP BY CD.DocID          
          
--select * from #COLTEMP          
          
SELECT FAC.NoteID,FAC.Adjustment INTO #JVTEMP           
FROM tblFAJournal FA          
JOIN tblFAJournelCancel FAC ON FAC.JVID = FA.JVID          
WHERE DocPrefix = 8 AND DocDate > @AsOnDate AND FA.Status IN (1,3,5)          
GROUP BY FAC.NoteID,FAC.Adjustment          
          
--select * from #JVTEMP          
          
-- Create #TempTable1 for Moving Original Data          
CREATE TABLE #TempTable (DocPrefix int,ID INT,[Beat Name] NVARCHAR(255),[SalesMan Name] NVARCHAR(255)          
,[Opening Amount] DECIMAL(25,6),[Pending Amount] DECIMAL(25,6),[SR Balance] DECIMAL(25,6),[Ageing] INT)          
          
CREATE TABLE #TempTable1 (ID INT IDENTITY(1,1),DocPrefix int,[Beat Name] NVARCHAR(255),[SalesMan Name] NVARCHAR(255)          
,[Opening Amount] NVARCHAR(255),[Pending Amount] NVARCHAR(255),[SR Balance] NVARCHAR(255),[Ageing] INT)          
          
SELECT DocPrefix,SRI.[ID],SRI.[Beat Name],SRI.[Salesman Name],SRI.[Opening Amount],        
SRI.[Pending Amount],SRI.[SR Balance],SRI.Ageing,SRI.[Beat ID],SRI.[Salesman ID]         
INTO #TEMPDATA          
FROM          
(           
SELECT  SH.DocPrefix,          
SH.ID[ID],ISNULL(MB.ID,0)[Beat ID],MB.Name[Beat Name],ISNULL(MS.ID,0)[Salesman ID],MS.Name[Salesman Name],        
SH.NetAmt [Opening Amount],        
CASE WHEN SH.DocPrefix = 15 THEN SH.Balance  ELSE 0 END AS [Pending Amount],          
CASE WHEN SH.DocPrefix = 16 THEN SH.Balance * -1 ELSE 0 END AS [SR Balance],        
DATEDIFF(DAY,InvDate,@AsOnDate) AS [Ageing]          
FROM tblTranSalesHeader SH          
JOIN tblMasterCustomer MC on MC.ID = SH.CustID          
LEFT JOIN tblMasterCustomerType MCT on MCT.ID = MC.CustomerType          
LEFT JOIN tblMasterBeat MB on MB.ID = SH.BeatID          
LEFT JOIN tblMasterSalesman MS on MS.ID = SH.SalesManID          
WHERE SH.DocPrefix in (15,16) AND SH.InvDate <= @AsOnDate AND SH.Status IN  (1,3,5,6,7)          
UNION ALL          
SELECT RV.TransID DocPrefix,           
RV.ID[ID],ISNULL(MB.ID,0)[Beat ID],MB.Name[Beat Name],ISNULL(MS.ID,0)[Salesman ID],MS.Name[Salesman Name],        
RV.NetAmount [Opening Amount],RV.Balance[Pending Amount],0 AS [SR Balance],        
DATEDIFF(DAY, RV.DocDate, @AsOnDate)  AS [Ageing]          
FROM tblTranPRVoucher RV          
JOIN tblMasterCustomer MC on MC.FAID = RV.PartyID          
LEFT JOIN tblMasterCustomerType MCT on MCT.ID = MC.CustomerType          
LEFT JOIN tblBeatSalesmanMapping AS CBS ON CBS.CustomerId = MC.ID          
LEFT JOIN tblMasterBeat MB on MB.ID = CBS.BeatID          
LEFT JOIN tblMasterSalesman MS on MS.ID = CBS.SalesmanID          
WHERE RV.TransID IN(7) AND RV.DocDate <= @AsOnDate AND RV.Status IN (1,3,5)     
UNION ALL          
SELECT RV.TransID DocPrefix,RV.ID[ID],ISNULL(MB.ID,0)[Beat ID],MB.Name[Beat Name],ISNULL(MS.ID,0)[Salesman ID],MS.Name[Salesman Name],        
RV.NoteValue * -1 [NoteValue]  ,0 [Pending Amount],RV.Balance * -1 AS [SR Balance],        
DATEDIFF(DAY, RV.DocDate, @AsOnDate)  AS [Ageing]          
FROM tblNoteDetails RV          
JOIN tblMasterCustomer MC on MC.FAID = RV.PartyID          
LEFT JOIN tblMasterCustomerType MCT on MCT.ID = MC.CustomerType          
LEFT JOIN tblBeatSalesmanMapping AS CBS ON CBS.CustomerId = MC.ID          
LEFT JOIN tblMasterBeat MB on MB.ID = CBS.BeatID          
LEFT JOIN tblMasterSalesman MS on MS.ID = CBS.SalesmanID          
    WHERE RV.TransID IN(4) AND RV.DocDate <= @AsOnDate AND RV.Status IN (1,3,5)    
    UNION ALL          
SELECT RV.DocPrefix DocPrefix,RV.ColID [ID],ISNULL(MB.ID,0)[Beat ID],MB.Name[Beat Name],ISNULL(MS.ID,0)[Salesman ID],MS.Name[Salesman Name],        
RV.ColAmt * -1 [NoteValue] ,0 [Pending Amount],RV.Balance * -1 AS [SR Balance],        
DATEDIFF(DAY, RV.ColDate, @AsOnDate)  AS [Ageing]          
FROM tblTranCollectionHeader RV          
JOIN tblMasterCustomer MC on MC.FAID = RV.AccID          
LEFT JOIN tblMasterCustomerType MCT on MCT.ID = MC.CustomerType                 
LEFT JOIN tblMasterBeat MB on MB.ID = RV.BeatID          
LEFT JOIN tblMasterSalesman MS on MS.ID = RV.SalesmanID          
    WHERE RV.DocPrefix IN(4) AND RV.ColDate <= @AsOnDate AND RV.Status IN (1,3,5)    
) SRI          
-- Create #TempID for Split String Ageing Wise          
CREATE TABLE #TempID (IdentID INT IDENTITY(1,1),ID INT)          
          
-- Create #TempAlterColumns for Identifying Column and Checking Range Between          
CREATE TABLE #TempAlterColumns (IdentID INT IDENTITY(1,1),[From] INT,[To] INT,OriginalColumn NVARCHAR(MAX))          
          
-- Insert Spliting String Datas          
INSERT INTO #TempID          
SELECT * FROM (SELECT DISTINCT id FROM dbo.fnSplitString(@fnSplitString,'','') WHERE ISNULL(id,'''')!='''') AS SRI ORDER BY CAST(SRI.id AS INT)          
          
--select * from #TEMPDATA          
INSERT INTO #TempTable          
SELECT DocPrefix,ID,[Beat Name],[SalesMan Name],SUM([Opening Amount]) [Opening Amount],SUM([Pending Amount]) [Pending Amount],        
SUM([SR Balance]) [SR Balance],Ageing          
FROM #TEMPDATA          
WHERE (Ageing = 0 OR Ageing != 0)           
AND(@BeatName = '''' OR [Beat ID] IN (SELECT * from dbo.fnSplitString (@BeatName,'','')))          
AND(@SalesmanName = '''' OR [Salesman ID] IN (SELECT * from dbo.fnSplitString(@SalesmanName,'','')))          
GROUP BY  DocPrefix,ID,[Beat Name],[SalesMan Name],Ageing          
ORDER BY [Beat Name]          
          
  --select * from #TempTable        
          
INSERT INTO #TempTable1          
SELECT DocPrefix,[Beat Name],[SalesMan Name],          
DBO.fnGetRoundedValue([Opening Amount]) [Opening Amount],DBO.fnGetRoundedValue([Pending Amount]) [Pending Amount],        
DBO.fnGetRoundedValue([SR Balance]) [SR Balance],Ageing FROM (          
SELECT DocPrefix,TT.[ID],[Beat Name],[SalesMan Name],          
SUM((TT.[Opening Amount])) [Opening Amount],SUM(((TT.[Pending Amount]  + ISNULL(CT.TotalAmtAdj,0)+ ISNULL(Adjustment,0)))) AS [Pending Amount],        
SUM(TT.[SR Balance]) AS [SR Balance],Ageing          
FROM #TempTable TT          
LEFT JOIN #COLTEMP CT ON CT.DocID = TT.ID          
LEFT JOIN #JVTEMP JV ON JV.NoteID = TT.ID          
--WHERE (TT.[Pending Amount] + ISNULL(CT.TotalAmtAdj,0)+ ISNULL(Adjustment,0)) <> 0          
GROUP BY DocPrefix,ID,[Beat Name],[SalesMan Name],Ageing          
) AS NK          
WHERE ((cast(([Pending Amount]) as numeric(26,2))) <> 0  or  (cast(([SR Balance]) as numeric(26,2))) <> 0 )        
order by [Beat Name]          
          
SET @Count1 = (SELECT COUNT(*) FROM #TempID);          
SET @Count = (SELECT COUNT(*) FROM #TempID);          
SET @Serial = 1          
-- Looping for Alter and Spliting Columns using Ageing Wise          
IF ISNULL(@Count1,0)>1          
BEGIN          
print ''aaaaaaaaaaaaaaaaaa''          
WHILE (@Count > 0)          
BEGIN          
SET @AlterColumnName0 = (SELECT ID FROM #TempID WHERE IdentID = @Serial-1)          
SET @AlterColumnName1 = (SELECT ID FROM #TempID WHERE IdentID = @Serial)          
SET @AlterColumnName0 = @AlterColumnName0+1          
IF ISNULL(@Count,0)=1          
BEGIN          
SET @Query = ''ALTER TABLE #TempTable1 ADD [''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days] VARCHAR(100) NULL,[>''+@AlterColumnName1+'' Days] VARCHAR(100) NULL''          
EXEC(@Query)          
INSERT INTO #TempAlterColumns VALUES ((@AlterColumnName0),@AlterColumnName1,''[''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days]'')          
INSERT INTO #TempAlterColumns VALUES ((@AlterColumnName1),0,''[>''+@AlterColumnName1+'' Days]'')          
END          
ELSE IF ISNULL(@Count,0)= @Count1          
BEGIN          
SET @Query = ''ALTER TABLE #TempTable1 ADD [0-''+@AlterColumnName1+'' Days] VARCHAR(100) NULL''          
EXEC(@Query)          
INSERT INTO #TempAlterColumns VALUES (0,@AlterColumnName1,''[0-''+@AlterColumnName1+'' Days]'')          
END          
ELSE          
BEGIN          
SET @Query = ''ALTER TABLE #TempTable1 ADD [''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days] VARCHAR(100) NULL''          
EXEC(@Query)          
INSERT INTO #TempAlterColumns VALUES ((@AlterColumnName0),@AlterColumnName1,''[''+@AlterColumnName0+''-''+@AlterColumnName1+'' Days]'')          
END          
SET @Count = @Count - 1;          
SET @Serial = @Serial + 1;          
END          
END          
ELSE          
BEGIN          
SET @AlterColumnName0 = (SELECT ID FROM #TempID WHERE IdentID = 1)          
SET @Query = ''ALTER TABLE #TempTable1 ADD [0-''+@AlterColumnName0+'' Days] VARCHAR(100) NULL,[>''+@AlterColumnName0+'' Days] VARCHAR(100) NULL''          
EXEC(@Query)          
INSERT INTO #TempAlterColumns VALUES (0,@AlterColumnName0,''[0-''+@AlterColumnName0+'' Days]'')          
INSERT INTO #TempAlterColumns VALUES (@AlterColumnName0,0,''[>''+@AlterColumnName0+'' Days]'')          
END          
SET @MainCount = (SELECT COUNT(*) FROM #TempTable1);          
SET @MainSerial = 1          
-- Looping for Get Ageing Information from #TempTable1          
WHILE (@MainCount > 0)          
BEGIN          
SET @Ageing = (SELECT Ageing FROM #TempTable1 WHERE ID = @MainSerial)          
SET @nCount = (SELECT COUNT(*) FROM #TempAlterColumns)          
SET @nCount1 = (SELECT COUNT(*) FROM #TempAlterColumns)          
SET @nSerial = 1          
-- Looping for Check Ageing and From and To Between Ageing Range          
WHILE (@nCount > 0)          
BEGIN          
SET @nF = (SELECT [From] FROM #TempAlterColumns WHERE IdentID = @nSerial)          
SET @nT = (SELECT [to] FROM #TempAlterColumns WHERE IdentID = @nSerial)          
SET @nColumnName = (SELECT OriginalColumn FROM #TempAlterColumns WHERE IdentID = @nSerial)          
IF ISNULL(@nCount1,0) = ISNULL(@nSerial,0)          
BEGIN          
SELECT @IsTrueFalse = (CASE WHEN @Ageing > @nF THEN ''TRUE'' ELSE ''FALSE'' END)          
END          
ELSE          
BEGIN          
SELECT @IsTrueFalse = (CASE WHEN @Ageing BETWEEN @nF AND @nT THEN ''TRUE'' ELSE ''FALSE'' END)          
END          
          
-- IF TRUE Updating Pending Amount to Specific Columns          
IF ISNULL(@IsTrueFalse,'''')=''TRUE''          
BEGIN          
SET @Query = ''UPDATE #TempTable1 SET ''+@nColumnName+'' = (CASE WHEN DocPrefix = 16 then [SR Balance] ELSE [Pending Amount] END) WHERE ID=''+CAST(@MainSerial AS NVARCHAR)+''''          
EXEC (@Query)          
BREAK;          
END          
          
SET @nCount = @nCount - 1;          
SET @nSerial = @nSerial + 1;          
END          
SET @MainCount = @MainCount - 1;          
SET @MainSerial = @MainSerial + 1;          
END          
      
--select ''SUM(''+Coalesce(OriginalColumn + '''', '''')+'') ''+Coalesce(OriginalColumn + '''', ''''),* from #TempAlterColumns        
--uspRepBeatwiseOutstandingsHeader '''','''',''0,10,20'',''12/02/2026''          
      
declare @Name varchar(max)                
Select @Name = Coalesce(@Name + '','', '''') + ''dbo.fnGetRoundedValue(SUM(CONVERT(DECIMAL(25,4), ISNULL(['' + Ltrim(name) + ''],0)))) AS '' + ''['' + Ltrim(name) + '']''                
from tempdb.sys.columns                
where object_id = object_id(''tempdb..#TempTable1'') and name not in (''ID'',''Beat Name'',''SalesMan Name'',''Ageing'',''DocPrefix'')                
ORDER BY column_id      
--SELECT @Name      
      
-- Select all data from #TempTable1 Finally          
alter table #TempTable1 drop column ID          
set @Query = ''SELECT [Beat Name],[SalesMan Name],''+@Name +'' FROM #TempTable1 GROUP BY [Beat Name],[SalesMan Name] ORDER BY [Beat Name]''      
EXEC(@Query)      
ENd          
-- Drop all #Temp Tables          
DROP TABLE #TempTable1,#TempTable,#TempID,#COLTEMP,#JVTEMP ,#TempAlterColumns,#TEMPDATA',
N'[export] nocount';
GO
/****** uspRepBillWiseMarginDetail ******/
EXEC #Apply07 N'dbo.uspRepBillWiseMarginDetail', 0x46FDE3D1BA14E75BEEE67CA0635A99979DF4E38D03B1074AD19F537401546F7B, NULL, NULL, 0xA39590CDF84D39384F1B5922A02747F6618B41FE40AB5949C0AFE99327650A6E, 0xE787C4484A61094F66D4D6616313365284DAB31351B7C3CFBF82917E21ED5FA1, NULL,
N'--uspRepBillWiseMarginDetail 15,''2024-01-01'',''2026-01-26'',1
 ALTER PROCEDURE [dbo].[uspRepBillWiseMarginDetail]
 @ID INT ,  
@Fromdate DATE,  
@ToDate DATE ,  
@GNAmount INT 

AS
SET NOCOUNT ON;
BEGIN
IF(@GNAmount = 1) --GROSS AMOUNT
BEGIN

SELECT SRI.[Doc ID],SRI.[Product Code],SRI.[Product Name],SRI.EAN,
dbo.fnGetRoundedValue(SRI.[Purchase Price]) AS [Purchase Price],dbo.fnGetRoundedValue(SRI.[Sale Price]) AS [Sale Price],
dbo.fnGetRoundedValue((SRI.[Sale Margin Amount])) AS [Sale Marign Amount],dbo.fnGetRoundedValue((SRI.[Sale Margin (%)])) AS [Sale Margin (%)],
dbo.fnGetRoundedValue(SRI.[ECP Price]) AS [ECP Price],dbo.fnGetRoundedValue((SRI.[ECP Margin Amount])) AS [ECP Marign Amount],
dbo.fnGetRoundedValue((SRI.[ECP Margin (%)])) AS [ECP Margin (%)],dbo.fnGetRoundedValue(SRI.[SPL Price]) AS [SPL Price],
dbo.fnGetRoundedValue((SRI.[SPL Margin Amount])) AS [SPL Marign Amount],dbo.fnGetRoundedValue((SRI.[SPL Margin (%)])) AS [SPL Margin (%)],
dbo.fnGetRoundedValue(SRI.[MRP Price]) AS [MRP Price],dbo.fnGetRoundedValue((SRI.[MRP Margin Amount])) AS [MRP Marign Amount],
dbo.fnGetRoundedValue((SRI.[MRP Margin (%)])) AS [MRP Margin (%)]
FROM
(
SELECT PH.DocID[Doc ID],MP.Code AS [Product Code],MP.Name AS [Product Name],MP.EAN,(PD.UomPurchasePrice * PD.UomQty)  AS [Purchase Price],
-- Sale Price,Margin Amount,Margin %
(PD.UomSalePrice * PD.UomQty) AS [Sale Price],
((PD.UomSalePrice - PD.UomPurchasePrice) * PD.UomQty) AS [Sale Margin Amount],
(((((PD.UomSalePrice - PD.UomPurchasePrice) * PD.UomQty)*100)/(CASE WHEN ISNULL(PD.UomPurchasePrice,0)=0 THEN 1 ELSE (PD.UomPurchasePrice * PD.UomQty) END))) AS [Sale Margin (%)],
-- ECP Price,Margin Amount,Margin %
(PD.UomECP * PD.UomQty) AS [ECP Price],
((PD.UomECP - PD.UomPurchasePrice) * PD.UomQty) AS [ECP Margin Amount],
(((((PD.UomECP - PD.UomPurchasePrice) * PD.UomQty)*100)/(CASE WHEN ISNULL(PD.UomPurchasePrice,0)=0 THEN 1 ELSE (PD.UomPurchasePrice * PD.UomQty) END))) AS [ECP Margin (%)],
-- SPL Price,Margin Amount,Margin %
(PD.UomSPLPrice * PD.UomQty) AS [SPL Price],
((PD.UomSPLPrice - PD.UomPurchasePrice) * PD.UomQty) AS [SPL Margin Amount],
(((((PD.UomSPLPrice - PD.UomPurchasePrice) * PD.UomQty)*100)/(CASE WHEN ISNULL(PD.UomPurchasePrice,0)=0 THEN 1 ELSE (PD.UomPurchasePrice * PD.UomQty) END))) AS [SPL Margin (%)],
-- MRP Price,Margin Amount,Margin %
((PD.UomMRP * PD.UomQty) / (1 + (PD.[Tax%] / 100))) AS [MRP Price],
(((PD.UomMRP * PD.UomQty) / (1 + (PD.[Tax%] / 100)) - (PD.UomPurchasePrice * PD.UomQty))) AS [MRP Margin Amount],
(((((PD.UomMRP  * PD.UomQty) / (1 + (PD.[Tax%] / 100)) - (PD.UomPurchasePrice * PD.UomQty)) * 100) /(CASE WHEN ISNULL(PD.UomPurchasePrice,0)=0 THEN 1 ELSE (PD.UomPurchasePrice * PD.UomQty) END))) AS [MRP Margin (%)]

FROM tblTransPurchaseDetail PD 
JOIN tblTransPurchaseHeader PH on PH.ID = PD.HID
JOIN tblMasterProduct AS MP ON MP.ID = PD.ProdID
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = PH.BranchID  
JOIN tblMasterVendor MV on MV.ID = PH.VendorID
WHERE PH.Date BETWEEN @Fromdate AND @ToDate AND PH.[Status] IN (1,3,5) AND PH.ID = @ID)SRI
END

ELSE IF (@GNAmount = 2)
BEGIN

SELECT SRI.[Doc ID],SRI.[Product Code],SRI.[Product Name],SRI.EAN,dbo.fnGetRoundedValue(SRI.[Purchase Price]) AS [Purchase Price],
dbo.fnGetRoundedValue(SRI.[Sale Price]) AS [Sale Price],dbo.fnGetRoundedValue([Sale Price] - [Purchase Price]) AS [Sale Marign Amount],
dbo.fnGetRoundedValue((([Sale Price] - [Purchase Price]) / [Purchase Price]) * 100)AS [Sale Margin (%)],dbo.fnGetRoundedValue(SRI.[ECP Price]) AS [ECP Price],
dbo.fnGetRoundedValue([ECP Price] - [Purchase Price])AS [ECP Marign Amount],dbo.fnGetRoundedValue((([ECP Price] - [Purchase Price]) / [Purchase Price]) * 100) AS [ECP Margin (%)],
dbo.fnGetRoundedValue(SRI.[SPL Price]) AS [SPL Price],dbo.fnGetRoundedValue(([SPL Price] - [Purchase Price])) AS [SPL Marign Amount],
dbo.fnGetRoundedValue((([SPL Price] - [Purchase Price]) / [Purchase Price]) * 100) AS [SPL Margin (%)],dbo.fnGetRoundedValue(SRI.[MRP Price]) AS [MRP Price],
dbo.fnGetRoundedValue((SRI.[MRP Price] - [Purchase Price])) AS [MRP Marign Amount],dbo.fnGetRoundedValue((((SRI.[MRP Price] - [Purchase Price]) / [Purchase Price]) * 100)) AS [MRP Margin (%)]
FROM
(
SELECT PH.DocID[Doc ID],MP.Code AS [Product Code],MP.Name AS [Product Name],MP.EAN,
(((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + (PD.UomPurchasePrice * PD.UomQty) AS [Purchase Price],
-- Sale Price,Margin Amount,Margin %
(((PD.UomSalePrice * PD.UomQty) * PD.[Tax%]) / 100) + (PD.UomSalePrice * PD.UomQty) AS [Sale Price],
((PD.UomSalePrice - PD.UomPurchasePrice) * PD.UomQty) AS [Sale Margin Amount],
(((((PD.UomSalePrice - PD.UomPurchasePrice) * PD.UomQty)*100)/(CASE WHEN ISNULL(PD.UomPurchasePrice,0)=0 THEN 1 ELSE (PD.UomPurchasePrice * PD.UomQty) END))) AS [Sale Margin (%)],
-- ECP Price,Margin Amount,Margin %
(((PD.UomECP * PD.UomQty) * PD.[Tax%]) / 100) +  (PD.UomECP * PD.UomQty) AS [ECP Price],
((PD.UomECP - PD.UomPurchasePrice) * PD.UomQty) AS [ECP Margin Amount],
(((((PD.UomECP - PD.UomPurchasePrice) * PD.UomQty)*100)/(CASE WHEN ISNULL(PD.UomPurchasePrice,0)=0 THEN 1 ELSE (PD.UomPurchasePrice * PD.UomQty) END))) AS [ECP Margin (%)],
(((PD.UomSPLPrice * PD.UomQty) * PD.[Tax%]) / 100) +  (PD.UomSPLPrice * PD.UomQty) AS [SPL Price],
((PD.UomSPLPrice - PD.UomPurchasePrice) * PD.UomQty) AS [SPL Margin Amount],
(((((PD.UomSPLPrice - PD.UomPurchasePrice) * PD.UomQty)*100)/(CASE WHEN ISNULL(PD.UomPurchasePrice,0)=0 THEN 1 ELSE (PD.UomPurchasePrice * PD.UomQty) END))) AS [SPL Margin (%)],
(PD.UomMRP  * PD.UomQty) AS [MRP Price],
((PD.UomMRP  * PD.UomQty) - (PD.UomPurchasePrice * PD.UomQty)) AS [MRP Margin Amount],
((((PD.UomMRP  * PD.UomQty) - (PD.UomPurchasePrice * PD.UomQty)) * 100) /(CASE WHEN ISNULL(PD.UomPurchasePrice,0)=0 THEN 1 ELSE (PD.UomPurchasePrice * PD.UomQty) END)) AS [MRP Margin (%)]

FROM tblTransPurchaseDetail PD 
JOIN tblTransPurchaseHeader PH on PH.ID = PD.HID
JOIN tblMasterProduct AS MP ON MP.ID = PD.ProdID
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = PH.BranchID  
JOIN tblMasterVendor MV on MV.ID = PH.VendorID
WHERE PH.Date BETWEEN @Fromdate AND @ToDate AND PH.[Status] IN (1,3,5) AND PH.ID = @ID) SRI
END
END',
N'[export] nocount';
GO
/****** uspRepBillWiseMarginHeader ******/
EXEC #Apply07 N'dbo.uspRepBillWiseMarginHeader', 0x06E74CCB787B052D8D0C7C4622B4DF6EDC51F4A4EBF4B796270A597DE39AD5E2, NULL, NULL, 0xC0E1CA7851A681402CDBE43B1324718F7996B1C5B650E1E23BEE1252595F4DC2, 0x09909571DE1C6FA685009EB9480C68B34813C9E0BD7A407378C120D6C3BDD2A4, NULL,
N'--uspRepBillWiseMarginHeader '''','''',''2024-01-01'',''2026-01-26'',2    
ALTER PROCEDURE [dbo].[uspRepBillWiseMarginHeader]    
    
@VendorName NVARCHAR(255) = '''',    
@BranchName INT,    
@Fromdate DATE =NULL,    
@ToDate DATE =NULL,    
@Type INT    
    
AS     
SET NOCOUNT ON;
BEGIN    
    
IF (@Type = 1)    
BEGIN    
    
SELECT PH.ID[ID], @Fromdate as [From],@ToDate as [To],@Type AS [GNAmount],PH.DocID[Doc ID],    
FORMAT(PH.Date,''dd/MMM/yyyy'') [Doc Date],MV.Name[Vendor Name],MBO.Name[Branch Name],    
dbo.fnGetRoundedValue(PH.GrossAmt)[Selected Amount],    
dbo.fnGetRoundedValue(SUM(ISNULL(PD.UomPurchasePrice,0) * ISNULL(PD.UomQty,0)))  AS [Purchase Price],    
dbo.fnGetRoundedValue(SUM((PD.UomSalePrice - PD.UomPurchasePrice) * PD.UomQty)) AS [Sales Margin Amount],    
dbo.fnGetRoundedValue((SUM((PD.UomSalePrice - PD.UomPurchasePrice) * PD.UomQty)*100)/ NULLIF (SUM(PD.UomPurchasePrice * PD.UomQty),0)) as [Sales Margin %],    
dbo.fnGetRoundedValue(SUM((PD.UomECP - PD.UomPurchasePrice) * PD.UomQty)) AS [ECP Margin Amount],    
dbo.fnGetRoundedValue((SUM((PD.UomECP - PD.UomPurchasePrice) * PD.UomQty)*100)/ NULLIF (SUM(PD.UomPurchasePrice * PD.UomQty),0)) as [ECP Margin %],    
dbo.fnGetRoundedValue(SUM((PD.UomSPLPrice - PD.UomPurchasePrice) * PD.UomQty)) AS [SPL Margin Amount],    
dbo.fnGetRoundedValue((SUM((PD.UomSPLPrice - PD.UomPurchasePrice) * PD.UomQty)*100) / NULLIF (SUM(PD.UomPurchasePrice * PD.UomQty),0)) as [SPL Margin %],    
dbo.fnGetRoundedValue(SUM(((PD.UomMRP / (1 + (PD.[Tax%] / 100)) - PD.UomPurchasePrice) * PD.UomQty))) AS [MRP Margin Amount],    
dbo.fnGetRoundedValue(SUM((((PD.UomMRP / (1 + (PD.[Tax%] / 100))) - PD.UomPurchasePrice) * PD.UomQty)*100)/ NULLIF (SUM(PD.UomPurchasePrice * PD.UomQty),0)) as [MRP Margin %]    
    
FROM tblTransPurchaseHeader PH    
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = PH.BranchID    
JOIN tblMasterVendor MV on MV.ID = PH.VendorID    
JOIN tblTransPurchaseDetail PD on PD.HID = PH.ID    
WHERE PH.Date BETWEEN @Fromdate AND @ToDate AND PH.[Status] IN (1,3,5) AND PH.TransID = 1    
AND(@VendorName = '''' OR MV.ID IN(SELECT * from dbo.fnSplitString( @VendorName,'','')))    
AND(@BranchName = 0 OR MBO.ID = @BranchName)    
GROUP BY PH.ID,PH.DocID,PH.Date,PH.UDFDocId,MV.Name,MBO.Name,PH.GrossAmt    
END    
    
ELSE IF (@Type = 2)    
BEGIN    
    
SELECT PH.ID[ID], @Fromdate as [From],@ToDate as [To],@Type AS [GNAmount],PH.DocID[Doc ID],    
FORMAT(PH.Date,''dd/MMM/yyyy'') [Doc Date],MV.Name[Vendor Name],MBO.Name[Branch Name],    
dbo.fnGetRoundedValue(PH.NetAmt)AS [Selected Amount],    
dbo.fnGetRoundedValue(((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty)))  AS [Purchase Price],    
dbo.fnGetRoundedValue(((sum((PD.UomSalePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomSalePrice * PD.UomQty))    
- ((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty)))  AS [Sales Margin Amount],    
dbo.fnGetRoundedValue(((((sum((PD.UomSalePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomSalePrice * PD.UomQty))    
- ((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty))) /    
NULLIF (((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty)),0))* 100 ) as [Sales Margin %],    
dbo.fnGetRoundedValue(((sum((PD.UomECP * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomECP * PD.UomQty))    
- ((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty)))  AS [ECP Margin Amount],    
dbo.fnGetRoundedValue(((((sum((PD.UomECP * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomECP * PD.UomQty))    
- ((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty))) /    
NULLIF (((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty)),0))* 100 ) as [ECP Margin %],    
dbo.fnGetRoundedValue(((sum((PD.UomSPLPrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomSPLPrice * PD.UomQty))    
- ((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty))) AS [SPL Margin Amount],    
dbo.fnGetRoundedValue(((((sum((PD.UomSPLPrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomSPLPrice * PD.UomQty))    
- ((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty))) /    
NULLIF (((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty)),0))* 100 ) as [SPL Margin %],    
dbo.fnGetRoundedValue((sum(PD.UomMRP * PD.UomQty))    
- ((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty))) AS [MRP Margin Amount],    
dbo.fnGetRoundedValue((((sum((PD.UomMRP * PD.UomQty))    
- ((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty))) /    
NULLIF (((sum((PD.UomPurchasePrice * PD.UomQty) * PD.[Tax%]) / 100) + sum(PD.UomPurchasePrice * PD.UomQty)),0))* 100 )) as [MRP Margin %]    
    
FROM tblTransPurchaseHeader PH    
JOIN tblMasterVendor MV on MV.ID = PH.VendorID    
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = PH.BranchID    
JOIN tblTransPurchaseDetail PD on PD.HID = PH.ID    
WHERE PH.Date BETWEEN @Fromdate AND @ToDate AND PH.[Status] IN (1,3,5)AND PH.TransID = 1    
AND(@VendorName = '''' OR MV.ID IN(SELECT * from dbo.fnSplitString (@VendorName,'','')))    
AND(@BranchName = 0 OR MBO.ID = @BranchName)    
GROUP BY PH.ID,PH.DocID,PH.Date,MV.Name,MBO.Name,PH.NetAmt    
END    
END',
N'[export] nocount';
GO
