/****** uspRepChequeDepositHeader ******/
EXEC #Apply07 N'dbo.uspRepChequeDepositHeader', 0xD6917D3AE41562DD3150525BD26EFE0C6387E44158F0ADF47FFA0A8853CA339A, NULL, NULL, 0xFF568061BDC50848261F99A86144D6BC5856F543A8C0C416FAE5E9D608697F30, 0xCAF6C3F5AE6AEF617FB5C098A2273D6A5F833A6CFB5EF39DD4FC6018881A275B, NULL,
N'ALTER procedure [dbo].[uspRepChequeDepositHeader]
@StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2024-01-01'',@ToDate DATE =''2026-09-30''
AS    
SET NOCOUNT ON;
BEGIN    
DECLARE @Sts AS TABLE(Status INT)    
IF(@StatusID = 0)    
BEGIN    
INSERT INTO @Sts values (1),(3),(5)    
