/****** uspRepChequeInHandHeader ******/
EXEC #Apply07 N'dbo.uspRepChequeInHandHeader', 0xBFF9EBD2978239784C5B2111FE1D3BAB46E2550920A8A8B283B20AE919D263DA, NULL, NULL, 0x3894F2C7FB1540190FAC0AC90E074C8963CA23AA6B280CFB26989EB9038E840F, 0x5FBA50F82E3413A30D46A6BC5FFB688D5148C4D7932CCB070EC56238C1539472, NULL,
N'--uspRepChequeInHandHeader '''', '''',''''  
ALTER PROCEDURE [dbo].[uspRepChequeInHandHeader]  
@ChequeNo NVARCHAR(255) = '''',  
@CustomerName NVARCHAR(255) = '''',  
@Status INT = 1  
  
  
AS  
SET NOCOUNT ON;
BEGIN  
DECLARE @Sts AS TABLE(Status INT)  
IF(@Status = 0)  
BEGIN  
INSERT INTO @Sts values (1),(9),(5)  
END  
ELSE            
BEGIN            
INSERT INTO @Sts values(@Status)            
END     
  
SELECT *INTO #MainTemp FROM (  
  
SELECT CH.ColID,DocID AS [Doc ID],FORMAT(ColDate,''dd/MMM/yyyy'') AS [Collection Date],  
FA.AccountName as [Party Name],FORMAT(CPM.Date,''dd/MMM/yyyy'') AS [Cheque Date],(SUM(CPM.CollAmt)) AS [Cheque Amount], CPM.[Cheque/DD Number] as [Cheque No],  
CPM.BankName as [Bank Name],CPM.IfscCode AS [IFSC Code], S.Description as [Status],S.ID as [nStatus]  
  
FROM tblCollPMDetails CPM  
JOIN tblTranCollectionHeader CH ON CH.ColID = CPM.ColID  
JOIN tblPaymentMode PM ON PM .Id =CPM .PaymentTermID  
JOIN tblFAAccount FA ON FA.FAID =CPM.AccId  
JOIN tblMasterCustomer MC on MC.FAID = CH.AccID  
JOIN tblStatus S ON S.ID =CPM.[Status]  
WHERE CPM.PaymentTermID IN (2,3)  
AND CPM.Status in (select * from @Sts)  
AND (@CustomerName = '''' OR MC.ID IN (SELECT * from dbo.fnSplitString(@CustomerName,'','')))  
  
  
GROUP BY CH.ColID,DocID,ColDate,MC.Name,FA.AccountName,CPM.[Cheque/DD Number],CPM.Date,CPM.BankName  
,CPM.IfscCode, S.Description,S.ID  
  
UNION ALL  
  
SELECT CH.ColID,CH.DocID AS [Doc Id],CONVERT(NVARCHAR,ColDate,103) AS [Collection Date],  
FA.AccountName as [Party Name],CONVERT(NVARCHAR,CPM.Date,103) AS [Cheque Date],(SUM(CPM.CollAmt)) AS [Cheque Amount], CPM.[Cheque/DD Number] as [Cheque No],  
CPM.BankName as [Bank Name],CPM.IfscCode AS [IFSC Code], S.Description as [Status],S.ID as [nStatus]  
  
FROM tblCollPMDetails CPM  
JOIN tblTranCollectionHeader CH ON CH.ColID = CPM.ColID  
JOIN tblTranChequeDeposit CD ON CD.CollId =CPM.ColID  
JOIN tblPaymentMode PM ON PM .Id =CPM .PaymentTermID  
JOIN tblFAAccount FA ON FA.FAID =CPM .AccId  
JOIN tblMasterCustomer MC on MC.FAID = CH.AccID  
JOIN tblStatus S ON S.ID =CPM.Status  
JOIN tblTranPRVoucher TPR ON CD.ChaqueVoucherId= TPR.ID  
WHERE  CPM.Status in (select * from @Sts)  
AND TPR.NetAmount = TPR.Balance AND TPR.[Status]=1  
AND (@CustomerName = '''' OR MC.ID IN (SELECT * from dbo.fnSplitString(@CustomerName,'','')))    
  
GROUP BY CH.ColID,CH.DocID,ColDate,MC.Name,FA.AccountName,CPM.[Cheque/DD Number],CPM.Date,CPM.BankName  
,CPM.IfscCode, S.Description,S.ID) AS REC  
  
IF(LEN(@ChequeNo) > 0)  
BEGIN  
SELECT ColID,[Doc Id],[Collection Date],[Party Name],[Cheque Date],[dbo].[fnGetRoundedValue]([Cheque Amount]) [Cheque Amount],  
[Cheque No],[Bank Name],[IFSC Code],Status FROM #MainTemp  
WHERE [Cheque No] IN (SELECT * FROM dbo.fnSplitString(@ChequeNo, '',''))   
GROUP BY ColID,[Doc Id],[Collection Date],[Party Name],[Cheque Date],([Cheque Amount]),[Bank Name],[IFSC Code],Status,  
[Cheque No]  
ORDER BY ColID ASC  
END  
ELSE  
BEGIN  
SELECT ColID,[Doc Id],[Collection Date],[Party Name],[Cheque Date],[dbo].[fnGetRoundedValue]([Cheque Amount]) [Cheque Amount],  
[Cheque No],[Bank Name],[IFSC Code],Status FROM #MainTemp  
WHERE nStatus IN (SELECT Status FROM @Sts)  
GROUP BY ColID,[Doc Id],[Collection Date],[Party Name],[Cheque Date],([Cheque Amount]),[Bank Name],[IFSC Code],Status,  
[Cheque No]  
ORDER BY ColID  
END  
  
DROP TABLE #MainTemp  
END',
N'[export] nocount';
GO
/****** uspRepContraHeader ******/
EXEC #Apply07 N'dbo.uspRepContraHeader', 0x2F64997E86A7B84FF1F9F8B831612EBFC80ABB7EF59378F4917C7984473DBD3B, NULL, NULL, 0xAD8A4DAE5CCCD6CA8A6867BB11505A50020C19A47916ACF2EC99D5E98D21B0D7, 0x76E7B94F9EFD8D1AB9137DC31D16E655026C6CB03ADFE455F8CF89D6B4945168, NULL,
N'ALTER procedure [dbo].[uspRepContraHeader]
@StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2024-01-01'',@ToDate DATE =''2026-09-30'', @TransID INT = 8
AS  
SET NOCOUNT ON;
BEGIN  
DECLARE @Sts AS TABLE(Status INT)  
IF(@StatusID = 0)  
BEGIN  
INSERT INTO @Sts values (1),(3),(5)  
END  
ELSE  
BEGIN   
INSERT INTO @Sts values(@StatusID)  
END  

SELECT
	C.ID[ID],C.DocID[Doc ID], FORMAT(C.DocDate,''dd/MMM/yyyy'')[Doc Date],C.RefNo[Ref No],CT.TypeName[Contra Type],CM.ModeName[Contra Mode],
	FA.AccountName[From A/C Name], FT.AccountName[To A/C Name],dbo.fnGetRoundedValue(C.Amount)[Amount],
	dbo.fnGetRoundedValue(C.Balance)[Balance],C.ChequeNo[Cheque No], C.WDSlipNo[NEFT No],SM.Name[Salesman],
	C.Remarks[Remarks],C.Narration[Narration],S.Description[Status]
	,CU.UserName[Created By],CONVERT(NVARCHAR,C.CDate)[Create Date],
	MU.UserName[Modified By],CONVERT(NVARCHAR,C.MDate)[Modify Date]


From tblTranContra C
LEFT JOIN tblContraType CT on CT.ID = C.TypeID 
LEFT JOIN tblContraMode CM on CM.ID = C.ModeID
LEFT JOIN tblFAAccount FA on FA.FAID = C.FromFAID
LEFT JOIN tblFAAccount FT on FT.FAID = C.ToFAID
LEFT JOIN tblStatus S on S.ID = C.Status
LEFT JOIN tblUsers CU on CU.ID = C.Cby
LEFT JOIN tblUsers MU on MU.ID = C.Mby
LEFT JOIN tblMasterSalesman SM on SM.ID = C.SalesManID
		  WHERE C.DocDate BETWEEN @FromDate AND @ToDate
      AND C.Status IN (SELECT Status FROM @Sts)
	  AND (@TransID IS NULL OR C.TransID = @TransID);

END',
N'[export] nocount';
GO
/****** uspRepCreditNoteHeader ******/
EXEC #Apply07 N'dbo.uspRepCreditNoteHeader', 0x190E561D03AA72CC75A86F2DA81E42C483E95E368D6AC43149FD5EAC01B2E613, NULL, NULL, 0x1FDF4696CC77D8CDCB9958DB44DF36A50DD26A7978DD291383A5BAA6ED85BEA5, 0x57F1FB0344272D5770958C15D7EF41CE966FB991613E6D4C46B068DBC58ADBB7, NULL,
N'ALTER procedure [dbo].[uspRepCreditNoteHeader]
@StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2024-01-01'',@ToDate DATE =''2026-09-30'', @TransID INT = 4  
AS  
SET NOCOUNT ON;
BEGIN  
DECLARE @Sts AS TABLE(Status INT)  
IF(@StatusID = 0)  
BEGIN  
INSERT INTO @Sts values (1),(3),(5)  
END  
ELSE  
