select 
	CDN.ID[ID],CDN.DocID as [Doc ID], FORMAT(CDN.DocDate, ''dd/MMM/yyyy'') AS [Doc Date],CDN.RefNo[Ref No],MCD.AccountName[Party Name],FCD.AccountName[Account Name],
	[dbo].[fnGetRoundedValue](CDN.NoteValue)[Amount],[dbo].[fnGetRoundedValue](CDN.Balance)[Balance],SCD.Description[Status],
