	From tblNoteDetails CDN
	left join tblFAAccount MCD on MCD.FAID = CDN.PartyID
	LEFT JOIN tblFAAccount FCD on FCD.FAID = CDN.FAID
	left join tblStatus SCD on SCD.ID = CDN.Status
	LEFT JOIN tblUsers CU  ON CU.ID = CDN.CBy  
    LEFT JOIN tblUsers MU  ON MU.ID = CDN.MBy  
	  WHERE CDN.DocDate BETWEEN @FromDate AND @ToDate
      AND CDN.Status IN (SELECT Status FROM @Sts)
	  AND (@TransID IS NULL OR CDN.TransID = @TransID);

