/****** uspRepDiscountedSalesDetail ******/
EXEC #Apply07 N'dbo.uspRepDiscountedSalesDetail', 0x35CB91D7AC6CBE5ED8ED92012C90F79F0740C583F3845892FE015704E373CEDE, NULL, NULL, 0x3270803EDDF85053886C6099D285C7FAAF0EB79941524BB4235BE6E9286B733E, 0x099498C0B9DE01B7E21A950AF6734CEDD86BF98623384F2C32A5229A73F52726, NULL,
N'--uspRepDiscountedSalesDetail 18,''2025-01-01'',''2026-08-01''
ALTER PROCEDURE [dbo].[uspRepDiscountedSalesDetail]

@CustomerID INT,
@FromDate DATE,
@ToDate DATE

AS
SET NOCOUNT ON;
BEGIN

SELECT ISNULL(MCT.ID,0) AS CustTypeId,MC.ID as CustId,
ISNULL(TMB.ID,0) AS BeatId ,ISNULL(SM.ID,0) AS SalesmanId,
SH.ID,SH.DocId AS [Invoice No],CONVERT(NVARCHAR,SH.InvDate,103) AS [Date],
MC.Name as [Customer Name],TMB.Name as [Beat Name],SM.Name as [Salesman Name],
SH.DocRef AS [Ref No],(ISNULL(sum(sd.GoodsAmt),0)) AS [Goods Amount],
(ISNULL((TotalProdDiscAmt * 100) / CASE WHEN (SH.GrossAmt+TotalTradeDiscAmt+AdditionalDiscAmt+TotalProdDiscAmt)=0
THEN 1 ELSE (SH.GrossAmt+TotalTradeDiscAmt+AdditionalDiscAmt+TotalProdDiscAmt) END,0)) AS [Product Discount %],
(ISNULL((SH.TotalProdDiscAmt),0))AS [Product Discount Amount],
(ISNULL((SH.TradeDisc),0))AS [Trade Discount %],
(ISNULL((SH.TotalTradeDiscAmt),0))AS [Trade Discount Amount],
(ISNULL((SH.AdditionalDisc),0))AS [Addtional Discount %],
(ISNULL((SH.AdditionalDiscAmt),0))AS [Addtional Discount Amount],
(ISNULL((SH.Frieght),0))AS [Freight Amt],
(ISNULL((SH.OtherCharge),0))AS [Other Charge %],
(ISNULL((SH.OtherChargeAmt),0))AS [Other Charge Amount],
(ISNULL((SH.TotalDiscountAmt),0))AS [Discount Amount],
(ISNULL((SH.GrossAmt),0))AS [Gross Amount],
(ISNULL((SH.TotalTaxAmt),0))AS [Tax Amount],
(ISNULL((SH.NetAmt),0)) AS [Net Amount] into #DisTemp
--dbo.fnGetRoundedValue(ISNULL((SH.TotalDiscountAmt + ABS(SH.OtherChargeAmt)),0)) AS [Net Impact Amount]
FROM tblTranSalesHeader AS SH
JOIN tblTranSalesDetail AS SD ON SH.ID = SD.InvId
LEFT JOIN tblMasterCustomer AS MC ON MC.ID = SH.CustId
LEFT JOIN tblMasterCustomerType AS MCT ON MCT.ID = MC.CustomerType
left JOIN tblMasterBeat AS TMB ON TMB.ID = SH.BeatID
LEFT JOIN tblMasterSalesMan AS SM ON SM.ID = SH.SalesManId
WHERE SH.InvDate BETWEEN @FromDate AND @ToDate
AND SH.DocPrefix=15 AND SH.Status IN(1,3,5)
AND ISNUll(MC.ID,0)=@CustomerID
GROUP By MCT.ID,MC.ID,TMB.ID,MC.Name,TMB.Name ,SM.Name,SM.ID,SH.DocId,SH.InvDate,
SH.UDFDocId,SH.DocRef,SH.TotalProdDiscAmt,
SH.TotalTradeDiscAmt,SH.AdditionalDiscAmt,SH.TotalDiscountAmt,SH.GrossAmt,SH.TotalTaxAmt,SH.NetAmt,
SH.TradeDisc,SH.AdditionalDisc,SH.Frieght,SH.OtherCharge,SH.OtherChargeAmt,SH.TotalDiscountAmt,SH.ID
ORDER BY SH.ID

SELECT DISTINCT TSH.ID,SUM(isnull(case when TCH.Status != 4 then (DiscAmt) else 0 end ,0)) AS [Coll DiscAmt]
into #CollTemp FROM tblTranCollectionDetail TCD
LEFT JOIN tblTranSalesHeader TSH ON TSH.ID = TCD.DocID
JOIN tblTranCollectionHeader TCH ON TCH.ColID = TCD.ColID
GROUP BY TSH.ID
SELECT 
[Invoice No],Date,[Customer Name],[Beat Name],[Salesman Name],[Ref No],
dbo.fnGetRoundedValue([Goods Amount]) [Goods Amount],
dbo.fnGetRoundedValue([Product Discount %]) [Product Discount %],
dbo.fnGetRoundedValue([Product Discount Amount]) [Product Discount Amount],
dbo.fnGetRoundedValue([Trade Discount %]) [Trade Discount %],
dbo.fnGetRoundedValue([Trade Discount Amount]) [Trade Discount Amount],
dbo.fnGetRoundedValue([Addtional Discount %]) [Addtional Discount %],
dbo.fnGetRoundedValue([Addtional Discount Amount]) [Addtional Discount Amount],
dbo.fnGetRoundedValue([Freight Amt]) [Freight Amt],
dbo.fnGetRoundedValue([Other Charge %]) [Other Charge %],
dbo.fnGetRoundedValue([Other Charge Amount]) [Other Charge Amount],
dbo.fnGetRoundedValue([Discount Amount]) [Discount Amount],
dbo.fnGetRoundedValue([Gross Amount]) [Gross Amount],
dbo.fnGetRoundedValue([Tax Amount]) [Tax Amount],
dbo.fnGetRoundedValue([Net Amount]) [Net Amount],
dbo.fnGetRoundedValue(([Discount Amount] + abs([Other Charge Amount]) + isnull(CT.[Coll DiscAmt],0))) as [Net Impact Amount],
dbo.fnGetRoundedValue(isnull(CT.[Coll DiscAmt],0)) [Discount in Collection]
FROM #DisTemp DT
LEFT JOIN #CollTemp CT ON CT.ID = DT.ID
WHERE ([Product Discount Amount] > 0 OR [Trade Discount Amount] > 0
OR [Addtional Discount Amount] > 0 OR [Other Charge Amount] > 0 OR CT.[Coll DiscAmt] > 0)
ORDER BY [Invoice No]
DROP TABLE #CollTemp,#DisTemp
END',
N'[export] nocount';
GO
/****** uspRepDiscountedSalesHeader ******/
EXEC #Apply07 N'dbo.uspRepDiscountedSalesHeader', 0x47DFB3FB39466F40EDBE5C7911D661AA95A4552693B48BC1949A0F7DF1387341, NULL, NULL, 0xF2023E7BB58ECE426EB00F5504B8B18003188478F9055EF69B0494843329B13E, 0xA3812584BBF42B958A9376E7FD3C6FB7775E9FC4E964527495F7A2BB74BE4714, NULL,
N'--uspRepDiscountedSalesHeader '''','''','''','''','''',''2026-01-01'',''2026-08-01''          
ALTER PROCEDURE [dbo].[uspRepDiscountedSalesHeader]          
      
@BranchName INT,      
@BeatName NVARCHAR(255) = '''',      
@SalesmanName NVARCHAR(255) = '''',      
@CustomerName NVARCHAR(255) = '''',            
@CustomerType NVARCHAR(255) = '''',          
@FromDate DATE = ''2024-08-01'',              
@ToDate DATE = ''2026-08-30''            
          
AS              
SET NOCOUNT ON;
BEGIN            
          
          
SELECT MCT.ID AS CustTypeId,MC.ID CustId,MB.ID BeatId,MBO.ID BranchId,SM.ID SalesmanId,  MC.Name[Customer Name],MCT.Name[Customer Type],SM.Name[Salesman Name], MB.Name[Beat Name], MBO.Name[Branch Name],          
COUNT(SH.ID) AS InvId, SUM(ISNULL(SD.GoodsAmt,0)) AS [GoodsAmt],ISNULL((TotalProdDiscAmt * 100) / CASE WHEN (SH.GrossAmt+TotalTradeDiscAmt+AdditionalDiscAmt+TotalDiscountAmt+TotalProdDiscAmt)=0          
THEN 1 ELSE (SH.GrossAmt+TotalTradeDiscAmt+AdditionalDiscAmt+TotalProdDiscAmt) END,0) AS [Product Discount %],          
(SH.TotalProdDiscAmt) AS [Product Discount Amount],          
(SH.TradeDisc) AS [Trade Discount %],(SH.TotalTradeDiscAmt) AS [Trade Discount Amount],          
(SH.AdditionalDisc) AS [Addtional Discount %],(SH.AdditionalDiscAmt) AS [Addtional Discount Amount],          
(SH.Frieght) AS [Fright Amt],(SH.OtherCharge) AS [Other Charge %],(SH.OtherChargeAmt) AS [Other Charge Amount],          
(SH.TotalDiscountAmt) AS [Discount Amount],(SH.GrossAmt) AS [Gross Amount],(SH.TotalTaxAmt) AS [Tax Amount],          
(SH.NetAmt) AS [Net Amount] into #DiscTemp          
          
FROM tblTranSalesHeader AS SH          
JOIN tblTranSalesDetail AS SD ON SD.InvID = SH.ID          
LEFT JOIN tblMasterCustomer AS MC ON MC.ID = SH.CustID          
LEFT JOIN tblMasterCustomerType AS MCT ON MCT.ID = MC.CustomerType          
Left JOIN tblMasterBranchOffice MBO on MBO.ID = SH.BranchID          
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID          
LEFT JOIN tblMasterSalesMan AS SM ON SM.ID = SH.SalesManId          
WHERE SH.DocPrefix = 15 AND SH.Status IN(1,3,5)          
AND SH.InvDate BETWEEN @FromDate AND @ToDate  AND (@BranchName = 0 OR sh.BranchID = @BranchName)        
          
          
GROUP By MCT.ID,MC.ID,MB.ID,MBO.ID,SM.ID, MC.Name,MCT.Name,SM.Name,          
MB.Name,MBO.Name, SH.TotalProdDiscAmt,SH.TotalTradeDiscAmt,          
SH.AdditionalDiscAmt,SH.TotalDiscountAmt,SH.GrossAmt,SH.TotalTaxAmt,SH.NetAmt,SH.AdditionalDisc,SH.TradeDisc,          
SH.Frieght,SH.OtherCharge,SH.OtherChargeAmt,SH.TotalDiscountAmt,SH.Frieght,SH.ID          
          
SELECT DISTINCT TSH.ID,SUM(isnull(case when TCH.Status != 4 then (DiscAmt) else 0 end ,0)) AS [Coll DiscAmt]          
into #CollTemp FROM tblTranCollectionDetail TCD          
LEFT JOIN tblTranSalesHeader TSH ON TSH.ID = TCD.DocID          
--LEFT JOIN tblTranSalesHeader TSH ON TSH.InvId = TSD.InvId          
JOIN tblTranCollectionHeader TCH ON TCH.ColID = TCD.ColID          
--where TSH.DocPrefix = 2 AND TSH.Status IN(1,3,5)          
GROUP BY TSH.ID          
select isnull(CustTypeId,0) CustTypeId,isnull(CustId,0) CustId,isnull(BeatId,0) BeatId,isnull(BranchId,0) BranchId,isnull(SalesmanId,0) SalesmanId,          
@FromDate AS [FromDate],@ToDate AS [ToDate],[Customer Name],[Customer Type],          
[Salesman Name],[Beat Name],[Branch Name],dt.InvId,GoodsAmt,(([Product Discount Amount] / GoodsAmt) * 100) [Product Discount %],          
[Product Discount Amount],[Trade Discount %],[Trade Discount Amount],          
[Addtional Discount %],[Addtional Discount Amount],[Fright Amt],[Other Charge %],[Other Charge Amount],[Discount Amount],          
[Gross Amount],[Tax Amount],[Net Amount],([Discount Amount] + abs([Other Charge Amount]) + isnull(CT.[Coll DiscAmt],0)) as [Net Impact],          
isnull(CT.[Coll DiscAmt],0) [Coll DiscAmt] into #MainTemp from #DiscTemp DT          
left join #CollTemp CT ON CT.ID = DT.InvId          
where ([Product Discount %] > 0  or [Addtional Discount Amount] > 0 or          
[Other Charge Amount] > 0 or CT.[Coll DiscAmt] > 0 OR [Trade Discount Amount] > 0)          
     
          
select custId, FromDate,ToDate,[Branch Name],[Customer Name],[Customer Type],[Salesman Name],[Beat Name],COUNT(InvId) as [Invoice Count],          
dbo.fnGetRoundedValue(SUM(GoodsAmt)) [Goods Amount],dbo.fnGetRoundedValue((SUM([Product Discount Amount]) / SUM(GoodsAmt))*100) [Product Discount %],          
dbo.fnGetRoundedValue(SUM([Product Discount Amount])) [Product Discount Amount],          
dbo.fnGetRoundedValue((SUM([Trade Discount Amount]) / (SUM(GoodsAmt) - SUM([Product Discount Amount]) ))*100)  [Trade Discount %],          
dbo.fnGetRoundedValue(SUM([Trade Discount Amount])) [Trade Discount Amount],          
dbo.fnGetRoundedValue((SUM([Addtional Discount Amount]) / (SUM(GoodsAmt) - SUM([Product Discount Amount])))*100)  [Addtional Discount %],          
dbo.fnGetRoundedValue(SUM([Addtional Discount Amount])) [Addtional Discount Amount],dbo.fnGetRoundedValue(SUM([Fright Amt])) [Freight Amount],          
dbo.fnGetRoundedValue(SUM([Other Charge %])) [Other Charge %],dbo.fnGetRoundedValue(SUM([Other Charge Amount])) [Other Charge Amount],          
dbo.fnGetRoundedValue(SUM([Discount Amount])) [Discount Amount],          
dbo.fnGetRoundedValue(SUM([Gross Amount])) [Gross Amount],dbo.fnGetRoundedValue(SUM([Tax Amount])) [Tax Amount],          
dbo.fnGetRoundedValue(SUM([Net Amount])) [Net Amount],dbo.fnGetRoundedValue(SUM([Net Impact])) [Net Impact Amount],          
dbo.fnGetRoundedValue(SUM([Coll DiscAmt])) [Discount in Collection] from #MainTemp WHERE 1 = 1           
          
AND (@CustomerName = '''' OR CustId IN (SELECT * from dbo.fnSplitString( @CustomerName,'','')))          
AND (@CustomerType = '''' OR CustTypeId IN (SELECT * from dbo.fnSplitString( @CustomerType,'','')))          
AND (@BeatName = '''' OR BeatId IN (SELECT * from dbo.fnSplitString( @BeatName,'','')))          
AND (@SalesmanName = '''' OR SalesmanId IN (SELECT * from dbo.fnSplitString( @SalesmanName,'','')))          
          
group by CustTypeId,CustId,BeatId,SalesmanId,BranchId,[Customer Name],[Customer Type],[Salesman Name],[Beat Name],[Branch Name],FromDate,ToDate          
order by [Customer Name]          
drop table #CollTemp,#DiscTemp,#MainTemp          
END',
N'[export] nocount';
GO
