/****** uspRepInventoryAdjustmentDetail ******/
EXEC #Apply07 N'dbo.uspRepInventoryAdjustmentDetail', 0xF20A79A971DC1B89F6FB2664E21F2A5DA9234E80FF19F30C7ACDFB40E8D2BA0D, 0x987D18CE97BA5840D645DE8090D17F44321BB2CC9CE0A951E867C410A0E920E1, NULL, 0xFCEC7795DCD5E42A8D86ADB23CE7F10B3B528E391EC2D9470166799BC3470B7E, 0x087EAC11706575089820193A0E3DC0154F3E6ADAAE7E4D9E65882ED1A1457A4C, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspRepInventoryAdjustmentDetail]  
 @InventoryID int = 67,@BranchName NVARCHAR(255) = '''',  @ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',      
@ProductName NVARCHAR(255)='''', @FromDate DATE = ''2025-09-01'', @ToDate DATE = ''2025-12-31''  
as  
SET NOCOUNT ON;
begin  
DECLARE @query NVARCHAR(MAX)      
set @query = ''   
SELECT InventHeader.DocID AS [Doc ID],    
format(InventoryDate,''''dd/MMM/yyyy'''') AS [Doc Date],product.Code AS [Product Code] ,product.Name AS [Product Name],  
Manuf.Name AS [Mfr Name],MB.Name AS [Brand Name],PHL.Name AS [Category Name],    
[dbo].[fnGetRoundedValue](OrgPurPrice) AS [Original Purchase Price],    
[dbo].[fnGetRoundedValue](OrgQty) AS [Original Purchase Qty] ,[dbo].[fnGetRoundedValue](OrgFreeQty) as [Original Free Qty],    
[dbo].[fnGetRoundedValue](OrgDmgQty) as [Original Damage Qty],    
[dbo].[fnGetRoundedValue](ActualPurPrice)as [Actual Purchase Price],    
[dbo].[fnGetRoundedValue](InvDetail.ActualQty)AS[Actual Qty],    
[dbo].[fnGetRoundedValue](InvDetail.ActualFreeQty)AS[Actual Free Qty]    
,[dbo].[fnGetRoundedValue](InvDetail.ActualDmgQty)AS [Actual Damage Qty],    
[dbo].[fnGetRoundedValue](InvDetail.ActualQty - InvDetail.OrgQty)AS[Actual Qty Difference],    
[dbo].[fnGetRoundedValue](InvDetail.ActualFreeQty - InvDetail.OrgFreeQty)AS[Actual Free Qty Difference],    
[dbo].[fnGetRoundedValue](InvDetail.ActualDmgQty - InvDetail.OrgDmgQty)AS[Actual Damage Qty Difference],    
[dbo].[fnGetRoundedValue]((ActualPurPrice - OrgPurPrice) * ActualQty) as [Actual Price Difference],    
[dbo].[fnGetRoundedValue]((ActualPurPrice - OrgPurPrice) * ActualDmgQty) as [Actual Damage Price Difference],    
[dbo].[fnGetRoundedValue]((InvDetail.ActualQty - InvDetail.OrgQty) * ActualPurPrice) [Final Diff Value],    
[dbo].[fnGetRoundedValue]((InvDetail.ActualDmgQty - InvDetail.OrgDmgQty) * ActualPurPrice) [Final Diff Damage Value],    
[dbo].[fnGetRoundedValue](GrossAmt) AS [Gross Amount] ,rea.Name AS [Reason]    
FROM tblInventoryDetail AS InvDetail  
join tblInventoryHeader as InventHeader on InventHeader.InventoryID = InvDetail.InventoryID  
JOIN tblMasterProduct AS Product  ON InvDetail.ProdID=Product.ID    
JOIN tblMasterBrand MB ON MB.ID = Product.BrandID      
JOIN tblMasterCategory PHL ON PHL.ID = Product.CategoryID          
JOIN tblMasterManufacturer AS Manuf ON Manuf.ID = Product.MfrID   
LEFT JOIN tblMasterReason as rea ON rea.ID=InvDetail.ReasonId    
WHERE InventHeader.InventoryID=  @InventoryID ''  
set @query += case when ISNULL(@BranchName,0) = 0 then '''' else '' AND InventHeader.BranchID = ''+'' @BranchName ''+'''' END      
set @query += case when ISNULL(@BrandName,'''') = '''' then '''' else '' AND MB.ID IN (SELECT * from dbo.fnSplitString( ''+'' @BrandName ,'''',''''))'' END      
set @query += case when ISNULL(@CategoryName,'''') = '''' then '''' else '' AND PHL.ID IN (SELECT * from dbo.fnSplitString( ''+'' @CategoryName ,'''',''''))'' END      
set @query += case when ISNULL(@ManufName,'''') = '''' then '''' else '' AND Manuf.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ManufName ,'''',''''))'' END      
set @query += case when ISNULL(@ProductName,'''') = '''' then '''' else '' AND Product.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ProductName ,'''',''''))'' END    
EXEC sys.sp_executesql @query, N''@InventoryID int, @BranchName NVARCHAR(255), @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @InventoryID, @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @FromDate, @ToDate  
end',
N'[06] nocount';
GO
/****** uspRepInventoryAdjustmentHeader ******/
EXEC #Apply07 N'dbo.uspRepInventoryAdjustmentHeader', 0x0338B5B31C505A75DE6FA5F0BF8658C49561203289CA4EB7EA1C3218537DA55D, 0xD654606F22057044AAD1113F57E32682DC4DC28770B5387089E1276F34B41705, NULL, 0x667372357C1756DD7EA8CC7D84DD8485A85D21EBEC6957ADBD76009A370A3767, 0xC2500945D04FDB5C6BC6F9C25E08DA93A8F70E63F9FAE5FA4A598FD0D193A91B, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspRepInventoryAdjustmentHeader]      
@BranchName NVARCHAR(255) = '''',  @ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',      
@ProductName NVARCHAR(255)='''', @FromDate DATE = ''2025-09-01'', @ToDate DATE = ''2025-12-31''  
as  
SET NOCOUNT ON;
begin  
DECLARE @query NVARCHAR(MAX)      
set @query = ''SELECT InventHeader.InventoryID,InventHeader.DocID AS [Doc ID],    
format(InventoryDate,''''dd/MMM/yyyy'''') AS [Doc Date],MBO.Name [Branch Name],RefNo [Ref No],  
[dbo].[fnGetRoundedValue](SUM(invd.ActualQty - invd.OrgQty)) AS[Actual Qty Difference],    
[dbo].[fnGetRoundedValue](SUM(invd.ActualFreeQty - invd.OrgFreeQty)) AS[Actual Free Qty Difference],    
[dbo].[fnGetRoundedValue](SUM(invd.ActualDmgQty - invd.OrgDmgQty))AS[Actual Damage Qty Difference],    
[dbo].[fnGetRoundedValue](SUM((ActualPurPrice - OrgPurPrice) * ActualQty)) as [Actual Price Difference],    
[dbo].[fnGetRoundedValue](SUM((ActualPurPrice - OrgPurPrice) * ActualDmgQty)) as [Actual Damage Price Difference],    
[dbo].[fnGetRoundedValue](SUM((invd.ActualQty - invd.OrgQty) * ActualPurPrice)) [Final Diff Value],    
[dbo].[fnGetRoundedValue](SUM((invd.ActualDmgQty - invd.OrgDmgQty) * ActualPurPrice)) [Final Diff Damage Value],    
[dbo].[fnGetRoundedValue]((TotalAmt)) AS [Total Amount],s.Description Status,  
u.username as [User Name],convert(nvarchar,InventHeader.CDate) [Create Date],InventHeader.Remarks,Narration    
FROM tblInventoryHeader AS InventHeader   
JOIN tblInventoryDetail as invd ON invd.InventoryID=InventHeader.InventoryID    
JOIN tblMasterBranchOffice MBO ON MBO.ID = InventHeader.BranchID  
JOIN tblUsers as u ON u.ID = InventHeader.CBy    
LEFT JOIN tblUsers as us ON us.ID = InventHeader.MBy    
LEFT JOIN tblStatus as s ON s.ID = InventHeader.Status    
JOIN tblMasterProduct AS Prod ON Prod.ID = invd.ProdId      
JOIN tblMasterBrand MB ON MB.ID = Prod.BrandID      
JOIN tblMasterCategory PHL ON PHL.ID = Prod.CategoryID          
JOIN tblMasterManufacturer AS Manuf ON Manuf.ID = Prod.MfrID   
WHERE InventHeader.TransID = 13 ''  
SET @query = @query  + (CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (InventHeader.InventoryDate BETWEEN  @FromDate  AND  @ToDate )'' END)        
            
set @query += case when ISNULL(@BranchName,0) = 0 then '''' else '' AND InventHeader.BranchID = ''+'' @BranchName ''+'''' END      
set @query += case when ISNULL(@BrandName,'''') = '''' then '''' else '' AND MB.ID IN (SELECT * from dbo.fnSplitString( ''+'' @BrandName ,'''',''''))'' END      
set @query += case when ISNULL(@CategoryName,'''') = '''' then '''' else '' AND PHL.ID IN (SELECT * from dbo.fnSplitString( ''+'' @CategoryName ,'''',''''))'' END      
set @query += case when ISNULL(@ManufName,'''') = '''' then '''' else '' AND Manuf.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ManufName ,'''',''''))'' END      
set @query += case when ISNULL(@ProductName,'''') = '''' then '''' else '' AND Prod.ID IN (SELECT * from dbo.fnSplitString( ''+'' @ProductName ,'''',''''))'' END      
 set @query += ''  
GROUP BY InventHeader.InventoryID,TotalAmt,    
InventHeader.DocID,InventoryDate,s.Description,u.username,InventHeader.CDate,MBO.Name,InventHeader.Remarks,Narration,RefNo  
ORDER BY InventHeader.DocID asc  ''  
EXEC sys.sp_executesql @query, N''@BranchName NVARCHAR(255), @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @FromDate, @ToDate   
end',
N'[06] nocount';
GO
/****** uspRepInventoryConversionDetail ******/
EXEC #Apply07 N'dbo.uspRepInventoryConversionDetail', 0xF97898BD1294828CEC3EB971291D977F40AC95EBA4B036E93873F6B2A1F1846A, NULL, NULL, 0x228CB753FD78C70BE123FED6B5B03EA8C1B55D0FFBE80958CF7F1B2B8FD637A4, 0x86789DC77B5FF419712405C18BB77A48B9D958D12A2B839A526FAD887901B6BD, NULL,
N'--uspRepInventoryConversionDetail ''42''
ALTER PROCEDURE [dbo].[uspRepInventoryConversionDetail]

@ID INT

AS   
SET NOCOUNT ON;
BEGIN  
DECLARE @ConvType INT
SET @ConvType = (SELECT ConvertionTypeId FROM tblInventoryHeader WHERE InventoryID=@ID)
SELECT
SRIRAM.InventoryID,SRIRAM.[Product Code],SRIRAM.[Product Name],SRIRAM.EAN,
[dbo].[fnGetRoundedValue](isnull(SRIRAM.[Purchase Price] ,0)) AS [Purchase Price],
ISNULL(SUM(CONVERT(DECIMAL(25,6), SRIRAM.[Sales Qty])), 0) AS [Saleble Qty],
ISNULL(SUM(CONVERT(DECIMAL(25,6), SRIRAM.[Free Qty])), 0) AS [Free Qty],
ISNULL(SUM(CONVERT(DECIMAL(25,6), SRIRAM.[Damage Qty])), 0) AS [Damage Qty],
[dbo].[fnGetRoundedValue](isnull(SUM(CONVERT(DECIMAL (25,6),SRIRAM.[Gross Amount])),0)) AS [Gross Amount],
SRIRAM.Reason
FROM
(SELECT InvDetail.InventoryID,TMP.Code AS [Product Code] ,TMP.Name AS [Product Name], TMP.EAN AS [EAN],
[dbo].[fnGetRoundedValue]((InvDetail.OrgSalePrice)) AS [Purchase Price],
(CASE
WHEN ISNULL(@ConvType,0) IN (1,2,7) AND ISNULL(NewBatchID,0)!=0 THEN (OrgSaleQty * -1)
WHEN ISNULL(@ConvType,0) IN (3,5) AND ISNULL(NewBatchID,0)!=0 THEN (OrgSaleQty)
END) AS [Sales Qty],
(CASE
WHEN ISNULL(@ConvType,0) IN (3,4) AND ISNULL(NewBatchID,0)!=0 THEN (OrgSaleQty * -1)
WHEN ISNULL(@ConvType,0) IN (1,6) AND ISNULL(NewBatchID,0)!=0 THEN (OrgSaleQty)
END) AS [Free Qty],
(CASE
WHEN ISNULL(@ConvType,0) IN (5,6) AND ISNULL(NewBatchID,0)!=0 THEN (OrgSaleQty * -1)
WHEN ISNULL(@ConvType,0) IN (2,4) AND ISNULL(NewBatchID,0)!=0 THEN (OrgSaleQty)
END) AS [Damage Qty],
(CASE WHEN ISNULL(NewBatchID,0)!=0 THEN InvDetail.GrossAmt END) AS [Gross Amount],
MR.Name AS [Reason]
FROM tblInventoryDetail AS InvDetail
LEFT JOIN tblMasterProduct AS TMP ON InvDetail.ProdID = TMP.ID
LEFT JOIN tblMasterReason as MR ON MR.ID=InvDetail.ReasonId
WHERE InvDetail.InventoryID=@ID
) AS SRIRAM
GROUP BY SRIRAM.InventoryID,SRIRAM.[Product Code],SRIRAM.[Product Name],SRIRAM.EAN,
SRIRAM.Reason,SRIRAM.[Purchase Price]
ORDER BY SRIRAM.InventoryID
END',
N'[export] nocount';
GO
/****** uspRepInventoryConversionHeader ******/
EXEC #Apply07 N'dbo.uspRepInventoryConversionHeader', 0x329CD7139B316567EAAC01D170BAA984E6BE7C7B47A71BE4515386DD18C4FD83, NULL, NULL, 0x17D61CB2E91BECDF33899CFC4BBBFD4BC53DE6952367BB1C090DC76797688FBE, 0x7A2F8F57812BC62BDE9C1325AA35A2E9684898A79255D0632343F911BB4E272C, NULL,
N'--uspRepInventoryConversionHeader ''4'','''',''2024-01-01'',''2026-02-28''    
ALTER PROCEDURE [dbo].[uspRepInventoryConversionHeader]    
    
@ProductName NVARCHAR(100) = '''',      
@BranchName INT,      
@FromDate DATE = ''2025-01-01'',      
@ToDate   DATE = ''2025-12-20''      
    
AS    
SET NOCOUNT ON;
BEGIN    
    
SELECT IH.InventoryID,    
IH.DocID AS [DOC ID],FORMAT(IH.InventoryDate,''dd/MMM/yyyy'') AS [Inventory Date],IH.RefNo[Ref No],ct.ConvertionType AS [Convertion Type],    
dbo.fnGetRoundedValue(SUM(TID.GrossAmt)) GrossAmt ,CU.UserName AS [Created By],  CONVERT(NVARCHAR,IH.CDate) AS [Created Date],s.Description[Status]    
,IH.Remarks[Remarks], IH.Narration[Narration]    
    
FROM  tblInventoryHeader AS IH    
left join tblInventoryDetail AS TID on IH.InventoryID = TID.InventoryID    
JOIN tblDocumentSeries AS Doc on IH.TransID=Doc.TransID    
LEFT JOIN tblStatus as s ON s.ID = IH.Status    
JOIN tblMasterProduct MP ON MP.ID = TID.ProdID     
JOIN tblMasterBranchOffice MB on MB.ID = IH.BranchID     
JOIN tblInventoryDetail as invd ON invd.InventoryID=IH.InventoryID    
JOIN tblUsers as u ON u.ID = IH.CBy    
LEFT JOIN tblUsers as us ON us.ID = IH.MBy    
JOIN tblUsers CU  ON CU.ID = IH.CBy          
LEFT JOIN tblUsers MU  ON MU.ID = IH.MBy      
left join tblConvertionType as ct on ct.ConvertionTypeId=IH.ConvertionTypeId    
WHERE IH.TransID=22 AND (IH.InventoryDate BETWEEN @FromDate AND @ToDate)    
AND (isnull(@ProductName,'''') = '''' OR MP.ID IN ( SELECT * from dbo.fnSplitString( @ProductName,'','')))          
AND (@BranchName = 0 OR MB.ID = @BranchName)     
GROUP BY  IH.InventoryID,CU.UserName, IH.CDate,    
IH.DocID,ct.ConvertionType,InventoryDate,IH.RefNo,s.Description,IH.Remarks, IH.Narration ORDER BY IH.InventoryID asc    
END',
N'[export] nocount';
GO
/****** uspRepInvoiceCollectionDetail ******/
EXEC #Apply07 N'dbo.uspRepInvoiceCollectionDetail', 0x9830B91F9D19FAADFE8E82E854AC7F7163F00E3B47F441EE7AD453173681B8A9, NULL, NULL, 0xB7C42BCACC8C8B4A92444AE3E5F870380D1555AFE03F9E63A519073FC7D15C6D, 0x94AAFE89DFA736F2E279F1A4E871DE6C8DE0E72F9205F7BBE32EA60530EBE1E0, NULL,
N'ALTER PROCEDURE [dbo].[uspRepInvoiceCollectionDetail]  
@ID  INT,  
@DocPrefix INT  
AS   
SET NOCOUNT ON;
BEGIN  
  
SELECT   
CH.DocID[Doc ID],FORMAT(Ch.ColDate,''dd/MMM/yyyy'')[DocDate], CH.ColDocRefNo[Ref No],dbo.fnGetRoundedValue(SUM(CD.TotalAmtAdj))[Total Amount Adjusted], 
dbo.fnGetRoundedValue(SUM(CD.DiscAmt))[Collection Discount],
U.UserName[Collected User], PM.PaymentMode[Payment Mode],CMM.ModeName[BT Mode],MBA.AccountName [Bank A/c No],CP.[Cheque/DD Number],  
 CP.NeftID [NEFT],FORMAT(CP.Date,''dd/MMM/yyyy'')[Payment Date],dbo.fnGetRoundedValue(CP.PayAt)[Pay At],CP.IfscCode[IFSC],Cp.BankName[Bank Name],  
 CP.BranchName[Branch Name]  
  
  
FROM tblTranCollectionHeader CH  
JOIN tblTranCollectionDetail CD on CD.ColID = CH.ColID  
JOIN tblUsers U on U.ID = CH.CBy  
JOIN tblCollPMDetails  CP ON CP.ColID = CH.ColID  
LEFT JOIN tblMasterBankAccount MBA ON MBA.FAID = CP.BankAccID  
JOIN tblPaymentMode PM on PM.ID = CH.ColMode  
LEFT JOIN tblContraMode CMM on CMM.ID = CH.BTMode  
WHERE CD.DocID = @ID AND CH.STATUS IN (1,3,5) and CD.DocPrefix = @DocPrefix  
  
GROUP BY  
    CH.DocID,  
    CH.ColDate,  
    CH.ColDocRefNo,  
    U.UserName,  
    PM.PaymentMode,  
    CMM.ModeName,  
    MBA.AccountName,  
    CP.[Cheque/DD Number],  
    CP.NeftID,  
    CP.Date,  
    CP.PayAt,  
    CP.IfscCode,  
    CP.BankName,  
    CP.BranchName;  
  
END',
N'[export] nocount';
GO
/****** uspRepInvoiceOS ******/
EXEC #Apply07 N'dbo.uspRepInvoiceOS', 0x0EA1B4BD539E2898616513A3587A8DDCB879697D9CA6154E44EC049B42F73193, 0xE19DE023597C7BE3DDE894B6C81E7EC2DD5DA38FE21DB1C9532D026A445EE1EA, NULL, 0x3E35DBC859DDF16F7353646E066BB8C2DC6772186E78846E8B3B046E5A50CBEA, 0xBDAC452635FCE2735AAD4686B934792C5892BDA3691D34BECBC02B545E20AEA1, NULL,
N'--uspRepInvoiceOS '''','''',''DHANYANTH'',''2025-03-25''            
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspRepInvoiceOS]            
@BeatName nvarchar(max) = null,@SalesmanName nvarchar(max) = null,@CustomerName nvarchar(max) = null,@AsonDate date = null              
as                  
SET NOCOUNT ON;
BEGIN                  
DECLARE @strQuery NVARCHAR(MAX) = ''''            
create table #temp([Doc ID] nvarchar(255),[Doc Date] nvarchar(255),[Ref No] nvarchar(255),[Beat Name] nvarchar(255),          
[Salesman Name] nvarchar(255),[Customer Name] nvarchar(255),[Net Amount] decimal(25,2),[Balance] decimal(25,2),Ageing int,[Assigned Invoice Count] int)          
SET @strQuery = ''SELECT DocID [Doc ID],CONVERT(nvarchar(50),InvDate,103) [Doc Date],DocRef [Ref No],MB.Name [Beat Name],SM.Name [Salesman Name],            
MC.Name [Customer Name],case when DocPrefix = 15 THEN dbo.fnGetRoundedValue(SH.NetAmt) ELSE dbo.fnGetRoundedValue(SH.NetAmt * -1) END [Net Amount],            
case when DocPrefix = 15 THEN dbo.fnGetRoundedValue(SH.Balance) ELSE dbo.fnGetRoundedValue(SH.Balance * -1) END [Balance],        
DATEDIFF(DD,InvDate,GETDATE()) Ageing,        
(select count(*) from tblAssignInvoicesDETAIL AD JOIN tblAssignInvoicesHeader AH ON AH.ID = AD.HID AND AH.Status IN (1,3,5)         
where AD.InvID = SH.ID) [Assigned Invoice Count]        
FROM tblTranSalesHeader SH            
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID            
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID            
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesManID            
  WHERE SH.Status in (1,3,6,7) and SH.InvDate <=  '' +'' @AsonDate ''            
SET @strQuery += CASE WHEN ISNULL(@BeatName,'''') = '''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString(''+'' @BeatName ,'''',''''))'' END                
SET @strQuery += CASE WHEN ISNULL(@SalesmanName,'''') = '''' THEN '''' ELSE '' AND SM.ID  IN (SELECT * from dbo.fnSplitString(''+'' @SalesmanName ,'''',''''))'' END               
SET @strQuery += CASE WHEN ISNULL(@CustomerName,'''') = '''' THEN '''' ELSE '' AND MC.ID  IN (SELECT * from dbo.fnSplitString(''+'' @CustomerName ,'''',''''))'' END                  
SET @strQuery += '' ORDER BY InvDate,DocValue''            
insert into #temp          
EXEC sys.sp_executesql @strQuery, N''@BeatName nvarchar(max), @SalesmanName nvarchar(max), @CustomerName nvarchar(max), @AsonDate date'', @BeatName, @SalesmanName, @CustomerName, @AsonDate            
      
select [Doc ID],[Doc Date],[Ref No],[Beat Name],[Salesman Name],[Customer Name],  
dbo.fnGetRoundedValue([Net Amount]) [Net Amount],dbo.fnGetRoundedValue([Balance]) [Balance],Ageing,[Assigned Invoice Count] from #temp  
        
drop table #temp          
END',
N'[06] nocount';
GO
/****** uspRepInvoiceWiseCollectionHeader ******/
EXEC #Apply07 N'dbo.uspRepInvoiceWiseCollectionHeader', 0x4751B043D8609E389787CEB918D676F4853F329E64B98114E73F9CC5DBE7C33C, NULL, NULL, 0x1265FA2322018584AEC4B31BEC18188966F5FAC7B08E890E19FD54DABBA5B486, 0x8B45C73FF7A040D39226DFD7EE22094060F4016E9B3B24A904D4ED871EC8AC0E, NULL,
N'ALTER PROCEDURE [dbo].[uspRepInvoiceWiseCollectionHeader]      
  
@BranchName INT ,        
@BeatName NVARCHAR(255) = '''',      
@SalesmanName NVARCHAR(255) = '''',      
@CustomerName NVARCHAR(255) = '''',       
@CustomerType NVARCHAR(255) = '''',      
@DocRange NVARCHAR(MAX) = '''',      
@FromDate DATE = ''2024-08-01'',      
@ToDate DATE = ''2026-08-30''         
AS      
SET NOCOUNT ON;
BEGIN      
      
select       
SH.ID[ID],SH.DocPrefix[Doc Prefix],SH.DocID[DOC ID],      
FORMAT(SH.InvDate,''dd/MMM/yyyy'')[Doc Date],SH.DocRef[Ref No],Mb.Name[Beat Name],MS.Name[Salesman Name],MC.Name[Customer Name],     
MBO.Name[Branch Name],MCT.Name[Customer Type], dbo.fnGetRoundedValue(SH.TotalDiscountAmt)[Total Discount Amount],dbo.fnGetRoundedValue(CD.DiscAmt)[Collection Discount],dbo.fnGetRoundedValue( SH.NetAmt)[Net Amount],dbo.fnGetRoundedValue(SH.Balance)[Balance
  
],U.UserName[User Name]      
      
FROM tblTranSalesHeader SH      
LEFT JOIN tblMasterBeat MB on MB.ID = Sh.BeatID      
LEFt JOIN tblMasterSalesman MS on MS.ID = SH.SalesManID      
LEFT JOIN tblTranCollectionDetail CD on CD.DocID = SH.ID     
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = SH.BranchID    
JOIN tblMasterCustomer MC on MC.ID = SH.CustID      
LEFT JOIN tblMasterCustomerType MCT on MCT.ID = MC.CustomerType      
Join tblUsers U on U.ID = SH.CBy      
WHERE SH.DocPrefix = 15 and SH.Status IN (1,3,5)      
    AND SH.InvDate BETWEEN @FromDate AND @ToDate        
    AND (        
        @DocRange = ''''         
        OR SH.DocValue IN (SELECT DocValue FROM dbo.SplitDocRange(@DocRange))        
    )      
    AND (@CustomerName = '''' OR MC.ID IN (SELECT * from dbo.fnSplitString( @CustomerName,'','')))      
    AND (@CustomerType = '''' OR MCT.ID IN (SELECT * from dbo.fnSplitString( @CustomerType,'','')))      
    AND (@BranchName = 0 OR MBO.ID = @BranchName)    
    AND (@BeatName = '''' OR MB.ID IN (SELECT * from dbo.fnSplitString( @BeatName,'','')))        
    AND (@SalesmanName = '''' OR MS.ID IN (SELECT * from dbo.fnSplitString( @SalesmanName,'','')))       
END',
N'[export] nocount';
GO
/****** uspRepInvoiceWiseMarginDetail ******/
EXEC #Apply07 N'dbo.uspRepInvoiceWiseMarginDetail', 0x85A15B5152B1998351B471EFF908C768B55E767802C113B7CBD54D1434B5A9DE, NULL, NULL, 0x60C667E387DDBFBA50AE55F4C2A3A4C662C779C455A33A4B90E4AD41C879013A, 0x4FA6B22DECB9361CB0A7AAE6263174BC6EFBA1608E326D14609211020B04393F, NULL,
N'--uspRepInvoiceWiseMarginDetail 10,''2018-08-18'',''2026-08-18'',2
ALTER PROCEDURE [dbo].[uspRepInvoiceWiseMarginDetail]

@ID INT ,
@Fromdate DATE,
@ToDate DATE ,
@GNAmount INT

AS
SET NOCOUNT ON;
BEGIN
IF(@GNAmount = 1)  --GrossAmount
BEGIN

create table #temp(docid nvarchar(255),InvDate NVARCHAR(255),Code NVARCHAR(255),Name NVARCHAR(255),EAN NVARCHAR(255),
PurchaseValue DECIMAL(25,6), SalesValue DECIMAL(25,6))
INSERT INTO #temp

SELECT SH.DocID[Invoice ID],FORMAT(SH.InvDate,''dd/MMM/yyyy'')[Invoice Date],MP.Code[Product Code],MP.Name[Product Name],MP.EAN[EAN],
dbo.fnGetRoundedValue((CASE WHEN ISNULL(SD.InventoryId,0) = 0 THEN (MP.PurchasePrice / MP.PurchaseCR) 
ELSE Inv.PurchasePrice END) * SD.UomQty) AS [PurchaseValue]
,dbo.fnGetRoundedValue(SD.GrossAmt) AS [SalesValue]

FROM tblTranSalesDetail AS SD
LEFT JOIN tblMasterProduct AS MP ON MP.ID = SD.ProdId
LEFT JOIN tblProductInventory AS Inv ON Inv.InventoryId = SD.InventoryId
LEFT JOIN tblTranSalesHeader AS SH ON SH.ID = SD.InvID
WHERE SH.InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix =15 AND SH.Status IN(1,3,5) AND SD.NetAmt > 0
AND SD.InvId = @ID

SELECT docid as [Invoice ID],InvDate as [Invoice Date],Code as [Product Code],NAME as [Product Name],EAN,
dbo.fnGetRoundedValue(isnull(PurchaseValue,0)) as [Purchase Price],dbo.fnGetRoundedValue(isnull(SalesValue,0)) as [Sales Price],
dbo.fnGetRoundedValue(isnull((SalesValue-PurchaseValue),0)) as [Margin Amount],
dbo.fnGetRoundedValue(isnull(((SalesValue-PurchaseValue) / NULLIF(PurchaseValue,0)) * 100 ,0)) as [Margin %] FROM #temp
DROP TABLE #temp
END

ELSE IF (@GNAmount = 2)
BEGIN

create table #temp1(docid nvarchar(255),InvDate NVARCHAR(255), Code NVARCHAR(255),Name NVARCHAR(255),EAN NVARCHAR(255),
PurchaseValue DECIMAL(25,6), SalesValue DECIMAL(25,6))
INSERT INTO #temp1

SELECT SH.DocID[Invoice ID],FORMAT(SH.InvDate,''dd/MMM/yyyy'')[Invoice Date],MP.Code[Product Code],MP.Name[Product Name],MP.EAN[EAN],
dbo.fnGetRoundedValue((CASE WHEN ISNULL(SD.InventoryId,0) = 0 THEN (MP.PurchasePrice / MP.PurchaseCR) 
ELSE Inv.PurchasePrice END) * SD.UomQty) AS [PurchaseValue]
,dbo.fnGetRoundedValue(SD.NetAmt) AS [SalesValue]

FROM tblTranSalesDetail AS SD
LEFT JOIN tblMasterProduct AS MP ON MP.ID = SD.ProdId
LEFT JOIN tblProductInventory AS Inv ON Inv.InventoryId = SD.InventoryId
LEFT JOIN tblTranSalesHeader AS SH ON SH.ID = SD.InvID
WHERE SH.InvDate BETWEEN @FromDate AND @ToDate AND DocPrefix =15 AND SH.Status IN(1,3,5) AND SD.NetAmt > 0
AND SD.InvId = @ID

SELECT docid as [Invoice ID],InvDate as [Invoice Date],Code as [Product Code],NAME as [Product Name],EAN,
dbo.fnGetRoundedValue(isnull(PurchaseValue,0)) as [Purchase Price],dbo.fnGetRoundedValue(isnull(SalesValue,0)) as [Sales Price],
dbo.fnGetRoundedValue(isnull((SalesValue-PurchaseValue),0)) as [Margin Amount],
dbo.fnGetRoundedValue(isnull(((SalesValue-PurchaseValue) / NULLIF(PurchaseValue,0)) * 100 ,0)) as [Margin %] FROM #temp1
DROP TABLE #temp1
END
END',
N'[export] nocount';
GO
/****** uspRepInvoiceWiseMarginHeader ******/
EXEC #Apply07 N'dbo.uspRepInvoiceWiseMarginHeader', 0xC52E7E6DF1BAC7B50FE6A922AFCD189610479EFE2BB65D7940D8563482F4C6A8, NULL, NULL, 0xF9E62365D6403E70E7084B6F5566255CFD0CE0DA9BEC53FD586B039ABF79CFFB, 0x5427F0242170530CDF74B3308FDEAE1DF3191545E083975C94C77E4EB9D19B09, NULL,
N'--uspRepInvoiceWiseMarginHeader '''','''','''','''',''2019-06-26'',''2026-09-26'' ,2    
ALTER PROCEDURE [dbo].[uspRepInvoiceWiseMarginHeader]    
@BranchName INT,    
@BeatName NVARCHAR(255) = '''',      
@SalesmanName NVARCHAR(255) = '''',      
@CustomerName NVARCHAR(255) = '''',       
@FromDate DATE = ''2024-08-01'',      
@ToDate DATE = ''2026-08-30'',    
@Type INT    
    
AS     
SET NOCOUNT ON;
BEGIN    
    
IF (@Type = 1)    
BEGIN    
create table #temp(ID INT,docid nvarchar(255),InvDate NVARCHAR(255),BranchName NVARCHAR(255),Customername nvarchar(255),    
Beatname nvarchar(255),salemanname nvarchar(255),netamount decimal(25,6),purchaseprice decimal (25,6),salesprice decimal(25,6))    
insert into #temp    
    
SELECT SH.ID[ID],SH.DocID[Invoice ID],FORMAT(SH.InvDate,''dd/MMM/yyyy'')[Invoice Date],MBO.Name[Branch Name],MC.Name[Customer Name],    
MB.Name[Beat Name],MS.Name[Salesman Name],SH.GrossAmt[Selected Amount],    
((CASE WHEN ISNULL(SD.InventoryId,0) = 0 THEN (MP.PurchasePrice / MP.PurchaseCR)     
ELSE INV.PurchasePrice END) * SD.UomQty) AS [PurchasePrice],    
(SD.GrossAmt)    AS [SalesPrice]    
    
    
FROM tblTranSalesHeader SH    
LEFT JOIN tblTranSalesDetail AS SD ON SD.InvId = SH.ID    
JOIN tblMasterCustomer MC on MC.ID = SH.CustID    
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = SH.BranchID    
LEFT JOIN tblMasterBeat MB on MB.ID = Sh.BeatID    
LEFT JOIN tblMasterSalesman MS on MS.ID = SH.SalesManID    
LEFT JOIN tblMasterProduct MP on MP.ID = SD.ProdID    
LEFT JOIN tblProductInventory INV on INV.InventoryId = SD.InventoryID    
WHERE SH.InvDate BETWEEN @Fromdate AND @ToDate AND DocPrefix =15 AND SH.Status IN(1,3,5)    
AND ISNULL(SD.NetAmt,0) > 0    
AND (@BranchName = 0 OR @BranchName = MBO.ID)    
AND (@BeatName = '''' OR MB.ID IN (SELECT * from dbo.fnSplitString(@BeatName,'','')))    
AND (@SalesmanName = '''' OR MS.ID IN (SELECT * from dbo.fnSplitString(@SalesmanName,'','')))    
AND (@CustomerName = '''' OR MC.ID IN (SELECT * from dbo.fnSplitString(@CustomerName,'',''))) 
    
    
select ID,@Fromdate as [From],@ToDate as [To],@Type AS [GNAmount] ,docid as [Invoice ID],InvDate as [Invoice Date],BranchName as [Branch Name],Customername as [Customer Name],    
salemanname as [Salesman Name],Beatname as [Beat Name],    
dbo.fnGetRoundedValue(isnull(netamount,0)) as [Selected Amount],dbo.fnGetRoundedValue(isnull(sum(purchaseprice),0)) as [Purchase Price],    
dbo.fnGetRoundedValue(isnull((sum(salesprice)),0)) as [Sales Price],dbo.fnGetRoundedValue(isnull(sum(salesprice - purchaseprice),0)) as  [Margin Amount],    
dbo.fnGetRoundedValue(ISNULL(((sum(salesprice - purchaseprice) * 100)  / nullif(sum(purchaseprice),0)),0)) as [Margin %]  from #temp    
GROUP BY ID,docid,InvDate,BranchName,Customername ,netamount,salemanname,Beatname    
ORDER BY ID    
drop table #temp    
END    
    
ELSE IF (@Type = 2)    
BEGIN    
create table #temp1(ID INT,docid nvarchar(255),InvDate NVARCHAR(255),BranchName NVARCHAR(255),Customername nvarchar(255),    
Beatname nvarchar(255),salemanname nvarchar(255),netamount decimal(25,6),purchaseprice decimal (25,6),salesprice decimal(25,6))    
insert into #temp1    
    
SELECT SH.ID[ID],SH.DocID[Invoice ID],FORMAT(SH.InvDate,''dd/MMM/yyyy'')[Invoice Date],MBO.Name[Branch Name],MC.Name[Customer Name],    
MB.Name[Beat Name],MS.Name[Salesman Name],SH.NetAmt [Selected Amount],    
((CASE WHEN ISNULL(SD.InventoryId,0) = 0 THEN (MP.PurchasePrice / MP.PurchaseCR)     
ELSE INV.PurchasePrice END) * SD.UomQty) AS [PurchasePrice],    
(SD.NetAmt)    AS [SalesPrice]    
    
FROM tblTranSalesHeader SH    
LEFT JOIN tblTranSalesDetail AS SD ON SD.InvId = SH.ID    
JOIN tblMasterCustomer MC on MC.ID = SH.CustID    
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = SH.BranchID    
LEFT JOIN tblMasterBeat MB on MB.ID = Sh.BeatID    
LEFT JOIN tblMasterSalesman MS on MS.ID = SH.SalesManID    
LEFT JOIN tblMasterProduct MP on MP.ID = SD.ProdID    
LEFT JOIN tblProductInventory INV on INV.InventoryId = SD.InventoryID    
WHERE SH.InvDate BETWEEN @Fromdate AND @ToDate AND DocPrefix =15 AND SH.Status IN(1,3,5)    
AND ISNULL(SD.NetAmt,0) > 0    
AND (@BranchName = 0 OR @BranchName = MBO.ID)    
AND (@BeatName = '''' OR MB.ID IN (SELECT * from dbo.fnSplitString(@BeatName,'','')))    
AND (@SalesmanName = '''' OR MS.ID IN (SELECT * from dbo.fnSplitString(@SalesmanName,'','')))    
AND (@CustomerName = '''' OR MC.ID IN (SELECT * from dbo.fnSplitString(@CustomerName,'','')))    
    
    
select ID,@Fromdate as [From],@ToDate as [To],@Type AS [GNAmount] ,docid as [Invoice ID],InvDate as [Invoice Date],BranchName as [Branch Name],Customername as [Customer Name],    
salemanname as [Salesman Name],Beatname as [Beat Name],    
dbo.fnGetRoundedValue(isnull(netamount,0)) as [Selected Amount],dbo.fnGetRoundedValue(isnull(sum(purchaseprice),0)) as [Purchase Price],    
dbo.fnGetRoundedValue(isnull(sum(salesprice),0)) as [Sales Price],dbo.fnGetRoundedValue(isnull(sum(salesprice - purchaseprice),0)) as  [Margin Amount],    
dbo.fnGetRoundedValue(sum(salesprice - purchaseprice) / nullif(sum(purchaseprice),0) * 100) as [Margin %]  from #temp1    
GROUP BY ID,docid,InvDate,BranchName,Customername,netamount,salemanname,Beatname    
ORDER BY ID    
drop table #temp1    
END    
END',
N'[export] nocount';
GO
/****** uspRepItemLedger ******/
EXEC #Apply07 N'dbo.uspRepItemLedger', 0x76ADD1E75F60F4056EC91DA27A329CB0ADDF08E7BF0088EFB91A22A780CFFCBB, 0x1E8D04B0AB647E8C53AF7D7AEFF0ED176DEBC1C8E80CD1ADE3E73CB6346A75A4, NULL, 0x6511DE6C5CA524C020A4FFEF9A87EAAC2263E31BCCC9825C2C8C2C84FE3A87DC, 0x262EF40C0B80E6E2D12EA762CD959BA7C4A06137482BE6CD79F2B47A2153A902, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspRepItemLedger]   
@BranchName NVARCHAR(255) = ''0'',@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255) = '''',  
@FromDate DATE = ''2025-08-01'',@ToDate DATE = ''2025-08-30''     
as  
SET NOCOUNT ON;
begin  
declare @StrQuery nvarchar(max) = ''''    
 set @StrQuery = ''   
select PV.ProdID,MP.Code,MP.Name,MM.Name [Mfr Name],MB.Name [Brand Name],PHL.Name [Category Name], dbo.fnGetRoundedValue(ISNULL(SUM(RecdQty), 0)) AS [Recd Qty],  
       dbo.fnGetRoundedValue(ISNULL(SUM(RecdFreeQty), 0)) AS [Recd Free Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(RecdDmgQty), 0)) AS [Recd Dmg Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(PRQty), 0)) AS [PR Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(PRFreeQty), 0)) AS [PR Free Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(PRDmgQty), 0)) AS [PR Dmg Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(SRQty), 0)) AS [SR Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(SRFreeQty), 0)) AS [SR Free Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(SRDmgQty), 0)) AS [SR Dmg Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(InvoiceQty), 0)) AS [Invoice Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(InvoiceFreeQty), 0)) AS [Invoice Free Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(InvoiceDmgQty), 0)) AS [Invoice Dmg Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(InvenoryAdjQty), 0)) AS [Inventory Adj Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(InvenoryAdjFreeQty), 0)) AS [Inventory Adj Free Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(InvenoryAdjDmgQty), 0)) AS [Inventory Adj Dmg Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(InvenoryConvQty), 0) * -1) AS [Inventory Conv Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(InvenoryConvFreeQty), 0) * -1) AS [Inventory Conv Free Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(InvenoryConvDmgQty), 0) * -1) AS [Inventory Conv Dmg Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(ActualQty), 0)) AS [Actual Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(ActualFreeQty), 0)) AS [Actual Free Qty],  
        dbo.fnGetRoundedValue(ISNULL(SUM(ActualDmgQty), 0)) AS [Actual Dmg Qty],  
    PV.BatchNumber [Batch No],FORMAT(PV.PKDDate,''''dd-MMM-yyyy'''') [PKD Date],FORMAT(PV.ExpiryDate,''''dd-MMM-yyyy'''') [Expiry Date]  
 from tblproductinventory PV  
right JOIN tblMasterProduct MP ON MP.ID = PV.ProdID  
JOIN tblMasterManufacturer MM ON MM.ID=MP.MfrID      
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID    
JOIN tblMasterCategory PHL ON PHL.ID = MP.CategoryID where MP.ID > 0 ''  
SET @StrQuery = @StrQuery  +(CASE WHEN ISNULL(@FromDate,'''')='''' AND ISNULL(@ToDate,'''')='''' THEN '''' ELSE '' AND (PV.TransDate BETWEEN  @FromDate  AND  @ToDate )'' END)                 
   
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BranchName,''0'')=''0'' THEN '''' ELSE '' AND PV.BranchID =  @BranchName '' END)     
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ManufName,'''')='''' THEN '''' ELSE '' AND MM.ID IN (SELECT * from dbo.fnSplitString(  @ManufName ,'''',''''))'' END)         
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@BrandName,'''')='''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString(  @BrandName ,'''',''''))'' END)            
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@CategoryName,'''')='''' THEN '''' ELSE '' AND PHL.ID IN (SELECT * from dbo.fnSplitString(  @CategoryName ,'''',''''))'' END)     
SET @StrQuery = @StrQuery + (CASE WHEN ISNULL(@ProductName,'''')='''' THEN '''' ELSE '' AND MP.ID IN (SELECT * from dbo.fnSplitString(  @ProductName ,'''',''''))'' END)   
SET @StrQuery = @StrQuery +  '' GROUP BY PV.ProdID,MP.Code,MP.Name,MM.Name,MB.Name,PHL.Name,PV.BatchNumber,PV.PKDDate,PV.ExpiryDate ''  
EXEC sys.sp_executesql @StrQuery, N''@BranchName NVARCHAR(255), @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @FromDate DATE, @ToDate DATE'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @FromDate, @ToDate  
end',
N'[06] nocount';
GO
/****** uspRepItemLedgerDetail ******/
EXEC #Apply07 N'dbo.uspRepItemLedgerDetail', 0x18E2346DA9908166F470328BEC4BC35A87E092C57DD9DD6AB28397923683A644, NULL, NULL, 0x940259D277B3B2E3D759015EB9A47EC13CDBDB7AEBE73540E420676632289A59, 0xDC6E43DE52A5A21A53516939CF8B3E14E5CE6D1C419A3B608030D1B8668D0AF4, NULL,
N'-- [uspStockLedgerDetail] 286,''03/11/2021'',''03/11/2021''        
ALTER PROC [dbo].[uspRepItemLedgerDetail]                  
@ProdID INT = 123,@BranchName NVARCHAR(255) = ''0'',@ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',@ProductName NVARCHAR(255) = '''',    
@FromDate DATE = ''2025-08-01'',@ToDate DATE = ''2025-08-30''     
AS            
SET NOCOUNT ON;
BEGIN            
SET DATEFORMAT dmy;                  
SELECT [Product Code],[Product Name],[Doc ID],[Doc Date],[Ref No],[Branch Name],TransType [Trans Type],dbo.fnGetRoundedValue(SUM([Qty])) [Qty] FROM (          
SELECT MP.Code [Product Code],MP.Name [Product Name],BILLH.DocId [Doc ID],FORMAT(BILLH.Date,''dd-MMM-yyyy'') [Doc Date],BILLH.RefNo [Ref No],BILLH.UDFDocId [UDN],
DS.TransName TransType,     
case when BILLH.TransID = 1 then ISNULL(SUM(AdjQty),0) else ISNULL(SUM(-AdjQty),0) end AS [Qty],MBO.Name [Branch Name]
FROM tblTransPurchaseDetail AS BILL                                      
JOIN tblTransPurchaseHeader AS BILLH ON BILL.HID=BILLH.ID    
join tblMasterBranchOffice MBO ON MBO.ID = BILLH.BranchID    
join tblMasterProduct MP on MP.ID = BILL.ProdID
join tblDocumentSeries DS ON DS.TransID = BILLH.TransID
WHERE BILL.ProdID=@ProdID AND BILLH.Date BETWEEN @FromDate AND @ToDate AND Status IN (1,3,5,6) AND     
BILLH.BranchID = (CASE WHEN ISNULL(@BranchName,''0'') = ''0'' THEN BILLH.BranchID ELSE @BranchName END)    
group by  BILLH.DocId,BILLH.Date,BILLH.RefNo,BILLH.UDFDocId,BILLH.TransID,MBO.Name,MP.Code, MP.Name,DS.TransName         
UNION ALL          
-- Get Sales Stock                                      
SELECT MP.Code [Product Code],MP.Name [Product Name],SaleH.DocId [Doc ID],FORMAT(SaleH.InvDate,''dd-MMM-yyyy'') [Doc Date],SaleH.DocRef [Ref No],SaleH.UDFDocId [UDN],
''Invoice'' TransType,    
ISNULL(SUM(-AdjustQty),0)AS [SaleQty],MBO.Name [Branch Name]          
FROM tblTranSalesDetail AS Sale                                      
JOIN tblTranSalesHeader AS SaleH ON Sale.InvId=SaleH.ID           
join tblMasterBranchOffice MBO ON MBO.ID = SaleH.BranchID    
join tblMasterProduct MP on MP.ID = Sale.ProdID  
WHERE Sale.ProdID=@ProdID AND SaleH.InvDate BETWEEN @FromDate AND @ToDate AND Status IN (1,3,5) AND DocPrefix = 15 AND     
SaleH.BranchID = (CASE WHEN ISNULL(@BranchName,''0'') = ''0'' THEN SaleH.BranchID ELSE @BranchName END)         
GROUP BY SaleH.DocId,SaleH.InvDate,SaleH.DocRef,SaleH.UDFDocId,MBO.Name,MP.Code, MP.Name           
UNION ALL          
-- GET Sales Return Stock                                      
SELECT MP.Code [Product Code],MP.Name [Product Name],SaleH.DocId [Doc ID],FORMAT(SaleH.InvDate,''dd-MMM-yyyy'') [Doc Date],SaleH.DocRef [Ref No],SaleH.UDFDocId [UDN],
''Sales Return'' TransType,    
ISNULL(SUM(AdjustQty),0)AS [SRQty],MBO.Name [Branch Name]           
FROM tblTranSalesDetail AS Sale                                      
JOIN tblTranSalesHeader AS SaleH ON Sale.InvId=SaleH.ID    
join tblMasterBranchOffice MBO ON MBO.ID = SaleH.BranchID    
join tblMasterProduct MP on MP.ID = Sale.ProdID  
WHERE Sale.ProdID=@ProdID AND DocPrefix=16 AND SaleH.InvDate BETWEEN @FromDate AND @ToDate AND Status IN (3,5,6) AND SaleH.TransactionType = 2 AND     
SaleH.BranchID = (CASE WHEN ISNULL(@BranchName,''0'') = ''0'' THEN SaleH.BranchID ELSE @BranchName END)    
group by SaleH.DocId,SaleH.InvDate,SaleH.DocRef,SaleH.UDFDocId,MBO.Name,MP.Code, MP.Name           
UNION ALL          
-- GET Sales Return Stock                                      
SELECT MP.Code [Product Code],MP.Name [Product Name],SaleH.DocId [Doc ID],FORMAT(SaleH.InvDate,''dd-MMM-yyyy'') [Doc Date],SaleH.DocRef [Ref No],SaleH.UDFDocId [UDN],''Damage Return'' TransType,    
ISNULL(SUM(AdjustQty),0)AS [SRQty],MBO.Name [Branch Name]           
FROM tblTranSalesDetail AS Sale                                      
JOIN tblTranSalesHeader AS SaleH ON Sale.InvId=SaleH.ID    
join tblMasterBranchOffice MBO ON MBO.ID = SaleH.BranchID  
join tblMasterProduct MP on MP.ID = Sale.ProdID  
WHERE Sale.ProdID=@ProdID AND DocPrefix=16 AND SaleH.InvDate BETWEEN @FromDate AND @ToDate AND Status IN (3,5,6,7) AND SaleH.TransactionType = 3 AND     
SaleH.BranchID = (CASE WHEN ISNULL(@BranchName,''0'') = ''0'' THEN SaleH.BranchID ELSE @BranchName END)                              
AND QtyType = 1                  
group by SaleH.DocId,SaleH.InvDate,SaleH.DocRef,SaleH.UDFDocId,MBO.Name,MP.Code, MP.Name        
-- GET Inventory Adjustment Stock                                      
union all          
SELECT MP.Code [Product Code],MP.Name [Product Name],InvH.DocID [Doc ID],FORMAT(InvH.InventoryDate,''dd-MMM-yyyy'') [Doc Date],'''' [Ref No],InvH.UDFDocId [UDN],''Inv Adjustment'' TransType,    
ISNULL(SUM(ActualQty - OrgQty),0)AS [AdjQty],MBO.Name [Branch Name]           
FROM tblInventoryDetail AS Inv           
JOIN tblInventoryHeader AS InvH ON Inv.InventoryID=InvH.InventoryID    
join tblMasterBranchOffice MBO ON MBO.ID = InvH.BranchID    
join tblMasterProduct MP on MP.ID = Inv.ProdID  
WHERE Inv.ProdID=@ProdID AND TransID=13 AND InvH.InventoryDate BETWEEN @FromDate AND @ToDate AND Status = 1 AND     
InvH.BranchID = (CASE WHEN ISNULL(@BranchName,''0'') = ''0'' THEN InvH.BranchID ELSE @BranchName END)               
group by InvH.DocID,InvH.InventoryDate,InvH.UDFDocId,MBO.Name,MP.Code, MP.Name                              
union all          
-- GET Inventory Conversion Stock                              
(SELECT [Product Code],[Product Name],[Doc ID],FORMAT([Doc Date],''dd-MMM-yyyy'')[Doc Date],[Ref No],[UDN],''Inv Conversion'' TransType,SUM(SRI.ConQty) AS [Conversion Qty],[Branch Name] FROM                              
(                              
SELECT MP.Code [Product Code],MP.Name [Product Name],InvH.DocID [Doc ID],InvH.InventoryDate [Doc Date],'''' [Ref No],InvH.UDFDocId [UDN],InvH.ConvertionTypeId,                         
(CASE                              
WHEN InvH.ConvertionTypeId IN (3,5) THEN OrgSaleQty                              
WHEN InvH.ConvertionTypeId IN (1,2,7) THEN ''-''+ CONVERT(NVARCHAR,OrgSaleQty)                            
END) AS [ConQty],MBO.Name [Branch Name] FROM tblInventoryDetail AS Inv                              
JOIN tblInventoryHeader AS InvH ON Inv.InventoryID=InvH.InventoryID     
join tblMasterBranchOffice MBO ON MBO.ID = InvH.BranchID    
join tblMasterProduct MP on MP.ID = Inv.ProdID  
WHERE Inv.ProdID=@ProdID AND TransID=22 AND InvH.InventoryDate BETWEEN @FromDate AND @ToDate AND Status = 1 AND     
InvH.BranchID = (CASE WHEN ISNULL(@BranchName,''0'') = ''0'' THEN InvH.BranchID ELSE @BranchName END)                       
AND ISNULL(Inv.NewBatchID,'''')!='''' AND InvH.ConvertionTypeId IN (1,2,3,5,7)          
--group by InvH.DocID,InvH.InventoryDate,InvH.UDFDocId ,InvH.ConvertionTypeId          
) AS SRI group by[Doc ID],[Doc Date],[Ref No],[UDN],[Branch Name],[Product Code],[Product Name])                                    
) AS MAINDATA          
GROUP BY [Doc ID],[Doc Date],UDN,[Ref No],TransType,[Branch Name],[Product Code],[Product Name]         
END',
N'[export] nocount';
GO
/****** uspRepItemwiseclosingstockheader ******/
EXEC #Apply07 N'dbo.uspRepItemwiseclosingstockheader', 0xA0CDD661BF7940C51F25B5B9ECA8DF0671317A02A167455EA7C0A0F1261F1F18, 0x4421D4605498BF8505B5D1C92667D4AA3D2D668B5CF7B6E02270B4532F93E0F7, NULL, 0xFE142D8B58D00D54CEF2CDAFA595940C127D0C258C035F8E476FE08F42D76FE9, 0xE3184EFF6D30F3EA4756F13F679959C306952C3CEC889C9D7104D3A034F470BF, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspRepItemwiseclosingstockheader]      
@BranchName NVARCHAR(255) = '''',  @ManufName NVARCHAR(255) = '''',@BrandName NVARCHAR(255) = '''',@CategoryName NVARCHAR(255) = '''',      
@ProductName NVARCHAR(255)='''',@Date date = ''2026-09-05'',@QtyType int = 1      
as      
SET NOCOUNT ON;
begin      
CREATE TABLE #TempProductData      
(      
ProductID              INT,      
BranchID               INT,  
BrandID       INT,  
CategoryID             INT,  
ManufID                INT,  
[Date]                 DATE,      
[Product Code]         NVARCHAR(100),      
[Product Name]         NVARCHAR(200),      
[Branch Name]          NVARCHAR(200),      
[Mfr Name]             NVARCHAR(200),      
[Brand Name]           NVARCHAR(200),      
[Category Name]        NVARCHAR(200),      
[Sales Qty]            DECIMAL(25,4),      
[Sales Gross Amount]   DECIMAL(25,4),      
[Sales Net Amount]     DECIMAL(25,4),      
[Free Qty]             DECIMAL(25,4),      
[Damage Qty]           DECIMAL(25,4),      
[Damage Gross Amount]  DECIMAL(25,4),      
[Damage Net Amount]    DECIMAL(25,4)      
);      
IF @Date=CAST(GETDATE() AS DATE)      
BEGIN      
insert into #TempProductData      
select * from (      
SELECT Prod.ID ProductID,PInv.BranchID BranchID,Prod.BrandID, Prod.CategoryID, Manuf.ID AS ManufID,@Date AS [Date],Prod.Code [Product Code],Prod.Name [Product Name], MBO.Name [Branch Name],      
Manuf.Name[Mfr Name],MB.Name [Brand Name],PHL.Name [Category Name],      

(SUM(PInv.ActualQty)) + SUM(isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0)) AS [Sales Qty],     
(SUM(PInv.PurchasePrice* PInv.ActualQty)) +
SUM(((isnull(VLD.UomQty,0)*PInv.PurchasePrice))- (isnull(VLD.VLSMQty,0)*PInv.PurchasePrice) + (isnull(VLD.VLSRetrunQty,0)*PInv.PurchasePrice))
AS [Sales Gross Amount],           
dbo.fngetInclusiveValue(PInv.TaxId,SUM(PInv.MRPONPrice* 
(isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0)) + PInv.ActualQty),
SUM(PInv.PurchasePrice* ((isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0)) + PInv.ActualQty))) AS [Sales Net Amount],
(SUM(PInv.ActualFreeQty)) AS [Free Qty],      
(SUM(PInv.ActualDmgQty)) AS [Damage Qty],      
(SUM(PInv.PurchasePrice* PInv.ActualDmgQty)) AS [Damage Gross Amount],      
dbo.fngetInclusiveValue(PInv.TaxId,SUM(PInv.MRPONPrice* PInv.ActualDmgQty),SUM(PInv.PurchasePrice* PInv.ActualDmgQty)) AS [Damage Net Amount]
FROM tblProductInventory AS PInv      
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = PInv.BranchID      
LEFT JOIN tblMasterProduct AS Prod ON Prod.ID = PInv.ProdId      
JOIN tblMasterBrand MB ON MB.ID = Prod.BrandID      
JOIN tblMasterCategory PHL ON PHL.ID = Prod.CategoryID      
JOIN tblMasterTax AS Tax ON Tax.TaxID = Prod.SalesTaxId      
JOIN tblMasterManufacturer AS Manuf ON Manuf.ID = Prod.MfrID      
LEFT JOIN tblVanLoadingSlipDetail VLD ON VLD.InventoryID = PInv.InventoryId  
--WHERE Manuf.ManufacturerId IN (SELECT ID FROM @tvpAutoListDetails WHERE nIndex=0)      
WHERE PInv.TransDate<=@Date      
GROUP BY Prod.ID,Prod.Code,Prod.Name, MBO.Name,Manuf.Name,MB.Name,PHL.Name,PInv.BranchID,Prod.BrandID, Prod.CategoryID, Manuf.ID,PInv.TaxId) as nk      
END      
ELSE      
BEGIN      
insert into #TempProductData      
SELECT  Prod.ID ProductID,CS.BranchID BranchID,Prod.BrandID, Prod.CategoryID, Manuf.ID AS ManufID,@Date AS [Date],Prod.Code [Product Code],Prod.Name [Product Name], MBO.Name [Branch Name],      
Manuf.Name[Mfr Name],MB.Name [Brand Name],PHL.Name [Category Name],      
(SUM(CS.SaleQty)) AS [Sales Qty],      
(SUM(CS.SaleStockValue)) AS [Sales Gross Amount],      
(SUM(CS.SaleStockValue + (CS.SaleStockValue * Tax.GST)/100)) AS [Sales Net Amount] ,      
(SUM(CS.FreeQty)) AS [Free Qty],      
(SUM(CS.DmgQty)) AS [Damage Qty],      
(SUM(CS.DmgStockValue)) AS [Damage Gross Amount],      
(SUM(CS.DmgStockValue + (CS.DmgStockValue * Tax.GST)/100))  AS [Damage Net Amount]      
FROM tblClosingStock AS CS      
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = CS.BranchID      
LEFT JOIN tblMasterProduct AS Prod ON Prod.ID = CS.ProdId      
JOIN tblMasterBrand MB ON MB.ID = Prod.BrandID      
JOIN tblMasterCategory PHL ON PHL.ID = Prod.CategoryID      
JOIN tblMasterTax AS Tax ON Tax.TaxID = Prod.SalesTaxId      
JOIN tblMasterManufacturer AS Manuf ON Manuf.ID = Prod.MfrID      
--WHERE Manuf.ManufacturerId IN (SELECT ID FROM @tvpAutoListDetails WHERE nIndex=0)      
WHERE CS.ClsDate=@Date      
GROUP BY Prod.ID,Prod.Code,Prod.Name, MBO.Name,Manuf.Name,MB.Name,PHL.Name,CS.BranchID,Prod.BrandID, Prod.CategoryID, Manuf.ID     
END      
DECLARE @query NVARCHAR(MAX)      
set @query = '' select ProductID,      
BranchID,      
[Date],      
[Product Code],      
[Product Name],      
[Branch Name],      
[Mfr Name],      
[Brand Name],      
[Category Name],      
dbo.fnGetRoundedValue(SUM([Sales Qty]))             AS [Sales Qty],      
dbo.fnGetRoundedValue(SUM([Sales Gross Amount]))    AS [Sales Gross Amount],      
dbo.fnGetRoundedValue(SUM([Sales Net Amount]))      AS [Sales Net Amount],      
dbo.fnGetRoundedValue(SUM([Free Qty]))              AS [Free Qty],      
dbo.fnGetRoundedValue(SUM([Damage Qty]))            AS [Damage Qty],      
dbo.fnGetRoundedValue(SUM([Damage Gross Amount]))   AS [Damage Gross Amount],      
dbo.fnGetRoundedValue(SUM([Damage Net Amount]))     AS [Damage Net Amount]  FROM #TempProductData TPD WHERE ProductID > 0''      
set @query += case when ISNULL(@QtyType,1) = 1 then '' and ([Sales Qty] > 0 OR [Free Qty] > 0 OR [Damage Qty] > 0)'' else '''' END      
set @query += case when ISNULL(@BranchName,0) = 0 then '''' else '' AND TPD.BranchID  = ''+'' @BranchName ''+'''' END      
set @query += case when ISNULL(@BrandName,'''') = '''' then '''' else '' AND BrandID IN (SELECT * from dbo.fnSplitString( ''+'' @BrandName ,'''',''''))'' END      
set @query += case when ISNULL(@CategoryName,'''') = '''' then '''' else '' AND CategoryID IN (SELECT * from dbo.fnSplitString( ''+'' @CategoryName ,'''',''''))'' END      
set @query += case when ISNULL(@ManufName,'''') = '''' then '''' else '' AND ManufID IN (SELECT * from dbo.fnSplitString( ''+'' @ManufName ,'''',''''))'' END      
set @query += case when ISNULL(@ProductName,'''') = '''' then '''' else '' AND ProductID IN (SELECT * from dbo.fnSplitString( ''+'' @ProductName ,'''',''''))'' END      
set @query += '' GROUP BY      
ProductID,      
BranchID,      
[Date],      
[Product Code],      
[Product Name],      
[Branch Name],      
[Mfr Name],      
[Brand Name],      
[Category Name];''      
EXEC sys.sp_executesql @query, N''@BranchName NVARCHAR(255), @ManufName NVARCHAR(255), @BrandName NVARCHAR(255), @CategoryName NVARCHAR(255), @ProductName NVARCHAR(255), @Date date, @QtyType int'', @BranchName, @ManufName, @BrandName, @CategoryName, @ProductName, @Date, @QtyType      
drop table #TempProductData      
end',
N'[06] nocount';
GO
/****** uspRepItemWisePurchaseDetail ******/
EXEC #Apply07 N'dbo.uspRepItemWisePurchaseDetail', 0xF55D059C1E73B7555087EBD34C466920FC4C393E3CFB88DC772DE8281653DE4A, NULL, NULL, 0x96592DDCD47D21BFB77C21B7932D4F16E1C108E647EA806B44121A7CD2728DCF, 0xEA582B789C9E2BE44DF2A12B0A45B0DFC0B765FA1A20848BC2F0164760766509, NULL,
N'ALTER PROCEDURE [dbo].[uspRepItemWisePurchaseDetail]
@FromDate DATE = ''2025-01-01'',
@ToDate   DATE = ''2025-12-20'',
@ProdID   INT = 45,
@BranchID INT = 1
AS
SET NOCOUNT ON;
BEGIN
SELECT
H.DocID AS [Doc ID],
FORMAT(H.Date,''dd-MMM-yyyy'') AS [Invoice Date],
H.RefNo AS [Doc Ref],
V.Code AS [Vendor Code],
V.Name AS [Vendor Name],
MBO.Name AS [Branch Name],
dbo.fnGetRoundedValue(SUM(CASE WHEN H.TransID = 1
THEN ISNULL(D.UomQty,0) * ISNULL(MP.BaseCR,1)
WHEN H.TransID = 12
THEN (ISNULL(D.UomQty,0) * ISNULL(MP.BaseCR,1)) * -1
END)) AS [Base Qty],
MU.Name AS [Base UOM],
dbo.fnGetRoundedValue(SUM(CASE WHEN H.TransID = 1
THEN ISNULL(D.UomQty,0) * ISNULL(MP.SalesCR,1)
WHEN H.TransID = 12
THEN ISNULL(D.UomQty,0) * ISNULL(MP.SalesCR,1) * -1
END)) AS [Sales UOM Qty],
MS.Name AS [Sales UOM],
dbo.fnGetRoundedValue(SUM(CASE WHEN H.TransID = 1
THEN ISNULL(D.UomQty,0) * ISNULL(MP.ReportingCR,1)
WHEN H.TransID = 12
THEN ISNULL(D.UomQty,0) * ISNULL(MP.ReportingCR,1) * -1
END)) AS [Reporting UOM Qty],
MR.Name AS [Reporting UOM],
dbo.fnGetRoundedValue(SUM(ISNULL(D.GrossAmt,0))) AS [Gross Amt],
dbo.fnGetRoundedValue(SUM(ISNULL(D.NetAmt,0))) AS [Net Amt],
dbo.fnGetRoundedValue(H.NetAmt) AS [Doc Net Amt],
H.Remarks AS [Remarks],
H.Narration AS [Narration],
MP.Name [Product Name]
FROM tblTransPurchaseHeader H
JOIN tblTransPurchaseDetail D ON D.InventoryId = H.ID
JOIN tblMasterProduct MP ON MP.ID = D.ProdID
LEFT JOIN tblMasterVendor V ON V.ID = H.VendorID
LEFT JOIN tblMasterBranchOffice MBO ON MBO.ID = H.BranchID
LEFT JOIN tblMasterUom MU ON MU.ID = MP.BaseUomID
LEFT JOIN tblMasterUom MS ON MS.ID = MP.SalesUomID
LEFT JOIN tblMasterUom MR ON MR.ID = MP.ReportingUomID
WHERE H.Date BETWEEN @FromDate AND @ToDate
AND H.Status NOT IN (2,4)
AND D.ProdID = @ProdID
AND H.BranchID = @BranchID
GROUP BY
MP.Code, H.DocID, H.Date, H.RefNo, V.Code, V.Name, MP.Name,
MU.Name, MS.Name, MR.Name, MBO.Name, H.NetAmt, H.Remarks, H.Narration;
END',
N'[export] nocount';
GO
/****** uspRepItemWisePurchaseHeader ******/
EXEC #Apply07 N'dbo.uspRepItemWisePurchaseHeader', 0x89C94A330B77607D8B1DF151B12406169B4F3BCF820D489761DF63DA574741D5, NULL, NULL, 0xE5871316CDB97023F21D70606E93848C98E4F56A9C4FE1941C15196E32C1C128, 0xA724DD8294A08846AB89F57C77BB841DD123AEFE5B5A0236FE56487A55BC2430, NULL,
N'--uspRepItemWisePurchaseHeader 4
ALTER PROCEDURE [dbo].[uspRepItemWisePurchaseHeader]  
@BranchName INT,      
@MfrName NVARCHAR(100) = '''',      
@BrandName NVARCHAR(100) = '''',      
@CategoryName NVARCHAR(100) = '''',      
@ProductName NVARCHAR(100) = '''',      
@FromDate DATE = ''2025-01-01'',      
@ToDate   DATE = ''2026-12-20''      
AS      
SET NOCOUNT ON;
BEGIN      
SELECT      
@FromDate [From Date],      
@ToDate [To Date],      
D.ProdID [Product ID],      
H.BranchID,      
MBO.Name [Branch Name],      
MP.Code  [Product Code],      
MP.Name  [Product Name],      
MM.Name  [Manufacturer Name],      
MB.Name  [Brand Name],      
MC.Name  [Category Name],      
dbo.fnGetRoundedValue(SUM(CASE WHEN H.TransID = 1      
THEN ISNULL(D.UomQty,0) * ISNULL(MP.BaseCR,1)      
WHEN H.TransID = 12      
THEN (ISNULL(D.UomQty,0) * ISNULL(MP.BaseCR,1)) * -1      
END      
)) AS [Base Qty],      
MU.Name  [Base UOM],      
dbo.fnGetRoundedValue(SUM( CASE WHEN H.TransID = 1      
THEN ISNULL(D.UomQty,0) * ISNULL(MP.SalesCR,1)      
WHEN H.TransID = 12      
THEN ISNULL(D.UomQty,0) * ISNULL(MP.SalesCR,1) * -1      
END      
)) AS [Sales UOM Qty],      
MS.Name  [Sales UOM],      
dbo.fnGetRoundedValue(SUM( CASE WHEN H.TransID = 1      
Then ISNULL(D.UomQty,0) * ISNULL(MP.ReportingCR,1)      
WHEN H.TransID = 12      
Then ISNULL(D.UomQty,0) * ISNULL(MP.ReportingCR,1) * -1      
END      
)) AS [Reporting UOM Qty],      
MR.Name  [Reporting UOM],      
dbo.fnGetRoundedValue(SUM(isnull(D.GrossAmt,0))) AS [Gross Amt],      
dbo.fnGetRoundedValue(sum(isnull(D.NetAmt,0))) as [Net Amt]      
FROM tblTransPurchaseHeader H      
JOIN tblTransPurchaseDetail D ON D.InventoryId = H.ID      
JOIN tblMasterProduct MP ON MP.ID = D.ProdID      
left join tblMasterBranchOffice MBO on MBO.ID = H.BranchID      
left Join tblMasterManufacturer MM on MM.ID = MP.MfrID      
left join tblMasterBrand MB on MB.ID = MP.BrandID      
left join tblMasterCategory MC on MC.ID = MP.CategoryID      
left join tblMasterUom MU on MU.ID = MP.BaseUomID      
left join tblMasterUom MS on MS.ID = MP.SalesUomID      
left join tblMasterUom MR on MR.ID = MP.ReportingUomID      
WHERE H.Date BETWEEN @FromDate AND @ToDate      
AND H.status NOT IN (2,4)      
AND (isnull(@MfrName,'''') = '''' or MM.ID IN (SELECT * from dbo.fnSplitString(@MfrName,'','')))     
AND (isnull(@BrandName,'''') = '''' or MB.ID IN (SELECT * from dbo.fnSplitString (@BrandName,'','')))      
AND (isnull(@CategoryName,'''') = '''' or MC.ID IN (SELECT * from dbo.fnSplitString (@CategoryName,'','')))      
AND (isnull(@ProductName,'''') = '''' OR MP.ID IN (SELECT * from dbo.fnSplitString (@ProductName,'','')))      
AND (@BranchName =0 OR MBO.ID = @BranchName)      
GROUP BY      
MP.Code,      
D.ProdID,      
H.BranchID,      
MP.Name,      
MM.Name,      
MB.Name,      
MC.Name,      
MU.Name,      
MS.Name,      
MR.Name,      
MBO.Name      
END',
N'[export] nocount';
GO
/****** uspRepItemWiseSalesAndReturnHeader ******/
EXEC #Apply07 N'dbo.uspRepItemWiseSalesAndReturnHeader', 0x06A7BC1F1A2D433C11871FED58D7CD7BD98B328CCFDBC8335FB0D64E2055B212, NULL, NULL, 0x65B45062C499FB49C05BA51EAB74059EBD3E3C7DD2B4CFF6DC25DF1E3D0FEF85, 0xCC6961DD3ADBDDCCBF6B44C7E5109E58474FD14E9C12E6F63B27F86E00A2C460, NULL,
N'--uspRepItemWiseSalesAndReturnHeader @AnaProdCustValueType=''Qty'',@FromDate=''2025-01-01'',@ToDate=''2025-12-20'';    
ALTER procedure [dbo].[uspRepItemWiseSalesAndReturnHeader]    
@BranchID INT = 0,    
@MfrName NVARCHAR(100) = '''',    
@BrandName NVARCHAR(100) = '''',    
@CategoryName NVARCHAR(100) = '''',    
@ProductName NVARCHAR(100) = '''',    
@AnaProdCustValueType INT = 1,    
@FromDate DATE = ''2025-01-01'',    
@ToDate   DATE = ''2025-12-20''    
AS    
SET NOCOUNT ON;
BEGIN      
SELECT     
D.ProdID[Product ID],MP.Code[Product Code],MP.Name[Product Name],MB.Name[Branch Name],MM.Name[Manufacturer Name],    
MBB.Name[Brand Name],MC.Name[Category Name],    
    
dbo.fnGetRoundedValue(    
    CASE WHEN @AnaProdCustValueType = 3 THEN SUM(D.UomQty)    
         WHEN @AnaProdCustValueType = 2 THEN SUM(D.GrossAmt)    
         ELSE SUM(D.NetAmt) END    
) [Sales Qty],    
    
dbo.fnGetRoundedValue(    
    CASE WHEN @AnaProdCustValueType = 3 THEN SUM(CASE WHEN H.TransactionType = 2 THEN D.UomQty ELSE 0 END)    
         WHEN @AnaProdCustValueType = 2 THEN SUM(CASE WHEN H.TransactionType = 2 THEN D.GrossAmt ELSE 0 END)    
         ELSE SUM(CASE WHEN H.TransactionType = 2 THEN D.NetAmt ELSE 0 END) END    
) [Saleable Return Qty],    
    
dbo.fnGetRoundedValue(    
    CASE WHEN @AnaProdCustValueType = 3 THEN SUM(CASE WHEN H.TransactionType = 3 THEN D.UomQty ELSE 0 END)    
         WHEN @AnaProdCustValueType = 2 THEN SUM(CASE WHEN H.TransactionType = 3 THEN D.GrossAmt ELSE 0 END)    
         ELSE SUM(CASE WHEN H.TransactionType = 3 THEN D.NetAmt ELSE 0 END) END    
) [Damage Return Qty]    
    
FROM tblTranSalesHeader H        
LEFT JOIN tblTranSalesDetail D ON D.InvID = H.ID    
JOIN tblMasterProduct MP ON MP.ID = D.ProdID      
JOIN tblMasterBranchOffice MB on MB.ID = H.BranchID    
JOIN tblMasterManufacturer MM on MM.ID = Mp.MfrID    
JOIN tblMasterCategory MC on MC.ID = MP.CategoryID    
JOIN tblMasterBrand MBB on MBB.ID = MP.BrandID    
WHERE H.InvDate BETWEEN @FromDate AND @ToDate        
AND H.status NOT IN (2,4)        
AND (isnull(@MfrName,'''') = '''' or MM.ID IN (SELECT * from dbo.fnSplitString( @MfrName,'','')))        
AND (isnull(@BrandName,'''') = '''' or MBB.ID IN (SELECT * from dbo.fnSplitString( @BrandName,'','')))        
AND (isnull(@CategoryName,'''') = '''' or MC.ID IN (SELECT * from dbo.fnSplitString( @CategoryName,'','')))        
AND (isnull(@ProductName,'''') = '''' OR MP.ID IN (SELECT * from dbo.fnSplitString( @ProductName,'','')))        
AND (@BranchID = 0 OR H.BranchID = @BranchID)    
GROUP BY    
    D.ProdID,    
    MP.Code,    
    MP.Name,    
    MB.Name,    
    MM.Name,    
    MBB.Name,    
    MC.Name    
    
END',
N'[export] nocount';
GO
/****** uspRepJournalEntryDetail ******/
EXEC #Apply07 N'dbo.uspRepJournalEntryDetail', 0xF87B3A47B24F82C0FCC633B1562238E988FF072CD7C980787F561318F1426E5C, NULL, NULL, 0x93E04FA84CE5C210A4727AFC168EAF7CEE3E92C1DC355DA3C1A856E8DE9D4DA8, 0xA35116FE6314EC851D087BDA08CDC137291ADC57FFA9CC5F6B8B14F5C2C374BB, NULL,
N'ALTER procedure [dbo].[uspRepJournalEntryDetail]    
@JVID INT    
AS     
SET NOCOUNT ON;
BEGIN     
SELECT    
 FAA.AccountName[Account Name],CASE FSJ.Adjusment WHEN 0 THEN ''No'' ELSE  ''Yes'' END AS Adjustment,    
 dbo.fnGetRoundedValue(FSJ.Credit)[Credit],dbo.fnGetRoundedValue(FSJ.Debit)[Debit],FSJ.Remarks[Remarks],dbo.fnGetRoundedValue(FSJ.Balance)[Balance]    
    
FROM tblFAJournal FSJ    
LEFT JOIN tblFAAccount FAA on FAA.FAID = FSJ.AccountID    
WHERE FSJ.JVID = @JVID and FSJ.DocPrefix = 9     
END;',
N'[export] nocount';
