/****** uspRepJournalEntryHeader ******/
EXEC #Apply07 N'dbo.uspRepJournalEntryHeader', 0x60510DA2046F67B5D2FF30EDEA47176B230B243B4F6E8E25025E0F3D9A5C489B, NULL, NULL, 0xA8D199676546D54C34F473D07D68877084A724555F6E3112992FC890EFDDC3F0, 0x40E0FBBF3CB1A0933B3CF813B924D31E5FC1F41EECE4953C24970AC0531807BD, NULL,
N'ALTER procedure [dbo].[uspRepJournalEntryHeader]  
@StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2024-01-01'',@ToDate DATE =''2026-09-30''
AS    
SET NOCOUNT ON;
BEGIN    
DECLARE @Sts AS TABLE(Status INT)    
IF(@StatusID = 0)    
BEGIN    
INSERT INTO @Sts values (1),(3),(5)    
END    
ELSE    
BEGIN     
INSERT INTO @Sts values(@StatusID)    
END    
  
SELECT  
 JV.JVID[ID],JV.DocID[Doc ID],FORMAT(JV.DocDate,''dd/MMM/yyyy'')[Doc Date],JV.DocRef[Ref No],JV.Narration[Narration],
 S.Description[Status],CU.UserName[Created By],CONVERT(NVARCHAR,JV.CDate)[Created Date],MU.UserName[Modify By],
 CONVERT(NVARCHAR,JV.MDate)[Modified Date]
  
FROM tblFAJournal JV   
LEFT JOIN tblStatus S on S.ID = JV.Status  
LEFT JOIN tblUsers CU on CU.ID = JV.CBy  
LEFT JOIN tblUsers MU on MU.ID = JV.MBy  
    WHERE JV.DocPrefix = 9 and 
    JV.DocDate BETWEEN @FromDate AND @ToDate  
      AND JV.Status IN (SELECT Status FROM @Sts) 
      GROUP BY
    JV.JVID, JV.DocID, JV.DocDate, JV.DocRef, JV.Narration,
    S.Description, CU.UserName, CONVERT(NVARCHAR,JV.CDate),MU.UserName, JV.MDate

END',
N'[export] nocount';
GO
/****** uspRepManufacturerwiseOSDetail ******/
EXEC #Apply07 N'dbo.uspRepManufacturerwiseOSDetail', 0x1A5E20DAECA0A75D0608A7A311DCF65A279D7F0BDF08F6AE9E7C507BB3F899A5, NULL, NULL, 0x7C6CF88850B90362418CE40E82045144D1146B84C4F12EFD02094FCBA6AF2E67, 0x085E35A104A1E07A5CD7162FB7C30D62EC32FB3D1924CCF6602035F36A0AE85B, NULL,
N'--uspRepManufacturerwiseOSDetail 0,''2026-04-01'',2
ALTER PROC [dbo].[uspRepManufacturerwiseOSDetail]
@BranchID int = 4 ,@ToDate date = ''2026-08-17'',@ManufID INT = 8
as
SET NOCOUNT ON;
begin
set dateformat dmy;
select DocID [Doc ID],FORMAT(InvDate,''dd/MMM/yyyy'') [Doc Date],BeatName [Beat Name],Salesman [Salesman Name],
CustomerName [Customer Name],dbo.fnGetRoundedValue(NetAmt) [Invoice Value],
dbo.fnGetRoundedValue(Balance) [Balance]
,dbo.fnGetRoundedValue(MfrOS) [Mfr Outstanding],
dbo.fnGetRoundedValue(MfrRatio) [Mfr Outstanding %],
Ageing [Ageing]
from (
select SH.DocID,SH.InvDate,MB.Name BeatName,SM.Name Salesman,MC.Name CustomerName,
SH.NetAmt,SH.Balance,(SUM(SD.NetAmt) / SH.NetAmt) * SH.Balance MfrOS,
IIF((((SUM(SD.NetAmt) / SH.NetAmt) * SH.Balance) / SH.NetAmt) * 100 >= 100, 100,
(((SUM(SD.NetAmt) / SH.NetAmt) * SH.Balance) / SH.NetAmt) * 100) MfrRatio,
DATEDIFF(DD,SH.InvDate,GETDATE()) AS [Ageing]
from tblTranSalesHeader SH
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID
LEFT JOIN tblMasterBeat MB ON MB.ID = SH.BeatID
LEFT JOIN tblMasterSalesman SM ON SM.ID = SH.SalesManID
WHERE SH.BranchID = (CASE WHEN @BranchID = 0 THEN SH.BranchID ELSE @BranchID end)
and InvDate <= @ToDate
and DocPrefix = 15 and Status not in (2,4) AND Balance > 0 AND SD.TaxID > 0  AND
MP.MFRID IN (@ManufID)
GROUP BY SH.DocID,SH.InvDate,MB.Name,SM.Name,MC.Name,SH.NetAmt,SH.Balance,SH.ID
) as rec  GROUP BY DocID,InvDate,BeatName,Salesman,CustomerName,Balance,NetAmt,MfrOS,MfrRatio,Ageing
order by DocID
end',
N'[export] nocount';
GO
/****** uspRepManufacturerwiseOSHeader ******/
EXEC #Apply07 N'dbo.uspRepManufacturerwiseOSHeader', 0x71388880420A42CBEF2286E48C7B1B662BD9D2A73CDF48F149EE0EDC4518B30A, NULL, NULL, 0x6340881A4042196E9ECA1F57CFAC3B8C68F36C3B41CBC07DB4CC665E6EC1933D, 0x73892C90AD6585519BB5EB8D211A630FCBC0729627C0123701051541687937F7, NULL,
N'ALTER PROC [dbo].[uspRepManufacturerwiseOSHeader]
@BranchID int = 4,@ManufIDs nvarchar(255) = '''',@ToDate date = ''2026-08-17''
AS
SET NOCOUNT ON;
BEGIN
select @BranchID BranchID,@ToDate ToDate,MfrID,MfrName,
dbo.fnGetRoundedValue(SUM(MfrOS)) MfrOS,COUNT(InvID) InvCount from (
select MP.MfrID,MF.Name MfrName,(SUM(SD.NetAmt) / SH.NetAmt) * SH.Balance MfrOS,SH.ID InvID from tblTranSalesHeader SH
JOIN tblTranSalesDetail SD ON SD.InvID = SH.ID
JOIN tblMasterProduct MP ON MP.ID = SD.ProdID
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID
WHERE SH.BranchID = (CASE WHEN @BranchID = 0 THEN SH.BranchID ELSE @BranchID end)
and InvDate <= @ToDate
and DocPrefix = 15 and Status not in (2,4) AND Balance > 0 AND SD.TaxID > 0  AND
(ISNULL(@ManufIDs,'''') = '''' OR MF.ID IN (SELECT * FROM dbo.fnSplitString(@ManufIDs,'','')))
GROUP BY MP.MfrID,MF.Name,SH.NetAmt,SH.Balance,SH.ID) as rec
GROUP BY MfrID,MfrName
END',
N'[export] nocount';
GO
/****** uspRepMasterBeatData ******/
EXEC #Apply07 N'dbo.uspRepMasterBeatData', 0x8C9897559B1E1686940DF67059D0C712FBD9544507DC64EF725AF3D7E5A6BA07, NULL, NULL, 0xE0F81E25E5534F32E713EFFBFE4852622ACD220E2CEF59E6EBBB0AD0A5827F7D, 0x6B59CF4390728EF09418BFB0F501DB9C30D9952CDE2013D4A1E7696C845D4FD0, NULL,
N'ALTER proc [dbo].[uspRepMasterBeatData]    
@BeatName nvarchar(max) = null,@UserID INT = NULL    
as    
SET NOCOUNT ON;
begin    
if(isnull(@BeatName,'''') != '''')    
begin    
select Name [Beat Name],case when MB.Active = 1 then ''Yes'' ELSE ''No'' end Active,
MU.UserName [Created By],CONVERT(NVARCHAR,MB.CDate) [Create Date],
MUM.UserName [Modify By],CONVERT(NVARCHAR,MB.MDate) [Modify Date]
from tblMasterBeat MB   
JOIN tblUsers MU ON MU.ID = MB.CBy    
LEFT JOIN tblUsers MUM ON MUM.ID = MB.MBy    
where Name = @BeatName AND (MB.CBy = CASE WHEN ISNULL(@UserID,0) = 0 THEN MB.CBy ELSE @UserID END)  order by Name    
end    
else    
begin    
select Name [Beat Name],case when MB.Active = 1 then ''Yes'' ELSE ''No'' end Active,
MU.UserName [Created By],CONVERT(NVARCHAR,MB.CDate) [Create Date],
MUM.UserName [Modify By],CONVERT(NVARCHAR,MB.MDate) [Modify Date]
from tblMasterBeat MB   
JOIN tblUsers MU ON MU.ID = MB.CBy    
LEFT JOIN tblUsers MUM ON MUM.ID = MB.MBy    
WHERE (MB.CBy = CASE WHEN ISNULL(@UserID,0) = 0 THEN MB.CBy ELSE @UserID END) order by Name    
end    
end',
N'[export] nocount';
GO
