/****** uspRepMasterProductData ******/
EXEC #Apply07 N'dbo.uspRepMasterProductData', 0xE78420395D738ABE906A6B09552F0019D2AF21E297AFD2D62C90A5D08A609DCD, 0x59426BCF50B684E0A04249BB4E9E0A2B7411E5E7C761FA67F3EEE9315144A8C0, NULL, 0x4EC5B240FD15A4451DE076B8DCEF6093105F5EFC25A5297827C520D7AD4F3711, 0x56D51C9EECD498BFFB5A8D7F0871B9B91A2F2315E1B43E8D5ED12F87527996DD, NULL,
N'--uspRepMasterProductData '''','''','''',''''      
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspRepMasterProductData]      
@ManufName nvarchar(max) = null,@BrandName nvarchar(max) = null,@CategoryName nvarchar(max) = null,@ProductName nvarchar(max) = null    
as        
SET NOCOUNT ON;
begin        
    
DECLARE @strQuery NVARCHAR(MAX) = ''''      
SET @strQuery = '' SELECT MP.Code,MP.Name,MP.EAN,MF.Name [Mfr Name],MB.Name [Brand Name],MC.Name [Category Name],MUB.Name [Base UOM],MUP.Name [Purcase UOM],MUS.Name [Sales UOM],    
MT.TaxName Tax,PurchasePrice,SalesPrice,ECP,SPLPrice,MRP,ReturnPrice,case when MP.TrackInventory = 1 then ''''Yes'''' ELSE ''''No'''' END [Track Inventory],    
case when MP.TrackBatch = 1 then ''''Yes'''' ELSE ''''No'''' END [Track Batch],case when MP.TrackSerial = 1 then ''''Yes'''' ELSE ''''No'''' END [Track Serial],    
case when MP.TrackPDK = 1 then ''''Yes'''' ELSE ''''No'''' END [Track PDK],case when MP.DateFormat = 1 then ''''DMY'''' ELSE ''''MY'''' END [Date Format],MOH,MOQ    
,MV.Name [Vendor Name],case when MP.Active = 1 then ''''Yes'''' ELSE ''''No'''' end Active,  
MU.UserName [Created By],CONVERT(NVARCHAR,MP.CDate) [Create Date],  
MUM.UserName [Modify By],CONVERT(NVARCHAR,MB.MDate) [Modify Date]  
from tblMasterProduct MP          
JOIN tblMasterManufacturer MF ON MF.ID = MP.MfrID          
JOIN tblMasterBrand MB ON MB.ID = MP.BrandID          
JOIN tblMasterCategory MC ON MC.ID = MP.CategoryID          
join tblMasterTax MT ON MT.TaxID = MP.SalesTaxID    
join tblMasterUOM MUB ON MUB.ID = MP.BaseUomID    
join tblMasterUOM MUP ON MUP.ID = MP.PurchaseUomID    
join tblMasterUOM MUS ON MUS.ID = MP.PurchaseUomID    
JOIN tblUsers MU ON MU.ID = MP.CBy        
LEFT JOIN tblUsers MUM ON MUM.ID = MP.MBy    
left JOIN tblMasterVendor MV ON MV.ID = MP.VendorID  WHERE MP.Active IN (0,1) ''    
SET @strQuery += CASE WHEN ISNULL(@ManufName,'''') = '''' THEN '''' ELSE '' AND MF.ID IN (SELECT * from dbo.fnSplitString(''+'' @ManufName ,'''',''''))'' END      
SET @strQuery += CASE WHEN ISNULL(@BrandName,'''') = '''' THEN '''' ELSE '' AND MB.ID IN (SELECT * from dbo.fnSplitString(''+'' @BrandName ,'''',''''))'' END     
SET @strQuery += CASE WHEN ISNULL(@CategoryName,'''') = '''' THEN '''' ELSE '' AND MC.ID IN (SELECT * from dbo.fnSplitString(''+'' @CategoryName ,'''',''''))'' END      
SET @strQuery += CASE WHEN ISNULL(@ProductName,'''') = '''' THEN '''' ELSE '' AND MP.ID IN (SELECT * from dbo.fnSplitString(''+'' @ProductName ,'''',''''))'' END     
EXEC sys.sp_executesql @strQuery, N''@ManufName nvarchar(max), @BrandName nvarchar(max), @CategoryName nvarchar(max), @ProductName nvarchar(max)'', @ManufName, @BrandName, @CategoryName, @ProductName    
end',
N'[06] nocount';
GO
/****** uspRepMasterSalesmanData ******/
EXEC #Apply07 N'dbo.uspRepMasterSalesmanData', 0x11E6A90507E6167C83D3A9298268AE6467E3670C8399BE89F08010960E54E018, 0x8A2644B8CE13BF80FA03C3A38F7CB7A9841AEBE1F5FD3C904206D56E499558A5, NULL, 0x5B0FB47787BB40CCE07A53E54F3B42D82EFC56FB41700F5CAE15C6B058A05DE2, 0x0B1DD799872FFA9DEC12C0BBEA3419403DC7BA295C70CADE240B51B3F3DC6C83, NULL,
N'--uspRepMasterSalesmanData '''',''4,2''
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspRepMasterSalesmanData]      
@SalesmanName nvarchar(max) = null,@SalesmanGrpName nvarchar(max) = null  
as        
SET NOCOUNT ON;
begin        
DECLARE @strQuery NVARCHAR(MAX) = ''''      
SET @strQuery = '' select MS.Name [Salesman Name],MSG.Name [Salesman Group],CONVERT(nvarchar,DOJ,103) DOJ,    
MS.MobileNo,case when MS.Active = 1 then ''''Yes'''' ELSE ''''No'''' end Active,MU.UserName [Created By],CONVERT(NVARCHAR,MS.CDate) [Create Date],    
MUM.UserName [Modify By],CONVERT(NVARCHAR,MS.MDate) [Modify Date]    
from tblMasterSalesman MS      
LEFT JOIN tblMasterSalesmanGroup MSG ON MSG.ID = MS.SalesmanGroupID      
JOIN tblUsers MU ON MU.ID = MS.CBy        
LEFT JOIN tblUsers MUM ON MUM.ID = MS.MBy WHERE MS.Active IN (0,1) ''      
--SET @strQuery += CASE WHEN ISNULL(@SalesmanName,'''') = '''' THEN '''' ELSE '' AND MS.Name = ''+'' @SalesmanName '' END      
--SET @strQuery += CASE WHEN ISNULL(@SalesmanGrpName,'''') = '''' THEN '''' ELSE '' AND MSG.Name = ''+'' @SalesmanGrpName '' END      
SET @strQuery += CASE WHEN ISNULL(@SalesmanName,'''') = '''' THEN '''' ELSE '' AND 
MS.ID IN (SELECT * from dbo.fnSplitString(''+'' @SalesmanName ,'''',''''))'' END      
SET @strQuery += CASE WHEN ISNULL(@SalesmanGrpName,'''') = '''' THEN '''' ELSE '' AND MSG.ID
IN (SELECT * from dbo.fnSplitString(''+'' @SalesmanGrpName ,'''',''''))'' END      
EXEC sys.sp_executesql @strQuery, N''@SalesmanName nvarchar(max), @SalesmanGrpName nvarchar(max)'', @SalesmanName, @SalesmanGrpName      
end',
N'[06] nocount';
GO
/****** uspRepMfrWiseProductMarginDetail ******/
EXEC #Apply07 N'dbo.uspRepMfrWiseProductMarginDetail', 0xDFB7963F03B5A26079538B59E3B564953AE44FEE24B74BF9E4AEC993DCAAA6AC, NULL, NULL, 0xE11C0527C40AB2FF9B41A1049027DD50547659FEC24F4E6F2B53D1932DF7DB66, 0xB148D7B9C5519AB7E350EAC8B329745EABA6BCF4F95185E73E85719A731D2084, NULL,
N'--uspRepMfrWiseProductMarginDetail ''15'',''2024-01-01'',''2026-01-26'',2  
ALTER PROCEDURE [dbo].[uspRepMfrWiseProductMarginDetail]  
  
 @ID INT ,      
@Fromdate DATE,      
@ToDate DATE ,      
@GNAmount INT  
  
AS  
SET NOCOUNT ON;
BEGIN  
  
IF (@GNAmount = 1)  
BEGIN  
  
SELECT  
SRI.[Product Name],dbo.fnGetRoundedValue(SUM(SRI.[Sales Qty])) AS [Sales Qty],dbo.fnGetRoundedValue(SUM(SRI.[Base Qty]))  AS [Base Qty],    
dbo.fnGetRoundedValue(SUM(SRI.[Purchase Price] * SRI.[Base Qty])) AS [Purchase Price],    
dbo.fnGetRoundedValue(SUM(SRI.[Sale Price])) AS [Sale Price],   
dbo.fnGetRoundedValue(ISNULL((SRI.[Sale Price]) - (SRI.[Purchase Price] * SUM(SRI.[Base Qty])),0)) AS [Margin Amount],  
dbo.fnGetRoundedValue(ISNULL(((SRI.[Sale Price]) - (SRI.[Purchase Price] * SUM(SRI.[Base Qty])))/ NULLIF((SRI.[Purchase Price] * SUM(SRI.[Base Qty])),0) * 100 , 0))AS [Margin %]  
FROM  
(  
SELECT MP.Name AS [Product Name],(TSD.UomQty ) AS [Sales Qty],(TSD.AdjustQty) AS [Base Qty],  
MP.PurchasePrice AS [Purchase Price],(TSD.GrossAmt) AS [Sale Price]  
  
FROM tblTranSalesDetail AS TSD    
JOIN tblTranSalesHeader AS TSH ON TSH.ID = TSD.InvId    
LEFT JOIN tblMasterProduct AS MP ON MP.ID = TSD.ProdId    
LEFT JOIN tblMasterManufacturer AS MMF ON MMF.ID = MP.MfrID    
LEFT JOIN tblProductInventory AS PIN ON PIN.InventoryId = TSD.InventoryId    
WHERE TSH.INVDate BETWEEN @Fromdate AND @ToDate AND TSH.Status IN (1,3,5) AND TSD.ProdID = @ID )SRI  
GROUP BY SRI.[Product Name],SRI.[Purchase Price],SRI.[Sale Price]  
ORDER BY SRI.[Product Name]  
END  
  
ELSE IF (@GNAmount = 2)    
BEGIN    
  
SELECT SRI.[Product Name],dbo.fnGetRoundedValue(SUM(SRI.[Sales Qty])) AS [Sales Qty],dbo.fnGetRoundedValue(SUM(SRI.[Base Qty])) AS [Base Qty],    
dbo.fnGetRoundedValue(SUM(SRI.[Purchase Price] * SRI.[Base Qty])) AS [Purchase Price],    
dbo.fnGetRoundedValue(SUM(SRI.[Sale Price])) AS [Sale Price],   
dbo.fnGetRoundedValue(ISNULL((SRI.[Sale Price]) - (SRI.[Purchase Price] * SUM(SRI.[Base Qty])),0)) AS [Margin Amount],  
dbo.fnGetRoundedValue(ISNULL(((SRI.[Sale Price]) - (SRI.[Purchase Price] * SUM(SRI.[Base Qty])))/ NULLIF((SRI.[Purchase Price] * SUM(SRI.[Base Qty])),0) * 100 , 0))AS [Margin %]  
FROM  
(  
SELECT MP.Name AS [Product Name],(TSD.UomQty ) AS [Sales Qty],(TSD.UomQty) AS [Base Qty],  
MP.PurchasePrice AS [Purchase Price],(TSD.NetAmt) AS [Sale Price]  
  
FROM tblTranSalesDetail AS TSD    
JOIN tblTranSalesHeader AS TSH ON TSH.ID = TSD.InvId    
LEFT JOIN tblMasterProduct AS MP ON MP.ID = TSD.ProdId    
LEFT JOIN tblMasterManufacturer AS MMF ON MMF.ID = MP.MfrID    
LEFT JOIN tblProductInventory AS PIN ON PIN.InventoryId = TSD.InventoryId    
WHERE TSH.INVDate BETWEEN @Fromdate AND @ToDate AND TSH.Status IN (1,3,5) AND TSD.ProdID = @ID )SRI  
GROUP BY SRI.[Product Name],SRI.[Purchase Price],SRI.[Sale Price]  
ORDER BY SRI.[Product Name]  
END  
END',
N'[export] nocount';
GO
/****** uspRepMfrWiseProductMarginHeader ******/
EXEC #Apply07 N'dbo.uspRepMfrWiseProductMarginHeader', 0x28E0C4D73A891F9EF929A8E297EF5BBF7D04B845DDA70DC3C47CFCBB09182F88, NULL, NULL, 0xBF3A4CE8588D87CC94E1EFCDFFC6351ACBFE6B1E794F5A1A4563EBD5F4C1B825, 0x12FA10FADD505DBF51694479FFE881CBAFFBF840281BD5311C7F1F0828449127, NULL,
N'--uspRepMfrWiseProductMarginHeader '''','''',''2024-01-01'',''2026-01-26'',1    
ALTER PROCEDURE [dbo].[uspRepMfrWiseProductMarginHeader]    
    
@ManufacturerName NVARCHAR(255) = '''',      
@ProductName NVARCHAR(255) = '''',      
@Fromdate DATE =NULL,      
@ToDate DATE =NULL,      
@Type INT      
    
AS    
SET NOCOUNT ON;
BEGIN    
    
IF (@Type = 1)    
BEGIN    
    
 SELECT SRI.ID, @Fromdate as [From],@ToDate as [To],@Type AS [GNAmount],SRI.[Product Code],SRI.[Product Name],    
SRI.EAN,SRI.[Manuf Name] [Mfr Name],dbo.fnGetRoundedValue(SUM(SRI.[Sales Qty])) AS [Sales Qty],    
dbo.fnGetRoundedValue(SUM(SRI.[Base Qty]))  AS [Base Qty],    
dbo.fnGetRoundedValue(SUM(SRI.[Purchase Price] * SRI.[Base Qty])) AS [Purchase Price],    
dbo.fnGetRoundedValue(SUM(SRI.[Sale Price])) AS [Sale Price],    
dbo.fnGetRoundedValue(ISNULL(SUM((SRI.[Sale Price]) - (SRI.[Purchase Price] * (SRI.[Base Qty]))),0)) AS [Margin Amount],    
dbo.fnGetRoundedValue(ISNULL((SUM((SRI.[Sale Price]) - (SRI.[Purchase Price] * (SRI.[Base Qty]))))/Case when (SUM(SRI.[Purchase Price] * (SRI.[Base Qty])))=0 then 1 else (SUM(SRI.[Purchase Price] * (SRI.[Base Qty])))end  *100 ,0)) as [Margin %]    
FROM    
(    
SELECT MP.ID,@Fromdate as [From],@ToDate as [To],@Type AS [GNAmount],MP.Code AS [Product Code],    
MP.Name AS [product Name],MP.EAN,MMF.Name AS [Manuf Name],(TSD.UomQty) AS [Sales Qty],(TSD.UomQty) AS [Base Qty],    
(MP.PurchasePrice) AS [Purchase Price],    
(TSD.GrossAmt) AS [Sale Price]    
    
FROM tblTranSalesDetail AS TSD    
JOIN tblTranSalesHeader AS TSH ON TSH.ID = TSD.InvId    
LEFT JOIN tblMasterProduct AS MP ON MP.ID = TSD.ProdId    
LEFT JOIN tblMasterManufacturer AS MMF ON MMF.ID = MP.MfrID    
LEFT JOIN tblProductInventory AS PIN ON PIN.InventoryId = TSD.InventoryId    
WHERE TSH.InvDate BETWEEN @Fromdate AND @ToDate AND TSH.Status IN (1,3,5) AND TSH.DocPrefix=15    
AND(@ManufacturerName = '''' OR MMF.ID IN (SELECT * from dbo.fnSplitString( @ManufacturerName,'','')))    
AND(@ProductName = '''' OR MP.ID IN (SELECT * from dbo.fnSplitString (@ProductName,'',''))) ) SRI    
GROUP BY SRI.ID,SRI.[Product Code],SRI.[Product Name],SRI.EAN,SRI.[Manuf Name]     
END   
    
ELSE IF (@Type = 2)    
BEGIN    
    
 SELECT SRI.ID, @Fromdate as [From],@ToDate as [To],@Type AS [GNAmount],SRI.[Product Code],SRI.[Product Name],    
SRI.EAN,SRI.[Manuf Name] [Mfr Name],dbo.fnGetRoundedValue(SUM(SRI.[Sales Qty])) AS [Sales Qty],    
dbo.fnGetRoundedValue(SUM(SRI.[Base Qty]))  AS [Base Qty],    
dbo.fnGetRoundedValue(SUM(SRI.[Purchase Price] * SRI.[Base Qty])) AS [Purchase Price],    
dbo.fnGetRoundedValue(SUM(SRI.[Sale Price])) AS [Sale Price],    
dbo.fnGetRoundedValue(ISNULL(SUM((SRI.[Sale Price]) - (SRI.[Purchase Price] * (SRI.[Base Qty]))),0)) AS [Margin Amount],    
dbo.fnGetRoundedValue(ISNULL((SUM((SRI.[Sale Price]) - (SRI.[Purchase Price] * (SRI.[Base Qty]))))/Case when (SUM(SRI.[Purchase Price] * (SRI.[Base Qty])))=0 then 1 else (SUM(SRI.[Purchase Price] * (SRI.[Base Qty])))end  *100 ,0)) as [Margin %]    
FROM    
(    
SELECT MP.ID,@Fromdate as [From],@ToDate as [To],@Type AS [GNAmount],MP.Code AS [Product Code],MP.Name AS [product Name],MP.EAN,    
MMF.Name AS [Manuf Name],(TSD.UomQty) AS [Sales Qty],(TSD.UomQty) AS [Base Qty],    
(MP.PurchasePrice + (MP.PurchasePrice * PIN.TaxValue / 100)) AS [Purchase Price],    
(TSD.NetAmt) AS [Sale Price]    
    
FROM tblTranSalesDetail AS TSD    
JOIN tblTranSalesHeader AS TSH ON TSH.ID = TSD.InvId    
LEFT JOIN tblMasterProduct AS MP ON MP.ID = TSD.ProdId    
LEFT JOIN tblMasterManufacturer AS MMF ON MMF.ID = MP.MfrID    
LEFT JOIN tblProductInventory AS PIN ON PIN.InventoryId = TSD.InventoryId    
WHERE TSH.INVDate BETWEEN @Fromdate AND @ToDate AND TSH.Status IN (1,3,5) AND TSH.DocPrefix=15    
AND(@ManufacturerName = '''' OR MMF.ID IN (SELECT * from dbo.fnSplitString (@ManufacturerName,'','')))    
AND(@ProductName = '''' OR MP.ID IN (SELECT * from dbo.fnSplitString (@ProductName,'',''))) )SRI    
GROUP BY SRI.ID,SRI.[Product Code],SRI.[Product Name],SRI.EAN,SRI.[Manuf Name]     
END    
END',
N'[export] nocount';
GO
/****** uspRepMobileCollectionDetail ******/
EXEC #Apply07 N'dbo.uspRepMobileCollectionDetail', 0xC3A60C6F21D12F1924D71597049E24F7F5484E287801430F3A390A01D729338F, NULL, NULL, 0x465888820DF70887C5914E637625AA1DD700F4A8877EEE57C6251A62D3B05022, 0x82EDE34D18C1F76D50FFE8DC082FDC4B8143F36E01D686E2DD19A8A62B118864, NULL,
N'--uspRepMobileCollectionDetail 19
ALTER PROCEDURE [dbo].[uspRepMobileCollectionDetail]
@ID INT

AS 
SET NOCOUNT ON;
BEGIN

SELECT ID,DS.TransName[Trans Name], 
CASE 
WHEN InvDocPrefix = 15 THEN (SELECT DocID FROM tblTranSalesHeader WHERE ID=InvoiceID)
WHEN InvDocPrefix = 6 THEN (SELECT DocID FROM tblTranPRVoucher WHERE ID=InvoiceID)END AS [Doc ID],
CONVERT(NVARCHAR,CASE 
WHEN InvDocPrefix = 15 THEN (SELECT FORMAT(InvDate,''dd/MMM/yyyy'') FROM tblTranSalesHeader WHERE ID=InvoiceID)
WHEN InvDocPrefix = 6 THEN (SELECT FORMAT(DocDate,''dd/MMM/yyyy'') FROM tblTranPRVoucher WHERE ID=InvoiceID) END) AS [Doc Date],
CASE 
WHEN InvDocPrefix = 15 THEN (SELECT DocRef FROM tblTranSalesHeader WHERE ID=InvoiceID)
WHEN InvDocPrefix = 6 THEN (SELECT RefNo FROM tblTranPRVoucher WHERE ID = InvoiceID) END AS [Ref No],

dbo.fnGetRoundedValue(InvoiceAmt) [Invoice Amount],dbo.fnGetRoundedValue(InvBalance) [Balance],dbo.fnGetRoundedValue(AdjAmt) [Collected Amount],dbo.fnGetRoundedValue(WriteOff) [Adj Amount(+/-)]
,dbo.fnGetRoundedValue(DiscPern)[Discount %],dbo.fnGetRoundedValue(DiscAmt)[Discount Amount]

FROM tblTranOrderCollectionHeader AS OCH
LEFT JOIN tblTranOrderCollectionDetail OCD on OCD.HID = OCH.ID
LEFT JOIN tblDocumentSeries AS DS ON DS.TransID = OCD.InvDocPrefix
WHERE OCH.ID = @ID

END',
N'[export] nocount';
GO
/****** uspRepMobileCollectionHeader ******/
EXEC #Apply07 N'dbo.uspRepMobileCollectionHeader', 0x6C3E9929652ACD5FCE2F8AC1012EB70EE71A4C7794CE2DDC6ECB00640E1ADC2C, NULL, NULL, 0xBD9B97F880DDE9E732B550A57F6D431E64333E09E6415D168B5636A1D3EBC21F, 0x768AA4F410B53B306B8753F0AE36D643A0BAC1ED7CE088A7D2CF09A01EB2E2A9, NULL,
N'--uspRepMobileCollectionHeader ''4'',''2024-04-02'',''2025-12-01''  
ALTER PROCEDURE [dbo].[uspRepMobileCollectionHeader]  
@Status NVARCHAR(50)=NULL,  
@FromDate DATE=NULL,  
@ToDate DATE=NULL  
AS  
SET NOCOUNT ON;
BEGIN  
DECLARE @Sts AS TABLE(Status INT)    
IF(@Status = 0)    
BEGIN    
INSERT INTO @Sts values (1),(8),(4)    
END    
ELSE              
BEGIN              
INSERT INTO @Sts values(@Status)              
END   
  
  
SELECT TCH.ID[ID],MBO.Name as [Branch Name], FORMAT(TCH.DocDate,''dd/MMM/yyyy'')[DocDate], MB.Name[Beat Name],MS.Name[Salesman Name], MC.Code[Customer Code],  
MC.Name[Customer Name],PM.PaymentMode[Payment Mode], TCH.ChequeNo[Cheque/NEFT No],   
FORMAT(TCH.ChequeDate,''dd/MMM/yyyy'')[Cheque/NEFT No Date],dbo.fnGetRoundedValue(TCH.Amt) [Collected Amt],  
dbo.fnGetRoundedValue(SUM(TCD.AdjAmt)) [Total Adj Amount],  
CU.UserName AS [Created By],  CONVERT(NVARCHAR,TCH.CDate) AS [Created Date],  MU.UserName AS [Cancel By],    
CONVERT(NVARCHAR,TCH.ClDate) AS [Cancel Date],TCH.Remarks[Remarks], TCH.Narration[Narration], S.Description[Status]  
FROM tblTranOrderCollectionHeader TCH  
LEFT JOIN tblTranOrderCollectionDetail TCD on TCD.HID = TCH.ID  
LEFT JOIN tblMasterBeat MB on MB.ID = TCH.BeatID  
LEFT JOIN tblMasterSalesman MS on MS.ID = TCH.SalesManID  
left join tblMasterBranchOffice MBO on MBO.ID = TCH.BranchID
JOIN tblMasterCustomer MC on MC.ID = TCH.CustID  
JOIN tblPaymentMode PM on PM.ID = TCH.PaymentID  
JOIN tblUsers CU  ON CU.ID = TCH.CBy    
LEFT JOIN tblUsers MU  ON MU.ID = TCH.ClBy   
JOIN tblStatus S on S.ID = TCH.Status  
WHERE TCH.DocDate BETWEEN @FromDate AND @ToDate   
AND TCH.Status in (select * from @Sts)   
GROUP BY  
    TCH.ID, TCH.DocDate, MB.Name, MS.Name, MC.Code, MC.Name,MBO.Name,  
    PM.PaymentMode, TCH.ChequeNo, TCH.ChequeDate,Amt,  
    CU.UserName, S.Description, TCH.CDate, MU.UserName, TCH.ClDate,TCH.Remarks,TCH.Narration  
ORDER BY TCH.ID;  
  
  
END',
N'[export] nocount';
GO
/****** uspRepMobileReturnDetail ******/
EXEC #Apply07 N'dbo.uspRepMobileReturnDetail', 0x67F34EFF03FC0E0365B77250440970AA6211EE8B6B6CAB754735D25BE31D947B, NULL, NULL, 0x85B061411AB5230F27BF0B79ECCE1F92BED9A4F34A1CC36B534DFED4A80382B2, 0xBAE13AD5B728C136559A849C8315DAFC2F872365C4E242FC8D04EBD9CFD76EAA, NULL,
N'ALTER PROCEDURE [dbo].[uspRepMobileReturnDetail]
@ReturnID INT
AS
SET NOCOUNT ON;
BEGIN
SELECT ''WR''+ CAST(ORD.ID AS NVARCHAR(10))[Doc ID],  MP.Name[Product Name],MP.Code[Product Code],  dbo.fnGetRoundedValue(SUM(ORD.Price)) AS [Price], dbo.fnGetRoundedValue(SUM(ORD.Qty)) AS [QTY],
dbo.fnGetRoundedValue(SUM(ORD.DisPern)) AS [DisPern], dbo.fnGetRoundedValue(SUM(ORD.DisAmt)) AS [DisAmt],
dbo.fnGetRoundedValue(SUM(ORD.Amount)) AS [Amount], dbo.fnGetRoundedValue(SUM(ORD.MRP)) AS [MRP]
