/****** uspRepOrderTakenHeader ******/
EXEC #Apply07 N'dbo.uspRepOrderTakenHeader', 0x0EBA54D293E3F4C8B81BE1D3D47E4E193B795F450F28150CEABE02FFB384AD77, NULL, NULL, 0xC781F2BD70430F7CDF7D4EBCD485AA7ADE4CF2C6FABC06ACFCB89E478965A1A4, 0xE94D35726F3EB50D254FBF88DD4CF7B8D1C6B95D28579B43DBAA7EAC56663D5E, NULL,
N'--uspRepOrderTakenHeader ''0'',''2024-04-02'',''2026-12-01''   
ALTER PROCEDURE [dbo].[uspRepOrderTakenHeader]  
@Status NVARCHAR(50)=NULL,    
@FromDate DATE=NULL,    
@ToDate DATE=NULL    
AS    
SET NOCOUNT ON;
BEGIN    
DECLARE @Sts AS TABLE(Status INT)      
IF(@Status = 0)      
BEGIN      
INSERT INTO @Sts values (1),(2),(3),(8),(4)
END      
ELSE                
BEGIN                
INSERT INTO @Sts values(@Status)                
END   
  
SELECT OTH.ID[ID], TSH.DocID[Invoice No],  
CASE  
WHEN OTH.ActivityID = 1 THEN ''Order Taken''  
WHEN OTH.ActivityID = 2 THEN ''Feedback''  
WHEN OTH.ActivityID = 3 THEN ''No Order''END[Activity Name],  
MBO.Name[Branch Name], FORMAT (OTH.DocDate,''dd/MMM/yyy'')[Doc Date],   
MB.Name[Beat Name],MS.Name[Salesman Name], MC.Code[Customer Code],MC.Name[Customer Name],  
dbo.fnGetRoundedValue(SUM(OTD.Price * OTD.Qty)) [Net Amount],  
dbo.fnGetRoundedValue(SUM(OTD.DisAmt))[Product Discount Amount],  
dbo.fnGetRoundedValue(OTH.AdDiscPern)[AD Discount %],dbo.fnGetRoundedValue(OTH.TrDiscPern)[TR Discount %],  
OTH.FeedBack[FeedBack], OTH.Narration[Narration], S.Description[Status],CU.UserName AS [Created By],  CONVERT(NVARCHAR,OTH.CDate) AS [Created Date]  
,MU.UserName AS [Modify By],    CONVERT(NVARCHAR,OTH.MDate) AS [Modified Date],  CL.UserName AS [Cancel By],CONVERT(NVARCHAR,OTH.ClDate) AS [Cancel Date]  
  
FROM tblTranOrderTakenHeader OTH  
LEFT JOIN tblTranOrderTakenDetail OTD ON OTD.ID = OTH.ID  
LEFT JOIN tblMasterBeat MB ON MB.ID = OTH.BeatID  
JOIN tblMasterCustomer MC ON MC.ID = OTH.CustID  
LEFT JOIN tblMasterSalesman MS ON MS.ID = OTH.SalesManID  
JOIN tblMasterBranchOffice MBO ON MBO.ID = OTH.BranchID  
JOIN tblUsers CU  ON CU.ID = OTH.CBy      
LEFT JOIN tblUsers MU  ON MU.ID = OTH.MBy  
LEFT JOIN tblUsers CL  ON CL.ID = OTH.ClBy     
JOIN tblStatus S on S.ID = OTH.Status    
LEFT JOIN tblTranSalesHeader TSH ON TSH.ID = OTH.InvoiceID  
WHERE OTH.DocDate BETWEEN @FromDate AND @ToDate     
AND OTH.Status in (select * from @Sts)   
Group By OTH.ID,TSH.DocID,MBO.Name, OTH.DocDate,MB.Name,MS.Name,MC.Code,MC.Name,CU.UserName, OTH.CDate, MU.UserName,OTH.MDate,  
S.Description,CL.UserName,OTH.ClDate,OTH.AdDiscPern,OTH.TrDiscPern,OTH.FeedBack,OTH.Narration,OTH.ActivityID  
ORDER BY OTH.ID;  
  
END',
N'[export] nocount';
GO
/****** uspReportPermission ******/
EXEC #Apply07 N'dbo.uspReportPermission', 0xBF2E839D97A7AC0E11B97DD696DF2017F1D0C4C2E9FCAC0716014DA208644A23, NULL, NULL, 0xDF96AC4CE7E80E6A79107BC3069C12A78C0F339BF4E5965F04AB2F71C24E140C, 0xB5C729387856B44B73B0BA3548BABC74FEBB73E3A60EA889F3C2B5FDFD1DCF6C, NULL,
N'--[uspReportPermission] 2,2,2,0                    
ALTER PROCEDURE [dbo].[uspReportPermission]                          
@Mode INT,@RoleID INT = NULL,@UserID INT=1,@WeborMobile int = 0
AS                                        
SET NOCOUNT ON;
BEGIN                               
create table #tempFavPar(idx tinyint,ReportID smallint,ReportName nvarchar(255),ParentId smallint,      
LocationName  nvarchar(255),ProcedureName  nvarchar(255),DisplayIndex smallint)      
      
DECLARE @PERMISSION AS TABLE (USERID INT)                                            
INSERT INTO @PERMISSION SELECT PermissionFormId FROM tblRolePermissions WHERE Role=@RoleID            
IF ISNULL(@Mode,0)=1                          
BEGIn                          
IF isnull(@RoleID,0) = 1 AND ISNULL(@UserID,0) = 1                    
BEGIN      
      
if exists(select * from tblMenus where IsReport = 1 and Favourite = 1)      
begin      
insert into #tempFavPar values(1,(select max(ReportID) + 1 from tblReportViewer where IsMobileReport = @WeborMobile),''Favourite'',0,''Reports'',null,0)      
end      
      
SELECT 2 idx,ReportID,ReportName,ParentId,''Reports'' LocationName,ProcedureName,MM.DisplayIndex            
FROM tblReportViewer RV      
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE ParentId=0 and IsMobileReport = @WeborMobile
union all      
SELECT * from #tempFavPar      
ORDER BY idx,ParentID,DisplayIndex,ReportName ASC                      
      
END                            
ELSE          
BEGIN          
      
if exists(SELECT * FROM tblReportViewer RV      
JOIN tblMenus MM ON MM.MenuId = RV.MenuID       
WHERE RV.Active = 1  and IsMobileReport = @WeborMobile and RV.MenuId IN (SELECT * FROM @PERMISSION) AND RV.MenuId IN (            
SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2) AND IsReport = 1 and Favourite = 1)      
begin      
insert into #tempFavPar values(1,(select max(ReportID) + 1 from tblReportViewer where  IsMobileReport = @WeborMobile),''Favourite'',0,''Reports'',null,0)      
end      
      
SELECT ReportID,ReportName,ParentId,LocationName,ProcedureName FROM (      
SELECT 2 idx,ReportID,ReportName,ParentId,''Reports'' LocationName,ProcedureName,MM.DisplayIndex            
FROM tblReportViewer RV      
JOIN tblMenus MM ON MM.MenuId = RV.MenuID      
WHERE ParentId=0  and IsMobileReport = @WeborMobile and RV.Active = CASE WHEN @RoleID = 1 THEN RV.Active ELSE 1 END      
and RV.MenuId IN (SELECT * FROM @PERMISSION) AND RV.MenuId IN (            
SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2)      
UNION ALL      
SELECT * from #tempFavPar      
) AS REC      
ORDER BY idx,ParentID,DisplayIndex,ReportName ASC           
END          
END          
ELSE                          
BEGIn                          
IF isnull(@RoleID,0) = 1 AND ISNULL(@UserID,0) = 1                    
BEGIN                  
select ReportID,ReportName,ParentId,LocationName,ProcedureName from (      
SELECT 2 idx,ReportID,ReportName,ParentId,''Reports'' LocationName,ProcedureName,MM.DisplayIndex            
FROM tblReportViewer RV      
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE ParentId!=0  and IsMobileReport = @WeborMobile      
union all      
SELECT 1 idx,ReportID,ReportName,(select max(ReportID) + 1 from tblReportViewer where IsMobileReport = @WeborMobile),''Favourite'' LocationName,ProcedureName,MM.DisplayIndex            
FROM tblReportViewer RV      
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE ParentId!=0  and IsMobileReport = @WeborMobile AND MM.IsReport = 1 AND MM.Favourite = 1) as rec      
ORDER BY idx,DisplayIndex,ParentID,ReportName ASC                      
END                            
ELSE                            
BEGIN                 
select * from (      
SELECT 2 idx,ReportID,ReportName,ParentId,''Reports'' LocationName,ProcedureName,mm.DisplayIndex           
FROM tblReportViewer RV      
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE ParentId!=0  and IsMobileReport = @WeborMobile and RV.Active = 1 and RV.MenuId IN (SELECT * FROM @PERMISSION) AND       
RV.MenuId IN (SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2)      
UNION ALL      
SELECT 1 idx,ReportID,ReportName,(select max(ReportID) + 1 from tblReportViewer where IsMobileReport = @WeborMobile),''Favourite'' LocationName,ProcedureName,0 DisplayIndex           
FROM tblReportViewer RV      
JOIN tblMenus MM ON MM.MenuId = RV.MenuID WHERE (ParentId!=0  and IsMobileReport = @WeborMobile and RV.Active = 1 and RV.MenuId IN (SELECT * FROM @PERMISSION) AND       
RV.MenuId IN (SELECT PermissionFormId FROM tblRolePermissions WHERE Role = 2)) AND MM.IsReport = 1 AND MM.Favourite = 1      
      
  ) as rec      
ORDER BY idx,ParentID,DisplayIndex,ReportName ASC               
END                                      
END                
drop table #tempFavPar      
END',
N'[export] nocount';
GO
/****** uspReportScript ******/
EXEC #Apply07 N'dbo.uspReportScript', 0xDE26BAF4DE3DA98651F25E98D182827586EA3484F213D75EB42CEA3C2B52819E, 0x2E7C7E340E438B970B49535FCB5B40728A99F4876259E66F85DE2C1FF699352A, NULL, 0xD56937E5FFD767A5DE1D589A0ED13D971B0B287BDD25EA4942597B2932B16862, 0x0F83071A05C13EE3C0FB8465871C53B8638A66A127EA6B264B9245FE5B01D4AA, NULL,
N'--    
-- Security fix: sp_helptext is called directly with the procedure name instead of through EXEC() of a concatenated string.
ALTER PROCEDURE [dbo].[uspReportScript]          
@Mode INT = 1,@ReportID INT = 16          
AS          
SET NOCOUNT ON;
BEGIN          
DECLARE @MenuId int          
Set @MenuId = (Select MenuID from tblReportViewer where ReportId = @ReportID)          
          
IF ISNULL(@Mode,0)=1 -- Menu permission           
BEGIN          
IF ISNULL((SELECT COUNT(*) FROM tblReportViewer WHERE ReportId = @ReportID),0) > 0          
BEGIN          
Select ''IF (SELECT COUNT(*) FROM tblMenus WHERE MenuId = ''+Convert(nvarchar,@MenuId)+'') = 0''          
UNION all          
Select ''BEGIN''          
UNION ALL          
SELECT          
''INSERT INTO [dbo].[tblMenus]          
([MenuId],[MenuName],[MenuParentId],[MenuChildLevel],[MenuTree],[LocationName],          
[Permission],[Active],[DisplayIndex],[IsMenu],[FormID],[IsReport],          
[EncMenuID],[EncMenuName],[EncFormID],[IsMobileApp],Favourite,IsFincancialReport)          
VALUES ('' +          
'''''''' + CONVERT(NVARCHAR(MAX),MenuId) + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),MenuName),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),MenuParentId),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),MenuChildLevel),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),MenuTree),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),LocationName),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),Permission),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),Active),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),DisplayIndex),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),IsMenu),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),FormID),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),IsReport),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),EncMenuID),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),EncMenuName),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),EncFormID),'''') + '''''','' +          
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),IsMobileApp),'''') + '''''',0,0)''          
FROM tblMenus          
WHERE MenuId IN (SELECT MenuID FROM tblReportViewer WHERE ReportId=@ReportID)          
UNION ALL          
Select ''END''          
          
END          
END          
else IF ISNULL(@Mode,0)=2 -- report permission          
BEGIN          
IF ISNULL((SELECT COUNT(*) FROM tblReportViewer WHERE ReportId = @ReportID),0) > 0          
BEGIN          
SELECT ''DELETE tblReportViewer WHERE ReportId = ''+CONVERT(NVARCHAR,@ReportID)+''''          
UNION ALL          
SELECT           
    ''INSERT INTO [dbo].[tblReportViewer]          
    ([ReportID],[ReportName],[ParentID],[Active],[MenuID],          
     [ProcedureName],[DetailProcedureName],[Frames],[SendFiltersDetail],[IsDynamicReport])           
    VALUES ('' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ReportID),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ReportName),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ParentID),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),Active),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),MenuID),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ProcedureName),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),DetailProcedureName),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),Frames),'''') + '''''','' +          
 '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),SendFiltersDetail),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),IsDynamicReport),'''') + '''''')''          
FROM tblReportViewer          
WHERE ReportID = @ReportID          
END          
END          
ELSE IF ISNULL(@Mode,0)=3 -- report columns          
BEGIN          
IF ISNULL((SELECT COUNT(*) FROM tblColumnSettings WHERE FormorReport = 1 and FormID = @ReportID),0) > 0          
BEGIN          
SELECT ''DELETE tblColumnSettings WHERE  FormorReport = 1 and FormID = ''+CONVERT(NVARCHAR,@ReportID)+''''          
UNION ALL          
  
  
SELECT           
''INSERT INTO [dbo].[tblColumnSettings]      (FormID,FormName,FormorReport,TableID,ColumnID,ColumnName,DisplayColumnName,Width,Visible,Alignment,DisplayIndex,      
IsHiddenColumn,Total,TotalYN,EnableSum,EnableAvg,ClickPopup,EnableColumnMenu,ShowinColumnOption,OriginalColumnName,      
PrintYN,PrintColumnName,PrintWidth,EnableCount,EnableUnique,ColumnType,Permission)      
VALUES ('' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),FormID),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),FormName),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),FormorReport),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),TableID),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ColumnID),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ColumnName),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),DisplayColumnName),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),Width),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),Visible),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),Alignment),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),DisplayIndex),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),IsHiddenColumn),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),Total),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),TotalYN),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),EnableSum),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),EnableAvg),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ClickPopup),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),EnableColumnMenu),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ShowinColumnOption),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),OriginalColumnName),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),PrintYN),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),PrintColumnName),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),PrintWidth),'''') + '''''','' +     
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),EnableCount),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),EnableUnique),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ColumnType),'''') + '''''','' +      
'''''''' + ISNULL(CONVERT(NVARCHAR(MAX),Permission),'''') + '''''')''      
FROM tblColumnSettings          
WHERE FormorReport = 1 and FormID = @ReportID;      
END          
END          
ELSE IF ISNULL(@Mode,0)=4 -- report parameters          
BEGIN          
SELECT ''DELETE tblParameterInfo WHERE ReportId = ''+CONVERT(NVARCHAR,@ReportID)+''''          
UNION ALL           
SELECT '' SET IDENTITY_INSERT [dbo].[tblParameterInfo] ON  ''          
UNION ALL          
SELECT           
    ''          
 INSERT INTO [dbo].[tblParameterInfo]          
    ([ParameterID],[ReportID],[ParameterName],[ParameterType],[IsMandatory],[ParamOrder],[AutolistName])           
    VALUES ('' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ParameterID),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ReportID),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ParameterName),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ParameterType),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),IsMandatory),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),ParamOrder),'''') + '''''','' +          
    '''''''' + ISNULL(CONVERT(NVARCHAR(MAX),AutolistName),'''') + '''''')          
 ''          
FROM tblParameterInfo          
WHERE ReportID = @ReportID          
UNION ALL          
SELECT '' SET IDENTITY_INSERT [dbo].[tblParameterInfo] OFF  ''          
END          
ELSE IF ISNULL(@Mode,0)=5 -- Header Procedure script          
BEGIN          
DECLARE @tempHeader TABLE (H_Data NVARCHAR(MAX))          
DECLARE @SpHeader NVARCHAR(255) = (SELECT ProcedureName FROM tblReportViewer WHERE ReportId=@ReportID)          
-- (was: EXEC of ''SP_HELPTEXT ''+@SpHeader in an NVARCHAR(50) buffer)          
INSERT INTO @tempHeader EXEC sys.sp_helptext @SpHeader          
          
SELECT ''IF EXISTS (SELECT * FROM sys.objects WHERE type=''''P'''' AND name=''''''+@SpHeader+'''''')''          
UNION ALL          
SELECT ''BEGIN''          
UNION ALL      
SELECT ''DROP PROC ''+@SpHeader+''''          
UNION ALL          
SELECT ''END''          
UNION ALL          
SELECT ''GO''          
UNION ALL          
SELECT H_Data FROM @tempHeader          
UNION ALL          
SELECT ''GO''          
END          
ELSE IF ISNULL(@Mode,0)=6 -- Detail Procedure script          
BEGIN          
DECLARE @tempFooter TABLE (F_Data NVARCHAR(MAX))          
DECLARE @SpFooter NVARCHAR(255) = (SELECT DetailProcedureName FROM tblReportViewer WHERE ReportId=@ReportID)          
IF ISNULL(@SpFooter,'''')!=''''          
BEGIN          
-- (was: EXEC of ''SP_HELPTEXT ''+@SpFooter in an NVARCHAR(50) buffer)          
INSERT INTO @tempFooter EXEC sys.sp_helptext @SpFooter          
          
SELECT ''IF EXISTS (SELECT * FROM sys.objects WHERE type=''''P'''' AND name=''''''+@SpFooter+'''''')''          
UNION ALL          
SELECT ''BEGIN''          
UNION ALL          
SELECT ''DROP PROC ''+@SpFooter+''''          
UNION ALL          
SELECT ''END''          
UNION ALL          
SELECT ''GO''          
UNION ALL          
SELECT F_Data FROM @tempFooter          
END          
ELSE          
BEGIN          
SELECT F_Data FROM @tempFooter          
END          
END          
END',
N'[06] nocount';
GO
/****** uspRepPayableVoucherHeader ******/
EXEC #Apply07 N'dbo.uspRepPayableVoucherHeader', 0x9F22921AC71D1A85F7EE6B294E4A970D8739F0C8B4048349BEC655D0106B71C6, NULL, NULL, 0x349C33436358ABA706EC776C5C0C1C588087505A4697B82211F873AE2A40912C, 0xCB51512FE5A87571DA47CBDB733C9783A735BEE2572068C865308BBE37E7D718, NULL,
N'ALTER procedure [dbo].[uspRepPayableVoucherHeader]  
@StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2024-01-01'',@ToDate DATE =''2026-09-30'', @TransID INT = 6  
AS    
SET NOCOUNT ON;
BEGIN    
DECLARE @Sts AS TABLE(Status INT)    
IF(@StatusID = 0)    
BEGIN    
INSERT INTO @Sts values (1),(3),(5)    
END    
ELSE    
BEGIN     
INSERT INTO @Sts values(@StatusID)    
END    
  
select   
 PRD.ID[ID],PRD.DocID[Doc ID],FORMAT(PRD.DocDate, ''dd/MMM/yyyy'') AS [Doc Date],PRD.RefNo[Ref No],  
 FPV.AccountName[Party Name],FAV.AccountName,PRD.SACorHSNCode[SAC/HSN Code],MTT.TaxName[Tax Name],  
 dbo.fnGetRoundedValue(PRD.Amount)[Amount],PRD.DiscPern[Disc %],dbo.fnGetRoundedValue(PRD.DiscAmt)[Disc Amount],dbo.fnGetRoundedValue(PRD.RoundoffAmt)[RoundOff Amount],  
 dbo.fnGetRoundedValue(PRD.GrossAmount)[Gross Amount],dbo.fnGetRoundedValue(PRD.TaxtAmount)[Tax Amount], dbo.fnGetRoundedValue(PRD.NetAmount)[Net Amount],  
 PRD.Remarks[Remarks], PRD.Narration[Narration],SS.Description[Status],CU.UserName AS [Created By],  
 CONVERT(NVARCHAR, PRD.CDate) AS [Create Date],  MU.UserName AS [Modified By],  
 CONVERT(NVARCHAR, PRD.MDate) AS [Modify Date]  
  
  
 from tblTranPRVoucher PRD  
 LEFT JOIN tblFAAccount FPV on FPV.FAID = PRD.PartyID  
  LEFT JOIN tblFAAccount FAV on FAV.FAID = PRD.FAID  
  LEFT JOIN tblMasterTax MTT on MTT.TaxID = PRD.TaxID  
   LEFT JOIN tblUsers CU  ON CU.ID = PRD.CBy    
    LEFT JOIN tblUsers MU  ON MU.ID = PRD.MBy   
 LEFT JOIN tblStatus SS on SS.ID = PRD.Status  
    WHERE PRD.DocDate BETWEEN @FromDate AND @ToDate  
      AND PRD.Status IN (SELECT Status FROM @Sts)  
   AND (@TransID IS NULL OR PRD.TransID = @TransID);  
END',
N'[export] nocount';
GO
/****** uspRepPaymentmodeAnalysisDetail ******/
EXEC #Apply07 N'dbo.uspRepPaymentmodeAnalysisDetail', 0x844C1769E57620FD834B1B7396EA2FBC64C202EC162EBC50DDD142C713382E95, NULL, NULL, 0x8B7DF016B1F6A601B14C8C0B6538EE9381FE32218EF320650FFA777D72BADAAB, 0xB815B6F16B4A57E637626BE2600AD4F6C63C6624288F56BFC0374039827D9F4A, NULL,
N'ALTER proc [dbo].[uspRepPaymentmodeAnalysisDetail]
@Date date = ''2025-12-18'',@PaymentMode int = 0
as
SET NOCOUNT ON;
begin
select DS.TransName [Transaction],CH.DocID [Doc ID],FORMAT(CH.ColDate,''dd-MMM-yyyy'') [Doc Date],
CASE WHEN COLLType IN (0,1,3) THEN ACC.AccountName WHEN COLLType = 2 THEN EXPACC.AccountName ELSE '''' END [Party/Account Name],
ColDocRefNo [Ref No],PM.PaymentMode [Payment Mode],dbo.fngetroundedvalue(SUM(ColAmt)) Amount,
dbo.fngetroundedvalue(SUM(Balance)) Balance,MBA.AccountNo [Account No],
COLLPM.[Cheque/DD Number],NeftID [Bank Ref No],
FORMAT(COLLPM.Date,''dd-MMM-yyyy'') [PM Date],COLLPM.IfscCode IFSC,COLLPM.BankName [Bank Name],COLLPM.BranchName [Branch Name],
CH.Remarks,CH.Narration
from tblTranCollectionHeader CH 
JOIN tblDocumentSeries DS ON DS.TransID = CH.DocPrefix
JOIN tblPaymentMode PM ON PM.ID = CH.ColMode
LEFT JOIN tblFAAccount ACC ON ACC.FAID = CH.AccID
LEFT JOIN tblFAAccount EXPACC ON EXPACC.FAID = CH.ExpanceAcc
LEFT JOIN tblCollPMDetails COLLPM ON COLLPM.ColID = CH.ColID
LEFT JOIN tblMasterBankAccount MBA ON MBA.FAID = COLLPM.BankAccID
WHERE CH.Status IN (1,3,5) AND CH.ColDate = @Date
and CH.ColMode = (case when @PaymentMode > 0 THEN @PaymentMode ELSE CH.ColMode END)
GROUP BY CH.DocID,CH.ColDate,DS.TransName ,ColDocRefNo,PM.PaymentMode,ACC.AccountName,EXPACC.AccountName,COLLType,MBA.AccountNo
,COLLPM.IfscCode,COLLPM.BankName,COLLPM.BranchName,COLLPM.Date,COLLPM.[Cheque/DD Number],NeftID,CH.Remarks,CH.Narration
UNION ALL
select DS.TransName [Transaction],CH.DocID [Doc ID],FORMAT(CH.PYDate,''dd-MMM-yyyy'') [Doc Date],
CASE WHEN PYType IN (0,1,3) THEN ACC.AccountName WHEN PYType = 2 THEN EXPACC.AccountName ELSE '''' END [Party/Account Name],
PYDocRefNo [Ref No],PM.PaymentMode [Payment Mode],dbo.fngetroundedvalue(SUM(CH.PYAmt)) Amount,
dbo.fngetroundedvalue(SUM(Balance)) Balance,MBA.AccountNo [Account No],
COLLPM.[Cheque/DD Number],NeftID [Bank Ref No],
FORMAT(COLLPM.Date,''dd-MMM-yyyy'') [PM Date],COLLPM.IfscCode IFSC,COLLPM.BankName [Bank Name],COLLPM.BranchName [Branch Name],CH.Remarks,CH.Narration
from tblTranPaymentHeader CH 
JOIN tblDocumentSeries DS ON DS.TransID = CH.PYPrefix
JOIN tblPaymentMode PM ON PM.ID = CH.PYMode
LEFT JOIN tblFAAccount ACC ON ACC.FAID = CH.AccID
LEFT JOIN tblFAAccount EXPACC ON EXPACC.FAID = CH.ExpanseAcc
LEFT JOIN tblPaymentPMDetail COLLPM ON COLLPM.PYID = CH.PYID
LEFT JOIN tblMasterBankAccount MBA ON MBA.FAID = COLLPM.BankAccID
WHERE CH.Status IN (1,3,5) AND CH.PYDate = @Date
and CH.PYMode = (case when @PaymentMode > 0 THEN @PaymentMode ELSE CH.PYMode END)
GROUP BY CH.DocID,CH.PYDate,DS.TransName ,PYDocRefNo,PM.PaymentMode,ACC.AccountName,EXPACC.AccountName,PYType,MBA.AccountNo
,COLLPM.IfscCode,COLLPM.BankName,COLLPM.BranchName,COLLPM.Date,COLLPM.[Cheque/DD Number],NeftID,CH.Remarks,CH.Narration
UNION ALL
select DS.TransName [Transaction],CH.DocID [Doc ID],FORMAT(CH.DocDate,''dd-MMM-yyyy'') [Doc Date],
CASE WHEN CH.TypeID IN (1,4) THEN FAFROM.AccountName ELSE MBA.AccountNo END [Account Name],
RefNo [Ref No],PM.TypeName [Payment Mode],dbo.fngetroundedvalue(SUM(CH.Amount)) Amount,dbo.fngetroundedvalue(SUM(Balance)) Balance,MBA.AccountNo [Account No],
CH.ChequeNo [Cheque/DD Number],WDSlipNo [Bank Ref No],
FORMAT(CH.DocDate,''dd-MMM-yyyy'') [PM Date],MBA.IFSCCode IFSC,MB.Name [Bank Name],MBA.BranchName [Branch Name],CH.Remarks,CH.Narration
from tblTranContra CH 
JOIN tblDocumentSeries DS ON DS.TransID = CH.TransID
JOIN tblContraType PM ON PM.ID = CH.TypeID
LEFT JOIN tblFAAccount FAFROM ON FAFROM.FAID = CH.FromFAID
LEFT JOIN tblMasterBankAccount MBA ON MBA.FAID = CH.FromFAID
LEFT JOIN tblMasterBankAccount TOMBA ON TOMBA.FAID = CH.ToFAID
LEFT JOIN tblMasterBank MB ON MB.ID = MBA.BankID
WHERE CH.Status IN (1,3,5) AND CH.DocDate = @Date
--and CH.PYMode = (case when @PaymentMode > 0 THEN @PaymentMode ELSE CH.PYMode END)
GROUP BY CH.DocID,CH.DocDate,DS.TransName ,RefNo,CH.ChequeNo,PM.TypeName,MBA.AccountNo
,CH.Remarks,CH.Narration,WDSlipNo,MBA.IFSCCode,MB.Name,MBA.BranchName,CH.TypeID,FAFROM.AccountName
end',
N'[export] nocount';
GO
/****** uspRepPaymentmodeAnalysisHeader ******/
EXEC #Apply07 N'dbo.uspRepPaymentmodeAnalysisHeader', 0x06735984A0F7AB3D5627E024C66C6D945C8D1C1EB4E4DC22DD786DEE4C93F846, NULL, NULL, 0xB80189B24FC6DB30D09A3A22C6B035C91496E5BAC73AFF447AA5533763FB3668, 0x27B22A2CC3EB48DF4ABCEE61672D4DB5679168529075F91863B09AF2125748CD, NULL,
N'ALTER proc [dbo].[uspRepPaymentmodeAnalysisHeader]  
@PaymentMode int = 1,@FromDate date = ''2025-12-01'',@ToDate date = ''2025-12-31''  
as  
SET NOCOUNT ON;
begin  
select OrgDate,Date,TransName,sum(ColAmt) ColAmt into #temp from (  
select CH.ColDate OrgDate,FORMAT(CH.ColDate,''dd-MMM-yyyy'') Date,DS.TransName,SUM(ColAmt) ColAmt from tblTranCollectionHeader CH  
JOIN tblDocumentSeries DS ON DS.TransID = CH.DocPrefix  
WHERE Status IN (1,3,5) AND CH.ColDate BETWEEN @FromDate AND @ToDate  
and CH.ColMode = (case when @PaymentMode > 0 THEN @PaymentMode ELSE CH.ColMode END)  
GROUP BY CH.ColDate,DS.TransName  
UNION ALL  
select CH.PYDate OrgDate,FORMAT(CH.PYDate,''dd-MMM-yyyy'') Date,DS.TransName,SUM(PYAmt) ColAmt from tblTranPaymentHeader CH  
JOIN tblDocumentSeries DS ON DS.TransID = CH.PYPrefix  
WHERE Status IN (1,3,5) AND CH.PYDate BETWEEN @FromDate AND @ToDate  
and CH.PYMode = (case when @PaymentMode > 0 THEN @PaymentMode ELSE CH.PYMode END)  
GROUP BY CH.PYDate,DS.TransName  
UNION ALL  
select CH.DocDate OrgDate,FORMAT(CH.DocDate,''dd-MMM-yyyy'') Date,DS.TransName,  
case when CH.TypeID = 1 THEN SUM(Amount) * -1 ELSE SUM(Amount) end ColAmt from tblTranContra CH  
JOIN tblDocumentSeries DS ON DS.TransID = CH.TransID  
WHERE Status IN (1,3,5) and CH.TransID = 8 AND CH.DocDate BETWEEN @FromDate AND @ToDate  
and CH.TypeID in (1,2)  
GROUP BY CH.DocDate,DS.TransName,CH.TypeID) as rec  
group by OrgDate,Date,TransName  
ORDER BY Date  


SELECT  
OrgDate,  
@PaymentMode PaymentMode,  
FORMAT(OrgDate, ''dd-MMM-yyyy'') AS [Date],  
dbo.fnGetRoundedValue(ISNULL([Collection] + ISNULL([Other Collection],0), 0)) AS Collection,  
dbo.fnGetRoundedValue(ISNULL([Payment] + ISNULL([Other Payment],0), 0)) AS Payment,  
--dbo.fnGetRoundedValue(ISNULL([Other Collection], 0)) AS [Other Collection],  
--dbo.fnGetRoundedValue(ISNULL([Other Payment], 0)) AS [Other Payment],  
dbo.fnGetRoundedValue(ISNULL([Contra], 0)) AS Contra,  
dbo.fnGetRoundedValue(ISNULL(ISNULL([Collection],0) + ISNULL([Other Collection],0), 0) - ISNULL(ISNULL([Payment],0) + ISNULL([Other Payment],0), 0) + ISNULL([Contra], 0)) AS Balance  
FROM #temp  
PIVOT  
(  
SUM(ColAmt)  
FOR TransName IN ([Collection], [Payment],[Other Collection],[Other Payment], [Contra])  
) p  
ORDER BY OrgDate;  
drop table #temp  
end',
N'[export] nocount';
GO
/****** uspRepReceivableVoucher ******/
EXEC #Apply07 N'dbo.uspRepReceivableVoucher', 0x58AB7822517D8078A22F1A588676977E55AF17E15697C273B5640F4751B0E0A0, NULL, NULL, 0xA4F6B22D3DCB234E29F7C325AFDEE82E3184EFABB71B6468136A1661D65656AE, 0x44E4E04ACEBEB6BEF48400D4E8647D565435AB0C86D586E893F0ECD339BA37F3, NULL,
N'ALTER procedure [dbo].[uspRepReceivableVoucher]  
@StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2024-01-01'',@ToDate DATE =''2026-09-30'', @TransID INT = 7  
AS    
SET NOCOUNT ON;
BEGIN    
DECLARE @Sts AS TABLE(Status INT)    
IF(@StatusID = 0)    
BEGIN    
INSERT INTO @Sts values (1),(3),(5)    
END    
ELSE    
BEGIN     
INSERT INTO @Sts values(@StatusID)    
END    
  
select   
 PRD.ID[ID],PRD.DocID[Doc ID],FORMAT(PRD.DocDate, ''dd/MMM/yyyy'') AS [Doc Date],PRD.RefNo[Ref No],  
 FPV.AccountName[Party Name],FAV.AccountName,PRD.SACorHSNCode[SAC/HSN Code],MTT.TaxName[Tax Name],  
 dbo.fnGetRoundedValue(PRD.Amount)[Amount],PRD.DiscPern[Disc %],dbo.fnGetRoundedValue(PRD.DiscAmt)[Disc Amount],
 dbo.fnGetRoundedValue(PRD.RoundoffAmt)[RoundOff Amount],  
 dbo.fnGetRoundedValue(PRD.GrossAmount)[Gross Amount],dbo.fnGetRoundedValue(PRD.TaxtAmount)[Tax Amount],dbo.fnGetRoundedValue(PRD.NetAmount)[Net Amount],  
 PRD.Remarks[Remarks], PRD.Narration[Narration],SS.Description[Status],CU.UserName AS [Created By],  
 CONVERT(NVARCHAR, PRD.CDate) AS [Create Date],  MU.UserName AS [Modified By],  
 CONVERT(NVARCHAR, PRD.MDate) AS [Modify Date]  
  
  
 from tblTranPRVoucher PRD  
 LEFT JOIN tblFAAccount FPV on FPV.FAID = PRD.PartyID  
  LEFT JOIN tblFAAccount FAV on FAV.FAID = PRD.FAID  
  LEFT JOIN tblMasterTax MTT on MTT.TaxID = PRD.TaxID  
   LEFT JOIN tblUsers CU  ON CU.ID = PRD.CBy    
    LEFT JOIN tblUsers MU  ON MU.ID = PRD.MBy   
 LEFT JOIN tblStatus SS on SS.ID = PRD.Status  
    WHERE PRD.DocDate BETWEEN @FromDate AND @ToDate  
      AND PRD.Status IN (SELECT Status FROM @Sts)  
   AND (@TransID IS NULL OR PRD.TransID = @TransID);  
END',
N'[export] nocount';
GO
/****** UspRepSalesmanVlsClosingHeader ******/
EXEC #Apply07 N'dbo.UspRepSalesmanVlsClosingHeader', 0xFBF766D0DF8655A1ECCA09E5751E8009D409626AF61A63E292302AC0D240B033, NULL, NULL, 0x1D328436C854B05144ABBE92BF2593BABF35706D2C2A8E3F51A9DDBDB5330E61, 0x7E6F7F28C8AB10D65D321D8DF32786C644D2BCB9EDF5BD16805C7BA1C09B194F, NULL,
N'ALTER PROCEDURE [dbo].[UspRepSalesmanVlsClosingHeader]  
@BranchName INT = 0, @SalesmanName nvarchar(255)='''', @MfrName nvarchar(255)='''', @ProductName nvarchar(255)=''''  
AS  
SET NOCOUNT ON;
BEGIN  
SELECT MS.Name[Salesman Name], MP.Code[Product Code], MP.Name[Product Name], dbo.fnGetRoundedValue(TPI.MRPONPrice)[MRP],  
dbo.fnGetRoundedValue( SUM(ISNULL(VLD.UomQty,0) - ISNULL(VLD.VLSMQty,0) + ISNULL(VLD.VLSRetrunQty,0))) [Closing Stock],  
MM.Name[Manufacturer Name]  
FROM tblVanLoadingSlipHeader VLH  
JOIN tblVanLoadingSlipDetail VLD on VLD.ID = VLH.ID  
JOIN tblProductInventory TPI on TPI.InventoryId = VLD.InventoryID  
JOIN tblMasterProduct  MP on MP.ID = VLD.ProdID  
JOIN tblMasterManufacturer MM on MM.ID = MP.MfrID  
JOIN tblMasterSalesman MS on MS.ID = VLH.SalesmanID  
WHERE  
(isnull(@MfrName,'''') = '''' OR MM.ID IN (SELECT * from dbo.fnSplitString(@MfrName,'','')))  
AND (isnull(@SalesmanName,'''') = '''' OR MS.ID IN (SELECT * from dbo.fnSplitString (@SalesmanName,'','')))  
AND (isnull(@ProductName,'''') = '''' OR MP.ID IN (SELECT * from dbo.fnSplitString (@ProductName,'','')))  
AND (@BranchName =0 OR VLH.BranchID = @BranchName)  
GROUP BY MS.Name,MP.Code,MP.Name,TPI.MRPONPrice,MM.Name  
HAVING  SUM(ISNULL(VLD.UomQty,0) - ISNULL(VLD.VLSMQty,0) + ISNULL(VLD.VLSRetrunQty,0)) > 0  
END',
N'[export] nocount';
GO
