/****** uspRepSingleMasterData ******/
EXEC #Apply07 N'dbo.uspRepSingleMasterData', 0x6E161656DD2E38B540C831B33EA2D45CC38DDDE79766D5D31148E1BDFF2C2420, 0x14794B5C12EFD4F076A7715ACA86C6BEF28C924A361F08CB138163580F0DA6A1, NULL, 0x1D70F46A85DD3340A7DEA998C11A46B16E3E0A53585891E121B071CD12C559B9, 0xCB93E1FDD3B19591358F573B481BF0F4743AE5A7F8A1CD18E96B21250051678F, NULL,
N'--uspRepSingleMasterData 1,0
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspRepSingleMasterData]
@FormID int,@UserID INT = 0
AS
SET NOCOUNT ON;
BEGIN
declare @TableName nvarchar(255) = (select TableName from tblTablesNames where ID = @FormID)    
declare @SafeTable NVARCHAR(600) = CASE WHEN OBJECT_ID(@TableName, ''U'') IS NOT NULL THEN QUOTENAME(OBJECT_SCHEMA_NAME(OBJECT_ID(@TableName, ''U''))) + ''.'' + QUOTENAME(OBJECT_NAME(OBJECT_ID(@TableName, ''U''))) END
IF @SafeTable IS NULL AND @TableName IS NOT NULL BEGIN RAISERROR(''Master table for this form was not found.'', 16, 1); RETURN; END
declare @strQuery NVARCHAR(MAX)   
SET @strQuery = '' select Name [Name],case when MB.Active = 1 then ''''Yes'''' ELSE ''''No'''' end Active,  
MU.UserName [Created By],CONVERT(NVARCHAR,MB.CDate) [Create Date],  
MUM.UserName [Modify By],CONVERT(NVARCHAR,MB.MDate) [Modify Date] from ''+@SafeTable+'' MB      
JOIN tblUsers MU ON MU.ID = MB.CBy      
LEFT JOIN tblUsers MUM ON MUM.ID = MB.MBy ''
SET @strQuery += CASE WHEN ISNULL(@UserID,0) = 0 THEN '''' ELSE ''WHERE MB.CBy =  @UserID '' END
SET @strQuery += '' ORDER BY MB.[Name]''                 
EXEC sys.sp_executesql @strQuery, N''@FormID int, @UserID INT'', @FormID, @UserID 
END',
N'[06] nocount';
GO
/****** uspRepStockMovement ******/
EXEC #Apply07 N'dbo.uspRepStockMovement', 0x6355CA16BD678CBB0B19F484D3ABF11A2C41CC41E780EC30B58CC4FEA8604A4B, NULL, NULL, 0x98F79A71CDADB57E813B9AB97A374F35903996BE4713A929820E61F27151EFD6, 0x699EDBF257AB11EF8830268B57D693AA499D3A8A9A7EFC0CD3BD53B132578A14, NULL,
N'--[uspRepStockMovement] 0,'''',''2026-01-01'',''2026-08-31''
ALTER proc [dbo].[uspRepStockMovement]      
@BranchID int = 4,@Product nvarchar(max) = '''',@FromDate DATE = ''2025-04-15'',@ToDate DATE = ''2025-06-15''      
as      
SET NOCOUNT ON;
begin      
select * into #temp from (      
SELECT DS.TransName [Trasaction],BH.DocID [Doc ID],convert(nvarchar(50),BH.Date,106) Date,BO.Name Branch,MP.Code [Product Code],MP.Name [Product Name],      
(CASE WHEN BH.TransID = 1 THEN SUM(PD.UomQty) ELSE SUM(PD.UomQty) * -1 END) Qty,  
(CASE WHEN BH.TransID = 1 THEN SUM(PD.UomFreeQty) ELSE SUM(PD.UomFreeQty) * -1 END) FreeQty,  
(CASE WHEN BH.TransID = 1 THEN SUM(PD.UomDamageQty) ELSE SUM(PD.UomDamageQty) * -1 END) DamageQty FROM tblTransPurchaseHeader BH      
JOIN tblTransPurchaseDetail PD ON PD.HID = BH.ID      
JOIN tblMasterProduct MP ON MP.ID = PD.ProdID      
join tblMasterBranchOffice BO ON BO.ID = BH.BranchID      
JOIN tblDocumentSeries DS ON DS.TransID = BH.TransID      
where Status IN (1,3,5,6) AND Date BETWEEN @FromDate AND @ToDate AND BH.BranchID = (CASE WHEN @BranchID = 0 THEN BH.BranchID ELSE @BranchID END)      
AND (ISNULL(@Product, '''') = '''' OR PD.ProdID IN (SELECT * FROM dbo.fnSplitString(@Product, '','')))    
GROUP BY DS.TransName,BH.TransID,BH.BranchID,BH.DocID,BH.Date,MP.Code,MP.Name,BO.Name      
union all      
SELECT DS.TransName,BH.DocID,convert(nvarchar(50),BH.InvDate,106) Date,BO.Name Branch,MP.Code,MP.Name,      
case when BH.TransactionType = 1 THEN (CASE WHEN BH.DocPrefix = 15 THEN SUM(PD.UomQty * MP.SalesCR)*-1 ELSE SUM(PD.UomQty) END) ELSE 0 END Qty,  
case when BH.TransactionType = 2 THEN (CASE WHEN BH.DocPrefix = 15 THEN SUM(PD.UomQty * MP.SalesCR)*-1 ELSE SUM(PD.UomQty) END) ELSE 0 END FreeQty,  
case when BH.TransactionType = 3 THEN (CASE WHEN BH.DocPrefix = 16 THEN SUM(PD.UomQty * MP.SalesCR)*-1 ELSE SUM(PD.UomQty) END) ELSE 0 END DmgQty FROM tblTransalesheader BH      
JOIN tblTransalesDetail PD ON PD.InvID = BH.ID      
JOIN tblMasterProduct MP ON MP.ID = PD.ProdID      
join tblMasterBranchOffice BO ON BO.ID = BH.BranchID      
JOIN tblDocumentSeries DS ON DS.TransID = BH.DocPrefix      
where Status IN (1,3,5,6,7) AND InvDate BETWEEN @FromDate AND @ToDate  AND BH.BranchID = (CASE WHEN @BranchID = 0 THEN BH.BranchID ELSE @BranchID END)      
AND (ISNULL(@Product, '''') = '''' OR PD.ProdID IN (SELECT * FROM dbo.fnSplitString(@Product, '','')))     
GROUP BY DS.TransName,BH.DocPrefix,BH.BranchID,BH.DocID,BH.InvDate,MP.Code,MP.Name,BO.Name,BH.TransactionType) as rec      
--order by Branch,[Product Name]      
select Trasaction,[Doc ID],Date,Branch,[Product Code],[Product Name],dbo.fnGetRoundedValue(Qty) Qty,  
dbo.fnGetRoundedValue(FreeQty) [Free Qty],dbo.fnGetRoundedValue(DamageQty) [Dmg Qty] from (      
select 1 Idx,* from #temp      
union all      
select 2 Idx,''Total'',null,null,null,null,null,sum(Qty),sum(FreeQty),sum(DamageQty) from #temp) as rec      
order by Idx,Branch,[Product Name]      
drop table #temp      
end',
N'[export] nocount';
GO
