/****** uspRepVanLoadingSlipHeader ******/
EXEC #Apply07 N'dbo.uspRepVanLoadingSlipHeader', 0x64B785E987A85C932AB70A40B67AA21853BDD541CF033392AAC2750B6F357439, NULL, NULL, 0xB136407EBD750A957D91B93E1848A157E570E17067B82C431EAFDA56454B934F, 0xF7794223011427ABAC91C7D9E839A17197FD14DDCA8860FA8F6D2314FF1F7EDD, NULL,
N'--uspRepVanLoadingSlipHeader  , 1, ''2026-01-01'',''2026-12-12''  
ALTER PROCEDURE [dbo].[uspRepVanLoadingSlipHeader]  
@SalesmanName INT,@StatusID NVARCHAR(255)= 0,@FromDate DATE = ''2025-04-01'',@ToDate DATE =''2025-09-30''  
AS  
SET NOCOUNT ON;
BEGIN  
DECLARE @Sts AS TABLE(Status INT)  
IF(@StatusID = 0)  
BEGIN  
INSERT INTO @Sts values (1),(3),(4)  
END  
ELSE  
BEGIN  
INSERT INTO @Sts values(@StatusID)  
END  
SELECT VLH.ID[ID] ,VLH.DocID[Doc ID], FORMAT(VLH.DocDate,''dd/MMM/yyy'')[Doc Date], VLH.RefNo[Ref No], MBO.Name[Branch Name], MS.Name[Salesman Name],  
dbo.fnGetRoundedValue(VLH.GrossAmt)[Gross Amount], dbo.fnGetRoundedValue(VLH.TaxAmt)[Tax Amount],  
dbo.fnGetRoundedValue(VLH.NetAmt)[Net Amount], VLH.EWBNo[EWB No],MV.VehicleNo[Vehicle No],VLH.Distance[Distance], VLH.TransMode[Transport Mode],  
VLH.VehicleType[Vehicle Type], VLH.TransportID[Transport ID], VLH.TransportName[Transport Name], VLH.Remarks, VLH.Narration,S.Description[Status],  
CU.UserName[Created By], VLH.CDate[Created Date]  
FROM tblVanLoadingSlipHeader VLH  
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = VLH.BranchID  
Left JOIN tblMasterSalesman MS on MS.ID = VLH.SalesmanID  
Left JOIN tblMasterVehicle MV on MV.ID = VLH.VehicleNo  
LEFT JOIN tblStatus S on S.ID = VLH.Status  
LEFT JOIN tblUsers CU on CU.ID = VLH.CBy  
WHERE VLH.DocDate BETWEEN @FromDate AND @ToDate AND VLH.Status IN (select * from @Sts)  
AND MS.ID = (CASE WHEN @SalesmanName  = 0 THEN MS.ID ELSE @SalesmanName END)
END',
N'[export] nocount';
GO
