/****** UspRepVlsAbsDetail ******/
EXEC #Apply07 N'dbo.UspRepVlsAbsDetail', 0xD3956BC1B4D0777D3A3D8DA32259A028F3D5A214FBFBD3440362B00A6FEDAAFF, NULL, NULL, 0x13597F962F24223E073CFFCD0CDB572B9FAC8C5A6CE4DA831876E6418C32288B, 0xEDAC4DB5655498412EC3A13A499C946DEF885E61861D0D75A5CC8BFC7DD79FA5, NULL,
N'--UspRepVlsAbsDetail 1  
ALTER  Procedure [dbo].[UspRepVlsAbsDetail]  
@ProductID INT  
AS  
SET NOCOUNT ON;
BEGIN  
--SELECT  [Salesman Name],  
--dbo.fnGetRoundedValue(SUM([VLS Closing])) AS [VLS Closing],  
--dbo.fnGetRoundedValue(SUM([Free Qty])) AS [Free Qty],  
--dbo.fnGetRoundedValue(SUM([Damage Qty])) AS [Damage Qty]  
--FROM (  
--SELECT MS.Name[Salesman Name],SUM((VLD.UomQty)-(VLD.VLSMQty) + (VLD.VLSRetrunQty))[VLS Closing],  
--0 AS [Free Qty], 0 AS [Damage Qty]  
--FROM tblVanLoadingSlipHeader VLH  
--JOIN tblVanLoadingSlipDetail VLD on VLD.ID = VLH.ID  
--JOIN tblMasterSalesman MS on MS.ID = VLH.SalesmanID  
--WHERE VLD.ProdID = @ProductID  
--GROUP BY MS.Name  
--HAVING SUM(VLD.UomQty - VLD.VLSMQty + VLD.VLSRetrunQty) > 0  
--UNION ALL  
--SELECT MS.Name[Salesman Name],0 AS [VLS Closing],SUM(TPI.ActualFreeQty)[Free Qty], SUM(TPI.ActualDmgQty)[Damage Qty]  
--FROM tblProductInventory TPI  
--JOIN tblVanLoadingSlipDetail VLD on VLD.InventoryID = TPI.InventoryId  
--JOIN tblVanLoadingSlipHeader VLH on VLH.ID = VLD.ID  
--JOIN tblMasterSalesman MS on MS.ID = VLH.SalesmanID  
--WHERE TPI.ProdID = @ProductID  
--GROUP By MS.Name  
--) AS Detail  
--GROUP BY [Salesman Name]  
SELECT  Trans,[Product Name],[Salesman Name],  
dbo.fnGetRoundedValue(SUM([VLS Closing])) AS [Qty],  
dbo.fnGetRoundedValue(SUM([Free Qty])) AS [Free Qty],  
dbo.fnGetRoundedValue(SUM([Damage Qty])) AS [Damage Qty]  
FROM (  
SELECT ''Van Loading Slip'' Trans,MP.Name [Product Name],MS.Name[Salesman Name],SUM(isnull(VLD.UomQty,0)-isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0))[VLS Closing],  
0 AS [Free Qty], 0 AS [Damage Qty]  
FROM tblVanLoadingSlipHeader VLH  
JOIN tblVanLoadingSlipDetail VLD on VLD.ID = VLH.ID  
JOIN tblMasterSalesman MS on MS.ID = VLH.SalesmanID  
JOIN tblMasterProduct MP ON MP.ID = VLD.ProdID
WHERE VLD.ProdID = @ProductID  
GROUP BY MP.Name,MS.Name  
HAVING SUM(isnull(VLD.UomQty,0)-isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0)) > 0  
UNION ALL  
SELECT ''Inventory'',MP.Name,null [Salesman Name],SUM(ActualQty) AS [VLS Closing],SUM(TPI.ActualFreeQty)[Free Qty], SUM(TPI.ActualDmgQty)[Damage Qty]  
FROM tblProductInventory TPI  
JOIN tblMasterProduct MP ON MP.ID = TPI.ProdID
WHERE TPI.ProdID = @ProductID  
group by  MP.Name
) AS Detail  
GROUP BY Trans,[Product Name],[Salesman Name]  
END',
N'[export] nocount';
GO
/****** UspRepVlsAbsHeader ******/
EXEC #Apply07 N'dbo.UspRepVlsAbsHeader', 0xF8E897A16A87500219B511D71505224B847F50E05A36C6716376F491708DA3C5, NULL, NULL, 0x14941167089E1F960F1502CD07BE49589C83A0AB5FA5549B9392E8E1E1A0BF3F, 0x43806C0A31BAF1B9CDB5932E9F9DC62B432E27E7C60E9CAF30724055C40318F3, NULL,
N'--UspRepVlsAbsHeader 0,'''','''','''',''''
ALTER Procedure [dbo].[UspRepVlsAbsHeader]
@BranchName INT = 0, @ManufName nvarchar(255) = '''', @BrandName nvarchar(255) = '''',@CategoryName nvarchar(255) = '''', @ProductName nvarchar(255) = ''''
AS
SET NOCOUNT ON;
BEGIN
SELECT ID,[Product Code],[Product Name],[Manufacturer Name],[Brand Name],[Category Name],
dbo.fnGetRoundedValue(SUM([MRP])) AS [MRP],dbo.fnGetRoundedValue(SUM([ABS Qty])) AS [ABS Qty],
dbo.fnGetRoundedValue(SUM([VLS Closing])) AS [VLS Closing],dbo.fnGetRoundedValue(SUM([Free Qty])) AS [Free Qty],
dbo.fnGetRoundedValue(SUM([VLS Closing] + [ABS Qty])) as [Total Qty],
dbo.fnGetRoundedValue(SUM([Damage Qty])) AS [Damage Qty]
FROM (
SELECT MP.ID, MP.Code[Product Code], MP.Name[Product Name], MM.Name[Manufacturer Name], MB.Name[Brand Name], MC.Name[Category Name],
0 AS [MRP],0 AS [ABS Qty],SUM(isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0))[VLS Closing],
0 AS [Free Qty],0 AS [Damage Qty]
FROM tblVanLoadingSlipHeader VLH
JOIN tblVanLoadingSlipDetail VLD on VLD.ID = VLH.ID
JOIN tblMasterProduct MP on MP.ID = VLD.ProdID
JOIN tblMasterManufacturer MM on MM.ID = MP.MfrID
JOIN tblMasterBrand MB on MB.ID = MP.BrandID
JOIN tblMasterCategory MC on MC.ID = MP.CategoryID
WHERE
(@BranchName =0 OR VLH.BranchID = @BranchName)
AND (isnull(@ManufName, '''') = '''' OR MM.ID IN (SELECT * from dbo.fnSplitString(@ManufName,'','')))
AND (isnull(@BrandName,'''') = '''' OR MB.ID IN (SELECT * from dbo.fnSplitString(@BrandName,'','')))
AND (isnull(@CategoryName,'''') = '''' OR MC.ID IN (SELECT * from dbo.fnSplitString(@CategoryName,'','')))
AND (isnull(@ProductName,'''') = '''' OR MP.ID IN (SELECT * from dbo.fnSplitString(@ProductName,'','')))
Group by MP.ID,MP.Code,MP.Name,MM.Name,MB.Name,MC.Name
HAVING SUM(isnull(VLD.UomQty,0)- isnull(VLD.VLSMQty,0) + isnull(VLD.VLSRetrunQty,0)) > 0
UNION ALL
SELECT MP.ID, MP.Code[Product Code], MP.Name[Product Name], MM.Name[Manufacturer Name], MB.Name[Brand Name], MC.Name[Category Name],
SUM(TPI.MRPONPrice)[MRP],SUM(TPI.ActualQty)[ABS Qty],0 AS[VLS Closing],SUM(TPI.ActualFreeQty)[Free Qty],
SUM(TPI.ActualDmgQty)[Damage Qty]
FROM tblProductInventory TPI
--JOIN tblVanLoadingSlipDetail VLD on VLD.InventoryID = TPI.InventoryId
--JOIN tblVanLoadingSlipHeader VLH on VLH.ID = VLD.ID
JOIN tblMasterProduct MP on MP.ID = TPI.ProdID
JOIN tblMasterManufacturer MM on MM.ID = MP.MfrID
JOIN tblMasterBrand MB on MB.ID = MP.BrandID
JOIN tblMasterCategory MC on MC.ID = MP.CategoryID
WHERE
(@BranchName =0 OR TPI.BranchID = @BranchName)
AND (isnull(@ManufName, '''') = '''' OR MM.ID IN (SELECT * from dbo.fnSplitString(@ManufName,'','')))
AND (isnull(@BrandName,'''') = '''' OR MB.ID IN (SELECT * from dbo.fnSplitString(@BrandName,'','')))
AND (isnull(@CategoryName,'''') = '''' OR MC.ID IN (SELECT * from dbo.fnSplitString(@CategoryName,'','')))
AND (isnull(@ProductName,'''') = '''' OR MP.ID IN (SELECT * from dbo.fnSplitString(@ProductName,'','')))
Group by MP.ID,MP.Code,MP.Name,MM.Name,MB.Name,MC.Name
) AS FINAL
GROUP BY ID, [Product Code], [Product Name], [Manufacturer Name], [Brand Name], [Category Name]
END',
N'[export] nocount';
GO
/****** uspSalesRegisterDetail ******/
EXEC #Apply07 N'dbo.uspSalesRegisterDetail', 0xEE2E1682E7FE0894E7A8B2857DA88356E2240E5431A9BBFE848B9CE52C516A62, NULL, NULL, 0xB786C0D2D4DDAAD3FE23970AA0B2DAB9F12B688BE362FD97793C841DCCF14F6D, 0x398BE7DCDBE6D3E9EF30A151008C413E0DEFC9D90190167AD274BFF392202ACA, NULL,
N'--[uspSalesRegisterDetail] 521  
 ALTER proc [dbo].[uspSalesRegisterDetail]            
 @InvId INT = 15              
 as            
 SET NOCOUNT ON;
begin            
SELECT  SalesHead.DocID [Doc ID],FORMAT(InvDate,''dd-MMM-yyyy'') [Doc Date],Product.Code AS [Product Code], Product.Name AS [Product Name],  Product.EAN as EAN,                
MF.Name Manufacturer,MB.Name Brand,MC.Name Category,UOM.Name as [Uom Name],[dbo].[fnGetRoundedValue](UomQty)AS [Uom Qty],[dbo].[fnGetRoundedValue](UomPrice) as [Uom Price],        
[dbo].[fnGetRoundedValue](DetailMRP) MRP,              
[dbo].[fnGetRoundedValue](ProdDisc) as [Product Disc %],
[dbo].[fnGetRoundedValue](ProdDiscAmt) as [Product Disc Amount],
[dbo].[fnGetRoundedValue](SalesDetail.TradeDiscPern) as [Trade Disc %],
[dbo].[fnGetRoundedValue](SalesDetail.TradeDisc) as [Trade Disc Amount],
[dbo].[fnGetRoundedValue](AddnlDiscPern) as[Additional Disc %],   
[dbo].[fnGetRoundedValue](AddnlDisc) as[Additional Disc Amount],              
tax.TaxName as [Tax Name],[dbo].[fnGetRoundedValue] (TaxValue) as [Tax %],[dbo].[fnGetRoundedValue](SalesDetail.GrossAmt) AS [Gross Amount],              
[dbo].[fnGetRoundedValue]( TaxAmt) AS [Tax Amount],[dbo].[fnGetRoundedValue](SalesDetail.NetAmt) AS [Net Amount],RSN.Name Reason,            
[dbo].[fnGetRoundedValue](SalesDetail.DiffValue) AS [Diff Amount]              
FROM tblTranSalesDetail AS SalesDetail              
join tblTranSalesHeader as SalesHead on SalesHead.id = SalesDetail.InvId              
JOIN tblMasterProduct AS Product ON SalesDetail.ProdId=Product.ID              
LEFT JOIN tblMasterUom AS UOM ON UOM.ID = SalesDetail.UomId              
LEFT JOIN tblMasterTax as tax ON tax.TaxID= SalesDetail.TaxId              
left JOIN tblMasterReason RSN ON RSN.ID = SalesDetail.ReasonID         
join tblMasterManufacturer MF ON MF.ID = Product.MfrID  
join tblMasterBrand MB ON MB.ID = Product.BrandID  
join tblMasterCategory MC ON MC.ID = Product.CategoryID  
WHERE SalesDetail.InvId= @InvId and SalesDetail.TaxID > 0    
--group by SalesDetail.InvId,Product.Code,Product.Name,Product.EAN,            
--BaseUomPrice,UomQty,UomPrice,SalesHead.TransactionType,UOM.Name,ProdDisc,SalesDetail.TradeDisc,AddnlDisc,tax.TaxName,TaxValue,SalesDetail.NetAmt,      
--SalesDetail.GrossAmt,TaxAmt,Serial ,RSN.Name,SalesDetail.DiffValue,DetailMRP,SalesHead.DocID,InvDate,SalesDetail.TaxID,MF.Name,MB.Name,MC.Name  
order by Serial              
end',
N'[export] nocount';
GO
/****** uspSalesRegisterHeader ******/
EXEC #Apply07 N'dbo.uspSalesRegisterHeader', 0x1B3E2C5176803B7D3DE3F4C7D962ABAB9D28243004CA1908109152043A20A121, NULL, NULL, 0x716D7FDDC04A7FA3E2AC16C26CC1D8AB61BB64AE78DE785BF604A40B952FCF7D, 0xF1D267A09F848BD970B5C476102763A112C3A09BF2488B15B101F2AF568BDB8D, NULL,
N'--uspSalesRegisterHeader      
ALTER proc [dbo].[uspSalesRegisterHeader]        
@StatusID INT = 1,@FromDate DATE = ''2025-03-01'',@ToDate DATE = ''2025-06-21''      
AS      
SET NOCOUNT ON;
BEGIN      
DECLARE @Sts AS TABLE(Status INT)          
IF(@StatusID = 0)          
BEGIN          
INSERT INTO @Sts values (1),(3),(5),(6),(7)      
END          
ELSE IF(@StatusID = 1)          
BEGIN          
INSERT INTO @Sts values (1),(6),(7)      
END       
ELSE          
BEGIN          
INSERT INTO @Sts values(@StatusID)          
END        
      
SELECT SaleHeader.Id AS [ID],    
case when saleHeader.TransactionType = 1 THEN ''Invoice'' when saleHeader.TransactionType = 2 THEN ''Sale Return'' ELSE ''Damage Return'' END [Transaction],      
SaleHeader. DocId AS [Doc Id],FORMAT(SaleHeader.invdate,''dd-MMM-yyyy'') AS [Doc Date],                
Beat.Name AS [Beat Name],SalesMan.Name AS [Salesman Name],                
cust.Code AS [Customer Code],cust.Name AS [Customer Name],MCT.Name [Customer Type],RT.RatingName Ratings,       
cust.GSTIN AS [GSTIN],TaxType.TaxTypeName AS [Tax Type Name],SaleHeader.DocRef AS [Ref No],                
(CASE WHEN SaleHeader.TradeDisc LIKE ''%[%]''                
THEN CAST([dbo].[fnGetRoundedValue](REPLACE(SaleHeader.TradeDisc,''%'',''''))+''%'' AS NVARCHAR)                
ELSE CAST([dbo].[fnGetRoundedValue](SaleHeader.TradeDisc) AS NVARCHAR) END) AS [Trade Discount %],                
(CASE WHEN SaleHeader.AdditionalDisc LIKE ''%[%]''                
THEN CAST([dbo].[fnGetRoundedValue](REPLACE(SaleHeader.AdditionalDisc,''%'',''''))+''%'' AS NVARCHAR)                
ELSE CAST([dbo].[fnGetRoundedValue](SaleHeader.AdditionalDisc) AS NVARCHAR)END) AS [Additional Discount %],                
[dbo].[fnGetRoundedValue](SaleHeader.Frieght) AS [Freight],            
(CASE WHEN SaleHeader.OtherCharge LIKE ''%[%]''                
THEN CAST([dbo].[fnGetRoundedValue](REPLACE(SaleHeader.OtherCharge,''%'',''''))+''%'' AS NVARCHAR)                
ELSE CAST([dbo].[fnGetRoundedValue](SaleHeader.OtherCharge) AS NVARCHAR)END)AS [Other Charges %],                      
[dbo].[fnGetRoundedValue](SaleHeader.TotalProdDiscAmt) AS [Total Prod Discount Amount],                
[dbo].[fnGetRoundedValue](SaleHeader.TotalTradeDiscAmt) AS [Total Trade Discount Amount],                
[dbo].[fnGetRoundedValue](SaleHeader.AdditionalDiscAmt) AS [Total Additional Discount Amount],                
[dbo].[fnGetRoundedValue](SaleHeader.TotalDiscountAmt) AS [All Discount Amount],                
[dbo].[fnGetRoundedValue](SaleHeader.GrossAmt) AS [Gross Amount],                
[dbo].[fnGetRoundedValue](SaleHeader.TotalTaxAmt) AS [Tax Amount],                
[dbo].[fnGetRoundedValue](SaleHeader.RoundOfAmt) AS [Round off Amount],                
[dbo].[fnGetRoundedValue](SaleHeader.NetAmt) AS [Net Amount],                
dbo.fngetroundedvalue(isnull(SaleHeader.DiffValueGross,0)) [Diff Excl],dbo.fngetroundedvalue(isnull(SaleHeader.DiffValueNet,0)) [Diff Incl],  
case when SaleHeader.Status IN (6,7) THEN ''Open'' ELSE s.Description END as [Status],MRT.Name AS [Return Type],                
CASE ISNULL(us.username ,'''') WHEN '''' THEN  u.username  ELSE  us.username END [User],          
ORGSH.DocId AS [Org Doc Id],CONVERT(NVARCHAR,ORGSH.InvDate,103)AS [Org Doc Date]          
FROM tblTranSalesHeader as SaleHeader                
JOIN tblMasterCustomer cust ON cust.ID = SaleHeader.CustId                
LEFT JOIN tblMasterBeat Beat ON SaleHeader.BeatID=Beat.ID                
LEFT JOIN tblMasterSalesMan SalesMan ON SaleHeader.SalesManId=SalesMan.ID                        
LEFT JOIN tblMasterTaxType AS TaxType ON TaxType.TaxTypeID = SaleHeader.TaxTypeId                
LEFT JOIN tblUsers AS U ON  U.ID = SaleHeader.CBy                
LEFT JOIN tblUsers AS Us ON  Us.ID = SaleHeader.MBy                
LEFT JOIN tblStatus as s ON s.ID = SaleHeader.Status                
LEFT JOIN tblMasterReturnType AS MRT ON MRT.ID = SaleHeader.ReturnType                
LEFT JOIN tblTranSalesHeader ORGSH ON ORGSH.ID = SaleHeader.OrgInvID 
LEFT JOIN tblMasterCustomerType AS MCT ON  MCT.ID = cust.CustomerType  
LEFT JOIN tblRatings AS RT ON  RT.ID = cust.Rating 
WHERE SaleHeader.InvDate BETWEEN @FromDate AND @ToDate    
AND SaleHeader.Status in (select * from @Sts)        
ORDER BY SaleHeader.DocValue        
END',
N'[export] nocount';
GO
/****** uspSalesReturnBody ******/
EXEC #Apply07 N'dbo.uspSalesReturnBody', 0x92E783574F70DB328ECD0CFDB815A7409F28007E73A05FBD2B10162F679A4E8E, NULL, NULL, 0x685A94240E3A5C6B98B070EF901BBD10107A8B7E9AFC5C87D5BF4D9066B85CCA, 0x8B21981F8CADD9EDC8F916BAE4E5532724BB0F3B13A9D87AC892AEB17F6D2614, NULL,
N'--[uspSalesReturnBody] 4                  
ALTER PROC [dbo].[uspSalesReturnBody]                         
@InvId NVARCHAR(255)=NULL,                                                                                                                
@Cond SMALLINT =NULL                                                                                                                
AS              
SET NOCOUNT ON;
BEGIN                                
--DECLARE @InvId INT = 6730                                                      
CREATE TABLE #TempBaseQty (ProdID INT, BaseQty DECIMAL (25,6),SerialNo INT)                                                                                            
INSERT INTO #TempBaseQty                                                          
SELECT ProdId,SUM(AdjustQty) AS [AdjustQty],Serial FROM tblTranSalesDetail                                                                                            
WHERE InvId = @InvId                                                      
GROUP BY ProdId,Serial                                                          
ORDER BY Serial                                                          
declare @oby NVARCHAR(10) = 0--(SELECT AppValue FROM tblAppConfig WHERE AppId = 167)                        
SELECT ProdID,Serial [Temp Serial],(SUM(RAM.[CGST %])) AS [CGST %],SUM((RAM.[CGST Amount])) AS [CGST Amount],                          
(SUM(RAM.[SGST %])) AS [SGST %],(SUM(RAM.[SGST Amount])) AS [SGST Amount],(SUM(RAM.[UTGST %])) AS [UTGST %],                          
SUM((RAM.[UTGST Amount])) AS [UTGST Amount],(SUM(RAM.[GCESS %])) AS [GCESS %],SUM((RAM.[GCESS Amount])) AS [GCESS Amount],                          
(SUM(RAM.[IGST %])) AS [IGST %],SUM((RAM.[IGST Amount])) AS [IGST Amount],(SUM(RAM.[ICESS %])) AS [ICESS %],                          
SUM((RAM.[ICESS Amount])) AS [ICESS Amount],SUM([GUOM %]) [GUOM %],SUM([IUOM %]) [IUOM %],                          
SUM(RAM.[GUOM Amount]) [GUOM Amount],SUM(RAM.[IUOM Amount]) [IUOM Amount],                          
SUM([GCESS Amount]  + [ICESS Amount] + [GUOM Amount] + [IUOM Amount]) [Cumulative CESS Amount] INTO #Tax                                              
FROM                                                            
(                  
SELECT SRI.ProdID,SRI.Serial,--SRI.[Gross Amount],                                                        
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[CGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 1),0)) AS [CGST %],            
(ISNULL(SRI.[CGST Amount],0)) AS [CGST Amount],                                                            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[SGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 2),0)) AS [SGST %],            
(ISNULL(SRI.[SGST Amount],0)) AS [SGST Amount],                                                            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[UTGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 3),0)) AS [UTGST %],            
(ISNULL(SRI.[UTGST Amount],0)) AS [UTGST Amount],            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GCESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 4),0)) AS [GCESS %],            
(ISNULL(SRI.[GCESS Amount],0)) AS [GCESS Amount],            
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[GUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 1 AND GSTTaxType = 5),0)) AS [GUOM %],            
(ISNULL(SRI.[GUOM Amount],0)) AS [GUOM Amount],                                                 
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IGST Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 1),0)) AS [IGST %],            
(ISNULL(SRI.[IGST Amount],0)) AS [IGST Amount],                             
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[ICESS Amount],0)=0 THEN SUM(CumulativeTax) ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 2),0)) AS [ICESS %],            
(ISNULL(SRI.[ICESS Amount],0)) AS [ICESS Amount],              
(ISNULL((SELECT (CASE WHEN ISNULL(SRI.[IUOM Amount],0)=0 THEN 0 ELSE SUM(CumulativeTax) END) FROM tblMasterTaxDetail WHERE TaxID = SRI.TaxID AND TaxTypeID = 2 AND GSTTaxType = 3),0)) AS [IUOM %],                                                
(ISNULL(SRI.[IUOM Amount],0)) AS [IUOM Amount]                           
FROM                                                            
(                  
SELECT * FROM                  
(                  
SELECT Temp.ProdID,Temp.Serial,Temp.TaxTypeID,Temp.TaxID,Temp.[GST Comp],                                                            
Temp.TaxName AS TaxName,                                          
SUM(Temp.TaxValue) AS [TaxValue]--, SUM(Temp.[Gross Amount]) AS [Gross Amount]                                                        
FROM                                                            
(                                                            
SELECT GSTInfo.ProdID,GSTInfo.SERIAL,MT.TaxID,GSTInfo.TaxTypeID,MT.TaxName,GSTInfo.TaxCompPern,GSTInfo.TaxValue,                                                  
CASE                                                    
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 1 THEN ''CGST Amount''                                                     
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 1 THEN ''SGST Amount''                                                            
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 1 THEN ''UTGST Amount''                                                  
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=4 AND GSTInfo.TaxTypeID = 1 THEN ''GCESS Amount''                           
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=5 AND GSTInfo.TaxTypeID = 1 THEN ''GUOM Amount''                                         
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=1 AND GSTInfo.TaxTypeID = 2 THEN ''IGST Amount''                                          
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=2 AND GSTInfo.TaxTypeID = 2 THEN ''ICESS Amount''                           
WHEN ISNULL(GSTInfo.GSTTaxTypeID,0)=3 AND GSTInfo.TaxTypeID = 2 THEN ''IUOM Amount''                                                    
END AS [GST Comp]--, GSTInfo.GrossAmt AS [Gross Amount]                  
FROM tblTransGSTInfo AS GSTInfo                  
JOIN tblMasterTax AS MT ON MT.TaxID = GSTInfo.TaxID                  
WHERE TransIdentID=@InvId AND TransID IN (15,16,17)              
) Temp                  
GROUP BY Temp.[GST Comp],Temp.TaxCompPern,Temp.TaxName,Temp.TaxID,Temp.TaxTypeID ,Temp.ProdID,Temp.Serial                                              
) src                  
PIVOT                                                            
(                                                            
SUM([TaxValue])                                                            
FOR [GST Comp] in ([CGST %],[CGST Amount],[SGST %],[SGST Amount],[UTGST %],[UTGST Amount],[GCESS %],[GCESS Amount],[IGST %],[IGST Amount],[ICESS %],[ICESS Amount],[GUOM Amount],[IUOM Amount])                                                            
) piv                                                            
) AS SRI                                                            
) AS RAM                                                        
GROUP BY ProdID,Serial--,[CGST %]                                        
--ORDER BY RAM.[CGST %] ASC                                                   
                                                      
--SELECT GST.TransID,TransIdentID,GST.ProdId,GST.Serial,GST.TaxId,GST.TaxTypeID,GST.GSTTaxTypeID,GST.TaxCompPern,GST.TaxValue FROM tblTranSalesDetail SD                                              
--JOIN tblTransGSTInfo GST ON GST.TransIdentID = SD.InvId                                                      
--WHERE SD.InvId = 6730                                                 
                                                       
SELECT IDENTITY (INT, 1, 1) AS NEW_ID,PROD.ID ProdID,prod.Code AS [Product Code],prod.Name AS [Product Name],prod.HSNCode AS [HSN Code],                                                          
Loc.Name AS [Location Name],prod.RemarkS AS [Remark1],prod.WebOrder AS [Web Order],                                
'''' AS [Uom Group Name],INV.BaseQty AS [Base Qty],Sales.UomQty AS [Uom Qty],                    
(INV.BaseQty / prod.SalesCR) AS [Deft_S_UOM_Qty],                                                          
Uom.Name AS [Uom Name],(Sales.UomPrice / prod.BaseCR) AS [Base Uom Price],                                                          
Sales.UomPrice AS [Uom Price],prod.SalesCR AS [UOM CF],                                                          
prod.SalesCR AS [Deft_S_UOM_CF],                                                          
Sales.UomPrice + (Sales.UomPrice * (Sales.TaxValue / 100)) as [Rate],                                                          
Sales.GrossAmt / Sales.UomQty as [Per Piece Exclusive Price],                                                          
Sales.NetAmt / Sales.UomQty as [Per Piece Inclusive Price],                                                          
--Case when (prod.TrackInventory = 0)then  (prod.MRP) ELSE (ProdInv.MRPONPrice) end As [MRP Price],                                                          
Sales.DetailMRP As [MRP Price],MT.TaxName [Tax Name],                  
Sales.GoodsAmt AS [Goods Amount],0 AS [User Discount Percnt],                                                          
0 AS [User Discount Amt],                                                          
CAST(dbo.fnGetRoundedValue(0) AS NVARCHAR(255))+''%'' AS [UserDisc Discount %],                                                          
Sales.ProdDisc AS [Product Discount Percnt],((Sales.GoodsAmt) * (Sales.ProdDisc) /100) as [Product Disc Amt],                                                          
CAST(dbo.fnGetRoundedValue(ProdDisc) AS NVARCHAR(255))+''%'' AS [Product Discount %],                                                          
Sales.TradeDisc AS [Trade Discount],Sales.AddnlDisc AS [Addnl Discount],                                                          
(ISNULL(((Sales.GoodsAmt) *(1)/100),0)+ISNULL(((Sales.GoodsAmt) * (Sales.ProdDisc) /100),0)+ISNULL(Sales.TradeDisc,0)+ISNULL(Sales.AddnlDisc,0)) AS [Total Disc Amt],                                                                
Sales.GrossAmt AS [Gross Amount],Sales.TaxValue AS [Tax percentage],Sales.TaxAmt AS [Tax Amount],                                                                                                                  
Sales.NetAmt AS [Net Amount],Sales.Serial  AS [Serial],Sales.IdentID Ident,                                                                                                              
'''' AS [ProdSerial],ROW_NUMBER() OVER (ORDER BY Sales.IdentID) AS [Serial No],                                                                                      
Header.DocPrefix AS [Doc Prefix],                  
'''' [T_Prod_Code],'''' [T_Prod_Name],                  
'''' [T_EAN],'''' [T_UD_Code],'''' [T_UD_Name],ISNULL(UDFDocId,DocId) DocId,'''' AS SR,TransactionType,            
1 [UOM 1 Qty CF],PROd.ReportingQty [Rep UOM CF]            
INTO #Temp                  
FROM dbo.tblTranSalesDetail AS Sales                  
JOIN tblTranSalesHeader AS Header ON Header.Id =Sales.InvId                  
LEFT JOIN tblMasterProduct AS prod ON prod.ID=Sales.ProdId                  
join tblMasterTax MT ON MT.TaxID = Sales.TaxId                  
LEFT JOIN tblMasterLocation AS Loc ON Loc.Id=prod.LocationId                               
JOIN dbo.tblMasterUom AS Uom ON Uom.ID = Sales.UomId                                                                          
LEFT JOIN dbo.tblProductInventory AS ProdInv ON Sales.InventoryId = ProdInv.InventoryId                                                          
LEFT JOIN #TempBaseQty AS INV ON INV.ProdID = Sales.ProdId AND INV.SerialNo = Sales.Serial                                                                                
WHERE Sales.InvId = @InvId                                 
--ORDER BY Serial                              
 ORDER BY (CASE WHEN @oby = ''0'' THEN Serial END) asc,                        
(CASE WHEN @oby = ''1'' THEN prod.Name END) asc                                                 
ALTER TABLE #Temp DROP COLUMN Ident                                                 
--Get Product with Ide                                                                                 
                                                       
SELECT [Product Code],[Product Name],[HSN Code],[Location Name],[Remark1],[Web Order],[Uom Group Name],[Base Qty],[Uom Qty],CONVERT(int,round([Uom Qty],0,0)) [UOM Qty (RD)],[Deft_S_UOM_Qty],      
[Uom Name],[Base Uom Price],[Uom Price],[UOM CF],[Deft_S_UOM_CF],[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price]                                              
,[MRP Price],CONVERT(int,round([MRP Price],0,0)) [MRP Price (RD)],[Goods Amount],[User Discount Percnt],[User Discount Amt],[UserDisc Discount %],[Product Discount Percnt],                                              
[Product Disc Amt],[Product Discount %],[Trade Discount],[Addnl Discount],[Total Disc Amt],[Gross Amount],                                              
[Tax Name],[Tax percentage],[Tax Amount],[Net Amount],[Serial],[ProdSerial],NEW_ID AS [Serial No],[Doc Prefix],[T_Prod_Code],                                              
[T_Prod_Name],[T_EAN],[T_UD_Code],[T_UD_Name],DocId,SR,TransactionType,                                    
dbo.fnGetRoundedValue(sum(t2.[CGST %])) [CGST %],dbo.fnGetRoundedValue(sum(t2.[CGST Amount])) [CGST Amount],                                        
dbo.fnGetRoundedValue(sum(t2.[SGST %])) [SGST %],                                              
dbo.fnGetRoundedValue(sum(t2.[SGST Amount])) [SGST Amount],                                              
dbo.fnGetRoundedValue(sum(t2.[UTGST %])) [UTGST %],dbo.fnGetRoundedValue(sum(t2.[UTGST Amount])) [UTGST Amount],                                        
dbo.fnGetRoundedValue(sum(t2.[GCESS %])) [GCESS %], dbo.fnGetRoundedValue(SUM(t2.[GCESS Amount])) [GCESS Amount],                                        
dbo.fnGetRoundedValue(sum(t2.[IGST %])) [IGST %],                                              
dbo.fnGetRoundedValue(sum(t2.[IGST Amount])) [IGST Amount],                                  
dbo.fnGetRoundedValue(sum(t2.[ICESS %])) [ICESS %],dbo.fnGetRoundedValue(sum(t2.[ICESS Amount])) [ICESS Amount],                          
dbo.fnGetRoundedValue(sum(t2.[GUOM %])) [GUOM %],dbo.fnGetRoundedValue(sum(t2.[GUOM Amount])) [GUOM Amount],                          
dbo.fnGetRoundedValue(sum(t2.[IUOM %])) [IUOM %],dbo.fnGetRoundedValue(sum(t2.[IUOM Amount])) [IUOM Amount],                          
dbo.fnGetRoundedValue(sum(t2.[Cumulative CESS Amount])) [Cumulative CESS Amount],0 [Def 0 Value],            
convert(int,FLOOR([Base Qty] / NULLIF([UOM 1 Qty CF],0))) [UOM 1 Qty (RD)] ,      
convert(int,FLOOR([Base Qty]-(FLOOR([Base Qty]/NULLIF([UOM 1 Qty CF],0))*[UOM 1 Qty CF]))) [UOM 1 B Qty (RD)],            
convert(int,FLOOR([Base Qty] / NULLIF([Rep UOM CF],0))) [Rep Qty (RD)] ,      
convert(int,FLOOR([Base Qty]-(FLOOR([Base Qty]/NULLIF([Rep UOM CF],0))*[Rep UOM CF]))) [Rep B Qty (RD)] FROM #Temp t1                                              
left join #Tax t2 on t2.ProdID = t1.ProdID and t1.[Serial No] = t2.[Temp Serial]                                  
GROUP BY [Product Code],[Product Name],[HSN Code],[Location Name],[Remark1],[Web Order],[Uom Group Name],[Base Qty],[Uom Qty],[Deft_S_UOM_Qty],                                              
[Uom Name],[Base Uom Price],[Uom Price],[UOM CF],[Deft_S_UOM_CF],[Rate],[Per Piece Exclusive Price],[Per Piece Inclusive Price]      
,[MRP Price],[Goods Amount],[User Discount Percnt],[User Discount Amt],[UserDisc Discount %],[Product Discount Percnt],                                              
[Product Disc Amt],[Product Discount %],[Trade Discount],[Addnl Discount],[Total Disc Amt],[Gross Amount],                                              
[Tax percentage],[Tax Amount],[Net Amount],[Serial],[ProdSerial],[Serial No],[Doc Prefix],[T_Prod_Code],[UOM 1 Qty CF],[Rep UOM CF],            
[T_Prod_Name],[T_EAN],[T_UD_Code],[T_UD_Name],DocId,SR,TransactionType,NEW_ID,[Tax Name]--,[CGST %],[SGST %],[UTGST %],[GCESS %],[IGST %],[ICESS %]                                              
 --ORDER BY [Serial No] ASC                      
 ORDER BY (CASE WHEN @oby = ''0'' THEN [Serial No] END) asc                      
 ,(CASE WHEN @oby = ''1'' THEN [Product Name] END) asc                      
 IF ISNULL(@Cond,0)=0                      
BEGIN                      
ALTER TABLE #Temp DROP COLUMN Serial                      
ALTER TABLE #Temp DROP COLUMN [ProdSerial]                      
ALTER TABLE #Temp DROP COLUMN [SR]                      
END                      
--SELECT * FROM #ORGTBL                        
--ORDER BY (CASE WHEN @oby = ''0'' THEN #ORGTBL.[Serial No] END) asc,                        
--(CASE WHEN @oby = ''1'' THEN #ORGTBL.[Product Name] END) asc                        
DROP TABLE #Temp--,#ORGTBL                        
DROP TABLE #TempBaseQty,#Tax                      
END',
N'[export] nocount';
GO
/****** uspSalesReturnHeader ******/
EXEC #Apply07 N'dbo.uspSalesReturnHeader', 0xD7523A578EAC2FFA32D0090B658311C9DBB970066995D1FDBC0A217E17D7FDB3, NULL, NULL, 0xF8C42004CE1A17FF3B0903F02F648D2F7E5D6D175CF391D1E955E28F89E8269F, 0x37D27437F0060BE4E7EF49503209302847861A1439FDBD4DDBDDEAECF3B69D39, NULL,
N'--uspSalesReturnHeader 465                                            
ALTER PROC [dbo].[uspSalesReturnHeader]                                            
@IdentID INT =NULL                              
AS                              
SET NOCOUNT ON;
BEGIN                              
-- Total Saving----------------                              
Declare @TotalSaving DECIMAL(25,6) =                                            
(select Sum((((MRP/MRPCF)*SelectedCF) - Rate)*qty)  as Diff From (select Case when (prod.TrackInventory = 0) then (prod.MRP) ELSE (ProdInv.MRPONPrice) end As MRP,                                            
(detail.NetAmt / detail.UomQty) as Rate, detail.UomQty as qty, prod.SalesCR as SelectedCF,                                            
prod.SalesCR as MRPCF From dbo.tblTranSalesDetail as detail                                            
join dbo.tblProductInventory as prodinv on prodinv.InventoryId = detail.InventoryId              
JOIN tblMasterProduct AS prod ON prod.ID=detail.ProdId              
where InvId = @IdentID)as Fin)                                 
DECLARE @PGross DECIMAL(25,6),@PTaxAmt DECIMAL(25,6),@PNetAmt DECIMAL(25,6),@PGoodsAmt DECIMAL(25,6),@PSQty DECIMAL(25,2)              
SELECT @PGoodsAmt = SUM(ISNULL((GoodsAmt),0)),@PGross = SUM(ISNULL((GrossAmt),0)),@PTaxAmt = SUM(ISNULL(TaxAmt,0)),                
@PNetAmt = SUM(ISNULL(NetAmt,0)),@PSQty = SUM(ISNULL(UomQty,0))                
FROM tblTranSalesDetail Sales WHERE InvId = @IdentID               
              
DECLARE @AdjQty DECIMAL(25,6),@UOMQty DECIMAL(25,6),@UOMCF DECIMAL(25,6),@RepCF DECIMAL(25,6),@SU1BQTY INT = 0,                
@SU1QTY INT = 0,@REPU1BQTY INT = 0,@REPU1QTY INT = 0              
              
SELECT IDENTITY(INT,1,1) AS ID,Sales.ProdId,SUM(Sales.AdjustQty) AdjustQty,sum(Uomqty) UomQty,    
prod.SalesCR UOMCF,prod.ReportingCR REPUOMCF INTO #DPROD     
FROM tblTranSalesDetail Sales              
LEFT JOIN tblMasterProduct AS prod ON prod.iD=Sales.ProdId  WHERE InvId = @IdentID --AND TaxId > 0              
group by Sales.ProdId,prod.ReportingCR,prod.SalesCR    
              
              
DECLARE @CF DECIMAL(25,6),@nCount INT,@nInt INT = 1,@ProdID INT              
SET @nCount = (SELECT COUNT(*) FROM #DPROD)              
WHILE(@nCount >= @nInt)              
BEGIN              
SELECT  @SU1QTY = @SU1QTY + convert(int,FLOOR(AdjustQty / nullif(UOMCF,0))),@SU1BQTY = @SU1BQTY + convert(int,FLOOR(AdjustQty-(FLOOR(AdjustQty/UOMCF)*UOMCF))),              
@REPU1QTY = @REPU1QTY + convert(int,FLOOR(AdjustQty / nullif(REPUOMCF,0))),@REPU1BQTY = @REPU1BQTY + convert(int,FLOOR(AdjustQty-(FLOOR(AdjustQty/REPUOMCF)*REPUOMCF)))  FROM #DPROD WHERE ID = @nInt              
SET @nInt = @nInt + 1;              
END              
--SELECT @SU1QTY SU1QTY,@SU1BQTY SU1BQTY,@REPU1QTY REPU1QTY,@REPU1BQTY REPU1BQTY              
DROP TABLE #DPROD                 
              
--Payment Mode Name--------------                                            
Declare @InvPaymode nvarchar(1000)              
              
Select @InvPaymode = Coalesce (@InvPaymode + '', '', '''') + mode.PaymentMode From dbo.tblTran_Sale_Bill_PaymentDetail as BS              
left Join dbo.tblPaymentMode as mode on mode.Id = BS.PayModeId              
where InvId = @IdentID and TransId = 15 Group by mode.PaymentMode              
                                            
--Cash Balance-----                                            
DeClare @Amt DECIMAL(25,6), @Recdamt DECIMAL(25,6)                                            
Select @Amt=SUM(Amt),@Recdamt = SUM(RecdAmt)  From dbo.tblTran_Sale_Bill_PaymentDetail as BS                                            
where InvId = @IdentID  and TransId = 15              
              
Select Inv.Id As [Inv ID],convert (nvarchar,Inv.InvDate,103) as [Doc Date],Isnull(CONVERT(nvarchar(5),Inv.MDate,108),CONVERT(nvarchar(5),Inv .CDate,108)) as [Time],              
CASE WHEN TransactionType = 2 then ''Sales Return'' ELSE ''Damage Return'' END as [Trans Name],Inv.DocId as [Doc ID],UDN.DocName AS [UDN Name],Inv.UDFDocId AS [UDN Doc ID],                         
Beat.Name as [Beat Name],SM.Name as [Salesman Name],SM.MobileNo as [Salesman Mobile No],                             
Cust.code as [Party Code],Cust.Name as [Party Name],                                                   
Cust.mob1 as [Party Prim Mobile No],Cust.ph1 as [Party Prim Phone No],Cust.Email as [Email ID],Cust.ContactPerson as [Contact Person],                                            
Cust.billadd1 AS [Party Bill Address 1],Cust.billadd2 as [Party Bill Address 2],Cust.billadd3 as [Party Bill Address 3],                              
Cust.billadd1+Cust.billadd2+Cust.billadd3 as [Party Full Address],                              
Cust.shipadd1 AS [Party Ship Address 1],Cust.shipadd2 as [Party Ship Address 2],Cust.shipadd3 as [Party Ship Address 3],                              
'''' AS [Party Area Name],cust.Pincode as [Party PinCode],'''' AS [Party Tin No],'''' AS [Party CST No],                                            
NULL as [Party CST Date],Cust.GSTIN AS [Party GSTIN],GSTST.StateName [GST State Name],        
GSTST.TINNo [GST State Code],Cust.AadharNo AS [Party Aadhar Number],                                            
Cust.PANNumber AS [Party PAN No],'''' AS [Party ServiceTax No],Cust.FSSAINo AS [Party FSSAI No],TaxType.TaxTypeName AS [Party TaxType],                                            
PriceType.PriceType as [Price Type],Cust.OSValue AS [Party Outstanding value],cust.ClosingTrackPoint [Reward Points],Tax.TaxTypeName as [TaxType Name],                              
--Invpaymode.PaymentMode as [Payment Mode],                              
isnull(@InvPaymode,''CREDIT'') as [Payment Mode],                              
--InvCreditTerm.CreditName as [CreditTerm Name],                              
CONVERT (nvarchar,Inv.CreditDate,103) AS [CreditTerm Date],                              
--PGrp.ProductGroupName as [Product Group Name],                                            
Inv.DocRef as [Doc Ref],SUM(Detail.UomQty) As [Total Qty],                              
SUM(Detail.AdjustQty / Prod.SalesCR) As [Deft_S_UOM_Total_Qty],                          
Inv.TradeDisc as [Trade Discount Percentage],Inv.AdditionalDisc as [Addnl Discount Percentage],                                            
Inv.Frieght as [Frieght Amount],                                            
Inv.OtherCharge as [OtherCharge Percentage],Inv.OtherChargeAmt as [OtherCharge Amount],                              
Inv.CreditNoteAdjAmt as [Adjust Amount],0 as [T.User Discount Amount],                            
dbo.fnGetRoundedValue(Inv.AdditionalDiscAmt)+'' (''+dbo.fnGetRoundedValue(Inv.AdditionalDisc)+''%)'' [Addnl Disc Pern Amt],    
dbo.fnGetRoundedValue(Inv.TotalTradeDiscAmt)+'' (''+dbo.fnGetRoundedValue(Inv.TradeDisc)+''%)''[Trade Disc Pern Amt],  
Inv.TotalTradeDiscAmt as [T.Trade Discount Amount],Inv.TotalProdDiscAmt AS [T.Product Discount Amount],                              
Inv.AdditionalDiscAmt as [T.Addnl Discount Amount],Inv.TotalDiscountAmt as [T.Discount Amount],                              
@TotalSaving AS [Total Saving Amount],(ISNULL(Inv.GrossAmt,0) + ISNULL(TotalDiscountAmt,0)) AS [Goods Amount],                              
Inv.GrossAmt as [T.Gross Amount],Inv.TotalTaxAmt as [T.Total Tax Amount],Inv.RoundOfAmt as [Round Off Amount],                              
Inv.NetAmt+(@Recdamt-@Amt) as [Received Amount],Inv.Balance AS [Balance Amount],@Recdamt-@Amt as [Cash Balance],                              
Inv.NetAmt as [Rounded Net Amount],(inv.NetAmt - Inv.CreditNoteAdjAmt) AS [Aft Adj NetAmt],                                            
[dbo].[fnConvertAmountinWords](Inv.NetAmt) AS [Amt_in_Words],UserTab.username as [User Name],                          
null[PO Date],'''' [PO Doc Ref],                        
--'''' AS [Tax Value],'''' AS [Tax Percentage],'''' AS [Tax Amount] ,'''' AS [Doc Prefix],                          
'''' [T_Customer Name],'''' [T_Bill_Address1],                              
'''' [T_Bill_Address2],'''' [T_Bill_Address3],'''' [T_Cont Person],'''' [T_Beat_Name],                              
'''' [T_SalesmanName],convert(nvarchar(255),MAX(Detail.Serial)) + '' / '' + convert(nvarchar(255),dbo.fnGetRoundedValue(SUM(Detail.UomQty))) as [Tot Count Qty],     
CH.VisaPern as [Visa %],((Inv.NetAmt * CH.VisaPern) / 100) AS [Visa Amt],(Inv.NetAmt + ((Inv.NetAmt * CH.VisaPern) / 100)) as [All Incl],                            
Inv.TCSTaxPern [TCS %],TCSTaxAmt [TCS Amt],IRN,AckNo,AckDate,AckStatus,SignedQRCode,''B2B'' SupplyType,isnull(TDSAmount,0) TDSAmount,EWBNo,                            
vh.VehicleNo,Inv.Distance,TransMode [Transport Mode],VehicleType [Vehicle Type],TransportID [Transport ID],TransportName [Transport Name],                    
0 [Def 0 Value],dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(Inv.GrossAmt)) [Gross Amt (WC)],dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(Inv.TotalTaxAmt)) [Total Tax Amt (WC)],                  
dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(Inv.NetAmt - RoundOfAmt - Inv.OtherChargeAmt - Inv.TotalDiscountAmt)) [Net Amt For TCS (WC)],                  
dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(Inv.NetAmt)) [Net Amt (WC)],@PGoodsAmt [PS Goods],@PGross [PS Gross],@PTaxAmt [PS Tax],                  
dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(@PNetAmt)) [PS Net Amt (WC)],CONVERT(int,round(@PSQty,0,0)) [PS UOM Qty (RD)],                  
dbo.ConvertAmtINDFormat(dbo.fnGetRoundedValue(@PGoodsAmt)) [PS Goods (WC)],              
@SU1QTY [Total UOM 1 Qty (RD)],@SU1BQTY [Total UOM 1 B Qty (RD)],@REPU1QTY [Total Rep Qty (RD)],@REPU1BQTY [Total Rep B Qty (RD)]              
From dbo.tblTranSalesHeader as Inv                                            
Join dbo.tblTranSalesDetail as Detail on Detail.InvId = Inv.ID                              
left JOIN tblTranCollectionDetail CD ON CD.DocID = Inv.ID AND CD.DocPrefix = Inv.DocPrefix                                            
left JOIN tblTranCollectionHeader CH ON CH.ColID = CD.ColID                                            
LEFT JOIN tblMasterProduct AS Prod ON Prod.ID = Detail.ProdId                                            
join dbo.tblDocumentSeries AS Doc ON Inv. DocPrefix = Doc.TransID                                            
Join dbo.tblMasterCustomer as Cust ON Inv.CustId = Cust.ID                                            
Join dbo.tblMasterTaxType as Tax on Inv.TaxTypeId = Tax.TaxTypeID                                            
Left JOIN tblMasterUserDefineNoHeader AS UDN ON UDN.UDNId=Inv.UDFId                                                                
--Left Join dbo.tblA as Area on Area.GeoID = Cust.areaid    
Left Join dbo.tblMasterTaxType as TaxType on TaxType.TaxTypeID = Cust.taxtypeid                                            
Join dbo.tblUsers as UserTab on UserTab.ID = Inv.MBy or UserTab.ID  = Inv.Cby                                            
Left Join tblMasterBeat as Beat on Beat.ID = Inv.BeatID                                            
Left Join tblMasterSalesMan as SM on SM.ID = Inv.SalesManId                                                                
Left Join dbo.tblPriceType as PriceType on PriceType.Id = Cust.PriceTypeID                                               
LEFT join tblMasterVehicle vh on vh.ID = Inv.VehicleNo                                  
LEFT JOIN tblGSTStateNameandCode GSTST ON GSTST.StateID = Cust.StateID        
WHERE  Inv.Id = @IdentID  AND Inv.DocPrefix IN (16,17)                              
Group By Inv.Id,Inv.InvDate,Inv.MDate,Inv.CDate,Doc.TransName,Inv.DocId,Inv.DocValue,Beat.Name,SM.Name,                     
SM.MobileNo,Cust.Code,Cust.Name,Inv.UDFDocId,UDN.DocName,Cust.mob1,Cust.mob2,Cust.ph1,Cust.Ph2,Cust.Email,Cust.ContactPerson                              
,Cust.Billadd1,Cust.Billadd2,Cust.Billadd3,Cust.shipadd1,Cust.shipadd2,Cust.Shipadd3                              
,cust.Pincode,Cust.PANNumber,Cust.Fssaino,TaxType.TaxTypeName,                              
PriceType.PriceType,Cust.OSValue,Cust.GSTIN,Cust.AadharNo,Tax.TaxTypeName,Inv.CreditDate,                              
Inv.DocRef,Inv.TradeDisc,Inv.AdditionalDisc,Inv.Frieght,                             
Inv.OtherCharge,Inv.OtherChargeAmt,Inv.CreditNoteAdjAmt,Inv.TotalTradeDiscAmt,                            
Inv.TotalProdDiscAmt,Inv.AdditionalDiscAmt,Inv.TotalDiscountAmt,Inv.GrossAmt,Inv.TotalTaxAmt,Inv.RoundOfAmt,                              
Inv.RecievedAmt,Inv.Balance,Inv.NetAmt,UserTab.username,(inv.NetAmt - Inv.CreditNoteAdjAmt),                              
CH.VisaPern,Inv.TCSTaxPern,TCSTaxAmt,IRN,AckNo,AckDate,AckStatus,SignedQRCode,TDSAmount,EWBNo,                            
vh.VehicleNo,Inv.Distance,TransMode,VehicleType,TransportID,TransportName,cust.ClosingTrackPoint,        
GSTST.TINNo,GSTST.StateName,TransactionType    
END',
N'[export] nocount';
GO
/****** uspSalesReturnTransactionDetail ******/
EXEC #Apply07 N'dbo.uspSalesReturnTransactionDetail', 0xF975FDE29E07601BCD93FCF9D70F4863F35ABCE51CCACEC6F8F622E34EC7BD5D, NULL, NULL, 0x8EAE800CDFE211927955E5E05625310F0865152FCE386226A644592246D6BC6C, 0xF7F45D701D624552638248BACD332D0D255D475BE04C5952F0171BB95947D9DE, NULL,
N'ALTER proc [dbo].[uspSalesReturnTransactionDetail]    
 @InvId INT = 15      
 as    
 SET NOCOUNT ON;
begin    
SELECT  SalesHead.DocID [Doc ID],FORMAT(InvDate,''dd-MMM-yyyy'') [Doc Date], Product.Code AS [Product Code], Product.Name AS [Product Name],  Product.EAN as EAN,        
UOM.Name as [Uom Name],[dbo].[fnGetRoundedValue](UomQty)AS [Uom Qty],[dbo].[fnGetRoundedValue](UomPrice) as [Uom Price],
(SalesDetail.BaseUomPrice) AS [Base Uom Price],
(SalesDetail.AdjustQty) [Base Qty], BaseUOM.Name [Base UOM], 
[dbo].[fnGetRoundedValue] (ProdDisc) as [Product Disc %],      
[dbo].[fnGetRoundedValue](SalesDetail.TradeDisc) as [Trade Disc Amount],[dbo].[fnGetRoundedValue](AddnlDisc) as[Additional Disc Amount],      
tax.TaxName as [Tax Name],[dbo].[fnGetRoundedValue] (TaxValue) as [Tax %],[dbo].[fnGetRoundedValue](SalesDetail.GrossAmt) AS [Gross Amountt],      
[dbo].[fnGetRoundedValue]( TaxAmt) AS [Tax Amount],[dbo].[fnGetRoundedValue](SalesDetail.NetAmt) AS [Net Amount],RSN.Name,    
[dbo].[fnGetRoundedValue](SalesDetail.DiffValue) AS [Diff Amount]      
FROM tblTranSalesDetail AS SalesDetail      
join tblTranSalesHeader as SalesHead on SalesHead.id = SalesDetail.InvId      
JOIN tblMasterProduct AS Product ON SalesDetail.ProdId=Product.ID      
LEFT JOIN tblMasterUom AS UOM ON UOM.ID = SalesDetail.UomId
JOIN tblMasterUom BaseUOM ON BaseUOM.ID=Product.BaseUomID  
LEFT JOIN tblMasterTax as tax ON tax.TaxID= SalesDetail.TaxId      
left JOIN tblMasterReason RSN ON RSN.ID = SalesDetail.ReasonID    
WHERE SalesDetail.InvId= @InvId      
group by SalesDetail.InvId,Product.Code,Product.Name,Product.EAN,    
BaseUomPrice,UomQty,UomPrice,SalesHead.TransactionType,UOM.Name,ProdDisc,SalesDetail.TradeDisc,AddnlDisc,Product.SalesCR,SalesDetail.AdjustQty,BaseUOM.Name,     
tax.TaxName,TaxValue,SalesDetail.NetAmt,SalesDetail.GrossAmt,TaxAmt,Serial ,RSN.Name,SalesDetail.DiffValue,SalesHead.DocID,InvDate      
order by Serial      
end',
N'[export] nocount';
GO
/****** uspSalesReturnTransactionHeader ******/
EXEC #Apply07 N'dbo.uspSalesReturnTransactionHeader', 0xB5B1328EE1534D870427945F1BF7891B78DE9A53E123105A981D28F3283C3A23, NULL, NULL, 0xA9EE3D7381AF479CFC74BA1D24074589B69987E1DCCBB21E7827DD6EB57A602A, 0xC3DB694F74D447F72F150C67EF2E52170F8209BE125D89C2539A033ABFDC8DA1, NULL,
N'--uspSalesReturnTransactionHeader    
ALTER proc [dbo].[uspSalesReturnTransactionHeader]      
@StatusID INT = 1,@FromDate DATE = ''2025-03-01'',@ToDate DATE = ''2025-06-21''    
AS    
SET NOCOUNT ON;
BEGIN    
DECLARE @Sts AS TABLE(Status INT)        
IF(@StatusID = 0)        
BEGIN        
INSERT INTO @Sts values (3),(5),(6),(7)    
END        
ELSE IF(@StatusID = 1)        
BEGIN        
INSERT INTO @Sts values (6),(7)    
END     
ELSE        
BEGIN        
INSERT INTO @Sts values(@StatusID)        
END      
    
SELECT SaleHeader.Id AS [ID],case when saleHeader.TransactionType = 2 THEN ''Sale Return'' ELSE ''Damage Return'' END [Transaction],    
SaleHeader. DocId AS [Doc Id],FORMAT(SaleHeader.invdate,''dd-MMM-yyyy'') AS [Doc Date],              
Beat.Name AS [Beat Name],SalesMan.Name AS [Salesman Name],              
cust.Code AS [Customer Code],cust.Name AS [Customer Name],MCT.Name [Customer Type],RT.RatingName Ratings,     
cust.GSTIN AS [GSTIN],TaxType.TaxTypeName AS [Tax Type Name],SaleHeader.DocRef AS [Ref No],              
(CASE WHEN SaleHeader.TradeDisc LIKE ''%[%]''              
THEN CAST([dbo].[fnGetRoundedValue](REPLACE(SaleHeader.TradeDisc,''%'',''''))+''%'' AS NVARCHAR)              
ELSE CAST([dbo].[fnGetRoundedValue](SaleHeader.TradeDisc) AS NVARCHAR) END) AS [Trade Discount %],              
(CASE WHEN SaleHeader.AdditionalDisc LIKE ''%[%]''              
THEN CAST([dbo].[fnGetRoundedValue](REPLACE(SaleHeader.AdditionalDisc,''%'',''''))+''%'' AS NVARCHAR)              
ELSE CAST([dbo].[fnGetRoundedValue](SaleHeader.AdditionalDisc) AS NVARCHAR)END) AS [Additional Discount %],              
[dbo].[fnGetRoundedValue](SaleHeader.Frieght) AS [Freight],          
(CASE WHEN SaleHeader.OtherCharge LIKE ''%[%]''              
THEN CAST([dbo].[fnGetRoundedValue](REPLACE(SaleHeader.OtherCharge,''%'',''''))+''%'' AS NVARCHAR)              
ELSE CAST([dbo].[fnGetRoundedValue](SaleHeader.OtherCharge) AS NVARCHAR)END)AS [Other Charges %],                    
[dbo].[fnGetRoundedValue](SaleHeader.TotalProdDiscAmt) AS [Total Prod Discount Amount],              
[dbo].[fnGetRoundedValue](SaleHeader.TotalTradeDiscAmt) AS [Total Trade Discount Amount],              
[dbo].[fnGetRoundedValue](SaleHeader.AdditionalDiscAmt) AS [Total Additional Discount Amount],              
[dbo].[fnGetRoundedValue](SaleHeader.TotalDiscountAmt) AS [All Discount Amount],              
[dbo].[fnGetRoundedValue](SaleHeader.GrossAmt) AS [Gross Amount],              
[dbo].[fnGetRoundedValue](SaleHeader.TotalTaxAmt) AS [Tax Amount],              
[dbo].[fnGetRoundedValue](SaleHeader.RoundOfAmt) AS [Round off Amount],              
[dbo].[fnGetRoundedValue](SaleHeader.NetAmt) AS [Net Amount],     
dbo.fngetroundedvalue(isnull(SaleHeader.DiffValueGross,0)) [Diff Excl],dbo.fngetroundedvalue(isnull(SaleHeader.DiffValueNet,0)) [Diff Incl],  
s.Description as [Status],MRT.Name AS [Return Type],              
CASE ISNULL(us.username ,'''') WHEN '''' THEN  u.username  ELSE  us.username END [User],        
ORGSH.DocId AS [Org Doc Id],CONVERT(NVARCHAR,ORGSH.InvDate,103)AS [Org Doc Date]        
FROM tblTranSalesHeader as SaleHeader              
JOIN tblMasterCustomer cust ON cust.ID = SaleHeader.CustId              
LEFT JOIN tblMasterBeat Beat ON SaleHeader.BeatID=Beat.ID              
LEFT JOIN tblMasterSalesMan SalesMan ON SaleHeader.SalesManId=SalesMan.ID                      
LEFT JOIN tblMasterTaxType AS TaxType ON TaxType.TaxTypeID = SaleHeader.TaxTypeId              
LEFT JOIN tblUsers AS U ON  U.ID = SaleHeader.CBy              
LEFT JOIN tblUsers AS Us ON  Us.ID = SaleHeader.MBy              
LEFT JOIN tblStatus as s ON s.ID = SaleHeader.Status              
LEFT JOIN tblMasterReturnType AS MRT ON MRT.ID = SaleHeader.ReturnType              
LEFT JOIN tblTranSalesHeader ORGSH ON ORGSH.ID = SaleHeader.OrgInvID    
LEFT JOIN tblMasterCustomerType AS MCT ON  MCT.ID = cust.CustomerType  
LEFT JOIN tblRatings AS RT ON  RT.ID = cust.Rating  
WHERE SaleHeader.InvDate BETWEEN @FromDate AND @ToDate AND SaleHeader.DocPrefix=16 AND SaleHeader.TransactionType IN (2,3)     
AND SaleHeader.Status in (select * from @Sts)      
ORDER BY SaleHeader.DocValue      
END',
N'[export] nocount';
GO
/****** uspSalesTransactionDetail ******/
EXEC #Apply07 N'dbo.uspSalesTransactionDetail', 0x200F9427CEA50B61044BA6A5635E14A876F1C132B3D91A6059FDD84A1B6CEF6D, NULL, NULL, 0x16616779AA67915DEAD53889FF3B0FB09C7B7A8C62B6EB3DC4DE2FD0F1E49117, 0xEBC416849065CDB7FEE871935205CE26170A41FE6B3ABC5798D52C994749BAA5, NULL,
N'--[uspSalesTransactionDetail] 755
--[uspSalesTransactionDetail] 757
ALTER proc [dbo].[uspSalesTransactionDetail]        
@InvId INT = 153      
AS        
SET NOCOUNT ON;
BEGIN        
SELECT SH.DocID [Doc ID],FORMAT(InvDate,''dd-MMM-yyyy'') [Doc Date],SaleDetail.InventoryId,SaleDetail.InvId ,Prod.Code AS [Product Code],Prod .Name AS [Product Name],prod.EAN as [EAN],        
MF.Name AS "Manuf Name",MB.Name "Brand Name",PHL.Name "Category Name"        
,MV.name "Vendor Name"  , PV.MRPONPrice,(SaleDetail.UomPrice) AS [UOM Price],(SaleDetail.UomQty) AS [Uom Qty],         
UOM.Name AS [UOM Name], (BaseUomPrice) AS [Base Uom Price],(SaleDetail.UomQty * PROD.SalesCR) [Base Qty], BaseUOM.Name [Base UOM],      
 (SaleDetail.ProdDisc) AS [Product Discount %],        
isnull((SaleDetail.UomPrice * SaleDetail.UomQty) * (nullif(SaleDetail.ProdDisc,0) / 100),0) "Product Disc Amt",        
isnull((SaleDetail.TradeDisc / nullif((SaleDetail.UomPrice * SaleDetail.UomQty),0) * 100),0) "Trade Disc %",        
isnull((SaleDetail.TradeDisc),0) AS [Trade Discount Amount],        
isnull((SaleDetail.AddnlDisc / nullif((SaleDetail.UomPrice * SaleDetail.UomQty),0) * 100),0) "Additional Disc %",        
isnull((SaleDetail.AddnlDisc),0) AS [Additional Discount Amount],        
Tax.TaxName AS [Tax Name], (SaleDetail.TaxValue) AS [Tax %], (SaleDetail.TaxAmt) AS [Tax Amount],        
(SaleDetail.GrossAmt) AS [Gross Amount],(SaleDetail.NetAmt) AS [Net Amount], isnull((SaleDetail.DiffValue),0) AS [Diff Value],       
MR.Name Reason,      
PV.BatchNumber AS [Batch Number],CONVERT(NVARCHAR,PV.PkDDate,103) AS [PKD Date],        
CONVERT(NVARCHAR,PV.ExpiryDate,103) AS [Expiry Date]      
INTO #TEMP        
FROM tblTranSalesDetail AS SaleDetail        
join tblTranSalesHeader  AS SH ON SH.ID = SaleDetail.InvID    
JOIN tblMasterProduct Prod ON SaleDetail.prodId =Prod.ID        
LEFT join tblProductInventory PV ON PV.InventoryId = SaleDetail.InventoryId        
JOIN tblMasterUom UOM ON SaleDetail.UomId=UOM.ID        
JOIN tblMasterUom BaseUOM ON BaseUOM.ID=Prod.BaseUomID
JOIN tblMasterTax Tax ON SaleDetail.TaxId=Tax.TaxID        
join tblMasterManufacturer MF ON MF.ID = Prod.MfrID        
JOIN tblMasterBrand MB ON MB.ID = Prod.BrandID        
JOIN tblMasterCategory PHL ON PHL.ID = Prod.CategoryID        
LEFT JOIN tblMasterVendor MV ON MV.id = Prod.VendorID        
left join tblMasterReason MR ON MR.ID = SaleDetail.ReasonID      
WHERE SaleDetail.InvId = @InvId AND ISNULL(SaleDetail.TaxId,0)>0        
ORDER BY SaleDetail.Serial        
        
SELECT [Doc ID],[Doc Date],[Product Code],[Product Name],EAN,[Manuf Name] [Mfr Name],[Brand Name],[Category Name],        
dbo.[fnGetRoundedValue](MRPONPrice) [MRP on Price],
dbo.[fnGetRoundedValue]([UOM Price]) [UOM Price],
dbo.[fnGetRoundedValue]([Uom Qty]) [Uom Qty], 
[UOM Name],        
[dbo].[fnGetRoundedValue]([Base Uom Price]) [Base Uom Price],        
dbo.[fnGetRoundedValue]([Base Qty]) [Base Qty],
[Base UOM],
dbo.[fnGetRoundedValue]([Product Discount %]) [Product Discount %],        
dbo.[fnGetRoundedValue]([Product Disc Amt]) [Product Disc Amount],        
dbo.[fnGetRoundedValue]([Trade Disc %]) [Trade Disc %],        
dbo.[fnGetRoundedValue]([Trade Discount Amount]) [Trade Discount Amount],        
dbo.[fnGetRoundedValue]([Additional Disc %]) [Additional Disc %],        
dbo.[fnGetRoundedValue]([Additional Discount Amount]) [Additional Discount Amount],        
dbo.[fnGetRoundedValue]([Product Disc Amt] + [Trade Discount Amount] + [Additional Discount Amount]) AS [All Disc Amount],        
[Tax Name],dbo.[fnGetRoundedValue]([Tax %]) [Tax %],        
dbo.[fnGetRoundedValue]([Tax Amount]) [Tax Amount],        
dbo.[fnGetRoundedValue]([Gross Amount]) [Gross Amount],        
dbo.[fnGetRoundedValue]([Net Amount]) [Net Amount],dbo.[fnGetRoundedValue]([Diff Value]) [Diff Value],Reason,[Batch Number],[PKD Date],[Expiry Date],[Vendor Name] FROM #TEMP        
DROP TABLE #TEMP        
END 

--select * from tblTranSalesDetail order by 2 desc
--select * from tblTranSalesHeader order by 1 desc

--select * from tblMasterUOM',
N'[export] nocount';
GO
/****** uspSalesTransactionHeader ******/
EXEC #Apply07 N'dbo.uspSalesTransactionHeader', 0xCB135AA90CA1C788BC7D05FFFF058CC71F3113FBD5BA5A335DD89BFB6BE412DC, NULL, NULL, 0x57FE67A45D59D358010F2205158CF94EE8347E241F9E3A318C32E7149ED0593F, 0x1E48A3BD4904C998D59505876A71A533345B1C3CE85D55591F42691B98B74D61, NULL,
N'ALTER proc [dbo].[uspSalesTransactionHeader]          
@StatusID INT = 1,@FromDate DATE = ''2025-06-01'',@ToDate DATE = ''2025-06-30''          
AS          
SET NOCOUNT ON;
BEGIN          
DECLARE @Sts AS TABLE(Status INT)          
IF(@StatusID = 0)          
BEGIN          
INSERT INTO @Sts values (1),(3),(5)          
END          
ELSE          
BEGIN          
INSERT INTO @Sts values(@StatusID)          
END          
SELECT SaleHeader.ID,SaleHeader.DocId AS [Doc ID],FORMAT(SaleHeader.invdate, ''dd-MMM-yyyy'')  AS [Invoice Date],FORMAT(SaleHeader.CDate, ''hh:mm tt'') AS [Invoice Time],                  
BO.Name AS [Branch Name],Beat.Name AS [Beat Name],SalesMan.Name AS [SalesMan Name],cust.Name AS [Customer Name],MCT.Name [Customer Type],RT.RatingName Ratings,                  
TaxType.TaxTypeName AS [Tax Type Name],PT.PriceType,SaleHeader.DocRef AS [Ref No],                  
Mode.PaymentMode AS [Payment Mode],cr.Name AS [Credit Term],SaleHeader.CreditDate AS [Credit Date],                   
 dbo.fngetroundedvalue(SaleHeader.TradeDisc) AS [Trade Discount],  dbo.fngetroundedvalue(SaleHeader.AdditionalDisc) AS [Addnl Discount],                  
dbo.fngetroundedvalue(SaleHeader.Frieght) AS [Freight],  dbo.fngetroundedvalue(SaleHeader.OtherCharge) AS [Other Charge],                  
dbo.fngetroundedvalue(SaleHeader.GrossAmt+SaleHeader.TotalProdDiscAmt) AS [Total Goods Amount],                   
dbo.fngetroundedvalue(SaleHeader.TotalProdDiscAmt) AS [Total Product Discount],  dbo.fngetroundedvalue(SaleHeader.TotalTradeDiscAmt) AS [Total Trade Discount],                  
dbo.fngetroundedvalue(SaleHeader.AdditionalDiscAmt) AS [Total Additional Discount],  dbo.fngetroundedvalue(SaleHeader.CreditNoteAdjAmt) AS [Adjusted Amount],                  
dbo.fngetroundedvalue(SaleHeader.TotalDiscountAmt) AS [All Discount Amount],  dbo.fngetroundedvalue(SaleHeader.TCSTaxPern) AS [TCS Tax Pern],                  
dbo.fngetroundedvalue(SaleHeader.TCSTaxAmt) AS [TCS Amount],dbo.fngetroundedvalue(SaleHeader.TDSAmount) TDSAmount,dbo.fngetroundedvalue(SaleHeader.GrossAmt) AS [Gross Amount],                  
dbo.fngetroundedvalue(SaleHeader.TotalTaxAmt) AS [Tax Amount],  dbo.fngetroundedvalue(SaleHeader.RoundOfAmt) AS [Round Off Amount],                  
dbo.fngetroundedvalue(SaleHeader.NetAmt) AS [Net Amount] ,    
dbo.fngetroundedvalue(CONVERT(NVARCHAR,dbo.fnDiffBWNetAmount(SaleHeader.NetAmt,SaleHeader.OrgId))) AS [Net Difference],                  
dbo.fngetroundedvalue(SaleHeader.Balance) as [Balance],     
dbo.fngetroundedvalue(isnull(DiffValueGross,0)) [Diff Excl],dbo.fngetroundedvalue(isnull(DiffValueNet,0)) [Diff Incl], s.Description as [Status],                  
CASE ISNULL(us.username ,'''') WHEN '''' THEN  u.username  ELSE  us.username END [User Name]          
FROM tblTranSalesHeader as SaleHeader                  
JOIN tblMasterCustomer cust ON cust.ID = SaleHeader.CustID              
JOIN tblMasterBranchOffice BO ON BO.ID = SaleHeader.BranchID      
LEFT JOIN tblMasterBeat Beat ON SaleHeader.BeatId=Beat.ID                  
LEFT JOIN tblMasterSalesMan SalesMan ON SaleHeader.SalesManId=SalesMan.ID                     
LEFT JOIN tblMasterTaxType AS TaxType ON TaxType.TaxTypeID = SaleHeader.TaxTypeId                  
LEFT JOIN tblPaymentMode As Mode ON Mode.Id = SaleHeader.ID                  
LEFT JOIN tblMasterCreditTerm As CR ON CR.ID = SaleHeader.CreditTermID                  
LEFT JOIN tblUsers AS U ON  U.ID = SaleHeader.CBy                  
LEFT JOIN tblUsers AS Us ON  Us.ID = SaleHeader.MBy                  
join tblPriceType PT ON PT.ID = SaleHeader.PriceID                  
JOIN tblStatus as s ON s.ID = SaleHeader.Status                  
LEFT JOIN tblMasterCustomerType AS MCT ON  MCT.ID = cust.CustomerType  
LEFT JOIN tblRatings AS RT ON  RT.ID = cust.Rating  
WHERE SaleHeader.DocPrefix=15 AND (SaleHeader.InvDate BETWEEN @FromDate AND @ToDate) AND SaleHeader.Status in (select * from @Sts)     
order by DocValue    
END',
N'[export] nocount';
GO
