EXEC #Apply07 N'dbo.uspSamplePrintDetailSave', 0x83975AB8C930109657D55D723E60C35324A375F3F3D7064F00850C340BA1212F, NULL, NULL, 0x0A5C3617B0FBBC7D7E896F188A6CF75C8CC9EBA0D8B91557E99DDD147E861141, 0xCB03A9135F9569FE98F7E908949C0621E1B1C964AD633BDAB2B55498A0DC7B49, NULL,
N'ALTER proc [dbo].[uspSamplePrintDetailSave]
@Mode int = 1,@PrintID int,@tvpPrintConfigDetail [tvpPrintConfigDetail] readonly
as
SET NOCOUNT ON;
begin
if(@Mode = 1)
BEGIN
