/****** uspSaveBarcodePrinting ******/
EXEC #Apply07 N'dbo.uspSaveBarcodePrinting', 0x2D79346053B631B718E98A45F07835645067D333D3A1D0D1F0928B063F5D0C30, NULL, NULL, 0x600C2CF956FE38832368A7483AF720383443285324130B77C7DB770A6DFE24A3, 0xD743B1039D4FBAE2A684EDF8E5C1B939AEA8A1F02DECC9225B227783431CB938, NULL,
N'ALTER proc [dbo].[uspSaveBarcodePrinting]
@TransMode int,@TransID int,@ID int,@BranchID int,@DocDate date,@RefNo nvarchar(100) = null,@Remarks nvarchar(100) = null,@Narration nvarchar(100) = null,
@UserID int = 0, @tvpTranSaleDetail tvpTranSaleDetail READONLY
as
BEGIN
begin try
--begin tran

SET DATEFORMAT dmy;        
SET NOCOUNT ON;        
DECLARE @ActiveCheck INT,@DocValue INT,@DocID NVARCHAR(255),@PreviousTranDate DATE,@ScopeID INT ,@nCurrStatus INT        
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)        
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)        
declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))        
DECLARE @DocSeriesIdent int     

insert into @tblDocdetails        
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@DocDate between FromDate and ToDate) and BranchID = @BranchID        
and TransID = @TransID        
IF((select count(*) from @tblDocdetails) = 0)        
BEGIN        
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)        
END        
IF((SELECT COUNT(DocValue) FROM tblVanLoadingSlipHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and        
DocDate BETWEEN @F_SD AND @F_ED and TransID = @TransID) != 0)-- and Status in (3,4,5,6)        
BEGIN        
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)        
END        
SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails        
UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = @TransID and ID = @DocSeriesIdent        

insert into tblBarcodePrintHeader(DocDate,TransID,DocID,DocValue,RefNo,BranchID,Remarks,Narration,CBy,CDate,Status)
values (@DocDate,@TransID,@DocID,@DocValue,@RefNo,@BranchID,@Remarks,@Narration,@UserID,GETDATE(),1)

SET @ScopeID =(SELECT SCOPE_IDENTITY());  

DECLARE @ProdID INT,@InventoryId INT  ,@Qty DECIMAL (15,4),@Price DECIMAL (15,4),@MRP DECIMAL (15,4),@ReasionId INT,@Index INT=1     

DECLARE  Cursor_IC CURSOR LOCAL FAST_FORWARD FOR (SELECT ProdID,TempBatchInvId,UomQty,UomPrice,ReasonId,MRP FROM  @tvpTranSaleDetail)                                    
OPEN Cursor_IC                                    
FETCH Cursor_IC INTO @ProdID,@InventoryId,@Qty,@Price,@ReasionId,@MRP                                 
WHILE @@FETCH_STATUS=0                                    
BEGIN                                    
       
INSERT INTO tblBarcodePrintDetail(HID,ProdID,Inventory,Qty,Price,MRP,ReasonID,Serial)                                    
VALUES (@ScopeID,@ProdID,@InventoryId,@Qty,@Price,@MRP  ,@ReasionId,@Index)   
SET @Index=@Index+1;     
FETCH Cursor_IC INTO  @ProdID,@InventoryId,@Qty,@Price,@ReasionId,@MRP                                    
END                                    
CLOSE Cursor_IC                                    
DEALLOCATE Cursor_IC   
--commit tran
select @ScopeID
end try
begin catch
--rollback tran
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE();        
end catch
end',
N'[export] cursor-local-fast_forward=1;number-series-updlock=1;readcommittedlock=3';
GO
/****** uspSaveColumnConfiguration ******/
EXEC #Apply07 N'dbo.uspSaveColumnConfiguration', 0x5A37F8AD87D617EE16CEC88E32413AFC05FFB794E4391DA7500DA87175B2D0F8, NULL, NULL, 0x0D5CB19A959A94AE24642E0841362B0AF672BAA51564854068195BC9B90B813F, 0x2AB989F38620DD9E13EF111617075F0D6BFB355D6BD4A0311E5123D829B306D7, NULL,
N'ALTER Procedure [dbo].[uspSaveColumnConfiguration]
@Mode int = 1,@FormID smallint,@TableID tinyint,@ColumnID SMALLINT,@FormorReport SMALLINT,                  
@DisplayColumnName nvarchar(255),@Width SMALLINT,@Visible TINYINT = 0,@Alignment TINYINT = 1,@DisplayIndex TINYINT = 1,@TotalYN TINYINT = 0             
,@EnableSum TINYINT = 0,@EnableAvg TINYINT = 0,@EnableCount TINYINT = 0,@EnableUnique TINYINT = 0,@EnableColumnMenu TINYINT = 0,@ShowinColumnOption TINYINT = 0             
,@PrintYN TINYINT = 0,@PrintColumnName nvarchar(255) = null,@PrintWidth SMALLINT = 0,@ColumnType SMALLINT = 1,@Permission SMALLINT = 1
AS
SET NOCOUNT ON;
BEGIN
if(@Mode = 1)          
BEGIN        
UPDATE tblColumnSettings SET DisplayColumnName = @DisplayColumnName,Width = @Width,Visible = @Visible,Alignment =  @Alignment,                  
DisplayIndex = @DisplayIndex,TotalYN = @TotalYN,EnableSum = @EnableSum,EnableAvg = @EnableAvg,EnableCount = @EnableCount,EnableUnique = @EnableUnique,EnableColumnMenu = @EnableColumnMenu,            
ShowinColumnOption = @ShowinColumnOption,PrintYN = @PrintYN,PrintColumnName = @PrintColumnName,PrintWidth = @PrintWidth,ColumnType=@ColumnType,Permission = @Permission
WHERE FormID = @FormID and TableID = @TableID and ColumnID = @ColumnID and FormorReport = @FormorReport                  
END          
end',
N'[export] nocount';
GO
/****** uspSaveCustomerfromMobile ******/
EXEC #Apply07 N'dbo.uspSaveCustomerfromMobile', 0x1714366A26C0B9631B30D796BA94ABDC6F3B9EFF04185AEABB4CE8DBEB4D6F71, NULL, NULL, 0x7907F8E9EE62FB07929DD320165E67E9ED1DEDDA694489FC67872D3B2C23BC5B, 0x6702A6D2DA49E1C902B9D4AFBD0269EFA5B400318509FE95C1336E06B3A0654C, NULL,
N'ALTER proc [dbo].[uspSaveCustomerfromMobile]                                      
@Mode int,@ID int = null,@Code nvarchar(255) = null,@Name nvarchar(255) = null,      
@Mob1 nvarchar(25) = null,@GSTIN nvarchar(40) = null,@Pincode nvarchar(15) = null,@Billadd1 nvarchar(MAX) = null      
,@Latitude nvarchar(25) = null,@Longtitude nvarchar(25) = null,@UserID int = 0      
as      
SET NOCOUNT ON;
begin try    
    
IF((SELECT COUNT(*) FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE Name = @Name AND ID != @ID) > 0)    
BEGIN    
RAISERROR(''Customer already exists'',16,1)    
END    
    
UPDATE tblMasterCustomer SET Code = @Code,Name = @Name,Mob1 = @Mob1,GSTIN = @GSTIN,Pincode = @Pincode,  
MobilePinAddress = @Billadd1 ,Latitude = @Latitude,Longtitude = @Longtitude,MBy = @UserID,MDate = GETDATE()      
WHERE ID = @ID          

declare @LocVerifyTracking int = 0,@RoleID int

select @RoleID = RoleID from tblUsers WITH (READCOMMITTEDLOCK) where ID = @UserID
SET @LocVerifyTracking = (SELECT COUNT(*) FROM tblRolePermissions WITH (READCOMMITTEDLOCK) WHERE Role = ISNULL(@RoleID,0) AND PermissionFormId = 569)
IF(@LocVerifyTracking = 1)
BEGIN
INSERT INTO tblCustomerLocVerifyTracking(CustomerID,Status,RequestBy,RequestTime) VALUES (@ID,1,@UserID,GETDATE())
END

SELECT @ID        
end try    
begin catch    
select ERROR_MESSAGE() msg,ERROR_LINE() line,ERROR_PROCEDURE() pro    
end catch',
N'[export] nocount;readcommittedlock=3';
GO
/****** uspSaveCustomerLocationVerification ******/
EXEC #Apply07 N'dbo.uspSaveCustomerLocationVerification', 0x2A166FC51D63E4FCBEA251A01A38B53E2AD33A3D1C09F2B204745D1BF88A8904, NULL, NULL, 0xC011E7FB08477276C1B79C8A70717F3C252E4D70DD72143CA24F19F1EFDA6B16, 0x163012331B7016167BFE94F4B1B14926F93A936D3F0099D15EF481C815DAFA41, NULL,
N'ALTER PROCEDURE [dbo].[uspSaveCustomerLocationVerification]    
    @nMode INT,    
    @nID INT,    
    @nUserID INT,  
    @sRemarks NVARCHAR(500) = NULL  
AS    
BEGIN    
    SET NOCOUNT ON;    
    
    IF @nMode NOT IN (2, 3)    
    BEGIN    
        SELECT ''1'' AS MsgID, ''Invalid Mode specified.'' AS Message;    
        RETURN;    
    END    
    
    BEGIN TRY    
        BEGIN TRANSACTION;    
    
        UPDATE tblCustomerLocVerifyTracking    
        SET Status = @nMode,    
            ApproveorRejectBy = @nUserID,    
            ApproveorRejectTime = GETDATE(),  
            Remarks = @sRemarks  
        WHERE ID = @nID;    
    
        IF (@nMode = 3)    
        BEGIN    
            UPDATE MC    
            SET MC.Latitude = NULL,    
                MC.Longtitude = NULL,
                MC.MobilePinAddress = NULL,
                MC.MBy = @nUserID,
                MC.MDate = GETDATE()
            FROM tblMasterCustomer MC    
            INNER JOIN tblCustomerLocVerifyTracking CLV WITH (READCOMMITTEDLOCK) ON MC.ID = CLV.CustomerID    
            WHERE CLV.ID = @nID;    
    
            DELETE I    
            FROM tblImages I    
            INNER JOIN tblCustomerLocVerifyTracking CLV WITH (READCOMMITTEDLOCK) ON I.ID = CLV.CustomerID    
            WHERE CLV.ID = @nID AND I.FormID = 2;    
        END    
    
        COMMIT TRANSACTION;    
    
        IF (@nMode = 2)    
            SELECT ''0'' AS MsgID, ''Approved Successfully.!!!'' AS Message;    
        ELSE IF (@nMode = 3)    
            SELECT ''0'' AS MsgID, ''Rejected Successfully.!!!'' AS Message;    
    
    END TRY    
    BEGIN CATCH    
        IF @@TRANCOUNT > 0     
            ROLLBACK TRANSACTION;    
    
        SELECT ''1'' AS MsgID, ERROR_MESSAGE() AS Message;    
    END CATCH    
END',
N'[export] readcommittedlock=2';
GO
/****** uspSaveDocumentSeries ******/
EXEC #Apply07 N'dbo.uspSaveDocumentSeries', 0x4C0E531B0D9FBDB85C802F3F83902EADFC2209F9976E64AB342B5B2CA7E94DB5, NULL, NULL, 0x381DAFD5D5AF8C09F3981789086B95B30D3DE872BC9E19D01EC2429D754ACDD5, 0x968916C0820316EF04B424EBB0BC14A7DD6A174946E4F5B31E1336D87706A425, NULL,
N'ALTER proc [dbo].[uspSaveDocumentSeries]      
@Mode INT,@ID int = 0,@BranchID smallint =0,@TransID INT = NULL,@Prefix nvarchar(255) = NULL,@DocVal nvarchar(255) = NULL,@FromDate date = null,      
@ToDate date = null,@UserID smallint = 0,@orgFromDate date = null,@orgToDate date = null,@orgBranch INT = 0,@AlreadyVerified int = 0,    
@VerifiedID int = 0    
as      
SET NOCOUNT ON;
begin      
begin try      
declare @Ident int    
if(@Mode = 1)--NEW      
BEGIN
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where Prefix = @Prefix) > 0) -- and @AlreadyVerified = 0
begin      
raiserror(''<p class="fs-5"><code class="fs-4">%s</code> this Prefix already user in another Financial Year/Branch/Transaction</p>'',16,1,@Prefix)      
end      
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where @FromDate between FromDate and ToDate and BranchID = @BranchID and @AlreadyVerified = 0) > 0)      
begin      
raiserror(''Financial Year already created between From Date'',16,1)      
end      
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where @ToDate  between FromDate and ToDate and BranchID = @BranchID and @AlreadyVerified = 0) > 0)      
begin      
raiserror(''Financial Year already created between To Date'',16,1)      
end      
if(@AlreadyVerified = 0)    
begin    
set @Ident =(select count(*) from (    
select FromDate,ToDate,BranchID from tblYearwiseDocumentSeries WITH (UPDLOCK) group by FromDate,ToDate,BranchID) as rec) + 1    
end    
else    
begin    
set @Ident = @VerifiedID    
end    
insert into tblYearwiseDocumentSeries(ID,TransID,BranchID,FromDate,ToDate,Prefix,DocValue,CBy,CDate) values      
(@Ident,@TransID,@BranchID,@FromDate,@ToDate,@Prefix,@DocVal,@UserID,GETDATE())      
SELECT @Ident    
END      
ELSE if(@Mode = 2)--MODIFY      
BEGIN
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where Prefix = @Prefix and ID != @ID) > 0)-- and @AlreadyVerified = 0
begin      
raiserror(''<p class="fs-5"><code class="fs-4">%s</code> this Prefix already user in another Financial Year/Branch/Transaction</p>'',16,1,@Prefix)      
end    
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where @FromDate  between FromDate and ToDate  and @AlreadyVerified = 0 and       
@orgFromDate not between FromDate and ToDate and ID != @ID) > 0)      
begin      
raiserror(''Financial Year already created between From Date'',16,1)      
end      
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where @ToDate  between FromDate and ToDate and @AlreadyVerified = 0 and      
@orgFromDate not between FromDate and ToDate and ID != @ID) > 0)      
begin      
raiserror(''Financial Year already created between To Date'',16,1)      
end      
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where TransID = @TransID and (@orgFromDate between FromDate and ToDate) and       
@orgToDate between FromDate and ToDate and ID = @ID) = 0)      
begin      
insert into tblYearwiseDocumentSeries(ID,TransID,BranchID,FromDate,ToDate,Prefix,DocValue,CBy,CDate) values      
(@ID,@TransID,@BranchID,@FromDate,@ToDate,@Prefix,@DocVal,@UserID,GETDATE())      
SELECT @ID    
end      
else      
begin      
--UPDATE tblDocumentSeries SET DocPrefix = @Prefix,DocValue = @DocVal WHERE TransID = @TransID       
UPDATE tblYearwiseDocumentSeries SET BranchID = @BranchID,FromDate = @FromDate,ToDate = @ToDate , Prefix = @Prefix,DocValue = @DocVal,    
MBy = @UserID,MDate = GETDATE() WHERE ID = @ID and TransID = @TransID    
SELECT @ID      
enD      
END
ELSE IF(@Mode = 3)--VERIFY PREFIX,FROM,TO DATE ALREADY EXISTS
BEGIN
IF(ISNULL(@ID,0) = 0)--ADD
BEGIN
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where Prefix = @Prefix) > 0) -- and @AlreadyVerified = 0
begin      
raiserror(''<p class="fs-5"><code class="fs-4">%s</code> this Prefix already user in another Financial Year/Branch/Transaction</p>'',16,1,@Prefix)      
end      
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where @FromDate between FromDate and ToDate and BranchID = @BranchID and @AlreadyVerified = 0) > 0)      
begin      
raiserror(''Financial Year already created between From Date'',16,1)      
end      
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where @ToDate  between FromDate and ToDate and BranchID = @BranchID and @AlreadyVerified = 0) > 0)      
begin      
raiserror(''Financial Year already created between To Date'',16,1)      
end 
END
ELSE -- MODIFY
BEGIN
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where Prefix = @Prefix and ID != @ID) > 0)-- and @AlreadyVerified = 0
begin      
raiserror(''<p class="fs-5"><code class="fs-4">%s</code> this Prefix already user in another Financial Year/Branch/Transaction</p>'',16,1,@Prefix)      
end    
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where @FromDate  between FromDate and ToDate  and @AlreadyVerified = 0 and       
@orgFromDate not between FromDate and ToDate and ID != @ID) > 0)      
begin      
raiserror(''Financial Year already created between From Date'',16,1)      
end      
if((select count(*) from tblYearwiseDocumentSeries WITH (UPDLOCK) where @ToDate  between FromDate and ToDate and @AlreadyVerified = 0 and      
@orgFromDate not between FromDate and ToDate and ID != @ID) > 0)      
begin      
raiserror(''Financial Year already created between To Date'',16,1)      
end 
END
END
end try
begin catch
select  ERROR_MESSAGE(),ERROR_LINE(),ERROR_PROCEDURE()      
end catch      
end',
N'[export] nocount;number-series-updlock=14';
GO
/****** uspSaveFAAccOpening ******/
EXEC #Apply07 N'dbo.uspSaveFAAccOpening', 0x94E869E9B6D65FAD8C49873D0F6B33D5B4F8B5CB60DC44E483D4F486E9BD206E, NULL, NULL, 0x1C08A464B4E049B081561D1A5D0B09CFC7DA340E8B8433C8F29A764BCB4D89C5, 0x497ACA726CBE7DC0FA52CE5CFEC7B1AAB70335AE3EF9CF5F3DCF7EC5C0D2771F, NULL,
N'ALTER proc [dbo].[uspSaveFAAccOpening]              
@Mode INT,@OPID INT = 0,@BranchID int = 0,@Period int = 0,@UserID smallint = 0,@tvpFAAccOpening [tvpFAAccOpening] readonly        
AS          
SET NOCOUNT ON;
BEGIN      
begin try        
DECLARE @FAID INT,@FATYPEID INT,@OpenValue decimal(25,4),@NSERIAL INT = 1,@ID INT,      
@NTOTCOUNT INT =(SELECT COUNT(*) FROM @tvpFAAccOpening)        
      
IF(@Mode = 1)      
begin      
if((select count(*) from tblFAAccOpening WITH (READCOMMITTEDLOCK) where DocSeriesID = @Period and BranchID = @BranchID) > 0)            
begin            
raiserror(''Account Opening already created for this Branch and Period'',16,1)            
end        
SET @ID = (SELECT ISNULL(MAX(ID),0) + 1 FROM tblFAAccOpening WITH (READCOMMITTEDLOCK))      
      
WHILE(@NTOTCOUNT >= @NSERIAL)        
BEGIN        
SELECT @FAID = FAID,@FATYPEID = FAType,@OpenValue = OpeningValue FROM @tvpFAAccOpening WHERE ID = @NSERIAL        
      
if((select count(*) from  tblFAAccOpening WITH (READCOMMITTEDLOCK) where DocSeriesID = @Period and BranchID = @BranchID AND FAID = @FAID) > 0)        
begin        
update tblFAAccOpening set FAType = @FATYPEID,OpeningBalance = @OpenValue,MBy = @UserID,MDate = GETDATE() where       
 DocSeriesID = @Period and BranchID = @BranchID AND FAID = @FAID      
end        
else        
begin        
insert into tblFAAccOpening values (@ID,@Period,@BranchID,@FAID,@FATYPEID,@OpenValue,@UserID,GETDATE(),NULL,NULL)          
end        
SET @NSERIAL += 1;        
END       
END      
--      

ELSE IF(@Mode = 2)      
BEGIN      
if((select count(*) from tblFAAccOpening WITH (READCOMMITTEDLOCK) where DocSeriesID = @Period and BranchID = @BranchID AND ID != @OPID) > 0)            
begin            
raiserror(''Account Opening already created for this Branch and Period'',16,1)            
end       
update tblFAAccOpening set DocSeriesID = @Period , BranchID = @BranchID where ID = @OPID
WHILE(@NTOTCOUNT >= @NSERIAL)        
BEGIN        
SELECT @FAID = FAID,@FATYPEID = FAType,@OpenValue = OpeningValue FROM @tvpFAAccOpening WHERE ID = @NSERIAL        
      
if((select count(*) from  tblFAAccOpening WITH (READCOMMITTEDLOCK) where DocSeriesID = @Period and BranchID = @BranchID AND FAID = @FAID) > 0)        
begin        
update tblFAAccOpening set FAType = @FATYPEID,OpeningBalance = @OpenValue,MBy = @UserID,MDate = GETDATE() where       
 DocSeriesID = @Period and BranchID = @BranchID AND FAID = @FAID      
end        
else        
begin        
insert into tblFAAccOpening values (@OPID,@Period,@BranchID,@FAID,@FATYPEID,@OpenValue,@UserID,GETDATE(),@UserID,GETDATE())          
end        
SET @NSERIAL += 1;        
ENd      
end    
END TRY      
begin catch            
select  ERROR_MESSAGE(),ERROR_LINE(),ERROR_PROCEDURE()            
end catch       
END',
N'[export] nocount;readcommittedlock=5';
GO
/****** uspSaveGendralColumnSettings ******/
EXEC #Apply07 N'dbo.uspSaveGendralColumnSettings', 0xC0F3D9E45975EDC19AC4CA9FC1622213CF510231D2D8D160690EB14CFD334FCD, NULL, NULL, 0x57E1AF647A820A1B9E1A7220D9F220B802ED72CAC334D3D5D517A2A11292A301, 0x2A3998C65B69A8BACB4B32E247A57EBD113547183A11E924062D5920DEA0FF9F, NULL,
N'ALTER proc [dbo].[uspSaveGendralColumnSettings]                  
@Mode int = 1,@FormID smallint,@TableID tinyint,@ColumnID SMALLINT,@FormorReport SMALLINT,                  
@DisplayColumnName nvarchar(255),@Width SMALLINT,@Visible TINYINT = 0,@Alignment TINYINT = 1,@DisplayIndex TINYINT = 1,@TotalYN TINYINT = 0             
,@EnableSum TINYINT = 0,@EnableAvg TINYINT = 0,@EnableCount TINYINT = 0,@EnableUnique TINYINT = 0,@EnableColumnMenu TINYINT = 0,@ShowinColumnOption TINYINT = 0             
,@PrintYN TINYINT = 0,@PrintColumnName nvarchar(255) = null,@PrintWidth SMALLINT = 0,@ColumnType SMALLINT = 1           
as                  
SET NOCOUNT ON;
begin            
if(@Mode = 1)          
begin          
if(@FormorReport = 0)        
BEGIN        
UPDATE tblColumnSettings SET DisplayColumnName = @DisplayColumnName,Width = @Width,Visible = @Visible,Alignment =  @Alignment,                  
DisplayIndex = @DisplayIndex,TotalYN = @TotalYN,EnableSum = @EnableSum,EnableAvg = @EnableAvg,EnableCount = @EnableCount,EnableUnique = @EnableUnique,    
EnableColumnMenu = @EnableColumnMenu,ShowinColumnOption = @ShowinColumnOption,ColumnType=@ColumnType   
WHERE FormID = @FormID and TableID = @TableID and ColumnID = @ColumnID and FormorReport = @FormorReport                  
END        
if(@FormorReport = 3)--Transaction GRID
BEGIN 
UPDATE tblColumnSettings SET DisplayColumnName = @DisplayColumnName,Width = @Width,Visible = @Visible
WHERE FormID = @FormID and TableID = @TableID and ColumnID = @ColumnID and FormorReport = @FormorReport    
END
ELSE -- REPORT        
BEGIN        
UPDATE tblColumnSettings SET DisplayColumnName = @DisplayColumnName,Width = @Width,Visible = @Visible,Alignment =  @Alignment,                  
DisplayIndex = @DisplayIndex,TotalYN = @TotalYN,EnableSum = @EnableSum,EnableAvg = @EnableAvg,EnableCount = @EnableCount,EnableUnique = @EnableUnique,EnableColumnMenu = @EnableColumnMenu,            
ShowinColumnOption = @ShowinColumnOption,PrintYN = @PrintYN,PrintColumnName = @PrintColumnName,PrintWidth = @PrintWidth,ColumnType=@ColumnType        
WHERE FormID = @FormID and TableID = @TableID and ColumnID = @ColumnID and FormorReport = @FormorReport                  
END        
end          
else if(@Mode = 2)          
begin          
UPDATE tblColumnSettings SET Width = @Width WHERE FormID = @FormID and TableID = @TableID and ColumnName = @DisplayColumnName and FormorReport = @FormorReport                  
end          
end',
N'[export] nocount';
GO
/****** UspSaveGstReconciliation ******/
EXEC #Apply07 N'dbo.UspSaveGstReconciliation', 0xDB1A4561342B79A5E1403DF3BD91ACECF25262B2DCC005D788FBB9F8C802C879, NULL, NULL, 0x1EA0CDA1CCFADDB7E90D64B8C29AF4605A50EF4DC85088E15D5A393AE4AE3FA0, 0x3A56CD35F39959E7F4EB399AE8D35B11C13241124217C6A33914A31A41CA69CE, NULL,
N'ALTER PROCEDURE [dbo].[UspSaveGstReconciliation]
    @tvpGstReconSave AS tvpGstReconSave READONLY
AS
SET NOCOUNT ON;
BEGIN
BEGIN TRY
  DECLARE @nID INT, @nTransID INT, @PortalDate NVARCHAR(15), @TransDate DATE, @nCount INT = (SELECT COUNT(*) FROM @tvpGstReconSave),
       @Initial INT = 1;

   WHILE (@nCount >= @Initial)
     BEGIN
      SELECT @nID = ID,@nTransID = TransID,@PortalDate = PortalDate,@TransDate = CONVERT(DATE, TransDate)
      FROM @tvpGstReconSave
      WHERE SNO = @Initial;

      IF @nTransID IN (1, 12)
        BEGIN
         UPDATE tblTransPurchaseHeader
        SET PortalDate = NULLIF(@PortalDate, '''')
        WHERE ID = @nID AND TransID = @nTransID
        AND CONVERT(DATE, [Date]) = @TransDate;
        END
        SET @Initial += 1;
        END
    END TRY
    BEGIN CATCH
        SELECT ERROR_LINE(), ERROR_PROCEDURE(), ERROR_MESSAGE();
    END CATCH
END',
N'[export] nocount';
GO
/****** uspSaveImagedata ******/
EXEC #Apply07 N'dbo.uspSaveImagedata', 0x1A9F4CDA6AAAAFA1EB83C0B6C2BF43ACB69C643A034A571972E3112DBEB0405B, NULL, NULL, 0xE356AC14E7E45C075C93188AA0B53FD8C96654F126FB013D20F2B15FD1971416, 0xBECF2F018528469B8E97CA49B183F1C99D868412BB68635D7222678A90BC14F9, NULL,
