/****** uspSaveInvoicefromVLSMobile ******/
EXEC #Apply07 N'dbo.uspSaveInvoicefromVLSMobile', 0x7F7DA0C6C56840F55D6F43810E4F16AD8C172ABFE03AA4FCDDEF01DD8C3A299E, NULL, NULL, 0x2CAD155F80F1803369FD80BE0D80857C104530B142C92647150CD6A9E47FCE01, 0x8A970FEFBED85E75BBEA4448986E3B4710A79D17CCFA7C94B173D931C506B075, NULL,
N'ALTER PROC [dbo].[uspSaveInvoicefromVLSMobile]    
@VLSID INT=NULL,@InvDate DATE =NULL,@BranchId INT=NULL,@BeatId INT=NULL,@SalesManId INT=NULL,@CustId INT=NULL,    
@AppPriceId SMALLINT,@TaxTypeId INT=NULL,@PaymentModeId INT=NULL,@CreditTermId INT=NULL,@DocRef NVARCHAR(255)=NULL,@RoundOfAmt DECIMAL (25,6) =NULL,@TotalGrossAmt DECIMAL (25,6)=NULL,    
@ToatlTaxAmt DECIMAL (25,6)=NULL,@TotalNetAmt DECIMAL (25,6)=NULL,@Status int,@UID INT,    
@tvpTranSaleDetail [tvpTranSaleDetail] READONLY, @InvoiceID INT OUTPUT    
as    
SET NOCOUNT ON;
begin try    
DECLARE @DocValue INT,@DocID NVARCHAR(255),@ScopeID INT,@CreditDate NVARCHAR(25) =NULL,@Accid int    
DECLARE @F_SD DATE = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)    
DECLARE @F_ED DATE = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK) WHERE CompanyId = 1)    
declare @tblDocdetails as table(ID int,DocValue int,Prefix nvarchar(100))    
DECLARE @DocSeriesIdent int    
    
    
insert into @tblDocdetails    
select ID,DocValue,Prefix DocID from tblYearwiseDocumentSeries WITH (UPDLOCK) where (@InvDate between FromDate and ToDate) and BranchID = @BranchID    
and TransID = 15    
IF((select count(*) from @tblDocdetails) = 0)    
BEGIN    
RAISERROR (''Document ID not found for this Branch/Date/Transaction'',16,1)    
END    
    
SELECT @DocValue = DocValue,@DocId = Prefix + Convert(nvarchar, DocValue),@DocSeriesIdent = ID FROM @tblDocdetails    
    
UPDATE tblYearwiseDocumentSeries SET DocValue = @DocValue + 1 WHERE TransID = 15 and ID = @DocSeriesIdent    
    
IF((SELECT COUNT(DocValue) FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE DocID = @DocId and    
InvDate BETWEEN @F_SD AND @F_ED and DocPrefix = 15) != 0)-- and Status in (3,4,5,6)    
BEGIN    
RAISERROR(''<code><h4>%s</h4></code> &ensp;Document ID already exists'',16,1,@DocId)    
END    
    
IF(ISNULL(@CreditTermId,0) > 0)    
BEGIN    
SET @CreditDate = (select DATEADD(DD,CONVERT(INT, Value),CONVERT(DATE,@InvDate)) ADDEDDATE from tblmastercreditterm WITH (READCOMMITTEDLOCK) WHERE id = @CreditTermID)    
END    
ELSE    
BEGIN    
SET @CreditDate=NULL;    
END    
    
-- Header Insert    
INSERT INTO tblTranSalesHeader ([InvDate] ,[DocPrefix],[DocId],[DocValue],[BeatID],[SalesManId],[CustId],BranchID,[PriceID],    
[TaxTypeId],[PaymentModeId],[CreditTermId],[CreditDate],[DocRef],[RoundOfAmt],[GrossAmt],[TotalTaxAmt],[NetAmt],[Balance],[Status],    
[CBY],[CDate],TransactionType,VLSID)    
VALUES(@InvDate,15,@DocId,@DocValue ,@BeatId,@SalesManId,@CustId,@BranchId,@AppPriceId,@TaxTypeId,@PaymentModeId,@CreditTermId,    
@CreditDate,@DocRef,@RoundOfAmt ,@TotalGrossAmt,@ToatlTaxAmt ,@TotalNetAmt,@TotalNetAmt,1,@UID ,GETDATE(),1,@VLSID)    
--Invoice Header Indentity Get At Scope    
SET @ScopeID =(SELECT SCOPE_IDENTITY());    
--Update Track Point when Save    
EXEC [uspAddTrackPoint] @TotalNetAmt,1,@CustId    
    
/* Note :-
User Discount % column used as Adjustqty(BaseQty)  
Reason ID column used as VLSID
*/  
  
-- Detail Insert    
insert into tblTranSalesDetail    
select @ScopeID,TempBatchInvId,UserDisc,ProdId,BaseUomPrice,UomId,UomQty,UomPrice,MRP,0,0,0,0,0,0,GoodsAmt,GrossAmt,    
TaxId,TaxPercentage,TaxAmt,NetAmt,Serial,InvQtyType,0,NULL,NULL,UomCR,ReasonId    
from @tvpTranSaleDetail    
    
--Back Dated Transaction Stored In Initial Table(tblBackDateTran)    
EXEC uspCreateBackTran 1,@BranchID,@ScopeID,0,15,@DocValue ,@InvDate,NULL,@UID    
    
--Get Customer Account Id    
SELECT @Accid=FAID FROM tblMasterCustomer WITH (READCOMMITTEDLOCK) WHERE ID =@CustId    
--Account Posting FA Journal Table    
DECLARE @JVID INT    
SET @JVID=(SELECT (MAX(ISNULL(JVID,0))+1) FROM dbo.tblFAJournal WITH (READCOMMITTEDLOCK))    
SET @Status = 1;    
IF ISNULL(@JVID,0)=0    
BEGIn    
SET @JVID =1    
END    
--Total Net Amount    
IF ISNULL(@TotalNetAmt,0)>0    
BEGIn    
DECLARE @RAmt DECIMAL (25,6)    
SET @RAmt =-1* @RoundOfAmt    
--Customer Account Dr    
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],    
CBy ,CDate,TransId,BranchID )    
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,@Accid,0,(ISNULL(@TotalNetAmt,0)+ISNULL(@RAmt,0)), 0,NULL,''Sales Invoice'',@Status,    
@UID ,GETDATE (),@ScopeID,@BranchID)    
END    
--Total Tax Amount    
IF ISNULL(@ToatlTaxAmt,0)>0    
BEGIN    
--VAT Payable Cr    
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],    
CBy ,CDate,TransId,BranchID)    
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,112,@ToatlTaxAmt,0, 0,NULL,''Sales Invoice'',@Status,    
@UID ,GETDATE (),@ScopeID,@BranchID)    
END    
--Total Gross Amount    
IF ISNULL(@TotalGrossAmt,0)>0    
BEGIN    
--Sales Account Debit Cr    
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],    
CBy ,CDate,TransId ,BranchID )    
VALUES ( @JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,84,ISNULL(@TotalGrossAmt,0),0, 0,NULL,''Sales Invoice'',@Status, @UID ,GETDATE (),@ScopeID,@BranchID)    
END    
    
IF ISNULL(@RoundOfAmt,0)<>0    
BEGIN--Round Off Amt    
SET @JVID=@JVID+1;    
IF ISNULL(@RoundOfAmt,0)>0    
BEGIN    
--Customer Account Dr    
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],    
CBy ,CDate,TransId,BranchID )    
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,@Accid,0,@RoundOfAmt,0,NULL,''Sales Invoice'',@Status,    
@UID ,GETDATE (),@ScopeID,@BranchID )    
--Round Off Acount Postive Cr    
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],    
CBy ,CDate,TransId,BranchID )    
VALUES (@JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,82,@RoundOfAmt,0, 0,NULL,''Sales Invoice'',@Status,    
@UID ,GETDATE (),@ScopeID,@BranchID )    
END    
ELSE IF ISNULL(@RoundOfAmt,0)<0    
BEGIN    
--Round Off Acount Negative Dr    
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],    
CBy ,CDate ,TransId,BranchID )    
VALUES (@JVID, @DocId, 15, @DocValue,@InvDate ,@DocRef ,82,0,ABS(@RoundOfAmt), 0,NULL,''Sales Invoice'',@Status,    
@UID ,GETDATE (),@ScopeID,@BranchID )    
--Customer Account Cr    
INSERT INTO tblFAJournal(JVID,[DocID],[DocPrefix],[DocValue],[DocDate],[DocRef],[AccountID],[Credit],[Debit],[Balance],[Remarks],[Narration],[Status],    
CBy ,CDate,TransId,BranchID )    
VALUES ( @JVID,@DocId, 15, @DocValue,@InvDate ,@DocRef ,@Accid,ABS(@RoundOfAmt),0,0,NULL,''Sales Invoice'',@Status,    
@UID ,GETDATE (),@ScopeID ,@BranchID)    
END    
END    
set @InvoiceID = @ScopeID    
end try    
BEGIN CATCH    
SELECT ERROR_MESSAGE() ,ERROR_PROCEDURE() ,ERROR_LINE();    
END CATCH',
N'[export] nocount;number-series-updlock=1;readcommittedlock=6';
GO
/****** uspSaveLoginHistory ******/
EXEC #Apply07 N'dbo.uspSaveLoginHistory', 0xFC178DAFA3A0312532EA5040E9BFF039D45273D65C5F0F6C18B860D94B187E00, NULL, NULL, 0x1157228358755D1FBE82DC111717F92CB75F8E75BC636F14F30D784BCDEF270D, 0xFE1148A36AB0E281C52926FF8499024F5BC647101F5491DA35B8E97F1C7AE543, NULL,
N'ALTER PROC [dbo].[uspSaveLoginHistory]
@Mode int,@UserID int = 0,@SessionID nvarchar(100) = null,@Latitude nvarchar(100) = null,
@Longtitude nvarchar(100) = null
as
