/****** uspSaveMobileDelivery ******/
EXEC #Apply07 N'dbo.uspSaveMobileDelivery', 0x8D3E59828A56A72BA0D209932955B455691F70CB429D2161E4548FECF561E80F, NULL, NULL, 0x68F383FDA95E237D7219EF9B035678C0E632541224C2750364AFAAD7615F05D7, 0x7F4C48520BAB584AC210ADAB599EB86F81CEB05FE525718FFA706A1E613E52BC, NULL,
N'ALTER proc [dbo].[uspSaveMobileDelivery]    
@DeliveryType int,@InvoiceID int,@BranchID int,@UserID int,@RecieverName nvarchar(255) = null,@Latitude nvarchar(50) = null    
,@Longtitude nvarchar(50) = null    
as    
SET NOCOUNT ON;
begin    
begin try    
if(@DeliveryType = 1)  -- delivery done  
begiN  
IF((select COUNT(*) from tblDeliveryOrderHeader DH WITH (READCOMMITTEDLOCK)    
JOIN tblDeliveryOrderDetail DD WITH (READCOMMITTEDLOCK) ON DD.DOID = DH.ID    
where DH.BranchID = @BranchID AND DD.InvIdentID = @InvoiceID AND DH.Status NOT IN (2,4) AND DD.Status = 5) > 0)    
BEGIN    
RAISERROR(''This Document already Delivered'',16,1);    
END    
UPDATE tblDeliveryOrderDetail SET STATUS = 5,DelivBy = @UserID,DelivTime = GETDATE(),ReceiverName = @RecieverName,    
latitude = @Latitude,Longtitude = @Longtitude WHERE InvIdentID = @InvoiceID    
end    
if(@DeliveryType = 0)  -- cancel delivery  
begin  
UPDATE tblDeliveryOrderDetail SET STATUS = 4,CancelBy = @UserID,CancelDate = GETDATE() WHERE InvIdentID = @InvoiceID    
end  
end try    
begin catch    
select ERROR_LINE(),ERROR_MESSAGE(),ERROR_PROCEDURE()    
end catch    
end',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspSaveMobileVLSData ******/
EXEC #Apply07 N'dbo.uspSaveMobileVLSData', 0x4D2134B721DC48DDFC52166C0261A996E6491D72BCA1F0659B18EBFA5C444D66, NULL, NULL, 0xF11FA5F51DB1D242B5CA8B90FCC8BDE4BE11F97DE2BC36679F5BF930E625D223, 0xB7F1CC94A7F171BD430C0CDA9C521F66D283AB395D101C84669DAF89F578093A, NULL,
N'ALTER proc [dbo].[uspSaveMobileVLSData]    
@ID int = 2,@Status int = 1,@CustomerID int = 24,@SalesmanID int = 17,@UserID int = 2,    
@tvpVLSItemdetails as [tvpVLSItemdetails] readonly,@INVPOSTBranchId INT= 1,@SpotSalePriceMode int = 1    
as    
    
SET NOCOUNT ON;
BEGIN TRY    
SET @ID = 1    
DECLARE @SaleQty DECIMAL(15,4) = 5    
declare @tblTranSaleDetail [tvpTranSaleDetail]    
    
declare @checkStatus int,@InvDetailSerial int= 1,@VLSDocID nvarchar(100),    
@INVPOSTInvDate DATE =GETDATE(),@InvoiceID int;    
    
DECLARE @ValIdentID int,@ValProdID int,@ValAvailableQty DECIMAL(15,4),@CompareAvailableQty DECIMAL(15,4)    
    
DECLARE @InvQtyType INT = 1,@Index INT    
DECLARE @dtluomqty DECIMAL(15,4),@dtluomprice DECIMAL(15,4),@dtlgross DECIMAL(15,4),@dtltax DECIMAL(15,4),    
@dtlnet DECIMAL(15,4),@mrponcumtax DECIMAL(15,4)    
DECLARE @TrackInventory TINYINT,@TrackBatch TINYINT,@TrackPDK TINYINT,@TrackSerial TINYINT,@BatchNumber nvarchar(255),    
@PKDDate DATE,@ExpiryDate DATE    
----    
declare @tvpCount INT, @tvpIndex INT,@TempSerial int    
DECLARE @InsertIdent INT SET @InsertIdent=1;    
DECLARE @InvAdjId INT,@InvAdjQty DECIMAL(25, 4),@InvAdjVLSID INT    
SET @tvpCount =(SELECT COUNT(*) FROM @tvpVLSItemdetails)    
SET @tvpIndex =1    
SET @TempSerial=1    
DECLARE @IdentID INT,@ProdID INT,@AvailableQty DECIMAL(15,4),@AdjustQty DECIMAL(15,4),@UOMPrice DECIMAL(15,4),    
@MRP DECIMAL(15,4),@SaleUomCRate DECIMAL(15,4),@TaxPercentage DECIMAL(15,4),@BaseUomPrice decimal(15,4);    
declare @TaxID smallint,@UOMID smallint    
--Loop through Table Value Parameter(TVP)    
WHILE @tvpCount >0    
BEGIN    
CREATE TABLE #InventoryId (Ident INT IDENTITY ,TempInvId INT,TempInvQty DECIMAL (15,4),TempVLAID int)    
CREATE TABLE #DATA1(ID INT,InventoryID INT,ProdID INT,UomQty DECIMAL (15,4),VLSMQty DECIMAL (15,4),UomPrice DECIMAL (15,4),    
MRP DECIMAL (15,4))    
    
select @IdentID = IdentID,@ProdID = ProdID,@AvailableQty = AvailableQty,@AdjustQty = AdjustQty,    
@UOMPrice = UOMPrice,@MRP = MRP,@SaleUomCRate = UOMCR,@TaxPercentage = TaxPern,    
@BaseUomPrice = BaseUomPrice,@TaxID = TaxID,@UOMID = UOMID    
from @tvpVLSItemdetails where [Index] = @tvpIndex    
    
IF(ISNULL(@SpotSalePriceMode,1) = 1)--VLS PRICE BASE QTY REDUCE(ECP/other price & MRP)    
BEGIN    
INSERT INTO #DATA1    
select VD.ID,VD.InventoryID,VD.ProdID,SUM(VD.UomQty - (ISNULL(VLSMQty,0) + ISNULL(VD.VLSRetrunQty,0))) UomQty,SUM(VD.VLSMQty) VLSMQty,    
VD.UomPrice,VD.MRP    
from tblVanLoadingSlipHeader VH WITH (READCOMMITTEDLOCK)    
JOIN tblVanLoadingSlipDetail VD WITH (READCOMMITTEDLOCK) ON VD.ID = VH.ID    
WHERE VH.SalesmanID = @SalesmanID AND ProdID = @ProdID AND UomPrice = @UOMPrice AND VD.MRP = @MRP
 AND VH.Status not in (4)
AND (UomQty - (ISNULL(VLSMQty,0) + ISNULL(VD.VLSRetrunQty,0))) > 0    
GROUP BY VD.ID,VD.InventoryID,VD.ProdID,VD.UomPrice,VD.MRP    
ORDER BY VD.ID    
END    
ELSE IF(ISNULL(@SpotSalePriceMode,1) = 2)--INVENTORY PRICE BASE QTY REDUCE(MRP)    
BEGIN    
INSERT INTO #DATA1    
select VD.ID,VD.InventoryID,VD.ProdID,SUM(VD.UomQty - (ISNULL(VLSMQty,0) + ISNULL(VD.VLSRetrunQty,0))) UomQty,SUM(VD.VLSMQty) VLSMQty,    
PV.ECP UomPrice,PV.MRPONPrice MRP    
from tblVanLoadingSlipHeader VH WITH (READCOMMITTEDLOCK)    
JOIN tblVanLoadingSlipDetail VD WITH (READCOMMITTEDLOCK) ON VD.ID = VH.ID    
JOIN tblProductInventory PV WITH (READCOMMITTEDLOCK) ON PV.InventoryId = VD.InventoryID
WHERE VH.SalesmanID = @SalesmanID AND VD.ProdID = @ProdID AND PV.MRPONPrice = @MRP  AND VH.Status not in (4)
AND (UomQty - (ISNULL(VLSMQty,0) + ISNULL(VD.VLSRetrunQty,0))) > 0    
GROUP BY VD.ID,VD.InventoryID,VD.ProdID,PV.ECP,PV.MRPONPrice    
ORDER BY VD.ID
END    
    
SET @SaleQty = @SaleUomCRate * @AdjustQty    
    
DECLARE @InventoryId INT,@InventoryQty DECIMAL(25, 4),@VLSID INT    
DECLARE cursor_Inventory CURSOR LOCAL FAST_FORWARD FOR (SELECT InventoryId,UomQty,ID AS Qty FROM #DATA1)    
OPEN cursor_Inventory    
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty,@VLSID    
WHILE @@FETCH_STATUS =0    
BEGIN    
--Loop Exist Qty Adjusted After    
IF(@SaleQty =0)    
BEGIN    
BREAK;    
END    
--Qty Type SALE    
IF(@InvQtyType=1)    
BEGIN IF @SaleQty >@InventoryQty    
BEGIN    
UPDATE tblVanLoadingSlipDetail SET VLSMQty = ISNULL(VLSMQty,0)+ISNULL(@InventoryQty,0)    
WHERE InventoryId =@InventoryId AND ID = @VLSID    
SET @SaleQty =@SaleQty - @InventoryQty    
INSERT INTO #InventoryId VALUES (@InventoryId,@InventoryQty,@VLSID)    
END    
ELSE IF @SaleQty <@InventoryQty    
BEGIN    
UPDATE tblVanLoadingSlipDetail SET VLSMQty = ISNULL(VLSMQty,0)+ISNULL(@SaleQty,0)    
WHERE InventoryId =@InventoryId AND ID = @VLSID    
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty,@VLSID)    
SET @SaleQty =0    
END    
ELSE IF @SaleQty=@InventoryQty    
BEGIN    
UPDATE tblVanLoadingSlipDetail SET VLSMQty = ISNULL(VLSMQty,0)+ISNULL(@SaleQty,0)    
WHERE InventoryId =@InventoryId AND ID = @VLSID    
INSERT INTO #InventoryId VALUES (@InventoryId,@SaleQty,@VLSID)    
SET @SaleQty =0    
END    
END    
FETCH NEXT FROM cursor_Inventory INTO @InventoryId,@InventoryQty,@VLSID    
END    
CLOSE cursor_Inventory    
DEALLOCATE cursor_Inventory    
IF ISNULL(@SaleQty,0) !=0    
BEGIN    
RAISERROR(''Qty Mismatched'',16,1);    
END    
ELSE    
BEGIN    
DECLARE @InsertCount INT=(SELECT COUNT(*) FROM #InventoryId )    
    
SET @Index=1;SET @InsertIdent=1;    
--loop Inentory Adjustment Qty    
SET @mrponcumtax = 0    
WHILE @InsertCount>0    
BEGIn    
SET @InvAdjId = (SELECT TempInvId FROM #InventoryId WHERE Ident=@InsertIdent)    
SET @InvAdjQty = (SELECT TempInvQty FROM #InventoryId WHERE Ident=@InsertIdent)    
SET @InvAdjVLSID = (SELECT TempVLAID FROM #InventoryId WHERE Ident=@InsertIdent)    
    
select @TrackInventory = TrackInventory,@TrackBatch = TrackBatch,@TrackSerial = TrackSerial,@TrackPDK = TrackPDK,    
@BatchNumber = PV.BatchNumber,@PKDDate = PV.PKDDate,@ExpiryDate = PV.ExpiryDate    
from tblMasterProduct MP WITH (READCOMMITTEDLOCK)    
JOIN tblProductInventory PV WITH (READCOMMITTEDLOCK) ON PV.ProdID = MP.ID    
WHERE MP.ID = @ProdID AND PV.InventoryId = @InvAdjId    
    
SELECT @mrponcumtax = ISNULL(SUM(CumulativeTax),0) FROM tblMasterTaxDetail WITH (READCOMMITTEDLOCK) WHERE TaxID = @TaxId AND TaxTypeID = 1 AND AppOn = -1;    
    
IF @Index=1    
BEGIN    
set @dtluomqty = (@InvAdjQty / @SaleUomCRate)    
set @dtluomprice = (@UOMPrice)-- * @SaleUomCRate    
set @dtlgross = (@AdjustQty * @dtluomprice)    
set @dtltax = (select dbo.fngetMRPonTaxValue(2,@dtlgross,@MRP,@TaxId,1))    
SET @dtltax = @dtltax * (CASE WHEN @mrponcumtax > 0 THEN @AdjustQty ELSE 1 END)    
set @dtlnet = @dtlgross + @dtltax    
    
/* Note :-    
User Discount % column used as Adjustqty(BaseQty)    
Reason ID column used as VLSID    
*/    
    
--ProdId InventoryYesNo BatchYesNo PKDYesNo SerialYesNo BaseUomPrice UomId UomQty UomPrice    
--GoodsAmt UserDisc UserDiscAmt ProdDisc ProdDiscAmt TradeDisc TradeDiscPern AddnlDisc    
--AddnlDiscPern GrossAmt TaxId TaxPercentage TaxAmt NetAmt ReasonId Serial    
--BatchNumber PkgDate ExpiryDate InventoryPrice MRP InvQtyType TempBatchInvId UomCR DiffVal    
INSERT INTO @tblTranSaleDetail VALUES (@ProdID,@TrackInventory,@TrackBatch,@TrackPDK,@TrackSerial,@BaseUomPrice,@UOMID,    
@AdjustQty,@UOMPrice,@dtlgross,@InvAdjQty,0,0,0,0,0,0,0,@dtlgross,@TaxID,@TaxPercentage,@dtltax,@dtlnet,@InvAdjVLSID,@tvpIndex,    
@BatchNumber,@PKDDate,@ExpiryDate,(@UOMPrice* @SaleUomCRate),@MRP,1,@InvAdjId,@SaleUomCRate,0)    
ENd    
ELSE    
BEGIN    
INSERT INTO @tblTranSaleDetail VALUES (@ProdID,@TrackInventory,@TrackBatch,@TrackPDK,@TrackSerial,NULL,NULL,    
NULL,null,null,@InvAdjQty,0,0,0,0,0,0,0,null,0,null,null,null,@InvAdjVLSID,@tvpIndex,@BatchNumber,@PKDDate,@ExpiryDate,    
@BaseUomPrice,null,1,@InvAdjId,@SaleUomCRate,0)    
END    
SET @Index=@Index+1    
--Insert Loop Increment    
SET @InsertIdent=@InsertIdent+1;    
SET @InsertCount=@InsertCount-1;    
END    
END    
DROP TABLE #DATA1,#InventoryId    
SET @tvpIndex =@tvpIndex+1    
SET @tvpCount =@tvpCount-1;    
END    
----    
    
    
DECLARE @INVPOSTBeatId INT=NULL,@INVPOSTSalesManId INT=@SalesmanID,@INVPOSTCustId INT=NULL,    
@INVPOSTAppPriceId SMALLINT,@INVPOSTTaxTypeId INT=NULL,@INVPOSTPaymentModeId INT=NULL,@INVPOSTCreditTermId INT=NULL,    
@INVPOSTRoundOfAmt DECIMAL (25,6) =NULL,@INVPOSTTotalGrossAmt DECIMAL (25,6)=NULL,    
@INVPOSTToatlTaxAmt DECIMAL (25,6)=NULL,@INVPOSTTotalNetAmt DECIMAL (25,6)=NULL,    
    
@TempRoundoffAmt DECIMAL (25,6)=NULL,@TempNetAmt DECIMAL (25,6)=NULL    
    
select @INVPOSTTotalGrossAmt = sum(GrossAmt),@INVPOSTToatlTaxAmt = sum(TaxAmt),@TempNetAmt = sum(NetAmt) from @tblTranSaleDetail    
set @INVPOSTRoundOfAmt = (select dbo.fnGetRoundOffandRoundedNetAmount(@TempNetAmt,1))    
set @INVPOSTTotalNetAmt = (select dbo.fnGetRoundOffandRoundedNetAmount(@TempNetAmt,2))    
    
SELECT TOP 1 @INVPOSTBeatId = BeatID FROM tblusers WITH (READCOMMITTEDLOCK) WHERE id = @UserID ORDER BY ID    
    
SELECT @INVPOSTAppPriceId = MC.PriceTypeID,@INVPOSTTaxTypeId = MC.TaxTypeID,    
@INVPOSTPaymentModeId = 7,@INVPOSTCreditTermId = (CASE WHEN ISNULL(MC.CreditTermID,0) = 0 THEN 1 ELSE MC.CreditTermID END)    
FROM tblMasterCustomer MC WITH (READCOMMITTEDLOCK)    
where MC.ID = @CustomerID    
    
    
EXEC uspSaveInvoicefromVLSMobile @ID,@INVPOSTInvDate,@INVPOSTBranchId,@INVPOSTBeatId,@INVPOSTSalesManId,@CustomerID,    
@INVPOSTAppPriceId,@INVPOSTTaxTypeId,@INVPOSTPaymentModeId,@INVPOSTCreditTermId,@VLSDocID,@INVPOSTRoundOfAmt,    
@INVPOSTTotalGrossAmt,@INVPOSTToatlTaxAmt,@INVPOSTTotalNetAmt,1,@UserID,@tblTranSaleDetail,@InvoiceID out    
    
--SET @InvoiceID =(SELECT SCOPE_IDENTITY());    
    
select @ID VLSScopeID,@InvoiceID InvoiceScopeID,@INVPOSTTaxTypeId TaxTypeID,* from @tblTranSaleDetail    
    
END TRY    
BEGIN CATCH    
select ERROR_MESSAGE() EMsg,ERROR_LINE() ELine,ERROR_PROCEDURE() EProc,@ValIdentID ErrorID    
END CATCH',
N'[export] nocount;cursor-local-fast_forward=1;readcommittedlock=10';
GO
/****** UspSavePreferredLanguage ******/
EXEC #Apply07 N'dbo.UspSavePreferredLanguage', 0x00E793C3EB5C0C58196C35B24A03BCD7655CAA0631E7D117B578356919730DBF, NULL, NULL, 0x427047335C39309379A39CF905A238E5619CA2BFB83B2F3A1BEF7B7262B88C7E, 0x7E1AAA5585F17F8807DFA3F14AC81C1A0C1E4FE738CE15BD6A8A950C930E8276, NULL,
N'ALTER PROCEDURE [dbo].[UspSavePreferredLanguage]
    @tvpPLSave AS tvpPreferredLanguageSave READONLY
AS
SET NOCOUNT ON;
BEGIN
BEGIN TRY
    DECLARE @nID INT, @nForm INT,
            @PLName NVARCHAR(200), @Add1 NVARCHAR(200), @Add2 NVARCHAR(200), @Add3 NVARCHAR(200), @Contact NVARCHAR(200),
            @nCount INT = (SELECT COUNT(*) FROM @tvpPLSave),
            @Initial INT = 1;

WHILE (@nCount >= @Initial)
BEGIN
SELECT @nForm = Form, @nID = ID,@PLName = NULLIF(TRIM(PLName), ''''),@Add1 = NULLIF(TRIM(PLBillAdd1), ''''),
@Add2 = NULLIF(TRIM(PLBillAdd2), ''''),@Add3 = NULLIF(TRIM(PLBillAdd3), ''''),@Contact = NULLIF(TRIM(PLContactPerson), '''')
FROM @tvpPLSave
WHERE SNO = @Initial;

IF @nForm = 1
UPDATE tblMasterCustomer
SET PLName = @PLName, PLBillAdd1 = @Add1, PLBillAdd2 = @Add2,
PLBillAdd3 = @Add3, PLContactPerson = @Contact
WHERE ID = @nID;

ELSE IF @nForm = 2
UPDATE tblMasterVendor
SET PLName = @PLName, PLBillAdd1 = @Add1, PLBillAdd2 = @Add2,
PLBillAdd3 = @Add3, PLContactPerson = @Contact
WHERE ID = @nID;

ELSE IF @nForm = 3
UPDATE tblMasterProduct SET PLName = @PLName WHERE ID = @nID;
ELSE IF @nForm = 4
UPDATE tblMasterBeat SET PLName = @PLName WHERE ID = @nID;
ELSE IF @nForm = 5
UPDATE tblMasterSalesman SET PLName = @PLName WHERE ID = @nID;
SET @Initial += 1;
    END
END TRY
BEGIN CATCH
    SELECT ERROR_LINE(), ERROR_PROCEDURE(), ERROR_MESSAGE();
END CATCH
END',
N'[export] nocount';
GO
/****** uspSavePrintConfig ******/
EXEC #Apply07 N'dbo.uspSavePrintConfig', 0xF62C6AD226BC69120FEC43A0528B1DA46BCC735E8BFAFEEDA50D8E257D8A7E85, NULL, NULL, 0x13261AE281B8BC5FE79BD5422FD4B1C141D61B74D6689420A27FE2770C9257C3, 0x88BCF68A3E285F77AB2E4852B84C71279E3D4D927552657DC632D7DE4B5373B1, NULL,
N'ALTER proc [dbo].[uspSavePrintConfig] 
@SaveType NVARCHAR(255),@SaveMode NVARCHAR(255),@PrintID NVARCHAR(255),@ConfigName NVARCHAR(255),@TransactionID NVARCHAR(255),
@Height NVARCHAR(255),@Width NVARCHAR(255),@BoxX NVARCHAR(255),@BoxY NVARCHAR(255),@PrintMode NVARCHAR(255),@DetailItemPerPage NVARCHAR(255),
@ContinuesPaper NVARCHAR(255),@HeaderOnEP NVARCHAR(255),@FooterOnEP NVARCHAR(255),@PaperType NVARCHAR(255),@PaperSizeType NVARCHAR(255),
@BodyLineSpace NVARCHAR(255),@LineFeed NVARCHAR(255),@IncludeCut NVARCHAR(255),@WebPrint NVARCHAR(255),@UserID NVARCHAR(255),
@tvpPrintConfigDetail [tvpPrintConfigDetail] readonly  
AS
SET NOCOUNT ON;
BEGIN
BEGIN TRY
BEGIN TRAN
DECLARE @ScopeID INT
IF(@SaveType = ''saveas'' or (@SaveType = ''save'' and @SaveMode = 1))--@SaveMode - 1 : Add, 2 : Modify
BEGIN
IF EXISTS(SELECT * FROM tblPrintConfig WITH (READCOMMITTEDLOCK) WHERE TransactionID = @TransactionID AND ConfigName = @ConfigName)
BEGIN
RAISERROR(''Config Name already exists'',16,1);
END
INSERT INTO tblPrintConfig (ConfigName,TransactionID,BoxW,BoxH,BoxX,BoxY,PrintMode,DetailItemPerPage,ContinuesPaper,HeaderOnEP,
FooterOnEP,PaperType,PaperSizeType,BodyLineSpace,LineFeed,IncludeCut,WebPrint,CBy,Cdate)
VALUES (@ConfigName,@TransactionID,@Height,@Width,@BoxX,@BoxY,@PrintMode,@DetailItemPerPage,
@ContinuesPaper,@HeaderOnEP,@FooterOnEP,@PaperType,@PaperSizeType,@BodyLineSpace,@LineFeed,@IncludeCut,@WebPrint,
@UserID,GETDATE());
SET @ScopeID = (SELECT SCOPE_IDENTITY())
insert into tblPrintConfigDetail   
select @ScopeID,ctrlName,ctrlWidth,ctrlHeight,ctrlXposition,ctrlYposition,SourceName,FontName,FontSize,FontStyle,Type,Footer,
Bold,Italic,Underline,Align,ImageSource,QRCodeValue,FontColor,WrapText from @tvpPrintConfigDetail  
END
ELSE
BEGIN
IF EXISTS(SELECT * FROM tblPrintConfig WITH (READCOMMITTEDLOCK) WHERE TransactionID = @TransactionID AND ConfigName = @ConfigName AND PrintID != @PrintID)
BEGIN
RAISERROR(''Config Name already exists'',16,1);
END

UPDATE tblPrintConfig SET TransactionID = @TransactionID,BoxW = @Width,BoxH = @Height,BoxX = @BoxX,BoxY = @BoxY,PrintMode = @PrintMode,DetailItemPerPage = @DetailItemPerPage,ContinuesPaper = @ContinuesPaper,
HeaderOnEP = @HeaderOnEP,FooterOnEP = @FooterOnEP,PaperType = @PaperType,PaperSizeType = @PaperSizeType,BodyLineSpace = @BodyLineSpace,
LineFeed = @LineFeed,IncludeCut = @IncludeCut,WebPrint = @WebPrint,MBy = @UserID,Mdate = GETDATE()
WHERE PrintID = @PrintID;

delete from tblPrintConfigDetail where PrintID = @PrintID  

insert into tblPrintConfigDetail   
select @PrintID,ctrlName,ctrlWidth,ctrlHeight,ctrlXposition,ctrlYposition,SourceName,FontName,FontSize,FontStyle,Type,Footer,
Bold,Italic,Underline,Align,ImageSource,QRCodeValue,FontColor,WrapText from @tvpPrintConfigDetail  

SET @ScopeID = @PrintID
END
PRINT ''SAVE''
COMMIT TRAN
SELECT @ScopeID PrintID
END TRY
BEGIN CATCH
ROLLBACK TRAN
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() PRO
END CATCH
END',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspSaveReportColumnSettings ******/
EXEC #Apply07 N'dbo.uspSaveReportColumnSettings', 0xC8FB2A10784680F0900E1235369EEFE7FDAC2A4141862669CF8D1B869E37D3FA, NULL, NULL, 0x4B208C95FC11699D1E390A078CE1C3C3755919BDF74A2387BE453703438190B6, 0x531EED30B653CBD0DC80BE3472452216E02B7562BD89F17E96A7EFDF50851157, NULL,
N'ALTER proc [dbo].[uspSaveReportColumnSettings]    
@ReportID smallint,@TableID tinyint,@ColumnID SMALLINT,@ColumnName nvarchar(255),    
@DisplayColumnName nvarchar(255),@Width SMALLINT,@Visible TINYINT,@Alignment TINYINT,@DisplayIndex TINYINT,@TotalYN TINYINT = 0
as    
SET NOCOUNT ON;
begin    
UPDATE tblReportColumnSettings SET DisplayColumnName = @DisplayColumnName,Width = @Width,Visible = @Visible,Alignment =  @Alignment,    
