/****** uspSaveSchemeDiscount ******/
EXEC #Apply07 N'dbo.uspSaveSchemeDiscount', 0x3805E21B00F4ECE6B9DE5631D0115CC51BE035CBACC27AD3ECFA1074E0AFDA81, NULL, NULL, 0xB75385A31E352EF495E6D6DF16FB49B74EEBAA0391068CB48A991804044583F4, 0xF628F14F60D4430FB3A762D7B830236636F3C2F22BB3E27915553B1CD456D970, NULL,
N'ALTER PROC [dbo].[uspSaveSchemeDiscount]      
@SchemeID INT,@SchemeName NVARCHAR(255),@IsReplace INT,@FromDate DATE,@ToDate DATE,@Active INT,@UID INT,      
@tvpDiscountScheme tvpDiscountScheme READONLY  ,@tvpIdentId tvpIdentId READONLY,@ApplyIn INT
AS      
SET NOCOUNT ON;
BEGIN TRY      
SET DATEFORMAT dmy;      
DECLARE @ScopeID INT      
IF ISNULL(@SchemeID,0) = 0      
BEGIN      
IF ISNULL((SELECT COUNT(*) FROM tblMasterDiscountSchemeHeader WITH (READCOMMITTEDLOCK) WHERE Name = @SchemeName),0) > 0      
BEGIN      
RAISERROR(''1'',16,1)      
END      
SET @SchemeName = (select dbo.ProperCase(@SchemeName))    
INSERT INTO tblMasterDiscountSchemeHeader(Name,IsReplace,FromDate,ToDate,Active,CBy,CDate,ApplyIn)      
VALUES(@SchemeName,@IsReplace,@FromDate,@ToDate,@Active,@UID,GETDATE(),@ApplyIn)      
SET @ScopeID = SCOPE_IDENTITY()      
END      
ELSE      
BEGIN      
IF ISNULL((SELECT COUNT(*) FROM tblMasterDiscountSchemeHeader WITH (READCOMMITTEDLOCK) WHERE Name = @SchemeName AND ID != @SchemeID),0) > 0      
BEGIN      
RAISERROR(''1'',16,1)      
END       
SET @SchemeName = (select dbo.ProperCase(@SchemeName))    
UPDATE tblMasterDiscountSchemeHeader SET Name = @SchemeName,IsReplace = @IsReplace,FromDate = @FromDate,ToDate = @ToDate,    
Active = @Active,MBy = @UID,MDate = GETDATE(),ApplyIn=@ApplyIn WHERE ID = @SchemeID    
    
SET @ScopeID = @SchemeID    
END      
DELETE tblMasterDiscountSchemeDetail WHERE ID = @SchemeID  
DELETE tblMasterDiscountSchemeCustomers WHERE ID = @SchemeID  

INSERT INTO tblMasterDiscountSchemeCustomers
SELECT @ScopeID,DocumentId FROM @tvpIdentId

insert into tblMasterDiscountSchemeDetail
select @ScopeID,0,ProdID,ProdDisc,ProdDiscAmt,TradeDisc,TradeDiscAmt from @tvpDiscountScheme

--DECLARE @Serial INT = 1, @Count INT = (SELECT COUNT(*) FROM @tvpDiscountScheme)      
--DECLARE @ProdDisc DECIMAL(25,4),@ProdDiscAmt DECIMAL(25,4),@TradeDisc DECIMAL(25,4),@TradeDiscAmt DECIMAL(25,4),@CustID INT,@ProdID INT      
--WHILE ISNULL(@Count,0) > 0      
--BEGIN      
--SELECT @CustID= CustID,@ProdID = ProdID,@ProdDisc=ProdDisc,@ProdDiscAmt=ProdDiscAmt,@TradeDisc=TradeDisc,@TradeDiscAmt=TradeDiscAmt      
--FROM @tvpDiscountScheme WHERE Serial = @Serial      
--INSERT INTO tblMasterDiscountSchemeDetail(ID,CustID,ProdID,ProdDisc,ProdDiscAmt,TradeDiscPern,TradeDiscAmt)      
--VALUES(@ScopeID,@CustID,@ProdID,@ProdDisc,@ProdDiscAmt,@TradeDisc,@TradeDiscAmt)      
--SET @Serial = @Serial + 1;      
--SET @Count = @Count - 1;      
--END      
SELECT @ScopeID      
END TRY      
BEGIN CATCH      
SELECT ERROR_MESSAGE(),ERROR_PROCEDURE(),ERROR_LINE()      
END CATCH',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspSaveTranGSTInfo ******/
EXEC #Apply07 N'dbo.uspSaveTranGSTInfo', 0xAEF4384F0F0E1E777A48CBC6AAFE613D3A68D743EEF1867F3E4408C60E59D8F7, NULL, NULL, 0x9F202E39D6FDF71C18F1EAC0A86D6E23C7DB17F1226E50B6528E499AF9FDDE02, 0x86BBE7E17428D8F0A737BAB60185930BFF07908278ECD3F1293388C2B2E0095A, NULL,
N'ALTER PROC [dbo].[uspSaveTranGSTInfo]      
@tvpTranGSTInfo tvpTranGSTInfo READONLY      
AS      
SET NOCOUNT ON;
BEGIN      
DECLARE @Serial INT = 1, @Count INT = (SELECT COUNT(*) FROM @tvpTranGSTInfo)      
WHILE ISNULL(@Count,0) > 0      
BEGIN      
DECLARE @TransID INT,@TransIdentID INT,@ProdID INT,@TaxID INT,@GSTTaxTypeID INT,  
@TaxTypeID INT,@TaxCompID INT,@TaxCompPern DECIMAL(25,6),      
@TaxValue DECIMAL(25,6),@GrossAmount DECIMAL(25,6),@TransSerial INT  
      
SELECT @TransID=TransID,@TransIdentID=TransIdentID,@ProdID=ProdID,@TaxID=TaxID,@GSTTaxTypeID=GSTTaxTypeID,@TaxTypeID=TaxTypeID,      
@TaxCompID=TaxCompID,@TaxCompPern=TaxCompPern,@TaxValue=TaxValue,@GrossAmount=GrossAmount,@TransSerial=TransSerial    
FROM @tvpTranGSTInfo WHERE SerialNo = @Serial      
      
INSERT INTO tblTransGSTInfo  
(TransID,TransIdentID,ProdID,TaxID,TaxTypeID,TaxCompID,TaxCompPern,TaxValue,GrossAmt,Serial,GSTTaxTypeID)      
VALUES      
(@TransID,@TransIdentID,@ProdID,@TaxID,@TaxTypeID,@TaxCompID,@TaxCompPern,@TaxValue,@GrossAmount,@TransSerial,@GSTTaxTypeID)      
      
SET @Serial = @Serial + 1      
SET @Count = @Count - 1      
END      
END',
N'[export] nocount';
GO
/****** uspShrinkDataBase ******/
EXEC #Apply07 N'dbo.uspShrinkDataBase', 0x7290C528E7BBF6174C7DA1A0AF655EFD3329E1E9AE2B5B4899FC38321AFD4944, 0x465F98FF9D503C6817A654C72AE8AF3F52835C87D78DE7FE6A3AED924CB2D435, NULL, 0xFF228E41643D94BF4B07440582B902AB47F311DB5E742843C7C962C15A76F588, 0xE00F4042EEBEC4F4E1A912F85218365C1DCB908F08FF98EDE7ACF421E54016D1, NULL,
N'--[uspShrinkDataBase] ''WSHINE_TEMP01_APR2026''
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspShrinkDataBase]      
@DBName NVARCHAR(255)      
AS      
SET NOCOUNT ON;
BEGIN      

DECLARE @StrQuery NVARCHAR(MAX),@LDFFilename nvarchar(255)
IF DB_ID(@DBName) IS NULL BEGIN RAISERROR(''Database %s not found.'', 16, 1, @DBName); RETURN; END

SELECT  @LDFFilename =  name FROM sys.database_files WHERE type_desc = ''LOG'';

SET @StrQuery = ''ALTER DATABASE ''+QUOTENAME(@DBName)+'' SET RECOVERY SIMPLE''      
EXEC sys.sp_executesql @StrQuery, N''@DBName NVARCHAR(255)'', @DBName      
DBCC SHRINKFILE (@LDFFilename, 1)      
SET @StrQuery = ''ALTER DATABASE ''+QUOTENAME(@DBName)+'' SET RECOVERY FULL''      
EXEC sys.sp_executesql @StrQuery, N''@DBName NVARCHAR(255)'', @DBName      
DBCC FREESESSIONCACHE      
DBCC FREEPROCCACHE      
SELECT ''1''    
END',
N'[06] nocount';
GO
