/****** uspStockDestructionDetailSave ******/
EXEC #Apply07 N'dbo.uspStockDestructionDetailSave', 0x3681BF2F58A0EBD240F7FE433B4DD16AD08F911C3BF9B657E128DFE8D73945A8, NULL, NULL, 0xD270866907C7DCC520E3D2070C733888DFB03EB218E1E08CC2DAC8645E5D1458, 0x1A4E161E4660A90FB801F67C176C0D1313BA18F69639FA06238339BF5FCF4CE4, NULL,
N'ALTER PROC [dbo].[uspStockDestructionDetailSave]    
@BranchID INT,@HeaderID INT,@Date DATE,@ProdID INT ,@Qty DECIMAL(25, 9),@InvID INT,@GrossAmt DECIMAL (25,6),                    
@ReasonId INT,@CBy int = 0    
AS                                      
BEGIN TRY                            
SET NOCOUNT ON;                   
SET DATEFORMAT DMY;                                  
DECLARE @TransDate Date,@BatchNo nvarchar(255),@PKD Date,@Expiry Date,@PurPrice DECIMAL (25,6),@SalePrice DECIMAL (25,6),@ECP DECIMAL (25,6),                            
@SPL DECIMAL (25,6),@MRP DECIMAL (25,6),@TaxID INT,@TaxTypeID INT,@TaxValue INT,@ScopeID INT,                   
@ADQty DECIMAL(25, 9),@ActiveCheck NVARCHAR(255),                          
@GrossAmt1 DECIMAL (25,6) , @Qty1 DECIMAL(25, 9) ,@MRPonPrice DECIMAL (25,6),@DocValue INT      
    
--Get Inventory Table detail                                     
SELECT @ADQty=ActualDmgQty,@Transdate = TransDate, @BatchNo = BatchNumber,@PKD = PKDDate,                    
@Expiry = ExpiryDate,@PurPrice = PurchasePrice, @SalePrice = SalesPrice,@ECP = ECP,@MRP = MRP,@SPL = SPLPrice,@TaxID = TaxId,                    
@TaxTypeID = TaxTypeId,@TaxValue = TaxValue ,@MRPonPrice =MRPONPrice                            
FROM dbo.tblProductInventory WITH (READCOMMITTEDLOCK) WHERE InventoryId = @InvID      
SELECT @DocValue = DocValue FROM tblInventoryHeader WITH (READCOMMITTEDLOCK) WHERE InventoryID = @HeaderID      
IF(@Transdate > @Date)                                    
BEGIN                            
RAISERROR(''2'',16,1);                                  
END                 
--Validate Reason Active                                                                                                                             
UPDATE tblProductInventory SET ActualDmgQty = ActualDmgQty-@Qty WHERE InventoryId = @InvID                                                                
                    
-- Detail table                                                                                         
INSERT INTO dbo.tblInventoryDetail(InventoryID,ProdID,NewBatchID,OrgPurPrice,OrgDmgQty,GrossAmt,ReasonId,ActualDmgQty)          
VALUES(@HeaderID,@ProdID,@InvID,@PurPrice,@Qty,@GrossAmt,@ReasonId, @Qty)  

END TRY                            
BEGIN CATCH                            
SELECT ERROR_MESSAGE (),ERROR_PROCEDURE (),ERROR_LINE ()                            
END CATCH',
N'[export] readcommittedlock=2';
GO
/****** uspSyncMasterData ******/
EXEC #Apply07 N'dbo.uspSyncMasterData', 0xB29C446475845FB6C84A151C1C47F1AD1C8582F3F749B4295E6A3A56BD73BE95, 0x51C045D214D47AAE15E2AF0380D1999941C8CCAB3B405736F192BA54BCC53DD0, NULL, 0x4EF5EF4E0BF730EB8ED78159F318171FB864A1F57DD4774EF09EBEB73B08AC4A, 0xB3D033B654828FA807499071FD7A28D92F013533CEAFC3A68DDEE50365DE6981, NULL,
N'-- Security fix: @TableName must be enabled in tblWebshineMasterSyncTables.
ALTER PROCEDURE [dbo].[uspSyncMasterData]    
@sourcedbname NVARCHAR(128) = ''WSHINE_DEV001_APR2024'',    
@TableName    NVARCHAR(128) = ''tblMasterBank'',    
@SyncDate     DATETIME = ''2026-08-10 19:14:32.937''    
AS
-- Security: only tables enabled for master sync may be synced; @TableName comes from the client.
SET NOCOUNT ON;
IF NOT EXISTS (SELECT 1 FROM dbo.tblWebshineMasterSyncTables WHERE TableName = @TableName AND IsSync = 1)
BEGIN
    SELECT N''Table '' + ISNULL(@TableName, N'''') + N'' is not enabled for master sync.'' MSG, 0 LINE, 50001 ENO;
    RETURN;
END    
BEGIN TRY    
BEGIN TRAN    
DECLARE @qry NVARCHAR(MAX);    
DECLARE @Columns NVARCHAR(MAX);    
DECLARE @SourceColumns NVARCHAR(MAX);    
DECLARE @UpdateColumns NVARCHAR(MAX);    
    
DECLARE @ISNOTCOMMON INT = 0;    
IF(@TableName IN (''tblBeatSalesmanMapping'',''tblMasterChequeBookDetail'',''tblMasterCustomerRemarks'',    
''tblMasterTaxDetail'', ''tblProductLocationMapping'',''tblFAAccount'',''tblFAGroup'',''tblMasterChequeBook'',    
''tblMasterTax'',''tblRolePermissions'',''tblMasterDiscountSchemeDetail''))    
BEGIN    
SET @ISNOTCOMMON = 1    
END    
    
IF(@ISNOTCOMMON = 1)    
BEGIN    
IF(@TableName = ''tblBeatSalesmanMapping'')    
BEGIN    
SET @qry = ''DELETE tblBeatSalesmanMapping WHERE CustomerID IN (    
SELECT CustomerID FROM ''+@sourcedbname+''.dbo.tblMasterCustomer MC    
JOIN ''+@sourcedbname+''.dbo.tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate)    
    
INSERT INTO tblBeatSalesmanMapping    
SELECT BSM.CustomerID,BSM.BeatID,BSM.SalesmanID FROM ''+@sourcedbname+''.dbo.tblMasterCustomer MC    
JOIN ''+@sourcedbname+''.dbo.tblBeatSalesmanMapping BSM ON BSM.CustomerID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate ''    
END    
IF(@TableName = ''tblMasterChequeBookDetail'')    
BEGIN    
SET @qry = ''DELETE tblMasterChequeBookDetail WHERE ChequeBookID IN (    
SELECT ChequeBookID FROM ''+@sourcedbname+''.dbo.tblMasterChequeBook MC    
WHERE COALESCE(MDate,CDate) >= @SyncDate)    
    
INSERT INTO tblMasterChequeBookDetail    
SELECT BSM.ChequeBookID,BSM.ChequeNo,BSM.Status FROM ''+@sourcedbname+''.dbo.tblMasterChequeBook MC    
JOIN ''+@sourcedbname+''.dbo.tblMasterChequeBookDetail BSM ON BSM.ChequeBookID = MC.ChequeBookID    
WHERE COALESCE(MDate,CDate) >= @SyncDate ''    
END    
IF(@TableName = ''tblMasterCustomerRemarks'')    
BEGIN    
SET @qry = ''DELETE tblMasterCustomerRemarks WHERE CustomerID IN (    
SELECT CustomerID FROM ''+@sourcedbname+''.dbo.tblMasterCustomer MC    
JOIN ''+@sourcedbname+''.dbo.tblMasterCustomerRemarks BSM ON BSM.CustomerID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate)    
    
INSERT INTO tblMasterCustomerRemarks    
SELECT BSM.CustomerID,BSM.CustomerRemarks FROM ''+@sourcedbname+''.dbo.tblMasterCustomer MC    
JOIN ''+@sourcedbname+''.dbo.tblMasterCustomerRemarks BSM ON BSM.CustomerID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate ''    
END    
    
IF(@TableName = ''tblMasterTaxDetail'')    
BEGIN    
SET @qry = ''DELETE tblMasterTaxDetail WHERE TaxID IN (    
SELECT MC.TaxID FROM ''+@sourcedbname+''.dbo.tblMasterTax MC    
JOIN ''+@sourcedbname+''.dbo.tblMasterTaxDetail BSM ON BSM.TaxID = MC.TaxID    
WHERE COALESCE(MDate,CDate) >= @SyncDate)    
    
INSERT INTO tblMasterTaxDetail    
SELECT BSM.TaxID,TaxTypeID,TaxCompID,TaxRate,AppOn,PartOff,CumulativeTax,GSTTaxType    
FROM ''+@sourcedbname+''.dbo.tblMasterTax MC    
JOIN ''+@sourcedbname+''.dbo.tblMasterTaxDetail BSM ON BSM.TaxID = MC.TaxID    
WHERE COALESCE(MDate,CDate) >= @SyncDate ''    
END    
IF(@TableName = ''tblProductLocationMapping'')    
BEGIN    
SET @qry = ''DELETE tblProductLocationMapping WHERE ProductID IN (    
SELECT MC.ID FROM ''+@sourcedbname+''.dbo.tblMasterProduct MC    
JOIN ''+@sourcedbname+''.dbo.tblProductLocationMapping BSM ON BSM.ProductID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate)    
    
INSERT INTO tblProductLocationMapping    
SELECT BSM.*    
FROM ''+@sourcedbname+''.dbo.tblMasterProduct MC    
JOIN ''+@sourcedbname+''.dbo.tblProductLocationMapping BSM ON BSM.ProductID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate ''    
END    
IF(@TableName = ''tblMasterDiscountSchemeDetail'')    
BEGIN    
SET @qry = ''DELETE tblMasterDiscountSchemeDetail WHERE ID IN (    
SELECT MC.ID FROM ''+@sourcedbname+''.dbo.tblMasterDiscountSchemeHeader MC    
JOIN ''+@sourcedbname+''.dbo.tblMasterDiscountSchemeDetail BSM ON BSM.ID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate)    
    
INSERT INTO tblMasterDiscountSchemeDetail    
SELECT BSM.*    
FROM ''+@sourcedbname+''.dbo.tblMasterDiscountSchemeHeader MC    
JOIN ''+@sourcedbname+''.dbo.tblMasterDiscountSchemeDetail BSM ON BSM.ID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate ''    

SET @qry += '' DELETE tblMasterDiscountSchemeCustomers WHERE ID IN (    
SELECT MC.ID FROM ''+@sourcedbname+''.dbo.tblMasterDiscountSchemeHeader MC    
JOIN ''+@sourcedbname+''.dbo.tblMasterDiscountSchemeCustomers BSM ON BSM.ID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate)    
    
INSERT INTO tblMasterDiscountSchemeCustomers    
SELECT BSM.*    
FROM ''+@sourcedbname+''.dbo.tblMasterDiscountSchemeHeader MC    
JOIN ''+@sourcedbname+''.dbo.tblMasterDiscountSchemeCustomers BSM ON BSM.ID = MC.ID    
WHERE COALESCE(MDate,CDate) >= @SyncDate '' 
END  
IF(@TableName = ''tblFAAccount'')    
BEGIN    
-- Get columns except ID    
SELECT @Columns = STRING_AGG(QUOTENAME(COLUMN_NAME), '',''),@SourceColumns = STRING_AGG(    
    ''S.'' + QUOTENAME(COLUMN_NAME), '',''),    
    @UpdateColumns = STRING_AGG(''T.'' + QUOTENAME(COLUMN_NAME) + '' = S.'' + QUOTENAME(COLUMN_NAME),'','')    
FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME <> ''FAID'';    
    
SET @qry = N'' UPDATE T    
SET '' + @UpdateColumns + ''    
FROM dbo.'' + QUOTENAME(@TableName) + '' T    
INNER JOIN '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
ON T.FAID = S.FAID WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate;     
    
SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' ON;    
INSERT INTO dbo.'' + QUOTENAME(@TableName) + ''    
(    
    FAID,    
    '' + @Columns + ''    
)    
SELECT    
    S.FAID,    
    '' + @SourceColumns + ''    
FROM '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate    
AND NOT EXISTS    
(    
    SELECT 1    
    FROM dbo.'' + QUOTENAME(@TableName) + '' T    
    WHERE T.FAID = S.FAID    
);    
SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' OFF;'';    
END    
IF(@TableName = ''tblFAGroup'')    
BEGIN    
-- Get columns except ID    
SELECT @Columns = STRING_AGG(QUOTENAME(COLUMN_NAME), '',''),@SourceColumns = STRING_AGG(    
    ''S.'' + QUOTENAME(COLUMN_NAME), '',''),    
    @UpdateColumns = STRING_AGG(''T.'' + QUOTENAME(COLUMN_NAME) + '' = S.'' + QUOTENAME(COLUMN_NAME),'','')    
FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME <> ''FAGroup'';    
    
SET @qry = N'' UPDATE T    
SET '' + @UpdateColumns + ''    
FROM dbo.'' + QUOTENAME(@TableName) + '' T    
INNER JOIN '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
ON T.FAGroup = S.FAGroup WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate;     
    
SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' ON;    
INSERT INTO dbo.'' + QUOTENAME(@TableName) + ''    
(    
    FAGroup,    
    '' + @Columns + ''    
)    
SELECT    
    S.FAGroup,    
    '' + @SourceColumns + ''    
FROM '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate    
AND NOT EXISTS    
(    
    SELECT 1    
    FROM dbo.'' + QUOTENAME(@TableName) + '' T    
    WHERE T.FAGroup = S.FAGroup    
);    
SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' OFF;'';    
END    
--CHQ    
IF(@TableName = ''tblMasterChequeBook'')    
BEGIN    
-- Get columns except ID    
SELECT @Columns = STRING_AGG(QUOTENAME(COLUMN_NAME), '',''),@SourceColumns = STRING_AGG(    
    ''S.'' + QUOTENAME(COLUMN_NAME), '',''),    
    @UpdateColumns = STRING_AGG(''T.'' + QUOTENAME(COLUMN_NAME) + '' = S.'' + QUOTENAME(COLUMN_NAME),'','')    
FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME <> ''ChequeBookID'';    
    
SET @qry = N'' UPDATE T    
SET '' + @UpdateColumns + ''    
FROM dbo.'' + QUOTENAME(@TableName) + '' T    
INNER JOIN '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
ON T.ChequeBookID = S.ChequeBookID WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate;     
    
SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' ON;    
INSERT INTO dbo.'' + QUOTENAME(@TableName) + ''    
(    
    ChequeBookID,    
    '' + @Columns + ''    
)    
SELECT    
    S.ChequeBookID,    
    '' + @SourceColumns + ''    
FROM '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate    
AND NOT EXISTS    
(    
    SELECT 1    
    FROM dbo.'' + QUOTENAME(@TableName) + '' T    
    WHERE T.ChequeBookID = S.ChequeBookID    
);    
SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' OFF;'';    
END    
--TAX    
IF(@TableName = ''tblMasterTax'')    
BEGIN    
-- Get columns except ID    
SELECT @Columns = STRING_AGG(QUOTENAME(COLUMN_NAME), '',''),@SourceColumns = STRING_AGG(    
    ''S.'' + QUOTENAME(COLUMN_NAME), '',''),    
    @UpdateColumns = STRING_AGG(''T.'' + QUOTENAME(COLUMN_NAME) + '' = S.'' + QUOTENAME(COLUMN_NAME),'','')    
FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME = @TableName AND COLUMN_NAME <> ''TaxID'';    
    
SET @qry = N'' UPDATE T    
SET '' + @UpdateColumns + ''    
FROM dbo.'' + QUOTENAME(@TableName) + '' T    
INNER JOIN '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
ON T.TaxID = S.TaxID WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate;     
    
SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' ON;    
INSERT INTO dbo.'' + QUOTENAME(@TableName) + ''    
(    
    TaxID,    
    '' + @Columns + ''    
)    
SELECT    
    S.TaxID,    
    '' + @SourceColumns + ''    
FROM '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate  AND NOT EXISTS    
(    
    SELECT 1    
    FROM dbo.'' + QUOTENAME(@TableName) + '' T    
    WHERE T.TaxID = S.TaxID    
);    
SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' OFF;'';    
END    
IF(@TableName = ''tblRolePermissions'')    
BEGIN    
SET @qry = ''DELETE tblRolePermissions WHERE Role IN (    
SELECT Role FROM ''+@sourcedbname+''.dbo.tblRolePermissions MC    
WHERE CDate >= @SyncDate)    
    
INSERT INTO tblRolePermissions    
SELECT MC.* FROM ''+@sourcedbname+''.dbo.tblRolePermissions MC    
WHERE CDate >= @SyncDate ''    
END    
END    
ELSE    
BEGIN    
-- Get columns except ID    
SELECT    
    @Columns = STRING_AGG(QUOTENAME(COLUMN_NAME), '',''),    
        
    @SourceColumns = STRING_AGG(    
        ''S.'' + QUOTENAME(COLUMN_NAME), '',''    
    ),    
        
    @UpdateColumns = STRING_AGG(    
        ''T.'' + QUOTENAME(COLUMN_NAME) + '' = S.'' + QUOTENAME(COLUMN_NAME),    
        '',''    
    )    
FROM INFORMATION_SCHEMA.COLUMNS    
WHERE TABLE_NAME = @TableName    
  AND COLUMN_NAME <> ''ID'';    
    
    
SET @qry = N''    
    
/* ============================================    
   UPDATE EXISTING RECORDS    
   ============================================ */    
    
UPDATE T    
SET    
    '' + @UpdateColumns + ''    
FROM dbo.'' + QUOTENAME(@TableName) + '' T    
INNER JOIN '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
    ON T.ID = S.ID    
WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate;    
    
    
/* ============================================    
   INSERT NEW RECORDS WITH SAME ID    
   ============================================ */    
''    
SET @qry += CASE WHEN @TableName = ''tblProductTransactionprices'' THEN '''' ELSE    
N'' SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' ON;'' END    
SET @qry += N''    
INSERT INTO dbo.'' + QUOTENAME(@TableName) + ''    
(    
    ID,    
    '' + @Columns + ''    
)    
SELECT    
    S.ID,    
    '' + @SourceColumns + ''    
FROM '' + QUOTENAME(@sourcedbname) + ''.dbo.'' + QUOTENAME(@TableName) + '' S    
WHERE COALESCE(S.MDate, S.CDate) >= @SyncDate    
AND NOT EXISTS    
(    
    SELECT 1    
    FROM dbo.'' + QUOTENAME(@TableName) + '' T    
    WHERE T.ID = S.ID    
);''    
    
SET @qry += CASE WHEN @TableName = ''tblProductTransactionprices'' THEN '''' ELSE    
N''SET IDENTITY_INSERT dbo.'' + QUOTENAME(@TableName) + '' OFF; ''END    
    
END    
--PRINT @qry;    
    
EXEC sp_executesql    
    @qry,    
    N''@SyncDate DATETIME'',    
    @SyncDate = @SyncDate;    
        
    
COMMIT TRAN;    
END TRY    
BEGIN CATCH    
ROLLBACK TRAN;    
select ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_NUMBER() ENO    
END CATCH',
N'[01] nocount';
GO
/****** usptempprdraftbatch ******/
EXEC #Apply07 N'dbo.usptempprdraftbatch', 0x268E0A5FE18F56A63319D9B578D382894BE07F445B4DA40982D7C17FD659DC87, NULL, NULL, 0x1CD8EE307C7757105BA2C29FF74FA800612A698F0A78C53DFF750B240AA8CE12, 0xAFE84FD37D59FF124E7656F63290F13C3BD74761E463CAD4F332108FCF8A432E, NULL,
N'ALTER proc [dbo].[usptempprdraftbatch]
as
SET NOCOUNT ON;
begin
DECLARE @BID INT ,@TDate DATE,@ApplyPrice int,@ID   int = 97
SELECT @BID = BranchID,@TDate =Date,@ApplyPrice = PriceType FROM tblPurchaseDraftHeader where ID = @ID          

CREATE TABLE #MainDraftData
(
    InventoryId     INT,
    ProdID          INT,
    BatchNumber     NVARCHAR(50) NULL, 
    PKDDate         DATE NULL,
    ExpiryDate      DATE NULL,
    Qty             DECIMAL(18,4),
    FreeQty         DECIMAL(18,4),
    DmgQty          DECIMAL(18,4),
    MRP             DECIMAL(18,4),
    PurchasePrice   DECIMAL(18,4),
    ReturnPrice     DECIMAL(18,4),
    PRQty           DECIMAL(18,4),
    PRFree          DECIMAL(18,4),
    PRDmg           DECIMAL(18,4),
    TaxName         NVARCHAR(100),
    GSTPern         DECIMAL(5,2),
    PurchaseTaxID   INT,
    ConversionRate  DECIMAL(18,4)
);


select PD.*,MTT.TaxName into #draftdetails from tblPurchaseDraftDetail PD
join tblMasterTax MTT ON MTT.TaxID = PD.TaxID where hid = @ID
ALTER TABLE #draftdetails ADD RowID INT IDENTITY(1,1);

DECLARE @PRODID INT,@MRP DECIMAL(25,4),@PPrice DECIMAL(25,4),@RTNPrice DECIMAL(25,4),@batchno nvarchar(255),
@pkd date,@expiry date,@qty DECIMAL(25,4),@freeqty DECIMAL(25,4),@dmgqty DECIMAL(25,4),@TaxName nvarchar(255),
@GSTPern  DECIMAL(25,4),@PurchaseTaxID INT,@ConversionRate  DECIMAL(25,4)


declare @n int = 1,@totcount int = (select count(*) from #draftdetails)

while(@totcount >= @n)
BEGIN
select @PRODID = ProdID,@batchno =  isnull(BatchNo,''''),@pkd = PKD,@expiry = Expiry,@qty =  UomQty,
@freeqty = UomFreeQty,@dmgqty = UomDamageQty,@PPrice = UomPurchasePrice,@RTNPrice = UomReturnPrice,
@MRP = UomMRP,@TaxName = TaxName,@GSTPern = TaxPern,@PurchaseTaxID = TaxID,@ConversionRate = ISNULL(UOMCF,1) 
from #draftdetails WHERE RowID = @n

SELECT ProdID,BatchNumber,PKDDate,ExpiryDate,SUM(Qty) Qty,SUM(FreeQty) FreeQty,SUM(DmgQty) DmgQty,MRP,PurchasePrice,ReturnPrice
 into #prodinvdata FROM (
select PV.ProdID,ISNULL(PV.BatchNumber,'''') BatchNumber,convert(date,PV.PKDDate,105) PKDDate,convert(date,PV.ExpiryDate,105) ExpiryDate,
(SUM(ISNULL(ActualQty,0))) Qty,(SUM(ISNULL(ActualFreeQty,0))) FreeQty,(SUM(ISNULL(ActualDmgQty,0))) DmgQty,          
(PV.MRPONPrice) MRP,(case when @ApplyPrice = 6 THEN PV.ReturnPrice ELSE PV.PurchasePrice end) PurchasePrice,          
(case when @ApplyPrice = 6 THEN PV.ReturnPrice ELSE PV.PurchasePrice end) ReturnPrice
from tblProductInventory PV 
where (ProdID = @PRODID and branchid = @bid and TransDate <= @TDate) AND (ActualQty > 0 OR ActualFreeQty > 0 OR ActualDmgQty > 0)
GROUP BY PV.BatchNumber,PV.PKDDate,PV.ExpiryDate,PV.MRPONPrice,PV.ReturnPrice,PV.ProdID,PV.PurchasePrice) AS GRP
GROUP BY ProdID,BatchNumber,PKDDate,ExpiryDate,MRP,PurchasePrice,ReturnPrice
ALTER TABLE #prodinvdata ADD IDENT INT IDENTITY(1,1);

DECLARE @nPV INT = 1,@totPV int = (select count(*) from #prodinvdata)
declare @pvProdID int,@pvBatchNumber nvarchar(255),@pvPKDDate date,@pvExpiryDate date,@pvQty DECIMAL(25,4),
@pvFreeQty DECIMAL(25,4),@pvDmgQty DECIMAL(25,4),@pvMRP DECIMAL(25,4),@pvPurchasePrice DECIMAL(25,4),@pvReturnPrice DECIMAL(25,4)

while(@totPV >= @nPV)
BEGIN

select @pvProdID=ProdID,@pvBatchNumber= isnull(BatchNumber,''''),	@pvPKDDate=PKDDate,	@pvExpiryDate=ExpiryDate,@pvQty=Qty,@pvFreeQty=FreeQty,
@pvDmgQty=DmgQty,@pvMRP=MRP,@pvPurchasePrice=PurchasePrice,@pvReturnPrice=ReturnPrice
from #prodinvdata where IDENT = @nPV

declare @adjQty decimal(25,4) = 0,@adjFreeQty decimal(25,4) = 0,@adjDmtQty decimal(25,4) = 0
declare @compareprice decimal(25,4) = (case when @ApplyPrice = 1 then @PPrice else @RTNPrice end)
declare @compareProdInvprice decimal(25,4) = (case when @ApplyPrice = 1 then @pvPurchasePrice else @pvReturnPrice end)
--select @qty qty,@freeqty freeqty,@dmgqty dmgqty,@compareprice compareprice,@compareProdInvprice compareProdInvprice,@MRP MRP,@pvMRP pvMRP,@batchno batchno,
--@pvBatchNumber pvBatchNumber,@pkd pkd,@pvPKDDate pvPKDDate,@expiry expiry,@pvExpiryDate pvExpiryDate
if(@compareprice = @compareProdInvprice and @MRP = @pvMRP and isnull(@batchno,'''') = isnull(@pvBatchNumber,'''') 
and  isnull(@pkd,'''') =  isnull(@pvPKDDate,'''') and  isnull(@expiry,'''') =  isnull(@pvExpiryDate,''''))
begin
print ''assign qty''
set @adjQty = @qty;
set @adjFreeQty = @freeqty;
set @adjDmtQty = @dmgqty;
end

insert into #MainDraftData values(0,@PRODID,@pvBatchNumber,@pvPKDDate,@pvExpiryDate,@pvQty,@pvFreeQty,@pvDmgQty,@pvMRP,
@pvPurchasePrice,@pvReturnPrice,@adjQty,@adjFreeQty,@adjDmtQty,@TaxName,@GSTPern,@PurchaseTaxID,@ConversionRate
)

SET @nPV += 1
end

drop table #prodinvdata
SET @n += 1
END

--select * from tblProductInventory pv

--SELECT InventoryId,ProdID,BatchNumber,PKDDate,ExpiryDate,(SUM(Qty)) Qty,(SUM(FreeQty)) FreeQty          
--,(SUM(DmgQty)) DmgQty,MRP,PurchasePrice,ReturnPrice,(SUM(PRQty)) PRQty,(SUM(PRFree)) PRFree          
--,(SUM(PRDmg)) PRDmg,TaxName,GSTPern,PurchaseTaxID,ConversionRate FROM (          
--SELECT 0 InventoryId,PV.ProdID,PV.BatchNumber,convert(date,PV.PKDDate,105) PKDDate,convert(date,PV.ExpiryDate,105) ExpiryDate,(SUM(ActualQty)) Qty,          
--(SUM(ActualFreeQty)) FreeQty,(SUM(ActualDmgQty)) DmgQty,          
--(PV.MRPONPrice) MRP,(case when @ApplyPrice = 6 THEN PV.ReturnPrice ELSE PV.PurchasePrice end) PurchasePrice,          
--(case when @ApplyPrice = 6 THEN PV.ReturnPrice ELSE PV.PurchasePrice end) ReturnPrice,(SUM(UomQty)) PRQty,          
--(SUM(UomFreeQty)) PRFree,(SUM(UomDamageQty)) PRDmg,MTT.TaxName,PD.TaxPern GSTPern,PD.TaxID PurchaseTaxID,isnull(UOMCF,1) ConversionRate          
--FROM tblPurchaseDraftDetail PD          
-- JOIN tblProductInventory PV ON  PV.ProdID = PD.ProdID
--join tblMasterTax MTT ON MTT.TaxID = PD.TaxID          
--WHERE PD.HID = @ID and TransDate <= @TDate-- and (ActualQty > 0 OR ActualDmgQty > 0)          
--GROUP BY PV.BatchNumber,PV.PKDDate,PV.ExpiryDate,PV.MRPONPrice,PV.ReturnPrice,PV.ProdID,MTT.TaxName,PD.TaxPern,
--PD.TaxID,UOMCF,PV.PurchasePrice) AS REC          
----where (Qty > 0 or FreeQty > 0 or DmgQty > 0)          
--group by InventoryId,ProdID,BatchNumber,PKDDate,ExpiryDate,MRP,PurchasePrice,ReturnPrice,TaxName,
--GSTPern,PurchaseTaxID,ConversionRate    

select * from #MainDraftData
drop table #draftdetails,#MainDraftData
end',
N'[export] nocount';
GO
/****** uspTransProductAutocomplete ******/
EXEC #Apply07 N'dbo.uspTransProductAutocomplete', 0x29C54EC859405813301B9A09B4D39A5123230B9A59A6FAC0B12397D10E0610AC, NULL, NULL, 0xB52D7BF8D2FD3F31341679FD8C9E919155FB1B3A3740740432A8B637CC6B8A3B, 0x24913D0F221B852C0A4110C72767C15BC9B6F0CFD5CC78D70FC69C0C9CAD4C6E, NULL,
N'--[uspTransProductAutocomplete] 15,1,2,''2025-07-19''            
ALTER proc [dbo].[uspTransProductAutocomplete]              
@DocPrefix INT = 12,@BranchID INT=4,@PriceTypeID int=6,@Date date=''2025-05-19''              
as              
SET NOCOUNT ON;
BEGIN              
CREATE TABLE #ABS(ProdID INT,ABSQty DECIMAL(25,4),ABSFreeQty DECIMAL(25,4),ABSDmgQty DECIMAL(25,4))              
DECLARE @StockOnly INT =  (SELECT AppValue FROM tblAppConfig WHERE AppId = 24)      
DECLARE @ItemsOrderby INT =  (SELECT AppValue FROM tblAppConfig WHERE AppId = 11)      
INSERT into #ABS               
SELECT ProdID,SUM(ISNULL(ActualQty,0)) ABSQty,SUM(ISNULL(ActualFreeQty,0)) ABSFreeQty,SUM(ISNULL(ActualDmgQty,0)) ABSDmgQty           
FROM tblProductInventory WHERE BranchID = @BranchID                   
AND TransDate <= @Date              
GROUP BY ProdID              
IF(@DocPrefix = 15)-- INVOICE              
BEGIN              
SELECT MP.ID,MP.Code,MP.Name,MP.EAN,MP.HSNCode,dbo.fnGetRoundedValue(CASE WHEN @PriceTypeID = 1 THEN PurchasePrice WHEN @PriceTypeID = 2 THEN SalesPrice WHEN @PriceTypeID = 3 THEN ECP                              
WHEN @PriceTypeID = 4 THEN MRP WHEN @PriceTypeID = 5 THEN SPLPrice WHEN @PriceTypeID = 6 THEN ReturnPrice ELSE 0 END) Price,                  
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) + '' + ''+dbo.fnGetRoundedValue(ISNULL(AB.ABSFreeQty,0)) ABSandFreeQty,    
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) ABSQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSFreeQty,0)) ABSFreeQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSDmgQty,0)) ABSDmgQty,
ML.NAME LocationName,MP.Shinecode           
FROM tblMasterProduct MP                       
LEFT JOIN #ABS AB ON AB.ProdID = MP.ID                
LEFT JOIN tblMasterLocation ML ON ML.ID = MP.LOCATIONID                
WHERE MP.Active = 1 AND ISNULL(AB.ABSQty,0) > (CASE WHEN @StockOnly = 1  AND MP.TrackInventory = 1 THEN 0 ELSE -1 END)       
ORDER BY (case when @ItemsOrderby = 1 then code else MP.Name end)      
END              
IF(@DocPrefix = 16 or @DocPrefix = 17)--  SALES RETURN              
BEGIN              
SELECT MP.ID,MP.Code,MP.Name,MP.EAN,MP.HSNCode,dbo.fnGetRoundedValue(CASE WHEN @PriceTypeID = 1 THEN PurchasePrice WHEN @PriceTypeID = 2 THEN SalesPrice WHEN @PriceTypeID = 3 THEN ECP                              
WHEN @PriceTypeID = 4 THEN MRP WHEN @PriceTypeID = 5 THEN SPLPrice WHEN @PriceTypeID = 6 THEN ReturnPrice ELSE 0 END) Price,                  
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) + '' + ''+dbo.fnGetRoundedValue(ISNULL(AB.ABSFreeQty,0)) ABSandFreeQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) ABSQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSFreeQty,0)) ABSFreeQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSDmgQty,0)) ABSDmgQty,    
ML.NAME LocationName,MP.Shinecode FROM tblMasterProduct MP                       
LEFT JOIN #ABS AB ON AB.ProdID = MP.ID                
LEFT JOIN tblMasterLocation ML ON ML.ID = MP.LOCATIONID                
WHERE MP.Active = 1 AND MP.TrackInventory = 1 ORDER BY (case when @ItemsOrderby = 1 then code else MP.Name end)                       
END              
IF(@DocPrefix = 1)--  Purchase Bill              
BEGIN              
SELECT MP.ID,MP.Code,MP.Name,MP.EAN,MP.HSNCode,dbo.fnGetRoundedValue(mp.PurchasePrice) Price,                  
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) ABSandFreeQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) ABSQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSFreeQty,0)) ABSFreeQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSDmgQty,0)) ABSDmgQty,    
ML.NAME LocationName,MP.Shinecode FROM tblMasterProduct MP                       
LEFT JOIN #ABS AB ON AB.ProdID = MP.ID                
LEFT JOIN tblMasterLocation ML ON ML.ID = MP.LOCATIONID                
WHERE MP.Active = 1 AND MP.TrackInventory = 1              
ORDER BY (case when @ItemsOrderby = 1 then code else MP.Name end)                       
END              
IF(@DocPrefix = 12)--  Purchase Return              
BEGIN              
SELECT MP.ID,MP.Code,MP.Name,MP.EAN,MP.HSNCode,dbo.fnGetRoundedValue(case when @PriceTypeID = 6 then mp.ReturnPrice else mp.PurchasePrice end) Price,                  
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) ABSandFreeQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) ABSQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSFreeQty,0)) ABSFreeQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSDmgQty,0)) ABSDmgQty,    
ML.NAME LocationName,MP.Shinecode FROM tblMasterProduct MP                       
LEFT JOIN #ABS AB ON AB.ProdID = MP.ID                
LEFT JOIN tblMasterLocation ML ON ML.ID = MP.LOCATIONID                
WHERE MP.Active = 1 AND MP.TrackInventory = 1 and (ISNULL(AB.ABSQty,0) > 0 OR ISNULL(ABSFreeQty,0) > 0 OR ISNULL(ABSDmgQty,0) > 0)           
ORDER BY (case when @ItemsOrderby = 1 then code else MP.Name end)                       
END  
IF(@DocPrefix = 25)--  Barcode Printing       
BEGIN              
SELECT MP.ID,MP.Code,MP.Name,MP.EAN,MP.HSNCode,dbo.fnGetRoundedValue(CASE WHEN MP.BarcodePriceID = 1 THEN PurchasePrice WHEN @PriceTypeID = 2 THEN SalesPrice WHEN @PriceTypeID = 3 THEN ECP                              
WHEN MP.BarcodePriceID = 4 THEN MRP WHEN MP.BarcodePriceID = 5 THEN SPLPrice WHEN MP.BarcodePriceID = 6 THEN ReturnPrice ELSE 0 END) Price,                  
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) + '' + ''+dbo.fnGetRoundedValue(ISNULL(AB.ABSFreeQty,0)) ABSandFreeQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSQty,0)) ABSQty,
dbo.fnGetRoundedValue(ISNULL(AB.ABSFreeQty,0)) ABSFreeQty,dbo.fnGetRoundedValue(ISNULL(AB.ABSDmgQty,0)) ABSDmgQty,
ML.NAME LocationName,MP.Shinecode           
FROM tblMasterProduct MP                       
LEFT JOIN #ABS AB ON AB.ProdID = MP.ID                
LEFT JOIN tblMasterLocation ML ON ML.ID = MP.LOCATIONID                
WHERE MP.Active = 1 AND ISNULL(AB.ABSQty,0) > (CASE WHEN @StockOnly = 1  AND MP.TrackInventory = 1 THEN 0 ELSE -1 END)  
and ISNULL(MP.BarcodeEnable,0) = 1  
ORDER BY (case when @ItemsOrderby = 1 then code else MP.Name end)                     
END   
drop table #ABS                
END',
N'[export] nocount';
GO
/****** uspUpdateClsStockRepost ******/
EXEC #Apply07 N'dbo.uspUpdateClsStockRepost', 0xF721784260D8CA03F7B1B4E33AFF6F0FAF30AE22E73F1CBEEE9E7AFA02FC64AB, NULL, NULL, 0xBD0DEAB43E00A54538B3619C287C7927A432A4B1D9C556B318F76FA9E0507AB1, 0xEC7BB3131F38F2003FBD0A7B1FC3F965B82F251844F91DF3458530DD6A43CAB1, NULL,
N'--[uspUpdateClsStockRepost] 2                
ALTER PROC [dbo].[uspUpdateClsStockRepost]                
@Mode INT,@TranDate DATE = NULL                
AS                
SET NOCOUNT ON;
BEGIN                
begin try                
begin tran                
SET DATEFORMAT DMY;                
DECLARE @ClsDate DATE = (SELECT UpdateClsDate FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)),@FromDate DATE,@ToDate DATE,@FED date                
CREATE TABLE #AllTransRecords(TRANSNAME NVARCHAR(255),TransDate DATE,BranchID INT,ProdID INT,BatchNo NVARCHAR(255),PKDDate DATE,EXPDate DATE,                
AQty DECIMAL(25,6),FQty DECIMAL(25,6),DQty DECIMAL(25,6),PPrice DECIMAL(25,6))                
CREATE INDEX ix_TEMPTransDate ON #AllTransRecords(TransDate)                
CREATE TABLE #TempFinalClsStock                
(                
TransDate DATE,BranchID INT,ProdID INT,BatchNo NVARCHAR(255),PKDDate DATE,EXPDate DATE,AQty DECIMAL(25,6),FQty DECIMAL(25,6),DQty DECIMAL(25,6),                
PPrice DECIMAL(25,6)                
)                
CREATE INDEX ix_TEMPTransDate2134 ON #TempFinalClsStock(TransDate)                
set @FED = (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK))                
IF(@Mode != 3)                
BEGIN               
        
IF(@Mode = 1)                
BEGIN                
SET @FromDate = (SELECT F_SD FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK))                
SET @ToDate = @FED--(SELECT F_ED FROM tblCompanyRegistration)                
END                
ELSE                
BEGIN                
SET @FromDate = (SELECT UpdateClsDate FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK))                
SET @ToDate = (case when @FED > GETDATE() then CAST(DATEADD(DAY,-1,GETDATE()) AS DATE) else @FED end)                
END                
DECLARE @CLSMAX DATE = (SELECT MAX(ClsDate) FROM tblClosingStock WITH (READCOMMITTEDLOCK))              
DECLARE @RUN INT = (case when @CLSMAX is null then 0 else  (case when (SELECT F_ED FROM tblCompanyRegistration WITH (READCOMMITTEDLOCK)) > @CLSMAX then 0 else 1 end) end)        
--SELECT @RUN,@CLSMAX,(SELECT F_ED FROM tblCompanyRegistration)               
        
IF(@RUN = 0)              
BEGIN              
print ''Posting Transaction wise''            
INSERT INTO #AllTransRecords                
SELECT TransName,SRI.[Doc Date],SRI.BranchID,SRI.ProdID,CASE WHEN BatchNumber = '''' THEN NULL ELSE SRI.BatchNumber END BatchNumber,SRI.[PKD Date],SRI.[Expiry Date],                
SUM(ISNULL(SRI.[Sales Qty],0)) AS [Sales Qty],                
SUM(ISNULL(SRI.[Free Qty],0)) AS [Free Qty],                
SUM(ISNULL(SRI.[Damage Qty],0)) AS [Damage Qty],SRI.[Purchase Price]--,SRI.Cdate                
FROM                
(                
-- Get GRN Inventory Details +                
SELECT ''CLS'' TransName,0 AS [Inventory ID],ClsDate AS [Doc Date],BranchID,ProdId,CASE WHEN BatchNo = '''' THEN NULL ELSE BatchNo END BatchNumber,PKD AS [PKD Date],Expiry AS [Expiry Date],                
SaleQty AS [Sales Qty],FreeQty AS [Free Qty],DmgQty AS [Damage Qty],PurchPrice AS [Purchase Price],ClsDate CDate                
FROM tblClosingStock WITH (READCOMMITTEDLOCK)                
WHERE ClsDate = CAST(DATEADD(DAY,-1,@FromDate) AS DATE)                
UNION ALL                
SELECT ''BILL'' TransName,GD.InventoryId AS [Inventory ID],GH.Date AS [Doc Date],GH.BranchID,GD.ProdID,                
PInv.BatchNumber BatchNumber,PInv.PKDDate AS [PKD Date],                
PInv.ExpiryDate AS [Expiry Date],                
(GD.AdjQty) AS [Sales Qty],                
(GD.AdjFreeQty) AS [Free Qty],                
(GD.AdjDmgQty) AS [Damage Qty],          
PInv.PurchasePrice AS [Purchase Price],convert(date,GH.Cdate) CDate                
FROM tblTransPurchaseHeader AS GH WITH (READCOMMITTEDLOCK)                
JOIN tblTransPurchaseDetail AS GD WITH (READCOMMITTEDLOCK) ON GD.HID = GH.ID          
JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = GD.InventoryId                
WHERE GH.Status IN (1,3,5) AND GH.TransID = 1 AND GH.Date BETWEEN @FromDate AND @ToDate                
UNION ALL                
-- Get SR Inventory Details +                
SELECT ''SR'' TransName,SD.InventoryId AS [Inventory ID],SH.InvDate AS [Doc Date],SH.BranchID,              
SD.ProdId,PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,
(case when QtyType = 1 THEN (SD.AdjustQty) ELSE 0 END) AS [Sales Qty],                
(case when QtyType = 2 THEN (SD.AdjustQty) ELSE 0 END)  AS [Free Qty],
0 AS [Damage Qty],PInv.PurchasePrice,convert(date,SH.CDate)                
FROM tblTranSalesHeader AS SH WITH (READCOMMITTEDLOCK)                
JOIN tblTranSalesDetail AS SD WITH (READCOMMITTEDLOCK) ON SD.InvId = SH.ID                
JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = SD.InventoryId                
WHERE SH.Status IN (3,6,5) AND SH.DocPrefix = 16 AND SH.TransactionType=2 AND                
SH.InvDate BETWEEN @FromDate AND                
@ToDate                
UNION ALL                
-- Get DR Inventory Details +                
SELECT ''DR'' TransName,SD.InventoryId AS [Inventory ID],SH.InvDate AS [Doc Date],SH.BranchID,                
SD.ProdId,PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,0 AS [Sales Qty],                
0 AS [Free Qty],(SD.AdjustQty) AS [Damage Qty],PInv.PurchasePrice,convert(date,SH.CDate)                
FROM tblTranSalesHeader AS SH WITH (READCOMMITTEDLOCK)                
JOIN tblTranSalesDetail AS SD WITH (READCOMMITTEDLOCK) ON SD.InvId = SH.ID                
JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = SD.InventoryId                
WHERE SH.Status IN (3,7,5) AND SH.DocPrefix = 16 AND SH.TransactionType=3 AND SH.InvDate BETWEEN @FromDate AND                
@ToDate                
UNION ALL                
-- Get DISPATCH Inventory Details -                
SELECT ''INV'' TransName,SD.InventoryId AS [Inventory ID],SH.InvDate AS [Doc Date],SH.BranchID,                
SD.ProdId,PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,
(case when QtyType = 1 THEN -(SD.AdjustQty) ELSE 0 END) AS [Sales Qty],                
(case when QtyType = 2 THEN -(SD.AdjustQty) ELSE 0 END) AS [Free Qty],
0 AS [Damage Qty],PInv.PurchasePrice,convert(date,SH.Cdate)                
FROM tblTranSalesHeader AS SH WITH (READCOMMITTEDLOCK)                
JOIN tblTranSalesDetail AS SD WITH (READCOMMITTEDLOCK) ON SD.InvID = SH.ID                
JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = SD.InventoryId                
WHERE SH.Status IN (1,3,5) AND SH.DocPrefix=15 AND SH.InvDate BETWEEN @FromDate AND                
@ToDate                
UNION ALL                
-- Get Purchase Return Inventory Details -                
SELECT ''PR'' TransName,GD.InventoryId AS [Inventory ID],GH.Date AS [Doc Date],GH.BranchID,GD.ProdID,                
PInv.BatchNumber AS BatchNumber,PInv.PKDDate AS [PKD Date],                
PInv.ExpiryDate AS [Expiry Date],-GD.AdjQty AS [Sales Qty],                
-GD.AdjFreeQty AS [Free Qty],-GD.AdjDmgQty AS [Damage Qty],PInv.PurchasePrice AS [Purchase Price],convert(date,GH.CDate)                
FROM tblTransPurchaseHeader AS GH WITH (READCOMMITTEDLOCK)                
JOIN tblTransPurchaseDetail AS GD WITH (READCOMMITTEDLOCK) ON GD.HID = GH.ID                
JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = GD.InventoryId                
WHERE GH.Status IN (3,6,5) AND GH.TransID=12 AND GH.Date BETWEEN @FromDate AND                
@ToDate                
              
UNION ALL                
-- Get Inventory Conversion Old Batch Details -                
SELECT ''IVCO OLD BATCH'' TransName,InvD.UpdatedBatchID,InvH.InventoryDate,InvH.BranchID,InvD.ProdID,PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,                
(CASE WHEN InvH.ConvertionTypeId=1 OR InvH.ConvertionTypeId=2 OR InvH.ConvertionTypeId=7 THEN -InvD.OrgSaleQty END) AS OrgQty,                
(CASE WHEN InvH.ConvertionTypeId=3 OR InvH.ConvertionTypeId=4 THEN -InvD.OrgSaleQty END) AS OrgFreeQty,                
(CASE WHEN InvH.ConvertionTypeId=5 OR InvH.ConvertionTypeId=6 THEN -InvD.OrgSaleQty END) AS OrgDmgQty,                
PInv.PurchasePrice,convert(date,InvH.CDate)                
FROM tblInventoryDetail AS InvD WITH (READCOMMITTEDLOCK)                
JOIN tblInventoryHeader AS InvH WITH (READCOMMITTEDLOCK) ON InvD.InventoryID=InvH.InventoryID                
JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = InvD.NewBatchID --UpdatedBatchID                
WHERE InvH.TransID=22 AND InvH.Status = 1 AND InvH.InventoryDate BETWEEN @FromDate AND                
@ToDate                
UNION ALL                
-- Get Inventory Conversion New Batch Details +                
SELECT ''IVCO NEW BATCH'' TransName,InvD.NewBatchID,InvH.InventoryDate,InvH.BranchID,InvD.ProdID,PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,                
(CASE WHEN InvH.ConvertionTypeId=3 OR InvH.ConvertionTypeId=5 THEN InvD.OrgSaleQty END) AS ActQty,           
(CASE WHEN InvH.ConvertionTypeId=1 OR InvH.ConvertionTypeId=6 THEN InvD.OrgSaleQty END) AS ActFreeQty,                
(CASE WHEN InvH.ConvertionTypeId=2 OR InvH.ConvertionTypeId=4 THEN InvD.OrgSaleQty END) AS ActDmgQty,                
PInv.PurchasePrice,convert(date,InvH.CDate)                
FROM tblInventoryDetail AS InvD WITH (READCOMMITTEDLOCK)                
JOIN tblInventoryHeader AS InvH WITH (READCOMMITTEDLOCK) ON InvD.InventoryID=InvH.InventoryID                
JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = InvD.NewBatchID                
WHERE InvH.TransID=22 AND InvH.Status = 1 AND InvH.InventoryDate BETWEEN @FromDate AND                
@ToDate                
UNION ALL                
-- Get Inventory Adjustment Old Batch Details -                
SELECT ''IVA OLD BATCH'' TransName,InvD.UpdatedBatchID,InvH.InventoryDate,InvH.BranchID,InvD.ProdID,PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,                
-InvD.OrgQty,-InvD.OrgFreeQty,-InvD.OrgDmgQty,PInv.PurchasePrice,convert(date,InvH.CDate)                
FROM tblInventoryDetail AS InvD WITH (READCOMMITTEDLOCK)                
JOIN tblInventoryHeader AS InvH WITH (READCOMMITTEDLOCK) ON InvD.InventoryID=InvH.InventoryID                
JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = InvD.UpdatedBatchID                
WHERE InvH.TransID=13 AND InvH.Status = 1 AND InvH.InventoryDate BETWEEN @FromDate AND                
@ToDate                
UNION ALL                
-- Get Inventory Adjustment New Batch Details +                
SELECT ''IVA NEW BATCH'' TransName,InvD.NewBatchID,InvH.InventoryDate,InvH.BranchID,InvD.ProdID,PInv.BatchNumber,PInv.PKDDate,PInv.ExpiryDate,                
InvD.ActualQty,InvD.ActualFreeQty,InvD.ActualDmgQty,PInv.PurchasePrice,convert(date,InvH.CDate)                
FROM tblInventoryDetail AS InvD WITH (READCOMMITTEDLOCK)                
JOIN tblInventoryHeader AS InvH WITH (READCOMMITTEDLOCK) ON InvD.InventoryID=InvH.InventoryID                
JOIN tblProductInventory AS PInv WITH (READCOMMITTEDLOCK) ON PInv.InventoryId = InvD.NewBatchID                
WHERE InvH.TransID=13 AND InvH.Status = 1 AND InventoryDate BETWEEN @FromDate AND                
@ToDate                    
) AS SRI                
GROUP BY SRI.[Doc Date],SRI.BranchID,SRI.ProdID,SRI.BatchNumber,SRI.[PKD Date],SRI.[Expiry Date],SRI.[Purchase Price],SRI.TransName--,SRI.Cdate                
ORDER BY SRI.ProdID--,SRI.CDate                
    --select * from #AllTransRecords          
DECLARE @BookEndDate DATE = @ToDate            
DECLARE @MINClsDate DATE = DATEADD(DAY,-1,@FromDate)            
DECLARE @MINTransDate DATE = @FromDate            
DECLARE @ServerDateMinusOne DATE =(CASE WHEN @BookEndDate < GETDATE() THEN @BookEndDate ELSE (DATEADD(DAY,-1,GETDATE())) END)             
            
WHILE @MINTransDate <= @ServerDateMinusOne                
BEGIN                
                
INSERT INTO #TempFinalClsStock                
SELECT @MINTransDate,BranchID,ProdID,BatchNo,PKDDate,EXPDate,SUM(AQty),SUM(FQty),SUM(DQty),PPrice                
FROM #AllTransRecords WHERE CONVERT(DATE,TransDate)<=@MINTransDate --30                
GROUP BY BranchID,ProdID,BatchNo,PKDDate,EXPDate,PPrice                
SET @MINTransDate = DATEADD(DAY,1,@MINTransDate)                
ENd                
delete tblClosingStock where ClsDate between @FromDate and @ToDate                
INSERT INTO tblClosingStock                
SELECT *,AQty * PPrice [Sales Value],DQty * PPrice [Dmg Value] FROM #TempFinalClsStock     
where (isnull(AQty,0) > 0 or isnull(FQty,0) > 0 or isnull(DQty,0) > 0)        
ORDER BY TransDate,ProdID                
update tblCompanyRegistration set updateclsdate = (case when @FED > GETDATE() then CAST(GETDATE() AS DATE) else @FED end)                
END              
END                
ELSE IF(@Mode = 3)                
BEGIN                
if(@TranDate < @ClsDate)                
BEGIN                
UPDATE tblCompanyRegistration SET UpdateClsDate = @TranDate     
END                
END                
DROP TABLE #AllTransRecords,#TempFinalClsStock                
commit tran                
end try                
begin catch                
rollback tran                
end catch                
END',
N'[export] nocount;readcommittedlock=34';
GO
/****** uspUpdateEwayInTrans ******/
EXEC #Apply07 N'dbo.uspUpdateEwayInTrans', 0x39E6DE099D9B879366FC7CF4B479BC922E5F72BDD5A956845D4207B030674390, 0x13A804CE7BAB1C744C5DCD3E951FA743EA0D8052A75FE145F60EE0B8D41241B5, NULL, 0xCE8E73D3FB38ACF866F110986306AFED6C1362B45180DC49B8D94090EC70F1A8, 0xFEC71D4BEEF6921357041CB1BC52759F8FEABCDC195B4DF37B71AE2CA9B85AC0, NULL,
N'--uspUpdateEwayInTrans 2,''2,3,6'',1,3,''Road'',''Regular'',NULL,NULL      
-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspUpdateEwayInTrans]            
@Mode INT,@InvID NVARCHAR(MAX),@VehicleID NVARCHAR(50) = 0,@Distance NVARCHAR(50) = NULL,@TranMode NVARCHAR(100) = NULL,            
@VehicleType NVARCHAR(100) = NULL,@TransportID NVARCHAR(100) = NULL,@TransportName NVARCHAR(255) = NULL,@Branch NVARCHAR(255) = NULL,  
@FromDate date = NULL,@ToDate date = NULL,@Type int = 1  
AS            
SET NOCOUNT ON;
BEGIN            
IF(@Mode = 1)            
BEGIN            
SELECT sh.VehicleNo ID,VH.VehicleNo,Distance,TransMode,VehicleType,TransportID,TransportName FROM tblTranSalesHeader SH            
JOIN tblMasterVehicle VH ON VH.ID = SH.VehicleNo            
WHERE SH.DocValue = @InvID and BranchID = case when isnull(@Branch,'''') = '''' then BranchID else @Branch end    
END            
ELSE IF(@Mode = 2)            
BEGIN            
DECLARE @sql NVARCHAR(MAX)      
if(@Type = 1)-- update in invoice
BEGIN
SET @sql = ''UPDATE tblTranSalesHeader SET VehicleNo =''+ '' @VehicleID '' +'',Distance =''+ '' @Distance '' +'',
TransMode =''+ '' @TranMode '' +'',VehicleType =''+ '' @VehicleType '' +'',TransportID = ISNULL(@TransportID,'''''''') ,
TransportName =  ISNULL(@TransportName,'''''''')  
WHERE Docprefix = 15 and status in (1,3,5) and DocValue IN (SELECT id FROM dbo.fnSplitString(@InvID, N'''',''''))''      
set @sql += case when isnull(@Branch,'''') = '''' then '''' else '' and BranchID = @Branch '' end    
SET @sql += CASE WHEN ISNULL(@FromDate,'''') = '''' OR ISNULL(@ToDate,'''') = '''' THEN '''' ELSE 
'' AND InvDate BETWEEN ''+'' @FromDate  AND ''+'' @ToDate '' END      
END
ELSE if(@Type = 2)-- update in Van Loading Slip
BEGIN
SET @sql = ''UPDATE tblVanLoadingSlipHeader SET VehicleNo =''+ '' @VehicleID '' +'',Distance =''+ '' @Distance '' +'',
TransMode =''+ '' @TranMode '' +'',VehicleType =''+ '' @VehicleType '' +'',TransportID = ISNULL(@TransportID,'''''''') ,
TransportName =  ISNULL(@TransportName,'''''''')  
WHERE status in (1,3,5) and DocValue IN (SELECT id FROM dbo.fnSplitString(@InvID, N'''',''''))''      
set @sql += case when isnull(@Branch,'''') = '''' then '''' else '' and BranchID = @Branch '' end    
SET @sql += CASE WHEN ISNULL(@FromDate,'''') = '''' OR ISNULL(@ToDate,'''') = '''' THEN '''' ELSE 
'' AND DocDate BETWEEN ''+'' @FromDate  AND ''+'' @ToDate '' END    
END
EXEC sys.sp_executesql @sql, N''@Mode INT, @InvID NVARCHAR(MAX), @VehicleID NVARCHAR(50), @Distance NVARCHAR(50), @TranMode NVARCHAR(100), @VehicleType NVARCHAR(100), @TransportID NVARCHAR(100), @TransportName NVARCHAR(255), @Branch NVARCHAR(255), @FromDate date, @ToDate date, @Type int'', @Mode, @InvID, @VehicleID, @Distance, @TranMode, @VehicleType, @TransportID, @TransportName, @Branch, @FromDate, @ToDate, @Type      
END            
END',
N'[06] nocount';
GO
/****** uspUpdateEWBImport ******/
EXEC #Apply07 N'dbo.uspUpdateEWBImport', 0xF1CE153133CF1142AEFD46032F6F7A5B1B28CCF9DF7E21887D35611AC35F5848, NULL, NULL, 0xE76BCCD2B79FF19F0AF060CEE5210F2406A85E8CF27369BADA3AAD6B03A94155, 0x342FDF39CEBD63C9D605F459EACC61D2CFB93C1CE7A7992DAD3E24BCD921717D, NULL,
N'ALTER PROC [dbo].[uspUpdateEWBImport]      
@DocID NVARCHAR(50),@DocDate NVARCHAR(MAX),@EWBNo NVARCHAR(MAX),@DocType NVARCHAR(255) = ''Tax Invoice'',
@EWBDate datetime = null,@ValidTill datetime = null
AS      
SET NOCOUNT ON;
BEGIN      
set dateformat dmy;              
Declare @Ident INT = 0       
IF(@DocType = ''Tax Invoice'' OR @DocType = ''Credit Note'')        
BEGIN      
set @Ident = (SELECT TOP 1 ID FROM tblTranSalesHeader WITH (READCOMMITTEDLOCK) WHERE  Status IN (1,3,5,6,7) AND DocPrefix IN (15,16)               
AND DocId = @DocID and InvDate = convert(date,@DocDate) ORDER BY ID DESC)       
END  
ELSE IF(@DocType = ''Delivery Challan'')  
BEGIN  
set @Ident = (SELECT TOP 1 ID FROM tblVanLoadingSlipHeader WITH (READCOMMITTEDLOCK) WHERE  Status IN (1,3,5,6,7)          
AND DocId = @DocID and DocDate = convert(date,@DocDate) ORDER BY ID DESC)      
END  
      
--SELECT @Ident                  
if(@Ident > 0)            
BEGIN        
IF(@DocType = ''Tax Invoice'' OR @DocType = ''Credit Note'')        
BEGIN        
UPDATE tblTranSalesHeader SET EWBNo=@EWBNo,EWBDate = @EWBDate,ValidTill = @ValidTill WHERE ID = @Ident                  
END       
ELSE IF(@DocType = ''Delivery Challan'')  
BEGIN  
UPDATE tblVanLoadingSlipHeader SET EWBNo=@EWBNo,EWBDate = @EWBDate,ValidTill = @ValidTill WHERE ID = @Ident     
END  
SELECT @Ident            
END       
END',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspUpdateFAGroupLevels ******/
EXEC #Apply07 N'dbo.uspUpdateFAGroupLevels', 0xC908B13E07BEBE1974ADC4F155CF68E4EE750D84BBDE0C21367ECB365BE3DBBF, NULL, NULL, 0xB16AF70ACA533B5D69953C4BA6B984B6322C81A18C99F9302B5BA4166AF2A309, 0x4AA403D1E52456C20340150C4BC56365A934FD4CC5F800F8058066D18E753766, NULL,
N'-- update level id in FA Group Table  
ALTER PROC [dbo].[uspUpdateFAGroupLevels]  
AS  
SET NOCOUNT ON;
BEGIN  
declare @NewUpdateLevID INT = 1,@CountLevValue INT  
CREATE TABLE #NewUpdateDs(AccGrpID INT)  
WHILE(@NewUpdateLevID < 10)  
BEGIN  
SELECT @CountLevValue = COUNT(*) FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE LevelID = @NewUpdateLevID  
IF(@CountLevValue > 0)  
BEGIN  
INSERT INTO #NewUpdateDs  
SELECT FAGroup FROM tblFAGroup WITH (READCOMMITTEDLOCK) WHERE LevelID = @NewUpdateLevID  
END  
IF((SELECT COUNT(*) FROM #NewUpdateDs) > 0)  
BEGIN  
UPDATE tblFAGroup SET LevelID = (@NewUpdateLevID + 1) WHERE ParentGroup IN (SELECT AccGrpID FROM #NewUpdateDs)  
END  
TRUNCATE TABLE #NewUpdateDs  
SET @NewUpdateLevID = @NewUpdateLevID + 1;  
END  
DROP TABLE #NewUpdateDs  
END',
N'[export] nocount;readcommittedlock=2';
GO
/****** uspUpdateIRNImport ******/
