/****** uspValidateBulkOrderTaken ******/
EXEC #Apply07 N'dbo.uspValidateBulkOrderTaken', 0x469CE51BE0A33539E40B81269CC2AC65BD3C66398BCBA01A684A6E256B0DF426, NULL, NULL, 0xDD0547F73B4CA823B1CCD3D0D70CBCC3D9577E468355DBA6944C98CB22B93177, 0xEE4CD41BDEF7EF11D551478C7B428DF2856CB148AB5FB7D14A5B851EBA0865A7, NULL,
N'ALTER proc [dbo].[uspValidateBulkOrderTaken]  
@VerifyorCancel int = 1,@ID int = 176,@Status int = 1,@UID int  
as  
SET NOCOUNT ON;
begin  
BEGIN TRY  
declare @CurrStatus int  
select @CurrStatus = Status from tblTranOrderTakenHeader WITH (READCOMMITTEDLOCK) where ID = @ID  
if(@CurrStatus = 4)  
RAISERROR(''Document Already Cancelled'',16,1);  
else if(@CurrStatus = 8)  
RAISERROR(''Document Already Processed'',16,1);  
else if(@Status <> @CurrStatus)  
RAISERROR(''Document Status Already Changed'',16,1);  
if(@VerifyorCancel = 2)  
UPDATE tblTranOrderTakenHeader SET Status = 4,ClBy = @UID ,ClDate = getdate() where ID = @ID  
end TRY  
BEGIN CATCH  
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() PRO  
END CATCH  
END',
N'[export] nocount;readcommittedlock=1';
GO
/****** uspValidateCustomerCreditLimit ******/
EXEC #Apply07 N'dbo.uspValidateCustomerCreditLimit', 0x3CC6638FCBBF6A372FDD5004FD675210E18CAC8AC675377E45CDBD362867553E, NULL, NULL, 0x2FE8AC0F2280D30FBF725E2BD31249BBE50D5EEAE0AA5A7C344E26A57C193CB3, 0x4559A03072BC45A64B74651FA0AEE5DBD42CCD3A604C7DF14AFA970144C7A9C5, NULL,
N'--uspValidateCustomerCreditLimit 2,18,10003,''2025-04-16'',0  
ALTER PROC [dbo].[uspValidateCustomerCreditLimit]  
@nMode INT,@CustID INT,@Date DATE,@CreditTermID INT,@NetAmt DECIMAL (25,6)=NULL,@TransID INT=NULL  
AS  
SET NOCOUNT ON;
BEGIN  
SET DATEFORMAT dmy;  
declare @commonCreditblockdays int = (select isnull(appvalue,0) from tblappconfig where appid = 30)
DECLARE @CreditDate DATE = ( select DATEADD(DD,CONVERT(INT, Value),CONVERT(DATE,@Date)) ADDEDDATE from tblmastercreditterm WHERE id = @CreditTermID)  
IF ISNULL(@nMode,0)=1  
BEGIN  
SELECT  
dbo.fnGetRoundedValue(CreditLimitValue) AS [Credit Limit Value],CreditLimitCount AS [Credit Limit Invoice Count],dbo.fnGetRoundedValue(creditlimitOS) AS [Credit Limit O/S],  
OverDueInvCount AS [Overdue Inv Count] FROM tblMasterCustomer WHERE ID=@CustID  
END  
ELSE IF ISNULL(@nMode,0)=2  
BEGIN  
DECLARE @isError NVARCHAR(10)=''Pass'',@ErrorMsg NVARCHAR(500)=''''  
DECLARE @CreditLimitValue DECIMAL (25,6),@CreditLimitInvCount INT,@CreditLimitOS DECIMAL (25,6),@OverdueInvCount INT,  
@CustInvCount INT,@CustOS DECIMAL (25,6),@CustCLValue DECIMAL (25,6),@TotCLValue DECIMAL (25,6),@CustSRValue DECIMAL (25,6),  
@CustOSBaseDate DECIMAL (25,6)  
-- Create Temp table for error return  
DECLARE @tempErrors TABLE (ERROR_ID INT, ERROR_MSG NVARCHAR(255),LIMIT_VALUE NVARCHAR(50))  
-- Credit Limit Invoice and OS from Customer Master  
SELECT @CreditLimitValue = CreditLimitValue,@CreditLimitInvCount = CreditLimitCount,@CreditLimitOS = creditlimitOS,  
@OverdueInvCount = OverDueInvCount FROM tblMasterCustomer WHERE ID=@CustID  
-- Credit Limit Invoice and OS from Invoice Table  
IF ISNULL(@TransID,0)>0  
BEGIN  
SELECT @CustInvCount = COUNT(Id),@CustCLValue = ISNULL(SUM(Balance),0)  
FROM tblTranSalesHeader WHERE CustId=@CustID AND Balance > 0 AND DocPrefix=15 AND Status IN (1,3) AND PaymentModeId in (7,8) AND Id!=@TransID  
END  
ELSE  
BEGIN  
SELECT @CustInvCount = COUNT(ID),@CustCLValue = ISNULL(SUM(Balance),0)  
FROM tblTranSalesHeader WHERE CustId=@CustID AND Balance > 0 AND DocPrefix=15 AND Status IN (1,3) AND PaymentModeId in (7,8)  
END  
-- Credit Limit Value Taken Credit date <= GETDATE()  
IF ISNULL(@TransID,0)>0  
BEGIN  
SELECT @CustOS = SUM(Balance) FROM tblTranSalesHeader  
WHERE CustId=@CustID AND Balance > 0 AND DocPrefix=15 AND PaymentModeId in (7,8) AND Status IN (1,3) AND CreditDate <= GETDATE() AND Id!=@TransID  
END  
ELSE  
BEGIn  
SELECT @CustOS = SUM(Balance) FROM tblTranSalesHeader  
WHERE CustId=@CustID AND Balance > 0 AND DocPrefix=15 AND PaymentModeId in (7,8) AND Status IN (1,3) AND CreditDate <= GETDATE()  
END  
-- Get Sales Return Balance of this Customer and INV - SR  
SELECT @CustSRValue = SUM(Balance)  
FROM tblTranSalesHeader WHERE CustId=@CustID AND Balance > 0 AND DocPrefix=16 AND Status IN (3,6,7)  
SET @TotCLValue = (ISNULL(@CustCLValue,0) - ISNULL(@CustSRValue,0))  
SET @CustOSBaseDate = (CASE WHEN @CreditDate<=GETDATE() THEN ISNULL(@CustOS,0)+ISNULL(@NetAmt,0) ELSE ISNULL(@CustOS,0) END)  
-- Checking Condition for CL Value | CL Invoice count | CL O/S | Overdue Invoice Count  
DELETE @tempErrors  
IF ISNULL(@CreditLimitValue,0) < (ISNULL(@TotCLValue,0)+ISNULL(@NetAmt,0)) AND ISNULL(@CreditLimitValue,0) > 0  
BEGIN  
SET @isError = ''Fail''  
INSERT INTO @tempErrors VALUES (1,''Reached Credit Limit Value : ''+CAST(dbo.fnGetRoundedValue((ISNULL(@TotCLValue,0)+ISNULL(@NetAmt,0))) AS NVARCHAR),  
dbo.fnGetRoundedValue(@CreditLimitValue))  
END  
IF ISNULL(@CreditLimitInvCount,0) <= ISNULL(@CustInvCount,0) AND ISNULL(@CreditLimitInvCount,0) > 0  
BEGIN  
SET @isError = ''Fail''  
INSERT INTO @tempErrors VALUES (5,''Reached Credit Limit Invoice Count : ''+CAST(@CustInvCount+1 AS NVARCHAR),@CreditLimitInvCount)  
END  
IF (ISNULL(@CreditLimitOS,0) < ISNULL(@CustOSBaseDate,0)) AND ISNULL(@CreditLimitOS,0) > 0  
BEGIN  
SET @isError = ''Fail''  
INSERT INTO @tempErrors VALUES (6,''Reached O/S Amount Limit : ''+CAST(dbo.fnGetRoundedValue(ISNULL(@CustOSBaseDate,0)) AS NVARCHAR),  
dbo.fnGetRoundedValue(@CreditLimitOS))  
END  
IF ISNULL(@OverdueInvCount,0) > 0  
BEGIN  
DECLARE @InvCount INT = (SELECT COUNT(*) FROM tblTranSalesHeader  
WHERE CustId = @CustID AND Status in (1,3,5) AND DocPrefix = 15 AND Balance > 0 AND CreditDate < CAST(GETDATE() AS DATE))  
IF ISNULL(@InvCount,0)>=@OverdueInvCount  
BEGIN  
SET @isError = ''Fail''  
INSERT INTO @tempErrors VALUES (7,''Already ''+ CAST(@InvCount AS NVARCHAR) +'' Overdue Invoice''+(CASE WHEN @InvCount = 1 THEN '''' ELSE ''s'' END)+'' is there'',@OverdueInvCount)  
END  
END  
-- COMMON CREDIT BLOCK
IF ISNULL(@commonCreditblockdays,0) > 0  
BEGIN  
DECLARE @InvMinDate DATE = (SELECT DATEADD(DD,@commonCreditblockdays,MIN(InvDate)) FROM tblTranSalesHeader WHERE CustID = @CustID AND Status in (1,3,5) AND DocPrefix = 15 AND Balance > 0)  
IF @InvMinDate < @Date
BEGIN 
SET @isError = ''Fail''  
INSERT INTO @tempErrors VALUES (10,''Reached Common Ageing Credit Days (''+ CAST(@commonCreditblockdays AS NVARCHAR) +'')'',
CONVERT(NVARCHAR(50),@InvMinDate,103))
END  
END  
IF ISNULL(@isError,'''')=''Pass''  
BEGIN  
SELECT @isError AS SuccessMsg  
END  
ELSE  
BEGIN  
SELECT ERROR_ID,ERROR_MSG,LIMIT_VALUE FROM @tempErrors  
END  
END  
END',
N'[export] nocount';
GO
/****** uspValidateDeliveryDocumentData ******/
EXEC #Apply07 N'dbo.uspValidateDeliveryDocumentData', 0xB140742578074591490D6A0C31535BE950D8DB61C85FE4854E8A4E0A5BAFA667, NULL, NULL, 0xF93F1DFFD6CD2D269565307CB83D6F374317EC09100DC5F344C3BFFACA417F45, 0x89AC3F9C724A4A52F368BBD196BC3E5C5C003A481628942631D684C03D329E54, NULL,
N'ALTER PROC [dbo].[uspValidateDeliveryDocumentData]                      
 @BranchID int = 4,@TransMode int = 0,@DeliveryID int = 0,@tvpIdentId tvpIdentId READONLY        
 as        
 SET NOCOUNT ON;
begin  
 begin try  
CREATE table #DeliProcs1(InvIdentID INT,IsMods INT)              
CREATE table #DeliProcs(InvIdentID INT,IsMods INT)  
DECLARE @Status INT ,@DocumentId nvarchar(255),@InvStatus int  
IF(@TransMode = 1)--CREATE MODE  
BEGIN    
-- Point 11: set-based check replaces the DocumentCount cursor loop (same error; @DocumentId = first invoice that failed)
SELECT TOP (1) @DocumentId = CONVERT(NVARCHAR(255), T.DocumentId)
FROM @tvpIdentId AS T
JOIN tblTranSalesHeader AS H WITH (READCOMMITTEDLOCK) ON H.ID = T.DocumentId
WHERE H.Status <> T.Status OR H.Status IN (2, 4);
IF @@ROWCOUNT > 0
BEGIN
    RAISERROR(''Invoice status already changed'', 16, 1, @DocumentId);
END       
END  
INSERT INTO #DeliProcs1              
select DD.InvIdentID,1 from tblDeliveryOrderHeader DH WITH (READCOMMITTEDLOCK)                            
JOIN tblDeliveryOrderDetail DD WITH (READCOMMITTEDLOCK) ON DD.DOID = DH.ID                            
JOIN tblTranSalesHeader DSH WITH (READCOMMITTEDLOCK) ON DSH.ID = DD.InvIdentID              
WHERE DD.Status in (1,5) AND DH.Status IN (1,3,5) group by DD.InvIdentID              
IF(@TransMode = 2)              
BEGIN              
INSERT INTO #DeliProcs1              
SELECT InvIdentID,2 FROM tblDeliveryOrderDetail WITH (READCOMMITTEDLOCK) WHERE DOID = @DeliveryID              
GROUP BY InvIdentID              
END              
INSERT INTO #DeliProcs              
SELECT InvIdentID,MAX(IsMods) FROM #DeliProcs1 GROUP BY InvIdentID          
        
select SH.ID,SH.DocID,SH.DocValue,SH.InvDate into #Alreadyassigned from tblTranSalesHeader SH WITH (READCOMMITTEDLOCK)        
JOIN @tvpIdentId TVPDOC ON TVPDOC.DocumentId = SH.ID        
where SH.DocPrefix = 15 AND SH.BranchID = @BranchID AND SH.Status IN (1,3,5)         
AND SH.ID IN (SELECT InvIdentID FROM #DeliProcs WHERE IsMods = 1)        
if((select COUNT(*) from #Alreadyassigned) > 0)  
begin  
set @DocumentId = (select STRING_AGG(ID, '','') from #Alreadyassigned)  
raiserror(''Invoice already assign'',16,1,@DocumentId)  
end  
drop table #Alreadyassigned  
end try  
begin catch  
select ERROR_MESSAGE(),ERROR_LINE() ,  ERROR_PROCEDURE(),@DocumentId  
end catch  
end',
N'[export] nocount;validation-cursor-removed=1;readcommittedlock=5';
GO
/****** uspValidateDevice ******/
EXEC #Apply07 N'dbo.uspValidateDevice', 0x29AF7AB684B3C9A86F5EB13E042FB616B68C77ACE1B2F70628C89FD35ABBA221, NULL, NULL, 0x753A64BE31876C7E86DA6BF46104C420B14BAFD385C66E78ABBAD0D7AFDFEC4D, 0x5076527CFB715C201FFB55DDCDE170FE702EB1FDFA984256AB7B28BEF5C19402, NULL,
N'ALTER proc [dbo].[uspValidateDevice]            
@Mode int,@DeviceID nvarchar(255) = NULL,@UserID int = 0,@DeviceName nvarchar(100) = null,@Latitude nvarchar(100) = null,            
@Longtitude nvarchar(100) = null,@Pincode nvarchar(100) = null            
as            
SET NOCOUNT ON;
begin            
if(@Mode = 1)            
BEGIN            
select * from tblDeviceInfo WITH (READCOMMITTEDLOCK) where DeviceID = @DeviceID            
END            
if(@Mode = 2)            
BEGIN            
DECLARE @ISSA INT = (CASE WHEN @UserID = 1 THEN 1 ELSE 0 END)      
insert into tblDeviceInfo(UserID,DeviceID,DeviceName,Latitude,Longtitude,Active,CDate,Pincode) values(@UserID,@DeviceID,@DeviceName,            
@Latitude,@Longtitude,@ISSA,getdate(),@Pincode)            
select SCOPE_IDENTITY();            
END            
if(@Mode = 3)            
BEGIN            
update tblDeviceInfo set Active = 1 where DeviceID = @DeviceID and UserID = @UserID            
end            
if(@Mode = 4)            
BEGIN            
select * from tblCompanyRegistration WITH (READCOMMITTEDLOCK)            
END            
if(@Mode = 5)            
BEGIN            
select * from tblDeviceInfo WITH (READCOMMITTEDLOCK) where DeviceID = @DeviceID and Active = 1          
end          
if(@Mode = 6)            
BEGIN            
select * from tblRefreshTokens WITH (READCOMMITTEDLOCK) where UserID = @UserID and IsRevoked = 1          
end        
if(@Mode = 7)            
BEGIN          
UPDATE tblRefreshTokens SET IsRevoked = 0,ExpiresAt = GETDATE() - 1 where UserID = @UserID and IsRevoked = 1          
END      
if(@Mode = 8)            
BEGIN   
declare @existscount int  
SELECT @existscount = count(*) FROM tblRefreshTokens WITH (READCOMMITTEDLOCK) WHERE IsRevoked = 1 and userid not in (1,@UserID)  
if(@existscount >= (@DeviceID) and @UserID != 1)  
begin  
select ''Login limit reached. The maximum number of active users is currently connected.  
Please try again when a user logs out or Contact admin''  
end  
END  
END',
N'[export] nocount;readcommittedlock=5';
GO
/****** uspValidateDraftData ******/
EXEC #Apply07 N'dbo.uspValidateDraftData', 0xA9C47D3F2B974AC87E9F44EE6DCCF650BCD1FD73A570D9FFBB42E298BFDCCDCB, NULL, NULL, 0x4B6B6EB3D1034072A03E164A6B5DC935D64B5766C580065F809606F4193056EE, 0x1BD603616378DD58D1589EACCC54D64F0094E8599F7B399528552BC19E12D86D, NULL,
N'ALTER proc [dbo].[uspValidateDraftData]        
@Checkmode int = 1,@TransID int = 2,@ID int = 18,@CurrentStatus int = 1,@UserID int = 0      
as        
SET NOCOUNT ON;
begin        
begin try        
declare @Status int,@HaveRec int = 0        
if(@TransID in (1,2,3,12))--Purchase        
BEGIn        
select @Status = Status,@HaveRec = count(ID) from tblPurchaseDraftHeader WITH (READCOMMITTEDLOCK) where TransID = @TransID and ID = @ID        
group by Status        
if(ISNULL(@HaveRec,0) = 0)        
BEGIN        
RAISERROR(''This Draft already cancelled'',16,1)        
END        
if((isnull(@CurrentStatus,0) != 0 and @Status != @CurrentStatus)  OR @Status IN (2,4))        
begin        
RAISERROR(''Document Status already changed'',16,1)        
end        
if(@Checkmode = 2) -- cancel        
begin        
DELETE tblPurchaseDraftHeader WHERE ID = @ID                                      
DELETE tblPurchaseDraftDetail WHERE HID = @ID        
end        
END        
ELSE if(@TransID in (14,15)) -- Sales      
BEGIN        
select @Status = Status,@HaveRec = count(ID) from tblSalesDraftHeader WITH (READCOMMITTEDLOCK) where TransID = @TransID and ID = @ID        
group by Status--,TransID,TransactionType    
--(CASE WHEN TransID = 15 THEN Status WHEN TransID = 16 AND Status = 1 AND TransactionType = 2 THEN 6    
-- WHEN TransID = 16 AND Status = 1 AND TransactionType = 3 THEN 7 ELSE Status END)    
--select * from tblSalesDraftHeader where TransID = 15 and ID = 1372        
-- select * from tblSalesDraftHeader where cby = 2 order by 1 desc  
if(ISNULL(@HaveRec,0) = 0)        
BEGIN        
RAISERROR(''This Draft already cancelled'',16,1)        
END        
if((isnull(@CurrentStatus,0) != 0 and @Status != @CurrentStatus)  OR @Status IN (2,4))     
begin        
RAISERROR(''Document Status already changed'',16,1)        
end        
if(@Checkmode = 2) -- cancel        
begin        
DELETE tblSalesDraftHeader WHERE ID = @ID                                      
DELETE tblSalesDraftDetail WHERE HID = @ID        
end        
END     
ELSE if(@TransID in (16,17)) -- SR,DR      
BEGIN        
select @Status = Status,@HaveRec = count(ID) from tblSalesDraftHeader WITH (READCOMMITTEDLOCK) where TransID IN (16,17) and ID = @ID        
group by Status        
if(ISNULL(@HaveRec,0) = 0)        
BEGIN        
RAISERROR(''This Draft already cancelled'',16,1)        
END        
if((isnull(@CurrentStatus,0) != 0 and @Status != @CurrentStatus)  OR @Status IN (2,4))    
begin        
RAISERROR(''Document Status already changed'',16,1)        
end        
if(@Checkmode = 2) -- cancel        
begin        
DELETE tblSalesDraftHeader WHERE ID = @ID                                      
DELETE tblSalesDraftDetail WHERE HID = @ID        
end        
END     
ELSE if(@TransID in (100)) -- OT      
BEGIN      
select @Status = Status from TBLTRANORDERTAKENHEADER WITH (READCOMMITTEDLOCK) where ID = @ID        
if((isnull(@CurrentStatus,0) != 0 and @Status != @CurrentStatus) OR @Status IN (2,4))
begin        
RAISERROR(''Document Status already changed'',16,1)        
end        
if(@Checkmode = 2) -- cancel        
begin        
update TBLTRANORDERTAKENHEADER set status = 4,ClBy = @userID,ClDate = getdate() where ID = @ID        
end       
END      
ELSE if(@TransID in (101)) -- WEB SR      
BEGIN      
select @Status = Status from tblTranOrderReturnHeader WITH (READCOMMITTEDLOCK) where ID = @ID        
if((isnull(@CurrentStatus,0) != 0 and @Status != @CurrentStatus)  OR @Status IN (2,4))
begin        
RAISERROR(''Document Status already changed'',16,1)        
end        
if(@Checkmode = 2) -- cancel        
begin        
update tblTranOrderReturnHeader set status = 4,ClBy = @userID,ClDate = getdate() where ID = @ID        
end       
END      
end try        
begin catch        
select ERROR_MESSAGE() MSG,ERROR_LINE(),ERROR_PROCEDURE() PROCS        
end catch        
end',
N'[export] nocount;readcommittedlock=5';
GO
/****** uspValidateEditCanceldocument ******/
EXEC #Apply07 N'dbo.uspValidateEditCanceldocument', 0x09121C0267F4E27090EF6C9345CC043D45FC3D3768673724683AA5F3C5CF699C, NULL, NULL, 0xC69F8916A6AF365EC7AE8F6A073A29F9CFFEB1C1056C6CF593DB313B3A12625B, 0x5169A99E6458B3FD36234FEFF0E2B8B9A42C17D4A4FE7A2D03F960ADAC2DC342, NULL,
N'ALTER proc [dbo].[uspValidateEditCanceldocument]          
@ActionType int,@TransID int,@ID int = 894,@StatusID int = 4          
as          
SET NOCOUNT ON;
begin try          
declare @CurrentStatus int,@NetAmt decimal(18,4),@Balance decimal(18,4),@StsDesc nvarchar(100) = '''',@DispBalance nvarchar(100),        
@Action nvarchar(10) = case when @ActionType = 1 then ''Edit'' else ''Cancel'' end        
IF(@TransID = 14)--Quotation          
BEGIN          
select @CurrentStatus = Status,@StsDesc = STS.Description from tblQuotationHeader QH WITH (READCOMMITTEDLOCK)           
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status          
where QH.ID = @ID          
AND DocPrefix = @TransID          
        
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END          
ELSE if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)         
end          
END          
ELSE IF(@TransID = 15 OR @TransID = 16)--Invoice or Sales Return          
BEGIN          
select @CurrentStatus = Status,@NetAmt = NetAmt ,@Balance = Balance,@StsDesc = STS.Description from tblTranSalesHeader QH WITH (READCOMMITTEDLOCK)        
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status where QH.ID = @ID          
AND DocPrefix = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END         
if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)        
end          
else if(@NetAmt != @Balance)          
begin          
set @DispBalance = dbo.fnGetRoundedValue(@Balance);        
RAISERROR(''Document partially collected (Current Balance :&ensp;<code style="font-size:13px"> %d </code>)'',16,1,@DispBalance)         
end          
END          
ELSE IF(@TransID = 21)--Assign Invoice          
BEGIN          
select @CurrentStatus = Status,@StsDesc = STS.Description from tblAssignInvoicesHeader QH WITH (READCOMMITTEDLOCK)           
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status          
where QH.ID = @ID AND TransID = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END          
ELSE if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)         
end          
END         
ELSE IF(@TransID = 19 or @TransID = 10)--Collection or Other Collection        
BEGIN          
select @CurrentStatus = Status,@StsDesc = STS.Description from tblTranCollectionHeader QH WITH (READCOMMITTEDLOCK)           
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status          
where QH.ColID = @ID AND DocPrefix = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END          
ELSE if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)         
end          
END        
ELSE IF(@TransID = 18 or @TransID = 11)--Payment or Other Payment        
BEGIN          
select @CurrentStatus = Status,@StsDesc = STS.Description from tblTranPaymentHeader QH WITH (READCOMMITTEDLOCK)           
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status          
where QH.PYID = @ID AND PYPrefix = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END          
ELSE if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)         
end          
END       
IF(@TransID = 2)--Auto Indent          
BEGIN          
select @CurrentStatus = Status,@StsDesc = STS.Description from tblTransAutomaticIndentHeader QH WITH (READCOMMITTEDLOCK)           
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status          
where QH.ID = @ID AND TransID = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END          
ELSE if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)         
end          
END          
IF(@TransID = 3)--Purchase Order        
BEGIN          
select @CurrentStatus = Status,@StsDesc = STS.Description from tblPurchaseOrderHeader QH WITH (READCOMMITTEDLOCK)           
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status          
where QH.ID = @ID AND TransID = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END          
ELSE if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)         
end          
END        
ELSE IF(@TransID = 1 OR @TransID = 12)--Bill or Purchase Return          
BEGIN          
select @CurrentStatus = Status,@NetAmt = NetAmt ,@Balance = Balance,@StsDesc = STS.Description from tblTransPurchaseHeader QH WITH (READCOMMITTEDLOCK)        
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status where QH.ID = @ID          
AND TransID = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END         
if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)        
end          
else if(@NetAmt != @Balance)          
begin          
set @DispBalance = dbo.fnGetRoundedValue(@Balance)        
RAISERROR(''Document partially collected (Current Balance :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@DispBalance)         
end          
ENd        
ELSE IF(@TransID = 4 OR @TransID = 5)--Credit or Debit Note        
BEGIN          
select @CurrentStatus = Status,@NetAmt = NoteValue ,@Balance = Balance,@StsDesc = STS.Description from tblNoteDetails QH WITH (READCOMMITTEDLOCK)        
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status where QH.ID = @ID          
AND TransID = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END         
if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)        
end          
else if(@NetAmt != @Balance)          
begin          
set @DispBalance = dbo.fnGetRoundedValue(@Balance)        
RAISERROR(''Document partially collected (Current Balance :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@DispBalance)         
end          
ENd        
ELSE IF(@TransID = 6 OR @TransID = 7)--Payable or Receivable voucher        
BEGIN          
select @CurrentStatus = Status,@NetAmt = NetAmount ,@Balance = Balance,@StsDesc = STS.Description from tblTranPRVoucher QH WITH (READCOMMITTEDLOCK)        
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status where QH.ID = @ID          
AND TransID = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)     
END         
if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)        
end          
else if(@NetAmt != @Balance)          
begin          
set @DispBalance = dbo.fnGetRoundedValue(@Balance)        
RAISERROR(''Document partially collected (Current Balance :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@DispBalance)         
end          
ENd        
ELSE IF(@TransID = 8)--Contra        
BEGIN          
select @CurrentStatus = Status,@NetAmt = Amount ,@Balance = Balance,@StsDesc = STS.Description from tblTranContra QH WITH (READCOMMITTEDLOCK)        
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status where QH.ID = @ID          
AND TransID = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END         
if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)        
end          
else if(@NetAmt != @Balance)          
begin          
set @DispBalance = dbo.fnGetRoundedValue(@Balance)        
RAISERROR(''Document partially collected (Current Balance :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@DispBalance)         
end          
ENd        
ELSE IF(@TransID = 9)--Journal Entry        
BEGIN          
select TOP 1 @CurrentStatus = Status,@NetAmt = (case when Credit = 0 then Debit else credit end) ,@Balance = Balance,        
@StsDesc = STS.Description from tblFAJournal QH WITH (READCOMMITTEDLOCK)        
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status where QH.JVID = @ID         
AND DocPrefix = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END         
if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)        
end          
else if(@NetAmt != @Balance)          
begin          
set @DispBalance = dbo.fnGetRoundedValue(@Balance)        
RAISERROR(''Document partially collected (Current Balance :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@DispBalance)         
end          
ENd
IF(@TransID = 24)--Van loading slip
BEGIN          
select @CurrentStatus = Status,@StsDesc = STS.Description from tblVanLoadingSlipHeader QH WITH (READCOMMITTEDLOCK)           
JOIN tblStatus STS WITH (READCOMMITTEDLOCK) ON STS.ID = QH.Status          
where QH.ID = @ID AND TransID = @TransID          
IF(@CurrentStatus IN (2,4,5,8))          
BEGIN          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)          
END          
ELSE if(@CurrentStatus != @StatusID)          
begin          
RAISERROR(''Document status already changed (Current Status :&ensp;<code style="font-size:13px"> %s </code>)'',16,1,@StsDesc)         
end          
END 
end try          
begin catch          
select ERROR_MESSAGE(),ERROR_LINE(),ERROR_PROCEDURE()          
end catch',
N'[export] nocount;readcommittedlock=26';
GO
/****** uspValidateWebCollection ******/
EXEC #Apply07 N'dbo.uspValidateWebCollection', 0x1D26AE3DF12273F710D25932958241C9E9093F50739B4D5A9FC5B68A6D7EBBD7, NULL, NULL, 0x596883215BF4F4B36A28F80C83112654EDA159022C1B78C09C05E1FFC6F88A3E, 0x37DF1F58899735D5514563BCCA8872A8B5F917718809EC57D6A8DB6DEDFA87AC, NULL,
N'ALTER proc [dbo].[uspValidateWebCollection]
@VerifyorCancel int = 1,@ID int = 176,@Status int = 1,@UID int
as
SET NOCOUNT ON;
begin
BEGIN TRY
declare @CurrStatus int
select @CurrStatus = Status from tblTranOrderCollectionHeader WITH (READCOMMITTEDLOCK) where ID = @ID
if(@CurrStatus = 4)
RAISERROR(''Document Already Cancelled'',16,1);
else if(@CurrStatus = 8)
RAISERROR(''Document Already Processed'',16,1);
else if(@Status <> @CurrStatus)
RAISERROR(''Document Status Already Changed'',16,1);
if(@VerifyorCancel = 2)
UPDATE tblTranOrderCollectionHeader SET Status = 4,ClBy = @UID ,ClDate = getdate() where ID = @ID
end TRY
BEGIN CATCH
SELECT ERROR_MESSAGE() MSG,ERROR_LINE() LINE,ERROR_PROCEDURE() PRO
END CATCH
END',
N'[export] nocount;readcommittedlock=1';
GO
/****** uspVendorReport ******/
EXEC #Apply07 N'dbo.uspVendorReport', 0x2F8E4F946AFA960DA3E7EF3E39B48BF733B4CE5BC9DE79C24E246A4264D1DF8B, 0xFCC6374AEC65611A5503B14F314BC71118565BC47E51EC940E99620D45188034, NULL, 0xFB0FB061ADE1DE03A44D8AFF8DEFF8C154A3D8500E11F1ECB01E7B3A0475A1C0, 0x3F7012F044F5DB6D622F229A28C59450F5A2B601BB3CB1892924B75C57E4F6D5, NULL,
N'-- Security fix: report filter values are passed to sp_executesql as typed parameters instead of being concatenated into the SQL text.
ALTER PROCEDURE [dbo].[uspVendorReport]
 @WeekCycle nvarchar(50) = ''0'',@Ratings nvarchar(50) = ''0''
AS
SET NOCOUNT ON;
BEGIN
DECLARE @strQuery NVARCHAR(MAX) = ''''  
SET @strQuery = ''
select 
    MV.Code [Vendor Code],
    MV.Name [Vendor Name],
    MV.Billadd1 [Bill Add 1],
    MV.Billadd2 [Bill Add 2],
    MV.Billadd3 [Bill Add 3],
    MV.Shipadd1 [Ship Add 1],
    MV.Shipadd2 [Ship Add 2],
    MV.Shipadd3 [Ship Add 3],
    MV.Pincode,
    MV.ContactPerson [Contact Person],
    MV.Ph1 [Phone No 1],
    MV.Ph2 [Phone No 2],
    MV.Mob1 [Mob No 1],
    MV.Mob2 [Mob No 2],
    MV.Email [Email ID],
    MV.PANNumber [PAN No],
    MV.AadharNo [Aadhar No],
    MV.DLNo20 [DL No 20],
    MV.DLNo21 [DL No 22],
    MV.FSSAINo,
    GST.StateName [State Name],
    MV.GSTIN,    
    PM.PaymentMode [Payment Mode],
    CT.Name [Credit Term],
    MTT.TaxTypeName [Tax Type],
    WK.WeekDays [Week Cycle],
    RT.RatingnAME Ratings,
    [dbo].[fnGetRoundedValue]((dbo.fnGetClosingBal(MV.FAID))) AS [OutStanding Value],
    case when MV.Active = 1 then ''''Yes'''' ELSE ''''No'''' end Active,  
	MU.UserName [Created By],CONVERT(NVARCHAR,MV.CDate) [Create Date],  
	MUM.UserName [Modify By],CONVERT(NVARCHAR,MV.MDate) [Modify Date]
     from tblMasterVendor MV
LEFT JOIN tblGSTStateNameandCode GST ON GST.StateID = MV.StateID
LEFT JOIN tblMasterCreditTerm CT ON CT.ID = MV.CreditTermID
LEFT JOIN tblPaymentMode PM ON PM.ID = MV.PaymentModeID
JOIN tblMasterTaxType MTT ON MTT.TaxTypeID = MV.TaxTypeID
LEFT JOIN tblRatings RT ON RT.ID = MV.Rating
LEFT JOIN tblWeekCycle WK ON WK.ID = MV.WeekCycle
JOIN tblUsers MU ON MU.ID = MV.CBy        
LEFT JOIN tblUsers MUM ON MUM.ID = MV.MBy WHERE MV.ID > 0 ''
SET @strQuery += CASE WHEN ISNULL(@WeekCycle,''0'') = ''0'' THEN '''' ELSE '' AND MV.WeekCycle = ''+'' @WeekCycle '' END      
SET @strQuery += CASE WHEN ISNULL(@Ratings,''0'') = ''0'' THEN '''' ELSE '' AND MV.Rating = ''+'' @Ratings '' END     
SET @strQuery += '' ORDER BY MV.Name ''
EXEC sys.sp_executesql @strQuery, N''@WeekCycle nvarchar(50), @Ratings nvarchar(50)'', @WeekCycle, @Ratings    
END',
N'[06] nocount';
GO
/****** uspVerifyMobileDeviceInfo ******/
EXEC #Apply07 N'dbo.uspVerifyMobileDeviceInfo', 0x09D5CAA2A32235E011C06D511EFC35E4701FE0F637B68BEDCA112B134B4AF9B6, NULL, NULL, 0xE8F8F94499ACEF17A54B881BEE63138EA7D685E784866CC66299184A4C23C75E, 0x53BECC37610E519DBA73586190A90357A59570EA3359ED4562A49704B8ECD869, NULL,
N'ALTER PROC [dbo].[uspVerifyMobileDeviceInfo]          
@Mode TINYINT,@DeviceName NVARCHAR(50) = null,@DeviceID NVARCHAR(255)  = null,@UserID SMALLINT  = null,@DBName NVARCHAR(50) = null,          
@Active INT,@RequestTime DATETIME = null,@Ident INT = NULL          
as          
SET NOCOUNT ON;
begin      
      
if(@Mode = 1)          
begin          
if((select COUNT(*) from tblMobileDeviceInfo WITH (READCOMMITTEDLOCK) WHERE DeviceName = @DeviceName AND DeviceID = @DeviceID) > 0)          
BEGIN          
SELECT ''exists'' AS "DeviceExists",ID from tblMobileDeviceInfo WITH (READCOMMITTEDLOCK) WHERE DeviceName = @DeviceName AND DeviceID = @DeviceID        
ENd          
else          
begin          
INSERT INTO tblMobileDeviceInfo (DeviceName,DeviceID,RequestTime) values (@DeviceName,@DeviceID,          
@RequestTime)          
select SCOPE_IDENTITY()          
end          
enD         
else if(@Mode = 2)          
begin          
if((select COUNT(*) from tblMobileDevicePermission WITH (READCOMMITTEDLOCK) WHERE UserID = @UserID AND DeviceIdent = @Ident) > 0)          
BEGIN       
select MDP.Active,UR.ID,UR.UserName from tblMobileDevicePermission MDP WITH (READCOMMITTEDLOCK)
JOIN TBLUSERS  UR WITH (READCOMMITTEDLOCK) ON UR.ID = MDP.UserID
WHERE UserID = @UserID AND DeviceIdent = @Ident      
END      
ELSE      
BEGIN      
INSERT INTO tblMobileDevicePermission (DeviceIdent,UserID,DBName,RequestTime,Active) VALUES (@Ident,@UserID,@DBName,@RequestTime,@Active)      
select MDP.Active,UR.ID,UR.UserName from tblMobileDevicePermission MDP WITH (READCOMMITTEDLOCK)
JOIN TBLUSERS  UR WITH (READCOMMITTEDLOCK) ON UR.ID = MDP.UserID
WHERE UserID = @UserID AND DeviceIdent = @Ident      
END           
end  
else if(@Mode = 3)  
begin  
select MDP.Active,UR.ID,UR.UserName from tblMobileDevicePermission MDP WITH (READCOMMITTEDLOCK)
JOIN TBLUSERS  UR WITH (READCOMMITTEDLOCK) ON UR.ID = MDP.UserID
WHERE UserID = @UserID AND DeviceIdent = @Ident    
end  
end',
N'[export] nocount;readcommittedlock=9';
GO
/****** uspVerifyStatutory ******/
