/****** uspVLSBody ******/
EXEC #Apply07 N'dbo.uspVLSBody', 0x8B3CF7C2DDC2855B502D7B3C2B04E59A4BCA9DD8E468080FDC19DD90BD428C79, NULL, NULL, 0x373196462DCAEA97FFA1E2FD84C2FDA0400ACE469677FE5AFA9467DEFA8090A7, 0xE2EDA535AFDCDA7FD66589F0D4CDB4C5A5232820B86617CD5C5D7A66949A58C6, NULL,
N'--uspVLSBody 15  
ALTER PROC [dbo].[uspVLSBody]      
@ID INT  = NULL    
AS      
SET NOCOUNT ON;
BEGIN      
select ROW_NUMBER() OVER (ORDER BY VD.ProdID) AS [SerialNo],MP.Code ProductCode,MP.Name ProductName,MP.HSNCode,  
SUM(VD.UomQty) Qty,SUM(isnull(VD.VLSMQty,0)) SoldQty,SUM(VD.UomQty - isnull(VD.VLSMQty,0)) AvlVLSQty,      
MUM.Name UOMName,(VD.UomPrice) ExclPrice,(dbo.fngetinclusivevalue(VD.TaxID,VD.MRP,VD.UomPrice)) InclPrice,      
(VD.MRP) MRP,MT.TaxName,(ISNULL(dbo.fngetMRPonCumValue(0,VD.TaxID,1,0),0)) CumMRPonTax,                      
SUM((ISNULL(dbo.fngetMRPonCumValue(1,VD.TaxID,1,VD.MRP),0)) * VD.UomQty) MRPonTaxAmt,SUM(VD.GrossAmt) GrossAmt,  
SUM(VD.TaxAmt) TaxAmt,  
SUM(VD.NetAmt) NetAmt,PV.BatchNumber BatchNo,PV.PKDDate PKD,PV.ExpiryDate Expiry,  
convert(nvarchar(20),CONVERT(decimal(15,2), VD.TaxValue / 2)) + '' + '' +  
convert(nvarchar(20),CONVERT(decimal(15,2), VD.TaxValue / 2)) +'' + ''+  
''0.00 + 0.00 + 0.00'' [Tax Rate(C+S+I+CESS+CESS Non Advol)],'''' "H_Line",'''' "V_Line"  
from tblVanLoadingSlipDetail VD            
JOIN tblMasterProduct MP ON MP.ID = VD.ProdID            
JOIN tblMasterUOM MUM ON MUM.ID = VD.UOMID            
JOIN tblMasterTax MT ON MT.TaxID = VD.TaxID            
JOIN tblProductInventory PV ON PV.InventoryId = VD.InventoryID       
WHERE VD.ID = @ID   
GROUP BY MP.Code, MP.Name, MP.HSNCode, MUM.Name, VD.UomPrice, VD.TaxID, VD.MRP,   
MT.TaxName, PV.BatchNumber, PV.PKDDate, PV.ExpiryDate, VD.TaxValue,VD.SERIAL,VD.ProdID    
ORDER BY VD.SERIAL    
END',
N'[export] nocount';
GO
/****** uspVLSHeader ******/
EXEC #Apply07 N'dbo.uspVLSHeader', 0x1371BFF23F13AB50EBA9E2C97201B8A2E670738728BD27A2341DAFA718618C55, NULL, NULL, 0xF7906C51D195EE94BA58A90282CD3CFFDB17B4316586962B349F94864896A576, 0x1E06FFCC65F917340CC466E140A535257B18B6013B046BA9380C0C0D8BDC53C9, NULL,
N'ALTER PROC [dbo].[uspVLSHeader]      
@ID INT = NULL      
AS      
SET NOCOUNT ON;
BEGIN      
declare @CompGSTNo nvarchar(50) = (SELECT TOP 1 GSTIN FROM tblCompanyRegistration)  
SELECT DocID [Document ID],FORMAT(DocDate,''dd/MM/yyyy'') DocDate,RefNo,MBO.Name Branch,MV.Name Salesman,              
dbo.fnGetRoundedValue(PH.GrossAmt) GrossAmt,                                    
dbo.fnGetRoundedValue(PH.TaxAmt) TaxAmt,dbo.fnGetRoundedValue(PH.RoundoffAmt) RoundoffAmt,    
dbo.fnGetRoundedValue(PH.NetAmt) NetAmt,[dbo].[fnConvertAmountinWords](PH.NetAmt) AS [Amt_in_Words],STS.Description Status,                              
CUR.UserName CreateBy,CONVERT(NVARCHAR(100),PH.CDate) CreateDate,PH.Remarks,PH.Narration,      
EWBNo,VH.VehicleNo,Distance,TransMode,VehicleType,TransportID,TransportName,  
TransportID+ (case when isnull(TransportName,'''') != '''' then '' & '' else '''' end) +TransportName [TransportID_Name],  
DocID+'' & ''+FORMAT(DocDate,''dd/MM/yyyy'') [TransportDocID_Dt],  
VH.VehicleNo+'' & ''+DocID+'' & ''+FORMAT(DocDate,''dd/MM/yyyy'') [Vehicle/Trans DocID&Dt],  
isnull(PH.EWBNo,'''')+''/''+@CompGSTNo+''/''+FORMAT(DocDate,''dd/MM/yyyy'') EwayInfo ,
FORMAT(PH.EWBDate,''dd/MM/yyyy hh:mm tt'') EWBDate,FORMAT(ValidTill,''dd/MM/yyyy'') ValidTill
FROM tblVanLoadingSlipHeader PH                                    
JOIN tblMasterSalesman MV ON MV.ID = PH.SalesmanID                                    
JOIN tblStatus STS ON STS.ID = PH.Status                                    
JOIN tblMasterBranchOffice MBO ON MBO.ID = PH.BranchID                              
JOIN tblUsers CUR ON CUR.ID = PH.CBy       
left join tblMasterVehicle VH ON VH.ID = PH.VehicleNo      
WHERE PH.ID = @ID      
END',
N'[export] nocount';
GO
/****** uspWebShineTodayRoute ******/
EXEC #Apply07 N'dbo.uspWebShineTodayRoute', 0x85C4836C9A0805D3D1431E391E07D5EAECD720BBC95310C536462BCA8CA3BE32, NULL, NULL, 0xC951E1FFE8B521ED914933536F2344D395BCB5BEF00555D1324799E464A49692, 0x7CDEED23AF988D9B0F7012862634D96B716A756A1C3E946B9BB363B744E7BB96, NULL,
N'ALTER PROC [dbo].[uspWebShineTodayRoute]      
@Mode INT,@UserID INT = 0,@BeatID INT = 0,@SalesmanID INT= 0 ,@BranchID int = 0,@ProfileID int = 0,
@UPIID nvarchar(255) = NULL   
AS      
SET NOCOUNT ON;
BEGIN      
IF(@Mode = 1)      
BEGIN      
SELECT 1 Type,''Beat'' Trans,ID,Name FROM tblMasterBeat WITH (READCOMMITTEDLOCK) WHERE Active = 1                            
union all                            
SELECT 2 Type,''Salesman'' Trans,ID,Name FROM tblMasterSalesman WITH (READCOMMITTEDLOCK) WHERE Active = 1         
union all                            
SELECT 3 Type,''Branch'' Trans,ID,Name FROM tblMasterBranchOffice WITH (READCOMMITTEDLOCK) WHERE Active = 1     
union all                            
SELECT 4 Type,''User'' Trans,ID,UserName Name FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE Active = 1  and ID <> 1 
union all                            
SELECT 5 Type,''PrintProfile'' Trans,PrintID ID,ConfigName Name FROM tblPrintConfig WITH (READCOMMITTEDLOCK) WHERE TransactionID = 4 
order by Type,Name      
END      
IF(@Mode = 2)      
BEGIN      
SELECT isnull(BeatID,0) BeatID,isnull(SalesmanID,0) SalesmanID,isnull(BranchID,0) BranchID
,isnull(PrintProfileID,0) PrintProfileID ,UPIID FROM tblUsers WITH (READCOMMITTEDLOCK) WHERE ID = @UserID      
END      
IF(@Mode = 3)      
BEGIN      
UPDATE TBLUSERS SET BeatID = @BeatID,SalesmanID = @SalesmanID,BranchID = @BranchID,PrintProfileID = @ProfileID,
UPIID = @UPIID WHERE ID = @UserID      
END      
END',
N'[export] nocount;readcommittedlock=6';
GO
/****** uspWhatsappmessagecontent ******/
EXEC #Apply07 N'dbo.uspWhatsappmessagecontent', 0xEE2DB7780DCF78B224A6AA782999A27B0CA43B53F63EACD37DF4D7E443E030E7, NULL, NULL, 0xA3CF03FB66B90B3C8B56E7786C0F75B364B7B252E2D958251165031A99C353BE, 0xB0E5BB050681CB792FA1F21FFAE910AAA81EDF45C02D9FD6DC85F109699C0460, NULL,
N'--uspWhatsappmessagecontent 23,6,''https://localhost:44396/api/''                
ALTER PROCEDURE [dbo].[uspWhatsappmessagecontent]                
@TransactionType INT = 4,@TransactionId INT =433,@APIUrl nvarchar(max) = ''''                
as                
SET NOCOUNT ON;
begin                
DECLARE @DueDate NVARCHAR(100),@OrgDocId NVARCHAR(100), @DocDate NVARCHAR(100), @DocValue nvarchar(100), @NetAmt NVARCHAR(255),                
@PartyName NVARCHAR(255), @PartyMobileNo NVARCHAR(255), @ItemsCount int, @CompanyName nvarchar(255),@CompanyMobNo nvarchar(20),      
@ContactPerson nvarchar(255),@WhatsAppMsg NVARCHAR(MAX),                
@OSAmt DECIMAL(25,4) ,@PaymentMode nvarchar(100), @VendorName NVARCHAR(255), @PurchasePrice NVARCHAR(50), @ABSQty NVARCHAR(50),       
@MOH NVARCHAR(50), @MOQ NVARCHAR(50) , @IndentValue INT, @TotalValue NVARCHAR(50),@TotalItems NVARCHAR(50),@TotalQty NVARCHAR(50),        
@BranchName NVARCHAR(255), @CreditTerm NVARCHAR(255),@TotalFreeQty NVARCHAR(50),@TotalDamageQty NVARCHAR(50),@NoteValue NVARCHAR(255),      
@AccountName NVARCHAR(255),@VehicleNo NVARCHAR(255)        
                
select @CompanyName = CompanyName,@CompanyMobNo = MobileNo,@ContactPerson = Contact_Person from tblCompanyRegistration where CompanyId = 1                
--  select * from tblTransName              
if(@TransactionType = 4 or @TransactionType = 5) -- Invoice & Sales Return                
BEGIN                
SELECT                
@DueDate = case when CreditDate is null then null else FORMAT(CreditDate,''dd-MMM-yyyy'') end,@OrgDocId = DocId,@DocValue = DocValue,                
@DocDate = FORMAT(InvDate,''dd-MMM-yyyy''),@PartyName = Name,@NetAmt = dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(SH.NetAmt)),                
@ItemsCount = count(SD.ProdID),@PartyMobileNo = MC.Mob1 ,@OSAmt = dbo.fnGetClosingBal(MC.FAID)                
FROM tblTranSalesHeader SH                
join tblTranSalesDetail SD ON SD.InvID = SH.ID                
JOIN tblMasterCustomer MC ON MC.ID = SH.CustID                
WHERE SH.ID = @TransactionId AND isnull(SD.TaxID,0) > 0
GROUP BY CreditDate,InvDate,DocId,Name,SH.NetAmt, MC.Mob1,DocValue,MC.FAID                
-- WhatsApp Message Construction                
SET @WhatsAppMsg =                 
''Hello *'' + @PartyName + N''👋* ,'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +                
''Thank you for your purchase from *'' + @CompanyName + N''*😊'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +                
N''*🧾 **Invoice Details***'' + CHAR(13) + CHAR(10) +                
''• Invoice No : *'' + @OrgDocId +''*''+ CHAR(13) + CHAR(10) +                
''• Invoice Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) +                
''• Amount : *''+N''₹ '' + @NetAmt +''*''+ CHAR(13) + CHAR(10) +                
''• OS : *''+N''₹ '' + (CASE WHEN @OSAmt >=0 THEN dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(CONVERT(NVARCHAR(100),@OSAmt))) +'' Dr''                
ELSE dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(CONVERT(NVARCHAR(100),ABS(@OSAmt)))) +'' Cr'' END) +''*''+ CHAR(13) + CHAR(10) +                
''• Total Items : *'' + CAST(@ItemsCount AS NVARCHAR) +''*''+ CHAR(13) + CHAR(10) +  CHAR(10) + CHAR(10)         
--''• Due Date : '' + (case when @DueDate is null then '' - '' else ''*''+ @DueDate+''*'' end) + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + CHAR(10)                
-- Final Output                
SELECT @PartyMobileNo AS MobileNo,@DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;                
END                
if(@TransactionType = 2 or @TransactionType = 3) -- Bill & Purchase Return                
BEGIN                
SELECT                
@DueDate = case when PaymentDate is null then null else FORMAT(PaymentDate,''dd-MMM-yyyy'') end,@OrgDocId = DocId,@DocValue = DocValue,                
@DocDate = FORMAT(Date,''dd-MMM-yyyy''),@PartyName = Name,@NetAmt = dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(SH.NetAmt)),                
@ItemsCount = count(SD.ProdID),@PartyMobileNo = MC.Mob1 ,@OSAmt = dbo.fnGetClosingBal(MC.FAID)                
FROM tblTransPurchaseHeader SH                
join tblTransPurchaseDetail SD ON SD.HID = SH.ID                
JOIN tblMasterVendor MC ON MC.ID = SH.VendorID                
WHERE SH.ID = @TransactionId                
GROUP BY PaymentDate,Date,DocId,Name,SH.NetAmt, MC.Mob1,DocValue,MC.FAID                
-- WhatsApp Message Construction                
SET @WhatsAppMsg =                 
''Hello *'' + @PartyName + N''👋* ,'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +                
''Thank you for your purchase from *'' + @CompanyName + N''*😊'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +                
N''*🧾 **Bill Details***'' + CHAR(13) + CHAR(10) +                
''• Bill No : *'' + @OrgDocId +''*''+ CHAR(13) + CHAR(10) +                
''• Bill Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) +                
''• Amount : *''+N''₹ '' + @NetAmt +''*''+ CHAR(13) + CHAR(10) +                
''• OS : *''+N''₹ '' + (CASE WHEN @OSAmt >=0 THEN dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(CONVERT(NVARCHAR(100),@OSAmt))) +'' Dr''                
ELSE dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(CONVERT(NVARCHAR(100),ABS(@OSAmt)))) +'' Cr'' END) +''*''+ CHAR(13) + CHAR(10) +                
''• Total Items : *'' + CAST(@ItemsCount AS NVARCHAR) +''*''+ CHAR(13) + CHAR(10) +                
''• Due Date : '' + (case when @DueDate is null then '' - '' else ''*''+ @DueDate+''*'' end) + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) + CHAR(10)                
-- Final Output                
SELECT @PartyMobileNo AS MobileNo,@DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;                
END                
if(@TransactionType = 8) -- Collection              
BEGIN                
SELECT  @OrgDocId = sh.DocId,@DocValue = sh.DocValue,                
@DocDate = FORMAT(ColDate,''dd-MMM-yyyy''),@PartyName = Name,@NetAmt = dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(SH.ColAmt)),                
@PartyMobileNo = MC.Mob1 ,@OSAmt = dbo.fnGetClosingBal(MC.FAID) ,@PaymentMode = PM.PaymentMode               
FROM tblTranCollectionHeader SH                
JOIN tblMasterCustomer MC ON MC.FAID = SH.AccID                
JOIN tblPaymentMode PM ON PM.ID = SH.ColMode              
WHERE SH.ColID = @TransactionId                
GROUP BY ColDate,DocId,Name,SH.ColAmt, MC.Mob1,DocValue,MC.FAID  ,PM.PaymentMode               
              
SET @WhatsAppMsg =  N''Hello *'' + @PartyName + '' 👋*'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +              
''Greeting from *'' + @CompanyName + N''😊,*''+CHAR(13) + CHAR(10)  + CHAR(13) + CHAR(10) +              
    ''Thank you for your payment. We have successfully received the amount.'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +              
    N''💰 Amount Received : *₹'' + @NetAmt +''*''+ CHAR(13) + CHAR(10) +              
    N''💰 Payment Type : *'' + @PaymentMode +''*''+ CHAR(13) + CHAR(10) +              
    N''📄 Collection No :*'' + @OrgDocId + ''*''+CHAR(13) + CHAR(10) +              
    N''📅 Payment Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10)                   
SELECT @PartyMobileNo AS MobileNo,@DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;                
END           
          
if(@TransactionType = 7) -- Automatic Indent          
BEGIN          
SELECT @OrgDocId = AI.DocID, @DocValue = AI.DocValue,          
@DocDate = FORMAT(AI.Date,''dd-MMM-yyyy''),@VendorName = MV.Name,@BranchName = MBO.Name,        
@PartyMobileNo = MV.Mob1        
FROM tblTransAutomaticIndentHeader AI          
LEFT JOIN tblMasterVendor MV on  MV.ID = AI.VendorID        
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = AI.BranchID        
WHERE AI.ID = @TransactionId            
        
    SELECT         
        @TotalItems = CAST(COUNT(AID.ProdID) AS NVARCHAR(50)),        
        @TotalValue = CAST(DBO.fnGetRoundedValue(SUM(AID.PurchasePrice * AID.IndentValue)) AS NVARCHAR(50))        
    FROM tblTransAutomaticIndentDetail AID        
    WHERE AID.HID = @TransactionId        
          
SET @WhatsAppMsg = N''Hello* '' + @VendorName + '' 👋*'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +           
''Greeting from *'' + @CompanyName + N''😊,*''+CHAR(13) + CHAR(10)  + CHAR(13) + CHAR(10) +          
    ''Stock levels have reached the required threshold, and an automatic indent has been generated for replenishment.'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +           
N''*🧾 **Automatic Indent Details***'' + CHAR(13) + CHAR(10) +         
N''• Branch Name : *'' + ISNULL(@BranchName, ''-'') +''*''+ CHAR(13) + CHAR(10) +        
''• Doc ID : *'' + @OrgDocId +''*''+ CHAR(13) + CHAR(10) +                
''• Doc Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) +           
N''📦 Total Items : *'' + @TotalItems + ''*'' + CHAR(13) + CHAR(10) +        
N''💵 Total Value : *'' + @TotalValue + ''*'' + CHAR(13) + CHAR(10)         
SELECT @PartyMobileNo AS MobileNo, @DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;          
          
END          
        
if(@TransactionType = 1) -- Purchase Order        
BEGIN         
        
SELECT @OrgDocId = PO.DocID, @DocValue = PO.DocValue,@DocDate = FORMAT(PO.DocDate,''dd-MMM-yyyy''),@VendorName = MV.Name,        
@PartyMobileNo = MV.Mob1, @BranchName = MBO.Name        
        
From tblPurchaseOrderHeader PO        
LEFT JOIN tblPurchaseOrderDetail POD on POD.HID = PO.ID        
LEFT JOIN tblMasterVendor MV on MV.ID = PO.VendorID        
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = PO.BranchID        
WHERE PO.ID = @TransactionId        
        
        
SELECT @TotalItems = CAST(COUNT(POD.ProdID) AS NVARCHAR(50)),        
@TotalQty = CAST(DBO.fnGetRoundedValue(SUM(POD.Qty)) AS NVARCHAR(50)),        
@NetAmt = CAST(DBO.fnGetRoundedValue(SUM(POD.NetAmt)) AS NVARCHAR(50))        
        
FROM tblPurchaseOrderDetail POD        
WHERE POD.HID = @TransactionId        
        
SET @WhatsAppMsg = N''Hello* '' + @VendorName + '' 👋*'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +           
''Greeting from *'' + @CompanyName + N''😊,*''+CHAR(13) + CHAR(10)  + CHAR(13) + CHAR(10) +          
   ''Your Purchase Order is ready! We''''ve got everything lined up, just check the details below! 🎯'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +          
N''*🧾 **Purchase Order Details***'' + CHAR(13) + CHAR(10) +          
N''• Branch Name : *'' + ISNULL(@BranchName, ''-'') +''*''+ CHAR(13) + CHAR(10) +        
''• Doc ID : *'' + @OrgDocId +''*''+ CHAR(13) + CHAR(10) +                
''• Doc Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) +        
N''📦 Total Items : *'' + @TotalItems + ''*'' + CHAR(13) + CHAR(10) +        
N''📦 Total Qty : *'' + @TotalQty + ''*'' + CHAR(13) + CHAR(10) +        
N''💵 Net Amount : *'' + @NetAmt + ''*'' + CHAR(13) + CHAR(10)         
SELECT @PartyMobileNo AS MobileNo, @DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;          
        
END        
        
        
        
if(@TransactionType = 9) -- Payment             
BEGIN                
SELECT  @OrgDocId = sh.DocId,@DocValue = sh.DocValue,                
@DocDate = FORMAT(PYDate,''dd-MMM-yyyy''),@VendorName = MV.Name,@NetAmt = dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(SH.PYAmt)),                
@PartyMobileNo = MV.Mob1 ,@OSAmt = dbo.fnGetClosingBal(MV.FAID) ,@PaymentMode = PM.PaymentMode, @BranchName = MBO.Name               
FROM tblTranPaymentHeader SH                
JOIN tblMasterVendor MV ON MV.FAID = SH.AccID                
JOIN tblPaymentMode PM ON PM.ID = SH.PYMode        
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = SH.BranchID        
WHERE SH.PYID = @TransactionId                
GROUP BY PYDate,DocId,MV.Name,SH.PYAmt, MV.Mob1,DocValue,MV.FAID  ,PM.PaymentMode, MBO.Name               
              
SET @WhatsAppMsg =  N''Hello *'' + @VendorName + '' 👋*'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +              
''Greeting from *'' + @CompanyName + N''😊,*''+CHAR(13) + CHAR(10)  + CHAR(13) + CHAR(10) +              
    ''We''''ve successfully processed your payment! Please find the payment details below. 🙏, Thanks for your Support'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +        
    N''• Branch Name : *'' + ISNULL(@BranchName, ''-'') +''*''+ CHAR(13) + CHAR(10) +        
    N''📄 Doc ID :*'' + @OrgDocId + ''*''+CHAR(13) + CHAR(10) +              
    N''📅 Doc Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10)+        
    N''💰 Amount Paid : *₹'' + @NetAmt +''*''+ CHAR(13) + CHAR(10) +              
    N''💰 Payment Type : *'' + @PaymentMode +''*''+ CHAR(13) + CHAR(10)                          
SELECT @PartyMobileNo AS MobileNo,@DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;                
END          
        
        
if(@TransactionType = 6) -- Quotation         
BEGIN        
        
SELECT @OrgDocId = DocId,@DocValue = DocValue,                
@DocDate = FORMAT(QH.DocDate,''dd-MMM-yyyy''),@PartyName = MC.Name,                
@PartyMobileNo = MC.Mob1 ,@OSAmt = dbo.fnGetClosingBal(MC.FAID), @BranchName = MBO.Name        
        
FROM tblQuotationHeader QH        
LEFT JOIN tblQuotationDetail QD on QD.QuationID = QH.ID        
LEFT JOIN tblMasterCustomer MC on MC.ID = QH.CustomerID        
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = QH.BranchID        
WHERE QH.ID = @TransactionId        
        
SELECT @TotalItems = CAST(COUNT(QD.ProdID) AS NVARCHAR(50)),        
@TotalQty = CAST(DBO.fnGetRoundedValue(SUM(QD.Qty)) AS NVARCHAR(50)),        
@NetAmt = CAST(DBO.fnGetRoundedValue(SUM(QD.NetAmt)) AS NVARCHAR(50))        
        
FROM tblQuotationDetail QD        
WHERE QD.QuationID = @TransactionId        
        
SET @WhatsAppMsg =  N''Hello *'' + @PartyName + '' 👋*'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +              
''Greeting from *'' + @CompanyName + N''😊,*''+CHAR(13) + CHAR(10)  + CHAR(13) + CHAR(10) +              
    ''Your Quotation is ready! We''''ve put together the best pricing just for you. Have a look! 😊'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +        
    N''• Branch Name : *'' + ISNULL(@BranchName, ''-'') +''*''+ CHAR(13) + CHAR(10) +        
    N''📄 Doc ID :*'' + @OrgDocId + ''*''+CHAR(13) + CHAR(10) +              
    N''📅 Doc Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10)+        
    N''📦 Total Items : *'' + @TotalItems + ''*'' + CHAR(13) + CHAR(10) +        
    N''📦 Total Qty : *'' + @TotalQty + ''*'' + CHAR(13) + CHAR(10) +        
    ''• OS : *''+N''₹ '' + (CASE WHEN @OSAmt >=0 THEN dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(CONVERT(NVARCHAR(100),@OSAmt))) +'' Dr''                
ELSE dbo.ConvertAmtINDFormat(DBO.fnGetRoundedValue(CONVERT(NVARCHAR(100),ABS(@OSAmt)))) +'' Cr'' END) +''*''+ CHAR(13) + CHAR(10) +         
    N''💵 Net Amount : *'' + @NetAmt + ''*'' + CHAR(13) + CHAR(10)                           
SELECT @PartyMobileNo AS MobileNo,@DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;         
        
END        
        
if(@TransactionType = 12) -- Credit Note        
BEGIN        
        
SELECT @OrgDocId = ND.DocId,@DocValue = ND.DocValue,                
@DocDate = FORMAT(ND.DocDate,''dd-MMM-yyyy''),@PartyName = MC.Name, @AccountName = FAA.AccountName ,              
@PartyMobileNo =  MV.Mob1,@BranchName = MBO.Name        
        
FROM tblNoteDetails ND        
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = ND.BranchID        
LEFT JOIN tblMasterVendor MV on MV.ID = ND.PartyID         
LEFT JOIN tblMasterCustomer MC on MC.ID = ND.PartyID        
LEFT JOIN tblFAAccount FAA on FAA.FAID = ND.FAID        
LEFT JOIN tblFAAccount FA on FA.FAID = ND.PartyID        
WHERE ND.ID = @TransactionId and TransID = 4        
        
SET @WhatsAppMsg =  N''Hello *'' + @PartyName + '' 👋*'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +              
''Greeting from *'' + @CompanyName + N''😊,*''+CHAR(13) + CHAR(10)  + CHAR(13) + CHAR(10) +              
    ''Your Credit Note is ready! We''''ve made sure everything is sorted for you. Have a look below! 🤝'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +        
    N''• Branch Name : *'' + ISNULL(@BranchName, ''-'') +''*''+ CHAR(13) + CHAR(10) +        
    N''📄 Account Name :*'' + @AccountName + ''*''+CHAR(13) + CHAR(10) +        
    N''📄 Doc ID :*'' + @OrgDocId + ''*''+CHAR(13) + CHAR(10) +        
    N''📄 Account Name :*'' + @AccountName + ''*''+CHAR(13) + CHAR(10) +         
    N''📅 Doc Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10)+        
    N''💰 Note Value : *₹'' + @NoteValue +''*''+ CHAR(13) + CHAR(10)                          
SELECT @PartyMobileNo AS MobileNo,@DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;         
        
END        
        
if(@TransactionType = 13) -- Debit Note        
BEGIN        
        
SELECT @OrgDocId = ND.DocId,@DocValue = ND.DocValue,                
@DocDate = FORMAT(ND.DocDate,''dd-MMM-yyyy''),@PartyName = MC.Name, @AccountName = FAA.AccountName,              
@PartyMobileNo = COALESCE(MC.Mob1, MV.Mob1),@BranchName = MBO.Name        
FROM tblNoteDetails ND        
LEFT JOIN tblMasterBranchOffice MBO on MBO.ID = ND.BranchID        
LEFT JOIN tblMasterVendor MV on MV.ID = ND.PartyID         
LEFT JOIN tblMasterCustomer MC on MC.ID = ND.PartyID        
LEFT JOIN tblFAAccount FAA on FAA.FAID = ND.FAID        
LEFT JOIN tblFAAccount FA on FA.FAID = ND.PartyID        
WHERE ND.ID = @TransactionId and TransID = 5        
        
SET @WhatsAppMsg =  N''Hello *'' + @PartyName + '' 👋*'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +              
''Greeting from *'' + @CompanyName + N''😊,*''+CHAR(13) + CHAR(10)  + CHAR(13) + CHAR(10) +              
    ''We''''ve processed a Debit Note for you! Kindly review the details below and get back to us if needed. 🎯'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +        
    N''• Branch Name : *'' + ISNULL(@BranchName, ''-'') +''*''+ CHAR(13) + CHAR(10) +        
    N''📄 Account Name :*'' + @AccountName + ''*''+CHAR(13) + CHAR(10) +        
    N''📄 Doc ID :*'' + @OrgDocId + ''*''+CHAR(13) + CHAR(10) +         
    N''📅 Doc Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10)+        
    N''💰 Note Value : *₹'' + @NoteValue +''*''+ CHAR(13) + CHAR(10)                          
SELECT @PartyMobileNo AS MobileNo,@DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;         
        
END        
if(@TransactionType = 11) -- Inventory Adjustment      
BEGIN       
select @OrgDocId = IH.DocId,@DocValue = IH.DocValue,                
@DocDate = FORMAT(IH.InventoryDate,''dd-MMM-yyyy''),@BranchName = MBO.Name,@ItemsCount = COUNT(ID.ProdID) from tblInventoryHeader IH       
JOIN tblMasterBranchOffice MBO on MBO.ID = IH.BranchID        
JOIN tblInventoryDetail ID ON ID.InventoryID = IH.InventoryID      
where TransID = 13 AND IH.InventoryID = @TransactionId      
GROUP BY MBO.Name,IH.DocId,IH.DocValue,IH.InventoryDate      
SET @WhatsAppMsg =  N''Hello *'' + @ContactPerson + '' *'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +              
    N''A new Inventory Adjustment has been created.'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +        
    N''• Branch Name : *'' + ISNULL(@BranchName, ''-'') +''*''+ CHAR(13) + CHAR(10) +            
    N''📄 Doc ID :*'' + @OrgDocId + ''*''+CHAR(13) + CHAR(10) +         
    N''📅 Doc Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10)+        
    N''📦 Total Items : *'' + CAST(@ItemsCount AS NVARCHAR(50)) + ''*'' + CHAR(13) + CHAR(10)       
    --N''💰 Note Value : *₹'' + @NoteValue +''*''+ CHAR(13) + CHAR(10)          
  
SELECT @CompanyMobNo AS MobileNo,@DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;      
end      
if(@TransactionType = 23) -- Delivery challan  
BEGIN        
        
SELECT @OrgDocId = VH.DocId,@DocValue = VH.DocValue,                
@DocDate = FORMAT(VH.DocDate,''dd-MMM-yyyy''),@PartyName = SM.Name,              
@PartyMobileNo = SM.MobileNo,@ItemsCount = COUNT(VD.ProdID),@VehicleNo = upper(V.VehicleNo)  
FROM tblVanLoadingSlipHeader VH   
join tblVanLoadingSlipDetail VD ON VD.ID = VH.ID  
LEFT JOIN tblMasterSalesman SM on SM.ID = VH.SalesmanID    
LEFT JOIN tblMasterVehicle V ON V.ID = VH.VehicleNo   
WHERE VH.ID = @TransactionId and TransID = 24       
GROUP BY  VH.DocId,VH.DocValue,VH.DocDate,SM.Name,SM.MobileNo,V.VehicleNo  
SET @WhatsAppMsg =  N''Hello *'' + @PartyName + ''*'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +              
''Greeting from *'' + @CompanyName + N''😊,*''+CHAR(13) + CHAR(10)  + CHAR(13) + CHAR(10) +              
    ''We''''ve prepared your Delivery Challan. Please find the details below.'' + CHAR(13) + CHAR(10) + CHAR(13) + CHAR(10) +        
           
    N''📄 Doc ID :*'' + @OrgDocId + ''*''+CHAR(13) + CHAR(10) +         
    N''📅 Doc Date : *'' + @DocDate +''*''+ CHAR(13) + CHAR(10) +    
    N''🚚 Vehicle No : *'' + isnull(@VehicleNo,'''') +''*''+ CHAR(13) + CHAR(10)  +  
    N''📦 Total Items : *'' + CAST(@ItemsCount AS NVARCHAR(50)) + ''*'' + CHAR(13) + CHAR(10)  + CHAR(13) + CHAR(10)                   
SELECT @PartyMobileNo AS MobileNo,@DocValue AS DocValue,@WhatsAppMsg AS WhatsAppMessage;         
        
END   
end',
N'[export] nocount';
GO
/* ---------------------------------------------------------------- results */
SELECT Result = CASE WHEN Result LIKE N'FAILED%' THEN N'FAILED' WHEN Result LIKE N'SKIPPED%' THEN N'SKIPPED' ELSE Result END,
       Objects = COUNT(*)
FROM #Log07
GROUP BY CASE WHEN Result LIKE N'FAILED%' THEN N'FAILED' WHEN Result LIKE N'SKIPPED%' THEN N'SKIPPED' ELSE Result END;
SELECT ObjectName, Result, Detail FROM #Log07 WHERE Result <> N'APPLIED' ORDER BY Seq;
SELECT FunctionName = o.name, m.is_inlineable FROM sys.sql_modules AS m JOIN sys.objects AS o ON o.object_id = m.object_id
WHERE o.name = N'fnGetRoundedValue';
GO